#[derive(Default)]
struct SessionReportState {
    header_printed: bool,
    // Identity, not a scalar counter: a repeated query/pass must not let one
    // body mask a different eligible body that was never verified.
    processed_bodies: FxHashSet<LocalDefId>,
}

/// Pre-pass outcomes that still account for one coverage-eligible function.
/// Each newly credited body emits an honest function envelope so the terminal
/// coverage identity inventory can be reconciled exactly by downstream gates.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum CoverageEarlyOutKind {
    /// The body already carries an `ErrorGuaranteed`; it is processed but never
    /// proof credit and the compilation remains failing.
    TaintedByErrors,
    /// A single empty `unreachable` block has no executable behavior and is a
    /// genuine zero-obligation function inventory entry.
    VacuouslyUnreachable,
}

#[derive(Clone)]
enum ClauseMonitorEvidence {
    /// The proposition/evaluator equivalence is kernel-certified, but exact
    /// MIR binding and control-flow placement have not yet been authenticated.
    /// Like `MeasureCertified`, this state is private and never transports a
    /// positive executability grade.
    MonitorCertified(BoundCertifiedMonitor),
    Monitored(BoundCertifiedMonitor),
    /// The Clean kernel certified the exact scalar evaluator, but the current
    /// MIR body has not yet authenticated every transition on which it would
    /// run. This provisional state is compiler-private and must never cross
    /// the public transport as `measured`.
    MeasureCertified(BoundCertifiedMeasure),
    /// The scalar evaluator plus a successful read-only placement preflight
    /// over this body's pristine optimized MIR.
    Measured(BoundCertifiedMeasure),
    Unmonitored {
        reason: String,
    },
}

/// Runtime payload plus the exact static proposition it was certified against.
/// This carrier is created only after the query-owned structural tree, its
/// canonical spelling, Clean's executable tree, and `trust_types::Formula`
/// all agree. Keeping both values together prevents later runtime wiring from
/// accidentally retaining the monitor after dropping its static identity.
#[derive(Clone, Debug)]
struct BoundCertifiedMonitor {
    runtime: trust_spec_elab::RuntimeMonitor,
    static_formula: Formula,
    variable_domains: Vec<trust_types::CompilerContractVariableDomain>,
}

/// Kernel-bound executable scalar measure plus the exact static expression it
/// was certified against. This is deliberately distinct from a Boolean
/// monitor: E5 placement compares successive evaluations at authenticated
/// control-flow edges instead of treating the scalar itself as a predicate.
#[derive(Clone, Debug)]
struct BoundCertifiedMeasure {
    runtime: trust_spec_elab::RuntimeScalarTerm,
    static_formula: Formula,
    variable_domains: Vec<trust_types::CompilerContractVariableDomain>,
}

#[derive(Debug, PartialEq, Eq)]
struct StaticMonitorProposition {
    formula: Formula,
    variable_domains: Vec<trust_types::CompilerContractVariableDomain>,
}

#[derive(Clone)]
struct ClauseMonitorRecord {
    /// Canonical combined source index: dense function contracts followed by
    /// loop contracts, matching the indices preserved in public contract ids.
    source_index: usize,
    kind: rustc_middle::mir::trust_contract::TrustContractKind,
    subject: rustc_middle::mir::trust_contract::TrustContractSubject,
    span: rustc_span::Span,
    /// Digest of the compiler-native predicate identity consumed by the
    /// monitor lane, never of source-span text.
    predicate_digest: String,
    /// Structural digest shared with the downstream static Formula. `None`
    /// means this query predicate was not structurally typed and therefore can
    /// never carry `Monitored` evidence.
    typed_proposition_digest: Option<String>,
    evidence: ClauseMonitorEvidence,
}

/// Invocation-scoped, per-clause monitor evidence. The Clean proof object is
/// checked before insertion; only its fully-bound executable payload crosses
/// into this cache. Unsupported clauses retain an explicit reason and have no
/// runtime representation.
#[derive(Default)]
struct SessionCertifiedMonitors {
    functions: FxHashMap<LocalDefId, Vec<ClauseMonitorRecord>>,
}

/// Trust: E9 in-walk ensures-citation discharge (design note
/// 2026-07-15-e9-discharge-criterion §5d). A CLONE of the island-checked Clean
/// kernel environment, stashed right after `trust_check_clean_islands` so the
/// per-body verification lane can adjudicate `ensures … by thm` citations
/// in-walk for the bounded result-bearing/self-definition and result-free
/// fragments. `None` while islands are unchecked or the session is tainted —
/// the discharge then never fires (fail-closed).
#[derive(Default)]
pub(crate) struct SessionIslandEnv {
    // Trust: pub(crate) for the R4 §1 recognition seam — the contract query
    // refines its unsupported-predicate diagnostics for island-cited calls
    // (read-only; the stash is written only here, right after island checking).
    pub(crate) env: Option<trust_certify::clean_island::KernelEnvironment>,
    /// The session checked no island and declared no callee, so `env` is
    /// deliberately unbuilt: it would be exactly Clean's prelude, which costs
    /// ~0.8 s per crate to build and which almost no crate reads. Readers go
    /// through [`session_island_env`], which builds it on first use.
    prelude_only: bool,
}

/// The island-checked Clean environment of this crate, if the session is
/// untainted — building the prelude-only environment on first use (see
/// `SessionIslandEnv::prelude_only`).
pub(crate) fn session_island_env(
    sess: &Session,
) -> Option<trust_certify::clean_island::KernelEnvironment> {
    sess.with_trust_compiler_state::<SessionIslandEnv, _>(|state| {
        if state.prelude_only {
            state.prelude_only = false;
            state.env =
                trust_certify::clean_island::CleanIslandSession::new().environment().cloned();
        }
        state.env.clone()
    })
}

/// Stash the session's environment for the per-body lanes, without building a
/// prelude nothing has asked for.
fn stash_session_island_env(
    sess: &Session,
    clean_session: &trust_certify::clean_island::CleanIslandSession,
) {
    let materialized = clean_session.environment_is_materialized();
    let env = if materialized { clean_session.environment().cloned() } else { None };
    let prelude_only = !materialized && !clean_session.is_tainted();
    sess.with_trust_compiler_state::<SessionIslandEnv, _>(|state| {
        state.env = env;
        state.prelude_only = prelude_only;
    });
}

/// Trust (GREEN THAT LIES, `docs/KNOWN_HAZARDS.md` 2026-09-18): every stand-in
/// disclosure this crate's Clean session accumulated, in the ONE wording
/// `trust_certify` owns (`CleanIslandStandinImport::disclosure`).
///
/// An `import Mathlib` inside a `clean { … }` island is served by Clean's
/// built-in prelude STAND-IN, never by the library of that name. Both seams
/// that accept an island already disclose that per-ISLAND, beside the island.
/// A kernel-discharged contract row is per-FUNCTION, and nothing connected the
/// two: a reader of the row alone saw an unqualified green. This stash is the
/// connection — written by [`trust_record_clean_origin_identity_rows`] from
/// the session that checked the islands, read by the per-clause discharge
/// notes, which repeat the disclosure beside the row it qualifies.
///
/// SESSION-scoped like its source: one crate gets one Clean `Environment` and
/// one `FileContext`, so the substitution is a fact about the provider set
/// every island shared, not about the island whose text spelled the `import`
/// (see `CleanIslandSession::standin_imports`). Empty for the overwhelming
/// majority of crates, which have no island `import` at all, so no existing
/// diagnostic gains a line.
///
/// KNOWN RESIDUAL, unmeasured: the stash is written twice, and the second
/// write is what learns about the DEFERRED island suffix (an island naming the
/// `trust_import_*` namespace, checked after program admissions are minted).
/// A note emitted DURING the body walk therefore cannot carry a disclosure
/// that only a deferred island introduces — it is not yet known. The
/// post-walk notes and every row-side record do carry it, because both the
/// stash and `install_island_admission` take the UNION rather than refusing a
/// changed set. Closing that window would mean deciding "served by a stand-in"
/// for an island before it is checked, which no honest reading of the text
/// alone can do.
///
/// The same window has a SECOND edge, also unmeasured, on the row side:
/// `trust_mint_program_admissions` runs ONCE and runs BEFORE the deferred
/// suffix, so a FORWARDING function's admission copies its callee's
/// disclosures as they stood then and is never re-stamped. The callee's own
/// identity row and every post-walk note do widen. Diagnostic-only either
/// way — nothing reads the field to decide a verdict — but a row-consuming
/// lane must not read an empty disclosure set as "no substitution" for a
/// crate with a deferred island.
#[derive(Default)]
struct SessionIslandStandinDisclosures {
    lines: Vec<String>,
}

/// Trust: the stand-in disclosures to repeat beside a kernel-discharged row.
/// Empty unless an island `import` of this crate was served by the prelude
/// stand-in.
fn trust_island_standin_disclosures(tcx: TyCtxt<'_>) -> Vec<String> {
    tcx.sess.with_trust_compiler_state::<SessionIslandStandinDisclosures, _>(|state| {
        state.lines.clone()
    })
}

/// Trust (two-language design item 10, phase 2): ensures-citations in a crate
/// that carries a DEFERRED island suffix.
///
/// Phase 1 defers any island whose text names the `trust_import_*` namespace
/// until after `trust_mint_program_admissions`, because the constants it talks
/// about do not exist before the walk. A clause citing a theorem out of that
/// suffix would see `TheoremNotFound` in-walk — a scheduling fact, not a
/// verdict. More subtly, a clause citing an EARLIER theorem could certify
/// in-walk and then outlive a rejected deferred suffix that taints the
/// authoritative session. Therefore every cited-ensures body that reaches the
/// citation-authority lane in such a crate is adjudicated after the suffix,
/// not only bodies whose theorem name happens to be deferred. Bodies rejected
/// before that lane cannot mint citation authority and need no quarantine.
///
/// Replaying the island INTO the walk instead is unsound, and cannot be repaired
/// inside that lane at any level of care: the in-walk environment holds only the
/// program admissions accumulated so far, so an island elaborated there can mean
/// something other than what the authoritative whole-crate check produces
/// (pinned by `tests/e6-fragment-probe/probes/d13_deferred_import_citation.rs`).
/// Parity is available only where the authoritative check already runs, so the
/// DISCHARGE moves post-walk rather than the island moving into the walk.
///
/// A body recorded here is QUARANTINED: `run_pass` publishes none of its
/// authority-dependent output (no human verdict report, no transport envelope,
/// no strict abort, no proof-authorized check elision), and
/// [`finalize_pending_import_citations`] publishes exactly one envelope for it
/// once the complete environment exists. The body is still credited in
/// `processed_bodies`, so whole-crate coverage accounting is untouched: this
/// withholds a body's SOLE envelope until the authoritative stage and never
/// emits a second, amending one.
#[derive(Default)]
struct SessionPendingImportCitations {
    /// Whether this crate carries at least one deferred island. Written once,
    /// before the body walk starts. A crate with no deferred suffix can have no
    /// pending citation, so an unregistered theorem name stays an ordinary
    /// fail-closed decline there and nothing about that path changes.
    crate_has_deferred_islands: bool,
    bodies: FxHashMap<LocalDefId, PendingImportCitation>,
    /// Trust (T3 L4, C07r; L4-E9-1): the VC contexts the records' provisional artifacts
    /// hold past their bodies' verify passes, counted.
    citation_holds: CitationContextHolds,
}

/// Trust (T3 L4, C07r; L4-E9-1): the bodies' VC contexts pending import citations held
/// past their verify passes (`contexts_held_for_citation`). A quarantined body's
/// provisional artifacts, and with them its context, stay attached to its record
/// ([`PendingImportCitation::artifacts`]) as a [`CitationHold`] until
/// [`finalize_pending_import_citations`] has amended and published them. Every other
/// body's context is released when its verify pass returns, because its compacted slot
/// holds none.
///
/// The hold ends when the [`CitationHold`] drops, wherever that is: after the amendment,
/// with a record replaced or drained and dropped unfinalized, or in an unwind. So `held`
/// counts exactly the holds still alive, by construction, whatever path a record takes.
#[derive(Debug, Default)]
struct CitationContextHolds {
    /// Shared with every live hold, which releases itself on drop. Atomic because the
    /// session state is `Send`; nothing contends for it.
    counts: Arc<CitationHoldCounts>,
}

#[derive(Debug, Default)]
struct CitationHoldCounts {
    /// Records that took provisional artifacts, each counted once.
    attached: std::sync::atomic::AtomicU64,
    /// Holds alive now.
    held: std::sync::atomic::AtomicU64,
    /// The most holds alive at once.
    max_held: std::sync::atomic::AtomicU64,
}

/// What the memory census reads of [`CitationContextHolds`] (field docs on
/// [`CitationHoldCounts`]).
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
struct CitationHoldCensus {
    attached: u64,
    held: u64,
    max_held: u64,
}

/// A pending citation's provisional artifacts, and the hold on the body's VC context they
/// count (L4-E9-1): it reads as the artifacts, and its hold ends when it drops.
struct CitationHold {
    artifacts: Arc<VerificationArtifacts>,
    counts: Arc<CitationHoldCounts>,
}

impl std::ops::Deref for CitationHold {
    type Target = VerificationArtifacts;

    fn deref(&self) -> &VerificationArtifacts {
        &self.artifacts
    }
}

impl Drop for CitationHold {
    fn drop(&mut self) {
        // Every live hold was counted when it was made, so `held` is never 0 here; the
        // update saturates anyway, so a miscount cannot wrap.
        let _ = self.counts.held.fetch_update(
            std::sync::atomic::Ordering::Relaxed,
            std::sync::atomic::Ordering::Relaxed,
            |held| Some(held.saturating_sub(1)),
        );
    }
}

impl CitationContextHolds {
    /// `slot` takes `artifacts`. The hold is counted once per record: a slot that already
    /// holds provisional artifacts keeps its hold and replaces them, and they drop.
    fn attach(&self, slot: &mut Option<CitationHold>, artifacts: &Arc<VerificationArtifacts>) {
        use std::sync::atomic::Ordering::Relaxed;
        if let Some(hold) = slot.as_mut() {
            hold.artifacts = Arc::clone(artifacts);
            return;
        }
        let _ = self
            .counts
            .attached
            .fetch_update(Relaxed, Relaxed, |attached| Some(attached.saturating_add(1)));
        let held = self
            .counts
            .held
            .fetch_update(Relaxed, Relaxed, |held| Some(held.saturating_add(1)))
            .map_or(u64::MAX, |before| before.saturating_add(1));
        let _ = self.counts.max_held.fetch_max(held, Relaxed);
        *slot = Some(CitationHold {
            artifacts: Arc::clone(artifacts),
            counts: Arc::clone(&self.counts),
        });
    }

    /// The counts now.
    fn census(&self) -> CitationHoldCensus {
        use std::sync::atomic::Ordering::Relaxed;
        CitationHoldCensus {
            attached: self.counts.attached.load(Relaxed),
            held: self.counts.held.load(Relaxed),
            max_held: self.counts.max_held.load(Relaxed),
        }
    }
}

/// Exact authored identity of one function-level cited `ensures` clause plus
/// the text the citation lane may grade. `Err` is retained as counted evidence:
/// source recovery and the query-owned canonical spelling both failed, so the
/// artifact exposes a preparation refusal rather than silently dropping the
/// clause.
#[derive(Clone)]
struct PendingImportCitationClause {
    contract_index: u64,
    clause: Result<String, String>,
    theorem: rustc_span::Symbol,
}

/// Invocation-scoped exactly-once ledger for compiler-authored cited-goal
/// rows. Dense `(owner, contract_index)` identity distinguishes two authored
/// clauses even when their text and theorem are byte-identical.
#[derive(Default)]
struct SessionEnsuresCitationGoalRows {
    emitted: FxHashSet<(LocalDefId, u64)>,
}

struct PendingImportCitation {
    /// Canonical crate-qualified identity, byte-identical to the spelling the
    /// coverage inventory uses (`safe_def_path_str`), because this body's single
    /// envelope is emitted under it from the post-walk stage.
    func_path: String,
    func: trust_types::VerifiableFunction,
    /// Every `ensures` clause of the function with its cited theorem, in
    /// authored order. The in-walk conjunction rule still governs: all of them
    /// must Certified-grade against the complete environment, or the body
    /// discharges nothing.
    cited: Vec<PendingImportCitationClause>,
    /// Trust: the UNCITED `ensures` clauses of a MIXED surface — dense contract
    /// index and clause span, in authored order; empty for an all-cited
    /// function. The conjunction rule covers them too: post-walk, each must
    /// name an admissible Clean island definition and kernel-discharge by
    /// definitional equality, or the body discharges nothing (see
    /// `grade_uncited_island_ensures_clause`).
    uncited: Vec<(u64, rustc_span::Span)>,
    /// Row indices the citation would discharge in the finally selected
    /// verification carrier, gated to solver-UNKNOWN / bare-Proved entries.
    /// The quarantine seam recomputes this list from the selected carrier so
    /// an E4→E5 second pass can never reuse first-pass row positions.
    postcondition_indices: Vec<usize>,
    /// The body's provisional artifacts, attached by `run_pass` when it
    /// quarantines. `None` means the walk recorded the pending citation but
    /// never reached ordinary outcome publication for this body (a skip or
    /// abort lane returned first). Finalization still grades and emits every
    /// citation goal row, but has no verification envelope or VC rows to amend.
    /// Trust (T3 L4, C07r; L4-E9-1): held as a [`CitationHold`], which counts the
    /// body's VC context as held until it drops.
    artifacts: Option<CitationHold>,
}

/// Invocation-scoped E6 facet records (two-language design §3.1, v3
/// no-marker ruling): per-function `Pure ∧ Total ∧ Deterministic ∧ NoPanic`
/// findings from the structural scan, keyed by the extracted `def_path` AND
/// by every path SPELLING a spec could write for it
/// ([`trust_spec_elab::spec_spellings`] — the bare name and each proper
/// module-path suffix, e.g. `narrow` and `guard::narrow` for
/// `lib::guard::narrow`). A spelling that resolves to two different def_paths
/// is AMBIGUOUS: it is evicted from the table and blocked from re-insertion,
/// so a spec call under that spelling gets the fail-closed "no facet record"
/// diagnostic rather than either function's findings. Consumers are
/// diagnostics-only until the E6 admission gate mints a kernel-import
/// `Admission` — nothing else here can admit a call.
#[derive(Default)]
struct SessionFnFacets {
    table: trust_spec_elab::FacetTable,
    /// def_path currently backing each spelling key (collision detector).
    spelling_owner: FxHashMap<String, String>,
    /// spellings evicted after a collision; never re-inserted.
    ambiguous_spellings: FxHashSet<String>,
    /// Every extracted body, kept so the whole-crate call-graph composition
    /// (`trust_types::facet_inference::infer_facets`) can upgrade the per-body
    /// whitelist base with facets that only a cross-function view establishes
    /// (a caller of a trusted external / a certified internal). See
    /// [`SessionFnFacets::composed_table`].
    accumulated: Vec<trust_types::VerifiableFunction>,
}

impl SessionFnFacets {
    /// The facet table a consumer should read: the per-body whitelist base
    /// (already keyed by def_path AND every spec spelling with collision eviction),
    /// MONOTONICALLY upgraded by the whole-crate composition over every body
    /// accumulated so far. Composition is soundness-audited
    /// (`trust_types::facet_inference`) and only ever promotes
    /// `Undetermined → Certified`, so reading it against a partially-accumulated
    /// crate is sound — an as-yet-unseen callee just leaves a facet
    /// `Undetermined`. Diagnostics-only: nothing here admits a call, since no
    /// `Admission` is minted outside the kernel-import brick.
    fn composed_table(&self) -> trust_spec_elab::FacetTable {
        let mut table = self.table.clone();
        if self.accumulated.is_empty() {
            return table;
        }
        let inferred = trust_types::facet_inference::infer_facets(&self.accumulated);
        // Build the spelling-keyed rows first while borrowing `inferred`, via the
        // (spelling → def_path) map, so an unambiguous spelling a spec actually
        // writes is upgraded too, then consume `inferred` into `inferred_rows`
        // without cloning every `def_path` `String`. Ambiguous spellings were
        // evicted and are absent from both maps. Upgrade order (`inferred_rows`
        // then `spelling_rows`) is preserved identically.
        #[allow(rustc::potential_query_instability)]
        let mut spelling_rows = self
            .spelling_owner
            .iter()
            .filter_map(|(spelling, dp)| {
                inferred
                    .get(dp)
                    .map(|fs| (spelling.clone(), fs.total, fs.no_panic, fs.pure, fs.deterministic))
            })
            .collect::<Vec<_>>();
        spelling_rows.sort_unstable_by(|left, right| left.0.cmp(&right.0));
        // Upgrade the def_path-keyed records …
        // `inferred` is a HashMap. Its order cannot affect the monotone
        // upgrade, but sorting also keeps diagnostics and future table changes
        // deterministic instead of relying on that order-independence.
        #[allow(rustc::potential_query_instability)]
        let mut inferred_rows = Vec::with_capacity(inferred.len());
        #[allow(rustc::potential_query_instability)]
        for (dp, fs) in inferred {
            inferred_rows.push((dp, fs.total, fs.no_panic, fs.pure, fs.deterministic));
        }
        inferred_rows.sort_unstable_by(|left, right| left.0.cmp(&right.0));
        table.upgrade_from_structural(inferred_rows);
        table.upgrade_from_structural(spelling_rows);
        // Trust (joint cited theorem, 2026-09-15): a Rust body that is ONE call
        // into a Clean-origin def (`fn pb_max_r(l, r) -> u64 { pb_max(l, r) }`)
        // has facets the structural closure can never close — its callee is an
        // island item the verifier never walks — so its `ensures` could not be
        // E6-admitted and a cited theorem about the island def was checked
        // against a ∀-closed `result`. This monotone closure certifies exactly
        // the forwarding bodies whose callee row is KernelChecked (Refuted is
        // never promoted; no record → nothing invented). ONE choke point feeds
        // every consumer: the in-walk cited/uncited routes, the program
        // admissions mint, and the citation sweep.
        trust_certify::clean_island::certify_clean_origin_forwarding_facets(
            &self.accumulated,
            &mut table,
        );
        table
    }
}

/// Trust (W5 increment 3, 2026-09-25): the Clean-origin defs whose `RustCallChain`
/// callees this crate CHARGED and whose charge passed.
///
/// A `RustCallChain` def's emitted body computes its declaration ONLY IF every Rust
/// callee returns — the kernel proved `twice_inc ≡ inc (inc x)` with `inc` an OPAQUE
/// constant it can prove nothing about. Until this set exists, every such def is
/// fail-closed at [`clean_origin_call_model_of_record`], so its callers take the fatal
/// absent-callee arm and no bidirectional program is verify-on green.
///
/// WHY PRE-WALK AND NOT POST-WALK. The design of record anchors this charge "after"
/// the body walk. That cannot work: both consumers of the call model run EARLIER —
/// the panic-free registration loop runs before the walk, and the absent-call-identity
/// site is evaluated per call site DURING it — so a set published post-walk is empty
/// when it is read, and the charge could refuse but never license. The charge is
/// therefore taken PRE-WALK.
///
/// KNOWN RESIDUE, stated because a documented guard that does not run is worse than an
/// admitted gap: there is NO post-walk re-check. The composed facet table is not
/// monotone in two ways — `infer_facets` zeroes a whole group on a duplicate
/// `def_path`, and `record_fn_facets` evicts a colliding key forever — so a licence
/// taken here can rest on a row the FINAL table no longer carries. Closing that needs a
/// post-walk pass re-deriving every licensed verdict against the final table and
/// hard-erroring on a changed one. It is NOT built.
#[derive(Default)]
struct SessionCleanRustCallChainCharged {
    /// Set once the pre-walk charge has run, so a reader can tell "charged, nothing
    /// passed" from "never charged" — the second must never license anything.
    charged: bool,
    admitted: FxHashSet<DefId>,
}

/// Facet evidence that CANNOT license a Clean-origin def's Rust callee, because it is
/// itself derived from a Clean declaration.
///
/// `certify_clean_origin_forwarding_facets` promotes a one-call forwarder into a
/// kernel-checked island def to four `Certified`, and `install_island_admission` stamps
/// four `Certified` on every precondition-free Clean-origin def's Rust def-path. For
/// `inc -> twice_inc -> inc` that means the facet predicate ALONE answers
/// `admissible = true` for the cycle. Refusing these two evidence strings by name is
/// what stops a Clean declaration from certifying itself through its own callee.
const CIRCULAR_FACET_EVIDENCE: [&str; 2] =
    ["clean-origin-forwarding", "clean-island-kernel-definition"];

/// May this facet row license a Clean-origin def's Rust callee?
///
/// `Ok(())` only when all four facets are `Certified` AND none of them rests on
/// evidence derived from a Clean declaration. Every other state — `Unknown`,
/// `Undetermined`, `Refuted`, or circular evidence — is a refusal carrying its reason.
fn charge_facet_row(facets: &trust_spec_elab::FnFacets) -> Result<(), String> {
    use trust_spec_elab::FacetStatus;
    if !facets.admissible() {
        return Err(facets.deficits().join(", "));
    }
    // `FnFacets::facets()` is private, so the four are named here. They are `pub`
    // fields, and the compiler will not let this list silently fall behind a fifth.
    let named: [(&str, &FacetStatus); 4] = [
        ("Pure", &facets.pure),
        ("Total", &facets.total),
        ("Deterministic", &facets.deterministic),
        ("NoPanic", &facets.no_panic),
    ];
    for (name, status) in named {
        if let FacetStatus::Certified { evidence } = status
            && CIRCULAR_FACET_EVIDENCE.iter().any(|circular| evidence.contains(circular))
        {
            return Err(format!(
                "{name} is established only by `{evidence}` — evidence derived from a \
                 Clean declaration, which cannot license a Clean declaration"
            ));
        }
    }
    Ok(())
}

/// Trust (W5 increment 3): charge every `RustCallChain` def's Rust callees against the
/// composed E6 facet table, and publish the passing set.
///
/// The kernel proved the emitted chain definitionally equal to the island's own
/// application term, but with each Rust callee an OPAQUE constant: the binary computes
/// the declaration ONLY IF every call returns. That conditional is closed here, by the
/// callee's own `Pure ∧ Total ∧ Deterministic ∧ NoPanic` — the same predicate E6 uses.
///
/// FAIL-CLOSED EVERYWHERE. A callee with no facet row, any non-`Certified` facet,
/// circular evidence, a non-local callee, or a plan that will not resolve leaves its def
/// OUT of the set, and an absent def stays on the fatal absent-callee arm exactly as
/// before this pass existed. Nothing here can turn a refusal into a licence.
///
/// This charge is a conservative structural scan closed over the call graph — it is NOT
/// a Clean kernel re-check, and `docs/TCB.md` carries that row.
fn trust_charge_clean_rust_callees(tcx: TyCtxt<'_>) {
    // Each `RustCallChain` def with the Rust callees its chain actually names — never
    // `plan.callees()`, which is the whole crate's admitted callee table — or `None`
    // when one of them cannot be charged at all.
    let mut chains: Vec<(DefId, Option<Vec<DefId>>)> = Vec::new();
    for local in crate::clean_origin_mir::clean_origin_defs(tcx) {
        let def_id = local.to_def_id();
        let Some(plan) = clean_origin_plan_of_record(tcx, def_id) else { continue };
        let trust_clean_origin::CleanOriginShape::RustCallChain { nodes } = plan.shape() else {
            continue;
        };
        let Some((_name, span)) = crate::clean_origin_mir::clean_origin_registry_entry(tcx, local)
        else {
            continue;
        };
        // A chain with no node licenses nothing: refuse rather than vacuously pass.
        if nodes.is_empty() {
            continue;
        }
        let callees = nodes
            .iter()
            .map(|node| {
                if node.callee >= plan.callees().len() {
                    return None;
                }
                let callee =
                    crate::clean_origin_mir::resolve_rust_callee(tcx, &plan, node.callee, span);
                callee.is_local().then_some(callee)
            })
            .collect::<Option<Vec<DefId>>>();
        chains.push((def_id, callees));
    }
    if chains.is_empty() {
        tcx.sess.with_trust_compiler_state::<SessionCleanRustCallChainCharged, _>(|state| {
            state.charged = true;
            state.admitted = FxHashSet::default();
        });
        return;
    }
    // The facet table holds only the bodies verified so far, so verify every named
    // callee (and, through its bundle, what it calls) BEFORE reading it: the charge
    // must not depend on which other demand happened to verify a callee first. (It
    // used to rest on the Clean purity guard's `optimized_mir` demand, which ran
    // inside `mir_for_ctfe`; the guard now reads a pre-steal fact and verifies
    // nothing.) This is the analysis seam, outside every type-system query, where the
    // walk below demands the same bodies anyway; the order is the chains'.
    for (_, callees) in &chains {
        for &callee in callees.iter().flatten() {
            let _ = tcx.optimized_mir(callee);
        }
    }
    // `composed_table()` is uncached and runs a least-fixpoint over every accumulated
    // body, so it is read ONCE for the whole charge, never per callee.
    let facet_table =
        tcx.sess.with_trust_compiler_state::<SessionFnFacets, _>(|state| state.composed_table());

    let mut admitted = FxHashSet::default();
    for (def_id, callees) in chains {
        let Some(callees) = callees else { continue };
        // The facet table is keyed by the EXTRACTOR's def-path. `RustCalleeRef::
        // def_path` is a different producer's rendering and must never be used here.
        let all_charged = callees.iter().all(|&callee| {
            let key = trust_mir_extract::safe_def_path_str(tcx, callee);
            matches!(facet_table.get(&key).map(charge_facet_row), Some(Ok(())))
        });
        if all_charged {
            admitted.insert(def_id);
        }
    }

    tcx.sess.with_trust_compiler_state::<SessionCleanRustCallChainCharged, _>(|state| {
        state.charged = true;
        state.admitted = admitted;
    });
}

/// Trust (joint cited theorem, 2026-09-15): give every Clean-origin def a
/// compiler-facing IDENTITY row in the E6 facet table — its Rust def-path keyed
/// to the SAME audited `KernelChecked` island admission the island route minted,
/// four Certified facets. Without this row a Rust body that is one call into the
/// island def (`fn pb_max_r(l, r) -> u64 { pb_max(l, r) }`) can never be
/// E6-admitted: its callee is an island item the verifier never walks, so the
/// structural closure leaves every facet `Undetermined`, `result` in its
/// `ensures` is ∀-closed, and a cited theorem ABOUT `pb_max` is checked against
/// `∀ result lhs, lhs <= result` — a TypeMismatch that read as an audit defect
/// and was not one.
///
/// Fail-closed shape: only a def whose plan carries NO caller precondition is
/// recorded (the row claims `no_panic` at every call site); an ambiguous Rust
/// spelling is skipped; the identity is keyed by exact def-path; and a refused
/// admission leaves NO row (`TRUST_E6_DEBUG` prints why). A later Rust item that
/// collides on the spelling EVICTS rather than overwrites, via `spelling_owner`.
///
/// Trust (GREEN THAT LIES, 2026-09-18): this is also where the crate's STAND-IN
/// qualification is threaded. Takes the SESSION rather than a bare environment
/// for exactly that reason — the environment alone cannot say which of its
/// islands' `import`s were served by Clean's built-in prelude stand-in, and
/// `CleanIslandOutcome::standin_imports` (whose doc states the invariant: a
/// consumer reporting `registered` reports these alongside it) is reachable
/// only from the session that checked them. Every row minted here carries them
/// (`admit_clean_origin_callee_identity`), and the same set is stashed in
/// [`SessionIslandStandinDisclosures`] for the per-clause discharge notes.
/// Nothing about admissibility changes: a stand-in-served island is admitted
/// exactly as before, with more information attached to the row.
///
/// Both call sites run it, and the second runs AFTER the deferred island
/// suffix is checked — so the set can be larger the second time, which is why
/// the stash and the row-side merge both take the union rather than refusing a
/// changed set.
fn trust_record_clean_origin_identity_rows(
    tcx: TyCtxt<'_>,
    clean_session: &trust_certify::clean_island::CleanIslandSession,
) {
    // Stash the qualification first and unconditionally: it qualifies every
    // kernel-discharged row of this crate, including the cited-theorem rows of
    // a crate that has no Clean-origin def at all, and a tainted session (whose
    // `environment()` is `None`) is a failing build whose notes must still say
    // what they were relative to.
    let disclosures = clean_session.standin_disclosures();
    tcx.sess.with_trust_compiler_state::<SessionIslandStandinDisclosures, _>(|state| {
        for line in &disclosures {
            if !state.lines.iter().any(|known| known == line) {
                state.lines.push(line.clone());
            }
        }
    });
    // An unmaterialized session checked no island, so it registered no
    // Clean-origin def and there is no row to record.
    if !clean_session.environment_is_materialized() {
        return;
    }
    let Some(env) = clean_session.environment() else { return };
    let standin_imports = clean_session.standin_imports();
    let mut rows: Vec<(clean_kernel::Name, String)> = Vec::new();
    for def in crate::clean_origin_mir::clean_origin_defs(tcx) {
        let Some((name, span)) = crate::clean_origin_mir::clean_origin_registry_entry(tcx, def)
        else {
            continue;
        };
        // `no_panic` at every call site requires a plan with NO caller
        // precondition; a contracted def is not identity-admissible here.
        let Some(plan) = clean_origin_plan_of_record(tcx, def.to_def_id()) else { continue };
        if !plan.preconditions().is_empty() {
            continue;
        }
        rows.push((
            crate::clean_origin_mir::clean_source_name(tcx, &name, span),
            trust_mir_extract::safe_def_path_str(tcx, def.to_def_id()),
        ));
    }
    tcx.sess.with_trust_compiler_state::<SessionFnFacets, _>(|state| {
        for (clean_name, rust_path) in rows {
            if state.ambiguous_spellings.contains(&rust_path) {
                continue;
            }
            match trust_certify::clean_island::admit_clean_origin_callee_identity(
                env,
                &clean_name,
                &rust_path,
                standin_imports,
                &mut state.table,
            ) {
                Ok(_) => {
                    // A later Rust spelling collision must EVICT, never overwrite.
                    state
                        .spelling_owner
                        .entry(rust_path.clone())
                        .or_insert_with(|| rust_path.clone());
                }
                Err(reason) => {
                    if trust_env_var_present("TRUST_E6_DEBUG") {
                        eprintln!(
                            "TRUST_E6_DEBUG clean-origin identity fn={rust_path} REFUSED: {reason}"
                        );
                    }
                }
            }
        }
    });
}

/// Fast process-cached presence check for `TRUST_*` diagnostic/trace environment
/// variables inside `rustc_mir_transform` (where no code mutates process env vars).
pub(crate) fn trust_env_var_present(name: &str) -> bool {
    static PRESENT: std::sync::OnceLock<FxHashSet<String>> = std::sync::OnceLock::new();
    PRESENT
        .get_or_init(|| {
            std::env::vars_os()
                .filter_map(|(k, _)| k.into_string().ok())
                .filter(|k| k.starts_with("TRUST_"))
                .collect()
        })
        .contains(name)
}

/// Record the structural E6 facet scan of one extracted body into the
/// session table. Runs on the main per-body verification path, AFTER loop
/// clauses are bound (the scan sees the same `func` VC generation sees).
fn record_fn_facets(sess: &rustc_session::Session, func: &trust_types::VerifiableFunction) {
    use trust_spec_elab::{FacetStatus, FnFacets};
    use trust_vcgen::facets::FacetFinding;

    let to_status = |finding: &FacetFinding| match finding {
        // `Certified` is the legacy public spelling for a positive diagnostic
        // finding. FacetTable exposes no admission constructor, so this value
        // cannot authorize definitional use of the function.
        FacetFinding::Established { evidence } => {
            FacetStatus::Certified { evidence: evidence.clone() }
        }
        // A scan miss is NOT a refutation: the property may hold, the
        // structural lane just cannot see it. Undetermined keeps the reason
        // for the diagnostic without overclaiming in either direction.
        FacetFinding::NotEstablished { reason } => {
            FacetStatus::Undetermined { reason: reason.clone() }
        }
    };
    let scan = trust_vcgen::facets::scan_structural_facets(func);
    let facets = FnFacets {
        pure: to_status(&scan.pure),
        total: to_status(&scan.total),
        deterministic: to_status(&scan.deterministic),
        no_panic: to_status(&scan.no_panic),
    };
    let def_path = func.def_path.clone();
    // Every key this item may be looked up under: its canonical def-path, then
    // every path spelling a clause could write for it — the bare name and each
    // proper module-path suffix (`narrow`, `guard::narrow`).
    //
    // The def-path is registered through the SAME owner/eviction discipline as
    // the spellings rather than being inserted unconditionally. A suffix has
    // fewer segments than the def-path it came from, but it can still coincide
    // with a SHALLOWER item's whole def-path (crate `k`, items `k::k::f` and
    // `k::f`: the first's suffix `k::f` is the second's def-path). Letting a
    // spelling overwrite a def-path key would silently bind one function's
    // findings to another function's identity, so the two lanes share one
    // keyspace and one collision rule: two def_paths under one key evict it and
    // block it forever, and both items then fail closed under that key.
    let mut keys = vec![def_path.clone()];
    for spelling in trust_spec_elab::spec_spellings(&def_path) {
        if !keys.contains(&spelling) {
            keys.push(spelling);
        }
    }
    sess.with_trust_compiler_state::<SessionFnFacets, _>(|state| {
        // Keep the body for the whole-crate composition consumers read via
        // `composed_table`; the per-body whitelist insert below is its base.
        state.accumulated.push(func.clone());
        for key in keys {
            if state.ambiguous_spellings.contains(&key) {
                continue;
            }
            match state.spelling_owner.get(&key) {
                Some(owner) if *owner != def_path => {
                    // Second def_path under this key: evict, block forever.
                    state.table.remove(&key);
                    state.spelling_owner.remove(&key);
                    state.ambiguous_spellings.insert(key);
                }
                _ => {
                    state.spelling_owner.insert(key.clone(), def_path.clone());
                    state.table.insert(key, facets.clone());
                }
            }
        }
    });
}

const LOWERED_COMPILER_CONTRACT_PREFIX: &str = "__trust_lowered_compiler_contract__:";
const TRUST_MONITOR_STATUS_METADATA_KEY: &str = "trust.monitor.status";
const TRUST_MONITOR_REASON_METADATA_KEY: &str = "trust.monitor.reason";
const TRUST_MONITOR_PREDICATE_DIGEST_METADATA_KEY: &str = "trust.monitor.predicate_digest";
const TRUST_MONITOR_REASON_MAX_BYTES: usize = 512;
const TRUST_CONTRACT_PREDICATE_DIGEST_METADATA_KEY: &str = "trust.contract.predicate.digest.sha256";
const TRUST_CONTRACT_TYPED_PROPOSITION_DIGEST_METADATA_KEY: &str =
    "trust.contract.typed_proposition.digest.sha256";
const TRUST_VC_SOURCE_CONTRACT_INDEX_METADATA_KEY: &str = "trust.vc.source_contract_index.v1";
const TRUST_VC_SOURCE_CONTRACT_ROLE_METADATA_KEY: &str = "trust.vc.source_contract_role.v1";

/// Parse the compiler-owned monitor record at the boundary where the original
/// verifier bundle becomes private row bindings. Metadata returned by a
/// verifier run is deliberately never passed here: a backend cannot promote a
/// clause to `monitored` by reflecting or rewriting public metadata.
///
/// Every field must occur exactly once and satisfy the compiler's canonical
/// wire shape. A missing, duplicated, truncated, or future value fails closed
/// to no monitor evidence; in particular it can never create `Monitored`.
fn transport_monitor_evidence_from_metadata(
    metadata: &[trust_verifier_api::MetadataEntry],
) -> Option<TransportMonitorEvidence> {
    let mut status_raw: Option<&str> = None;
    let mut reason_raw: Option<&str> = None;
    let mut digest_raw: Option<&str> = None;
    for entry in metadata {
        match entry.key.as_str() {
            TRUST_MONITOR_STATUS_METADATA_KEY => {
                if status_raw.replace(entry.value.as_str()).is_some() {
                    return None;
                }
            }
            TRUST_MONITOR_REASON_METADATA_KEY => {
                if reason_raw.replace(entry.value.as_str()).is_some() {
                    return None;
                }
            }
            TRUST_MONITOR_PREDICATE_DIGEST_METADATA_KEY => {
                if digest_raw.replace(entry.value.as_str()).is_some() {
                    return None;
                }
            }
            _ => {}
        }
    }

    let status = match status_raw? {
        "monitored" => TransportMonitorStatus::Monitored,
        "measured" => TransportMonitorStatus::Measured,
        "unmonitored" => TransportMonitorStatus::Unmonitored,
        _ => return None,
    };
    let reason = reason_raw?;
    if reason.trim().is_empty() || reason.len() > TRUST_MONITOR_REASON_MAX_BYTES {
        return None;
    }
    let predicate_digest = digest_raw?;
    let digest = predicate_digest.strip_prefix("sha256:")?;
    if digest.len() != 64
        || !digest.bytes().all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return None;
    }

    Some(TransportMonitorEvidence {
        status,
        reason: reason.to_string(),
        predicate_digest: predicate_digest.to_string(),
    })
}

/// Recover the canonical spelling retained next to the compiler-query
/// proposition. There is deliberately no source-span fallback. Monitor
/// authority is minted only later, when the query-owned structural tree, this
/// spelling, the downstream Formula, and Clean's executable tree all agree.
fn canonical_monitor_predicate_text(
    predicate: &rustc_middle::mir::trust_contract::TrustContractPredicateKind,
) -> Result<String, String> {
    use rustc_middle::mir::trust_contract::TrustContractPredicateKind;

    match predicate {
        TrustContractPredicateKind::Typed { text, .. } => {
            canonical_monitor_opaque_predicate_text(text.as_str())
        }
        TrustContractPredicateKind::Opaque { text } => {
            canonical_monitor_opaque_predicate_text(text.as_str())
        }
        TrustContractPredicateKind::BoolLiteral { value } => Err(format!(
            "compiler-native BoolLiteral({value}) has no certified monitor in the current fragment"
        )),
        TrustContractPredicateKind::MirLocal { local } => Err(format!(
            "compiler-native MIR-local predicate _{} has no certified monitor",
            local.as_usize()
        )),
        TrustContractPredicateKind::Unsupported { reason } => {
            Err(format!("compiler-native contract predicate is unsupported: {reason}"))
        }
    }
}

fn canonical_monitor_opaque_predicate_text(text: &str) -> Result<String, String> {
    let body = text.strip_prefix(LOWERED_COMPILER_CONTRACT_PREFIX).unwrap_or(text).trim();
    if body.is_empty() {
        Err("compiler-native contract predicate is empty".to_string())
    } else {
        Ok(body.to_string())
    }
}

fn monitor_expression_class(
    kind: TrustContractKind,
) -> trust_types::CompilerContractExpressionClass {
    if kind == TrustContractKind::Decreases {
        trust_types::CompilerContractExpressionClass::Measure
    } else {
        trust_types::CompilerContractExpressionClass::Proposition
    }
}

fn canonical_monitor_predicate_digest(
    kind: TrustContractKind,
    predicate: &rustc_middle::mir::trust_contract::TrustContractPredicateKind,
) -> String {
    use rustc_middle::mir::trust_contract::TrustContractPredicateKind;

    let identity = match predicate {
        TrustContractPredicateKind::Typed { text, proposition } => {
            let text = text.as_str();
            let body = text.strip_prefix(LOWERED_COMPILER_CONTRACT_PREFIX).unwrap_or(text).trim();
            match trust_mir_extract::trust_contract_proposition_to_formula_and_domains_for_class(
                proposition,
                monitor_expression_class(kind),
            ) {
                Ok((formula, domains)) => format!(
                    "typed:{body}:{}",
                    trust_types::typed_contract_proposition_digest(&formula, &domains)
                ),
                Err(reason) => format!("typed-invalid:{body}:{reason}"),
            }
        }
        TrustContractPredicateKind::Opaque { text } => {
            let text = text.as_str();
            let body = text.strip_prefix(LOWERED_COMPILER_CONTRACT_PREFIX).unwrap_or(text).trim();
            format!("opaque:{body}")
        }
        TrustContractPredicateKind::BoolLiteral { value } => format!("bool:{value}"),
        TrustContractPredicateKind::MirLocal { local } => {
            format!("mir-local:{}", local.as_usize())
        }
        TrustContractPredicateKind::Unsupported { reason } => {
            format!("unsupported:{}", reason.as_str())
        }
    };
    format!(
        "sha256:{}",
        domain_length_bound_sha256_hex("trust.monitor.predicate.v1", identity.as_bytes())
    )
}

/// Recover the query-owned static proposition and verify that the retained
/// spelling round-trips to exactly the same formula. Opaque/bool/MIR-local
/// rows deliberately have no typed monitor carrier.
fn canonical_monitor_static_proposition(
    kind: TrustContractKind,
    predicate: &rustc_middle::mir::trust_contract::TrustContractPredicateKind,
) -> Result<StaticMonitorProposition, String> {
    use rustc_middle::mir::trust_contract::TrustContractPredicateKind;

    let TrustContractPredicateKind::Typed { text, proposition } = predicate else {
        return Err("compiler contract predicate has no query-owned typed proposition".to_string());
    };
    let class = monitor_expression_class(kind);
    let (formula, variable_domains) =
        trust_mir_extract::trust_contract_proposition_to_formula_and_domains_for_class(
            proposition,
            class,
        )?;
    let body = text
        .as_str()
        .strip_prefix(LOWERED_COMPILER_CONTRACT_PREFIX)
        .ok_or_else(|| {
            "typed compiler proposition is missing its canonical lowering prefix".to_string()
        })?
        .trim();
    if body.is_empty() {
        return Err("compiler-native contract predicate is empty".to_string());
    }
    let round_trip = trust_types::parse_spec_expr(body).and_then(|parsed| {
        trust_types::compiler_contract_formula_with_domains_for_class(
            &parsed,
            &variable_domains,
            class,
        )
    });
    if round_trip.as_ref() != Some(&formula) {
        return Err(
            "query-owned typed proposition does not structurally match its canonical spelling"
                .to_string(),
        );
    }
    Ok(StaticMonitorProposition { formula, variable_domains })
}

fn monitor_formula_variable_name(name: &str) -> &str {
    if name == "_0" { "result" } else { name }
}

/// Project the downstream static Formula into the executable monitor
/// vocabulary. This is intentionally exact and non-simplifying: associativity,
/// operand order, negation placement, and every literal must match the Clean
/// monitor tree. Any solver-only or wider static node rejects monitor authority.
fn static_runtime_monitor_domain(
    domain: trust_types::CompilerContractValueDomain,
) -> Result<trust_spec_elab::RuntimeMonitorDomain, String> {
    use trust_spec_elab::RuntimeMonitorDomain as Runtime;
    use trust_types::CompilerContractValueDomain as Static;

    match domain {
        Static::Bool => Ok(Runtime::Bool),
        Static::MachineInt { width: 8, signed: false } => Ok(Runtime::U8),
        Static::MachineInt { width: 16, signed: false } => Ok(Runtime::U16),
        Static::MachineInt { width: 32, signed: false } => Ok(Runtime::U32),
        Static::MachineInt { width: 64, signed: false } => Ok(Runtime::U64),
        Static::MachineInt { width: 128, signed: false } => Ok(Runtime::U128),
        Static::MachineInt { width: 8, signed: true } => Ok(Runtime::I8),
        Static::MachineInt { width: 16, signed: true } => Ok(Runtime::I16),
        Static::MachineInt { width: 32, signed: true } => Ok(Runtime::I32),
        Static::MachineInt { width: 64, signed: true } => Ok(Runtime::I64),
        Static::MachineInt { width: 128, signed: true } => Ok(Runtime::I128),
        Static::PointerSizedInt { width: 16, signed: false } => Ok(Runtime::USize16),
        Static::PointerSizedInt { width: 32, signed: false } => Ok(Runtime::USize32),
        Static::PointerSizedInt { width: 64, signed: false } => Ok(Runtime::USize64),
        Static::PointerSizedInt { width: 16, signed: true } => Ok(Runtime::ISize16),
        Static::PointerSizedInt { width: 32, signed: true } => Ok(Runtime::ISize32),
        Static::PointerSizedInt { width: 64, signed: true } => Ok(Runtime::ISize64),
        other => {
            Err(format!("static source domain {other:?} has no exact certified runtime carrier"))
        }
    }
}

fn static_monitor_domain_map(
    variable_domains: &[trust_types::CompilerContractVariableDomain],
) -> Result<BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>, String> {
    let mut domains = BTreeMap::new();
    let mut previous: Option<&str> = None;
    for entry in variable_domains {
        if let Some(previous) = previous
            && previous >= entry.name.as_str()
        {
            return Err("static monitor domain sidecar is not strictly name-sorted".to_string());
        }
        previous = Some(&entry.name);
        let name = monitor_formula_variable_name(&entry.name).to_string();
        let domain = static_runtime_monitor_domain(entry.domain)?;
        if domains.insert(name.clone(), domain).is_some() {
            return Err(format!("static source domain for `{name}` is duplicated"));
        }
    }
    Ok(domains)
}

fn runtime_monitor_sort(domain: trust_spec_elab::RuntimeMonitorDomain) -> Sort {
    if domain == trust_spec_elab::RuntimeMonitorDomain::Bool { Sort::Bool } else { Sort::Int }
}

fn static_formula_variable<'a>(formula: &'a Formula) -> Option<(&'a str, &'a Sort)> {
    match formula {
        Formula::Var(name, sort) => Some((name, sort)),
        Formula::SymVar(name, sort) => Some((name.as_str(), sort)),
        _ => None,
    }
}

fn collect_static_term_domain(
    formula: &Formula,
    domains: &BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>,
    found: &mut Option<trust_spec_elab::RuntimeMonitorDomain>,
) -> Result<(), String> {
    if let Some((name, sort)) = static_formula_variable(formula) {
        let name = monitor_formula_variable_name(name);
        let domain = domains.get(name).copied().ok_or_else(|| {
            format!("static monitor variable `{name}` has no exact source domain")
        })?;
        if sort != &runtime_monitor_sort(domain) {
            return Err(format!(
                "static monitor variable `{name}` has sort {sort:?}, expected {:?}",
                runtime_monitor_sort(domain)
            ));
        }
        match found {
            None => *found = Some(domain),
            Some(expected) if *expected == domain => {}
            Some(expected) => {
                return Err(format!(
                    "static monitor atom mixes runtime domains {expected:?} and {domain:?}"
                ));
            }
        }
        return Ok(());
    }
    match formula {
        Formula::Int(_) | Formula::UInt(_) | Formula::Bool(_) => Ok(()),
        Formula::Add(lhs, rhs)
        | Formula::Sub(lhs, rhs)
        | Formula::Mul(lhs, rhs)
        | Formula::Div(lhs, rhs)
        | Formula::Rem(lhs, rhs) => {
            collect_static_term_domain(lhs, domains, found)?;
            collect_static_term_domain(rhs, domains, found)
        }
        Formula::Neg(inner) => collect_static_term_domain(inner, domains, found),
        other => Err(format!(
            "static term node {other:?} is outside the exact certified-monitor fragment"
        )),
    }
}

fn static_atom_domain(
    lhs: &Formula,
    rhs: &Formula,
    domains: &BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>,
) -> Result<trust_spec_elab::RuntimeMonitorDomain, String> {
    let mut found = None;
    collect_static_term_domain(lhs, domains, &mut found)?;
    collect_static_term_domain(rhs, domains, &mut found)?;
    Ok(found.unwrap_or(trust_spec_elab::RuntimeMonitorDomain::Nat))
}

fn static_positive_literal(formula: &Formula) -> bool {
    match formula {
        Formula::Int(value) => *value > 0,
        Formula::UInt(value) => *value > 0,
        _ => false,
    }
}

fn runtime_monitor_domain_bits(domain: trust_spec_elab::RuntimeMonitorDomain) -> Option<u32> {
    use trust_spec_elab::RuntimeMonitorDomain as Domain;
    match domain {
        Domain::Nat => None,
        Domain::U8 | Domain::I8 => Some(8),
        Domain::U16 | Domain::I16 | Domain::USize16 | Domain::ISize16 => Some(16),
        Domain::U32 | Domain::I32 | Domain::USize32 | Domain::ISize32 => Some(32),
        Domain::U64 | Domain::I64 | Domain::USize64 | Domain::ISize64 => Some(64),
        Domain::U128 | Domain::I128 => Some(128),
        Domain::Bool => Some(1),
    }
}

fn runtime_monitor_domain_is_signed(domain: trust_spec_elab::RuntimeMonitorDomain) -> bool {
    use trust_spec_elab::RuntimeMonitorDomain as Domain;
    matches!(
        domain,
        Domain::I8
            | Domain::I16
            | Domain::I32
            | Domain::I64
            | Domain::I128
            | Domain::ISize16
            | Domain::ISize32
            | Domain::ISize64
    )
}

fn runtime_monitor_domain_mask(domain: trust_spec_elab::RuntimeMonitorDomain) -> Option<u128> {
    runtime_monitor_domain_bits(domain)
        .map(|bits| if bits == 128 { u128::MAX } else { (1_u128 << bits) - 1 })
}

fn static_monitor_literal(
    value: u128,
    domain: trust_spec_elab::RuntimeMonitorDomain,
) -> Result<trust_spec_elab::RuntimeMonitorExpr, String> {
    use trust_spec_elab::{RuntimeMonitorDomain as Domain, RuntimeMonitorExpr as Runtime};

    let max = match domain {
        Domain::Nat | Domain::U128 => u128::MAX,
        Domain::U8 => u128::from(u8::MAX),
        Domain::U16 => u128::from(u16::MAX),
        Domain::U32 => u128::from(u32::MAX),
        Domain::U64 => u128::from(u64::MAX),
        Domain::USize16 => u128::from(u16::MAX),
        Domain::USize32 => u128::from(u32::MAX),
        Domain::USize64 => u128::from(u64::MAX),
        Domain::I8 => i8::MAX as u128,
        Domain::I16 | Domain::ISize16 => i16::MAX as u128,
        Domain::I32 | Domain::ISize32 => i32::MAX as u128,
        Domain::I64 | Domain::ISize64 => i64::MAX as u128,
        Domain::I128 => i128::MAX as u128,
        Domain::Bool => 1,
    };
    if value > max {
        return Err(format!("static monitor literal {value} is out of range for {domain:?}"));
    }
    Ok(if value == 0 { Runtime::Zero } else { Runtime::Lit(value) })
}

fn static_monitor_negative_literal(
    magnitude: u128,
    domain: trust_spec_elab::RuntimeMonitorDomain,
) -> Result<trust_spec_elab::RuntimeMonitorExpr, String> {
    use trust_spec_elab::RuntimeMonitorExpr as Runtime;

    if !runtime_monitor_domain_is_signed(domain) {
        return Err(format!("negative static monitor literal has non-signed carrier {domain:?}"));
    }
    let bits = runtime_monitor_domain_bits(domain)
        .ok_or_else(|| format!("signed monitor carrier {domain:?} has no width"))?;
    let max_magnitude = 1_u128 << (bits - 1);
    if magnitude > max_magnitude {
        return Err(format!(
            "negative static monitor literal -{magnitude} is out of range for {domain:?}"
        ));
    }
    let mask = runtime_monitor_domain_mask(domain)
        .ok_or_else(|| format!("signed monitor carrier {domain:?} has no mask"))?;
    let pattern = 0_u128.wrapping_sub(magnitude) & mask;
    Ok(if pattern == 0 { Runtime::Zero } else { Runtime::Lit(pattern) })
}

fn static_formula_monitor_term(
    formula: &Formula,
    domain: trust_spec_elab::RuntimeMonitorDomain,
    domains: &BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>,
) -> Result<trust_spec_elab::RuntimeMonitorExpr, String> {
    use trust_spec_elab::{RuntimeMonitorDomain as Domain, RuntimeMonitorExpr as Runtime};

    if let Some((name, sort)) = static_formula_variable(formula) {
        let name = monitor_formula_variable_name(name);
        let actual = domains.get(name).copied().ok_or_else(|| {
            format!("static monitor variable `{name}` has no exact source domain")
        })?;
        if actual != domain || sort != &runtime_monitor_sort(domain) {
            return Err(format!(
                "static monitor variable `{name}` does not match atom domain {domain:?}"
            ));
        }
        return Ok(Runtime::Var(name.to_string()));
    }
    match formula {
        Formula::Bool(value) if domain == Domain::Bool => {
            static_monitor_literal(u128::from(*value), domain)
        }
        Formula::Int(value) if *value >= 0 => static_monitor_literal(*value as u128, domain),
        Formula::Int(value) => static_monitor_negative_literal(value.unsigned_abs(), domain),
        Formula::UInt(value) => static_monitor_literal(*value, domain),
        Formula::Neg(inner) => {
            if let Formula::Int(value) = &**inner
                && *value >= 0
            {
                return static_monitor_negative_literal(*value as u128, domain);
            }
            if let Formula::UInt(value) = &**inner {
                return static_monitor_negative_literal(*value, domain);
            }
            if !runtime_monitor_domain_is_signed(domain) {
                return Err(format!("static unary negation has non-signed carrier {domain:?}"));
            }
            Ok(Runtime::Sub(
                Box::new(Runtime::Zero),
                Box::new(static_formula_monitor_term(inner, domain, domains)?),
            ))
        }
        Formula::Add(lhs, rhs)
        | Formula::Sub(lhs, rhs)
        | Formula::Mul(lhs, rhs)
        | Formula::Div(lhs, rhs)
        | Formula::Rem(lhs, rhs) => {
            if domain == Domain::Bool {
                return Err("arithmetic is not supported for a Bool monitor atom".to_string());
            }
            // A variable-free numeric atom has no source carrier sidecar, so
            // Clean's executable projector defaults it to `Nat`. The static
            // proposition, however, uses mathematical `Int`: accepting
            // subtraction here would identify `Nat.sub` (truncated at zero)
            // with integer subtraction. For example, `0 - 1 == 0` is true for
            // the former and false for the latter. Keep that closed shape
            // unmonitored until the query carries an exact numeric domain or
            // the runtime lane grows an exact mathematical-Int carrier.
            if domain == Domain::Nat && matches!(formula, Formula::Sub(..)) {
                return Err("variable-free integer subtraction has no exact Nat runtime monitor"
                    .to_string());
            }
            if matches!(formula, Formula::Div(..) | Formula::Rem(..))
                && !static_positive_literal(rhs)
            {
                return Err(
                    "monitor division/remainder requires a positive literal divisor".to_string()
                );
            }
            let lhs = Box::new(static_formula_monitor_term(lhs, domain, domains)?);
            let rhs = Box::new(static_formula_monitor_term(rhs, domain, domains)?);
            Ok(match formula {
                Formula::Add(..) => Runtime::Add(lhs, rhs),
                Formula::Sub(..) => Runtime::Sub(lhs, rhs),
                Formula::Mul(..) => Runtime::Mul(lhs, rhs),
                Formula::Div(..) => Runtime::Div(lhs, rhs),
                Formula::Rem(..) => Runtime::Rem(lhs, rhs),
                // Trust: the outer arm already restricted `formula` to these
                // five. Refuse rather than abort the compilation if it did not.
                _ => {
                    return Err("monitor lowering: unexpected arithmetic formula shape".to_string());
                }
            })
        }
        other => Err(format!(
            "static term node {other:?} is outside the exact certified-monitor fragment"
        )),
    }
}

fn static_formula_monitor_prop(
    formula: &Formula,
    domains: &BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>,
) -> Result<trust_spec_elab::RuntimeMonitorExpr, String> {
    use trust_spec_elab::{RuntimeMonitorDomain as Domain, RuntimeMonitorExpr as Runtime};

    if let Some((name, sort)) = static_formula_variable(formula) {
        let name = monitor_formula_variable_name(name);
        let domain = domains.get(name).copied().ok_or_else(|| {
            format!("static monitor variable `{name}` has no exact source domain")
        })?;
        if domain != Domain::Bool || sort != &Sort::Bool {
            return Err("a bare static monitor variable must have exact Bool domain".to_string());
        }
        return Ok(Runtime::Eq(
            Box::new(Runtime::Var(name.to_string())),
            Box::new(Runtime::Lit(1)),
        ));
    }
    match formula {
        Formula::Bool(value) => {
            Ok(Runtime::Eq(Box::new(Runtime::Lit(u128::from(*value))), Box::new(Runtime::Lit(1))))
        }
        Formula::Not(inner) => {
            Ok(Runtime::Not(Box::new(static_formula_monitor_prop(inner, domains)?)))
        }
        Formula::And(terms) | Formula::Or(terms) => {
            let mut terms = terms.iter();
            let first = static_formula_monitor_prop(
                terms.next().ok_or_else(|| "empty static connective".to_string())?,
                domains,
            )?;
            terms.try_fold(first, |lhs, rhs| {
                let rhs = static_formula_monitor_prop(rhs, domains)?;
                Ok(if matches!(formula, Formula::And(_)) {
                    Runtime::And(Box::new(lhs), Box::new(rhs))
                } else {
                    Runtime::Or(Box::new(lhs), Box::new(rhs))
                })
            })
        }
        Formula::Eq(lhs, rhs)
        | Formula::Le(lhs, rhs)
        | Formula::Lt(lhs, rhs)
        | Formula::Ge(lhs, rhs)
        | Formula::Gt(lhs, rhs) => {
            let domain = static_atom_domain(lhs, rhs, domains)?;
            if domain == Domain::Bool && !matches!(formula, Formula::Eq(..)) {
                return Err("Bool monitor values are not ordered".to_string());
            }
            let lhs = Box::new(static_formula_monitor_term(lhs, domain, domains)?);
            let rhs = Box::new(static_formula_monitor_term(rhs, domain, domains)?);
            Ok(match formula {
                Formula::Eq(..) => Runtime::Eq(lhs, rhs),
                Formula::Le(..) => Runtime::Le(lhs, rhs),
                Formula::Lt(..) => Runtime::Lt(lhs, rhs),
                Formula::Ge(..) => Runtime::Ge(lhs, rhs),
                Formula::Gt(..) => Runtime::Gt(lhs, rhs),
                // Trust: as above — the outer arm restricted `formula` to these
                // five comparisons.
                _ => {
                    return Err("monitor lowering: unexpected comparison formula shape".to_string());
                }
            })
        }
        other => Err(format!(
            "static proposition node {other:?} is outside the exact certified-monitor fragment"
        )),
    }
}

fn static_formula_monitor_expr(
    formula: &Formula,
    variable_domains: &[trust_types::CompilerContractVariableDomain],
) -> Result<trust_spec_elab::RuntimeMonitorExpr, String> {
    let domains = static_monitor_domain_map(variable_domains)?;
    static_formula_monitor_prop(formula, &domains)
}

fn static_formula_measure_expr(
    formula: &Formula,
    variable_domains: &[trust_types::CompilerContractVariableDomain],
) -> Result<trust_spec_elab::RuntimeMonitorExpr, String> {
    let domains = static_monitor_domain_map(variable_domains)?;
    let mut domain = None;
    collect_static_term_domain(formula, &domains, &mut domain)?;
    let domain = domain.unwrap_or(trust_spec_elab::RuntimeMonitorDomain::Nat);
    static_formula_monitor_term(formula, domain, &domains)
}

fn collect_runtime_monitor_variables(
    expr: &trust_spec_elab::RuntimeMonitorExpr,
    variables: &mut Vec<String>,
) {
    use trust_spec_elab::RuntimeMonitorExpr as Runtime;
    match expr {
        Runtime::Var(name) => {
            if !variables.contains(name) {
                variables.push(name.clone());
            }
        }
        Runtime::Zero | Runtime::Lit(_) => {}
        Runtime::Not(inner) => collect_runtime_monitor_variables(inner, variables),
        Runtime::Add(lhs, rhs)
        | Runtime::Sub(lhs, rhs)
        | Runtime::Mul(lhs, rhs)
        | Runtime::Div(lhs, rhs)
        | Runtime::Rem(lhs, rhs)
        | Runtime::BitAnd(lhs, rhs)
        | Runtime::BitOr(lhs, rhs)
        | Runtime::BitXor(lhs, rhs)
        | Runtime::Eq(lhs, rhs)
        | Runtime::Le(lhs, rhs)
        | Runtime::Lt(lhs, rhs)
        | Runtime::Ge(lhs, rhs)
        | Runtime::Gt(lhs, rhs)
        | Runtime::And(lhs, rhs)
        | Runtime::Or(lhs, rhs) => {
            collect_runtime_monitor_variables(lhs, variables);
            collect_runtime_monitor_variables(rhs, variables);
        }
    }
}

fn bind_certified_monitor_to_static_formula(
    certified: trust_spec_elab::CertifiedMonitor,
    static_proposition: StaticMonitorProposition,
) -> Result<BoundCertifiedMonitor, String> {
    let runtime = certified.into_runtime();
    let StaticMonitorProposition { formula: static_formula, variable_domains } = static_proposition;
    let static_expr = static_formula_monitor_expr(&static_formula, &variable_domains)?;
    if runtime.expr() != &static_expr {
        return Err(format!(
            "Clean executable proposition {0:?} differs structurally from static proposition {1:?}",
            runtime.expr(),
            static_expr
        ));
    }
    let mut variables = Vec::new();
    collect_runtime_monitor_variables(&static_expr, &mut variables);
    if runtime.variables() != variables {
        return Err(format!(
            "Clean executable variables {:?} differ from static proposition variables {:?}",
            runtime.variables(),
            variables
        ));
    }
    validate_runtime_monitor_domains(&runtime, &variable_domains)?;
    // Closed Nat monitors are emitted as one compile-time Boolean constant.
    // Require that the reference evaluator can compute that constant exactly
    // now; otherwise metadata would claim `monitored` only for MIR insertion
    // to fail later (for example after an exact Nat term exceeds the bounded
    // u128 evaluator representation).
    if runtime.variables().is_empty() {
        runtime.evaluate(&[]).map_err(|reason| {
            format!("closed certified monitor is not exactly executable: {reason}")
        })?;
    }
    Ok(BoundCertifiedMonitor { runtime, static_formula, variable_domains })
}

fn bind_certified_measure_to_static_formula(
    certified: trust_spec_elab::CertifiedMeasure,
    static_proposition: StaticMonitorProposition,
) -> Result<BoundCertifiedMeasure, String> {
    let runtime = certified.into_runtime();
    let StaticMonitorProposition { formula: static_formula, variable_domains } = static_proposition;
    let static_expr = static_formula_measure_expr(&static_formula, &variable_domains)?;
    if runtime.expr() != &static_expr {
        return Err(format!(
            "Clean executable measure {0:?} differs structurally from static measure {1:?}",
            runtime.expr(),
            static_expr
        ));
    }
    let mut variables = Vec::new();
    collect_runtime_monitor_variables(&static_expr, &mut variables);
    if runtime.variables() != variables {
        return Err(format!(
            "Clean executable measure variables {:?} differ from static measure variables {:?}",
            runtime.variables(),
            variables
        ));
    }
    validate_runtime_measure_domains(&runtime, &variable_domains)?;
    if runtime.variables().is_empty() {
        runtime.evaluate(&[]).map_err(|reason| {
            format!("closed certified measure is not exactly executable: {reason}")
        })?;
    }
    Ok(BoundCertifiedMeasure { runtime, static_formula, variable_domains })
}

fn runtime_and_static_domains_match(
    runtime: trust_spec_elab::RuntimeMonitorDomain,
    static_domain: trust_types::CompilerContractValueDomain,
) -> bool {
    use trust_spec_elab::RuntimeMonitorDomain as Runtime;
    use trust_types::CompilerContractValueDomain as Static;
    matches!(
        (runtime, static_domain),
        (Runtime::U8, Static::MachineInt { width: 8, signed: false })
            | (Runtime::U16, Static::MachineInt { width: 16, signed: false })
            | (Runtime::U32, Static::MachineInt { width: 32, signed: false })
            | (Runtime::U64, Static::MachineInt { width: 64, signed: false })
            | (Runtime::U128, Static::MachineInt { width: 128, signed: false })
            | (Runtime::I8, Static::MachineInt { width: 8, signed: true })
            | (Runtime::I16, Static::MachineInt { width: 16, signed: true })
            | (Runtime::I32, Static::MachineInt { width: 32, signed: true })
            | (Runtime::I64, Static::MachineInt { width: 64, signed: true })
            | (Runtime::I128, Static::MachineInt { width: 128, signed: true })
            | (Runtime::USize16, Static::PointerSizedInt { width: 16, signed: false })
            | (Runtime::USize32, Static::PointerSizedInt { width: 32, signed: false })
            | (Runtime::USize64, Static::PointerSizedInt { width: 64, signed: false })
            | (Runtime::ISize16, Static::PointerSizedInt { width: 16, signed: true })
            | (Runtime::ISize32, Static::PointerSizedInt { width: 32, signed: true })
            | (Runtime::ISize64, Static::PointerSizedInt { width: 64, signed: true })
            | (Runtime::Bool, Static::Bool)
    )
}

fn validate_runtime_monitor_domains(
    runtime: &trust_spec_elab::RuntimeMonitor,
    variable_domains: &[trust_types::CompilerContractVariableDomain],
) -> Result<(), String> {
    if runtime.variables().is_empty() {
        if !runtime.domains().is_empty() || !variable_domains.is_empty() {
            return Err(
                "closed Clean monitor differs from variable-bearing static proposition".to_string()
            );
        }
        return Ok(());
    }
    if runtime.domains().len() != runtime.variables().len() {
        return Err("Clean monitor variable/domain tables are not an exact bijection".to_string());
    }
    let mut seen = BTreeSet::new();
    for runtime_name in runtime.variables() {
        if !seen.insert(runtime_name.as_str()) {
            return Err(format!("Clean monitor variable `{runtime_name}` is duplicated"));
        }
        let static_name = if runtime_name == "result" { "_0" } else { runtime_name.as_str() };
        let mut matches = variable_domains.iter().filter(|entry| entry.name == static_name);
        let domain = matches.next().ok_or_else(|| {
            format!("Clean variable `{runtime_name}` has no static source domain")
        })?;
        if matches.next().is_some() {
            return Err(format!("static source domain for `{runtime_name}` is duplicated"));
        }
        let runtime_domain = runtime
            .domain(runtime_name)
            .ok_or_else(|| format!("Clean variable `{runtime_name}` has no runtime domain"))?;
        let exact = runtime_and_static_domains_match(runtime_domain, domain.domain);
        if !exact {
            return Err(format!(
                "Clean runtime domain {:?} for `{runtime_name}` differs from static source domain {:?}",
                runtime_domain, domain.domain
            ));
        }
    }
    if variable_domains.len() != runtime.variables().len() {
        return Err(format!(
            "static proposition has {} domain binding(s), Clean monitor has {} variable(s)",
            variable_domains.len(),
            runtime.variables().len()
        ));
    }
    Ok(())
}

fn validate_runtime_measure_domains(
    runtime: &trust_spec_elab::RuntimeScalarTerm,
    variable_domains: &[trust_types::CompilerContractVariableDomain],
) -> Result<(), String> {
    if runtime.variables().is_empty() {
        if !runtime.domains().is_empty() || !variable_domains.is_empty() {
            return Err(
                "closed Clean measure differs from variable-bearing static expression".to_string()
            );
        }
        return Ok(());
    }
    if runtime.domains().len() != runtime.variables().len() {
        return Err("Clean measure variable/domain tables are not an exact bijection".to_string());
    }
    let mut seen = BTreeSet::new();
    for runtime_name in runtime.variables() {
        if !seen.insert(runtime_name.as_str()) {
            return Err(format!("Clean measure variable `{runtime_name}` is duplicated"));
        }
        let static_name = if runtime_name == "result" { "_0" } else { runtime_name.as_str() };
        let mut matches = variable_domains.iter().filter(|entry| entry.name == static_name);
        let static_domain = matches.next().ok_or_else(|| {
            format!("Clean measure variable `{runtime_name}` has no static source domain")
        })?;
        if matches.next().is_some() {
            return Err(format!(
                "static source domain for measure variable `{runtime_name}` is duplicated"
            ));
        }
        let runtime_domain = runtime.domains().get(runtime_name).copied().ok_or_else(|| {
            format!("Clean measure variable `{runtime_name}` has no runtime domain")
        })?;
        if !runtime_and_static_domains_match(runtime_domain, static_domain.domain) {
            return Err(format!(
                "Clean measure runtime domain {runtime_domain:?} for `{runtime_name}` differs from static source domain {:?}",
                static_domain.domain
            ));
        }
    }
    if variable_domains.len() != runtime.variables().len() {
        return Err(format!(
            "static measure has {} domain binding(s), Clean measure has {} variable(s)",
            variable_domains.len(),
            runtime.variables().len()
        ));
    }
    if runtime.domain()
        != runtime
            .variables()
            .first()
            .and_then(|name| runtime.domains().get(name).copied())
            .unwrap_or(trust_spec_elab::RuntimeMonitorDomain::Nat)
    {
        return Err("Clean measure result carrier differs from its variable carrier".to_string());
    }
    Ok(())
}

fn bounded_monitor_reason(reason: &str) -> String {
    if reason.len() <= TRUST_MONITOR_REASON_MAX_BYTES {
        return reason.to_string();
    }
    const ELLIPSIS: &str = "…";
    let mut end = TRUST_MONITOR_REASON_MAX_BYTES - ELLIPSIS.len();
    while !reason.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}{}", &reason[..end], ELLIPSIS)
}
