fn dyn_probe_enabled() -> bool {
    env_flag_enabled("TRUST_DYN_PROBE")
}

/// Whether one MIR owner belongs to the stdlib crate that is the current
/// verification subject. Both facts are required: stdlib MIR reached as a
/// dependency is non-local, while a local owner in an ordinary crate is not
/// stdlib merely because one of its expanded spans points there.
fn stdlib_subject_memory_safety_policy(def_id_is_local: bool, local_crate_name: &str) -> bool {
    def_id_is_local && trust_vcgen::is_stdlib_crate_name(local_crate_name)
}

fn verification_semantics_key(
    tcx: TyCtxt<'_>,
    sess: &Session,
    policy: &TrustVerifyPolicy,
) -> String {
    // Trust SOUNDNESS: the target triple + pointer width are result-determining
    // (pointer-width overflow obligations, `cfg(target_*)` MIR), but were folded
    // NOWHERE in the cache key — so one cache dir shared across cross-compile
    // targets could serve a proof computed for a different pointer width as a HIT
    // (a false-PROVE / unsound skip). Fold them in so the key is target-sound.
    // Trust (plan P4, T4.1): no solver segment. trustc's only SMT solver is the
    // ay linked into this compiler, so its identity is the compiler's own (the
    // seal identity, plan §4.2), and this key is invocation-scoped anyway.
    let target_key = verification_target_key(sess);
    verification_semantics_key_from_parts(
        policy,
        sess.opts.unstable_opts.trust_verify_level,
        sess.overflow_checks(),
        crate_types_are_whole_program(tcx),
        &target_key,
    )
}

fn verification_target_key(sess: &Session) -> String {
    format!("{};ptr{}", sess.target.llvm_target, sess.target.pointer_width)
}

fn verification_semantics_key_from_parts(
    policy: &TrustVerifyPolicy,
    proof_level: usize,
    overflow_checks: bool,
    whole_program: bool,
    target: &str,
) -> String {
    // Preserve the established cache tag after retiring the dead pipeline switch.
    let pipeline = "pipeline-v2";
    let base = format!(
        "v3;mode=Full;generated={generated};dependencies={dependencies};\
         level={proof_level};overflow_checks={overflow_checks};{pipeline};target={target}",
        generated = true,
        dependencies = policy.include_dependencies,
    );
    // Compose the whole-program segment via the shared trust-cache helper so the
    // compiler key and any trust-cache-side key fold the bit in byte-identically.
    trust_cache::compose_semantics_key(&base, whole_program)
}

/// A VC's exact key for the hashed exact sites (the dedupe, the definition-entry counts):
/// its structural fingerprint, the table's index, and its [`RowKey`], which decides. Trust
/// (T3 L4, C09): the key carries the row's identity beside its canonical string, so the
/// derived equality compares both through `RowKey::same` (L4-ORACLE-1, `row_key`'s docs).
#[derive(Debug, PartialEq, Eq)]
struct ExactVcKey {
    fingerprint: u64,
    canonical_payload: RowKey,
}

// Trust: production uses the shared original-VC claim encoder.
#[cfg(test)]
const EXACT_VC_CLAIM_SCHEMA_VERSION: &str =
    trust_types::original_vc_snapshot::EXACT_VC_CLAIM_SCHEMA_VERSION;
const EXACT_VC_CLAIM_DIGEST_DOMAIN: &str = "trustc.transport-exact-vc-claim.v3";

impl Hash for ExactVcKey {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        // Keep the structural fingerprint as the fast hash-table index, but
        // never treat it as equality. A 64-bit collision must only create an
        // extra equality comparison, not let one VC inherit another's proof.
        self.fingerprint.hash(state);
    }
}

fn exact_vc_key(vc: &VerificationCondition) -> Option<ExactVcKey> {
    Some(ExactVcKey {
        fingerprint: trust_vcgen::vc_fingerprint(vc),
        // `vc_fingerprint` intentionally omits source identity and contract
        // routing metadata and, like every fixed-width digest, can collide.
        // Equality therefore uses the complete serialized VC. This also keeps
        // otherwise-identical formulas with different contract metadata from
        // being routed/solved only once under the wrong policy.
        // Serialization failure means exact equality is unavailable. It must
        // disable deduplication/authority, never fall back to Debug text that
        // could collapse semantically different rows.
        // Trust (T3 L4, C09): the string decides; the key also carries the row's
        // identity, which the identity oracle compares beside it (`RowKey::same`).
        canonical_payload: RowKey::of(vc)?,
    })
}

/// Serialize the complete VC with recursively sorted JSON object keys. Derived
/// structs already have stable field order, but a VC can contain unordered maps
/// (notably temporal state-machine `labels`). Raw serde output would therefore
/// make equivalent claims depend on map insertion/bucket order. Arrays remain
/// ordered because their order is part of the model/formula semantics.
///
/// Trust (T3 L4, C09): an exact site compares this string only inside a [`RowKey`]
/// (`RowKey::of`), whose equality also counts the identity oracle; the elision audit's
/// row keys are the only other callers, and the census in `row_key`'s tests pins them.
fn canonical_exact_vc_payload(vc: &VerificationCondition) -> Option<String> {
    // i128-safe canonicalization (round-14): plain `serde_json::to_value` returns
    // Err for a VC whose formula carries an i128/u128 literal outside i64/u64/f64
    // range (`serde_json::Number` has no arbitrary precision), so a 128-bit
    // overflow VC produced NO exact-VC payload and could never mint authority —
    // it was PROVED-but-uncounted. `canonical_digest_json_value` tags big
    // integers as decimal strings, the same injective form the VC digest uses.
    let vc = trust_types::canonical_digest_json_value(vc).ok()?;
    let mut payload = String::with_capacity(256);
    write_canonical_json_value(&vc, &mut payload)?;
    Some(payload)
}

/// Bind the VC to the compiler semantics that are available at the
/// transport boundary. The target is optional only for the session-free unit
/// helper; production callers always supply `llvm_target;ptrN` from `Session`.
///
/// Trust (T3 L4, C09w; design §8, ROW-IDENTITY-1): claim v3, a hand-written encoder. It
/// starts with an exhaustive destructure of the VC, and of its obligation record and every
/// wrapper, so a field added to any of them does not compile until it is bound here. It
/// binds every non-formula field v2 bound, by the same canonical JSON (`kind`, `function`,
/// `location`, `contract_metadata`); every formula, the VC's own and each of its record's
/// (`body`, `subject`, each wrapper's facts or each path's guards, in order), by its Merkle
/// digest (`trust_types::formula_merkle`: a function of the tree, I5); the record's `width`
/// and each wrapper's and path's tag by value; and the semantics, as v2 did. A formula
/// with no Merkle digest gives no claim, as a VC that did not serialize gave none in v2: the
/// row then has no claim digest and mints no authority (fail-closed). There is no decoder
/// for v2, and its digest domain differs, so a v2 claim digest equals no v3 digest.
fn canonical_exact_vc_claim_payload(
    vc: &VerificationCondition,
    overflow_checks: bool,
    target: Option<&str>,
) -> Option<String> {
    // Trust: one shared implementation also validates persisted original VCs.
    trust_types::original_vc_snapshot::canonical_exact_vc_claim_payload(vc, overflow_checks, target)
}

fn write_canonical_json_string(value: &str, output: &mut String) -> Option<()> {
    // Fast path: printable ASCII without `"` or `\` needs no JSON escaping and
    // matches `serde_json::to_string` byte-for-byte without allocating.
    if value.bytes().all(|byte| (0x20..=0x7e).contains(&byte) && byte != b'"' && byte != b'\\') {
        output.reserve(value.len() + 2);
        output.push('"');
        output.push_str(value);
        output.push('"');
        return Some(());
    }
    output.push_str(&serde_json::to_string(value).ok()?);
    Some(())
}

fn write_canonical_json_value(value: &serde_json::Value, output: &mut String) -> Option<()> {
    use std::fmt::Write as _;

    match value {
        serde_json::Value::Null => output.push_str("null"),
        serde_json::Value::Bool(value) => output.push_str(if *value { "true" } else { "false" }),
        serde_json::Value::Number(value) => write!(output, "{value}").ok()?,
        serde_json::Value::String(value) => write_canonical_json_string(value, output)?,
        serde_json::Value::Array(values) => {
            output.push('[');
            for (index, value) in values.iter().enumerate() {
                if index != 0 {
                    output.push(',');
                }
                write_canonical_json_value(value, output)?;
            }
            output.push(']');
        }
        serde_json::Value::Object(values) => {
            output.push('{');
            let already_sorted = {
                let mut keys = values.keys();
                match keys.next() {
                    None => true,
                    Some(mut prev) => keys.all(|key| {
                        let ordered = prev <= key;
                        prev = key;
                        ordered
                    }),
                }
            };
            if already_sorted {
                for (index, (key, value)) in values.iter().enumerate() {
                    if index != 0 {
                        output.push(',');
                    }
                    write_canonical_json_string(key, output)?;
                    output.push(':');
                    write_canonical_json_value(value, output)?;
                }
            } else {
                let mut entries: Vec<_> = values.iter().collect();
                entries.sort_unstable_by(|(left, _), (right, _)| left.cmp(right));
                for (index, (key, value)) in entries.into_iter().enumerate() {
                    if index != 0 {
                        output.push(',');
                    }
                    write_canonical_json_string(key, output)?;
                    output.push(':');
                    write_canonical_json_value(value, output)?;
                }
            }
            output.push('}');
        }
    }
    Some(())
}

fn exact_vc_claim_digest_sha256(
    vc: &VerificationCondition,
    overflow_checks: bool,
    target: Option<&str>,
) -> Option<String> {
    let canonical_payload = canonical_exact_vc_claim_payload(vc, overflow_checks, target)?;
    Some(domain_length_bound_sha256_hex(EXACT_VC_CLAIM_DIGEST_DOMAIN, canonical_payload.as_bytes()))
}

/// Keep the first row of each exact identity, each with its id (T3 L4, C07: the rows are
/// carried with their ids in the body's context). A row with no exact identity is always
/// kept: its equality is unavailable, so it is never merged.
///
/// Trust (T3 L4, C09): the canonical keys decide, as on the parent. While the identity oracle
/// runs, the rows' identity partition is counted against it first (`row_key::count_partition`):
/// the dedupe's own lookups compare only keys whose strings hash alike, so two rows the
/// canonical keys keep apart and the identities would merge are counted only there.
fn dedupe_exact_vcs(rows: &mut BodyRows) {
    if row_key::oracle_runs() {
        let keys: Vec<RowKey> = rows.vcs().iter().filter_map(RowKey::of).collect();
        row_key::count_partition(&keys);
    }
    rows.dedupe_by(exact_vc_key);
}

#[derive(Clone)]
pub(crate) struct VerificationArtifacts {
    pub(crate) proof_results: TrustProofResults,
    pub(crate) telemetry: TrustProofTelemetry,
    // Trust (T3 L4, C07r): every row with its id in `ctx`, the body's VC context. Readers
    // see the rows as a slice; a writer has only the carrier's aligned operations.
    pub(crate) results: RowResults,
    pub(crate) transport_results: Vec<TransportObligationResult>,
    pub(crate) full_verification: Option<trust_router::VerificationRunResult>,
    // Trust: independently captured from this live body, never a proof payload.
    expanded_function_identity:
        Option<trust_types::expanded_function_identity::ExpandedFunctionIdentity>,
    // Exact, row-aligned identity and proof authority. These are deliberately
    // private capabilities: public `VerificationResult` / `ProofStrength`
    // labels cannot construct either one.
    result_bindings: Vec<Option<ResultObligationBinding>>,
    proof_authorities: Vec<Option<ResultProofAuthority>>,
    // Trust (runtime ledger): the fail-closed join map from a VC's canonical
    // string to the MIR block that emitted its overflow Assert. Private, in-memory
    // only (never serialized), so it cannot enter any equality/seal. Populated on
    // the native lane from the consumed generation's own rows (T3 C05); empty
    // elsewhere, which makes the elision seam a no-op.
    overflow_check_origins: OverflowCheckOrigins,
    // Trust (coroutine resume-state contract): the bridge's authenticated
    // evidence that THIS function's native lowering converted its ResumedAfter*
    // sentinels to refutable, solver-owned obligations under the recognized
    // resume-state entry contract. Extracted ONLY from the live native bundle's
    // module (`trust_ir_bridge::coroutine_resume_contract_module_evidence`) —
    // never from transport rows or re-pattern-matched MIR (the info-flow/
    // forgery class). Private and in-memory only, exactly like
    // `overflow_check_origins`: a deserialized or hand-built artifacts value
    // cannot carry it. `None` (every non-native constructor) keeps the
    // fail-closed `assumption:coroutine` + strict-abort behavior byte-for-byte.
    coroutine_resume_contract: Option<trust_ir_bridge::CoroutineResumeContractModuleEvidence>,
    // Trust (D9, 2026-09-27): the level `filter_vcs_by_level` applied to THIS
    // body's obligations, recorded where the filter ran
    // (`collect_verification_artifacts_inner_with_policy`) so the
    // `termination-unmeasured` charge reads the real filter instead of re-deriving
    // it (critique H6: `effective_max_level` also raises to L1 on bare
    // preconditions/postconditions). `collect_full_verification_artifacts` and its
    // `_once` pass take the level as a REQUIRED argument and set it in their
    // struct literal (review F4), so no future caller of either can leave it
    // unset. `None` only for every artifact that generated no obligations at all
    // (the synthetic single-Unknown-row constructors), which the charge treats as
    // "no termination claim in scope".
    max_proof_level: Option<trust_types::ProofLevel>,
    // Trust (2026-09-29): the bundled std/core/alloc members the native bundle's
    // Assert gate KEPT under the runtime-checked disposition
    // (`RuntimeCheckedStdMember`). Private and in-memory only, like
    // `coroutine_resume_contract`: minted only by the live bundle builder, so a
    // deserialized or hand-built artifacts value carries none. Non-empty makes
    // this function's verdict CONDITIONAL — one `runtime_checked` row per member
    // in the published rows (`runtime_checked_std_member_rows`), no panic-free
    // registration, and a `certify` refusal. Empty on every other constructor.
    runtime_checked_std_members: Vec<RuntimeCheckedStdMember>,
    // Current selected-carrier inputs for the late final-artifact report.
    // Data only; None on every synthetic/refused/non-native construction.
    calculus_reporting: Option<calculus_pending::Computation>,
    // Trust (T3 L4, C07; L4-CTX-1): the body's VC context, frozen. The consumed path and
    // the full lane own it mutably while they intern the generation's rows, their own and
    // (C07r) every results row, and `collect_full_verification_artifacts` freezes it into
    // this `Arc`; a clone of the artifacts shares it. Nothing reads a row from it yet
    // except the row oracle, whose count is written at publication as the function's
    // `PARITY <fn> row` audit row. A synthetic artifact holds a context of its own row.
    // `CompactArtifacts::project` leaves it out, so a compacted slot releases it; a pending
    // import citation holds it until its amendment (L4-E9-1).
    ctx: Arc<trust_types::vc_context::VcContext>,
}

/// Trust (runtime ledger): the fail-closed origin map for proven-overflow-check
/// elision. Built from the PRISTINE, pre-dedupe rows of the generation the compiler
/// consumed, each carried with its origin block from the safety walk (T3 C05,
/// `trust_vcgen::OverflowOrigins`), keyed by the row's [`RowKey`] (the SAME
/// formula-inclusive key a KernelCertified row seals as
/// `ExactResultRowIdentity.canonical_vc`), so identical-formula asserts in >=2
/// distinct blocks collapse to `Ambiguous` — the seam refuses to elide any of them
/// (the coalesce/macro over-license defense). A key only an arithmetic statement
/// produced is `Statement`: it counts toward `Ambiguous` but never resolves, because
/// that block's overflow `Assert` guards a different operation. A generation whose
/// enumeration is not complete (a truncated walk, a work-meter trip, a refused body,
/// misaligned origins) gives the empty map.
///
/// The key is the row's [`RowKey`] because that is what `KernelCertified` seals: the
/// canonical string decides, and the row's identity (§8 of
/// docs/design/2026-10-08-t3-memory-proportional-reconstruction.md) rides beside it. Trust
/// (T3 L4, C09; DECISION_QUEUE C05-ORIGIN-1): the table's key moved with KernelCertified
/// sealing, in the same commit, so every join compares through `RowKey::same` and the
/// identity oracle counts it; when C11 makes the identity decide, both move again together.
#[derive(Debug, Clone, Default)]
struct OverflowCheckOrigins(FxHashMap<RowKey, OverflowOrigin>);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OverflowOrigin {
    /// One block's overflow `Assert` produced the key.
    Unique(BasicBlock),
    /// Only an arithmetic statement in this block produced the key: no check to elide.
    Statement(BasicBlock),
    Ambiguous,
}

impl OverflowCheckOrigins {
    /// The table of one consumed generation's origins: its complete inventory, or the
    /// empty table when it has none.
    ///
    /// T3 L4 (C07): the inventory names each row by its id in the body's context, `rows`,
    /// and `eager` is each of the generation's rows by that id (see [`Self::from_rows`]).
    fn from_generation(
        tcx: TyCtxt<'_>,
        body: &Body<'_>,
        rows: &trust_types::vc_context::VcContext,
        eager: &FxHashMap<trust_types::vc_context::RowId, &VerificationCondition>,
        origins: &trust_vcgen::OverflowOrigins,
    ) -> Self {
        match origins.complete().and_then(|listed| Self::from_rows(rows, eager, listed)) {
            Some(table) => {
                audit_overflow_check_origins(tcx, body, "production", "complete", &table);
                table
            }
            None => {
                let table = Self::default();
                audit_overflow_check_origins(tcx, body, "production", "truncated", &table);
                table
            }
        }
    }

    /// The table of `origins`, each row read back from `rows` for today's key (T3 L4, C07).
    ///
    /// The eager row decides (L4-ORACLE-1): `eager` holds each generated row by its id, and
    /// a row's key is spelled from its read-back only where that agrees with the eager row
    /// in every field, from the eager row otherwise. So the table, and the checks it lets
    /// the elision seam delete, are the parent's by construction, whatever the context
    /// does. `None`, and no table, when an origin names a row the generation did not
    /// return: the inventory no longer lines up with the generation, so every check is
    /// kept.
    fn from_rows(
        rows: &trust_types::vc_context::VcContext,
        eager: &FxHashMap<trust_types::vc_context::RowId, &VerificationCondition>,
        origins: &[trust_vcgen::OriginRow],
    ) -> Option<Self> {
        let mut map: FxHashMap<RowKey, OverflowOrigin> = FxHashMap::default();
        // Trust (T3 L4, C09): every key the table was built from, in order, for the identity
        // partition below; collected only while the identity oracle runs.
        let mut keyed: Vec<RowKey> = Vec::new();
        for row in origins {
            let &eager_row = eager.get(&row.vc)?;
            let read_back = rows.materialize(row.vc).ok();
            let vc = match &read_back {
                Some(materialized)
                    if trust_types::vc_context::same_row(materialized.vc(), eager_row) =>
                {
                    materialized.vc()
                }
                _ => eager_row,
            };
            let Some(key) = RowKey::of(vc) else { continue };
            if row_key::oracle_runs() {
                keyed.push(key.clone());
            }
            let bb = BasicBlock::from_usize(row.block.0);
            let origin = match row.site {
                trust_vcgen::OriginSite::Assert => OverflowOrigin::Unique(bb),
                trust_vcgen::OriginSite::Statement => OverflowOrigin::Statement(bb),
            };
            // Any second origin that is not the same one makes the key ambiguous: another
            // block, or the same block's Assert beside one of its statements.
            map.entry(key)
                .and_modify(|o| {
                    if *o != origin {
                        *o = OverflowOrigin::Ambiguous;
                    }
                })
                .or_insert(origin);
        }
        // The lookups above compare only keys whose strings hash alike; two rows whose
        // strings differ and whose identities are one are counted here (`row_key`'s docs).
        row_key::count_partition(&keyed);
        Some(Self(map))
    }

    /// The unique origin block for a row's key, or `None` if absent or ambiguous.
    fn resolve(&self, key: &RowKey) -> Option<BasicBlock> {
        match self.0.get(key) {
            Some(OverflowOrigin::Unique(bb)) => Some(*bb),
            _ => None,
        }
    }

    /// Why `key` did not resolve, for the elision audit only.
    fn audit_miss(&self, key: &RowKey) -> &'static str {
        match self.0.get(key) {
            Some(OverflowOrigin::Ambiguous) => "ambiguous",
            Some(OverflowOrigin::Statement(_)) => "statement",
            Some(OverflowOrigin::Unique(_)) => "unique",
            None => "absent",
        }
    }

    /// `[unique, ambiguous]` key counts, for the elision audit only (a statement-only
    /// key is in neither).
    fn audit_counts(&self) -> [usize; 2] {
        let mut unique = 0usize;
        let mut ambiguous = 0usize;
        // A count is independent of the map's iteration order.
        #[allow(rustc::potential_query_instability)]
        for origin in self.0.values() {
            match origin {
                OverflowOrigin::Unique(_) => unique += 1,
                OverflowOrigin::Ambiguous => ambiguous += 1,
                OverflowOrigin::Statement(_) => {}
            }
        }
        [unique, ambiguous]
    }
}

// Trust (T3 C05, 2026-10-11): `TRUST_ELIDE_AUDIT=<dir>` records the elided-Assert set
// and each function's origin table, outside stderr (see the module).
mod elide_audit;

// Replay observations travel with their selected proof, and are published only
// while the final row still carries that proof. They confer no authority.
mod replay_audit;

// Trust (T3 L4, C07): the consumed path's solver rows, each carried with its id in the
// body's VC context (see the module).
mod body_rows;
use body_rows::BodyRows;

// Trust (T3 L4, C07r): `VerificationArtifacts::results`, each row carried with its id in the
// body's VC context (see the module).
mod row_results;
use row_results::RowResults;

// Trust (T3 L4, C09): the exact key of a row at every exact-identity site, its canonical
// string, which decides, and its identity, which the identity oracle compares beside it (see
// the module).
mod row_key;
use row_key::RowKey;

/// Record `table`'s `source` and `state` for `body` in the elision audit.
fn audit_overflow_check_origins(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    source: &str,
    state: &str,
    table: &OverflowCheckOrigins,
) {
    if !elide_audit::enabled() {
        return;
    }
    let [unique, ambiguous] = table.audit_counts();
    elide_audit::record(
        tcx,
        body.source.def_id(),
        "ORIGINS",
        &[
            source.to_string(),
            state.to_string(),
            format!("unique={unique}"),
            format!("ambiguous={ambiguous}"),
        ],
    );
}

/// Exact public/native identity retained from the verifier-api obligation that
/// produced one legacy result row. Keeping this beside the row prevents later
/// consumers from reconstructing authority from a source span or display key.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ResultObligationBinding {
    /// Exact result-carrier row this public/native obligation was mapped onto.
    /// Public obligation IDs and native proof IDs identify verifier objects,
    /// not their position in the compiler's current result carrier; without
    /// this seal, swapping two otherwise-valid bindings could donate B's
    /// evidence to A's row.
    row: ExactResultRowIdentity,
    public_obligation_id: String,
    native_identity: NativeTransportIdentity,
    /// Exact compiler-held public obligation from which this row was mapped.
    /// Verifier-returned rows are untrusted transport data: matching an ID and
    /// native proof triple is insufficient if their kind, context, formula
    /// carrier, summary inputs, or other semantic metadata changed after
    /// dispatch.
    canonical_obligation: trust_verifier_api::TrustObligation,
    /// Private classification minted by the exact compiler-reference marker
    /// seal, never from either this public copy or the verifier-returned copy.
    /// A controlled semantic replacement revokes it so the modular
    /// entry-assumption exemption cannot follow a new row.
    definition_entry_assumption: bool,
    /// Compiler-stamped caller-side `#[trust::assume_total]` bookkeeping row.
    /// This is a recorded assumption classification, never proof authority.
    assumed_total_callee_assumption: bool,
    /// Runtime-monitor evidence parsed only from the original compiler-stamped
    /// verifier bundle and sealed to this exact row. Verifier-returned
    /// obligation metadata is never an authority for this field.
    monitor: Option<BoundTransportMonitorEvidence>,
}

/// Exact identity of one row in the current result carrier. The canonical VC
/// payload prevents two different obligations at the same index from sharing
/// authority after filtering/reordering; the index separates duplicate,
/// structurally-identical VCs in the same carrier. This is deliberately not a
/// fixed-width digest: a hash collision must never donate proof authority.
///
/// Trust (T3 L4, C09): `canonical_vc` is the row's [`RowKey`]: the canonical VC
/// payload, which decides, and the row's identity beside it, which the derived
/// equality compares through `RowKey::same` and the identity oracle counts
/// (L4-ORACLE-1). Every binding, authority, receipt and record that seals a row
/// holds this, so each of their comparisons is the oracle's; the canonical half
/// stays until C11.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ExactResultRowIdentity {
    index: usize,
    canonical_vc: RowKey,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct BoundTransportMonitorEvidence {
    row: ExactResultRowIdentity,
    evidence: TransportMonitorEvidence,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ExactSourceClauseBodyProofBinding {
    public_obligation_id: String,
    row: ExactResultRowIdentity,
}

fn exact_result_row_identity(
    index: usize,
    vc: &VerificationCondition,
) -> Option<ExactResultRowIdentity> {
    Some(ExactResultRowIdentity { index, canonical_vc: RowKey::of(vc)? })
}

impl ResultObligationBinding {
    fn matches_row(&self, index: usize, vc: &VerificationCondition) -> bool {
        exact_result_row_identity(index, vc).as_ref() == Some(&self.row)
    }

    /// Did the compiler itself attest this postcondition row's typed-CHC encoding EXACT
    /// (`annotate_trust_mc_typed_chc_encoding_fidelity`)? Read from the compiler-held
    /// canonical obligation, never from a verifier-returned copy, and only as a unique
    /// value: a duplicated key is ambiguous and answers no.
    fn postcondition_refutation_is_attested_exact(&self) -> bool {
        matches!(self.canonical_obligation.kind, trust_verifier_api::ObligationKind::Postcondition)
            && unique_api_obligation_metadata_value(
                &self.canonical_obligation,
                TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_METADATA_KEY,
            ) == Some(TRUST_MC_TYPED_CHC_ENCODING_FIDELITY_EXACT)
    }

    fn matches_public_obligation(&self, obligation: &trust_verifier_api::TrustObligation) -> bool {
        obligation.obligation_id == self.public_obligation_id
            && native_transport_identity(obligation) == self.native_identity
            && obligation == &self.canonical_obligation
    }

    fn monitor_evidence_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
    ) -> Option<&TransportMonitorEvidence> {
        if !self.matches_row(index, vc) {
            return None;
        }
        let current = exact_result_row_identity(index, vc)?;
        let bound = self.monitor.as_ref()?;
        (bound.row == current).then_some(&bound.evidence)
    }

    /// Move this capability only across the bridge's already-validated exact
    /// semantic replacement. The old seal must match the current carrier row;
    /// a swapped/stale binding cannot use re-keying to repair itself. Any
    /// source-clause authority is separately row-sealed and is rebuilt only
    /// after all body authorities have been minted.
    fn reseal_for_semantic_replacement(
        &mut self,
        index: usize,
        current: &VerificationCondition,
        replacement: &VerificationCondition,
    ) -> bool {
        if !self.matches_row(index, current) {
            return false;
        }
        let Some(replacement_row) = exact_result_row_identity(index, replacement) else {
            return false;
        };
        if self.row != replacement_row {
            self.row = replacement_row.clone();
            self.definition_entry_assumption = false;
            self.assumed_total_callee_assumption = false;
            if let Some(monitor) = self.monitor.as_mut() {
                monitor.row = replacement_row;
            }
        }
        true
    }
}

fn result_obligation_binding_with_compiler_assumptions(
    index: usize,
    vc: &VerificationCondition,
    obligation: &trust_verifier_api::TrustObligation,
    definition_entry_assumption: bool,
    assumed_total_callee_assumption: bool,
) -> Option<ResultObligationBinding> {
    let Some(row) = exact_result_row_identity(index, vc) else {
        if env_flag_enabled("TRUST_ASSERT_DEBUG")
            && obligation.obligation_id.contains("panic-freedom")
        {
            eprintln!(
                "[PF_BIND] mint FAILED for {} at row {index}: exact_result_row_identity None (vc kind={:?}, canonical payload fails)",
                obligation.obligation_id, &vc.kind
            );
        }
        return None;
    };
    let monitor = transport_monitor_evidence_from_metadata(&obligation.metadata)
        .map(|evidence| BoundTransportMonitorEvidence { row: row.clone(), evidence });
    Some(ResultObligationBinding {
        row,
        public_obligation_id: obligation.obligation_id.clone(),
        native_identity: native_transport_identity(obligation),
        canonical_obligation: obligation.clone(),
        definition_entry_assumption,
        assumed_total_callee_assumption,
        monitor,
    })
}

/// Test helper with no compiler-authenticated assumed-total capability. Public
/// obligation shape alone must never mint that private classification.
#[cfg(test)]
fn result_obligation_binding(
    index: usize,
    vc: &VerificationCondition,
    obligation: &trust_verifier_api::TrustObligation,
) -> Option<ResultObligationBinding> {
    result_obligation_binding_with_compiler_assumptions(index, vc, obligation, false, false)
}

/// Linear index of exact compiler row bindings by public obligation identity.
/// Duplicate identities are retained as an explicit ambiguous set rather than
/// selecting a first row. This replaces receipt/public-evidence nested scans
/// while preserving fail-closed behavior for moved or duplicated bindings.
struct ExactResultBindingRowIndex<'a> {
    unique_rows: FxHashMap<&'a str, usize>,
    ambiguous_ids: FxHashSet<&'a str>,
}

fn build_exact_result_binding_row_index<'a>(
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &'a [Option<ResultObligationBinding>],
) -> ExactResultBindingRowIndex<'a> {
    let mut unique_rows = FxHashMap::default();
    let mut ambiguous_ids = FxHashSet::default();
    for (row, binding) in result_bindings.iter().enumerate() {
        let Some(binding) = binding.as_ref() else { continue };
        let Some((vc, _)) = results.get(row) else { continue };
        if !binding.matches_row(row, vc) {
            continue;
        }
        let id = binding.public_obligation_id.as_str();
        if ambiguous_ids.contains(id) {
            continue;
        }
        if unique_rows.insert(id, row).is_some() {
            unique_rows.remove(id);
            ambiguous_ids.insert(id);
        }
    }
    ExactResultBindingRowIndex { unique_rows, ambiguous_ids }
}

/// Replace one compiler-private VC formula without carrying public/native
/// evidence across the semantic rewrite. An aligned binding is revoked before
/// the replacement; a stale or missing binding slot makes the rewrite fail
/// closed. The rewritten row may still receive a fresh `KernelCertified`
/// authority because that capability is derived from the exact replacement VC
/// and does not depend on a public verifier binding.
fn rewrite_result_formula_revoking_binding(
    index: usize,
    results: &mut [(VerificationCondition, VerificationResult)],
    result_bindings: Option<&mut [Option<ResultObligationBinding>]>,
    replacement: trust_types::Formula,
) -> bool {
    let Some((current_vc, _)) = results.get(index) else {
        return false;
    };
    if let Some(result_bindings) = result_bindings {
        let Some(binding_slot) = result_bindings.get_mut(index) else {
            return false;
        };
        if binding_slot.as_ref().is_some_and(|binding| !binding.matches_row(index, current_vc)) {
            // Never let a stale/swapped binding repair itself by following a
            // controlled formula rewrite. Revoke it and retain the old row.
            *binding_slot = None;
            return false;
        }
        if current_vc.formula == replacement {
            return true;
        }
        // The public obligation/evidence described the old formula. Even when
        // it was aligned, it has no authority over the replacement semantics.
        *binding_slot = None;
    } else if current_vc.formula == replacement {
        return true;
    }
    results[index].0.formula = replacement;
    true
}

/// Private authority minted only by an exact kernel certificate, an affine
/// live DirectTrustVc or fresh exact-direct CHC/PDR receipt, fresh strict solver
/// revalidation, a validated exact source-clause derivation, or the compiler's
/// origin-checked definition-site entry-assumption rule. Public verifier
/// evidence is attribution-only and does not enter this enum in production.
#[derive(Debug, Clone)]
enum ResultProofAuthority {
    /// A violation refutation the Clean kernel re-checked, and (the KR0 switch,
    /// proven-core plan increment 2) re-checked again through Clean's fenced
    /// reference entry: `reference` is the certificate that entry's
    /// `ReferenceAccepted` token yielded for exactly `evidence`'s bytes
    /// (`trust_certify::reference_certificate_for`). It is constructible only
    /// inside trust-certify from such a token, and `matches_row` re-checks that
    /// it is the certificate issued for exactly `evidence`'s bytes
    /// (`bound_reference`), so this variant authorizes no row for a payload
    /// the entry did not accept, nor with another payload's certificate.
    KernelCertified {
        row: ExactResultRowIdentity,
        evidence: trust_ir::ProofEvidence,
        reference: trust_certify::ReferenceCertificate,
        replay_audit: Option<trust_certify::proof_artifacts::ReplayAudit>,
    },
    /// One exact compiler-authenticated Ownership row proved by the dedicated
    /// release-admitted direct TrustVC MIR-memory lane. This is minted only by
    /// consuming the router's non-cloneable live receipt after final composite
    /// publication. It is `Trusted`/`Ownership`, never `Certified`: the Alethe
    /// checker remains trusted code and no Clean-kernel reconstruction is
    /// carried here. Unlike the CHC/PDR capability below, this authority may
    /// never seed E4/E5 feedback or an exact source-clause derivation.
    DirectTrustVcLive {
        authority: DirectTrustVcLiveAuthority,
    },
    /// Trust: sealed-authority S3. This token can be minted only by consuming
    /// the non-cloneable `FreshExactDirectChcPdrReceipt` returned alongside the
    /// genuine in-process native dispatch. The receipt is rechecked against the
    /// exact post-publication evidence row before this compiler-private,
    /// cloneable snapshot is created. It is deliberately `Trusted`/`Inductive`,
    /// never `Certified`: CHC/PDR's strict SMT replay remains in the trusted
    /// solver/checker TCB and is not a Clean kernel reconstruction.
    FreshExactDirectChcPdr {
        authority: ExactLiveChcPdrAuthority,
    },
    /// A source-authorized native whole-function safety proof, consumed from
    /// its own affine receipt family. This is not an isolated formula proof
    /// and cannot seed exact-direct E4/E5 or source-clause derivations.
    /// Strict CHC/PDR replay remains Trusted/Inductive, never Certified.
    FreshWholeFunctionChcPdr {
        authority: FreshWholeFunctionChcPdrAuthority,
    },
    /// A source marker is a catalog row, not an independently solved formula.
    /// This authority is derived from its exact, complete fresh body-VC group
    /// only after every body row carries a matching sealed private authority.
    ExactSourceClauseDischarge {
        row: ExactResultRowIdentity,
        binding: ResultObligationBinding,
        body_proofs: Vec<ExactSourceClauseBodyProofBinding>,
        certificate: Option<source_clause_certificate::Publication>,
    },
    /// Exact raw source postcondition checked against its typed native body.
    /// This is Trusted/Deductive, not a Clean-kernel certificate or a license
    /// to elide runtime checks.
    NativeWpSource {
        authority: native_wp_source::Authority,
    },
    DefinitionEntryAssumption {
        row: ExactResultRowIdentity,
        binding: ResultObligationBinding,
    },
    /// Caller-side bookkeeping for a callee explicitly marked
    /// `#[trust::assume_total]`. This is a recorded assumption, not a static
    /// proof, and is transported in the skipped/assumption partition.
    AssumedTotalCalleeAssumption {
        row: ExactResultRowIdentity,
        binding: ResultObligationBinding,
    },
    //
    // REMOVED (2026-08-14, FALSE PROOF): `WholeFunctionPanicFreedomSubsumption`
    // — the "every OTHER row is a static proof ⟹ the synthesized
    // `assertion:panic-freedom:0` aggregate holds" derivation. Its premise (1),
    // "the row set enumerates every panic source", is FALSE BY CONSTRUCTION.
    // `lower_function` (trust-ir-bridge) emits that aggregate ONLY when the body
    // has a diverging panic `Terminator::Call` (`panic!`/`assert!`/
    // `unreachable!`) or an absent-callee / drop-glue / coroutine-resume
    // assumption marker — i.e. EXACTLY the panic classes that never become a
    // counted per-site obligation. A `Terminator::Assert` (overflow / bounds /
    // div) body, whose sites DO all get per-site rows, gets no aggregate at all.
    // So whenever the aggregate exists, at least one panic source is carried by
    // it ALONE and no conjunction over the sibling rows can entail it.
    //
    // The sound lane for the same aggregate already exists and is strictly
    // stronger: `refute_full_assert_obligations` requires EVERY assert/panic
    // block to be individually refuted-unreachable (`refuted == 0 &&
    // left_unknown == 0 && !proved_vcs.is_empty()`) AND every other obligation
    // Proved, then discharges the aggregate in place against the GROUNDED
    // residual disjunction so the clean CIC kernel re-checks it. The subsumption
    // fired precisely in that lane's complement — when a panic site was left
    // Unknown — which is why it false-proved:
    //   `while i < 4 { assert!(n != i); t ^= i; i += 1; }` verified rc=0
    //   ("2 proved") off the UNRELATED `i += 1` overflow proof, and panics for
    //   every `n` in 0..4.
    // Do not reintroduce this without publishing a real per-site row for each
    // diverging-panic site first; see tests/trust-falsification/mutant/
    // pf_subsume_*.rs.
    /// Trust: E9 ensures-citation discharge (design note
    /// 2026-07-15-e9-discharge-criterion §5d). The cited island theorem was
    /// kernel-graded `Certified` against the postcondition goal
    /// `∀ params, Q(params, self_def(params))` — the clause with `result`
    /// bound to THIS function's E6-imported defining equation — via
    /// `cert_meter::grade` (proof term re-typechecked against that exact goal;
    /// full transitive closure sorry/axiom-free). Minted ONLY by
    /// `discharge_ensures_citations_in_walk` for a solver-UNKNOWN
    /// postcondition (a solver REFUTATION is never overridden), and sealed to
    /// the exact result row like every other authority.
    ///
    /// The SAME variant is minted for the uncited island-defeq route and for a
    /// mixed surface (see the lanes below and `docs/TCB.md`'s row).
    /// Trust: TG9 — both grade routes now require the full certification
    /// audit, including raw trustc's `kernel_prove_ensures_by_defeq` entry.
    /// Evidence production independently audits the complete surface again.
    EnsuresCitationDischarge {
        row: ExactResultRowIdentity,
        theorem: String,
        /// Trust: the kernel-audited `CleanCic` payload for this row — the
        /// closed proof term for the function's COMPLETE `ensures` surface, the
        /// exact elaborated goal with its referent / island-definition /
        /// function / kernel-environment bindings, and a lineage over this row's
        /// canonical identity
        /// (`trust_certify::clean_island::certify_ensures_discharge`). It is
        /// what `kernel_evidence_for` hands to the transport so the
        /// authenticated publication boundary can publish the row.
        ///
        /// The producer re-judges the whole surface under the FULL
        /// `Environment::audit_certification`, which is at least as strict as
        /// either grade route, so a payload can be ABSENT for a row this
        /// authority discharged but is never PRESENT for a judgment the audit
        /// refuses. `None` also covers every other production miss (a term over
        /// the size bound, a row past the identity depth gate). In every case
        /// the authority and its verdict are unaffected and the wire row ships
        /// evidence-free, which publication withholds (fail closed).
        evidence: Option<trust_ir::ProofEvidence>,
        /// KR0 switch: the Clean reference entry's certificate for the
        /// surface's closed judgment (`EnsuresDischargeCertificate::reference`),
        /// read off `evidence`'s exact bytes. This `Certified` variant is minted
        /// only with it (`trust_ensures_discharge_authority`); a discharge the
        /// entry did not accept mints no authority at all.
        reference: trust_certify::ReferenceCertificate,
    },
    /// Trust (ref-self I1): the SAME E9 discharge lane as
    /// `EnsuresCitationDischarge`, for a goal built over a borrow-erased E6
    /// PARAMETER VIEW — a binder naming a frozen shared pointee's scalar field
    /// VALUE at entry (`trust_types::e6_param_view::VIEW_MARKER`).
    ///
    /// **This is a SEPARATE VARIANT because it is a separate verdict class,
    /// and `docs/TCB.md` models one class per variant.** Owner ruling R1
    /// (2026-09-17) accepted the underlying aliasing assumption as a named TCB
    /// row and, in the same ruling, forbade calling any row that rests on it
    /// `Certified`. A field on the ordinary variant would have made one variant
    /// carry two grades, which `tcb_document_exhaustiveness` refuses by
    /// construction (its `disposition_arms` parser accepts a bare or `{..}`
    /// pattern only) — and which would have left every other
    /// `EnsuresCitationDischarge { .. }` match site silently covering the view
    /// form. As a variant, each of those sites is a compile error until it is
    /// revisited deliberately.
    ///
    /// The kernel really did check a closed proof term, so the STRENGTH stays
    /// `Constructive`; what it proved is a proposition about the pointee's
    /// field values at entry, and that those values are what the Rust function
    /// reads is the ASSUMPTION — so the STATUS is `Trusted`.
    ///
    /// It carries NO `evidence` payload, deliberately and by the guard's own
    /// invariant: `kernel_evidence_for` hands out a proof term for exactly the
    /// `Certified` variants, because handing one out is itself the claim that
    /// the kernel checked THIS row's obligation. The wire therefore ships this
    /// row with its own distinct solver label (`clean-kernel-view-*`) and NO
    /// kernel proof evidence, which the authenticated publication boundary
    /// withholds (`authenticated_proved_row_has_publication_evidence` is false
    /// with no envelope) — fail closed, on every path, with no dependence on
    /// whether a certificate happened to be produced.
    ///
    /// It is decided from the SIGNATURE (`trust_e6_view_marker`), not from
    /// whether the import minted: every clause binder a frozen shared
    /// parameter contributes names a pointee value, so an uncited
    /// `ensures self.x <= 5` rests on R1 exactly as a `result`-bearing clause
    /// does.
    EnsuresCitationViewDischarge {
        row: ExactResultRowIdentity,
        theorem: String,
        /// The view marker, carried so every reporting site names the SAME
        /// string rather than re-deriving it.
        view: &'static str,
    },
    /// Trust (OR-A1, owner ruling 2026-09-27 — Inc 1a): the SAME E9 discharge
    /// lane as `EnsuresCitationDischarge`, for a function whose cited theorem
    /// proves the postcondition only UNDER the function's own `requires` — the
    /// conditional goal `∀ params, P_0 → … → P_{n-1} → Q(params, f_def params)`
    /// (`trust_certify::clean_island::kernel_discharge_ensures_citation_under_in`).
    ///
    /// **A SEPARATE VARIANT because it is a separate verdict class**, exactly as
    /// `EnsuresCitationViewDischarge` is: `docs/TCB.md` models one class per
    /// variant and `tcb_document_exhaustiveness` parses one literal disposition
    /// per arm, so a field on the ordinary variant would have made one variant
    /// carry two grades and left every `EnsuresCitationDischarge { .. }` match
    /// site silently covering the conditional form.
    ///
    /// The kernel really did check a closed proof term against the conditional
    /// goal (so the STRENGTH stays `Constructive`). What it did NOT check is the
    /// requires→hypothesis LINK — that what callers are charged implies what the
    /// theorem consumes (`F_R ⇒ P_R`). `link` records which reading carried it:
    /// `KernelCanonical` (the theorem proved `G1★`, whose hypotheses are the
    /// lifted mathematical reading `T_j` of the charged canonical text, built
    /// through the nat-lift table) or `AllowListed` (the theorem proved `G1`,
    /// whose hypotheses are the Clean reading `H_j`, linked by the `E-allow`
    /// argument — code, not a kernel check). The ruling reserves `Certified`
    /// for a link that is itself kernel-checked as the IDENTICAL canonical term;
    /// whether a definitional-equality judgment against the compiler-built
    /// `T_j` is that check is the Inc 1b decision (`docs/DECISION_QUEUE.md`),
    /// so in Inc 1a BOTH links report `Trusted`. The link is DATA on the row —
    /// the marker the ruling requires — never a grade.
    ///
    /// Like the view variant it carries NO `evidence`: `kernel_evidence_for`
    /// hands a proof term out only for the `Certified` variants, so the wire row
    /// ships its own solver label (`clean-kernel-requires-canonical-citation` /
    /// `clean-kernel-requires-allowlist-citation`) and no proof-evidence
    /// envelope, and the authenticated publication boundary withholds it on
    /// every path.
    ///
    /// Minted ONLY where every safety condition of the lane holds (see
    /// `trust_grade_conditional_citation`): the ladder certified a conditional
    /// goal, the carried preconditions have a ground witness (`Found` — H3), the
    /// function has no borrow-erased parameter view, and the row carries NO
    /// existing static proof (H2 — a `KernelCertified` row is never demoted).
    EnsuresCitationUnderRequiresDischarge {
        row: ExactResultRowIdentity,
        theorem: String,
        /// Which reading of the function's `requires` the cited theorem's
        /// hypotheses took — the disclosed marker (`requires-link: …`).
        link: trust_certify::clean_island::RequiresLink,
    },
    /// Trust: sealed-authority S1 (SolverReplayAuthority, SMT lane — design note
    /// 2026-07-17-sealed-authority-blueprint). A solver-`Proved` row whose
    /// violation formula the gate INDEPENDENTLY re-solved to strict-UNSAT with
    /// its OWN fresh in-process ay run (`trust_router::in_process_ay_backend::
    /// revalidate_vc_unsat_strict` = the exact bar `verify` applies). Authority
    /// flows from THAT re-solve's verdict, never the producer's label
    /// (constitution U1/U6); a SATISFIABLE violation re-solves to `Failed` and
    /// mints nothing (refutation immunity). Minted ONLY by the deadline-capped
    /// `revalidate_all_solver_proofs` pass and sealed to the exact result row
    /// (the `ExactResultRowIdentity` carries the canonical VC payload, so it
    /// cannot transplant to another row). Reports `Trusted`/`SmtUnsat` — strictly
    /// above the label-only status quo, deliberately NOT `Certified` (ay's
    /// checker is trusted code; a kernel reconstruction is required for that).
    SolverRevalidated {
        row: ExactResultRowIdentity,
        receipt: SolverRevalidationReceipt,
    },
    /// Trust #540 (R1): sealed whole-program caller-propagation discharge.
    /// Minted ONLY by `install_r1_flip_authorities`, which requires the actual
    /// `SealedCallerPropagationCertificate` by reference — the row's `Proved`
    /// verdict was itself written from that token (`attributed_verdict` in
    /// `apply_r1_flips`), so this authority exists only for a row a sealed,
    /// kernel-replayed certificate flipped. The token binds the discharge VC
    /// identity, the strengthened (`V ∧ P`) proof, and every enumerated
    /// caller's discharge proof, all re-checked through the clean CIC kernel
    /// (docs/design-notes/2026-07-14-r1-authority-restoration.md). The row's
    /// OWN violation formula is the ISOLATED obligation — genuinely satisfiable
    /// — so no per-row re-solve/kernel-recheck of it can ever succeed; the
    /// proof semantics live entirely in the sealed token, exactly like an
    /// `EnsuresCitationDischarge`'s live in its graded theorem.
    CallerPropagation {
        row: ExactResultRowIdentity,
        /// The actual unforgeable token, retained so every later result check
        /// can require its complete attributed verdict instead of trusting a
        /// digest or public label. Operation identity was checked at the sole
        /// private apply seam; the exact frozen row prevents later movement.
        sealed: trust_router::strengthen_whole_program::SealedCallerPropagationCertificate,
    },
    /// Trust: whole-function panic-freedom closure from the interprocedural
    /// seam in refute_full_assert_obligations. The recorded gate is
    /// others_all_proved && all_calls_discharge_panic_free, for the unconditional
    /// tag only. It examines Call and TailCall sites through extracted_call_sites.
    /// Callees may pass registry, bridge, authenticated per-caller or per-site
    /// admissions, or have their instantiated preconditions kernel-certified.
    /// docs/TCB.md enumerates those premises. This is broader than the separate
    /// zero-obligation gate all_calls_target_proven_panic_free.
    ///
    /// The composition remains Trusted: the opaque panic_reachable atom is not
    /// kernel-rechecked. Only install_interprocedural_callee_closure_authorities
    /// mints this exact-row-bound authority after the recorded gate, expected
    /// verdict shape, still-None slot and sibling-unconditionality checks.
    InterproceduralCalleeClosure {
        row: ExactResultRowIdentity,
    },
    /// Trust (grounded catch-all premise floor, 2026-09-24): a whole-function
    /// panic-freedom catch-all that a grounding rewrite
    /// (`refute_full_assert_obligations`' intraprocedural discharge or
    /// `ground_panic_freedom_catchall`) re-pointed at a residual disjunction the
    /// Clean kernel then certified, LOWERED to `Trusted` because the weakest
    /// premise that disjunction rests on is itself only `Trusted`: a sibling
    /// row, or — on the refute lane — a call its call gate discharged from a
    /// registry or recognizer.
    ///
    /// Both rewrites gate on "every other row reads `Proved`" before any proof
    /// authority exists, so the kernel certificate of the grounded formula is the
    /// faithful residual of whole-function panic-freedom only while those
    /// premises really hold. `cap_grounded_panic_freedom_authorities` runs after
    /// every lane has claimed its rows and grades the grounded row by its
    /// weakest premise: all `Certified` (and no gate-discharged call) keeps
    /// `KernelCertified`; a `Trusted` premise mints THIS variant; a premise
    /// without authority — including a tail call or opaque terminator the
    /// refute lane's gate never examined — strips the row's authority entirely. A
    /// compiler-composed derivation like `InterproceduralCalleeClosure`:
    /// `Trusted`/`Deductive`, no kernel term handed out, and `unconditional` is
    /// `false` exactly when some premise was not itself an unconditional static
    /// proof (an R1 or `assume_total` premise). Sealed to the exact grounded row.
    GroundedPanicFreedomDerivation {
        row: ExactResultRowIdentity,
        unconditional: bool,
    },
    /// Trust (2026-10-08, D15 and the reference-argument `Box` root; owner
    /// ruling R1's rule): a row the Clean kernel re-checked, in a body whose VC
    /// generation rested on a LANGUAGE PREMISE about its reference arguments that
    /// nothing in this compiler proves: two `&mut` arguments never overlap
    /// (`noalias`), or a `Box` read out of a reference argument's pointee is valid.
    /// The kernel checked the VC, so the strength stays `Constructive`; that the VC
    /// is faithful to the program is the ASSUMPTION, so the status is `Trusted`.
    ///
    /// Minted ONLY by `demote_argument_premise_authorities`, which runs LAST in the
    /// authority phase of a body the compiler installed a premise for
    /// (`argument_premise::record`) and replaces with this variant, sealed to the
    /// same row, the `KernelCertified` token of every row whose certified VC the
    /// body's premise-free generation does not also produce (graded per row since
    /// 2026-10-17; `argument_premise` module doc, # Grading). Like
    /// `EnsuresCitationViewDischarge` (R1) it hands out NO kernel evidence, so the
    /// authenticated publication boundary withholds the row, and it licenses no
    /// check elision. It is not an unconditional static proof, so a caller never
    /// spends it as one.
    /// `evidence` is retained only for this body's own E4/E5 feedback.
    ArgumentPremiseKernelDischarge {
        row: ExactResultRowIdentity,
        evidence: trust_ir::ProofEvidence,
        /// The premise's name (`NOALIAS_MUT_ARGS` / `REFERENCE_ARG_BOX_VALID`),
        /// carried so every reporting site names the same string.
        premise: &'static str,
    },
    /// Trust (TINV step 10.4, decision TINV-23): a row whose violation formula carries
    /// type-invariant USE-SITE facts (`trust_vcgen::generate::type_invariant_facts`),
    /// each tagged `And([$tinv_assume_<digest>, I_k(σ)])`, proved by the S1 fresh strict
    /// re-solve of exactly that formula. The proof is CONDITIONAL on the TINV
    /// certificate (a Houdini induction over the crate's complete body inventory, its
    /// rows kernel-certified inside the pre-pass) and on the step-0(a) version oracle
    /// that keeps an entry fact off a written place; `assumes` names the `(type,
    /// conjunct)` premises, decoded from the row's tags through THIS session's use set.
    ///
    /// Minted ONLY by `mint_type_invariant_composed_authorities`, and only when the two
    /// disclosure channels agree: the formula's tag set equals the generation-scoped
    /// record of the row (`with_tinv_assumed_rows_scope`), every tag names a published conjunct, and the
    /// row's S1 receipt matches it. `Trusted`/`Deductive`, NEVER `Certified`: the kernel
    /// refuses every tagged VC (`kernel_authority_refusal`), there is no tag-accepting
    /// kernel entry in v1, and `kernel_evidence_for` hands out nothing. Conditional:
    /// excluded from `is_unconditional_static_proof_for`, from the source-clause body
    /// proofs and from E4/E5 feedback; the body is never check-elided and never
    /// registered panic-free (TINV-27). `cap_type_invariant_authorities` strips every
    /// other authority from a TINV-premised row (TINV-26).
    ///
    /// Step 10.7 (TINV-28 amended): `disclosure` is the rendered premise list, one line
    /// per `assumes` entry in the same order (`assumes type_invariant(S)#k`, the
    /// conjunct's text and the certificate's provenance), fixed at the mint from the
    /// session's published certificates. Every output surface renders exactly these
    /// lines, and the row reads proved (`is_static_proof_for`) only together with them.
    TypeInvariantComposed {
        row: ExactResultRowIdentity,
        receipt: SolverRevalidationReceipt,
        assumes: std::collections::BTreeSet<(String, u32)>,
        disclosure: Vec<String>,
    },
    /// Trust (VF5, proven-core plan; Clean `docs/DECISIONS.md` R169, R170): a
    /// "proved (calculus)" row. F1's VC calculus over SemR proved the
    /// function safe: the reference entry accepted `row_of … : VF5.RowProved
    /// bytes A fid sym` over the VF5 family base whose environment digest is
    /// pinned (`trust_certify::calculus_row`), where `bytes` is the compiler's
    /// trust-ir artifact and `sym` the function's own symbol in it. `RowProved`
    /// rests on `vc_sound_F1` (every obligation of `vc` refuted ⟹ `Valid_R`)
    /// and `compose_F1` (every function `Valid_R` ⟹ the closed module
    /// `ClosedSafe`), both admitted through the entry with closures ⊆ Ax0, and
    /// carries the entry premise `entriesOK` the kernel decides. So no run of
    /// the function is `Bad` (UB, a type error, an unsupported step or a
    /// panic), and each row whose violation would be such a run holds, for the
    /// reading the premises name: SemR's translation of the artifact, the
    /// target κ (64-bit), and the closed world (no caller outside the module
    /// enters an annotated function).
    ///
    /// Minted ONLY by `install_calculus_row_authorities`, from a certificate
    /// about the symbol this compile's published trust-ir module gives the
    /// function AND about that module's own bytes, on a row of an L0 kind
    /// `ClosedSafe` excludes (`calculus_row_covers`) that no other lane claimed
    /// and no solver refuted; the row's result is rewritten
    /// to the calculus' own `Proved` label. `Trusted`/`Constructive` while the
    /// owner's E4.7 ruling is not taken
    /// (`trust_types::authority_grade::E4_7_CALCULUS_ROWS_CERTIFIED`): the row
    /// counts as proved and as calculus credit, never toward `Certified`
    /// totals, licenses no check elision, and hands out no kernel evidence.
    /// Conditional (the closed-world entry): excluded from
    /// `is_unconditional_static_proof_for`, the panic-free registry, the
    /// source-clause body proofs and E4/E5 feedback.
    CalculusRowProved {
        row: ExactResultRowIdentity,
        /// The function's symbol, as the compiler names it.
        symbol: Vec<u8>,
        certificate: trust_certify::calculus_row::CalculusRowCertificate,
    },
}

/// Cloneable compiler-private projection of one consumed affine direct
/// TrustVC receipt. The complete compiler/public carriers are retained so the
/// authority cannot be reconstructed from a public run or transplanted after
/// a row, result, evidence, request, context, or deadline mutation.
#[derive(Debug, Clone)]
struct DirectTrustVcLiveAuthority {
    row: ExactResultRowIdentity,
    binding: ResultObligationBinding,
    obligation: trust_verifier_api::TrustObligation,
    compiler_result: ExactLiveCompilerProvedResult,
    accepted_evidence: trust_verifier_api::ObligationEvidence,
    dispatch_deadline: Option<std::time::Instant>,
    run_seal: Arc<DirectTrustVcLiveRunSeal>,
}

#[derive(Debug, Clone)]
struct DirectTrustVcLiveRunSeal {
    bundle: trust_verifier_api::TrustContractBundle,
    dispatched_obligations: Vec<trust_verifier_api::TrustObligation>,
    context: trust_verifier_api::VerifierExecutionSnapshot,
    dispatch_deadline: Option<std::time::Instant>,
    source_run: trust_verifier_api::VerificationRunResult,
    final_run: trust_verifier_api::VerificationRunResult,
    strict_accepted_evidence_positions: FxHashMap<String, usize>,
}

fn direct_trust_vc_strength_is_authoritative(strength: &trust_verifier_api::ProofStrength) -> bool {
    strength
        == &trust_verifier_api::ProofStrength::certified(
            trust_verifier_api::ReasoningKind::OwnershipAnalysis,
        )
}

impl DirectTrustVcLiveRunSeal {
    fn envelope_is_valid(&self) -> bool {
        self.bundle.validate().is_ok()
            && self.bundle.validate_requested_obligations(&self.dispatched_obligations).is_ok()
            && self.source_run.validate_derived_state().is_ok()
            && self.final_run.validate_derived_state().is_ok()
            && is_permitted_bridge_publication_transition(&self.source_run, &self.final_run)
            && self.source_run.bundle_id == self.bundle.bundle_id
            && self.source_run.subject == self.bundle.subject
            && self.source_run.context == self.context
            && self.source_run.run_id == self.context.run_id
            && self.source_run.requested_obligations == self.dispatched_obligations
            && self.final_run.bundle_id == self.bundle.bundle_id
            && self.final_run.subject == self.bundle.subject
            && self.final_run.context == self.context
            && self.final_run.run_id == self.context.run_id
            && self.final_run.requested_obligations == self.dispatched_obligations
            && !self.context.cancellation.requested
            && self.source_run.summary.publication_conflicts == 0
            && self.final_run.summary.publication_conflicts == 0
            && self.strict_accepted_evidence_positions
                == strict_accepted_evidence_positions(&self.final_run)
    }
}

impl DirectTrustVcLiveAuthority {
    fn authorizes_final_run(&self, run: &trust_verifier_api::VerificationRunResult) -> bool {
        run == &self.run_seal.final_run && self.run_seal.envelope_is_valid()
    }

    fn authorizes_row(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        exact_result_row_identity(index, vc).as_ref() == Some(&self.row)
            && binding == Some(&self.binding)
            && self.binding.matches_row(index, vc)
            && self.binding.matches_public_obligation(&self.obligation)
            && self.dispatch_deadline == self.run_seal.dispatch_deadline
            && self.obligation.kind == trust_verifier_api::ObligationKind::Ownership
            && has_exact_direct_trust_vc_deferred_marker(&self.obligation)
            && self.accepted_evidence.status == trust_verifier_api::EvidenceStatus::Proved
            && self
                .run_seal
                .strict_accepted_evidence_positions
                .get(self.obligation.obligation_id.as_str())
                .and_then(|position| self.run_seal.final_run.evidence.get(*position))
                == Some(&self.accepted_evidence)
            && self
                .accepted_evidence
                .proof_strength
                .as_ref()
                .is_some_and(direct_trust_vc_strength_is_authoritative)
    }

    fn authorizes_compiler_result(&self, result: &VerificationResult) -> bool {
        self.compiler_result.matches(result)
    }
}

/// Cloneable compiler-private projection of one consumed affine CHC/PDR
/// receipt. Every semantically relevant carrier is retained by value: the
/// complete public bundle/inventory, exact dispatched subset, execution
/// snapshot and absolute deadline, final derived run, public obligation,
/// result row/binding, and the complete accepted evidence row (including
/// engine, artifacts, diagnostics, publication metadata, and counterexample),
/// not merely its identity/strength. No public constructor exists; production
/// construction is confined to the two typed CHC/PDR installers below.
/// This common carrier is identity storage, not a receipt-family classifier;
/// the distinct ResultProofAuthority variants preserve each proof's scope.
#[derive(Debug, Clone)]
struct ExactLiveChcPdrAuthority {
    row: ExactResultRowIdentity,
    binding: ResultObligationBinding,
    obligation: trust_verifier_api::TrustObligation,
    compiler_result: ExactLiveCompilerProvedResult,
    accepted_evidence: trust_verifier_api::ObligationEvidence,
    evidence_id: String,
    proof_strength: trust_verifier_api::ProofStrength,
    dispatch_deadline: Option<std::time::Instant>,
    run_seal: Arc<ExactLiveChcPdrRunSeal>,
}

/// Exact private snapshot of the compiler's legacy `Proved` carrier at mint.
/// Every field is retained so a later strength/solver/certificate/warning/
/// envelope rewrite cannot borrow authority from the original result.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ExactLiveCompilerProvedResult {
    solver: trust_types::Symbol,
    time_ms: u64,
    strength: trust_types::ProofStrength,
    proof_certificate: Option<Vec<u8>>,
    solver_warnings: Option<Vec<String>>,
    native_proof_envelope: Option<trust_types::NativeProofEnvelope>,
}

impl ExactLiveCompilerProvedResult {
    fn from_result(result: &VerificationResult) -> Option<Self> {
        let VerificationResult::Proved {
            solver,
            time_ms,
            strength,
            proof_certificate,
            solver_warnings,
            native_proof_envelope,
        } = result
        else {
            return None;
        };
        Some(Self {
            solver: solver.clone(),
            time_ms: *time_ms,
            strength: strength.clone(),
            proof_certificate: proof_certificate.clone(),
            solver_warnings: solver_warnings.clone(),
            native_proof_envelope: native_proof_envelope.clone(),
        })
    }

    fn matches(&self, result: &VerificationResult) -> bool {
        let VerificationResult::Proved {
            solver,
            time_ms,
            strength,
            proof_certificate,
            solver_warnings,
            native_proof_envelope,
        } = result
        else {
            return false;
        };
        &self.solver == solver
            && self.time_ms == *time_ms
            && &self.strength == strength
            && &self.proof_certificate == proof_certificate
            && &self.solver_warnings == solver_warnings
            && &self.native_proof_envelope == native_proof_envelope
    }
}

#[derive(Debug, Clone)]
struct ExactLiveChcPdrRunSeal {
    bundle: trust_verifier_api::TrustContractBundle,
    dispatched_obligations: Vec<trust_verifier_api::TrustObligation>,
    context: trust_verifier_api::VerifierExecutionSnapshot,
    dispatch_deadline: Option<std::time::Instant>,
    source_run: trust_verifier_api::VerificationRunResult,
    final_run: trust_verifier_api::VerificationRunResult,
    strict_accepted_evidence_positions: FxHashMap<String, usize>,
}

fn exact_direct_chc_pdr_strength_is_authoritative(
    strength: &trust_verifier_api::ProofStrength,
) -> bool {
    strength.assurance == trust_verifier_api::AssuranceLevel::SmtBacked
        && matches!(
            &strength.reasoning,
            trust_verifier_api::ReasoningKind::Chc | trust_verifier_api::ReasoningKind::Pdr
        )
}

impl ExactLiveChcPdrRunSeal {
    fn envelope_is_valid(&self) -> bool {
        self.bundle.validate().is_ok()
            && self.bundle.validate_requested_obligations(&self.dispatched_obligations).is_ok()
            && self.source_run.validate_derived_state().is_ok()
            && self.final_run.validate_derived_state().is_ok()
            && is_permitted_bridge_publication_transition(&self.source_run, &self.final_run)
            && self.source_run.bundle_id == self.bundle.bundle_id
            && self.source_run.subject == self.bundle.subject
            && self.source_run.context == self.context
            && self.source_run.run_id == self.context.run_id
            && self.source_run.requested_obligations == self.dispatched_obligations
            && self.final_run.bundle_id == self.bundle.bundle_id
            && self.final_run.subject == self.bundle.subject
            && self.final_run.context == self.context
            && self.final_run.run_id == self.context.run_id
            && self.final_run.requested_obligations == self.dispatched_obligations
            && !self.context.cancellation.requested
            && self.source_run.summary.publication_conflicts == 0
            && self.final_run.summary.publication_conflicts == 0
            && self.strict_accepted_evidence_positions
                == strict_accepted_evidence_positions(&self.final_run)
    }
}

impl ExactLiveChcPdrAuthority {
    fn authorizes_final_run(&self, run: &trust_verifier_api::VerificationRunResult) -> bool {
        run == &self.run_seal.final_run && self.run_seal.envelope_is_valid()
    }

    fn authorizes_row(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        exact_result_row_identity(index, vc).as_ref() == Some(&self.row)
            && binding == Some(&self.binding)
            && self.binding.matches_row(index, vc)
            && self.binding.matches_public_obligation(&self.obligation)
            && self.dispatch_deadline == self.run_seal.dispatch_deadline
            && exact_direct_chc_pdr_strength_is_authoritative(&self.proof_strength)
            && !self.evidence_id.is_empty()
            && self.accepted_evidence.evidence_id == self.evidence_id
            && self.accepted_evidence.proof_strength.as_ref() == Some(&self.proof_strength)
            && self
                .run_seal
                .strict_accepted_evidence_positions
                .get(self.obligation.obligation_id.as_str())
                .and_then(|position| self.run_seal.final_run.evidence.get(*position))
                == Some(&self.accepted_evidence)
    }

    fn authorizes_compiler_result(&self, result: &VerificationResult) -> bool {
        self.compiler_result.matches(result)
    }
}

/// Identity of one shared immutable live-authority run seal. Every receipt in
/// a dispatch shares an `Arc`, so whole-run validation can be performed once
/// per seal and then reused without weakening the per-row exact-evidence gate.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum LiveAuthorityRunSealKey {
    DirectTrustVc(usize),
    FreshExactDirectChcPdr(usize),
    FreshWholeFunctionChcPdr(usize),
}

type LiveAuthorityRunValidationCache = FxHashMap<LiveAuthorityRunSealKey, bool>;

fn live_authority_run_seal_key(
    authority: &ResultProofAuthority,
) -> Option<LiveAuthorityRunSealKey> {
    match authority {
        ResultProofAuthority::DirectTrustVcLive { authority } => {
            Some(LiveAuthorityRunSealKey::DirectTrustVc(Arc::as_ptr(&authority.run_seal) as usize))
        }
        ResultProofAuthority::FreshExactDirectChcPdr { authority } => {
            Some(LiveAuthorityRunSealKey::FreshExactDirectChcPdr(
                Arc::as_ptr(&authority.run_seal) as usize
            ))
        }
        ResultProofAuthority::FreshWholeFunctionChcPdr { authority } => {
            Some(LiveAuthorityRunSealKey::FreshWholeFunctionChcPdr(Arc::as_ptr(
                &authority.exact.run_seal,
            ) as usize))
        }
        ResultProofAuthority::KernelCertified { .. }
        | ResultProofAuthority::ExactSourceClauseDischarge { .. }
        | ResultProofAuthority::NativeWpSource { .. }
        | ResultProofAuthority::DefinitionEntryAssumption { .. }
        | ResultProofAuthority::AssumedTotalCalleeAssumption { .. }
        | ResultProofAuthority::EnsuresCitationDischarge { .. }
        | ResultProofAuthority::EnsuresCitationViewDischarge { .. }
        | ResultProofAuthority::EnsuresCitationUnderRequiresDischarge { .. }
        | ResultProofAuthority::SolverRevalidated { .. }
        | ResultProofAuthority::CallerPropagation { .. }
        | ResultProofAuthority::InterproceduralCalleeClosure { .. }
        | ResultProofAuthority::GroundedPanicFreedomDerivation { .. }
        | ResultProofAuthority::ArgumentPremiseKernelDischarge { .. }
        // Trust (TINV step 10.4): a compiler-composed authority over an S1 receipt; no
        // live run seal.
        | ResultProofAuthority::TypeInvariantComposed { .. }
        // Trust (VF5): a reference-entry certificate; no live run seal.
        | ResultProofAuthority::CalculusRowProved { .. } => None,
    }
}

fn build_live_authority_run_validation_cache(
    authorities: &[Option<ResultProofAuthority>],
    run: &trust_verifier_api::VerificationRunResult,
) -> LiveAuthorityRunValidationCache {
    let mut cache = LiveAuthorityRunValidationCache::default();
    for authority in authorities.iter().flatten() {
        let Some(key) = live_authority_run_seal_key(authority) else { continue };
        cache.entry(key).or_insert_with(|| match authority {
            ResultProofAuthority::DirectTrustVcLive { authority } => {
                authority.authorizes_final_run(run)
            }
            ResultProofAuthority::FreshExactDirectChcPdr { authority } => {
                authority.authorizes_final_run(run)
            }
            ResultProofAuthority::FreshWholeFunctionChcPdr { authority } => {
                authority.authorizes_final_run(run)
            }
            _ => unreachable!("live run-seal key exists only for live authority variants"),
        });
    }
    cache
}

fn live_authority_run_is_valid(
    authority: &ResultProofAuthority,
    cache: Option<&LiveAuthorityRunValidationCache>,
) -> bool {
    let Some(key) = live_authority_run_seal_key(authority) else { return true };
    cache.and_then(|cache| cache.get(&key)).copied() == Some(true)
}

/// Private, exact eligibility for S1 revalidation. This capability is minted
/// only while the local v1 bridge is substituting a strict in-process AY proof
/// into its exact result row. Public solver names, evidence metadata, cached or
/// deserialized results, and other native/structural backends cannot construct
/// it. The complete row identity and producer problem bytes make a later
/// formula rewrite, row swap, or carrier permutation reject before a solve.
#[derive(Debug, Clone, PartialEq, Eq)]
struct SolverRevalidationEligibility {
    row: ExactResultRowIdentity,
    producer_canonical_problem: String,
}

/// Sealed result of one strict fresh revalidation. Keeping this compiler-local
/// adapter lets the core pass use an injected deterministic revalidator in unit
/// tests while production values still originate only in trust-router's sealed
/// `SmtRevalidationOutcome` constructor.
#[derive(Debug, Clone, PartialEq, Eq)]
struct StrictSmtRevalidation {
    canonical_problem: String,
    problem_sha256: String,
    time_ms: u64,
}

/// A strict re-solve's outcome: the sealed result, or the stop cause of a
/// re-solve that minted nothing (`wall-backstop` when its own clock ended it).
type StrictSmtRevalidationOutcome =
    Result<StrictSmtRevalidation, trust_types::determinism::StopCause>;

/// S1 strict revalidation's per-solve clock, unchanged by determinism P2.
///
/// The re-solve's search runs on its query's effort count
/// (`-Ztrust-verify-effort`), and since P4a.1 (ay ffaba97f6) so does ay's
/// strict-proof discharge inside it: its nested solves draw from that count
/// and install no clock. Since ay da447f9a6 (Trust's pin, P4a) the
/// eager-persistent split-loop arm and every BV/FP bit-blast solve run on
/// counts under `:rlimit` as well. The review rule of 2026-09-30 — no clock
/// becomes a backstop until a count stands in front of ALL the work it bounds
/// — therefore no longer keeps this clock for any of them; demoting it is
/// plan T2d, which still waits on ay-sat's wall-capped inprocessing and
/// lookahead in the other SAT solves. Until then it stays where it was: at
/// most four seconds per re-solve, never past the function deadline. A
/// re-solve it ends is recorded by the in-process lane (`wall-backstop`), and
/// one another non-reproducible stop ends is recorded as that stop
/// ([`StoppingClock::Backstop`]).
const SOLVER_REVALIDATION_BUDGET_MS: u64 = 4_000;

/// Reject-only shape check for the ordinary AY producer row. A public strength
/// can never create S1 eligibility, but a bounded-finite, structural, or other
/// non-SMT result must revoke an otherwise stale private capability rather than
/// inherit authority from a later strict solve.
fn is_strict_smt_proved_result(result: &VerificationResult) -> bool {
    matches!(
        result,
        VerificationResult::Proved { strength, .. }
            if strength == &trust_types::ProofStrength::smt_unsat_strict_checked()
    )
}

/// Trust: sealed-authority S1 receipt — the audit record a gate re-solve leaves
/// on the exact row it revalidated. It retains the full canonical VC payload,
/// row index, and canonical SMT problem bytes, not merely a digest. The builder
/// byte-compares all of them against the current carrier before minting; a
/// digest collision, stale row, or swapped receipt therefore cannot donate
/// authority. It is built only inside `revalidate_all_solver_proofs_with` from
/// an authenticated private eligibility plus a fresh strict revalidation.
#[derive(Debug, Clone, PartialEq, Eq)]
struct SolverRevalidationReceipt {
    row_index: usize,
    /// Trust (T3 L4, C09): the row's [`RowKey`], compared through `RowKey::same`.
    canonical_vc: RowKey,
    canonical_problem: String,
    problem_sha256: String,
    time_ms: u64,
}

impl ResultProofAuthority {
    /// Reject a legacy-result carrier rewrite after a private capability was
    /// minted. Most authority variants derive their own result and therefore
    /// do not need a second snapshot; the direct TrustVC and S3 affine receipts
    /// start from existing native `Proved` rows, so they seal every field.
    fn matches_compiler_result(&self, result: &VerificationResult) -> bool {
        match self {
            Self::NativeWpSource { authority } => authority.matches_result(result),
            Self::DirectTrustVcLive { authority } => authority.authorizes_compiler_result(result),
            Self::FreshExactDirectChcPdr { authority } => {
                authority.authorizes_compiler_result(result)
            }
            Self::FreshWholeFunctionChcPdr { authority } => {
                authority.exact.authorizes_compiler_result(result)
            }
            Self::CallerPropagation { sealed, .. } => r1_attributed_verdict_matches(result, sealed),
            Self::KernelCertified { .. }
            | Self::ExactSourceClauseDischarge { .. }
            | Self::DefinitionEntryAssumption { .. }
            | Self::AssumedTotalCalleeAssumption { .. }
            | Self::EnsuresCitationDischarge { .. }
            | Self::EnsuresCitationViewDischarge { .. }
            // Trust (OR-A1): the discharge lane wrote this row's `Proved`
            // result, exactly as for the two variants above.
            | Self::EnsuresCitationUnderRequiresDischarge { .. }
            | Self::SolverRevalidated { .. }
            // The seam wrote this row's `Proved` result; the frozen
            // `ExactResultRowIdentity` in `matches_row` binds the exact carrier,
            // so no separate compiler-result re-snapshot is required.
            | Self::InterproceduralCalleeClosure { .. }
            // Trust (grounded catch-all premise floor): minted only in place
            // of the grounded row's `KernelCertified` token, which bound no
            // result snapshot either; the frozen grounded-row identity is the
            // seal.
            | Self::GroundedPanicFreedomDerivation { .. }
            // Minted only in place of a `KernelCertified` token, which bound no
            // result snapshot either.
            | Self::ArgumentPremiseKernelDischarge { .. }
            // Trust (TINV step 10.4): minted from the row's own S1 receipt, like
            // `SolverRevalidated`; the receipt and frozen row are the seal.
            | Self::TypeInvariantComposed { .. } => true,
            // Trust (VF5): the mint wrote this row's result; only that label holds.
            Self::CalculusRowProved { .. } => is_calculus_row_result(result),
        }
    }

    fn matches_row(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        let Some(current_row) = exact_result_row_identity(index, vc) else {
            return false;
        };
        match self {
            Self::NativeWpSource { authority } => authority.matches_row(index, vc, binding),
            // KR0 switch: a `Certified` variant binds its row AND its reference
            // certificate to its payload: the certificate must be the one the
            // reference entry issued for exactly `evidence`'s bytes
            // (`reference_is_bound`). An authority holding some other payload's
            // certificate, or none for its payload, authorizes no row.
            Self::KernelCertified { row, .. } => {
                row == &current_row && self.reference_is_bound()
            }
            Self::EnsuresCitationDischarge { row, theorem, .. } => {
                row == &current_row && !theorem.is_empty() && self.reference_is_bound()
            }
            // Trust (ref-self I1): the view discharge binds its row exactly as
            // the ordinary one does — the DEMOTION is a grading decision, not a
            // weaker binding.
            Self::EnsuresCitationViewDischarge { row, theorem, .. }
            // Trust (OR-A1): so does the conditional discharge.
            | Self::EnsuresCitationUnderRequiresDischarge { row, theorem, .. } => {
                row == &current_row && !theorem.is_empty()
            }
            Self::SolverRevalidated { row, receipt } => {
                row == &current_row && solver_revalidation_receipt_matches_row(receipt, index, vc)
            }
            // Trust (TINV step 10.4): the S1 receipt's binding, and a premise list.
            // Step 10.7: and exactly one rendered disclosure line per premise.
            Self::TypeInvariantComposed { row, receipt, assumes, disclosure } => {
                row == &current_row
                    && !assumes.is_empty()
                    && type_invariant_disclosure_matches(assumes, disclosure)
                    && solver_revalidation_receipt_matches_row(receipt, index, vc)
            }
            Self::InterproceduralCalleeClosure { row, .. }
            | Self::GroundedPanicFreedomDerivation { row, .. }
            | Self::ArgumentPremiseKernelDischarge { row, .. } => row == &current_row,
            Self::FreshExactDirectChcPdr { authority } => {
                authority.authorizes_row(index, vc, binding)
            }
            Self::FreshWholeFunctionChcPdr { authority } => {
                authority.exact.authorizes_row(index, vc, binding)
            }
            Self::DirectTrustVcLive { authority } => authority.authorizes_row(index, vc, binding),
            Self::CallerPropagation { row, .. } => row == &current_row,
            Self::DefinitionEntryAssumption { row, binding: exact }
            | Self::AssumedTotalCalleeAssumption { row, binding: exact } => {
                row == &current_row && binding == Some(exact)
            }
            Self::ExactSourceClauseDischarge { row, binding: exact, body_proofs, .. } => {
                row == &current_row && binding == Some(exact) && !body_proofs.is_empty()
            }
            // Trust (VF5): the frozen row, a certificate about THIS symbol, and
            // still the one the process recorded for it (a withdrawn or replaced
            // certificate authorizes nothing).
            Self::CalculusRowProved { row, symbol, certificate } => {
                row == &current_row
                    && certificate.binds_symbol(symbol)
                    && trust_certify::calculus_row::calculus_row_certificate_for(symbol).as_ref()
                        == Some(certificate)
            }
        }
    }

    fn is_static_proof_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        result: &VerificationResult,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding)
            && self.matches_compiler_result(result)
            && matches!(
                self,
                Self::KernelCertified { .. }
                    | Self::DirectTrustVcLive { .. }
                    | Self::FreshExactDirectChcPdr { .. }
                    | Self::FreshWholeFunctionChcPdr { .. }
                    | Self::ExactSourceClauseDischarge { .. }
                    | Self::NativeWpSource { .. }
                    | Self::EnsuresCitationDischarge { .. }
                    // Trust (ref-self I1): admitted here exactly as the
                    // ordinary E9 discharge is, and DELIBERATELY. This
                    // predicate decides whether the row counts as PROVED on the
                    // human line and on the wire
                    // (`permits_static_proved_transport_for` is this predicate),
                    // so excluding it would not make the lane safer — it would
                    // delete the verdict the lane exists to produce. What the
                    // demotion changes is the STATUS the row reports
                    // (`Trusted`, never `Certified`) and what it licenses
                    // (nothing: `elide_kernel_certified_checks` gates on the
                    // `KernelCertified` variant). Recorded in `docs/TCB.md`'s
                    // `EnsuresCitationViewDischarge` row, `Independent static
                    // proof` column, so it is a documented decision rather than
                    // an inherited one.
                    | Self::EnsuresCitationViewDischarge { .. }
                    // Trust (OR-A1): admitted for the same reason — the
                    // postcondition row of a function with `requires` already
                    // MEANS "requires ⇒ ensures" for every authority that can
                    // prove it (the solver lane proves it under the entry
                    // assumption; `KernelCertified` rows on such a function rest
                    // on that same assumption). The lane mints this only when
                    // the carried preconditions AND the function's full
                    // `requires` set, searched jointly, each have a ground
                    // witness (`Found`) — the latter the same bar the solver
                    // lane applies before it assumes them (owner ruling S1).
                    // It IS excluded from `is_unconditional_static_proof_for`
                    // (owner ruling S3): the proof rests on the function's own
                    // preconditions, so a consumer that needs an all-input
                    // claim must not take it. `docs/TCB.md` records the column
                    // as "yes (conditional)".
                    | Self::EnsuresCitationUnderRequiresDischarge { .. }
                    | Self::SolverRevalidated { .. }
                    // The interprocedural callee-closure discharge is a real,
                    // UNCONDITIONAL all-input static proof (every sibling
                    // obligation unconditionally proved, every call to a
                    // registered panic-free callee), so it is deliberately NOT
                    // excluded from `is_unconditional_static_proof_for`.
                    | Self::InterproceduralCalleeClosure { .. }
                    // R1 is a real static proof for this closed-world carrier,
                    // but not an unconditional all-input proof. Consumers that
                    // need the latter use `is_unconditional_static_proof_for`.
                    | Self::CallerPropagation { .. }
                    // Trust (grounded catch-all premise floor): the kernel
                    // checked the grounded disjunction and every premise it
                    // rests on carries its own sealed authority, so the row
                    // counts as proved — at the weakest premise's grade, never
                    // the kernel's. A premise with NO sealed authority never
                    // yields this variant: the floor pass strips the row's
                    // authority instead. Conditional exactly when a premise was
                    // not an unconditional static proof (below).
                    | Self::GroundedPanicFreedomDerivation { .. }
                    // Trust (argument premise): PROVED on the human line and on
                    // the wire, as the R1 view discharge is; what the premise
                    // changes is the status (`Trusted`) and what the row
                    // licenses (no elision, no kernel evidence, no spending as
                    // an unconditional proof, below).
                    | Self::ArgumentPremiseKernelDischarge { .. }
                    // Trust (TINV step 10.7, TINV-28 amended): admitted now that every
                    // output surface renders the row's `assumes type_invariant(S)#k`
                    // lines (proof results `premises`, telemetry `assumes`, the transport
                    // row's `assumes`, the JSON report row and the terminal note), all
                    // read off this token's `disclosure`. It is `Trusted`, never
                    // `Certified`, and it is EXCLUDED from
                    // `is_unconditional_static_proof_for` (below), from the source-clause
                    // body proofs, from E4/E5 feedback and from the panic-free registry,
                    // so no other body's verdict can rest on it without the disclosure.
                    | Self::TypeInvariantComposed { .. }
                    // Trust (VF5): proved by the calculus, under its stated premises
                    // (every surface reads them off the row's grade). Conditional on
                    // the closed-world entry (below).
                    | Self::CalculusRowProved { .. }
            )
    }

    fn is_unconditional_static_proof_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        result: &VerificationResult,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.is_static_proof_for(index, vc, result, binding)
            && !matches!(
                self,
                Self::CallerPropagation { .. }
                    // Trust (OR-A1, owner ruling S3 2026-09-28): the cited
                    // theorem proved the postcondition only UNDER the function's
                    // own `requires`, so the row is a static proof of what the
                    // row means but not an all-input one. Excluded, fail
                    // closed; no consumer is known to be affected today
                    // (postcondition rows are exempt from the panic-free
                    // registry's sibling bar, and a `requires` function carries
                    // `DefinitionEntryAssumption` rows), which is exactly why
                    // it is decided here rather than left to inheritance.
                    | Self::EnsuresCitationUnderRequiresDischarge { .. }
                    // Trust (grounded catch-all premise floor): computed when
                    // the floor pass minted it, from each premise's OWN
                    // `is_unconditional_static_proof_for` — an R1 or
                    // `assume_total` premise makes the derivation conditional.
                    | Self::GroundedPanicFreedomDerivation { unconditional: false, .. }
                    // Rests on an unproved language premise about this body's
                    // reference arguments: never an all-input proof a caller,
                    // a registry or a grounded derivation may spend.
                    | Self::ArgumentPremiseKernelDischarge { .. }
                    // Trust (TINV step 10.7, TINV-27): conditional on the crate's
                    // type-invariant certificate — never an all-input proof.
                    | Self::TypeInvariantComposed { .. }
                    // Trust (VF5): conditional on the closed-world entry premise (no
                    // caller outside the module enters an annotated function).
                    | Self::CalculusRowProved { .. }
            )
    }

    /// Trust (TINV step 10.7): the rendered `assumes type_invariant(S)#k` lines of a
    /// `TypeInvariantComposed` token that reads proved on this row, or `None` for every
    /// other authority and for a token that does not. Every output surface reads its
    /// disclosure here, so a row reads proved exactly when its premises are rendered.
    fn type_invariant_disclosure_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        result: &VerificationResult,
        binding: Option<&ResultObligationBinding>,
    ) -> Option<&[String]> {
        match self {
            Self::TypeInvariantComposed { disclosure, .. }
                if self.permits_static_proved_transport_for(index, vc, result, binding) =>
            {
                Some(disclosure.as_slice())
            }
            _ => None,
        }
    }

    fn is_kernel_proof_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding) && matches!(self, Self::KernelCertified { .. })
    }

    fn is_solver_revalidated_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding) && matches!(self, Self::SolverRevalidated { .. })
    }

    fn permits_static_proved_transport_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        result: &VerificationResult,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        // Historically this admitted one extra REPORTABLE-but-not-premise
        // authority (the removed whole-function panic-freedom subsumption).
        // With that lane gone the transport bar is exactly the premise bar; a
        // new reportable-only authority must re-add its own arm here rather
        // than inherit one.
        self.is_static_proof_for(index, vc, result, binding)
    }

    fn is_definition_entry_assumption_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding)
            && matches!(self, Self::DefinitionEntryAssumption { .. })
    }

    fn is_assumed_total_callee_assumption_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding)
            && matches!(self, Self::AssumedTotalCalleeAssumption { .. })
    }

    fn is_exact_source_clause_discharge_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding)
            && matches!(self, Self::ExactSourceClauseDischarge { .. } | Self::NativeWpSource { .. })
    }

    /// Trust: E9 §5d — whether this authority is the sealed ensures-citation
    /// kernel discharge for exactly this row. Used by the vacuity gate: the
    /// discharge's semantics are carried by the authority itself (a
    /// kernel-certified proof of the ensures CLAUSE, row-bound by the
    /// conjunction pairing), not by this row's formula representation.
    fn is_ensures_citation_discharge_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding)
            && matches!(
                self,
                // Trust (ref-self I1): the vacuity gate asks WHICH LANE proved
                // the row, not how it is graded. A view discharge is the same
                // lane, so it takes the same exemption. Trust (OR-A1): so is a
                // conditional (requires-carrying) discharge.
                Self::EnsuresCitationDischarge { .. }
                    | Self::EnsuresCitationViewDischarge { .. }
                    | Self::EnsuresCitationUnderRequiresDischarge { .. }
            )
    }

    fn is_fresh_exact_direct_chc_pdr_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        result: &VerificationResult,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding)
            && self.matches_compiler_result(result)
            && matches!(self, Self::FreshExactDirectChcPdr { .. })
    }

    fn is_direct_trust_vc_live_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        result: &VerificationResult,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding)
            && self.matches_compiler_result(result)
            && matches!(self, Self::DirectTrustVcLive { .. })
    }

    /// Whether this is a non-recursive, sealed proof of a source-clause body
    /// row. Source-marker derivation deliberately names the accepted private
    /// authority variants instead of reusing `is_static_proof_for`: an earlier
    /// source-marker discharge must never prove another source marker, and
    /// neither a definition-entry assumption nor a solver revalidation is a
    /// body proof. The only non-kernel lane admitted here is S3's consumed
    /// affine exact-direct CHC/PDR receipt, which proves the exact
    /// compiler-authenticated E4/E5 violation formula and remains below
    /// `Certified`.
    fn is_exact_source_clause_body_proof_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        result: &VerificationResult,
        binding: Option<&ResultObligationBinding>,
    ) -> bool {
        self.matches_row(index, vc, binding)
            && self.matches_compiler_result(result)
            && matches!(self, Self::KernelCertified { .. } | Self::FreshExactDirectChcPdr { .. })
            // Trust (TINV step 10.4, TINV-26): never a row carrying a type-invariant tag.
            && matches!(vc.type_invariant_tags(), trust_types::TinvTagScan::None)
    }

    /// KR0 switch: the reference-entry certificate of a `Certified` variant
    /// bound to this row; `None` for every other variant (and for a row the
    /// authority is not sealed to). The transport stamps the row's evidence
    /// with it, so the theory id is visible on the emitted row.
    fn kernel_reference_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> Option<&trust_certify::ReferenceCertificate> {
        // Only beside the payload this authority hands out for the row (which
        // also binds the row and, through `matches_row`, the certificate).
        self.kernel_evidence_for(index, vc, binding)?;
        self.bound_reference()
    }

    /// KR0 switch: the reference certificate of a `Certified` variant, only
    /// when it is the one the reference entry issued for exactly the payload
    /// this authority carries (`trust_certify::reference_certificate_for`).
    /// `None` for every other variant, for a `Certified` variant with no
    /// payload, and for one holding a certificate of other bytes.
    fn bound_reference(&self) -> Option<&trust_certify::ReferenceCertificate> {
        let (evidence, reference) = match self {
            Self::KernelCertified { evidence, reference, .. } => (Some(evidence), reference),
            Self::EnsuresCitationDischarge { evidence, reference, .. } => {
                (evidence.as_ref(), reference)
            }
            Self::EnsuresCitationViewDischarge { .. }
            | Self::EnsuresCitationUnderRequiresDischarge { .. }
            | Self::DirectTrustVcLive { .. }
            | Self::FreshExactDirectChcPdr { .. }
            | Self::FreshWholeFunctionChcPdr { .. }
            | Self::ExactSourceClauseDischarge { .. }
            | Self::NativeWpSource { .. }
            | Self::DefinitionEntryAssumption { .. }
            | Self::AssumedTotalCalleeAssumption { .. }
            | Self::SolverRevalidated { .. }
            | Self::CallerPropagation { .. }
            | Self::InterproceduralCalleeClosure { .. }
            | Self::GroundedPanicFreedomDerivation { .. }
            | Self::ArgumentPremiseKernelDischarge { .. }
            | Self::TypeInvariantComposed { .. }
            // Trust (VF5): its reference certificate is the calculus row's, bound
            // in `matches_row`, and it is not a `Certified` variant.
            | Self::CalculusRowProved { .. } => return None,
        };
        let issued = trust_certify::reference_certificate_for(evidence?)?;
        (issued == *reference).then_some(reference)
    }

    /// Whether a `Certified` variant's certificate is bound to its payload
    /// (`bound_reference`); `true` for every other variant (not this check's).
    fn reference_is_bound(&self) -> bool {
        !matches!(self, Self::KernelCertified { .. } | Self::EnsuresCitationDischarge { .. })
            || self.bound_reference().is_some()
    }

    fn kernel_evidence_for(
        &self,
        index: usize,
        vc: &VerificationCondition,
        binding: Option<&ResultObligationBinding>,
    ) -> Option<&trust_ir::ProofEvidence> {
        if !self.matches_row(index, vc, binding) {
            return None;
        }
        match self {
            Self::KernelCertified { evidence, .. } => Some(evidence),
            // Trust: the E9 discharge retains the kernel-audited payload minted
            // with it (absent when it could not be produced — fail closed).
            Self::EnsuresCitationDischarge { evidence, .. } => evidence.as_ref(),
            // Trust (ref-self I1): NOTHING. Handing out a kernel proof term is
            // itself the claim that the kernel checked this row's own
            // obligation, and for a view row it did not — it checked a
            // proposition about the pointee's entry VALUES. The guard
            // `tcb_kernel_checked_column_is_exactly_the_certified_rows` enforces
            // exactly this correspondence in both directions, and the row is
            // therefore withheld at the authenticated publication boundary on
            // EVERY path, not only when a certificate happened to be produced.
            Self::EnsuresCitationViewDischarge { .. }
            // Trust (OR-A1): NOTHING, for the view row's reason. The kernel
            // checked a proof of the CONDITIONAL goal; the link from what callers
            // are charged to what the theorem consumed is not a kernel judgment
            // in Inc 1a, so no proof term may be handed out as if the row's own
            // obligation were kernel-checked. `Trusted`, withheld, on every path.
            | Self::EnsuresCitationUnderRequiresDischarge { .. }
            | Self::DirectTrustVcLive { .. }
            | Self::FreshExactDirectChcPdr { .. }
            | Self::FreshWholeFunctionChcPdr { .. }
            | Self::ExactSourceClauseDischarge { .. }
            | Self::NativeWpSource { .. }
            | Self::DefinitionEntryAssumption { .. }
            | Self::AssumedTotalCalleeAssumption { .. }
            | Self::SolverRevalidated { .. }
            | Self::CallerPropagation { .. }
            | Self::InterproceduralCalleeClosure { .. }
            // Trust (grounded catch-all premise floor): NOTHING, although the
            // grounded disjunction's CleanCic term exists. Handing it out would
            // claim the kernel checked THIS row's obligation — whole-function
            // panic-freedom — of which the disjunction is the residual only
            // under sibling premises the kernel never saw.
            | Self::GroundedPanicFreedomDerivation { .. }
            // Trust (argument premise): NOTHING, although the row's own CleanCic
            // term exists. Handing it out is the claim that the kernel checked
            // THIS row's obligation, and the VC is that obligation only under
            // the premise (R1's rule).
            | Self::ArgumentPremiseKernelDischarge { .. }
            // Trust (TINV step 10.4): NOTHING. The kernel refuses every tagged VC; the
            // row's proof is an S1 re-solve under a type-invariant premise.
            | Self::TypeInvariantComposed { .. }
            // Trust (VF5): NOTHING. The kernel checked `RowProved` of the artifact,
            // not this row's VC, and the row is not `Certified` before E4.7.
            | Self::CalculusRowProved { .. } => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct LoopInvariantProofPairKey {
    function: String,
    invariant: String,
    header_block: usize,
    location: SourceSpan,
    contract_metadata: Option<trust_types::ContractMetadata>,
}

#[derive(Debug, Clone)]
struct LoopInvariantProofPairRows {
    key: LoopInvariantProofPairKey,
    initiation: Vec<usize>,
    consecution: Vec<usize>,
}

#[derive(Debug, Clone)]
struct ProofGatedLoopE5Replacement {
    row_index: usize,
    replacement: VerificationCondition,
    changed: bool,
}

/// Compiler-private authority to consume one structurally validated E4
/// feedback candidate. The wrapped vcgen value carries no proof authority;
/// this type is constructed only after both exact result rows pass the private
/// `ResultProofAuthority` checks below and is never exported from this crate.
#[derive(Debug, Clone, PartialEq)]
struct ProofGatedLoopInvariant {
    candidate: trust_vcgen::LoopInvariantFeedbackCandidate,
}

fn loop_feedback_candidates(
    feedback: &[ProofGatedLoopInvariant],
) -> Vec<trust_vcgen::LoopInvariantFeedbackCandidate> {
    feedback.iter().map(|item| item.candidate.clone()).collect()
}

fn loop_invariant_proof_pair_key(
    vc: &VerificationCondition,
) -> Option<(bool, LoopInvariantProofPairKey)> {
    let (is_initiation, invariant, header_block) = match &vc.kind {
        VcKind::LoopInvariantInitiation { invariant, header_block } => {
            (true, invariant.clone(), *header_block)
        }
        VcKind::LoopInvariantConsecution { invariant, header_block } => {
            (false, invariant.clone(), *header_block)
        }
        _ => return None,
    };
    Some((
        is_initiation,
        LoopInvariantProofPairKey {
            function: vc.function.to_string(),
            invariant,
            header_block,
            location: vc.location.clone(),
            contract_metadata: vc.contract_metadata,
        },
    ))
}

fn result_row_has_e4_e5_proof_authority(
    index: usize,
    vc: &VerificationCondition,
    result: &VerificationResult,
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> bool {
    result.is_proved()
        // Trust (TINV step 10.4, TINV-26): a row carrying a type-invariant tag never
        // seeds E4/E5 feedback.
        && matches!(vc.type_invariant_tags(), trust_types::TinvTagScan::None)
        && proof_authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
            authority.is_kernel_proof_for(
                index,
                vc,
                result_bindings.get(index).and_then(Option::as_ref),
            )
                // Trust (argument premise): a demoted kernel re-check still feeds
                // its OWN body's E4/E5 loop-invariant pass. The strengthened rows
                // belong to the same premise-carrying body, and the second pass
                // demotes them again.
                || (matches!(authority, ResultProofAuthority::ArgumentPremiseKernelDischarge { .. })
                    && authority.matches_row(
                        index,
                        vc,
                        result_bindings.get(index).and_then(Option::as_ref),
                    ))
                || authority.is_fresh_exact_direct_chc_pdr_for(
                index,
                vc,
                result,
                result_bindings.get(index).and_then(Option::as_ref),
            )
        })
}

/// Mint ephemeral E4 feedback tokens only from exact row-aligned kernel proof
/// authority or S3's consumed fresh exact-direct CHC/PDR receipt. Other
/// Trusted native/S1/R1 evidence remains valid for its original result row,
/// but cannot strengthen a different E5 obligation. A public
/// `VerificationResult::Proved` is checked only to reject a stale authority
/// paired with a changed outcome; it is never sufficient to mint a token.
fn proof_gated_loop_invariant_feedback_tokens(
    func: &trust_types::VerifiableFunction,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> Result<Vec<ProofGatedLoopInvariant>, String> {
    const MAX_FEEDBACK_PAIRS: usize = 64;
    if results.len() != proof_authorities.len()
        || (!result_bindings.is_empty() && results.len() != result_bindings.len())
    {
        return Err("E4 feedback authority carriers are not row-aligned".to_string());
    }

    let mut pairs: Vec<LoopInvariantProofPairRows> = Vec::new();
    for (index, (vc, _)) in results.iter().enumerate() {
        let Some((is_initiation, key)) = loop_invariant_proof_pair_key(vc) else {
            continue;
        };
        let pair = if let Some(pair) = pairs.iter_mut().find(|pair| pair.key == key) {
            pair
        } else {
            if pairs.len() == MAX_FEEDBACK_PAIRS {
                return Err(format!(
                    "E4 feedback pair count exceeds the bounded reconstruction limit {MAX_FEEDBACK_PAIRS}",
                ));
            }
            pairs.push(LoopInvariantProofPairRows {
                key,
                initiation: Vec::new(),
                consecution: Vec::new(),
            });
            pairs.last_mut().expect("just inserted E4 pair")
        };
        if is_initiation {
            pair.initiation.push(index);
        } else {
            pair.consecution.push(index);
        }
    }

    let mut feedback = Vec::new();
    if pairs.is_empty() {
        return Ok(feedback);
    }
    let Some(reconstruction) = trust_vcgen::prepare_loop_invariant_feedback_validation(func) else {
        return Ok(feedback);
    };
    for pair in pairs {
        if pair.initiation.len() != 1 || pair.consecution.len() != 1 {
            return Err(format!(
                "ambiguous E4 rows for {} bb{} `{}` (initiation={}, consecution={})",
                pair.key.function,
                pair.key.header_block,
                pair.key.invariant,
                pair.initiation.len(),
                pair.consecution.len(),
            ));
        }
        let initiation_index = pair.initiation[0];
        let consecution_index = pair.consecution[0];
        let initiation = &results[initiation_index].0;
        let consecution = &results[consecution_index].0;
        let has_initiation_authority = result_row_has_e4_e5_proof_authority(
            initiation_index,
            initiation,
            &results[initiation_index].1,
            result_bindings,
            proof_authorities,
        );
        let has_consecution_authority = result_row_has_e4_e5_proof_authority(
            consecution_index,
            consecution,
            &results[consecution_index].1,
            result_bindings,
            proof_authorities,
        );
        if !has_initiation_authority || !has_consecution_authority {
            continue;
        }
        let candidate = trust_vcgen::loop_invariant_feedback_candidate_with_context(
            func,
            &reconstruction,
            initiation,
            consecution,
        );
        if let Some(candidate) = candidate {
            feedback.push(ProofGatedLoopInvariant { candidate });
        }
    }
    Ok(feedback)
}

/// The row's exact key, or why it has none. Trust (T3 L4, C09): a [`RowKey`], so the E5
/// plan's `!=` compares through `RowKey::same`.
fn exact_vc_payload(vc: &VerificationCondition) -> Result<RowKey, String> {
    RowKey::of(vc)
        .ok_or_else(|| "verification condition could not be canonically serialized".to_string())
}

/// Exact routing identity with only the formula erased. This is used solely to
/// pair first-pass and regenerated E5 rows; proof authority continues to use
/// the complete formula-bearing [`ExactResultRowIdentity`].
fn exact_vc_routing_payload(vc: &VerificationCondition) -> Result<String, String> {
    #[derive(serde::Serialize)]
    struct BorrowedRoutedVc<'a, M, O> {
        kind: &'a VcKind,
        function: &'a trust_types::Symbol,
        location: &'a trust_types::SourceSpan,
        formula: Formula,
        contract_metadata: &'a M,
        obligation: &'a O,
    }

    // Exhaustive destructure so adding a field to `VerificationCondition`
    // forces `BorrowedRoutedVc` to stay in lockstep with its serde shape
    // without cloning `vc.formula` on every routing lookup.
    let VerificationCondition {
        kind,
        function,
        location,
        formula: _,
        contract_metadata,
        obligation,
    } = vc;
    let routed = BorrowedRoutedVc {
        kind,
        function,
        location,
        formula: Formula::Bool(false),
        contract_metadata,
        obligation,
    };
    serde_json::to_string(&routed)
        .map_err(|error| format!("E5 routing identity could not be serialized: {error}"))
}

fn is_loop_local_e5_row(vc: &VerificationCondition) -> bool {
    matches!(
        &vc.kind,
        VcKind::NonTermination { context, .. } if context == "loop-decreases"
    ) || matches!(
        &vc.kind,
        VcKind::UnsupportedMir { kind, detail }
            if kind == "UserLoopContractUnsupported" && detail.contains("loop decreases")
    )
}

fn graft_proof_gated_e5_formula(
    current: &VerificationCondition,
    baseline: &VerificationCondition,
    augmented_baseline: &VerificationCondition,
    raw_replacement: &VerificationCondition,
    augmented_replacement: &VerificationCondition,
) -> Result<VerificationCondition, String> {
    if current.formula == baseline.formula || current.formula == raw_replacement.formula {
        return Ok(raw_replacement.clone());
    }
    if current.formula == augmented_baseline.formula
        || current.formula == augmented_replacement.formula
    {
        return Ok(augmented_replacement.clone());
    }
    Err("current E5 formula is neither an exact raw nor an exact production-augmented variant"
        .to_string())
}

fn proof_gated_loop_e5_replacement_plan(
    func: &trust_types::VerifiableFunction,
    current_vcs: &[VerificationCondition],
    feedback: &[ProofGatedLoopInvariant],
    // Trust (T3 L4, C07p): the body's VC context; both regenerations are interned into it
    // through the row oracle, so a regenerated row equal to a body row is its node.
    rows: &mut trust_types::vc_context::VcContext,
) -> Result<Vec<ProofGatedLoopE5Replacement>, String> {
    let feedback_candidates = loop_feedback_candidates(feedback);
    let (baseline, augmented_baseline) =
        trust_vcgen::regenerate_loop_decreases_with_invariant_feedback_production_variants_rows(
            func,
            &[],
            rows,
        )
        .ok_or_else(|| {
            "E5 baseline reconstruction exceeded the VC-generation work budget".to_string()
        })?;
    let (regenerated, augmented_regenerated) =
        trust_vcgen::regenerate_loop_decreases_with_invariant_feedback_production_variants_rows(
            func,
            &feedback_candidates,
            rows,
        )
        .ok_or_else(|| {
            "E5 feedback reconstruction exceeded the VC-generation work budget".to_string()
        })?;
    if baseline.len() != augmented_baseline.len()
        || baseline.len() != regenerated.len()
        || baseline.len() != augmented_regenerated.len()
    {
        return Err(format!(
            "E5 regeneration changed raw/augmented row cardinality (baseline raw {}, baseline augmented {}, replacement raw {}, replacement augmented {})",
            baseline.len(),
            augmented_baseline.len(),
            regenerated.len(),
            augmented_regenerated.len(),
        ));
    }
    if baseline.iter().any(|vc| !is_loop_local_e5_row(vc))
        || augmented_baseline.iter().any(|vc| !is_loop_local_e5_row(vc))
        || regenerated.iter().any(|vc| !is_loop_local_e5_row(vc))
        || augmented_regenerated.iter().any(|vc| !is_loop_local_e5_row(vc))
    {
        return Err("E5 regeneration returned a non-loop-local row".to_string());
    }
    let current_e5_rows = current_vcs
        .iter()
        .enumerate()
        .filter_map(|(index, vc)| is_loop_local_e5_row(vc).then_some(index))
        .collect::<FxHashSet<_>>();
    if current_e5_rows.len() != baseline.len() {
        return Err(format!(
            "current loop-local E5 row cardinality differs from regeneration ({} current, {} expected)",
            current_e5_rows.len(),
            baseline.len(),
        ));
    }

    let current_routes: FxHashMap<String, Vec<usize>> = if baseline.is_empty() {
        FxHashMap::default()
    } else {
        let mut map: FxHashMap<String, Vec<usize>> =
            FxHashMap::with_capacity_and_hasher(current_vcs.len(), Default::default());
        for (index, vc) in current_vcs.iter().enumerate() {
            if let Ok(candidate) = exact_vc_routing_payload(vc) {
                map.entry(candidate).or_default().push(index);
            }
        }
        map
    };

    let mut used_current = FxHashSet::default();
    let mut used_routes = FxHashSet::default();
    let mut plan = Vec::with_capacity(baseline.len());
    for row in 0..baseline.len() {
        let baseline = &baseline[row];
        let augmented_baseline = &augmented_baseline[row];
        let raw_replacement = &regenerated[row];
        let augmented_replacement = &augmented_regenerated[row];
        let route = exact_vc_routing_payload(baseline)?;
        if used_routes.contains(&route) {
            return Err("ambiguous duplicate E5 routing identity in regenerated rows".to_string());
        }
        if exact_vc_routing_payload(augmented_baseline)? != route
            || exact_vc_routing_payload(raw_replacement)? != route
            || exact_vc_routing_payload(augmented_replacement)? != route
        {
            return Err("E5 regeneration changed function/kind/source routing".to_string());
        }
        let matches = current_routes.get(&route).map_or(&[][..], Vec::as_slice);
        used_routes.insert(route);
        let [row_index] = matches else {
            return Err(format!(
                "E5 routing is not one-to-one for {} (matched {} current rows)",
                baseline.kind.description(),
                matches.len(),
            ));
        };
        if !used_current.insert(*row_index) {
            return Err("one current row was selected by multiple E5 replacements".to_string());
        }
        let replacement = graft_proof_gated_e5_formula(
            &current_vcs[*row_index],
            baseline,
            augmented_baseline,
            raw_replacement,
            augmented_replacement,
        )?;
        let changed =
            exact_vc_payload(&current_vcs[*row_index])? != exact_vc_payload(&replacement)?;
        plan.push(ProofGatedLoopE5Replacement { row_index: *row_index, replacement, changed });
    }
    if used_current != current_e5_rows {
        return Err("current loop-local E5 route set differs from regeneration".to_string());
    }
    Ok(plan)
}

/// Revalidate both sides of the feedback boundary after every changed E5 row
/// has been solved and the complete result carrier has been certified anew.
/// This prevents a stale first-pass E4 capability or a partially-applied E5
/// replacement from surviving into public proof/transport output.
fn validate_proof_gated_loop_feedback_candidate(
    func: &trust_types::VerifiableFunction,
    candidate: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
    expected_feedback: &[ProofGatedLoopInvariant],
    // Trust (T3 L4, C07p): the body's VC context, which the re-planned regeneration
    // writes into.
    rows: &mut trust_types::vc_context::VcContext,
) -> Result<(), String> {
    let final_feedback = proof_gated_loop_invariant_feedback_tokens(
        func,
        candidate,
        result_bindings,
        proof_authorities,
    )?;
    if final_feedback != expected_feedback {
        return Err("E4 proof authority changed while applying E5 feedback".to_string());
    }

    let final_vcs = candidate.iter().map(|(vc, _)| vc.clone()).collect::<Vec<_>>();
    let final_plan =
        proof_gated_loop_e5_replacement_plan(func, &final_vcs, expected_feedback, rows)?;
    if final_plan.iter().any(|replacement| replacement.changed) {
        return Err("final E5 carrier does not contain every regenerated formula".to_string());
    }
    Ok(())
}

/// Trust (ref-self I1): the E9 discharge authority for one row — the ordinary
/// variant, the VIEW one when the goal was built over the borrow-erased E6
/// parameter view, or (OR-A1) the CONDITIONAL one when the discharge rests on a
/// cited theorem proved only under the function's own `requires`.
///
/// ONE constructor, called from every seam that mints an E9 discharge, so the
/// grade a row reports cannot be decided from a different reading of the
/// signature — or of the rung — than the one the goal was built with.
///
/// `requires_link` is the RUNG carried as data from the grading lane (H1): the
/// weakest link over every cited clause of the discharged surface, or `None`
/// when every clause certified unconditionally. It is decided FIRST, so a
/// conditional credit can never come out as the `Certified` variant however the
/// view marker reads; the lanes additionally never mint a conditional credit on
/// a view function, so the two markers do not meet in practice.
///
/// The kernel-audited `evidence` payload is DROPPED for a view row and for a
/// conditional row, and that is the point rather than a loss: handing a proof
/// term to the transport is itself the claim that the kernel checked THIS
/// row's own obligation, which for those rows it did not
/// (`kernel_evidence_for`). The row therefore ships with no kernel evidence on
/// every path and the authenticated publication boundary withholds it
/// uniformly.
///
/// KR0 switch: the `Certified` arm requires the Clean reference entry's
/// certificate for `evidence` (`trust_certify::reference_certificate_for`).
/// Without it — no payload, or a payload the entry refused — the row gets NO
/// authority (`None`): it is neither Certified nor silently relabelled, and
/// the caller leaves its slot empty, so the row publishes as an unbacked
/// `Proved` label does (fail closed).
fn trust_ensures_discharge_authority(
    view: Option<&'static str>,
    requires_link: Option<trust_certify::clean_island::RequiresLink>,
    row: ExactResultRowIdentity,
    theorem: String,
    evidence: Option<trust_ir::ProofEvidence>,
) -> Option<ResultProofAuthority> {
    match (requires_link, view) {
        (Some(link), _) => {
            Some(ResultProofAuthority::EnsuresCitationUnderRequiresDischarge { row, theorem, link })
        }
        (None, Some(view)) => {
            Some(ResultProofAuthority::EnsuresCitationViewDischarge { row, theorem, view })
        }
        (None, None) => {
            let reference = evidence.as_ref().and_then(trust_certify::reference_certificate_for)?;
            Some(ResultProofAuthority::EnsuresCitationDischarge {
                row,
                theorem,
                evidence,
                reference,
            })
        }
    }
}

/// Trust (OR-A1 H1): the solver label and strength of an E9-discharged row,
/// decided from the SAME data the authority constructor above reads — the view
/// marker and the carried rung — so the wire label, the strength and the sealed
/// variant cannot disagree about which class a row is in. `defeq` selects the
/// uncited island-defeq family (an all-uncited surface); a mixed surface takes
/// the citation family, as it always has.
fn trust_ensures_discharge_label(
    view: Option<&'static str>,
    requires_link: Option<trust_certify::clean_island::RequiresLink>,
    defeq: bool,
) -> (&'static str, trust_types::ProofStrength) {
    use trust_certify::clean_island::RequiresLink;
    match (requires_link, view, defeq) {
        // A conditional credit only ever reaches the uncited lane through a
        // mixed surface's cited half, so `defeq` cannot be `true` here; the
        // arms are total so no combination falls into a `Certified` label.
        (Some(RequiresLink::KernelCanonical), _, _) => (
            "clean-kernel-requires-canonical-citation",
            trust_types::ProofStrength::requires_conditioned_constructive(),
        ),
        (Some(RequiresLink::AllowListed), _, _) => (
            "clean-kernel-requires-allowlist-citation",
            trust_types::ProofStrength::requires_conditioned_constructive(),
        ),
        (None, Some(_), false) => {
            ("clean-kernel-view-citation", trust_types::ProofStrength::view_erased_constructive())
        }
        (None, Some(_), true) => {
            ("clean-kernel-view-defeq", trust_types::ProofStrength::view_erased_constructive())
        }
        (None, None, false) => {
            ("clean-kernel-citation", trust_types::ProofStrength::smt_unsat_certified())
        }
        (None, None, true) => {
            ("clean-kernel-defeq", trust_types::ProofStrength::smt_unsat_certified())
        }
    }
}

fn trust_disposition_for_authority(
    authority: Option<&ResultProofAuthority>,
    index: usize,
    vc: &VerificationCondition,
    result: &VerificationResult,
    binding: Option<&ResultObligationBinding>,
) -> Option<(TrustStatus, TrustProofStrength)> {
    let authority = authority?;
    if !authority.matches_row(index, vc, binding) || !authority.matches_compiler_result(result) {
        return None;
    }
    match authority {
        ResultProofAuthority::KernelCertified { .. } => {
            Some((TrustStatus::Certified, TrustProofStrength::Constructive))
        }
        // An ensures-citation discharge is a kernel-certified proof of the
        // postcondition goal (Certified grade = re-typechecked proof term +
        // sorry/axiom-free transitive closure), so it reports the same
        // Certified/Constructive disposition as a canonical kernel re-check.
        //
        ResultProofAuthority::EnsuresCitationDischarge { .. } => {
            Some((TrustStatus::Certified, TrustProofStrength::Constructive))
        }
        // Trust (ref-self I1) — THE ONE EXCEPTION, and it is owner ruling R1's
        // (2026-09-17), not this function's to relax: when the goal was built
        // over the borrow-erased PARAMETER VIEW, the kernel really did check a
        // closed proof term (so the STRENGTH stays `Constructive`) but what it
        // proved is a proposition about the pointee's field VALUES at entry,
        // and that those values are what the Rust function reads is an
        // ASSUMPTION — `docs/TCB.md`'s `EnsuresCitationViewDischarge` row. "No
        // `Certified` row may rest on an unproved aliasing assumption", so the
        // STATUS is `Trusted`. Only `Certified` licenses codegen check elision,
        // and `elide_kernel_certified_checks` additionally requires
        // `KernelCertified`, so a view row licenses nothing twice over.
        ResultProofAuthority::EnsuresCitationViewDischarge { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Constructive))
        }
        // Trust (OR-A1, owner ruling 2026-09-27; Inc 1a): a discharge proved
        // UNDER the function's own `requires`. The kernel checked a closed proof
        // term against the conditional goal (so `Constructive`), but the
        // requires→hypothesis link it rests on is not a kernel judgment in this
        // increment — `KernelCanonical` (built through the lift table) and
        // `AllowListed` (the E-allow argument) alike. The ruling: "no `Certified`
        // row may rest on a step the kernel did not check", so the STATUS is
        // `Trusted` for BOTH links. `Certified` for `KernelCanonical` is Inc 1b,
        // gated on its own `docs/DECISION_QUEUE.md` entry.
        ResultProofAuthority::EnsuresCitationUnderRequiresDischarge { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Constructive))
        }
        ResultProofAuthority::DirectTrustVcLive { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Ownership))
        }
        ResultProofAuthority::FreshExactDirectChcPdr { .. }
        | ResultProofAuthority::FreshWholeFunctionChcPdr { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Inductive))
        }
        ResultProofAuthority::ExactSourceClauseDischarge { .. } => {
            // The compiler has derived the authored clause from its complete
            // exact body-proof group. Report the derivation honestly rather
            // than borrowing any one backend's proof-strength label.
            Some((TrustStatus::Trusted, TrustProofStrength::Deductive))
        }
        ResultProofAuthority::NativeWpSource { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Deductive))
        }
        // The gate independently re-solved the row's violation formula to
        // strict-UNSAT with its own fresh ay run. That is a real, replayable
        // (re-run the deterministic solve) SMT proof of THIS obligation —
        // `Trusted`/`SmtUnsat`, strictly above the label-only status quo, but
        // not `Certified` (no kernel reconstruction).
        ResultProofAuthority::SolverRevalidated { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::SmtUnsat))
        }
        ResultProofAuthority::DefinitionEntryAssumption { .. } => {
            // Conditional contract bookkeeping, not an independently
            // discharged proof.  `Trusted` is the compiler's existing
            // contract-assumed bucket; `None` prevents an invented deductive
            // strength from leaking into reports or downstream proof gates.
            Some((TrustStatus::Trusted, TrustProofStrength::None))
        }
        ResultProofAuthority::AssumedTotalCalleeAssumption { .. } => {
            // assume_total: user-audited assumption bookkeeping — same
            // `Trusted`/no-strength bucket as the entry assumption; never a
            // certified or static proof.
            Some((TrustStatus::Trusted, TrustProofStrength::None))
        }
        // R1 is a sealed, compiler-composed closed-world derivation. Its
        // component proofs were kernel-replayed, but the attributed end claim
        // is not an isolated-VC kernel theorem, so report Trusted/Deductive.
        ResultProofAuthority::CallerPropagation { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Deductive))
        }
        // The interprocedural callee-closure discharge is a compiler-composed,
        // UNCONDITIONAL whole-function panic-freedom derivation (every sibling
        // obligation unconditionally proved, every call to a registered
        // panic-free callee). It is a compiler-composed conjunction, not an
        // isolated-VC kernel theorem: Trusted/Deductive, exactly like the
        // source-clause and R1 derivations.
        //
        // MERGE (b62 <- origin/main; squash d24c671211): the whole-function panic-freedom
        // SUBSUMPTION used to share this arm. Upstream 983bc1a3b6 REMOVED that
        // lane as a live false proof, so it is gone from this arm too.
        ResultProofAuthority::InterproceduralCalleeClosure { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Deductive))
        }
        // Trust (grounded catch-all premise floor): the kernel re-checked the
        // grounded residual disjunction, but the row's claim is whole-function
        // panic-freedom, which that disjunction entails only together with the
        // sibling premises the grounding read as bare labels (and, on the
        // refute lane, the calls its gate discharged). Graded by the weakest of
        // them, and minted only when that is `Trusted`: a compiler composition,
        // Trusted/Deductive like the source-clause, R1 and callee-closure
        // derivations. `Certified` stays with the `KernelCertified` token, which
        // the floor pass leaves in place when every premise is itself
        // `Certified`.
        ResultProofAuthority::GroundedPanicFreedomDerivation { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Deductive))
        }
        // Trust (2026-10-08, argument premise; R1's rule): the kernel checked the
        // VC (`Constructive`), whose faithfulness rests on an unproved language
        // premise about the body's reference arguments (`Trusted`).
        ResultProofAuthority::ArgumentPremiseKernelDischarge { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Constructive))
        }
        // Trust (TINV step 10.4, TINV-23): an S1 re-solve of the row's formula
        // composed with the type-invariant certificate the formula's tagged facts
        // assume — a compiler composition, Trusted/Deductive, never Certified.
        ResultProofAuthority::TypeInvariantComposed { .. } => {
            Some((TrustStatus::Trusted, TrustProofStrength::Deductive))
        }
        // Trust (VF5): the kernel checked a closed proof term (`Constructive`); the
        // status is the owner's E4.7 ruling's, `Trusted` until it is taken, so a
        // calculus row never reaches a `Certified` total before then.
        ResultProofAuthority::CalculusRowProved { .. } => {
            // Keep the TCB guard's explicit block-arm grammar inspectable.
            Some(calculus_row_disposition(
                trust_types::authority_grade::E4_7_CALCULUS_ROWS_CERTIFIED,
            ))
        }
    }
}

/// Trust (VF5): a "proved (calculus)" row's disposition under the owner's E4.7
/// ruling. `e4_7` false (the ruling not taken, as shipped): `Trusted`, outside
/// every `Certified` total; true: `Certified`. The strength is `Constructive`
/// either way: the kernel checked a closed proof term of `RowProved`.
fn calculus_row_disposition(e4_7: bool) -> (TrustStatus, TrustProofStrength) {
    if e4_7 {
        (TrustStatus::Certified, TrustProofStrength::Constructive)
    } else {
        (TrustStatus::Trusted, TrustProofStrength::Constructive)
    }
}

/// Trust (VF1; soundness-by-construction R7, M0.3): the three-axis grade of each
/// proof-authority class, one literal triple per variant. `docs/TCB.md`'s
/// authority table carries the same triple, and `tcb_document_exhaustiveness`
/// parses this function as it parses `trust_disposition_for_authority` and holds
/// the two to each other, so every arm is a single literal `trust_grade(..)`.
///
/// What the axes say today: no row's encoding is a proven calculus, so no
/// `KernelCertified` row is calculus credit; it is a kernel-checked UNSAT of an
/// unvalidated encoding. The E9 rows (`EnsuresCitation*`) are graded by the E6
/// reflector's reading of the body, not by calculus credit. `DirectTrustVcLive`
/// and the two CHC/PDR lanes are solver-asserted.
///
/// The grade is disclosure. Nothing reads it to decide a status, a publication,
/// a cache hit or an elision.
fn trust_grade_for_authority(
    authority: &ResultProofAuthority,
) -> trust_types::authority_grade::ObligationGrade {
    use trust_types::authority_grade::{GradeDischarge, GradeEncoding, GradePremise};
    let trust_grade = trust_types::authority_grade::ObligationGrade::new;
    match authority {
        ResultProofAuthority::KernelCertified { .. } => trust_grade(
            GradeEncoding::UnvalidatedEncoder,
            GradeDischarge::KernelReferenceChecked,
            &[],
        ),
        ResultProofAuthority::DirectTrustVcLive { .. } => {
            trust_grade(GradeEncoding::UnvalidatedEncoder, GradeDischarge::SolverAsserted, &[])
        }
        ResultProofAuthority::FreshExactDirectChcPdr { .. }
        | ResultProofAuthority::FreshWholeFunctionChcPdr { .. } => {
            trust_grade(GradeEncoding::UnvalidatedEncoder, GradeDischarge::SolverAsserted, &[])
        }
        ResultProofAuthority::ExactSourceClauseDischarge { .. } => trust_grade(
            GradeEncoding::UnvalidatedEncoder,
            GradeDischarge::CompilerComposed,
            &[GradePremise::BodyProofGroup],
        ),
        ResultProofAuthority::NativeWpSource { .. } => {
            trust_grade(GradeEncoding::UnvalidatedEncoder, GradeDischarge::SolverSelfChecked, &[])
        }
        ResultProofAuthority::DefinitionEntryAssumption { .. } => trust_grade(
            GradeEncoding::NotEncoded,
            GradeDischarge::Assumed,
            &[GradePremise::RequiresAssumedAtEntry],
        ),
        ResultProofAuthority::AssumedTotalCalleeAssumption { .. } => trust_grade(
            GradeEncoding::NotEncoded,
            GradeDischarge::Assumed,
            &[GradePremise::UserAssumeTotal],
        ),
        // The E6 rows: the kernel checked a closed proof term, but the goal is
        // stated over the E6 reflector's reading of the body.
        ResultProofAuthority::EnsuresCitationDischarge { .. } => {
            trust_grade(GradeEncoding::E6Reflector, GradeDischarge::KernelReferenceChecked, &[])
        }
        ResultProofAuthority::EnsuresCitationViewDischarge { .. } => trust_grade(
            GradeEncoding::E6Reflector,
            GradeDischarge::KernelReconstructed,
            &[GradePremise::ParameterView],
        ),
        ResultProofAuthority::EnsuresCitationUnderRequiresDischarge { .. } => trust_grade(
            GradeEncoding::E6Reflector,
            GradeDischarge::KernelReconstructed,
            &[GradePremise::RequiresLink],
        ),
        ResultProofAuthority::SolverRevalidated { .. } => {
            trust_grade(GradeEncoding::UnvalidatedEncoder, GradeDischarge::SolverSelfChecked, &[])
        }
        ResultProofAuthority::CallerPropagation { .. } => trust_grade(
            GradeEncoding::UnvalidatedEncoder,
            GradeDischarge::CompilerComposed,
            &[GradePremise::ClosedWorldCallers],
        ),
        ResultProofAuthority::InterproceduralCalleeClosure { .. } => trust_grade(
            GradeEncoding::UnvalidatedEncoder,
            GradeDischarge::CompilerComposed,
            &[GradePremise::PanicFreeCalleeRegistry, GradePremise::SiblingRows],
        ),
        ResultProofAuthority::GroundedPanicFreedomDerivation { .. } => trust_grade(
            GradeEncoding::UnvalidatedEncoder,
            GradeDischarge::CompilerComposed,
            &[GradePremise::PanicFreeCalleeRegistry, GradePremise::SiblingRows],
        ),
        ResultProofAuthority::ArgumentPremiseKernelDischarge { .. } => trust_grade(
            GradeEncoding::UnvalidatedEncoder,
            GradeDischarge::KernelReconstructed,
            &[GradePremise::ArgumentPremise],
        ),
        ResultProofAuthority::TypeInvariantComposed { .. } => trust_grade(
            GradeEncoding::UnvalidatedEncoder,
            GradeDischarge::SolverSelfChecked,
            &[GradePremise::TypeInvariantCertificate],
        ),
        // Trust (VF5): the calculus proved sound in the kernel (`vc_sound_F1`,
        // `compose_F1` ⊆ Ax0, through the reference entry); the premises are
        // `trust_types::authority_grade::CALCULUS_ROW_PREMISES`.
        ResultProofAuthority::CalculusRowProved { .. } => trust_grade(
            GradeEncoding::ProvenCalculus,
            GradeDischarge::KernelReferenceChecked,
            &[
                GradePremise::SemrTranslation,
                GradePremise::TargetKappa,
                GradePremise::ClosedWorldEntry,
            ],
        ),
    }
}

/// Trust (VF1): one row's grade: its authority class's grade
/// (`trust_grade_for_authority`) plus the premises the class grade cannot see,
/// because they live in the row rather than in the variant's kind:
///
/// * a `KernelCertified` token on a whole-function panic-freedom catch-all
///   (`is_panic_freedom_assertion_vc`, the broad prefix) may be a GROUNDED
///   residual, faithful only under its sibling rows' verdicts
///   (`cap_grounded_panic_freedom_authorities` lets it keep the kernel token
///   when every sibling is `Certified`): `sibling-rows`;
/// * a `GroundedPanicFreedomDerivation { unconditional: false }` rests on a
///   sibling that is not an all-input proof: `sibling-premises`.
///
/// Each refinement only adds a premise, so it never raises the encoding or
/// the discharge.
fn trust_grade_for_row(
    authority: &ResultProofAuthority,
    vc: &VerificationCondition,
) -> trust_types::authority_grade::ObligationGrade {
    use trust_types::authority_grade::GradePremise;
    let grade = trust_grade_for_authority(authority);
    match authority {
        ResultProofAuthority::KernelCertified { .. } if is_panic_freedom_assertion_vc(vc) => {
            grade.with_premise(GradePremise::SiblingRows)
        }
        ResultProofAuthority::GroundedPanicFreedomDerivation { unconditional: false, .. } => {
            grade.with_premise(GradePremise::SiblingPremises)
        }
        _ => grade,
    }
}

/// Trust (VF1): the one place a row's grade is held to its outcome before the
/// rows leave the compiler. A grade is stated only on a `proved` or `skipped`
/// row; every later rewrite that turns a row into anything else (a fail-closed
/// demotion, the contract-panic aggregate's `failed`, a lane's `unknown`)
/// withdraws the grade here, whatever path it took.
fn withdraw_grades_outrunning_outcome(rows: &mut [TransportObligationResult]) {
    for row in rows {
        if !matches!(row.outcome, Outcome::Proved | Outcome::Skipped) {
            row.grade = None;
        }
    }
}

type ArtifactCacheKey = String;

/// One artifact-cache slot.
///
/// `Full` is the artifact the verify pass consumes: VC formulas, transport rows,
/// the full verifier run, bindings, authorities. `Compact` is what the slot
/// becomes once that pass returns: [`CompactArtifacts`], the fields the readers
/// that can still come AFTER the pass take, and nothing else. `Absent` is a
/// cached negative.
///
/// WHY. Every slot used to stay `Full` until the session ended. MEASURED
/// 2026-09-17 (ay 0.27.0 release gate, seal ac551a56, `ay-dpll` lib test, `-j 4`):
/// resident memory grew ~1.2 GB per minute while diagnostics streamed, which is
/// retained state and not one function's work, to 58 GB, and the kernel SIGKILLed
/// the compile at 0.1 GB free on a 128 GiB box with no swapfile. No verify bound
/// fired; from outside the kill read as `could not compile ay-dpll (lib test)`.
/// A body's retained bytes are this slot, so the slot is shrunk to what is still
/// read the moment its one heavy reader is done. (First shipped as seal-line
/// commit 321aaeda75 in atpkg pack 9192; re-ported onto main without that
/// commit's resident-memory ceiling, which main deleted as dead in 5aa81ac168.)
///
/// WHO READS A SLOT, and what each gets:
///   * the verify pass (`run_pass`): the FULL artifact, exactly once per key.
///     A pass that finds its own slot already `Compact` recomputes it and counts
///     that (`compacted_rehits`) — never a silent read of a projection.
///   * the query providers (`trust_proof_results` / `trust_proof_telemetry`):
///     `proof_results` and `telemetry` only.
///   * the panic-freedom premise (`trait_panic_free`, and through it the
///     writer-relative bar): the rows its conjuncts read, as [`PremiseArtifacts`].
///     This reader arrived on main after 321aaeda75 and is the reason this port
///     keeps more than that commit's two-field projection: a premise asked of an
///     already-verified callee must be answered from its compact slot, not by
///     re-running the callee's whole verification.
enum CachedArtifacts {
    Absent,
    Full(Arc<VerificationArtifacts>),
    Compact(Arc<CompactArtifacts>),
}

/// The part of a body's [`VerificationArtifacts`] kept after its verify pass
/// returns. See [`CachedArtifacts`] for who reads it.
///
/// DROPPED: every VC formula (`results` keeps only each row's `VcKind`), the full
/// verifier run (only the one bit the premise reads of it survives), the
/// row-aligned bindings and proof authorities, the overflow-check origin map, the
/// coroutine resume contract, the proof level and the body's VC context (T3 L4, C07),
/// and, of each transport row, the VC and proof payloads no reader takes: its VC
/// snapshot, its evidence artifacts' bytes and its evidence diagnostics
/// ([`premise_transport_row`]). None of them has a reader once the pass is done; a new
/// field of `VerificationArtifacts` or of a transport row must decide the same question
/// here (`CompactArtifacts::project` and `premise_transport_row` destructure exhaustively).
pub(crate) struct CompactArtifacts {
    proof_results: TrustProofResults,
    telemetry: TrustProofTelemetry,
    /// `results[i].0.kind`, in `results` order, so row-alignment with the
    /// published dispositions is decided exactly as it is on the full artifact.
    row_kinds: Vec<VcKind>,
    /// Trust (memory, 2026-11-01): `transport_results`, in order, each row as
    /// [`premise_transport_row`] keeps it: every field but its proof, IR and VC payload
    /// bytes. Never published (see there).
    transport_results: Vec<TransportObligationResult>,
    has_runtime_checked_std_member: bool,
    native_run_is_vacuously_clean: bool,
    results_discharge_by_assumed_total: bool,
}

impl CompactArtifacts {
    fn project(full: &VerificationArtifacts) -> Self {
        // Exhaustive on purpose: a field added to `VerificationArtifacts` stops
        // this compiling until someone says whether a post-pass reader needs it.
        let VerificationArtifacts {
            proof_results,
            telemetry,
            results,
            transport_results,
            full_verification,
            expanded_function_identity: _,
            result_bindings: _,
            proof_authorities: _,
            overflow_check_origins: _,
            coroutine_resume_contract: _,
            max_proof_level: _,
            runtime_checked_std_members,
            calculus_reporting: _,
            // Trust (T3 L4, C07): no post-pass reader reads a row of the body's context, so
            // a compacted slot releases it (`SessionArtifactCache::compacted_contexts`).
            ctx: _,
        } = full;
        Self {
            proof_results: proof_results.clone(),
            telemetry: telemetry.clone(),
            row_kinds: results.iter().map(|(vc, _)| vc.kind.clone()).collect(),
            // Trust (memory, 2026-11-01): row by row from a borrow, never a clone of the
            // full rows first — their payloads are what the slot sheds.
            transport_results: transport_results.iter().map(premise_transport_row).collect(),
            has_runtime_checked_std_member: !runtime_checked_std_members.is_empty(),
            native_run_is_vacuously_clean: full_verification
                .as_ref()
                .is_some_and(native_run_is_vacuously_clean),
            results_discharge_by_assumed_total: results_discharge_by_assumed_total(results),
        }
    }
}

/// Trust (memory, 2026-11-01): one transport row as a compacted slot keeps it. Every
/// field a post-pass reader reads is kept verbatim; every VC or proof payload no row
/// predicate reads is dropped. Built field by field from a borrow, never by cloning the full row (its
/// payloads are the thing being shed), and exhaustive in every struct it opens, so a
/// field added to any of them stops this compiling until someone decides whether a
/// compact-slot reader needs it.
///
/// WHY. `CompactArtifacts::project` used to clone the rows whole. A certified row's
/// `clean_cic` artifact carries the kernel payload as `metadata: serde_json::Value`
/// (`serde_json::to_value` of `ProofEvidence::CleanCic`, whose `term` and `context` are
/// byte vectors, so every byte becomes one 72-byte `Value`: an 86,702-byte term is a
/// ~6.9 MB array), and the clone kept that tree for the rest of the session for every
/// verified body. MEASURED 2026-11-01 (`malloc_history` of a stage 1 `targo trust check
/// -j 1` on a probe crate alternating certified-row and certified-row-free functions):
/// 19.8 MB of live slot and +25.3 MB of `Malloc Large` per function with certified rows,
/// +0 per function without; with this projection the slot is ~20 KB per function. The
/// same clone was ~2.3 MB per function, 83% of the growth, on ay-drat-check, and 55-64%
/// of the footprint growth on ay-sat (docs/DECISION_QUEUE.md, COMPACT-SLOT-PAYLOAD-1).
///
/// WHO READS THESE ROWS: the callers of [`PremiseArtifacts::transport_results`] (the
/// panic-freedom premise's conjunct 3 through each `RowExcuse`, the writer-relative
/// excuse `fmt_writer_relative::WriterEdgeExcuse` through
/// `fmt_writer_relative::writer_edge_rows_excused`,
/// `refusal_carries_no_violation_evidence`, and
/// `PremiseArtifacts::spends_a_user_assumed_total_axiom`), through
/// `assumption_panic_row_cause` and its four disjuncts, `transport_row_stands_for_fold`,
/// `transport_rows_with_fold_sites`, `absent_callee_path_of_row`,
/// `extern_call_row_callee`, `transport_row_is_assumed_total_assumption`,
/// `transport_row_is_unproved_assumed_total_callee` and
/// `fmt_writer_relative::row_names_writer_edge`. Between them they read `kind`,
/// `description`, `outcome`, `design_mandate`, and whether `native_trust_ir` and
/// `proof_evidence` are present (`is_none()`), plus the row count. All of these are kept
/// exactly; an evidence record stays `Some` with its header.
///
/// ALSO KEPT, though no compact-slot reader reads them today, because a compact row has
/// the full row's type, so a reader added later compiles against either and would answer
/// silently differently on the two arms:
///   * every field whose ABSENCE some row predicate in this crate reads as acceptance:
///     `typed_kind` (the exact-shape predicates
///     `instance_hypothesis::transport_row_is_instance_hypothesis_assumption` and
///     `termination_unmeasured::transport_row_is_termination_unmeasured_assumption` admit
///     a row only when it is `None`), `counterexample` and `counterexample_model` (the
///     authenticated-assumption shapes admit only `None`; a counterexample is the
///     violation evidence `refusal_carries_no_violation_evidence` is about). Dropping one
///     would turn a refused row into an admitted one on the compact arm, failing open.
///     Each is bounded by its obligation's kind or model, not by a proof (adversarial
///     review of COMPACT-SLOT-PAYLOAD-1, finding 1).
///   * every small header, so a compact row is the same row to a reader that reads one:
///     the obligation id and claim digest, location, solver, time, reason, gap class,
///     monitor, `assumes`, grade, each evidence record's header (suite, backend, ids,
///     status, strength, evidence model, `present`) and each artifact's header (kind,
///     format, id, digest, uri).
///
/// DROPPED, because no row predicate in this crate reads them and each is the size of
/// the VC or the proof: `original_vc_snapshot`, and in both evidence records every
/// artifact's `metadata` and `materialization` and the record's `diagnostics`. Their
/// absence can only make a row look LESS proved (no kernel payload, no certificate
/// bytes), never more admissible.
///
/// NEVER PUBLISHED. Publication (`publish_body_verification_outcome`) runs inside the
/// verify pass, before the pass's guard compacts the slot, and takes the full artifact;
/// a compact row is reachable only as a slice through
/// [`PremiseArtifacts::transport_results`], whose callers are predicates. If one were
/// published by mistake it would carry no proof: the publication gate refuses a
/// `clean_cic` artifact without its `metadata`, whose bytes its digest and proof id are
/// computed over (targo-trust `clean_cic_transport_proof_is_publishable`), and every
/// native proof route needs a materialized, digest-bound certificate or transcript
/// (`trust_types::transport_proof_artifact_topology_defect`).
fn premise_transport_row(row: &TransportObligationResult) -> TransportObligationResult {
    let TransportObligationResult {
        obligation_id,
        claim_digest_sha256,
        kind,
        original_vc_snapshot: _,
        typed_kind,
        description,
        location,
        outcome,
        solver,
        time_ms,
        counterexample,
        counterexample_model,
        reason,
        design_mandate,
        gap_class,
        native_trust_ir,
        proof_evidence,
        monitor,
        assumes,
        grade,
    } = row;
    TransportObligationResult {
        obligation_id: obligation_id.clone(),
        claim_digest_sha256: claim_digest_sha256.clone(),
        kind: kind.clone(),
        original_vc_snapshot: None,
        typed_kind: typed_kind.clone(),
        description: description.clone(),
        location: location.clone(),
        outcome: *outcome,
        solver: solver.clone(),
        time_ms: *time_ms,
        counterexample: counterexample.clone(),
        counterexample_model: counterexample_model.clone(),
        reason: reason.clone(),
        design_mandate: *design_mandate,
        gap_class: *gap_class,
        native_trust_ir: native_trust_ir.as_ref().map(premise_native_trust_ir),
        proof_evidence: proof_evidence.as_ref().map(premise_proof_evidence),
        monitor: monitor.clone(),
        assumes: assumes.clone(),
        grade: grade.clone(),
    }
}

/// [`premise_transport_row`]'s native-TrustIr record: its header, each artifact's header,
/// no diagnostics.
fn premise_native_trust_ir(
    native: &TransportNativeTrustIrEvidence,
) -> TransportNativeTrustIrEvidence {
    let TransportNativeTrustIrEvidence {
        suite,
        backend,
        request_id,
        native_id,
        present,
        artifacts,
        diagnostics: _,
    } = native;
    TransportNativeTrustIrEvidence {
        suite: suite.clone(),
        backend: backend.clone(),
        request_id: request_id.clone(),
        native_id: native_id.clone(),
        present: *present,
        artifacts: artifacts.iter().map(premise_evidence_artifact).collect(),
        diagnostics: Vec::new(),
    }
}

/// [`premise_transport_row`]'s proof-evidence record: its header, each artifact's header,
/// no diagnostics.
fn premise_proof_evidence(proof: &TransportProofEvidence) -> TransportProofEvidence {
    let TransportProofEvidence {
        suite,
        backend,
        request_id,
        proof_id,
        native_id,
        status,
        strength,
        evidence,
        artifacts,
        diagnostics: _,
    } = proof;
    TransportProofEvidence {
        suite: suite.clone(),
        backend: backend.clone(),
        request_id: request_id.clone(),
        proof_id: proof_id.clone(),
        native_id: native_id.clone(),
        status: *status,
        strength: strength.clone(),
        evidence: evidence.clone(),
        artifacts: artifacts.iter().map(premise_evidence_artifact).collect(),
        diagnostics: Vec::new(),
    }
}

/// [`premise_transport_row`]'s evidence artifact: its header, without the bytes
/// (`metadata`, `materialization`).
fn premise_evidence_artifact(artifact: &TransportEvidenceArtifact) -> TransportEvidenceArtifact {
    let TransportEvidenceArtifact {
        kind,
        format,
        artifact_id,
        digest,
        uri,
        materialization: _,
        metadata: _,
    } = artifact;
    TransportEvidenceArtifact {
        kind: kind.clone(),
        format: format.clone(),
        artifact_id: artifact_id.clone(),
        digest: digest.clone(),
        uri: uri.clone(),
        materialization: None,
        metadata: None,
    }
}

/// A body's artifact as the panic-freedom premise reads it
/// (`trait_panic_free::instance_discharges_panic_freedom_modulo`): the full
/// artifact when its slot is still `Full` (the pass has not run, or never runs,
/// as for a shim nobody optimized), else the compact projection. Every accessor
/// answers the same on both arms for the same body; the `Compact` arm's answers
/// were computed from the `Full` one by [`CompactArtifacts::project`].
pub(crate) enum PremiseArtifacts {
    Full(Arc<VerificationArtifacts>),
    Compact(Arc<CompactArtifacts>),
}

impl PremiseArtifacts {
    pub(crate) fn transport_results(&self) -> &[TransportObligationResult] {
        match self {
            Self::Full(full) => &full.transport_results,
            Self::Compact(compact) => &compact.transport_results,
        }
    }

    /// How many obligation rows the artifact has (`results.len()`).
    pub(crate) fn row_count(&self) -> usize {
        match self {
            Self::Full(full) => full.results.len(),
            Self::Compact(compact) => compact.row_kinds.len(),
        }
    }

    /// The `VcKind` of obligation row `index`.
    pub(crate) fn row_kind(&self, index: usize) -> Option<&VcKind> {
        match self {
            Self::Full(full) => full.results.get(index).map(|(vc, _)| &vc.kind),
            Self::Compact(compact) => compact.row_kinds.get(index),
        }
    }

    pub(crate) fn has_runtime_checked_std_member(&self) -> bool {
        match self {
            Self::Full(full) => !full.runtime_checked_std_members.is_empty(),
            Self::Compact(compact) => compact.has_runtime_checked_std_member,
        }
    }

    /// `native_run_is_vacuously_clean` of the full verifier run, `false` without one.
    pub(crate) fn native_run_is_vacuously_clean(&self) -> bool {
        match self {
            Self::Full(full) => {
                full.full_verification.as_ref().is_some_and(native_run_is_vacuously_clean)
            }
            Self::Compact(compact) => compact.native_run_is_vacuously_clean,
        }
    }

    /// Does this body's ledger record a `#[trust::assume_total]` axiom being spent?
    pub(crate) fn spends_a_user_assumed_total_axiom(&self) -> bool {
        let from_results = match self {
            Self::Full(full) => results_discharge_by_assumed_total(&full.results),
            Self::Compact(compact) => compact.results_discharge_by_assumed_total,
        };
        transport_rows_spend_a_user_assumed_total_axiom(self.transport_results()) || from_results
    }
}

// Trust #3: store artifacts behind Arc so pass/query consumers share owned
// vectors. This cache used to be process-global; Session ownership prevents a
// later rustc_driver compilation from replaying another crate's artifacts and
// releases the potentially large map at the end of the invocation.
#[derive(Default)]
struct SessionArtifactCache {
    entries: FxHashMap<ArtifactCacheKey, CachedArtifacts>,
    /// Cached `"{policy_key}|semantics={semantics_key}|"` prefixes keyed by
    /// `(policy.mode_cache_tag(), policy.include_dependencies)`.
    key_prefixes: Vec<(&'static str, bool, String)>,
    /// Slots compacted after their verify pass.
    compacted: u64,
    /// Of `compacted`, the slots whose compaction found the pass's own handle
    /// already dropped (the slot's `Arc` was its only owner). Expected 0: the
    /// guard is declared after the pass binds `artifacts`, so it drops first and
    /// compacts while the pass still holds its handle. A non-zero count means the
    /// guard moved above that binding; `-Ztrust-memory-notes` reports it, and
    /// `tests/ui/trust/memory_notes_census.rs` pins it at 0 beside a non-zero
    /// `compacted`.
    compacted_after_handle_dropped: u64,
    /// A verify pass that found its own slot already `Compact` and recomputed the
    /// full artifact. Expected 0; reported at crate end, so a non-zero count is
    /// visible instead of a silent doubling of work.
    compacted_rehits: u64,
    /// The highest resident size read at a body boundary (after a compaction).
    /// Observed, not the kernel's peak: a spike inside one body's verification
    /// that is gone by its end is not seen.
    highest_resident_bytes: u64,
    /// The resident size at which the next memory checkpoint note fires.
    next_memory_checkpoint_bytes: u64,
    /// Trust (T3 L4, C07): a `Weak` to the VC context of each compacted slot whose context
    /// may still be alive. The compaction drops the slot's own handle; the context is
    /// released once the pass that consumed the slot (and any other holder, such as a
    /// pending E9 citation) drops its artifacts too. Swept at each compaction, so only the
    /// contexts still alive are kept.
    compacted_contexts: Vec<std::sync::Weak<trust_types::vc_context::VcContext>>,
    /// Of the compacted slots' contexts, how many a sweep found released.
    contexts_released: u64,
}

impl SessionArtifactCache {
    /// Compact `key`'s slot, if it is still `Full`, once the verify pass that consumed it
    /// returns (`compact_cached_artifacts_after_pass`): the slot keeps only the
    /// [`CompactArtifacts`] projection. T3 L4 (C07): the projection holds no handle to the
    /// body's VC context, and a `Weak` to that context is kept, so its release is counted.
    fn compact_after_pass(&mut self, key: &ArtifactCacheKey) {
        if let Some(slot) = self.entries.get_mut(key)
            && let CachedArtifacts::Full(full) = slot
        {
            if Arc::strong_count(full) < 2 {
                self.compacted_after_handle_dropped += 1;
            }
            let compact = Arc::new(CompactArtifacts::project(full));
            let context = Arc::downgrade(&full.ctx);
            *slot = CachedArtifacts::Compact(compact);
            self.compacted += 1;
            // Trust (T3 L4, C07): the slot no longer holds the body's context; the pass
            // still does, until it returns. The sweep counts the ones released since.
            self.sweep_compacted_contexts();
            self.compacted_contexts.push(context);
        }
    }

    /// Count, and forget, every compacted slot's context that has been released.
    fn sweep_compacted_contexts(&mut self) {
        let before = self.compacted_contexts.len();
        self.compacted_contexts.retain(|context| context.strong_count() > 0);
        let released = before - self.compacted_contexts.len();
        self.contexts_released += u64::try_from(released).unwrap_or(u64::MAX);
    }

    /// Trust (T3 L4, C09w): the compacted slots' contexts still alive that no pending
    /// citation holds (`held`, by address), the summary's `context_alive_after_compaction`.
    /// A context a citation holds is the summary's `contexts_held_for_citation` instead.
    fn compacted_contexts_alive_unheld(&self, held: &FxHashSet<usize>) -> u64 {
        let alive = self
            .compacted_contexts
            .iter()
            .filter(|context| context.strong_count() > 0)
            .filter(|context| !held.contains(&context.as_ptr().addr()))
            .count();
        u64::try_from(alive).unwrap_or(u64::MAX)
    }
}

/// Memory checkpoint notes fire each time the resident size read at a body
/// boundary crosses another multiple of this. Only under `-Ztrust-memory-notes`:
/// the resident size is the host's, so a note keyed on it would make a compile's
/// diagnostics depend on the machine (main's 5aa81ac168 measured
/// tests/ui/borrowck/ever-init-many-locals.rs at 4858 MB max RSS).
const MEMORY_CHECKPOINT_STEP_BYTES: u64 = 4 << 30;

fn gib(bytes: u64) -> String {
    format!("{:.1}", bytes as f64 / f64::from(1u32 << 30))
}

/// The process's resident size now, 0 where the platform cannot say.
fn resident_bytes_now() -> u64 {
    rustc_data_structures::profiling::get_resident_set_size()
        .and_then(|bytes| u64::try_from(bytes).ok())
        .unwrap_or(0)
}

/// Compacts `key`'s slot when the verify pass that consumed it returns: on every
/// return path, which is why this is a guard and not a call at the end of
/// `run_pass` (that function returns from many places). Skipped while
/// panicking: an ICE must not re-enter the session state.
struct CompactArtifactsAfterPass<'tcx> {
    tcx: TyCtxt<'tcx>,
    key: ArtifactCacheKey,
}

impl Drop for CompactArtifactsAfterPass<'_> {
    fn drop(&mut self) {
        if std::thread::panicking() {
            return;
        }
        compact_cached_artifacts_after_pass(self.tcx, &self.key);
    }
}

fn compact_cached_artifacts_after_pass<'tcx>(tcx: TyCtxt<'tcx>, key: &ArtifactCacheKey) {
    let notes = tcx.sess.opts.unstable_opts.trust_memory_notes;
    // Read only when the notes were asked for: nothing else consumes it.
    let resident = if notes { resident_bytes_now() } else { 0 };
    let checkpoint = tcx.sess.with_trust_compiler_state::<SessionArtifactCache, _>(|cache| {
        cache.compact_after_pass(key);
        if !notes {
            return None;
        }
        cache.highest_resident_bytes = cache.highest_resident_bytes.max(resident);
        if cache.next_memory_checkpoint_bytes == 0 {
            cache.next_memory_checkpoint_bytes = MEMORY_CHECKPOINT_STEP_BYTES;
        }
        if resident < cache.next_memory_checkpoint_bytes {
            return None;
        }
        cache.next_memory_checkpoint_bytes =
            (resident / MEMORY_CHECKPOINT_STEP_BYTES + 1) * MEMORY_CHECKPOINT_STEP_BYTES;
        Some(cache.compacted)
    });
    if let Some(bodies) = checkpoint {
        tcx.dcx().note(format!(
            "trust: memory checkpoint after {bodies} compacted artifact slots: resident {} GiB",
            gib(resident),
        ));
    }
}

/// Trust (T3 L4, C09w; L4-SUMMARY-1): the crate's verification-memory counters, for its
/// coverage row (`CoverageTransportSummary::memory`, required on the wire) and the
/// `-Ztrust-memory-notes` census, which prints the same values. Read once, at the end of
/// the eager walk: every pass has returned and every pending citation has been finalized, so
/// the sweep counts every compacted context no other holder kept, and a context a pending
/// citation still holds counts as held for that citation, never as alive after compaction.
/// Counts only: the resident sizes are the host's and stay in the note.
fn memory_summary(tcx: TyCtxt<'_>) -> trust_types::MemorySummary {
    use trust_types::MemorySummary;
    // The contexts the records' provisional artifacts still hold, by address: read before
    // the cache, and nothing drops between the two reads.
    let (citations, held_contexts) =
        tcx.sess.with_trust_compiler_state::<SessionPendingImportCitations, _>(|state| {
            // The addresses go into a set, which no visit order changes.
            #[allow(rustc::potential_query_instability)]
            let held: FxHashSet<usize> = state
                .bodies
                .values()
                .filter_map(|record| record.artifacts.as_ref())
                .map(|hold| Arc::as_ptr(&hold.ctx).addr())
                .collect();
            (state.citation_holds.census(), held)
        });
    let (compacted, handle_dropped, rehits, released, alive) =
        tcx.sess.with_trust_compiler_state::<SessionArtifactCache, _>(|cache| {
            // Trust (T3 L4, C07): every pass has returned, so the sweep counts every
            // compacted context no other holder kept.
            cache.sweep_compacted_contexts();
            (
                cache.compacted,
                cache.compacted_after_handle_dropped,
                cache.compacted_rehits,
                cache.contexts_released,
                cache.compacted_contexts_alive_unheld(&held_contexts),
            )
        });
    let CitationHoldCensus { attached, held, max_held } = citations;
    MemorySummary::new(
        [
            (MemorySummary::SLOTS_COMPACTED, compacted),
            (MemorySummary::COMPACTED_AFTER_HANDLE_DROPPED, handle_dropped),
            (MemorySummary::COMPACTED_REHITS, rehits),
            (MemorySummary::CONTEXTS_RELEASED, released),
            (MemorySummary::CONTEXT_ALIVE_AFTER_COMPACTION, alive),
            (MemorySummary::CONTEXTS_HELD_FOR_CITATION, held),
            (MemorySummary::CITATION_HOLDS_ATTACHED, attached),
            (MemorySummary::CITATION_HOLDS_MAX, max_held),
        ]
        .map(|(name, value)| (name.to_string(), value)),
    )
}

/// The crate's retained-memory census, emitted beside the transport crate
/// summary it explains — only under `-Ztrust-memory-notes`, and then always.
/// Off by default because its resident figures are the host's: a note that
/// appeared once a compile crossed 4 GiB made ui stderr machine-dependent.
/// Trust (T3 L4, C09w): its counts are `memory`'s, the coverage row's summary, so the
/// note and the wire cannot disagree.
fn emit_memory_census_note(tcx: TyCtxt<'_>, memory: &trust_types::MemorySummary) {
    use trust_types::MemorySummary;
    if !tcx.sess.opts.unstable_opts.trust_memory_notes {
        return;
    }
    let count = |name: &str| memory.counter(name).unwrap_or(0);
    let compacted = count(MemorySummary::SLOTS_COMPACTED);
    let handle_dropped = count(MemorySummary::COMPACTED_AFTER_HANDLE_DROPPED);
    let rehits = count(MemorySummary::COMPACTED_REHITS);
    let released = count(MemorySummary::CONTEXTS_RELEASED);
    // Trust (T3 L4, C07): the plan's §3.6 reads the contexts still alive after their slots
    // were compacted under its own name, `context_alive_after_compaction` (expected 0).
    let alive = count(MemorySummary::CONTEXT_ALIVE_AFTER_COMPACTION);
    // Trust (T3 L4, C07r; L4-E9-1): and the contexts pending import citations held past
    // their passes, under the plan's name `contexts_held_for_citation` (expected 0). Every
    // amendment has run, so none is still held unless a record outlived its finalization.
    // C09w: a held context is counted here and not in `alive`.
    let still_held = count(MemorySummary::CONTEXTS_HELD_FOR_CITATION);
    let attached = count(MemorySummary::CITATION_HOLDS_ATTACHED);
    let max_held = count(MemorySummary::CITATION_HOLDS_MAX);
    let highest = tcx
        .sess
        .with_trust_compiler_state::<SessionArtifactCache, _>(|cache| cache.highest_resident_bytes);
    tcx.dcx().note(format!(
        "trust: memory census: {compacted} artifact slots compacted after their verify pass \
         ({handle_dropped} after the pass had dropped its own handle), {rehits} compacted slots \
         recomputed by a later pass (compacted_rehits={rehits}), {released} compacted \
         contexts released (context_alive_after_compaction={alive}), {attached} contexts \
         held for a pending citation (contexts_held_for_citation={still_held}, at most \
         {max_held} at once); resident {} GiB now, highest {} GiB read at a body boundary",
        gib(resident_bytes_now()),
        gib(highest),
    ));
}

fn format_artifact_cache_key_with_prefix<'tcx>(
    prefix: &str,
    def_path: &str,
    body: &Body<'tcx>,
) -> ArtifactCacheKey {
    use std::fmt::Write as _;

    let promoted = body.source.promoted.map(|promoted| promoted.index()).unwrap_or(usize::MAX);
    let mut key = String::with_capacity(prefix.len() + def_path.len() + 64);
    key.push_str(prefix);
    key.push_str(def_path);
    let _ = write!(
        key,
        "|{:?}|promoted={promoted}|pipeline_v2={}",
        body.source.instance, true
    );
    key
}

fn artifact_cache_key_with_def_path<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    policy: &TrustVerifyPolicy,
    def_path: &str,
) -> ArtifactCacheKey {
    let mode_tag = policy.mode_cache_tag();
    let include_dependencies = policy.include_dependencies;
    if let Some(key) = tcx.sess.with_trust_compiler_state::<SessionArtifactCache, _>(|cache| {
        cache
            .key_prefixes
            .iter()
            .find(|&&(tag, deps, _)| tag == mode_tag && deps == include_dependencies)
            .map(|(_, _, prefix)| format_artifact_cache_key_with_prefix(prefix, def_path, body))
    }) {
        return key;
    }
    let policy_key = artifact_cache_policy_key(policy);
    // Trust: state is invocation-scoped, while this key distinguishes every
    // result-determining policy/semantic and every body within that invocation.
    let semantics_key = verification_semantics_key(tcx, tcx.sess, policy);
    let prefix = format!("{policy_key}|semantics={semantics_key}|");
    let key = format_artifact_cache_key_with_prefix(&prefix, def_path, body);
    tcx.sess.with_trust_compiler_state::<SessionArtifactCache, _>(|cache| {
        if !cache
            .key_prefixes
            .iter()
            .any(|&(tag, deps, _)| tag == mode_tag && deps == include_dependencies)
        {
            cache.key_prefixes.push((mode_tag, include_dependencies, prefix));
        }
    });
    key
}

fn artifact_cache_key<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    policy: &TrustVerifyPolicy,
) -> ArtifactCacheKey {
    let def_path = trust_mir_extract::safe_def_path_str(tcx, body.source.def_id());
    artifact_cache_key_with_def_path(tcx, body, policy, &def_path)
}

fn artifact_cache_policy_key(policy: &TrustVerifyPolicy) -> String {
    format!(
        "mode={mode};generated={generated};dependencies={dependencies}",
        mode = policy.mode_cache_tag(),
        generated = true,
        dependencies = policy.include_dependencies,
    )
}

/// Trust: the query providers' read. Clones the one field the provider takes —
/// never the whole artifact (the cache always holds a second handle, so the
/// old `Arc::try_unwrap` never succeeded and every provider call deep-cloned
/// every VC formula only to drop all but this field).
pub(crate) fn collect_proof_results_cached<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Option<TrustProofResults> {
    collect_verification_artifacts_cached(
        tcx,
        body,
        false,
        |full| full.proof_results.clone(),
        |compact| Some(compact.proof_results.clone()),
    )
}

/// Trust: `collect_proof_results_cached` for the telemetry provider.
pub(crate) fn collect_proof_telemetry_cached<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Option<TrustProofTelemetry> {
    collect_verification_artifacts_cached(
        tcx,
        body,
        false,
        |full| full.telemetry.clone(),
        |compact| Some(compact.telemetry.clone()),
    )
}

/// Trust: the panic-freedom premise's read (see [`PremiseArtifacts`]). Computes
/// with the decision already taken, as the verify pass does, on a miss.
pub(crate) fn collect_premise_artifacts_cached<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Option<PremiseArtifacts> {
    collect_verification_artifacts_cached(tcx, body, true, PremiseArtifacts::Full, |compact| {
        Some(PremiseArtifacts::Compact(compact))
    })
}

/// Trust: the verify pass's read. It needs the full artifact, so a compacted
/// slot is a miss here and the pass recomputes. Returns the computed cache key
/// alongside the artifact so `CompactArtifactsAfterPass` reuses it without
/// formatting a second key or re-walking `safe_def_path_str`.
fn collect_verification_artifacts_cached_after_decision<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    policy: &TrustVerifyPolicy,
    def_path: &str,
) -> Option<(ArtifactCacheKey, Arc<VerificationArtifacts>)> {
    // Trust #3: the in-pass consumer only borrows the artifact, so share the Arc
    // instead of deep-cloning the cached payload.
    collect_verification_artifacts_cached_inner(
        tcx,
        body,
        policy,
        Some(def_path),
        true,
        true,
        |full| full,
        |_| None,
    )
}

/// Trust: one artifact-cache read, seen through its reader. `full` and `compact`
/// turn a slot into the reader's value; `compact` answers `None` when the reader
/// needs the full artifact, and that compacted slot is then a miss that
/// recomputes — counted in `compacted_rehits`, never silent.
fn collect_verification_artifacts_cached<'tcx, R>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    decision_already_verified: bool,
    full: impl Fn(Arc<VerificationArtifacts>) -> R,
    compact: impl FnOnce(Arc<CompactArtifacts>) -> Option<R>,
) -> Option<R> {
    let policy = TrustVerifyPolicy::from_session(tcx.sess);
    collect_verification_artifacts_cached_inner(
        tcx,
        body,
        &policy,
        None,
        decision_already_verified,
        false,
        full,
        compact,
    )
    .map(|(_, value)| value)
}

fn collect_verification_artifacts_cached_inner<'tcx, R>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    policy: &TrustVerifyPolicy,
    def_path: Option<&str>,
    decision_already_verified: bool,
    return_key: bool,
    full: impl Fn(Arc<VerificationArtifacts>) -> R,
    compact: impl FnOnce(Arc<CompactArtifacts>) -> Option<R>,
) -> Option<(ArtifactCacheKey, R)> {
    let key = match def_path {
        Some(def_path) => artifact_cache_key_with_def_path(tcx, body, policy, def_path),
        None => artifact_cache_key(tcx, body, policy),
    };
    let native_scope = native_admission::Scope::open(tcx, body.source.def_id(), &key);
    enum Slot {
        Miss,
        Absent,
        Full(Arc<VerificationArtifacts>),
        Compact(Arc<CompactArtifacts>),
    }
    // Trust #3: clone the Arc (refcount bump), not the artifact payload.
    let slot = tcx.sess.with_trust_compiler_state::<SessionArtifactCache, _>(|cache| {
        match cache.entries.get(&key) {
            None => Slot::Miss,
            Some(CachedArtifacts::Absent) => Slot::Absent,
            Some(CachedArtifacts::Full(artifacts)) => Slot::Full(Arc::clone(artifacts)),
            Some(CachedArtifacts::Compact(projection)) => Slot::Compact(Arc::clone(projection)),
        }
    });
    let hit = match slot {
        Slot::Miss => None,
        Slot::Absent => {
            native_scope
                .outcome(trust_types::native_admission::NativeAdmissionOutcome::CachedAbsence);
            return None;
        }
        Slot::Full(artifacts) => Some(full(artifacts)),
        // A compacted slot means a verify pass already consumed this key. A reader
        // that needs the full artifact recomputes — counted, never silent.
        Slot::Compact(projection) => {
            let value = compact(projection);
            if value.is_none() {
                tcx.sess.with_trust_compiler_state::<SessionArtifactCache, _>(|cache| {
                    cache.compacted_rehits += 1;
                });
            }
            value
        }
    };
    if let Some(value) = hit {
        native_scope.outcome(trust_types::native_admission::NativeAdmissionOutcome::CacheReuse);
        debug!("Trust: artifact cache hit for {key}");
        let ret_key = if return_key { key } else { String::new() };
        return Some((ret_key, value));
    }

    // Trust (T3 L4, C09): the identity oracle's context for this body's collection, installed
    // while it runs, so every key the collection mints is identified in it, and left in the
    // frozen context's memo slot, where the pass that consumes the artifacts finds it again
    // (`row_key::Installed`). Nothing when the elision audit is off.
    let row_keys = row_key::Installed::open();
    let artifacts = collect_verification_artifacts_inner_with_policy(
        tcx,
        body,
        decision_already_verified,
        policy,
        &native_scope,
    )
    .map(|artifacts| {
        row_keys.adopt(&artifacts.ctx);
        Arc::new(artifacts)
    });
    drop(row_keys);
    let ret_key = if return_key && artifacts.is_some() { key.clone() } else { String::new() };
    tcx.sess.with_trust_compiler_state::<SessionArtifactCache, _>(|cache| {
        // Trust #3: store a shared Arc handle, not a deep clone of the artifact.
        let slot = match &artifacts {
            Some(artifacts) => CachedArtifacts::Full(Arc::clone(artifacts)),
            None => CachedArtifacts::Absent,
        };
        cache.entries.insert(key, slot);
    });
    artifacts.map(|artifacts| (ret_key, full(artifacts)))
}

/// Trust #529, plan P4 / T4.1: a router over a fresh backend inventory.
///
/// Every call builds its own backends, so no solver context, learned lemma or
/// cached answer survives from one call to the next, and a verdict cannot
/// depend on which function's VCs reached the router first. The one consumer,
/// the Liskov check in `all_trait_impls_verified`, builds one router per impl
/// pair and dispatches its VCs serially (`Router::verify_all`).
fn build_router(sess: &Session) -> trust_router::Router {
    trust_router::Router::with_backends(discover_router_backends(
        vc_timeout_ms(sess),
        effort_scale(sess),
    ))
}

/// Resolve the tracked per-VC wall-clock timeout: the backstop of
/// [`effort_scale`] on the ay lanes, and still the bound of the native CHC/PDR
/// engine, which has no count yet (determinism plan P4a). The option layer owns
/// the default so parsing, hashing, and execution cannot diverge.
fn vc_timeout_ms(sess: &Session) -> u64 {
    sess.opts.unstable_opts.trust_verify_timeout_ms
}

/// Trust (determinism plan §3.2a): the tracked scale of the ONE solver-effort
/// count (`-Ztrust-verify-effort`). Every router ay lane sends each query
/// `(set-option :rlimit N)`, `N = min(100000, max(1, k · size))` over the
/// assertions in scope at its check-sat. A search the count ends stops at the
/// same point on every host at every load. It does not stand in front of the
/// wall clock above for every query: `:rlimit` bounds each SAT solve, not the
/// whole check, and ay's residual clocks spend time no count reaches, so a
/// query can still end on the clock (`wall-backstop`) until T2
/// (`EffortScale`'s docs list what is not covered). There is no per-function
/// count.
fn effort_scale(sess: &Session) -> trust_types::determinism::EffortScale {
    trust_types::determinism::EffortScale {
        conflicts_per_node: sess.opts.unstable_opts.trust_verify_effort,
    }
}

fn remaining_solver_timeout_ms(
    configured_ms: u64,
    deadline: Option<std::time::Instant>,
    now: std::time::Instant,
) -> Option<u64> {
    let Some(deadline) = deadline else {
        return Some(configured_ms);
    };
    let remaining = deadline.checked_duration_since(now)?;
    let remaining_ms = u64::try_from(remaining.as_millis()).unwrap_or(u64::MAX).max(1);
    Some(configured_ms.min(remaining_ms))
}

/// Trust: Resolve the cooperative per-function verification wall-clock budget.
///
/// This is a soundness-preserving safety net, not a tuning knob. The per-VC
/// solver timeout defaults to 5 seconds, so a single
/// machine-generated function with hundreds of thousands of obligations (e.g.
/// in `rustc_query_impl`) could otherwise consume *hours* — the sum of per-VC
/// timeouts is unbounded in function size. When this budget is exceeded, the
/// remaining obligations of that function degrade to `Unknown` (never `Proved`)
/// so a pathological body does not start more solver work indefinitely. Each
/// synchronous backend also receives a per-query timeout, and any result that
/// returns after this deadline is rejected. This is deliberately described as
/// cooperative: rustc verification runs in-process, so the deadline cannot
/// asynchronously unwind arbitrary synchronous Rust preprocessing code. Healthy
/// functions verify in milliseconds and never approach it. Override with
/// `-Ztrust-verify-function-budget-ms=<ms>`; `0` disables the budget entirely.
/// The option layer is the single owner of the default value; this layer only
/// turns that tracked value into a deadline computed fresh for each function.
fn verify_fn_deadline(sess: &Session) -> Option<std::time::Instant> {
    let ms = sess.opts.unstable_opts.trust_verify_function_budget_ms;
    verify_fn_deadline_from_ms(ms, std::time::Instant::now())
}

fn verify_fn_deadline_from_ms(ms: u64, now: std::time::Instant) -> Option<std::time::Instant> {
    if ms == 0 {
        return None;
    }
    if let Some(deadline) = now.checked_add(std::time::Duration::from_millis(ms)) {
        return Some(deadline);
    }

    // Do not turn an extremely large user budget into the much smaller
    // 120-second default merely because this platform's `Instant` cannot
    // represent the requested date. Clamp to the greatest representable
    // millisecond offset instead. This preserves monotonic option semantics:
    // increasing the budget can never unexpectedly shorten it.
    let mut low = 0_u64;
    let mut high = ms;
    while low < high {
        let midpoint = low + (high - low) / 2 + 1;
        if now.checked_add(std::time::Duration::from_millis(midpoint)).is_some() {
            low = midpoint;
        } else {
            high = midpoint - 1;
        }
    }
    now.checked_add(std::time::Duration::from_millis(low))
}

/// Trust (L0 termination guarantee): if the per-function budget is already spent
/// at a synchronous-preprocessing checkpoint (after extraction, after VC
/// generation), emit a LOCATED diagnostic and return `true` so the caller stops
/// preprocessing this function. In a fail-closed lane (strict/certify/
/// memory-safe) the diagnostic is deliberately a hard error, NOT the `Unknown`
/// a solver timeout gets: a solver timeout means "could not decide" (a
/// completeness gap); a preprocessing overrun means the verifier could not even
/// finish building the obligations — a defect the developer must see, and a
/// fail-closed build may not continue past an incomplete inventory. In the
/// advisory lane the same finding is a WARNING and the caller substitutes the
/// honest per-function budget verdict (`preprocessing_budget_artifacts`: one
/// synthetic `Unknown` row, partial VCs discarded) — advisory's documented
/// contract is that nothing in the verify pass is a hard error, and an
/// over-budget function costs completeness, never soundness. Combined
/// with the ambient `verify_budget` polls inside the preprocessing loops, the
/// audited loops either terminate by their own bound or trip the budget (step
/// count OR wall clock), and reaching a checkpoint over budget is always
/// reported, never spun on.
/// This does not claim a whole-pass kernel proof that every future loop is
/// instrumented. `-Ztrust-verify-function-budget-ms=0` disables the clock half;
/// the step half is a seal constant with no off switch.
fn preprocessing_budget_exceeded<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    def_path: &str,
    phase: &str,
    fail_closed: bool,
) -> bool {
    // Reads the ambient budget installed at function entry — catches both a
    // spent step count and a passed wall-clock deadline. Non-charging.
    if !trust_types::verify_budget::exhausted_readonly() {
        return false;
    }
    let message = format!(
        "Trust verification exceeded its per-function budget ({} ms / {} steps) during {phase} \
         of `{def_path}` — possible verifier non-termination. If the clock fired, raise \
         `-Ztrust-verify-function-budget-ms` (`[trust] backstop` under `targo trust`); the \
         step budget is a seal constant: simplify the function, or report a verifier defect.",
        tcx.sess.opts.unstable_opts.trust_verify_function_budget_ms,
        tcx.sess.opts.unstable_opts.trust_verify_function_budget_steps,
    );
    if fail_closed {
        // Strict/certify/memory-safe: the halt stays a located BUILD ERROR — the
        // verifier could not even finish building this function's obligations,
        // and a fail-closed lane may not continue past an incomplete inventory.
        tcx.dcx().span_err(body.span, message);
        // Keyed on the DefId, not a rendered path: the checkpoint's `def_path` is the
        // bare item path (`stepped`) while the no-artifacts abort renders the
        // crate-qualified one (`verifier_budget_termination::stepped`) — measured,
        // a string key never matched and the second error still fired.
        with_crate_verification_state(tcx.sess, |state| {
            state.budget_aborted_defs.insert(body.source.def_id());
        });
    } else {
        // Advisory ("NOTHING in the verify pass is a hard error" — the
        // TrustVerifyPolicy contract): same located finding, WARNING severity.
        // The caller replaces this function's whole inventory with a single
        // synthetic `Unknown` budget row, so the overrun is REPORTED as an
        // unverified coverage gap instead of aborting a survey build. An
        // over-budget function is never `Proved` — the cost is completeness,
        // never soundness (see `trust_types::verify_budget`).
        tcx.dcx().span_warn(body.span, message);
    }
    true
}

/// Trust (L0 termination guarantee, advisory lane): the honest per-function
/// verdict for a preprocessing budget overrun — the SAME synthetic single-
/// obligation `Unknown` shape `unsupported_contract_artifacts` uses, so an
/// over-budget function can never read as `Proved`/passed in the terminal
/// report, the cache, or any downstream gate. Partial VC output from the
/// interrupted phase is deliberately DISCARDED by the caller: a truncated
/// obligation set must not masquerade as this function's complete inventory.
///
/// Constructed under a FRESH ambient step budget: the enclosing function's
/// budget is spent by definition here, and the O(1) synthetic-row build must
/// not trip charged choke points inside the report builders.
fn preprocessing_budget_artifacts(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    def_path: &str,
    phase: &str,
) -> VerificationArtifacts {
    // Which bound decided this: the step COUNT (reproducible) or the wall
    // clock (a backstop; not reproducible). Read BEFORE the fresh guard below
    // replaces the enclosing scope's latch (determinism plan §3.2/§3.7).
    let cause = trust_types::verify_budget::exhaustion_cause()
        .unwrap_or(trust_types::determinism::StopCause::Unclassified);
    // A NAMED binding, dropped explicitly below: the fresh budget must stay
    // installed across the whole shared report build, not just this statement.
    let fresh_budget = trust_types::verify_budget::VerifyBudgetGuard::install(
        None,
        tcx.sess.opts.unstable_opts.trust_verify_function_budget_steps,
    );
    let reason = cause.stamp(&format!(
        "unverified: per-function verification budget ({} ms / {} steps) exhausted during {phase}",
        tcx.sess.opts.unstable_opts.trust_verify_function_budget_ms,
        tcx.sess.opts.unstable_opts.trust_verify_function_budget_steps,
    ));
    // Determinism plan §3.7 (2026-10-01): when the CLOCK half tripped, the
    // function's one row is a clock stop and is published as one — `timed_out`,
    // naming the budget, with the `wall-backstop` cause — like every other row
    // a clock left unproved (`stamp_clock_stopped_rows`). The phase stays in
    // the row's detail. A step-count trip is deterministic and stays `unknown`.
    let artifacts = if cause == trust_types::determinism::StopCause::WallBackstop {
        single_row_artifacts(
            tcx,
            body,
            def_path,
            "TrustPreprocessingBudget",
            reason,
            VerificationResult::Timeout {
                solver: trust_types::Symbol::intern("trust-verify-budget"),
                timeout_ms: tcx.sess.opts.unstable_opts.trust_verify_function_budget_ms,
            },
        )
    } else {
        single_unknown_row_artifacts(
            tcx,
            body,
            def_path,
            "TrustPreprocessingBudget",
            reason.clone(),
            "trust-verify-budget",
            reason,
        )
    };
    drop(fresh_budget);
    artifacts
}

fn verify_worker_thread_limit(sess: &Session) -> Option<u16> {
    verify_worker_thread_limit_from(sess.opts.unstable_opts.trust_verify_worker_threads)
}

fn verify_worker_thread_limit_from(requested: usize) -> Option<u16> {
    (requested > 0).then(|| u16::try_from(requested).ok()).flatten()
}

fn full_verifier_execution_context(
    sess: &Session,
    run_id: impl Into<String>,
    deadline: Option<std::time::Instant>,
) -> trust_router::VerifierExecutionContext {
    full_verifier_execution_context_from(run_id, deadline, verify_worker_thread_limit(sess))
}

/// Trust (2026-10-17, gate-rca deadline): the instant the native TrustIr lane — bundle
/// construction (`build_full_verification_input`) and the live dispatch
/// (`verify_full_bundle_with_live_receipts`) — must stop at: half of what is left of the
/// function's clock when the lane starts. `None` when the function has no clock.
///
/// WHY A SHARE. After the dispatch, the full lane's certifying lanes decide the rows the
/// native engines left open: the in-process ay bridge (with its interval lane and S1's
/// strict re-solve), the refutation lanes, `promote_structurally_dead_unreachable`,
/// `promote_kernel_certifiable` and the certification sweep. They share the function
/// deadline with the dispatch and run after it, so a dispatch that runs to the deadline
/// leaves them nothing. Measured on the candidate gate 20261016T202952Z-7f3690ed73: 214
/// rows the seal proved in milliseconds (clean-kernel-certified 96, interval 59,
/// ay-in-process 28, structural-propositional-unsat 19, …) were published as clock-stopped
/// timeouts, in 33 functions whose native lane, newly able to lower them, spent the whole
/// 120 s in trust-mc PDR solves (16 functions) or in bundle construction (17); the
/// re-run of aterm-conformance alone reproduced the gate row for row.
///
/// WHY HALF. Neither side's need is known before it runs: the native lane's is the sum of
/// its per-obligation solves (each up to the per-query clock and the driver watchdog),
/// the certifying lanes' the sum of their per-row ay solves, re-solves and kernel checks.
/// An even split bounds the loss on either side to half the clock, never doubles the
/// function's worst-case wall time (a separate later window for the certifying lanes,
/// tried 2026-10-02, did), and changes nothing for the function whose native lane
/// finishes early: every lane after it still runs to the function's own deadline. The
/// clocks stay what the determinism plan calls them, backstops: a row either clock
/// leaves undecided is published as a clock stop (`stamp_clock_stopped_rows`).
fn native_lane_cutoff(
    now: std::time::Instant,
    function_deadline: Option<std::time::Instant>,
) -> Option<std::time::Instant> {
    let deadline = function_deadline?;
    Some(now + deadline.saturating_duration_since(now) / 2)
}

fn full_verifier_run_id(def_path: &str) -> String {
    format!("trustc-full:{}", trust_types::canonical_artifact_id_component(def_path))
}

fn full_verifier_execution_context_from(
    run_id: impl Into<String>,
    deadline: Option<std::time::Instant>,
    worker_threads: Option<u16>,
) -> trust_router::VerifierExecutionContext {
    let mut context = trust_router::VerifierExecutionContext::new(run_id);
    if let Some(deadline) = deadline {
        context = context.with_deadline(deadline);
    }
    if let Some(worker_threads) = worker_threads {
        context = context.with_limits(trust_verifier_api::VerifierResourceLimits {
            worker_threads: Some(worker_threads),
            ..trust_verifier_api::VerifierResourceLimits::unlimited()
        });
    }
    context
}

/// Trust #529, plan P4 / T4.1: the routed source-verification backends, built
/// fresh for each router (`build_router`) from the tracked per-VC timeout and
/// effort scale. Every one runs in this process: no backend spawns a solver,
/// none is found through PATH or an environment variable, and the environment
/// variables they do read (`TRUST_INTERVAL_DEBUG`, `TRUST_AY_SMT_TRACE`,
/// `TRUST_BOUNDED_MC_DEBUG`, `AY_LOG`) only switch on diagnostic output.
///
/// Backend portfolio, in dispatch order:
/// 1. `IntervalBackend` — cheap interval/range lane for bounded arithmetic
/// 2. `InProcessAyBackend` — the ay linked into this compiler, primary SMT
/// 3. `TyBackend` — temporal obligations and protocol-style properties
/// 4. `ConstantFolderBackend` — canonical evaluation of constant formulas
///
/// On a Liskov VC (`VcKind::Postcondition` or `Precondition`, no contract
/// metadata), the interval lane matches only safety kinds and `TyBackend`
/// only temporal ones. The constant folder cannot decide a symbolic formula,
/// so symbolic Liskov checks still use the linked ay,
/// the same lane `Router::deterministic_in_process_ay` builds.
///
/// Until T4.1 (2026-10-10) slot 2 was the subprocess `IncrementalAYSession`
/// over a snapshot of the `ay` beside `trustc` (or `-Ztrust-verify-ay-path`),
/// kept for the whole Session behind a mutex, so learned lemmas crossed
/// functions and which function reached it first was a scheduling accident
/// (plan §3.5, "Solver history"). The in-process lane sets `:produce-proofs`
/// and returns a strict-checked `SmtBacked`, a kernel-replayed `Certified`, or
/// a finite-domain `Sound`, never an `Unchecked` bare `unsat`.
fn discover_router_backends(
    timeout_ms: u64,
    scale: trust_types::determinism::EffortScale,
) -> Vec<Box<dyn trust_router::VerificationBackend>> {
    vec![
        // Trust: cheap in-process interval/range backend — discharges bounded
        // arithmetic-overflow VCs (modulo, bitmasks, widening casts, branch
        // constants) in microseconds, ranked ahead of ay which otherwise times
        // out / returns unknown / false-fails on them. Sound by
        // over-approximation: it only claims VCs it can prove, so everything
        // else falls through to ay.
        Box::new(trust_router::interval_backend::IntervalBackend),
        // Trust (plan P4, T4.1): the linked ay, a fresh solver context per
        // query, bounded by the one effort count with the per-VC clock as its
        // backstop.
        Box::new(
            trust_router::InProcessAyBackend::new()
                .with_timeout(timeout_ms)
                .with_effort_scale(scale),
        ),
        // Trust: the temporal backend for temporal / protocol obligations.
        Box::new(trust_router::ty_backend::TyBackend),
        // Trust: use the shared constant evaluator instead of constructing
        // formula-only WP requests for an engine that owns no such claims.
        // Real body-aware WP remains in the typed full-verification route.
        Box::new(trust_router::constant_folder::ConstantFolderBackend),
    ]
}

/// Trust: The trust_verify MIR pass.
///
/// Runs batteries-on verification on each in-scope function's optimized MIR.
/// The pass is read-only apart from one bounded rewrite: a KernelCertified
/// Add/Sub/Mul overflow check loses its panic edge, because a proof that does not
/// survive to codegen is not worth having. vcgen supplies a private exact
/// VC-to-block origin, and the pass rechecks the live `Assert` before changing
/// its panic edge. Source spans remain presentation metadata and never
/// authorize a CFG rewrite.
pub(super) struct TrustVerify;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TrustOutputMode {
    Human,
    Json,
    Both,
}

impl TrustOutputMode {
    /// The catch-all is total over a CLOSED domain, not a silent fallback: this
    /// reads a `String` that `parse_trust_verify_output` (rustc_session) accepts
    /// only as `human`/`json`/`both`, and that the driver re-checks for a
    /// callback-injected value. Its default is also `human`, so the arm it lands
    /// on for the one reachable unmatched value is the option's own default and
    /// not a demotion. Said here because the sibling profile read below could
    /// once have carried the same sentence and could not — see
    /// `hardened_verification_enabled`, where answering "no" to an unknown value
    /// turned hardening off while the front end announced it.
    fn parse(sess: &Session) -> Self {
        match sess.opts.unstable_opts.trust_verify_output.as_str() {
            "json" => Self::Json,
            "both" => Self::Both,
            _ => Self::Human,
        }
    }

    fn emit_human(self) -> bool {
        matches!(self, Self::Human | Self::Both)
    }

    fn emit_json(self) -> bool {
        matches!(self, Self::Json | Self::Both)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct TrustVerifyPolicy {
    include_dependencies: bool,
    /// The selected `-Ztrust-policy`. Advisory runs the artifact-backed full
    /// verifier but does NOT fail-closed (unproved obligations report
    /// `unknown`/`failed` instead of aborting the crate), so a whole crate's
    /// proved/unknown/failed coverage is reportable. It also suppresses the
    /// ground/forced-counterexample escalation
    /// (`escalate_refuted_l0_safety_counterexamples`), so NOTHING in the verify
    /// pass is a hard error — verification is purely advisory. This is the
    /// opt-in escape hatch while the prover/solver is being improved:
    /// provably-safe code the prover cannot yet prove still compiles, with the
    /// full obligation report intact.
    policy: TrustPolicy,
}

impl TrustVerifyPolicy {
    fn from_session(sess: &Session) -> Self {
        // Reporting roles never weaken compiler scope. Batteries-on
        // verification always includes generated MIR and uses the native typed
        // route; the nonfatal policies retain the same evidence path and only
        // change what an unproved obligation does to the build.
        Self {
            include_dependencies: sess.opts.unstable_opts.trust_verify_include_dependencies,
            policy: sess.opts.unstable_opts.trust_policy,
        }
    }

    fn fail_closed(&self) -> bool {
        // Advisory keeps full (artifact-backed) verification but never aborts.
        self.policy.is_strict() || self.policy.is_memory_safe()
    }

    fn is_explicit_advisory(&self) -> bool {
        self.policy.is_advisory()
    }

    fn admits_contract_panic_conditional_evidence(&self) -> bool {
        // A declared reachable panic is not a proof. Only the broad, explicitly
        // nonfatal policy may retain it as conditional evidence. In particular,
        // memory-safe uses the otherwise-strict policy object and must not
        // acquire a second, contract-based admission path.
        self.is_explicit_advisory()
    }

    fn includes_non_local_mir(&self) -> bool {
        self.include_dependencies
    }

    fn skip_is_full_verification_failure(&self, reason: &TrustVerifySkipReason) -> bool {
        if !self.fail_closed() {
            return false;
        }
        // `UserOptOut` is the user-applied `#[trust::skip]`. Allowing it in an
        // in-scope strict unit silently removes a function from proof inventory,
        // so it is a fail-closed coverage error.
        //
        // `ContractGeneratedClosure`: Trust never treats rustc's inherited
        // `__requires_checker`/`__ensures_checker` closure as proof inventory.
        // Trust-active compilations reject the legacy runtime-projection option,
        // and the explicit vanilla-compatibility lane disables Trust verification.
        // Dead compatibility machinery's absence from the proven set is not a
        // coverage gap; the contract itself is still enforced through the PARENT's
        // precondition/postcondition obligations and the callers' call-site
        // precondition VCs, which are all verified as before.
        if matches!(
            reason,
            TrustVerifySkipReason::ContractGeneratedClosure
                | TrustVerifySkipReason::UninhabitedArgument
        ) {
            return false;
        }
        // Trust (CB4): `TestHarnessSynthesized` — rustc's libtest harness code
        // (a builtin `#[test]` runner closure, the harness `main`), excluded only
        // on provenance plus an exact MIR shape check
        // (`test_harness_exclusion::decide`). It carries no user code, every
        // test function it calls is verified as its own body, and it is never
        // proof: its one transport row is an `excluded:` row targo keeps out of
        // the obligation total. Not a coverage gap in any policy — the same
        // disposition as `ContractGeneratedClosure`, except that these bodies
        // RUN, which is why libtest is listed as Conditional trust base in
        // test-mode units (docs/DECISION_QUEUE.md).
        if matches!(reason, TrustVerifySkipReason::TestHarnessSynthesized(_)) {
            return false;
        }
        // `#[trust::assume_total]` is an explicit user-audited assumption. It
        // remains visible as an assumption row in every mode and is never a
        // full-verification skip failure.
        if matches!(reason, TrustVerifySkipReason::AssumedTotal) {
            return false;
        }
        // Full verification is target-crate scoped so ordinary Cargo
        // dependency graphs remain buildable. Dependency verification is still
        // fail-closed when explicitly requested through the dependency scope.
        !(matches!(
            reason,
            TrustVerifySkipReason::ExternalDependencyScope | TrustVerifySkipReason::NonLocalMir
        ) && !self.include_dependencies)
    }

    /// Whether a fail-closed skip aborts the build. Raw/unscoped and primary
    /// scopes are strict, including capability gaps. Survey is nonfatal
    /// and record eligible gaps as assumption rows instead.
    fn skip_aborts_build(&self, reason: &TrustVerifySkipReason) -> bool {
        self.skip_is_full_verification_failure(reason)
    }

    fn includes_native_trust_ir_callee_closure(&self) -> bool {
        // Batteries-on verification intentionally uses the native typed path
        // (R-U Phase D: the former `uses_native_typed_route` policy hook was
        // hardcoded true and its legacy Path-1 alternative is deleted).
        true
    }

    fn mode_cache_tag(&self) -> &'static str {
        "full"
    }
}

fn env_flag_enabled(name: &str) -> bool {
    static ENABLED_TRUST_ENV_FLAGS: std::sync::OnceLock<FxHashSet<String>> =
        std::sync::OnceLock::new();
    if name.starts_with("TRUST_") {
        let enabled = ENABLED_TRUST_ENV_FLAGS.get_or_init(|| {
            std::env::vars_os()
                .filter_map(|(k, v)| {
                    let k = k.into_string().ok()?;
                    if !k.starts_with("TRUST_") {
                        return None;
                    }
                    let v = v.into_string().ok()?;
                    env_flag_value_enabled(&v).then_some(k)
                })
                .collect()
        });
        !enabled.is_empty() && enabled.contains(name)
    } else {
        std::env::var(name).is_ok_and(|value| env_flag_value_enabled(&value))
    }
}

// Trust: the def-path LABEL for an env-gated probe `eprintln!` (`TRUST_*_DEBUG`,
// `TRUST_*_PROBE`, `TRUST_*_TRACE`). A probe line is not a diagnostic, so it must
// not render through the diagnostic printer: a bare `tcx.def_path_str` runs the
// `trimmed_def_paths` query, which arms rustc's `must_produce_diag`, and a probed
// compile that emits no diagnostic — every fully proved crate under
// `-Ztrust-verify-output=json` with a human `--error-format` — then ICEs at
// `DiagCtxt` teardown, after the probe output, with exit 101. Deliberately the
// same width as the call it replaces, so no probe line reflows.
fn probe_label(tcx: TyCtxt<'_>, def_id: DefId) -> String {
    with_no_trimmed_paths!(tcx.def_path_str(def_id))
}

// Trust: gate for the debug-only per-function coverage-attribution eprintln.
// When unset (or not truthy) the pass behaves identically to before — the
// coverage lines are pure observability and never affect any verdict.
fn trust_coverage_debug_enabled() -> bool {
    env_flag_enabled("TRUST_COVERAGE_DEBUG")
}

fn env_flag_value_enabled(value: &str) -> bool {
    let trimmed = value.trim();
    trimmed == "1"
        || trimmed.eq_ignore_ascii_case("true")
        || trimmed.eq_ignore_ascii_case("yes")
        || trimmed.eq_ignore_ascii_case("on")
}

// Trust #verifier-perf: dropped `Copy` because `TrustVerifySkipReason` now
// carries an `TreatedAsAssumption(UnsupportedReason)` variant whose payload
// (the reason string) isn't Copy. Callers only consume the decision once
// in the match below, so removing Copy is safe — no downstream code reads
// the value twice.
#[derive(Clone, Debug, PartialEq, Eq)]
enum TrustVerifyDecision {
    Verify,
    Skip(TrustVerifySkipReason),
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum TrustVerifySkipReason {
    ExternalDependencyScope,
    NonLocalMir,
    ContractGeneratedClosure,
    /// Trust (2026-09-30): the body starts at `Unreachable` because a BY-VALUE
    /// argument's type is uninhabited (`fn from(x: Infallible) -> Self { match x
    /// {} }`). No value of that type exists, so the function can never be entered:
    /// nothing to verify, and not a coverage gap. Every other unreachable start
    /// (e.g. an inlined `unreachable_unchecked`) stays `UnreachableStart`.
    UninhabitedArgument,
    /// Trust (CB4): a body rustc's libtest harness synthesized, in the exact
    /// harness shape — EXCLUDED from the proof inventory with one disclosed
    /// `excluded:test-harness-synthesized` row. See `test_harness_exclusion`.
    TestHarnessSynthesized(test_harness_exclusion::TestHarnessExclusion),
    UnreachableStart,
    /// User-applied `#[trust::skip]` is a coverage gap in strict scope and a
    /// recorded unverified assumption in survey mode.
    UserOptOut,
    /// User-applied `#[trust::assume_total]`: a recorded, explicitly audited
    /// assumption that remains non-fatal and visible in every mode.
    AssumedTotal,
    /// Trust #verifier-perf #22: cheap MIR-shape classifier already
    /// knows lowering cannot succeed on this function (pattern type,
    /// un-monomorphized generic, escaped binder, coroutine, …). The
    /// function is **treated as an unverified assumption** in the proof
    /// report — *not* silently dropped: `record_skip_assumption` emits an
    /// `assumption:<tag>` transport row (outcome `skipped`, under
    /// `-Z trust-verify-output=json|both`) and a human
    /// `Trust: ASSUMPTION [...]` line, and targo surfaces the set in
    /// `report.json`'s `assumptions[]` ("crate X assumed N functions
    /// where the shape was Y"). Strict primary/unscoped scope rejects these
    /// skips as hard errors instead.
    ///
    /// This is the honest framing per the verifier reviews: advisory
    /// verification doesn't mean "attempt full proof of
    /// everything", but skipping silently violates it too. Recording
    /// the assumption is the third state — between Proved and Failed —
    /// that lets us be both fast AND faithful to the methodology.
    TreatedAsAssumption(trust_mir_extract::supportability::UnsupportedReason),
}

/// Trust (skip taxonomy, 2026-09-16): WHAT A SKIP IS.
///
/// `Trust full verification skipped `f`` was ONE headline for four
/// structurally different verdicts. Measured on the aterm corpus
/// (`targo trust check -p aterm-types`) it was the single largest error class
/// — 219 of 569 errors — and NOT ONE of them was a refutation. Only a
/// refutation is a statement about the program being compiled. The other three
/// are statements about Trust, about the author's own declarations, or about
/// scope; printing them in the same words as a proved-false property is wrong
/// ATTRIBUTION, not strictness.
///
/// THIS TYPE CHANGES NO VERDICT. Every compilation whose skips failed the build
/// before still fails it, under the same policy predicate. It is deliberately
/// NOT a demotion lever: there is no arm here that can turn an error into a
/// warning, because a taxonomy that can also mute is a mute button wearing a
/// taxonomy's clothes. (The one place an error MOVES — a closure or nested fn
/// that only inherits `#[trust::skip]` reports through its declaration — is
/// verified at the crate checkpoint; see `trust_reconcile_inherited_skips`.)
///
/// What it does change is three things:
///   1. WHICH WORDS the error uses, so the reader can tell a gap in Trust from
///      a gap they wrote themselves;
///   2. that a locally recorded skip reason writes its `assumption:` transport
///      row *before* the policy rules on it (see the `record, then rule`
///      ordering in `run_pass`) — strict used to abort without a row, so the
///      largest error class in the lane had no machine-readable inventory at
///      all. The row exists only under JSON transport output
///      (`-Ztrust-verify-output=json|both`, which targo always passes), and a
///      def the step-4 library lane NARROWED never gets one (that lane
///      promised a proof, not an assumption);
///   3. that the set is COUNTED per crate, so "can that set grow without
///      anyone noticing?" is answered by an artifact and not by a habit.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum SkipClass {
    /// Nothing can be STATED over the body: rustc's own inherited
    /// contract-checker closure (never a failure), or a body whose START is an
    /// `unreachable` terminator. The second is not thereby safe — entering it
    /// is undefined behaviour — which is why a fail-closed policy still
    /// refuses it unless the memory-safe demotion applies.
    NotASubject,
    /// The AUTHOR declared the gap, in the source, on the item:
    /// `#[trust::skip]` or `#[trust::assume_total]`. It is a PREMISE, not a
    /// Trust capability gap. It is greppable where it is written and it cannot
    /// enter the set without a diff — which is exactly the property an
    /// assumption set has to have.
    Declared,
    /// The TOOLCHAIN cannot model the construct. A PRODUCER defect — the same
    /// class the native-lowering lane already names in its own diagnostic as
    /// "not a finding about your code" — and the only one of the four whose
    /// count Trust itself can drive to zero.
    ToolchainGap,
    /// Cost policy put the body outside the selected scope (a dependency's
    /// MIR, an external crate). Non-fatal under the default policy; fatal only
    /// when dependency scope was explicitly requested.
    OutOfScope,
    /// Trust (CB4): code rustc's libtest harness SYNTHESIZED around the tests —
    /// a runner closure, the harness `main`. Not the author's code and not a
    /// Trust gap: it is excluded from the proof inventory, disclosed by one
    /// `excluded:test-harness-synthesized` row, and never an error.
    HarnessGlue,
}

impl SkipClass {
    /// Stable machine tag, for the census and `TRUST_COVERAGE_DEBUG`.
    const fn tag(self) -> &'static str {
        match self {
            Self::NotASubject => "not-a-subject",
            Self::Declared => "declared",
            Self::ToolchainGap => "toolchain-gap",
            Self::OutOfScope => "out-of-scope",
            Self::HarnessGlue => "harness-glue",
        }
    }

    /// The clause APPENDED to the existing diagnostic headline.
    ///
    /// The `Trust full verification skipped `{path}`` prefix is kept verbatim
    /// and byte-identical, so every pinned expectation still matches — the
    /// `//~ ERROR` annotations in `tests/ui/trust/` and the `.contains(...)`
    /// assertions in `tests/run-make/trust-assumption-rows/` are all substring
    /// matches on that prefix. This ADDS the attribution that was missing; it
    /// does not rename the error out from under its pins.
    const fn headline_suffix(self) -> &'static str {
        match self {
            Self::NotASubject => ": this body has no executable path to verify",
            Self::Declared => ": the source DECLARES this gap, and a declaration is not a proof",
            Self::ToolchainGap => ": Trust cannot model this function yet",
            Self::OutOfScope => ": the body is outside the selected verification scope",
            Self::HarnessGlue => ": rustc's libtest harness synthesized this body",
        }
    }

    /// WHO the error is about. This is the line the four-way collapse was
    /// hiding, and the reason a clean tree could report hundreds of "errors"
    /// with zero refutations behind them.
    const fn attribution(self) -> &'static str {
        match self {
            Self::NotASubject => {
                "ATTRIBUTION: this body's entry is an `unreachable` terminator (or it is \
                 compiler-generated contract machinery), so no obligation can be stated over \
                 it. That is NOT a proof that the body is never entered — entering it is \
                 undefined behaviour — so a fail-closed policy does not count it as verified"
            }
            Self::Declared => {
                "ATTRIBUTION: this is YOUR declaration, not a gap in Trust. A fail-closed \
                 policy (strict, certify, memory-safe) requires every in-scope function to be \
                 PROVED, and a declared premise is not a proof — so it refuses the skip. \
                 Removing the attribute does not make the function verified; it makes the real \
                 obligation visible"
            }
            Self::ToolchainGap => {
                "ATTRIBUTION: this is a PRODUCER defect — a gap in the Trust toolchain, not a \
                 finding about your code. Nothing here was proved false; a construct in this \
                 body (or the verification pipeline itself) has no model yet, so no obligation \
                 could be stated over it"
            }
            Self::OutOfScope => {
                "ATTRIBUTION: scope policy, not a property of this code. The body was never \
                 offered to the verifier"
            }
            Self::HarnessGlue => {
                "ATTRIBUTION: rustc's libtest harness generated this body around a test; the \
                 author never wrote it. It is excluded from the proof inventory (never proved) \
                 and every test function it calls is verified as its own body"
            }
        }
    }
}

/// Trust (skip taxonomy): the honest name for a skip reason.
///
/// Total and `const` ON PURPOSE: adding a `TrustVerifySkipReason` variant
/// without classifying it fails to compile, so the taxonomy cannot silently
/// acquire an unnamed member — the same fail-closed shape the rest of this file
/// uses for its policy matches.
const fn skip_class(reason: &TrustVerifySkipReason) -> SkipClass {
    match reason {
        TrustVerifySkipReason::ExternalDependencyScope | TrustVerifySkipReason::NonLocalMir => {
            SkipClass::OutOfScope
        }
        // Trust (merge 2026-10-14): `UninhabitedArgument` (2026-09-30) — a body no
        // value can enter — is not a subject either, and like the contract
        // closure it is never a failure (`skip_is_full_verification_failure`).
        TrustVerifySkipReason::ContractGeneratedClosure
        | TrustVerifySkipReason::UninhabitedArgument
        | TrustVerifySkipReason::UnreachableStart => SkipClass::NotASubject,
        TrustVerifySkipReason::TestHarnessSynthesized(_) => SkipClass::HarnessGlue,
        TrustVerifySkipReason::UserOptOut | TrustVerifySkipReason::AssumedTotal => {
            SkipClass::Declared
        }
        TrustVerifySkipReason::TreatedAsAssumption(_) => SkipClass::ToolchainGap,
    }
}

/// Trust (skip taxonomy): the ONE diagnostic a declined body gets.
///
/// The skip arm of `run_pass` used to be two independent `if`s — the step-4
/// library-lane abort, then the ordinary policy abort — and for a step-4
/// narrowed def under a fail-closed policy BOTH guards were true, so one body
/// emitted two `Trust full verification skipped` errors. Deciding the plan as a
/// single value makes "at most one error per declined body" a property of the
/// type, and lets a unit test drive every combination of the three inputs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SkipDiagnosticPlan {
    /// The body only inherits `#[trust::skip]`; its error is reported through
    /// the declaration and VERIFIED at the crate checkpoint
    /// (`trust_reconcile_inherited_skips`), which re-emits it if the
    /// declaration never reported.
    DeferredToDeclaration,
    /// The step-4 library lane narrowed this def and requires a proof.
    Step4ProofRequired,
    /// The selected policy does not permit this skip.
    PolicyRejected,
    /// A nonfatal lane: the skip is recorded, not refused.
    NoError,
}

/// Trust (skip taxonomy): pick the one diagnostic for a declined body. See
/// [`SkipDiagnosticPlan`].
fn skip_diagnostic_plan(
    inherited_from_declaration: bool,
    step4_demands_proof: bool,
    policy_aborts: bool,
) -> SkipDiagnosticPlan {
    if inherited_from_declaration {
        SkipDiagnosticPlan::DeferredToDeclaration
    } else if step4_demands_proof {
        SkipDiagnosticPlan::Step4ProofRequired
    } else if policy_aborts {
        SkipDiagnosticPlan::PolicyRejected
    } else {
        SkipDiagnosticPlan::NoError
    }
}

/// Trust (skip taxonomy, RECORD-THEN-RULE): what the skip seam writes for one
/// declined body, decided as a value BEFORE anything is written.
///
/// Split out of `run_pass` for the same reason as [`skip_diagnostic_plan`]: the
/// two rules this carries are each one conjunct in a boolean chain, and a
/// conjunct deleted from a chain fails no compiler run that does not happen to
/// take that lane. As a pure function, a unit test drives every input shape:
///
/// * a def the step-4 library lane NARROWED records NOTHING (wiring B: such a
///   def must never leave an assumption record where a proof was promised),
///   under every output mode and every policy;
/// * the machine row exists only under JSON transport output, and the error's
///   ledger claim ([`SkipRecordPlan::ledger_claim`]) is derived from that same
///   field, so no output mode can produce a claim without a row.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct SkipRecordPlan {
    /// Write the `assumption:<tag>` transport row (`TRUST_JSON`).
    machine_row: bool,
    /// Print the human `Trust: ASSUMPTION [...]` line. Only on a lane that does
    /// not also print an error: where the build fails, the ERROR is the human
    /// statement.
    human_note: bool,
}

impl SkipRecordPlan {
    /// The `assumption:<tag>` row the skip ERROR may state as written: exactly
    /// the row this plan writes, and nothing when it writes none.
    fn ledger_claim(self, tag: &'static str) -> Option<&'static str> {
        self.machine_row.then_some(tag)
    }
}

/// Trust (skip taxonomy): pick what the skip seam records. See
/// [`SkipRecordPlan`].
fn skip_record_plan(
    reason_is_recorded_assumption: bool,
    step4_demands_proof: bool,
    policy_aborts: bool,
    emit_json: bool,
    emit_human: bool,
) -> SkipRecordPlan {
    let records = reason_is_recorded_assumption && !step4_demands_proof;
    SkipRecordPlan {
        machine_row: records && emit_json,
        human_note: records && emit_human && !policy_aborts,
    }
}

/// Trust (skip census): per-crate counts of what the skip lane declined and
/// why, keyed by `(SkipClass::tag, skip_assumption_tag)`, plus the identity set
/// itself.
///
/// This is the ratchet anchor. A count alone can be argued with; an identity
/// SET can be diffed, and a set that grew names the function that joined it.
/// Written from the one skip seam in `run_pass`, so nothing can enter the set
/// without being counted here.
#[derive(Default)]
struct SessionSkipCensus {
    /// `(class tag, reason tag) -> count`.
    counts: std::collections::BTreeMap<(&'static str, &'static str), usize>,
    /// `class tag -> the exact function identities`, sorted by construction.
    identities: std::collections::BTreeMap<&'static str, std::collections::BTreeSet<String>>,
    /// `declaration identity -> how many nested bodies inherited its
    /// `#[trust::skip]``. Read back when the DECLARATION's own error is emitted,
    /// so the one error that is printed says how many bodies it speaks for.
    /// Closures are walked before their parent (measured), so this is populated
    /// by the time the parent emits; if a future walk order changes that, the
    /// inline note simply does not appear — it can never be wrong, only absent,
    /// because the AUTHORITATIVE account is recomputed at the crate checkpoint
    /// from `deferred_inherited` x `declared_skip_errors` (see
    /// `trust_reconcile_inherited_skips`), where no walk order is involved.
    inherited_by_origin: std::collections::BTreeMap<String, usize>,
    /// Every identity on which a `Trust full verification skipped` ERROR was
    /// actually emitted, written from the ONE emission seam
    /// (`emit_full_verification_skipped_at`). This is an OBSERVED fact about
    /// this compilation, not an implication about what `classify_def` should
    /// have decided — which is the whole point: the checkpoint reconciliation
    /// below can then verify the deduplication instead of trusting it.
    declared_skip_errors: std::collections::BTreeSet<String>,
    /// Every body whose own skip error was DEFERRED to an enclosing
    /// declaration, with everything needed to emit that error later if the
    /// declaration turns out not to have reported.
    deferred_inherited: Vec<DeferredInheritedSkip>,
}

/// Trust (skip taxonomy): one body whose `Trust full verification skipped`
/// error was withheld because an enclosing declaration carries the
/// `#[trust::skip]` it inherited.
///
/// The record exists so the withholding can be VERIFIED rather than reasoned
/// about. Round 1 argued that the declaration must also reach the pass, take
/// the same `UserOptOut` decision under the same policy, and emit the error
/// this one defers to. That is an implication over `classify_def`, walk
/// reachability and policy agreement — three things that can diverge. The
/// checkpoint reconciliation asserts the CONCLUSION directly instead, and
/// emits the deferred error itself when the premise did not hold, so an orphan
/// is fail-closed by construction.
#[derive(Clone)]
struct DeferredInheritedSkip {
    /// The suppressed body's own canonical identity.
    func_path: String,
    /// The declaration whose error this one was deferred to.
    origin: String,
    /// The suppressed body, so the checkpoint can point the recovered error at
    /// it. A `DefId` rather than a `Span` so nothing but plain data crosses
    /// the session-state boundary.
    def_id: DefId,
    /// Which skip verdict this was.
    class: SkipClass,
    /// The exact message this body's own error would have carried.
    reason: String,
    /// The `assumption:<tag>` row this body wrote before its error was
    /// deferred, when it wrote one (JSON transport output only), so a
    /// recovered error states only what was actually recorded.
    ledger_row: Option<&'static str>,
    /// Whether this body's OWN decision demanded an error. `false` is an
    /// advisory/nonfatal lane where nothing was suppressed because nothing was
    /// going to be printed; only a `true` entry carries a reconciliation
    /// obligation, so a green advisory build can never be reddened by this
    /// lane.
    demanded_error: bool,
}

/// Trust (skip census): record one declined body. Observability only — it reads
/// no policy and returns nothing, so it can never participate in a verdict.
fn record_skip_census(
    tcx: TyCtxt<'_>,
    func_path: &str,
    class: SkipClass,
    reason_tag: &'static str,
    inherited_from: Option<&str>,
) {
    tcx.sess.with_trust_compiler_state::<SessionSkipCensus, _>(|census| {
        *census.counts.entry((class.tag(), reason_tag)).or_insert(0) += 1;
        census.identities.entry(class.tag()).or_default().insert(func_path.to_owned());
        if let Some(origin) = inherited_from {
            *census.inherited_by_origin.entry(origin.to_owned()).or_insert(0) += 1;
        }
    });
}

/// Trust (skip taxonomy): how many nested bodies inherited this declaration's
/// `#[trust::skip]` and are therefore NOT reported separately. Observability
/// only: `0` (or an unpopulated census) yields no note and changes nothing.
fn inherited_skip_count(tcx: TyCtxt<'_>, declaration: &str) -> usize {
    tcx.sess.with_trust_compiler_state::<SessionSkipCensus, _>(|census| {
        census.inherited_by_origin.get(declaration).copied().unwrap_or(0)
    })
}

/// Trust (skip census): publish the crate's skip taxonomy once, at the end of
/// the completed walk.
///
/// Emitted as a compiler NOTE (never a warning, so `-Dwarnings` cannot promote
/// an observability line into a build failure, and `allow` cannot silence it),
/// and gated behind `TRUST_SKIP_CENSUS=1` so that turning it on by default is a
/// separate, blessable change to every `tests/ui/trust/` expectation rather
/// than a side effect of this one. The MACHINE-readable half of the same
/// inventory is the `assumption:` transport row each locally recorded skip
/// reason now writes in every policy (see `run_pass`) — under JSON transport
/// output (`-Ztrust-verify-output=json|both`, which targo always passes), and
/// never for a def the step-4 library lane narrowed. That is what targo
/// aggregates into `report.json`'s `assumptions[]`.
fn emit_skip_census(tcx: TyCtxt<'_>) {
    if !env_flag_enabled("TRUST_SKIP_CENSUS") {
        return;
    }
    let (counts, identities) =
        tcx.sess.with_trust_compiler_state::<SessionSkipCensus, _>(|census| {
            (census.counts.clone(), census.identities.clone())
        });
    if counts.is_empty() {
        return;
    }
    let total: usize = counts.values().sum();
    let mut lines = vec![format!("Trust skip census: {total} body/bodies were not verified")];
    for ((class, reason), n) in &counts {
        lines.push(format!("  {class} / {reason}: {n}"));
    }
    for (class, set) in &identities {
        for id in set {
            lines.push(format!("  [{class}] {id}"));
        }
    }
    tcx.dcx().note(lines.join("\n"));
}

impl<'tcx> crate::MirPass<'tcx> for TrustVerify {
    fn policy(&self, _ctx: &crate::PassCtx<'_>) -> crate::PassPolicy {
        // Trust: upstream 1.101's pass policy has no "required but
        // session-gated" shape (the old is_required + can_be_overridden +
        // is_enabled triple). Verification is part of the batteries-on
        // compiler contract and the sole supported bypass is the tracked
        // `-Ztrust-verify=off` option, so the policy is Required (never
        // suppressible by -Zmir-enable-passes or #[optimize(none)]) and
        // `run_pass` itself performs the session gate the old `is_enabled`
        // performed, returning without touching the body when off.
        crate::PassPolicy::Required
    }

    fn run_pass(&self, tcx: TyCtxt<'tcx>, body: &mut Body<'tcx>) {
        // Trust: the session gate (see `policy`). Targo deliberately compiles
        // the normal library linked by an integration-test target outside the
        // static proof roots. That unit still belongs to the authenticated
        // test session and must reach this final MIR pass so its certified
        // monitors can be installed. Keep native `--test -Ztrust-verify=off`
        // in the explicit vanilla lane: only Targo's nonce-bound marker can
        // activate monitor-only execution.
        let monitor_only = targo_certified_monitor_test_mode(tcx.sess);
        if !(verification_enabled(tcx.sess) || monitor_only) {
            return;
        }
        // Trust (2026-09-27): record which pointer width this compilation verifies for.
        // vcgen's bounded-source allocation grant is withheld off 64-bit, and the
        // bridge's `Vec<u8>` grow summary needs a witnessed 64-bit width
        // (`trust_types::target_pointer_bits`, which this setter writes).
        trust_vcgen::set_target_pointer_bits(tcx.data_layout.pointer_size().bits() as u32);
        // Trust (plan step 3.5, design §5.7): a Clean-origin body this pass builds (its callee
        // model, until item V) is charged to the reach counter's `verification` lane.
        let _clean_origin_reach = crate::clean_origin_ir::clean_origin_reach::within(
            crate::clean_origin_ir::clean_origin_reach::ReachLane::Verification,
        );
        // Opt-in diagnostic pairing borrows the real pre/post values in this
        // invocation. The inner closure preserves every existing early-return
        // decision while ensuring ordinary skipped paths also finish capture.
        // Trust (T3 L4, C06a): the elision audit's scope for this body's pass, opened before
        // anything the pass records (the scalar capture below records cap hits): what the
        // audit ledger attributes to it (the innermost scope, L4-SCOPE-2) becomes this
        // body's STOP, CERTIFY-STOP and CAP rows when the pass ends. Nothing when the audit
        // is off.
        let _audit_scope = elide_audit::BodyScope::enter(tcx, body.source.def_id());
        let scalar_capture = scalar_mir_capture::begin(tcx, body);
        // Trust (2026-09-25, E0391 on formatting impls that format each other or
        // themselves): an ITEM body's pass runs inside `optimized_mir(def_id)`
        // (`inner_optimized_mir` -> `run_optimization_passes`), for the WHOLE pass —
        // not only while its artifacts are collected. Publication
        // (`publish_body_verification_outcome`) runs after collection has returned and
        // forces OTHER bodies' verdicts: the formatting-sink bar asks
        // `trust_proof_results` of every user formatter this body's `format_args!`
        // packs, and that body's own publication asks the same of this one. With the
        // mark scoped to collection, `optimized_mir_query_would_cycle` answered `false`
        // for this body during its own publication and every guarded reader went on to
        // `optimized_mir(def_id)` — the query already on the stack. Measured:
        //
        //   optimized_mir(<A as Debug>::fmt) -> publish -> fmt_target_sink_basis(B)
        //     -> dyn_target_is_verified_panic_free -> trust_proof_results(<B as Debug>::fmt)
        //     -> optimized_mir(<B as Debug>::fmt) -> publish -> ... -> trust_proof_results(<A as Debug>::fmt)
        //     -> optimized_mir(<A as Debug>::fmt)                          (E0391)
        //   optimized_mir(<T as Debug>::fmt) -> publish -> error_opacity_note
        //     -> item_is_error_transparent(<T as Debug>::fmt) -> optimized_mir(<T as Debug>::fmt)  (E0391)
        //
        // Marking the def for the whole pass makes every guarded reader DECLINE the
        // re-entrant request (fail-closed: no credit for the cyclic edge) instead.
        // Sound in the strict sense: each newly-`true` answer names a def whose
        // `optimized_mir` IS on this stack, so the reader's alternative was an E0391
        // abort, never a verdict. Restricted to non-promoted `Item` bodies — the only
        // ones this pass runs on inside `optimized_mir` of the same def; a shim runs
        // inside `mir_shims`, and marking its def here would claim a query that is not
        // on the stack (its collection keeps marking it, as before).
        let _optimized_mir_in_progress_guard =
            (matches!(body.source.instance, ty::InstanceKind::Item(_))
                && body.source.promoted.is_none())
            .then(|| OptimizedMirInProgressGuard::enter(body.source.def_id()));
        let mut run_existing_pass = || {
            let mir_source = body.source;
            if dyn_probe_enabled() {
                let dp = trust_mir_extract::safe_def_path_str(tcx, mir_source.def_id());
                if dp.contains("use_widget") || dp.contains("rank") || dp.contains("main") {
                    let pol = TrustVerifyPolicy::from_session(tcx.sess);
                    eprintln!(
                        "TRUST_DYN_PROBE: run_pass {} enabled={} decision={:?}",
                        dp,
                        verification_enabled(tcx.sess),
                        verification_decision(tcx, body, &pol),
                    );
                }
            }
            trace!("Trust: run_pass entered for {:?}", mir_source.def_id());
            // Evaluator certification alone is not executable authority. Resolve
            // exact function/loop placement against this pristine optimized body
            // before any report bundle can stamp `monitored` or `measured`.
            preflight_certified_monitor_placement(tcx, body);
            if !verification_enabled(tcx.sess) {
                // Static verification/coverage/transport remains disabled for a
                // scoped-out Cargo unit. The authenticated Targo test marker is
                // a narrower execution channel: it installs only monitors whose
                // equivalence to the canonical proposition was kernel-certified.
                if targo_certified_monitor_test_mode(tcx.sess) {
                    inject_certified_test_monitors(tcx, body);
                }
                trace!(
                    "Trust: static verification disabled for {:?}; authenticated monitor-only pass complete",
                    mir_source.def_id()
                );
                return;
            }
            // Trust (assertion-grade coverage): count every COVERAGE-ELIGIBLE body that
            // reaches the pass with verification enabled as PROCESSED. The eligibility
            // scope is byte-identical to the eager walk's selection in
            // `trust_ensure_whole_crate_verification` (same predicate), so the crate
            // summary comparison is exact — a non-eligible body (ctor shim, synthetic
            // coroutine glue, promoted) can neither trip nor MASK a shortfall.
            //
            // Trust (2026-10-17): whether THIS call credited the body, kept for the
            // skip arm below. A credited body must publish exactly one function
            // envelope, because targo authenticates the processed identity set
            // against the envelope set as an exact set.
            let mut newly_credited = None;
            if mir_source.promoted.is_none()
                && let Some(local) = mir_source.def_id().as_local()
                && trust_coverage_eligible_body(tcx, local)
            {
                let inserted =
                    tcx.sess.with_trust_compiler_state::<SessionReportState, _>(|state| {
                        state.processed_bodies.insert(local)
                    });
                newly_credited = inserted.then_some(local);
            }

            // Reporting-role metadata is deliberately absent from this decision.
            // Every enabled local compilation reaches the verifier; only explicit
            // body properties and the tracked dependency-inclusion option may
            // classify individual MIR bodies below.

            let def_id = mir_source.def_id();
            let policy = TrustVerifyPolicy::from_session(tcx.sess);

            // Use the same canonical semantic identity as extraction, R1
            // attribution, and interprocedural summary routing.
            let func_path = trust_mir_extract::safe_def_path_str(tcx, def_id);

            match verification_decision(tcx, body, &policy) {
                TrustVerifyDecision::Verify => {}
                TrustVerifyDecision::Skip(reason) => {
                    // Trust: debug-gated per-function coverage attribution. Pure
                    // observability — emits one classifying line and never changes
                    // any verdict or control flow. Gated behind TRUST_COVERAGE_DEBUG.
                    // Trust (skip taxonomy): the honest name for this skip,
                    // decided once and used by the ledger, the census and the
                    // diagnostic so the three can never disagree.
                    let class = skip_class(&reason);
                    if trust_coverage_debug_enabled() {
                        eprintln!(
                            "TRUST_COVERAGE: {func_path} => skipped:{reason:?} class={}",
                            class.tag()
                        );
                    }
                    // Trust (2026-09-27): a classifier skip, like the lowering
                    // collapse, may stand only for its OWN body. The skipped body is
                    // never verified, so none of its calls is charged: on stage-1
                    // 436c9eb6d0 one safe `let _q = &raw const s.a;` (classified
                    // `AddressOfField`) beside `dep::deref_raw(p)` built rc=0 under
                    // memory-safe, and the binary read a dangling pointer (SIGSEGV),
                    // while the same body without the raw borrow was refused on the
                    // `deref_raw` charge. An `UnreachableStart` body executes nothing.
                    let skip_uncharged_edges =
                        if matches!(reason, TrustVerifySkipReason::TreatedAsAssumption(_))
                            && memory_safe_demotion_applies(tcx, body)
                        {
                            memory_safe_assumption_uncharged_edges(tcx, body)
                        } else {
                            Vec::new()
                        };
                    let memory_safe_gap = matches!(
                        reason,
                        TrustVerifySkipReason::TreatedAsAssumption(_)
                            | TrustVerifySkipReason::UnreachableStart
                    ) && memory_safe_demotion_applies(tcx, body);
                    // Trust (2026-09-30, residual L2 review): the demotion's one
                    // assumption row stands for this body's own panic-freedom, and a
                    // skipped body charges none of its calls; withheld where it would
                    // stand for more (`uncharged_callable::memory_safe_skip_withheld`).
                    // Asked beside `skip_uncharged_edges` (2026-09-27/30, main), not
                    // instead of it: each withholds on its own, and a body both
                    // withhold names both reasons. The L2 rule adds a DIRECT call to a
                    // LOCAL `requires`-carrying callee, which the edge rule's
                    // verified-local induction admits although no call is charged.
                    let memory_safe_withheld = memory_safe_gap
                        .then(|| uncharged_callable::memory_safe_skip_withheld(tcx, body))
                        .flatten();
                    let memory_safe_gap = memory_safe_gap
                        && skip_uncharged_edges.is_empty()
                        && memory_safe_withheld.is_none();
                    let memory_safe_demotion = policy.skip_aborts_build(&reason) && memory_safe_gap;
                    let aborts = policy.skip_aborts_build(&reason) && !memory_safe_gap;
                    // Trust (§5 step 4, wiring B — the crux): a def the library
                    // lane NARROWED must never leave an assumption record where a
                    // proof was promised. Its bucket's unsupported_is_failure()
                    // is the contract: a TreatedAsAssumption skip here becomes a
                    // RED count, so the ratchet's assumption_records_excluded
                    // attestation stays true. Without this, classify_def narrows
                    // the bucket but the skip handler never reads it.
                    //
                    // Trust (skip taxonomy, 2026-09-16) — DOUBLE-EMIT FIX: this
                    // arm used to fall THROUGH into the ordinary policy arm
                    // below, and for its only reachable reason
                    // (`TreatedAsAssumption` under a fail-closed policy) that
                    // arm's guard is also true — so one narrowed def emitted TWO
                    // errors for ONE body, in an error class whose COUNT is the
                    // thing being driven to zero. `skip_diagnostic_plan` makes
                    // the arms what they always read as: at most one diagnostic
                    // per declined body (pinned by its unit test).
                    let step4_demands_proof =
                        matches!(reason, TrustVerifySkipReason::TreatedAsAssumption(_))
                            && step4_lane_narrowed_def(tcx, def_id);
                    // Trust (skip taxonomy, 2026-09-16) — RECORD, THEN RULE.
                    //
                    // This write used to live in the `else` of the abort, i.e.
                    // the STRICT lane — the one whose whole purpose is to be
                    // believed — aborted WITHOUT writing a ledger row, and its
                    // own comment said so ("strict scope aborted above without a
                    // row"). Measured consequence on the aterm corpus: 219 of
                    // 569 errors were skips and NONE of them was enumerable
                    // afterwards; the question "what, exactly, is assumed rather
                    // than proved here?" had no answer that was a file. It also
                    // broke this pass's own stated invariant that a body credited
                    // in `processed_bodies` "must also emit exactly one function
                    // envelope" (see the no-artifacts arm below): a strict-skipped
                    // body was credited as processed and emitted none.
                    //
                    // SOUNDNESS — this cannot mute anything, in either direction:
                    //   * the row's outcome is `Skipped`, never `Proved`, and every
                    //     consumer counts it as non-proof;
                    //   * it is written only on paths that were ALREADY declining
                    //     the body, so it can never remove a proof obligation;
                    //   * where it is newly written the compilation is also
                    //     emitting an `ErrorGuaranteed` on the same body (or on
                    //     the declaration it inherited `#[trust::skip]` from), so
                    //     no red build can become green by gaining an inventory
                    //     row. None of the rows written here is one targo's
                    //     strict lane admits as conditional evidence
                    //     (`trust_types::assumption::strict_policy_publishes_assumption_row`).
                    // The human note stays on the nonfatal path alone: when the
                    // build is failing, the ERROR is the human channel, and a
                    // duplicate line would only add noise to stderr expectations.
                    //
                    // EXCEPT the step-4 narrowed def: the wiring-B contract above
                    // is that such a def never leaves an assumption record where a
                    // proof was promised, so it records nothing and its error
                    // stands alone.
                    //
                    // `ledger_row` is the tag of the row ACTUALLY written — `None`
                    // under human-only output, where no machine row is written —
                    // so the error below never claims a row that does not exist.
                    // Both rules are decided by `skip_record_plan`, a pure
                    // function whose unit tests pin them.
                    let output_mode = TrustOutputMode::parse(tcx.sess);
                    let record_plan = skip_record_plan(
                        skip_reason_is_recorded_assumption(&reason),
                        step4_demands_proof,
                        aborts,
                        output_mode.emit_json(),
                        output_mode.emit_human(),
                    );
                    record_skip_assumption(
                        tcx,
                        body,
                        &func_path,
                        &reason,
                        memory_safe_demotion,
                        record_plan,
                    );
                    // Trust (CB4): an excluded libtest harness body is not an
                    // assumption (the plan above wrote nothing for it); it
                    // leaves its own `excluded:` row — the body's one envelope
                    // under JSON output — and counts toward the crate's one
                    // human summary line.
                    if let TrustVerifySkipReason::TestHarnessSynthesized(exclusion) = &reason {
                        test_harness_exclusion::record_exclusion(tcx, &func_path, exclusion);
                    }
                    // Trust (2026-10-17, coverage identity): an uncallable body
                    // (`UninhabitedArgument`) was credited as processed above and is
                    // not a recorded assumption, so nothing else here publishes its
                    // envelope. With none, targo's exact-set authentication of the
                    // processed identities against the envelopes failed for every
                    // crate holding one: strict refused the run ("processed coverage
                    // identities did not exactly equal authenticated function
                    // envelopes"), advisory dropped the crate's coverage row and
                    // printed `Coverage: unknown`. MEASURED on the 2026-10-16
                    // candidate gate (trust 7f3690ed73): aterm-serde's seven
                    // `<Impossible<Ok, Error> as Serialize*>::end(self)` bodies
                    // (`match self.void {}`), 1466 eligible against 1459 envelopes.
                    // It publishes the envelope the lone-`unreachable` early-out
                    // publishes (`trust_note_coverage_early_out`), for the same
                    // reason: a body that can never be entered has zero obligations.
                    if let Some(local) = newly_credited
                        && skip_publishes_zero_obligation_envelope(&reason)
                    {
                        publish_zero_obligation_envelope(tcx, local, &func_path);
                    }
                    let ledger_row = record_plan.ledger_claim(skip_assumption_tag(&reason));
                    // Trust (skip taxonomy): a `UserOptOut` on a body that does
                    // not itself carry the attribute is a SECOND report of an
                    // enclosing declaration. Counted under its own census tag so
                    // "how many gaps" and "how many errors" stop being the same
                    // number.
                    let inherited_from = if matches!(reason, TrustVerifySkipReason::UserOptOut) {
                        trust_skip_attr_inherited_from(tcx, def_id)
                            .map(|origin| trust_mir_extract::safe_def_path_str(tcx, origin))
                    } else {
                        None
                    };
                    // Trust (skip census): count every declined body under its
                    // honest class, before the policy decides the diagnostic.
                    let census_tag = if inherited_from.is_some() {
                        "user-opt-out-inherited"
                    } else {
                        skip_assumption_tag(&reason)
                    };
                    record_skip_census(
                        tcx,
                        &func_path,
                        class,
                        census_tag,
                        inherited_from.as_deref(),
                    );
                    // Trust (skip taxonomy, 2026-09-16) — ONE ERROR PER
                    // DECLARATION, NOT PER MENTION.
                    //
                    // MEASURED: `targo trust check -p aterm-types` reported 219
                    // `Trust full verification skipped` errors — the largest
                    // single class of the crate's 569 — from 111 source
                    // annotations. 40 of the 219 are `{closure#N}` bodies that
                    // carry no attribute of their own: `item_has_trust_skip_attr`
                    // walks ancestors (correctly — a waiver full of holes is not a
                    // waiver), but the DIAGNOSTIC walked nothing, so a function
                    // with two closures in it billed the author three times for
                    // one line. On that corpus EVERY ONE of the 40 had its parent
                    // body separately reported: zero orphans.
                    //
                    // SOUNDNESS — why this is a deduplication and not a mute:
                    //   * the CENSUS ENTRY (and, under JSON transport output, the
                    //     ledger row) is written above, before this point. The
                    //     inventory of what is assumed rather than proved does not
                    //     shrink by one body; only the second printing of one gap
                    //     goes away.
                    //   * the guard in `trust_skip_attr_inherited_from` returns a
                    //     declaration only when it is LOCAL and FUNCTION-LIKE, so
                    //     that ancestor's own body reaches this same pass, takes
                    //     this same `UserOptOut` decision under this same policy,
                    //     and emits the error this one is deferring to. An
                    //     attribute on a `mod`, an `impl`, or an impl self-type
                    //     yields `None` and changes nothing.
                    //   * the two ways that ancestor body could still fail to
                    //     reach the pass are both already-safe: `tainted_by_errors`
                    //     means the compilation is failing anyway, and a
                    //     lone-`unreachable` parent means the parent can never run,
                    //     so neither can a closure defined inside it — the case
                    //     this file already credits as `VacuouslyUnreachable`.
                    //   * it cannot reach any other skip class: `inherited_from` is
                    //     `None` for everything except `UserOptOut`.
                    //
                    // ORDERING NOTE (measured, and the reason this is a STATIC
                    // implication rather than a "has the root already errored?"
                    // check): closures are walked BEFORE their parent — on the
                    // two-closure fixture the errors arrive `{closure#0}`,
                    // `{closure#1}`, then `parent` — so a seen-set guard would
                    // suppress nothing. The implication above needs no ordering.
                    //
                    // ROUND 2 — THE DEFERRAL IS NOW VERIFIED, NOT TRUSTED. The
                    // implication above ("that ancestor's own body reaches this
                    // same pass ... and emits the error this one is deferring
                    // to") quantifies over `classify_def`, walk reachability
                    // and policy agreement. Each is an argument, and an
                    // argument that fails silently here withholds a real
                    // finding from a build that then goes green. So the
                    // deferral is RECORDED, and
                    // `trust_reconcile_inherited_skips` checks at the crate
                    // checkpoint that the named declaration actually reported —
                    // emitting this body's own error there if it did not. The
                    // reasoning above is now a prediction the checkpoint tests,
                    // not a premise the build rests on.
                    let mut policy_reason =
                        format!("full verification policy rejected skip reason `{reason:?}`");
                    if !skip_uncharged_edges.is_empty() {
                        policy_reason.push_str(&format!(
                            "; memory-safe records a skipped body as an assumption only when it \
                             has no edge out of the verified closure (a call, a foreign static \
                             read, a function pointer or vtable it mints, drop glue, inline \
                             assembly), and this body has: {}; a skipped body charges none of \
                             them",
                            skip_uncharged_edges.join(", "),
                        ));
                    }
                    // Trust (2026-09-30): and say why memory-safe did not demote it.
                    if let Some(withheld) = &memory_safe_withheld {
                        policy_reason.push_str(withheld);
                    }
                    if let Some(origin) = inherited_from.as_deref() {
                        // TEST-ONLY FAULT INJECTION, and deliberately the
                        // ONLY knob this lane has. It rewrites the recorded
                        // ORIGIN to a name no declaration can ever carry,
                        // putting the census into exactly the state the judge's
                        // path produces: a body whose error was deferred to a
                        // declaration that did not report. It can only ever ADD
                        // an error (the reconciliation recovers the deferred
                        // one); it cannot remove, demote or silence anything,
                        // so it is not a mute button and cannot be misused as
                        // one. The declaration still emits its own error
                        // normally. See tests/ui/trust/skip_dedup_orphan_is_fail_closed.rs.
                        let origin = if env_flag_enabled("TRUST_SKIP_DEDUP_ORPHAN_FAULT") {
                            format!("{origin}::{{fault-injected-never-reported}}")
                        } else {
                            origin.to_owned()
                        };
                        // `inherited_from` is `Some` only for `UserOptOut` and
                        // `step4_demands_proof` only for `TreatedAsAssumption`,
                        // so the only error a deferral can withhold is the
                        // policy one.
                        let record = DeferredInheritedSkip {
                            func_path: func_path.clone(),
                            origin,
                            def_id,
                            class,
                            reason: policy_reason.clone(),
                            ledger_row,
                            demanded_error: aborts,
                        };
                        tcx.sess.with_trust_compiler_state::<SessionSkipCensus, _>(|census| {
                            census.deferred_inherited.push(record.clone());
                        });
                    }
                    match skip_diagnostic_plan(
                        inherited_from.is_some(),
                        step4_demands_proof,
                        aborts,
                    ) {
                        SkipDiagnosticPlan::DeferredToDeclaration => trace!(
                            "Trust: skip on {func_path} is inherited; the declaration is reported \
                             at its own body (verified at the crate checkpoint)"
                        ),
                        SkipDiagnosticPlan::Step4ProofRequired => abort_full_verification_skipped(
                            tcx,
                            body,
                            &func_path,
                            class,
                            None,
                            "the library verification lane requires a proof for this def; \
                         an assumption record is not a proof",
                        ),
                        SkipDiagnosticPlan::PolicyRejected => abort_full_verification_skipped(
                            tcx,
                            body,
                            &func_path,
                            class,
                            ledger_row,
                            &policy_reason,
                        ),
                        SkipDiagnosticPlan::NoError => {}
                    }
                    trace!("Trust: skipping {func_path}: {reason:?}");
                    // Runtime monitor evidence is independent of static-engine
                    // support. Advisory skip lanes still install every certified
                    // monitor in a Targo test session; only monitors on paths
                    // reached by the selected tests execute.
                    inject_certified_test_monitors(tcx, body);
                    return;
                }
            }
            debug!("Trust: verifying {func_path}");
            // Trust (CB4): a harness body whose shape check refused exclusion is
            // verified as ordinary code; human output says why, once, here.
            test_harness_exclusion::note_refusal(tcx, body, &func_path);
            // Trust (ty): `#[trust::terminating]` engages the temporal/typestate lane
            // — verify an enum-step transition function converges (no livelock).
            verify_terminating_attr(tcx, def_id, body);
            // Trust (trust-vc): `#[trust::must_consume]` engages the ownership lane —
            // verify an owned parameter is consumed (moved out) on every path.
            verify_must_consume_attr(tcx, def_id, body);
            // Trust (trust-cg): `#[trust::verified_codegen]` engages the verified
            // codegen lane — lower the function to trust-cg LIR, validate it, and
            // round-trip-check the lowering.
            verify_codegen_attr(tcx, def_id, body);
            let Some((cache_key, artifacts)) =
                collect_verification_artifacts_cached_after_decision(
                    tcx, body, &policy, &func_path,
                )
            else {
                // Trust: debug-gated coverage attribution for the no-artifacts case.
                // Pure observability; does not alter the fail-closed/return behavior.
                if trust_coverage_debug_enabled() {
                    eprintln!("TRUST_COVERAGE: {func_path} => pipeline-gap:no-artifacts");
                }
                // The pass already credited this body in `processed_bodies`, so it
                // must also emit exactly one function envelope. Treating a missing
                // artifact bundle as vacuous would manufacture proof credit; emit
                // the existing honest UNKNOWN gap row instead. This keeps the
                // terminal processed identity set exactly reconcilable in advisory
                // lanes, while strict policy still fails the compilation below.
                let gap_row = transport_native_verification_gap_row();
                audit_published_rows(tcx, def_id, &func_path, std::slice::from_ref(&gap_row));
                if TrustOutputMode::parse(tcx.sess).emit_json() {
                    emit_transport_json(tcx, def_id.as_local(), &func_path, &[gap_row], 0);
                }
                // Trust (2026-09-14): a preprocessing BUDGET overrun has already emitted
                // its LOCATED hard error carrying the fix options
                // (`preprocessing_budget_exceeded`, fail-closed lanes); a second, generic
                // "produced no artifacts" error on the same body says nothing new and buries
                // the one that names the remedy (ruling v7/D3). The exit code is already
                // non-zero. The budget thread-local cannot answer this here — its RAII guard
                // has been dropped with the collector — so the checkpoint RECORDS the body
                // and this site reads the record. Measured on
                // tests/ui/trust/verifier_budget_termination.rs (one error per body).
                let budget_already_refused = with_crate_verification_state(tcx.sess, |state| {
                    state.budget_aborted_defs.contains(&body.source.def_id())
                });
                if policy.fail_closed() && !budget_already_refused {
                    // Trust (skip taxonomy): a pipeline that produced nothing is
                    // a PRODUCER defect by construction — the decision above said
                    // VERIFY, so this body was in scope, was offered, and the
                    // toolchain came back empty. It is the same class as an
                    // incomplete lowering and must be attributed the same way.
                    // (The `budget_already_refused` guard immediately above is
                    // the pre-existing CASCADE rule for this site: a second,
                    // generic error on a body whose real refusal was already
                    // reported is not a second finding.)
                    abort_full_verification_skipped(
                        tcx,
                        body,
                        &func_path,
                        SkipClass::ToolchainGap,
                        // No `assumption:` row: this site writes only the
                        // `native-verification-gap` UNKNOWN row above.
                        None,
                        "the verification pipeline produced no artifacts",
                    );
                }
                // Preserve runtime checking in nonfatal no-artifact lanes. Strict
                // mode still fails the compilation after retaining this honest MIR.
                inject_certified_test_monitors(tcx, body);
                return;
            };
            // Trust (memory): this pass is the artifact's only FULL reader; shrink
            // its cache slot to the post-pass projection when the pass returns,
            // whichever way it returns (see `CachedArtifacts`). Declared after
            // `artifacts` so it drops first: the slot is compacted, then the pass's
            // own handle goes, and the full payload with it. PINNED by
            // tests/ui/trust/memory_notes_census.rs: its census counts the slots
            // compacted (0 if this guard is deleted) and those compacted after the
            // pass's handle was already gone (non-zero if it moves above the
            // `artifacts` binding).
            let _compact_after_pass = CompactArtifactsAfterPass { tcx, key: cache_key };
            // Trust (T3 L4, C09): the identity oracle's context of these artifacts, installed for
            // the rest of the pass (publication and the elision seam compare the keys the
            // collection sealed), and this body's `PARITY <fn> identity` row written when the
            // pass ends, whichever way it ends (`row_key::Installed::resume`).
            let _row_keys = row_key::Installed::resume(tcx, body.source.def_id(), &artifacts.ctx);
            debug!(
                "Trust: proof results for {func_path}: {} obligations ({} trusted, {} runtime-checked, {} failed, {} unknown, {} cached)",
                artifacts.proof_results.summary.total,
                artifacts.proof_results.summary.trusted,
                artifacts.proof_results.summary.runtime_checked,
                artifacts.proof_results.summary.failed,
                artifacts.proof_results.summary.unknown,
                artifacts.proof_results.summary.cached,
            );
            // Trust: debug-gated per-function coverage attribution. Classifies each
            // local function the pass analyzes as zero-obligation or analyzed:<n>.
            // Pure observability — emits one line, never changes a verdict. Gated
            // behind TRUST_COVERAGE_DEBUG.
            if trust_coverage_debug_enabled() {
                let total = artifacts.proof_results.summary.total;
                if total == 0 {
                    eprintln!("TRUST_COVERAGE: {func_path} => zero-obligation");
                } else {
                    eprintln!("TRUST_COVERAGE: {func_path} => analyzed:{total}");
                }
            }

            // Trust (item 10 phase 2): a body whose ensures-citation names a theorem
            // out of the DEFERRED island suffix cannot be adjudicated yet — the
            // declarations it cites are kernel-checked only after the program mint.
            // Quarantine its ENTIRE authority-dependent output (human verdict report,
            // transport envelope, strict abort, and the proof-authorized check
            // elision below); `finalize_pending_import_citations` publishes exactly
            // one outcome for it once the complete environment exists. The body was
            // already credited in `processed_bodies` above, so coverage accounting is
            // unchanged: this withholds the body's SOLE envelope rather than adding a
            // second, amending one.
            //
            // Runtime monitor injection still runs. A certified clause monitor is
            // executable evidence, not proof authority, and it needs `&mut Body`,
            // which no longer exists post-walk — dropping it here would silently lose
            // runtime checking for the affected body.
            if quarantine_pending_import_citation_body(tcx, body, &artifacts) {
                inject_certified_test_monitors(tcx, body);
                return;
            }

            publish_body_verification_outcome(tcx, body, &func_path, &artifacts, &policy);

            // Trust (P4): the bounded runtime-ledger seam. A proof that survives to
            // codegen is the product, so this runs wherever verification runs — there
            // is no opt-in. Only an Add/Sub/Mul overflow row carrying compiler-private
            // KernelCertified authority and a unique pristine VC-to-MIR-block origin
            // may lose its panic edge; every other check is retained.
            elide_kernel_certified_checks(tcx, body, artifacts.as_ref());

            // `rustc --test` / `targo test` is the compiler-selected runtime
            // evidence lane. Insert only equivalence-certified clause monitors,
            // after static verification so monitor calls cannot create or discharge
            // the proposition's own VCs.
            inject_certified_test_monitors(tcx, body);
        };
        run_existing_pass();
        if let Some(capture) = scalar_capture {
            capture.finish(tcx, body);
        }
    }

    fn is_mir_dump_enabled(&self) -> bool {
        // Honor the ordinary explicit `-Zdump-mir` selector. Verification can
        // elide proved assertions and insert certified monitors, so its exact
        // input/output bodies must be inspectable like every other mutating
        // pass. The pass manager writes these only when dumping is requested;
        // dump bytes themselves confer no refinement or proof authority.
        true
    }
}

/// Publish one body's verification outcome: human diagnostics, the single
/// transport envelope, and every strict-policy abort.
///
/// Freeze source-owned open-dispatch facts at the original publication
/// callpoint. Its refutation-ledger write must remain visible to later bodies
/// even when final-artifact proof reporting waits for module publication.
fn prepare_publication_dispatch<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &VerificationArtifacts,
) -> OpenDispatchRefutationWitnesses {
    let propagated_refutations = propagated_open_dispatch_refutations(tcx, body);
    let (mut witness_callees, virtual_witnesses) =
        adversarially_refutable_open_dispatch_callees(tcx, body);
    #[allow(rustc::potential_query_instability)]
    witness_callees.extend(propagated_refutations.keys().cloned());
    let adversarial_open_dispatch = OpenDispatchRefutationWitnesses::new(
        witness_callees,
        session_panic_freedom_fold_sites(tcx.sess, func_path).as_deref(),
    )
    .with_propagated(propagated_refutations)
    .with_virtual(virtual_witnesses);
    // Trust (OD-1, 2026-10-04, open shapes): remember which open dispatches this
    // body's rows were refuted on, so a still-generic caller can carry the
    // refutation to its own row for the call (`propagated_open_dispatch_refutation`).
    if body.source.promoted.is_none() && matches!(body.source.instance, ty::InstanceKind::Item(_)) {
        let refuted = refuted_open_dispatch_callees(&artifacts.results, &adversarial_open_dispatch);
        if !refuted.is_empty() {
            with_crate_verification_state(tcx.sess, |state| {
                state.open_dispatch_refuted_callees.insert(body.source.def_id(), refuted);
            });
        }
    }
    adversarial_open_dispatch
}

/// Factored out of [`TrustVerify::run_pass`] so the ordinary in-walk path and the
/// post-walk [`finalize_pending_import_citations`] path emit output from ONE
/// implementation. A body whose ensures-citation was deferred must not acquire a
/// different report shape than one adjudicated in-walk; two copies of this logic
/// would drift, and the drift would be invisible.
///
/// MIR-MUTATING consequences deliberately stay in `run_pass`
/// (`elide_kernel_certified_checks`, `inject_certified_test_monitors`): they need
/// `&mut Body`, which no longer exists once the walk is over.
fn publish_body_verification_outcome<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &Arc<VerificationArtifacts>,
    policy: &TrustVerifyPolicy,
) {
    // Trust: freeze the ACTUAL selected carrier's clock before dispatch or
    // policy helpers can demand other bodies and earn their genuine credit.
    let calculus_clock = calculus_pending::capture_publication_clock(tcx, artifacts);
    let errors_before_publish = calculus_pending::publication_errors::baseline(tcx);
    let mut dispatch = Some(prepare_publication_dispatch(tcx, body, func_path, artifacts));
    if calculus_pending::defer(
        tcx, body, func_path, artifacts, policy, &mut dispatch, errors_before_publish, calculus_clock,
    ) {
        return;
    }
    publish_final_body_verification_outcome(
        tcx, body, func_path, artifacts, policy,
        dispatch.as_ref().expect("a non-deferred publisher retains its prepared facts"),
        errors_before_publish,
    );
}

/// Frozen diagnostic DATA, never a certificate, proof grade or selected
/// policy outcome. A private live selector and the committed prepared record
/// determine which alternative may actually be emitted.
#[derive(serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct PreparedDiagnostic<S = rustc_span::Span> {
    aborting: bool,
    header: String,
    children: Vec<PreparedDiagnosticChild<S>>,
}

#[derive(serde::Serialize, serde::Deserialize)]
enum PreparedDiagnosticChild<S = rustc_span::Span> {
    Note(String),
    Help(String),
    SpanNote(S, String),
}

/// Actual source spans stay in process. Before spooling, a caller maps them
/// to checked slots in its private live span table; the stored DATA cannot
/// manufacture a source-map identity, proof authority or selected outcome.
struct PreparedLocatedDiagnostic {
    span: rustc_span::Span,
    diagnostic: PreparedDiagnostic,
}

struct PreparedLocatedNote {
    span: rustc_span::Span,
    report: PreparedHumanReport,
}

use calculus_pending::publication_output::PreparedAction;
use calculus_pending::publication_errors::OriginalErrorBaseline;

/// Output is the only interchangeable part of the sole original publisher.
/// Its predicates, queries, hypothesis consumption and semantic ledger writes
/// execute once in `run_body_publication`, before a compact carrier can be
/// released. DATA in an output sink cannot itself select a calculus verdict.
trait PublicationOutput {
    fn action(&mut self, tcx: TyCtxt<'_>, action: PreparedAction);

    fn original_errors_unchanged(&self, tcx: TyCtxt<'_>, baseline: &OriginalErrorBaseline) -> bool;

    fn level_zero_row_failure(
        &mut self,
        tcx: TyCtxt<'_>,
        span: rustc_span::Span,
        diagnostic: PreparedDiagnostic,
    ) {
        self.action(tcx, PreparedAction::LevelZeroRowFailure(PreparedLocatedDiagnostic {
            span, diagnostic,
        }));
    }

    fn header(&mut self, tcx: TyCtxt<'_>) {
        for line in prepare_report_header(tcx) { eprintln!("{line}"); }
    }

    fn original_rows(
        &mut self,
        _tcx: TyCtxt<'_>,
        _rows: &[TransportObligationResult],
        _tally: PublishedRowTally,
    ) {}

    fn results_report(
        &mut self,
        tcx: TyCtxt<'_>,
        span: rustc_span::Span,
        results: &[(VerificationCondition, VerificationResult)],
        bindings: &[Option<ResultObligationBinding>],
        authorities: &[Option<ResultProofAuthority>],
        certified: usize,
        published_rows: PublishedRowTally,
        conditional_on_coroutine_premise: bool,
    ) {
        if let Some(report) = prepare_results_report(
            tcx.sess, results, bindings, authorities, certified,
            published_rows, conditional_on_coroutine_premise,
        ) {
            self.action(tcx, PreparedAction::Note(PreparedLocatedNote { span, report }));
        }
    }

    fn full_failure(
        &mut self,
        tcx: TyCtxt<'_>,
        span: rustc_span::Span,
        failure: publication_failure::PreparedFullFailure,
    ) {
        self.action(tcx, PreparedAction::FullFailure { span, failure });
    }

    fn transport(
        &mut self,
        tcx: TyCtxt<'_>,
        def_id: Option<LocalDefId>,
        func_path: &str,
        rows: &[TransportObligationResult],
        cached: u32,
        modeled_facts: &[String],
        expanded_function_identity: Option<
            &trust_types::expanded_function_identity::ExpandedFunctionIdentity,
        >,
    ) {
        emit_transport_json_with_modeled_facts(
            tcx, def_id, func_path, rows, cached, modeled_facts, expanded_function_identity,
        );
    }
}

struct ImmediatePublication;

impl PublicationOutput for ImmediatePublication {
    fn action(&mut self, tcx: TyCtxt<'_>, action: PreparedAction) {
        match action {
            PreparedAction::Diagnostic(diagnostic) | PreparedAction::LevelZeroRowFailure(diagnostic) => {
                diagnostic.emit(tcx)
            }
            PreparedAction::FullFailure { span, failure } => failure.into_original().emit(tcx, span),
            PreparedAction::Note(note) => note.emit(tcx),
            PreparedAction::Stderr(line) => eprintln!("{line}"),
        }
    }

    fn original_errors_unchanged(&self, tcx: TyCtxt<'_>, baseline: &OriginalErrorBaseline) -> bool {
        calculus_pending::publication_errors::unchanged(tcx, baseline)
    }
}

impl PreparedLocatedNote {
    fn emit(self, tcx: TyCtxt<'_>) {
        emit_prepared_human_report(tcx, self.span, self.report);
    }
}

impl PreparedLocatedDiagnostic {
    fn emit(self, tcx: TyCtxt<'_>) {
        self.diagnostic.emit(tcx, self.span);
    }
}

impl PreparedDiagnostic<rustc_span::Span> {
    fn emit(self, tcx: TyCtxt<'_>, span: rustc_span::Span) {
        if self.aborting {
            let mut diag = tcx.dcx().struct_span_err(span, self.header);
            for child in self.children {
                match child {
                    PreparedDiagnosticChild::Note(note) => { diag.note(note); }
                    PreparedDiagnosticChild::Help(help) => { diag.help(help); }
                    PreparedDiagnosticChild::SpanNote(span, note) => { diag.span_note(span, note); }
                }
            }
            diag.emit();
        } else {
            let mut diag = tcx.dcx().struct_span_warn(span, self.header);
            for child in self.children {
                match child {
                    PreparedDiagnosticChild::Note(note) => { diag.note(note); }
                    PreparedDiagnosticChild::Help(help) => { diag.help(help); }
                    PreparedDiagnosticChild::SpanNote(span, note) => { diag.span_note(span, note); }
                }
            }
            diag.emit();
        }
    }
}

/// One invocation-scoped view of the complete policy composition. The
/// callback may stream its bulk data into owned storage without cloning it.
/// These references cannot be retained in session state; source-dependent
/// charges and ledger writes run in their original order before this view.
struct PreparedBodyPolicy<'a> {
    published_rows: &'a [TransportObligationResult],
    effective_rows: &'a [TransportObligationResult],
    published_row_tally: PublishedRowTally,
    strict: bool,
    memory_safe: bool,
    conditional_on_coroutine_premise: bool,
    coroutine_protocol_rows: &'a Option<CoroutineProtocolDisposition>,
    global_alloc_dealloc_rows: &'a Option<GlobalAllocDeallocDisposition>,
    entry_termination_rows: &'a Option<Vec<TransportObligationResult>>,
    termination_unmeasured_charge: &'a Option<termination_unmeasured::TerminationUnmeasuredCharge>,
    safety_comment_charge: &'a Option<safety_comment_assumption::SafetyCommentCharge>,
    instance_hypothesis_charge: &'a Option<instance_hypothesis::InstanceHypothesisCharge>,
    zero_obligation_vacuously_clean: Option<bool>,
}

fn with_body_publication_policy<'tcx, R>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &Arc<VerificationArtifacts>,
    policy: &TrustVerifyPolicy,
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
    consume: impl FnOnce(PreparedBodyPolicy<'_>) -> R,
) -> R {
    // Compute the policy-visible rows once, independently of rendering.
    // They are both the JSON payload and the compiler's memory-safe fatality
    // boundary; tying enforcement to `emit_json()` would let a human-output
    // invocation bypass a failure that Targo correctly rejects.
    //
    // Trust (D2, part C): this block is computed BEFORE human reporting on
    // purpose. `report_results` renders its denominator from the VC-level
    // `artifacts.results`, which does NOT contain the additive policy rows
    // minted here — so the human line used to read "… out of 2 obligation(s)"
    // for the very body whose JSON said `skipped: 1, total: 3`. A summary that
    // silently drops a skipped row is how the D2 false PROVE stayed invisible;
    // the count is now handed to the renderer. Nothing here emits a
    // diagnostic, so hoisting it leaves stderr ORDER byte-identical.
    //
    // Trust (2026-10-02, diag-vs-report): FIRST, every Level-0 refutation the
    // compiler's own Level-0 summary counts (`l0_refutation_class`) is stamped
    // onto its row, so the base every later rewrite starts from already says
    // `failed` where the summary line says failed. Before this the line said
    // "1 failed" and the row `runtime_checked` for `impl<T: Clone> Clone for
    // Wrap<T>` (stage-1 `b0b9258cc9`), and targo's advisory gate counted the row.
    // Only the PUBLISHED copy changes; `artifacts.transport_results` is untouched,
    // so the strict/certify Level-0 abort (which counts the summary) and
    // `abort_on_full_verification_failure` do not move. The memory-safe gates DO
    // read these rows (`memory_safe_artifacts_have_non_demotable_failure` over
    // `effective_rows`, and `native_lowering_collapse_keeps_row`, which keeps a
    // `failed` row): a stamped row is never folded into `assumption:native-lowering`
    // and is never an authenticated assumption, so a memory-safe body whose
    // lowering collapsed can exit 1 where it exited 0. That is the stricter
    // direction only (not reproduced on any probe; see DECISION_QUEUE "L0
    // refutation rows").
    //
    // Trust (OD-1 phase 0, 2026-10-04): the witness set also judges the
    // whole-function panic-freedom FOLD per site, not on its representative —
    // see `OpenDispatchRefutationWitnesses`.
    // Trust (OD-1, 2026-10-04, open shapes): plus the still-generic calls that carry a
    // callee's open-dispatch refutation (`propagated_open_dispatch_refutations`).
    let l0_refuted_rows = rows_with_l0_refutations(
        &artifacts.results,
        &artifacts.transport_results,
        adversarial_open_dispatch,
    );
    let base_rows: &[TransportObligationResult] =
        l0_refuted_rows.as_deref().unwrap_or(&artifacts.transport_results);
    let demoted_rows = (artifacts.proof_results.summary.total != 0)
        .then(|| {
            demote_transport_rows_for_default_lane(
                tcx,
                body,
                &policy,
                artifacts.as_ref(),
                base_rows,
            )
        })
        .flatten();
    let rows_after_demotion = demoted_rows.as_deref().unwrap_or(base_rows);
    let contract_rows = rewrite_contract_panic_transport_rows(&policy, rows_after_demotion);
    let rows_before_coroutine_assumption = contract_rows.as_deref().unwrap_or(rows_after_demotion);
    // The fail-closed lanes, needed BEFORE the disposition: publishing a
    // coroutine contract row is an explicit-advisory-only capability (see
    // `coroutine_protocol_publish_decision`).
    let strict = policy.fail_closed();
    let memory_safe = memory_safe_demotion_applies(tcx, body);
    // Coroutine resume bodies remain fully analyzed: their real arithmetic,
    // bounds, and panic obligations must never disappear behind a whole-body
    // skip. The three compiler-inserted ResumedAfter* sentinels are instead
    // an executor-protocol boundary. Every lane publishes that boundary as
    // exactly one authenticated assumption row, additive to every real
    // verdict. Explicit advisory lanes may continue conditionally; strict
    // and memory-safe lanes reject the premise after preserving all result
    // rows and diagnostics, so a zero-data-obligation coroutine can never
    // manufacture `no_obligations` proof credit over a hidden Assume.
    let coroutine_protocol_rows = coroutine_protocol_disposition(
        tcx,
        body,
        rows_before_coroutine_assumption,
        artifacts.as_ref(),
        &func_path,
        policy.is_explicit_advisory(),
    );
    let effective_rows = match &coroutine_protocol_rows {
        Some(
            CoroutineProtocolDisposition::ContractPublished(rows)
            | CoroutineProtocolDisposition::UnprovedAssumption(rows),
        ) => rows.as_slice(),
        None => rows_before_coroutine_assumption,
    };
    // §5 STEP 5 (`GlobalAlloc::dealloc` caller contract): charge every
    // allocation-owning drop in this body. Computed compiler-side from the
    // optimized MIR (never from row text), AFTER the coroutine disposition so
    // both additive policy rows compose; `None` when nothing here relied on
    // dealloc panic-freedom. See `global_alloc_dealloc_disposition`.
    let global_alloc_dealloc_rows = global_alloc_dealloc_disposition(tcx, body, effective_rows);
    let effective_rows = match &global_alloc_dealloc_rows {
        Some(
            GlobalAllocDeallocDisposition::DischargedVacuouslyForGlobal(rows)
            | GlobalAllocDeallocDisposition::RefusedUserAllocator(rows)
            | GlobalAllocDeallocDisposition::RefusedAllocErrorHook(rows),
        ) => rows.as_slice(),
        None => effective_rows,
    };
    // Trust (D2, part C): the additive policy rows the VC-level renderer cannot
    // see. `saturating_sub` because the disposition also STRIPS any stale row
    // claiming a published kind, so the delta is not unconditionally positive.
    // Trust (2026-09-16, refuted): `main`'s RETURN VALUE is dispatched by std —
    // `lang_start` calls `<T as Termination>::report`, which runs the value's
    // `Debug` (on `Err`) and its `Drop` — through no terminator in any local
    // body, so neither the fold mask nor any obligation row saw it. Measured:
    // `fn main() -> Result<(), dep::Bomb>` built exit 0 with only the tolerated
    // print row ("can dispatch into no user code") and panicked in the
    // verify-off dependency's `Debug`, then `Drop`. Policy B: the dispatch is a
    // REPORTED gap — a panic there is a defined abort during error reporting —
    // published as its own honest runtime-checked row (never folded under the
    // print row), CONDITIONAL at targo, fatal under `certify`.
    let entry_termination_rows = entry_termination_dispatch_rows(tcx, body, effective_rows);
    let effective_rows = entry_termination_rows.as_deref().unwrap_or(effective_rows);
    // Trust (D9, ruled 2026-09-27): every direct self call of a function for
    // which vcgen's recursion lanes made no termination statement is charged as
    // an `assumption:termination-unmeasured` row — computed from the MIR's
    // `DefId`-resolved calls and the VC-level results, never from row text.
    // Added BEFORE `additional_policy_rows` so the human line counts it.
    let termination_unmeasured_charge = termination_unmeasured::termination_unmeasured_charge(
        tcx,
        body,
        func_path,
        artifacts.as_ref(),
    );
    let termination_unmeasured_rows = termination_unmeasured::rows_with_termination_unmeasured(
        effective_rows,
        termination_unmeasured_charge.as_ref(),
    );
    let effective_rows = termination_unmeasured_rows.as_deref().unwrap_or(effective_rows);
    // Trust (SAFETY-ASSUME-1, ruled 2026-10-17): one `assumption:safety-comment` row
    // per user `unsafe { }` block whose clippy-placed `// SAFETY:` comment declared
    // it and that LOST an unmodeled unsafe-operation row to that declaration at
    // generation (`safety_comment_assumption`). Read from the session ledger the
    // collection wrote, never from row text; any stale row claiming the kind is
    // stripped. Added BEFORE `additional_policy_rows` so the human line counts it.
    let safety_comment_charge =
        safety_comment_assumption::safety_comment_charge(tcx, body, func_path);
    let safety_comment_rows = safety_comment_assumption::rows_with_safety_comment_assumptions(
        effective_rows,
        safety_comment_charge.as_ref(),
    );
    let effective_rows = safety_comment_rows.as_deref().unwrap_or(effective_rows);
    // Trust (OD-1 phase 1, ruled 2026-10-03): one `assumption:instance-hypothesis`
    // row per admitted open generic dispatch site of this body (and per site it
    // inherits from a hypothesis-carrying callee it calls at still-generic
    // arguments), the crate's one inventory-incomplete row the first time, and one
    // discharge row per (site, concrete instance) this body names. Computed from the
    // session ledger written at bundle construction and from the MIR's fn-item
    // mentions, never from row text; any stale row claiming these kinds is stripped.
    // Added BEFORE `additional_policy_rows` so the human line counts it. These rows
    // are minted OUTSIDE the panic-freedom fold: an admitted site is no fold site.
    let instance_hypothesis_charge =
        instance_hypothesis::instance_hypothesis_charge(tcx, body, func_path);
    let instance_hypothesis_rows = instance_hypothesis::rows_with_instance_hypotheses(
        effective_rows,
        instance_hypothesis_charge.as_ref(),
    );
    let effective_rows = instance_hypothesis_rows.as_deref().unwrap_or(effective_rows);
    // Trust (2026-09-29): one `runtime_checked` row per bundled std member the
    // native bundle's Assert gate KEPT under the runtime-checked disposition
    // (`runtime_checked_std_member`). Computed from the compiler-private artifacts
    // field, never from row text; any stale row claiming the kind is stripped.
    // Added BEFORE `additional_policy_rows` so the human line counts it.
    let std_member_row_location = (!artifacts.runtime_checked_std_members.is_empty())
        .then(|| source_span_from_rustc_span(tcx, body.span));
    let runtime_checked_std_member_rows =
        runtime_checked_std_member::rows_with_runtime_checked_std_members(
            effective_rows,
            std_member_row_location.clone(),
            &artifacts.runtime_checked_std_members,
        );
    let effective_rows = runtime_checked_std_member_rows.as_deref().unwrap_or(effective_rows);
    if !artifacts.runtime_checked_std_members.is_empty() {
        // The verdict is withheld from L0: the same flag the discarded-bundle
        // tolerance set, so R1's scan-gap warning keeps its trigger.
        with_crate_verification_state(tcx.sess, |state| state.l0_verdict_withheld = true);
    }
    // Trust (2026-09-27): a failed native lowering is a coverage gap in EVERY lane,
    // not only under the memory-safe demotion (which publishes its own collapse or
    // gap row above). Measured on stage-1 436c9eb6d0 with `fn f(v: &Vec<u32>, i:
    // usize, k: u8) -> u32 { if i < v.len() { v[i] ^ (k as u32 + 1) } else { 0 } }`:
    // advisory printed "1 proved … out of 1" and published `proved: 1, total: 1`
    // with `functions_verified: 1`, and strict published the SAME JSON beside its
    // "native typed-TrustIr lowering did not complete" build error. The one
    // exception is the R1 per-mono suppression — since 2026-09-29 the only path on
    // which the strict gate accepts a discarded bundle — where the function's proof
    // is the per-monomorphization one, so the transport publishes no row for it.
    //
    // The same holds for a CLOSURE-DRIVING consumer call that runs foreign code
    // (`uncharged_foreign_closure_consumer_edges`): nothing the native lane counted
    // charges it, so the transport says so instead of publishing the VC rows alone.
    let uncharged_consumer_edges =
        uncharged_foreign_closure_consumer_edges(tcx, body, func_path, artifacts);
    // Trust (2026-10-25, GLR-1): and so does a call the indirect-call gate refuses —
    // a fn-pointer value, an unresolved callable type argument — which no row charged
    // at all, so the advisory lane said nothing (`unresolved_indirect_call_gap_row`).
    let unresolved_indirect_call_row = unresolved_indirect_call_gap_row(tcx, body);
    let lowering_gap_rows = (artifacts.proof_results.summary.total != 0)
        .then(|| {
            unaccounted_gap_rows(
                artifacts,
                effective_rows,
                &uncharged_consumer_edges,
                unresolved_indirect_call_row.as_ref(),
            )
        })
        .flatten();
    let effective_rows = lowering_gap_rows.as_deref().unwrap_or(effective_rows);
    // Trust #542 / FALSE PROOF #11: the rows the JSON transport publishes for a body
    // with ZERO obligations. Computed HERE, before human reporting, so the human
    // surface and the JSON count the SAME rows (2026-09-30, below); nothing here
    // emits anything, so stderr order is unchanged.
    //
    // A VERIFIED function with ZERO panic obligations (it reached here only after the
    // Verify decision + successful native lowering + artifact collection -- a lowering
    // failure aborts earlier) is trivially panic-free. Emit a synthetic
    // `no_obligations` proved evidence row so the per-function transport is COMPLETE
    // (every analyzed fn has a row) and an all-0-obligation crate reports VERIFIED
    // instead of tripping targo-trust's "no per-function TRUST_JSON transport rows"
    // guard. SOUND: this path is never reached for a SKIPPED function, so it cannot
    // mark an unverified function as proved.
    //
    // Trust (2026-10-03): EVERY zero-obligation body takes this branch. It used to be
    // guarded by "no coroutine disposition and no global-alloc disposition" (so their
    // rows reached the JSON), which diverted a charged body to `effective_rows` and
    // dropped the honest gap row it owed; and it never read the entry-`Termination`
    // row, which it dropped in favour of the synthetic proved `no_obligations` row.
    // A body any of the three dispositions charged now publishes its composed rows
    // with the gap row in front when owed (`zero_obligation_disposition`).
    let charged_by_disposition = coroutine_protocol_rows.is_some()
        || global_alloc_dealloc_rows.is_some()
        || entry_termination_rows.is_some();
    // Trust (2026-10-10, ZERO-ROW-GATE): computed ONCE, here, and read by both the
    // row selection below and the strict/certify/memory-safe gates further down
    // (`zero_obligation_native_vacuously_clean`'s doc). `None` for a body with
    // bridged obligations, which neither consumer asks about.
    let zero_obligation_vacuously_clean = (artifacts.proof_results.summary.total == 0).then(|| {
        let hypotheses_published_exactly = instance_hypothesis_charge
            .as_ref()
            .is_some_and(instance_hypothesis::InstanceHypothesisCharge::hypotheses_are_exact);
        zero_obligation_native_vacuously_clean(
            tcx.sess,
            zero_obligation_source_owner(body.source),
            artifacts,
            uncharged_consumer_edges.is_empty(),
            unresolved_indirect_call_row.is_none(),
            hypotheses_published_exactly,
        )
    });
    let zero_obligation_rows = zero_obligation_vacuously_clean.map(|native_vacuously_clean| {
        // FALSE PROOF #11 (transport half). "Zero obligations" means no
        // question was ASKED, which is not the same as "the answer is yes".
        // The registry gate
        // (`zero_obligation_run_establishes_unconditional_panic_freedom`)
        // has already refused to call this function panic-free because it
        // makes a `Terminator::Call` that no authenticated registry
        // discharges; publishing `no_obligations` ("function has no panic
        // obligations (trivially panic-free)", outcome `proved`, solver
        // `trust-structural`) for the SAME function would let the transport
        // contradict the registry — and that affirmative mint is exactly
        // what `targo trust check` printed as `[NO OBLIGATIONS]` for
        // `fn f(a: u64) -> u64 { leaf(a, 0) }` with a divide-by-zero `leaf`.
        //
        // Publish the honest gap row instead. Fail-closed and one-directional:
        // it can only turn a vacuous green into a visible gap, never the
        // reverse. An ABSENT record leaves this branch byte-identical to
        // before, so no lane that never computes the fact is penalised.
        // Trust (OD-1 phase 1): calls that are ONLY this body's admitted
        // instance-hypothesis sites are accounted for by its hypothesis rows
        // (`zero_obligation_calls_only_hypotheses`); the gap row is not owed for
        // them, and the `no_obligations` row is withheld below.
        // The exemption also requires the hypothesis rows this body publishes to be
        // in their exact compiler shape (`hypotheses_are_exact`): only those
        // account for the calls. All of this is `zero_obligation_native_vacuously_
        // clean`, evaluated once above (`native_vacuously_clean` here).
        //
        // Exactly one of: the synthetic `no_obligations` row, the honest
        // `native-verification-gap` row (a native lowering/dispatch failure
        // can leave the legacy summary and display rows empty; that is not a
        // vacuous proof, so an unproved row is published before strict mode
        // aborts), or the transport rows. Trust (D9, critique H3): a
        // `termination-unmeasured` charge is APPENDED to that row set rather
        // than diverting the body to the `effective_rows` branch below, which
        // would drop the gap row (an Unknown) and publish a weaker result.
        //
        // Trust (2026-09-29): the same rule for a runtime-checked std member —
        // its rows are APPENDED to the base, and the proved `no_obligations`
        // row is never minted beside them (`runtime_checked_std_member::
        // zero_obligation_rows`); the D9 charge is appended after both.
        //
        // Trust (2026-10-03): the same rule for the coroutine premise, the
        // global-alloc contract and the policy-B entry-`Termination` row. Their rows,
        // the D9 charge and the std-member rows are already composed into
        // `effective_rows`; the gap row leads them when this branch owes it, and the
        // proved `no_obligations` row is never minted beside them. MEASURED on
        // stage-1 `6011b74bad`: `fn main() -> Result<(), Box<dyn Error>> { Ok(()) }`
        // published `[no_obligations: proved]` with `functions_verified: 1` and no
        // entry row, and the rlib `o.unwrap_or_else(AssertUnwindSafe(Instant::now))`
        // published the skipped premise row without the gap row it owed.
        if charged_by_disposition {
            zero_obligation_disposition::rows_over_charged_dispositions(
                native_vacuously_clean,
                base_rows,
                effective_rows,
            )
        } else if artifacts.runtime_checked_std_members.is_empty() {
            termination_unmeasured::zero_obligation_rows(
                native_vacuously_clean,
                base_rows,
                termination_unmeasured_charge.as_ref(),
            )
        } else {
            let base = runtime_checked_std_member::zero_obligation_rows(
                native_vacuously_clean,
                base_rows,
                std_member_row_location.clone(),
                &artifacts.runtime_checked_std_members,
            );
            termination_unmeasured::rows_with_termination_unmeasured(
                &base,
                termination_unmeasured_charge.as_ref(),
            )
            .unwrap_or(base)
        }
    });
    // Trust (OD-1 phase 1): the instance-hypothesis rows join the zero-obligation
    // rows too (idempotent over `effective_rows`, which already holds them). A body
    // that carries a hypothesis never publishes the proved `no_obligations` row: its
    // claim is relative to the hypothesis, not "trivially panic-free".
    let zero_obligation_rows = zero_obligation_rows.map(|rows| match &instance_hypothesis_charge {
        Some(charge) => {
            let rows: Vec<TransportObligationResult> = if charge.has_hypotheses() {
                rows.into_iter().filter(|row| row.kind != "no_obligations").collect()
            } else {
                rows
            };
            instance_hypothesis::rows_with_instance_hypotheses(&rows, Some(charge)).unwrap_or(rows)
        }
        None => rows,
    });
    // Trust (2026-10-09, review round 85): a body whose rows an argument premise
    // REMOVED (D14 keeps its marker at zero rows) is not "trivially panic-free": it
    // is panic-free UNDER the premise. `no_obligations` published it to the
    // authenticated `targo trust` lane as a complete verification with no trace of
    // the premise, so it publishes an unproved premise row instead.
    // Trust (merge 2026-10-14): ported onto the composed zero-obligation rows. The
    // proved `no_obligations` row is withheld and the unproved premise row is
    // APPENDED; every other row the composition owes (the gap row, a charge, a
    // hypothesis or std-member row) is kept, which is at least as conservative as
    // the pre-merge "premise row only" publication.
    let zero_obligation_rows = zero_obligation_rows.map(|rows| {
        let premises = argument_premise::premises_for(tcx.sess, body.source.def_id());
        if premises.is_empty() {
            return rows;
        }
        let mut rows: Vec<TransportObligationResult> =
            rows.into_iter().filter(|row| row.kind != "no_obligations").collect();
        rows.push(transport_argument_premise_row(&premises));
        rows
    });
    // Trust (SAFETY-ASSUME-1): the safety-comment charge joins the zero-obligation
    // rows too (idempotent over the branches that already composed it), and a body
    // that carries one never publishes the proved `no_obligations` row: a body whose
    // only unsafe operation is assumed on its comment is not "trivially panic-free".
    let zero_obligation_rows = zero_obligation_rows.map(|rows| {
        safety_comment_assumption::zero_obligation_rows(rows, safety_comment_charge.as_ref())
    });
    // Trust (assumption ledger, W2.1 + W3.5/W3.6; T9 contract-panic): every other
    // body publishes `effective_rows` — the memory-safe ledger rewrite and the
    // advisory contract-panic reclassification have already composed into it above,
    // and strict enforcement keeps the original rows byte-identical.
    let published_rows: &[TransportObligationResult] =
        zero_obligation_rows.as_deref().unwrap_or(effective_rows);
    // Trust (2026-09-25): a failed native lowering under memory-safe changes the
    // NUMBER of rows — the collapse drops every row it cannot keep and mints one
    // `assumption:native-lowering` row, and a refused collapse appends one
    // `native-verification-gap` row — and neither has a VC counterpart, so no
    // delta over the VC-level results reconciles with the JSON. Measured before
    // this: `g` (admitted on the collapse) printed "1 proved, 0 failed, 0 unknown,
    // 0 timed out, 0 runtime-checked out of 1 obligation(s)" while its JSON said
    // `proved: 1, unknown: 1, skipped: 1, total: 2`; `stop` printed "… 1 unknown …
    // out of 1" for a JSON row that is the skipped collapse row. Then the line
    // counts the rows the JSON publishes (`effective_rows`, the
    // `emit_transport_json_with_modeled_facts` input on this path).
    //
    // Trust (2026-09-30): and so does EVERY body, not only these. The line used to
    // count the VC-level results and add the policy rows minted after them as
    // "skipped" whatever their outcome, so it disagreed with the JSON wherever a
    // policy row was not a skip or a row was rewritten. MEASURED on stage-1
    // `f2e5ebbc0f`: `std::env::args().count()` printed "1 runtime-checked, 2
    // skipped out of 3" in every lane while its JSON said `runtime_checked: 3,
    // skipped: 0` (the two runtime-checked std-member rows), and under memory-safe
    // `v[i]`, `a / b` and `assert!(x != 7)` printed "1 failed" for a row the JSON
    // publishes as a skipped `assumption:memory-safe-panic`. Both surfaces now
    // count `published_rows` through ONE tally (`PublishedRowTally::of`).
    let published_rows_cause =
        if effective_rows.iter().any(transport_row_is_authenticated_native_lowering_assumption) {
            Some(PublishedRowsCause::NativeLoweringCollapse)
        } else if demoted_rows
            .as_deref()
            .is_some_and(|rows| rows.iter().any(|row| row.kind == NATIVE_VERIFICATION_GAP_ROW_KIND))
        {
            Some(PublishedRowsCause::UnchargedLoweringGap)
        } else if lowering_gap_rows.is_some() {
            Some(PublishedRowsCause::UnaccountedGap)
        } else {
            None
        };
    let published_row_tally = PublishedRowTally::of(published_rows, published_rows_cause);
    // Trust (D2, part C): whether this body's discharges are conditional on the
    // coroutine executor-protocol premise. A published disposition means the
    // bridge injected the entry `Assume`, which DOMINATES every block — so no
    // discharge in this body is unconditional, and the human summary must not
    // advertise a kernel-certified UNCONDITIONAL proof over it. Derived from the
    // disposition itself rather than from the row delta, which a strip can zero.
    let conditional_on_coroutine_premise = coroutine_protocol_rows.is_some();

    consume(PreparedBodyPolicy {
        published_rows,
        effective_rows,
        published_row_tally,
        strict,
        memory_safe,
        conditional_on_coroutine_premise,
        coroutine_protocol_rows: &coroutine_protocol_rows,
        global_alloc_dealloc_rows: &global_alloc_dealloc_rows,
        entry_termination_rows: &entry_termination_rows,
        termination_unmeasured_charge: &termination_unmeasured_charge,
        safety_comment_charge: &safety_comment_charge,
        instance_hypothesis_charge: &instance_hypothesis_charge,
        zero_obligation_vacuously_clean,
    })
}

fn publish_final_body_verification_outcome<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &Arc<VerificationArtifacts>,
    policy: &TrustVerifyPolicy,
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
    errors_before_publish: OriginalErrorBaseline,
) {
    run_body_publication(
        tcx, body, func_path, artifacts, policy, adversarial_open_dispatch,
        errors_before_publish, &mut ImmediatePublication,
    );
}

/// One execution of original source queries, private ledgers and policy
/// predicates. The immediate sink preserves ordinary output timing. A compact
/// sink may retain only prepared DATA; it must account original planned errors
/// without promoting amended caller, optimizer or owned-root facts.
fn run_body_publication<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &Arc<VerificationArtifacts>,
    policy: &TrustVerifyPolicy,
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
    errors_before_publish: OriginalErrorBaseline,
    output: &mut impl PublicationOutput,
) {
    let output_mode = TrustOutputMode::parse(tcx.sess);

    with_body_publication_policy(
        tcx, body, func_path, artifacts, policy, adversarial_open_dispatch,
        |prepared| {
            let PreparedBodyPolicy {
                published_rows,
                effective_rows,
                published_row_tally,
                strict,
                memory_safe,
                conditional_on_coroutine_premise,
                coroutine_protocol_rows,
                global_alloc_dealloc_rows,
                entry_termination_rows,
                termination_unmeasured_charge,
                safety_comment_charge,
                instance_hypothesis_charge,
                zero_obligation_vacuously_clean,
            } = prepared;
            output.original_rows(tcx, published_rows, published_row_tally);
            // Trust: Report results via rustc diagnostics when human-readable output is enabled.
            if output_mode.emit_human() {
                if !artifacts.results.is_empty() {
                    output.header(tcx);
                    output.results_report(
                        tcx,
                        body.span,
                        &artifacts.results,
                        &artifacts.result_bindings,
                        &artifacts.proof_authorities,
                        artifacts.proof_results.summary.certified as usize,
                        published_row_tally,
                        conditional_on_coroutine_premise,
                    );
                } else if !artifacts.transport_results.is_empty() {
                    if let Some(report) = prepare_transport_results_report(
                        published_rows, artifacts.proof_results.summary.cached,
                    ) {
                        output.action(tcx, PreparedAction::Note(PreparedLocatedNote { span: body.span, report }));
                    }
                }
            }

            // Trust (D2 tier 1): every row of a body that received an `ADAPTER_YIELD`
            // premise rests on that modeled fact; name it beside the report (and in the
            // JSON `modeled_facts` field below).
            let mut modeled_facts = adapter_yield::modeled_facts(tcx, body);
            // Trust (2026-10-08): the argument premises (D15) ride the same field, each
            // entry prefixed by its own key (`NOALIAS_MUT_ARGS: …`).
            modeled_facts.extend(argument_premise::premises_for(tcx.sess, body.source.def_id()));
            if output_mode.emit_human() {
                for note in adapter_yield::prepare_premise_disclosures(tcx, body) {
                    output.action(tcx, PreparedAction::Note(note));
                }
                for note in argument_premise::prepare_premise_disclosures(tcx, body) {
                    output.action(tcx, PreparedAction::Note(note));
                }
            }
            // Trust (STR_BYTE_POSITION): the byte-position premises installed for this body.
            let byte_position_facts = byte_eq_predicate::modeled_facts(tcx, body);
            if output_mode.emit_human() {
                for fact in &byte_position_facts {
                    output.action(tcx, PreparedAction::Note(PreparedLocatedNote {
                        span: body.span,
                        report: PreparedHumanReport { summary: format!(
                                "Trust modeled fact {fact} (assumed for the str range rows on that \
                                 call's index, not re-derived; docs/TCB.md, Modeled-fact axioms)"
                            ), notes: Vec::new() },
                    }));
                }
            }
            modeled_facts.extend(byte_position_facts);

            if output_mode.emit_human() {
                match &coroutine_protocol_rows {
                    Some(CoroutineProtocolDisposition::UnprovedAssumption(_)) => output.action(tcx, PreparedAction::Stderr(format!(
                        "Trust: ASSUMPTION [{COROUTINE_PROTOCOL_ASSUMPTION_TAG}] `{func_path}`: \
                         {COROUTINE_PROTOCOL_ASSUMPTION_DETAIL} — recorded as an unverified \
                         assumption (NOT proved)"
                    ))),
                    // Trust (coroutine resume-state contract): the sentinels were
                    // genuinely solver-proved under the bridge's exported entry
                    // precondition, so the premise publishes as a CONTRACT row
                    // (verified-modulo-callers) instead of an unverified assumption.
                    Some(CoroutineProtocolDisposition::ContractPublished(rows)) => {
                        let states = rows
                            .iter()
                            .rev()
                            .find_map(|row| {
                                trust_types::assumption::parse_coroutine_resume_contract_row_description(
                                    &row.description,
                                )
                            })
                            .map(|states| {
                                trust_types::assumption::coroutine_resume_contract_states_render(&states)
                            })
                            .unwrap_or_else(|| "{..}".to_string());
                        output.action(tcx, PreparedAction::Stderr(format!(
                            "Trust: CONTRACT [coroutine-resume-state] `{func_path}`: \
                             ResumedAfterReturn/Panic/Drop sentinels PROVED under exported \
                             precondition resume state ∈ {states}; the crate's proof remains \
                             conditional on every caller establishing the resume state"
                        )));
                    }
                    None => {}
                }
            }

            // §5 STEP 5: the `GlobalAlloc::dealloc` contract's human line, additive to
            // (and after) the coroutine premise's — same seam, same ordering rules.
            if output_mode.emit_human() {
                match &global_alloc_dealloc_rows {
                    Some(GlobalAllocDeallocDisposition::DischargedVacuouslyForGlobal(_)) => output.action(tcx, PreparedAction::Stderr(format!(
                        "Trust: CONTRACT [global-alloc-dealloc-panic-free] `{func_path}`: \
                         allocation(s) and/or allocation-owning drop(s) rely on \
                         `GlobalAlloc::{{alloc,dealloc}}` never panicking; DISCHARGED vacuously — no \
                         `#[global_allocator]` in the crate graph, so every allocation and dealloc is \
                         `Global`'s std chain, which has no panic path; the proof remains conditional \
                         on the final link registering no other allocator"
                    ))),
                    Some(GlobalAllocDeallocDisposition::RefusedUserAllocator(_)) => {
                        match user_allocator_interposer_only(tcx) {
                            None => output.action(tcx, PreparedAction::Stderr(format!(
                                "Trust: CONTRACT-REFUSED [global-alloc-dealloc-panic-free] \
                                 `{func_path}`: a user `#[global_allocator]` is registered and its \
                                 `dealloc` impl is not verified panic-free — allocation-owning drops in \
                                 this body may panic (fail-closed; no discharge-at-impl lane exists yet)"
                            ))),
                            Some(interposer) => output.action(tcx, PreparedAction::Stderr(format!(
                                "Trust: CONTRACT-REFUSED [global-alloc-dealloc-panic-free] \
                                 `{func_path}`: {} — allocations and allocation-owning drops in this \
                                 body run that unverified code (fail-closed; no discharge lane exists \
                                 yet)",
                                interposer.clause()
                            ))),
                        }
                    }
                    Some(GlobalAllocDeallocDisposition::RefusedAllocErrorHook(_)) => output.action(tcx, PreparedAction::Stderr(format!(
                        "Trust: CONTRACT-REFUSED [global-alloc-dealloc-panic-free] `{func_path}`: a \
                         crate in the graph references `std::alloc::set_alloc_error_hook` — an \
                         allocation in this body may fail into a hook that panics (fail-closed; no lane \
                         verifies the hook)"
                    ))),
                    None => {}
                }
            }

            // Trust (D1 residual, 2026-09-24): the policy-B entry-`Termination` row was
            // transport-only, so a `main -> Result<(), Box<dyn Error>>` with no other row
            // built with ZERO warnings on bare `trustc`. Make it visible; `certify`
            // refuses it below with an error instead. Diagnostic only.
            if output_mode.emit_human()
                && entry_termination_rows.is_some()
                && !matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
            {
                output.action(tcx, PreparedAction::Diagnostic(fmt_termination_dyn::prepare_entry_termination_dispatch_warning(tcx, body, &func_path)));
            }

            // Trust (D9): the unmeasured-self-recursion charge is disclosed on every
            // non-`certify` lane; `certify` refuses it below with an error instead.
            // Diagnostic only; renders nothing but `func_path`.
            if output_mode.emit_human()
                && !matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
                && let Some(charge) = &termination_unmeasured_charge
            {
                output.action(tcx, PreparedAction::Diagnostic(termination_unmeasured::prepare_termination_unmeasured_warning(tcx, body, &func_path, charge)));
            }

            // Trust (SAFETY-ASSUME-1): a SAFETY-comment declared block is disclosed on every
            // non-`certify` lane; `certify` refuses it below with an error instead.
            // Diagnostic only; renders nothing but `func_path` and source positions.
            if output_mode.emit_human()
                && !matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
                && let Some(charge) = &safety_comment_charge
            {
                output.action(tcx, PreparedAction::Diagnostic(safety_comment_assumption::prepare_safety_comment_warning(tcx, body, &func_path, charge)));
            }

            // Trust (OD-1 phase 1): instance hypotheses are disclosed on every non-`certify`
            // lane; `certify` refuses them below with an error instead.
            if output_mode.emit_human()
                && !matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
                && let Some(charge) = &instance_hypothesis_charge
            {
                if let Some(diagnostic) = instance_hypothesis::prepare_instance_hypothesis_warning(tcx, body, &func_path, charge) {
                    output.action(tcx, PreparedAction::Diagnostic(diagnostic));
                }
            }

            // Trust (TINV-29, review fold-in): a type-invariant premise is disclosed per function on
            // every non-`certify` lane; `certify` refuses it below.
            if output_mode.emit_human()
                && !matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
            {
                if let Some(diagnostic) = type_invariant::prepare_type_invariant_warning(tcx, body.source.def_id(), &func_path) {
                    output.action(tcx, PreparedAction::Diagnostic(diagnostic));
                }
            }

            // Trust (2026-09-29): the runtime-checked std-member disposition is disclosed on
            // every lane where it passes CONDITIONALLY; `certify` refuses it below with an
            // error instead, and memory-safe refuses its row as an unauthenticated
            // non-proved row (`memory_safe_artifacts_have_non_demotable_failure`), so
            // neither gets the "passes conditionally" advisory. Emitted in EVERY output
            // mode, as the lowering-failure advisory it replaces was: a JSON consumer reads
            // the row, and a human reading the same run must see the same fact. Diagnostic
            // only; renders nothing but `func_path` and the stored member paths.
            if !matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
                && !memory_safe
                && !artifacts.runtime_checked_std_members.is_empty()
            {
                output.action(tcx, PreparedAction::Diagnostic(runtime_checked_std_member::prepare_runtime_checked_std_member_warning(
                    tcx,
                    body,
                    &func_path,
                    &artifacts.runtime_checked_std_members,
                )));
            }

            // Trust (T3 C05): the elision audit's verdict vector, in either output mode.
            audit_published_rows(tcx, body.source.def_id(), &func_path, published_rows);
            // Trust (T3 L4, C06a): and one digest per results row, for the L4 row comparison.
            elide_audit::record_row_digests(
                tcx,
                body.source.def_id(),
                &artifacts.results,
                canonical_exact_vc_payload,
            );
            // Trust (T3 L4, C07r): the row oracle reads every results row's id back, as published,
            // from the body's context (`RowResults::check_in`). Only when the audit is on: the count
            // is all it changes, and the count is read only by the row below. Each results row is
            // then counted at least twice in that row, as it joined the context (again wherever a
            // rewrite changed or moved it, `RowResults::rewrite`) and once here, so from C07r the
            // row's `rows=` is not comparable with C07's or C07p's; `mismatches=` is
            // (`elide_audit`'s PARITY docs).
            if elide_audit::enabled() {
                artifacts.results.check_in(&artifacts.ctx);
            }
            // Trust (T3 L4, C07): and the row oracle's count over the body's context, once per
            // function, always (`PARITY <fn> row`).
            elide_audit::record_parity(
                tcx,
                body.source.def_id(),
                &artifacts.ctx,
                &[trust_types::vc_context::Oracle::Row],
            );
            // Trust #542: Emit structured JSON transport only when requested.
            // targo-trust requests this for programmatic access without forcing raw
            // transport into ordinary compiler stderr.
            if output_mode.emit_json() {
                // `published_rows`, computed above for both surfaces: the zero-obligation
                // rows (the synthetic `no_obligations` row, the honest gap row, or the
                // transport rows, with any appended charge; for a body a policy disposition
                // charged, its composed rows behind any owed gap row) or `effective_rows`.
                output.transport(
                    tcx,
                    body.source.def_id().as_local(),
                    &func_path,
                    published_rows,
                    artifacts.proof_results.summary.cached,
                    &modeled_facts,
                    artifacts.expanded_function_identity.as_ref(),
                );
            }

            // Batteries-on verification uses the native typed route. Strict scopes
            // fail closed; the explicit memory-safe policy relaxes only rows the
            // compiler reclassified with its authenticated no-unsafe marker.
            // (`strict` / `memory_safe` are bound above the disposition — the contract
            // upgrade is explicit-advisory-only and must consult them first.)
            //
            // Trust #3: `artifacts` is now an `Arc<VerificationArtifacts>`; borrow the
            // shared payload (`as_ref`) for the `&VerificationArtifacts` consumers.
            // Pass the policy so diagnostics distinguish strict, survey, and
            // memory-safe runs.
            if let Some(diagnostic) = prepare_strict_l0_verification_failure(
                tcx,
                body,
                &func_path,
                artifacts.as_ref(),
                &policy,
                published_row_tally,
                &adversarial_open_dispatch,
            ) {
                output.level_zero_row_failure(tcx, body.span, diagnostic);
            }
            // A PUBLISHED contract (sentinels solver-proved under the exported
            // precondition) is verified-modulo-callers and does not abort; only the
            // UNPROVED premise keeps the fail-closed strict rejection. Since D2 the
            // contract cannot publish in a fail-closed lane at all, so this abort is
            // reachable for EVERY strict coroutine resume body again.
            if strict
                && matches!(
                    &coroutine_protocol_rows,
                    Some(CoroutineProtocolDisposition::UnprovedAssumption(_))
                )
                && !memory_safe
            {
                output.action(tcx, PreparedAction::Diagnostic(publication_contracts::prepare_coroutine_protocol_assumption(tcx, body, &func_path)));
            }

            // §5 STEP 5: the REFUSED `GlobalAlloc::dealloc` contract fails closed in
            // the same lanes, at the same point in the pipeline (after reporting and
            // transport), as the unproved coroutine premise. The DISCHARGED (vacuous
            // `Global`) disposition never aborts: its premise is established against
            // the crate graph in view, and its residual link-time condition is carried
            // by the published row + the blocked panic-free registry, not by an abort.
            let global_alloc_refusal = match &global_alloc_dealloc_rows {
                Some(GlobalAllocDeallocDisposition::RefusedUserAllocator(_)) => {
                    Some(GlobalAllocRefusal::UserAllocator)
                }
                Some(GlobalAllocDeallocDisposition::RefusedAllocErrorHook(_)) => {
                    Some(GlobalAllocRefusal::AllocErrorHook)
                }
                Some(GlobalAllocDeallocDisposition::DischargedVacuouslyForGlobal(_)) | None => None,
            };
            if strict
                && let Some(refusal) = global_alloc_refusal
                && !memory_safe
            {
                output.action(tcx, PreparedAction::Diagnostic(publication_contracts::prepare_global_alloc_dealloc_contract_refusal(tcx, body, &func_path, refusal)));
            }

            // Trust (2026-09-16): under `certify` a reported entry-`Termination` dispatch
            // gap is fatal, exactly as the tolerated print gap is.
            if entry_termination_rows.is_some()
                && matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
            {
                output.action(tcx, PreparedAction::Diagnostic(publication_contracts::prepare_entry_termination_dispatch(tcx, body, &func_path)));
            }

            // Trust (D9, ruled 2026-09-27): `--certify` refuses a function whose
            // termination rests on an `assumption:termination-unmeasured` row. Every
            // other lane records the row and passes (the strict fatal paths read the
            // VC-level `artifacts`, which the charge does not touch; memory-safe admits
            // the row by its exact shape).
            if matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
                && let Some(charge) = &termination_unmeasured_charge
            {
                output.action(tcx, PreparedAction::Diagnostic(termination_unmeasured::prepare_termination_unmeasured_refusal(tcx, body, &func_path, charge)));
            }

            // Trust (SAFETY-ASSUME-1, ruled 2026-10-17): `--certify` refuses a function whose
            // unsafe block is sound only by its `// SAFETY:` comment. Every other lane
            // records the `assumption:safety-comment` row and passes CONDITIONALLY: the
            // strict fatal paths read the VC-level `artifacts`, from which the declared
            // rows were withheld, and a body with an unsafe operation is never judged by
            // the memory-safe demotion gate.
            if matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
                && let Some(charge) = &safety_comment_charge
            {
                output.action(tcx, PreparedAction::Diagnostic(safety_comment_assumption::prepare_safety_comment_refusal(
                    tcx, body, &func_path, charge,
                )));
            }

            // Trust (OD-1 phase 1, ruled 2026-10-03): `--certify` refuses a function that
            // carries an instance hypothesis; every other lane records it and passes
            // CONDITIONALLY (memory-safe refuses it as an unauthenticated non-proved row).
            // A discharge row that did not establish its instance is an error on every
            // fail-closed lane and a warning under advisory: an instance this very
            // compilation creates reaches a callee nobody proved panic-free.
            if let Some(charge) = &instance_hypothesis_charge {
                if matches!(policy.policy, rustc_session::config::TrustPolicy::Certify) {
                    if let Some(diagnostic) = instance_hypothesis::prepare_instance_hypothesis_refusal(tcx, body, &func_path, charge) {
                        output.action(tcx, PreparedAction::Diagnostic(diagnostic));
                    }
                }
                if let Some(diagnostic) = instance_hypothesis::prepare_unestablished_discharges(tcx, body, &func_path, charge, strict) {
                    output.action(tcx, PreparedAction::Diagnostic(diagnostic));
                }
            }

            // Trust (TINV-29, review fold-in): `--certify` refuses a function whose rows carry a
            // type-invariant premise, as it refuses an instance hypothesis above and as targo's
            // `--certify` refuses the `assumed` row.
            if matches!(policy.policy, rustc_session::config::TrustPolicy::Certify) {
                if let Some(diagnostic) = type_invariant::prepare_type_invariant_refusal(tcx, body.source.def_id(), &func_path) {
                    output.action(tcx, PreparedAction::Diagnostic(diagnostic));
                }
            }

            // Trust (2026-09-29): a trait impl method's `requires` is an entry
            // hypothesis no caller is charged (`trait_impl_requires`). Refused on every
            // fail-closed lane that judges with the full gate below; memory-safe keeps its
            // own gate, advisory reports.
            if strict && !memory_safe {
                if let Some(diagnostic) = trait_impl_requires::prepare_uncharged_trait_impl_requires(tcx, body, &func_path) {
                    output.action(tcx, PreparedAction::Diagnostic(diagnostic));
                }
            }

            // Trust (2026-09-29): `--certify` refuses a function that owes a
            // runtime-checked std-member row. Every other fail-closed lane records the
            // row and passes CONDITIONALLY (memory-safe refuses it as an unauthenticated
            // non-proved row in `memory_safe_artifacts_have_non_demotable_failure`).
            if matches!(policy.policy, rustc_session::config::TrustPolicy::Certify)
                && !artifacts.runtime_checked_std_members.is_empty()
            {
                output.action(tcx, PreparedAction::Diagnostic(runtime_checked_std_member::prepare_runtime_checked_std_member_refusal(
                    tcx,
                    body,
                    &func_path,
                    &artifacts.runtime_checked_std_members,
                )));
            }

            // Trust (D1 increment 0, 2026-09-23): the hidden `Termination` sink. A LOCAL
            // (or foundational-over-local) error type mints no entry row above, yet std's
            // `Termination::report` panics when its `Debug` returns `Err` spontaneously
            // (`fn main() -> Result<(), E> { Err(E) }` built rc=0, exited 101). Standalone
            // and refusal-only; same lanes as the packer gate's `println!` refusal.
            if strict && !memory_safe {
                if let Some(diagnostic) = fmt_error_transparency::prepare_entry_termination_error_opacity(tcx, body, &func_path) {
                    output.action(tcx, PreparedAction::Diagnostic(diagnostic));
                }
            }

            // Trust: a GUARANTEED Level-0 safety violation — one whose counterexample
            // formula is GROUND (folds to forced-true on every reaching execution, e.g.
            // a constant `Vec::with_capacity(1 << 28)` lowering to `Ge(1<<28, 1<<28)`) —
            // is a hard error in strict scope. The escalation is soundness-gated:
            // only a GROUND forced violation (no free input vars) escalates; a merely
            // POSSIBLE symbolic violation remains an ordinary unproved obligation.
            if strict {
                if memory_safe {
                    // Trust (2026-10-10, ZERO-ROW-GATE): the gate reads the rows this body
                    // PUBLISHES as well as `effective_rows`. They differ only for a
                    // zero-obligation body, whose published set can be the `unknown`
                    // `native-verification-gap` row; scanning the union can only add a
                    // refusal, never drop one. And it is handed the publisher's own
                    // vacuity verdict.
                    let memory_safe_rows: std::borrow::Cow<'_, [TransportObligationResult]> =
                        if std::ptr::eq(published_rows, effective_rows) {
                            std::borrow::Cow::Borrowed(effective_rows)
                        } else {
                            std::borrow::Cow::Owned(
                                effective_rows.iter().chain(published_rows.iter()).cloned().collect(),
                            )
                        };
                    if let Some(diagnostic) = publication_memory_safe::prepare_memory_safe_non_demotable_failure(
                        tcx,
                        body,
                        &func_path,
                        artifacts.as_ref(),
                        &memory_safe_rows,
                        zero_obligation_vacuously_clean,
                    ) {
                        output.action(tcx, PreparedAction::Diagnostic(PreparedLocatedDiagnostic { span: body.span, diagnostic }));
                    }
                    // Trust (2026-09-30, residual L2): the indirect-call gate the branch
                    // below asks inside `abort_on_full_verification_failure` — an
                    // unresolved indirect call has no row for the memory-safe gate to read.
                    if let Some(diagnostic) = uncharged_callable::prepare_memory_safe_unresolved_indirect_call(
                        tcx, body, &func_path,
                    ) {
                        output.action(tcx, PreparedAction::Diagnostic(diagnostic));
                    }
                } else {
                    if let Some(failure) = publication_failure::prepare_full_verification_failure(
                        tcx,
                        body,
                        &func_path,
                        artifacts.as_ref(),
                        published_row_tally,
                        zero_obligation_vacuously_clean,
                    ) {
                        output.full_failure(tcx, body.span, failure);
                    }
                }
                // Strict mode ALSO escalates a GROUND forced L0 violation here. The
                // native trust-mc lane lowers only arithmetic-safety / panic-freedom
                // obligations and never the OOM-ceiling check, so it vacuously forges
                // `Proved` for a forced over-budget bulk allocation;
                // the malformed native row may still be independently kernel-certified
                // as its encoded formula, so without this structural escalation (which
                // overrides any `Proved` for a forced
                // UnboundedAllocation) the over-budget allocation slips through.
                if !memory_safe {
                    if let Some(diagnostic) = publication_escalation::prepare_refuted_l0_safety_counterexamples(tcx, body, &func_path, artifacts.as_ref()) {
                        output.action(tcx, PreparedAction::Diagnostic(PreparedLocatedDiagnostic { span: body.span, diagnostic }));
                    }
                }
                // Trust (2026-09-23, i02): every body-level abort above has run, so an
                // unchanged error count means this function's own verdict is final and
                // accepted. Any error — this body's or a concurrent one — withholds it.
                if !memory_safe && output.original_errors_unchanged(tcx, &errors_before_publish) {
                    with_crate_verification_state(tcx.sess, |state| {
                        state.strict_accepted_fns.insert(func_path.to_string());
                    });
                    // Trust (2026-09-25): the same point, keyed by `LocalDefId`: promote this
                    // body's pending own-root Assert charges to evidence a caller's bundle
                    // may credit — only if every charged row proved here
                    // (`member_assert_ownership`).
                    member_assert_ownership::promote_own_root_assert_charges(tcx, body, artifacts.as_ref());
                }
            }
        },
    );
}

/// Did this function's own fail-closed verification finish accepted earlier in
/// this compilation? See `CrateVerificationState::strict_accepted_fns`.
fn function_accepted_in_strict(sess: &Session, def_path: &str) -> bool {
    with_crate_verification_state(sess, |state| state.strict_accepted_fns.contains(def_path))
}

/// Trust (P4 — proof survives to codegen): bounded, fail-closed check-elision.
///
/// Source spans are never authority: macro expansion, compiler synthesis, and
/// multiple checks at one expression can share them. For the current
/// Add/Sub/Mul overflow increment, the generation the compiler consumes carries
/// each row's pristine originating MIR block beside the exact formula-bearing VC
/// (T3 C05). The compiler joins that private map only to the same canonical row
/// sealed by `KernelCertified`, requires the origin to be unique in a complete
/// inventory, and rechecks the live terminator's assert kind and operation
/// immediately before rewriting it. Missing, ambiguous, stale, weak, truncated
/// or non-overflow evidence keeps the check. Other assert families remain
/// outside this lane.
fn elide_kernel_certified_checks<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &mut Body<'tcx>,
    artifacts: &VerificationArtifacts,
) {
    // Runtime ledger, increment 1: drop the panic/unwind edge of an arithmetic
    // Add/Sub/Mul overflow Assert whose no-overflow VC was KERNEL-certified. Every
    // gate below is fail-CLOSED — a check is kept unless a genuine per-op kernel
    // proof, joined to THIS MIR block by the authority's own formula-inclusive
    // canonical string, is confirmed live. With overflow-checks off no Assert
    // exists, so nothing to elide.
    if !tcx.sess.overflow_checks() {
        return;
    }
    // Trust (D2 tier 1): a body that received an `ADAPTER_YIELD` premise is never
    // elided — keyed on INSTALLATION, not on whether vcgen's closure-side gates
    // used it. A false premise can then only yield a panicking program reported
    // panic-free, never a removed runtime check.
    if adapter_yield::body_carries_premise(tcx, body.source.def_id()) {
        return;
    }
    // Trust (2026-10-18, FRESH-CAPTURE-1): nor a closure body handed fresh shared
    // capture fields — keyed on installation, like the line above: a wrong occurrence
    // accounting can then only report a panicking closure panic-free, never remove its
    // runtime check.
    if fresh_capture::body_carries_premise(tcx, body.source.def_id()) {
        return;
    }
    // Trust (2026-10-08): nor one carrying an argument premise (D15). Its rows
    // whose VC the premise shaped are already demoted off `KernelCertified`; a row
    // the premise-free generation also produces keeps its token (2026-10-17), but
    // no check of the body is removed: the guard is keyed on installation.
    if argument_premise::body_carries_premise(tcx.sess, body.source.def_id()) {
        return;
    }
    // Trust (STR_BYTE_POSITION): the same exclusion for a body handed a
    // byte-position premise.
    if byte_eq_predicate::body_carries_premise(tcx, body) {
        return;
    }
    // Trust (TINV step 10.4, TINV-27): nor a body any type-invariant use-site fact was
    // conjoined into — keyed on installation, like the two above.
    if type_invariant::body_carries_premise(tcx, body.source.def_id()) {
        return;
    }
    // Trust (2026-10-04, ADVISORY-REQUIRES-INSTANCE): a trait impl method's
    // `requires` is charged to no call, so a check proved under it is not removed
    // (`trait_impl_requires::entry_requires_charged_to_no_call`). The fail-closed
    // lanes refuse the body anyway; advisory does not, and its callers' rows say
    // `runtime_checked` for the call.
    if trait_impl_requires::entry_requires_charged_to_no_call(tcx, body.source.def_id()) {
        return;
    }
    // Trust (2026-10-04, ADVISORY-REQUIRES-INSTANCE, the sibling route): under
    // `-Ztrust-policy=advisory` NO route that reaches a `requires` body uncharged is
    // refused (the value-use gate, `uncharged_callable`, is fail-closed on every
    // lane but advisory), and a refuted caller-side `Precondition` row is a warning,
    // so the clause every elision in such a body rests on is enforced nowhere.
    // MEASURED on stage 1 of `1177c327fa`: `fn add1(x: u32) -> u32 requires x < 100
    // { x + 1 }` called through `let fp: fn(u32) -> u32 = add1; fp(u32::MAX)` built
    // under advisory (caller row `unknown`) and RETURNED 0, where a verify-off build
    // panics. Advisory makes no proof claim, so it removes no check proved under a
    // caller precondition. Verdicts are unchanged; only the advisory binary keeps
    // the check.
    if !tcx.sess.trust_proof_claimed()
        && trust_mir_extract::def_owes_caller_precondition(tcx, body.source.def_id())
    {
        return;
    }
    // Trust (2026-10-05, ADVISORY-REQUIRES-CROSS-CRATE, the dependency route): the
    // gate above is decided by THIS crate's policy, but a call from another crate is
    // charged under ITS policy — an advisory consumer only warns on a failed
    // `Precondition` row, a verify-off one charges nothing. MEASURED on stage 1 of
    // `71fc7a07cc`: `pub fn add1(x: u32) -> u32 requires x < 100 { x + 1 }` built on
    // the default policy had its check elided, and an advisory consumer's
    // `la::add1(u32::MAX)` (direct, or through a fn pointer) built exit 0 and
    // returned 0, where a verify-off build of both crates panics. So in every lane
    // no check proved under a caller precondition is elided from a body another
    // crate can call (`trait_impl_requires::entry_requires_reachable_from_another_crate`).
    // Verdicts are unchanged; only the binary keeps the check.
    //
    // Trust (2026-10-05, ADVISORY-REQUIRES-TRANSITIVE-1): nor from a body such a
    // call reaches through `requires` bodies of this crate. A private `bump` whose
    // only caller is `pub fn inc_via(x) requires x < 100 { bump(x) }` is charged its
    // clause here, but under `inc_via`'s own clause, which an advisory or verify-off
    // consumer of `inc_via` does not enforce; MEASURED on the stage 1 of
    // `c1c028f41f`, `bump`'s check elided and `inc_via(u32::MAX)` returned 0. The
    // check is removed only when no chain of `requires` bodies that names this one
    // starts at a body another crate can call
    // (`trait_impl_requires::entry_requires_charged_only_in_this_crate`; it is
    // false for such a body itself too, so it replaces the reachability test above).
    if trust_mir_extract::def_owes_caller_precondition(tcx, body.source.def_id())
        && !trait_impl_requires::entry_requires_charged_only_in_this_crate(
            tcx,
            body.source.def_id(),
        )
    {
        return;
    }
    let mut rewrites: Vec<(BasicBlock, BasicBlock)> = Vec::new();
    for i in 0..artifacts.results.len() {
        // (1) AUTHORITY: only KernelCertified licenses. Every weaker authority
        // (SolverRevalidated / Trusted / assumption / a bare public "Proved" with
        // no private authority => None) falls through.
        let Some(auth @ ResultProofAuthority::KernelCertified { row, .. }) =
            artifacts.proof_authorities.get(i).and_then(Option::as_ref)
        else {
            audit_kept_overflow_check(tcx, body, &artifacts.results[i].0, "uncertified");
            continue;
        };
        let (vc, result) = &artifacts.results[i];
        let binding = artifacts.result_bindings.get(i).and_then(Option::as_ref);
        // (2) Re-gate: index + sealed canonical_vc == current results[i] (formula-
        // drift guard), mirroring trust_disposition_for_authority.
        if !auth.matches_row(i, vc, binding) || !auth.matches_compiler_result(result) {
            audit_kept_overflow_check(tcx, body, vc, "stale");
            continue;
        }
        // (3) KIND: increment 1 is arithmetic Add/Sub/Mul overflow only.
        let VcKind::ArithmeticOverflow { op, .. } = &vc.kind else { continue };
        if !matches!(op, BinOp::Add | BinOp::Sub | BinOp::Mul) {
            continue;
        }
        // (4) IDENTITY JOIN: the authority's OWN canonical_vc (== the sealed
        // ExactResultRowIdentity string), never a span. Unique only — a canonical
        // shared by >=2 blocks is Ambiguous => skip (coalesce/macro defense).
        let Some(bb) = artifacts.overflow_check_origins.resolve(&row.canonical_vc) else {
            // Trust (T3 C05): a certified overflow row the table could not join.
            if elide_audit::enabled() {
                let state = artifacts.overflow_check_origins.audit_miss(&row.canonical_vc);
                audit_kept_overflow_check(tcx, body, vc, state);
            }
            continue;
        };
        // (5) LIVE RE-CONFIRM: the origin block must STILL hold an Assert whose
        // AssertKind::Overflow op bridges the certified op. Any shift/mismatch =>
        // skip (TrustVerify is the last pass, so bb indices are stable).
        let live = body.basic_blocks.get(bb).and_then(|bbdata| {
            let TerminatorKind::Assert { msg, target, .. } = &bbdata.terminator().kind else {
                return None;
            };
            let rustc_middle::mir::AssertKind::Overflow(mir_op, ..) = &**msg else {
                return None;
            };
            matches!(
                (mir_op, op),
                (MirBinOp::Add, BinOp::Add)
                    | (MirBinOp::Sub, BinOp::Sub)
                    | (MirBinOp::Mul, BinOp::Mul)
            )
            .then_some(*target)
        });
        let Some(target) = live else {
            audit_kept_overflow_check(tcx, body, vc, "moved");
            continue;
        };
        // (6) HARDENED TWIN AGREEMENT. `VcKind::HardenedBoundary` over a
        // `mir_assert::Overflow(..)` answers `true` to
        // `site_retains_language_check_in` when overflow checks are on
        // (crates/trust-types/src/formula/vc_kind.rs), i.e. it makes the POSITIVE
        // FACTUAL claim that THIS `Assert` is still in the generated program —
        // which is what targo's `--test-target-panics=runtime-checked` reads
        // before it will reclassify such a row inside a test target. This seam is
        // the one thing in the compiler that can make that claim false, so it
        // declines whenever the hardened twin over the same operation and span is
        // not itself proved.
        //
        // NOTE the claim is factual only: `has_runtime_fallback_in` still answers
        // `false` for the whole hardened family, so no report labels these rows
        // covered. This gate protects the FACT, not a discharge.
        //
        // WHY THE CORNER IS REAL. The two lanes are deliberately NOT the same
        // query: the hardened twin filters its semantic guards by the block's
        // killed set while the per-statement lane conjoins them unfiltered
        // (trust-vcgen/src/hardened.rs, "DROP-ONLY: dropping a hypothesis can only
        // turn a PROVE into a FAIL"). So a KernelCertified primary can stand beside
        // a refuted twin. Targo's `subsume_hardened_panic_twins` does not close it
        // either — it flips only an `Unknown` twin to `Proved`, never a `Failed`
        // one.
        //
        // STRICTLY CHECK-KEEPING, so it can only make the program safer, and it is
        // inert when the hardening profile is off (no twin exists, `any` is false).
        // The join is (function, span, exact `mir_assert::Overflow(<op>)` callee) —
        // the same byte-identical-`SourceSpan` correspondence targo's subsumption
        // pass uses, with the callee spelled through `AssertMessage`'s own `Debug`
        // so it cannot drift from the producer in trust-vcgen's hardened lane.
        if hardened_overflow_twin_is_unproved(artifacts, vc, *op) {
            audit_kept_overflow_check(tcx, body, vc, "twin");
            continue;
        }
        // Trust (T3 C05): the elided-Assert set, for the L3 gate's parent comparison.
        if elide_audit::enabled() {
            elide_audit::record(
                tcx,
                body.source.def_id(),
                "ELIDED",
                &[
                    format!("bb{}", bb.as_usize()),
                    format!("{op:?}"),
                    elide_audit::location(&vc.location),
                    elide_audit::key_digest(Some(row.canonical_vc.canonical())),
                ],
            );
        }
        rewrites.push((bb, target));
    }
    let n = rewrites.len();
    if n > 0 {
        // Drop only the panic/unwind edge (Assert -> Goto{target}); the preceding
        // *WithOverflow rvalue is untouched — LLVM lowers its now-dead overflow flag
        // to a plain arithmetic op. Collect-then-apply mirrors RedundantBoundsCheckElim.
        let blocks = body.basic_blocks.as_mut();
        for (bb, target) in rewrites {
            blocks[bb].terminator_mut().kind =
                TerminatorKind::Goto { target, loop_hint_attrs: Default::default() };
        }
    }
    if env_flag_enabled("TRUST_ELIDE_DEBUG") {
        eprintln!(
            "TRUST_ELIDE: elided {n} kernel-certified overflow checks in {:?}",
            body.source.def_id()
        );
    }
}

/// Whether a hardened `PanicBoundary` twin standing over the SAME arithmetic
/// overflow assert as `primary` is present and NOT proved.
///
/// `true` means the proven-overflow-check elision seam must decline: removing
/// the `Assert` would falsify the positive runtime-guard claim
/// `VcKind::site_retains_language_check_in` makes for that twin, and therefore
/// the reclassification targo's `--test-target-panics=runtime-checked` builds on
/// it. `false` is returned when no such twin exists at all, which is every build
/// with the hardening profile off — so this costs those builds nothing.
///
/// The twin's `callee` is rebuilt with `trust_types::hardened_mir_assert_callee`,
/// the one builder `trust_vcgen::hardened` mints it with, so the marker is
/// spelled in one place.
fn hardened_overflow_twin_is_unproved(
    artifacts: &VerificationArtifacts,
    primary: &VerificationCondition,
    op: BinOp,
) -> bool {
    // Trust: the shared builder, not a second spelling of the `mir_assert::` marker.
    let twin_callee =
        trust_types::hardened_mir_assert_callee(&trust_types::AssertMessage::Overflow(op));
    artifacts.results.iter().any(|(vc, result)| {
        let VcKind::HardenedBoundary {
            category: HardenedVcCategory::PanicBoundary, callee, ..
        } = &vc.kind
        else {
            return false;
        };
        *callee == twin_callee
            && vc.function == primary.function
            && vc.location == primary.location
            && !result.is_proved()
    })
}

/// Trust (T3 C05): record that the elision seam kept `vc`'s check, and the first gate
/// that kept it, when `vc` is an Add/Sub/Mul overflow row (the only rows the seam can
/// elide) and the elision audit is on.
fn audit_kept_overflow_check(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    vc: &VerificationCondition,
    reason: &str,
) {
    if !elide_audit::enabled() {
        return;
    }
    let VcKind::ArithmeticOverflow { op: op @ (BinOp::Add | BinOp::Sub | BinOp::Mul), .. } =
        &vc.kind
    else {
        return;
    };
    elide_audit::record(
        tcx,
        body.source.def_id(),
        "KEPT",
        &[
            reason.to_string(),
            format!("{op:?}"),
            elide_audit::location(&vc.location),
            elide_audit::key_digest(canonical_exact_vc_payload(vc).as_deref()),
        ],
    );
}

// Trust: execute the `trust_contracts` query only for defs that can actually
// carry contracts (single-sourced with the metadata encoder's pre-filter via
// `TrustContractBundle::def_may_have_contracts`) — the query is
// `cache_on_disk`, so every execution costs a dep node plus an incremental
// disk-cache row, and its disk-cache eligibility rests on being invoked only
// for contract-bearing items. Returns `None` when a local def cannot have
// contracts; extern defs go through the query (their bundles decode from
// rmeta, recorded only when non-empty).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TrustResolvedScalarType {
    U8,
    U16,
    U32,
    U64,
    U128,
    Usize,
    I8,
    I16,
    I32,
    I64,
    I128,
    Isize,
    Bool,
}

impl TrustResolvedScalarType {
    fn elaborator_name(self) -> &'static str {
        match self {
            Self::U8 => "u8",
            Self::U16 => "u16",
            Self::U32 => "u32",
            Self::U64 => "u64",
            Self::U128 => "u128",
            Self::Usize => "usize",
            Self::I8 => "i8",
            Self::I16 => "i16",
            Self::I32 => "i32",
            Self::I64 => "i64",
            Self::I128 => "i128",
            Self::Isize => "isize",
            Self::Bool => "bool",
        }
    }

    fn runtime_monitor_ty<'tcx>(self, tcx: TyCtxt<'tcx>) -> Option<Ty<'tcx>> {
        Some(match self {
            Self::U8 => tcx.types.u8,
            Self::U16 => tcx.types.u16,
            Self::U32 => tcx.types.u32,
            Self::U64 => tcx.types.u64,
            Self::U128 => tcx.types.u128,
            Self::Usize => tcx.types.usize,
            Self::I8 => tcx.types.i8,
            Self::I16 => tcx.types.i16,
            Self::I32 => tcx.types.i32,
            Self::I64 => tcx.types.i64,
            Self::I128 => tcx.types.i128,
            Self::Isize => tcx.types.isize,
            Self::Bool => tcx.types.bool,
        })
    }
}

/// Classify a type after rustc resolution. Matching `TyKind`, rather than the
/// spelling of the HIR path, makes `type Word = u64` and
/// `core::primitive::u64` share the same semantic carrier.
fn trust_resolved_scalar_type(ty: Ty<'_>) -> Option<TrustResolvedScalarType> {
    use ty::{IntTy, UintTy};

    Some(match ty.kind() {
        ty::Bool => TrustResolvedScalarType::Bool,
        ty::Uint(UintTy::U8) => TrustResolvedScalarType::U8,
        ty::Uint(UintTy::U16) => TrustResolvedScalarType::U16,
        ty::Uint(UintTy::U32) => TrustResolvedScalarType::U32,
        ty::Uint(UintTy::U64) => TrustResolvedScalarType::U64,
        ty::Uint(UintTy::U128) => TrustResolvedScalarType::U128,
        ty::Uint(UintTy::Usize) => TrustResolvedScalarType::Usize,
        ty::Int(IntTy::I8) => TrustResolvedScalarType::I8,
        ty::Int(IntTy::I16) => TrustResolvedScalarType::I16,
        ty::Int(IntTy::I32) => TrustResolvedScalarType::I32,
        ty::Int(IntTy::I64) => TrustResolvedScalarType::I64,
        ty::Int(IntTy::I128) => TrustResolvedScalarType::I128,
        ty::Int(IntTy::Isize) => TrustResolvedScalarType::Isize,
        _ => return None,
    })
}

/// Trust: collect `(param_name, rust_type_name)` for a function's parameters
/// plus a `result` entry when the return type is a supported primitive, so
/// the E9 citation lane can elaborate machine-typed clauses over the matching
/// domain (two-language design §1.1). The carrier is derived from resolved
/// typeck/function-signature `Ty`, never the source path spelling: transparent
/// aliases and qualified primitive paths therefore retain their Rust meaning.
/// Only the primitive type names the elaborator understands
/// (`u8`…`u128`, `usize`, `i8`…`i128`, `isize`, and `bool`) are reported;
/// anything else is omitted, which — since a clause referencing an unmapped var
/// fails closed in `elaborate_goal_typed` — keeps unsupported shapes out of the
/// machine lane rather than mis-elaborating them.
/// The FLATTENED clause-side rows one parameter named `name` of type `ty`
/// contributes to the E9 binding table (E6/E9 widening increment 7).
///
/// A supported SCALAR contributes one row, exactly as before. A by-value STRUCT
/// contributes ONE ROW PER DECLARED FIELD, named by its dotted path
/// (`c.degree`) and typed at the field's own carrier — which is what lets a
/// clause mention an aggregate's scalar field as one opaque atom
/// (`trust_spec_elab::atom_var_name`). Everything else contributes NOTHING, and
/// a clause naming it then fails the exact-binding gate.
///
/// THE TWO SIDES ARE NOT SYMMETRIC, and this comment used to say they were.
/// THIS side SKIPS a field it cannot type (see the `continue` below and the
/// reason beside it). `trust_certify::clean_island::param_flat_rows`, which
/// recomputes the same list from the extracted IR to decide the minted import's
/// binder order, is still ALL-OR-NOTHING: one field with no domain refuses the
/// whole parameter and therefore the whole mint. So a struct with a non-scalar
/// field still cannot carry a citing clause — the MINT refuses it — while a
/// clause naming a field skipped here fails closed as an unbound variable
/// instead of suppressing its scalar siblings' rows.
///
/// What keeps the two flattenings from drifting is therefore NOT "neither side
/// filters". It is that a residual disagreement changes the ARITY, which makes
/// the goal ill-typed and `reject_untyped_goal` refuses it, or the NAMES, which
/// `Admission::param_names` compares by exact list equality in
/// `elaborate_ensures`. A same-length REORDERING is caught by the second.
///
/// The struct is CANONICALIZED, never the clause: every field is enumerated in
/// declaration order whether or not the clause mentions it, so the flattening
/// depends only on the signature. `discharge_used_bindings` narrows the table
/// to the clause's free variables afterwards.
///
/// REFERENCES contribute nothing HERE. `&Cst` is not an `Adt`, so it falls
/// through. That is not the whole story since ref-self I1:
/// `trust_fn_param_type_names` consults [`trust_frozen_shared_param_scan`]
/// FIRST and, for a shared borrow of a `Freeze` struct, emits that table's
/// `self.<field>` rows without ever reaching this function. What falls through
/// here is every reference the table refused — `&mut`, a non-`Freeze` pointee,
/// a slice — for the reason this paragraph always gave: the pointee is not
/// provably unchanged between entry and exit, and the clause lane has no
/// two-state reading for it.
fn trust_param_scalar_rows<'tcx>(
    tcx: TyCtxt<'tcx>,
    name: &str,
    ty: Ty<'tcx>,
) -> Vec<(String, String)> {
    if let Some(carrier) = trust_resolved_scalar_type(ty) {
        return vec![(name.to_string(), carrier.elaborator_name().to_string())];
    }
    // `is_struct` excludes both enums (a field is variant-relative) and unions
    // (fields alias one another, so a field read is not a projection of an
    // independent value).
    let ty::Adt(def, args) = ty.kind() else {
        return Vec::new();
    };
    if !def.is_struct() {
        return Vec::new();
    }
    let mut rows = Vec::new();
    for field in &def.non_enum_variant().fields {
        // `field.ty` instantiates with the ADT's arguments, so an
        // un-instantiated generic field resolves to a `Param` and is refused
        // here rather than being read at some default carrier. The result is
        // deliberately NOT normalized: an unnormalized alias is not a `ty::Uint`
        // and is refused, which is the fail-closed direction — normalization can
        // only turn a non-scalar spelling INTO a scalar, never the reverse, so
        // skipping it can lose a row but never invent one at the wrong carrier.
        // SKIP a field this lane cannot type, rather than abandoning the whole
        // record. A row is a TYPING FACT about one projection; omitting a field
        // can only make a clause that names it fail closed as an unbound
        // variable, never read it at a wrong carrier. Bailing entirely was the
        // same fail-closed direction but far blunter: one non-scalar field
        // (`Term`'s `lit: Lit`) suppressed the rows for every scalar sibling, so
        // `result.coeff <= degree` was refused with "missing supported type"
        // even though `coeff` is a plain `i64`.
        let Some(carrier) = trust_resolved_scalar_type(field.ty(tcx, *args).skip_normalization())
        else {
            continue;
        };
        rows.push((format!("{name}.{}", field.name), carrier.elaborator_name().to_string()));
    }
    rows
}

// Trust (ref-self I1): the borrow-erased E6 PARAMETER VIEW.
//
// A function with a `&self` / `&T` parameter has no E6 facets — the validator
// refuses every `Ty::Ref`-typed local (`facet_inference::
// local_ty_in_closed_fragment`) — so no `ensures` clause on it can cite Lean.
// This lane does not edit that refusal. It computes ONE table naming the frozen
// shared parameters and the pointee fields it may read, and derives BOTH the
// clause-side binder rows (below) and a borrow-erased COPY of the extracted
// body (`trust_types::e6_param_view`) from it. The unchanged validator,
// recognizer and mints then run on the copy.
//
// THE ASSUMPTION THIS RESTS ON, and its price, are owner ruling R1
// (`docs/design-notes/2026-09-18-e6-parameter-view-ruling.md`, and a named row
// in `docs/TCB.md`): a live `&T` argument with `T: Freeze` is dereferenceable
// and its pointee bytes are immutable for the duration of the call. The same
// ruling forbids calling a row discharged this way `Certified`; every reporting
// site below grades such a row BELOW `Certified` and discloses
// `trust_types::e6_param_view::VIEW_MARKER`.

/// The compiler-side reading of `trust_types::e6_param_view::e6_view_scalar` —
/// the SAME vocabulary, keyed on the carrier NAME the two sides already share.
///
/// `usize`/`isize` are excluded here exactly as they are there: the clause side
/// types them but `trust_certify::clean_island::ty_to_domain` has no signed
/// pointer-sized arm, so admitting one would put the two flattenings at
/// different arities. The live `usize` lane extends BOTH functions or neither.
///
/// The two lists are not merely intended to agree: the view builder re-derives
/// each listed field's carrier from the EXTRACTED IR and refuses the whole view
/// on any disagreement with this one, so a drift here costs a capability and
/// can never mint at a wrong carrier.
fn trust_e6_view_carrier(ty: Ty<'_>) -> Option<&'static str> {
    let name = trust_resolved_scalar_type(ty)?.elaborator_name();
    matches!(
        name,
        "bool" | "u8" | "u16" | "u32" | "u64" | "u128" | "i8" | "i16" | "i32" | "i64" | "i128"
    )
    .then_some(name)
}

/// K2, the SECOND KEY: a plain structural walk of `ty` looking for an
/// `UnsafeCell` (or a union, or a shape it cannot classify) INLINE in the type.
///
/// It re-derives `Freeze`'s structural definition without the trait solver, so
/// this lane is not the sole reader of one `is_freeze` answer. It is defence in
/// depth, NOT an independent authority — it reads rustc's own `AdtDef`s, the
/// same definitions C2 does — and it can only ever REFUSE.
///
/// It stops at every POINTER (`&T`, `*const T`, a function pointer — and
/// therefore inside `Box`/`Vec`/`String`), which is the SHALLOW `Freeze`
/// notion and the right one: the scalar bytes this lane reads are inline in the
/// pointee, and a `Vec<Cell<u8>>` sibling field covers none of them.
///
/// `Err` carries the offending FIELD PATH, which is what the `D-REF-2`
/// diagnostic prints — `is_freeze` answers a bool and names nothing.
///
/// It renders NO `Ty`, deliberately. Rendering one runs `trimmed_def_paths`,
/// and running that query in a compilation that then emits no diagnostic is the
/// `trimmed_def_paths called, diagnostics were expected but none were emitted`
/// ICE; this walk runs on a hot path where the refusal is usually discarded.
fn trust_k2_no_inline_unsafe_cell<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    path: &str,
    depth: u32,
) -> Result<(), String> {
    const MAX_DEPTH: u32 = 24;
    if depth > MAX_DEPTH {
        return Err(format!("{path} (nested deeper than {MAX_DEPTH}; not classified)"));
    }
    match ty.kind() {
        ty::Bool | ty::Char | ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Str | ty::Never => {
            Ok(())
        }
        // A pointer ENDS the walk: its pointee is not inline in this type, so
        // no `UnsafeCell` behind it covers a byte this lane reads.
        ty::Ref(..) | ty::RawPtr(..) | ty::FnPtr(..) | ty::FnDef(..) => Ok(()),
        ty::Array(elem, _) | ty::Slice(elem) => {
            trust_k2_no_inline_unsafe_cell(tcx, *elem, &format!("{path}[]"), depth + 1)
        }
        // A pattern type is its BASE type refined by a value pattern; the
        // representation is the base's, so the base is exactly what to walk.
        // MEASURED: without this arm K2 refused `&Cursor` for
        // `Cursor { .., cells: Vec<u8> }` at
        // `cells.buf.inner.ptr.pointer.pointer`, because `NonNull`'s inner
        // pointer is a pattern type in this tree — a disagreement with the
        // trait solver (which answers `Freeze`) on EVERY pointee carrying a
        // `Vec`/`Box`/`String`. Fail-closed, so not a soundness hole, but it
        // refused a shape `Freeze` admits and `docs/design` had it recorded as
        // an unmeasured risk. It is the one gap the probes found.
        ty::Pat(base, _) => trust_k2_no_inline_unsafe_cell(tcx, *base, path, depth + 1),
        ty::Tuple(elems) => {
            for (index, elem) in elems.iter().enumerate() {
                trust_k2_no_inline_unsafe_cell(tcx, elem, &format!("{path}.{index}"), depth + 1)?;
            }
            Ok(())
        }
        ty::Adt(def, args) => {
            if def.is_unsafe_cell() {
                return Err(format!("{path} (an `UnsafeCell`)"));
            }
            if def.is_union() {
                return Err(format!("{path} (a union, whose fields alias)"));
            }
            // EVERY variant, not only the struct one: an inline enum field can
            // carry a cell in any of its constructors.
            for variant in def.variants().iter() {
                for field in &variant.fields {
                    trust_k2_no_inline_unsafe_cell(
                        tcx,
                        field.ty(tcx, *args).skip_normalization(),
                        &format!("{path}.{}", field.name),
                        depth + 1,
                    )?;
                }
            }
            Ok(())
        }
        // Everything else is refused, NAMED. "a shape the structural walk does
        // not classify" on its own sent a reader looking for a cell that is not
        // there; the label says which kind actually stopped the walk, and it is
        // a fixed string, so no `Ty` is rendered and no `trimmed_def_paths`
        // query runs (see this function's doc).
        _ => Err(format!("{path} ({})", trust_k2_unclassified_label(ty))),
    }
}

/// The fixed label for a type kind [`trust_k2_no_inline_unsafe_cell`] does not
/// walk. Renders no `Ty`.
fn trust_k2_unclassified_label(ty: Ty<'_>) -> &'static str {
    match ty.kind() {
        ty::Param(_) => "an undecided generic type parameter",
        ty::Alias(..) => "an unnormalized associated or opaque type",
        ty::Dynamic(..) => "a trait object",
        ty::Closure(..) | ty::CoroutineClosure(..) => "a closure capture set",
        ty::Coroutine(..) | ty::CoroutineWitness(..) => "a coroutine state",
        ty::Foreign(..) => "an extern type with no declared fields",
        ty::UnsafeBinder(..) => "an unsafe binder",
        ty::Error(..) => "an erroneous type",
        _ => "a shape the structural walk does not classify",
    }
}

/// The FROZEN SHARED PARAMETER table of `local`, plus one `D-REF` note per
/// reference parameter that did NOT get a row.
///
/// Computed once per function from `fn_sig` under
/// `TypingEnv::post_analysis(tcx, local)`; it needs no MIR body, so every
/// in-walk site can call it. A parameter gets a row only when ALL of:
///
/// * **C1** the type is `&T`, SHARED (`Mutability::Not`) — a `&mut` pointee may
///   differ at exit, and this lane models a function of ENTRY values;
/// * **C2** `T: Freeze`, `T: Sized`, and `T` carries no non-region parameter
///   (a generic `T`'s `Freeze` is not decidable here);
/// * **K2** the structural walk above finds no inline `UnsafeCell`;
/// * **C3** `T` is a `struct` (an enum's field is variant-relative; a union's
///   fields alias);
/// * the HIR pattern is a plain named binding (`p: &Point`, `&self`) — `_`,
///   `&x: &u64` and `&Point { x, .. }` bind no single name to prefix the rows
///   with, so there is no clause spelling to record;
/// * **at least ONE declared field of `T` is in the view vocabulary.** Since
///   I2 (disposition R4 — IMPLEMENTER-PROPOSED, not an owner ruling; see
///   `docs/TCB.md`) the others are SKIPPED rather than refusing the
///   parameter: `struct Parser { pos: usize, max: u32, buf: Vec<u8> }` yields
///   the `max` row and nothing for `buf`. I1's all-or-nothing rule D-REF-8 is
///   deleted, not relaxed — see the body for why the argument it rested on was
///   not the invariant that holds, and for what that makes load-bearing.
///
/// `explain` decides whether the D-REF notes are BUILT, and it is `false` on
/// every hot path for a reason that has bitten this file before: rendering a
/// `Ty` runs `trimmed_def_paths`, and running that query in a compilation that
/// then emits no diagnostic is the
/// `trimmed_def_paths called, diagnostics were expected but none were emitted`
/// ICE. This scan runs for EVERY contracted function through
/// `trust_fn_param_type_names`, where the notes are discarded; only the
/// diagnostic shortfall path asks for them, and it is already emitting.
fn trust_frozen_shared_param_scan(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    explain: bool,
) -> (trust_types::e6_param_view::FrozenSharedParams, Vec<String>) {
    use rustc_hir::PatKind;
    use trust_types::e6_param_view::{FrozenPointee, FrozenRow, FrozenSharedParams};

    let mut table = FrozenSharedParams::new();
    let mut notes: Vec<String> = Vec::new();
    // Every note below goes through this, so `explain == false` renders no `Ty`
    // at all — not merely "builds a string nobody reads".
    macro_rules! note {
        ($($arg:tt)*) => {
            if explain {
                notes.push(with_no_trimmed_paths!(format!($($arg)*)));
            }
        };
    }
    if !matches!(tcx.def_kind(local.to_def_id()), DefKind::Fn | DefKind::AssocFn) {
        return (table, notes);
    }
    let sig = tcx.fn_sig(local.to_def_id()).instantiate_identity().skip_binder();
    if !matches!(sig.abi(), rustc_abi::ExternAbi::Rust) {
        return (table, notes);
    }
    let Some(hir_body) = tcx.hir_maybe_body_owned_by(local) else {
        return (table, notes);
    };
    let inputs = sig.inputs();
    if hir_body.params.len() != inputs.len() {
        return (table, notes);
    }
    let typing_env = ty::TypingEnv::post_analysis(tcx, local.to_def_id());

    for (position, param) in hir_body.params.iter().enumerate() {
        let param_ty = inputs[position];
        // C1. Anything that is not a shared borrow is simply not this lane's;
        // a `&mut` gets the note because it is the shape authors reach for.
        let ty::Ref(_, pointee, mutability) = param_ty.kind() else {
            if matches!(param_ty.kind(), ty::RawPtr(..)) {
                note!(
                    "rule: a raw pointer carries no validity or aliasing guarantee, so its \
                     pointee has no value a clause can name; parameter {position} is \
                     `{param_ty}`. options: (1) take `&T` and let the caller do the unsafe \
                     conversion; (2) pass the scalars by value; (3) keep this clause solver-only"
                );
            }
            continue;
        };
        if *mutability != rustc_ast::Mutability::Not {
            note!(
                "rule: a borrowed parameter is E6-admitted only as a read-only shared borrow \
                 `&T` of a `Freeze` struct; parameter {position} is `{param_ty}`, a mutable \
                 borrow, and through `&mut` the pointee at exit may differ from the pointee at \
                 entry, while the Lean-citing lane models a function of ENTRY values only. \
                 options: (1) take `&self` instead if the body only reads; (2) move the \
                 read-only computation into a `&self` or by-value helper and put the \
                 Lean-citing clause there; (3) keep this clause solver-only (no island call, \
                 no `by <theorem>`): the native verifier handles `&mut` post-state with primes"
            );
            continue;
        }
        let pointee = *pointee;
        // C0 — ESCAPING BOUND VARS, decided before ANY trait-solver query.
        //
        // `fn_sig(..).instantiate_identity().skip_binder()` leaves a
        // signature's LATE-BOUND REGIONS as escaping bound vars in the types it
        // hands out. An ordinary `&'a Point` is fine (the POINTEE `Point`
        // mentions no binder), but `&'a dyn Widget` leaves `dyn Widget + 'a`
        // carrying one — and `Ty::is_sized` on such a type is an ICE, not a
        // `false`: "`<dyn sealed::Widget as Sized>` has escaping bound vars, so
        // it cannot be wrapped in a dummy binder"
        // (`rustc_middle/src/ty/predicate.rs`). MEASURED: it took down
        // `tests/ui/trust/trust_sealed_dyn_summary.rs` and
        // `contract_verify_off_no_ice.rs`, the second of which exists to pin
        // that this pass does not ICE.
        //
        // Refusing is exactly right on the merits too: a pointee whose type is
        // only meaningful under a binder has no fixed field list to flatten.
        if pointee.has_escaping_bound_vars() {
            note!(
                "rule: a shared borrow is admitted only for a pointee whose type is fixed by \
                 the signature alone; parameter {position} borrows a type that is meaningful \
                 only under the signature's own lifetime binder (a trait object, or a type \
                 naming a late-bound lifetime), so it has no fixed field list to read. \
                 options: (1) pass the scalars the contract needs by value; (2) keep this \
                 clause solver-only"
            );
            continue;
        }
        // C2, as THREE separate conditions with three separate notes. They were
        // one guard and one message, and the message was FALSE for two of the
        // three shapes it covered: `fn first(xs: &[u64])` got "`[u64]` is not
        // `Freeze`, so another alias may change the value" when `[u64]` IS
        // `Freeze` and is merely unsized. v7/D3 requires the rule, why THIS
        // program broke it, and the options; a message that states something
        // untrue about the author's type sends them to the wrong fix.
        if pointee.has_non_region_param() {
            note!(
                "rule: a shared borrow is admitted only for a pointee whose interior mutability \
                 is DECIDABLE here; parameter {position} borrows `{pointee}`, which still carries \
                 a generic type parameter, and `Freeze` for an uninstantiated parameter is not \
                 something this lane can answer. options: (1) write the Lean-citing contract on a \
                 concrete instantiation (a monomorphic wrapper or an inherent method on the \
                 concrete type); (2) pass the scalars the contract reads by value; (3) keep this \
                 clause solver-only"
            );
            continue;
        }
        if !pointee.is_sized(tcx, typing_env) {
            note!(
                "rule: a shared borrow is admitted only for a SIZED pointee with a fixed field \
                 list; parameter {position} borrows `{pointee}`, which is unsized — a slice or \
                 `str` has a length instead of declared fields, and this lane has no sequence \
                 carrier. NOTE this is not an interior-mutability refusal: `{pointee}` may well \
                 be `Freeze`. options: (1) contract a helper over the element or the length \
                 (`fn len(&self) -> usize`, `fn at(xs: &[u64], i: usize) -> u64`) and cite THAT; \
                 (2) pass the scalars the contract reads by value; (3) keep this clause \
                 solver-only"
            );
            continue;
        }
        if !pointee.is_freeze(tcx, typing_env) {
            let because = if explain {
                match trust_k2_no_inline_unsafe_cell(tcx, pointee, "", 0) {
                    // The walk's path is EMPTY when the pointee is itself the
                    // offender (`&UnsafeCell<u32>`); say so rather than printing
                    // `at  (an UnsafeCell)` with the field name missing.
                    Err(where_) => match where_.trim_start_matches('.').split_once(' ') {
                        Some((field, what)) if !field.is_empty() => {
                            format!(" (at field {field}, {})", what.trim_matches(['(', ')']))
                        }
                        _ => format!(" (it is itself {})", where_.trim().trim_matches(['(', ')'])),
                    },
                    Ok(()) => String::new(),
                }
            } else {
                String::new()
            };
            note!(
                "rule: entry == exit holds for a shared borrow only when the pointee is `Freeze` \
                 — no `UnsafeCell` inline anywhere in it; `{pointee}`{because} is not, so another \
                 alias may change the value DURING the call and a field of it has no single value \
                 a clause can name. options: (1) pass the scalars by value and contract a \
                 by-value helper; (2) split `{pointee}` into a frozen part (the fields the \
                 contract reads) and a cell part, and put the method on the frozen part; (3) keep \
                 this clause solver-only"
            );
            continue;
        }
        // K2, the second key. It can only refuse; a K2-only refusal is reported
        // AS a K2 refusal so a disagreement with the trait solver is visible.
        if let Err(path) = trust_k2_no_inline_unsafe_cell(tcx, pointee, "", 0) {
            note!(
                "rule: the structural interior-mutability walk (K2) refused `{pointee}` at \
                 {}, although the trait solver answered `Freeze`. This lane requires BOTH. \
                 options: (1) pass the scalars by value and contract a by-value helper; \
                 (2) keep this clause solver-only",
                path.trim_start_matches('.')
            );
            continue;
        }
        // C3.
        let ty::Adt(def, args) = pointee.kind() else {
            note!(
                "rule: a read-only borrow is admitted for a STRUCT pointee (`&Point`, `&self`); \
                 parameter {position} borrows `{pointee}`, which has no scalar-field reading in \
                 this fragment (a slice or `str` needs a sequence carrier, an enum field is \
                 variant-relative, a second indirection has no inline scalars, and a borrowed \
                 SCALAR awaits the clause-spelling ruling R5). options: (1) pass the scalars the \
                 contract needs by value; (2) for a slice, contract a helper over the element or \
                 the length; (3) keep this clause solver-only"
            );
            continue;
        };
        if !def.is_struct() {
            let why = if def.is_union() {
                "a union field aliases its siblings, so reading one does not name an independent \
                 value"
            } else {
                "an enum field is variant-relative and is reached through a `Downcast` this lane \
                 refuses"
            };
            note!(
                "rule: a read-only borrow is admitted for a STRUCT pointee (`&Point`, `&self`); \
                 `{pointee}` is not a struct — {why}. options: (1) pass the scalars the contract \
                 needs by value; (2) keep this clause solver-only"
            );
            continue;
        }
        // The HIR binding. `Pat::each_binding` is deliberately NOT used: a
        // pattern that binds several names has no single prefix for the rows.
        let PatKind::Binding(_, _, ident, None) = param.pat.kind else {
            note!(
                "rule: a borrowed parameter needs ONE name for its clause rows (`self.x`); the \
                 pattern of parameter {position} binds none. options: (1) name it \
                 (`p: &Point`) and read `p.x` in the body"
            );
            continue;
        };
        // The same recovery guard the by-value loop carries: an error path must
        // never reinterpret the return place as an input.
        if ident.name == sym::result || ident.name.as_str() == "_0" {
            continue;
        }
        // I2 (disposition R4 — IMPLEMENTER-PROPOSED, not an owner ruling; the
        // tree carries no R4 ruling text and `docs/TCB.md`'s
        // `EnsuresCitationViewDischarge` row says so): a declared field
        // outside the view vocabulary is
        // SKIPPED, and its scalar siblings still get rows. D-REF-8 — I1's
        // all-or-nothing rule, which refused the whole parameter here — is
        // GONE, and with it the note it printed.
        //
        // WHY THE REVERSAL IS SOUND, since the rule it replaces was justified
        // as a soundness property. D-REF-8 existed because the MINT side was
        // believed to recompute this same list and refuse a partial one, so a
        // partial table would bind clause names nothing minted. That is not the
        // shape of this lane:
        //
        //   * there is ONE filter, this loop. `trust_fn_param_type_names` reads
        //     the rows it produces; `e6_param_view` does not filter at all — it
        //     VERIFIES each listed row against the extracted IR (name, index,
        //     carrier) and refuses the WHOLE view on any disagreement, so a
        //     drift costs the capability and can never mint at a wrong field.
        //   * `clean_island::param_flat_rows`, the all-or-nothing flattening
        //     D-REF-8 was written for, never sees a borrow on this lane: the
        //     mint runs on the VIEW's body, whose parameters are already
        //     by-value scalars, so it takes its `ty_to_domain` arm per local.
        //   * a skipped field is never inspected by the view (it may be lowered
        //     opaquely), never named by a clause row, and — because the view's
        //     `read_place` admits only `[Deref, Field(k)]` for a LISTED `k` —
        //     a body that READS one refuses the whole view.
        //   * field names are unique within a struct and the rows keep DECLARED
        //     order, so a same-length reorder cannot pass the view's per-row
        //     name check. THAT CHECK IS THE ONLY NET, and the count is stated
        //     because an earlier draft of this comment claimed two:
        //     `Admission::param_names`' exact-list comparison in
        //     `elaborate_ensures` compares two lists that BOTH descend from
        //     this table — the clause side through
        //     `trust_fn_param_type_names`, the minted side through
        //     `e6_param_view`'s `param_names`, which is built from
        //     `pointee.rows` and not from the extracted field names. Sort the
        //     rows below by name instead of declared order and both lists move
        //     together; only the per-row name check notices. That comparison
        //     is real defence on the BY-VALUE lane, where `param_flat_rows`
        //     re-derives the list from the extracted IR.
        //
        // WHAT THIS MAKES LOAD-BEARING. `Cell<u32>` and `AtomicU32` are
        // `ty::Adt`s outside the vocabulary, so until now the carrier rule
        // refused a pointee carrying one as a SIBLING — a second net behind C2
        // and K2. From here that net is gone by construction: a `Cell` sibling
        // is skipped like any other unsupported field, and C2 (`is_freeze`)
        // plus K2 are the ONLY things refusing it. Neither is kernel-checked;
        // `docs/TCB.md`'s `EnsuresCitationViewDischarge` row says so, and probes
        // `f71`/`f84` with their `Freeze` twin `f85` are the differential.
        let mut rows = Vec::new();
        // Diagnostic only, and built only when a note is actually being
        // rendered — the same `trimmed_def_paths` rule the notes above follow.
        let mut skipped: Vec<String> = Vec::new();
        for (field_index, field) in def.non_enum_variant().fields.iter_enumerated() {
            // NOT normalized, exactly as `trust_param_scalar_rows`: an
            // unnormalized alias is not a `ty::Uint` and is refused, which can
            // lose a row but never invent one at the wrong carrier.
            let field_ty = field.ty(tcx, *args).skip_normalization();
            let Some(carrier) = trust_e6_view_carrier(field_ty) else {
                if explain {
                    skipped.push(with_no_trimmed_paths!(format!("`{}: {field_ty}`", field.name)));
                }
                continue;
            };
            rows.push(FrozenRow {
                field_index: field_index.as_usize(),
                field_name: field.name.to_string(),
                carrier: carrier.to_string(),
            });
        }
        if rows.is_empty() {
            note!(
                "rule: a frozen shared pointee contributes one clause binder per field in the \
                 scalar carrier vocabulary (`bool`, `u8`..`u128`, `i8`..`i128`); `{pointee}` \
                 declares no field in it{}. options: (1) pass the values the contract needs by \
                 value; (2) move the scalar fields the contract reads into their own struct and \
                 borrow that; (3) keep this clause solver-only",
                if skipped.is_empty() {
                    String::new()
                } else {
                    format!(" (every declared field is outside it: {})", skipped.join(", "))
                }
            );
            continue;
        }
        // A PARTIAL admission is a partial refusal, so say which fields fell
        // outside — a clause naming one is an unbound variable and a body
        // reading one loses the whole view, and neither refusal names the field
        // on its own. Emitted only alongside a shortfall that is already being
        // reported (`explain`), so no green output moves.
        if !skipped.is_empty() {
            note!(
                "rule: a frozen shared pointee contributes one clause binder per field in the \
                 scalar carrier vocabulary (`bool`, `u8`..`u128`, `i8`..`i128`); `{pointee}`'s \
                 field(s) {} are outside it and were SKIPPED, so `{}.<that field>` is not a \
                 binder any clause here can name, and a body that READS one is not admitted \
                 through the borrow-erased view at all. options: (1) state the contract over the \
                 scalar fields only; (2) read the value first and contract a by-value helper \
                 (`let n = {}.<that field>.len(); helper(n)`); (3) keep this clause solver-only",
                skipped.join(", "),
                ident.name,
                ident.name
            );
        }
        table.insert(
            position,
            FrozenPointee {
                param_name: ident.name.to_string(),
                adt_name: trust_frozen_pointee_ir_name(tcx, def.did()),
                rows,
            },
        );
    }
    (table, notes)
}

/// The name `trust-mir-extract` gives this ADT in the extracted IR, which is
/// what the view's C4 check compares against.
///
/// It calls the EXTRACTOR'S OWN function rather than restating it: a second
/// spelling of the same identity is how the two sides drift, and the failure
/// would be silent — a mismatch simply refuses the view, so the capability
/// disappears with no diagnostic anyone would connect to a renaming.
fn trust_frozen_pointee_ir_name(tcx: TyCtxt<'_>, did: DefId) -> String {
    trust_mir_extract::sysroot_authenticated_def_path_str(tcx, did)
}

/// [`trust_frozen_shared_param_scan`]'s table alone.
fn trust_frozen_shared_param_table(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
) -> trust_types::e6_param_view::FrozenSharedParams {
    trust_frozen_shared_param_scan(tcx, local, false).0
}

/// Trust (ref-self I1): whether `local`'s E9 discharges rest on the parameter
/// view, and therefore on ruling R1's aliasing assumption.
///
/// Keyed on the TABLE, not on whether the import minted. Every clause binder a
/// frozen shared parameter contributes (`self.x`) names a pointee VALUE at
/// entry, so the goal is a statement about entry values whether or not
/// `result` appears in it — an uncited `ensures self.x <= 5` rests on R1
/// exactly as `ensures result == id(self.x)` does. The `self_result_only` mark
/// is what makes this decidable from ONE function: no other function's view
/// import can enter this goal.
fn trust_e6_view_marker(tcx: TyCtxt<'_>, local: LocalDefId) -> Option<&'static str> {
    (!trust_frozen_shared_param_table(tcx, local).is_empty())
        .then_some(trust_types::e6_param_view::VIEW_MARKER)
}

/// Trust (ref-self I1): the borrow-erased view of `func`, or `None`.
///
/// `None` covers both "this function needs no view" and every refusal; a
/// refusal is printed under `TRUST_E6_DEBUG` and is otherwise invisible, since
/// the function then simply carries no kernel import exactly as before.
fn trust_e6_view_of(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    func: &trust_types::VerifiableFunction,
) -> Option<trust_types::e6_param_view::E6ParamView> {
    let table = trust_frozen_shared_param_table(tcx, local);
    match trust_types::e6_param_view::e6_param_view(func, &table) {
        Ok(view) => view,
        Err(refusal) => {
            if trust_env_var_present("TRUST_E6_DEBUG") {
                eprintln!("TRUST_E6_DEBUG param-view fn={} REFUSED: {refusal}", func.def_path);
            }
            None
        }
    }
}

/// Trust (ref-self I1): mint `func`'s parameter-view import into `env` and
/// record it in `table`, when `func` has one.
///
/// A no-op unless the function has a frozen shared parameter, and it never
/// overwrites an ordinary admission: the two are mutually exclusive by
/// construction (a body with a `Ty::Ref` local has no facets, so the ordinary
/// mint declines it), and the `has_admission` guard makes that structural
/// rather than argued.
fn trust_admit_param_view_into(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    func: &trust_types::VerifiableFunction,
    env: &mut trust_certify::clean_island::KernelEnvironment,
    table: &mut trust_spec_elab::FacetTable,
) {
    if table.has_admission(&func.def_path) {
        return;
    }
    let Some(view) = trust_e6_view_of(tcx, local, func) else {
        return;
    };
    let Some((path, admission)) =
        trust_certify::clean_island::admit_view_function_into(env, &view, table)
    else {
        return;
    };
    // Keyed under the def-path AND every spec spelling, exactly like the
    // ordinary mint loop. An ambiguity-evicted spelling carries no facet
    // record, so `FacetTable::admitted` still fails closed for it.
    for spelling in trust_spec_elab::spec_spellings(&path) {
        if spelling != path {
            table.admit(spelling, admission.clone());
        }
    }
    table.admit(path, admission);
}

fn trust_fn_param_type_names(tcx: TyCtxt<'_>, local: LocalDefId) -> Vec<(String, String)> {
    use rustc_hir::PatKind;

    let mut out = Vec::new();
    let Some(fn_decl) = tcx.hir_fn_decl_by_hir_id(tcx.local_def_id_to_hir_id(local)) else {
        return out;
    };
    let body = tcx.hir_body_owned_by(local);
    let typeck_results = tcx.typeck(local);
    // Trust (ref-self I1): the ONE table. A frozen shared parameter's rows come
    // from it; every other parameter keeps taking the UNCHANGED
    // `trust_param_scalar_rows`, which is not edited at all by this lane.
    let frozen = trust_frozen_shared_param_table(tcx, local);
    for (position, param) in body.params.iter().enumerate() {
        // A frozen shared parameter contributes ONE ROW PER LISTED FIELD, named
        // `self.x` — never a bare `self` row (there is no value to bind it to)
        // and never a row for a field the table did not list.
        if let Some(pointee) = frozen.get(&position) {
            out.extend(pointee.rows.iter().map(|row| {
                (format!("{}.{}", pointee.param_name, row.field_name), row.carrier.clone())
            }));
            continue;
        }
        if let PatKind::Binding(_, _, ident, _) = param.pat.kind
            // The `trust_contracts` query rejects the complete synthetic-name
            // namespace before producing a bundle. Keep this recovery guard so
            // an error path can never reinterpret the return place as an input.
            && ident.name != sym::result
            && ident.name.as_str() != "_0"
        {
            out.extend(trust_param_scalar_rows(
                tcx,
                ident.name.as_str(),
                typeck_results.pat_ty(param.pat),
            ));
        }
    }
    // `result` names the return value (E2); add it when the return type is a
    // supported primitive so `ensures result <= x` elaborates in-domain.
    if matches!(fn_decl.output, rustc_hir::FnRetTy::Return(_)) {
        // Same expansion the parameters get: a scalar return yields the bare
        // `result` row, and a struct return additionally yields `result.<field>`
        // for every field this lane can type. Without the struct case an
        // aggregate-returning function could carry no citable clause at all --
        // both `result.coeff <= degree` and its closure spelling were refused
        // out of the exact statement fragment, which is why SATURATE's per-term
        // step had to stay uncited.
        out.extend(trust_param_scalar_rows(
            tcx,
            "result",
            tcx.fn_sig(local.to_def_id()).instantiate_identity().skip_binder().output(),
        ));
    }
    out
}

/// Trust: [`trust_fn_param_type_names`] with pointer-sized rows resolved for
/// the E9 DISCHARGE lanes (the citation sweep, the in-walk and deferred
/// `ensures … by thm` discharges, and the uncited island-defeq discharge).
///
/// `trust-spec-elab` deliberately refuses a bare `usize`/`isize` binder: the
/// name does not say which carrier it means. The compiler is the only party
/// that knows, so it resolves the row HERE, from the compilation TARGET's data
/// layout — the same `pointer_size()` `trust-mir-extract` reads when it spells a
/// pointer-sized integer `Int { width, .. }`. That agreement is the point: a
/// discharge goal applies the function's E6 import to these binders, the import
/// is minted from the extracted body, and an admitted call is checked against
/// its declared carriers and never coerced — so `usize` on a 64-bit target binds
/// as `u64` (`UInt64`), exactly the carrier its import carries. See
/// `trust_spec_elab::discharge_binding_ty_for_target` for why this is not the
/// `usize64` (`BitVec 64`) spelling the statement-only lanes use, and for the
/// width argument: a theorem stated at 64 bits closes nothing on a 32-bit
/// target, where the same clause quantifies over `UInt32`.
///
/// Fail-closed: a pointer width the elaborator does not model leaves the bare
/// name in place, which the binding gate refuses as before.
///
/// NOT for the monitor lane or the uncited-denotation lane. Both resolve the
/// target themselves from a query-owned domain and compare against the RUST
/// spelling (`usize`) this table's unresolved form carries.
fn trust_fn_discharge_binder_types(tcx: TyCtxt<'_>, local: LocalDefId) -> Vec<(String, String)> {
    let mut rows = trust_fn_param_type_names(tcx, local);
    let Ok(pointer_width) = monitor_target_pointer_width(tcx) else {
        return rows;
    };
    for (_, ty) in &mut rows {
        let resolved = trust_spec_elab::discharge_binding_ty_for_target(ty.as_str(), pointer_width)
            .to_string();
        *ty = resolved;
    }
    rows
}

/// Trust: the note an E9 discharge REFUSAL on `clause` carries when THAT CLAUSE
/// mentions a pointer-sized binder, or `None` when it mentions none (every
/// existing diagnostic on a fixed-width function, and on a clause that names no
/// pointer-sized row, stays byte-identical).
///
/// [`trust_fn_discharge_binder_types`] resolves `usize` to the target's
/// fixed-width spelling, so an elaborator or kernel refusal downstream speaks of
/// `u64`/`UInt64` about a parameter the author wrote as `usize` — and the
/// natural first guesses for the Lean side (`USize`, `BitVec 64`, `Nat`) are all
/// carriers a clause is never coerced to. Diagnostic-only: it reads the same
/// two inputs the resolution reads and changes no verdict.
///
/// SCOPED TO THE CLAUSE on purpose. The refusals this hangs on have many causes
/// that have nothing to do with a carrier (an unadmitted callee, a wrong
/// theorem, a `result` the lane cannot bind), and a note whose "options" answer
/// a question the author did not ask is a misdirection, not a help (v7/D3). A
/// row counts as mentioned when its ROOT name — `p` for a `p.len: usize` field
/// row, `result` for `result.<field>` — appears as a bare identifier in the
/// clause text, which is the same hand lexer the island-call recognizer uses.
fn trust_pointer_sized_binder_note(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    clause: &str,
) -> Option<String> {
    let pointer_width = monitor_target_pointer_width(tcx).ok()?;
    let bits = pointer_width.bits();
    let mentioned = crate::trust_contract_query::bare_identifiers(clause);
    let mut resolved = Vec::new();
    for (name, ty) in trust_fn_param_type_names(tcx, local) {
        let carrier = match ty.as_str() {
            "usize" => format!("Clean carrier `UInt{bits}`"),
            "isize" => format!("Clean carrier `BitVec {bits}`, ordered as `i{bits}` is"),
            _ => continue,
        };
        let root = name.split('.').next().unwrap_or(name.as_str());
        if !mentioned.iter().any(|ident| ident == root) {
            continue;
        }
        let fixed = trust_spec_elab::discharge_binding_ty_for_target(ty.as_str(), pointer_width);
        resolved.push(format!("`{name}: {ty}` binds as `{fixed}` ({carrier})"));
    }
    if resolved.is_empty() {
        return None;
    }
    Some(format!(
        "on this {bits}-bit target {} — the carrier this function's kernel-imported definition \
         uses. options: (1) state the cited theorem or island definition over that carrier; \
         `USize`, `Nat`, and (for `usize`) `BitVec {bits}` are different carriers, and a clause is \
         never coerced to them; (2) a theorem stated at another width cannot discharge this \
         clause — restate it at {bits} bits for this target",
        resolved.join(", ")
    ))
}

/// Names of by-value params whose HIR binding is the plain immutable form
/// `BindingMode(ByRef::No, Mutability::Not)`. ONLY for these is the post-state
/// binding provably equal to entry — Rust rejects reassigning a non-`mut`
/// binding — so the `p'`→`p` collapse in the ensures-citation discharge
/// (`discharge_ensures_citations_in_walk`) is sound. A `mut` by-value param may
/// be reassigned (`bad(mut x){ x = 0; x }`), so its prime must NOT be collapsed;
/// it is excluded here and left to fail closed downstream (unbound `p'`).
fn trust_fn_collapsible_by_value_params(tcx: TyCtxt<'_>, local: LocalDefId) -> FxHashSet<String> {
    use rustc_ast::{ByRef, Mutability};
    use rustc_hir::{BindingMode, PatKind};

    let mut out = FxHashSet::default();
    let body = tcx.hir_body_owned_by(local);
    for param in body.params {
        if let PatKind::Binding(BindingMode(ByRef::No, Mutability::Not), _, ident, _) =
            param.pat.kind
        {
            out.insert(ident.name.to_string());
        }
    }
    out
}

fn trust_fn_monitor_places<'tcx>(
    tcx: TyCtxt<'tcx>,
    local: LocalDefId,
) -> FxHashMap<String, (Place<'tcx>, Ty<'tcx>)> {
    use rustc_hir::PatKind;

    let mut out = FxHashMap::default();
    let Some(fn_decl) = tcx.hir_fn_decl_by_hir_id(tcx.local_def_id_to_hir_id(local)) else {
        return out;
    };
    let body = tcx.hir_body_owned_by(local);
    let typeck_results = tcx.typeck(local);
    for (index, param) in body.params.iter().enumerate() {
        if let PatKind::Binding(_, _, ident, _) = param.pat.kind
            && ident.name != sym::result
            && ident.name.as_str() != "_0"
            && let Some(ty) = trust_resolved_scalar_type(typeck_results.pat_ty(param.pat))
                .and_then(|carrier| carrier.runtime_monitor_ty(tcx))
        {
            out.insert(ident.name.to_string(), (Place::from(Local::arg(index)), ty));
        }
    }
    if matches!(fn_decl.output, rustc_hir::FnRetTy::Return(_))
        && let Some(ty) = trust_resolved_scalar_type(
            tcx.fn_sig(local.to_def_id()).instantiate_identity().skip_binder().output(),
        )
        .and_then(|carrier| carrier.runtime_monitor_ty(tcx))
    {
        out.insert("result".to_string(), (Place::return_place(), ty));
    }
    out
}

fn source_scope_ancestor_distance(
    body: &Body<'_>,
    mut descendant: SourceScope,
    ancestor: SourceScope,
) -> Option<usize> {
    let mut distance = 0usize;
    loop {
        if descendant == ancestor {
            return Some(distance);
        }
        descendant = body.source_scopes[descendant].parent_scope?;
        distance = distance.checked_add(1)?;
    }
}

/// Rebind one query-authenticated loop clause environment to optimized MIR.
///
/// The query and MIR builder independently carry the same compiler-owned
/// HIR-local binding identity. We require one whole local with that identity,
/// a non-inlined source scope visible from the exact authenticated header, the
/// exact certified scalar type, and definite initialization at that header.
/// Optional debug names never participate. A missing or ambiguous row fails
/// closed; there is no span/name-only fallback.
fn trust_loop_monitor_places<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    header: BasicBlock,
    required: &BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>,
    source_bindings: &BTreeMap<String, u32>,
) -> Result<FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>, String> {
    let header_scope = body.basic_blocks[header].terminator().source_info.scope;
    let move_data = MoveData::gather_moves(body, tcx, |_| true);
    let mut maybe_uninit = MaybeUninitializedPlaces::new(tcx, body, &move_data)
        .iterate_to_fixpoint(tcx, body, Some("trust-certified-loop-monitor"))
        .into_results_cursor(body);
    maybe_uninit.seek_to_block_start(header);
    let uninitialized = maybe_uninit.get();

    let mut bindings = FxHashMap::default();
    for (name, domain) in required {
        let hir_local_id = source_bindings.get(name).ok_or_else(|| {
            format!("loop monitor variable `{name}` has no exact whole-scalar HIR source binding")
        })?;
        let expected_ty = runtime_monitor_domain_ty(tcx, *domain)?;
        let mut candidates = Vec::new();
        let mut identity_matches = 0usize;
        let mut non_inlined_matches = 0usize;
        let mut visible_scope_matches = 0usize;
        let mut type_matches = 0usize;
        let mut initialized_matches = 0usize;
        for (local, decl) in body.local_decls.iter_enumerated() {
            let candidate_hir_local_id = match &decl.local_info {
                ClearCrossCrate::Set(info) => match &**info {
                    LocalInfo::TrustSourceBinding { hir_local_id } => Some(*hir_local_id),
                    // Keep the helper valid at pre-cleanup test seams while
                    // making optimized MIR use the compact carrier.
                    LocalInfo::User(BindingForm::Var(binding)) => {
                        Some(binding.binding_hir_local_id.as_u32())
                    }
                    _ => None,
                },
                ClearCrossCrate::Clear => None,
            };
            if candidate_hir_local_id != Some(*hir_local_id) {
                continue;
            }
            identity_matches += 1;
            if decl.source_info.scope.inlined_instance(&body.source_scopes).is_some() {
                continue;
            }
            non_inlined_matches += 1;
            let Some(distance) =
                source_scope_ancestor_distance(body, header_scope, decl.source_info.scope)
            else {
                continue;
            };
            visible_scope_matches += 1;
            if decl.ty != expected_ty {
                continue;
            }
            type_matches += 1;
            let place = Place::from(local);
            let LookupResult::Exact(path) = move_data.rev_lookup.find(place.as_ref()) else {
                continue;
            };
            if uninitialized.contains(path) {
                continue;
            }
            initialized_matches += 1;
            candidates.push((distance, place));
        }
        candidates.sort_by_key(|(distance, place)| (*distance, place.local.as_usize()));
        candidates.dedup();
        let Some(best_distance) = candidates.first().map(|(distance, _)| *distance) else {
            return Err(format!(
                "no exact, initialized MIR source binding exists for loop monitor variable \
                 `{name}` (identity={identity_matches}, non-inlined={non_inlined_matches}, \
                 visible-scope={visible_scope_matches}, exact-type={type_matches}, \
                 initialized={initialized_matches})"
            ));
        };
        let mut best = candidates
            .iter()
            .filter(|(distance, _)| *distance == best_distance)
            .map(|(_, place)| *place);
        // Trust: REFUSE rather than panic. `best_distance` came from a
        // candidate, so this cannot miss — but this runs inside the compiler's
        // verification pass, where an abort takes the whole compilation down
        // mid-proof while an `Err` is just an undischarged obligation.
        let Some(place) = best.next() else {
            return Err(format!(
                "loop monitor variable `{name}` lost its closest MIR source binding \
                 while resolving"
            ));
        };
        if best.any(|candidate| candidate != place) {
            return Err(format!(
                "loop monitor variable `{name}` has multiple closest MIR source bindings"
            ));
        }
        bindings.insert(name.clone(), (place, expected_ty));
    }
    Ok(bindings)
}

/// Trust (identity binding, 2026-10-02): resolve every ROOT name of this body's loop
/// clauses to the MIR local its exact HIR binding denotes at the clause's loop header,
/// for `CompilerContractBundle::loop_clause_source_locals`.
///
/// The query's `source_place_bindings` name each root's HIR binding. A PARAMETER binds
/// by position (MIR locals `1..=arg_count` are the parameters in declaration order,
/// which every MIR pass preserves, and the `self` parameter carries no binding id). Any
/// other binding needs exactly one local carrying its identity
/// (`LocalInfo::TrustSourceBinding`, kept for bodies with loop clauses), declared in a
/// non-inlined scope visible from the header, of the binding's type, and initialized at
/// the header; the closest such local wins and a tie refuses. A name resolving to two
/// locals, a local claimed by two names, a missing header, or a clause whose binding map
/// is incomplete (`None`) maps to `None`: the name then binds nothing. Debug names never
/// participate. Rounds 37-43 found 18 ways a debug-name binding chose the wrong local.
fn resolve_loop_clause_source_locals<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    rustc_contracts: &TrustContractBundle<'tcx>,
    compiler_contracts: &trust_types::CompilerContractBundle,
) -> Option<BTreeMap<String, Option<usize>>> {
    use rustc_middle::mir::trust_contract::TrustContractSubject;

    if rustc_contracts.loop_contracts.is_empty() {
        return None;
    }
    fn root_of(name: &str) -> String {
        let cut = name.find(['*', '.', '[', '#', '@']).unwrap_or(name.len());
        let base = &name[..cut];
        base.strip_suffix("__slice_len")
            .or_else(|| base.strip_suffix("__len"))
            .unwrap_or(base)
            .to_string()
    }
    let mut table: BTreeMap<String, Option<usize>> = BTreeMap::new();
    let claim = |table: &mut BTreeMap<String, Option<usize>>, name: String, local| {
        use std::collections::btree_map::Entry;
        match table.entry(name) {
            Entry::Vacant(entry) => {
                entry.insert(local);
            }
            Entry::Occupied(mut entry) => {
                if *entry.get() != local {
                    entry.insert(None);
                }
            }
        }
    };
    let Some(local_def_id) = body.source.def_id().as_local() else {
        // Every name claims `None`, and `claim` keeps `None` once any sighting
        // stored it, so the free-variable set's order cannot reach the table.
        #[allow(rustc::potential_query_instability)]
        for spec in &compiler_contracts.loop_contracts {
            for name in trust_types::parse_spec_expr(&spec.body)
                .map(|f| f.free_variables())
                .unwrap_or_default()
            {
                claim(&mut table, root_of(&name), None);
            }
        }
        return Some(table);
    };
    let typeck_results = tcx.typeck(local_def_id);
    let owner = tcx.local_def_id_to_hir_id(local_def_id).owner;
    let mut parameter_locals: BTreeMap<u32, Local> = BTreeMap::new();
    let mut parameter_names: BTreeMap<String, Local> = BTreeMap::new();
    if let Some(hir_body) = tcx.hir_maybe_body_owned_by(local_def_id)
        && hir_body.params.len() == body.arg_count
    {
        for (index, param) in hir_body.params.iter().enumerate() {
            if let rustc_hir::PatKind::Binding(
                rustc_hir::BindingMode(rustc_hir::ByRef::No, _),
                hir_id,
                ident,
                None,
            ) = param.pat.kind
            {
                parameter_locals.insert(hir_id.local_id.as_u32(), Local::arg(index));
                parameter_names.insert(ident.name.to_string(), Local::arg(index));
            }
        }
    }
    // Every HIR binding of this body by name, with its span: the debug-row
    // fallback below needs a binding whose name and span no other binding shares.
    let mut same_name_bindings: BTreeMap<String, Vec<(u32, rustc_span::Span)>> = BTreeMap::new();
    if let Some(hir_body) = tcx.hir_maybe_body_owned_by(local_def_id) {
        struct Bindings<'a>(&'a mut BTreeMap<String, Vec<(u32, rustc_span::Span)>>);
        impl<'tcx> rustc_hir::intravisit::Visitor<'tcx> for Bindings<'_> {
            fn visit_pat(&mut self, pat: &'tcx rustc_hir::Pat<'tcx>) {
                if let rustc_hir::PatKind::Binding(_, hir_id, ident, _) = pat.kind {
                    self.0
                        .entry(ident.name.to_string())
                        .or_default()
                        .push((hir_id.local_id.as_u32(), pat.span));
                }
                rustc_hir::intravisit::walk_pat(self, pat);
            }
        }
        rustc_hir::intravisit::Visitor::visit_body(
            &mut Bindings(&mut same_name_bindings),
            hir_body,
        );
    }
    let move_data = MoveData::gather_moves(body, tcx, |_| true);
    let mut maybe_uninit = MaybeUninitializedPlaces::new(tcx, body, &move_data)
        .iterate_to_fixpoint(tcx, body, Some("trust-loop-clause-identity"))
        .into_results_cursor(body);
    // The converted loop contracts are index-aligned with the query's
    // (`bind_compiler_loop_contract_bundle` relies on the same alignment).
    for (index, contract) in rustc_contracts.loop_contracts.iter().enumerate() {
        let TrustContractSubject::HirLoop { id, .. } = contract.subject else { continue };
        let spec = compiler_contracts
            .loop_contracts
            .get(index)
            .filter(|spec| spec.source_loop_id == id.index);
        let header = spec.and_then(|spec| spec.mir_header).map(BasicBlock::from_usize);
        let Some(bindings) = &contract.predicate.source_place_bindings else {
            // Every name claims `None`, and `claim` keeps `None` once any sighting
            // stored it, so the free-variable set's order cannot reach the table.
            #[allow(rustc::potential_query_instability)]
            for spec in compiler_contracts
                .loop_contracts
                .iter()
                .filter(|spec| spec.source_loop_id == id.index)
            {
                for name in trust_types::parse_spec_expr(&spec.body)
                    .map(|f| f.free_variables())
                    .unwrap_or_default()
                {
                    claim(&mut table, root_of(&name), None);
                }
            }
            continue;
        };
        for binding in bindings {
            // Keyed by ROOT name: a reference binding's query spelling is `r*`, but
            // the local carries `r` (review round 47: keyed `r*`, the `r` debug name
            // was never stripped and a `*r` clause still bound by debug name).
            let name = root_of(binding.name.as_str());
            let Some(header) = header else {
                claim(&mut table, name, None);
                continue;
            };
            if let Some(local) = parameter_locals.get(&binding.hir_local_id) {
                claim(&mut table, name, Some(local.as_usize()));
                continue;
            }
            let expected_ty = typeck_results
                .node_type_opt(rustc_hir::HirId {
                    owner,
                    local_id: rustc_hir::ItemLocalId::from_u32(binding.hir_local_id),
                })
                .map(|ty| tcx.erase_and_anonymize_regions(ty));
            let Some(expected_ty) = expected_ty else {
                claim(&mut table, name, None);
                continue;
            };
            maybe_uninit.seek_to_block_start(header);
            let uninitialized = maybe_uninit.get();
            let header_scope = body.basic_blocks[header].terminator().source_info.scope;
            let mut candidates = Vec::new();
            for (local, decl) in body.local_decls.iter_enumerated() {
                let carried = match &decl.local_info {
                    ClearCrossCrate::Set(info) => match &**info {
                        LocalInfo::TrustSourceBinding { hir_local_id } => Some(*hir_local_id),
                        LocalInfo::User(BindingForm::Var(binding)) => {
                            Some(binding.binding_hir_local_id.as_u32())
                        }
                        _ => None,
                    },
                    ClearCrossCrate::Clear => None,
                };
                if carried != Some(binding.hir_local_id)
                    || decl.source_info.scope.inlined_instance(&body.source_scopes).is_some()
                    || tcx.erase_and_anonymize_regions(decl.ty) != expected_ty
                {
                    continue;
                }
                let Some(distance) =
                    source_scope_ancestor_distance(body, header_scope, decl.source_info.scope)
                else {
                    continue;
                };
                let place = Place::from(local);
                let LookupResult::Exact(path) = move_data.rev_lookup.find(place.as_ref()) else {
                    continue;
                };
                if uninitialized.contains(path) {
                    continue;
                }
                candidates.push((distance, local.as_usize()));
            }
            // CopyProp merges a single-assignment copy (`let alias = xs;`) into its
            // source and deletes the binding's own local, so no local carries the
            // identity; the binding's debug ROW survives, retargeted to the merged
            // local (an equal value: DestinationPropagation, which merges unequal
            // values, does not run while verifying). A row names its binding only
            // when NO other HIR binding of this body has the same name with an
            // overlapping span: review round 47 found a `macro_rules!` metavariable
            // giving every expansion the same span, and `one!(v, x); one!(v, 7)`
            // bound the first `v` (certified) while the `v` in scope is 7.
            if candidates.is_empty() {
                let binding_hir_id = rustc_hir::HirId {
                    owner,
                    local_id: rustc_hir::ItemLocalId::from_u32(binding.hir_local_id),
                };
                let pat_span = tcx.hir_span(binding_hir_id);
                let binding_name = name.as_str();
                let span_is_unique = same_name_bindings.get(binding_name).is_some_and(|spans| {
                    spans.iter().all(|(other, span)| {
                        *other == binding.hir_local_id
                            || !(span.overlaps(pat_span)
                                || span.contains(pat_span)
                                || pat_span.contains(*span))
                    })
                });
                let rows: Vec<(Local, SourceScope)> = if span_is_unique {
                    body.var_debug_info
                        .iter()
                        .filter(|row| {
                            row.name.as_str() == binding_name
                                && row.composite.is_none()
                                && !row.source_info.span.is_dummy()
                                && row.source_info.span.ctxt() == pat_span.ctxt()
                                && pat_span.contains(row.source_info.span)
                                && row
                                    .source_info
                                    .scope
                                    .inlined_instance(&body.source_scopes)
                                    .is_none()
                        })
                        .filter_map(|row| match &row.value {
                            VarDebugInfoContents::Place(place) if place.projection.is_empty() => {
                                Some((place.local, row.source_info.scope))
                            }
                            _ => None,
                        })
                        .collect()
                } else {
                    Vec::new()
                };
                if let [(local, row_scope)] = rows.as_slice() {
                    let decl = &body.local_decls[*local];
                    let place = Place::from(*local);
                    let visible = source_scope_ancestor_distance(body, header_scope, *row_scope);
                    let initialized = match move_data.rev_lookup.find(place.as_ref()) {
                        LookupResult::Exact(path) => !uninitialized.contains(path),
                        LookupResult::Parent(_) => false,
                    };
                    if let Some(distance) = visible
                        && initialized
                        && tcx.erase_and_anonymize_regions(decl.ty) == expected_ty
                    {
                        candidates.push((distance, local.as_usize()));
                    }
                }
            }
            candidates.sort();
            candidates.dedup();
            let resolved = match candidates.as_slice() {
                [(distance, local), rest @ ..]
                    if rest.first().is_none_or(|(next, _)| next != distance) =>
                {
                    Some(*local)
                }
                _ => None,
            };
            claim(&mut table, name, resolved);
        }
    }
    // A name that is also a PARAMETER's source name keeps meaning that parameter:
    // extraction writes the table onto the locals that function `requires`/`ensures`
    // also bind by name, so a loop clause on a shadow (`let n = ..` in an inner
    // block) handed `n` to the shadow and `ensures result == n` was proved about it,
    // certified, while a caller divided by zero (review round 47). Resolving it
    // elsewhere refuses both clauses instead.
    for (name, target) in table.iter_mut() {
        if let Some(param) = parameter_names.get(name)
            && *target != Some(param.as_usize())
        {
            *target = None;
        }
    }
    // One local carries one name: two names resolving to the same local both refuse.
    let mut by_local: BTreeMap<usize, usize> = BTreeMap::new();
    for local in table.values().flatten() {
        *by_local.entry(*local).or_default() += 1;
    }
    for target in table.values_mut() {
        if target.is_some_and(|local| by_local.get(&local).copied().unwrap_or(0) > 1) {
            *target = None;
        }
    }
    Some(table)
}

fn monitor_target_pointer_width(
    tcx: TyCtxt<'_>,
) -> Result<trust_spec_elab::TargetPointerWidth, String> {
    let bits = u32::try_from(tcx.data_layout.pointer_size().bits())
        .map_err(|_| "target pointer width does not fit u32".to_string())?;
    trust_spec_elab::TargetPointerWidth::from_bits(bits)
}

fn monitor_var_types_from_static(
    proposition: &StaticMonitorProposition,
    pointer_width: trust_spec_elab::TargetPointerWidth,
) -> Result<Vec<(String, String)>, String> {
    use trust_types::CompilerContractValueDomain as Domain;

    let mut out = Vec::with_capacity(proposition.variable_domains.len());
    for entry in &proposition.variable_domains {
        let ty = match entry.domain {
            Domain::Bool => "bool".to_string(),
            // An executable monitor for a float clause would have to reproduce
            // IEEE comparison exactly, NaN and both zeroes included, and a Rust
            // `f32`/`f64` expression does not do that for `==` the way the
            // static form does. Decline the monitor rather than emit one whose
            // runtime answer can differ from the proof's.
            Domain::Float { .. } => {
                return Err(format!(
                    "static source domain {:?} has no exact Rust monitor type",
                    entry.domain
                ));
            }
            Domain::MachineInt { width, signed } => match (width, signed) {
                (8 | 16 | 32 | 64 | 128, false) => format!("u{width}"),
                (8 | 16 | 32 | 64 | 128, true) => format!("i{width}"),
                _ => {
                    return Err(format!(
                        "static source domain {:?} has no exact Rust monitor type",
                        entry.domain
                    ));
                }
            },
            Domain::PointerSizedInt { width, signed } if width == pointer_width.bits() => {
                if signed { "isize".to_string() } else { "usize".to_string() }
            }
            Domain::PointerSizedInt { width, .. } => {
                return Err(format!(
                    "static pointer domain is {width}-bit but compilation target is {}-bit",
                    pointer_width.bits()
                ));
            }
            Domain::MathematicalInt => {
                return Err(format!(
                    "static variable `{}` has no lossless Rust runtime carrier",
                    entry.name
                ));
            }
        };
        let name = monitor_formula_variable_name(&entry.name).to_string();
        if out.iter().any(|(existing, _)| existing == &name) {
            return Err(format!("static monitor binding `{name}` is duplicated"));
        }
        out.push((name, ty));
    }
    Ok(out)
}

fn runtime_monitor_domain_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    domain: trust_spec_elab::RuntimeMonitorDomain,
) -> Result<Ty<'tcx>, String> {
    use trust_spec_elab::RuntimeMonitorDomain;
    Ok(match domain {
        RuntimeMonitorDomain::U8 => tcx.types.u8,
        RuntimeMonitorDomain::U16 => tcx.types.u16,
        RuntimeMonitorDomain::U32 => tcx.types.u32,
        RuntimeMonitorDomain::U64 => tcx.types.u64,
        RuntimeMonitorDomain::U128 => tcx.types.u128,
        RuntimeMonitorDomain::I8 => tcx.types.i8,
        RuntimeMonitorDomain::I16 => tcx.types.i16,
        RuntimeMonitorDomain::I32 => tcx.types.i32,
        RuntimeMonitorDomain::I64 => tcx.types.i64,
        RuntimeMonitorDomain::I128 => tcx.types.i128,
        RuntimeMonitorDomain::USize16
        | RuntimeMonitorDomain::USize32
        | RuntimeMonitorDomain::USize64 => {
            let expected = match domain {
                RuntimeMonitorDomain::USize16 => 16,
                RuntimeMonitorDomain::USize32 => 32,
                RuntimeMonitorDomain::USize64 => 64,
                // Trust: the outer arm restricted `domain` to the three
                // USize carriers. Refuse rather than abort.
                _ => {
                    return Err("certified monitor carrier: unexpected USize domain".to_string());
                }
            };
            if tcx.data_layout.pointer_size().bits() != expected {
                return Err(format!(
                    "certified usize monitor carrier is {expected}-bit but the target pointer width is {}",
                    tcx.data_layout.pointer_size().bits()
                ));
            }
            tcx.types.usize
        }
        RuntimeMonitorDomain::ISize16
        | RuntimeMonitorDomain::ISize32
        | RuntimeMonitorDomain::ISize64 => {
            let expected = match domain {
                RuntimeMonitorDomain::ISize16 => 16,
                RuntimeMonitorDomain::ISize32 => 32,
                RuntimeMonitorDomain::ISize64 => 64,
                // Trust: the outer arm restricted `domain` to the three
                // ISize carriers. Refuse rather than abort.
                _ => {
                    return Err("certified monitor carrier: unexpected ISize domain".to_string());
                }
            };
            if tcx.data_layout.pointer_size().bits() != expected {
                return Err(format!(
                    "certified isize monitor carrier is {expected}-bit but the target pointer width is {}",
                    tcx.data_layout.pointer_size().bits()
                ));
            }
            tcx.types.isize
        }
        RuntimeMonitorDomain::Bool => tcx.types.bool,
        RuntimeMonitorDomain::Nat => {
            return Err("Nat monitor has no lossless Rust runtime carrier".to_string());
        }
    })
}

fn monitor_const_operand<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    value: u128,
    ty: Ty<'tcx>,
    span: rustc_span::Span,
) -> Operand<'tcx> {
    Operand::Constant(Box::new(rustc_middle::mir::ConstOperand {
        span,
        user_ty: None,
        const_: Const::from_bits(tcx, value, body.typing_env(tcx), ty),
    }))
}

fn monitor_temp<'tcx>(body: &mut Body<'tcx>, ty: Ty<'tcx>, source_info: SourceInfo) -> Place<'tcx> {
    Place::from(body.local_decls.push(LocalDecl::with_source_info(ty, source_info)))
}

fn collect_runtime_monitor_term_domain(
    domains: &BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>,
    expr: &trust_spec_elab::RuntimeMonitorExpr,
    found: &mut Option<trust_spec_elab::RuntimeMonitorDomain>,
) -> Result<(), String> {
    use trust_spec_elab::RuntimeMonitorExpr;
    match expr {
        RuntimeMonitorExpr::Var(name) => {
            let domain = domains
                .get(name)
                .copied()
                .ok_or_else(|| format!("certified monitor has no domain for `{name}`"))?;
            match found {
                None => *found = Some(domain),
                Some(expected) if *expected == domain => {}
                Some(expected) => {
                    return Err(format!(
                        "certified monitor atom mixes domains {expected:?} and {domain:?}"
                    ));
                }
            }
            Ok(())
        }
        RuntimeMonitorExpr::Zero | RuntimeMonitorExpr::Lit(_) => Ok(()),
        RuntimeMonitorExpr::Add(lhs, rhs)
        | RuntimeMonitorExpr::Sub(lhs, rhs)
        | RuntimeMonitorExpr::Mul(lhs, rhs)
        | RuntimeMonitorExpr::Div(lhs, rhs)
        | RuntimeMonitorExpr::Rem(lhs, rhs)
        | RuntimeMonitorExpr::BitAnd(lhs, rhs)
        | RuntimeMonitorExpr::BitOr(lhs, rhs)
        | RuntimeMonitorExpr::BitXor(lhs, rhs) => {
            collect_runtime_monitor_term_domain(domains, lhs, found)?;
            collect_runtime_monitor_term_domain(domains, rhs, found)
        }
        _ => Err("certified monitor proposition used where a term was required".to_string()),
    }
}

fn runtime_monitor_atom_domain(
    domains: &BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>,
    lhs: &trust_spec_elab::RuntimeMonitorExpr,
    rhs: &trust_spec_elab::RuntimeMonitorExpr,
) -> Result<trust_spec_elab::RuntimeMonitorDomain, String> {
    let mut found = None;
    collect_runtime_monitor_term_domain(domains, lhs, &mut found)?;
    collect_runtime_monitor_term_domain(domains, rhs, &mut found)?;
    Ok(found.unwrap_or(trust_spec_elab::RuntimeMonitorDomain::Nat))
}

fn runtime_monitor_literal_fits(
    value: u128,
    domain: trust_spec_elab::RuntimeMonitorDomain,
) -> bool {
    use trust_spec_elab::RuntimeMonitorDomain as Domain;
    value
        <= match domain {
            Domain::Nat | Domain::U128 | Domain::I128 => u128::MAX,
            Domain::U8 => u128::from(u8::MAX),
            Domain::U16 | Domain::USize16 => u128::from(u16::MAX),
            Domain::U32 | Domain::USize32 => u128::from(u32::MAX),
            Domain::U64 | Domain::USize64 => u128::from(u64::MAX),
            Domain::I8 => u128::from(u8::MAX),
            Domain::I16 | Domain::ISize16 => u128::from(u16::MAX),
            Domain::I32 | Domain::ISize32 => u128::from(u32::MAX),
            Domain::I64 | Domain::ISize64 => u128::from(u64::MAX),
            Domain::Bool => 1,
        }
}

fn emit_monitor_term<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &mut Body<'tcx>,
    source_info: SourceInfo,
    domains: &BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>,
    expr: &trust_spec_elab::RuntimeMonitorExpr,
    domain: trust_spec_elab::RuntimeMonitorDomain,
    domain_ty: Ty<'tcx>,
    bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    statements: &mut Vec<Statement<'tcx>>,
) -> Result<Operand<'tcx>, String> {
    use trust_spec_elab::{RuntimeMonitorDomain, RuntimeMonitorExpr};
    match expr {
        RuntimeMonitorExpr::Var(name) => {
            if domains.get(name).copied() != Some(domain) {
                return Err(format!(
                    "certified monitor variable `{name}` is not bound to atom domain {domain:?}"
                ));
            }
            let &(place, actual_ty) = bindings
                .get(name)
                .ok_or_else(|| format!("no MIR binding for certified monitor variable `{name}`"))?;
            if actual_ty != domain_ty {
                return Err(format!(
                    "certified monitor variable `{name}` changed type ({actual_ty:?}, expected {domain_ty:?})"
                ));
            }
            Ok(Operand::Copy(place))
        }
        RuntimeMonitorExpr::Zero => {
            Ok(monitor_const_operand(tcx, body, 0, domain_ty, source_info.span))
        }
        RuntimeMonitorExpr::Lit(value) => {
            if !runtime_monitor_literal_fits(*value, domain) {
                return Err(format!(
                    "certified monitor literal {value} is out of range for {domain:?}"
                ));
            }
            Ok(monitor_const_operand(tcx, body, *value, domain_ty, source_info.span))
        }
        RuntimeMonitorExpr::Add(lhs, rhs)
        | RuntimeMonitorExpr::Sub(lhs, rhs)
        | RuntimeMonitorExpr::Mul(lhs, rhs)
        | RuntimeMonitorExpr::Div(lhs, rhs)
        | RuntimeMonitorExpr::Rem(lhs, rhs)
        | RuntimeMonitorExpr::BitAnd(lhs, rhs)
        | RuntimeMonitorExpr::BitOr(lhs, rhs)
        | RuntimeMonitorExpr::BitXor(lhs, rhs) => {
            if domain == RuntimeMonitorDomain::Bool {
                return Err("arithmetic is not supported for a Bool monitor atom".to_string());
            }
            if matches!(expr, RuntimeMonitorExpr::Div(..) | RuntimeMonitorExpr::Rem(..))
                && !matches!(&**rhs, RuntimeMonitorExpr::Lit(value) if *value > 0)
            {
                return Err(
                    "monitor division/remainder requires a positive literal divisor".to_string()
                );
            }
            if runtime_monitor_domain_is_signed(domain)
                && matches!(expr, RuntimeMonitorExpr::Div(..) | RuntimeMonitorExpr::Rem(..))
            {
                return Err(
                    "signed monitor division/remainder is outside the certified runtime fragment"
                        .to_string(),
                );
            }
            let op = match expr {
                RuntimeMonitorExpr::Add(..) => MirBinOp::Add,
                RuntimeMonitorExpr::Sub(..) => MirBinOp::Sub,
                RuntimeMonitorExpr::Mul(..) => MirBinOp::Mul,
                RuntimeMonitorExpr::Div(..) => MirBinOp::Div,
                RuntimeMonitorExpr::Rem(..) => MirBinOp::Rem,
                RuntimeMonitorExpr::BitAnd(..) => MirBinOp::BitAnd,
                RuntimeMonitorExpr::BitOr(..) => MirBinOp::BitOr,
                RuntimeMonitorExpr::BitXor(..) => MirBinOp::BitXor,
                _ => unreachable!(),
            };
            let lhs = emit_monitor_term(
                tcx,
                body,
                source_info,
                domains,
                lhs,
                domain,
                domain_ty,
                bindings,
                statements,
            )?;
            let rhs = emit_monitor_term(
                tcx,
                body,
                source_info,
                domains,
                rhs,
                domain,
                domain_ty,
                bindings,
                statements,
            )?;
            let dest = monitor_temp(body, domain_ty, source_info);
            statements.push(Statement::new(
                source_info,
                StatementKind::Assign(Box::new((dest, Rvalue::BinaryOp(op, Box::new((lhs, rhs)))))),
            ));
            Ok(Operand::Copy(dest))
        }
        _ => Err("certified monitor proposition used where a term was required".to_string()),
    }
}

fn emit_measure_value<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &mut Body<'tcx>,
    source_info: SourceInfo,
    measure: &trust_spec_elab::RuntimeScalarTerm,
    bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    statements: &mut Vec<Statement<'tcx>>,
) -> Result<(Operand<'tcx>, Ty<'tcx>), String> {
    if measure.variables().is_empty() {
        let value = measure.evaluate(&[])?;
        let ty = if measure.domain() == trust_spec_elab::RuntimeMonitorDomain::Nat {
            tcx.types.u128
        } else {
            runtime_monitor_domain_ty(tcx, measure.domain())?
        };
        if !runtime_monitor_literal_fits(value, measure.domain()) {
            return Err(format!(
                "closed certified measure value {value} is outside {:?}",
                measure.domain()
            ));
        }
        return Ok((monitor_const_operand(tcx, body, value, ty, source_info.span), ty));
    }
    if measure.domain() == trust_spec_elab::RuntimeMonitorDomain::Nat {
        return Err(
            "a variable-bearing Nat measure has no lossless Rust runtime carrier".to_string()
        );
    }
    let ty = runtime_monitor_domain_ty(tcx, measure.domain())?;
    let value = emit_monitor_term(
        tcx,
        body,
        source_info,
        measure.domains(),
        measure.expr(),
        measure.domain(),
        ty,
        bindings,
        statements,
    )?;
    Ok((value, ty))
}

fn emit_monitor_prop<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &mut Body<'tcx>,
    source_info: SourceInfo,
    monitor: &trust_spec_elab::RuntimeMonitor,
    expr: &trust_spec_elab::RuntimeMonitorExpr,
    bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    statements: &mut Vec<Statement<'tcx>>,
) -> Result<Operand<'tcx>, String> {
    use trust_spec_elab::{RuntimeMonitorDomain, RuntimeMonitorExpr};
    match expr {
        RuntimeMonitorExpr::Eq(lhs, rhs)
        | RuntimeMonitorExpr::Le(lhs, rhs)
        | RuntimeMonitorExpr::Lt(lhs, rhs)
        | RuntimeMonitorExpr::Ge(lhs, rhs)
        | RuntimeMonitorExpr::Gt(lhs, rhs) => {
            let domain = runtime_monitor_atom_domain(monitor.domains(), lhs, rhs)?;
            if domain == RuntimeMonitorDomain::Nat {
                return Err(
                    "a variable-free Nat monitor must be constant-folded before MIR emission"
                        .to_string(),
                );
            }
            if domain == RuntimeMonitorDomain::Bool && !matches!(expr, RuntimeMonitorExpr::Eq(..)) {
                return Err("Bool monitor values are not ordered".to_string());
            }
            let domain_ty = runtime_monitor_domain_ty(tcx, domain)?;
            let op = match expr {
                RuntimeMonitorExpr::Eq(..) => MirBinOp::Eq,
                RuntimeMonitorExpr::Le(..) => MirBinOp::Le,
                RuntimeMonitorExpr::Lt(..) => MirBinOp::Lt,
                RuntimeMonitorExpr::Ge(..) => MirBinOp::Ge,
                RuntimeMonitorExpr::Gt(..) => MirBinOp::Gt,
                _ => unreachable!(),
            };
            let lhs = emit_monitor_term(
                tcx,
                body,
                source_info,
                monitor.domains(),
                lhs,
                domain,
                domain_ty,
                bindings,
                statements,
            )?;
            let rhs = emit_monitor_term(
                tcx,
                body,
                source_info,
                monitor.domains(),
                rhs,
                domain,
                domain_ty,
                bindings,
                statements,
            )?;
            let dest = monitor_temp(body, tcx.types.bool, source_info);
            statements.push(Statement::new(
                source_info,
                StatementKind::Assign(Box::new((dest, Rvalue::BinaryOp(op, Box::new((lhs, rhs)))))),
            ));
            Ok(Operand::Copy(dest))
        }
        RuntimeMonitorExpr::And(lhs, rhs) | RuntimeMonitorExpr::Or(lhs, rhs) => {
            let op = if matches!(expr, RuntimeMonitorExpr::And(..)) {
                MirBinOp::BitAnd
            } else {
                MirBinOp::BitOr
            };
            let lhs =
                emit_monitor_prop(tcx, body, source_info, monitor, lhs, bindings, statements)?;
            let rhs =
                emit_monitor_prop(tcx, body, source_info, monitor, rhs, bindings, statements)?;
            let dest = monitor_temp(body, tcx.types.bool, source_info);
            statements.push(Statement::new(
                source_info,
                StatementKind::Assign(Box::new((dest, Rvalue::BinaryOp(op, Box::new((lhs, rhs)))))),
            ));
            Ok(Operand::Copy(dest))
        }
        RuntimeMonitorExpr::Not(inner) => {
            let inner =
                emit_monitor_prop(tcx, body, source_info, monitor, inner, bindings, statements)?;
            let dest = monitor_temp(body, tcx.types.bool, source_info);
            statements.push(Statement::new(
                source_info,
                StatementKind::Assign(Box::new((dest, Rvalue::UnaryOp(UnOp::Not, inner)))),
            ));
            Ok(Operand::Copy(dest))
        }
        _ => Err("certified monitor term used where a proposition was required".to_string()),
    }
}

fn append_monitor_chain<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &mut Body<'tcx>,
    helper: DefId,
    monitors: &[&trust_spec_elab::RuntimeMonitor],
    bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    final_target: BasicBlock,
    source_info: SourceInfo,
) -> Result<BasicBlock, String> {
    let mut next = final_target;
    for monitor in monitors.iter().rev() {
        let mut statements = Vec::new();
        let cond = if monitor.variables().is_empty() {
            let value = monitor.evaluate(&[])?;
            monitor_const_operand(tcx, body, u128::from(value), tcx.types.bool, source_info.span)
        } else {
            emit_monitor_prop(
                tcx,
                body,
                source_info,
                monitor,
                monitor.expr(),
                bindings,
                &mut statements,
            )?
        };
        let destination = monitor_temp(body, tcx.types.unit, source_info);
        let term = Terminator {
            source_info,
            kind: TerminatorKind::Call {
                func: Operand::function_handle(tcx, helper, &[], source_info.span),
                args: [Spanned { node: cond, span: source_info.span }].into(),
                destination,
                target: Some(next),
                unwind: UnwindAction::Continue,
                call_source: CallSource::Misc,
                fn_span: source_info.span,
            },
        };
        next =
            body.basic_blocks_mut().push(BasicBlockData::new_stmts(statements, Some(term), false));
    }
    Ok(next)
}

fn append_measure_snapshot_block<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &mut Body<'tcx>,
    measure: &trust_spec_elab::RuntimeScalarTerm,
    bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    previous: Place<'tcx>,
    previous_ty: Ty<'tcx>,
    final_target: BasicBlock,
    source_info: SourceInfo,
) -> Result<BasicBlock, String> {
    let mut statements = Vec::new();
    let (value, ty) =
        emit_measure_value(tcx, body, source_info, measure, bindings, &mut statements)?;
    if ty != previous_ty {
        return Err(format!(
            "certified measure changed MIR carrier ({ty:?}, expected {previous_ty:?})"
        ));
    }
    statements.push(Statement::new(
        source_info,
        StatementKind::Assign(Box::new((previous, Rvalue::Use(value, WithRetag::No)))),
    ));
    Ok(body.basic_blocks_mut().push(BasicBlockData::new_stmts(
        statements,
        Some(Terminator {
            source_info,
            kind: TerminatorKind::Goto {
                target: final_target,
                loop_hint_attrs: Default::default(),
            },
        }),
        false,
    )))
}

fn append_measure_backedge_block<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &mut Body<'tcx>,
    helper: DefId,
    measure: &trust_spec_elab::RuntimeScalarTerm,
    bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    previous: Place<'tcx>,
    previous_ty: Ty<'tcx>,
    final_target: BasicBlock,
    source_info: SourceInfo,
) -> Result<BasicBlock, String> {
    let mut statements = Vec::new();
    let (current, ty) =
        emit_measure_value(tcx, body, source_info, measure, bindings, &mut statements)?;
    if ty != previous_ty {
        return Err(format!(
            "certified measure changed MIR carrier ({ty:?}, expected {previous_ty:?})"
        ));
    }
    let decreasing = monitor_temp(body, tcx.types.bool, source_info);
    statements.push(Statement::new(
        source_info,
        StatementKind::Assign(Box::new((
            decreasing,
            Rvalue::BinaryOp(MirBinOp::Lt, Box::new((current.clone(), Operand::Copy(previous)))),
        ))),
    ));
    let condition = if runtime_monitor_domain_is_signed(measure.domain()) {
        // E5's signed violation formula is `pre < 0 ∨ post >= pre`.
        // Its executable success condition is therefore exactly
        // `pre >= 0 ∧ post < pre`.
        let nonnegative = monitor_temp(body, tcx.types.bool, source_info);
        statements.push(Statement::new(
            source_info,
            StatementKind::Assign(Box::new((
                nonnegative,
                Rvalue::BinaryOp(
                    MirBinOp::Ge,
                    Box::new((
                        Operand::Copy(previous),
                        monitor_const_operand(tcx, body, 0, previous_ty, source_info.span),
                    )),
                ),
            ))),
        ));
        let combined = monitor_temp(body, tcx.types.bool, source_info);
        statements.push(Statement::new(
            source_info,
            StatementKind::Assign(Box::new((
                combined,
                Rvalue::BinaryOp(
                    MirBinOp::BitAnd,
                    Box::new((Operand::Copy(nonnegative), Operand::Copy(decreasing))),
                ),
            ))),
        ));
        Operand::Copy(combined)
    } else {
        Operand::Copy(decreasing)
    };

    let update = body.basic_blocks_mut().push(BasicBlockData::new_stmts(
        vec![Statement::new(
            source_info,
            StatementKind::Assign(Box::new((previous, Rvalue::Use(current, WithRetag::No)))),
        )],
        Some(Terminator {
            source_info,
            kind: TerminatorKind::Goto {
                target: final_target,
                loop_hint_attrs: Default::default(),
            },
        }),
        false,
    ));
    let destination = monitor_temp(body, tcx.types.unit, source_info);
    Ok(body.basic_blocks_mut().push(BasicBlockData::new_stmts(
        statements,
        Some(Terminator {
            source_info,
            kind: TerminatorKind::Call {
                func: Operand::function_handle(tcx, helper, &[], source_info.span),
                args: [Spanned { node: condition, span: source_info.span }].into(),
                destination,
                target: Some(update),
                unwind: UnwindAction::Continue,
                call_source: CallSource::Misc,
                fn_span: source_info.span,
            },
        }),
        false,
    )))
}

/// Check one function-recursion E5 edge against the measure captured at
/// function entry. The call-site bindings denote the recursive arguments, so
/// this implements exactly `entry >= 0 && call < entry` for signed carriers
/// and `call < entry` for unsigned carriers.
fn append_recursion_measure_check_block<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &mut Body<'tcx>,
    helper: DefId,
    measure: &trust_spec_elab::RuntimeScalarTerm,
    call_bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    entry: Place<'tcx>,
    entry_ty: Ty<'tcx>,
    final_target: BasicBlock,
    source_info: SourceInfo,
) -> Result<BasicBlock, String> {
    let mut statements = Vec::new();
    let (call_value, ty) =
        emit_measure_value(tcx, body, source_info, measure, call_bindings, &mut statements)?;
    if ty != entry_ty {
        return Err(format!(
            "certified recursion measure changed MIR carrier ({ty:?}, expected {entry_ty:?})"
        ));
    }
    let decreasing = monitor_temp(body, tcx.types.bool, source_info);
    statements.push(Statement::new(
        source_info,
        StatementKind::Assign(Box::new((
            decreasing,
            Rvalue::BinaryOp(MirBinOp::Lt, Box::new((call_value, Operand::Copy(entry)))),
        ))),
    ));
    let condition = if runtime_monitor_domain_is_signed(measure.domain()) {
        let nonnegative = monitor_temp(body, tcx.types.bool, source_info);
        statements.push(Statement::new(
            source_info,
            StatementKind::Assign(Box::new((
                nonnegative,
                Rvalue::BinaryOp(
                    MirBinOp::Ge,
                    Box::new((
                        Operand::Copy(entry),
                        monitor_const_operand(tcx, body, 0, entry_ty, source_info.span),
                    )),
                ),
            ))),
        ));
        let combined = monitor_temp(body, tcx.types.bool, source_info);
        statements.push(Statement::new(
            source_info,
            StatementKind::Assign(Box::new((
                combined,
                Rvalue::BinaryOp(
                    MirBinOp::BitAnd,
                    Box::new((Operand::Copy(nonnegative), Operand::Copy(decreasing))),
                ),
            ))),
        ));
        Operand::Copy(combined)
    } else {
        Operand::Copy(decreasing)
    };
    let destination = monitor_temp(body, tcx.types.unit, source_info);
    Ok(body.basic_blocks_mut().push(BasicBlockData::new_stmts(
        statements,
        Some(Terminator {
            source_info,
            kind: TerminatorKind::Call {
                func: Operand::function_handle(tcx, helper, &[], source_info.span),
                args: [Spanned { node: condition, span: source_info.span }].into(),
                destination,
                target: Some(final_target),
                unwind: UnwindAction::Continue,
                call_source: CallSource::Misc,
                fn_span: source_info.span,
            },
        }),
        false,
    )))
}

/// Authenticate the bounded function-level E5 topology before inserting any
/// runtime calls. A non-self/indirect call may participate in mutual
/// recursion, and Drop/coroutine/assembly control flow may hide another call
/// edge, so none may be silently omitted from a positive measured row.
fn certified_direct_self_recursion_sites<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    self_def: DefId,
) -> Result<Vec<BasicBlock>, String> {
    let mut sites = Vec::new();
    let typing_env = body.typing_env(tcx);
    for (bb, data) in body.basic_blocks.iter_enumerated() {
        match &data.terminator().kind {
            TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. } => {
                let Some((callee, generic_args)) = func.const_fn_def() else {
                    return Err(format!(
                        "function-level decreases cannot classify indirect call in {bb:?}"
                    ));
                };
                if callee != self_def {
                    return Err(format!(
                        "function-level decreases cannot classify non-self call `{callee:?}` in {bb:?} as non-recursive"
                    ));
                }
                let resolved = ty::Instance::try_resolve(tcx, typing_env, callee, generic_args)
                    .map_err(|_| {
                        format!(
                            "function-level decreases could not resolve direct self call in {bb:?}"
                        )
                    })?
                    .ok_or_else(|| {
                        format!(
                            "function-level decreases left direct self call in {bb:?} unresolved"
                        )
                    })?;
                if resolved.def_id() != self_def {
                    return Err(format!(
                        "function-level decreases call in {bb:?} resolved to `{resolved:?}`, not the current function"
                    ));
                }
                sites.push(bb);
            }
            TerminatorKind::Drop { .. } => {
                return Err(format!(
                    "function-level decreases cannot classify drop glue in {bb:?} as non-recursive"
                ));
            }
            TerminatorKind::Yield { .. } | TerminatorKind::CoroutineDrop => {
                return Err(format!(
                    "function-level decreases cannot classify coroutine control flow in {bb:?}"
                ));
            }
            TerminatorKind::InlineAsm { .. } => {
                return Err(format!(
                    "function-level decreases cannot classify inline assembly in {bb:?}"
                ));
            }
            TerminatorKind::Goto { .. }
            | TerminatorKind::SwitchInt { .. }
            | TerminatorKind::UnwindResume
            | TerminatorKind::UnwindTerminate(_)
            | TerminatorKind::Return
            | TerminatorKind::Unreachable
            | TerminatorKind::Assert { .. }
            | TerminatorKind::FalseEdge { .. }
            | TerminatorKind::FalseUnwind { .. } => {}
        }
    }
    Ok(sites)
}

struct CertifiedLoopRuntimeGroup<'a> {
    header: BasicBlock,
    span: rustc_span::Span,
    source_loop_id: u32,
    source_hir_local_id: u32,
    invariants: Vec<&'a BoundCertifiedMonitor>,
    invariant_source_indices: Vec<usize>,
    measures: Vec<&'a BoundCertifiedMeasure>,
    measure_source_indices: Vec<usize>,
    source_bindings: BTreeMap<String, u32>,
}

struct CertifiedLoopRuntimeGroups<'a> {
    groups: Vec<CertifiedLoopRuntimeGroup<'a>>,
    provenance_rejections: BTreeMap<usize, String>,
}

fn certified_loop_provenance_rejections(
    records: &[ClauseMonitorRecord],
    failures: &[(u32, String)],
) -> BTreeMap<usize, String> {
    use rustc_middle::mir::trust_contract::TrustContractSubject;

    let failures = failures.iter().cloned().collect::<BTreeMap<_, _>>();
    records
        .iter()
        .filter(|record| {
            matches!(
                &record.evidence,
                ClauseMonitorEvidence::MonitorCertified(_)
                    | ClauseMonitorEvidence::Monitored(_)
                    | ClauseMonitorEvidence::MeasureCertified(_)
                    | ClauseMonitorEvidence::Measured(_)
            )
        })
        .filter_map(|record| {
            let TrustContractSubject::HirLoop { id, .. } = record.subject else {
                return None;
            };
            failures.get(&id.index).map(|reason| {
                (
                    record.source_index,
                    format!(
                        "could not authenticate loop monitor header provenance: source loop {}: \
                         {reason}",
                        id.index
                    ),
                )
            })
        })
        .collect()
}

fn certified_loop_runtime_groups<'a>(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    local: LocalDefId,
    records: &'a [ClauseMonitorRecord],
) -> Result<CertifiedLoopRuntimeGroups<'a>, String> {
    use rustc_middle::mir::trust_contract::TrustContractSubject;

    let rustc_bundle = tcx.trust_contracts(local.to_def_id());
    let mut portable = trust_mir_extract::convert_trust_contract_bundle(tcx, rustc_bundle)
        .map_err(|reason| {
            format!(
                "could not reconstruct exact loop contract bundle for monitor placement: {reason}"
            )
        })?;
    let failures = trust_mir_extract::stamp_loop_header_provenance(body, &mut portable);
    // Provenance is compiler-authenticated per source-loop identity. A missing
    // optimized-away inner loop therefore rejects only that source group; it
    // cannot revoke (or borrow) the distinct surviving outer loop's exact
    // header. Conversion/catalog failures above remain body-global because
    // they prevent trustworthy row alignment altogether.
    let provenance_rejections = certified_loop_provenance_rejections(records, &failures);

    let function_contract_count = rustc_bundle.contracts.len();
    let mut groups = BTreeMap::<usize, CertifiedLoopRuntimeGroup<'a>>::new();
    for record in records {
        let TrustContractSubject::HirLoop { id, .. } = record.subject else {
            continue;
        };
        let is_positive = matches!(
            &record.evidence,
            ClauseMonitorEvidence::MonitorCertified(_)
                | ClauseMonitorEvidence::Monitored(_)
                | ClauseMonitorEvidence::MeasureCertified(_)
                | ClauseMonitorEvidence::Measured(_)
        );
        if !is_positive {
            continue;
        }
        if provenance_rejections.contains_key(&record.source_index) {
            continue;
        }
        let loop_index =
            record.source_index.checked_sub(function_contract_count).ok_or_else(|| {
                format!(
                    "positive loop monitor row #{} overlaps the function contract namespace",
                    record.source_index
                )
            })?;
        let spec = portable.loop_contracts.get(loop_index).ok_or_else(|| {
            format!(
                "positive loop monitor row #{} has no portable loop clause",
                record.source_index
            )
        })?;
        let query_contract = rustc_bundle.loop_contracts.get(loop_index).ok_or_else(|| {
            format!(
                "positive loop monitor row #{} has no compiler-query loop clause",
                record.source_index
            )
        })?;
        if spec.source_loop_id != id.index || spec.source_hir_local_id != Some(id.hir_local_id) {
            return Err(format!(
                "positive loop monitor row #{} changed source-loop identity",
                record.source_index
            ));
        }
        let header_index = spec.mir_header.ok_or_else(|| {
            format!(
                "positive loop monitor row #{} has no authenticated MIR header",
                record.source_index
            )
        })?;
        if header_index >= body.basic_blocks.len() {
            return Err(format!(
                "positive loop monitor row #{} names invalid MIR header bb{header_index}",
                record.source_index
            ));
        }
        let header = BasicBlock::from_usize(header_index);
        let group = groups.entry(header_index).or_insert_with(|| CertifiedLoopRuntimeGroup {
            header,
            span: record.span,
            source_loop_id: id.index,
            source_hir_local_id: id.hir_local_id,
            invariants: Vec::new(),
            invariant_source_indices: Vec::new(),
            measures: Vec::new(),
            measure_source_indices: Vec::new(),
            source_bindings: BTreeMap::new(),
        });
        if group.source_loop_id != id.index || group.source_hir_local_id != id.hir_local_id {
            return Err(format!(
                "distinct source loops ({}/{}) and ({}/{}) resolve to the same MIR header bb{header_index}",
                group.source_loop_id, group.source_hir_local_id, id.index, id.hir_local_id,
            ));
        }
        let required_names = match &record.evidence {
            ClauseMonitorEvidence::MonitorCertified(bound)
            | ClauseMonitorEvidence::Monitored(bound) => {
                bound.runtime.domains().keys().cloned().collect::<BTreeSet<_>>()
            }
            ClauseMonitorEvidence::MeasureCertified(bound)
            | ClauseMonitorEvidence::Measured(bound) => {
                bound.runtime.domains().keys().cloned().collect::<BTreeSet<_>>()
            }
            // Trust: an Unmonitored record carries no bound to read domains
            // from. Unreachable by construction here; refuse rather than abort.
            ClauseMonitorEvidence::Unmonitored { .. } => {
                return Err(format!(
                    "clause monitor record for source loop {} carries Unmonitored \
                     evidence where a runtime bound is required",
                    group.source_loop_id
                ));
            }
        };
        let mut clause_bindings = BTreeMap::new();
        for binding in &query_contract.predicate.source_bindings {
            let name = binding.name.to_string();
            if !required_names.contains(&name) {
                return Err(format!(
                    "positive loop monitor row #{} carries an unused HIR source binding for `{name}`",
                    record.source_index
                ));
            }
            if let Some(previous) = clause_bindings.insert(name.clone(), binding.hir_local_id)
                && previous != binding.hir_local_id
            {
                return Err(format!(
                    "positive loop monitor row #{} gives `{name}` conflicting HIR source bindings",
                    record.source_index
                ));
            }
        }
        for name in required_names {
            let hir_local_id = clause_bindings.get(&name).ok_or_else(|| {
                format!(
                    "positive loop monitor row #{} variable `{name}` has no exact whole-scalar HIR source binding",
                    record.source_index
                )
            })?;
            if let Some(previous) = group.source_bindings.insert(name.clone(), *hir_local_id)
                && previous != *hir_local_id
            {
                return Err(format!(
                    "loop monitor variable `{name}` changes HIR source identity across clauses"
                ));
            }
        }
        match (&record.kind, &record.evidence) {
            (
                TrustContractKind::LoopInvariant,
                ClauseMonitorEvidence::MonitorCertified(bound)
                | ClauseMonitorEvidence::Monitored(bound),
            ) => {
                group.invariants.push(bound);
                group.invariant_source_indices.push(record.source_index);
            }
            (
                TrustContractKind::Decreases,
                ClauseMonitorEvidence::MeasureCertified(bound)
                | ClauseMonitorEvidence::Measured(bound),
            ) => {
                group.measures.push(bound);
                group.measure_source_indices.push(record.source_index);
            }
            (kind, _) => {
                return Err(format!(
                    "positive loop monitor row #{} has incompatible evidence for {kind:?}",
                    record.source_index
                ));
            }
        }
    }
    Ok(CertifiedLoopRuntimeGroups { groups: groups.into_values().collect(), provenance_rejections })
}

fn certified_loop_required_domains(
    group: &CertifiedLoopRuntimeGroup<'_>,
) -> Result<BTreeMap<String, trust_spec_elab::RuntimeMonitorDomain>, String> {
    let mut required = BTreeMap::new();
    let mut insert = |name: &str, domain| match required.insert(name.to_string(), domain) {
        Some(previous) if previous != domain => Err(format!(
            "loop monitor variable `{name}` has conflicting certified domains {previous:?} and {domain:?}"
        )),
        _ => Ok(()),
    };
    for invariant in &group.invariants {
        for (name, domain) in invariant.runtime.domains() {
            insert(name, *domain)?;
        }
    }
    for measure in &group.measures {
        for (name, domain) in measure.runtime.domains() {
            insert(name, *domain)?;
        }
    }
    Ok(required)
}

fn canonical_monitor_predecessors(
    predecessors: impl IntoIterator<Item = BasicBlock>,
) -> Vec<BasicBlock> {
    let mut predecessors = predecessors.into_iter().collect::<Vec<_>>();
    predecessors.sort_unstable();
    predecessors.dedup();
    predecessors
}

fn preflight_monitor_emission<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    helper: DefId,
    monitor: &trust_spec_elab::RuntimeMonitor,
    bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    span: rustc_span::Span,
) -> Result<(), String> {
    // Exercise the exact emitter against an isolated clone. This is stronger
    // than maintaining a second "supported syntax" predicate which could
    // drift from the mutating placement path.
    let mut probe = body.clone();
    append_monitor_chain(
        tcx,
        &mut probe,
        helper,
        &[monitor],
        bindings,
        START_BLOCK,
        SourceInfo::outermost(span),
    )
    .map(|_| ())
}

fn preflight_measure_snapshot_and_backedge<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    helper: DefId,
    measure: &trust_spec_elab::RuntimeScalarTerm,
    bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    span: rustc_span::Span,
) -> Result<(), String> {
    let source_info = SourceInfo::outermost(span);
    let previous_ty = if measure.domain() == trust_spec_elab::RuntimeMonitorDomain::Nat {
        tcx.types.u128
    } else {
        runtime_monitor_domain_ty(tcx, measure.domain())?
    };
    let mut probe = body.clone();
    let previous = monitor_temp(&mut probe, previous_ty, source_info);
    append_measure_snapshot_block(
        tcx,
        &mut probe,
        measure,
        bindings,
        previous,
        previous_ty,
        START_BLOCK,
        source_info,
    )?;
    append_measure_backedge_block(
        tcx,
        &mut probe,
        helper,
        measure,
        bindings,
        previous,
        previous_ty,
        START_BLOCK,
        source_info,
    )?;
    Ok(())
}

fn preflight_function_measure_emission<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    helper: DefId,
    measure: &trust_spec_elab::RuntimeScalarTerm,
    entry_bindings: &FxHashMap<String, (Place<'tcx>, Ty<'tcx>)>,
    recursion_sites: &[BasicBlock],
    span: rustc_span::Span,
) -> Result<(), String> {
    let source_info = SourceInfo::outermost(span);
    let mut probe = body.clone();
    let mut entry_statements = Vec::new();
    let (entry_value, entry_ty) = emit_measure_value(
        tcx,
        &mut probe,
        source_info,
        measure,
        entry_bindings,
        &mut entry_statements,
    )?;
    let entry = monitor_temp(&mut probe, entry_ty, source_info);
    entry_statements.push(Statement::new(
        source_info,
        StatementKind::Assign(Box::new((entry, Rvalue::Use(entry_value, WithRetag::No)))),
    ));

    for &call_bb in recursion_sites {
        let args = match &body.basic_blocks[call_bb].terminator().kind {
            TerminatorKind::Call { args, .. } | TerminatorKind::TailCall { args, .. } => args,
            _ => {
                return Err(format!("authenticated recursive site {call_bb:?} is not a call"));
            }
        };
        let mut call_bindings = FxHashMap::default();
        for name in measure.variables() {
            let &(entry_place, expected_ty) = entry_bindings.get(name).ok_or_else(|| {
                format!(
                    "recursion measure variable `{name}` has no exact function parameter binding"
                )
            })?;
            if !entry_place.projection.is_empty()
                || entry_place.local.as_usize() == 0
                || entry_place.local.as_usize() > body.arg_count
            {
                return Err(format!(
                    "recursion measure variable `{name}` is not a direct scalar parameter"
                ));
            }
            let argument_index = entry_place.local.as_usize() - 1;
            let argument = args.get(argument_index).ok_or_else(|| {
                format!(
                    "recursive call in {call_bb:?} has no argument #{argument_index} for measure variable `{name}`"
                )
            })?;
            let actual_ty = argument.node.ty(&body.local_decls, tcx);
            if actual_ty != expected_ty {
                return Err(format!(
                    "recursive argument for `{name}` in {call_bb:?} changed type ({actual_ty:?}, expected {expected_ty:?})"
                ));
            }
            let captured = monitor_temp(&mut probe, expected_ty, source_info);
            call_bindings.insert(name.clone(), (captured, expected_ty));
        }
        append_recursion_measure_check_block(
            tcx,
            &mut probe,
            helper,
            measure,
            &call_bindings,
            entry,
            entry_ty,
            START_BLOCK,
            source_info,
        )?;
    }
    Ok(())
}

fn preflight_function_measure_placement<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    helper: DefId,
    local: LocalDefId,
    records: &[ClauseMonitorRecord],
) -> Result<Vec<usize>, String> {
    let measures = records
        .iter()
        .filter(|record| {
            matches!(
                record.subject,
                rustc_middle::mir::trust_contract::TrustContractSubject::Function
            ) && record.kind == TrustContractKind::Decreases
                && matches!(
                    &record.evidence,
                    ClauseMonitorEvidence::MeasureCertified(_) | ClauseMonitorEvidence::Measured(_)
                )
        })
        .collect::<Vec<_>>();
    if measures.is_empty() {
        return Ok(Vec::new());
    }

    let recursion_sites = certified_direct_self_recursion_sites(tcx, body, local.to_def_id())?;
    let bindings = trust_fn_monitor_places(tcx, local);
    for record in &measures {
        let measure = match &record.evidence {
            ClauseMonitorEvidence::MeasureCertified(bound)
            | ClauseMonitorEvidence::Measured(bound) => bound,
            _ => unreachable!(),
        };
        preflight_function_measure_emission(
            tcx,
            body,
            helper,
            &measure.runtime,
            &bindings,
            &recursion_sites,
            record.span,
        )
        .map_err(|reason| {
            format!(
                "function-entry/recursive-edge evaluator is not exactly MIR-emittable: {reason}"
            )
        })?;
    }
    Ok(measures.iter().map(|record| record.source_index).collect())
}

fn preflight_function_monitor_placement<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    helper: DefId,
    local: LocalDefId,
    records: &[ClauseMonitorRecord],
) -> (Vec<usize>, BTreeMap<usize, String>) {
    let bindings = trust_fn_monitor_places(tcx, local);
    let mut accepted = Vec::new();
    let mut rejected = BTreeMap::new();
    for record in records {
        if !matches!(
            record.subject,
            rustc_middle::mir::trust_contract::TrustContractSubject::Function
        ) {
            continue;
        }
        let ClauseMonitorEvidence::MonitorCertified(bound) = &record.evidence else {
            continue;
        };
        let result = match record.kind {
            TrustContractKind::Requires => {
                if bound.runtime.variables().iter().any(|name| name == "result") {
                    Err("requires monitor references uninitialized entry `result`".to_string())
                } else {
                    preflight_monitor_emission(
                        tcx,
                        body,
                        helper,
                        &bound.runtime,
                        &bindings,
                        record.span,
                    )
                }
            }
            TrustContractKind::Ensures => {
                // The mutating pass snapshots every non-result binding before
                // the first user statement. Copy scalar bindings are the only
                // certified carriers, so using the entry places in this probe
                // exercises the same evaluator and exact types without
                // changing the pristine body.
                preflight_monitor_emission(
                    tcx,
                    body,
                    helper,
                    &bound.runtime,
                    &bindings,
                    record.span,
                )
            }
            kind => Err(format!("function monitor has unsupported placement kind {kind:?}")),
        };
        match result {
            Ok(()) => accepted.push(record.source_index),
            Err(reason) => {
                rejected.insert(record.source_index, reason);
            }
        }
    }
    (accepted, rejected)
}

fn preflight_loop_monitor_placement<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    helper: DefId,
    local: LocalDefId,
    records: &[ClauseMonitorRecord],
) -> (Vec<usize>, BTreeMap<usize, String>) {
    let candidate_indices = records
        .iter()
        .filter_map(|record| {
            matches!(
                record.subject,
                rustc_middle::mir::trust_contract::TrustContractSubject::HirLoop { .. }
            )
            .then_some(record)
        })
        .filter(|record| {
            matches!(
                &record.evidence,
                ClauseMonitorEvidence::MonitorCertified(_)
                    | ClauseMonitorEvidence::MeasureCertified(_)
            )
        })
        .map(|record| record.source_index)
        .collect::<Vec<_>>();
    if candidate_indices.is_empty() {
        return (Vec::new(), BTreeMap::new());
    }

    let resolution = match certified_loop_runtime_groups(tcx, body, local, records) {
        Ok(resolution) => resolution,
        Err(reason) => {
            return (
                Vec::new(),
                candidate_indices.into_iter().map(|index| (index, reason.clone())).collect(),
            );
        }
    };
    let original_dominators = body.basic_blocks.dominators();
    let mut accepted = Vec::new();
    let mut rejected = resolution.provenance_rejections;
    for group in resolution.groups {
        let group_indices = group
            .invariant_source_indices
            .iter()
            .chain(&group.measure_source_indices)
            .copied()
            .collect::<Vec<_>>();
        let placement = (|| -> Result<(), String> {
            let domains = certified_loop_required_domains(&group)?;
            let loop_bindings = trust_loop_monitor_places(
                tcx,
                body,
                group.header,
                &domains,
                &group.source_bindings,
            )?;
            for invariant in &group.invariants {
                preflight_monitor_emission(
                    tcx,
                    body,
                    helper,
                    &invariant.runtime,
                    &loop_bindings,
                    group.span,
                )?;
            }
            if !group.measures.is_empty() {
                let predecessors = canonical_monitor_predecessors(
                    body.basic_blocks.predecessors()[group.header].iter().copied(),
                );
                if !predecessors
                    .iter()
                    .any(|&predecessor| !original_dominators.dominates(group.header, predecessor))
                {
                    return Err(
                        "loop measure has no authenticated non-backedge entry snapshot edge"
                            .to_string(),
                    );
                }
                for predecessor in predecessors {
                    if !body.basic_blocks[predecessor]
                        .terminator()
                        .successors()
                        .any(|target| target == group.header)
                    {
                        return Err(format!(
                            "authenticated loop predecessor {predecessor:?} does not target {:?}",
                            group.header
                        ));
                    }
                }
                for measure in &group.measures {
                    preflight_measure_snapshot_and_backedge(
                        tcx,
                        body,
                        helper,
                        &measure.runtime,
                        &loop_bindings,
                        group.span,
                    )?;
                }
            }
            Ok(())
        })();
        match placement {
            Ok(()) => accepted.extend(group_indices),
            Err(reason) => {
                rejected.extend(group_indices.into_iter().map(|index| (index, reason.clone())));
            }
        }
    }
    (accepted, rejected)
}

fn emit_clause_monitor_status(tcx: TyCtxt<'_>, record: &ClauseMonitorRecord) {
    match &record.evidence {
        ClauseMonitorEvidence::Monitored(_) => {
            tcx.dcx()
                .struct_span_note(
                    record.span,
                    format!(
                        "contract clause #{} ({:?}) is monitored: a kernel-certified runtime \
                         monitor exists (monitor = true ↔ proposition; {})",
                        record.source_index, record.kind, record.predicate_digest
                    ),
                )
                .emit();
        }
        ClauseMonitorEvidence::Measured(_) => {
            tcx.dcx()
                .struct_span_note(
                    record.span,
                    format!(
                        "contract clause #{} ({:?}) is measured: a kernel-certified scalar \
                         evaluator is bound to the exact E5 measure and authenticated MIR \
                         transitions ({})",
                        record.source_index, record.kind, record.predicate_digest
                    ),
                )
                .emit();
        }
        ClauseMonitorEvidence::MonitorCertified(_) => {
            tcx.dcx()
                .struct_span_note(
                    record.span,
                    format!(
                        "contract clause #{} ({:?}) is unmonitored (the Boolean evaluator is \
                         kernel-certified but exact MIR placement was not authenticated): not \
                         runtime-checked, never a fake value ({})",
                        record.source_index, record.kind, record.predicate_digest
                    ),
                )
                .emit();
        }
        ClauseMonitorEvidence::MeasureCertified(_) => {
            tcx.dcx()
                .struct_span_note(
                    record.span,
                    format!(
                        "contract clause #{} ({:?}) is unmonitored (the scalar evaluator is \
                         kernel-certified but exact MIR transition placement was not \
                         authenticated): not runtime-checked, never a fake value ({})",
                        record.source_index, record.kind, record.predicate_digest
                    ),
                )
                .emit();
        }
        ClauseMonitorEvidence::Unmonitored { reason } => {
            tcx.dcx()
                .struct_span_note(
                    record.span,
                    format!(
                        "contract clause #{} ({:?}) is unmonitored ({}): not runtime-checked, \
                         never a fake value ({})",
                        record.source_index,
                        record.kind,
                        bounded_monitor_reason(reason),
                        record.predicate_digest
                    ),
                )
                .emit();
        }
    }
}

/// Convert kernel-certified evaluator candidates into public executable
/// authority only after authenticating their exact pristine-MIR bindings and
/// placement topology. This runs before any verification bundle is built, so
/// neither human diagnostics nor durable metadata can observe a provisional
/// candidate as `monitored`/`measured`.
fn preflight_certified_monitor_placement<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) {
    if body.source.promoted.is_some() {
        return;
    }
    let Some(local) = body.source.def_id().as_local() else { return };
    let records = tcx.sess.with_trust_compiler_state::<SessionCertifiedMonitors, _>(|state| {
        state.functions.get(&local).cloned()
    });
    let Some(records) = records else { return };
    let candidate_indices = records
        .iter()
        .filter(|record| {
            matches!(
                &record.evidence,
                ClauseMonitorEvidence::MonitorCertified(_)
                    | ClauseMonitorEvidence::MeasureCertified(_)
            )
        })
        .map(|record| record.source_index)
        .collect::<Vec<_>>();

    let mut accepted = FxHashSet::default();
    let mut rejected = BTreeMap::new();
    if !candidate_indices.is_empty() {
        if let Some(helper) = tcx.get_diagnostic_item(sym::trust_certified_monitor_check) {
            let (function_monitors, function_monitor_rejections) =
                preflight_function_monitor_placement(tcx, body, helper, local, &records);
            accepted.extend(function_monitors);
            rejected.extend(function_monitor_rejections);

            match preflight_function_measure_placement(tcx, body, helper, local, &records) {
                Ok(indices) => accepted.extend(indices),
                Err(reason) => {
                    for record in &records {
                        if matches!(
                            record.subject,
                            rustc_middle::mir::trust_contract::TrustContractSubject::Function
                        ) && matches!(
                            &record.evidence,
                            ClauseMonitorEvidence::MeasureCertified(_)
                        ) {
                            rejected.insert(record.source_index, reason.clone());
                        }
                    }
                }
            }

            let (loop_records, loop_rejections) =
                preflight_loop_monitor_placement(tcx, body, helper, local, &records);
            accepted.extend(loop_records);
            rejected.extend(loop_rejections);
        } else {
            rejected.extend(candidate_indices.iter().copied().map(|index| {
                (
                    index,
                    "certified monitor runtime helper is missing from the Trust sysroot"
                        .to_string(),
                )
            }));
        }
    }

    let mut final_records = records;
    for record in &mut final_records {
        let evidence = record.evidence.clone();
        record.evidence = match evidence {
            ClauseMonitorEvidence::MonitorCertified(bound)
                if accepted.contains(&record.source_index) =>
            {
                ClauseMonitorEvidence::Monitored(bound)
            }
            ClauseMonitorEvidence::MeasureCertified(bound)
                if accepted.contains(&record.source_index) =>
            {
                ClauseMonitorEvidence::Measured(bound)
            }
            ClauseMonitorEvidence::MonitorCertified(_)
            | ClauseMonitorEvidence::MeasureCertified(_) => ClauseMonitorEvidence::Unmonitored {
                reason: rejected.remove(&record.source_index).unwrap_or_else(|| {
                    "exact MIR placement preflight did not produce unique authority".to_string()
                }),
            },
            other => other,
        };
    }
    tcx.sess.with_trust_compiler_state::<SessionCertifiedMonitors, _>(|state| {
        state.functions.insert(local, final_records.clone());
    });

    if env_flag_enabled("TRUST_MONITOR_REPORT") || certified_monitor_test_mode(tcx.sess) {
        for record in &final_records {
            emit_clause_monitor_status(tcx, record);
        }
    }
}

/// Insert runtime enforcement only for a native `--test` unit or a tracked
/// Targo-selected library linked by an ordinary unit/integration-test root.
/// Evidence-grade Targo doctests remain unavailable until rustdoc provides an
/// authenticated reusable-executable lane. No dual spec projection alters
/// clause meaning. Every inserted expression came from the canonical typed
/// predicate and a kernel-accepted `monitor = true ↔ P` proof.
fn inject_certified_test_monitors<'tcx>(tcx: TyCtxt<'tcx>, body: &mut Body<'tcx>) {
    if !certified_monitor_test_mode(tcx.sess) || body.source.promoted.is_some() {
        return;
    }
    let Some(local) = body.source.def_id().as_local() else { return };
    let records = tcx.sess.with_trust_compiler_state::<SessionCertifiedMonitors, _>(|state| {
        state.functions.get(&local).cloned()
    });
    let Some(records) = records else { return };
    for record in &records {
        if let ClauseMonitorEvidence::Measured(bound) = &record.evidence {
            // Keep the exact static measure live at the execution boundary,
            // just as Boolean monitors retain their proposition. A future
            // refactor must not be able to place an evaluator after silently
            // dropping the formula/domain identity it was certified against.
            debug_assert_eq!(
                static_formula_measure_expr(&bound.static_formula, &bound.variable_domains)
                    .as_ref(),
                Ok(bound.runtime.expr())
            );
            debug_assert!(
                validate_runtime_measure_domains(&bound.runtime, &bound.variable_domains).is_ok()
            );
        }
    }
    let Some(helper) = tcx.get_diagnostic_item(sym::trust_certified_monitor_check) else {
        if records.iter().any(|record| {
            matches!(
                &record.evidence,
                ClauseMonitorEvidence::Monitored(_) | ClauseMonitorEvidence::Measured(_)
            )
        }) {
            tcx.dcx().span_err(
                body.span,
                "certified monitor runtime helper is missing from the Trust sysroot",
            );
        }
        return;
    };
    let bindings = trust_fn_monitor_places(tcx, local);
    let mut requires = Vec::new();
    let mut ensures = Vec::new();
    for record in &records {
        let ClauseMonitorEvidence::Monitored(bound) = &record.evidence else { continue };
        // Touch the retained Formula at the execution boundary as a defensive
        // invariant: a monitored record can never be reduced to runtime bytes
        // alone by a future refactor.
        debug_assert_eq!(
            static_formula_monitor_expr(&bound.static_formula, &bound.variable_domains).as_ref(),
            Ok(bound.runtime.expr())
        );
        debug_assert!(
            validate_runtime_monitor_domains(&bound.runtime, &bound.variable_domains).is_ok()
        );
        let monitor = &bound.runtime;
        match record.kind {
            rustc_middle::mir::trust_contract::TrustContractKind::Requires => {
                // Defensive backstop for the producer-side classification:
                // `_0` is uninitialized at entry and must never be observed by
                // a precondition monitor.
                if monitor.variables().iter().any(|name| name == "result") {
                    tcx.dcx().span_err(
                        record.span,
                        "kernel-certified requires monitor unexpectedly references `result`",
                    );
                } else {
                    requires.push((record.span, monitor));
                }
            }
            rustc_middle::mir::trust_contract::TrustContractKind::Ensures => {
                ensures.push((record.span, monitor));
            }
            _ => {}
        }
    }
    let function_measures = records
        .iter()
        .filter_map(|record| {
            matches!(
                record.subject,
                rustc_middle::mir::trust_contract::TrustContractSubject::Function
            )
            .then_some(record)
        })
        .filter_map(|record| match (&record.kind, &record.evidence) {
            (TrustContractKind::Decreases, ClauseMonitorEvidence::Measured(bound)) => {
                Some((record.span, bound))
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    // Inventory the original body before loop/function monitor helper calls
    // are inserted. Those helpers are compiler-owned and must not be mistaken
    // for authored non-self edges in the E5 topology audit.
    let recursion_sites = if function_measures.is_empty() {
        Vec::new()
    } else {
        match certified_direct_self_recursion_sites(tcx, body, local.to_def_id()) {
            Ok(sites) => sites,
            Err(reason) => {
                tcx.dcx().span_err(
                    function_measures[0].0,
                    format!("could not place kernel-certified recursion measure: {reason}"),
                );
                Vec::new()
            }
        }
    };

    // Resolve every loop clause against the same unmodified optimized MIR
    // graph before installing any function-entry/return instrumentation.
    // Source-loop HIR identity + dominator-proved header provenance is
    // mandatory; positive evidence that cannot be placed is a hard compiler
    // error, never silently demoted to an unmonitored artifact.
    let has_positive_loop = records.iter().any(|record| {
        matches!(
            record.subject,
            rustc_middle::mir::trust_contract::TrustContractSubject::HirLoop { .. }
        ) && matches!(
            &record.evidence,
            ClauseMonitorEvidence::Monitored(_) | ClauseMonitorEvidence::Measured(_)
        )
    });
    let loop_groups = if has_positive_loop {
        match certified_loop_runtime_groups(tcx, body, local, &records) {
            Ok(resolution) => {
                for (source_index, reason) in resolution.provenance_rejections {
                    let span = records
                        .iter()
                        .find(|record| record.source_index == source_index)
                        .map_or(body.span, |record| record.span);
                    tcx.dcx().span_err(
                        span,
                        format!("could not place kernel-certified loop monitor: {reason}"),
                    );
                }
                resolution.groups
            }
            Err(reason) => {
                tcx.dcx().span_err(
                    body.span,
                    format!("could not place kernel-certified loop monitors: {reason}"),
                );
                Vec::new()
            }
        }
    } else {
        Vec::new()
    };
    let original_dominators = body.basic_blocks.dominators().clone();
    let original_predecessors = loop_groups
        .iter()
        .map(|group| {
            // `BasicBlocks::predecessors` retains one row per terminator
            // successor, so a `SwitchInt` with two values targeting the same
            // header names its predecessor twice. One instrumentation chain
            // rewires every matching edge in that terminator; iterating the
            // duplicate again would then reject the already-rewired edge.
            // Placement authority is per predecessor block, not per duplicate
            // switch value, so canonicalize that inventory before mutation.
            let predecessors = canonical_monitor_predecessors(
                body.basic_blocks.predecessors()[group.header].iter().copied(),
            );
            (group.header, predecessors)
        })
        .collect::<FxHashMap<_, _>>();
    let mut prepared_loops = Vec::new();
    for group in loop_groups {
        let prepared = certified_loop_required_domains(&group).and_then(|domains| {
            trust_loop_monitor_places(tcx, body, group.header, &domains, &group.source_bindings)
        });
        match prepared {
            Ok(loop_bindings) => {
                let source_info = SourceInfo::outermost(group.span);
                let mut previous = Vec::with_capacity(group.measures.len());
                let mut carrier_error = None;
                for measure in &group.measures {
                    let ty =
                        if measure.runtime.domain() == trust_spec_elab::RuntimeMonitorDomain::Nat {
                            tcx.types.u128
                        } else {
                            match runtime_monitor_domain_ty(tcx, measure.runtime.domain()) {
                                Ok(ty) => ty,
                                Err(reason) => {
                                    carrier_error = Some(reason);
                                    break;
                                }
                            }
                        };
                    previous.push((monitor_temp(body, ty, source_info), ty));
                }
                if let Some(reason) = carrier_error {
                    tcx.dcx().span_err(
                        group.span,
                        format!("could not place kernel-certified loop measure: {reason}"),
                    );
                } else {
                    prepared_loops.push((group, loop_bindings, previous));
                }
            }
            Err(reason) => {
                tcx.dcx().span_err(
                    group.span,
                    format!("could not bind kernel-certified loop monitor to MIR: {reason}"),
                );
            }
        }
    }

    // Split every original incoming edge to a measured header before any
    // header wrapper moves block contents. External entries initialize each
    // measure snapshot; only dominator-proved backedges compare/update it.
    // This resets an inner loop's snapshot on every outer-loop re-entry and
    // handles all latches/continues without one arbitrary-backedge choice.
    for (group, loop_bindings, previous) in &prepared_loops {
        if group.measures.is_empty() {
            continue;
        }
        let Some(predecessors) = original_predecessors.get(&group.header) else {
            tcx.dcx().span_err(
                group.span,
                "authenticated loop header has no original predecessor inventory",
            );
            continue;
        };
        if !predecessors
            .iter()
            .any(|&predecessor| !original_dominators.dominates(group.header, predecessor))
        {
            tcx.dcx().span_err(
                group.span,
                "kernel-certified loop measure has no authenticated non-backedge on which to initialize its entry snapshot",
            );
            continue;
        }
        for &predecessor in predecessors {
            let is_backedge = original_dominators.dominates(group.header, predecessor);
            let source_info = SourceInfo::outermost(group.span);
            let mut next = group.header;
            let mut failed = None;
            for (index, measure) in group.measures.iter().enumerate().rev() {
                let (previous_place, previous_ty) = previous[index];
                let block = if is_backedge {
                    append_measure_backedge_block(
                        tcx,
                        body,
                        helper,
                        &measure.runtime,
                        loop_bindings,
                        previous_place,
                        previous_ty,
                        next,
                        source_info,
                    )
                } else {
                    append_measure_snapshot_block(
                        tcx,
                        body,
                        &measure.runtime,
                        loop_bindings,
                        previous_place,
                        previous_ty,
                        next,
                        source_info,
                    )
                };
                match block {
                    Ok(block) => next = block,
                    Err(reason) => {
                        failed = Some(reason);
                        break;
                    }
                }
            }
            if let Some(reason) = failed {
                tcx.dcx().span_err(
                    group.span,
                    format!("could not wire kernel-certified loop measure edge: {reason}"),
                );
                continue;
            }
            let mut rewired = false;
            body.basic_blocks_mut()[predecessor].terminator_mut().successors_mut(|target| {
                if *target == group.header {
                    *target = next;
                    rewired = true;
                }
            });
            if !rewired {
                tcx.dcx().span_err(
                    group.span,
                    format!(
                        "authenticated loop predecessor {predecessor:?} no longer targets {:?}",
                        group.header
                    ),
                );
            }
        }
    }

    // Check every invariant on initial entry and after every completed
    // iteration by retaining the authenticated header block number as a
    // wrapper. The former header body is moved once; every original/split edge
    // still targets the wrapper.
    for (group, loop_bindings, _) in &prepared_loops {
        if group.invariants.is_empty() {
            continue;
        }
        let source_info = SourceInfo::outermost(group.span);
        let former_header = std::mem::replace(
            &mut body.basic_blocks_mut()[group.header],
            BasicBlockData::new(None, false),
        );
        let former_header = body.basic_blocks_mut().push(former_header);
        let monitors = group.invariants.iter().map(|bound| &bound.runtime).collect::<Vec<_>>();
        match append_monitor_chain(
            tcx,
            body,
            helper,
            &monitors,
            loop_bindings,
            former_header,
            source_info,
        ) {
            Ok(first) => {
                body.basic_blocks_mut()[group.header].terminator = Some(Terminator {
                    source_info,
                    kind: TerminatorKind::Goto {
                        target: first,
                        loop_hint_attrs: Default::default(),
                    },
                });
            }
            Err(reason) => {
                body.basic_blocks_mut()[group.header].terminator = Some(Terminator {
                    source_info,
                    kind: TerminatorKind::Goto {
                        target: former_header,
                        loop_hint_attrs: Default::default(),
                    },
                });
                tcx.dcx().span_err(
                    group.span,
                    format!("could not wire kernel-certified loop invariant: {reason}"),
                );
            }
        }
    }

    // Snapshot each function-level measure in the entry state, then check it
    // against the exact recursive argument tuple at every authenticated direct
    // self-call. Capturing call operands into fresh scalar temporaries both
    // preserves Move/Copy evaluation order and gives the certified evaluator a
    // stable MIR place; the original call is rewritten to consume those temps.
    let mut entry_measures = Vec::new();
    if !recursion_sites.is_empty() {
        let source_info = SourceInfo::outermost(function_measures[0].0);
        let mut snapshot_statements = Vec::new();
        let mut snapshot_failed = false;
        for (span, measure) in &function_measures {
            match emit_measure_value(
                tcx,
                body,
                source_info,
                &measure.runtime,
                &bindings,
                &mut snapshot_statements,
            ) {
                Ok((value, ty)) => {
                    let snapshot = monitor_temp(body, ty, source_info);
                    snapshot_statements.push(Statement::new(
                        source_info,
                        StatementKind::Assign(Box::new((
                            snapshot,
                            Rvalue::Use(value, WithRetag::No),
                        ))),
                    ));
                    entry_measures.push((*span, *measure, snapshot, ty));
                }
                Err(reason) => {
                    tcx.dcx().span_err(
                        *span,
                        format!(
                            "could not evaluate kernel-certified recursion measure at entry: {reason}"
                        ),
                    );
                    snapshot_failed = true;
                    break;
                }
            }
        }
        if !snapshot_failed {
            let entry_statements = &mut body.basic_blocks_mut()[START_BLOCK].statements;
            snapshot_statements.append(entry_statements);
            *entry_statements = snapshot_statements;
        } else {
            entry_measures.clear();
        }
    }
    if !entry_measures.is_empty() {
        for call_bb in recursion_sites {
            let placement = (|| -> Result<BasicBlock, String> {
                let mut original = body.basic_blocks[call_bb].terminator().clone();
                let original_source_info = original.source_info;
                let args = match &mut original.kind {
                    TerminatorKind::Call { args, .. } | TerminatorKind::TailCall { args, .. } => {
                        args
                    }
                    _ => {
                        return Err(format!(
                            "authenticated recursive site {call_bb:?} is no longer a call"
                        ));
                    }
                };
                let mut required_names = BTreeSet::new();
                for (_, measure, _, _) in &entry_measures {
                    required_names.extend(measure.runtime.variables().iter().cloned());
                }
                let mut capture_statements = Vec::new();
                let mut call_bindings = FxHashMap::default();
                for name in required_names {
                    let &(entry_place, expected_ty) = bindings.get(&name).ok_or_else(|| {
                        format!(
                            "recursion measure variable `{name}` has no exact function parameter binding"
                        )
                    })?;
                    if !entry_place.projection.is_empty()
                        || entry_place.local.as_usize() == 0
                        || entry_place.local.as_usize() > body.arg_count
                    {
                        return Err(format!(
                            "recursion measure variable `{name}` is not a direct scalar parameter"
                        ));
                    }
                    let argument_index = entry_place.local.as_usize() - 1;
                    let argument = args.get_mut(argument_index).ok_or_else(|| {
                        format!(
                            "recursive call has no argument #{argument_index} for measure variable `{name}`"
                        )
                    })?;
                    let actual_ty = argument.node.ty(&body.local_decls, tcx);
                    if actual_ty != expected_ty {
                        return Err(format!(
                            "recursive argument for `{name}` changed type ({actual_ty:?}, expected {expected_ty:?})"
                        ));
                    }
                    let captured = monitor_temp(body, expected_ty, original_source_info);
                    capture_statements.push(Statement::new(
                        original_source_info,
                        StatementKind::Assign(Box::new((
                            captured,
                            Rvalue::Use(argument.node.clone(), WithRetag::No),
                        ))),
                    ));
                    argument.node = Operand::Copy(captured);
                    call_bindings.insert(name, (captured, expected_ty));
                }

                let final_call =
                    body.basic_blocks_mut().push(BasicBlockData::new(Some(original), false));
                let mut next = final_call;
                for (span, measure, entry, entry_ty) in entry_measures.iter().rev() {
                    next = append_recursion_measure_check_block(
                        tcx,
                        body,
                        helper,
                        &measure.runtime,
                        &call_bindings,
                        *entry,
                        *entry_ty,
                        next,
                        SourceInfo::outermost(*span),
                    )?;
                }
                Ok(body.basic_blocks_mut().push(BasicBlockData::new_stmts(
                    capture_statements,
                    Some(Terminator {
                        source_info: original_source_info,
                        kind: TerminatorKind::Goto {
                            target: next,
                            loop_hint_attrs: Default::default(),
                        },
                    }),
                    false,
                )))
            })();
            match placement {
                Ok(first) => {
                    let source_info = body.basic_blocks[call_bb].terminator().source_info;
                    *body.basic_blocks_mut()[call_bb].terminator_mut() = Terminator {
                        source_info,
                        kind: TerminatorKind::Goto {
                            target: first,
                            loop_hint_attrs: Default::default(),
                        },
                    };
                }
                Err(reason) => {
                    tcx.dcx().span_err(
                        function_measures[0].0,
                        format!(
                            "could not wire kernel-certified recursion measure at {call_bb:?}: {reason}"
                        ),
                    );
                }
            }
        }
    }

    // In an ensures clause, parameter names denote ENTRY values (§1.2-3),
    // even when the Rust binding is `mut`. Snapshot only the supported Copy
    // arguments actually mentioned by certified postconditions, before the
    // first user-body statement. `result` remains RETURN_PLACE and is read at
    // each normal return.
    let mut ensures_bindings = bindings.clone();
    if !ensures.is_empty() {
        let source_info = SourceInfo::outermost(ensures[0].0);
        let mut snapshot_names = Vec::new();
        for (_, monitor) in &ensures {
            for name in monitor.variables() {
                if name != "result" && !snapshot_names.contains(name) {
                    snapshot_names.push(name.clone());
                }
            }
        }
        let mut snapshot_statements = Vec::new();
        for name in snapshot_names {
            let Some(&(entry_place, entry_ty)) = bindings.get(&name) else {
                tcx.dcx().span_err(
                    ensures[0].0,
                    format!("no entry value is observable for certified ensures variable `{name}`"),
                );
                continue;
            };
            let snapshot = monitor_temp(body, entry_ty, source_info);
            snapshot_statements.push(Statement::new(
                source_info,
                StatementKind::Assign(Box::new((
                    snapshot,
                    Rvalue::Use(Operand::Copy(entry_place), WithRetag::No),
                ))),
            ));
            ensures_bindings.insert(name, (snapshot, entry_ty));
        }
        let entry_statements = &mut body.basic_blocks_mut()[START_BLOCK].statements;
        snapshot_statements.append(entry_statements);
        *entry_statements = snapshot_statements;
    }

    if !requires.is_empty() {
        let source_info = SourceInfo::outermost(requires[0].0);
        let former_entry = std::mem::replace(
            &mut body.basic_blocks_mut()[START_BLOCK],
            BasicBlockData::new(None, false),
        );
        let former_entry = body.basic_blocks_mut().push(former_entry);
        let monitors = requires.iter().map(|(_, monitor)| *monitor).collect::<Vec<_>>();
        match append_monitor_chain(
            tcx,
            body,
            helper,
            &monitors,
            &bindings,
            former_entry,
            source_info,
        ) {
            Ok(first) => {
                body.basic_blocks_mut()[START_BLOCK].terminator = Some(Terminator {
                    source_info,
                    kind: TerminatorKind::Goto {
                        target: first,
                        loop_hint_attrs: Default::default(),
                    },
                });
            }
            Err(reason) => {
                body.basic_blocks_mut()[START_BLOCK].terminator = Some(Terminator {
                    source_info,
                    kind: TerminatorKind::Goto {
                        target: former_entry,
                        loop_hint_attrs: Default::default(),
                    },
                });
                tcx.dcx().span_err(
                    requires[0].0,
                    format!("could not wire kernel-certified requires monitor: {reason}"),
                );
            }
        }
    }

    if !ensures.is_empty() {
        let returns = body
            .basic_blocks
            .iter_enumerated()
            .filter_map(|(bb, data)| {
                matches!(data.terminator().kind, TerminatorKind::Return).then_some(bb)
            })
            .collect::<Vec<_>>();
        let source_info = SourceInfo::outermost(ensures[0].0);
        let monitors = ensures.iter().map(|(_, monitor)| *monitor).collect::<Vec<_>>();
        for return_bb in returns {
            let final_return = body.basic_blocks_mut().push(BasicBlockData::new(
                Some(Terminator { source_info, kind: TerminatorKind::Return }),
                false,
            ));
            match append_monitor_chain(
                tcx,
                body,
                helper,
                &monitors,
                &ensures_bindings,
                final_return,
                source_info,
            ) {
                Ok(first) => {
                    body.basic_blocks_mut()[return_bb].terminator_mut().kind =
                        TerminatorKind::Goto { target: first, loop_hint_attrs: Default::default() };
                }
                Err(reason) => {
                    tcx.dcx().span_err(
                        ensures[0].0,
                        format!("could not wire kernel-certified ensures monitor: {reason}"),
                    );
                }
            }
        }

        // A `TailCall` returns the callee's value directly to this function's
        // caller, so there is no post-call program point at which an `ensures`
        // monitor can observe RETURN_PLACE. In monitor-enabled test artifacts,
        // lower only that terminator to its semantically equivalent ordinary
        // call → certified monitor chain → return form. The ordinary production
        // artifact never runs this pass and retains the explicit tail call.
        //
        // This is the same instrumentation tradeoff made by stack-sensitive
        // sanitizers: the test artifact may use an extra frame while checking
        // the postcondition, but argument ownership, return value, and unwind
        // propagation are unchanged. A diverging callee never reaches the
        // monitor chain, unlike a pre-tail-call check, so a postcondition is not
        // spuriously enforced on a non-returning execution.
        let tail_calls = body
            .basic_blocks
            .iter_enumerated()
            .filter_map(|(bb, data)| {
                matches!(data.terminator().kind, TerminatorKind::TailCall { .. }).then_some(bb)
            })
            .collect::<Vec<_>>();
        for tail_bb in tail_calls {
            let original = body.basic_blocks[tail_bb].terminator().clone();
            let TerminatorKind::TailCall { func, args, fn_span } = original.kind else {
                // Trust: `tail_calls` was filtered on exactly this shape, so this
                // cannot happen. Skip the block rather than aborting the pass.
                continue;
            };
            let final_return = body.basic_blocks_mut().push(BasicBlockData::new(
                Some(Terminator {
                    source_info: original.source_info,
                    kind: TerminatorKind::Return,
                }),
                false,
            ));
            match append_monitor_chain(
                tcx,
                body,
                helper,
                &monitors,
                &ensures_bindings,
                final_return,
                source_info,
            ) {
                Ok(first) => {
                    let terminator = body.basic_blocks_mut()[tail_bb].terminator_mut();
                    terminator.kind = TerminatorKind::Call {
                        func,
                        args,
                        destination: Place::return_place(),
                        target: Some(first),
                        // A TailCall has no local cleanup successor because
                        // this frame has already run its drops, but a callee
                        // panic still continues unwinding through the caller.
                        // `Unreachable` would instead make that unwind UB.
                        unwind: UnwindAction::Continue,
                        call_source: CallSource::Misc,
                        fn_span,
                    };
                }
                Err(reason) => {
                    tcx.dcx().span_err(
                        ensures[0].0,
                        format!(
                            "could not wire kernel-certified ensures monitor after explicit tail call: {reason}"
                        ),
                    );
                }
            }
        }
    }
}

/// Authenticate Targo's monitor-only execution channel independently of
/// rustc's native `--test` bit. Keeping this predicate separate prevents an
/// explicit native `--test -Ztrust-verify=off` vanilla build from accidentally
/// re-enabling Trust's optimized-MIR pass.
fn targo_certified_monitor_test_mode(sess: &Session) -> bool {
    // The environment nonce is authenticated by rustc_driver before Session
    // construction. Never read it here: proc macros execute in-process and
    // can mutate process-global environment after startup. This immutable,
    // tracked Session bit is the only MIR-pass selector.
    if !sess.opts.unstable_opts.trust_targo_test_monitor {
        return false;
    }
    if sess.opts.unstable_opts.trust_verify_session.is_none() {
        sess.dcx().fatal("-Ztrust-targo-test-monitor requires -Ztrust-verify-session");
    }
    true
}

/// Runtime monitors are enabled either by rustc's native `--test` mode or by
/// Targo's tracked, per-unit test-graph decision. Cargo appends the latter only
/// to the selected package's normal library when an exact ordinary test root
/// links it, and fingerprints that derived decision independently. Doctests
/// fail closed before this lane. This is an execution-mode channel only: it
/// never selects a second spec projection.
fn certified_monitor_test_mode(sess: &Session) -> bool {
    // Always validate a present Targo marker, even on a native `--test` unit;
    // short-circuiting on `sess.opts.test` would let a stale marker pass.
    let targo = targo_certified_monitor_test_mode(sess);
    // `trust_certified_test_monitors` is a redundant, tracked Targo
    // fingerprint, never a second authorization path. The driver rejects it
    // unless this nonce-bound selector is also present.
    sess.opts.test || targo
}

/// Trust (GREEN THAT LIES, measured 2026-09-16): disclose every `import` of an
/// ACCEPTED island that Clean's built-in prelude stand-in served.
///
/// The island lane resolves no external `.olean`, so `clean { import Mathlib … }`
/// is accepted against a prelude provider that merely bears the module's name,
/// and the only output used to be "Clean island kernel-checked". The standalone
/// `.lean` lane already says so (`targo trust check`, battery row r26); this is
/// the same statement for an island or a `clean mod` unit, in the words
/// `trust_certify` owns so the resolver seam (`report_rejected_batch`) and this
/// one cannot drift. A NOTE on every build, never a refusal: vanilla Lean is
/// valid input (drop-in invariant 2) and the declarations really were
/// kernel-checked — relative to the stand-in, which is what the note says.
///
/// Reports nothing for a rejected island (`standin_imports` is empty there): it
/// reports no green for the disclosure to qualify.
fn trust_disclose_island_standin_imports(
    tcx: TyCtxt<'_>,
    content_span: rustc_span::Span,
    text: &str,
    outcome: &trust_certify::clean_island::CleanIslandOutcome,
) {
    for import in &outcome.standin_imports {
        // The same island-relative remap every island diagnostic here uses.
        let start = import.start.min(text.len());
        let end = import.end.max(start).min(text.len());
        let lo = content_span.lo() + rustc_span::BytePos(start as u32);
        let mut hi = content_span.lo() + rustc_span::BytePos(end as u32);
        if hi == lo && lo < content_span.hi() {
            hi = lo + rustc_span::BytePos(1);
        }
        tcx.dcx()
            .struct_span_note(content_span.with_lo(lo).with_hi(hi), import.disclosure())
            .with_note(import.options())
            .emit();
    }
}

/// Trust (temporal P2): report every finite model an accepted island declared
/// and the compiler checked on its own (`trust_certify`'s
/// `clean_island::model_check`): a constant whose kernel type is
/// `Trust.Temporal.FiniteModel.ScalarModel`.
///
/// A model the kernel proved safe is a note. One the check could NOT decide
/// (more reachable states than the budget, a construct outside the checker's
/// grammar) is a WARNING at the model: nothing is claimed about it, and an
/// unchecked model must never read like a checked one. An unsafe model is
/// already an error on its island; here it gets a note with a shortest run to
/// the state that breaks the invariant.
/// Trust (temporal P3): a binding the islands declare is checked against the
/// code by the thread census, which ran before this session and was given the
/// bindings the resolver read. One this session reads that the census was not
/// given was NOT checked: an island checked only after the body walk (it, or
/// one before it, names `trust_import_`; `deferred` says why), or a disagreement
/// between the two sessions. That is an error at the binding: an unchecked
/// binding must never look like one that holds.
fn trust_report_unchecked_island_bindings(
    tcx: TyCtxt<'_>,
    content_span: rustc_span::Span,
    text: &str,
    outcome: &trust_certify::clean_island::CleanIslandOutcome,
    deferred: Option<&str>,
) {
    for binding in &outcome.bindings {
        let start = binding.start.min(text.len());
        let end = binding.end.max(start).min(text.len());
        let lo = content_span.lo() + rustc_span::BytePos(start as u32);
        let mut hi = content_span.lo() + rustc_span::BytePos(end as u32);
        if hi == lo && lo < content_span.hi() {
            hi = lo + rustc_span::BytePos(1);
        }
        let span = content_span.with_lo(lo).with_hi(hi);
        let given = tcx
            .sess
            .trust_field_bindings()
            .iter()
            // By name and place in source. The resolver built its span from
            // the AST and this one comes from HIR: under incremental
            // compilation HIR spans carry a parent, so the two are never
            // equal as `Span`s though they cover the same bytes.
            .any(|known| {
                known.name == binding.name
                    && (known.span.lo() == span.lo() && known.span.hi() == span.hi())
            });
        if given {
            continue;
        }
        let why = deferred.unwrap_or(
            "the session that read this crate's islands before analysis did not report it \
             (an island that comes out of a macro expansion is read only after analysis: \
             declare the binding in an island written in the source)",
        );
        let mut diag = tcx.dcx().struct_span_err(
            span,
            format!("binding `{}` was not checked against the code: {why}", binding.name),
        );
        if deferred.is_some() {
            diag.help(
                "declare the binding in an island placed before the first island that names \
                 `trust_import_`",
            );
        }
        diag.emit();
    }
    // A seal goes the same way: the check that reads every body against it
    // was given the seals the resolver read, before analysis.
    for seal in &outcome.seals {
        let start = seal.start.min(text.len());
        let end = seal.end.max(start).min(text.len());
        let lo = content_span.lo() + rustc_span::BytePos(start as u32);
        let mut hi = content_span.lo() + rustc_span::BytePos(end as u32);
        if hi == lo && lo < content_span.hi() {
            hi = lo + rustc_span::BytePos(1);
        }
        let span = content_span.with_lo(lo).with_hi(hi);
        let given = tcx.sess.trust_seals().iter().any(|known| {
            known.name == seal.name
                && (known.span.lo() == span.lo() && known.span.hi() == span.hi())
        });
        if given {
            continue;
        }
        let why = deferred.unwrap_or(
            "the session that read this crate's islands before analysis did not report it \
             (an island that comes out of a macro expansion is read only after analysis: \
             declare the seal in an island written in the source)",
        );
        let mut diag = tcx.dcx().struct_span_err(
            span,
            format!("seal `{}` was not checked against the code: {why}", seal.name),
        );
        if deferred.is_some() {
            diag.help(
                "declare the seal in an island placed before the first island that names \
                 `trust_import_`",
            );
        }
        diag.emit();
    }
}

fn trust_report_island_model_checks(
    tcx: TyCtxt<'_>,
    content_span: rustc_span::Span,
    text: &str,
    outcome: &trust_certify::clean_island::CleanIslandOutcome,
) {
    use trust_certify::clean_island::CleanIslandModelVerdict;
    let rejected = outcome.is_rejected();
    for check in &outcome.model_checks {
        // The same island-relative remap every island diagnostic here uses.
        let start = check.start.min(text.len());
        let end = check.end.max(start).min(text.len());
        let lo = content_span.lo() + rustc_span::BytePos(start as u32);
        let mut hi = content_span.lo() + rustc_span::BytePos(end as u32);
        if hi == lo && lo < content_span.hi() {
            hi = lo + rustc_span::BytePos(1);
        }
        let span = content_span.with_lo(lo).with_hi(hi);
        // Whatever the verdict: it is about the model as written, over the
        // naturals, and this is where an integer reading of it differs.
        if let Some(truncation) = check.truncation_report() {
            tcx.dcx().struct_span_warn(span, truncation).emit();
        }
        match check.verdict {
            // A rejected island reports no green and qualifies none.
            CleanIslandModelVerdict::Safe { .. } if !rejected => {
                tcx.dcx().struct_span_note(span, check.report()).emit();
            }
            CleanIslandModelVerdict::Undecided { .. } if !rejected => {
                tcx.dcx().struct_span_warn(span, check.report()).emit();
            }
            CleanIslandModelVerdict::Live { .. } if !rejected => {
                tcx.dcx().struct_span_note(span, check.report()).emit();
            }
            // A progress claim an untrusted search found no counterexample to
            // and the kernel did not prove: never read as a proof.
            CleanIslandModelVerdict::Searched { .. } if !rejected => {
                tcx.dcx().struct_span_warn(span, check.report()).emit();
            }
            // The error is already on the island; this is how it gets there.
            CleanIslandModelVerdict::Unsafe { .. } | CleanIslandModelVerdict::Livelock { .. } => {
                if let Some(run) = check.run_report() {
                    tcx.dcx().struct_span_note(span, run).emit();
                }
            }
            CleanIslandModelVerdict::Safe { .. }
            | CleanIslandModelVerdict::Undecided { .. }
            | CleanIslandModelVerdict::Live { .. }
            | CleanIslandModelVerdict::Searched { .. } => {}
        }
    }
}

/// Trust: check every `clean { … }` parser island in the crate (E10). The
/// island body is Clean source carried span-only through AST/HIR; here the
/// text is recovered from the source map, parsed by the real Clean parser,
/// and every declaration elaborated + registered into a kernel environment
/// (`add_decl` re-typechecks — the L5 gate). Failures map island-relative
/// byte offsets back onto the Rust source and abort the build. Also certifies
/// per-clause runtime monitors against the island environment, then RETURNS
/// the crate-local Clean session so the citation sweep can run separately.
///
/// Ordering contract (E6): this fn must run BEFORE the per-body verification
/// walk — `inject_certified_test_monitors` consumes the monitor records
/// written here from inside `run_pass`. The citation sweep
/// (`trust_check_citations`) runs AFTER the walk, so the session facet table
/// is populated when a cited clause mentions a program function.
///
/// Returns the session plus any islands deferred to the post-walk phase
/// because they name the `trust_import_*` kernel-import namespace. Those
/// constants do not exist until program admissions have been minted.
fn trust_check_clean_islands(
    tcx: TyCtxt<'_>,
) -> (trust_certify::clean_island::CleanIslandSession, Vec<(rustc_span::Span, String)>) {
    crate::trust_lean_census::inventory(tcx);
    use rustc_span::BytePos;
    // HIR's item inventory is not an ordering contract. Clean file state is:
    // namespaces, `open`s, notation, options, and declarations affect later
    // islands. Sort by authored source position before feeding one stateful
    // Environment + FileContext session for this crate.
    //
    // The island TEXT rides along on the HIR node: `rustc_parse` captured the
    // exact bytes it handed to the Clean parser (ruling v7/D1), so the
    // elaborator below sees the same bytes by construction rather than by a
    // second source-map lookup that could disagree. The parse payload
    // (`decls`) is deliberately NOT consumed here — elaboration re-parses with
    // its own tactic-pattern table, and a parse-time success carries no
    // authority.
    let mut island_spans: Vec<(rustc_span::Span, String)> = Vec::new();
    for item_id in tcx.hir_crate_items(()).free_items() {
        if tcx.def_kind(item_id.owner_id) != DefKind::GlobalAsm {
            continue;
        }
        let item = tcx.hir_item(item_id);
        let rustc_hir::ItemKind::CleanIsland { content_span, text, .. } = item.kind else {
            continue;
        };
        island_spans.push((content_span, text.to_string()));
    }
    island_spans.sort_by_key(|(span, _)| (span.lo(), span.hi()));
    let ambiguous_order = island_spans.windows(2).find_map(|pair| {
        let earlier = pair[0].0;
        let later = pair[1].0;
        let same_start = earlier.lo() == later.lo();
        let overlaps = earlier.hi() > later.lo();
        (same_start || overlaps).then_some((earlier, later))
    });

    let mut clean_session = trust_certify::clean_island::CleanIslandSession::new();
    // Trust (TG6): local kernel facts; see `enable_clean_facts`.
    crate::clean_origin_mir::enable_clean_facts(tcx.sess, &mut clean_session);
    // Trust (temporal P2): THIS session reports island results, so it is the
    // one that model-checks the finite models the islands declare — once per
    // build. The resolver's mint session and the per-body environment
    // sessions elaborate the same islands and do not repeat the search.
    clean_session.enable_model_checks();
    // Bindings are read here too: an island that imports `Trust.Binding`
    // alone serves no model module, and one this session finds that the
    // resolver's did not report must be said, never passed over.
    clean_session.enable_binding_reads();
    // Trust (W5, Lean-calls-Rust): the SAME Rust callees the mint declared,
    // declared BEFORE the batch is checked — environment setup only, through
    // the one helper; the verify-ON charges for this shape (callee facets,
    // the cross-language cycle) are design increment 3 and are NOT here.
    let rust_callees = crate::clean_origin_mir::rust_callee_declarations(tcx);
    if let Err(refusal) = clean_session.declare_rust_callees(&rust_callees) {
        tcx.dcx().fatal(format!(
            "internal: the Clean environment refused a Rust callee the mint declared for this \
             crate's islands ({refusal}). Please report it."
        ));
    }
    let mut deferred_islands = Vec::new();
    let mut defer_island_suffix = false;
    if let Some((earlier, later)) = ambiguous_order {
        clean_session.invalidate();
        let diagnostic = tcx.dcx().struct_span_err(
            later,
            "Clean island source order is ambiguous because island spans are equal or overlap",
        );
        let diagnostic = if earlier.lo() != later.lo() || earlier.hi() != later.hi() {
            diagnostic.with_span_label(earlier, "overlapping Clean island span starts here")
        } else {
            diagnostic
        };
        diagnostic
            .with_note(
                "stateful Clean checking requires one unambiguous authored order; macro-collapsed \
                 spans are rejected rather than ordered by DefId or HIR inventory order",
            )
            .emit();
    } else {
        // I1: COLLECT every island's text before checking any of it. Header-first
        // checking elaborates every declaration's signature across the whole
        // crate before any body, so the batch cannot begin until the last
        // island's text exists. The authored sort above is still load-bearing —
        // it orders `FileContext` state (namespace / `open` / options /
        // notation) and the diagnostics — but it no longer decides which names
        // a declaration can resolve.
        let mut batch_islands: Vec<(rustc_span::Span, String)> = Vec::new();
        for (content_span, text) in island_spans {
            // Normal path: the text came straight off the HIR node, captured
            // by the parser. An EMPTY payload is either a genuinely empty
            // island or the one case the parser could not capture (no source
            // behind the span); both are cheap to settle through the source
            // map, and an island whose bytes cannot be recovered at all still
            // fails closed exactly as before.
            let text = if text.is_empty() {
                let Ok(recovered) = tcx.sess.source_map().span_to_snippet(content_span) else {
                    clean_session.invalidate();
                    tcx.dcx().span_err(
                        content_span,
                        "Clean island body could not be recovered from the source map",
                    );
                    continue;
                };
                recovered
            } else {
                text
            };
            // E6 program admissions are minted only after the body walk. An
            // island that names one of those constants must therefore be
            // checked after the mint. Detect it before calling `check`: a
            // rejection taints the stateful session, so probing early would
            // prevent the later valid check and disable unrelated evidence.
            //
            // Clean file state is ordered. Once one island is deferred, defer
            // the complete authored suffix as well: a later island may depend
            // on its namespace, `open`, notation, options, or declarations
            // even when its own text does not repeat `trust_import_`.
            //
            // This partition survives I1: source-order independence holds
            // WITHIN the pre-walk batch and within the post-walk one, not
            // across that boundary, because the post-walk islands need
            // constants that do not exist until program admissions are minted.
            // Trust (TG3): read with Clean's lexer — a comment or a string that
            // mentions the namespace names no constant and defers nothing.
            defer_island_suffix |= trust_certify::clean_island::island_names_kernel_import(&text);
            if defer_island_suffix {
                deferred_islands.push((content_span, text));
                continue;
            }
            batch_islands.push((content_span, text));
        }

        if !batch_islands.is_empty() {
            let texts: Vec<&str> = batch_islands.iter().map(|(_, text)| text.as_str()).collect();
            let batch = if tcx.sess.opts.unstable_opts.trust_lean_census.is_some() {
                let batch = clean_session.check_all_with_census(&texts);
                let sources: Vec<_> =
                    batch_islands.iter().map(|(span, text)| (*span, text.as_str())).collect();
                crate::trust_lean_census::checked(
                    tcx.sess,
                    &sources,
                    crate::trust_lean_census::CheckPhase::HeaderFirst,
                    batch.is_rejected(),
                    &batch.census.as_ref().expect("requested batch census").report,
                );
                batch
            } else {
                // Trust (TG4): only the complete validated pre-walk inventory
                // can take the resolver's actual reporting continuation. A
                // failed source recovery must never disappear behind a match
                // on the surviving islands. Kernel work stays outside the
                // Session-state lock; MIR's immutable snapshot is not consumed.
                let sources: Vec<String> =
                    batch_islands.iter().map(|(_, text)| text.clone()).collect();
                let prepared = if clean_session.is_tainted() {
                    None
                } else {
                    tcx.sess.with_trust_compiler_state::<
                        trust_certify::clean_island_environment::CheckedIslandEnvironment,
                        _,
                    >(|state| state.take_for_reporting(&sources, &rust_callees))
                };
                if let Some(mut prepared) = prepared {
                    // The producer retained declaration state, not a model
                    // verdict or the resolver's reporting policy. Use exactly
                    // the ordinary HIR policy and its existing default limits.
                    prepared.enable_model_checks();
                    prepared.enable_binding_reads();
                    let (continued, batch) =
                        tcx.sess.time("trust_clean_environment_hir_finish", || prepared.finish());
                    clean_session = continued;
                    batch
                } else {
                    tcx.sess.time("trust_clean_environment_hir_recheck", || {
                        clean_session.check_all(&texts)
                    })
                }
            };

            trust_report_island_cycles(tcx, &batch_islands, &batch.cycles);

            for (index, outcome) in batch.outcomes.iter().enumerate() {
                let (content_span, text) = &batch_islands[index];
                let content_span = *content_span;
                if outcome.is_rejected() {
                    for err in &outcome.errors {
                        let start = err.start.min(text.len());
                        let end = err.end.max(start).min(text.len());
                        let lo = content_span.lo() + BytePos(start as u32);
                        let mut hi = content_span.lo() + BytePos(end as u32);
                        if hi == lo && lo < content_span.hi() {
                            hi = lo + BytePos(1);
                        }
                        let span = content_span.with_lo(lo).with_hi(hi);
                        // A batch can fail during header collection or
                        // elaboration, before any terminal kernel check.
                        // Preserve the actual refusal without claiming a
                        // kernel verdict that this outcome does not carry.
                        tcx.dcx().struct_span_err(span, err.message.clone()).emit();
                    }
                } else if !outcome.registered.is_empty() {
                    tcx.dcx()
                        .struct_span_note(
                            content_span,
                            format!(
                                "Clean island kernel-checked: {} declaration(s) registered ({})",
                                outcome.registered.len(),
                                outcome.registered.join(", ")
                            ),
                        )
                        .emit();
                }
                // Trust: qualify that green — see the helper. Outside the
                // `registered` test on purpose: an island holding only the
                // `import` still changes what LATER islands were checked
                // against.
                trust_disclose_island_standin_imports(tcx, content_span, text, outcome);
                trust_report_island_model_checks(tcx, content_span, text, outcome);
                trust_report_unchecked_island_bindings(tcx, content_span, text, outcome, None);
            }
        }
    }

    // Trust: §1.1 monitor sweep over every contract owner. (The E9 citation
    // sweep over the same inventory lives in `trust_check_citations`, which
    // runs after the per-body walk — see the fn doc comment above.)
    //
    // Inventory every HIR body owner, not only `mir_keys`: MIR availability is
    // unrelated to whether an authored contract must be accounted for.
    // Trust: FAIL CLOSED on a loop clause in a body this inventory cannot
    // reach. `lower_body_with_contract` synthesises a HIR `FnContract` out of
    // loop clauses ALONE, in ANY body, and its own comment claims "no authored
    // clause can silently drop". Everything in between then works perfectly and
    // the clause is discarded HERE, with no diagnostic.
    //
    // `def_may_have_contracts` names `Fn | AssocFn | Closure`, but it also
    // requires `opt_hir_owner_nodes(..).is_some()`, and a closure is not its
    // own HIR owner -- so the `Closure` arm is dead in practice and a loop
    // clause written inside a closure is dropped exactly like one in a `const`.
    //
    // MEASURED on the integrated stage2 before this check existed. The
    // identical false invariant and bogus measure --
    // `invariant n == 99 decreases 0` over a loop that runs `n` from 0 to 3 --
    // gives:
    //
    //   pub fn h() -> u32 { .. }                 -> strict exit 1  (refused)
    //   pub const C: u32 = { .. };               -> strict exit 0, ZERO rows
    //   pub static S: u32 = { .. };              -> strict exit 0, ZERO rows
    //   fn g() -> u32 { const { .. } }           -> strict exit 0, ZERO rows
    //   impl T { pub const A: u32 = { .. }; }    -> strict exit 0, ZERO rows
    //   let f = || { .. };  (a CLOSURE)          -> strict exit 0, ZERO rows
    //
    // The closure row is the one that matters most, because `Closure` is named
    // in the admission predicate and looks supported. It is not, and
    // `tests/ui/trust/native_loop_clauses.rs` has carried a loop clause inside
    // a closure since it was written -- unnoticed because that file runs with
    // `-Z trust-verify=off`.
    //
    // That is silent acceptance of a FALSE clause, and it long predates the
    // attribute transport -- it is reachable from the native grammar alone. It
    // is caught here rather than in lowering because this is the one place
    // that knows the exact predicate deciding what gets verified, so the check
    // and the filter cannot drift apart.
    if verification_enabled(tcx.sess) {
        for local in tcx.hir_body_owners() {
            if TrustContractBundle::def_may_have_contracts(tcx, local) {
                continue;
            }
            let Some(body) = tcx.hir_maybe_body_owned_by(local) else { continue };
            let Some(contract) = body.contract else { continue };
            let Some(first) = contract.loop_clauses.first() else { continue };
            tcx.dcx()
                .struct_span_err(
                    first.keyword_span,
                    "a loop clause here would never be verified: the verifier's contract \
                     inventory cannot reach this body",
                )
                .with_span_label(
                    tcx.def_span(local),
                    format!("this {} owns the loop", tcx.def_descr(local.to_def_id())),
                )
                .with_note(
                    "`TrustContractBundle::def_may_have_contracts` admits only a body that is its \
                     own HIR owner and is a function or associated function; the clause here \
                     would be parsed, lowered into a HIR contract, and then dropped when the \
                     verifier builds its inventory, with no diagnostic and no obligation",
                )
                .with_help(
                    "move the loop into a free or associated function and put the clause there",
                )
                .emit();
        }
    }
    let mut contract_owners: Vec<_> = tcx
        .hir_body_owners()
        .filter(|&local| TrustContractBundle::def_may_have_contracts(tcx, local))
        .collect();
    contract_owners.sort_by_key(|&local| {
        let span = tcx.def_span(local);
        (span.lo(), span.hi())
    });
    // Status diagnostics are automatic for the executable test lane and remain
    // opt-in for ordinary check/build invocations. The authoritative durable
    // copy is stamped onto the public verifier-api contract bundle below.
    // Every Trust-enabled body reports only after its pristine-MIR placement
    // preflight in `run_pass`. The island sweep may expose provisional
    // evaluator state only in an explicit verify-off diagnostic probe; it
    // never mints a positive executability status.
    let report_monitor_status = env_flag_enabled("TRUST_MONITOR_REPORT")
        && !verification_enabled(tcx.sess)
        && !targo_certified_monitor_test_mode(tcx.sess);
    for local in contract_owners {
        let bundle = tcx.trust_contracts(local.to_def_id());
        let pointer_width = monitor_target_pointer_width(tcx);

        // Trust: §1.1 per-clause monitored|measured|unmonitored evidence. This sweep
        // is unconditional: it is the producer for both reporting and runtime
        // enforcement. It consumes `c.predicate.kind`, the exact canonical
        // compiler-native predicate that trust-mir-extract feeds into VC
        // generation; source spans are diagnostics only, never a second parser
        // or meaning. A `Monitored` record is created only from the executable
        // payload of a Clean-kernel-accepted EQUIVALENCE certificate
        // (`monitor = true ↔ P`). Failure retains a reason and no expression,
        // so an unsupported clause cannot acquire a dummy `true` at runtime.
        let function_decreases_count = bundle
            .contracts
            .iter()
            .filter(|contract| contract.kind == TrustContractKind::Decreases)
            .count();
        let mut loop_decreases_counts = BTreeMap::new();
        for contract in &bundle.loop_contracts {
            if contract.kind == TrustContractKind::Decreases
                && let rustc_middle::mir::trust_contract::TrustContractSubject::HirLoop {
                    id, ..
                } = contract.subject
            {
                *loop_decreases_counts.entry((id.index, id.hir_local_id)).or_insert(0usize) += 1;
            }
        }
        let mut monitor_records = Vec::with_capacity(bundle.len());
        for (source_index, c) in bundle.iter_all().enumerate() {
            let predicate_digest = canonical_monitor_predicate_digest(c.kind, &c.predicate.kind);
            let static_proposition =
                canonical_monitor_static_proposition(c.kind, &c.predicate.kind);
            let typed_proposition_digest = static_proposition.as_ref().ok().map(|proposition| {
                trust_types::typed_contract_proposition_digest(
                    &proposition.formula,
                    &proposition.variable_domains,
                )
            });
            let evidence = match c.kind {
                TrustContractKind::Requires
                | TrustContractKind::Ensures
                | TrustContractKind::LoopInvariant => {
                    match (canonical_monitor_predicate_text(&c.predicate.kind), static_proposition)
                    {
                        (Ok(text), Ok(static_proposition)) => match (
                            clean_session.environment(),
                            pointer_width.clone(),
                        ) {
                            (Some(env), Ok(pointer_width)) => {
                                let var_types = monitor_var_types_from_static(
                                    &static_proposition,
                                    pointer_width,
                                )
                                .map(|mut var_types| {
                                    // `result` denotes the output record and is
                                    // never initialized at function entry.
                                    if c.kind == TrustContractKind::Requires {
                                        var_types.retain(|(name, _)| name != "result");
                                    }
                                    var_types
                                });
                                match var_types.and_then(|var_types| {
                                    let borrowed = var_types
                                        .iter()
                                        .map(|(name, ty)| (name.as_str(), ty.as_str()))
                                        .collect::<Vec<_>>();
                                    trust_spec_elab::certify_monitor_typed_for_target(
                                        env,
                                        &text,
                                        &borrowed,
                                        pointer_width,
                                    )
                                    .and_then(|certified| {
                                        bind_certified_monitor_to_static_formula(
                                            certified,
                                            static_proposition,
                                        )
                                    })
                                }) {
                                    Ok(bound) => ClauseMonitorEvidence::MonitorCertified(bound),
                                    Err(reason) => ClauseMonitorEvidence::Unmonitored { reason },
                                }
                            }
                            (None, _) => ClauseMonitorEvidence::Unmonitored {
                                reason:
                                    "crate-local Clean session is tainted by a rejected island; \
                                         no positive monitor evidence can be minted"
                                        .to_string(),
                            },
                            (_, Err(reason)) => ClauseMonitorEvidence::Unmonitored { reason },
                        },
                        (Err(reason), _) | (_, Err(reason)) => {
                            ClauseMonitorEvidence::Unmonitored { reason }
                        }
                    }
                }
                TrustContractKind::Decreases
                    if match c.subject {
                        rustc_middle::mir::trust_contract::TrustContractSubject::Function => {
                            function_decreases_count != 1
                        }
                        rustc_middle::mir::trust_contract::TrustContractSubject::HirLoop {
                            id,
                            ..
                        } => {
                            loop_decreases_counts.get(&(id.index, id.hir_local_id)).copied()
                                != Some(1)
                        }
                        _ => true,
                    } =>
                {
                    ClauseMonitorEvidence::Unmonitored {
                        reason: "E5 runtime placement requires exactly one decreases clause per function or source loop; lexicographic/multi-measure semantics are not inferred"
                            .to_string(),
                    }
                }
                TrustContractKind::Decreases => {
                    match (canonical_monitor_predicate_text(&c.predicate.kind), static_proposition)
                    {
                        (Ok(text), Ok(static_proposition)) => match (
                            clean_session.environment(),
                            pointer_width.clone(),
                        ) {
                            (Some(env), Ok(pointer_width)) => {
                                let measured = monitor_var_types_from_static(
                                    &static_proposition,
                                    pointer_width,
                                )
                                .and_then(|var_types| {
                                    let borrowed = var_types
                                        .iter()
                                        .map(|(name, ty)| (name.as_str(), ty.as_str()))
                                        .collect::<Vec<_>>();
                                    trust_spec_elab::certify_measure_typed_for_target(
                                        env,
                                        &text,
                                        &borrowed,
                                        pointer_width,
                                    )
                                    .and_then(|certified| {
                                        bind_certified_measure_to_static_formula(
                                            certified,
                                            static_proposition,
                                        )
                                    })
                                });
                                match measured {
                                    Ok(bound) => ClauseMonitorEvidence::MeasureCertified(bound),
                                    Err(reason) => ClauseMonitorEvidence::Unmonitored { reason },
                                }
                            }
                            (None, _) => ClauseMonitorEvidence::Unmonitored {
                                reason:
                                    "crate-local Clean session is tainted by a rejected island; \
                                     no positive measure evidence can be minted"
                                        .to_string(),
                            },
                            (_, Err(reason)) => ClauseMonitorEvidence::Unmonitored { reason },
                        },
                        (Err(reason), _) | (_, Err(reason)) => {
                            ClauseMonitorEvidence::Unmonitored { reason }
                        }
                    }
                }
                other => ClauseMonitorEvidence::Unmonitored {
                    reason: format!(
                        "runtime placement for compiler contract kind {other:?} is not certified"
                    ),
                },
            };
            let record = ClauseMonitorRecord {
                source_index,
                kind: c.kind,
                subject: c.subject,
                span: c.span,
                predicate_digest,
                typed_proposition_digest,
                evidence,
            };
            if report_monitor_status {
                emit_clause_monitor_status(tcx, &record);
            }
            monitor_records.push(record);
        }
        tcx.sess.with_trust_compiler_state::<SessionCertifiedMonitors, _>(|state| {
            state.functions.insert(local, monitor_records);
        });
    }
    (clean_session, deferred_islands)
}

/// Trust: E6 kernel-import — after the whole-crate per-body walk has populated
/// the session facet table and body inventory, import the defining equation of
/// every facet-certified program function whose body is a recognized shape into
/// `clean_session`'s kernel environment (the one the citation sweep elaborates
/// against), and record the minted admissions so a spec citing such a function
/// elaborates to the imported kernel constant instead of failing closed.
///
/// Must run AFTER the walk (the accumulated bodies + facet certificates are
/// populated there) and BEFORE `trust_check_citations`. Fail-closed throughout:
/// nothing is minted for a tainted session, a non-admissible function, an
/// unrecognized body, or a kernel rejection — the kernel (`add_decl`) is the sole
/// trust root, and the body recognizer is deliberately conservative.
fn trust_mint_program_admissions(
    tcx: TyCtxt<'_>,
    clean_session: &mut trust_certify::clean_island::CleanIslandSession,
) {
    if clean_session.is_tainted() {
        return;
    }
    // Mint from the COMPOSED facet table — the same one `trust_check_citations`
    // consults (`composed_table()` at the citation sweep) — NOT the base
    // whitelist `s.table`. The base whitelist fails every CALL closed, so a
    // facet-certified function that reaches its facets THROUGH a trusted external
    // (e.g. `winc(x) = x.wrapping_add(1)`, certified Pure∧Total∧Det∧NoPanic only
    // via the call-graph closure over the allowlisted `wrapping_add`) is
    // `admissible=false` in the base table and never minted — yet the citation
    // check, reading the composed table, reports its facets certified and then
    // fails closed with "not yet wired". Minting from the composed table makes
    // the two consumers agree. SOUND: minting still requires BOTH admissibility
    // (composed) AND a faithful recognized body shape, so composition only ever
    // turns a fail-closed call into a kernel-rechecked admission.
    let (accumulated, facet_table) =
        tcx.sess.with_trust_compiler_state::<SessionFnFacets, _>(|s| {
            if s.accumulated.is_empty() {
                (Vec::new(), trust_spec_elab::FacetTable::new())
            } else {
                (s.accumulated.clone(), s.composed_table())
            }
        });
    if accumulated.is_empty() {
        return;
    }
    // Trust: TG11 imports nominal ODT signatures first; a struct field is a
    // projection, never the legacy flattened-parameter signature. The frozen
    // recognizer and TG14 scalar arithmetic path remain unchanged.
    let (odt_faces, odt_functions) = crate::trust_odt_e6::e6_faces(tcx, &accumulated)
        .unwrap_or_else(|reason| tcx.dcx().fatal(reason));
    let mut admissions = clean_session
        .admit_odt_program_functions(&odt_faces, &odt_functions, &facet_table)
        .unwrap_or_else(|reason| tcx.dcx().fatal(reason));
    for func in accumulated.iter().filter(|f| trust_types::e6_odt::read(f).is_none()) {
        admissions.extend(
            clean_session.admit_program_functions(std::slice::from_ref(func), &facet_table),
        );
    }
    if admissions.is_empty() {
        return;
    }
    tcx.sess.with_trust_compiler_state::<SessionFnFacets, _>(|s| {
        for (path, admission) in admissions {
            // A PER-FIELD key (`<def_path>__field_<name>`) names no Rust item,
            // so `record_fn_facets` never wrote a facet record for it — and
            // `FacetTable::admitted` requires BOTH an admission and a record,
            // which would make every per-field import fail closed however
            // correctly it was minted. Carry the PARENT's record onto the field
            // key: the field's definition is part of that body, and the mint
            // only ran because the parent was admissible, so the record it
            // inherits is the one that authorised the mint.
            // From the COMPOSED table, not `s.table`. Minting reads the
            // composed one deliberately (the base whitelist fails every call
            // closed), so copying the BASE record can hand the field a
            // non-admissible record while the mint that produced it was already
            // authorised -- and `FacetTable::admitted` then refuses a correctly
            // minted import. Measured exactly that: the mint fired silently and
            // the citation still reported "no per-field E6 import".
            if let Some((parent, _)) = path.split_once("__field_")
                && let Some(parent_facets) = facet_table.get(parent).cloned()
            {
                s.table.insert(path.clone(), parent_facets);
            }
            // A spec cites a function by the spelling it uses — the bare name
            // or a module-qualified suffix — so admit under the def-path AND
            // every such spelling, mirroring how `record_fn_facets` keys the
            // facet record. An ambiguity-evicted spelling has no facet record,
            // so `FacetTable::admitted` still fails closed for it.
            for spelling in trust_spec_elab::spec_spellings(&path) {
                if spelling != path {
                    s.table.admit(spelling, admission.clone());
                }
            }
            s.table.admit(path, admission);
        }
    });
    trust_mint_session_parameter_views(tcx, clean_session, &accumulated, &facet_table);
}

/// Trust (ref-self I1): mint every contracted function's borrow-erased E6
/// PARAMETER VIEW into the SESSION environment and facet table.
///
/// WHY THE SESSION AND NOT ONLY THE TWO PER-BODY CLONES. The in-walk discharge
/// lanes mint into a clone of the stashed island environment, but the post-walk
/// CITATION SWEEP (`trust_check_citations`) and the DEFERRED discharge lane
/// (`finalize_pending_import_citations`) both read THIS session's environment
/// and `SessionFnFacets::composed_table()`. Without this, a `&self` method with
/// a cited `ensures … by <theorem>` was discharged and sealed `Proved` by the
/// in-walk lane and then HARD-ERRORED in the sweep — "the postcondition goal
/// could not be built" — on the row the compiler had just proved (adversarial
/// reviews 1 and 2, blocking finding 2/3). The deferred lane had the same hole
/// in the other direction: it could not discharge at all.
///
/// WHAT THIS DOES NOT DO. It writes NO facet record. The record under a `&self`
/// function's key describes its borrow-bearing body, which `facet_inference`
/// refuses, and inventing a certified one would be a FALSE claim every other
/// reader of this table can see (the sweep prints per-facet status from it).
/// `FacetTable::admitted` answers a `self_result_only` admission from the
/// admission's own isolated certification instead; see its doc.
///
/// REACHABILITY IS UNCHANGED. `Admission::self_result_only` makes a view import
/// unnameable everywhere but the self-call `elaborate_ensures` splices in for
/// `result` in that same function's own `ensures`, so a session-wide admission
/// is not a wider one — it is the same single position, reached from the lanes
/// that run after the walk.
fn trust_mint_session_parameter_views(
    tcx: TyCtxt<'_>,
    clean_session: &mut trust_certify::clean_island::CleanIslandSession,
    accumulated: &[trust_types::VerifiableFunction],
    facet_table: &trust_spec_elab::FacetTable,
) {
    // Deterministic order: the same span order the citation sweep walks in, so
    // a `TRUST_E6_DEBUG` transcript reads the same way in both.
    let mut owners: Vec<LocalDefId> = tcx
        .hir_body_owners()
        .filter(|&local| TrustContractBundle::def_may_have_contracts(tcx, local))
        .collect();
    owners.sort_by_key(|&local| {
        let span = tcx.def_span(local);
        (span.lo(), span.hi())
    });
    let mut minted: Vec<(String, trust_spec_elab::Admission)> = Vec::new();
    for local in owners {
        let def_path = trust_mir_extract::safe_def_path_str(tcx, local.to_def_id());
        let Some(func) = accumulated.iter().find(|func| func.def_path == def_path) else {
            continue;
        };
        if facet_table.has_admission(&def_path) {
            continue;
        }
        let Some(view) = trust_e6_view_of(tcx, local, func) else {
            continue;
        };
        if let Some(one) = clean_session.admit_parameter_view(&view, facet_table) {
            minted.push(one);
        }
    }
    if minted.is_empty() {
        return;
    }
    tcx.sess.with_trust_compiler_state::<SessionFnFacets, _>(|s| {
        for (path, admission) in minted {
            // Keyed under the def-path AND every spec spelling, exactly like the
            // ordinary mint loop above. No facet record is written for either
            // key — see this function's doc.
            for spelling in trust_spec_elab::spec_spellings(&path) {
                if spelling != path {
                    s.table.admit(spelling, admission.clone());
                }
            }
            s.table.admit(path, admission);
        }
    });
}

fn spec_denotation_kind(kind: TrustContractKind) -> Option<&'static str> {
    match kind {
        TrustContractKind::Requires => Some("requires"),
        TrustContractKind::Ensures => Some("ensures"),
        _ => None,
    }
}

fn spec_denotation_source(
    source: rustc_middle::mir::trust_contract::TrustContractSource,
) -> &'static str {
    use rustc_middle::mir::trust_contract::TrustContractSource;
    match source {
        TrustContractSource::Attribute => "attribute",
        TrustContractSource::Native => "native",
        TrustContractSource::Builtin => "builtin",
        TrustContractSource::Inferred => "inferred",
        TrustContractSource::Synthesized => "synthesized",
    }
}

/// Return (resolved Rust signature spelling, target-explicit elaborator
/// spelling) for a query-owned source domain. Pointer-sized domains are made
/// width-explicit before reaching `trust-spec-elab`; bare `usize`/`isize` are
/// intentionally rejected by that elaborator because their meaning otherwise
/// depends on ambient target state.
fn spec_denotation_domain_spellings(
    domain: trust_types::CompilerContractValueDomain,
    pointer_width: trust_spec_elab::TargetPointerWidth,
) -> Result<(&'static str, &'static str), String> {
    use trust_types::CompilerContractValueDomain;
    match domain {
        CompilerContractValueDomain::Bool => Ok(("bool", "bool")),
        CompilerContractValueDomain::MachineInt { width: 8, signed: false } => Ok(("u8", "u8")),
        CompilerContractValueDomain::MachineInt { width: 16, signed: false } => Ok(("u16", "u16")),
        CompilerContractValueDomain::MachineInt { width: 32, signed: false } => Ok(("u32", "u32")),
        CompilerContractValueDomain::MachineInt { width: 64, signed: false } => Ok(("u64", "u64")),
        CompilerContractValueDomain::MachineInt { width: 128, signed: false } => {
            Ok(("u128", "u128"))
        }
        CompilerContractValueDomain::MachineInt { width: 8, signed: true } => Ok(("i8", "i8")),
        CompilerContractValueDomain::MachineInt { width: 16, signed: true } => Ok(("i16", "i16")),
        CompilerContractValueDomain::MachineInt { width: 32, signed: true } => Ok(("i32", "i32")),
        CompilerContractValueDomain::MachineInt { width: 64, signed: true } => Ok(("i64", "i64")),
        CompilerContractValueDomain::MachineInt { width: 128, signed: true } => {
            Ok(("i128", "i128"))
        }
        CompilerContractValueDomain::PointerSizedInt { width, .. }
            if width != pointer_width.bits() =>
        {
            Err(format!(
                "query-owned pointer domain is {width}-bit but compilation target is {}-bit",
                pointer_width.bits()
            ))
        }
        CompilerContractValueDomain::PointerSizedInt { width: 16, signed: false } => {
            Ok(("usize", "usize16"))
        }
        CompilerContractValueDomain::PointerSizedInt { width: 32, signed: false } => {
            Ok(("usize", "usize32"))
        }
        CompilerContractValueDomain::PointerSizedInt { width: 64, signed: false } => {
            Ok(("usize", "usize64"))
        }
        CompilerContractValueDomain::PointerSizedInt { width: 16, signed: true } => {
            Ok(("isize", "isize16"))
        }
        CompilerContractValueDomain::PointerSizedInt { width: 32, signed: true } => {
            Ok(("isize", "isize32"))
        }
        CompilerContractValueDomain::PointerSizedInt { width: 64, signed: true } => {
            Ok(("isize", "isize64"))
        }
        other => Err(format!(
            "query-owned contract domain {other:?} has no exact Clean denotation carrier"
        )),
    }
}

/// Bind the structural proposition's exact variables/domains back to the
/// resolved function signature. The returned type spellings, not a fresh scan
/// of clause text, drive Clean elaboration.
fn spec_denotation_typed_bindings(
    proposition: &StaticMonitorProposition,
    resolved_signature: &[(String, String)],
    pointer_width: trust_spec_elab::TargetPointerWidth,
) -> Result<Vec<(String, String)>, String> {
    let mut seen = BTreeSet::new();
    let mut bindings = Vec::with_capacity(proposition.variable_domains.len());
    for variable in &proposition.variable_domains {
        let name = monitor_formula_variable_name(&variable.name).to_string();
        if !seen.insert(name.clone()) {
            return Err(format!(
                "query-owned contract domain normalizes to duplicate binding `{name}`"
            ));
        }
        let (expected_rust, elaborator) =
            spec_denotation_domain_spellings(variable.domain, pointer_width)?;
        let mut matching = resolved_signature.iter().filter(|(candidate, _)| candidate == &name);
        let Some((_, resolved_rust)) = matching.next() else {
            return Err(format!(
                "query-owned contract variable `{name}` has no resolved function-signature \
                 binding"
            ));
        };
        if matching.next().is_some() {
            return Err(format!("resolved function signature contains duplicate binding `{name}`"));
        }
        if resolved_rust != expected_rust {
            return Err(format!(
                "query-owned contract domain for `{name}` expects Rust `{expected_rust}`, but \
                 the resolved function signature carries `{resolved_rust}`"
            ));
        }
        bindings.push((name, elaborator.to_string()));
    }
    Ok(bindings)
}

/// Trust: A1 (`requires-hyps`) — [`spec_denotation_typed_bindings`] for a
/// DISCHARGE goal.
///
/// Two tables, two jobs, and getting them the wrong way round is how pointer-
/// sized preconditions silently stopped being carryable. The CROSS-CHECK is
/// delegated unchanged to [`spec_denotation_typed_bindings`], which
/// [`trust_fn_discharge_binder_types`]'s own doc block says must be fed the
/// UNRESOLVED signature table (`trust_fn_param_type_names`): its refusal
/// compares the query domain's Rust spelling (`usize`) against the signature's,
/// and a resolved table carries `u64` there, so every `usize` clause failed a
/// check it was never meant to face. What this function then returns is the
/// spelling a DISCHARGE binder needs — the same `discharge_binding_ty_for_target`
/// resolution every E9 discharge lane applies — so the caller's own agreement
/// check compares two independently derived spellings after the identical
/// resolution, instead of comparing an unresolved one with a resolved one.
fn spec_denotation_discharge_bindings(
    proposition: &StaticMonitorProposition,
    unresolved_signature: &[(String, String)],
    pointer_width: trust_spec_elab::TargetPointerWidth,
) -> Result<Vec<(String, String)>, String> {
    // The refusals are this call's, byte for byte; only the SPELLING differs.
    spec_denotation_typed_bindings(proposition, unresolved_signature, pointer_width)?;
    let mut bindings = Vec::with_capacity(proposition.variable_domains.len());
    for variable in &proposition.variable_domains {
        let name = monitor_formula_variable_name(&variable.name).to_string();
        let (expected_rust, _) = spec_denotation_domain_spellings(variable.domain, pointer_width)?;
        bindings.push((
            name,
            trust_spec_elab::discharge_binding_ty_for_target(expected_rust, pointer_width)
                .to_string(),
        ));
    }
    Ok(bindings)
}

/// Trust (TG15 open item 4): the parameter list an uncited `ensures`
/// denotation applies the function's own import to: the FULL resolved
/// signature in DECLARATION order, the table every authority lane passes (the
/// citation sweep's `ensures_params`, the in-walk and deferred discharges and
/// the uncited island-defeq lane all filter `trust_fn_discharge_binder_types`
/// this way), never the clause's own variables.
///
/// `trust_spec_elab::elaborate_ensures_in` rewrites `result` to
/// `self_fn(p0, …, pn)` over the list it is given, in the order given.
/// [`spec_denotation_typed_bindings`] holds only the variables the clause
/// mentions, sorted by NAME: the query-owned domains are collected in a
/// `BTreeMap` by
/// `trust_mir_extract::trust_contract_proposition_to_formula_and_domains_for_class`.
/// Building the call from it put arguments in the wrong slots (a refusal when
/// their carriers differ; when they agree, a well-typed WRONG proposition, so
/// `fn first(b: u8, a: u8) -> u8 { b }` was printed as `first(a, b)`) and
/// dropped every parameter the clause does not mention (a refusal for arity).
///
/// ORDER and MEMBERSHIP come from `signature` alone. The SPELLING stays this
/// lane's statement-only one: a parameter the clause mentions keeps the
/// spelling `typed_bindings` cross-checked against its query-owned domain, and
/// one it does not mention, which has no query-owned domain, is spelled from
/// its resolved Rust type, `usize`/`isize` at the target width through
/// [`spec_denotation_domain_spellings`]. That is the `usize64` spelling a
/// query-owned pointer-sized domain gets, so one row never mixes the two
/// carriers of the pointer-sized divergence [`spec_clean_uncited_ensures_goal`]
/// discloses.
fn spec_denotation_ensures_params(
    signature: &[(String, String)],
    typed_bindings: &[(String, String)],
    pointer_width: trust_spec_elab::TargetPointerWidth,
) -> Result<Vec<(String, String)>, String> {
    signature
        .iter()
        .filter(|(name, _)| name != "result" && !name.starts_with("result."))
        .map(|(name, rust)| {
            if let Some((_, spelled)) = typed_bindings.iter().find(|(bound, _)| bound == name) {
                return Ok((name.clone(), spelled.clone()));
            }
            let spelled = match rust.as_str() {
                pointer_sized @ ("usize" | "isize") => {
                    let domain = trust_types::CompilerContractValueDomain::PointerSizedInt {
                        width: pointer_width.bits(),
                        signed: pointer_sized == "isize",
                    };
                    spec_denotation_domain_spellings(domain, pointer_width)?.1.to_string()
                }
                _ => rust.clone(),
            };
            Ok((name.clone(), spelled))
        })
        .collect()
}

/// The `ensures` arm of [`spec_clean_uncited_denotation`], free of `tcx`: the
/// proposition one uncited `ensures` clause denotes, from the function's
/// resolved signature (`trust_fn_param_type_names`), the clause's query-owned
/// bindings and the function's own name.
fn spec_clean_uncited_ensures_goal(
    clause: &str,
    all_param_types: &[(String, String)],
    typed_bindings: &[(String, String)],
    self_name: &str,
    facets: &trust_spec_elab::FacetTable,
    pointer_width: trust_spec_elab::TargetPointerWidth,
) -> Result<trust_spec_elab::ElaboratedClause, String> {
    // Trust (TG15 open item 4): the self-call's arguments are the full
    // signature in declaration order, as on every authority lane, and not
    // `typed_bindings`, which holds the clause's variables sorted by name.
    let signature_params =
        spec_denotation_ensures_params(all_param_types, typed_bindings, pointer_width)?;
    let params =
        signature_params.iter().map(|(name, ty)| (name.as_str(), ty.as_str())).collect::<Vec<_>>();
    // Trust (nat-lift §5.6): this row is zero-authority, which is
    // exactly why it must not disagree with the lane that has authority
    // — a disclosure row that prints a different proposition than the
    // one the kernel closed is worse than printing none. The lift inputs
    // are built from `typed_bindings`, the table that spells every binder
    // the clause mentions (an unmentioned parameter is spelled by
    // `spec_denotation_ensures_params`, `usize64`/`isize64` when
    // pointer-sized), not from the unresolved `all_param_types`: the
    // lift's self-function cross-check reads the `result` spelling, and
    // reading it from a different table than the binders would make a
    // pointer-sized return spell `usize` here while the goal binds
    // `usize64`, refusing a row whose binders are perfectly readable.
    //
    // KNOWN, DISCLOSED DIVERGENCE (not introduced here): this lane
    // keeps the statement-only `usize64`/`isize64` spelling by design
    // (see `trust_fn_discharge_binder_types`), whose carrier is
    // `BitVec 64`, while the authoritative discharge lanes resolve to
    // `u64`/`i64`, carrier `UInt64`. The two therefore already build
    // different propositions for a pointer-sized binder, before any
    // lift exists; the lift adds one more consequence — `Domain::USize`
    // has no lift row (`LiftRefusal::PointerWidth`) while
    // `Domain::Machine(U64)` does — so a `usize` clause carrying a cast
    // prints a refusal here and discharges there. That is the
    // pre-existing carrier split showing through, and it is recorded in
    // `docs/TCB.md`'s `EnsuresCitationDischarge` row.
    let denotation_inputs = trust_proof_clause_inputs(typed_bindings);
    trust_spec_elab::elaborate_ensures_in(clause, &params, self_name, facets, &denotation_inputs)
}

/// Produce the exact compiler-side Clean denotation for one uncited function
/// clause, or an explicit refusal. The query-owned structural proposition is
/// checked against its retained canonical spelling before that spelling is
/// allowed near the elaborator. Source-span text is never a fallback.
fn spec_clean_uncited_denotation(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    contract: &rustc_middle::mir::trust_contract::TrustContract<'_>,
    all_param_types: &[(String, String)],
    facets: &trust_spec_elab::FacetTable,
) -> (Option<String>, Result<String, String>) {
    let clause = match canonical_monitor_predicate_text(&contract.predicate.kind) {
        Ok(clause) => clause,
        Err(reason) => return (None, Err(reason)),
    };

    // A spelling alone is zero evidence. Only a query-owned Typed proposition
    // whose spelling round-trips to the identical Formula/domain tree may
    // acquire a non-null denotation row. Opaque text remains visible but
    // refused, which is how compatibility input stays counted without being
    // interpreted by guesswork.
    let proposition =
        match canonical_monitor_static_proposition(contract.kind, &contract.predicate.kind) {
            Ok(proposition) => proposition,
            Err(reason) => return (Some(clause), Err(reason)),
        };
    let pointer_width = match monitor_target_pointer_width(tcx) {
        Ok(pointer_width) => pointer_width,
        Err(reason) => return (Some(clause), Err(reason)),
    };
    let typed_bindings =
        match spec_denotation_typed_bindings(&proposition, all_param_types, pointer_width) {
            Ok(bindings) => bindings,
            Err(reason) => return (Some(clause), Err(reason)),
        };

    let goal = match contract.kind {
        TrustContractKind::Requires => {
            let available = typed_bindings
                .iter()
                .filter(|(name, _)| name != "result")
                .map(|(name, ty)| (name.as_str(), ty.as_str()))
                .collect::<Vec<_>>();
            trust_spec_elab::exact_typed_bindings_for_clause(&clause, &available).and_then(
                |exact| {
                    let exact = exact
                        .iter()
                        .map(|(name, ty)| (name.as_str(), ty.as_str()))
                        .collect::<Vec<_>>();
                    trust_spec_elab::elaborate_goal_typed_with_facets(&clause, &exact, facets)
                        .map(|goal| goal.to_string())
                },
            )
        }
        TrustContractKind::Ensures => {
            let self_name = tcx.item_name(local.to_def_id()).to_string();
            spec_clean_uncited_ensures_goal(
                &clause,
                all_param_types,
                &typed_bindings,
                &self_name,
                facets,
                pointer_width,
            )
            .map(|elaborated| elaborated.goal.to_string())
        }
        _ => unreachable!("caller filters denotation kinds"),
    };
    (Some(clause), goal)
}

/// Trust: A1 (design revision 2 `requires-hyps` §2.3) — the candidate
/// hypotheses for one function's cited `ensures` goal.
///
/// A hypothesis has the OPPOSITE polarity to a conclusion: soundness needs
/// "what callers are actually charged ⇒ what the theorem may consume". So this
/// derives every candidate from the QUERY-OWNED canonical proposition — the
/// same `canonical_monitor_static_proposition` /
/// `spec_denotation_typed_bindings` path [`spec_clean_uncited_denotation`] uses
/// (through [`spec_denotation_discharge_bindings`], which fixes the spelling),
/// whose stated rule is that source-span text is never a fallback — and hands
/// `trust-spec-elab` the query's own carrier view alongside the text, so the
/// elaborator can refuse a clause whose two flattenings disagree. The authored
/// spelling is carried for diagnostics only and is never elaborated.
///
/// Three classes never become a candidate, and each returns a refusal STRING
/// rather than disappearing (omission is sound — it only makes the goal harder
/// — but a silent omission is how an author stops being able to predict the
/// goal):
///
///  * a clause with no query-owned typed proposition, or whose canonical
///    spelling does not round-trip to the identical `Formula`/domain tree;
///  * a clause naming `result`: a precondition is an ENTRY-state statement and
///    `result` has no entry-state meaning, so a `requires` that mentions it is
///    refused rather than read at some other state;
///  * a clause naming a `mut` by-value parameter. `G1` uses ONE binder for a
///    parameter in both the hypothesis (entry value) and the conclusion, and a
///    `mut` by-value binding can be reassigned in the body, so the two are not
///    the same value. This is the same gate
///    [`trust_fn_collapsible_by_value_params`] already guards the `p'` collapse
///    with, applied to the shared binder.
///
/// The `requires` clause list is read from the DENSE function-level index;
/// loop clauses live in a separate vector and are not preconditions of the
/// function.
fn cited_requires_hypothesis_inputs(
    tcx: TyCtxt<'_>,
    bundle: &rustc_middle::mir::trust_contract::TrustContractBundle<'_>,
    unresolved_param_types: &[(String, String)],
    collapsible: &FxHashSet<String>,
) -> RequiresHypothesisCandidates {
    let mut inputs = Vec::new();
    let mut propositions = FxHashMap::default();
    let mut refusals = Vec::new();
    let pointer_width = match monitor_target_pointer_width(tcx) {
        Ok(pointer_width) => pointer_width,
        Err(reason) => {
            refusals.push(format!("no `requires` clause can be read on this target: {reason}"));
            return RequiresHypothesisCandidates { inputs, propositions, refusals };
        }
    };
    for (source_index, contract) in bundle.contracts.iter().enumerate() {
        if contract.kind != TrustContractKind::Requires {
            continue;
        }
        let clause = match canonical_monitor_predicate_text(&contract.predicate.kind) {
            Ok(clause) => clause,
            Err(reason) => {
                refusals.push(format!("`requires` #{source_index}: {reason}"));
                continue;
            }
        };
        let proposition =
            match canonical_monitor_static_proposition(contract.kind, &contract.predicate.kind) {
                Ok(proposition) => proposition,
                Err(reason) => {
                    refusals.push(format!("`requires` #{source_index} (`{clause}`): {reason}"));
                    continue;
                }
            };
        let typed_bindings = match spec_denotation_discharge_bindings(
            &proposition,
            unresolved_param_types,
            pointer_width,
        ) {
            Ok(typed_bindings) => typed_bindings,
            Err(reason) => {
                refusals.push(format!("`requires` #{source_index} (`{clause}`): {reason}"));
                continue;
            }
        };
        if typed_bindings.iter().any(|(name, _)| name == "result" || name.starts_with("result.")) {
            refusals.push(format!(
                "`requires` #{source_index} (`{clause}`): a precondition is an entry-state \
                 statement, so `result` has no meaning in it"
            ));
            continue;
        }
        if let Some((name, _)) = typed_bindings.iter().find(|(name, _)| {
            let base = name.split('.').next().unwrap_or(name.as_str());
            !collapsible.contains(base)
        }) {
            refusals.push(format!(
                "`requires` #{source_index} (`{clause}`): `{name}` is not a plain immutable \
                 by-value binding, so its value at entry and its value at return may differ and \
                 one binder cannot stand for both"
            ));
            continue;
        }
        // Diagnostics only. An expanded span cannot faithfully recover
        // macro-produced tokens, so it is not consulted; the canonical spelling
        // stands in, which is also the spelling that is actually graded.
        let authored_text = (!contract.span.from_expansion())
            .then(|| tcx.sess.source_map().span_to_snippet(contract.span).ok())
            .flatten()
            .filter(|text| !text.trim().is_empty())
            .unwrap_or_else(|| clause.clone());
        inputs.push(trust_spec_elab::HypothesisInput {
            contract_index: source_index,
            canonical_text: clause,
            authored_text,
            query_bindings: typed_bindings,
        });
        propositions.insert(source_index, proposition);
    }
    RequiresHypothesisCandidates { inputs, propositions, refusals }
}

/// Trust: A1 — how one hypothesis row is named in a diagnostic.
///
/// The CANONICAL spelling is what is elaborated and therefore what must be shown
/// first: it is the proposition the kernel saw. The AUTHORED spelling is shown
/// beside it only when the two differ after stripping the clause keyword, so an
/// author whose `requires a<=b` canonicalizes to `a <= b` is not told about a
/// difference that is only whitespace, while one whose macro or sugar really did
/// lower to something else can see both. Without this the `authored_text` field
/// was computed from `span_to_snippet` and printed nowhere.
fn hypothesis_row_label(row: &trust_spec_elab::HypothesisRow) -> String {
    let authored = row.authored_text.trim();
    let authored = authored.strip_prefix("requires").unwrap_or(authored).trim();
    let same = authored.split_whitespace().collect::<Vec<_>>()
        == row.canonical_text.split_whitespace().collect::<Vec<_>>();
    if same || authored.is_empty() {
        format!("`{}` (`requires` #{})", row.canonical_text, row.contract_index)
    } else {
        format!(
            "`{}` (`requires` #{}, written `{authored}`)",
            row.canonical_text, row.contract_index
        )
    }
}

/// What [`cited_requires_hypothesis_inputs`] found.
struct RequiresHypothesisCandidates {
    /// The candidates, in contract order.
    inputs: Vec<trust_spec_elab::HypothesisInput>,
    /// The query-owned proposition behind each candidate, by contract index —
    /// the `Formula` and exact carriers CALLERS are charged. Kept so the
    /// non-vacuity guard below asks its question about the charged reading
    /// rather than re-deriving one.
    propositions: FxHashMap<usize, StaticMonitorProposition>,
    /// One line per `requires` clause that could not even be offered.
    refusals: Vec<String>,
}

/// Trust: A1 (design revision 2 `requires-hyps` §2.5) — do the preconditions a
/// conditional discharge actually CARRIED admit any input at all?
///
/// A conditional row on an unsatisfiable precondition is logically true and
/// practically worthless: `requires a < a` makes every postcondition
/// discharge under a hypothesis no caller can ever establish. That is not a
/// soundness failure — it is a green that lies — so this is a DISCLOSURE guard,
/// consulted only to decide what to tell the author, never to grant anything.
///
/// The search runs over the exact query-owned carriers, so an out-of-range
/// witness cannot make `requires c.degree > 255` on a `u8` field look
/// satisfiable. It is a bounded enumeration, and its THREE outcomes are kept
/// apart all the way to the diagnostic: only
/// [`ContractWitnessSearch::NoneInSearchedSet`] may be reported as a search that
/// looked, and even that one is worded as "no satisfying input was found within
/// the bounded search", never as "your precondition admits no value". Collapsing
/// the two negatives is exactly how this note came to state, as a fact about the
/// program, something a capped enumeration cannot establish.
fn bound_hypotheses_have_ground_witness(
    rows: &[trust_spec_elab::HypothesisRow],
    propositions: &FxHashMap<usize, StaticMonitorProposition>,
) -> ContractWitnessSearch {
    requires_propositions_have_joint_ground_witness(
        rows.iter()
            .filter(|row| {
                matches!(row.disposition, trust_spec_elab::HypothesisDisposition::Bound { .. })
            })
            .map(|row| (row.contract_index, propositions.get(&row.contract_index))),
    )
}

/// Trust (OR-A1, owner ruling S1 2026-09-28): the joint bounded witness search
/// over the function's FULL `requires` set — every clause the candidate reader
/// read (`candidates.propositions`), carried or omitted — which is the bar the
/// solver lane applies before it assumes any precondition in the body:
/// `gate_contract_preconditions` searches the whole precondition set JOINTLY and,
/// on anything but `Found`, drops every contract precondition (collective drop).
///
/// A clause the reader REFUSED is part of that set too, and it cannot be
/// searched here, so any refusal makes this search `NotRun` (fail closed). A
/// search over the readable remainder alone could report `Found` for a set whose
/// refused clause contradicts it, and then a conditional credit would again be
/// looser than the lane beside it.
fn full_requires_have_joint_ground_witness(
    candidates: &RequiresHypothesisCandidates,
) -> ContractWitnessSearch {
    if let Some(refusal) = candidates.refusals.first() {
        return ContractWitnessSearch::NotRun {
            reason: format!(
                "a clause of the function's full `requires` set could not be read, so that set \
                 cannot be searched jointly: {refusal}"
            ),
        };
    }
    // `inputs` is in contract order and every input's proposition was
    // inserted beside it, so this is every key of `propositions`, in a
    // deterministic order (no hash-map iteration).
    requires_propositions_have_joint_ground_witness(
        candidates.inputs.iter().map(|input| {
            (input.contract_index, candidates.propositions.get(&input.contract_index))
        }),
    )
}

/// The one joint search both questions above ask: every `(contract index,
/// charged proposition)` pair is searched TOGETHER over its exact carriers, in
/// the order given. A pair whose proposition was not retained makes the search
/// `NotRun`, never a smaller `Found`.
fn requires_propositions_have_joint_ground_witness<'a>(
    clauses: impl IntoIterator<Item = (usize, Option<&'a StaticMonitorProposition>)>,
) -> ContractWitnessSearch {
    let mut formulas = Vec::new();
    let mut domains: BTreeMap<String, trust_types::CompilerContractValueDomain> = BTreeMap::new();
    for (contract_index, proposition) in clauses {
        let Some(proposition) = proposition else {
            return ContractWitnessSearch::NotRun {
                reason: format!(
                    "the charged reading of `requires` #{contract_index} was not retained"
                ),
            };
        };
        formulas.push(proposition.formula.clone());
        for variable in &proposition.variable_domains {
            // Two clauses of one signature must read a name at one carrier. A
            // disagreement is not reconcilable here, so it withholds the note.
            if let Some(previous) = domains.insert(variable.name.clone(), variable.domain) {
                if previous != variable.domain {
                    return ContractWitnessSearch::NotRun {
                        reason: format!(
                            "two `requires` clauses read `{}` at different carriers",
                            variable.name
                        ),
                    };
                }
            }
        }
    }
    let exact: Vec<trust_types::CompilerContractVariableDomain> = domains
        .into_iter()
        .map(|(name, domain)| trust_types::CompilerContractVariableDomain { name, domain })
        .collect();
    trust_mir_extract::contract_assumption_gate::contract_formulas_have_ground_witness(
        &formulas, &exact,
    )
}

/// Trust (OR-A1, owner ruling 2026-09-27 — Inc 1a): what the CONDITIONAL rungs
/// (`G1★`, then `G1`) decided for ONE cited `ensures` clause whose unconditional
/// grade already failed, and whether a discharge lane may CREDIT it.
///
/// ONE decision, shared by the in-walk lane, the deferred post-walk lane and the
/// diagnostic sweep ([`trust_grade_conditional_citation`]), so the three cannot
/// disagree about which clauses are credited — they differ only in the
/// environment they grade against and in what they do with the answer.
struct ConditionalCitationGrade {
    /// The conditional-only ladder the grade came from.
    ladder: trust_certify::clean_island::EnsuresCitationLadder,
    /// The bounded ground-witness search over the CARRIED preconditions — run
    /// only when a conditional rung certified.
    witness: Option<ContractWitnessSearch>,
    /// `Some(link)` exactly when the conditional discharge is CREDITED: a
    /// conditional rung certified, the carried preconditions AND the full
    /// `requires` set (owner ruling S1,
    /// [`full_requires_have_joint_ground_witness`], whose negative outcome is
    /// spelled out in `withheld`) each have a found witness, and the function
    /// has no parameter view.
    credited: Option<trust_certify::clean_island::RequiresLink>,
    /// Why a CERTIFIED conditional rung is nevertheless not credited.
    withheld: Option<String>,
}

/// Trust (OR-A1, Inc 1a): grade the conditional rungs through `grade` and decide
/// the credit. `None` when the function has no `requires` candidate at all (no
/// rung was climbed; the unconditional lane's behaviour is untouched).
///
/// THE CREDIT RULE, and why each conjunct is there:
///
///  * a conditional goal CERTIFIED (`EnsuresCitationLadder::conditional_link`)
///    — the full `cert_meter::grade` and certification audit, the same bar the
///    unconditional rung uses;
///  * the carried preconditions have a ground witness, `Found` ONLY (H3), AND
///    the joint search over the function's FULL `requires` set does too (owner
///    ruling S1, 2026-09-28; [`full_requires_have_joint_ground_witness`]). The
///    second is the same bar the solver lane applies: it assumes the
///    `requires` in the body only when the bounded search over the whole
///    precondition set, jointly, returns `Found`; `NotRun` (e.g. a
///    cross-product past the enumeration budget) and `NoneInSearchedSet` both
///    leave every precondition unassumed there, so a conditional credit over
///    them would be LOOSER than the lane beside it — a contradictory
///    high-arity `requires` would make every postcondition provable by ex
///    falso. The carried-subset search is kept beside it because it is what
///    the disclosure names ("the carried preconditions"). Every negative mints
///    nothing and keeps its disclosure;
///  * no borrow-erased E6 parameter view (the scope limit of this increment:
///    the view lane's own assumption and the requires link would compose, and
///    that composition is not graded here).
///
/// What is NOT decided here: whether the row already carries a static proof
/// (H2) — that is a per-ROW question the lanes answer against their own
/// authority vector ([`trust_rows_with_static_proof`]).
fn trust_grade_conditional_citation(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    candidates: &RequiresHypothesisCandidates,
    grade: impl FnOnce(
        &[trust_spec_elab::HypothesisInput],
    ) -> trust_certify::clean_island::EnsuresCitationLadder,
) -> Option<ConditionalCitationGrade> {
    if candidates.inputs.is_empty() {
        return None;
    }
    let ladder = grade(&candidates.inputs);
    let Some(link) = ladder.conditional_link() else {
        return Some(ConditionalCitationGrade {
            ladder,
            witness: None,
            credited: None,
            withheld: None,
        });
    };
    let witness =
        bound_hypotheses_have_ground_witness(&ladder.hypotheses, &candidates.propositions);
    let full_witness = full_requires_have_joint_ground_witness(candidates);
    let withheld = if let Some(view) = trust_e6_view_marker(tcx, local) {
        Some(format!(
            "this function carries a borrow-erased E6 parameter view (view: {view}); a \
             conditional discharge over a parameter view is outside this increment, so it \
             credits nothing"
        ))
    } else {
        let carried_withheld = match &witness {
            ContractWitnessSearch::Found => None,
            ContractWitnessSearch::NoneInSearchedSet => Some(
                "the bounded search found no input satisfying the carried preconditions, so the \
                 conditional statement may be true of nothing; it credits nothing"
                    .to_string(),
            ),
            ContractWitnessSearch::NotRun { reason } => Some(format!(
                "the carried preconditions were not checked for satisfiability ({reason}); a \
                 conditional discharge is credited only over preconditions with a FOUND ground \
                 witness"
            )),
        };
        carried_withheld.or_else(|| match &full_witness {
            ContractWitnessSearch::Found => None,
            ContractWitnessSearch::NoneInSearchedSet => Some(
                "the bounded search found no input satisfying the function's full `requires` set \
                 jointly, so the solver lane assumes none of it and the conditional statement \
                 may be true of nothing; it credits nothing"
                    .to_string(),
            ),
            ContractWitnessSearch::NotRun { reason } => Some(format!(
                "the function's full `requires` set was not checked jointly for satisfiability \
                 ({reason}); a conditional discharge is credited only when that joint search \
                 FINDS a ground witness, the same bar the solver lane applies before it assumes \
                 a `requires`"
            )),
        })
    };
    let credited = withheld.is_none().then_some(link);
    Some(ConditionalCitationGrade { ladder, witness: Some(witness), credited, withheld })
}

/// Trust (OR-A1 H2): the rows whose EXISTING authority is already a static
/// proof of that row. A conditional credit NEVER replaces one: it would at best
/// relabel a `Trusted` proof and at worst DEMOTE a `KernelCertified` row — which
/// carries publishable `clean-cic` evidence — to a `Trusted` row the
/// authenticated lane withholds (measured: the uncited `eqk` twin's
/// postcondition row is `Certified` today, probe c3). The conditional lane fills
/// only the rows nothing else proved; the unconditional lane's behaviour is
/// untouched by this set.
fn trust_rows_with_static_proof(
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> FxHashSet<usize> {
    proof_authorities
        .iter()
        .enumerate()
        .filter_map(|(index, authority)| {
            let authority = authority.as_ref()?;
            let (vc, result) = results.get(index)?;
            let binding = result_bindings.get(index).and_then(Option::as_ref);
            authority.is_static_proof_for(index, vc, result, binding).then_some(index)
        })
        .collect()
}

/// Trust (OR-A1): the spec-clean disclosure of a CREDITED conditional grade —
/// the goal actually graded (`G1★` or `G1`), the link, and the carried
/// hypotheses in binder order. `None` when the ladder did not render the goal
/// it certified (fail closed: the row then describes the unconditional grade).
fn trust_conditional_goal_row(
    ladder: &trust_certify::clean_island::EnsuresCitationLadder,
    link: trust_certify::clean_island::RequiresLink,
) -> Option<crate::trust_spec_emit::ConditionalGoalRow> {
    use trust_certify::clean_island::RequiresLink;
    let goal_clean = match link {
        RequiresLink::KernelCanonical => ladder.goal_under_requires_canonical.clone()?,
        RequiresLink::AllowListed => ladder.goal_under_requires.clone()?,
    };
    // Every BOUND row must be describable, or no row is written: a list that
    // silently dropped a hypothesis would disclose a goal other than the one
    // graded.
    let mut hypotheses: Vec<(usize, u64, String, String)> = ladder
        .hypotheses
        .iter()
        .filter_map(|row| match &row.disposition {
            trust_spec_elab::HypothesisDisposition::Bound { binder_index } => {
                Some((*binder_index, row))
            }
            trust_spec_elab::HypothesisDisposition::Omitted { .. } => None,
        })
        .map(|(binder_index, row)| {
            let graded = match link {
                RequiresLink::KernelCanonical => row.lifted_text.clone()?,
                RequiresLink::AllowListed => row.canonical_text.clone(),
            };
            Some((
                binder_index,
                u64::try_from(row.contract_index).ok()?,
                row.canonical_text.clone(),
                graded,
            ))
        })
        .collect::<Option<Vec<_>>>()?;
    hypotheses.sort_by_key(|(binder, ..)| *binder);
    Some(crate::trust_spec_emit::ConditionalGoalRow {
        requires_link: link.as_str(),
        goal_clean,
        hypotheses,
    })
}

/// Publish one zero-authority schema-v2 denotation row for every uncited
/// function `requires`/`ensures` clause in the compiler query inventory.
///
/// This runs only after the body walk, program admissions, and deferred-island
/// checks have completed, so result-bearing ensures clauses see the same final
/// facet/admission table the post-walk proof surface sees. It is deliberately
/// separate from every discharge function: rows can expose or refuse a
/// proposition, but can never change a VC, proof authority, diagnostic, or
/// exit status.
fn emit_uncited_contract_clean_denotations(tcx: TyCtxt<'_>) {
    if !crate::trust_spec_emit::emission_requested(tcx) {
        return;
    }
    let facets =
        tcx.sess.with_trust_compiler_state::<SessionFnFacets, _>(|state| state.composed_table());
    let mut contract_owners = tcx
        .hir_body_owners()
        .filter(|&local| TrustContractBundle::def_may_have_contracts(tcx, local))
        .collect::<Vec<_>>();
    contract_owners.sort_by_key(|&local| {
        let span = tcx.def_span(local);
        (span.lo(), span.hi())
    });

    for local in contract_owners {
        let bundle = tcx.trust_contracts(local.to_def_id());
        let def_path = trust_mir_extract::safe_def_path_str(tcx, local.to_def_id());
        let all_param_types = trust_fn_param_type_names(tcx, local);
        // Trust (ref-self I1): the same signature-keyed marker the graded rows
        // carry. This population grants nothing, which is exactly why it must
        // say when its binders name pointee values at entry.
        let view = trust_e6_view_marker(tcx, local);
        // `contracts` is the dense function-level inventory. Loop clauses live
        // in a separate vector and are outside this W3 increment by design.
        for (source_index, contract) in bundle.contracts.iter().enumerate() {
            let Some(kind) = spec_denotation_kind(contract.kind) else {
                continue;
            };
            if contract.citation.is_some() {
                // This population is uncited by definition. Cited `ensures`
                // belong to the authority-bearing goal lane; citation-bearing
                // kinds without such a producer remain outside this bounded
                // W3 increment rather than being mislabeled as uncited.
                continue;
            }
            let (clause, goal) =
                spec_clean_uncited_denotation(tcx, local, contract, &all_param_types, &facets);
            crate::trust_spec_emit::record_uncited_contract_denotation(
                tcx,
                &def_path,
                u64::try_from(source_index).expect("a dense contract index fits u64"),
                kind,
                spec_denotation_source(contract.source),
                clause.as_deref(),
                goal,
                view,
            );
        }
    }
}

/// Recover the semantic spelling one cited `ensures` grade will consume.
/// Authored, non-expanded source remains byte-exact. Expansion spans use the
/// compiler-query spelling because a call-site span cannot faithfully recover
/// macro-produced tokens and never fall back to an unrelated call-site
/// snippet. Ordinary source may fall back to a nonempty canonical query
/// predicate; otherwise the caller emits an explicit counted refusal.
fn cited_ensures_clause_text(
    tcx: TyCtxt<'_>,
    contract: &rustc_middle::mir::trust_contract::TrustContract<'_>,
) -> Result<String, String> {
    let source = || {
        tcx.sess
            .source_map()
            .span_to_snippet(contract.span)
            .map_err(|_| "authored source text is unavailable".to_string())
            .and_then(|text| {
                (!text.trim().is_empty())
                    .then_some(text)
                    .ok_or_else(|| "authored source text is empty".to_string())
            })
    };
    let query = || {
        canonical_monitor_predicate_text(&contract.predicate.kind)
            .map_err(|reason| format!("compiler-query clause spelling is unavailable: {reason}"))
    };

    if contract.span.from_expansion() {
        return query().map_err(|reason| {
            format!(
                "expanded cited clause has no query-owned semantic spelling; call-site source \
                 is not a valid fallback ({reason})"
            )
        });
    }
    match (source(), query()) {
        (Ok(text), _) | (Err(_), Ok(text)) => Ok(text),
        (Err(primary), Err(fallback)) => Err(format!(
            "cited clause could not be prepared for kernel grading ({primary}; {fallback})"
        )),
    }
}

fn cited_goal_origin(tcx: TyCtxt<'_>) -> &'static str {
    let deferred =
        tcx.sess.with_trust_compiler_state::<SessionPendingImportCitations, _>(|state| {
            state.crate_has_deferred_islands
        });
    if deferred { "ensures-citation-deferred" } else { "ensures-citation" }
}

fn reserve_cited_goal_row(tcx: TyCtxt<'_>, local: LocalDefId, contract_index: u64) -> bool {
    if !crate::trust_spec_emit::emission_requested(tcx) {
        return false;
    }
    tcx.sess.with_trust_compiler_state::<SessionEnsuresCitationGoalRows, _>(|state| {
        state.emitted.insert((local, contract_index))
    })
}

/// Trust (nat-lift): the PROOF-clause inputs a user-clause discharge lane runs
/// with — the mode, plus the contracted function's resolved RETURN-type
/// spelling.
///
/// `rows` is the binding table `trust_fn_param_type_names` built, whose
/// `result` entry is derived from `tcx.fn_sig(..).output()` through
/// `trust_resolved_scalar_type`. That is an INDEPENDENT read of the same
/// declaration the E6 mint recorded its return domain from
/// (`trust_types::Ty` off the extracted IR), which is exactly what the lift's
/// self-function cross-check needs: `i128` and `u128` share the carrier
/// `BitVec 128`, so a single recorded domain could select the wrong integer
/// VALUE in a well-typed goal the kernel would happily check. With no `result`
/// row — an unsupported return type — the inputs carry `None` and a lift of a
/// `result`-headed term fails closed.
///
/// Every lane that passes this is a PROOF position: a user `ensures` clause
/// being elaborated into a kernel proposition. Body mints, monitor lanes and
/// the CALL-direction faithfulness gate never receive it, and they cannot
/// acquire it by accident because the clause mode is a parameter of the two
/// `*_in` entry points only.
fn trust_proof_clause_inputs(rows: &[(String, String)]) -> trust_spec_elab::ProofClauseInputs {
    trust_spec_elab::ProofClauseInputs::proof_lift(
        rows.iter().find(|(n, _)| n == "result").map(|(_, t)| t.as_str()),
    )
}

#[allow(clippy::too_many_arguments)]
fn record_graded_cited_goal_once(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    contract_index: u64,
    def_path: &str,
    origin: &str,
    clause: &str,
    params: &[(&str, &str)],
    self_fn_name: &str,
    facets: &trust_spec_elab::FacetTable,
    theorem: &str,
    verdict: &trust_certify::clean_island::CitationVerdict,
    // Trust (nat-lift §5.6, disclosure): the SAME inputs the grade call ran
    // with. The row exists so an author can see the proposition the kernel was
    // asked to close; a row re-elaborated in a different mode would print a
    // different proposition, which is worse than printing none.
    inputs: &trust_spec_elab::ProofClauseInputs,
    // Trust (OR-A1): the CREDITED conditional grade, when the row records one —
    // then `verdict` is that grade's verdict and the row prints the conditional
    // goal the ladder returned (see `trust_conditional_goal_row`).
    conditional: Option<&crate::trust_spec_emit::ConditionalGoalRow>,
) {
    if !reserve_cited_goal_row(tcx, local, contract_index) {
        return;
    }
    crate::trust_spec_emit::record_ensures_citation_goal(
        tcx,
        def_path,
        contract_index,
        origin,
        clause,
        params,
        self_fn_name,
        facets,
        theorem,
        verdict,
        inputs,
        // Trust (ref-self I1): the disclosure on the SPEC-CLEAN row. Computed
        // from the same signature table the authority and the human note read,
        // so the three cannot disagree about which rows rest on the view.
        trust_e6_view_marker(tcx, local),
        conditional,
    );
}

fn record_refused_cited_goal_once(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    contract_index: u64,
    def_path: &str,
    origin: &str,
    theorem: &str,
    reason: &str,
) {
    if !reserve_cited_goal_row(tcx, local, contract_index) {
        return;
    }
    crate::trust_spec_emit::record_ensures_citation_preparation_refusal(
        tcx,
        def_path,
        contract_index,
        origin,
        theorem,
        reason,
    );
}

/// Trust: E9 citation diagnostics sweep — kernel-check every authored
/// `by <thm>` and report its mathematical statement match. This sweep does not
/// discharge or grade a Rust/TrustIR VC: the soundness-critical in-walk or
/// deferred post-walk lane independently checks the exact row and installs
/// sealed authority only for that row. It also fills any still-missing
/// spec-clean goal identity with this real post-walk grade (for example when a
/// body had no eligible VC row); that observational row is never proof
/// authority by itself. Free
/// identifiers are admitted only when they occur in the clause and have an
/// exact resolved scalar binding from that function; unrelated signature
/// entries are removed before the elaborator's exact-bijection gate. Any
/// missing/unsupported identifier or other expression outside the exact
/// fragment is a hard error, never a guessed Nat-domain proof.
///
/// Runs AFTER the per-body verification walk (unlike island/monitor checking
/// in [`trust_check_clean_islands`]) so the session E6 facet table is fully
/// populated when a cited clause mentions a program function.
fn trust_check_citations(
    tcx: TyCtxt<'_>,
    clean_session: &trust_certify::clean_island::CleanIslandSession,
) {
    // Inventory every HIR body owner, not only `mir_keys`: MIR availability is
    // unrelated to whether an authored contract must be accounted for.
    let mut contract_owners: Vec<_> = tcx
        .hir_body_owners()
        .filter(|&local| TrustContractBundle::def_may_have_contracts(tcx, local))
        .collect();
    contract_owners.sort_by_key(|&local| {
        let span = tcx.def_span(local);
        (span.lo(), span.hi())
    });
    for local in contract_owners {
        let bundle = tcx.trust_contracts(local.to_def_id());
        let def_path = trust_mir_extract::safe_def_path_str(tcx, local.to_def_id());
        let goal_origin = cited_goal_origin(tcx);
        // Trust: E6/§1.1 — the citation clause may carry machine-typed free
        // variables (`x <= y` over `u64` params). Recover this function's
        // parameter name → machine-int type table (the SAME source the monitor
        // lane uses) so the clause elaborates over the matching UInt domain
        // instead of failing closed as ungroundable. `result` names the output
        // record; it is meaningful only in an `ensures` clause and is filtered
        // per-clause below. Pointer-sized rows are resolved at the TARGET's
        // width (`trust_fn_discharge_binder_types`), so a `usize` clause binds
        // at the carrier its function's E6 import carries.
        let citation_param_types = trust_fn_discharge_binder_types(tcx, local);
        for (source_index, contract) in bundle.iter_all().enumerate() {
            let Some(citation) = contract.citation else { continue };
            let kind = contract.kind;
            let name = citation.name;
            let citation_span = citation.span;
            if kind == TrustContractKind::Decreases {
                tcx.dcx()
                    .struct_span_err(
                        citation_span,
                        format!(
                            "citation `{name}` on a `decreases` clause cannot be validated \
                             as a typed well-founded transition obligation"
                        ),
                    )
                    .with_note(
                        "decreases citations remain blocked until the before/after measure, \
                         strict descent, and well-founded carrier are bound into TrustIR",
                    )
                    .emit();
                continue;
            }
            let contract_index =
                u64::try_from(source_index).expect("a dense contract index fits u64");
            let clause_text = match cited_ensures_clause_text(tcx, contract) {
                Ok(clause_text) => clause_text,
                Err(reason) => {
                    if kind == TrustContractKind::Ensures {
                        record_refused_cited_goal_once(
                            tcx,
                            local,
                            contract_index,
                            &def_path,
                            goal_origin,
                            name.as_str(),
                            &reason,
                        );
                    }
                    tcx.dcx()
                        .struct_span_err(citation_span, "cited clause text could not be recovered")
                        .with_note(reason)
                        .emit();
                    continue;
                }
            };
            use trust_certify::clean_island::CitationVerdict;
            // Trust: E6 — consult the session facet table so a clause that
            // calls a program function reports per-facet status (or the
            // admission-gate pending message) instead of the bare
            // out-of-fragment error. Diagnostics-only: every call still
            // fails closed inside the elaborator.
            let mut facet_table = tcx
                .sess
                .with_trust_compiler_state::<SessionFnFacets, _>(|state| state.composed_table());
            // Trust: E9 — a CITED `ensures` may name a Clean island DEFINITION
            // (`ensures result == spec(x) by impl_correct`). Offer the clause's
            // island definitions to THIS clause's table exactly as the in-walk
            // and deferred discharge lanes do, so the sweep grades the same
            // goal they graded; without it the sweep refused a clause the
            // authority lane had kernel-discharged ("no diagnostic E6 facet
            // record exists for `spec`"). `facet_table` is rebuilt per clause,
            // so the admission is clause-local. A tainted session has no
            // environment and admits nothing.
            let mut island_refusals: Vec<(String, String)> = Vec::new();
            if kind == TrustContractKind::Ensures
                && let Some(env) = clean_session.environment()
            {
                island_refusals = admit_clause_island_definitions(
                    tcx,
                    local,
                    env,
                    &def_path,
                    &clause_text,
                    &mut facet_table,
                )
                .refused;
            }
            // Trust: why the POSTCONDITION reading of an `ensures` citation could
            // not even be built, when it could not. Reported with the fallback
            // verdict below instead of being dropped (it used to surface only in
            // `-Ztrust-dump=spec-clean`).
            let mut ensures_discharge_refusal: Option<String> = None;
            // Trust (d1/B2, 2026-09-28): the postcondition reading WAS built for a
            // clause that binds `result`, and the cited theorem did not prove it —
            // `(self_name, kernel detail)`. That is THE verdict on the citation;
            // the ∀-`result` fallback below reads the same clause with `result`
            // unbound, a different (generally false) statement, so its kernel
            // detail is a consequence and must not be what the author is told.
            // It was dropped before, and the fallback's refusal led.
            let mut ensures_discharge_mismatch: Option<(String, String)> = None;
            // Trust (d1, 2026-09-28): the CLAUSE MODE every rung below reads this
            // citation in. An `ensures` citation is a proof position, so its
            // discharge rung, its conditional rungs AND its ∀-`result` fallback
            // all elaborate at `ProofLift`; the fallback used to run at `Strict`
            // (a defaulted entry), so a lifted clause (`x as nat`) that the
            // verified lane certifies was refused there as outside the fragment —
            // a hard error with verification off, where the discharge rung cannot
            // bind `result` and the fallback is the only reading left, and a
            // false "the argument is a `u16` term" in either lane. Every other
            // kind stays `Strict`: a `requires`/`invariant`/`assert` clause also
            // feeds runtime-monitor lanes, where the lift has no lowering, and
            // admitting it there is a separate design question.
            let lift_inputs = if kind == TrustContractKind::Ensures {
                trust_proof_clause_inputs(&citation_param_types)
            } else {
                trust_spec_elab::ProofClauseInputs::strict()
            };
            // Trust: E9 DISCHARGE DECISION (design note 2026-07-15 §5c). For an
            // `ensures` citation, first try the postcondition-discharge goal:
            // `result` bound to the E6-admitted self-function's defining
            // equation and ∀-closed over the parameters only — the statement
            // the postcondition VC actually needs — instead of the ∀-over-
            // `result` reading (generally false, so no honest theorem proves
            // it). `Certified` here means the kernel re-checked that the cited
            // proof term proves THIS goal and that its full transitive closure
            // is sorry/axiom-free (`cert_meter::grade`). ADVISORY-ONLY here:
            // the obligation's verdict is untouched (the in-walk discharge that
            // grades the VC is the separate, soundness-critical lane); every
            // non-Certified outcome falls through to the existing advisory
            // citation flow unchanged.
            if kind == TrustContractKind::Ensures {
                let ensures_params: Vec<(&str, &str)> = citation_param_types
                    .iter()
                    .filter(|(n, _)| n != "result" && !n.starts_with("result."))
                    .map(|(n, t)| (n.as_str(), t.as_str()))
                    .collect();
                // E2 by-value primes: rewrite `p'` -> `p` ONLY for plain
                // immutable by-value params (post-state == entry), matching the
                // soundness-critical in-walk discharge (see
                // `trust_fn_collapsible_by_value_params`). A `mut` by-value
                // param's prime is left intact so this advisory note never
                // claims a "kernel-discharges this postcondition" for a clause
                // the verdict lane correctly refuses — the ungated collapse
                // otherwise turns a false `x' >= x` into the tautology `x >= x`
                // and mints a misleading note (diagnostic honesty; no verdict
                // impact, but the same incomplete-gating class as the in-walk fix).
                let collapsible = trust_fn_collapsible_by_value_params(tcx, local);
                let mut ensures_clause_text = clause_text.clone();
                for (pname, _) in &ensures_params {
                    if collapsible.contains(*pname) {
                        ensures_clause_text = rewrite_by_value_prime(&ensures_clause_text, pname);
                    }
                }
                // SELF IDENTITY (2026-08-26): the CANONICAL def-path, not
                // `tcx.item_name`. The bare name re-enters the ambiguity
                // keyspace that `record_fn_facets` deliberately evicts, so a
                // contract on a function whose bare name is shared with any
                // other item (`veripb_core_proved::cap_coeff` beside the
                // `CoeffDomain::cap_coeff` method and its four impls) could
                // never bind `result` — see `trust_spec_elab::self_fn_spelling`
                // for the soundness argument. The def-path here is the SAME
                // string `record_fn_facets` keys by (`VerifiableFunction::
                // def_path` is `safe_def_path_str` of this same `DefId`), so the
                // lookup hits the record that already exists. It also drops the
                // `tcx.item_name` panic on a synthetic body owner.
                let self_def_path = trust_mir_extract::safe_def_path_str(tcx, local.to_def_id());
                let self_key = trust_spec_elab::self_fn_spelling(&self_def_path);
                // The NOTE keeps naming the function the way an author does —
                // its last segment, byte-identical to what `tcx.item_name`
                // printed, so no blessed diagnostic changes. The note hangs on
                // this function's own citation span, where the short name is
                // unambiguous; the KEY above is the part that had to become
                // canonical.
                let self_name =
                    self_def_path.rsplit("::").next().unwrap_or(&self_def_path).to_string();
                use trust_certify::clean_island::CitationVerdict as DischargeVerdict;
                // Trust (nat-lift): the SWEEP is where a cited clause's
                // user-visible hard error is emitted, so it must speak the same
                // fragment as the lanes that grade the VC — otherwise a clause
                // that discharges in the in-walk lane is reported as outside
                // the fragment here. `lift_inputs` (hoisted above, d1) is
                // `ProofLift` for this `ensures` citation, and the ∀-`result`
                // fallback below reads the clause with the SAME inputs.
                let discharge_verdict = clean_session.check_ensures_discharge_in(
                    name.as_str(),
                    &ensures_clause_text,
                    &ensures_params,
                    &self_key,
                    &facet_table,
                    &lift_inputs,
                );
                // Trust (OR-A1, owner ruling 2026-09-27 — Inc 1a). The
                // UNCONDITIONAL goal did not certify: climb the conditional rungs
                // — the same postcondition under this function's eligible
                // `requires` clauses, first in their LIFTED reading (`G1★`, the
                // kernel-canonical link), then in their Clean reading (`G1`, the
                // allow-listed link) — through the session's taint gate, and
                // decide the credit by the ONE rule the in-walk and deferred
                // lanes apply (`trust_grade_conditional_citation`).
                //
                // This sweep stays DIAGNOSTIC-ONLY: it installs no authority.
                // The discharge lanes install the conditional authority over the
                // rows they own — never over a row another lane already proved
                // (H2) — and the sweep's note says so. A credited clause does not
                // fall through to the hard citation error below: the citation is
                // VALID (its theorem kernel-proves the conditional goal with a
                // clean certification audit), exactly as a `G0` success is, and a
                // row no lane credited stays unproved and fails strict
                // verification on its own.
                //
                // The UNRESOLVED signature table, deliberately: the query-owned
                // cross-check inside compares against the Rust spelling
                // (`usize`), which the discharge table has already rewritten to
                // `u64`. `spec_denotation_discharge_bindings` applies that same
                // rewrite to what it RETURNS, so the binder spellings still match
                // `ensures_params`.
                let certified_unconditionally =
                    matches!(discharge_verdict, DischargeVerdict::KernelStatementMatchCertified);
                let candidates = (!certified_unconditionally).then(|| {
                    cited_requires_hypothesis_inputs(
                        tcx,
                        bundle,
                        &trust_fn_param_type_names(tcx, local),
                        &collapsible,
                    )
                });
                let conditional = candidates.as_ref().and_then(|candidates| {
                    trust_grade_conditional_citation(tcx, local, candidates, |hyps| {
                        clean_session.check_ensures_discharge_conditional_in(
                            name.as_str(),
                            &ensures_clause_text,
                            &ensures_params,
                            &self_key,
                            &facet_table,
                            hyps,
                            &lift_inputs,
                        )
                    })
                });
                let goal_row = conditional.as_ref().and_then(|grade| {
                    grade.credited.and_then(|link| trust_conditional_goal_row(&grade.ladder, link))
                });
                let credited = if goal_row.is_some() {
                    conditional.as_ref().and_then(|grade| grade.credited)
                } else {
                    None
                };
                let recorded_verdict = match (&conditional, credited) {
                    (Some(grade), Some(_)) => grade.ladder.verdict.clone(),
                    _ => discharge_verdict.clone(),
                };
                // The graded row re-elaborates through the SAME
                // `elaborate_ensures` path the discharge used, so it receives
                // the canonical `self_key`, not the bare name — a bare-name row
                // could grade a clause the verdict lane resolved differently
                // (the ambiguity-keyspace argument above, applied to grading).
                // Trust (OR-A1): a CREDITED conditional grade prints the
                // conditional goal the ladder returned instead.
                record_graded_cited_goal_once(
                    tcx,
                    local,
                    contract_index,
                    &def_path,
                    goal_origin,
                    &ensures_clause_text,
                    &ensures_params,
                    &self_key,
                    &facet_table,
                    name.as_str(),
                    &recorded_verdict,
                    &lift_inputs,
                    goal_row.as_ref(),
                );
                if certified_unconditionally {
                    let mut diag = tcx.dcx().struct_span_note(
                        citation_span,
                        format!(
                            "citation `{name}` kernel-discharges this postcondition \
                             statement: the cited theorem proves the clause with \
                             `result` bound to the imported definition of \
                             `{self_name}`, with a clean certification audit"
                        ),
                    );
                    diag.note(
                        "E9 citation sweep is diagnostic-only; authority is installed only \
                         by the separately gated in-walk or deferred post-walk discharge \
                         over exact matching result rows",
                    );
                    // Trust (GREEN THAT LIES, 2026-09-18): the cited theorem is
                    // an island declaration of this crate's Clean session, so it
                    // was kernel-checked relative to whatever served that
                    // session's `import`s. Say so beside the row.
                    for disclosure in trust_island_standin_disclosures(tcx) {
                        diag.note(disclosure);
                    }
                    diag.emit();
                    continue;
                }
                // Trust: keep the postcondition lane's own refusal. When the
                // clause binds `result` and this function has no E6 kernel
                // import, the fallback below grades the ∀-`result` reading — a
                // generally false statement — and its kernel TypeMismatch dump
                // used to be the ONLY thing reported, with the actual cause
                // visible only in `-Ztrust-dump=spec-clean`.
                if let DischargeVerdict::ClauseOutsideFragment { reason } = &discharge_verdict {
                    let mut refusal = reason.clone();
                    if trust_spec_elab::is_self_not_e6_admitted_refusal(reason) {
                        refusal.push_str("; ");
                        refusal.push_str(&trust_e6_self_admission_shortfall(
                            tcx,
                            local,
                            &self_def_path,
                            &self_key,
                            &facet_table,
                        ));
                    }
                    ensures_discharge_refusal = Some(refusal);
                }
                // Trust (d1/B2): the postcondition goal WAS built and the theorem
                // does not prove it. Kept only for a clause that binds `result`:
                // for a `result`-free clause the fallback reads the same statement
                // (nothing to bind), so its own verdict already says this, and its
                // pinned message stays byte-identical.
                if let DischargeVerdict::StatementOrCertificationRejected { detail } =
                    &discharge_verdict
                    && trust_clause_binds_result(&clause_text, &citation_param_types)
                {
                    ensures_discharge_mismatch = Some((self_name.clone(), detail.clone()));
                }
                if let (Some(grade), Some(candidates)) = (&conditional, &candidates) {
                    let ladder = &grade.ladder;
                    let carried = ladder
                        .hypotheses
                        .iter()
                        .filter_map(|row| match &row.disposition {
                            trust_spec_elab::HypothesisDisposition::Bound { binder_index } => {
                                Some(format!("h{binder_index} = {}", hypothesis_row_label(row)))
                            }
                            trust_spec_elab::HypothesisDisposition::Omitted { .. } => None,
                        })
                        .collect::<Vec<_>>()
                        .join("; ");
                    let omitted = ladder
                        .hypotheses
                        .iter()
                        .filter_map(|row| match &row.disposition {
                            trust_spec_elab::HypothesisDisposition::Omitted { reason } => {
                                Some(format!("{} — {reason}", hypothesis_row_label(row)))
                            }
                            trust_spec_elab::HypothesisDisposition::Bound { .. } => None,
                        })
                        .collect::<Vec<_>>();
                    if let Some(link) = ladder.conditional_link() {
                        // WHY THE THREE NEGATIVES ARE KEPT APART. The bounded
                        // search has two different negatives, and only one of
                        // them is evidence about the program. `NoneInSearchedSet`
                        // means the enumeration ran over the whole candidate set
                        // and found nothing — worth telling the author, and worded
                        // as a search that looked. `NotRun` means no enumeration
                        // happened; turning THAT into "your preconditions admit no
                        // value" is a red that lies. Neither is CREDITED (H3):
                        // the solver lane assumes a `requires` only on `Found`,
                        // and a conditional credit must not be looser than it.
                        let vacuous =
                            matches!(grade.witness, Some(ContractWitnessSearch::NoneInSearchedSet))
                                && trust_e6_view_marker(tcx, local).is_none();
                        if vacuous {
                            // The theorem does prove the conditional goal — and
                            // the bounded search over the exact carriers found no
                            // input that satisfies the carried preconditions, so
                            // the row may say nothing about any reachable call.
                            // Reporting "your postcondition is discharged under
                            // `requires`" without this caveat would be a green
                            // that lies.
                            tcx.dcx()
                                .struct_span_note(
                                    citation_span,
                                    format!(
                                        "citation `{name}` proves this postcondition only under \
                                         preconditions for which no satisfying input was found"
                                    ),
                                )
                                .with_note(format!(
                                    "the carried `requires` clauses ({carried}) were searched over \
                                     their own carriers and no value satisfying all of them was \
                                     found, so the conditional statement may be true of nothing; \
                                     it is not reported as a discharge"
                                ))
                                .with_note(
                                    "the search is a bounded enumeration, so this is \
                                     \"none found\", not a proof that the preconditions are \
                                     contradictory",
                                )
                                .with_help(
                                    "check the precondition against the parameter's type — a \
                                     bound outside its range (`c.degree > 255` on a `u8`) or a \
                                     contradiction (`a < a`) makes every postcondition provable \
                                     and none enforced",
                                )
                                .emit();
                        } else {
                            let mut diag = tcx.dcx().struct_span_note(
                                citation_span,
                                format!(
                                    "citation `{name}` kernel-discharges this postcondition UNDER \
                                     this function's `requires`, but not unconditionally \
                                     (requires-link: {})",
                                    link.as_str()
                                ),
                            );
                            diag.note(format!(
                                "the cited theorem proves the clause with `result` bound to the \
                                 imported definition of `{self_name}` and these preconditions \
                                 assumed: {carried}"
                            ));
                            // Trust (OR-A1 review, round 2): NOT "every caller is
                            // charged these preconditions" — a call the compiler does
                            // not resolve statically (a fn pointer, `dyn`, a
                            // verify-off crate) is charged nothing. A statically
                            // resolved caller is charged them at every level since
                            // 2026-10-03: `effective_max_level` lifts a caller that
                            // owes a callee `requires` to L1, where the
                            // `L1Functional` call-site `Precondition` row survives
                            // the filter (before, a level-0 caller with no contract
                            // and no extracted precondition was not charged —
                            // `e9_requires_hypothesis_callee_reuse.rs`, revision
                            // `l0`). What holds for every caller is the GUARD — the
                            // callee's `ensures` reaches a caller only as
                            // `requires → ensures` (`callsite.rs`).
                            diag.note(
                                "it therefore says NOTHING about an input that violates them; a \
                                 caller assumes this `ensures` only as `requires → ensures` at a \
                                 statically resolved call, so it obtains the postcondition only \
                                 where it establishes these preconditions there",
                            );
                            match link {
                                trust_certify::clean_island::RequiresLink::KernelCanonical => {
                                    diag.note(
                                        "requires-link: kernel-canonical — each hypothesis the \
                                         theorem consumes was judged by the kernel against the \
                                         LIFTED reading (`x as nat` / `x as int`) of the \
                                         precondition callers are charged; that reading is \
                                         built by the compiler through the nat-lift table",
                                    );
                                }
                                trust_certify::clean_island::RequiresLink::AllowListed => {
                                    diag.note(
                                        "requires-link: allow-listed — the theorem consumes the \
                                         Clean (machine-carrier) reading of the preconditions, \
                                         which is linked to what callers are charged only by \
                                         the arithmetic-free allow-list, not by the kernel",
                                    );
                                    diag.help(
                                        "state each hypothesis over the lifted carrier \
                                         (`UInt64.toNat a = UInt64.toNat b`, not `a = b`) and \
                                         the kernel judges it against the reading callers are \
                                         charged (requires-link: kernel-canonical)",
                                    );
                                }
                            }
                            if let Some(ContractWitnessSearch::NotRun { reason }) = &grade.witness {
                                diag.note(format!(
                                    "the preconditions were NOT checked for satisfiability here, \
                                     so this note does not rule out a vacuous one: {reason}"
                                ));
                            }
                            for omission in &omitted {
                                diag.note(format!(
                                    "not carried as a hypothesis, so the goal is correspondingly \
                                     harder: {omission}"
                                ));
                            }
                            for refusal in &candidates.refusals {
                                diag.note(format!("not offered as a hypothesis: {refusal}"));
                            }
                            match (credited, &grade.withheld) {
                                (Some(_), _) => {
                                    // Trust (OR-A1 review S4): CREDITABLE, not
                                    // credited. This sweep installs nothing, and
                                    // the lanes that do skip every row another
                                    // lane already proved (H2) — often all of
                                    // them — so the note must not claim a credit
                                    // that may not have happened. The
                                    // per-function report note, read off the
                                    // sealed authorities, says which rows were.
                                    diag.note(
                                        "this conditional discharge is creditable to the \
                                         postcondition obligation at `Trusted`, never \
                                         `Certified` (owner ruling OR-A1, 2026-09-27): a row \
                                         already proved by another lane keeps that proof, and \
                                         a row the discharge lane does credit carries the \
                                         requires-link marker, ships no kernel proof evidence, \
                                         and is withheld by the authenticated `targo trust` \
                                         lane; the per-function report names the rows that \
                                         were credited, if any",
                                    );
                                    diag.note(
                                        "E9 citation sweep is diagnostic-only; authority is \
                                         installed only by the separately gated in-walk or \
                                         deferred post-walk discharge over exact matching result \
                                         rows, and never over a row another lane already proved",
                                    );
                                }
                                (None, Some(withheld)) => {
                                    diag.note(format!(
                                        "this conditional discharge is NOT credited to the \
                                         postcondition obligation: {withheld}"
                                    ));
                                }
                                (None, None) => {
                                    diag.note(
                                        "this conditional discharge is NOT credited to the \
                                         postcondition obligation: the conditional goal it \
                                         certified could not be disclosed on the spec-clean row",
                                    );
                                }
                            }
                            // Trust (GREEN THAT LIES, 2026-09-18): the same
                            // qualification the unconditional note carries — the
                            // cited theorem is an island declaration, checked
                            // relative to whatever served this session's imports.
                            for disclosure in trust_island_standin_disclosures(tcx) {
                                diag.note(disclosure);
                            }
                            if credited.is_none() {
                                diag.help(
                                    "to close the obligation, cite a theorem that proves the \
                                     clause for EVERY input; `TRUST_E9_DEBUG=1` prints the goals",
                                );
                            }
                            diag.emit();
                            if credited.is_some() {
                                // The citation is valid: no fallback hard error.
                                continue;
                            }
                        }
                        // Trust (OR-A1 review, round 2): a conditional goal
                        // CERTIFIED and its credit was WITHHELD (vacuous or
                        // unchecked preconditions, a parameter view, or an
                        // undisclosable goal — the note just emitted names which).
                        // The citation stays a hard error, but it must name THAT
                        // cause. Falling through to the typed statement check
                        // below reported a cause that is not this one: "outside
                        // the exact statement fragment: unsupported term shape"
                        // for a lifted clause, or a kernel `TypeMismatch` against
                        // the UNCONDITIONAL goal for a plain one.
                        let cause = grade.withheld.clone().unwrap_or_else(|| {
                            "the conditional goal it certified could not be disclosed on the \
                             spec-clean row"
                                .to_string()
                        });
                        tcx.dcx()
                            .struct_span_err(
                                citation_span,
                                format!(
                                    "citation `{name}` cannot be validated: it kernel-proves this \
                                     postcondition only under this function's `requires` \
                                     (requires-link: {}), and that conditional discharge was \
                                     withheld: {cause}",
                                    link.as_str()
                                ),
                            )
                            .with_note(
                                "authored citations are fail-closed: a conditional discharge that \
                                 is not credited validates nothing, and it proves no row",
                            )
                            .emit();
                        continue;
                    } else if ladder.g1_refusal.is_none() && !carried.is_empty() {
                        // D-A1. The theorem proves NEITHER goal — the common
                        // near-miss, and the case the raw kernel `TypeMismatch`
                        // dump below is least readable in. The ladder has
                        // already built and graded the conditional goals by this
                        // point, so it knows the author has a precondition they
                        // could be proving under and which clauses it would
                        // carry; saying nothing throws that away and leaves the
                        // dump to speak for itself (v7/D3: a refusal carries the
                        // fix, with options).
                        //
                        // Deliberately COMPACT: the goals are large Lean terms,
                        // and `TRUST_E9_DEBUG=1` already prints them. This note
                        // names what was tried, not what it looks like.
                        let binders = ladder
                            .value_binders
                            .iter()
                            .map(|b| format!("`{b}`"))
                            .collect::<Vec<_>>()
                            .join(", ");
                        let states_it =
                            ladder.rung == trust_certify::clean_island::CitationRung::UnderRequires;
                        let mut diag = tcx.dcx().struct_span_note(
                            citation_span,
                            format!(
                                "a SECOND goal was also tried for `{name}`: this \
                                 postcondition under this function's own `requires`"
                            ),
                        );
                        diag.note(format!(
                            "that goal is the clause with `result` bound to the imported \
                             definition of `{self_name}`, universally quantified over \
                             {binders} in that order, with these preconditions as kernel \
                             hypotheses in this order: {carried}"
                        ));
                        let lifted = ladder
                            .hypotheses
                            .iter()
                            .filter_map(|row| row.lifted_text.as_deref())
                            .map(|text| format!("`{text}`"))
                            .collect::<Vec<_>>();
                        if ladder.goal_under_requires_canonical.is_some()
                            && ladder.goal_under_requires_canonical != ladder.goal_under_requires
                        {
                            diag.note(format!(
                                "it was tried twice: with each precondition in its LIFTED \
                                 reading ({}) — the kernel-canonical link — and in its Clean \
                                 machine-carrier reading — the allow-listed link",
                                lifted.join(", ")
                            ));
                        }
                        if states_it {
                            diag.note(
                                "the cited theorem DOES state that goal; what failed is the \
                                 certification audit of its proof, not the statement",
                            );
                        } else {
                            diag.note(
                                "the cited theorem states neither goal, so the mismatch \
                                 reported below is against the UNCONDITIONAL one",
                            );
                        }
                        for omission in &omitted {
                            diag.note(format!(
                                "not carried as a hypothesis, so that goal is \
                                 correspondingly harder: {omission}"
                            ));
                        }
                        diag.help(
                            "options: (1) state the theorem with those hypotheses, in that \
                             order, and it becomes creditable as a conditional discharge at \
                             `Trusted` (owner ruling OR-A1) when the preconditions have a found \
                             ground witness and the function has no parameter view; a row \
                             another lane already proved keeps that proof — stated over the \
                             lifted carrier (`UInt64.toNat a`), each hypothesis is judged by the \
                             kernel against the reading callers are charged (requires-link: \
                             kernel-canonical); (2) prove the clause for EVERY input and it \
                             discharges unconditionally; (3) `TRUST_E9_DEBUG=1` prints the \
                             goals verbatim",
                        );
                        diag.emit();
                    }
                }
            }
            // `result` denotes the output record and is in scope only for an
            // `ensures` citation. Every other role must fail closed if it uses
            // that pseudo-variable rather than binding an entry read of
            // uninitialized RETURN_PLACE (mirrors the monitor lane's rule).
            let available_var_types: Vec<(&str, &str)> = citation_param_types
                .iter()
                .filter(|(n, _)| kind == TrustContractKind::Ensures || n != "result")
                .map(|(n, t)| (n.as_str(), t.as_str()))
                .collect();
            let verdict = match trust_spec_elab::exact_typed_bindings_for_clause(
                &clause_text,
                &available_var_types,
            ) {
                Ok(exact_var_types) => {
                    let exact_var_type_refs = exact_var_types
                        .iter()
                        .map(|(n, t)| (n.as_str(), t.as_str()))
                        .collect::<Vec<_>>();
                    // Trust (d1): the ∀-`result` reading, elaborated in the SAME
                    // clause mode as the discharge rung above (`ProofLift` for an
                    // `ensures` citation, `Strict` for every other kind), with the
                    // same signed-lift seeding. A lifted clause is therefore judged
                    // by statement here — a mismatch the unverified-lane allowance
                    // below already answers — instead of being refused as outside
                    // a fragment the verified lane does not use.
                    clean_session.check_citation_typed_with_facets_in(
                        name.as_str(),
                        &clause_text,
                        &exact_var_type_refs,
                        &facet_table,
                        &lift_inputs,
                    )
                }
                Err(reason) => CitationVerdict::ClauseOutsideFragment { reason },
            };
            // Trust (TG3, COMPILE-TIME-FACTS-1, 2026-11-05): there is no
            // unverified-lane allowance any more. Under `-Ztrust-verify=off` the
            // kernel-only lane (`trust_kernel_discharge_without_verification`)
            // E6-imports every body a cited clause names before this sweep runs,
            // so the discharge rung above binds `result` in both lanes, and a
            // mismatch is the hard error it is with verification on. The note
            // this replaced ("citation … was NOT checked against this
            // postcondition") said a kernel obligation went unchecked in the
            // everyday build; the owner's ruling is that it never does.
            match verdict {
                CitationVerdict::SessionTainted => {
                    tcx.dcx()
                        .struct_span_err(
                            citation_span,
                            format!(
                                "citation `{name}` cannot be validated because an earlier Clean \
                                 island was rejected and the crate-local environment is tainted"
                            ),
                        )
                        .with_note(
                            "positive citation evidence is forbidden after partial island registration",
                        )
                        .emit();
                }
                CitationVerdict::KernelStatementMatchCertified => {
                    tcx.dcx()
                        .struct_span_note(
                            citation_span,
                            format!(
                                "citation `{name}` has a Clean-kernel statement match \
                             with a clean certification audit; this is advisory \
                             only and does not discharge or grade the Rust/TrustIR VC"
                            ),
                        )
                        .emit();
                }
                CitationVerdict::KernelStatementMatchTrusted { closure } => {
                    tcx.dcx()
                        .struct_span_err(
                            citation_span,
                            format!(
                                "citation `{name}` rests on rejected trust provenance: {}; \
                                 suppressible diagnostics cannot carry citation policy",
                                closure.join(", ")
                            ),
                        )
                        .with_note(
                            "the statement match is non-authoritative and does not discharge \
                             or grade the Rust/TrustIR VC",
                        )
                        .emit();
                }
                CitationVerdict::TheoremNotFound => {
                    // Trust (cross-crate proof citation, increment 2): this
                    // refusal used to carry NO options at all, which made the
                    // commonest cross-crate attempt — a contract citing a
                    // dependency's theorem — indistinguishable from a typo.
                    // The notes below are facts of TRANSPORT only (which
                    // dependencies published Clean islands, and how many);
                    // nothing here runs a kernel or claims the cited name
                    // exists in one of them, and nothing here changes the
                    // verdict: a cross-crate citation is refused exactly as it
                    // was.
                    let mut diag = tcx.dcx().struct_span_err(
                        citation_span,
                        format!(
                            "cited theorem `{name}` is not registered in any Clean \
                             island or the prelude"
                        ),
                    );
                    if let Some(notes) =
                        crate::clean_extern_proof::cross_crate_citation_notes(tcx, name.as_str())
                    {
                        for note in notes {
                            diag.note(note);
                        }
                    }
                    diag.emit();
                }
                CitationVerdict::DeclarationNotTheorem { kind } => {
                    tcx.dcx()
                        .struct_span_err(
                            citation_span,
                            format!(
                                "cited declaration `{name}` is {kind}, not a theorem; \
                                 definitions, opaques, and axioms cannot serve as citations"
                            ),
                        )
                        .emit();
                }
                CitationVerdict::UnsafeTheorem => {
                    tcx.dcx()
                        .struct_span_err(
                            citation_span,
                            format!("cited theorem `{name}` is marked `unsafe`"),
                        )
                        .emit();
                }
                CitationVerdict::PartialTheorem => {
                    tcx.dcx()
                        .struct_span_err(
                            citation_span,
                            format!("cited theorem `{name}` is marked `partial`"),
                        )
                        .emit();
                }
                CitationVerdict::NoProofTerm => {
                    tcx.dcx()
                        .struct_span_err(
                            citation_span,
                            format!(
                                "cited theorem `{name}` has no proof term; malformed \
                                 theorem records are rejected"
                            ),
                        )
                        .emit();
                }
                CitationVerdict::ClauseOutsideFragment { reason } => {
                    // Trust (d1/B2): the postcondition goal WAS built and refuted;
                    // that is the verdict, and this fallback refusal is only why
                    // the ∀-`result` reading could not be judged as well.
                    if let Some((self_name, discharge_detail)) = &ensures_discharge_mismatch {
                        trust_emit_cited_postcondition_mismatch(
                            tcx,
                            local,
                            citation_span,
                            name.as_str(),
                            self_name,
                            discharge_detail,
                            &clause_text,
                            &island_refusals,
                            format!(
                                "the clause with `result` universally quantified (the reading \
                                 used when no function body is imported) could not be \
                                 elaborated either: {reason}"
                            ),
                        );
                        continue;
                    }
                    // Trust: the postcondition lane's own refusal and any island
                    // definition kept out of the clause ride along as notes.
                    let (context_notes, context_helps) = trust_cited_ensures_refusal_context(
                        Some(&reason),
                        ensures_discharge_refusal.as_deref(),
                        &island_refusals,
                    );
                    let mut diag = tcx.dcx().struct_span_err(
                        citation_span,
                        format!(
                            "citation `{name}` cannot be validated because this clause \
                             is outside the exact statement fragment: {reason}"
                        ),
                    );
                    diag.note(
                        "authored citations are fail-closed; missing or unsupported source \
                         bindings are never guessed, and a statement match remains \
                         non-authoritative until it is bound to the exact typed TrustIR \
                         obligation end-to-end",
                    );
                    // Trust: name the carrier a `usize`/`isize` binder took.
                    if let Some(note) = trust_pointer_sized_binder_note(tcx, local, &clause_text) {
                        diag.note(note);
                    }
                    for note in context_notes {
                        diag.note(note);
                    }
                    for help in context_helps {
                        diag.help(help);
                    }
                    diag.emit();
                }
                CitationVerdict::StatementOrCertificationRejected { detail } => {
                    // Trust (d1/B2): when the postcondition goal WAS built, the
                    // theorem's failure against IT is the verdict — the body and the
                    // theorem disagree, or the theorem is stated over something
                    // else. The ∀-`result` reading is a different statement, and
                    // leading with its kernel detail told the author about a goal
                    // nobody asked them to prove.
                    if let Some((self_name, discharge_detail)) = &ensures_discharge_mismatch {
                        trust_emit_cited_postcondition_mismatch(
                            tcx,
                            local,
                            citation_span,
                            name.as_str(),
                            self_name,
                            discharge_detail,
                            &clause_text,
                            &island_refusals,
                            "the clause was also graded with `result` universally quantified \
                             (the reading used when no function body is imported), and the \
                             cited theorem does not prove that reading either"
                                .to_string(),
                        );
                        continue;
                    }
                    // Trust: when the postcondition goal could not be BUILT, the
                    // kernel detail is about the ∀-`result` fallback reading — a
                    // consequence, not the cause. Lead with the cause and keep the
                    // kernel detail as the trailing note. The message head is
                    // unchanged, so every `//~ ERROR citation .. failed the strict
                    // Clean statement/certification audit` pin still matches.
                    let (context_notes, context_helps) = trust_cited_ensures_refusal_context(
                        None,
                        ensures_discharge_refusal.as_deref(),
                        &island_refusals,
                    );
                    let mut diag = match &ensures_discharge_refusal {
                        Some(refusal) => tcx.dcx().struct_span_err(
                            citation_span,
                            format!(
                                "citation `{name}` failed the strict Clean statement/\
                                 certification audit: the postcondition goal could not be \
                                 built ({refusal}), so the citation was graded against the \
                                 clause with `result` universally quantified, which the cited \
                                 theorem does not prove"
                            ),
                        ),
                        None => tcx.dcx().struct_span_err(
                            citation_span,
                            format!(
                                "citation `{name}` failed the strict Clean statement/\
                                 certification audit: {detail}"
                            ),
                        ),
                    };
                    diag.note(
                        "statement drift and authority/provenance failures are hard \
                         citation errors; there is no router fallback (E9)",
                    );
                    // Trust: name the carrier a `usize`/`isize` binder took.
                    if let Some(note) = trust_pointer_sized_binder_note(tcx, local, &clause_text) {
                        diag.note(note);
                    }
                    for note in context_notes {
                        diag.note(note);
                    }
                    for help in context_helps {
                        diag.help(help);
                    }
                    if ensures_discharge_refusal.is_some() {
                        diag.note(format!(
                            "kernel detail for the universally-quantified `result` reading: \
                             {detail}"
                        ));
                    }
                    diag.emit();
                }
            }
        }
    }
}

/// Trust: the notes and `help` options a refused `ensures` citation carries
/// beyond its primary message (v7/D3: what was refused, why, and what to do).
///
/// * `discharge_refusal` — why the POSTCONDITION reading (`result` bound to this
///   function's E6 kernel import) could not be built. Not repeated as a note
///   when the primary message already leads with it (`reported_reason` is
///   `None`) or merely restates it, which is the case for a `result`-free
///   clause (both readings elaborate the same text).
/// * `island_refusals` — every Clean island DEFINITION the clause names that
///   was kept out of the clause, with the admitter's reason.
///
/// Diagnostics only; no verdict reads any of it.
fn trust_cited_ensures_refusal_context(
    reported_reason: Option<&str>,
    discharge_refusal: Option<&str>,
    island_refusals: &[(String, String)],
) -> (Vec<String>, Vec<String>) {
    let mut notes = Vec::new();
    let mut helps = Vec::new();
    // Trust: "restates" is judged modulo whitespace. `elaborate_ensures`
    // re-tokenizes the clause (`quote!` re-spaces `f(x)` as `f (x)`), so two
    // refusals that embed the clause text can differ in spacing alone; that is
    // not a second reason and must not print as one.
    let squash = |text: &str| text.chars().filter(|c| !c.is_whitespace()).collect::<String>();
    if let Some(refusal) = discharge_refusal {
        if reported_reason
            .is_some_and(|reported| !squash(refusal).starts_with(squash(reported).as_str()))
        {
            notes.push(format!(
                "read as a postcondition (`result` bound to this function's E6 kernel import), \
                 the clause was refused before any theorem was consulted: {refusal}"
            ));
        }
        if trust_spec_elab::is_self_not_e6_admitted_refusal(refusal) {
            // Trust (TG3): one help for both lanes. With verification off the
            // kernel-only lane imports the cited function's body too, so the
            // cure is the same: a body the E6 lane can read.
            helps.push(
                "options: (1) reduce the body to an E6-importable shape — a projection, a \
                 constant, a wrapping `+`/`-`/`*` tree, a select \
                 (`if a < b { a } else { b }`), a comparison, `==`/`!=` over `bool`, a \
                 `bool` connective tree (`&&`, `||`, `!` over `bool` parameters and \
                 comparisons), or a decision tree (`if`/`else`, `match` on a parameter \
                 with literal arms and `_`) — so `result` has a kernel denotation; (2) \
                 state the fact over the parameters only: a clause that does not mention \
                 `result` is graded on any body; (3) drop the `by` citation and let the \
                 solver lanes prove the clause"
                    .to_string(),
            );
        }
    }
    for (island_name, reason) in island_refusals {
        notes.push(format!(
            "the Clean island definition `{island_name}` named in this clause was not admitted \
             into it: {reason}"
        ));
    }
    (notes, helps)
}

/// Trust (d1): whether a cited clause binds the `result` pseudo-variable (or a
/// `result.field` projection) against this function's signature table — the
/// same predicate the unverified-lane allowance applies. Diagnostics only.
fn trust_clause_binds_result(clause: &str, signature: &[(String, String)]) -> bool {
    let rows: Vec<(&str, &str)> = signature.iter().map(|(n, t)| (n.as_str(), t.as_str())).collect();
    trust_spec_elab::exact_typed_bindings_for_clause(clause, &rows)
        .is_ok_and(|bound| bound.iter().any(|(n, _)| n == "result" || n.starts_with("result.")))
}

/// Trust (d1/B2, 2026-09-28): the refusal for a cited `ensures` whose
/// POSTCONDITION goal was built — `result` bound to the imported definition of
/// `self_name` — and which the cited theorem does not prove.
///
/// Before, this outcome was dropped and the error spoke about the ∀-`result`
/// fallback instead: a kernel dump against a statement nobody asked for, or,
/// for a lifted clause, "the argument is a `u16` term" about an argument the
/// author had written `x as nat`. The message HEAD is the one every existing
/// `failed the strict Clean statement/certification audit` pin matches.
///
/// `fallback_note` says what the ∀-`result` reading did; it is reported after
/// the verdict, never instead of it. Diagnostics only: no authority is read or
/// written, and the refusal is the same hard error it was.
#[allow(clippy::too_many_arguments)]
fn trust_emit_cited_postcondition_mismatch(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    citation_span: rustc_span::Span,
    name: &str,
    self_name: &str,
    discharge_detail: &str,
    clause_text: &str,
    island_refusals: &[(String, String)],
    fallback_note: String,
) {
    let mut diag = tcx.dcx().struct_span_err(
        citation_span,
        format!(
            "citation `{name}` failed the strict Clean statement/certification audit against \
             this postcondition with `result` bound to the imported definition of \
             `{self_name}`: {discharge_detail}"
        ),
    );
    diag.note(
        "statement drift and authority/provenance failures are hard citation errors; there is \
         no router fallback (E9)",
    );
    if let Some(note) = trust_pointer_sized_binder_note(tcx, local, clause_text) {
        diag.note(note);
    }
    for (island_name, reason) in island_refusals {
        diag.note(format!(
            "the Clean island definition `{island_name}` named in this clause was not admitted \
             into it: {reason}"
        ));
    }
    diag.note(fallback_note);
    diag.help(format!(
        "options: (1) if the theorem states the intended rule, the body of `{self_name}` \
         disagrees with it: fix the body; (2) if the body is intended, restate the theorem so it \
         proves the clause with `result` replaced by `{self_name}`'s imported definition; (3) \
         drop the `by` citation and let the solver lanes prove the clause; `TRUST_E9_DEBUG=1` \
         prints the goal verbatim"
    ));
    diag.emit();
}

/// Trust: WHY a function has no E6 kernel import — the facet(s) the structural
/// scan could not establish, or, when all four hold, that the body is not an
/// importable shape. `elaborate_ensures` can only say "it is not admitted";
/// the recogniser's inputs are all still in the session, so say which half
/// failed. Diagnostics only: it re-reads the records, mints nothing, and no
/// verdict consults it.
fn trust_e6_self_admission_shortfall(
    tcx: TyCtxt<'_>,
    // Trust (ref-self I1): the function's own `LocalDefId`, so the shortfall can
    // name the D-REF reason a BORROWED parameter was not admitted. Without it
    // the author of a `&self` method gets "E6 facet(s) not established: Pure,
    // Total, …", which is true and useless — the facets are unestablished
    // BECAUSE the borrow is outside the fragment, and what they need to know is
    // which condition of the parameter view their signature missed.
    local: LocalDefId,
    self_def_path: &str,
    self_key: &str,
    facets: &trust_spec_elab::FacetTable,
) -> String {
    // Trust: TG11 names guards even when MIR optimization erased them.
    if let Some(reason) = crate::trust_odt_e6::e6_refusal(tcx, local) {
        return reason;
    }
    // The borrowed-parameter reasons come FIRST and are joined onto whatever
    // the facet/shape explanation says: a `&mut self` method has both, and the
    // borrow is the one the author can act on.
    let (_, borrow_notes) = trust_frozen_shared_param_scan(tcx, local, true);
    let borrow_prefix = if borrow_notes.is_empty() {
        String::new()
    } else {
        format!("{}; ", borrow_notes.join("; "))
    };
    let Some(record) = facets.get(self_key) else {
        return format!(
            "{borrow_prefix}no E6 facet record exists for `{self_def_path}`: its body was not \
             extracted in this compilation (the body was skipped, or it is not a nameable \
             local function), or its spec spelling is shared with another item"
        );
    };
    // Trust (E6 expansion I0): name the GATE that refused and the construct it
    // refused. `explain_e6_admission_refusal` re-runs `admit_function_into`'s
    // gate predicates in its order — facet gate, shape gate
    // (`recognize_admissible_body`, island forwarding, and the E6-only reader
    // once it reads a node), mint — over the SAME extracted body and record,
    // and mints nothing.
    let func = tcx.sess.with_trust_compiler_state::<SessionFnFacets, _>(|state| {
        state.accumulated.iter().find(|func| func.def_path == self_def_path).cloned()
    });
    // Trust (E6 expansion I0, review): what the extracted body cannot say. The
    // extraction the E6 lane reads lowers `char` to `u32` and `usize`/`isize`
    // to the pointer-width integers, so the parameters are spelled from the
    // SOURCE signature; and `facets` holds this session's admissions, so a
    // mint the kernel refused as a `DuplicateName` (another function's import
    // already holds the mangled name) is named as that collision.
    let source_param_types: Option<Vec<String>> =
        matches!(tcx.def_kind(local), DefKind::Fn | DefKind::AssocFn).then(|| {
            let sig = tcx.fn_sig(local.to_def_id()).instantiate_identity().skip_binder();
            sig.inputs().iter().map(|ty| with_no_trimmed_paths!(ty.to_string())).collect()
        });
    let cx = trust_certify::clean_island::E6RefusalContext {
        table: Some(facets),
        source_param_types: source_param_types.as_deref(),
    };
    match func {
        Some(func) => format!(
            "{borrow_prefix}{}",
            trust_certify::clean_island::explain_e6_admission_refusal_with(&func, record, cx)
        ),
        None if !record.admissible() => format!(
            "{borrow_prefix}E6 admission of `{self_def_path}` was refused by the FACET gate: {}",
            record.deficits().join(", ")
        ),
        None => format!(
            "{borrow_prefix}all four E6 facets of `{self_def_path}` hold, but its extracted \
             body is not in this session's inventory"
        ),
    }
}

fn trust_contracts_if_any<'tcx>(
    tcx: TyCtxt<'tcx>,
    def_id: DefId,
) -> Option<&'tcx TrustContractBundle<'tcx>> {
    match def_id.as_local() {
        None => Some(tcx.trust_contracts(def_id)),
        Some(local) if TrustContractBundle::def_may_have_contracts(tcx, local) => {
            Some(tcx.trust_contracts(def_id))
        }
        Some(_) => None,
    }
}

/// Trust (W5, 2026-10-01): does `def_id` carry a `requires` — its own, or one
/// decoded from its crate's metadata? The MIR inliner asks this before copying a
/// callee into a caller, because the callee's precondition is charged at the
/// `Call` and its body may have had checks elided under that `requires`
/// (`inline.rs`, docs/KNOWN_HAZARDS.md "under explicit `-Zinline-mir`").
pub(crate) fn callee_carries_trust_requires(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    trust_contracts_if_any(tcx, def_id).is_some_and(|bundle| bundle.summary.requires > 0)
}

pub(crate) fn verification_enabled(sess: &Session) -> bool {
    // Activation is a tracked Session option only. The driver translates the
    // exact nested-process transport `TRUST_NO_VERIFY=1` into
    // `-Ztrust-verify=off` before option parsing; MIR and every later phase read
    // only the resulting Session state.
    sess.trust_verification_enabled()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct FullVerificationFailure {
    failed: u32,
    unknown: u32,
    runtime_checked: u32,
    skipped: u32,
}

impl FullVerificationFailure {
    fn total(self) -> u32 {
        self.failed
            .saturating_add(self.unknown)
            .saturating_add(self.runtime_checked)
            .saturating_add(self.skipped)
    }

    fn is_empty(self) -> bool {
        self.total() == 0
    }
}

/// Trust: whether the strict-verification diagnostic may truthfully recommend
/// the nonfatal advisory policy for this failure.
///
/// The recommendation is intentionally narrower than "the build failed". A
/// concrete refutation is not a coverage gap, and structurally invalid native
/// evidence is not safe to interpret well enough to recommend a policy change.
/// At least one actual gap category must also be present so an empty failure can
/// never grow misleading guidance if a caller changes.
fn advisory_policy_help_applies(
    failure: FullVerificationFailure,
    has_unproved_assumption_panic: bool,
    native_structurally_sound: bool,
) -> bool {
    native_structurally_sound
        && failure.failed == 0
        && (has_unproved_assumption_panic
            || failure.unknown > 0
            || failure.runtime_checked > 0
            || failure.skipped > 0)
}

/// Is this L0 failure fatal to the build?
///
/// `require_full_discharge` (i.e. `targo trust certify`) keeps the historical
/// all-obligations gate: every non-proved bucket is fatal, because a timeout or
/// unsupported/skipped obligation is not a proof merely for not being a concrete
/// counterexample.
///
/// The DEFAULT is the ratified completeness-gap policy
/// (`docs/design/2026-07-25-completeness-gap-policy-ruling.md`). Two buckets stay
/// fatal and one does not:
///
/// * `failed` — a refutation. The verifier found a bug; report it.
/// * `unknown` / `skipped` — treated as having no runtime fallback. For the
///   LEGACY arm that is exact: it splits on
///   `runtime_check_available(&vc.kind, overflow_checks)`, so a row lands in
///   `unknown` precisely because nothing catches it at runtime. The native arm
///   does NOT consult that predicate, so a native row can land here even though
///   its operation does keep a check — conservative in the safe direction (it
///   fails a build that policy B would have allowed), never the unsafe one.
///   Accepting a genuine no-fallback row would ship unverified behaviour with
///   nothing beneath it: the UB class.
/// * `runtime_checked` — rustc still emits the check. Such a row is bit-for-bit
///   vanilla Rust semantics, so failing the build on it buys no safety and costs
///   drop-in. This is the only bucket the default now tolerates.
///
/// Note this needs NO new classification: the split already existed and is
/// single-sourced through `VcKind::has_runtime_fallback`.
fn strict_failure_is_fatal(failure: FullVerificationFailure, require_full_discharge: bool) -> bool {
    if require_full_discharge {
        return !failure.is_empty();
    }
    failure.failed > 0 || failure.unknown > 0 || failure.skipped > 0
}

/// Whether the compiler minted the exact private capability that identifies
/// this row as the function's catalog-only definition-entry assumption. The
/// public VC kind, solver label, and transport strings are attribution only;
/// none of them may suppress strict proof accounting on their own.
fn result_row_is_authenticated_definition_entry_assumption(
    index: usize,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> bool {
    let Some((vc, result)) = results.get(index) else { return false };
    matches!(result, VerificationResult::Proved { .. })
        && proof_authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
            authority.is_definition_entry_assumption_for(
                index,
                vc,
                result_bindings.get(index).and_then(Option::as_ref),
            )
        })
}

fn transport_row_is_authenticated_definition_entry_assumption(
    index: usize,
    transport: &TransportObligationResult,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> bool {
    if !result_row_is_authenticated_definition_entry_assumption(
        index,
        results,
        result_bindings,
        proof_authorities,
    ) {
        return false;
    }
    let Some((_, result)) = results.get(index) else { return false };
    let Some(binding) = result_bindings.get(index).and_then(Option::as_ref) else { return false };
    transport.kind == TRUST_ENTRY_ASSUMPTION_TRANSPORT_KIND
        && transport.outcome == Outcome::Skipped
        && transport.obligation_id.as_deref() == Some(binding.public_obligation_id.as_str())
        && transport.solver == result.solver_name()
        && transport.reason.as_deref() == Some(TRUST_ENTRY_ASSUMPTION_REASON)
        && transport.counterexample.is_none()
        && transport.counterexample_model.is_none()
        && !transport.design_mandate
        && transport.native_trust_ir.is_none()
        && transport.proof_evidence.is_none()
}

fn result_row_is_authenticated_assumed_total_assumption(
    index: usize,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> bool {
    let Some((vc, result)) = results.get(index) else { return false };
    matches!(result, VerificationResult::Proved { .. })
        && proof_authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
            authority.is_assumed_total_callee_assumption_for(
                index,
                vc,
                result_bindings.get(index).and_then(Option::as_ref),
            )
        })
}

fn transport_row_is_authenticated_assumed_total_assumption(
    index: usize,
    transport: &TransportObligationResult,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> bool {
    if !result_row_is_authenticated_assumed_total_assumption(
        index,
        results,
        result_bindings,
        proof_authorities,
    ) {
        return false;
    }
    let Some((_, result)) = results.get(index) else { return false };
    let Some(binding) = result_bindings.get(index).and_then(Option::as_ref) else { return false };
    transport.kind
        == format!("assumption:{}", trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_TAG)
        && transport.outcome == Outcome::Skipped
        && transport.obligation_id.as_deref() == Some(binding.public_obligation_id.as_str())
        && transport.solver == result.solver_name()
        && transport.reason.as_deref() == Some(TRUST_ASSUMED_TOTAL_REASON)
        && transport.counterexample.is_none()
        && transport.counterexample_model.is_none()
        && !transport.design_mandate
        && transport.native_trust_ir.is_none()
        && transport.proof_evidence.is_none()
}

/// Trust (completeness-gap ruling B): may this function's residual gap be
/// tolerated by the DEFAULT policy?
///
/// Only when every row is either:
///   * unresolved but protected by the exact Rust runtime check; or
///   * the explicitly classified IEEE-754 defined-behavior advisory. Reaching
///     infinity is neither a panic nor UB, so its refutation is useful numerical
///     information but cannot reject otherwise-valid Rust under the default
///     policy. `certify` still requires that advisory to be discharged.
///
/// Every other refutation, skip, or no-fallback row remains fatal.
///
/// The scan is deliberately whole-function and therefore conservative: one
/// UNPROVED row outside those two exact classes makes the whole function fatal,
/// even if the original coverage gap was on a different fallback-bearing row.
/// The failure mode to avoid is tolerating an unverified safety or
/// authored-contract claim that has neither a proof nor a runtime check — so a
/// row that HAS a proof is not asked the fallback question (2026-09-14).
/// Why `residual_gap_tolerance_denial` said no. Reported to the user, so a
/// build that fails where the ruling says it should pass explains itself instead
/// of leaving the reader to guess between four different causes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GapToleranceDenial {
    /// No obligation rows to scan, so the whole-function guarantee cannot be
    /// established. Fail-closed: an empty scan proves nothing.
    NoRows,
    /// A row carries a raw `Failed` verdict even though the aggregate summary may
    /// report it otherwise.
    RowRefuted,
    /// A row's solver verdict was a SAT counterexample that the bridge's
    /// kind-polarity asymmetry held below proof authority
    /// (`TRUST_HELD_ASSERT_REFUTATION_REASON`). No refutation is certified, but
    /// the only evidence in hand refutes the assertion, so runtime-check
    /// tolerance would let a solver-refuted claim compile clean.
    RowRefutationHeld,
    /// An UNPROVED non-advisory row's kind has no runtime check, so accepting it
    /// would ship unverified behaviour with nothing beneath it. (A `Proved` row
    /// of such a kind has its proof beneath it and does not deny.)
    RowHasNoFallback,
}

impl GapToleranceDenial {
    fn describe(self) -> &'static str {
        match self {
            Self::NoRows => {
                "there are no obligation rows to scan, so the whole-function guarantee that every \
                 obligation keeps a runtime check could not be established"
            }
            Self::RowRefuted => {
                "an obligation row carries a refuted verdict (even if the aggregate summary \
                 reports it differently)"
            }
            Self::RowRefutationHeld => {
                "an assertion obligation's solver verdict was a counterexample held below proof \
                 authority; the unproved claim keeps no runtime-check tolerance"
            }
            Self::RowHasNoFallback => {
                "at least one UNPROVED non-advisory obligation has no runtime fallback, so \
                 accepting it would ship behaviour with nothing checking it"
            }
        }
    }
}

/// Defined IEEE-754 outcomes that Trust reports for numerical hygiene but which
/// are not Rust safety or authored-contract violations. This exception is kept
/// exact rather than proof-level-wide: an L1 postcondition/refinement refutation
/// is still a real contract failure and remains fatal under the default policy.
fn is_defined_float_advisory(kind: &VcKind) -> bool {
    matches!(kind, VcKind::FloatOverflowToInfinity { .. } | VcKind::FloatDivisionByZero)
}

/// `None` when the residual gap MAY be tolerated; `Some(reason)` when it may not.
fn residual_gap_tolerance_denial(
    results: &[(VerificationCondition, VerificationResult)],
    overflow_checks: bool,
) -> Option<GapToleranceDenial> {
    // NOTE we do NOT deny on the aggregate `failure.failed`. That count folds in
    // the native run's `summary.failed`, which carries DERIVED refutations: the
    // whole-function `trust_mc_default_function` panic-freedom row is refuted
    // precisely BECAUSE a constituent obligation is unproved, so it restates the
    // gap rather than reporting an independent bug.
    //
    // MEASURED (stage2 e51769920): `(v as u16) * 2`, whose overflow obligation
    // PROVES, builds clean with no refuted obligation; `(a as u16) * (b as u16)`,
    // whose obligation is only runtime-checked, acquires one. The refutation
    // tracks the unproved constituent, which is what "derived" means here.
    //
    // A PRIMARY refutation is still denied, by the per-row scan below over
    // `results` — the authoritative post-processed view, the same one the
    // `failed` bucket of the legacy summary is built from. A genuine
    // counterexample surfaces there as `VerificationResult::Failed`, which is how
    // `a + b` and the other negatives in tests/trust-provability keep failing.
    if results.is_empty() {
        return Some(GapToleranceDenial::NoRows);
    }
    for (vc, result) in results {
        if is_defined_float_advisory(&vc.kind) {
            continue;
        }
        // Trust (hardened design mandates, 2026-09-16): an OPAQUE hardened row —
        // a `HardenedBoundary` whose violation formula is the tautology
        // `Bool(true)`, the shape `hardened_obligation_is_design_mandate` keys the
        // transport's `design_mandate` bit on — is a DESIGN REQUIREMENT the
        // profile states about the program (an explicit process-signal policy,
        // `OsString` arguments for a compatibility-sensitive tool, no error
        // discarded through `Result::ok`), not a safety obligation with a
        // runtime check and not a refutation. targo already partitions such
        // rows as `mandated` and grades them `conditional-pass`; the compiler
        // denying tolerance on them made `targo trust build` fail every ordinary
        // program under its default `unix_hardened` profile with no fix path
        // (`std::env::args` alone was fatal). Under the default policy the
        // mandate is REPORTED (the row stays Unknown, `design_mandate: true`);
        // `certify` still requires full discharge and fails it
        // (`requires_full_discharge` gates `tolerate_default_gap` separately).
        // A hardened row with a REAL formula — a `PanicBoundary` twin refuted
        // with a counterexample, a cap-wrapper discharge — is not opaque and
        // keeps every arm below.
        // Trust (G3-MANDATE-L1-ONLY-1, 2026-10-27): through the shared predicate,
        // which admits only the L1 profile-rule categories. An L0 unsafe/FFI row
        // whose `Bool(true)` is a modelling-gap fail-close (an FFI call with no
        // summary) is not a design requirement and keeps every arm below.
        if vc.kind.is_hardened_design_mandate(&vc.formula) {
            continue;
        }
        if matches!(result, VerificationResult::Failed { .. }) {
            return Some(GapToleranceDenial::RowRefuted);
        }
        if result_is_held_assert_refutation(result) {
            return Some(GapToleranceDenial::RowRefutationHeld);
        }
        // Trust (policy B as ruled, 2026-09-14): the fallback question is asked of
        // UNPROVED rows only. The ruling's second fatal class is "an unproved row
        // that has no runtime check"; a `Proved` row of a no-fallback kind — a
        // termination or postcondition obligation an engine discharged — has its
        // proof beneath it and is not a gap. Asking it of every row made a
        // function fatal the moment it carried one such proved row beside one
        // merely runtime-checked row (measured on `p5_recursion::fact`: 0 unknown,
        // 1 runtime-checked, denied `RowHasNoFallback`). Authority is not this
        // scan's job: `tolerate_default_gap` separately requires
        // `native_authority_validation_failures.is_empty()`, so a `Proved` row
        // that cannot back its claim still denies tolerance there.
        // Through the shared funnel, so the hardened-family refusal above cannot
        // be true here and false in the summary partition. Byte-identical to the
        // direct `has_runtime_fallback` call this replaced — the funnel IS that
        // call, and a hardened row answered `false` then and denies now.
        if !matches!(result, VerificationResult::Proved { .. })
            && !runtime_check_available(&vc.kind, overflow_checks)
        {
            return Some(GapToleranceDenial::RowHasNoFallback);
        }
    }
    None
}

fn full_verification_failure(
    summary: &TrustFunctionSummary,
    transport_results: &[TransportObligationResult],
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> Option<FullVerificationFailure> {
    if summary.total == 0 {
        return Some(FullVerificationFailure {
            failed: 0,
            unknown: 0,
            runtime_checked: 0,
            skipped: 1,
        });
    }

    // Trust: include EVERY disposition class (notably `cached`) via the single
    // `accounted()` helper so `unaccounted` is exactly the genuinely-unattributed
    // remainder. Defense-in-depth: this path is full-mode-only today (cache is
    // `Disabled` under fail-closed, so `cached == 0` here), but centralizing the
    // partition prevents a future mode-gate change from silently mis-bucketing
    // cached obligations as `skipped`.
    let accounted = summary.accounted();
    let unaccounted = summary.total.saturating_sub(accounted);
    let transport_skipped = transport_results
        .iter()
        .enumerate()
        .filter(|(index, result)| {
            result.outcome.is_skipped()
                && !transport_row_is_authenticated_definition_entry_assumption(
                    *index,
                    result,
                    results,
                    result_bindings,
                    proof_authorities,
                )
                && !transport_row_is_authenticated_assumed_total_assumption(
                    *index,
                    result,
                    results,
                    result_bindings,
                    proof_authorities,
                )
        })
        .count()
        .min(u32::MAX as usize) as u32;

    let failure = FullVerificationFailure {
        failed: summary.failed,
        unknown: summary.unknown,
        runtime_checked: summary.runtime_checked,
        skipped: unaccounted.saturating_add(transport_skipped),
    };

    (!failure.is_empty()).then_some(failure)
}

fn native_full_verification_failure(
    result: Option<&trust_verifier_api::VerificationRunResult>,
) -> Option<FullVerificationFailure> {
    let result = result?;
    let failure = native_run_accounting_failure(result);
    if matches!(result.status, trust_verifier_api::VerificationRunStatus::Proved)
        && native_run_summary_is_fully_proved(result)
        && failure.is_empty()
    {
        return None;
    }

    Some(failure)
}

/// S4 reject-only validation: every public native `Proved` row must resolve to
/// exactly one current compiler row carrying an exact private static-proof
/// capability. This never edits the public run or its counters. Missing,
/// ambiguous, stale, skipped/conflicting, or label-only rows make the strict
/// claim path fail validation instead.
fn native_proved_authority_validation_failures(
    sess: &Session,
    result: Option<&trust_verifier_api::VerificationRunResult>,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> Vec<String> {
    native_proved_authority_validation_failures_with_grounding_lookup(
        result,
        results,
        result_bindings,
        proof_authorities,
        |obligation_id| grounded_panic_freedom_row(sess, obligation_id),
    )
}

/// Pure carrier validation shared by production and unit fixtures. Production
/// supplies the session-owned grounding inventory above; sessionless fixtures
/// supply an empty lookup explicitly, so they cannot accidentally manufacture
/// a compiler-grounded row while still exercising every other S4 gate.
fn native_proved_authority_validation_failures_with_grounding_lookup(
    result: Option<&trust_verifier_api::VerificationRunResult>,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
    grounded_row: impl Fn(&str) -> Option<ExactResultRowIdentity>,
) -> Vec<String> {
    let Some(run) = result else { return Vec::new() };
    // Trust: keep the validator's specific defect in the refusal diagnostic.
    // A generic integrity error hides whether the native inventory, summary,
    // publication or provenance failed and prevents fixing the actual producer.
    if let Err(reason) = run.validate_derived_state() {
        return vec![format!("native run derived state is invalid: {reason}")];
    }
    if results.len() != result_bindings.len() || results.len() != proof_authorities.len() {
        return vec![format!(
            "compiler result/binding/authority carriers are not row-aligned \
             (results={}, bindings={}, authorities={})",
            results.len(),
            result_bindings.len(),
            proof_authorities.len(),
        )];
    }

    let index = build_full_verification_evidence_index(run);
    let live_run_validation = build_live_authority_run_validation_cache(proof_authorities, run);
    let binding_rows = build_exact_result_binding_row_index(results, result_bindings);
    let mut proved_evidence = FxHashMap::default();
    let mut duplicate_proved_evidence = FxHashSet::default();
    for evidence in run
        .evidence
        .iter()
        .filter(|evidence| evidence.status == trust_verifier_api::EvidenceStatus::Proved)
    {
        let id = evidence.obligation_id.as_str();
        if duplicate_proved_evidence.contains(id) {
            continue;
        }
        if proved_evidence.insert(id, evidence).is_some() {
            proved_evidence.remove(id);
            duplicate_proved_evidence.insert(id);
        }
    }
    let mut failures = Vec::new();
    let mut seen = FxHashSet::default();
    for obligation in
        run.requested_obligations.iter().filter(|obligation| !obligation.is_default_admission())
    {
        let id = obligation.obligation_id.as_str();
        let Some(evidence) = proved_evidence.get(id).copied() else {
            if duplicate_proved_evidence.contains(id) {
                failures.push(format!(
                    "{} has duplicate public Proved evidence",
                    obligation.obligation_id
                ));
            }
            continue;
        };
        if !seen.insert(id) || duplicate_proved_evidence.contains(id) {
            failures
                .push(format!("{} has duplicate public Proved evidence", obligation.obligation_id));
            continue;
        }
        if index.strict_accepted_by_obligation_id.get(obligation.obligation_id.as_str()).copied()
            != Some(evidence)
        {
            failures.push(format!(
                "{} has no unique conflict-free accepted Proved evidence",
                obligation.obligation_id
            ));
            continue;
        }

        if binding_rows.ambiguous_ids.contains(id) {
            failures.push(format!(
                "{} maps to multiple current compiler result rows",
                obligation.obligation_id
            ));
            continue;
        }
        // The compiler's OWN grounding pass retires the binding when it
        // re-points a panic-freedom aggregate's formula at the grounded
        // residual violation (that CleanCic upgrade is what most proved
        // functions depend on — withholding it measurably broke 79 fixtures).
        // Judge such an obligation on its recorded GROUNDED row: the row must
        // still be Proved under exact private authority, the same bar every
        // other row here must clear. Only the compiler can populate this
        // record, and only from a rewrite it performed itself.
        if let Some(grounded_identity) = grounded_row(id) {
            let grounded_row = grounded_identity.index;
            let authorized = results.get(grounded_row).is_some_and(|(vc, compiler_result)| {
                exact_result_row_identity(grounded_row, vc).as_ref() == Some(&grounded_identity)
                    && matches!(compiler_result, VerificationResult::Proved { .. })
                    && proof_authorities.get(grounded_row).and_then(Option::as_ref).is_some_and(
                        |authority| {
                            authority.permits_static_proved_transport_for(
                                grounded_row,
                                vc,
                                compiler_result,
                                result_bindings.get(grounded_row).and_then(Option::as_ref),
                            ) && live_authority_run_is_valid(authority, Some(&live_run_validation))
                        },
                    )
            });
            if authorized {
                continue;
            }
            failures.push(format!(
                "{} was grounded by the compiler but its exact grounded row is absent, changed, or lacks private proof authority",
                obligation.obligation_id
            ));
            continue;
        }
        let Some(row) = binding_rows.unique_rows.get(id).copied() else {
            if env_flag_enabled("TRUST_ASSERT_DEBUG") {
                eprintln!("[PF_VALIDATE] {} not in unique_rows; per-row binding state:", id);
                for (row_index, binding) in result_bindings.iter().enumerate() {
                    match binding {
                        None => eprintln!("[PF_VALIDATE]   row {row_index}: binding None"),
                        Some(binding) => eprintln!(
                            "[PF_VALIDATE]   row {row_index}: binding for {} matches_row={} vc_kind={:?}",
                            binding.public_obligation_id,
                            binding.matches_row(row_index, &results[row_index].0),
                            &results[row_index].0.kind
                        ),
                    }
                }
            }
            failures.push(format!(
                "{} has no exact current compiler result binding",
                obligation.obligation_id
            ));
            continue;
        };
        if !result_bindings[row]
            .as_ref()
            .is_some_and(|binding| binding.matches_public_obligation(obligation))
        {
            failures.push(format!(
                "{} has no exact current compiler result binding",
                obligation.obligation_id
            ));
            continue;
        }
        let (vc, compiler_result) = &results[row];
        if !matches!(compiler_result, VerificationResult::Proved { .. }) {
            failures.push(format!(
                "{} public Proved evidence disagrees with the current compiler result",
                obligation.obligation_id
            ));
            continue;
        }
        let binding = result_bindings[row].as_ref();
        // `permits_static_proved_transport_for` = the static-proof predicate
        // PLUS the whole-function panic-freedom subsumption. The subsumed
        // aggregate's compiler verdict is independently justified by its
        // premise rows (each carrying its own static authority), so a native
        // lane that ALSO proved the same obligation must not fail validation
        // for want of a per-row static token the opaque `panic_reachable`
        // formula can never earn (not kernel-certifiable, not re-solvable).
        // Without this, a natively-PROVED aggregate fared WORSE than a
        // natively-unknown one (which the subsumption carries outright) — the
        // measured wave-5 residual on assert_mut_field_identity while its
        // setter twin passed.
        if !proof_authorities[row].as_ref().is_some_and(|authority| {
            authority.permits_static_proved_transport_for(row, vc, compiler_result, binding)
                && live_authority_run_is_valid(authority, Some(&live_run_validation))
        }) {
            failures.push(format!(
                "{} lacks exact compiler-private static proof authority",
                obligation.obligation_id
            ));
        }
    }
    failures
}

fn native_run_accounting_failure(
    result: &trust_verifier_api::VerificationRunResult,
) -> FullVerificationFailure {
    let to_u32 = |value: usize| value.min(u32::MAX as usize) as u32;
    let empty_run_skip =
        u32::from(matches!(result.status, trust_verifier_api::VerificationRunStatus::Empty));
    let zero_obligation_proved_skip = u32::from(
        matches!(result.status, trust_verifier_api::VerificationRunStatus::Proved)
            && result.summary.requested_obligations == 0,
    );
    let accounted = result
        .summary
        .proved
        .saturating_add(result.summary.failed)
        .saturating_add(result.summary.unknown)
        .saturating_add(result.summary.timed_out)
        .saturating_add(result.summary.cancelled)
        .saturating_add(result.summary.unsupported)
        .saturating_add(result.summary.skipped)
        .saturating_add(result.summary.bounded_proved)
        .saturating_add(result.summary.insufficient_strength)
        .saturating_add(result.summary.missing_proof_artifacts)
        .saturating_add(result.summary.publication_conflicts);
    let unaccounted = result.summary.requested_obligations.saturating_sub(accounted);
    // `summary.requested_obligations` counts only REAL obligations — the
    // verifier-api excludes synthetic "default admission" sentinels (trivially-true
    // `false`-violation markers) from it (`requested_obligations.len() - admitted`).
    // Compare against the same non-admission count, else a function that carries an
    // admission sentinel (e.g. shift/widening-cast obligations) shows a spurious
    // off-by-`admitted` row mismatch and its genuine native proofs are dropped as
    // skipped under strict batteries-on verification. Mirrors the
    // `!is_default_admission()`
    // filtering already applied elsewhere in this file.
    let requested_row_mismatch = result
        .summary
        .requested_obligations
        .abs_diff(native_run_non_admission_requested_count(result));
    let evidence_row_mismatch =
        result.summary.evidence_count.abs_diff(native_run_non_admission_evidence_count(result));
    let malformed_proved_run = u32::from(
        matches!(result.status, trust_verifier_api::VerificationRunStatus::Proved)
            && result.summary.requested_obligations > 0
            && requested_row_mismatch == 0
            && evidence_row_mismatch == 0
            && !native_run_proved_coverage_is_exact(result),
    );

    FullVerificationFailure {
        failed: to_u32(result.summary.failed),
        unknown: to_u32(
            result
                .summary
                .unknown
                .saturating_add(result.summary.timed_out)
                .saturating_add(result.summary.cancelled),
        ),
        runtime_checked: 0,
        skipped: empty_run_skip
            .saturating_add(zero_obligation_proved_skip)
            .saturating_add(to_u32(result.summary.unsupported))
            .saturating_add(to_u32(result.summary.skipped))
            .saturating_add(to_u32(result.summary.bounded_proved))
            .saturating_add(to_u32(result.summary.insufficient_strength))
            .saturating_add(to_u32(result.summary.missing_proof_artifacts))
            .saturating_add(to_u32(result.summary.publication_conflicts))
            .saturating_add(to_u32(unaccounted))
            .saturating_add(to_u32(requested_row_mismatch))
            .saturating_add(to_u32(evidence_row_mismatch))
            .saturating_add(malformed_proved_run),
    }
}

/// The count of REAL requested obligations — excluding synthetic "default
/// admission" sentinels, matching how `summary.requested_obligations` is computed
/// in the verifier-api (`requested_obligations.len() - admitted`).
fn native_run_non_admission_requested_count(
    result: &trust_verifier_api::VerificationRunResult,
) -> usize {
    result.requested_obligations.iter().filter(|o| !o.is_default_admission()).count()
}

fn native_run_admission_obligation_ids(
    result: &trust_verifier_api::VerificationRunResult,
) -> FxHashSet<&str> {
    result
        .requested_obligations
        .iter()
        .filter(|obligation| obligation.is_default_admission())
        .map(|obligation| obligation.obligation_id.as_str())
        .collect()
}

fn native_run_non_admission_evidence_count(
    result: &trust_verifier_api::VerificationRunResult,
) -> usize {
    let admission_ids = native_run_admission_obligation_ids(result);
    result
        .evidence
        .iter()
        .filter(|evidence| !admission_ids.contains(evidence.obligation_id.as_str()))
        .count()
}

/// Trust (#47): the diagnostic prefix emitted by
/// [`native_trust_ir_bundle_build_failure_result`] when typed-TrustIr lowering of
/// a function FAILS — e.g. an unmodeled external call (`Option::unwrap`,
/// `u32::pow`) that `resolve_call_target` refuses, or any other MIR construct the
/// bridge cannot lower. A run carrying this marker had its native verification
/// ABORTED before any obligation could be discharged, so it must NEVER be treated
/// as vacuously clean: doing so passes a function that can actually panic under
/// strict batteries-on verification as a FALSE PROOF. Shared by the producer and the vacuity
/// gate so the two strings cannot drift (a drift would silently re-open the gap).
const NATIVE_TRUST_IR_LOWERING_FAILED_MARKER: &str =
    "compiler full verification requires typed TrustIr native evidence";

/// Whether a native run is a typed-TrustIr lowering-failure result (carries
/// [`NATIVE_TRUST_IR_LOWERING_FAILED_MARKER`]). Such a run never verified the
/// function — every obligation was marked `Unsupported` — so it must fail closed
/// under strict batteries-on verification rather than be mistaken for "nothing to prove".
fn native_run_trust_ir_lowering_failed(run: &trust_verifier_api::VerificationRunResult) -> bool {
    run.diagnostics.iter().any(|d| d.contains(NATIVE_TRUST_IR_LOWERING_FAILED_MARKER))
}

/// Trust (determinism plan §3.7, 2026-10-01): how `build_full_verification_input`
/// begins its decline when the per-function deadline expired before or during
/// native bundle construction. Shared with the consumers that publish such a
/// run's rows, and its gap row, as clock stops rather than as unexplained
/// unsupported ones ([`record_deadline_declined_bundle_clock_stops`],
/// [`transport_native_lowering_gap_row`]).
const NATIVE_BUNDLE_DEADLINE_DECLINE: &str =
    "per-function wall-clock budget (-Ztrust-verify-function-budget-ms) expired";

/// Whether this run's native lowering did not complete because the
/// per-function deadline declined it ([`NATIVE_BUNDLE_DEADLINE_DECLINE`]).
fn native_run_lowering_declined_by_deadline(
    run: &trust_verifier_api::VerificationRunResult,
) -> bool {
    run.diagnostics.iter().any(|d| {
        d.contains(NATIVE_TRUST_IR_LOWERING_FAILED_MARKER)
            && d.contains(NATIVE_BUNDLE_DEADLINE_DECLINE)
    })
}

/// Whether a native run found NOTHING outstanding: no real requested obligation
/// and no skipped / unsupported / unknown / timed-out / cancelled / insufficient
/// / missing-artifact / publication-conflict item. Used to accept a function with
/// zero proof-results obligations as vacuously fully-verified ONLY when the native
/// verifier agrees there was genuinely nothing to prove (vs verification skipped).
fn native_run_is_vacuously_clean(run: &trust_verifier_api::VerificationRunResult) -> bool {
    let s = &run.summary;
    s.requested_obligations == 0
        && s.failed == 0
        && s.unknown == 0
        && s.timed_out == 0
        && s.unsupported == 0
        && s.skipped == 0
        && s.cancelled == 0
        && s.insufficient_strength == 0
        && s.missing_proof_artifacts == 0
        && s.publication_conflicts == 0
        && run.skipped.is_empty()
        // Trust (#47): a run whose typed-TrustIr lowering FAILED is NOT vacuously
        // clean. The failure means an unmodeled construct was present — most
        // commonly an external call (`Option::unwrap`, `u32::pow`) whose
        // panic-freedom the native verifier could not establish. Without this
        // guard, a pure function whose only panic risk is such a call has an empty
        // public bundle (`summary.total == 0`) and the build-failure result reads
        // as `requested == 0` (its sole obligation is the excluded admission), so
        // the abort gate early-returns PASS — a definitive false proof
        // (`{ let o: Option<u32> = None; o.unwrap() }` ALWAYS panics yet
        // "verifies"). Fail closed instead; soundness over permissiveness.
        && !native_run_trust_ir_lowering_failed(run)
}

/// Verification here is over an item's pre-monomorphization body. A shim or
/// promoted MIR source is not that item and must not borrow its row findings or
/// definition-side identity. Generic items still have a real owner; item_identity
/// separately refuses to export their proof as a concrete instance identity.
fn zero_obligation_source_owner(source: rustc_middle::mir::MirSource<'_>) -> Option<DefId> {
    if source.promoted.is_some() {
        return None;
    }
    match source.instance {
        ty::InstanceKind::Item(owner) => Some(owner),
        _ => None,
    }
}

/// The transport lookup and its regression seam share the exact typed key.
/// An unsupported source owner is not evidence of an empty call inventory.
fn zero_obligation_calls_undischarged_for_owner(
    owner: Option<DefId>,
    undischarged: &FxHashSet<DefId>,
    only_hypotheses: &FxHashSet<DefId>,
    hypotheses_published_exactly: bool,
) -> bool {
    let Some(owner) = owner else { return true };
    undischarged.contains(&owner)
        && !(hypotheses_published_exactly && only_hypotheses.contains(&owner))
}

/// Trust (2026-10-10, ZERO-ROW-GATE): THE one test of whether a body with ZERO
/// bridged obligations is vacuously clean. It decides what the transport
/// PUBLISHES for such a body (the proved `no_obligations` row when true, the
/// `unknown` `native-verification-gap` row or the body's own rows otherwise) AND
/// whether the strict/certify/memory-safe gates ACCEPT the body on its empty
/// inventory. Both read the value `publish_body_verification_outcome` computes
/// once from this function, so the exit status can never again disagree with the
/// row it publishes.
///
/// It used to be two predicates. The publisher required `!calls_undischarged`
/// (every call in the body is discharged by an authenticated registry —
/// `zero_obligation_undischarged_call_funcs`) and the gate did not: `pub fn
/// f(x: u32, n: u32) -> u32 { x.rotate_left(n) }` published one `unknown` gap
/// row and exited 0 under `-Ztrust-policy=certify` (docs/KNOWN_HAZARDS.md
/// "EMPTY bridged inventory"; docs/DECISION_QUEUE.md ZERO-ROW-GATE).
///
/// The conjuncts, all fail-closed:
///  * the native run is vacuously clean (`native_run_is_vacuously_clean`); an
///    ABSENT run is not;
///  * no closure-driving consumer call reaches foreign code uncharged
///    (`uncharged_consumer_edges_empty`);
///  * no call in the body is undischarged by the authenticated registries,
///    except calls that are ONLY this body's admitted instance-hypothesis sites
///    AND whose hypothesis rows are published in their exact compiler shape
///    (`hypotheses_published_exactly`).
fn zero_obligation_native_vacuously_clean(
    sess: &Session,
    owner: Option<DefId>,
    artifacts: &VerificationArtifacts,
    uncharged_consumer_edges_empty: bool,
    // Trust (2026-10-25, GLR-1): the indirect-call gate refuses nothing in this body
    // (`unresolved_indirect_call_gap_row` is `None`). A belt over
    // `calls_undischarged`, which today names such a call too (the registry
    // discharges no fn-pointer value): a zero-obligation body the gate refuses must
    // never publish the proved `no_obligations` row on the advisory lane, where the
    // gate does not run.
    no_unresolved_indirect_call: bool,
    hypotheses_published_exactly: bool,
) -> bool {
    let calls_undischarged = with_crate_verification_state(sess, |state| {
        zero_obligation_calls_undischarged_for_owner(
            owner,
            &state.zero_obligation_undischarged_call_funcs,
            &state.zero_obligation_calls_only_hypotheses,
            hypotheses_published_exactly,
        )
    });
    !calls_undischarged
        && uncharged_consumer_edges_empty
        && no_unresolved_indirect_call
        && artifacts.full_verification.as_ref().is_some_and(native_run_is_vacuously_clean)
}

/// Trust (2026-10-10, ZERO-ROW-GATE): the strict/certify gate's own half of the
/// empty-inventory accept: the publisher called the body vacuously clean
/// (`zero_obligation_native_vacuously_clean`) AND no row it publishes is
/// `unknown` or timed out. The second conjunct is a belt over the first — today
/// the publisher mints the `unknown` gap row exactly when the first is false —
/// so a future row that says `unknown` on a zero-obligation body cannot ride the
/// empty-inventory accept either. `None` (a body with bridged obligations) is
/// never accepted here.
fn zero_obligation_inventory_accepted(
    zero_obligation_vacuously_clean: Option<bool>,
    published_rows: PublishedRowTally,
) -> bool {
    zero_obligation_vacuously_clean == Some(true)
        && published_rows.unknown == 0
        && published_rows.timed_out == 0
}

fn native_run_summary_is_fully_proved(result: &trust_verifier_api::VerificationRunResult) -> bool {
    let summary = &result.summary;
    summary.requested_obligations > 0
        && summary.requested_obligations == native_run_non_admission_requested_count(result)
        && summary.evidence_count == native_run_non_admission_evidence_count(result)
        && summary.proved == summary.requested_obligations
        && summary.bounded_proved == 0
        && summary.failed == 0
        && summary.unknown == 0
        && summary.timed_out == 0
        && summary.cancelled == 0
        && summary.unsupported == 0
        && summary.skipped == 0
        && summary.insufficient_strength == 0
        && summary.missing_proof_artifacts == 0
        && summary.publication_conflicts == 0
        && native_run_proved_coverage_is_exact(result)
}

fn native_run_proved_coverage_is_exact(result: &trust_verifier_api::VerificationRunResult) -> bool {
    let admission_ids = native_run_admission_obligation_ids(result);
    let admission_count = result
        .requested_obligations
        .iter()
        .filter(|obligation| obligation.is_default_admission())
        .count();
    let requested_obligations = result
        .requested_obligations
        .iter()
        .filter(|obligation| !obligation.is_default_admission())
        .collect::<Vec<_>>();
    let evidence = result
        .evidence
        .iter()
        .filter(|evidence| !admission_ids.contains(evidence.obligation_id.as_str()))
        .collect::<Vec<_>>();
    if admission_count > 1
        || result.summary.admitted != admission_count
        || requested_obligations.is_empty()
        || evidence.len() != requested_obligations.len()
        || result
            .skipped
            .iter()
            .any(|skipped| !admission_ids.contains(skipped.obligation_id.as_str()))
    {
        return false;
    }

    let mut requested_ids = FxHashSet::default();
    let mut requested_by_id = FxHashMap::default();
    for obligation in requested_obligations {
        if !requested_ids.insert(obligation.obligation_id.as_str()) {
            return false;
        }
        requested_by_id.insert(obligation.obligation_id.as_str(), obligation);
    }

    let mut evidence_ids = FxHashSet::default();
    for evidence in evidence {
        if !evidence_ids.insert(evidence.obligation_id.as_str()) {
            return false;
        }
        let Some(obligation) = requested_by_id.get(evidence.obligation_id.as_str()) else {
            return false;
        };
        if !evidence.satisfies_required_strength(obligation.required_strength.as_ref()) {
            return false;
        }
    }

    requested_ids.len() == evidence_ids.len()
        && native_run_all_requested_obligations_have_strict_full_evidence(result)
}

fn native_run_all_requested_obligations_have_strict_full_evidence(
    result: &trust_verifier_api::VerificationRunResult,
) -> bool {
    let requested_obligations = result
        .requested_obligations
        .iter()
        .filter(|obligation| !obligation.is_default_admission())
        .collect::<Vec<_>>();
    if requested_obligations.is_empty() {
        return false;
    }
    let strict_ids = strict_full_verification_accepted_obligation_ids(result);
    strict_ids.len() == requested_obligations.len()
        && requested_obligations
            .iter()
            .all(|obligation| strict_ids.contains(obligation.obligation_id.as_str()))
}

fn strict_full_verification_accepted_obligation_ids(
    result: &trust_verifier_api::VerificationRunResult,
) -> FxHashSet<String> {
    let index = build_full_verification_evidence_index(result);
    strict_accepted_obligation_ids_from_index(result, &index)
}

fn combine_full_verification_failures(
    legacy_failure: Option<FullVerificationFailure>,
    native_failure: Option<FullVerificationFailure>,
) -> Option<FullVerificationFailure> {
    match (legacy_failure, native_failure) {
        (None, None) => None,
        (Some(failure), None) | (None, Some(failure)) => Some(failure),
        (Some(legacy), Some(native)) => Some(FullVerificationFailure {
            failed: legacy.failed.saturating_add(native.failed),
            unknown: legacy.unknown.saturating_add(native.unknown),
            runtime_checked: legacy.runtime_checked.saturating_add(native.runtime_checked),
            skipped: legacy.skipped.saturating_add(native.skipped),
        }),
    }
}

fn strict_l0_verification_failure(
    overflow_checks: bool,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    // Callee names whose FATAL absent-callee rows are adversarially refutable
    // (open uncontracted generic trait dispatch) — see
    // `adversarially_refutable_open_dispatch_callees` — and, since OD-1 phase 0,
    // whether one of them is co-folded into the panic-freedom aggregate
    // (`OpenDispatchRefutationWitnesses`). Default = no effect.
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
) -> Option<FullVerificationFailure> {
    let mut failure =
        FullVerificationFailure { failed: 0, unknown: 0, runtime_checked: 0, skipped: 0 };

    for (index, (vc, result)) in results.iter().enumerate() {
        // A definition-site `requires` marker is a catalog-only modular
        // assumption, not an L0 safety obligation. Its reconstructed legacy VC
        // is intentionally `UnsupportedMir` (normally classified L0), so the
        // private capability must be checked before kind classification. Public
        // kind/solver strings alone receive no exemption.
        if result_row_is_authenticated_definition_entry_assumption(
            index,
            results,
            result_bindings,
            proof_authorities,
        ) {
            continue;
        }
        if result_row_is_authenticated_assumed_total_assumption(
            index,
            results,
            result_bindings,
            proof_authorities,
        ) {
            continue;
        }
        if !is_strict_l0_vc_kind(&vc.kind) {
            continue;
        }
        // Trust: a kernel-CERTIFIED obligation (clean's zero-trust CIC re-check,
        // recorded in `build_proof_results`) is a real static proof — it
        // discharges the L0 obligation exactly as a full-verifier-backed proof
        // does, regardless of the in-process solver's own (possibly
        // over-approximating, e.g. interval) reasoning strength. Crediting it
        // here keeps the L0 gap accounting consistent with `proof_results`, which
        // already counts it `certified`. Soundness is unaffected: a satisfiable
        // (buggy) obligation is never certified, so a real violation still falls
        // through to `runtime_checked`/`failed`.
        // `permits_static_proved_transport_for` = the static-proof predicate PLUS
        // the whole-function panic-freedom subsumption, which is deliberately
        // NOT a premise-grade static proof (a derived conjunction must never
        // feed the registries that expect independent proofs) but IS a real,
        // reportable discharge of THIS obligation: its premises are exactly the
        // other L0 rows this same loop credits, each under its own private
        // authority. Using the narrower predicate here left a subsumed
        // aggregate counted `runtime_checked`, so a function whose every
        // obligation was proved still failed the L0 gate — the measured
        // residual on modulo_unreachable ("2 proved ... 0 runtime-checked" in
        // the main summary vs "1 runtime-checked" in the L0 summary).
        if matches!(result, VerificationResult::Proved { .. })
            && proof_authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
                authority.permits_static_proved_transport_for(
                    index,
                    vc,
                    result,
                    result_bindings.get(index).and_then(Option::as_ref),
                )
            })
        {
            continue;
        }

        // Trust (2026-10-02, diag-vs-report): the three Level-0 REFUTATION
        // reclassifications below are decided by ONE predicate,
        // `l0_refutation_class` (over `trust_types::l0_refutation`), which
        // `publish_body_verification_outcome` also asks when it stamps the
        // published transport row. Before, only this summary applied them: the
        // line said "1 failed" while the row — what targo's gate and
        // report.json count — said `runtime_checked`/`unknown` for the same
        // obligation. The per-arm rationale:
        //
        // Trust (#47/#48 restoration): an `UnsupportedMir` obligation emitted for a
        // KNOWN-PANICKING unmodeled call (`Option`/`Result` `unwrap`/`expect`/
        // `unwrap_err`/`expect_err`) is NOT a benign coverage gap like an UNKNOWN the
        // solver returns for unmodeled std (`println!`). Its VC kind is
        // `Custom{namespace: trust.vc, name: unsupported_mir}`, which the full-verifier
        // router has no primary owner for, so it returns UNKNOWN. The call's
        // panic-freedom was never established by ANY engine, and the marker says
        // it is a known reachable panic path rather than a generic capability
        // gap. Reclassify it to `failed` so diagnostics and reports preserve that
        // distinction. Explicit full rejects either bucket; advisory consumers
        // still benefit from the more precise verdict. SOUNDNESS BOUNDARY: this
        // is exactly the kind emitted for a known-panicking unmodeled call — NOT
        // a generic unmodeled construct nor a genuine solver timeout. DEFAULT mode is
        // unaffected: `report_strict_l0_verification_failure` only aborts when
        // `strict == true`, and `escalate_refuted_l0_safety_counterexamples` deliberately
        // excludes `UnsupportedMir`, so a default-lane build of `o.unwrap()` still
        // compiles (exit 0) — drop-in Rust preserved; the L0-gap diagnostic note and
        // (since 2026-10-02) the published transport row label it `failed` (more
        // honest) instead of `unknown`.
        //
        // Trust: fail-closed on absent-callee panic (revert of d8a9bbc28e fail-open;
        // unproven panic MUST fail closed). An `UnsupportedMir` obligation for a
        // STRICT-L0 SAFETY property (arithmetic overflow / bounds / memory) that the
        // native typed lane could not model (`x.pow(20)`'s repeated-mul → trust-mc
        // Unsupported) is a genuine undischarged safety obligation. Before the
        // fail-soft bundle change it failed the whole native bundle and the #48
        // lowering-failure guard aborted; the fail-soft change left it a non-fatal
        // Unknown, re-opening the false proof (`{ let x=(a as u32)+1; x.pow(20) }`
        // verified with exit 0 while overflowing). Reclassify to `failed` so the
        // strict-L0 abort fires. SOUND: only a NON-`Proved` result reaches here (a
        // real proof / kernel-cert was skipped above), so this never over-rejects a
        // discharged safety obligation; see `is_native_unsupported_strict_l0_safety_mir`.
        //
        // Trust (adversarial-instantiation refutation): the FATAL absent-callee
        // row for an OPEN, uncontracted, unresolved generic trait dispatch. The
        // universal panic-freedom claim it stands for is constructively FALSE
        // (a downstream impl may panic — the witness the R3 fixtures name), so
        // a non-`Proved` row is a refutation, not a coverage gap. Reclassify to
        // `failed`. SOUND: the witness argument needs the trait OPEN and the
        // resolution `Ok(None)` — both checked at collection
        // (`adversarially_refutable_open_dispatch_callees`), which errs closed
        // on every other shape; and only a NON-`Proved` result reaches here, so
        // a rung-1/rung-2 discharge is never overridden.
        if l0_refutation_class(vc, result, adversarial_open_dispatch).is_some() {
            failure.failed += 1;
            continue;
        }

        match result {
            VerificationResult::Proved { .. } => {
                if runtime_check_available(&vc.kind, overflow_checks) {
                    failure.runtime_checked += 1;
                } else {
                    failure.unknown += 1;
                }
            }
            VerificationResult::Failed { .. } => failure.failed += 1,
            VerificationResult::Unknown { .. } | VerificationResult::Timeout { .. } => {
                // A held assertion refutation keeps NO runtime-check credit:
                // the only evidence in hand is a SAT counterexample the bridge
                // refused to certify, so the row stays a fatal coverage gap
                // rather than a tolerated "vanilla semantics" one.
                if result_is_held_assert_refutation(result) {
                    failure.unknown += 1;
                } else if runtime_check_available(&vc.kind, overflow_checks) {
                    failure.runtime_checked += 1;
                } else {
                    failure.unknown += 1;
                }
            }
            _ => failure.unknown += 1,
        }
    }

    if let Some(run) = full_verification {
        // Exact public IDs, not source locations, identify native obligations.
        // Two checks at one span must remain independently accountable.
        //
        // Trust (DESIGN_PHILOSOPHY §9 — defined behavior is not unsafe): this set
        // spans EVERY row that reached `results`, not only the L0 ones, because a
        // row present in `results` carries its real `VcKind` and that kind is the
        // authority on proof level. `obligation.kind` here is the COARSE
        // verifier-API family (`vc_obligation_kind` in trust-mir-extract), which is
        // deliberately lossy: it folds `FloatOverflowToInfinity` in with genuine
        // arithmetic panics under `ArithmeticSafety`, because both route to the same
        // engine. Level is not routing. Filtering this set to L0 left every non-L0
        // row UNCOVERED, so the loop below re-admitted it at the coarse family and
        // fail-closed the build on it.
        //
        // Measured before this fix: `pub fn f(x: f64) -> f64 { x * 2.0 }` — valid
        // Rust whose only unproved row is `float_overflow_to_infinity`, which
        // `proof_level()` rules `L1Functional` precisely because overflow to ±inf is
        // DEFINED (never a trap, never UB) — was rejected with "Trust Level 0 safety
        // verification incomplete". The VC-keyed pass above correctly ignored that
        // row via `is_strict_l0_vc_kind`; this pass then counted it anyway. §9's rule
        // is that a defined construct fails CLOSED as an honest UNKNOWN and never by
        // restricting valid Rust, and the advisory lane already reported it exactly
        // that way — the two gates disagreed about the same row.
        //
        // This can never weaken the gate. A row whose `VcKind` IS L0 is counted by
        // the VC-keyed pass above, so skipping it here removes a double count, not a
        // check; and an obligation with NO `results` row is not in this set at all,
        // so the native-only obligations this loop exists to catch are untouched.
        let accounted_in_results: FxHashSet<&str> = results
            .iter()
            .enumerate()
            .filter_map(|(index, _)| {
                result_bindings
                    .get(index)
                    .and_then(Option::as_ref)
                    .filter(|binding| binding.matches_row(index, &results[index].0))
                    .map(|binding| binding.public_obligation_id.as_str())
            })
            .collect();
        // Trust: index the run's evidence/skipped once (O(n+m)). The prior
        // per-obligation `.find`/`.any` scans were O(n*m) and hung
        // self-verification of large generated functions for hours.
        let full_index = build_full_verification_evidence_index(run);
        let strict_accepted_ids = strict_accepted_obligation_ids_from_index(run, &full_index);
        for obligation in &run.requested_obligations {
            if !is_strict_l0_api_obligation_kind(&obligation.kind) {
                continue;
            }
            // The synthetic admission is not a real obligation.
            if obligation.is_default_admission() {
                continue;
            }
            // Already accounted for (and possibly bridged) in `results`, where the
            // row's real `VcKind` — not this coarse API family — decides its level.
            if accounted_in_results.contains(obligation.obligation_id.as_str()) {
                continue;
            }

            match full_verification_legacy_result_for_obligation(
                obligation,
                &full_index.evidence_by_obligation_id,
                &full_index.skipped_by_id,
                &strict_accepted_ids,
                false,
                false,
            ) {
                VerificationResult::Proved { .. } => {}
                VerificationResult::Failed { .. } => failure.failed += 1,
                VerificationResult::Timeout { .. } | VerificationResult::Unknown { .. } => {
                    if full_index.skipped_by_id.contains_key(obligation.obligation_id.as_str()) {
                        failure.skipped += 1;
                    } else {
                        failure.unknown += 1;
                    }
                }
                _ => failure.unknown += 1,
            }
        }
    }

    (!failure.is_empty()).then_some(failure)
}

fn is_strict_l0_vc_kind(kind: &VcKind) -> bool {
    convert_proof_level(kind) == TrustProofLevel::L0Safety
}

// Trust (#47/#48): the marker substring `trust-vcgen` stamps into the
// `VcKind::UnsupportedMir` kind string it emits for a NORMALLY-RETURNING call to a
// known panicking std method (`Option`/`Result` `unwrap`/`expect`/`unwrap_err`/
// `expect_err`) whose internal panic path is unmodeled — see
// `trust_vcgen::generate::collect_terminator_unsupported`, which emits
// `kind = "Call::<m>::panic-freedom-unverified"`. The full-verifier round-trips
// this through a `Custom{namespace: trust.vc, name: unsupported_mir}` obligation,
// reconstructing the legacy VC as
// `UnsupportedMir { kind: "FullVerification::trust.vc::unsupported_mir", detail }`
// where the original `kind` string is preserved INSIDE `detail` (it is built from
// the obligation `description`, `unsupported MIR \`{kind}\`: {detail}`). Match on
// EITHER field so the discriminator is robust to both the direct (default-lane)
// and round-tripped (full-lane) representations.
// Trust (2026-10-02): owned by `trust_types::l0_refutation`, the single source of truth.
use trust_types::l0_refutation::KNOWN_PANICKING_CALL_UNSUPPORTED_MARKER;

/// Whether a VC is the `UnsupportedMir` obligation Trust emits for a known
/// panicking unmodeled call (`o.unwrap()` and the `Option`/`Result` family). Under
/// strict batteries-on verification such an obligation is a REFUTATION, not a tolerable
/// coverage gap: no engine established the call's panic-freedom, so it must fail
/// closed (it can panic at runtime). Narrowly scoped to the
/// `panic-freedom-unverified` marker so a generic unmodeled construct or a genuine
/// solver timeout is unaffected.
fn is_known_panicking_call_unsupported_mir(kind: &VcKind) -> bool {
    trust_types::l0_refutation::is_known_panicking_call_unsupported_mir(kind)
}

// The FATAL absent-callee arm's obligation text prefix, up to the callee name.
// Kept in lockstep with trust-ir-bridge's absent-callee row mint.
// Owned by `trust_types::l0_refutation` since 2026-10-02.
use trust_types::l0_refutation::ABSENT_CALLEE_ASSUMPTION_CALLEE_PREFIX;

/// Trust (falsification gate, `absent_callee_call_only_generic` /
/// `trait_default_body_generic_caller`): the ADVERSARIAL-INSTANTIATION witness
/// set for OPEN generic trait dispatch.
///
/// A call to `<T as D>::m` that `Instance::try_resolve` cannot pin
/// (`Ok(None)`, instantiation-dependent) on an OPEN trait (a downstream crate
/// can add impls this compilation never sees), with NO
/// `#[trust::panic_free]` contract on the trait method, has a panic-freedom
/// obligation quantified over ALL instantiations — and that universal claim is
/// PROVABLY FALSE by construction: `impl D for W { fn m(&self) -> u32 {
/// panic!() } }` composed with the caller is a concrete panicking execution
/// (the trait_default fixture's own comment names exactly this witness; a
/// DEFAULT body changes nothing, since an impl may override it — the T5b
/// hazard). Recording these calls lets the strict summary report the row as
/// `failed` (a refutation of the universal claim) instead of `unknown` (a
/// capability gap).
///
/// SOUNDNESS BOUNDARY — every arm errs closed toward NOT refuting:
/// * `Ok(Some(_))` resolutions are excluded: a pinned body's panic-freedom is a
///   question about that body, not about all instantiations. The one exception
///   (OD-1 open shapes, 2026-10-04) is a VIRTUAL call, which pins no body: it is a
///   witness when `virtual_dispatch_is_adversarial` holds.
/// * `dyn_trait_sealedness == Sealed` is excluded: a closed impl set means the
///   adversarial impl cannot exist; the row stays an honest unknown (rung 2
///   proves it instead when every enumerated target is verified).
/// * A `#[trust::panic_free]` trait contract is excluded (rung 1): the
///   obligation was moved to the implementors, not left universal.
/// * A FOREIGN trait is NOT excluded, even where its enumeration closure (D4
///   increment B, `foreign_trait_closure`) serves the call. The closure
///   discharges a call it proves by filing its key on the compiler-total channel,
///   so the call leaves NO unproved row for this label to reach; every row that
///   is still here is one the closure did NOT discharge — and it declines exactly
///   when some enumerated impl could not be shown panic-free, which can be a real
///   panicking impl in the loaded graph (`xcrate_foreign_trait_closure_phi.rs`
///   `dep_bad` / `third_bad`). An exemption keyed on the closure's STRUCTURE
///   (artifact, `Sized` `Self`, trait class) instead of its OUTCOME relabelled
///   those rows "runtime-checked" although a refutation witness existed
///   (the D4-B adversarial review, 2026-09-25); withdrawn.
/// * The match key is the FATAL absent-callee row text; `#[trust::skip]` /
///   expected-absent / compiler-total calls never carry it.
///
/// Answers (every witness, the subset that are VIRTUAL calls). The second set is
/// description only (2026-10-05, rg concrete-misclassified): it lets a stamped row
/// say whether its deciding site is a generic or a `dyn` dispatch; membership in
/// the first set is the only thing that decides a row.
fn adversarially_refutable_open_dispatch_callees<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> (FxHashSet<String>, FxHashSet<String>) {
    let typing_env = body.typing_env(tcx);
    let mut out = FxHashSet::default();
    let mut virtual_out = FxHashSet::default();
    for block in body.basic_blocks.iter() {
        let (TerminatorKind::Call { func, args, .. } | TerminatorKind::TailCall { func, args, .. }) =
            &block.terminator().kind
        else {
            continue;
        };
        let Some((callee_def_id, gen_args)) = func.const_fn_def() else {
            continue;
        };
        let Some(trait_def_id) = tcx.trait_of_assoc(callee_def_id) else {
            continue;
        };
        let is_virtual = match ty::Instance::try_resolve(tcx, typing_env, callee_def_id, gen_args) {
            Ok(None) => false,
            // Trust (OD-1, 2026-10-04, open shapes): a VIRTUAL call through a trait
            // object an adversary can construct (`virtual_dispatch_is_adversarial`)
            // and HAND TO THIS BODY (the receiver is read out of one of the body's own
            // arguments, `dyn_receiver_root::argument_root`, and a caller this
            // compilation does not see may choose that argument,
            // `virtual_receiver_is_callers_choice`). The claim "panic-free for every value of
            // that argument" is constructively false exactly as the generic one is: a
            // downstream `impl Tr for W { fn m(&self) { panic!() } }` unsized into
            // `&dyn Tr` and passed in panics. No instance inventory exists for a
            // vtable, so OD-1 admits no hypothesis here; the row is a refutation, not
            // a runtime check. A trait object this body builds itself (`let d: &dyn
            // Tr = &B`) is not adversarial and keeps its label (rung 2 decides it).
            //
            // Trust (2026-10-05, DYN-ARG-PROVENANCE-1): "the caller chooses" needs a
            // caller this compilation does not see. A private function whose every
            // call site in this crate hands that argument a pointer to a value the
            // call site builds (a closure, a fn item, a concrete ADT) that carries no
            // trait object, fn pointer or type parameter anywhere inside has no such
            // caller; its row keeps the disclosed label, as `local_dyn`'s does
            // (`dyn_argument_provenance`).
            Ok(Some(ty::Instance { def: ty::InstanceKind::Virtual(..), .. }))
                if virtual_dispatch_is_adversarial(tcx, trait_def_id, gen_args)
                    && args.first().is_some_and(|receiver| {
                        virtual_receiver_is_callers_choice(tcx, body, &receiver.node)
                    }) =>
            {
                true
            }
            _ => continue,
        };
        // The LOCAL-trait certificate only: this is a LABEL computed at report
        // time, and the whole predicate's foreign arm (D4 increment B) would
        // enumerate and force dependency verdicts to answer it.
        if trait_panic_free::local_trait_relies_on_panic_free_contract(tcx, callee_def_id) {
            continue;
        }
        // Trust (D4 increment B fix, 2026-09-25): no FOREIGN-trait exemption
        // here. A call the foreign-trait closure DISCHARGED carries no unproved
        // row, so this label cannot reach it; a row that remains is one the
        // closure declined, possibly on a real panicking impl. See the doc
        // comment above.
        if dyn_trait_sealedness(tcx, trait_def_id) != trust_vcgen::TraitSealedness::Open {
            continue;
        }
        let name = trust_mir_extract::func_operand_name_in_body(tcx, body, func);
        if is_virtual {
            virtual_out.insert(name.clone());
        }
        out.insert(name);
    }
    (out, virtual_out)
}

/// Trust (OD-1, 2026-10-04, open shapes): the still-generic calls of `body` to a
/// local body whose own rows were refuted on an open dispatch that stays adversarial
/// at this call's arguments (`propagated_open_dispatch_refutation`), as (the call's
/// absent-callee name, the refuted site's callee name). These join the witness set
/// beside [`adversarially_refutable_open_dispatch_callees`].
fn propagated_open_dispatch_refutations<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> FxHashMap<String, String> {
    let mut out = FxHashMap::default();
    if body.source.promoted.is_some() {
        return out;
    }
    for block in body.basic_blocks.iter() {
        let (TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. }) =
            &block.terminator().kind
        else {
            continue;
        };
        if let Some(inner) = propagated_open_dispatch_refutation(tcx, body, func) {
            out.insert(trust_mir_extract::func_operand_name_in_body(tcx, body, func), inner);
        }
    }
    out
}

/// Trust (OD-1, 2026-10-04, open shapes): is a call `func` of `body` to a LOCAL
/// body at arguments that still mention `body`'s parameters a witness of an open
/// dispatch refutation INSIDE the callee? Answers the callee's refuted site when it
/// is: the callee's published rows were stamped class (c) for an open dispatch
/// (`open_dispatch_refuted_callees`), and that site, its arguments substituted with
/// this call's, is still an open, uncontracted dispatch in `body`'s typing
/// environment (unresolved on an open trait, or an adversarial virtual call). The
/// adversary who instantiates the callee's parameter with a panicking impl
/// instantiates `body`'s, so `body`'s row for the call ("absent callee … may panic",
/// formerly `runtime_checked`) is the same unproved-fail-closed refutation.
///
/// Errs toward NOT refuting: a call at concrete arguments (bundled and verified as
/// that instance), a trait-item call (the generic arm above decides it), a callee
/// whose verdict is not available here (its MIR is being computed up this stack),
/// a site that resolves or seals at these arguments, and a site the callee's MIR no
/// longer shows all decline. A call the bridge lowered under propagated hypotheses
/// carries no fatal row, so this label cannot reach it.
fn propagated_open_dispatch_refutation<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func: &rustc_middle::mir::Operand<'tcx>,
) -> Option<String> {
    let (callee_def, gen_args) = func.const_fn_def()?;
    generic_call_carries_open_dispatch_refutation(
        tcx,
        body.typing_env(tcx),
        body.source.def_id(),
        callee_def,
        gen_args,
        0,
    )
}

/// The depth-capped core of [`propagated_open_dispatch_refutation`]: does the call
/// of `callee_def` at `gen_args`, made in a body `caller` typed by `typing_env`,
/// reach (through still-generic local calls, at most `PROPAGATION_DEPTH_CAP` deep)
/// a refuted open dispatch that stays adversarial at these arguments? Answers the
/// refuted site's callee name. Every decline is `None` (no refutation; the row keeps
/// its label).
fn generic_call_carries_open_dispatch_refutation<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    caller: DefId,
    callee_def: DefId,
    gen_args: ty::GenericArgs<'tcx>,
    depth: u32,
) -> Option<String> {
    const PROPAGATION_DEPTH_CAP: u32 = 8;
    if depth >= PROPAGATION_DEPTH_CAP
        || !gen_args.has_non_region_param()
        || tcx.trait_of_assoc(callee_def).is_some()
    {
        return None;
    }
    let Ok(Some(ty::Instance { def: ty::InstanceKind::Item(item), args: item_args })) =
        ty::Instance::try_resolve(tcx, typing_env, callee_def, gen_args)
    else {
        return None;
    };
    if !item.is_local()
        || item == caller
        || !matches!(tcx.def_kind(item), DefKind::Fn | DefKind::AssocFn)
        || !tcx.is_mir_available(item)
        || optimized_mir_query_would_cycle(tcx, item)
    {
        return None;
    }
    // Forces the callee's verification (and so its publish) if it has not run yet.
    let callee_body = tcx.optimized_mir(item);
    let refuted = with_crate_verification_state(tcx.sess, |state| {
        state.open_dispatch_refuted_callees.get(&item).cloned()
    })?;
    callee_body.basic_blocks.iter().find_map(|block| {
        let (TerminatorKind::Call { func: site, .. } | TerminatorKind::TailCall { func: site, .. }) =
            &block.terminator().kind
        else {
            return None;
        };
        let name = trust_mir_extract::func_operand_name_in_body(tcx, callee_body, site);
        if !refuted.contains(&name) {
            return None;
        }
        let (site_def, site_args) = site.const_fn_def()?;
        let substituted = tcx
            .try_instantiate_and_normalize_erasing_regions(
                item_args,
                typing_env,
                ty::EarlyBinder::bind(tcx, site_args),
            )
            .ok()?;
        let Some(trait_def_id) = tcx.trait_of_assoc(site_def) else {
            // The callee's refuted row was itself propagated from ITS callee.
            return generic_call_carries_open_dispatch_refutation(
                tcx,
                typing_env,
                caller,
                site_def,
                substituted,
                depth + 1,
            )
            .map(|_| name);
        };
        if trait_panic_free::local_trait_relies_on_panic_free_contract(tcx, site_def) {
            return None;
        }
        // Only the GENERIC arm propagates: the adversary of a generic refutation
        // picks a type parameter, which this call instantiates with its own
        // parameters; a virtual refutation's adversary picks the callee's argument
        // VALUE, which this caller supplies, so it is not carried over.
        let adversarial = match ty::Instance::try_resolve(tcx, typing_env, site_def, substituted)
        {
            Ok(None) => {
                dyn_trait_sealedness(tcx, trait_def_id) == trust_vcgen::TraitSealedness::Open
            }
            _ => false,
        };
        adversarial.then_some(name)
    })
}

/// Trust (OD-1, 2026-10-04, open shapes): the open-dispatch callee names this body's
/// Level-0 summary refutes as class (c) (`AdversarialOpenDispatch`): a row's own
/// absent callee, or the co-folded site a fold row was decided on.
fn refuted_open_dispatch_callees(
    results: &[(VerificationCondition, VerificationResult)],
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
) -> FxHashSet<String> {
    let mut out = FxHashSet::default();
    for (vc, result) in results {
        let Some((class, co_folded)) =
            l0_refutation_decision(vc, result, adversarial_open_dispatch)
        else {
            continue;
        };
        if class != trust_types::l0_refutation::L0RefutationClass::AdversarialOpenDispatch {
            continue;
        }
        let name = co_folded.or_else(|| trust_types::l0_refutation::absent_callee_name(&vc.kind));
        if let Some(name) = name {
            out.insert(name.to_string());
        }
    }
    out
}

/// Trust (2026-10-05, DYN-ARG-PROVENANCE-1): is the receiver of a virtual call a value
/// a caller this compilation does not see may choose? It must be one of `body`'s
/// arguments ([`dyn_receiver_root::argument_root`]), and that argument must not be one every call site
/// in this crate builds itself from nothing adversarial
/// (`dyn_argument_provenance::dyn_argument_is_built_locally_at_every_call`; a
/// promoted body is never asked and answers `true`).
fn virtual_receiver_is_callers_choice<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    receiver: &rustc_middle::mir::Operand<'tcx>,
) -> bool {
    let Some(root) = dyn_receiver_root::argument_root(tcx, body, receiver) else { return false };
    match root {
        dyn_receiver_root::ReceiverRoot::Arg(local) => {
            body.source.promoted.is_some()
                || !dyn_argument_provenance::dyn_argument_is_built_locally_at_every_call(
                    tcx,
                    body.source.def_id(),
                    local.as_usize() - 1,
                )
        }
        // Trust (2026-10-11, CLOSURE-CAPTURE-ROOT): a closure's capture of its
        // parent's parameter is the caller's choice exactly when the PARENT's
        // argument is — the same visibility / escape / call-site rule.
        dyn_receiver_root::ReceiverRoot::ParentArg { fn_def, param } => {
            !dyn_argument_provenance::dyn_argument_is_built_locally_at_every_call(
                tcx, fn_def, param,
            )
        }
    }
}

/// Trust (OD-1, 2026-10-04, open shapes): is a virtual call of a method of
/// `method_trait` on the trait object `gen_args.type_at(0)` adversarially
/// refutable — can a crate this compilation does not see construct a value of that
/// trait object whose method panics?
///
/// Every arm errs toward NOT refuting (the row then keeps its `runtime_checked`
/// label, which the strict and certify lanes refuse anyway):
/// * the `Self` must be a `dyn` with a principal trait;
/// * the principal and the method's trait must both be OPEN
///   (`dyn_trait_sealedness`): a sealed trait's impl set is closed, rung 2 decides it;
/// * the adversary must be able to supply an impl: a principal in the `Fn`/`AsyncFn`
///   family (any closure is one), or else a principal and a method trait with no
///   blanket impl (`impl<T: ?Sized + 'static> Any for T` leaves no impl to write).
/// Rung 1 (`#[trust::panic_free]`) is excluded by the caller as for the generic arm.
fn virtual_dispatch_is_adversarial<'tcx>(
    tcx: TyCtxt<'tcx>,
    method_trait: DefId,
    gen_args: ty::GenericArgs<'tcx>,
) -> bool {
    let Some(self_ty) = gen_args.types().next() else { return false };
    let ty::Dynamic(predicates, ..) = *self_ty.kind() else { return false };
    let Some(principal) = predicates.principal_def_id() else { return false };
    let open =
        |def_id: DefId| dyn_trait_sealedness(tcx, def_id) == trust_vcgen::TraitSealedness::Open;
    if !open(principal) || !open(method_trait) {
        return false;
    }
    let closure_principal = tcx.fn_trait_kind_from_def_id(principal).is_some()
        || tcx.async_fn_trait_kind_from_def_id(principal).is_some();
    let no_blanket = |def_id: DefId| tcx.trait_impls_of(def_id).blanket_impls().is_empty();
    closure_principal || (no_blanket(principal) && no_blanket(method_trait))
}

/// Trust (2026-10-02, diag-vs-report): the ONE decision whether a Level-0 row is
/// a compiler-reclassified REFUTATION (known-panicking call, native-unsupported
/// safety obligation, open generic dispatch). Asked by the Level-0 summary
/// (`strict_l0_verification_failure`) and by the published transport row
/// (`rows_with_l0_refutations`), so the compiler's line and the row targo's gate
/// counts cannot disagree. A `Proved` result or a non-L0 kind is never one.
///
/// Trust (OD-1 phase 0, 2026-10-04): the aggregate is decided per FOLD SITE, never
/// on its representative. A row standing for the whole-function panic-freedom fold
/// is an `AdversarialOpenDispatch` refutation whenever ANY co-folded site is one
/// (`OpenDispatchRefutationWitnesses::co_folded_callee`), whatever callee the row
/// happens to name.
fn l0_refutation_class(
    vc: &VerificationCondition,
    result: &VerificationResult,
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
) -> Option<trust_types::l0_refutation::L0RefutationClass> {
    l0_refutation_decision(vc, result, adversarial_open_dispatch).map(|(class, _)| class)
}

/// [`l0_refutation_class`], plus the co-folded open-dispatch callee when that is
/// what decided it (the row's own kind did not), so the published row can name
/// the site its text hides.
fn l0_refutation_decision<'w>(
    vc: &VerificationCondition,
    result: &VerificationResult,
    adversarial_open_dispatch: &'w OpenDispatchRefutationWitnesses,
) -> Option<(trust_types::l0_refutation::L0RefutationClass, Option<&'w str>)> {
    if matches!(result, VerificationResult::Proved { .. }) || !is_strict_l0_vc_kind(&vc.kind) {
        return None;
    }
    if let Some(class) = trust_types::l0_refutation::L0RefutationClass::of_kind(&vc.kind, |name| {
        adversarial_open_dispatch.contains(name)
    }) {
        return Some((class, None));
    }
    let co_folded = adversarial_open_dispatch.co_folded_callee.as_deref()?;
    vc_kind_stands_for_panic_freedom_fold(&vc.kind).then_some((
        trust_types::l0_refutation::L0RefutationClass::AdversarialOpenDispatch,
        Some(co_folded),
    ))
}

/// Trust (OD-1 phase 0, 2026-10-04): the adversarial-instantiation witnesses a
/// body's Level-0 refutations are classified against — the summary
/// (`strict_l0_verification_failure`) and the published row
/// (`rows_with_l0_refutations`) both read this one value.
///
/// THE GAP THIS CLOSES (measured on stage-1 `fbe76cb938`, 2026-10-04):
///
///     pub trait Tr { fn m(&self) -> u32; }
///     pub fn concrete_first<T: Tr>(v: &mut Vec<u32>, t: &T) -> u32 {
///         v.push(1);
///         t.m()
///     }
///
/// published its one panic-freedom row `runtime_checked` ("Level 0 summary: 0
/// failed, … 1 runtime-checked"), while the same two calls in the other order
/// published `failed`. The bridge folds every absent/foreign panic source into ONE
/// aggregate row named after its FIRST marked site (here the tolerated
/// `Vec::push`), and the refutation classifier matched callee names against that
/// row's text only, so the open dispatch `<T as Tr>::m` co-folded behind it was
/// invisible and `--allow-l0-gaps` would conditional-pass the body. (The fail-closed
/// full-verification gate already re-judged every fold site through
/// `transport_rows_with_fold_sites`; only the refutation label did not.)
#[derive(Debug, Default)]
struct OpenDispatchRefutationWitnesses {
    /// Callee names (as the absent-callee row spells them) of this body's
    /// adversarially refutable open dispatches: unresolved generic trait dispatches,
    /// virtual calls on a caller-supplied trait object
    /// (`adversarially_refutable_open_dispatch_callees`), and still-generic calls
    /// carrying a callee's refutation (`propagated_open_dispatch_refutations`).
    callees: FxHashSet<String>,
    /// The first site of this body's panic-freedom fold
    /// (`panic_freedom_fold_marked_sites`, via the session ledger) that is one of
    /// `callees`; `None` when no fold site is.
    co_folded_callee: Option<String>,
    /// Trust (OD-1, 2026-10-04, open shapes): for a witness that is a still-generic
    /// call carrying its callee's open-dispatch refutation, the refuted site's callee
    /// (`propagated_open_dispatch_refutations`), so the stamped row can say so.
    propagated: FxHashMap<String, String>,
    /// Trust (2026-10-05, rg concrete-misclassified): the witnesses in `callees`
    /// that are VIRTUAL calls through an argument-supplied trait object (OD-1 item
    /// 14). Description only — a stamped row names its deciding site's shape, so a
    /// fold row whose text names a concrete representative (`Term::unfold_apps`)
    /// is not read as "a concrete callee classified as generic dispatch".
    virtual_callees: FxHashSet<String>,
}

impl OpenDispatchRefutationWitnesses {
    fn new(callees: FxHashSet<String>, fold_sites: Option<&[String]>) -> Self {
        let co_folded_callee = fold_sites.unwrap_or_default().iter().find_map(|site| {
            let kind = VcKind::Assertion { message: site.clone() };
            trust_types::l0_refutation::absent_callee_name(&kind)
                .filter(|name| callees.contains(*name))
                .map(str::to_string)
        });
        Self {
            callees,
            co_folded_callee,
            propagated: FxHashMap::default(),
            virtual_callees: FxHashSet::default(),
        }
    }

    /// Record which witnesses are virtual (`dyn`) dispatches (row text only).
    fn with_virtual(mut self, virtual_callees: FxHashSet<String>) -> Self {
        self.virtual_callees = virtual_callees;
        self
    }

    /// The shape of the open dispatch a witness name stands for, as the stamped
    /// row's reason states it.
    fn shape_of(&self, name: &str) -> &'static str {
        if self.propagated.contains_key(name) {
            "a still-generic call carrying its callee's open-dispatch refutation"
        } else if self.virtual_callees.contains(name) {
            "an open, uncontracted VIRTUAL (`dyn`) trait dispatch on a trait object this \
             body's caller supplies"
        } else {
            "an open, uncontracted, unresolved GENERIC trait dispatch"
        }
    }

    /// Record which witnesses are propagated refutations (row text only: membership
    /// in `callees` is what decides).
    fn with_propagated(mut self, propagated: FxHashMap<String, String>) -> Self {
        self.propagated = propagated;
        self
    }

    fn contains(&self, name: &str) -> bool {
        self.callees.contains(name)
    }
}

/// Does this VC's kind carry one of the per-site markers the whole-function
/// panic-freedom aggregate's representative is chosen from? The VC-side twin of
/// `transport_row_stands_for_fold` (which reads the transport row's description).
fn vc_kind_stands_for_panic_freedom_fold(kind: &VcKind) -> bool {
    let text = match kind {
        VcKind::Assertion { message } => message.as_str(),
        VcKind::UnsupportedMir { detail, .. } => detail.as_str(),
        _ => return false,
    };
    PANIC_FREEDOM_FOLD_MARKERS.iter().any(|marker| text.contains(marker))
}

/// Trust (2026-10-02, diag-vs-report): stamp every Level-0 refutation the summary
/// counts onto the row the transport publishes for it. `rows` is built 1:1 from
/// `results` (`build_transport_results_with_runtime_checks_bound_attested` maps
/// each result to one row, in order); the row's typed kind must equal the VC's,
/// so a misaligned pairing reclassifies nothing rather than the wrong row (that
/// fallback leaves the summary and the row disagreeing again, as before this
/// stamp; it never relabels a row it cannot pair). Only ever turns an undecided
/// row into `failed` (`trust_types::l0_refutation::reclassify_published_row`).
/// `None` when no row changed.
///
/// The summary's two authenticated-assumption skips (definition-entry and
/// assumed-total) are not repeated here: those rows carry a `Proved` result,
/// which `l0_refutation_class` already rejects, so the set of rows classified is
/// the same. Pinned by
/// `l0_refutation_stamp_is_index_aligned_and_survives_the_lowering_collapse`.
fn rows_with_l0_refutations(
    results: &[(VerificationCondition, VerificationResult)],
    rows: &[TransportObligationResult],
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
) -> Option<Vec<TransportObligationResult>> {
    if results.len() != rows.len() {
        return None;
    }
    let mut rewritten: Option<Vec<TransportObligationResult>> = None;
    for (idx, ((vc, result), row)) in results.iter().zip(rows).enumerate() {
        if row.typed_kind.as_deref() == Some(&vc.kind)
            && let Some((class, co_folded)) =
                l0_refutation_decision(vc, result, adversarial_open_dispatch)
        {
            let mut candidate = row.clone();
            if trust_types::l0_refutation::reclassify_published_row(&mut candidate, class) {
                // Trust (OD-1 phase 0): the row's text names the fold's
                // representative, not the site that refuted it; say which.
                // Trust (2026-10-05, rg concrete-misclassified): say also that the
                // representative the row's text names is NOT the refuted site, and
                // which dispatch shape the deciding site is. Before, every fold row
                // read "… is an open, uncontracted generic trait dispatch" even when
                // the deciding site was a `dyn` call (OD-1 item 14), and preview 2
                // (10-05) misread 11 clean-ck0 rows naming `Term::unfold_apps`,
                // `infer_in`, `[T]::contains` as concrete callees misclassified.
                if let Some(callee) = co_folded
                    && let Some(reason) = candidate.reason.as_mut()
                {
                    let shape = adversarial_open_dispatch.shape_of(callee);
                    let representative = trust_types::l0_refutation::absent_callee_name(&vc.kind)
                        .filter(|named| *named != callee)
                        .map(|named| {
                            format!(
                                " (the callee this row's text names, `{named}`, is only the \
                                 fold's representative and is not itself the refuted site)"
                            )
                        })
                        .unwrap_or_default();
                    reason.push_str(&format!(
                        "; decided per fold site: this row stands for the whole-function \
                         panic-freedom fold, and its co-folded call to `{callee}` is {shape}\
                         {representative}"
                    ));
                }
                // Trust (OD-1, 2026-10-04, open shapes): a propagated refutation names
                // the callee's refuted site.
                let deciding = co_folded.map(str::to_string).or_else(|| {
                    trust_types::l0_refutation::absent_callee_name(&vc.kind).map(str::to_string)
                });
                if let Some(call) = deciding
                    && let Some(inner) = adversarial_open_dispatch.propagated.get(&call)
                    && let Some(reason) = candidate.reason.as_mut()
                {
                    reason.push_str(&format!(
                        "; propagated: `{call}` is a still-generic call to a local body whose \
                         own row was refuted on its open dispatch `{inner}`, which stays open \
                         at this call's arguments (the adversary instantiating this body's \
                         parameter instantiates the callee's)"
                    ));
                }
                let out = rewritten.get_or_insert_with(|| {
                    let mut v = Vec::with_capacity(rows.len());
                    v.extend_from_slice(&rows[..idx]);
                    v
                });
                out.push(candidate);
                continue;
            }
        }
        if let Some(out) = rewritten.as_mut() {
            out.push(row.clone());
        }
    }
    rewritten
}

// Trust: fail-closed on absent-callee panic (revert of d8a9bbc28e fail-open;
// unproven panic MUST fail closed). The `FullVerification::<kind>` prefixes the
// native round-trip stamps onto an `UnsupportedMir` VC for a STRICT-L0 SAFETY
// obligation (`ArithmeticSafety` — e.g. an `x.pow(20)` overflow whose repeated-mul
// the native trust-mc lane returns `Unsupported` for; `BoundsCheck`;
// `MemorySafety`). See [`legacy_unsupported_kind_detail`], which builds the kind as
// `format!("FullVerification::{kind:?}")`.
// Owned by `trust_types::l0_refutation::NATIVE_UNSUPPORTED_SAFETY_KIND_PREFIXES`
// since 2026-10-02.
// (`is_native_unsupported_strict_l0_safety_mir` moved to `trust_types::l0_refutation`
// on 2026-10-02; its rationale is in `strict_l0_verification_failure`, and the summary
// and the published row both
// reach it through `l0_refutation_class`.)

fn is_strict_l0_api_obligation_kind(kind: &trust_verifier_api::ObligationKind) -> bool {
    matches!(
        kind,
        trust_verifier_api::ObligationKind::MemorySafety
            | trust_verifier_api::ObligationKind::ArithmeticSafety
            | trust_verifier_api::ObligationKind::BoundsCheck
    )
}

/// Determinism plan §3.7 (2026-10-01): the `timed_out=` the compiler's verifier
/// status notes print is ONE number per function, the rows it publishes that a
/// clock left unproved (`PublishedRowTally::clock_stopped`), never the native
/// run's summary count. A release judge sums every `timed_out=` in a check's log
/// as the obligations whose wall-clock budget lapsed, and the native count
/// missed every row a later lane gave up on the deadline: measured on the
/// release lane at load ~70, aterm-codec's `base64::encode_padded` fell from
/// 73/81 proved to 0/83, every row `trust-full-verifier, 0ms`, and its note said
/// `timed_out=0`. The clock count still covers every native timeout no later
/// lane decided — that row publishes `timeout`, or `runtime_checked` with the
/// `wall-backstop` cause — and drops one a later lane proved or refuted.
///
/// The native status notes print it in place of the native count. This is the
/// note for a function with no native run (the advisory preprocessing-budget
/// verdict, a lane that never dispatched natively): printed only when a clock
/// stopped a row, so a run with no clock prints exactly what it printed before
/// and no function prints two `timed_out=` for one count.
fn verifier_status_timed_out_note(published_rows: PublishedRowTally) -> Option<String> {
    (published_rows.clock_stopped > 0).then(|| {
        format!(
            "verifier clock stops: timed_out={} published obligation(s) a wall clock left unproved",
            published_rows.clock_stopped
        )
    })
}

/// A native verifier status note (`label`: the L0 report's "native verifier
/// status", the strict abort's "native full verifier status"): the native run's
/// status and summary, except that `timed_out=` is this function's clock count
/// ([`verifier_status_timed_out_note`]).
fn native_verifier_status_note(
    label: &str,
    result: &trust_verifier_api::VerificationRunResult,
    published_rows: PublishedRowTally,
) -> String {
    format!(
        "{label}: {:?}; requested={}, proved={}, failed={}, unknown={}, timed_out={}, unsupported={}, skipped={}, insufficient_strength={}",
        result.status,
        result.summary.requested_obligations,
        result.summary.proved,
        result.summary.failed,
        result.summary.unknown,
        published_rows.clock_stopped,
        result.summary.unsupported,
        result.summary.skipped,
        result.summary.insufficient_strength,
    )
}

/// Emit a diagnostic for Level 0 safety verification gaps.
///
/// Under strict batteries-on verification, every non-proved Level-0 outcome is
/// a hard error: failed, unknown, timed out, runtime-checked, unsupported, or
/// skipped. Survey and the explicit memory-safe policy report their
/// permitted outcomes without claiming proof.
///
/// Known-panicking unmodeled calls are still reclassified as failed so reports
/// distinguish a concrete panic path from an ordinary coverage gap. Both are
/// fatal in strict mode. A declared, message-matched contract panic is
/// conditional evidence only in survey; strict and memory-safe keep it as
/// an ordinary failed obligation.
///
/// `published_rows` is the tally of the rows this function publishes; its
/// clock count is the `timed_out=` the status note prints
/// ([`verifier_status_timed_out_note`]).
fn report_strict_l0_verification_failure<'tcx>(

    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &VerificationArtifacts,
    policy: &TrustVerifyPolicy,
    published_rows: PublishedRowTally,
    // The adversarial-instantiation witness set `publish_body_verification_outcome`
    // computed once for this body and used to stamp the published rows, so the
    // summary and the rows classify against the SAME set.
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
) {
    if let Some(diagnostic) = prepare_strict_l0_verification_failure(
        tcx, body, func_path, artifacts, policy, published_rows, adversarial_open_dispatch,
    ) {
        diagnostic.emit(tcx, body.span);
    }
}

fn prepare_strict_l0_verification_failure<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &VerificationArtifacts,
    policy: &TrustVerifyPolicy,
    published_rows: PublishedRowTally,
    // The adversarial-instantiation witness set `publish_body_verification_outcome`
    // computed once for this body and used to stamp the published rows, so the
    // summary and the rows classify against the SAME set.
    adversarial_open_dispatch: &OpenDispatchRefutationWitnesses,
) -> Option<PreparedDiagnostic> {
    let strict = policy.fail_closed();
    let Some(failure) = strict_l0_verification_failure(
        tcx.sess.overflow_checks(),
        &artifacts.results,
        &artifacts.result_bindings,
        &artifacts.proof_authorities,
        artifacts.full_verification.as_ref(),
        adversarial_open_dispatch,
    ) else {
        return None;
    };
    // Trust (R1 scan-gap warning gate): a Level-0 verdict is being withheld for
    // this function (in EVERY policy/output mode that reaches this seam). Recorded
    // so `trust_ensure_whole_crate_verification` states the crate-level R1
    // scan-poison cause only on compiles where a verdict was actually withheld —
    // never on ordinary fully-proved source (see `r1_scan_gap_warning_applies`).
    with_crate_verification_state(tcx.sess, |state| state.l0_verdict_withheld = true);

    let header = format!(
        "Trust Level 0 safety verification incomplete for `{func_path}`: {} obligation(s) were not proved",
        failure.total()
    );

    // The explicit memory-safe policy may demote panic-only gaps in a function
    // with no source or inlined `unsafe`; undefined-behavior-bearing functions
    // remain strict. This is a policy opt-out, not an activation flag.
    let demote_panics = memory_safe_demotion_applies(tcx, body);
    let requires_full_discharge =
        tcx.sess.opts.unstable_opts.trust_policy.requires_full_discharge();
    let aborting =
        strict && !demote_panics && strict_failure_is_fatal(failure, requires_full_discharge);
    let note1 = if aborting {
        "strict Trust verification requires every Level 0 obligation to be statically proved; \
         failed, unknown, timed-out, runtime-checked, unsupported, and skipped outcomes are all \
         build errors"
    } else if demote_panics {
        "Level 0 safety refutations in this function (which contains no `unsafe`) are reachable \
         but MEMORY-SAFE panics — rustc inserts the runtime check, so they are not undefined \
         behavior; `-Z trust-policy=memory-safe` demotes them to warnings so correct memory-safe \
         code compiles"
    } else if policy.is_explicit_advisory() {
        // Verification still ran and is fully reported, but every Level 0
        // refutation is DOWNGRADED to this warning so the build succeeds. This is
        // the opt-in escape hatch while the prover/solver is being improved;
        // strict mode makes the same gap a build error.
        "this run is in survey mode (`-Z trust-policy=advisory`): Level 0 safety refutations are \
         DOWNGRADED to warnings (not build errors) so the crate compiles while the \
         prover/solver is improved; verification still ran and every obligation is \
         reported below. Strict verification makes a failed Level 0 \
         obligation a build error"
    } else if strict {
        // Trust: the only unproved rows here are runtime-checked, so this seam does
        // not abort (`strict_failure_is_fatal`). The build's outcome is the strict
        // verification seam's (`tolerate_default_gap`), which still fails it for a
        // fail-closed assumption-panic row and the other cases it lists, so the note
        // claims no outcome. No nonfatal policy was given, so it must not say one was.
        "every unproved Level 0 obligation here is runtime-checked; none of them carries \
         proof credit"
    } else {
        "this run uses an explicit nonfatal Trust policy: Level 0 obligations are \
         reported without proof credit"
    };
    let note2 = format!(
        "Level 0 summary: {} failed, {} unknown or timed out, {} runtime-checked, {} skipped",
        failure.failed, failure.unknown, failure.runtime_checked, failure.skipped,
    );
    let note3 = match artifacts.full_verification.as_ref() {
        Some(result) => {
            Some(native_verifier_status_note("native verifier status", result, published_rows))
        }
        None => verifier_status_timed_out_note(published_rows),
    };

    // Trust-as-feedback-partner: surface the agentic guidance for the unproved
    // obligations so a developer/AI sees the actionable remediation (the
    // must-hold property + the top suggested fix), not just a count. Deduped by
    // property and capped so the diagnostic stays readable.
    let mut seen_guidance = FxHashSet::default();
    let mut guidance_notes: Vec<String> = Vec::new();
    for (vc, result) in &artifacts.results {
        if matches!(result, VerificationResult::Proved { .. }) {
            continue;
        }
        if let Some(g) = vc.kind.agentic_guidance() {
            if seen_guidance.insert(g.must_hold.clone()) {
                let fix = g.suggested_fixes.first().map(|f| f.change.as_str()).unwrap_or("");
                guidance_notes
                    .push(format!("guidance — must hold: {} | fix: {}", g.must_hold, fix));
                if guidance_notes.len() >= 4 {
                    break;
                }
            }
        }
    }

    // Only DATA is retained. The selector cannot be reconstructed from this
    // severity or message; ordinary immediate callers emit it unchanged.
    let mut children = vec![
        PreparedDiagnosticChild::Note(note1.to_string()),
        PreparedDiagnosticChild::Note(note2),
    ];
    children.extend(note3.map(PreparedDiagnosticChild::Note));
    children.extend(guidance_notes.into_iter().map(PreparedDiagnosticChild::Help));
    Some(PreparedDiagnostic { aborting, header, children })
}

/// Trust: in advisory mode, hard-error on a guaranteed Level-0
/// safety refutation — a `Failed` obligation of a UB / guaranteed-panic kind
/// whose counterexample formula is GROUND (no free input variables), so the
/// violation is unconditional. This is the soundness discriminator that keeps
/// advisory verification useful without rejecting merely possible panics: a
/// constant `Vec::with_capacity(1 << 28)` lowers to the ground formula
/// `Ge(1<<28, 1<<28)` and errors, while `a + b` / `s[i]` carry free input vars
/// (merely POSSIBLE violations — defined Rust panic/wrap behavior) and stay
/// warnings.
fn escalate_refuted_l0_safety_counterexamples(

    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    func_path: &str,
    artifacts: &VerificationArtifacts,
) {
    if let Some(diagnostic) = publication_escalation::prepare_refuted_l0_safety_counterexamples(
        tcx, body, func_path, artifacts,
    ) {
        diagnostic.emit(tcx, body.span);
    }
}

/// Trust: the refutation label for a violation decided by CONSTRUCTION, and the
/// tripwire for the case where a backend claimed to have proved it anyway.
///
/// Two obligation families are refuted structurally, without consulting any
/// backend: a ground `Bool(true)` unsafe-demand FINDING (SAT is its own witness)
/// and a bulk allocation whose element count folds to a ground constant at or
/// above the budget ceiling. For both, the violation holds on every reaching
/// execution, so NO sound prover can return `Proved` — whichever lane produced
/// such a verdict did so about a formula that does not contain this violation.
///
/// That is precisely the failure the trust-mc positive-witness gate
/// (`trust_mc_chc_credit_witness`) exists to make impossible: an obligation whose
/// violation predicate never entered the solved rule set must fail closed to
/// unsupported, never to proved. So the `Proved` arm here is an ASSERTION over
/// that invariant, not routine coverage — reaching it means a credit path
/// admitted evidence without a witness. It stays fail-closed (the refutation is
/// still applied, so the build still rejects the program) and carries a distinct
/// solver token so the breach is visible in the report row instead of being
/// silently laundered into an ordinary structural refutation.
fn structural_refutation_solver_label(
    structural_label: &'static str,
    overridden: &VerificationResult,
) -> trust_types::Symbol {
    match overridden {
        VerificationResult::Proved { solver, .. } => {
            debug_assert!(
                false,
                "positive-witness invariant breach: `{solver}` proved a structurally refuted obligation"
            );
            format!("{structural_label}-over-unwitnessed-proof:{solver}").into()
        }
        _ => structural_label.into(),
    }
}

/// Trust: VC kinds whose `Failed` verdict is a sound refutation of undefined
/// behavior or a guaranteed panic. Deliberately EXCLUDES `Assertion`,
/// `Unreachable`, and `UnsupportedMir`: a refuted user `assert!` is a logic
/// property (not soundness), `Unreachable` is reachability, and `UnsupportedMir`
/// is a modeling gap — none is a sound refutation of valid Rust.
/// Trust (SOUNDNESS — surviving-mutant fix): force every UNSAFE-DEMAND Assertion
/// FINDING to `Failed`. The fail-closed producers
/// (`synthetic_unmodeled_unsafe_call_vcs` / `synthetic_nonmodeled_unsafe_op_vcs`)
/// emit `VcKind::Assertion { message: "[unsafe:…] …" }` with a `Bool(true)`
/// violation — "always a finding: no model of this construct's effects". Such a
/// finding is UNPROVABLE by construction (SAT is the trivial witness), but the
/// native typed-CHC transport cannot lower a bare ground assertion and returns
/// Proved by default, which silently regressed `undocumented_unsafe_sig_call`
/// from REFUTE to a false PROVE. This override is load-bearing on the native
/// path (mirrors `refute_forced_unbounded_allocations` for the OOM ceiling).
///
/// The `[unsafe` MESSAGE MARKER selects the FAMILY, not the verdict: the
/// full-lane reconstruction (`legacy_vc_from_api_obligation`) re-kinds the row to
/// `HardenedBoundary`/`UnsupportedMir` and can drop a payload-less `Bool(true)`
/// violation to the `Bool(false)` placeholder, so a formula-only selector would
/// miss the reconstructed mandate. The marker survives every shape, so it stays
/// the selector.
///
/// Trust (positive-witness ICE + nullified sep discharges): the marker alone is
/// NOT the refutation criterion. The `[unsafe` family holds BOTH
/// unprovable design mandates (`[unsafe] missing SAFETY comment`,
/// `[unsafe:unmodeled-call]`, `[unsafe:sep:addr_of]`, `[unsafe:asm]`, … — all
/// `Formula::Bool(true)`) AND genuinely solvable separation-logic obligations
/// with real violation formulas that the vcgen discharge lanes exist to prove:
/// `[unsafe:sep:deref] null check` (`ptr == 0`, discharged by
/// `SepEngine::discharge_stack_good` / `discharge_box_good`) and
/// `[unsafe:sep:backing] … at construction` (`alloc_size < len`, the ESTABLISH
/// obligation the `#[trust::backing]` certificate is built to discharge).
/// Overriding those destroyed real proofs — and, because a genuine `Proved`
/// then reached `structural_refutation_solver_label`, tripped its
/// positive-witness assertion and ICEd the compiler on ordinary code
/// (`let x = 7; let p = &x as *const i32; unsafe { *p }`).
///
/// So a result a solver PROVED about a NON-CONSTANT violation is left alone —
/// exactly the "a discharged Assertion carries a real formula and is untouched"
/// contract this pass was introduced with. A constant violation is still
/// overridden from any non-`Failed` verdict, but the two constant classes are
/// NOT symmetric:
/// - `Bool(true)` is unprovable by construction (SAT is the trivial witness),
///   so a `Proved` over it IS a positive-witness breach, and the assertion in
///   `structural_refutation_solver_label` is a real invariant on this class —
///   and on this class only.
/// - `Bool(false)` is the full-lane reconstruction PLACEHOLDER
///   (`legacy_vc_from_api_obligation` falls back to it when the obligation's
///   payload formula cannot be reconstructed), and it is UNSAT — any sound
///   solver CAN return `Proved` for it. Such a proof is refused for VACUITY,
///   not unprovability: it says nothing about the original obligation, and the
///   vacuity gate (`apply_vacuity_gate_with_authority`) runs only DOWNSTREAM of
///   this pass (from `build_proof_results_with_runtime_checks` / authority
///   minting), so this pass must refuse it itself. It is refuted under its own
///   `…-over-vacuous-placeholder-proof:` label and deliberately EXCLUDED from
///   the positive-witness assertion, which would otherwise ICE a debug build on
///   a legitimately provable formula.
/// Every other verdict (Unknown/Timeout/Skipped/…) is still forced Failed for
/// the whole family, so this can only ADD failures relative to no pass at
/// all, and removes none that a solver did not independently prove; a
/// panic-freedom Assertion (`"panic freedom …"`) or any non-unsafe Assertion is
/// untouched.
///
/// Trust (honest label, 2026-10-02): what this pass produces is a FAIL-CLOSED
/// failure, not a refutation. No row it rewrites carries a counterexample —
/// the row came back Unknown/Timeout, never reached a solver (e.g. the function
/// did not lower to native trust-ir), or carried a proof this pass refuses.
/// Every row it writes is stamped `trust_types::UNSAFE_DEMAND_FAIL_CLOSED_SOLVER`
/// (or `<that>-over-<reason>:<solver>`), and `trust_types::FailureBasis::
/// for_failed_row` reads that label as `UnprovedFailClosed`, so every report
/// surface says "unproved, no counterexample" instead of presenting a found
/// violation. The one exception is a DEFINITE structural finding
/// (`trust_types::unsafe_demand_is_definite_violation`: a double free or a
/// use-after-free the separation model established on every reaching
/// execution): that IS a found violation, so it is stamped
/// `trust_types::UNSAFE_DEMAND_DEFINITE_SOLVER` and keeps reading as refuted. The OUTCOME is unchanged — still `Failed`, still failing every
/// gate exactly as before; only its description changed
/// (docs/DECISION_QUEUE.md, row UD-1; docs/KNOWN_HAZARDS.md).
fn refute_unsafe_demand_findings(results: &mut [(VerificationCondition, VerificationResult)]) {
    let dbg = env_flag_enabled("TRUST_UNSAFE_CALL_DEBUG");
    for (vc, result) in results.iter_mut() {
        if dbg {
            let kind_dbg = format!("{:?}", vc.kind);
            if kind_dbg.to_lowercase().contains("unsafe") {
                eprintln!(
                    "TRUST_UNSAFE_CALL_DEBUG: refute pass sees kind={kind_dbg} result={result:?}"
                );
            }
        }
        // The `[unsafe` marker survives the full-lane reconstruction across every
        // shape the obligation can take. The ORIGINAL VC is
        // `Assertion { message: "[unsafe:…] …" }`; a native-transport row
        // reconstructs (`legacy_vc_from_api_obligation` →
        // `native_contract_vc_kind`) to `HardenedBoundary { category:
        // UnsafeOperation, detail: "[unsafe:…] …" }`; the fallback shape is
        // `UnsupportedMir { detail }`. Match all three. The
        // `HardenedBoundary { category: UnsafeOperation }` arm is itself
        // sufficient (that category IS the unsafe-op demand), but the marker
        // check keeps it precise across future category reuse.
        //
        // The native trust-mc lane can NOT trivially "prove" these rows:
        // `trust_mc_chc_credit_witness` (crates/trust-bmc/src/verifier_api.rs)
        // refuses `TriviallySafe`-route credit for any obligation that is not
        // the whole-function structural query, so a reconstructed unsafe row
        // cannot arrive here `Proved` without a per-obligation
        // violation-predicate witness. That gate is what makes the
        // `discharged_by_a_real_solve` skip below safe: it spares only
        // genuinely witnessed discharges, so the false-PROVE class this pass
        // was introduced to close stays closed.
        let carries_unsafe_marker = match &vc.kind {
            VcKind::Assertion { message } => message.starts_with("[unsafe"),
            VcKind::HardenedBoundary { category, detail, .. } => {
                matches!(category, trust_types::HardenedVcCategory::UnsafeOperation)
                    || detail.contains("[unsafe")
            }
            VcKind::UnsupportedMir { kind, detail } => {
                kind.contains("[unsafe") || detail.contains("[unsafe")
            }
            _ => false,
        };
        // Trust (honest label): a DEFINITE structural finding (a double free or
        // a use-after-free the separation model established on every reaching
        // execution) is a found violation, not a fail-closed gap, and is
        // stamped with its own label so it keeps reading as refuted. Read off
        // the same message that selected the family, in every shape it takes.
        let definite_violation = match &vc.kind {
            VcKind::Assertion { message } => {
                trust_types::unsafe_demand_is_definite_violation(message)
            }
            VcKind::HardenedBoundary { detail, .. } => {
                trust_types::unsafe_demand_is_definite_violation(detail)
            }
            VcKind::UnsupportedMir { kind, detail } => {
                trust_types::unsafe_demand_is_definite_violation(kind)
                    || trust_types::unsafe_demand_is_definite_violation(detail)
            }
            _ => false,
        };
        let structural_label = if definite_violation {
            trust_types::UNSAFE_DEMAND_DEFINITE_SOLVER
        } else {
            trust_types::UNSAFE_DEMAND_FAIL_CLOSED_SOLVER
        };
        // A solver that PROVED a NON-CONSTANT violation discharged a real
        // obligation (the sep-engine null / in-bounds / alignment / backing
        // ESTABLISH lanes). Only a CONSTANT violation may have a `Proved`
        // overridden, and the two constant classes carry different reasons —
        // see the doc comment.
        let discharged_by_a_real_solve = matches!(result, VerificationResult::Proved { .. })
            && !matches!(vc.formula, Formula::Bool(_));
        if !carries_unsafe_marker
            || discharged_by_a_real_solve
            || matches!(result, VerificationResult::Failed { .. })
        {
            continue;
        }
        let time_ms = match &*result {
            VerificationResult::Proved { time_ms, .. }
            | VerificationResult::Unknown { time_ms, .. } => *time_ms,
            VerificationResult::Timeout { timeout_ms, .. } => *timeout_ms,
            _ => 0,
        };
        // A `Proved` over the `Bool(false)` reconstruction placeholder is
        // refuted for VACUITY, under its own label: `Bool(false)` is UNSAT, so
        // a sound solver legitimately proves it, and the proof says nothing
        // about the obligation whose payload the reconstruction lost. It is
        // NOT a positive-witness breach, so it must not reach
        // `structural_refutation_solver_label`, whose assertion is an
        // invariant of the one class that is unprovable by construction:
        // `Bool(true)`.
        let solver = match (&*result, &vc.formula) {
            (VerificationResult::Proved { solver, .. }, Formula::Bool(false)) => {
                format!("{structural_label}-over-vacuous-placeholder-proof:{solver}").into()
            }
            _ => structural_refutation_solver_label(structural_label, result),
        };
        *result = VerificationResult::Failed { solver, time_ms, counterexample: None };
    }
}

fn is_refutable_l0_safety_vc_kind(kind: &VcKind) -> bool {
    matches!(
        kind,
        VcKind::ArithmeticOverflow { .. }
            | VcKind::ShiftOverflow { .. }
            | VcKind::NegationOverflow { .. }
            | VcKind::CastOverflow { .. }
            | VcKind::DivisionByZero
            | VcKind::RemainderByZero
            | VcKind::IndexOutOfBounds
            | VcKind::SliceBoundsCheck
            | VcKind::UnboundedAllocation { .. }
    )
}

/// Trust (`[unreach]` completeness, fuzzer-revealed): reclassify an inconclusive
/// (`Unknown`/`Timeout`) verdict on an exhaustive-enum `otherwise → unreachable`
/// obligation to `Proved` when its violation formula is PROPOSITIONALLY UNSAT.
///
/// The vcgen `build_exhaustive_enum_validity_facts` conjoins the validity fact
/// `disc ∈ {cases}` (`Or([Eq(disc,c0),…])`) onto every VC of a switch the TyCtxt
/// extraction certified `exhaustive_enum_unreachable`; the `otherwise → unreachable`
/// path guard contributes `disc ∉ {cases}` (`¬Eq(disc,c0) ∧ …`). Together that is
/// `(E0∨…∨En) ∧ ¬E0 ∧ … ∧ ¬En`, UNSAT by PURE RESOLUTION over the opaque `Eq`
/// atoms — a sound, theory-free proof the trap is dead. ay cannot STRICTLY
/// reconstruct this trivial contradiction (it only strict-proves linear-arithmetic
/// UNSAT; here it falls back to an unverified `trust` step / a `Generic` theory
/// lemma the strict checker rejects), so the trap would otherwise stay
/// `[unreach] runtime-checked` despite being provable. This brings the advisory route
/// to PARITY with the native trust-mc structural-reachability path, which already
/// drops the dead `otherwise` transition under the same flag (see the
/// `Inst::Switch { exhaustive_enum_unreachable, .. }` arm).
///
/// SOUNDNESS: the validity fact is emitted ONLY under the flag (case values ==
/// the enum's FULL tag set), so the contradiction reflects a real invariant — a
/// partial/non-exhaustive trap never gets the disjunction conjunct, so
/// `formula_is_unsat_by_exhaustive_discriminant` returns false and it stays
/// runtime-checked (drop-in). NEVER promotes a `Failed` (a genuine refutation is
/// untouched) and NEVER promotes a non-matching formula.
/// Promote an inconclusive (Unknown/Timeout) obligation to `Proved` when the clean
/// CIC kernel INDEPENDENTLY certifies it (`trust_certify::certify_vc` returns a
/// re-checked `CleanCic` term). ay's SMT/CHC and trust-mc's PDR leave some L0 safety
/// obligations Unknown/Unsupported (e.g. a BV-modeled i128 guarded add/overflow whose
/// bounded result-range fits the type) that the kernel-certification lane discharges
/// directly. Downstream, `certify_vc` runs ONLY on `Proved` obligations, so an Unknown
/// the kernel CAN prove would be a coverage gap despite a genuine kernel proof — this
/// closes that gap; the certificate is attached by the subsequent `certify_all`.
///
/// SOUND + fail-closed: `certify_vc` returns `Some` ONLY when the clean kernel
/// re-checks (under zero trust) a term proving the obligation's violation formula
/// UNSAT — a genuinely-violable obligation has a SAT violation, so `certify_vc`
/// returns `None` and nothing is promoted (never mints a false `Proved`). Monotone:
/// upgrades only an inconclusive verdict, never overrides `Proved`/`Failed`.
///
/// Trust (M5 blocker #0 — census core repeatability): `deadline` is the SAME
/// per-function wall-clock deadline the solver dispatch already respects
/// (`verify_fn_deadline` / tracked `-Ztrust-verify-function-budget-ms`; zero means
/// no deadline). `certify_vc` reconstructs and re-checks a CIC proof term with the
/// clean kernel (whnf/iota reduction) — for a machine-generated function with a
/// very large obligation set this per-VC kernel walk can itself stall the build
/// even though the solver stage already finished within budget (observed:
/// `num::dec2flt::lemire` stalled ≥8min/10GB inside the kernel here). Once the
/// deadline is reached, this loop STOPS attempting further kernel promotions for
/// this function — every remaining obligation simply keeps whatever verdict it
/// already had. Fail-closed by construction: this function only ever UPGRADES an
/// inconclusive verdict, so stopping early can only mean FEWER promotions, never
/// mint a `Proved` that wasn't independently kernel-certified.
///
/// Determinism plan §3.7: every `Unknown` row from the first one the deadline
/// kept from the kernel on is recorded in `clock_stops` — the clock, not the
/// kernel, left it undecided ([`record_kernel_lane_clock_cut`]). The lane
/// records its own cut, so a caller cannot run it and drop the record.
fn promote_kernel_certifiable(
    results: &mut [(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
    clock_stops: &mut ClockStops,
) {
    let debug = env_flag_enabled("TRUST_ASSERT_DEBUG");
    let mut cut_at = None;
    for (index, (vc, result)) in results.iter_mut().enumerate() {
        if deadline.is_some_and(|at| std::time::Instant::now() >= at) {
            cut_at = Some(index);
            break;
        }
        let time_ms = match &*result {
            VerificationResult::Unknown { time_ms, .. } => *time_ms,
            VerificationResult::Timeout { timeout_ms, .. } => *timeout_ms,
            _ => continue,
        };
        // Trust (M5 blocker #0): consult the deadline right before the
        // (potentially expensive) kernel re-check, not before — a function that
        // finishes well within budget never observes this at all.
        if deadline.is_some_and(|at| std::time::Instant::now() >= at) {
            if debug {
                eprintln!(
                    "[KERNEL_PROMOTE] per-function certify budget exceeded; stopping further kernel-certify promotion for this function (remaining obligations keep their prior verdict)"
                );
            }
            cut_at = Some(index);
            break;
        }
        let certifiable = trust_certify::certify_vc(vc).is_some();
        if debug {
            eprintln!(
                "[KERNEL_PROMOTE] {:?} @ {:?} inconclusive; certify_vc={} kind={:?}",
                vc.function, vc.location, certifiable, vc.kind
            );
        }
        if !certifiable {
            continue;
        }
        *result = VerificationResult::Proved {
            solver: "clean-kernel-certified".into(),
            time_ms,
            strength: ProofStrength::smt_unsat_strict_checked(),
            proof_certificate: None,
            solver_warnings: None,
            native_proof_envelope: None,
        };
    }
    if let Some(cut_at) = cut_at {
        record_kernel_lane_clock_cut(clock_stops, results, cut_at, |result| {
            matches!(result, VerificationResult::Unknown { .. })
        });
    }
}

/// A replacement earned by the actual kernel certifier before its original
/// native binding is retired. The certificate remains tied to the entire VC,
/// not just its formula, across the remaining result transformations.
struct CertifiedPanicFreedomGrounding {
    public_obligation_id: Option<String>,
    row: ExactResultRowIdentity,
    evidence: trust_ir::ProofEvidence,
    /// Trust (grounded catch-all premise floor): the sibling rows this
    /// grounding stood on — see [`GroundedCatchallPremises`].
    premises: GroundedCatchallPremises,
}

impl CertifiedPanicFreedomGrounding {
    fn seed_exact_certificate(
        self,
        results: &[(VerificationCondition, VerificationResult)],
        certificates: &mut [Option<trust_ir::ProofEvidence>],
    ) -> bool {
        if certificates.len() != results.len() {
            return false;
        }
        let Some((vc, VerificationResult::Proved { .. })) = results.get(self.row.index) else {
            return false;
        };
        if exact_result_row_identity(self.row.index, vc).as_ref() != Some(&self.row) {
            return false;
        }
        certificates[self.row.index] = Some(self.evidence);
        true
    }
}

/// Trust (grounded catch-all premise floor, 2026-09-24): what a whole-function
/// panic-freedom grounding stood on, recorded when its gate read it.
///
/// Both grounding rewrites — `refute_full_assert_obligations`' intraprocedural
/// discharge and [`ground_panic_freedom_catchall`] — fire only after "every
/// OTHER row reads `Proved`", and both run before any proof authority exists,
/// so that gate reads LABELS. The kernel certificate `certify_all` later mints
/// for the grounded formula re-checks the residual disjunction only; the
/// disjunction is the faithful residual of whole-function panic-freedom only
/// while those sibling rows really are discharged, and — for the refute lane —
/// only together with what its call gate assumed about the body's calls. This
/// record lets [`cap_grounded_panic_freedom_authorities`] grade the grounded
/// row by what those premises END the authority phase with, instead of by
/// what they read when the rewrite ran.
#[derive(Debug, Clone, PartialEq, Eq)]
struct GroundedCatchallPremises {
    /// The grounded catch-all row, frozen AFTER its formula rewrite — the exact
    /// identity the `KernelCertified` token this record grades is sealed to.
    row: ExactResultRowIdentity,
    /// Every sibling whose `Proved` label the gate consumed, with its exact
    /// identity at gate time. `None` is a row with no canonical identity:
    /// unverifiable, so it floors the grounding like a premise without
    /// authority.
    premises: Vec<(usize, Option<ExactResultRowIdentity>)>,
    /// What the grounding assumed about the panic sources of the body that are
    /// neither a sibling row nor a disjunct of the grounded formula (see
    /// [`GroundedCallPremise`]). The sibling rewrite assumes nothing here: it
    /// declines unless every source is a sibling row.
    calls: GroundedCallPremise,
}

impl GroundedCatchallPremises {
    /// Record the premises of a grounding of `row`: every row the gate read
    /// except `excluded` (the catch-all rows the gate itself exempted), plus
    /// what the grounding assumed about the body's calls.
    fn record(
        row: ExactResultRowIdentity,
        results: &[(VerificationCondition, VerificationResult)],
        excluded: impl Fn(usize) -> bool,
        calls: GroundedCallPremise,
    ) -> Self {
        let premises = results
            .iter()
            .enumerate()
            .filter(|(index, _)| *index != row.index && !excluded(*index))
            .map(|(index, (vc, _))| (index, exact_result_row_identity(index, vc)))
            .collect();
        Self { row, premises, calls }
    }
}

/// Trust (grounded catch-all premise floor, 2026-09-24): what a refute-lane
/// grounding assumed about the panic sources of its body that are neither a
/// sibling row nor an `assert!`/`panic!` failure block whose feasibility
/// formula is a disjunct of the grounded formula.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GroundedCallPremise {
    /// There is no such source.
    Absent,
    /// The lane's call gate (`all_calls_discharge_panic_free`) discharged at
    /// least one call (`Terminator::Call` or `Terminator::TailCall`, as
    /// `extracted_call_sites` enumerates them) from a Session registry or an
    /// audited total-callee recognizer. That callee's panic-freedom is a fact about
    /// ANOTHER body, a compiler-composed closure the kernel never saw, so the
    /// grounded row is `Trusted` at best — the grade
    /// `InterproceduralCalleeClosure` reports for the same premise.
    GateDischarged,
    /// The body carries an opaque terminator that runs code (an unresolved
    /// call, inline assembly, an assert the extractor could not model), or a
    /// terminator variant `extracted_call_sites` has never classified. The gate
    /// never examined these, and no lane discharged their panic-freedom: a
    /// premise with no authority at all, which leaves the grounded row none.
    /// (Trust, NEW-TAILCALL: a tail call was here too while the gate matched
    /// `Terminator::Call` alone; the gate now examines it with the same arms as
    /// an ordinary call, so it is `GateDischarged` like one.)
    Unexamined,
}

/// Trust (grounded catch-all premise floor, 2026-09-24): the
/// [`GroundedCallPremise`] of a refute-lane grounding of `func`'s catch-all.
///
/// Mirrors the gate's own enumeration, by walking it: every call site
/// [`extracted_call_sites`] yields (`Terminator::Call` AND `Terminator::TailCall`)
/// is gate-discharged, less the refutation-target blocks the gate exempts when
/// (and only when) `panic_calls_proven_unreachable` holds — and a tail call is
/// never exempted, exactly as in [`all_calls_discharge_panic_free`]. An opaque
/// terminator lies outside that enumeration altogether — except rustc's
/// `UnwindTerminate` sink, which is the unwind target of a call or a drop and so
/// runs only while some OTHER panic is already unwinding — and so does a
/// terminator variant the enumerator has never classified.
///
/// Trust (NEW-TAILCALL): this matched `Terminator::TailCall` as `Unexamined`
/// while the gate matched `Terminator::Call` alone. The gate now decides a tail
/// call by the same arms as an ordinary call, so the premise it grounded on is
/// the same `GateDischarged` one.
fn grounded_call_premise(
    func: &trust_types::VerifiableFunction,
    panic_calls_proven_unreachable: bool,
) -> GroundedCallPremise {
    let Ok(sites) = extracted_call_sites(func) else {
        return GroundedCallPremise::Unexamined;
    };
    let runs_unexamined_code = func.body.blocks.iter().any(|block| {
        matches!(
            &block.terminator,
            trust_types::Terminator::Opaque { kind, .. } if !is_unwind_terminate_sink(kind)
        )
    });
    if runs_unexamined_code {
        return GroundedCallPremise::Unexamined;
    }
    let gate_discharged = sites.iter().any(|site| {
        site.tail
            || !(panic_calls_proven_unreachable
                && trust_vcgen::is_assert_refutation_target_block(site.block))
    });
    if gate_discharged { GroundedCallPremise::GateDischarged } else { GroundedCallPremise::Absent }
}

/// Trust (grounded catch-all premise floor): rustc's `UnwindTerminate`, as
/// `trust-mir-extract` spells the opaque kind (`UnwindTerminate::{reason:?}`).
/// A change of spelling makes this false, which counts the sink as a source —
/// the fail-closed direction.
fn is_unwind_terminate_sink(opaque_kind: &str) -> bool {
    opaque_kind.starts_with("UnwindTerminate::")
}

/// Trust (grounded catch-all premise floor, 2026-09-24): whether every panic
/// source that the whole-function catch-all of `func` aggregates also carries a
/// per-site row of its own — the precondition for
/// [`ground_panic_freedom_catchall`]'s disjunction of SIBLING formulas to stand
/// for the catch-all's claim at all.
///
/// The bridge mints the aggregate only for panic sources that no per-site
/// obligation covers (`trust-ir-bridge` `lower.rs`: a diverging panic
/// `Terminator::Call`, a resolved call into a bundled body, an assumption
/// marker — never a `Terminator::Assert`, whose overflow/bounds/div row is
/// per-site). Of those, vcgen gives a per-site row (`v2_build_terminator_vc`)
/// to the `unreachable!()` family, the `assert!`-family panic entrypoints and
/// the exact outlined default-message family, which
/// `trust_types::terminator_obligations` classifies. Every other call — a
/// legacy bare `core::panicking::panic` without a sentinel message, an
/// `unwrap` failure path, a callee whose panic-freedom is a registry or
/// recognizer fact, a tail call, an opaque terminator that runs code — and a
/// coroutine resume sentinel (an `Assert` vcgen deliberately leaves without a
/// row) is a panic source that only the lane which proved the opaque catch-all
/// ever looked at. A kernel certificate over the siblings is silent about it,
/// so grounding such a row could only ever overclaim. rustc's `UnwindTerminate`
/// sink is not a source: it runs only while another panic is unwinding.
///
/// For the shapes it does admit, this relies on vcgen minting the per-site row
/// for every reachable block (its path-guard walk skips dead scaffolding) —
/// the producer trust every per-site row already carries, not a new premise.
/// A `Terminator::Drop` is not a source here: the bridge gives non-trivial drop
/// glue a `PanicFreedom` row of its own (an unproved drop-glue assumption, or a
/// recorded discharge), which is a sibling the floor grades like any other.
fn every_catchall_panic_source_has_a_site_row(func: &trust_types::VerifiableFunction) -> bool {
    use trust_types::terminator_obligations as site;
    !trust_vcgen::body_has_coroutine_protocol_sentinel(func)
        && func.body.blocks.iter().all(|block| match &block.terminator {
            // Trust: match the same named families as the ordinary site-row mint
            // without `unreachable_terminator_span`'s predecessor walk, which is
            // then only asked about the remaining shapes it classifies alone
            // (`unreachable_display`, `hint::unreachable_unchecked`).
            trust_types::Terminator::Call { func: callee, args, .. } => {
                site::is_unreachable_sentinel_panic(callee, args)
                    || site::is_assertion_panic_call(callee)
                    || site::is_bare_default_msg_panic_call(callee)
                    || site::unreachable_terminator_span(func, block).is_some()
            }
            trust_types::Terminator::TailCall { .. } => false,
            trust_types::Terminator::Opaque { kind, .. } => is_unwind_terminate_sink(kind),
            _ => true,
        })
}

/// How one premise row ended the authority phase, weakest first, so the
/// minimum over a premise set is the grade the grounded row may report.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum GroundedPremiseGrade {
    /// No sealed authority, no longer `Proved`, or no longer the row the gate
    /// read.
    Unproved,
    Trusted,
    Certified,
}

/// The grade of premise row `index` and whether its proof is an UNCONDITIONAL
/// static proof, or `None` when the row is exempt from the floor. `frozen` is
/// the identity the gate read, which the current row must still carry.
///
/// A premise is graded by what it will REPORT, not by its token alone: the
/// human line reads the authority through the vacuity gate
/// (`apply_vacuity_gate_with_authority`), which turns a `Proved` row whose
/// violation formula is constant-false into `Unknown` under most authorities,
/// and the wire drops a live authority whose run seal does not validate
/// against the final run (`live_authority_run_is_valid`). Either leaves the
/// premise unproved on that surface, and so leaves the grounded row nothing to
/// stand on there.
///
/// Two rows are exempt, for the reasons the panic-freedom registry
/// (`results_establish_unconditional_panic_freedom`) already gives:
///   * a functional `Postcondition` is not a panic site — an open or refuted
///     `ensures` clause does not make a panic reachable, and the registry and
///     the interprocedural discharge exempt exactly this kind;
///   * the definition-entry `requires` marker is the contract hypothesis every
///     sibling's own certificate in the same body rests on. It is conditional
///     bookkeeping, and that conditionality stays with ITS row (the registry
///     refuses any function carrying one).
fn grounded_premise_grade(
    index: usize,
    frozen: Option<&ExactResultRowIdentity>,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
    live_run_validation: Option<&LiveAuthorityRunValidationCache>,
) -> Option<(GroundedPremiseGrade, bool)> {
    const UNPROVED: Option<(GroundedPremiseGrade, bool)> =
        Some((GroundedPremiseGrade::Unproved, false));
    let Some((vc, result)) = results.get(index) else { return UNPROVED };
    let Some(frozen) = frozen else { return UNPROVED };
    if exact_result_row_identity(index, vc).as_ref() != Some(frozen) {
        return UNPROVED;
    }
    if matches!(vc.kind, VcKind::Postcondition) {
        return None;
    }
    if !matches!(result, VerificationResult::Proved { .. }) {
        return UNPROVED;
    }
    let binding = result_bindings.get(index).and_then(Option::as_ref);
    let Some(authority) = proof_authorities.get(index).and_then(Option::as_ref) else {
        return UNPROVED;
    };
    // Trust (TINV step 10.4, review fold-in 1): a premise whose proof rests on a
    // type-invariant fact — a `TypeInvariantComposed` authority, or a formula carrying a
    // TINV tag at all — grades UNPROVED, which strips the grounded catch-all's token:
    // `GroundedPanicFreedomDerivation` has no way to disclose the TINV premise it would
    // inherit (the refute lane grounds over untagged candidates while reading such a
    // sibling's `Proved` label).
    if matches!(authority, ResultProofAuthority::TypeInvariantComposed { .. })
        || !matches!(vc.type_invariant_tags(), trust_types::TinvTagScan::None)
    {
        return UNPROVED;
    }
    if authority.is_definition_entry_assumption_for(index, vc, binding) {
        return None;
    }
    if !live_authority_run_is_valid(authority, live_run_validation) {
        return UNPROVED;
    }
    let reported =
        apply_vacuity_gate_with_authority(index, vc, result.clone(), binding, Some(authority));
    if !reported.is_proved() {
        return UNPROVED;
    }
    let unconditional = authority.is_unconditional_static_proof_for(index, vc, &reported, binding);
    match trust_disposition_for_authority(Some(authority), index, vc, &reported, binding) {
        Some((TrustStatus::Certified, _)) => Some((GroundedPremiseGrade::Certified, unconditional)),
        Some((TrustStatus::Trusted, _)) => Some((GroundedPremiseGrade::Trusted, unconditional)),
        _ => UNPROVED,
    }
}

/// Trust (2026-10-08, argument premise; R1's rule, graded per row since 2026-10-17):
/// replace the `KernelCertified` token of every row whose VC the premise may have
/// shaped with `ArgumentPremiseKernelDischarge` (sealed to the same row, `Trusted`).
///
/// A token stays `KernelCertified` only when the exact VC it certified (the
/// `canonical_vc` it is sealed to) is one the body's PREMISE-FREE generation also
/// produces (`premise_free`, see `argument_premise::PremiseFreeRows`) and its row is
/// not a grounded catch-all (`groundings`): a grounded residual is faithful only
/// under its siblings' verdicts, which may rest on the premise. Every other token
/// is demoted, and so is every token when `premise_free` is unavailable. An E9
/// `EnsuresCitationDischarge` (a `Certified` class the premise also undercuts;
/// unreachable for these bodies today, since E6 refuses `Ty::Ref` locals) is
/// stripped, and a grounded derivation is re-graded conditional, for the whole
/// body as before. Returns `(kept, demoted)` kernel-token counts.
fn demote_argument_premise_authorities(
    proof_authorities: &mut [Option<ResultProofAuthority>],
    premise: &'static str,
    premise_free: &argument_premise::PremiseFreeRows,
    groundings: &[GroundedCatchallPremises],
) -> (usize, usize) {
    let (mut kept, mut demoted) = (0, 0);
    for slot in proof_authorities.iter_mut() {
        *slot = match slot.take() {
            Some(ResultProofAuthority::KernelCertified { row, evidence, reference, replay_audit }) => {
                if !groundings.iter().any(|grounding| grounding.row == row)
                    && premise_free.produces(&row.canonical_vc)
                {
                    kept += 1;
                    Some(ResultProofAuthority::KernelCertified {
                        row, evidence, reference, replay_audit,
                    })
                } else {
                    demoted += 1;
                    Some(ResultProofAuthority::ArgumentPremiseKernelDischarge {
                        row,
                        evidence,
                        premise,
                    })
                }
            }
            Some(ResultProofAuthority::EnsuresCitationDischarge { .. }) => None,
            // Review round 82: a grounded derivation graded before this pass
            // stands on premises of this same body, so it is conditional now.
            Some(ResultProofAuthority::GroundedPanicFreedomDerivation { row, .. }) => {
                Some(ResultProofAuthority::GroundedPanicFreedomDerivation {
                    row,
                    unconditional: false,
                })
            }
            other => other,
        };
    }
    (kept, demoted)
}

/// Trust (grounded catch-all premise floor, 2026-09-24): grade every grounded
/// whole-function panic-freedom catch-all by the WEAKEST premise its kernel
/// certificate stands on — never higher.
///
/// Runs LAST in the authority phase, after every lane (kernel, S1, native,
/// source-clause, R1, E9, callee-closure) has claimed its rows, because only
/// then is "this premise has no authority" observable rather than inferred —
/// the discipline `install_interprocedural_callee_closure_authorities` already
/// applies to the other catch-all discharge. Reads the recorded premise
/// identities, the FINAL authorities and the final run `full_verification`
/// the transport validates live authorities against; no label is consulted.
/// Only the `KernelCertified` token sealed to the grounded row (or a
/// derivation this pass minted in an earlier round) is touched: any other
/// authority on the row was minted, and gated, by its own lane.
///
///   * every premise `Certified` and an unconditional static proof (or
///     exempt), and no call premise ([`GroundedCallPremise::Absent`]): the
///     kernel token stays;
///   * weakest premise `Trusted`, a conditional premise, or a call the refute
///     lane's gate discharged ([`GroundedCallPremise::GateDischarged`]): the
///     token becomes `GroundedPanicFreedomDerivation` (`Trusted`/`Deductive`),
///     conditional exactly when some premise was not an unconditional static
///     proof;
///   * weakest premise unproved (no authority, refuted or no longer `Proved`,
///     no longer the row the gate read, or downgraded on the way to the
///     report — see [`grounded_premise_grade`]), a tail call or opaque
///     terminator the gate never examined
///     ([`GroundedCallPremise::Unexamined`]), or ANY panic-site row of the
///     function refuted — including one appended after the gate ran (a
///     call-site L0 replay or BMC refutation), which the gate never read but
///     which contradicts the catch-all's claim outright: the authority is
///     removed. The `Proved` label stays, and like every other label without a
///     sealed authority it is advisory only — the row reports exactly what its
///     unproved premise reports.
///
/// Iterates to a fixpoint, since one grounded catch-all can be another's
/// premise. Every step strictly lowers one row's grade, so it converges within
/// the round bound; a carrier skew, or a round bound reached anyway, strips
/// every grounded token instead (fail-closed). Returns how many grounded rows
/// ended lower than their kernel token.
fn cap_grounded_panic_freedom_authorities(
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &mut [Option<ResultProofAuthority>],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    groundings: &[GroundedCatchallPremises],
) -> usize {
    let is_grounded_token = |authority: Option<&ResultProofAuthority>,
                             grounding: &GroundedCatchallPremises| {
        matches!(
            authority,
            Some(
                ResultProofAuthority::KernelCertified { row, .. }
                | ResultProofAuthority::GroundedPanicFreedomDerivation { row, .. }
            ) if row == &grounding.row
        )
    };
    let strip_every_grounded_token = |proof_authorities: &mut [Option<ResultProofAuthority>]| {
        // Ordered sets: the count is all that leaves this pass, and an ordered
        // set keeps it free of hash-order iteration.
        let mut stripped: std::collections::BTreeSet<usize> = std::collections::BTreeSet::new();
        for grounding in groundings {
            if let Some(slot) = proof_authorities.get_mut(grounding.row.index)
                && is_grounded_token(slot.as_ref(), grounding)
            {
                *slot = None;
                stripped.insert(grounding.row.index);
            }
        }
        stripped
    };
    if results.len() != proof_authorities.len()
        || (!result_bindings.is_empty() && results.len() != result_bindings.len())
    {
        return strip_every_grounded_token(proof_authorities).len();
    }
    // Built once: this pass never mints, moves or removes a live authority, so
    // the run-seal verdicts it keys on cannot go stale inside the fixpoint.
    let live_run_validation = full_verification
        .map(|run| build_live_authority_run_validation_cache(proof_authorities, run));
    let debug = env_flag_enabled("TRUST_ASSERT_DEBUG");
    let mut lowered: std::collections::BTreeSet<usize> = std::collections::BTreeSet::new();
    // A row moves Certified -> Trusted (unconditional) -> Trusted (conditional)
    // -> none at most, one step per changed round at worst.
    let mut converged = false;
    for round in 0..=3 * groundings.len() {
        let mut changed = false;
        for grounding in groundings {
            let index = grounding.row.index;
            let Some((vc, _)) = results.get(index) else { continue };
            if exact_result_row_identity(index, vc).as_ref() != Some(&grounding.row)
                || !is_grounded_token(proof_authorities[index].as_ref(), grounding)
            {
                continue;
            }
            // A call the gate discharged is a compiler-composed closure over
            // other bodies' proofs: `Trusted` at best, whatever the siblings. A
            // terminator the gate never examined is no premise at all.
            let mut floor = match grounding.calls {
                GroundedCallPremise::Absent => GroundedPremiseGrade::Certified,
                GroundedCallPremise::GateDischarged => GroundedPremiseGrade::Trusted,
                GroundedCallPremise::Unexamined => GroundedPremiseGrade::Unproved,
            };
            // Monotone across rounds: a derivation this pass already graded
            // conditional never becomes unconditional again.
            let mut unconditional = !matches!(
                proof_authorities[index],
                Some(ResultProofAuthority::GroundedPanicFreedomDerivation {
                    unconditional: false,
                    ..
                })
            );
            let mut defeating: Option<usize> = None;
            for (premise, frozen) in &grounding.premises {
                let Some((grade, premise_unconditional)) = grounded_premise_grade(
                    *premise,
                    frozen.as_ref(),
                    results,
                    result_bindings,
                    proof_authorities,
                    live_run_validation.as_ref(),
                ) else {
                    continue;
                };
                if grade < floor || (unconditional && !premise_unconditional) {
                    defeating = Some(*premise);
                }
                floor = floor.min(grade);
                unconditional &= premise_unconditional;
            }
            if let Some((refuted, _)) =
                results.iter().enumerate().find(|(other, (other_vc, other_result))| {
                    *other != index
                        && matches!(other_result, VerificationResult::Failed { .. })
                        && !matches!(other_vc.kind, VcKind::Postcondition)
                })
            {
                defeating = Some(refuted);
                floor = GroundedPremiseGrade::Unproved;
            }
            let lowered_to = match floor {
                // The kernel token is kept only where every premise is itself a
                // `Certified`, unconditional static proof and no call rests on
                // the gate.
                GroundedPremiseGrade::Certified if unconditional => {
                    if debug && round == 0 {
                        eprintln!(
                            "[ASSERT_CAP] whole-function panic-freedom @ {:?} keeps Certified \
                             ({} premise row(s))",
                            vc.location,
                            grounding.premises.len(),
                        );
                    }
                    continue;
                }
                GroundedPremiseGrade::Certified | GroundedPremiseGrade::Trusted => {
                    Some(ResultProofAuthority::GroundedPanicFreedomDerivation {
                        row: grounding.row.clone(),
                        unconditional,
                    })
                }
                GroundedPremiseGrade::Unproved => None,
            };
            let unchanged = match (&proof_authorities[index], &lowered_to) {
                (
                    Some(ResultProofAuthority::GroundedPanicFreedomDerivation {
                        unconditional: was,
                        ..
                    }),
                    Some(ResultProofAuthority::GroundedPanicFreedomDerivation {
                        unconditional: now,
                        ..
                    }),
                ) => was == now,
                _ => false,
            };
            if unchanged {
                continue;
            }
            if debug {
                let premise = defeating.and_then(|premise| results.get(premise));
                eprintln!(
                    "[ASSERT_CAP] whole-function panic-freedom @ {:?} graded {floor:?} \
                     (unconditional={unconditional}, calls={:?}) by its weakest premise {:?} \
                     @ {:?}",
                    vc.location,
                    grounding.calls,
                    premise.map(|(premise_vc, _)| &premise_vc.kind),
                    premise.map(|(premise_vc, _)| &premise_vc.location),
                );
            }
            proof_authorities[index] = lowered_to;
            lowered.insert(index);
            changed = true;
        }
        if !changed {
            converged = true;
            break;
        }
    }
    if !converged {
        lowered.extend(strip_every_grounded_token(proof_authorities));
    }
    lowered.len()
}

/// Whether `vc` is an `Assertion` whose message starts with `panic freedom`.
///
/// Deliberately the BROAD prefix, shared by every panic-freedom catch-all
/// predicate. It is NOT `trust_types::assumption::PANIC_FREEDOM_AGGREGATE_DESCRIPTION_PREFIX`:
/// that full aggregate sentence exists to EXCLUDE enriched gap rows, and other
/// `panic freedom: …` rows (e.g. the `Termination::report` row) begin with this
/// prefix too, so substituting it would narrow every caller.
fn is_panic_freedom_assertion_vc(vc: &VerificationCondition) -> bool {
    matches!(&vc.kind, VcKind::Assertion { message } if message.starts_with("panic freedom"))
}

/// Ground a Proved-but-uncertified whole-function panic-freedom CATCH-ALL whose formula
/// is still the opaque `panic_reachable:` symbolic `Var` (i.e. NOT already grounded by
/// the assert-refute discharge). When EVERY other obligation is definitively `Proved`,
/// the function is panic-free and the catch-all's residual violation is exactly the
/// disjunction of those other obligations' violation formulas — each a modeled panic
/// site's reachability condition (calls, if any, were required proven-panic-free for
/// the catch-all to be Proved at all, so they contribute nothing). Re-point the
/// catch-all's formula at that OR ONLY after its exact replacement earns a real
/// kernel certificate — e.g. `let k = n % 4; if k >=
/// 4 { unreachable!() }`, whose dead trap certifies via the Euclidean range, lifts the
/// catch-all with it. SOUND + fail-closed: identical basis to the assert-refute
/// discharge (a reachable site's violation is SAT, so the OR is SAT and `certify_vc`
/// returns None); never upgrades a non-`Proved` verdict. Skips when the formula was
/// already grounded (assert path) so the two never fight.
/// An unsupported replacement or exhausted budget keeps the original row and
/// its aligned native binding unchanged; the ordinary exact native-authority
/// checks must still validate that original proof independently. In particular,
/// a correct native proof is not lost merely because an optional certificate
/// upgrade does not support the replacement's Boolean shape.
///
/// ---------------------------------------------------------------------------
/// FALSE PROOF #12 AUDIT — sibling site. VERDICT: SOUND TODAY, BUT ONLY BY AN
/// INVARIANT THAT IS NOT LOCALLY CHECKABLE. Stated here so it stops being
/// implicit.
///
/// The parenthetical "calls, if any, were required proven-panic-free for the
/// catch-all to be Proved at all" is a load-bearing assumption about OTHER
/// code — and it is the same sentence #11/#12 falsified for the SUBSUMPTION
/// lane. The empty-`others` case is already refused here (`0 => return None`),
/// so the VACUOUS half of #12 cannot occur; and this function never flips a
/// verdict, it only re-points an ALREADY-`Proved` catch-all's formula so
/// `certify_all` can kernel-certify it.
///
/// The residual exposure is ASSURANCE, not verdict: that kernel certificate is
/// exactly what the gate lane's publication-evidence check keys on
/// (`targo-trust/src/types.rs`, "compiler transport claimed a favorable outcome
/// without attachable native or clean-kernel proof evidence; downgraded before
/// publication"), so grounding an unsound `Proved` would promote a
/// gate-INVISIBLE false proof into a gate-VISIBLE `[VERIFIED]`. It is safe only
/// because EVERY producer of a `Proved` symbolic catch-all is independently
/// call-gated: refute path 1 (#11 (D)), refute path 2, the interprocedural
/// `all_calls_discharge_panic_free` seam, and the native CHC (which carries
/// the bundled callee's error rules through `try_direct_call_summary` /
/// `UnsupportedDirectCallSummary`).
/// `apply_whole_function_panic_freedom_subsumption` cannot launder into this
/// path: it runs strictly AFTER this call.
///
/// ANY NEW PRODUCER OF A `Proved` PANIC-FREEDOM CATCH-ALL MUST APPLY
/// `all_calls_discharge_panic_free` BEFORE minting — or this function must grow
/// the gate itself. Deliberately NOT added in the #12 commit: the grounding is
/// load-bearing for most proved functions in the corpus, and a call gate here
/// is a completeness change that must be MEASURED, not guessed.
///
/// ---------------------------------------------------------------------------
/// Trust (grounded catch-all premise floor, 2026-09-24) — the ASSURANCE half,
/// closed. The certificate re-checks the disjunction of the SIBLINGS'
/// formulas, and that disjunction stands for the catch-all only where every
/// panic source the catch-all aggregates is itself a sibling row. The bridge
/// mints the aggregate for exactly the sources no per-site row covers, so for
/// any other source (a 2021 `panic!()`'s bare `core::panicking::panic`, a
/// registry-discharged callee) the certificate checked a formula disjoint from
/// the claim, and only the lane that proved the opaque row ever looked at
/// that source. Measured (`tests/ui/trust/grounded_catchall_inherits_weakest_premise.rs`,
/// revision `opaque`): `let k = five(); if k != 5 { panic!() }` beside
/// `(n & 0x7f) + 1` reported the catch-all `clean-kernel/Certified` over the
/// overflow row's formula alone, while the panic block's refutation formula
/// was ungrounded and the call gate refused `core::panicking::panic`. The
/// caller therefore computes
/// `every_panic_source_has_a_site_row`
/// ([`every_catchall_panic_source_has_a_site_row`]) and this function
/// declines otherwise, which leaves the row, its formula and its native
/// binding untouched for the authority its own lane can seal
/// (`FreshWholeFunctionChcPdr`, `InterproceduralCalleeClosure`). A grounding
/// that does proceed records its siblings in
/// [`CertifiedPanicFreedomGrounding::premises`], and
/// [`cap_grounded_panic_freedom_authorities`] grades the grounded row by the
/// weakest of them.
fn ground_panic_freedom_catchall(
    results: &mut [(VerificationCondition, VerificationResult)],
    mut result_bindings: Option<&mut [Option<ResultObligationBinding>]>,
    deadline: Option<std::time::Instant>,
    every_panic_source_has_a_site_row: bool,
) -> Option<CertifiedPanicFreedomGrounding> {
    let is_symbolic = |vc: &VerificationCondition| matches!(&vc.formula, trust_types::Formula::Var(n, _) if n.starts_with("panic_reachable"));
    let Some(ci) = results.iter().position(|(vc, r)| {
        is_panic_freedom_assertion_vc(vc)
            && matches!(r, VerificationResult::Proved { .. })
            && is_symbolic(vc)
    }) else {
        return None;
    };
    // A declined upgrade must not preserve a stale/swapped capability. Check
    // this before the deadline or candidate-certificate early returns, just as
    // the controlled rewrite checks it before an equal-formula no-op.
    if let Some(bindings) = result_bindings.as_deref_mut() {
        let binding = bindings.get_mut(ci)?;
        if binding.as_ref().is_some_and(|binding| !binding.matches_row(ci, &results[ci].0)) {
            *binding = None;
            return None;
        }
    }
    // Every OTHER obligation must be definitively Proved (the function is panic-free).
    if !results
        .iter()
        .enumerate()
        .all(|(i, (_, r))| i == ci || matches!(r, VerificationResult::Proved { .. }))
    {
        return None;
    }
    // Trust (grounded catch-all premise floor): a certificate over the
    // siblings cannot stand for a panic source that has no sibling row, so
    // such a row is never re-pointed (see the doc above).
    if !every_panic_source_has_a_site_row {
        if env_flag_enabled("TRUST_ASSERT_DEBUG") {
            eprintln!(
                "[ASSERT_GROUND] declined @ {:?}: a panic source of this body has no per-site \
                 row, so the siblings' disjunction cannot stand for the catch-all",
                results[ci].0.location
            );
        }
        return None;
    }
    if deadline.is_some_and(|at| std::time::Instant::now() >= at) {
        return None;
    }
    let others: Vec<trust_types::Formula> = results
        .iter()
        .enumerate()
        .filter(|(i, _)| *i != ci)
        .map(|(_, (vc, _))| vc.formula.clone())
        .collect();
    let grounded = match others.len() {
        0 => return None,
        1 => others.into_iter().next().unwrap(),
        _ => trust_types::Formula::Or(others),
    };
    let mut candidate = results[ci].0.clone();
    candidate.formula = grounded.clone();
    let row = exact_result_row_identity(ci, &candidate)?;
    let evidence = trust_certify::certify_vc(&candidate)?;
    if deadline.is_some_and(|at| std::time::Instant::now() >= at) {
        return None;
    }
    // Grounding proceeds (see the refute lane's twin): the CleanCic upgrade of
    // the catch-all is load-bearing for most proved functions. Record the
    // retired binding so the post-run native proof-authority validation judges
    // this obligation on its GROUNDED row instead of a binding the compiler
    // deliberately revoked.
    let grounded_id = result_bindings
        .as_deref()
        .and_then(|bindings| bindings.get(ci).and_then(Option::as_ref))
        .filter(|binding| binding.matches_row(ci, &results[ci].0))
        .map(|binding| binding.public_obligation_id.clone());
    // Trust (grounded catch-all premise floor): the gate above read every
    // sibling's `Proved` LABEL; the certificate re-checks the disjunction of
    // their formulas, which says nothing about a sibling whose formula is a
    // placeholder or whose label no authority backs. Record the rows it stood
    // on so the authority phase grades this row by them. No call premise:
    // every call here is a sited panic entrypoint (checked above).
    let premises = GroundedCatchallPremises::record(
        row.clone(),
        results,
        |_| false,
        GroundedCallPremise::Absent,
    );
    rewrite_result_formula_revoking_binding(ci, results, result_bindings, grounded).then_some(
        CertifiedPanicFreedomGrounding {
            public_obligation_id: grounded_id,
            row,
            evidence,
            premises,
        },
    )
}

///
/// Returns how many obligations had their structural search CUT SHORT by the
/// deterministic case-split work bound. Reporting is the caller's job so this pass
/// stays pure and its tests need no `Session`; see the production call site, which
/// turns a non-zero count into a note.
#[must_use]
fn promote_structurally_dead_unreachable(
    results: &mut [(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
) -> usize {
    // Trust (verifier-perf, 2026-08-31): obligations whose structural search hit its
    // deterministic work bound instead of completing. This used to be indistinguishable
    // from "searched and found nothing" — both were a bare `false` — so a fan-out
    // blowup in the case-split degraded with NOTHING SAID, which is how it reached a
    // production stack sample before anyone knew it was there. Counted and reported.
    let mut search_bound_reached = 0usize;
    for (vc, result) in results.iter_mut() {
        if deadline.is_some_and(|at| std::time::Instant::now() >= at) {
            break;
        }
        // L0 safety kinds whose violation can reduce to a trivial propositional /
        // constant-arithmetic contradiction ay cannot discharge: a dead exhaustive
        // `Unreachable` trap (`disc ∈ {cases} ∧ disc ∉ {cases}`); a guarded
        // division/modulo (`b ≠ 0 ∧ b = 0`, possibly via a bool-temp biconditional);
        // or a bounded-reduction `ArithmeticOverflow` whose per-add check
        // `Or([Lt(Add,0), Gt(Add,MAX)])` is refuted by the post-add sum bound
        // `Add ≤ K·per_max ≤ MAX` (ay leaves the `<<k` Int/BV round-trip Unknown).
        // INDEX/SLICE bounds are included for the SAME structural reason: the violation
        // `idx ≥ len` is refuted by an emitted upper-bound fact `idx ≤ c < len`
        // (incompatible constant bounds — e.g. clamp-through-cast `(j as usize) ≤ 7` vs the
        // `≥ 8` violation on a len-8 array). ay cannot strictly reconstruct that trivial
        // linear contradiction. SOUND/self-limiting: promotion fires ONLY when the violation
        // formula is propositionally UNSAT (the out-of-bounds case is impossible given the
        // facts) — a genuinely OOB access has compatible bounds and stays Failed, and a
        // withheld/stale fact leaves no upper bound so nothing is promoted.
        if !matches!(
            vc.kind,
            VcKind::Unreachable
                | VcKind::DivisionByZero
                | VcKind::RemainderByZero
                | VcKind::ArithmeticOverflow { .. }
                | VcKind::IndexOutOfBounds
                | VcKind::SliceBoundsCheck
        ) {
            continue;
        }
        // Only upgrade an inconclusive verdict; never override Proved/Failed.
        let time_ms = match &*result {
            VerificationResult::Unknown { time_ms, .. } => *time_ms,
            VerificationResult::Timeout { timeout_ms, .. } => *timeout_ms,
            _ => continue,
        };
        match trust_router::constant_folder::formula_is_propositionally_unsat_reported(&vc.formula)
        {
            trust_router::constant_folder::PropUnsatVerdict::Unsat => {}
            // The search COMPLETED and there is no structural contradiction. A real
            // negative about this formula: leave the solver's verdict alone.
            trust_router::constant_folder::PropUnsatVerdict::NotProven => continue,
            // The search was CUT SHORT by the work bound. Not a statement about the
            // formula — the shortcut was declined undecided, so the obligation keeps
            // its solver verdict exactly as in the `NotProven` arm, but the decline is
            // recorded instead of vanishing.
            trust_router::constant_folder::PropUnsatVerdict::SearchBoundReached => {
                search_bound_reached += 1;
                continue;
            }
        }
        *result = VerificationResult::Proved {
            solver: "structural-propositional-unsat".into(),
            time_ms,
            // Sound-by-construction: propositional resolution over opaque atoms is
            // trivially valid (no theory, no solver trust). Mirrors the assurance
            // the constant-folder backend gives its own trivial-UNSAT proofs.
            strength: ProofStrength::smt_unsat(),
            proof_certificate: None,
            solver_warnings: None,
            native_proof_envelope: None,
        };
    }
    search_bound_reached
}

/// Trust (P0 OOM native-route gap): refute every `UnboundedAllocation` obligation
/// whose violation atom is FORCED — the element count provably folds to a constant
/// `>= UNBOUNDED_ALLOC_ELEM_CEILING` (`alloc_over_ceiling_forced`). On the native
/// native path the trust-mc typed-CHC encoding of the bulk-allocation obligation
/// reported it `Proved` SAFE (`vec![None; 1 << 28]` came back "3 proved, exit 0"),
/// while the structural VC route correctly `Failed` it and `escalate_refuted_l0_safety_
/// counterexamples` aborted. This lock-steps the routes: the SAME structural
/// decision the escalation makes (`alloc_over_ceiling_forced`) is enforced
/// here regardless of the native verdict, so the refutation is not lost to a native
/// CHC encoding that cannot model the budget ceiling.
///
/// SOUNDNESS: `alloc_over_ceiling_forced` returns true ONLY when the count is a
/// GROUND constant `>= ceiling` (a provably over-budget allocation), so overriding
/// it to `Failed` can never reject valid Rust — a symbolic or provably-bounded
/// count never folds and is left untouched (it stays whatever the solver decided).
/// A bulk allocation that always exceeds the host budget is genuinely unsafe; a
/// `Proved`-safe verdict for it is the false proof being corrected.
fn refute_forced_unbounded_allocations(
    results: &mut [(VerificationCondition, VerificationResult)],
) {
    for (vc, result) in results.iter_mut() {
        if !matches!(vc.kind, VcKind::UnboundedAllocation { .. }) {
            continue;
        }
        // Already a refutation — nothing to override.
        if matches!(result, VerificationResult::Failed { .. }) {
            continue;
        }
        if !trust_router::alloc_over_ceiling_forced(&vc.formula) {
            continue;
        }
        let time_ms = match &*result {
            VerificationResult::Proved { time_ms, .. }
            | VerificationResult::Unknown { time_ms, .. } => *time_ms,
            VerificationResult::Timeout { timeout_ms, .. } => *timeout_ms,
            _ => 0,
        };
        *result = VerificationResult::Failed {
            solver: structural_refutation_solver_label(
                "structural-forced-unbounded-allocation",
                result,
            ),
            time_ms,
            counterexample: None,
        };
    }
}

/// Whether the tracked MEMORY-SAFE policy may turn safe-code capability gaps
/// into explicit assumption rows. This is deliberately flag-only: reading an
/// ambient environment variable during MIR transformation would bypass option
/// dependency tracking and make incremental results depend on hidden process
/// state. Callers combine this with `function_uses_unsafe`, so any function
/// containing a source or inlined unsafe operation remains strict.
fn memory_safe_mode(tcx: TyCtxt<'_>) -> bool {
    tcx.sess.opts.unstable_opts.trust_policy.is_memory_safe()
}

/// Hardened boundary obligations ride the named verification profile and
/// nothing else. A second boolean carrier let the compiler's default and
/// Targo's default disagree about which obligation set a compile produces;
/// with one carrier the answer is on the command line either way.
///
/// One carrier also means one failure mode, and it is this: because the
/// profile is the ONLY thing this flag selects (measured: `-Ztrust-verify-profile`
/// has exactly one consumer in the compiler, this function), a value the
/// registry does not know verifies EXACTLY what passing no profile at all
/// verifies. A typo — `unix_hardend`, `unix_hardened_v2` — therefore used to
/// turn hardening off and report nothing, while the front end that supplied
/// the label went on announcing it and writing it into the proof record. So
/// an unregistered label is refused here, at the point the decision is made,
/// rather than answered `false`: a compile that asked for a profile and did
/// not get one must not produce a verdict. Requesting NO hardened obligations
/// stays exactly as it was — omit the flag (`targo trust --no-hardened` /
/// `[trust] hardened = false` do exactly that), which is an explicit choice a
/// typo cannot spell by accident.
fn hardened_verification_enabled(sess: &Session) -> bool {
    let Some(profile) = sess.opts.unstable_opts.trust_verify_profile.as_deref() else {
        return false;
    };
    if trust_vcgen::canonical_profile(profile).is_none() {
        sess.dcx().fatal(format!(
            "unregistered Trust verification profile `{profile}`: \
             -Ztrust-verify-profile selects the hardened obligation set and nothing else, so an \
             unregistered name generates exactly the obligations of no profile at all; \
             registered profiles are {} (`-` and `_` are the same separator, case-insensitive), \
             and omitting -Ztrust-verify-profile is how a compile asks for no hardened \
             obligations",
            trust_vcgen::known_hardened_profiles().join(", "),
        ));
    }
    trust_vcgen::profile_enables_hardened(Some(profile))
}

/// True if `did`'s SOURCE contains any unsafe — it is an `unsafe fn`, or its own HIR body has
/// an `unsafe { }` block. Rust GUARANTEES safe code is UB-free, and every unsafe operation in
/// compiling code MUST lexically sit in an `unsafe fn` or an `unsafe { }` block the HIR
/// records — so a FALSE result means `did` has no unsafe op at all. This is COMPLETE by
/// construction (it does not enumerate individual UB ops), unlike a MIR rvalue scan: vcgen
/// reuses PANIC-class VcKinds for UB intrinsics (`get_unchecked`,
/// `unchecked_{add,sub,mul,div,rem,shl,shr}`, `offset`, …) that `LowerIntrinsics` rewrites into
/// non-call rvalues before the verify pass, so no Call/BinOp allowlist can be provably
/// complete — but ALL of them require `unsafe`, so this single check excludes every one.
/// Nested bodies (closures) are separate `did`s with their own check, so the walk uses the
/// default `NestedFilter::None`. A non-local (no visible HIR) or body-less owner cannot be
/// confirmed safe and is treated conservatively as unsafe.
fn def_uses_unsafe_source<'tcx>(tcx: TyCtxt<'tcx>, did: DefId) -> bool {
    def_uses_unsafe_source_impl(tcx, did, false)
}

/// Trust (policy B, runtime-value println — 2026-09-13): the USER-only variant.
/// Identical to [`def_uses_unsafe_source`] except that a
/// `BlockCheckMode::UnsafeBlock(UnsafeSource::CompilerGenerated)` — the unsafe
/// block a DESUGARING synthesizes, never one the user wrote — does not count.
/// The single motivating instance: `format_args!` lowering wraps its call to the
/// foundational-TCB `core::fmt::Arguments::new` constructor in exactly such a
/// block (`rustc_ast_lowering::format`), so at any opt-level a `println!` with a
/// RUNTIME argument makes `main`'s own HIR "use unsafe" even though the user
/// wrote none. A user-authored `unsafe { … }` block is `UserProvided` and still
/// counts, and an `unsafe fn` still counts by its signature — so this narrows the
/// gate to genuine user unsafe intent, which is exactly what the std-print
/// tolerance must respect. Used ONLY by `function_uses_unsafe_outside_std`'s
/// own-body leg; every other caller keeps the conservative `false` mode.
fn def_uses_user_unsafe_source<'tcx>(tcx: TyCtxt<'tcx>, did: DefId) -> bool {
    def_uses_unsafe_source_impl(tcx, did, true)
}

fn def_uses_unsafe_source_impl<'tcx>(tcx: TyCtxt<'tcx>, did: DefId, user_only: bool) -> bool {
    use rustc_hir::def::DefKind;
    use rustc_hir::intravisit::{self, Visitor};
    // `unsafe fn` is itself an unsafe context (its ops may need no explicit block). Guard the
    // `fn_sig` query to genuine fns — it panics for closures/consts.
    if matches!(tcx.def_kind(did), DefKind::Fn | DefKind::AssocFn)
        && matches!(
            tcx.fn_sig(did).instantiate_identity().skip_binder().safety(),
            rustc_hir::Safety::Unsafe
        )
    {
        return true;
    }
    let Some(local) = did.as_local() else { return true };
    // Trust (I5): a Clean-origin def has no HIR body to walk, and needs none —
    // every emittable shape (projection / wrapping binop / composed tree) is
    // moves plus calls to safe, total, marker-authenticated core primitives;
    // `unsafe` is unrepresentable in the emission, so `false` is the honest
    // answer, not a concession. The conservative `true` would falsely poison
    // every caller's UB-free classification the moment the emitted body is
    // inlined. NINTH member of the synthetic-HIR family — reached through a
    // CALLER's inlined-scope scan once `cross_crate_inlinable` copies the
    // emitted body into it (measured under compiletest; the `hir_body_owned_by`
    // walk below `span_bug!`s on the synthetic owner).
    if crate::clean_origin_mir::is_clean_origin(tcx, local) {
        return false;
    }
    // Trust (2026-09-23): the by-move body rustc synthesizes for an async
    // closure called through `AsyncFnOnce` has no HIR either, and the walk below
    // ICEd on it (`crates/trust-thir-lower/src/generated_coroutine/fixtures/`,
    // pinned by `tests/ui/trust/async_closure_by_move_body_no_ice.rs`). It is a
    // by-move COPY of its parent coroutine's body, so the parent's source answers
    // exactly.
    if matches!(tcx.def_kind(did), DefKind::SyntheticCoroutineBody) {
        return def_uses_unsafe_source_impl(tcx, tcx.parent(did), user_only);
    }
    // Only fn/closure owners have a walkable HIR body; otherwise be conservative.
    if !tcx.hir_body_owner_kind(local).is_fn_or_closure() {
        return true;
    }
    struct UnsafeBlockFinder {
        found: bool,
        user_only: bool,
    }
    impl<'v> Visitor<'v> for UnsafeBlockFinder {
        fn visit_block(&mut self, b: &'v rustc_hir::Block<'v>) {
            if let rustc_hir::BlockCheckMode::UnsafeBlock(source) = b.rules {
                // In user-only mode a COMPILER-GENERATED unsafe block (a desugaring,
                // e.g. `format_args!`'s `Arguments::new` wrapper) does not count;
                // only a `UserProvided` block reflects user unsafe intent.
                if !self.user_only || matches!(source, rustc_hir::UnsafeSource::UserProvided) {
                    self.found = true;
                }
            }
            intravisit::walk_block(self, b);
        }
    }
    let mut finder = UnsafeBlockFinder { found: false, user_only };
    finder.visit_body(tcx.hir_body_owned_by(local));
    finder.found
}

/// True if this VERIFIED MIR body may contain an unsafe operation — either the function's own
/// source uses unsafe, OR the `Inline` pass (which runs BEFORE this Runtime-Optimized pass, at
/// lib.rs `&inline::Inline`) copied in the body of an inlined callee that uses unsafe. The
/// inlined-callee leg is ESSENTIAL: a SAFE caller that inlines an `unsafe fn` doing
/// `unchecked_add` would otherwise carry the inlined UB op's panic-class obligation while its
/// OWN HIR shows no unsafe, and the gate would wrongly demote it. Every transitively-inlined
/// callee appears as its own `SourceScopeData::inlined` scope (the inliner copies the callee's
/// scopes, already carrying their own inline markers), so a FLAT scan over `source_scopes` is
/// complete — no recursion needed. When the Inline pass did not run (e.g. unoptimized builds)
/// there are no `inlined` scopes and only the function's own source is checked.
fn function_uses_unsafe<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    if def_uses_unsafe_source(tcx, body.source.def_id()) {
        return true;
    }
    body.source_scopes.iter().any(|scope| {
        scope.inlined.is_some_and(|(instance, _)| def_uses_unsafe_source(tcx, instance.def_id()))
    })
}

/// Trust (policy B restoration, 2026-09-12): does this function carry `unsafe`
/// that the std print-backend tolerance must respect? Own-source `unsafe` always
/// counts. An INLINED scope counts only when its callee is NOT std/core/alloc.
///
/// WHY THIS EXISTS, measured. `println!` verified at `-Copt-level=0`/`1` and
/// failed at `>=2` — every `--release` build. Isolated by construction:
/// `-Copt-level=2 -Zmir-opt-level=0` and `-Zinline-mir=no` both PASS, so the MIR
/// inliner is the cause. `def_uses_unsafe_source` answers `true` for any
/// NON-LOCAL def by construction (it cannot see their HIR), and
/// `function_uses_unsafe` ORs that over every inlined scope — so once the
/// inliner copies std's `format_args!` machinery into a printing function, that
/// function "uses unsafe" and the tolerance switched itself off. The trigger is
/// std being non-local, not std using `unsafe`.
///
/// SOUNDNESS. This relaxes an EXCLUSION gate, never a proof, and only for the
/// std print-backend rows `transport_row_is_std_print_dispatch` names. A real
/// hazard reached through inlined code still surfaces as its OWN obligation row,
/// and a `failed` row denies tolerance through `residual_gap_tolerance_denial`'s
/// refutation arm regardless of this predicate. Measured on the
/// unverified-dependency `*p` shape at -O2: three `hardened_unsafe_operation`
/// rows with outcome `failed` (null check, allocation validity, alignment) plus
/// two unmodeled-safety-assert `unknown` rows — fatal for its own reasons at
/// every opt level. Inlined NON-std unsafe still trips this predicate, so that
/// protection is kept belt-and-braces even though the refutation rows already
/// cover it. Pinned by
/// `tests/ui/trust/policy_b/absent_dep_callee_stays_closed_opt2.rs`.
///
/// DELIBERATELY NOT used by `memory_safe_demotion_applies` (or the inlined-callee
/// caller below): that lane's promise is about the whole body including
/// everything inlined into it, and narrowing it is a separate decision with its
/// own counterexample history
/// (`reports/memory-safe-demote-is-unfixable-at-this-seam-2026-08-23.md`).
///
/// OWN-BODY leg uses `def_uses_user_unsafe_source` (2026-09-13): a
/// COMPILER-GENERATED unsafe block in this function's own HIR — the
/// `format_args!` desugaring's `unsafe { core::fmt::Arguments::new(…) }` wrapper
/// is the only one that occurs on this path — is a foundational-TCB construction,
/// not user unsafe, so it must not by itself flip the std-print tolerance off. A
/// `println!` with a RUNTIME argument emits that block at every opt-level (a
/// CONST argument folds to the safe `Arguments::from_str_nonconst`, so it never
/// did). A user-authored `unsafe { … }` (`UserProvided`) and an `unsafe fn`
/// signature both still count. The INLINED-scope leg keeps the conservative
/// whole-block scan: a non-std inlined body is genuinely foreign.
fn function_uses_unsafe_outside_std<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    if def_uses_user_unsafe_source(tcx, body.source.def_id()) {
        return true;
    }
    body.source_scopes.iter().any(|scope| {
        scope.inlined.is_some_and(|(instance, _)| {
            let did = instance.def_id();
            // AUTHENTICATED by lang-item ownership: a spoofed `--crate-name core`
            // inlined body must NOT dodge the unsafe-outside-std classification.
            !crate_is_authentic_foundational(tcx, did.krate) && def_uses_unsafe_source(tcx, did)
        })
    })
}

/// Trust (policy B, runtime-value println — 2026-09-13): is `ty` a type whose
/// `Display`/`Debug`/… formatting is FOUNDATIONAL TCB and provably runs no user
/// code? Only such types may ride the bundled-std-member tolerance when a runtime
/// value is formatted (see `function_format_args_all_foundational_display`).
///
/// The allow-list is deliberately narrow and fail-closed: a primitive scalar,
/// `str`, or `String` — the same core of the audited
/// `trust_ir_bridge::is_display_total_std_ty`, restricted to the shapes whose
/// `fmt` cannot forward to a user callback. A FORWARDING wrapper (`&UserT`,
/// `Box<UserT>`, `Rc<UserT>`, …) is EXCLUDED even though its container is std,
/// because its `Display` blanket calls the inner type's `fmt`; references are
/// peeled first, so `&str`/`&i32` still qualify by their pointee. Everything else
/// — every user ADT, every derived `Debug`, every container — is `false`, which
/// keeps its format fatal (an honest completeness gap).
fn ty_is_foundational_display<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let mut memo = FxHashMap::default();
    ty_is_foundational(tcx, ty, &mut memo)
}

/// Trust (2026-09-25): may a FOREIGN function ITEM handed to a callee as a TYPE
/// ARGUMENT be treated like a callable this compilation already accounts for?
///
/// The item runs INSIDE the callee, where no call-site family recognizer looks,
/// so it is admitted only where a DIRECT call to it would have been charged
/// nothing: it is a constructor (no body), or a sysroot item that EITHER cannot
/// panic by its own MIR ([`sysroot_fn_item_cannot_panic`]) OR is itself in the
/// tolerated vanilla-sysroot class ([`callee_is_vanilla_sysroot`], which already
/// excludes the division and caller-value families) AND in none of vcgen's
/// call-site panic families (`trust_vcgen::callee_has_call_site_panic_family`:
/// `unwrap`/`expect`, signed `abs`, slice-method panics, bounds-panicking
/// mutators). So `char::is_whitespace`/`is_numeric` and `Ord::min` stay admitted
/// while `u32::div_euclid` and `Option::unwrap` do not (measured, wave-3 review
/// c02). A user global allocator makes every sysroot item non-vanilla, as for calls.
///
/// Trust (2026-10-03, corrected): the second arm is the DEFAULT policy's standard
/// for an absent sysroot callee — the item called through its `FnOnce` shim is
/// charged a `runtime_checked` absent-callee row that policy B reports and builds —
/// and not "the same standard as a direct call" on every policy, as this said:
/// `certify` and memory-safe refuse that row. The indirect-call gate therefore asks
/// [`sysroot_callable_item::foreign_callable_item_is_accounted`], which consults this
/// function only on a policy that tolerates the row; on the other two it admits the
/// first two arms alone (`o.unwrap_or_else(AssertUnwindSafe(std::thread::current))`
/// built exit 0 under certify and memory-safe, the bare twin exit 1 — measured, see
/// that module). `ty_is_foundational_in` still asks this function as it stands.
///
/// Trust (W4 HASHMAP r3, 2026-09-29): the call-site families include the
/// ALLOCATION lane's charges (`with_capacity`, `reserve`, `collect`, `from_iter`,
/// `extend`, `unzip`, `collect_into`, ...), which a direct call pays as an
/// `[unbounded_allocation]` row. MEASURED on the redo's r2 (`b9288112d`):
/// `Some(n).map(HashSet::<u64>::with_capacity)` — and `Result::map`,
/// `Option::map_or_else`, `Iterator::map`, an `impl Fn`, and `Option::map(
/// HashSet::from_iter)` / `map(Iterator::collect::<HashMap<_, _>>)` — built rc=0
/// with no row and panicked "Hash table capacity overflow" (their `Vec` twins
/// built rc=0 on main too).
fn foreign_fn_item_type_arg_is_accounted<'tcx>(
    tcx: TyCtxt<'tcx>,
    def_id: DefId,
    args: ty::GenericArgs<'tcx>,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
    credit: HashTableCredit,
) -> bool {
    // Trust (2026-10-03): the constructor and structurally-total arms, shared with
    // the indirect-call gate's rule for `certify` and memory-safe
    // (`sysroot_callable_item`). Unchanged in effect: a constructor, or a sysroot
    // item `sysroot_fn_item_cannot_panic` proves, answers `true`; any other
    // non-sysroot item answers `false` just below.
    if sysroot_callable_item::foreign_fn_item_is_structurally_accounted(tcx, def_id, args) {
        return true;
    }
    if !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def_id) {
        return false;
    }
    // Trust (W4 ITER-HOF landing round, 2026-10-03): a DIVERGING item — declared
    // `-> !` — never returns to the callee that runs it, so every call is its
    // panic, abort or exit. The vanilla arm below never looks inside the item: a
    // DIRECT call bundles the body, and the bundle walk then reaches the panic
    // machinery (`panic_with_hook`, the user hook's `dyn Fn`), which is not
    // vanilla, so that call is refused. MEASURED (stage 1 of origin/main
    // `9fc182f094` and of the W4 branch `ba656c61b6`, `TRUST_VANILLA_DEBUG=1`):
    // `std::panic::panic_any::<u32>` is `vanilla=true` here and in none of vcgen's
    // call-site families, so `v.iter().copied().map(std::panic::panic_any::<u32>)
    // .count()` built rc=0 on main, and with W4's collect count the `.collect()`
    // spelling did too (review probes v01/w04/w05), while the closure twin
    // `.map(|&n| -> u32 { std::panic::panic_any(n) })` was refused on both. A
    // structurally total `-> !` item (a bare `loop {}`) is still admitted by the
    // arm above; this withholds only the vanilla admission.
    if tcx.fn_sig(def_id).instantiate(tcx, args).skip_binder().output().is_never() {
        return false;
    }
    let name = trust_mir_extract::safe_def_path_str_with_args(tcx, def_id, args);
    callee_is_vanilla_sysroot(
        tcx,
        def_id,
        args,
        &name,
        crate_graph_registers_user_global_allocator(tcx),
        false,
        memo,
        credit,
    ) && !trust_vcgen::callee_has_call_site_panic_family(&name)
}

/// How deep [`sysroot_fn_item_cannot_panic`] follows direct sysroot calls.
const SYSROOT_FN_ITEM_TOTALITY_DEPTH: u32 = 4;

/// Trust (2026-09-25): can this sysroot function ITEM, instantiated at `args`,
/// be shown STRUCTURALLY unable to panic from its own MIR? Every reachable
/// terminator must be one of: `Goto`, `SwitchInt`, `Return`, `Unreachable`,
/// `UnwindResume`, `UnwindTerminate`, or a `Call` that returns (`target: Some`)
/// to a statically resolved sysroot `Item` that passes this same test at depth
/// − 1. An `Assert` (a bounds, overflow or division check), a diverging call, a
/// tail call, inline asm, a `Drop`, a `Yield`, an indirect or virtual call, a
/// missing body, a cycle or the depth bound all answer `false`. Fail-closed:
/// this only decides whether the item may count as FOUNDATIONAL in a type
/// argument; `false` leaves the enclosing call to the ordinary absent-callee
/// lane. The sysroot's MIR is the base the vanilla class already trusts.
fn sysroot_fn_item_cannot_panic<'tcx>(
    tcx: TyCtxt<'tcx>,
    def_id: DefId,
    args: ty::GenericArgs<'tcx>,
    depth: u32,
    in_progress: &mut FxHashSet<DefId>,
) -> bool {
    use rustc_middle::mir::TerminatorKind as T;
    if depth == 0 || !in_progress.insert(def_id) {
        return false;
    }
    let typing_env = ty::TypingEnv::fully_monomorphized();
    let verdict = (|| {
        if args.has_non_region_param() {
            return false;
        }
        let Ok(Some(instance)) = ty::Instance::try_resolve(tcx, typing_env, def_id, args) else {
            return false;
        };
        let item = match instance.def {
            ty::InstanceKind::Item(item) => item,
            // Trust (1.101 migration, 2026-10-18): upstream integer
            // `Ord::min`/`max` now forward to the fallback-bodied intrinsics
            // `integer_min`/`integer_max` (`if a < b { a } else { b }`,
            // `#[rustc_nounwind]`, `#[miri::intrinsic_fallback_is_spec]`),
            // whose instance kind is `Intrinsic`, so the scan stopped at the
            // kind. A `#[rustc_nounwind]` intrinsic that is NOT
            // `must_be_overridden` runs either its native lowering (never
            // unwinds, by the attribute) or this very fallback body, so
            // scanning the fallback decides panic freedom on both paths. A
            // `must_be_overridden` intrinsic has no body to scan and stays
            // refused, as does one without the nounwind mark.
            ty::InstanceKind::Intrinsic(item) => {
                let Some(intr) = tcx.intrinsic(item) else { return false };
                if intr.must_be_overridden
                    || !tcx.codegen_fn_attrs(item).flags.contains(
                        rustc_middle::middle::codegen_fn_attrs::CodegenFnAttrFlags::NEVER_UNWIND,
                    )
                {
                    return false;
                }
                item
            }
            _ => return false,
        };
        if !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, item)
            || !tcx.is_mir_available(item)
        {
            return false;
        }
        let body = tcx.instance_mir(ty::InstanceKind::Item(item));
        body.basic_blocks.iter().all(|bb| {
            let Some(term) = &bb.terminator else { return false };
            match &term.kind {
                T::Goto { .. }
                | T::SwitchInt { .. }
                | T::Return
                | T::Unreachable
                | T::UnwindResume
                | T::UnwindTerminate(_) => true,
                // A `Drop` of a type that needs no drop at this instantiation
                // (a generic body's `drop(other)` at `T = i32`) runs nothing.
                T::Drop { place, .. } => {
                    let ty = instance.instantiate_mir_and_normalize_erasing_regions(
                        tcx,
                        typing_env,
                        ty::EarlyBinder::bind(tcx, place.ty(&body.local_decls, tcx).ty),
                    );
                    !ty.needs_drop(tcx, typing_env)
                }
                T::Call { func, target: Some(_), .. } => {
                    let Some((callee, callee_args)) = func.const_fn_def() else { return false };
                    let callee_args = instance.instantiate_mir_and_normalize_erasing_regions(
                        tcx,
                        typing_env,
                        ty::EarlyBinder::bind(tcx, callee_args),
                    );
                    sysroot_fn_item_cannot_panic(tcx, callee, callee_args, depth - 1, in_progress)
                }
                _ => false,
            }
        })
    })();
    in_progress.remove(&def_id);
    verdict
}

/// Trust (policy B as ruled, 2026-09-14): a type through which NO user code can be
/// reached — by its generic arguments OR by the values it carries — so any
/// std/core/alloc routine instantiated at it, handed it, or formatting it runs
/// only foundational-TCB code.
///
/// Affirmative, recursive over BOTH type arguments and (for a sysroot ADT) its
/// fields, coinductive on cycles, memoized per body, fail-closed on anything
/// unlisted:
///   * a primitive scalar, `str`, `!`;
///   * a reference, raw pointer, pattern type, tuple, array or slice over
///     qualifying types;
///   * an ADT defined in one of THIS compiler's own sysroot crates (authenticated
///     un-forgeably by `trust_mir_extract::def_is_in_real_sysroot_crate`, never
///     by name) whose type arguments AND whose instantiated, normalized field
///     types all qualify — `String`, `Vec<u32>`, `Option<u64>`, `PathBuf`,
///     `HashMap<String, i32>` (whose `base` field is a `hashbrown::HashMap`,
///     credited where std's declaration writes it: [`HashTableCredit`]), `File`,
///     `env::Args`;
///   * a sysroot function ITEM under the conditions the `FnDef` arm states.
/// A closure, coroutine, trait object, function pointer, type parameter,
/// projection, extern type, or user ADT is `false`: each is a channel into user
/// code. So is a std type OVER one (`Vec<UserT>`, `Box<dyn Trait>`) and — the
/// reason the FIELDS are walked, not only the arguments — a std type that
/// carries one by VALUE behind a foundational-looking surface: `fmt::Arguments`
/// (fn pointers to the formatters; so `_print`/`format` never enter the vanilla
/// class and stay governed by their own rules), `io::Error` (a `Box<dyn Error>`
/// in its `Custom` repr, reachable only through a `PhantomData` type argument in
/// the bit-packed layout — hence the arguments are walked too), `process::Command`
/// (`pre_exec` closures), `task::Waker` (a vtable), `fmt::Formatter` (`&mut dyn
/// Write`).
///
/// This widens the previous scalar/`str`/`String` allow-list, which refused
/// `{:?}` on a `Vec`/`Option` as a "user Display" although `<Vec<T> as Debug>::
/// fmt` is alloc code that only ever forwards to `<T as Debug>::fmt`. The
/// soundness argument is unchanged: no user `fmt` can be reached, so no user
/// panic edge is hidden by the ROOT-scope inventory reset. The orphan rules are
/// what make "sysroot trait + foundational arguments" resolve INSIDE the sysroot:
/// a user crate cannot implement a sysroot trait for a type it does not own,
/// and every type it owns is refused here.
/// Trust (2026-10-01): the signature types of a function POINTER type `arg` given as
/// the type argument of `PhantomData` itself (`def` is the `phantom_data` lang item),
/// for the two type walks below. `PhantomData<fn() -> T>` is a zero-sized variance
/// marker: it has no fields and holds no pointer, so no function can be reached
/// through it, and only the types it names matter. Every other `FnPtr` (a field, an
/// argument of any other ADT) is still a stored pointer into user code. Sweep w13:
/// `core::iter::empty::<u32>().max()`, whose `Empty<T>` is
/// `PhantomData<fn() -> T>`, was refused NOT-VANILLA on that marker.
fn phantom_fn_ptr_signature<'tcx>(
    tcx: TyCtxt<'tcx>,
    def: ty::AdtDef<'tcx>,
    arg: Ty<'tcx>,
) -> Option<Vec<Ty<'tcx>>> {
    if tcx.lang_items().phantom_data() != Some(def.did()) {
        return None;
    }
    let ty::FnPtr(sig_tys, _) = arg.kind() else { return None };
    Some(sig_tys.skip_binder().inputs_and_output.iter().collect())
}

fn ty_is_foundational<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
) -> bool {
    ty_is_foundational_in(tcx, ty, memo, HashTableCredit::Declared)
}

/// Trust (W4 HASHMAP redo, 2026-09-25): where a type of the crate behind
/// `std::collections::HashMap`/`HashSet` (`hashbrown`, identified structurally
/// by `trust_mir_extract::def_is_in_std_hash_table_crate`) counts as
/// foundational.
///
/// std's `HashMap<K, V, S>` is a single field, `base: hashbrown::HashMap<K, V,
/// S>`, so before this every `HashMap`/`HashSet` was non-foundational and every
/// call on one was refused as a channel into user code. hashbrown is the ONLY
/// crate outside `core`/`alloc`/`std` this class credits, and only where STD
/// put the value — never where a program could have chosen it:
///
///  * [`HashTableCredit::Declared`] (every user-code position: the root body's
///    call sites, the masking walk, the `Display` gate). A hashbrown ADT counts
///    only where a std or hashbrown DECLARATION writes it — std's `base` field,
///    hashbrown's own `table: RawTable<..>` — and is then walked like a sysroot
///    ADT (its type arguments and fields). The same ADT at TOP LEVEL, as a type
///    argument, or substituted for a type parameter is NOT foundational: a program
///    holds a hashbrown value only if some crate named hashbrown for it (a
///    `rustc_private` dependency re-exporting it), and there hashbrown's own API —
///    its `Index` impl ("invalid key"), its `Extend` (capacity), `get_many_mut` —
///    would be reachable at the caller's values with no std code in between.
///  * [`HashTableCredit::StdSite`] (a call site INSIDE an authentic std/core/
///    alloc body the bundle walk visits, `record_bundle_walk_vanilla_callee`).
///    There the hashbrown value is the one std's table code handed over
///    (`self.base.insert(k, v)`, `<base::Iter as Iterator>::next`, `self.base.
///    clone()`), so a hashbrown ADT counts wherever it appears, and a hashbrown
///    CALLEE may be vanilla (`callee_is_vanilla_sysroot`). A user-substituted
///    hashbrown type cannot ride this: it reaches a std body only through a root
///    call whose instantiation names it, which the masking walk
///    (`ty_reaches_foreign_user_code`, Declared mode) flags as foreign, and a
///    LOCAL generic callee's instantiation is checked for it the same way
///    (`callee_instantiation_reaches_foreign_user_code`).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum HashTableCredit {
    Declared,
    StdSite,
}

/// How deep [`declared_ty_is_foundational`] follows a DECLARED type that names a
/// hashbrown ADT. hashbrown's own nesting is 3-4 levels (`HashMap` -> `RawTable`
/// -> `RawTableInner`); the bound only guards against a pathological graph, and
/// exhausting it answers `false`.
const DECLARED_HASH_TABLE_DEPTH: u32 = 16;

/// Does a DECLARED type (a field type as written, in terms of its item's own
/// generic parameters) name an ADT of the crate behind std's hash tables?
/// `walk` yields the type and every nested type argument but never an ADT's
/// fields, so a std `HashMap<K, V>` written in a declaration does not count —
/// only a hashbrown ADT literally written there.
fn ty_names_std_hash_table_adt<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    ty.walk().filter_map(|arg| arg.as_type()).any(|t| {
        matches!(t.kind(), ty::Adt(def, _)
            if trust_mir_extract::def_is_in_std_hash_table_crate(tcx, def.did()))
    })
}

/// The FIELD half of [`ty_is_foundational_in`]'s ADT arm: is field `field_did`
/// of an ADT instantiated at `args` foundational?
///
/// A field whose DECLARED type names no hashbrown ADT is decided exactly as
/// before (instantiate, normalize, recurse). One that does is walked in its
/// declared form ([`declared_ty_is_foundational`]), which is what lets std's
/// `base: hashbrown::HashMap<K, V, S>` count while a hashbrown value substituted
/// for a type parameter (`Option<T>` at `T = hashbrown::HashMap<..>`) does not.
fn declared_field_is_foundational<'tcx>(
    tcx: TyCtxt<'tcx>,
    field_did: DefId,
    args: ty::GenericArgs<'tcx>,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
    credit: HashTableCredit,
) -> bool {
    let declared = tcx.type_of(field_did).instantiate_identity().skip_normalization();
    declared_ty_is_foundational(tcx, declared, args, memo, credit, DECLARED_HASH_TABLE_DEPTH)
}

/// Is `declared` — a type as WRITTEN in a std or hashbrown declaration, in terms
/// of that declaration's generic parameters, which `args` instantiate —
/// foundational?
///
/// Where it names no hashbrown ADT this is the ordinary question on the
/// instantiated, normalized type: every type PARAMETER is thereby judged at the
/// caller's own argument in the caller's mode, so a user type substituted into a
/// hashbrown table (`HashMap<UserKey, _>`) is still refused. Where it does, the
/// declared structure is walked: a hashbrown or sysroot ADT written here counts
/// when its declared arguments and its fields (hashbrown's own declarations,
/// instantiated at those declared arguments, so still in terms of the same
/// parameters) all do. Anything else that names a hashbrown ADT answers `false`.
fn declared_ty_is_foundational<'tcx>(
    tcx: TyCtxt<'tcx>,
    declared: Ty<'tcx>,
    args: ty::GenericArgs<'tcx>,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
    credit: HashTableCredit,
    depth: u32,
) -> bool {
    if !ty_names_std_hash_table_adt(tcx, declared) {
        // The pre-W4 field walk, unchanged.
        let field_ty = ty::EarlyBinder::bind(tcx, declared).instantiate(tcx, args);
        return match tcx
            .try_normalize_erasing_regions(ty::TypingEnv::fully_monomorphized(), field_ty)
        {
            Ok(field_ty) => ty_is_foundational_in(tcx, field_ty, memo, credit),
            Err(_) => false,
        };
    }
    let Some(depth) = depth.checked_sub(1) else { return false };
    match declared.kind() {
        ty::Ref(_, inner, _)
        | ty::RawPtr(inner, _)
        | ty::Array(inner, _)
        | ty::Slice(inner)
        | ty::Pat(inner, _) => declared_ty_is_foundational(tcx, *inner, args, memo, credit, depth),
        ty::Tuple(elems) => {
            elems.iter().all(|t| declared_ty_is_foundational(tcx, t, args, memo, credit, depth))
        }
        ty::Adt(def, declared_args) => {
            (trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def.did())
                || trust_mir_extract::def_is_in_std_hash_table_crate(tcx, def.did()))
                && declared_args
                    .types()
                    .all(|t| declared_ty_is_foundational(tcx, t, args, memo, credit, depth))
                && def.all_fields().all(|field| {
                    let nested = tcx.type_of(field.did).instantiate(tcx, declared_args);
                    declared_ty_is_foundational(
                        tcx,
                        nested.skip_normalization(),
                        args,
                        memo,
                        credit,
                        depth,
                    )
                })
        }
        _ => false,
    }
}

/// [`ty_is_foundational`] in an explicit [`HashTableCredit`] mode. A `memo` must
/// only ever be used with ONE mode (every caller creates its own).
fn ty_is_foundational_in<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
    credit: HashTableCredit,
) -> bool {
    if let Some(&known) = memo.get(&ty) {
        return known;
    }
    // Coinductive: a cycle (`LinkedList<T>` -> `Node<T>` -> `Option<NonNull<Node<T>>>`)
    // is foundational unless something ON it is not; the entry is overwritten below.
    memo.insert(ty, true);
    let verdict = match ty.kind() {
        ty::Bool | ty::Char | ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Str | ty::Never => true,
        ty::Ref(_, inner, _)
        | ty::RawPtr(inner, _)
        | ty::Array(inner, _)
        | ty::Slice(inner)
        | ty::Pat(inner, _) => ty_is_foundational_in(tcx, *inner, memo, credit),
        ty::Tuple(elems) => elems.iter().all(|t| ty_is_foundational_in(tcx, t, memo, credit)),
        // Trust (OVER-REFUSAL — a sysroot function ITEM, 2026-09-18): a `FnDef`
        // is the zero-sized item type of one NAMED function, and it is
        // foundational under exactly the condition this predicate's caller
        // applies to a callee — the function is sysroot code and every type it
        // is instantiated at is itself foundational. Such an item can dispatch
        // into no user code, which is the whole soundness content here.
        //
        // WHAT IT COSTS TODAY. `v.sort()` lowers to
        // `alloc::slice::stable_sort::<u32, fn(&u32,&u32)->bool {<u32 as
        // PartialOrd>::lt}>` and `s.split(char::is_whitespace)` to
        // `str::split::<fn(char)->bool {char::is_whitespace}>`. Both were
        // refused on the FnDef argument alone, while `v.sort_unstable()` — the
        // same sort at the same element type, differing only in that its
        // comparator is not reified into a type argument — was tolerated. The
        // two programs got IDENTICAL verification reports (one
        // `[assert] runtime-checked` row) and opposite exit codes.
        //
        // WHAT IT DOES NOT ADMIT. A closure is `ty::Closure`, a trait object
        // `ty::Dynamic`, a fn POINTER `ty::FnPtr` — none is a `FnDef` and each
        // still falls to `_ => false`, so `sort_by(|a, b| user(a, b))` and
        // `map(user_fn)` are untouched. A user function's own item type is a
        // `FnDef` whose def is not in the sysroot, and `<MyType as
        // PartialOrd>::lt` resolves to the USER's impl method, not core's.
        // The signature check mirrors the callee predicate rather than
        // inventing a second standard.
        ty::FnDef(def_id, args) => {
            // An ADT CONSTRUCTOR is foundational whoever owns the type. A
            // tuple-struct or enum-variant constructor has NO BODY: it moves its
            // fields into a value. It cannot panic and it can dispatch into no
            // user code, which is this predicate's whole question — so the usual
            // sysroot test is the wrong one for it.
            //
            // MEASURED 2026-09-19: `self.0.checked_add(1).map(Id)` for a local
            // `struct Id(pub u32)` charges
            // `<fn(u32) -> Id {Id} as FnOnce<(u32,)>>::call_once` and was refused
            // NOT-VANILLA on the `Id` in that type argument. `map(Some)`,
            // `map(Ok)` and `map(MyWrapper)` are the same shape.
            //
            // The generic arguments and signature inputs are still checked below,
            // so a constructor over a non-foundational FIELD type is refused: the
            // admission is about the constructor having no body, not about its
            // payload.
            // Trust (2026-09-25): a sysroot ITEM must also be one that cannot
            // PANIC. The vanilla class tolerates a sysroot callee's panic only
            // where vcgen's family recognizers see the call (they charge
            // `unwrap`, the division family, index mutators, … at the call site);
            // an item handed over as a TYPE ARGUMENT is called inside the sysroot
            // callee, where no recognizer looks. Measured (wave-3 adversarial
            // review, probe c02): `v.iter().copied().fold(100, u32::div_euclid)`
            // built rc=0 with no row and panicked. The question is asked of the
            // item's own MIR, never of its name — see
            // `sysroot_fn_item_cannot_panic`. A constructor has no body.
            foreign_fn_item_type_arg_is_accounted(tcx, *def_id, args.skip_binder(), memo, credit)
                && args.skip_binder().types().all(|t| ty_is_foundational_in(tcx, t, memo, credit))
                && tcx
                    .fn_sig(*def_id)
                    .instantiate(tcx, args.skip_binder())
                    .skip_binder()
                    .inputs()
                    .iter()
                    .all(|t| ty_is_foundational_in(tcx, *t, memo, credit))
        }
        ty::Adt(def, args) => {
            // Trust (W4 HASHMAP redo, 2026-09-25): the crate test admits a
            // hashbrown ADT at THIS position only at a std call site; in every
            // user-code position it counts only where a std/hashbrown declaration
            // writes it, which the field walk below decides
            // (`declared_field_is_foundational`). See [`HashTableCredit`].
            // Trust (merge 2026-10-14): this subsumes the 2026-09-29
            // `def_is_sysroot_code` arm (any non-user-visible private sysroot crate,
            // in every position), which is removed: it credited a top-level
            // hashbrown value a dependency could hand over. The `PhantomData<fn() ->
            // T>` marker relaxation (2026-10-01, `phantom_fn_ptr_signature`) is kept.
            (trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def.did())
                || (credit == HashTableCredit::StdSite
                    && trust_mir_extract::def_is_in_std_hash_table_crate(tcx, def.did())))
                && !std_collection_of_zero_sized_elements(tcx, *def, *args)
                && args.types().all(|t| match phantom_fn_ptr_signature(tcx, *def, t) {
                    Some(sig) => sig.iter().all(|t| ty_is_foundational_in(tcx, *t, memo, credit)),
                    None => ty_is_foundational_in(tcx, t, memo, credit),
                })
                && def.all_fields().all(|field| {
                    declared_field_is_foundational(tcx, field.did, *args, memo, credit)
                })
        }
        _ => false,
    };
    memo.insert(ty, verdict);
    verdict
}

/// Trust (2026-09-29): is `def<args>` a std collection of ZERO-SIZED elements —
/// a hash table ([`std_hash_table_of_zero_sized_elements`]) or a growable
/// sequence ([`std_growable_sequence_of_zero_sized_elements`])? Such a
/// collection stays OUT of the foundational class and is "foreign" for the
/// masking walk; the two walks ask this one question so they cannot disagree.
fn std_collection_of_zero_sized_elements<'tcx>(
    tcx: TyCtxt<'tcx>,
    def: ty::AdtDef<'tcx>,
    args: ty::GenericArgs<'tcx>,
) -> bool {
    std_hash_table_of_zero_sized_elements(tcx, def, args)
        || std_growable_sequence_of_zero_sized_elements(tcx, def, args)
}

/// Trust (2026-09-29): is `def<args>` a std `Vec`, `VecDeque` or `BinaryHeap`
/// (by diagnostic item) whose element is ZERO-SIZED, or whose element's layout
/// cannot be computed?
///
/// The vanilla-sysroot class tolerates the GROWTH panic every push-like call
/// shares (`reserve(1)` / `grow_one`: "capacity overflow" when `len ==
/// capacity == usize::MAX`) on the argument that a sized element exhausts
/// memory — an allocation-failure ABORT, outside the modeled panic set — long
/// before a length can reach that capacity. docs/TCB.md ruled `Vec::insert` into
/// that class ("inherits push's growth class") and named the ZST exception
/// without excluding it. For a zero-sized element the argument is false: the
/// capacity IS `usize::MAX`, no byte is ever allocated, and a length of
/// `usize::MAX` is a legitimate value a caller may hand in (`Vec<()>` with
/// `set_len(usize::MAX)` is sound; safe `vec![(); n]` reaches it too), so the
/// growth panic is reachable. Measured on main `0.10.0+g4715fe060` (probe r09):
/// `if i <= v.len() { v.insert(i, ()) }` on `&mut Vec<()>` built rc=0 and
/// panicked "capacity overflow"; `v.push(())` likewise. The same holds for
/// `VecDeque` (its capacity for a ZST is `usize::MAX`) and for `BinaryHeap`,
/// which is a `Vec`.
///
/// Excluding such a sequence from the foundational class makes every std call
/// that takes one non-vanilla, so its absent-callee panic row is fail-closed
/// again, exactly as a hash table of zero-sized elements already is. The
/// exclusion is by the collection's identity and its element's layout, never a
/// name, and only refuses.
fn std_growable_sequence_of_zero_sized_elements<'tcx>(
    tcx: TyCtxt<'tcx>,
    def: ty::AdtDef<'tcx>,
    args: ty::GenericArgs<'tcx>,
) -> bool {
    let did = def.did();
    let is_sequence = tcx.is_diagnostic_item(sym::Vec, did)
        || tcx.is_diagnostic_item(sym::VecDeque, did)
        || tcx.is_diagnostic_item(sym::BinaryHeap, did);
    if !is_sequence {
        return false;
    }
    let Some(element) = args.types().next() else { return true };
    match tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(element)) {
        Ok(layout) => layout.is_zst(),
        Err(_) => true,
    }
}

/// Trust (W4 HASHMAP, 2026-09-25; kept by the redo): is `def<args>` a std
/// `HashMap`/`HashSet` (its `HashMap`/`HashSet` diagnostic item) whose ELEMENT —
/// `(K, V)`, or `T` — is ZERO-SIZED, or whose element's layout cannot be computed?
///
/// Such a table stays OUT of the foundational class (and "foreign" for the
/// masking walk), exactly where every `HashMap` was before hashbrown was
/// credited. A bulk insert reserves the source's `size_hint().0` up front and
/// panics "Hash table capacity overflow" past `usize::MAX / 8` whatever the
/// element size, and "an existing collection bounds the count" says nothing when
/// the elements cost no memory (`vec![(); 1 << 61]`). vcgen's allocation lane now
/// refuses a zero-sized SOURCE itself (F3); this keeps a zero-sized DESTINATION
/// out of the class as a second, independent fence. The exclusion is by the
/// table's identity and its element's layout, never a name, and only refuses.
fn std_hash_table_of_zero_sized_elements<'tcx>(
    tcx: TyCtxt<'tcx>,
    def: ty::AdtDef<'tcx>,
    args: ty::GenericArgs<'tcx>,
) -> bool {
    let element = if tcx.is_diagnostic_item(sym::HashSet, def.did()) {
        args.types().next()
    } else if tcx.is_diagnostic_item(sym::HashMap, def.did()) {
        let mut types = args.types();
        match (types.next(), types.next()) {
            (Some(key), Some(value)) => Some(Ty::new_tup(tcx, &[key, value])),
            _ => None,
        }
    } else {
        return false;
    };
    let Some(element) = element else { return true };
    match tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(element)) {
        Ok(layout) => layout.is_zst(),
        Err(_) => true,
    }
}

/// Trust (ALLOC-WIDTH-1, 2026-10-08): the compilation target's pointer width in
/// bits — the SESSION fact the allocation-size lane judges every capacity line
/// against (`isize::MAX` at this width) and the only witness of a 64-bit target it
/// applies the live-address-space axiom under (`trust_vcgen::VcgenContext::
/// with_target_pointer_bits`). Read from the same `data_layout` the extraction lane
/// sizes `usize` with, never from the host.
fn trust_target_pointer_bits(tcx: TyCtxt<'_>) -> Option<u32> {
    u32::try_from(tcx.data_layout.pointer_size().bits()).ok()
}

/// Trust (refuted 2026-09-16, SIGPIPE lens): the process-signal policy this
/// compilation actually INSTALLS, or `None`. `Session::trust_declared_process_
/// signal_policy` says what the profile/flags DECLARE; the only installer is
/// std's `lang_start` -> `rt::init(.., sigpipe)`, which rustc emits solely for an
/// `EntryFnType::Main` entry (`rustc_passes::entry::sigpipe`). A `#![no_main]`
/// crate, a library, a cdylib or a proc-macro emits no installer, so a mandate
/// discharged on the declaration there was discharged on nothing (measured: a
/// `#![no_main]` binary under `unix_hardened` built with the mandate gone and
/// INHERITED its parent's SIGPIPE disposition). The mandate stays minted — and
/// reported — wherever this compilation does not install the policy.
fn installed_process_signal_policy(tcx: TyCtxt<'_>) -> Option<&'static str> {
    match tcx.entry_fn(()) {
        Some((_, rustc_session::config::EntryFnType::Main { .. }))
            if crate_static_constructor(tcx).is_none() =>
        {
            tcx.sess.trust_declared_process_signal_policy()
        }
        _ => None,
    }
}

/// Trust (2026-09-16, refuted): a `#[used] #[link_section = "__DATA,__mod_init_func"]`
/// static (the `ctor` crate's shape; `.init_array`/`.ctors`/`.CRT$XCU` on the
/// other targets) runs its function at image load, BEFORE `lang_start ->
/// rt::init -> reset_sigpipe` installs the declared disposition. Its stdout
/// writes ran under the parent's inherited `SIG_IGN` (measured: exit 134,
/// "failed printing to stdout: Broken pipe") while the mandate had been
/// discharged for the whole compilation. The compiler cannot see which bodies
/// such a constructor reaches, so ONE such static withdraws the discharge for
/// every body of the crate: the mandate stays minted and reported, naming the
/// static. Returns the offending static's `LocalDefId` and section name.
fn crate_static_constructor(tcx: TyCtxt<'_>) -> Option<(LocalDefId, String)> {
    if let Some(cached) =
        with_crate_verification_state(tcx.sess, |state| state.static_constructor_scan.clone())
    {
        return cached;
    }
    let found = crate_static_constructor_uncached(tcx);
    with_crate_verification_state(tcx.sess, |state| {
        state.static_constructor_scan = Some(found.clone());
    });
    found
}

fn crate_static_constructor_uncached(tcx: TyCtxt<'_>) -> Option<(LocalDefId, String)> {
    const INIT_SECTIONS: &[&str] = &["__mod_init_func", ".init_array", ".ctors", ".CRT$XC"];
    for item_id in tcx.hir_crate_items(()).free_items() {
        let item = tcx.hir_item(item_id);
        if !matches!(item.kind, rustc_hir::ItemKind::Static(..)) {
            continue;
        }
        let def_id = item.owner_id.def_id;
        let Some(section) = tcx.codegen_fn_attrs(def_id).link_section else {
            continue;
        };
        let section = section.as_str();
        if INIT_SECTIONS.iter().any(|init| section.contains(init)) {
            return Some((def_id, section.to_string()));
        }
    }
    None
}

/// Trust (policy B as ruled, 2026-09-14): for every call site in `body`, whether
/// the callee is a VANILLA-SEMANTICS sysroot routine — defined in one of this
/// compiler's own `core`/`alloc`/`std` crates AND instantiated only at
/// foundational types AND taking only foundational parameter types, so its panic
/// (if any) is std's own defined behaviour and it can dispatch into no user code.
/// Keyed by the exact string the bridge writes into an absent-callee row
/// (`func_operand_name`, the same key `collect_expected_absent_callees` uses);
/// the name is only the KEY — the verdict is computed from the `DefId`, generic
/// arguments and signature here, where they still exist. Two sites rendering
/// the same name are ANDed, so an impostor colliding with a real routine fails
/// closed, and a row naming a callee absent from the ledger is not tolerated.
///
/// WHY: the 2026-07-25 ruling makes a completeness gap that keeps rustc's
/// runtime check REPORTED, not fatal — "vanilla Rust semantics". What shipped
/// exempted exactly `std::io::_print`/`_eprint` by name; every other absent std
/// callee (`std::env::args`, `str::parse::<u64>`, `fs::read_to_string`) was a
/// fail-closed assumption panic, which is why six ordinary programs that build
/// and run correctly under advisory were all refused by the default lane
/// (`reports/2026-09-13-w1-alignment-obligation-sizing.md`). The `_print`
/// argument — the only unproved edge is std's own defined panic — is exactly
/// the argument for every routine this predicate admits; what distinguishes
/// `_print`, `write_fmt` and `fmt::write` (which keep their own, stricter
/// treatment) is that they take a `fmt::Arguments`, a VALUE carrying pointers
/// to arbitrary user `Display` impls — which is why the parameter types are
/// checked and `Arguments` is not foundational. Hence also the type-argument
/// half: `parse::<u64>` is vanilla, `parse::<UserT>` calls a user `FromStr` and
/// is not, and `Iterator::map::<F>` over a user closure is not either.
/// Trust (VEC-INSERT, 2026-09-25): is `def_id` std's INHERENT `Vec::remove`,
/// `Vec::swap_remove` or `Vec::insert` — decided on the `DefId` (an inherent assoc fn
/// of an impl whose self type carries the `Vec` diagnostic item, both resident in the
/// real sysroot), never a rendered path. Their panics: the index check (`index >=
/// len`, resp. `> len` for `insert`) and, for `insert`, the growth path `push`
/// shares (capacity overflow / allocation failure).
fn def_is_std_vec_index_mutator(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    if def_id.is_local()
        || !matches!(tcx.def_kind(def_id), DefKind::AssocFn)
        || tcx.trait_of_assoc(def_id).is_some()
        || !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def_id)
        || !matches!(tcx.item_name(def_id).as_str(), "remove" | "swap_remove" | "insert")
    {
        return false;
    }
    let Some(impl_did) = tcx.impl_of_assoc(def_id) else { return false };
    let ty::Adt(adt_def, _) =
        tcx.type_of(impl_did).instantiate_identity().skip_normalization().kind()
    else {
        return false;
    };
    !adt_def.did().is_local()
        && tcx.is_diagnostic_item(sym::Vec, adt_def.did())
        && trust_mir_extract::def_is_in_real_sysroot_crate(tcx, adt_def.did())
}

fn function_vanilla_sysroot_callees<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    // Trust (VEC-INSERT, 2026-09-25): the call blocks of THIS body at which vcgen
    // charged a `Vec` index mutator its real index precondition. `None` where that
    // record does not exist yet (the vcgen-context caller) — every mutator then
    // keeps its caller-value exclusion.
    charged_vec_mutator_blocks: Option<&[trust_types::BlockId]>,
    // Trust (VANILLA-REACH-1, 2026-10-27): also admit a call the TYPE rule refuses
    // when `vanilla_reach::callee_is_vanilla_sysroot_by_reach` closes it. `false`
    // for vcgen's non-reentrant callee set: a call admitted by reach may run a
    // local body, which may re-enter the caller, so the inferred
    // recursion-termination lane must keep the type rule alone.
    reach_admission: bool,
) -> FxHashMap<String, bool> {
    let mut out: FxHashMap<String, bool> = FxHashMap::default();
    let mut memo: FxHashMap<Ty<'tcx>, bool> = FxHashMap::default();
    let reach_typing_env = ty::TypingEnv::post_analysis(tcx, body.source.def_id());
    // Trust (refuted 2026-09-16, global-channels lens): a USER `#[global_allocator]`
    // anywhere in the crate graph — a verify-off dependency's included — is a
    // process-global channel from EVERY allocating sysroot routine (`String::from`,
    // `Vec::push`, `Box::new`) into user code that no type argument names and
    // no verdict covers (measured: a dependency allocator that panics in `alloc`
    // aborts a `String::from` + `mem::forget` program built exit 0 with one proved
    // row). The dealloc contract already refuses the drop side of that graph;
    // withdraw the vanilla class entirely on the allocation side too. `Global`'s
    // std chain (`__rdl_alloc` -> `System`) has no panic path, so with no user
    // allocator registered the class stands.
    let user_global_allocator = crate_graph_registers_user_global_allocator(tcx);
    for (bb_index, bb) in body.basic_blocks.iter_enumerated() {
        let Some(terminator) = &bb.terminator else { continue };
        let (TerminatorKind::Call { func, args, .. } | TerminatorKind::TailCall { func, args, .. }) =
            &terminator.kind
        else {
            continue;
        };
        let Some((def_id, generic_args)) = func.const_fn_def() else { continue };
        let name = trust_mir_extract::func_operand_name_in_body(tcx, body, func);
        // Trust (VEC-INSERT, 2026-09-25): is this call std's `Vec::{remove,
        // swap_remove, insert}` (by `DefId`) at a block where vcgen charged its index
        // precondition? Then its ONE caller-value panic is demanded of this body, and
        // the call is judged exactly like `push` (see `callee_is_vanilla_sysroot`).
        let caller_value_charged = charged_vec_mutator_blocks
            .is_some_and(|blocks| blocks.contains(&trust_types::BlockId(bb_index.index())))
            && def_is_std_vec_index_mutator(tcx, def_id);
        // Trust (2026-09-16): a sysroot callee the native-bundle lane DELIBERATELY
        // leaves absent BECAUSE ITS BODY PANICS ON A CALLER-SUPPLIED VALUE is not
        // vanilla, whatever its types look like.
        //
        // THE DEFECT THIS CLOSES, measured on stage1 `59161d88cc`:
        //
        //     pub fn wrapping(a: u32, b: u32) -> u32 { a.wrapping_div(b) }
        //
        // built exit 0 with two warnings, and `wrapping(10, 0)` panics with
        // "attempt to divide by zero" — while the SAME division written directly,
        // `a / d`, is refuted with a counterexample and correctly refused. Those
        // two programs have one panic between them and it is the same panic;
        // which one Trust refuses was being decided by whether the divide sat in
        // the caller's own body or behind a call. That asymmetry is exactly what
        // `tests/ui/trust/wrapping_div_zero_false_proof.rs` was minted to catch,
        // and its header says in capitals not to bless it if it goes red.
        //
        // WHY THE CLASS ADMITTED IT. This predicate's argument is about DISPATCH:
        // a sysroot routine at foundational types "can dispatch into no user
        // code", so no user panic edge hides behind it. That is true and it is
        // not the same as "cannot panic". `_print`'s broken pipe, `env::args`'s
        // invalid unicode and `fs::read_to_string`'s IO error are std's own
        // DEFINED behaviour reacting to the environment — the 2026-07-25 ruling's
        // "vanilla Rust semantics" case. A zero divisor is not: it is a Rust
        // SAFETY obligation about the caller's own value, one Trust models
        // exactly and discharges routinely one line away.
        //
        // THE AUTHORITY IS NOT NEW, and reusing it is the point rather than a
        // second name list. `is_panicking_primitive_int_div_method` is the same
        // predicate the decline above this function's caller consults, minted on
        // 2026-08-11 for this very fixture, and the bridge's own comment says
        // these spellings "PANIC on a zero divisor". The bundle lane declines
        // them so the call becomes an ABSENT callee and MINTS the fail-closed
        // assumption row; tolerating that row here threw the minted obligation
        // straight back. Both consumers of one decision now agree.
        //
        // SCOPE. Only the deliberately-unbundled division family. `saturating_add`,
        // `checked_div`, `str::parse::<u64>` and `env::args` are untouched, and the
        // policy_b run-pass pins that depend on them stay green.
        // The ROOT body is user code: `HashTableCredit::Declared`, so a hashbrown
        // callee or a top-level hashbrown type is never vanilla here.
        // Trust (W4 fix round 1, 2026-09-25): std `VecDeque`'s caller-value members
        // that no call-site lane charges (`insert`, `split_off`, `rotate_*`,
        // `drain`, ...) are excluded HERE, at the ROOT body's own call sites, and not
        // inside `callee_is_vanilla_sysroot`, which the bundle walk also asks: std
        // calls them with its own validated arguments, and asking there refused the
        // TOTAL `swap_remove_back` (measured, when `swap` was on the list). `swap`,
        // `range`, `range_mut`, `insert_mut` and `d[i]` are NOT excluded: vcgen's
        // `collection_range` charges them at the call site, so a guard discharges
        // them (W4 salvage 2026-09-28, reconciled with 92e7829ca5). See
        // `trust_vcgen::callee_is_root_call_caller_value_panic`.
        let by_type = callee_is_vanilla_sysroot(
            tcx,
            def_id,
            generic_args,
            &name,
            user_global_allocator,
            caller_value_charged,
            &mut memo,
            HashTableCredit::Declared,
        );
        // Trust (VANILLA-REACH-1, 2026-10-27): see `vanilla_reach`.
        let by_reach = !by_type
            && reach_admission
            && !bb.is_cleanup
            && vanilla_reach::callee_is_vanilla_sysroot_by_reach(
                tcx,
                body,
                reach_typing_env,
                func,
                args,
                callee_vanilla_exclusions_pass(
                    tcx,
                    def_id,
                    &name,
                    user_global_allocator,
                    caller_value_charged,
                    HashTableCredit::Declared,
                ),
                &name,
            );
        let vanilla =
            (by_type || by_reach) && !trust_vcgen::callee_is_root_call_caller_value_panic(&name);
        if env_flag_enabled("TRUST_VANILLA_DEBUG") {
            eprintln!(
                "[VANILLA_LEDGER] vanilla={vanilla} callee=`{name}`{}",
                if caller_value_charged { " (index precondition charged here)" } else { "" }
            );
        }
        out.entry(name).and_modify(|v| *v = *v && vanilla).or_insert(vanilla);
    }
    out
}

/// The VANILLA verdict for ONE callee, factored out of
/// [`function_vanilla_sysroot_callees`] so the bundle walk can reach the same
/// decision with the same inputs. `name` is the ledger key, needed only by the
/// deliberately-unbundled division family test, which is keyed on the method
/// spelling.
///
/// Every clause is the original one, in the original order; this is a move, not
/// a change.
///
/// Trust (W4 HASHMAP redo, 2026-09-25): `credit` says whose call site this is
/// ([`HashTableCredit`]). At a USER call site (`Declared`) the callee must be in
/// `core`/`alloc`/`std` exactly as before. At a call site inside an authentic
/// std/core/alloc body (`StdSite`) the callee may also be in the crate behind
/// std's hash tables (`hashbrown`, by structural identity), and a hashbrown type
/// counts wherever it appears; its caller-value panics are excluded by identity
/// ([`callee_is_hash_table_caller_value_panic`], against the pinned census in
/// `trust_vcgen::std_hash_table_census`).
fn callee_is_vanilla_sysroot<'tcx>(
    tcx: TyCtxt<'tcx>,
    def_id: DefId,
    generic_args: ty::GenericArgs<'tcx>,
    name: &str,
    user_global_allocator: bool,
    // Trust (VEC-INSERT, 2026-09-25): the caller charged this call's caller-value
    // panic itself (`def_is_std_vec_index_mutator` at a charged block), so the
    // caller-value exclusion below does not apply to it.
    caller_value_charged: bool,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
    credit: HashTableCredit,
) -> bool {
    callee_vanilla_exclusions_pass(
        tcx,
        def_id,
        name,
        user_global_allocator,
        caller_value_charged,
        credit,
    ) && generic_args.types().all(|t| ty_is_foundational_in(tcx, t, memo, credit))
        && tcx
            .fn_sig(def_id)
            .instantiate(tcx, generic_args)
            .skip_binder()
            .inputs()
            .iter()
            .all(|t| ty_is_foundational_in(tcx, *t, memo, credit))
}

/// Trust (VANILLA-REACH-1, 2026-10-27): every conjunct of
/// [`callee_is_vanilla_sysroot`] EXCEPT its two type conjuncts (the type
/// arguments and the parameter types are foundational), moved here unchanged so
/// `vanilla_reach::callee_is_vanilla_sysroot_by_reach` asks the same exclusions
/// before it replaces the type conjuncts with CALL-REACH-1's closure.
fn callee_vanilla_exclusions_pass(
    tcx: TyCtxt<'_>,
    def_id: DefId,
    name: &str,
    user_global_allocator: bool,
    caller_value_charged: bool,
    credit: HashTableCredit,
) -> bool {
    let deliberately_unbundled_panicking_div = name
        .rsplit("::")
        .next()
        .is_some_and(trust_ir_bridge::is_panicking_primitive_int_div_method);
    // Trust (2026-09-19): the rest of the "panics on a CALLER-SUPPLIED value"
    // family, consulted exactly as the division carve-out above is. The class's
    // argument is that the callee's panic is "std's own DEFINED behaviour
    // reacting to the environment"; an out-of-range index or a too-small buffer
    // is not that, it is a Rust safety obligation about the caller's own value.
    //
    // WHY HERE AND NOT ONLY IN VCGEN. `unsupported.rs` already stamps a
    // `Call::…::panic-freedom-unverified` row for these — but on the CALLER's
    // MIR, so it sees only calls in a body vcgen analyses. Measured 2026-09-19:
    // `core::char::methods::encode_utf8_raw`, reached through core's own bundled
    // `fmt::Write::write_char`, is invisible to that lane and was being refused
    // only because it was absent from this ledger. Consulting the same
    // predicates here covers the bundled case without a second name list.
    let known_caller_value_panic =
        trust_vcgen::callee_is_known_caller_value_panic(&name) && !caller_value_charged;
    // Trust (2026-09-19): the INEXACTLY-ROUNDED float intrinsics are not in the
    // class. They are panic-free, so nothing about panics would ever catch them,
    // and the class says nothing about the property they actually fail:
    // determinism. std's own docs — "The precision of this function is
    // non-deterministic ... can even differ within the same execution from one
    // invocation to the next" — are why `trust-mir-extract` deliberately leaves
    // them UNMARKED, and why
    // `tests/ui/trust/float_inexact_intrinsic_methods_stay_refused.rs` refuses
    // them.
    //
    // THE LIST IS EXPLICIT ON PURPOSE, and `convert.rs`'s
    // `exact_ieee754_intrinsics_are_marked_and_the_inexact_siblings_are_not`
    // says why: several share a prefix or a width suffix with an ADMITTED
    // sibling (`sqrt*` and `fma*` are exact and stay in the class), so any
    // `ends_with("f64")` / `starts_with("pow")` rule is wrong.
    //
    // KEYED ON THE FAMILY, NOT ON "unmarked". An earlier cut excluded every
    // intrinsic without the authenticated marker, which also caught
    // `std::hint::black_box` — total, deterministic, merely not VALUE-modeled —
    // and broke `wrapping_binop_opt_level.rs`. The marker means "exactly
    // value-modeled", which is a different question from this one.
    // Upstream 1.101: `sin`/`cos`/`exp`/`exp2`/`log`/`log2`/`log10` are single
    // GENERIC intrinsic items (the per-width items are gone), so the family
    // names below `powf32` are keyed on the generic item names rustc reports.
    let inexact_float_intrinsic = tcx.intrinsic(def_id).is_some_and(|i| {
        matches!(
            i.name.as_str(),
            "sin"
                | "cos"
                | "exp"
                | "exp2"
                | "log"
                | "log2"
                | "log10"
                | "powf32"
                | "powf64"
                | "powif32"
                | "powif64"
                | "fmuladdf32"
                | "fmuladdf64"
        )
    });
    // Trust (W4 HASHMAP, 2026-09-25; generalized r2 2026-09-27): the caller-value
    // panics behind std's hash tables that no call-site recognizer charges — the
    // DISJOINT-KEY lookups ("duplicate keys found" when two of the CALLER's keys
    // are equal) AND the KEY-EQUIVALENCE asserts ("key used for Entry creation is
    // not equivalent to the one used for insertion", reached from std's
    // `HashSet::get_or_insert_with` with the CALLER's `f`). The r1 comment here
    // called the disjoint lookups "the one caller-value panic family behind std's
    // hash tables"; its prober refuted that with nine programs. The complete list
    // is the census `trust_vcgen::std_hash_table_census`, pinned to the hashbrown
    // version the sysroot builds. See [`callee_is_hash_table_caller_value_panic`].
    let hash_table_caller_value_panic = callee_is_hash_table_caller_value_panic(tcx, def_id);
    // Trust (upstream 1.101): the StdSite hash-table credit is the one
    // verdict this ledger spends BY RENDERED NAME (the ledger and the row it
    // judges are both keyed on the callee path string), so it alone charges
    // name uniqueness: while another crate of this compilation shares std's
    // private table crate's name, a rendered `hashbrown::…` key cannot tell
    // the two apart and the credit is withdrawn
    // (`vanilla_hashbrown_name_shadowed_stays_closed.rs`). The structural
    // identity itself (`def_is_in_std_hash_table_crate`, foundational types)
    // is NOT withdrawn: std's own `HashMap` stays foundational while the
    // namesake sits unused in the graph
    // (`hashbrown_namesake_dep_not_vanilla.rs#namesake_loaded_std_map_ok`).
    let callee_crate_is_credited = trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def_id)
        || (credit == HashTableCredit::StdSite
            && trust_mir_extract::def_is_in_std_hash_table_crate(tcx, def_id)
            && !trust_mir_extract::crate_name_is_shared(tcx, def_id.krate, |_| false));
    !user_global_allocator
        && !deliberately_unbundled_panicking_div
        && !known_caller_value_panic
        && !inexact_float_intrinsic
        && !hash_table_caller_value_panic
        && callee_crate_is_credited
}

/// Trust (W4 HASHMAP, 2026-09-25; generalized r2 2026-09-27): does `def_id` panic
/// on the CALLER's values behind std's hash tables — one of the items the census
/// (`trust_vcgen::std_hash_table_census`, pinned to the hashbrown version
/// `library/Cargo.lock` builds) marks as excluded by identity?
///
///  * The DISJOINT-KEY lookups: std's `HashMap::get_disjoint_mut` /
///    `get_disjoint_unchecked_mut`, and every `get_disjoint_*` / `get_many_*` item
///    of the crate behind std's tables. The checked forms PANIC "duplicate keys
///    found" when two of the caller's keys are equal (the unchecked forms are UB).
///  * The KEY-EQUIVALENCE asserts: std's `HashSet::get_or_insert_with` (nightly
///    `hash_set_entry`), which hands the caller's `f(value)` to hashbrown's
///    `VacantEntryRef::insert_entry_with_key` and its `assert!` "key used for Entry
///    creation is not equivalent to the one used for insertion" (`map.rs:4735`);
///    and in the crate behind the tables, `get_or_insert_with`,
///    `insert_entry_with_key`, `insert_with_key`, `replace_key` (`map.rs:3823`)
///    and its `Index` impl's `index` (`map.rs:2101`, never called by std).
///    MEASURED on the redo's r1 (`9eadf44e0`): `set.get_or_insert_with(q,
///    str::to_ascii_uppercase)` built rc=0 (a sysroot fn item as `F` made the root
///    call vanilla, and the hashbrown callee was credited at the std call site
///    without its body ever being walked) and panicked; nine probes, incl. `-O`,
///    `char`/`u8`/`[u8]` sets, and a method of a local struct.
///
/// Each is an obligation about the caller's own values — the shape of the
/// division and index-mutator carve-outs in [`callee_is_vanilla_sysroot`] — not
/// std's defined behaviour reacting to its environment, and no vcgen call-site
/// recognizer charges it. Excluding it makes the call non-vanilla, so its
/// absent-callee row stays fatal. The other census sites are the allocation
/// lane's (capacity overflow), an abort (`handle_alloc_error`), or dead.
///
/// Decided on identity: the item's own NAME (`tcx.opt_item_name`, never a
/// rendering) AND its owner. In `core`/`alloc`/`std` only an INHERENT method of
/// std's `HashMap` / `HashSet` (their diagnostic items) matches, so core's
/// `<[T]>::get_disjoint_mut` (a `Result`, no panic) is not excluded. In the crate
/// behind std's tables (`def_is_in_std_hash_table_crate`, structural) every listed
/// name is excluded, over-inclusively, and only ever as a refusal. Cost, disclosed:
/// a `get_or_insert_with` whose `f` IS key-equivalent (`str::to_owned`) is refused
/// too.
fn callee_is_hash_table_caller_value_panic(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    let Some(name) = tcx.opt_item_name(def_id) else { return false };
    let name = name.as_str();
    if trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def_id) {
        let Some(owner) = tcx.inherent_impl_of_assoc(def_id).and_then(|impl_did| {
            tcx.type_of(impl_did).instantiate_identity().skip_normalization().ty_adt_def()
        }) else {
            return false;
        };
        return (tcx.is_diagnostic_item(sym::HashMap, owner.did())
            && trust_vcgen::std_hash_map_method_panics_on_caller_value(name))
            || (tcx.is_diagnostic_item(sym::HashSet, owner.did())
                && trust_vcgen::std_hash_set_method_panics_on_caller_value(name));
    }
    trust_vcgen::std_hash_table_crate_item_panics_on_caller_value(name)
        && trust_mir_extract::def_is_in_std_hash_table_crate(tcx, def_id)
}

/// Trust (2026-09-19): record ONE bundle-walk call site's vanilla verdict.
///
/// The ledger [`function_vanilla_sysroot_callees`] builds is keyed on the ROOT
/// body's call sites, while the bridge charges an absent-callee row for a callee
/// absent ANYWHERE in the bundle — so a callee reached only through a bundled
/// member has no entry and "absent from the ledger is not tolerated" fails it
/// closed. Measured on `pub fn f(v: &mut Vec<u32>) { v.sort(); }`, whose ledger
/// holds exactly `Vec::deref_mut` and `<[u32]>::sort` while the charged row names
/// `alloc::slice::stable_sort::<..>`. The 80-program sweep ranks this the most
/// frequent blocker in ordinary Rust.
///
/// The bundle enqueue walk visits precisely the call sites the bridge can charge
/// a row for, and already computes the ledger's own key, so the population is
/// exactly right and no second traversal has to be kept in step with this one.
/// The verdict is the same [`callee_is_vanilla_sysroot`] the root scan uses —
/// including its panic-family and unvouched-intrinsic exclusions, which is what
/// makes widening the coverage safe rather than fail-open.
///
/// Trust (W4 HASHMAP redo, 2026-09-25): `caller_def_id` is the body the call site
/// sits in. When it is an authentic std/core/alloc body the verdict is taken in
/// [`HashTableCredit::StdSite`] mode — the hashbrown value or callee there is the
/// one std's own table code chose — and otherwise (the root body, a bundled local
/// generic, a build-declared dependency body) in `Declared` mode, exactly as the
/// root scan decides it.
fn record_bundle_walk_vanilla_callee<'tcx>(
    tcx: TyCtxt<'tcx>,
    caller_def_id: DefId,
    callee_def_id: DefId,
    gen_args: ty::GenericArgs<'tcx>,
    name: String,
    // Trust (VEC-INSERT, 2026-09-25): see `native_trust_ir_monomorphic_foreign_callees`.
    caller_value_charged: bool,
    // Trust (VANILLA-REACH-1, 2026-10-27): the call site itself — the walked body,
    // its typing environment, the callee operand and the arguments — when the
    // reach admission (`vanilla_reach`) may be asked of it; `None` keeps the type
    // rule alone (the hash-table crate's StdSite arm).
    reach_site: Option<(
        &Body<'tcx>,
        ty::TypingEnv<'tcx>,
        &rustc_middle::mir::Operand<'tcx>,
        &[Spanned<rustc_middle::mir::Operand<'tcx>>],
    )>,
) {
    let user_global_allocator = crate_graph_registers_user_global_allocator(tcx);
    let mut memo: FxHashMap<Ty<'tcx>, bool> = FxHashMap::default();
    let credit = if call_site_is_in_authentic_std_body(tcx, caller_def_id) {
        HashTableCredit::StdSite
    } else {
        HashTableCredit::Declared
    };
    let by_type = callee_is_vanilla_sysroot(
        tcx,
        callee_def_id,
        gen_args,
        &name,
        user_global_allocator,
        caller_value_charged,
        &mut memo,
        credit,
    );
    let vanilla = by_type
        || reach_site.is_some_and(|(body, typing_env, func, args)| {
            vanilla_reach::callee_is_vanilla_sysroot_by_reach(
                tcx,
                body,
                typing_env,
                func,
                args,
                callee_vanilla_exclusions_pass(
                    tcx,
                    callee_def_id,
                    &name,
                    user_global_allocator,
                    caller_value_charged,
                    credit,
                ),
                &name,
            )
        });
    if env_flag_enabled("TRUST_VANILLA_DEBUG") {
        eprintln!("[VANILLA_BUNDLE] vanilla={vanilla} credit={credit:?} callee=`{name}`");
    }
    with_crate_verification_state(tcx.sess, |state| {
        state
            .bundle_walk_vanilla_callees
            .entry(name)
            .and_modify(|v| *v = *v && vanilla)
            .or_insert(vanilla);
    });
}

/// Trust (W4 HASHMAP redo, 2026-09-25): is `caller_def_id` — the body a
/// bundle-walk call site sits in — authentic `core`/`alloc`/`std` code? Both
/// authentications, lang-item ownership (the bundle admission's own test) AND
/// artifact residency, must hold; a local, dependency or hashbrown body answers
/// `false`. hashbrown bodies are never bundled, so their call sites are never
/// visited at all.
fn call_site_is_in_authentic_std_body(tcx: TyCtxt<'_>, caller_def_id: DefId) -> bool {
    !caller_def_id.is_local()
        && crate_is_authentic_foundational(tcx, caller_def_id.krate)
        && trust_mir_extract::def_is_in_real_sysroot_crate(tcx, caller_def_id)
}

/// The bundle walk's recorded verdicts (see [`record_bundle_walk_vanilla_callee`]).
fn bundle_walk_vanilla_callees(sess: &Session) -> FxHashMap<String, bool> {
    with_crate_verification_state(sess, |state| state.bundle_walk_vanilla_callees.clone())
}

/// The callee path an absent-callee row names, or `None` for any other row.
/// Same parse as the adversarial-witness gate (`ABSENT_CALLEE_ASSUMPTION_CALLEE_PREFIX`).
fn absent_callee_path_of_row(row: &TransportObligationResult) -> Option<&str> {
    let rest = row.description.split(ABSENT_CALLEE_ASSUMPTION_CALLEE_PREFIX).nth(1)?;
    rest.split('`').next()
}

/// Trust (policy B as ruled, 2026-09-14): is this an UNPROVED absent-callee row
/// whose callee `function_vanilla_sysroot_callees` judged vanilla? Scoped to the
/// fatal absent-callee row class alone — drop glue, extern `fmt` dispatch, and
/// expected-absent rows keep their own treatment untouched. A row naming a
/// callee the ledger has no entry for (a name the bridge rendered differently
/// from the extractor) fails closed.
fn transport_row_is_vanilla_sysroot_absent_callee(
    row: &TransportObligationResult,
    vanilla: &FxHashMap<String, bool>,
) -> bool {
    let unproved = transport_row_is_unproved_absent_callee(row);
    let path = absent_callee_path_of_row(row);
    let verdict = unproved && path.is_some_and(|path| vanilla.get(path).copied().unwrap_or(false));
    // Trust (diagnostic, 2026-09-18): this decision has exactly three outcomes
    // and the compiler's notes distinguish none of them — a row can be refused
    // because it is not an absent-callee row at all, because its callee is
    // ABSENT FROM THE LEDGER (the ledger is built from the ROOT body's call
    // sites, so a callee reached only through a bundled member has no entry and
    // fails closed), or because the callee IS in the ledger and was judged
    // NOT vanilla. Those three need different fixes and look identical from
    // outside: `v.sort()` and `v.sort_unstable()` print byte-identical
    // verification reports and differ only here. Print which one happened.
    if env_flag_enabled("TRUST_VANILLA_DEBUG") {
        let state = match (unproved, path) {
            (false, _) => "not-an-absent-callee-row".to_string(),
            (true, None) => "absent-callee-row-with-no-parsable-callee".to_string(),
            (true, Some(path)) => match vanilla.get(path) {
                None => format!("NOT-IN-LEDGER callee=`{path}`"),
                Some(true) => format!("vanilla callee=`{path}`"),
                Some(false) => format!("NOT-VANILLA callee=`{path}`"),
            },
        };
        eprintln!("[VANILLA_ROW] tolerated={verdict} {state}");
    }
    verdict
}

/// Trust (policy B, runtime-value println — 2026-09-13): the POSITIVE soundness
/// discriminator that keeps a USER `Display`/`Debug` fatal while a foundational
/// one (`i32`, `str`, …) may be tolerated.
///
/// WHY THIS IS NECESSARY, and why the reset architecture forces it here. When a
/// runtime value is formatted, the only member the native bundle refuses to lower
/// is still the foundational std `ReentrantLock` accounting reached through
/// `println!` — so `native_lowering_failure_is_bundled_std_member_assert_gap_only`
/// (removed 2026-09-29 with the lowering-failure tolerance; see
/// `runtime_checked_std_member`) held identically for `println!("{}", double(21))` (safe `i32`) and
/// `println!("{}", user_value)` (an arbitrary user `Display` that may `panic!`).
/// The user `Display::fmt` body IS bundled and DOES generate panic obligations,
/// but the public inventory is rebuilt ROOT-scoped after lowering
/// (`reset_native_trust_ir_proof_inventory_to_public_bundle`), so by the time the
/// tolerance is decided `artifacts.results`/`transport_results` are empty and the
/// native run summary is `Empty` for BOTH — none of the other gate booleans can
/// tell them apart. The ONLY surviving discriminator is `main`'s own MIR: it
/// packs each formatted value with `core::fmt::rt::Argument::new_*::<T>(&v)`, and
/// `T` names the formatted type. A CONSTANT argument folds to
/// `Arguments::from_str_nonconst` with no packer at all (vacuously foundational).
///
/// So: the tolerance may fire only when EVERY `Argument::new_*` packer in this
/// body formats a `ty_is_foundational_display` type. Any user (or forwarding)
/// type makes this `false`, and the caller stays fatal — the same boundary
/// `is_display_total_std_ty` draws for `format!`, applied one layer earlier at
/// the packer instead of at a `fmt::write` transport row (which the reset erased).
///
/// Opt-level note: at `-Copt-level>=2` the packer call may be inlined away, but a
/// runtime-value `println!` there carries its own unsupported `NonNull` cast rows
/// that deny tolerance through `own_rows_permit_tolerance` first, so no packer is
/// needed to keep it fatal and no opt-level hole is opened. At `-O0`/`-O1` the
/// packer call is present verbatim (measured), which is where this gate binds.
fn function_format_args_all_foundational_display<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> bool {
    for bb in body.basic_blocks.iter() {
        let Some(terminator) = &bb.terminator else { continue };
        let (TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. }) =
            &terminator.kind
        else {
            continue;
        };
        let Some((def_id, generic_args)) = func.const_fn_def() else { continue };
        if is_fmt_rt_argument_packer(tcx, def_id) {
            // Every type argument of the packer (its sole one is the formatted
            // `T`) must be a foundational-Display type — OR its formatting impl
            // must carry a verdict of its own (see
            // `fmt_target_sink_basis`); one unvouched user type refuses.
            for ty in generic_args.types() {
                if ty_is_foundational_display(tcx, ty) {
                    continue;
                }
                match fmt_target_sink_basis(tcx, body, def_id, ty) {
                    Some(fmt_termination_dyn::SinkBasis::Absolute) => continue,
                    // Trust (D1 increment 1): a formatter that is panic-free only
                    // RELATIVE TO its writer is safe here only if this body's
                    // `fmt::Arguments` reach nothing but a std sink that supplies
                    // the writer (`_print`/`_eprint`/`alloc::fmt::format`).
                    Some(fmt_termination_dyn::SinkBasis::WriterRelative)
                        if fmt_writer_relative::body_formats_only_into_recognized_sinks(
                            tcx, body,
                        ) =>
                    {
                        continue;
                    }
                    _ => return false,
                }
            }
            continue;
        }
        // Trust (HOLE — hidden-packer dispatch, 2026-09-14): `x.to_string()` is
        // `<T as ToString>::to_string(&x)`, whose `new_display::<T>` packer lives
        // INSIDE the alloc `ToString` blanket impl body — OUT of this function's
        // MIR — so the packer scan above never sees `T`. Read `T` (the Self type)
        // from the dispatch call's own generic args and require it foundational,
        // so `d.to_string()` of a non-foundational `Display` refuses exactly like
        // `format!("{}", d)`/`println!("{}", d)` (whose packer IS in this body).
        // A foundational `Self` (`41i32.to_string()`, `"s".to_string()`,
        // `String::to_string`) still passes. This is the general shape for any fmt
        // entry that hides its packer in a foreign body; a new such entry gets the
        // same treatment (read its formatted type from the call, never the row,
        // which cannot carry the type).
        //
        // Trust (2026-09-21): the arm now composes the SAME disjunction the packer
        // arm above does. The comment on this hole says it exists so `d.to_string()`
        // "refuses exactly like `format!(\"{}\", d)`/`println!(\"{}\", d)`" -- but
        // on 2026-09-19 the packer arm gained a fallback to the formatting impl's
        // OWN verdict, and this arm did not, so the two stopped agreeing in the
        // direction the comment promises: `format!("{}", d)` of a verified user
        // `Display` compiles and `d.to_string()` of the very same type does not.
        // Matching them is the whole change; the bar is the one four consumers
        // already share, and a `Display` impl that can panic still fails it.
        if callee_is_to_string_dispatch(tcx, def_id)
            && generic_args.types().next().is_some_and(|ty| {
                !ty_is_foundational_display(tcx, ty)
                    && !tcx.get_diagnostic_item(sym::Display).is_some_and(|display_trait| {
                        fmt_trait_impl_is_verified_panic_free(tcx, body, display_trait, ty)
                    })
            })
        {
            return false;
        }
    }
    true
}

/// Trust (HOLE — hidden-packer dispatch, 2026-09-14): is `def_id` the alloc
/// `ToString::to_string` method — the dispatch that formats its `Self` type
/// inside the blanket impl body, hiding the `new_display::<Self>` packer from a
/// caller-MIR scan? Identified by item name `to_string` plus the AUTHENTICATED
/// (lang-item-owning) foundational trait named `ToString` — the same
/// crate-identity + item-name shape `total_std_iterator_ty` uses for
/// `DoubleEndedIterator`, so a user trait merely named `ToString` (in a
/// non-authentic crate) fails closed. Never a `--crate-name` string.
fn callee_is_to_string_dispatch(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    if tcx.opt_item_name(def_id) != Some(rustc_span::sym::to_string) {
        return false;
    }
    // Resolve the trait whether `def_id` is the trait method (`trait_of_assoc`)
    // or the blanket/specialized IMPL method (`trait_impl_of_assoc` + the impl's
    // trait ref) — the same two-path resolution `total_std_iterator_ty` uses.
    let Some(trait_did) = tcx.trait_of_assoc(def_id).or_else(|| {
        tcx.trait_impl_of_assoc(def_id).map(|impl_did| {
            tcx.impl_trait_ref(impl_did).instantiate_identity().skip_normalization().def_id
        })
    }) else {
        return false;
    };
    !trait_did.is_local()
        && crate_is_authentic_foundational(tcx, trait_did.krate)
        && tcx.opt_item_name(trait_did).is_some_and(|n| n.as_str() == "ToString")
}

/// Trust (2026-09-19): the formatting trait a `fmt::rt::Argument` packer bounds
/// its formatted type parameter by — `Debug` for `new_debug`, `Display` for
/// `new_display`, `LowerHex` for `new_lower_hex`, and so on — or `None`.
///
/// READ OFF THE PACKER'S OWN SIGNATURE, never a name-to-trait table. The packer
/// recognizer above is deliberately a `new_` PREFIX so a future upstream
/// `new_foo::<T>` is caught rather than skipped; a table keyed on today's names
/// would re-open exactly that hole, silently answering `None` for the new packer
/// and — through this predicate's caller — quietly admitting it. `predicates_of`
/// cannot go stale that way: `pub const fn new_debug<T: Debug + ?Sized>` carries
/// its own bound.
///
/// FAIL-CLOSED in three directions: a packer with no trait bound on its own type
/// parameter, one with TWO different non-`Sized` bounds (ambiguous — which impl
/// does the value reach?), and a bound whose self type is not the packer's
/// parameter all yield `None`, which refuses.
fn fmt_packer_bound_trait(tcx: TyCtxt<'_>, packer_def_id: DefId) -> Option<DefId> {
    let sized = tcx.lang_items().sized_trait();
    let mut found: Option<DefId> = None;
    for (clause, _) in tcx.clauses_of(packer_def_id).clauses.iter().copied() {
        let ty::ClauseKind::Trait(pred) = clause.kind().skip_binder() else { continue };
        // Only a bound on the packer's OWN type parameter names the trait the
        // formatted value is reached through.
        if !matches!(pred.self_ty().kind(), ty::Param(_)) {
            continue;
        }
        let trait_def_id = pred.trait_ref.def_id;
        if sized == Some(trait_def_id) {
            continue;
        }
        match found {
            Some(prev) if prev != trait_def_id => return None,
            _ => found = Some(trait_def_id),
        }
    }
    found
}

/// Trust (2026-09-19): does the formatting impl this packer's value will reach
/// carry a panic-freedom verdict of its own?
///
/// THE GAP THIS CLOSES, measured. `function_format_args_all_foundational_display`
/// decides on `ty_is_foundational_display`, whose real proposition is "is the
/// formatted TYPE a sysroot type" — a statement about the type, never about the
/// impl and never about any verdict. So
///
/// ```text
///  impl fmt::Debug for S { fn fmt(..) -> fmt::Result { Ok(()) } }
///  fn main() { println!("{:?}", S); }
/// ```
///
/// was refused with "a value is formatted through a user `Display`/`Debug`
/// implementation whose panic-freedom was not established" while
/// `TRUST_PF_REG_TRACE=1` printed `established=true` for that very impl, in the
/// same compilation, BEFORE the caller was verified. The gate was not short of
/// evidence; it never asked. Pinned by
/// `tests/open-dispatch-ladder/pf1_println_of_a_provable_user_debug_impl.rs`.
///
/// THE BAR IS THE SHARED ONE. `dyn_target_is_verified_panic_free` is the same
/// evidence bar Φ's per-impl discharge, the `dyn` case split and the
/// `fmt::Write::write_fmt` reduction use, and its doc says why it is shared: "a
/// hand-copied evidence ledger is exactly how a soundness conjunct gets silently
/// dropped." It carries the `#[trust::skip]`/`#[trust::assume_total]` refusals,
/// the LOCAL-only requirement, the authored-clause refusal, the query-cycle and
/// in-progress bails, and the assumption-root gate. Nothing is re-derived here.
///
/// WHY THE IMPL'S OWN VERDICT SUFFICES. It is a whole-body verdict, so it already
/// covers what the body forwards to: `<S as Debug>::fmt` for a struct holding a
/// `Vec<Other>` calls `<Vec<Other> as Debug>::fmt` at a USER type, which is not
/// vanilla, so that impl fails its OWN verification and is never established.
/// The nesting is fail-closed by the same machinery, not by a second walk here.
///
/// WHAT STAYS REFUSED, and each has a rail: a panicking impl (it fails its own
/// verification, `pf2`); a type PARAMETER, which resolves to no body (`pf4`); and
/// a DEPENDENCY's impl outside the declared bundling scope — rmeta carries no
/// per-function verdict and never will (D4), so `xcrate/user_fmt_dep` stays red.
/// Since D4-A a declared dependency's impl with encoded MIR is RE-DERIVED here
/// through the same bar (`foreign_rederivation`), and still needs error
/// transparency (`xcrate/user_fmt_dep_declared`, `xcrate_fmt_dep.rs`).
/// The `ToString` hidden-packer path above is deliberately NOT given this
/// fallback: its formatted type is read off the dispatch call rather than a
/// packer, so there is no packer signature to take the trait from.
fn fmt_target_sink_basis<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    packer_def_id: DefId,
    formatted: Ty<'tcx>,
) -> Option<fmt_termination_dyn::SinkBasis> {
    // Trust (D1 increment 1): returns WHICH bar the formatter passed, so the packer
    // arm can hold a writer-relative formatter to its sink (see the caller).
    let trait_def_id = fmt_packer_bound_trait(tcx, packer_def_id)?;
    fmt_trait_impl_sink_basis(tcx, body, trait_def_id, formatted)
}

/// Trust (D1 increment 1): DIAGNOSTIC ONLY — decides nothing. When the packer arm
/// refused a formatter that passed only the WRITER-RELATIVE bar because this body
/// hands its `fmt::Arguments` to a consumer that is not a std formatting sink
/// (`fmt_writer_relative::body_formats_only_into_recognized_sinks`), the note that
/// says so; without it the refusal would read "panic-freedom was not
/// established" for an impl whose conditional verdict WAS established.
fn writer_relative_sink_refusal_note<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> Option<String> {
    if fmt_writer_relative::body_formats_only_into_recognized_sinks(tcx, body) {
        return None;
    }
    for bb in body.basic_blocks.iter() {
        let Some(terminator) = &bb.terminator else { continue };
        let (TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. }) =
            &terminator.kind
        else {
            continue;
        };
        let Some((def_id, generic_args)) = func.const_fn_def() else { continue };
        if !is_fmt_rt_argument_packer(tcx, def_id) {
            continue;
        }
        for ty in generic_args.types() {
            if ty_is_foundational_display(tcx, ty) {
                continue;
            }
            if fmt_target_sink_basis(tcx, body, def_id, ty)
                == Some(fmt_termination_dyn::SinkBasis::WriterRelative)
            {
                let label = with_no_trimmed_paths!(ty.to_string());
                return Some(format!(
                    "`{label}`'s formatting impl is panic-free only relative to its \
                     `Formatter`'s writer (the D1 writer-relative class), and this body hands \
                     its `fmt::Arguments` to a consumer that is not a std formatting sink \
                     (`println!`/`eprintln!`/`format!`), so the writer that impl would run \
                     against is not known to be std's. Format it through a std sink, or keep \
                     this an honest gap"
                ));
            }
        }
    }
    None
}

/// Trust (2026-09-21): [`fmt_target_sink_basis`] (formerly
/// `fmt_target_is_verified_panic_free`) with the formatting trait supplied by
/// the CALLER instead of read off a packer's bound.
///
/// The split exists because the packer route cannot serve the `to_string` route.
/// `fmt_packer_bound_trait` reads `predicates_of(packer_def_id)` for the bound on
/// the packer's own type parameter -- `Display` for `new_display`, `Debug` for
/// `new_debug`. Handed `ToString::to_string` it finds `Self: ToString`, and
/// `ToString` has no `fmt` associated item, so the lookup below returns `None`
/// and the whole check answers `false` no matter what the impl's verdict is.
/// Reusing the packer entry point for `to_string` would therefore have been
/// INERT -- visible in the diff, dead at runtime, which is a failure mode this
/// repo has paid for before. The `to_string` caller names `Display` directly.
fn fmt_trait_impl_is_verified_panic_free<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    trait_def_id: DefId,
    formatted: Ty<'tcx>,
) -> bool {
    // Trust (D1 increment 1): the `to_string` arm and `main`'s `Termination` check
    // read this; both are sinks whose writer is std's by construction (`String`,
    // stderr), so either basis serves them.
    fmt_trait_impl_sink_basis(tcx, body, trait_def_id, formatted).is_some()
}

/// Trust (D1 increment 1): [`fmt_trait_impl_is_verified_panic_free`] with the
/// basis it passed on named (`fmt_termination_dyn::SinkBasis`).
fn fmt_trait_impl_sink_basis<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    trait_def_id: DefId,
    formatted: Ty<'tcx>,
) -> Option<fmt_termination_dyn::SinkBasis> {
    let method_def_id = tcx
        .associated_items(trait_def_id)
        .in_definition_order()
        .find(|item| item.opt_name() == Some(rustc_span::sym::fmt))
        .map(|item| item.def_id)?;
    // The formatting method's generics are `Self` only, so the formatted type is
    // already the demanded instantiation. A type PARAMETER leaves a non-region
    // param here and must never be handed to `try_resolve`.
    let args = tcx.mk_args(&[formatted.into()]);
    if args.has_non_region_param() {
        return None;
    }
    let Ok(Some(instance)) =
        ty::Instance::try_resolve(tcx, ty::TypingEnv::fully_monomorphized(), method_def_id, args)
    else {
        return None;
    };
    // A `Virtual` or shim target names no body this bar can check.
    if !matches!(instance.def, ty::InstanceKind::Item(_)) {
        return None;
    }
    // Trust (D1 increment 0, 2026-09-23): BOTH consumers of this predicate (the
    // packer arm and the `to_string` arm) are sinks that PANIC when a formatter
    // returns `Err` while its writer did not fail, so panic-freedom alone is not
    // enough: `impl Display for E { fn fmt(..) { Err(fmt::Error) } }` passed the
    // bar and `println!`/`format!`/`to_string` of it built rc=0 and exited 101.
    // Error transparency is a REFUSAL-ONLY conjunct; the shared bar is untouched.
    // Trust (D1 residual, 2026-09-24): the bar AND ET, as ONE predicate shared
    // with `main`'s dynamic `Termination` reach check (`fmt_termination_dyn`).
    // Trust (D1 increment 1): now `(bar || writer-relative bar) && ET`, with the
    // basis returned.
    fmt_termination_dyn::formatter_sink_basis(tcx, instance, body.source.def_id())
}

/// Is `def_id` a `core::fmt::rt::Argument::new_*` value-packing constructor (the
/// `format_args!` machinery)? Crate-anchored to `core` so a user
/// `mycrate::Argument::new_display` fails closed, and matched against the exact
/// packer method names (kept in lockstep with
/// `trust_ir_bridge`'s `::Argument::new_*` list; `from_usize`/`from_str` are NOT
/// packers of a formatted value and are excluded).
fn is_fmt_rt_argument_packer<'tcx>(tcx: TyCtxt<'tcx>, def_id: DefId) -> bool {
    // Authentic core by lang-item ownership, never the `--crate-name core` string
    // (a spoofed dep would otherwise supply a fake `Argument::new_*` packer).
    if !crate_is_authentic_core(tcx, def_id.krate) {
        return false;
    }
    // Trust (hardened 2026-09-13): recognize a value packer by the `new_` PREFIX,
    // not an exact name list. Every `fmt::rt::Argument` value-of-`T` constructor is
    // `new_*` (new_display/new_debug/new_octal/new_lower_hex/…); the non-packer
    // helpers `from_usize`/`from_str` (count/precision/static-string args, which
    // carry no formatted user value) are `from_*` and are correctly excluded. A
    // FUTURE upstream packer `new_foo::<T>` is then still caught and its `T`
    // type-checked, rather than silently skipped — the exact-list form was the
    // "a wildcard admits a future variant" hazard this repo forbids. Broadening to
    // the prefix is strictly MORE fail-closed: an unrecognized `new_*` can only add
    // a foundational-type requirement, never remove one.
    //
    // Trust (ICE guard — 2026-09-14): `tcx.item_name` ICEs on a NAMELESS DefId,
    // and a core `CrateNum` is NOT proof of a named item — `core::panicking::
    // begin_panic::{closure}` passes the crate gate and has no item name. Use
    // `opt_item_name` and treat `None` (closure/ctor/etc.) as "not a packer".
    let Some(name) = tcx.opt_item_name(def_id) else { return false };
    if !name.as_str().starts_with("new_") {
        return false;
    }
    trust_mir_extract::safe_def_path_str(tcx, def_id).contains("fmt::rt::Argument")
}

/// Trust (crate-identity root fix — 2026-09-14): is `krate` an AUTHENTIC sysroot
/// foundational crate (core/alloc/std), decided by LANG-ITEM OWNERSHIP (a
/// `CrateNum`), never by the spoofable `--crate-name` string? Every earlier
/// foundational check keyed on `tcx.crate_name(..).as_str()` in {core,alloc,std},
/// so a dependency built `-Ztrust-verify=off --crate-name core` (a DIFFERENT
/// `CrateNum` that owns NO sysroot lang item) fell into the unmasked allow-list
/// and its panic was laundered under the print gap. A lang item is planted by the
/// real sysroot crate that DEFINES it and cannot be forged by renaming a dep:
///
///  * core  — owns `Sized` (`sized_trait`).
///  * alloc — owns `Box`/`String` (`owned_box`/`string`).
///  * std   — provides the `#[panic_handler]` (`panic_impl`); any program that
///    uses `println!` links std, so this anchor exists.
///
/// FAIL-CLOSED: a missing anchor lang item yields `false` (NOT authentic), so the
/// caller masks/refuses — the safe direction.
///
/// Trust (R2 residency, 2026-09-28): the lang-item anchors above are NECESSARY,
/// not sufficient, and every predicate in this family now ALSO requires
/// [`crate_is_compiler_resident_sysroot`]. A lang item is a source ATTRIBUTE
/// (`#![feature(lang_items)]` + `#[lang = "String"]`), and rustc refuses a
/// duplicate only when BOTH owners are loaded: in a `#![no_std]` graph the real
/// `alloc`/`std` never are, so a verify-off dependency that declares
/// `#[lang = "String"]`, or merely supplies the graph's `#[panic_handler]`, OWNED
/// the anchor and was graded core/alloc/std. MEASURED on stage-1 `trustc` at
/// `d06cc05bc12`: such a dependency's panicking `slice::Iter::next` was credited
/// by `total_std_iterator_ty` (`[PF_ZEROGATE] … arm=registry`) under both
/// anchors separately (the `String` lang item alone; the `#[panic_handler]`
/// alone), and the program panics at run time (exit 134). Only the bridge's own
/// residency check kept the row. Refutation pins:
/// `tests/ui/trust/total_std_iterator_lang_item_foundational_impostor_refuted.rs`
/// and `…_panic_handler_foundational_impostor_refuted.rs`.
fn crate_is_authentic_foundational(tcx: TyCtxt<'_>, krate: CrateNum) -> bool {
    let lang_items = tcx.lang_items();
    let owns = |item: Option<DefId>| item.is_some_and(|d| d.krate == krate);
    (owns(lang_items.sized_trait())
        || owns(lang_items.owned_box())
        || owns(lang_items.string())
        || owns(lang_items.panic_impl()))
        && crate_is_compiler_resident_sysroot(tcx, krate)
}

/// Trust (R2 residency, 2026-09-28): the IDENTITY conjunct of
/// `crate_is_authentic_{foundational,core,std}` — ARTIFACT RESIDENCY, via the
/// extractor's one implementation of the rule
/// ([`trust_mir_extract::is_real_sysroot_crate`]; residual R2 in
/// `trust-mir-extract/src/convert.rs`). An EXTERNAL crate qualifies only when the
/// loader opened it from THIS compiler's own target library directory, or when
/// the command line declares a sysroot build (`-Zforce-unstable-if-unmarked`,
/// which bootstrap sets for `Mode::Std`); the LOCAL crate only under that same
/// declaration. Neither input is an attribute or a fact about which crates the
/// graph contains, so no dependency can supply it.
///
/// It is a CONJUNCT, never a replacement for the lang-item anchor: the rule
/// authenticates the CRATE only (and is name-gated to `core`/`alloc`/`std`), so
/// the anchor still decides WHICH of the three a crate is.
///
/// Direction: every consumer treats `false` as "not foundational → mask/refuse"
/// (see the fail-closed note above). The real sysroot crates are resident in the
/// host lane, the plain `#![no_std]` lane and the cross-compiled lane, so those
/// answer as before (a `#![no_std]` crate's `core`/`alloc` credits are pinned by
/// `tests/ui/trust/no_std_panic_handler_owner_keeps_core_credit.rs`).
///
/// NOT "exactly as before" in every honest graph (review, 2026-09-28). The
/// answer changes, always toward `false`, in two honest shapes:
///
/// * the `panic_impl` owner of a `#![no_std]` graph that is not a sysroot crate
///   — a panic-handler dependency (`panic-halt` style), or the crate under
///   verification when it declares its own `#[panic_handler]` — is no longer
///   graded `std`/foundational. That grade was wrong in the first place: it
///   unmasked the handler crate's public functions in the masked-dispatch crate
///   rule and let a handler-owning local crate's `Drop` impls skip the drop-glue
///   mask;
/// * the GENUINE `core`/`alloc`/`std` loaded from outside this compiler's target
///   library directory without `-Zforce-unstable-if-unmarked` — the user crate
///   under `cargo -Zbuild-std`, an `--extern core=` sysroot, a `-L`-supplied
///   target std. The whole family (masked-dispatch crate rule, print backend,
///   bundle admission, typed-self-total) now declines there too. This is the
///   same fail-closed over-decline the extractor already discloses for its path
///   stamp at `invocation_is_building_the_sysroot`
///   (`crates/trust-mir-extract/src/convert.rs`); it costs visible unproved
///   obligations, never a grant.
fn crate_is_compiler_resident_sysroot(tcx: TyCtxt<'_>, krate: CrateNum) -> bool {
    trust_mir_extract::is_real_sysroot_crate(tcx, krate)
}

/// Trust (crate-identity root fix): authentic `core`, owner of the `Sized` lang
/// item. Never the `--crate-name core` string. Trust (R2 residency, 2026-09-28):
/// AND resident (see `crate_is_compiler_resident_sysroot`) — a `#![no_core]`
/// graph leaves `Sized` as uncontested as `#![no_std]` leaves `String`.
fn crate_is_authentic_core(tcx: TyCtxt<'_>, krate: CrateNum) -> bool {
    tcx.lang_items().sized_trait().is_some_and(|d| d.krate == krate)
        && crate_is_compiler_resident_sysroot(tcx, krate)
}

/// Trust (identity-anchor sweep, 2026-09-28): the diagnostic item `name`, but only
/// when its owner is AUTHENTIC core ([`crate_is_authentic_core`]). For every
/// consumer that reads core's formatting items (`FmtWrite`, `FmtArgumentsFromStr`)
/// as a statement about core's BODIES — the writer-relative class, the
/// static-str `write_fmt` reduction and its `dyn` twin — the item alone is not an
/// identity. A diagnostic item is a source ATTRIBUTE, and rustc refuses a
/// duplicate only when both owners are loaded; a whole-`core` substitute
/// (`#![no_core]` + `#![compiler_builtins]`, crate name `core`, `--extern core=`)
/// is the one graph where no real `core` is, and it owns every such item. The
/// item names WHICH item; residency says it is core's.
///
/// `None` is the refusal direction for every consumer (no writer edge, no facts,
/// no reduction). Real core is resident in the host, `#![no_std]` and
/// cross-compiled lanes, so those answer as before; a genuine core loaded from
/// outside the target library directory (`-Zbuild-std`, `--extern core=`) is
/// declined too, the over-decline `crate_is_compiler_resident_sysroot` discloses.
fn authentic_core_diagnostic_item(tcx: TyCtxt<'_>, name: Symbol) -> Option<DefId> {
    tcx.get_diagnostic_item(name).filter(|item| crate_is_authentic_core(tcx, item.krate))
}

/// Trust (crate-identity root fix): authentic `std`. Primary anchor is std's
/// `#[panic_handler]` (`panic_impl`) lang item, authenticated by `CrateNum`. Its
/// fallback is the crate NAME `std` — which, UNLIKE `core`/`alloc`, is NOT
/// spoofable: a dependency built `--crate-name std` COLLIDES with the real std
/// that any `println!` program links and is refused before it can be used (owner
/// measurement). The name fallback is load-bearing because `panic_impl` is a weak
/// lang item that may be ABSENT from an intermediate rlib's table (a
/// `--crate-type lib` build resolves the handler only at final link), so a
/// `panic_impl`-only check would fail to recognize the real std `_print` in a lib
/// and break the surgical print-backend unbundling. A spoofed non-std dep matches
/// neither anchor and is masked.
fn crate_is_authentic_std(tcx: TyCtxt<'_>, krate: CrateNum) -> bool {
    // Trust (2026-09-20): the `|| tcx.crate_name(krate).as_str() == "std"`
    // fallback that stood here is DELETED. A function whose name asserts
    // authenticity must not decide it on a string the crate being judged chose.
    //
    // MEASURED SPOOF, byte-identical source, only `--crate-name` differing. A
    // `#![no_std]` dependency whose `Drop` panics, built
    // `-Ztrust-verify=off --crate-type=rlib` and loaded under any `--extern`
    // alias:
    //
    //     --crate-name notstd -> TRUST_MASK_TRACE: "masked fail-closed source at drop(_1)"
    //     --crate-name std    -> the trace does NOT fire
    //
    // i.e. a verify-off dependency that merely CALLS ITSELF `std`, never
    // resident in the sysroot, was graded inside the foundational TCB. That is
    // spelling as authority — the same defect closed at HOLE A, where
    // `depA::a::std::io::_print` was classified as std's own print backend by a
    // `.contains()`.
    //
    // NO LIVE FALSE PROOF WAS DEMONSTRATED through it: every program built
    // around the spoof still refused (`rc=1`) on both spellings, because the
    // drop-glue row keeps such a function fail-closed either way. It was
    // load-bearing for a TOLERANCE that was PROPOSED and not built (W3 —
    // reports/2026-09-20-w3-spec-does-not-survive-review.md), which is how two
    // independent adversarial lenses found it.
    //
    // DELETING IT LOSES NOTHING FOR REAL STD: `library/std/src/panicking.rs`
    // carries `#[panic_handler]`, whose lang item IS `panic_impl`
    // (rustc_hir/src/lang_items.rs, `PanicImpl => sym::panic_impl`), so the
    // remaining disjunct already answers true for authentic std. And the
    // failure direction if some configuration ever had a std without it is
    // CONSERVATIVE — the crate loses its foundational grade and its callees
    // fail closed, which cannot mint a proof.
    //
    // Trust (R2 residency, 2026-09-28): `panic_impl` ownership alone is NOT std
    // identity. In a `#![no_std]` graph the `panic_impl` owner is whichever crate
    // declares `#[panic_handler]` — a verify-off dependency or the crate under
    // verification itself — so it was graded "std" by every consumer of this
    // family. MEASURED (stage-1 `trustc` at `d06cc05bc12`): a dependency carrying
    // only a `#[panic_handler]` (no other lang item) had its panicking
    // `slice::Iter::next` credited `arm=registry`. Residency is the identity; the
    // anchor only says which sysroot crate it is.
    //
    // PINS (corrected 2026-09-28, review): that measurement went through
    // `crate_is_authentic_foundational`, which no longer calls this predicate
    // (it tests `panic_impl` ownership itself), so
    // `total_std_iterator_panic_handler_foundational_impostor_refuted.rs` pins
    // the FOUNDATIONAL disjunct, not this conjunct. A review mutant dropping only
    // this conjunct and `crate_is_authentic_core`'s passed all of tests/ui/trust.
    // This conjunct's own pin is
    // `tests/ui/trust/std_print_backend_panic_handler_impostor_refuted.rs`, through
    // its consumer `def_is_std_print_backend`. `crate_is_authentic_core`'s
    // conjunct (its impostor needs `#![no_core]`) is pinned since the
    // identity-anchor sweep (2026-09-28) through its consumer
    // `native_trust_ir_partialord_default_comparator_instances`:
    // `tests/ui/trust/partialord_sublane_no_core_lang_item_impostor_refuted.rs`,
    // whose `#![no_core]` dependency owns `Sized` and is not resident.
    tcx.lang_items().panic_impl().is_some_and(|d| d.krate == krate)
        && crate_is_compiler_resident_sysroot(tcx, krate)
}

/// Trust (policy B, surgical print-backend gap — 2026-09-14): is `def_id` the std
/// stdout/stderr print backend (`std::io::_print`/`_eprint`)? These are
/// foundational TCB (docs/TCB.md) — Trust does not verify std's IO — so they must
/// be treated as ABSENT callees, NOT bundled. Bundling them pulls in their
/// transitive `ReentrantLock`/`LineWriter` internals whose `NullPointerDereference`
/// asserts are outside the exact Div/Rem/BoundsCheck lane, which fails the WHOLE
/// bundle lowering and ERASES every one of `main`'s own obligation rows (a proved
/// assert and an unproved assert then become indistinguishable). Kept absent, the
/// bundle lowers `main`'s own body, its obligations get real verdicts, and the
/// `_print` call's own broken-pipe panic is the tolerated `std_print_dispatch`
/// completeness gap.
///
/// Trust (HOLE A close — 2026-09-14): classify by the REAL crate identity
/// (`CrateNum`) plus EXACT def-path segments, NEVER a `.contains()` on the
/// rendered path. A dependency crate built `-Ztrust-verify=off` can define
/// `pub mod a { pub mod std { pub mod io { pub fn _print(..) { panic!() } } } }`
/// whose rendered path CONTAINS `std::io::_print`; the old substring test
/// classified `depA::a::std::io::_print` as the benign std backend and left its
/// panic absent+tolerated (a false SAFE claim — the program panics at runtime).
/// The crate of that def is `depA`, not `std`, so pinning `CrateNum` to the real
/// std sysroot crate defeats the spoof: it becomes an ordinary absent callee and
/// fails closed. Segment names then only DISAMBIGUATE within the authenticated
/// std crate, where no user/dependency code can inject an item (the same sound
/// pattern `def_path_has_module_segment` documents).
fn def_is_std_print_backend(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    // REAL std sysroot crate only, AUTHENTICATED by lang-item ownership
    // (`panic_impl`) AND artifact residency (2026-09-28: in a `#![no_std]` graph
    // any `#[panic_handler]` crate owns `panic_impl`), never the
    // `--crate-name std` string.
    if !crate_is_authentic_std(tcx, def_id.krate) {
        return false;
    }
    // Exact terminal item, matched by name (not substring). A std `CrateNum` is
    // not proof of a named item — a nameless std closure/ctor would ICE
    // `item_name`; `opt_item_name` returns `None` and this fails safe to `false`.
    let Some(name) = tcx.opt_item_name(def_id) else { return false };
    if !matches!(name.as_str(), "_print" | "_eprint") {
        return false;
    }
    // Under `std::io` (the backend is `std::io::stdio::_print`, re-exported at
    // `std::io::_print`); the `io` module segment disambiguates within std.
    def_path_has_module_segment(tcx, def_id, "io")
}

/// Trust (HOLE — masked verify-off dep call, 2026-09-14): is a Call/TailCall to
/// `def_id` a FAIL-CLOSED dispatch whose panic-freedom the std print grace must
/// NOT cover? The caller has already excluded the tolerated std print backend
/// (`def_is_std_print_backend`). Two rules, the first being the GENERAL form of
/// the HOLE A fix (crate-based, replacing the earlier whack-a-mole enumeration):
///
///  * GENERAL CRATE RULE. A NON-LOCAL callee whose crate is not std/core/alloc is
///    an unverified (verify-off) dependency/user function — Targo compiles every
///    dependency unit `-Ztrust-verify=off`, so its panic-freedom is unproven and
///    it is fail-closed WITHOUT a `println!` too. Making the print gap not launder
///    it is CONSISTENT, not stricter. This one rule covers an ARBITRARY dep fn
///    (`dep::boom`), a dep raw deref (`dep::deref_raw`), a dep `fmt::Write` impl
///    reached directly (`<DepSink as Write>::write_str`), AND the non-std
///    `_print`/`_eprint` spoof (HOLE A) — each has crate ≠ std/core/alloc. LOCAL
///    callees are EXCLUDED (verified as their own root); std/core/alloc callees
///    are the affirmative allow-list (black_box, `fmt::Arguments`/`rt::Argument`
///    ctors, `core::panicking::*`, the print backend), never masked by this rule.
///  * FOUNDATIONAL-CRATE SINK DISPATCH the crate rule cannot see. `write!`/
///    `writeln!` into a sink resolves to `core::fmt::Write::write_fmt` (and its
///    `spec_write_fmt` wrapper) — a std/core/alloc callee that nonetheless drives
///    an unmodeled sink that may panic. Kept as a name+crate guard (the crate
///    rule alone excludes it because its crate IS core). A user method merely
///    named `write_fmt` in a LOCAL crate is NOT matched (its own body is bundled
///    and earns real rows). `alloc::fmt::format` (the `format!` backend, no sink,
///    the b59 demotable-safe leg) and the internal `core::fmt::write` driver are
///    deliberately excluded so valid `format!` programs are not refused.
///
/// FAIL-CLOSED on an unresolvable crate: `tcx.crate_name` is total on a real
/// `CrateNum`, and `is_local()` is exact; there is no unresolved arm here.
fn callee_is_masked_fail_closed_dispatch(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    // GENERAL CRATE RULE: a non-local callee outside the AUTHENTIC sysroot
    // foundational crates is an unverified dependency/user function — masked
    // fail-closed. Authenticity is by lang-item ownership (`CrateNum`), never the
    // spoofable `--crate-name` string: a dep built `--crate-name core`/`alloc`
    // owns no sysroot lang item, so it is NOT authentic and is masked.
    if !def_id.is_local() && !crate_is_authentic_foundational(tcx, def_id.krate) {
        return true;
    }
    // A foundational-crate `write!`/`writeln!`-into-a-sink dispatch: `write_fmt`/
    // `spec_write_fmt` resolve into `core::fmt::Write`, so the crate rule above
    // (which masks a non-authentic crate) does not fire on them; catch them by
    // name AND authentic-foundational crate, which keeps a same-crate LOCAL user
    // `write_fmt` (not authentic-foundational) unmatched. `opt_item_name` (not
    // `item_name`) so a nameless std/core/alloc closure/ctor here is skipped, not
    // an ICE.
    tcx.opt_item_name(def_id)
        .is_some_and(|name| matches!(name.as_str(), "write_fmt" | "spec_write_fmt"))
        && crate_is_authentic_foundational(tcx, def_id.krate)
}

/// Trust (HOLE — indirect dispatch of a masked function VALUE, 2026-09-15): does
/// the type `ty` CARRY a function item whose direct call would be a masked
/// fail-closed dispatch (`callee_is_masked_fail_closed_dispatch`)?
///
/// WHY THIS EXISTS. `function_has_masked_fail_closed_dispatch` scans Call/TailCall
/// terminators, so it sees only the callee a body names DIRECTLY. A function VALUE
/// handed to a foundational higher-order callee is invoked inside THAT callee's
/// body — there is no Call terminator for it here at all:
///
/// ```text
///  let r = Some(i).map(mydep::boom);   // `boom` runs inside core's Option::map
/// ```
///
/// MEASURED 2026-09-15 with the prebuilt stage1 `trustc`: with a `println!` in the
/// same function this compiled exit 0 and the program then panicked (exit 101,
/// "index out of bounds: the len is 3 but the index is 9"), while the DIRECT call
/// `mydep::boom(i)` and the same indirect program with the `println!` removed were
/// both correctly refused. So the hole is exactly "an unverified dependency's
/// function reaches the program as a VALUE, and the print grace then launders the
/// folded panic-freedom row it hides behind".
///
/// The rule this restores: a non-foundational function VALUE that this body hands
/// to a callee is the SAME hazard as calling it directly, and is already refused in
/// its direct spelling. Treating them alike adds no new refusal class.
///
/// HOW. `Ty::walk` yields the type and every nested generic argument, so one walk
/// finds the function item wherever it is packaged — a bare `FnDef` argument, the
/// `F` type argument of `Option::map::<_, F>`, a `FnDef` inside `Option<F>`/a tuple/
/// a reference, and a CLOSURE's captured `FnDef` (upvars are closure generic args).
/// It deliberately does NOT descend into ADT FIELD types, which costs nothing here:
/// a `FnDef` type is unnameable, so it can only reach a field through a generic
/// argument, which `walk` does yield.
///
/// SCOPE, and why it cannot mint a `Proved`. This predicate only ever makes a gap
/// FATAL — it feeds `masked_fail_closed_source`, and through it
/// `tolerated_gap_masks_fail_closed_dispatch`, which subtracts from
/// `tolerate_default_gap` (and the same conjunct on the lowering-failure path).
/// A `true` refuses; it can never mark an obligation discharged.
///
/// NOT MASKED, so these keep compiling (measured as controls): a LOCAL function
/// item (`Some(i).map(dbl)`) — it is verified as its own root; a foundational one
/// (`Some(i).map(i64::from)`); and a local closure (`Some(i).map(|x| x + 1)`),
/// whose own body is verified as its own root. A local closure that CALLS a
/// verify-off dependency is likewise already refused on its own body (measured),
/// which is why no closure-body recursion — and its query-cycle risk — is taken
/// here.
fn ty_carries_masked_fail_closed_fn_value<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    ty.walk().filter_map(|arg| arg.as_type()).any(|t| match t.kind() {
        // A function ITEM: the callee identity is exact, so reuse the same
        // authenticated crate-identity test the direct-call arm uses. A `FnPtr`
        // carries no `DefId` and is deliberately NOT matched here — it is caught
        // where the pointer is MINTED instead (the cast scan in
        // `function_has_masked_fail_closed_dispatch`), because refusing every
        // `fn(..)`-typed value would refuse local and foundational ones too.
        ty::FnDef(did, _) => callee_is_masked_fail_closed_dispatch(tcx, *did),
        _ => false,
    })
}

/// Trust (HOLE B / Option Y, fold-safe print grace — 2026-09-14): does this
/// function's own MIR carry a fail-closed panic source OTHER than the tolerated
/// std print backend — a masked foreign CALL
/// (`callee_is_masked_fail_closed_dispatch`) or masked DROP GLUE
/// (`drop_ty_has_masked_fail_closed_glue`)?
///
/// WHY THIS IS RE-DERIVED FROM MIR. The bridge folds EVERY absent/foreign
/// panic-freedom source of a function into ONE whole-function aggregate row
/// (`…:assertion:panic-freedom:0`) whose description names a single representative
/// callee. When a `println!` is present that representative is often the tolerated
/// `std::io::stdio::_print`, and a co-folded `write!`-into-a-sink panic, a spoofed
/// `depA::a::std::io::_print` panic, or a dependency/user type's DROP-glue panic
/// then becomes INVISIBLE to the row-based `has_fail_closed_assumption_panic` scan
/// and would be laundered by the print grace (MEASURED: `write!(dep_sink,…);
/// println!(…)` and `println!(…); let _b = DepBomb(x);` each compiled exit 0 while
/// panicking; the no-`println!` controls each fail closed). Re-deriving these
/// sources from the MIR restores the ruling that the print grace covers the std
/// print backend ALONE, independent of which source the fold happened to name. A
/// RETAINED-runtime-check panic (an `assert!` on a runtime value, a dynamic
/// `{:width$}` count) is NOT such a source and is NOT matched: those keep their
/// runtime check and compile honestly under the default policy, with or without
/// the `println!` (Option Y).
fn function_has_masked_fail_closed_dispatch<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    function_has_masked_fail_closed_dispatch_except(tcx, body, |_| false)
}

/// Trust (D1 increment 2, 2026-09-25): [`function_has_masked_fail_closed_dispatch`]
/// with the terminators `exempt` names not counted. ONE implementation of the
/// scan — the plain entry passes `|_| false` and is byte-for-byte what it was.
/// The one caller that exempts anything is the writer-relative root
/// (`fmt_writer_relative::writer_relative_body_has_masked_source`), for core's
/// `<Formatter as fmt::Write>::{write_str, write_char}` only. The reified
/// fn-pointer CAST arm is never exempt.
fn function_has_masked_fail_closed_dispatch_except<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    exempt: impl Fn(&TerminatorKind<'tcx>) -> bool,
) -> bool {
    let typing_env = ty::TypingEnv::post_analysis(tcx, body.source.def_id());
    let trace = env_flag_enabled("TRUST_MASK_TRACE");
    body.basic_blocks.iter().any(|bb| {
        // Trust (HOLE — reified fn POINTER to a masked callee, 2026-09-15): a
        // `ReifyFnPointer` coercion turns a function ITEM into a `fn(..)` value
        // that carries no `DefId`, so neither the call arm below (the eventual
        // `Call` has a non-const `func` operand, and `const_fn_def()` is `None` for
        // it) nor the argument scan can name the callee at the point of USE. Catch
        // it where the pointer is MINTED: the cast's SOURCE operand still has the
        // `FnDef` type. MEASURED 2026-09-15 with the prebuilt stage1 `trustc`, this
        // is a second live accept-and-panic of the same family —
        // `let f: fn(usize) -> i32 = mydep::boom; f(i);` beside a `println!`
        // compiled exit 0 and panicked at runtime (exit 101).
        //
        // Any cast is matched, not just `PointerCoercion`: the discriminator is the
        // SOURCE type, and the only casts out of a `FnDef` are pointer coercions, so
        // this is precise in practice and fail-closed on an exotic transmute. A
        // local or foundational function item reified this way is NOT matched
        // (`callee_is_masked_fail_closed_dispatch` is `false` for it), so
        // `let f: fn(i32) -> i64 = i64::from;` keeps compiling.
        // Trust (merge, 2026-09-18): BOUND, not early-returned. This scan and the
        // `TRUST_MASK_TRACE` line below were written by two lanes that never saw each
        // other; a `return true` here is the same VERDICT but it steps over the trace,
        // so a reified-fn-pointer mask — the very shape this scan exists to catch —
        // was the one kind of mask the trace could never show. The refusal is not
        // where a lane spends its time; finding out WHY a build refused is, and an
        // observability hole in exactly the subtle case is how that time gets spent.
        let cast_masked = bb.statements.iter().any(|stmt| {
            let StatementKind::Assign(assign) = &stmt.kind else { return false };
            let Rvalue::Cast(_, src_op, _) = &assign.1 else { return false };
            ty_carries_masked_fail_closed_fn_value(tcx, src_op.ty(&body.local_decls, tcx))
        });
        // A block may mint the pointer and end in something that is not a `Call` at
        // all (the reification and the call are usually in different blocks), so the
        // cast hit must survive a missing terminator.
        let masked = cast_masked
            || bb.terminator.as_ref().is_some_and(|terminator| {
                !exempt(&terminator.kind)
                    && function_terminator_is_masked_fail_closed_dispatch(
                        tcx,
                        body,
                        typing_env,
                        &terminator.kind,
                    )
            });
        if trace && masked {
            // Trust: the WHOLE line under `with_no_trimmed_paths!`, not just the label:
            // a masked source is a `Call` of an `FnDef` constant, and `{:?}` of that
            // terminator prints the callee through `pretty_print_value_path`, which runs
            // the same `trimmed_def_paths` query `probe_label` exists to avoid. The
            // reified-pointer case has no such callee to print — the mask is the CAST,
            // and the block's terminator is usually an unrelated goto — so it names the
            // site it actually found rather than printing a terminator that means
            // nothing here.
            // The `{:?}` stays INSIDE the macro: it is the terminator's formatting that
            // must run untrimmed, so a `site` string built outside would defeat exactly
            // what the wrapper is for.
            with_no_trimmed_paths!({
                let label = probe_label(tcx, body.source.def_id());
                match (cast_masked, &bb.terminator) {
                    (true, _) => eprintln!(
                        "TRUST_MASK_TRACE: {label}: masked fail-closed source at reified \
                         fn-pointer cast"
                    ),
                    (false, Some(terminator)) => eprintln!(
                        "TRUST_MASK_TRACE: {label}: masked fail-closed source at {:?}",
                        terminator.kind
                    ),
                    (false, None) => unreachable!(
                        "`masked` is false with no terminator and no cast hit, so this \
                         block cannot be reached"
                    ),
                }
            });
        }
        masked
    })
}

fn function_terminator_is_masked_fail_closed_dispatch<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    kind: &TerminatorKind<'tcx>,
) -> bool {
    {
        match kind {
            // A masked foreign CALL: any non-local callee outside std/core/alloc
            // (a verify-off dependency/user fn whose panic-freedom is unproven),
            // or a foundational `write!`/`writeln!`-into-a-sink dispatch. See
            // `callee_is_masked_fail_closed_dispatch`. ALSO a by-VALUE drop hidden
            // inside a foundational consumer: `core::mem::drop::<T>` /
            // `core::ptr::drop_in_place::<T>` run `T`'s drop glue INSIDE core — so
            // there is no `Drop` terminator in this body for the arm below to catch
            // — read `T` from the call's generic args and reuse the drop-glue
            // check, closing the `std::mem::drop(dep_bomb)` fold-mask (both a
            // panicking and a UB `Drop`, since the check flags any non-foundational
            // `Drop::drop` crate).
            TerminatorKind::Call { func, args, .. }
            | TerminatorKind::TailCall { func, args, .. } => {
                // Trust (HOLE — indirect dispatch of a masked function VALUE,
                // 2026-09-15): a non-foundational function ITEM handed to this
                // callee is invoked INSIDE the callee's body, so it is never a
                // `Call` terminator here. Read it off the argument types and the
                // callee's own type arguments — `Option::map::<i32, F>(o, boom)`
                // carries `boom`'s `FnDef` in BOTH, and a future higher-order shape
                // that carries it in only one is still caught. Deliberately placed
                // BEFORE the `const_fn_def` bind: an indirect call through a
                // function pointer has no const callee, yet can still be handed a
                // masked function value. See
                // `ty_carries_masked_fail_closed_fn_value` for the measurement and
                // for what stays unmasked (local items, foundational items, local
                // closures).
                if args.iter().any(|arg| {
                    ty_carries_masked_fail_closed_fn_value(tcx, arg.node.ty(&body.local_decls, tcx))
                }) {
                    return true;
                }
                // Trust (review, 2026-09-15 — the FOURTH invocation route): an
                // INDIRECT call. `const_fn_def()` is `None` when `func` is not a
                // constant `FnDef` — a call through a `fn` POINTER held in a local,
                // a field, or a `static` (`static F: fn(usize) -> i32 = dep::boom;
                // F(i)`). The three mint-site scans above cannot see this one: the
                // pointer was minted in the static's OWN initializer body, and by
                // the time `main` calls it the operand is just a pointer-typed
                // value whose target this body cannot resolve. Under the print
                // grace an unresolvable callee is a masked panic source by
                // definition — the direct spelling `dep::boom(i)` is already a
                // build error — so a pointer-typed `func` operand FAILS CLOSED.
                // Measured before this arm: the static-fn-pointer program compiled
                // (exit 0) and panicked at runtime (exit 101). Refusing a fn-pointer
                // call beside a `println!` may over-refuse a pointer to a LOCAL or
                // foundational fn; that is the safe direction, and a resolvable
                // target can be recovered later by walking the static's allocation.
                let Some((def_id, generic_args)) = func.const_fn_def() else {
                    let func_ty = func.ty(&body.local_decls, tcx);
                    return matches!(func_ty.kind(), ty::FnPtr(..))
                        || ty_carries_masked_fail_closed_fn_value(tcx, func_ty);
                };
                if generic_args.types().any(|t| ty_carries_masked_fail_closed_fn_value(tcx, t)) {
                    return true;
                }
                (!def_is_std_print_backend(tcx, def_id)
                    && (callee_is_masked_fail_closed_dispatch(tcx, def_id)
                        || callee_instantiation_reaches_foreign_user_code(
                            tcx,
                            def_id,
                            generic_args,
                        )))
                    || (callee_is_foundational_value_dropper(tcx, def_id)
                        && generic_args.types().next().is_some_and(|t| {
                            let t = tcx.normalize_erasing_regions(
                                typing_env,
                                ty::Unnormalized::new_wip(t),
                            );
                            drop_ty_has_masked_fail_closed_glue(tcx, typing_env, t)
                        }))
            }
            // Masked DROP GLUE: a `TerminatorKind::Drop` whose dropped type runs a
            // `Drop::drop` outside the std/core/alloc foundational TCB (a verify-off
            // dependency or user type whose drop may `panic!`). Its panic-freedom
            // folds into the same whole-function aggregate as the tolerated `_print`
            // row, so it must be re-derived from MIR here (see
            // `drop_ty_has_masked_fail_closed_glue`).
            TerminatorKind::Drop { place, .. } => {
                let drop_ty = place.ty(&body.local_decls, tcx).ty;
                let drop_ty =
                    tcx.normalize_erasing_regions(typing_env, ty::Unnormalized::new_wip(drop_ty));
                drop_ty_has_masked_fail_closed_glue(tcx, typing_env, drop_ty)
            }
            _ => false,
        }
    }
}

/// Trust (2026-09-25, the memory-safe lowering-gap launder): the edges out of this
/// body that a memory-safe assumption row cannot stand for. Empty means the row is
/// admissible. Two rows ask it, because both stand for a body nothing verified: the
/// `assumption:native-lowering` collapse of a failed lowering, and (2026-09-27) the
/// `assumption:<tag>` row of a classifier skip (`TreatedAsAssumption`), whose body
/// is never lowered at all — measured on stage-1 436c9eb6d0, one safe `&raw const
/// s.a` beside `dep::deref_raw(p)` built rc=0 and the binary read a dangling
/// pointer.
///
/// The collapse replaces a failed native lowering with ONE authenticated
/// assumption row, and memory-safe admits that row on the premise that a body with
/// no `unsafe` can leave only PANIC-freedom undischarged. The premise holds for the
/// body's own operations. It fails for a call out of the body: the native bundle
/// is the one lane that charges a callee whose body it does not hold
/// (`[trust-absent-callee-assumption] … may panic`), memory-safe refuses that
/// charge, and a lowering that stopped part-way charged nothing at all. Measured with
/// a verify-off dependency whose safe `deref_raw(p)` is `unsafe { *p }`: on stage-1
/// `f0e3202c07`, `v[i] ^ dep::deref_raw(p)` over a slice was refused on the
/// `deref_raw` charge, while `let v = vec![1, 2, 3]; v[1] ^ dep::deref_raw(p)` —
/// whose lowering stops at the Assert-bearing `Vec::index` member the bundle
/// refuses — built with no error and no warning. On stage-1 `b4bc7cdf9d` the same
/// happened with the read behind `std::process::exit(1)`, `resume_unwind`,
/// `panic_any` or a dependency `fn never() -> !` (a `-> !` call the bridge refused
/// to lower until `a84aa67936`). Adding an unmodelled construct turned a refusal
/// into a pass.
///
/// So either row may stand only for a body whose every call resolves to a LOCAL,
/// non-`#[trust::skip]` function item WITH A BODY here (`local_item_is_held_to_this_rule`:
/// a local foreign-item declaration is not one), whose every `Drop` runs closed glue
/// (`memory_safe_drop_glue_open_reason`: no type parameter, trait object or
/// dependency destructor behind it), and that carries no masked fail-closed source
/// (`function_has_masked_fail_closed_dispatch`: a dependency call or function
/// value, a reified pointer, foreign drop glue). Everything else is named
/// here: a sysroot or dependency callee (memory-safe refuses the absent-callee
/// charge for both when the lowering succeeds — `Vec::push` and
/// `std::process::exit` were measured refused), an intrinsic, a shim, an
/// unresolved or virtual dispatch, and a call through a pointer. Fail-closed by
/// construction: only the one positively-classified shape is left out.
///
/// A local callee with a body is left out because it is this crate's body, held to the same
/// rule by induction and not "verified" as such: the pass either verifies it
/// (charging its calls), refuses it, or admits it on a row of its own — a memory-safe
/// skip or collapse row only when THIS check found no edge in it, an
/// `UnreachableStart` body that executes nothing, or an explicit
/// `#[trust::assume_total]` audit.
///
/// Trust (r15, 2026-10-01): the edges are enumerated in ONE place,
/// [`unverified_edges::unverified_edges`] under
/// [`unverified_edges::EdgeRule::MemorySafeAssumption`], which also names the reads
/// of a foreign static (a local `safe static` from an `unsafe extern` block needs
/// no `unsafe` block and has no validated initializer — measured rc=0 and SIGSEGV
/// on stage-1 `ae0494648a` before this) and the creation of a function pointer or
/// a vtable whose target this rule does not hold.
fn memory_safe_assumption_uncharged_edges<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Vec<String> {
    unverified_edges::unverified_edges(tcx, body, unverified_edges::EdgeRule::MemorySafeAssumption)
        .into_iter()
        .map(|edge| edge.what)
        .collect()
}

/// Is the LOCAL item `did` — a call's resolved `InstanceKind::Item` — a body this
/// crate verifies, refuses, or admits on a row of its own, so that the induction
/// in [`memory_safe_assumption_uncharged_edges`] reaches it? It must be local, not
/// `#[trust::skip]`, and have MIR here: a body to hold to the rule.
///
/// Trust (2026-09-30, the r14 review's P1): `did.is_local()` alone named a LOCAL
/// FOREIGN ITEM too — `unsafe extern "C" { pub safe fn atoi(p: *const u8) -> i32; }`
/// is a `DefId` of this crate with no body, and nothing holds it to any rule.
/// MEASURED on stage-1 `f2e5ebbc0f`, `-Ztrust-policy=memory-safe`: a body
/// `let _q = &raw const s.a; atoi(p)` (classifier-skipped as `addr-of-field`) was
/// recorded as an authenticated `assumption:addr-of-field` row, a binary whose
/// `main` is also skipped built rc=0 with no error or warning, and it died with
/// SIGSEGV (rc=139) in `atoi(NULL)`. The same body without the raw borrow is refused
/// (its native lane fails a `hardened_unsafe_operation` row for the foreign call).
/// A constructor has MIR (`mir_keys` builds it), so it stays a local edge's equal.
fn local_item_is_held_to_this_rule(tcx: TyCtxt<'_>, did: DefId) -> bool {
    did.is_local()
        && !tcx.is_foreign_item(did)
        && tcx.is_mir_available(did)
        && !item_has_trust_skip_attr(tcx, did)
}

/// Why a drop of `root` would run code outside the verified closure, or `None` when
/// its drop glue is CLOSED: every destructor it runs is a local, non-`#[trust::skip]`
/// `Drop::drop` (this crate's body, held to the same rule by induction) or an
/// authentic foundational one (core/alloc/std, and std's hash-table crate) whose
/// type arguments reach no foreign user code. The DROP arm of
/// `memory_safe_assumption_uncharged_edges`.
///
/// Trust (2026-09-30), MEASURED on stage-1 `094125ac4` with a verify-off dependency
/// whose `Crash::drop` writes through a null pointer: `g<T>(s: &S, t: T) { let _q =
/// &raw const s.a; let _t = t; }` beside a caller `c` (also skipped) that calls
/// `g(s, dep::Crash(7))` built rc=0 under `-Ztrust-policy=memory-safe`, both bodies
/// recorded as `assumption:addr-of-field` rows, and a binary built the same way died
/// with SIGSEGV in `Crash::drop`. Without the raw borrows the build is refused (the
/// native bundle charges the drop of `T` as an absent callee). The same launder held
/// for `t: impl Sized`, `t: Box<dyn Any>`, and `w: BufWriter<dep::W>`, whose
/// foundational destructor calls the dependency's `Write::write` (refused without the
/// raw borrow, rc=0 with it). The masked-source scan could not see any of them: it
/// asks whether glue can panic outside the TCB, and a type parameter or a trait
/// object names no destructor for it to judge.
///
/// FAIL-CLOSED BY CONSTRUCTION. A type with no drop glue at all (`!needs_drop`:
/// scalars, references, `T: Copy`, `ManuallyDrop<_>`) is closed. Otherwise only an
/// ADT whose destructor is positively classified, a tuple, an array or slice, and
/// a closure (whose glue drops only its upvars) are walked; every other kind — a
/// type parameter, an unnormalized alias, `dyn Trait`, a coroutine, anything
/// unlisted — is open, as is an async destructor, a dependency destructor, and a
/// walk that runs out of fuel.
///
/// A foundational destructor is closed only when its whole type reaches no foreign
/// user code (`foundational_destructor_foreign_reach`, the rule the print-grace scan
/// shares): the destructor itself is TCB, but it may call its arguments' trait impls
/// (`BufWriter<W>`'s drop flushes through `W::write`, `Box<T, A>`'s deallocates
/// through `A`) and the function pointers its value carries (`Waker`, `io::Error`).
/// That declines `Vec<dep::Plain>` too, whose destructor calls nothing of `Plain`'s —
/// the price of not keeping a list of which foundational destructors call what.
///
/// A LOCAL generic callee instantiated at a dependency type stays a local edge in
/// the call arm: its own polymorphic body is held to this rule, and every way its
/// instantiation can run the argument's code is an edge of THAT body — `T`'s drop
/// glue here, an unresolvable `T` method and a sysroot callee at `T` in the call arm.
///
/// Its reasons print types: call it under `with_no_trimmed_paths!`.
fn memory_safe_drop_glue_open_reason<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    root: Ty<'tcx>,
) -> Option<String> {
    let mut visited: FxHashSet<Ty<'tcx>> = FxHashSet::default();
    let mut worklist: Vec<Ty<'tcx>> = vec![root];
    let mut fuel = STRUCTURAL_DROP_CLOSURE_FUEL;
    while let Some(ty) = worklist.pop() {
        let Some(next) = fuel.checked_sub(1) else {
            return Some("its drop glue is too deep to enumerate".to_string());
        };
        fuel = next;
        if !visited.insert(ty) || !ty.needs_drop(tcx, typing_env) {
            continue;
        }
        match ty.kind() {
            ty::Adt(adt_def, _) => {
                if adt_def.async_destructor(tcx).is_some() {
                    return Some(format!("`{ty}` has an async destructor"));
                }
                if let Some(destructor) = adt_def.destructor(tcx) {
                    let did = destructor.did;
                    let foundational = crate_is_authentic_foundational(tcx, did.krate)
                        || trust_mir_extract::def_is_in_std_hash_table_crate(tcx, did);
                    if did.is_local() {
                        if item_has_trust_skip_attr(tcx, did) {
                            return Some(format!("the destructor of `{ty}` is `#[trust::skip]`"));
                        }
                        // Trust (2026-10-14, INSTANCE-WALK-1): a GENERIC local
                        // destructor runs, at this type's arguments, what its body
                        // resolves to there: `impl<T: dep::Act2> Drop for DG<T>`
                        // calling `self.0.a2()` runs the dependency's `impl Act2 for
                        // u32` when `DG<u32>` is dropped (bare, or inside an
                        // `Option`, a tuple or an array, whose components this walk
                        // reaches; `Box` and `Vec` reach it through the local impl
                        // surface). Its instance is walked (`unverified_edges`).
                        if let Some(reason) = local_destructor_instance_reason(tcx, did, ty) {
                            return Some(format!("the destructor of `{ty}` {reason}"));
                        }
                    } else if !foundational {
                        return Some(format!(
                            "the destructor of `{ty}` is in a crate this compilation does not \
                             verify"
                        ));
                    } else if let Some(reach) = foundational_destructor_foreign_reach(tcx, ty) {
                        return Some(format!("the foundational destructor of `{ty}` {reach}"));
                    }
                }
                worklist.extend(structural_drop_component_types(tcx, typing_env, ty));
            }
            ty::Tuple(_) | ty::Array(..) | ty::Slice(_) | ty::Closure(..) => {
                worklist.extend(structural_drop_component_types(tcx, typing_env, ty));
            }
            ty::Param(_) => {
                return Some(format!(
                    "`{ty}` is a type parameter, so each instantiation brings its own drop glue"
                ));
            }
            ty::Dynamic(..) => {
                return Some(format!(
                    "`{ty}` is a trait object, whose drop glue is chosen at run time"
                ));
            }
            _ => return Some(format!("the drop glue of `{ty}` is not known here")),
        }
    }
    None
}

/// Trust (2026-10-14, INSTANCE-WALK-1): why the LOCAL destructor `destructor` of the
/// ADT `ty`, at `ty`'s arguments, reaches code this compilation does not verify, or
/// `None`. Only a destructor of a generic ADT at concrete arguments is walked; the
/// instance is `<ty as Drop>::drop` as resolution picks it (fail-closed when it does
/// not resolve to that local body).
fn local_destructor_instance_reason<'tcx>(
    tcx: TyCtxt<'tcx>,
    destructor: DefId,
    ty: Ty<'tcx>,
) -> Option<String> {
    use rustc_middle::ty::TypeVisitableExt;
    if !unverified_edges::local_instance_is_generic(tcx, destructor) || ty.has_non_region_param() {
        return None;
    }
    let Some(drop_trait) = tcx.lang_items().drop_trait() else {
        return Some("cannot be resolved (no `Drop` lang item)".to_string());
    };
    let Some(&drop_fn) = tcx.associated_item_def_ids(drop_trait).first() else {
        return Some("cannot be resolved (no `Drop::drop`)".to_string());
    };
    let ty = tcx.erase_and_anonymize_regions(ty);
    match ty::Instance::try_resolve(
        tcx,
        ty::TypingEnv::fully_monomorphized(),
        drop_fn,
        tcx.mk_args(&[ty.into()]),
    ) {
        Ok(Some(instance)) if matches!(instance.def, ty::InstanceKind::Item(did) if did == destructor) => {
            unverified_edges::local_instance_unverified_reason(tcx, destructor, instance.args)
                .map(|reason| format!("at its type arguments: {reason}"))
        }
        _ => Some("does not resolve to its local body at these arguments".to_string()),
    }
}

/// Trust (2026-09-30): why the FOUNDATIONAL destructor of the ADT `ty` (core/alloc/
/// std's `Drop`, or that of std's hash-table crate) can run code this compilation
/// does not verify, described for a note, or `None` when it cannot. ONE answer for
/// both drop-glue scans: the masked-source scan behind the print grace and the
/// memory-safe demotion (`drop_ty_has_masked_fail_closed_glue`), and the memory-safe
/// skip/collapse edge scan (`memory_safe_drop_glue_open_reason`).
///
/// The destructor's own code is TCB; the code the VALUE chose is not. It calls its
/// type arguments' trait impls (`BufWriter<W>`'s drop flushes through `W::write`;
/// `Box<T, A>`'s deallocates through `A`) and the function pointers and trait objects
/// its fields carry (`Waker`'s vtable `drop`; `io::Error`'s `Repr` drops a boxed
/// `dyn Error`). So the WHOLE type is asked — its type arguments, then its
/// instantiated fields — through `ty_reaches_foreign_user_code`, the walk the
/// call-side scan already applies to every sysroot callee's instantiation. An
/// explicit `core::mem::drop::<T>` has always been judged by that walk
/// (`callee_instantiation_reaches_foreign_user_code`), so the scope-end drop of a
/// foundational owner and the explicit one now agree on what the owner reaches.
///
/// MEASURED on stage-1 `f2e5ebbc0f` before this rule, with a verify-off dependency
/// whose `Write::write`, `Drop::drop`, `RawWakerVTable::drop` and boxed error's
/// `Drop` each write through a null pointer: beside a `println!("{}", x)`, the
/// scope-end drops of `Box<dyn Any>`, `Rc<dyn Any>`, `Arc<dyn Any + Send + Sync>`,
/// `Vec<Box<dyn Any>>`, `Box<dyn Write>`, `BufWriter<&mut dyn Write>`,
/// `LineWriter<&mut dyn Write>`, a local struct holding a `BufWriter<dep::NullSink>`,
/// an `io::Error`, an `io::Result<u32>` and a `Waker` each built rc=0 under the
/// default policy, strict AND memory-safe (the same bodies without the print were
/// refused), and a verify-off `main` handing the dependency's value to the `Box<dyn
/// Any>`, local-`BufWriter`, `io::Error` and `Waker` shapes died with SIGSEGV (139).
/// Under memory-safe with a classifier-skipped body (`&raw const s.a`), the
/// scope-end drop of a `Waker` or an `io::Error` was recorded as an authenticated
/// `assumption:addr-of-field` row (rc=0), and both binaries died with SIGSEGV: the
/// type-argument-only rule this replaced saw no argument on either.
///
/// The memo is this call's own: `ty_reaches_foreign_user_code` is coinductive, so an
/// entry it records while an enclosing type is still being expanded is exact only for
/// the query that recorded it, and a memo carried across queries could hand a later
/// one such a provisional `false`.
///
/// The destructor of std's hash-table crate (`RawTable`, which every `HashMap` drop
/// runs) is the one foundational destructor whose ADT `ty_reaches_foreign_user_code`
/// answers `true` for by itself (a hash-table ADT a program names is foreign, see
/// [`HashTableCredit`]). Its fields are asked the way that walk asks them when it
/// reaches the table from std's own `HashMap` (`declared_ty_reaches_foreign_user_code`),
/// so `HashMap<u32, u32>` stays closed and `HashMap<dep::K, u8>` does not.
fn foundational_destructor_foreign_reach<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<String> {
    // Trust (IOERROR-PAYLOAD-1, 2026-10-27): a DROP question, so the rule is withheld
    // (`dyn_error_payload::withheld`): an `io::Error`'s destructor stays open here.
    dyn_error_payload::withheld(|| foundational_destructor_foreign_reach_inner(tcx, ty))
}

fn foundational_destructor_foreign_reach_inner<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Option<String> {
    let ty::Adt(def, args) = ty.kind() else { return None };
    let mut memo: FxHashMap<Ty<'tcx>, bool> = FxHashMap::default();
    if let Some(arg) = args.types().find(|t| ty_reaches_foreign_user_code(tcx, *t, &mut memo)) {
        return Some(format!(
            "is instantiated at `{arg}`, whose code this compilation does not verify"
        ));
    }
    // Every argument answered `false` as a query root, so no provisional entry the
    // memo holds was contradicted: reusing it for the whole type is exact.
    let fields_reach = if trust_mir_extract::def_is_in_std_hash_table_crate(tcx, def.did()) {
        let mut path = vec![ty];
        def.all_fields().any(|field| {
            let declared = tcx.type_of(field.did).instantiate_identity().skip_normalization();
            declared_ty_reaches_foreign_user_code(
                tcx,
                declared,
                *args,
                &mut memo,
                &mut path,
                DECLARED_HASH_TABLE_DEPTH,
            )
        })
    } else {
        ty_reaches_foreign_user_code(tcx, ty, &mut memo)
    };
    fields_reach.then(|| {
        "can run code the value's fields choose (a function pointer, a trait object or a \
         dependency's type), which this compilation does not verify"
            .to_string()
    })
}

/// Trust (refuted 2026-09-16, type-walk lens — the fold mask's missing half): a
/// SYSROOT callee whose instantiation reaches FOREIGN user code — a type
/// argument or parameter type naming a type from a crate that is neither this
/// one nor an authentic sysroot crate, a trait object, a fn pointer, a foreign
/// closure, or a type parameter — is a fail-closed panic source exactly like a
/// masked foreign call: `str::parse::<dep::P>` runs `dep`'s `FromStr`,
/// `Vec::<dep::Bomb>::push` grows a buffer of values whose `Drop` is `dep`'s,
/// and `dep` was compiled with verification OFF (targo's dependency lane), so
/// that user body has NO verdict anywhere. The crate rule
/// (`callee_is_masked_fail_closed_dispatch`) cannot see it because the callee
/// itself lives in core/alloc/std. Measured: `w.push(1); "3".parse::<dep2::P>()`
/// built exit 0 under the vanilla tolerance — the aggregate row named the
/// (vanilla) `push` representative — and panicked in `dep2`; the same two calls
/// in the other order were refused.
///
/// LOCAL user types are deliberately NOT foreign: a local `impl FromStr for T`
/// or `impl Drop for T` is a body of this crate and carries its own verdict
/// (measured across the orphan-and-coherence lens: every such impl reached
/// through a sysroot generic is verified as its own root and refused when it
/// panics). Sysroot ADTs are walked through their type arguments AND their
/// instantiated fields, as `ty_is_foundational` does, so a foreign type hidden
/// behind `Box<_>`, `Option<_>`, or a `PhantomData` argument is still found.
fn callee_instantiation_reaches_foreign_user_code<'tcx>(
    tcx: TyCtxt<'tcx>,
    def_id: DefId,
    generic_args: ty::GenericArgs<'tcx>,
) -> bool {
    // Trust (W4 HASHMAP redo, 2026-09-25): a LOCAL callee is verified on its own,
    // but when it is instantiated at a hashbrown type the program chose (a
    // `rustc_private` dependency's hashbrown value laundered through a local
    // generic), its bundled body would hand that value to std code, where the
    // std-site credit ([`HashTableCredit::StdSite`]) applies. Flag it here as the
    // non-local arm below flags it for a sysroot callee. std's own `base` field is
    // never an argument, so no program that only uses `HashMap` is affected.
    if def_id.is_local() {
        return generic_args.types().any(|t| ty_carries_program_chosen_hash_table_adt(tcx, t));
    }
    // A non-local callee outside the sysroot is already masked by the crate rule.
    if !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def_id) {
        return false;
    }
    // The format MACHINERY (`core::fmt::rt::Argument::new_*`, `Arguments::new_*`,
    // `alloc::fmt::format`, …) takes values that carry an `unsafe fn` formatter
    // pointer by construction — `rt::Argument` — so this walk would mask every
    // `println!`/`format!` body (measured: the whole policy_b run-pass set and
    // the battery went red). The user code those pointers can reach is exactly
    // the packers' formatted type `T`, which `function_format_args_all_
    // foundational_display` already refuses on this body when it is not
    // foundational; the machinery itself is owned by that gate, not this one.
    // Keyed on the def path's MODULE segments, never `def_path_str` (which
    // renders trimmed — `Arguments::<'_>::new`, no crate prefix — measured).
    //
    // Trust (2026-09-16, refuted): the exemption used to cover every item under
    // a `fmt` module, TRAIT METHODS included. A trait-method call is spelled
    // with the TRAIT item's `DefId` (`core::fmt::Write::write_str`) and its
    // dispatch target in `Self` — so `<dep::Buf as fmt::Write>::write_str(..)`,
    // a direct call into a verify-off dependency's own impl, was exempt from
    // the walk, co-folded under `println!`'s tolerated print row, and the
    // binary panicked in `dep` (also the provided `write_char` at a foreign
    // `Self`, and a local `fmt::Write` wrapper delegating to it). The machinery
    // this exemption is FOR is inherent/free (`rt::Argument::new_*`,
    // `Arguments::new_*`, `alloc::fmt::format`); a trait method's `Self` and
    // type arguments are walked like any other callee's.
    //
    // Trust (2026-09-28, refuted): the exemption also covers core's debug
    // builders and `core::fmt::write`, which are handed a `&dyn Debug` or a
    // `&mut dyn fmt::Write` — user code the packer gate never sees. That is sound
    // only while the native bundle's own rows judge the dyn calls those members
    // make — and a kept bundle's whole-function panic-freedom aggregate is reported
    // as runtime-checked on the default lane, so it does not judge them either.
    // Trust (2026-09-29): a function whose verdict rests on a runtime-checked
    // bundled std member (`runtime_checked_std_member`) re-judges exactly these
    // calls (`fmt_machinery_reach_without_verdict`). The predicate is shared so the
    // two cannot drift apart.
    if callee_is_sysroot_fmt_machinery(tcx, def_id) {
        return false;
    }
    let mut memo: FxHashMap<Ty<'tcx>, bool> = FxHashMap::default();
    generic_args.types().any(|t| ty_reaches_foreign_user_code(tcx, t, &mut memo))
        || tcx
            .fn_sig(def_id)
            .instantiate(tcx, generic_args)
            .skip_binder()
            .inputs()
            .iter()
            .any(|t| ty_reaches_foreign_user_code(tcx, *t, &mut memo))
}

/// Trust (2026-09-28): is `def_id` an inherent item or free function under a
/// `fmt` module of an AUTHENTIC sysroot foundational crate — core/alloc's
/// formatting MACHINERY (`rt::Argument::new_*`, `Arguments::new*`,
/// `Formatter::write_str`, `Formatter::debug_tuple_field1_finish`,
/// `DebugTuple::field`, `core::fmt::write`, `alloc::fmt::format`, …)?
///
/// Keyed on the def path's MODULE segments, never `def_path_str` (which renders
/// trimmed — `Arguments::<'_>::new`, no crate prefix — measured), and never on a
/// trait method (see the 2026-09-16 note in
/// `callee_instantiation_reaches_foreign_user_code`). ONE predicate with two
/// readers: that walk EXEMPTS these calls, and
/// `fmt_machinery_reach_without_verdict` RE-JUDGES exactly these calls for a
/// function whose verdict rests on a runtime-checked bundled std member.
fn callee_is_sysroot_fmt_machinery(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    !def_id.is_local()
        && trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def_id)
        && crate_is_authentic_foundational(tcx, def_id.krate)
        && tcx.trait_of_assoc(def_id).is_none()
        && tcx.def_path(def_id).data.iter().any(|segment| {
            matches!(segment.data, rustc_hir::definitions::DefPathData::TypeNs(name) if name.as_str() == "fmt")
        })
}

/// Trust (2026-09-28, refuted; re-homed 2026-09-29): the first call through which
/// this body hands core's formatting machinery a value whose code carries no
/// verdict of its own, described for the refusal, or `None`.
///
/// THE HOLE. When a bundled std/core/alloc member carries an internal `Assert`
/// the exact Div/Rem/BoundsCheck admission lane refuses, the policy-B tolerance
/// used to stand in for that member's runtime check. The calls core's formatting
/// machinery makes on a value the ROOT hands it — `DebugTuple::field`'s `<dyn
/// Debug as Debug>::fmt`, `core::fmt::write`'s `<dyn fmt::Write>::write_str`, the
/// formatters an `fmt::Arguments` carries — are user code, not std's own check,
/// and the fold-mask walk (`callee_instantiation_reaches_foreign_user_code`)
/// exempts every call in this family. MEASURED on stage-1 `trustc` at
/// `f992e2c307d`, strict policy, a verify-off dependency whose `Debug`/`fmt::Write`
/// impls panic on one value: with a RELEASE std, `v.iter().filter(..).count()`
/// (core's `<usize as Sum>::sum::{closure#0}`, an inherited `Overflow(Add)`
/// Assert), an enum `match`, then `f.debug_tuple(name).field(&self.dep)` built
/// exit 0 with `functions_verified` 2 of 2 and 0 unknown, and the program panicked
/// in the dependency (exit 101). The refused member is often NOT the one that
/// reaches the dependency, so no test on the refused member's path or generic
/// arguments can close this: what reaches user code is what the ROOT hands to core.
///
/// Trust (2026-09-29): the tolerance and its discarded bundle are gone — the
/// member is now KEPT under the runtime-checked disposition
/// (`runtime_checked_std_member`) — but KEEPING the bundle does not make its rows
/// judge these calls. MEASURED on stage-1 with this check removed (release-like
/// std and m3's debug std, strict): `fmt::format(a)` of a caller's
/// `fmt::Arguments` beside `filter().count()` built exit 0 — the dispatch folds
/// into the whole-function panic-freedom aggregate, which the default lane
/// reports as runtime-checked. So this rule now withholds the DISPOSITION instead
/// (`abort_on_full_verification_failure`), for a body with at least one
/// runtime-checked member.
///
/// THE RULE, fail-closed, over every call to `callee_is_sysroot_fmt_machinery`
/// except the `rt::Argument::new_*` packers (whose formatted type the packer
/// gate `function_format_args_all_foundational_display` judges — a conjunct of
/// the same disposition):
///
/// * every generic TYPE argument must be foundational
///   (`ty_is_foundational_display`: no user code reachable through it);
/// * every argument must be foundational, or
/// * `fmt::Arguments`/`rt::Argument` (behind references, arrays and slices) that
///   THIS body packed (`fmt_arguments_operand_packed_in_body`) — only then did the
///   packer gate see the formatted types it carries; one read from a parameter, a
///   field, a constant or a call result carries formatters no gate judged, or
/// * a `Formatter` or a debug builder holding one — only THIS formatting impl's
///   own `&mut Formatter` parameter, whose writer is its caller's (the
///   writer-relative premise), and only when every such value in the body
///   provably derives from it (`formatter_parameter_carriers`), or
/// * a `&dyn Trait`/`&mut dyn Trait` that this body MINTED by an unsize coercion
///   of `&S` (`minted_trait_object_sources`) where, for core's `Debug`/`Display`,
///   `S`'s impl passes the nested-formatter target bar
///   (`dyn_dispatch_reliance::minted_formatter_value_admitted`: core's `&T`
///   forwarding impl peeled, a sysroot impl at a foundational type, or a local
///   formatting impl with a verdict of its own), and for any other trait, `S` is
///   foundational. A trait object read from a parameter, a field, a constant or a
///   call result has no known target and refuses.
///
/// Only ever WITHHOLDS the disposition: a `Some` refuses the function. It never
/// mints, credits or excuses a row.
fn fmt_machinery_reach_without_verdict<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Option<String> {
    let root_def_id = body.source.def_id();
    let mut carriers: Option<FxHashSet<Local>> = None;
    for bb in body.basic_blocks.iter() {
        let Some(terminator) = &bb.terminator else { continue };
        let (TerminatorKind::Call { func, args, .. } | TerminatorKind::TailCall { func, args, .. }) =
            &terminator.kind
        else {
            continue;
        };
        let Some((def_id, generic_args)) = func.const_fn_def() else { continue };
        if !callee_is_sysroot_fmt_machinery(tcx, def_id) || is_fmt_rt_argument_packer(tcx, def_id) {
            continue;
        }
        let refusal = |what: String| -> Option<String> {
            Some(with_no_trimmed_paths!(format!("`{}` {what}", tcx.def_path_str(def_id))))
        };
        if let Some(ty) = generic_args.types().find(|ty| !ty_is_foundational_display(tcx, *ty)) {
            return refusal(with_no_trimmed_paths!(format!(
                "is instantiated at `{ty}`, a type through which user code can run"
            )));
        }
        for arg in args.iter() {
            let operand = &arg.node;
            let arg_ty = operand.ty(&body.local_decls, tcx);
            if ty_is_foundational_display(tcx, arg_ty) {
                continue;
            }
            // Trust (refuted 2026-09-28, review of the first cut of this check): an
            // `Arguments` value is packer-gate-owned only when THIS body packed it.
            // One handed in by a caller (a parameter, a field of one, a call
            // result) carries formatters the packer gate never saw. Measured on the
            // first cut, which skipped every `Arguments` unconditionally:
            // `fmt::format(a)` of a parameter beside `filter().count()` and an enum
            // `match` built exit 0 as `functions_verified` 2 of 2 under strict (the
            // tolerance fired), with a release std and with a debug std, and the
            // program panicked in a verify-off dependency's `Debug` (exit 101);
            // the same for `fmt::format(m.a)` of a parameter struct's field and
            // for `core::fmt::write(&mut String, a)`.
            if ty_is_core_fmt_arguments(tcx, arg_ty) {
                if fmt_arguments_operand_packed_in_body(tcx, body, operand, 0) {
                    continue;
                }
                return refusal(with_no_trimmed_paths!(format!(
                    "is handed a `{arg_ty}` that this body did not pack (it comes from a \
                     parameter, a field, a constant or a call), so the formatters it carries \
                     were judged by no packer gate"
                )));
            }
            if ty_is_core_fmt_writer_carrier(tcx, arg_ty) {
                let carriers =
                    carriers.get_or_insert_with(|| formatter_parameter_carriers(tcx, body));
                if operand_is_carrier(operand, carriers) {
                    continue;
                }
                return refusal(with_no_trimmed_paths!(format!(
                    "is handed a `{arg_ty}` that is not provably this formatting impl's own \
                     `&mut Formatter` parameter, so the writer it writes to is unknown"
                )));
            }
            if let Err(what) =
                fmt_machinery_trait_object_vouched(tcx, body, root_def_id, operand, arg_ty)
            {
                return refusal(what);
            }
        }
    }
    None
}

/// Trust (2026-09-28): is `ty` — behind references, arrays and slices — core's
/// `fmt::Arguments` or `fmt::rt::Argument`, authenticated by LANG ITEM (never a
/// name)? A TYPE test only. The formatted values such a value carries were judged
/// by the packer gate only if THIS body packed them (`rt::Argument::new_*`), so
/// `fmt_machinery_reach_without_verdict` pairs it with the provenance test
/// `fmt_arguments_operand_packed_in_body` and never exempts on the type alone.
fn ty_is_core_fmt_arguments<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let mut ty = ty;
    loop {
        match *ty.kind() {
            ty::Ref(_, inner, _) | ty::Array(inner, _) | ty::Slice(inner) => ty = inner,
            ty::Adt(def, _) => {
                let lang_items = tcx.lang_items();
                return lang_items.format_arguments() == Some(def.did())
                    || lang_items.format_argument() == Some(def.did());
            }
            _ => return false,
        }
    }
}

/// Trust (2026-09-28): the provenance half of the `ty_is_core_fmt_arguments`
/// exemption. `true` only when `operand` — an `Arguments`/`rt::Argument` value,
/// behind references and arrays — was built in THIS body: a whole non-argument
/// local every write of which is (a) a packer call `rt::Argument::new_*` (whose
/// formatted type the packer gate judges), (b) a call into core's formatting
/// machinery whose own `Arguments`-typed arguments are packed here in turn
/// (`Arguments::new`, `from_str`, …), (c) a borrow of, or a copy/move from, a
/// packed local, or (d) an array aggregate of packed operands. A constant, a
/// projection (a field of a parameter), a parameter, a call to anything else, a
/// local that is also mutably or raw-borrowed (`whole_local_writes`), or any
/// other write answers `false`: fail-closed. Refusal-only, like its caller: a
/// `false` keeps the lowering failure fatal and never touches a row.
fn fmt_arguments_operand_packed_in_body<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
    depth: usize,
) -> bool {
    let Some(place) = operand.place() else { return false };
    place.projection.is_empty() && fmt_arguments_local_packed_in_body(tcx, body, place.local, depth)
}

fn fmt_arguments_local_packed_in_body<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    local: Local,
    depth: usize,
) -> bool {
    if depth > 16 || body.args_iter().any(|arg| arg == local) {
        return false;
    }
    let Some(writes) = whole_local_writes(body, local, false) else { return false };
    !writes.is_empty()
        && writes.iter().all(|write| match write {
            WholeLocalWrite::Call { func, args } => {
                let Some((callee, _)) = func.const_fn_def() else { return false };
                if is_fmt_rt_argument_packer(tcx, callee) {
                    return true;
                }
                callee_is_sysroot_fmt_machinery(tcx, callee)
                    && args.iter().all(|arg| {
                        let arg_ty = arg.node.ty(&body.local_decls, tcx);
                        !ty_is_core_fmt_arguments(tcx, arg_ty)
                            || fmt_arguments_operand_packed_in_body(tcx, body, &arg.node, depth + 1)
                    })
            }
            WholeLocalWrite::Assign(Rvalue::Use(operand, _)) => {
                fmt_arguments_operand_packed_in_body(tcx, body, operand, depth + 1)
            }
            WholeLocalWrite::Assign(Rvalue::Ref(_, _, place)) => {
                place.projection.is_empty()
                    && fmt_arguments_local_packed_in_body(tcx, body, place.local, depth + 1)
            }
            WholeLocalWrite::Assign(Rvalue::Aggregate(kind, operands)) => {
                matches!(**kind, rustc_middle::mir::AggregateKind::Array(_))
                    && operands.iter().all(|operand| {
                        fmt_arguments_operand_packed_in_body(tcx, body, operand, depth + 1)
                    })
            }
            WholeLocalWrite::Assign(_) => false,
        })
}

/// Trust (2026-09-28): is `ty` — behind references — core's `Formatter` or a
/// core formatting ADT holding one (the debug builders: `DebugTuple`,
/// `DebugStruct`, `DebugList`, `DebugSet`, `DebugMap`, through `DebugInner`)? A
/// value through which core's machinery writes to a `Formatter`'s writer.
/// Authenticated: `Formatter` by diagnostic item in authentic core, a builder as
/// an authentic-core ADT under a `fmt` module with such a field.
fn ty_is_core_fmt_writer_carrier<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    fn at<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>, depth: usize) -> bool {
        let mut ty = ty;
        while let ty::Ref(_, inner, _) = *ty.kind() {
            ty = inner;
        }
        let ty::Adt(def, args) = *ty.kind() else { return false };
        if !crate_is_authentic_core(tcx, def.did().krate) {
            return false;
        }
        if tcx.is_diagnostic_item(sym::Formatter, def.did()) {
            return true;
        }
        depth < 3
            && def_path_has_module_segment(tcx, def.did(), "fmt")
            && def
                .all_fields()
                .any(|field| at(tcx, field.ty(tcx, args).skip_normalization(), depth + 1))
    }
    at(tcx, ty, 0)
}

/// Trust (2026-09-28): every write to `local` AS A WHOLE in `body` — the
/// right-hand side of each assignment, or the callee and arguments of each call
/// that returns into it — or `None` when it can also be written in a way this
/// list does not show: a projection store into it, a mutable or raw borrow of the
/// whole local (a later write through the borrow would be invisible here — unless
/// `mut_borrows_are_tracked`, whose caller proves by other means that no write
/// goes through one), a `SetDiscriminant`, an inline-asm output, or a coroutine
/// resume. Function arguments are initialised at entry, which this list does not
/// show either; the callers account for that.
enum WholeLocalWrite<'a, 'tcx> {
    Assign(&'a Rvalue<'tcx>),
    Call { func: &'a Operand<'tcx>, args: &'a [Spanned<Operand<'tcx>>] },
}

fn whole_local_writes<'a, 'tcx>(
    body: &'a Body<'tcx>,
    local: Local,
    mut_borrows_are_tracked: bool,
) -> Option<Vec<WholeLocalWrite<'a, 'tcx>>> {
    let mut writes = Vec::new();
    for bb in body.basic_blocks.iter() {
        for stmt in bb.statements.iter() {
            match &stmt.kind {
                StatementKind::Assign(boxed) => {
                    let (dest, rvalue) = &**boxed;
                    let aliases_local = match rvalue {
                        Rvalue::Ref(_, kind, borrowed) => {
                            !mut_borrows_are_tracked
                                && borrowed.local == local
                                && borrowed.projection.is_empty()
                                && !matches!(kind, rustc_middle::mir::BorrowKind::Shared)
                        }
                        Rvalue::RawPtr(_, borrowed) => {
                            borrowed.local == local && borrowed.projection.is_empty()
                        }
                        _ => false,
                    };
                    if aliases_local {
                        return None;
                    }
                    if dest.local == local {
                        if !dest.projection.is_empty() {
                            return None;
                        }
                        writes.push(WholeLocalWrite::Assign(rvalue));
                    }
                }
                StatementKind::SetDiscriminant { place, .. } if place.local == local => {
                    return None;
                }
                _ => {}
            }
        }
        let Some(terminator) = &bb.terminator else { continue };
        match &terminator.kind {
            TerminatorKind::Call { func, args, destination, .. } if destination.local == local => {
                if !destination.projection.is_empty() {
                    return None;
                }
                writes.push(WholeLocalWrite::Call { func, args: &args[..] });
            }
            TerminatorKind::InlineAsm { .. } | TerminatorKind::Yield { .. } => {
                // Outputs and resume arguments are places this list does not
                // decompose; refuse rather than reason about them.
                return None;
            }
            _ => {}
        }
    }
    Some(writes)
}

/// Trust (2026-09-28): an operand that reads a carrier local — the local itself or
/// a place reached from it through dereferences only (`copy _2`, `move _12`;
/// `&mut (*_2)` is an rvalue and is judged where it is assigned).
fn operand_is_carrier(operand: &Operand<'_>, carriers: &FxHashSet<Local>) -> bool {
    operand.place().is_some_and(|place| place_is_carrier(&place, carriers))
}

fn place_is_carrier(place: &Place<'_>, carriers: &FxHashSet<Local>) -> bool {
    carriers.contains(&place.local)
        && place
            .projection
            .iter()
            .all(|elem| matches!(elem, rustc_middle::mir::ProjectionElem::Deref))
}

/// Trust (2026-09-28): the escape half of `formatter_parameter_carriers`. Does a
/// `Formatter`/builder-typed local of `body` (`typed`) flow anywhere but (a) an
/// argument of core's formatting machinery, or (b) the right-hand side of a copy,
/// move, borrow or reborrow INTO another whole local of that kind? Anything else —
/// a store through a reference to one, a call to any other function, an aggregate
/// or a cast — is an escape: the value could be reseated or handed to code this
/// scan does not see. Storage markers, debug info, drops and retags are not uses
/// that can move a `Formatter`.
struct FormatterCarrierEscapes<'a, 'tcx> {
    tcx: TyCtxt<'tcx>,
    typed: &'a FxHashSet<Local>,
    escaped: bool,
}

impl<'a, 'tcx> rustc_middle::mir::visit::Visitor<'tcx> for FormatterCarrierEscapes<'a, 'tcx> {
    fn visit_statement(
        &mut self,
        statement: &Statement<'tcx>,
        location: rustc_middle::mir::Location,
    ) {
        if let StatementKind::Assign(boxed) = &statement.kind {
            let (dest, rvalue) = &**boxed;
            if dest.projection.is_empty()
                && self.typed.contains(&dest.local)
                && matches!(rvalue, Rvalue::Use(..) | Rvalue::Ref(..) | Rvalue::CopyForDeref(..))
            {
                // (b): the derivation in `formatter_parameter_carriers` decides
                // whether the source is a carrier.
                return;
            }
        }
        self.super_statement(statement, location);
    }

    fn visit_terminator(
        &mut self,
        terminator: &Terminator<'tcx>,
        location: rustc_middle::mir::Location,
    ) {
        if let TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. } =
            &terminator.kind
            && func
                .const_fn_def()
                .is_some_and(|(callee, _)| callee_is_sysroot_fmt_machinery(self.tcx, callee))
        {
            // (a): core's machinery is foundational TCB and does not reseat the
            // `Formatter` it is handed; its arguments are judged by
            // `fmt_machinery_reach_without_verdict`, its destination by the
            // derivation.
            return;
        }
        self.super_terminator(terminator, location);
    }

    fn visit_local(
        &mut self,
        local: Local,
        context: rustc_middle::mir::visit::PlaceContext,
        _location: rustc_middle::mir::Location,
    ) {
        use rustc_middle::mir::visit::{MutatingUseContext, NonMutatingUseContext, PlaceContext};
        if !self.typed.contains(&local) {
            return;
        }
        let harmless = matches!(
            context,
            PlaceContext::NonUse(_)
                | PlaceContext::MutatingUse(MutatingUseContext::Drop)
                | PlaceContext::NonMutatingUse(
                    NonMutatingUseContext::Inspect | NonMutatingUseContext::PlaceMention
                )
        );
        if !harmless {
            self.escaped = true;
        }
    }
}

/// Trust (2026-09-28): the locals of `body` that carry ITS OWN `&mut Formatter`
/// parameter — and therefore its caller's writer — or the empty set.
///
/// Non-empty only for a formatting-impl root (`fmt_writer_relative::
/// formatting_impl_root`: a local, non-generic `Debug::fmt`/`Display::fmt` with
/// the signature `(&Self, &mut Formatter<'_>)`), whose writer is its caller's and
/// is judged at the sink that supplied it (the D1 writer-relative premise). A
/// carrier is the parameter (never re-assigned), or a local every write of which
/// is a copy, move, borrow or reborrow of a carrier (through dereferences only),
/// or the result of a core formatting-machinery call handed a carrier
/// (`debug_tuple`, `DebugTuple::field`, …: a builder wrapping the same
/// `Formatter`). Builders are borrowed `&mut` to call their methods
/// (`_12 = &mut _13; DebugTuple::field(move _12, ..)`), so such borrows are
/// admitted — `FormatterCarrierEscapes` is what proves no write goes through one.
///
/// ALL OR NOTHING, fail-closed: the set is empty when any `Formatter`/builder
/// value in the body is NOT such a carrier (it holds a `Formatter` this body did
/// not receive), or when any of them escapes (`FormatterCarrierEscapes`).
fn formatter_parameter_carriers<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> FxHashSet<Local> {
    use rustc_middle::mir::visit::Visitor as _;
    let mut carriers = FxHashSet::default();
    if !fmt_writer_relative::formatting_impl_root(tcx, body.source.def_id()) {
        return carriers;
    }
    let Some(param) = body.args_iter().nth(1) else { return carriers };
    if !dyn_dispatch_reliance::ty_is_mut_ref_to_formatter(tcx, body.local_decls[param].ty)
        || !whole_local_writes(body, param, true).is_some_and(|writes| writes.is_empty())
    {
        return carriers;
    }
    let typed_in_order: Vec<Local> = body
        .local_decls
        .indices()
        .filter(|&local| ty_is_core_fmt_writer_carrier(tcx, body.local_decls[local].ty))
        .collect();
    let typed: FxHashSet<Local> = typed_in_order.iter().copied().collect();
    let mut escapes = FormatterCarrierEscapes { tcx, typed: &typed, escaped: false };
    escapes.visit_body(body);
    if escapes.escaped {
        return carriers;
    }
    let arguments: FxHashSet<Local> = body.args_iter().collect();
    carriers.insert(param);
    loop {
        let mut grew = false;
        for &local in &typed_in_order {
            if carriers.contains(&local) || arguments.contains(&local) {
                continue;
            }
            let Some(writes) = whole_local_writes(body, local, true) else { continue };
            let derived = !writes.is_empty()
                && writes.iter().all(|write| match write {
                    WholeLocalWrite::Assign(Rvalue::Use(operand, _)) => {
                        operand_is_carrier(operand, &carriers)
                    }
                    WholeLocalWrite::Assign(
                        Rvalue::Ref(_, _, place) | Rvalue::CopyForDeref(place),
                    ) => place_is_carrier(place, &carriers),
                    WholeLocalWrite::Call { func, args } => {
                        func.const_fn_def()
                            .is_some_and(|(callee, _)| callee_is_sysroot_fmt_machinery(tcx, callee))
                            && args.iter().any(|arg| operand_is_carrier(&arg.node, &carriers))
                    }
                    WholeLocalWrite::Assign(_) => false,
                });
            if derived {
                carriers.insert(local);
                grew = true;
            }
        }
        if !grew {
            break;
        }
    }
    if typed_in_order.iter().any(|local| !carriers.contains(local)) {
        carriers.clear();
    }
    carriers
}

/// Trust (2026-09-28): the referents of every value a `&dyn _`/`&mut dyn _`
/// operand can hold, when — and only when — this body MINTED each one by an
/// unsize coercion of a reference to a known type. `None` for anything else: a
/// parameter, a field or other projection, a constant, a call result, a copy of
/// another trait object, or a local that is also written some other way. Then
/// the concrete type behind the trait object is unknown here, and nothing can
/// vouch for the code it dispatches to.
fn minted_trait_object_sources<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Option<Vec<Ty<'tcx>>> {
    let place = operand.place()?;
    if !place.projection.is_empty() || body.args_iter().any(|arg| arg == place.local) {
        return None;
    }
    let writes = whole_local_writes(body, place.local, false)?;
    if writes.is_empty() {
        return None;
    }
    writes
        .iter()
        .map(|write| {
            let WholeLocalWrite::Assign(Rvalue::Cast(
                rustc_middle::mir::CastKind::PointerCoercion(
                    ty::adjustment::PointerCoercion::Unsize,
                    _,
                ),
                source,
                _,
            )) = write
            else {
                return None;
            };
            match *source.ty(&body.local_decls, tcx).kind() {
                ty::Ref(_, referent, _) => Some(referent),
                _ => None,
            }
        })
        .collect()
}

/// Trust (2026-09-28): may core's formatting machinery be handed this
/// `&dyn Trait`/`&mut dyn Trait` operand on the lowering-failure tolerance path?
/// See `fmt_machinery_reach_without_verdict` for the rule; `Err` names why not.
fn fmt_machinery_trait_object_vouched<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    root_def_id: DefId,
    operand: &Operand<'tcx>,
    arg_ty: Ty<'tcx>,
) -> Result<(), String> {
    let unknown = || {
        with_no_trimmed_paths!(format!(
            "is handed a `{arg_ty}`, a value through which user code can run"
        ))
    };
    let ty::Ref(_, pointee, _) = *arg_ty.kind() else { return Err(unknown()) };
    let ty::Dynamic(predicates, ..) = *pointee.kind() else { return Err(unknown()) };
    let Some(principal) = predicates.principal_def_id() else { return Err(unknown()) };
    let Some(sources) = minted_trait_object_sources(tcx, body, operand) else {
        return Err(with_no_trimmed_paths!(format!(
            "is handed a `{arg_ty}` that this body did not mint from a known type (it comes \
             from a parameter, a field, a constant or a call), so the code it dispatches to is \
             unknown"
        )));
    };
    let formatting_trait = crate_is_authentic_core(tcx, principal.krate)
        && (tcx.is_diagnostic_item(sym::Debug, principal)
            || tcx.is_diagnostic_item(sym::Display, principal));
    for source in sources {
        let vouched = if formatting_trait {
            dyn_dispatch_reliance::minted_formatter_value_admitted(
                tcx,
                principal,
                source,
                root_def_id,
            )
        } else {
            ty_is_foundational_display(tcx, source)
        };
        if !vouched {
            return Err(with_no_trimmed_paths!(format!(
                "is handed a `{arg_ty}` minted from `&{source}`, whose implementation is neither \
                 core's own at a foundational type nor a local formatting impl with a verdict \
                 of its own"
            )));
        }
    }
    Ok(())
}

/// Does `ty` reach a type through which FOREIGN (non-local, non-sysroot,
/// unverified) user code can run? The three-valued cousin of
/// `ty_is_foundational`: foundational leaves and LOCAL types answer `false`,
/// everything unlisted answers `true` (fail-closed), and sysroot ADTs are walked
/// through their type arguments and instantiated, normalized fields.
/// Coinductive on cycles, memoized per call site.
fn ty_reaches_foreign_user_code<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
) -> bool {
    ty_reaches_foreign_user_code_on_path(tcx, ty, memo, &mut Vec::new())
}

/// Trust (2026-09-26): the bound on nested ADTs this walk expands before it
/// answers `true`. A backstop only — `is_expanding_reentry` below is what cuts the
/// one infinite shape measured — but it makes termination a property of the walk
/// rather than of an argument about which types exist.
const FOREIGN_REACH_MAX_ADT_DEPTH: usize = 256;

/// Trust (2026-09-26): is re-entering `def` at `args` a NON-REGULAR recursion
/// through `outer`, an ADT still being expanded on this path — the same definition
/// at arguments that strictly CONTAIN the outer ones? Mirrors
/// `trust_mir_extract::ty_convert::is_expanding_recursive_adt`, the extractor's cut
/// for the same shape.
fn is_expanding_reentry<'tcx>(
    outer: Ty<'tcx>,
    def: ty::AdtDef<'tcx>,
    args: ty::GenericArgs<'tcx>,
) -> bool {
    let ty::Adt(outer_def, outer_args) = outer.kind() else { return false };
    *outer_def == def
        && args.types().any(|arg| {
            outer_args.types().any(|outer_arg| {
                arg != outer_arg && arg.walk().any(|inner| inner.as_type() == Some(outer_arg))
            })
        })
}

/// Trust (2026-09-26): `ty_reaches_foreign_user_code` with the path of ADTs being
/// expanded. MEASURED DEFECT: without the path the memo was the walk's only cut,
/// and a memo only cuts a type it has SEEN. A NESTED datatype never repeats one:
///
/// ```text
/// pub enum Nested<T> { Leaf(T), Nest(Box<Nested<Vec<T>>>) }
/// pub fn push_ref<'a>(v: &mut Vec<&'a Nested<u8>>, n: &'a Nested<u8>) { v.push(n); }
/// ```
///
/// `Nested<u8>` is local, so its fields are walked; `Box` and `Vec` are sysroot, so
/// their arguments are; that reaches `Nested<Vec<u8>>`, then `Nested<Vec<Vec<u8>>>`,
/// each a NEW type, until the stack runs out. `trustc -Ztrust-verify=on` on those
/// two lines died with SIGBUS in 2 s on stage2 `29b6f15c7` (backtrace: this
/// function through `AdtDef::all_fields`, "recursed 39 times" in the printed cycle);
/// with verification off it compiles. `ty_convert`'s lowering has cut this shape
/// since its `adt_stack` guard existed; this walk, added 2026-09-16, did not.
///
/// THE CUT answers `true` — fail-closed, this predicate's answer for anything it
/// cannot finish ("everything unlisted answers `true`"). It can only withhold a
/// tolerance from a body that is ALREADY failing full verification, never grant
/// one, so the price of a nested datatype is precision, not soundness. A REGULAR
/// recursive type (`List<T>` reaching `List<T>`) never reaches the cut: the memo's
/// coinductive entry answers it first, exactly as before.
fn ty_reaches_foreign_user_code_on_path<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
    path: &mut Vec<Ty<'tcx>>,
) -> bool {
    if let Some(&known) = memo.get(&ty) {
        return known;
    }
    memo.insert(ty, false);
    let reaches = match ty.kind() {
        ty::Bool | ty::Char | ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Str | ty::Never => {
            false
        }
        ty::Ref(_, inner, _)
        | ty::RawPtr(inner, _)
        | ty::Array(inner, _)
        | ty::Slice(inner)
        | ty::Pat(inner, _) => ty_reaches_foreign_user_code_on_path(tcx, *inner, memo, path),
        ty::Tuple(elems) => {
            elems.iter().any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
        }
        ty::Adt(def, args) => {
            // A LOCAL type's own impls are this crate's verified bodies — but a
            // foreign type nested INSIDE it is still foreign: `Vec::<Local(dep::
            // Bomb)>::clear` runs `dep::Bomb::drop` inside the sysroot callee,
            // with no `Drop` terminator in this body for the glue walk to catch.
            // So a local ADT does not stop the walk; it is walked like a sysroot
            // one, and only its OWN code is exempt.
            //
            // Trust (W4 HASHMAP redo, 2026-09-25): a SYSROOT ADT's fields are walked in
            // their DECLARED form (`declared_ty_reaches_foreign_user_code`), so std's
            // `base: hashbrown::HashMap<K, V, S>` is walked like a sysroot type (its
            // arguments and fields still searched: `HashMap<dep::K, V>` is foreign)
            // instead of answering "foreign" at the hashbrown ADT. A hashbrown ADT
            // anywhere ELSE — top level, a type argument, a substituted parameter, a
            // LOCAL type's field — is still foreign (the first arm), which is what
            // keeps a hashbrown value a program obtained from a `rustc_private`
            // dependency out of the std-site credit (see [`HashTableCredit`]). The
            // two walks must agree with `ty_is_foundational`, and a std table of
            // zero-sized elements stays foreign, as every `HashMap` was before.
            //
            // Ported onto the bounded walk (salvage merge, 2026-09-28): the declared
            // walk carries this walk's `path`, and every field it hands back to the
            // instantiated question goes through `ty_reaches_foreign_user_code_on_path`,
            // so the depth bound and `is_expanding_reentry` cut still apply to it.
            let is_local = def.did().is_local();
            // Trust (2026-10-10, CALL-REACH-1 amendment (b)): an ADT of a
            // StableCrateId-allowlisted TCB crate (num-bigint, num-rational,
            // serde_json; `ty_convert::is_authenticated_bignum_crate` and its
            // serde_json twin, a crate NAME and its `StableCrateId`, so a namesake
            // never matches) is not foreign BY ITSELF: its code is a disclosed TCB
            // entry (docs/TCB.md), and the C2 std-map lane credits
            // `HashMap<BigRational, _>` on it (ny-cert's intern map). Like a local
            // ADT it is not a stop: its type arguments and its instantiated fields
            // are still walked, so `Ratio<dep::T>` is foreign.
            let is_tcb = !is_local
                && (trust_mir_extract::is_authenticated_bignum_crate(tcx, def.did().krate)
                    || trust_mir_extract::is_authenticated_serde_json_crate(tcx, def.did().krate));
            if !(is_local
                || is_tcb
                || trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def.did()))
                || (!is_local && std_collection_of_zero_sized_elements(tcx, *def, *args))
            {
                true
            } else if path.len() >= FOREIGN_REACH_MAX_ADT_DEPTH
                || path.iter().any(|outer| is_expanding_reentry(*outer, *def, *args))
            {
                // A nested datatype: its instantiations never repeat, so there is
                // no finite walk to finish. Fail closed (see the doc above).
                true
            } else {
                path.push(ty);
                // Trust (2026-10-01): a `PhantomData<fn() -> T>` marker holds no
                // pointer; only the types its signature names are walked
                // (`phantom_fn_ptr_signature`).
                let reaches = args.types().any(|t| match phantom_fn_ptr_signature(tcx, *def, t) {
                    Some(sig) => sig
                        .iter()
                        .any(|t| ty_reaches_foreign_user_code_on_path(tcx, *t, memo, path)),
                    None => ty_reaches_foreign_user_code_on_path(tcx, t, memo, path),
                })
                    || def.all_fields().any(|field| {
                        if is_local || is_tcb {
                            let field_ty = tcx.type_of(field.did).instantiate(tcx, *args);
                            match tcx.try_normalize_erasing_regions(
                                ty::TypingEnv::fully_monomorphized(),
                                field_ty,
                            ) {
                                Ok(field_ty) => {
                                    ty_reaches_foreign_user_code_on_path(tcx, field_ty, memo, path)
                                }
                                Err(_) => true,
                            }
                        } else {
                            let declared =
                                tcx.type_of(field.did).instantiate_identity().skip_normalization();
                            // Trust (IOERROR-PAYLOAD-1, 2026-10-27): a `fn` pointer field
                            // of core's `io::error::Custom`/`OsFunctions`, which only
                            // sysroot code fills in this graph (`dyn_error_payload`).
                            if matches!(declared.kind(), ty::FnPtr(..))
                                && dyn_error_payload::io_error_fn_pointer_field_is_closed(
                                    tcx,
                                    def.did(),
                                )
                            {
                                return false;
                            }
                            declared_ty_reaches_foreign_user_code(
                                tcx,
                                declared,
                                *args,
                                memo,
                                path,
                                DECLARED_HASH_TABLE_DEPTH,
                            )
                        }
                    })
                    // Trust (r20, 2026-10-07): a local type's own impls are verified
                    // bodies, but what a sysroot callee at it runs THROUGH them is
                    // not only those bodies: `Iterator::count::<L>` drops every
                    // `<L as Iterator>::Item`, and a `dep` type there runs `dep`'s
                    // destructor. See `local_impl_surface`.
                    || (is_local
                        && local_impl_surface::local_impl_surface_reaches_foreign(
                            tcx, *def, *args, memo, path,
                        ));
                path.pop();
                reaches
            }
        }
        // A local closure is a verified body of this crate, but its CAPTURES may
        // carry a foreign value into a sysroot callee that drops or calls it.
        //
        // Trust (2026-10-10, CALL-REACH-1 amendment (a)): and so may its
        // SIGNATURE. A sysroot callee handed a local closure receives what the
        // closure RETURNS, and drops it or hands it on: `String: FromIterator<Box<str,
        // A>>` drops every item `map(|&x| dep::mk(x))` yields, running
        // `dep::DeallocBomb::deallocate` inside `collect` (design H5); its inputs are
        // what the callee builds to call it with. Neither is a capture, so the walk
        // that asked only the captures read that call as reaching nothing. The
        // signature is read with its late-bound regions erased.
        ty::Closure(did, args) => {
            !did.is_local()
                || args
                    .as_closure()
                    .upvar_tys()
                    .iter()
                    .any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
                || tcx
                    .instantiate_bound_regions_with_erased(args.as_closure().sig())
                    .inputs_and_output
                    .iter()
                    .any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
                // Trust (2026-10-14, INSTANCE-WALK-1): a closure of a GENERIC body
                // at concrete arguments runs what its body resolves to there:
                // `Some(x).map(|y| y.a2())` in `g::<u32>` calls the dependency's
                // `<u32 as Act2>::a2`. See `unverified_edges`' instance walk.
                || unverified_edges::local_instance_unverified_reason(tcx, *did, *args).is_some()
        }
        ty::CoroutineClosure(did, args) => {
            !did.is_local()
                || args
                    .as_coroutine_closure()
                    .upvar_tys()
                    .iter()
                    .any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
                || {
                    // Amendment (a), as for a closure: its inputs and what the
                    // coroutine it returns resumes with, yields and returns.
                    let sig = tcx.instantiate_bound_regions_with_erased(
                        args.as_coroutine_closure().coroutine_closure_sig(),
                    );
                    [sig.tupled_inputs_ty, sig.resume_ty, sig.yield_ty, sig.return_ty]
                        .into_iter()
                        .any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
                }
                // INSTANCE-WALK-1, as for a closure.
                || unverified_edges::local_instance_unverified_reason(tcx, *did, *args).is_some()
        }
        ty::Coroutine(did, args) => {
            !did.is_local()
                || args
                    .as_coroutine()
                    .upvar_tys()
                    .iter()
                    .any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
                // INSTANCE-WALK-1, as for a closure.
                || unverified_edges::local_instance_unverified_reason(tcx, *did, *args).is_some()
        }
        ty::FnDef(did, args) => {
            if did.is_local() {
                // Trust (2026-10-10, CALL-REACH-1 amendment (a)): a local fn item is
                // a verified body of this crate, but a sysroot callee handed it
                // receives what it RETURNS and builds what it TAKES (see the
                // closure arm), and a local GENERIC fn item at a dependency's type
                // runs that type's code through its bounds. So its instantiation
                // and its signature at that instantiation are asked; this arm used
                // to answer `false` outright.
                args.skip_binder().types().any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
                    || tcx
                        .instantiate_bound_regions_with_erased(
                            tcx.fn_sig(*did).instantiate(tcx, args.skip_binder()).skip_normalization(),
                        )
                        .inputs_and_output
                        .iter()
                        .any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
                    // Trust (2026-10-14, INSTANCE-WALK-1): and what it CALLS at that
                    // instantiation: `Some(&5u32).map(g2)` hands `map` a `g2::<u32>`
                    // whose `x.a2()` is the dependency's `impl Act2 for u32`. The
                    // instance's MIR is walked (`unverified_edges`' instance walk).
                    || unverified_edges::local_fn_item_instance_reaches_unverified(
                        tcx, *did, args.skip_binder(),
                    )
            } else if trust_mir_extract::def_is_in_real_sysroot_crate(tcx, *did) {
                args.skip_binder()
                    .types()
                    .any(|t| ty_reaches_foreign_user_code_on_path(tcx, t, memo, path))
            } else {
                true
            }
        }
        // Trust (IOERROR-PAYLOAD-1, 2026-10-27): a `dyn core::error::Error` (+ auto
        // traits) in a crate graph where every value of it is a sysroot type
        // (`dyn_error_payload`: no dependency crate, no local `Error` impl, no
        // local allocator, no `#[trust::skip]` item, every local impl of a sysroot
        // trait held). A local type inside such a value answers here as it does
        // anywhere else: held, not foreign. Every other trait object is foreign.
        ty::Dynamic(..) if dyn_error_payload::dyn_is_closed_error_object(tcx, ty) => false,
        _ => true,
    };
    memo.insert(ty, reaches);
    reaches
}

/// Trust (W4 HASHMAP redo, 2026-09-25): the masking-walk twin of
/// [`declared_ty_is_foundational`]: does `declared` — a field type as WRITTEN in a
/// std or hashbrown declaration, in terms of that declaration's generic
/// parameters, which `args` instantiate — reach foreign user code?
///
/// Where it names no hashbrown ADT this is the pre-W4 question on the
/// instantiated, normalized type. Where it does, a hashbrown or sysroot ADT
/// WRITTEN there is walked through its declared arguments and its own declared
/// fields; every type parameter is still judged at the caller's argument, so a
/// dependency type substituted into the table is found. Anything else that names
/// a hashbrown ADT, and an exhausted depth bound, answer `true` (fail-closed).
fn declared_ty_reaches_foreign_user_code<'tcx>(
    tcx: TyCtxt<'tcx>,
    declared: Ty<'tcx>,
    args: ty::GenericArgs<'tcx>,
    memo: &mut FxHashMap<Ty<'tcx>, bool>,
    path: &mut Vec<Ty<'tcx>>,
    depth: u32,
) -> bool {
    if !ty_names_std_hash_table_adt(tcx, declared) {
        let field_ty = ty::EarlyBinder::bind(tcx, declared).instantiate(tcx, args);
        return match tcx
            .try_normalize_erasing_regions(ty::TypingEnv::fully_monomorphized(), field_ty)
        {
            Ok(field_ty) => ty_reaches_foreign_user_code_on_path(tcx, field_ty, memo, path),
            Err(_) => true,
        };
    }
    let Some(depth) = depth.checked_sub(1) else { return true };
    match declared.kind() {
        ty::Ref(_, inner, _)
        | ty::RawPtr(inner, _)
        | ty::Array(inner, _)
        | ty::Slice(inner)
        | ty::Pat(inner, _) => {
            declared_ty_reaches_foreign_user_code(tcx, *inner, args, memo, path, depth)
        }
        ty::Tuple(elems) => elems
            .iter()
            .any(|t| declared_ty_reaches_foreign_user_code(tcx, t, args, memo, path, depth)),
        ty::Adt(def, declared_args)
            if trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def.did())
                || trust_mir_extract::def_is_in_std_hash_table_crate(tcx, def.did()) =>
        {
            declared_args
                .types()
                .any(|t| declared_ty_reaches_foreign_user_code(tcx, t, args, memo, path, depth))
                || def.all_fields().any(|field| {
                    let nested = tcx.type_of(field.did).instantiate(tcx, declared_args);
                    declared_ty_reaches_foreign_user_code(
                        tcx,
                        nested.skip_normalization(),
                        args,
                        memo,
                        path,
                        depth,
                    )
                })
        }
        _ => true,
    }
}

/// Trust (W4 HASHMAP redo, 2026-09-25): does `ty` carry, at any position `walk`
/// reaches (the type itself and every nested type ARGUMENT, never an ADT's
/// fields), an ADT of the crate behind std's hash tables? Such an occurrence was
/// chosen by the program, not written by std: std's own `base` field is only
/// reached through a field. See [`HashTableCredit`].
fn ty_carries_program_chosen_hash_table_adt<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    ty_names_std_hash_table_adt(tcx, ty)
}

/// Trust (HOLE — by-value drop hidden in a foundational consumer, 2026-09-14):
/// is `def_id` a foundational callee that RUNS its type argument's drop glue by
/// value — `core::mem::drop::<T>` or `core::ptr::drop_in_place::<T>`? Such a call
/// drops `T` INSIDE core, so there is no `Drop` terminator in the caller for
/// `drop_ty_has_masked_fail_closed_glue` to catch; the caller reads `T` from the
/// call's generic args and reuses that check instead.
///
/// `core::mem::forget` is DELIBERATELY EXCLUDED — it does NOT run drop glue.
/// Authenticated core only (a spoofed `--crate-name core` dropper is already
/// masked by the crate rule); `mem::drop` by its `mem_drop` diagnostic item and
/// `drop_in_place` by its item name within authentic core (never a `--crate-name`
/// string). A genuine `<S as Drop>::drop` reached here reads `S` the same way and
/// is handled identically.
fn callee_is_foundational_value_dropper(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    if !crate_is_authentic_core(tcx, def_id.krate) {
        return false;
    }
    tcx.is_diagnostic_item(rustc_span::sym::mem_drop, def_id)
        || tcx.opt_item_name(def_id) == Some(rustc_span::sym::drop_in_place)
}

/// Trust (HOLE — masked drop glue, 2026-09-14): does dropping a value of type
/// `root` run drop glue whose panic-freedom is NOT foundational-std TCB — i.e.
/// does its drop-glue closure reach a `Drop` impl in a crate OTHER than
/// std/core/alloc (a verify-off dependency or user type whose `Drop::drop` may
/// `panic!`)?
///
/// WHY CRATE-BASED, NOT PROOF-BASED. `String`/`Vec`/`Box` carry a `Drop` impl in
/// alloc; their dealloc is panic-free BY TCB (docs/TCB.md — Trust does not verify
/// std and every proof is already conditional on its semantics), exactly the same
/// grace the std print backend gets. So a std/core/alloc `Drop::drop` is EXCLUDED
/// (`String` + `println!` must keep compiling — measured), but a foundational
/// CONTAINER still drops its elements, so its component types are STILL explored
/// (`Vec<Bomb>` reaches the user `Bomb::drop` through the container's generic arg).
/// The prove-based `drop_glue_discharges_panic_freedom` is deliberately NOT reused
/// here: it would DECLINE `<Vec<u8> as Drop>::drop` (no static proof) and thereby
/// over-refuse a bare `String` + `println!` that the default policy compiles today.
///
/// FAIL-CLOSED: a `Drop`-bearing ADT whose destructor cannot be named, a
/// fuel-exhausted deep type, a foundational destructor whose type reaches foreign
/// user code (`foundational_destructor_foreign_reach`), and any droppy shape
/// `structural_drop_component_types` cannot enumerate (a trait object, a type
/// parameter, an alias, a coroutine) all resolve to `true`. Reuses the tested
/// transitive component enumerator and its fuel budget.
fn drop_ty_has_masked_fail_closed_glue<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    root: Ty<'tcx>,
) -> bool {
    let mut visited: FxHashSet<Ty<'tcx>> = FxHashSet::default();
    let mut worklist: Vec<Ty<'tcx>> = vec![root];
    let mut fuel = STRUCTURAL_DROP_CLOSURE_FUEL;
    while let Some(ty) = worklist.pop() {
        // Fuel exhausted on a pathological/deep type graph -> fail closed.
        let Some(next) = fuel.checked_sub(1) else { return true };
        fuel = next;
        if !visited.insert(ty) {
            continue;
        }
        if let ty::Adt(adt_def, _) = ty.kind()
            && adt_def.has_dtor(tcx)
        {
            match adt_def.destructor(tcx) {
                // Foundational std/core/alloc `Drop` (Vec/Box/String dealloc):
                // panic-free by TCB. Do NOT cut — its glue still drops the
                // container's components, explored below. AUTHENTICATED by
                // lang-item ownership (`CrateNum`), never the spoofable
                // `--crate-name` string: a dep built `--crate-name alloc` with a
                // panicking `Drop` owns no sysroot lang item, so it is NOT
                // foundational here and falls to the fail-closed arm.
                //
                // Trust (W4 HASHMAP redo, 2026-09-25): OR a destructor of the crate
                // behind std's hash tables (`hashbrown::raw::RawTable`, which every
                // `HashMap`/`HashSet` drop runs), identified STRUCTURALLY
                // (`def_is_in_std_hash_table_crate`: the crate std's `HashMap` field
                // is declared in, never a name; withdrawn when this crate names it
                // directly). The same base entry already credits that destructor as
                // bundled drop glue (`foreign_destructor_admission.rs`); without this
                // arm every body that dropped a `HashMap` was a masked source. NOT A
                // CUT, like the arm it joins: the table's element types are its type
                // arguments, so `HashMap<dep::Bomb, u8>` still reaches `Bomb`.
                //
                // Trust (2026-09-30, the r13 refix's left-open and the r14 review's
                // P2): panic-free BY TCB is a claim about the destructor's OWN code,
                // not about the code its value chose. `BufWriter<W>`'s destructor
                // flushes through `W::write`, `Rc<T>`'s drops its pointee, `Waker`'s
                // calls the vtable it carries, `io::Error`'s drops a boxed `dyn Error`
                // — and this arm used to stop at "foundational", asking only whether
                // a component type has a `Drop` of its own. So the destructor is TCB
                // only when its whole type reaches no foreign user code
                // (`foundational_destructor_foreign_reach`, the rule the memory-safe
                // edge scan shares; the measurement is on that function).
                Some(destructor)
                    if crate_is_authentic_foundational(tcx, destructor.did.krate)
                        || trust_mir_extract::def_is_in_std_hash_table_crate(
                            tcx,
                            destructor.did,
                        ) =>
                {
                    if foundational_destructor_foreign_reach(tcx, ty).is_some() {
                        return true;
                    }
                }
                // Trust (2026-09-21): a destructor THIS COMPILATION PROVED
                // panic-free, on the same shared bar every other premise uses.
                //
                // The header above explains why the prove-based test is not used
                // INSTEAD of the crate test: it declines `<Vec<u8> as Drop>::drop`
                // (no static proof) and would over-refuse a bare `String` +
                // `println!`. That is an argument against SUBSTITUTION, and it is
                // correct. It is not an argument against the UNION, which is what
                // this arm is -- and the lane only ever asked the first disjunct.
                // Same shape as W2, where a gate documented as reusing a route
                // "verbatim" had taken one disjunct of a three-way disjunction.
                //
                // The FMT half of this very `tolerate_default_gap` conjunction
                // already composes exactly this disjunction:
                // `function_format_args_all_foundational_display` falls back to
                // `fmt_target_sink_basis` when `ty_is_foundational_
                // display` says no, landed with the note "The gate was not short of
                // evidence; it never asked." The drop half never got the same
                // treatment, so a local `impl Drop` whose `Drop::drop` this
                // compilation PROVES panic-free -- and prints
                // `destructor PROVES panic-free -> credited` while doing it --
                // still counted as a "masked fail-closed source" and withheld the
                // gap tolerance from the whole function.
                //
                // MEASURED on stage1 before this arm, three files, one difference:
                //   (A) a local `struct S` with an empty `impl Drop`      -> rc=0
                //       (rc=0 even under `-Ztrust-policy=certify`: fully proved)
                //   (B) a bare `println!("hi")`                           -> rc=0
                //       (a tolerated completeness gap; certify rejects it)
                //   (C) the CONCATENATION of (A) and (B)                  -> rc=1
                // Proved plus tolerated came out refused. The reports for (B) and
                // (C) are byte-identical after name normalization with opposite
                // exit codes -- this repo's own signature for "a POLICY gate, not
                // proof, is deciding".
                //
                // NOT A CUT, deliberately: like the foundational arm above this
                // falls through to `structural_drop_component_types`, so a
                // container whose own glue is credited still explores its
                // components and `Vec<Bomb>` still reaches `Bomb`.
                //
                // FALSE-PROOF DIRECTION, which is the one that needs the argument:
                // this credits a destructor ONLY through
                // `drop_glue_discharges_panic_freedom`, which never inspects the
                // impl's source and never trusts a name -- a user `impl Drop` that
                // can panic mints an unproved row in its own body and fails the
                // bar. Measured: the same program with `fn drop(&mut self) {
                // panic!("boom") }` prints `destructor DECLINED -> cut` and stays
                // rc=1 both with and WITHOUT the `println!`. The arm says `false`
                // exactly where it must, which is what
                // `tests/ui/trust/drop_glue_panicking_drop_stays_closed.rs` and the
                // new `drop_glue_proved_local_drop_tolerates_print.rs` pin.
                Some(_) if drop_glue_discharges_panic_freedom(tcx, ty) => {}
                // A non-foundational (user/dep) `Drop` that this compilation did
                // NOT prove, or one that cannot be named: unproven panic-freedom
                // -> fail closed.
                _ => return true,
            }
        }
        match ty.kind() {
            ty::Adt(..)
            | ty::Tuple(_)
            | ty::Array(..)
            | ty::Slice(_)
            | ty::Closure(..)
            | ty::RawPtr(..) => {}
            // Trust (2026-09-30, the r14 review's P2): every OTHER kind that carries
            // drop glue is one the component walk cannot enumerate, and this
            // function's own contract (above) is that such a shape resolves to
            // `true`. It did not: `structural_drop_component_types` yields nothing
            // for it, so the walk simply ended and answered "not masked". A trait
            // object's glue is chosen at run time (`Box<dyn Any>`'s content, a
            // closure capturing one), a type parameter's by each instantiation, an
            // unnormalized alias's by whatever it resolves to, and a coroutine's by
            // the state it is suspended in. MEASURED on stage-1 `f2e5ebbc0f`: a
            // `Box<dyn Any>` dropped at scope end beside `println!("{}", x)` built
            // rc=0 under the default policy, strict and memory-safe while the
            // same body without the print was refused, and a verify-off `main`
            // handing it a box whose destructor writes through a null pointer died
            // with SIGSEGV. A type with no glue (`!needs_drop`: a reference, a
            // scalar, `T: Copy`) runs nothing and stays unmasked.
            _ if ty.needs_drop(tcx, typing_env) => return true,
            _ => {}
        }
        worklist.extend(structural_drop_component_types(tcx, typing_env, ty));
    }
    false
}

/// Trust (assumption ledger, W2.1): the explicit MEMORY-SAFE demotion predicate.
/// A function with no source or inlined `unsafe` is UB-free by Rust's safety
/// guarantee, so an unsupported but memory-safe construct can be recorded as an
/// explicit conditional assumption. Any function containing `unsafe` remains
/// under strict enforcement.
fn memory_safe_demotion_applies<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    memory_safe_mode(tcx) && !function_uses_unsafe(tcx, body)
}

/// Trust (2026-09-19): does this body call through a RUNTIME CODE ADDRESS — a
/// fn-pointer value with no `DefId` to resolve?
///
/// THIS IS CONFORMANCE TO A DOCUMENTED INVARIANT, NOT A NEW POLICY.
/// `trust_types::TRUST_INDIRECT_CALLEE_PATH` — the reserved `@trust-indirect-callee`
/// name extraction stamps on exactly these calls — says in its own doc: "It NAMES
/// a callee, it does not resolve one: nothing may treat it as a known function, a
/// summary key, or a totality claim. A consumer that cannot model an open
/// dispatch must fail closed on it exactly as it would on any other callee whose
/// body is absent." The strict gate did not.
///
/// THE HOLE THIS CLOSES, measured end to end and checked in as
/// `scripts/fn_pointer_witness.sh`:
///
/// ```text
///  // dep.rs, built -Ztrust-verify=off (how dependencies ARE built; the
///  // sysroot itself is built that way)
///  pub fn boom() { panic!(..) }  pub static F: fn() = boom;
///  // user.rs, built -Ztrust-verify=ON
///  pub fn call(f: fn()) { f() }  fn main() { call(dep::F); }
/// ```
///
/// built `rc=0` on the VERIFYING lane and the binary panicked with exit 101.
/// `user::call` carried no obligation row at all. No `unsafe`, no attribute, no
/// exotic flag on the crate under test.
///
/// WHY THE FIRST EARLY RETURN AND NOT THE SECOND. `full_verification_failure`
/// returns `Some` unconditionally when `summary.total == 0`, so the later
/// `legacy_failure.is_none()` return can never fire for a zero-obligation body
/// and a gate added there would be INERT. Measured: `native_run_is_vacuously_clean`
/// is TRUE for this body and for every designed discharge, so that conjunct buys
/// nothing on this population either.
///
/// WHY THIS SHAPE AND NOT `zero_obligation_undischarged_call_funcs`. A gate keyed
/// on that set was built and measured before (see the note further down this
/// function) and broke five of the designed discharges, because their calls are
/// discharged by a reliance CERTIFICATE rather than by the registry, so the set
/// names them too. Every one of those is a `dyn`/trait dispatch with a real
/// `DefId` callee. NONE is an indirect call through a fn pointer: measured,
/// `pub fn call(f: &dyn Fn()) { f() }` and `pub fn call<F: Fn()>(f: F) { f() }`
/// both already mint a real obligation and already refuse. Keying on the absence
/// of a `DefId` therefore separates the hole from every designed discharge
/// structurally, with no evidence channel to build and nothing to keep in step.
///
/// The recognizer shape is the one `local_key_try_with_glue_drift_pin` already
/// uses for its edge-A test: `const_fn_def()` is `None` AND the operand's type is
/// a bare `ty::FnPtr`. Root-scoped by construction — `body` is the body under
/// verification, so std's own admitted indirect call inside `LocalKey::try_with`
/// is not in scope here.
fn function_has_unresolved_indirect_call<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    unresolved_indirect_call_blocks(tcx, body).next().is_some()
        || uncharged_callable::body_mints_requires_carrying_value(tcx, body)
}

/// Trust (2026-10-25, GLR-1): the blocks whose call terminator the indirect-call gate
/// ([`function_has_unresolved_indirect_call`]) refuses, in block order and lazily (the
/// gate stops at the first). Split out of the gate, unchanged, so the row that
/// DISCLOSES a refusal ([`unresolved_indirect_call_gap_row`]) names exactly the sites
/// the gate refuses: one predicate, two readers. The gate's other arm,
/// `uncharged_callable::body_mints_requires_carrying_value`, is not a call site and
/// stays in the gate.
fn unresolved_indirect_call_blocks<'a, 'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &'a Body<'tcx>,
) -> impl Iterator<Item = BasicBlock> + use<'a, 'tcx> {
    // Trust (2026-09-29): the body's own typing environment, so a callable type
    // argument or a reified item is resolved exactly as far as THIS body's
    // generics allow (`T::m` in a generic body names no impl yet).
    let typing_env = body.typing_env(tcx);
    // Trust (2026-09-30, review of the ADT residual): after the calls, a cast that
    // takes an item owing a `requires` out of every later type — a fn pointer or a
    // `dyn` minted from it (`uncharged_callable`).
    // Trust (2026-10-03, the minting-site seam): widened to every value this body mints
    // from such an item that its calls do not show — R4 an unevaluated constant's
    // arguments (an inlined generic callee's promoted at `-Zmir-opt-level=2`), R5 an
    // evaluated constant's allocations (a guard for the trust-ir flips), R6 an
    // inline-asm `sym` operand, and a dropped place's type
    // (`uncharged_callable::body_mints_requires_carrying_value`).
    // Trust (OD-1, 2026-10-04, open shapes): the blocks of this body whose call is an
    // ADMITTED open-dispatch instance-hypothesis site the bridge lowered under the
    // hypothesis (`instance_hypothesis::dispatch_site_blocks`; a propagated call to a
    // hypothesis-carrying local body is not one, its type arguments are asked as
    // before). Such a call is not open here: its panic-freedom is the published
    // `assumption:instance-hypothesis` premise and each concrete instance is charged
    // by its discharge row. Before, `<F as Fn<(u32,)>>::call`
    // on an admitted `F: Fn(u32) -> u32` published only its hypothesis row yet strict
    // refused the body as "an unresolved indirect call" (its dispatched `Self`, `F`,
    // read as a callable type argument), so the rows and the gate disagreed.
    let admitted = instance_hypothesis::dispatch_site_blocks(tcx.sess, body.source.def_id());
    body.basic_blocks.iter_enumerated().filter_map(move |(block, bb)| {
        block_makes_unresolved_indirect_call(tcx, body, typing_env, &admitted, block, bb)
            .then_some(block)
    })
}

/// One block of [`unresolved_indirect_call_blocks`]: the body of the gate's former
/// `any` closure, unchanged.
fn block_makes_unresolved_indirect_call<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    admitted: &FxHashSet<u32>,
    block: BasicBlock,
    bb: &BasicBlockData<'tcx>,
) -> bool {
    let Some(terminator) = &bb.terminator else { return false };
    let (TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. }) =
        &terminator.kind
    else {
        return false;
    };
    // Only the item's own MIR: the recorded blocks are blocks of `optimized_mir`
    // of the item, never of a shim or a promoted body sharing its `DefId`.
    let admitted_site = body.source.promoted.is_none()
        && matches!(body.source.instance, ty::InstanceKind::Item(_))
        && admitted.contains(&block.as_u32());
    // Trust (2026-09-30): the item is read off the operand's TYPE, so a call
    // through a local holding it (`let g = run; g(it)` at `-Zmir-opt-level=0
    // -Zinline-mir=yes`) has its type arguments asked as a constant's are.
    let func_ty = func.ty(&body.local_decls, tcx);
    if let ty::FnDef(callee, args) = *func_ty.kind() {
        // Trust (2026-09-30): a foreign import whose link symbol this crate (or a
        // dependency) defines runs a body verified only under its own `requires`
        // (`foreign_item_symbol_is_defined_by_this_crate`): unresolved.
        if foreign_item_symbol_is_defined_by_this_crate(tcx, callee) {
            return true;
        }
        // At an admitted site only the dispatched `Self` (the first type
        // argument, whose impl the hypothesis covers) is exempt; every other
        // type argument is still asked (fail-closed: a callable handed THROUGH
        // the call is not what the hypothesis names).
        let skip = usize::from(admitted_site);
        return args
            .skip_binder()
            .types()
            .skip(skip)
            .any(|t| callable_type_arg_is_unresolved(tcx, typing_env, t));
    }
    if !matches!(func_ty.kind(), ty::FnPtr(..)) {
        return false;
    }
    // An admitted POINTER site: a fn pointer this body reified from an open
    // trait item at its own parameters, called here (`instance_hypothesis`).
    !admitted_site && !indirect_callee_is_a_reified_constant(tcx, body, func)
}

/// Trust (2026-09-30): is `callee` a foreign import (`extern` block item) whose link
/// symbol THIS crate defines (`#[no_mangle]`, `#[export_name]`, or a `#[link_name]`
/// naming one)? The body that runs is then a local function, verified under its own
/// `requires`, which the call never establishes; and the FFI summary db, keyed on the
/// Rust declaration name, gave a `safe fn close(..)` import libc's demand-free
/// summary while a local `#[no_mangle] extern "C" fn` with a `requires` answered it
/// (review round 19: certify rc=0, the caller panicked). Such a call is unresolved.
/// The same holds when a dependency exports the symbol.
fn foreign_item_symbol_is_defined_by_this_crate(tcx: TyCtxt<'_>, callee: DefId) -> bool {
    if !tcx.is_foreign_item(callee) {
        return false;
    }
    // Compare LINKER symbols, not attribute strings: a leading `\x01` makes a name
    // verbatim, and otherwise the target adds its global prefix (`_` on Mach-O), so
    // `#[link_name = "\x01_my_close"]` IS `my_close` on macOS (review round 20
    // certified both directions of that alias against a raw string compare).
    let linker = |name: &str| -> String {
        match name.strip_prefix('\u{1}') {
            Some(verbatim) => verbatim.to_string(),
            None if tcx.sess.target.is_like_darwin => format!("_{name}"),
            None => name.to_string(),
        }
    };
    let symbol = linker(
        tcx.codegen_fn_attrs(callee).symbol_name.unwrap_or_else(|| tcx.item_name(callee)).as_str(),
    );
    // An assembly label (`global_asm!`, `.globl _close`) defines a symbol no HIR fn
    // names; review round 21 certified a `close` import that this crate's asm bound
    // to a `requires`-bearing fn. With any `global_asm!` here, no import is trusted.
    let crate_has_global_asm = tcx
        .hir_crate_items(())
        .free_items()
        .any(|item| matches!(tcx.def_kind(item.owner_id.to_def_id()), DefKind::GlobalAsm));
    if crate_has_global_asm {
        return true;
    }
    let defined_locally = tcx.hir_crate_items(()).definitions().any(|local| {
        let def_id = local.to_def_id();
        if !matches!(tcx.def_kind(def_id), DefKind::Fn | DefKind::AssocFn)
            || tcx.is_foreign_item(def_id)
        {
            return false;
        }
        let attrs = tcx.codegen_fn_attrs(def_id);
        attrs.contains_extern_indicator()
            && linker(attrs.symbol_name.unwrap_or_else(|| tcx.item_name(def_id)).as_str()) == symbol
    });
    // A DEPENDENCY that exports the symbol answers it just as well (review round
    // 20: a verified dependency's `#[no_mangle]` fn with a `requires`, imported as
    // `close`, certified both crates and aborted). Its exports decode from metadata.
    defined_locally
        || tcx.crates(()).iter().any(|&cnum| {
            tcx.exported_non_generic_symbols(cnum).iter().any(|(exported, _)| {
                matches!(
                    exported,
                    rustc_middle::middle::exported_symbols::ExportedSymbol::NonGeneric(_)
                        | rustc_middle::middle::exported_symbols::ExportedSymbol::NoDefId(_)
                ) && linker(exported.symbol_name_for_local_instance(tcx).name) == symbol
            })
        })
}

/// Trust (2026-09-30): the `requires` question the own-root carve-outs must ask.
///
/// The carve-outs that accept a call because its target "is verified as its own
/// root" hold only for a target whose root verdict is UNCONDITIONAL. A target
/// with a `requires` is proved assuming its precondition, and the call paths
/// those carve-outs accept (a pointer reified from the item, the item handed to
/// a callee as a callable) never establish it. Measured on the stage-1 build of
/// `a449d93d255`: `fn g(x: u8) -> u8 requires x < 10 { t[x as usize] }` over a
/// 10-element `t`, and `pub fn via_ptr(x: u8) -> u8 { let f: fn(u8) -> u8 = g;
/// f(x) }`, built rc=0 under `-Ztrust-policy=certify`, and `via_ptr(15)` panics.
///
/// Does a FUNCTION ITEM (`FnDef(def_id, args)`) reach a body carrying an authored
/// `requires`? A trait item names the trait's declaration, never the impl that
/// runs: `let f: fn(&S) -> u8 = <S as Tr>::m;` over `impl Tr for S { fn m(&self)
/// -> u8 requires self.0 < 10 {..} }` read the DECLARATION, found no `requires`,
/// and certified a caller that panics on `S(15)` (review of 2026-09-30). So a
/// trait item is resolved to its impl and THAT is asked; one this env cannot
/// resolve answers `true`, fail-closed.
fn fn_item_reaches_authored_requires<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    def_id: DefId,
    args: ty::GenericArgs<'tcx>,
) -> bool {
    // A FOREIGN item (`extern` block) has no body here, so nothing verified it "as
    // its own root"; `#[link_name]` can bind it to a local `#[no_mangle]` fn proved
    // only under its `requires` (review round 18 certified a pointer reified from
    // such an alias). Unknown, so true.
    if tcx.is_foreign_item(def_id) || item_has_authored_requires(tcx, def_id) {
        return true;
    }
    if tcx.trait_of_assoc(def_id).is_none() {
        return false;
    }
    if args.has_non_region_param() {
        return true;
    }
    // Only an `Item` names the body that runs. `<dyn Tr as Tr>::m` resolves to
    // `InstanceKind::Virtual`, whose def_id is the trait DECLARATION again: asking
    // it answered "no requires" and certified a pointer that dispatches into a
    // `requires`-bearing impl (review round 17). Anything but an `Item` is
    // unknown here, so it answers true.
    match ty::Instance::try_resolve(tcx, typing_env, def_id, args) {
        Ok(Some(instance)) if matches!(instance.def, ty::InstanceKind::Item(_)) => {
            item_has_authored_requires(tcx, instance.def_id())
        }
        _ => true,
    }
}

/// Any crate: the contract query decodes from metadata for a foreign item.
fn item_has_authored_requires(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    trust_contracts_if_any(tcx, def_id).is_some_and(|bundle| {
        bundle.contracts.iter().any(|contract| contract.kind == TrustContractKind::Requires)
    })
}

/// Trust (2026-09-25): is `ty` — a generic argument of a DIRECT call — a
/// callable the callee will invoke that nobody in this compilation verified?
///
/// `v.iter().copied().fold(100, u32::div_euclid)` is a direct call to core's
/// `fold` whose `F` is the item type `fn(u32, u32) -> u32 {u32::div_euclid}`:
/// the item is called INSIDE `fold`, where neither this body's rows nor vcgen's
/// family recognizers look. Measured (wave-3 adversarial review, probe c02): the
/// root carried NO row at all and the binary panicked. A LOCAL item is verified
/// as its own root — resolved only when that verification owes no caller a
/// precondition (`local_fn_item_is_verified_unconditionally`, 2026-09-29: a
/// `requires`-carrying item handed to `map`/`filter`/`any` was called inside core
/// with its precondition charged to nobody); a constructor has no body; a
/// sysroot item whose own MIR cannot panic (`sysroot_fn_item_cannot_panic` —
/// `<u32 as PartialOrd>::lt` for `sort`) calls nothing that can. Anything else —
/// a foreign item that may panic, or a bare `fn` POINTER type (whose value is
/// unknown) — is as unresolved as an indirect call. Trust (2026-10-03): "may
/// panic" is asked under the session's policy — on the default policy a vanilla
/// sysroot item is resolved (its `runtime_checked` row is tolerated there), on
/// `certify` and memory-safe it is not (`sysroot_callable_item`).
///
/// Trust (2026-09-29): the argument is asked THROUGH the layers core and alloc
/// forward every call through (`peel_fn_forwarding_layers`: `&F`, `&mut F`,
/// `Box<F>`), not only at the top level. The previous "only the TOP-LEVEL
/// argument is asked" let `v.iter().any(&pos)` — `F = &fn(&u32) -> bool {pos}` —
/// fall to `_ => false`, so core called `pos` through `<&F as FnMut>::call_mut`
/// with its `requires` charged to nobody. MEASURED on the stage 1 of the
/// requires-gate change (adversarial review, m3's std): `any(&pos)`, `any(&&pos)`,
/// `let mut f = pos; any(&mut f)`, `any(&<S as Tr>::pos)` (a trait default
/// method), `any(&pos as &dyn Fn(&u32) -> bool)` and a cross-crate `any(&a::pos)`
/// each built exit 0 under `-Ztrust-policy=certify` and divided by zero at run
/// time; `any(&big)` with `big` carrying `requires *x < 100` RETURNED `true` for
/// `u32::MAX` (no overflow check left in `big`). The missing peel also left the
/// caller-supplied callable open (the `scripts/fn_pointer_witness.sh` class,
/// independent of any `requires`): `f: fn(&u32) -> bool` handed as `any(&f)`,
/// `f: &dyn Fn(&u32) -> bool` handed as `any(f)`, `f: &F` with `F: Fn(&u32) ->
/// bool`, and `f: &mut dyn FnMut(&u32) -> bool` each built exit 0 under certify
/// and ran a verify-off caller's dividing function; `f: Box<fn(&u32) -> bool>`
/// passed strict and the default policy. What remains after the peel is asked by
/// kind:
///  * a `dyn` whose principal is, or extends, an `Fn`/`AsyncFn`-family trait:
///    the target is a vtable entry, unknown here;
///  * a type parameter or alias that may implement `FnOnce`/`AsyncFnOnce`
///    (`type_may_be_called_as_fn`): its body is whatever the caller instantiates;
///  * a closure of ANOTHER crate that is not this compiler's sysroot (an opaque
///    `impl Fn` a dependency returned, revealed): verified by nobody here;
///  * a LOCAL closure is verified as its own body, as before;
///  * Trust (2026-09-30): a SYSROOT closure, coroutine-closure or coroutine is
///    asked through its parent's type arguments and its upvars, each as a type
///    argument here would be (`uncharged_callable`, residual L1).
///
/// Trust (2026-10-01): a callable ADT is OPENED, not answered "resolved" by the
/// `_ => false` arm: `AssertUnwindSafe<F>` (and any sysroot or local type with an
/// `Fn`-family impl) forwards the call to what it wraps, so each of its type
/// arguments is asked in its place; a dependency's callable ADT is unresolved.
/// See `forwarded_callables`.
///
/// Trust (2026-09-30, the ADT residual): then, whatever the argument is, a function
/// item owing its caller a `requires` ANYWHERE inside it makes it unresolved — the
/// `Self` of `<Map<Once<u32>, fn(u32) -> u32 {add1}> as Iterator>::reduce`, which the
/// MIR inliner leaves at `-Zmir-opt-level=2` (`uncharged_callable`).
///
/// Trust (W4 ITER-HOF (b), 2026-09-25; rebased onto the requires gate 2026-09-29):
/// a LOCAL item that passes `local_fn_item_is_verified_unconditionally` is resolved
/// only as a NON-generic instance. A verdict on a generic function is per instance,
/// and the instance a type argument hands over is instantiated by no lane of this
/// compilation — see [`local_fn_item_type_arg_is_unverified_instance`].
fn callable_type_arg_is_unresolved<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    ty: Ty<'tcx>,
) -> bool {
    let unresolved = callable_type_arg_is_unresolved_inner(tcx, typing_env, ty)
        || uncharged_callable::ty_carries_requires_carrying_fn_item(tcx, typing_env, ty);
    if unresolved && env_flag_enabled("TRUST_VANILLA_DEBUG") {
        eprintln!("[CALLABLE_TYPE_ARG] unresolved `{ty}`");
    }
    unresolved
}

fn callable_type_arg_is_unresolved_inner<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    ty: Ty<'tcx>,
) -> bool {
    let mut callables = Vec::new();
    forwarded_callables(tcx, typing_env, ty, &mut callables);
    callables.into_iter().any(|ty| forwarded_callable_is_unresolved(tcx, typing_env, ty))
}

/// Trust (2026-10-01): one callable `forwarded_callables` reached, asked by kind.
fn forwarded_callable_is_unresolved<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    ty: Ty<'tcx>,
) -> bool {
    match *ty.kind() {
        ty::FnPtr(..) => true,
        // Trust (2026-09-29): a LOCAL item is resolved only when it names a body
        // this crate verifies and calling it owes no precondition — see
        // `local_fn_item_is_verified_unconditionally`. W4 ITER-HOF (b): and only as
        // a NON-generic instance — see `local_fn_item_type_arg_is_unverified_instance`.
        // Trust (merge 2026-10-14): and never when the item (resolved through a
        // trait to the impl that runs) carries an authored `requires`
        // (`fn_item_reaches_authored_requires`, the 2026-09-30 requires gate), kept
        // as an extra fail-closed disjunct.
        ty::FnDef(def_id, args) if def_id.is_local() => {
            !local_fn_item_is_verified_unconditionally(tcx, typing_env, def_id, args.skip_binder())
                || local_fn_item_type_arg_is_unverified_instance(
                    tcx,
                    typing_env,
                    def_id,
                    args.skip_binder(),
                )
                || fn_item_reaches_authored_requires(
                    tcx,
                    ty::TypingEnv::fully_monomorphized(),
                    def_id,
                    args.skip_binder(),
                )
        }
        // Trust (2026-10-03): asked under the session's policy. On `certify` and
        // memory-safe, which refuse the vanilla-sysroot `runtime_checked` row, only a
        // constructor or a sysroot item shown unable to panic is resolved
        // (`sysroot_callable_item`): `AssertUnwindSafe(std::thread::current)` and a
        // bare `std::thread::park` built exit 0 there through the vanilla arm.
        ty::FnDef(def_id, args) => !sysroot_callable_item::foreign_callable_item_is_accounted(
            tcx,
            def_id,
            args.skip_binder(),
        ),
        ty::Dynamic(predicates, ..) => predicates
            .principal_def_id()
            .is_some_and(|principal| trait_is_or_extends_fn_family(tcx, principal)),
        ty::Closure(def_id, _) | ty::CoroutineClosure(def_id, _)
            if !def_id.is_local()
                && !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def_id) =>
        {
            true
        }
        // Trust (2026-09-30, residual L1): a SYSROOT closure or coroutine — the
        // `map_fold` closure the MIR inliner hands `fold` at `-Zmir-opt-level=2` —
        // is asked through what it was instantiated with; a local one is its own
        // verified body, as before (`uncharged_callable`).
        ty::Closure(..) | ty::CoroutineClosure(..) | ty::Coroutine(..) => {
            uncharged_callable::sysroot_closure_carries_unresolved_callable(tcx, typing_env, ty)
        }
        ty::Param(_) | ty::Alias(..) => type_may_be_called_as_fn(tcx, typing_env, ty),
        // Trust (2026-10-01): a callable ADT `forwarded_callables` did not open —
        // one a dependency defines. Its `Fn` impl is that crate's code, verified
        // by nobody here, exactly like that crate's closure above.
        ty::Adt(adt, _) => {
            !adt_fn_impl_is_opened(tcx, adt.did()) && type_may_be_called_as_fn(tcx, typing_env, ty)
        }
        _ => false,
    }
}

/// Trust (2026-10-01): the callables a type argument HANDS OVER — `ty` itself
/// after `peel_fn_forwarding_layers`, unless it is an ADT that may be called
/// (`type_may_be_called_as_fn`) whose `Fn`-family impl this compilation either
/// verifies (a LOCAL type: the impl is a local body) or trusts as a forwarder (a
/// type of this compiler's sysroot — `AssertUnwindSafe<F>`'s `FnOnce<()>`,
/// `SyncView<F>`'s `Fn<Args>`). Such an ADT is OPENED: every generic type argument
/// is asked in its place, recursively, since calling the wrapper calls whatever it
/// wraps. Opening every type argument rather than "the" wrapped one is the
/// fail-closed direction: an argument the impl never calls can only add a refusal.
///
/// THE HOLE THIS CLOSES, measured on stage 1 of origin/main `486460dbe77` (m3,
/// release-like std): `o.unwrap_or_else(AssertUnwindSafe(trust_probe_boom0))`
/// with `trust_probe_boom0` a `safe fn` of a local `unsafe extern "Rust"` block
/// (its body a verify-off `#[no_mangle]` function dividing by zero) built exit 0
/// under strict, the default policy AND certify, and the program panicked (exit
/// 101); `o.unwrap_or_else(trust_probe_boom0)` was refused on all three.
/// `Box::new(AssertUnwindSafe(..))` of it passed strict and the default policy.
/// The type argument was `AssertUnwindSafe<fn() -> u32 {trust_probe_boom0}>`, an
/// ADT, and fell to `_ => false`. (A `requires`-carrying local item cannot be
/// wrapped this way today: `AssertUnwindSafe` forwards `FnOnce<()>` only, and a
/// zero-argument function's `requires` is either unparseable or refused as
/// vacuous — measured — so the opening covers it for when that changes.)
fn forwarded_callables<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    ty: Ty<'tcx>,
    out: &mut Vec<Ty<'tcx>>,
) {
    let ty = peel_fn_forwarding_layers(ty);
    if let ty::Adt(adt, args) = *ty.kind()
        && adt_fn_impl_is_opened(tcx, adt.did())
        && type_may_be_called_as_fn(tcx, typing_env, ty)
    {
        for arg in args.types() {
            forwarded_callables(tcx, typing_env, arg, out);
        }
        return;
    }
    out.push(ty);
}

/// Trust (2026-10-01): is a callable ADT's `Fn`-family impl one this compilation
/// verifies (a local type) or trusts as forwarding to its type arguments (a type
/// of this compiler's sysroot)? Anything else is a dependency's code.
fn adt_fn_impl_is_opened(tcx: TyCtxt<'_>, adt_def_id: DefId) -> bool {
    adt_def_id.is_local() || trust_mir_extract::def_is_in_real_sysroot_crate(tcx, adt_def_id)
}

/// Trust (2026-09-29): strip the layers core and alloc FORWARD every `Fn`-family
/// call through — `impl<F: Fn<A> + ?Sized> Fn<A> for &F` (and `FnMut`/`FnOnce`),
/// the same for `&mut F`, and `impl<F: Fn<A> + ?Sized, Al> Fn<A> for Box<F, Al>`.
/// Calling any of them calls the `F` underneath, so that `F` is the callable a
/// type argument hands over. Nothing else is peeled HERE: a callable ADT that is
/// not a `Box` (`AssertUnwindSafe<F>`, `SyncView<F>`) is opened by
/// `forwarded_callables`, and any other layer is asked as it stands.
fn peel_fn_forwarding_layers<'tcx>(mut ty: Ty<'tcx>) -> Ty<'tcx> {
    loop {
        ty = match *ty.kind() {
            ty::Ref(_, pointee, _) => pointee,
            _ => match ty.boxed_ty() {
                Some(pointee) => pointee,
                None => return ty,
            },
        };
    }
}

/// Trust (2026-09-29): is `trait_def_id` an `Fn`/`FnMut`/`FnOnce` or
/// `AsyncFn*` trait, or a trait with one among its (transitive) supertraits?
/// A `dyn` of such a trait is callable, and its target is a vtable entry.
fn trait_is_or_extends_fn_family(tcx: TyCtxt<'_>, trait_def_id: DefId) -> bool {
    ty::elaborate::supertrait_def_ids(tcx, trait_def_id).any(|def_id| {
        tcx.fn_trait_kind_from_def_id(def_id).is_some()
            || tcx.async_fn_trait_kind_from_def_id(def_id).is_some()
    })
}

/// Trust (2026-09-29): may the type parameter or alias `ty` be CALLED — does
/// `ty: FnOnce<?A>` or `ty: AsyncFnOnce<?A>` possibly hold in this body's typing
/// environment? Asked of the trait solver rather than of the written bounds, so a
/// supertrait (`F: Pred` with `trait Pred: Fn(&u32) -> bool`) and an associated
/// type's item bound (`<H as Has>::F` with `type F: Fn(&u32) -> bool`) count too.
/// Ambiguity and overflow count as callable (fail-closed); an unbounded `T`
/// cannot be called by the code it is handed to and is not asked further.
fn type_may_be_called_as_fn<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    ty: Ty<'tcx>,
) -> bool {
    use rustc_infer::infer::TyCtxtInferExt;
    use rustc_trait_selection::infer::InferCtxtExt;
    let (infcx, param_env) = tcx.infer_ctxt().build_with_typing_env(typing_env);
    [tcx.lang_items().fn_once_trait(), tcx.lang_items().async_fn_once_trait()]
        .into_iter()
        .flatten()
        .any(|trait_def_id| {
            let inputs = infcx.next_ty_var(rustc_span::DUMMY_SP);
            infcx.type_implements_trait(trait_def_id, [ty, inputs], param_env).may_apply()
        })
}

/// Trust (2026-09-29): may a call to the LOCAL function item `def_id` that is NOT
/// a direct call — the item reified to a fn pointer, or handed to generic code as
/// a value — rest on "it is verified as its own root"?
///
/// Only when that verification is UNCONDITIONAL. A function with a `requires` is
/// verified under it: `fn div10(x: u32) -> u32 requires x != 0 { 100 / x }` proves
/// its division with `x != 0` as an entry hypothesis, and every DIRECT caller is
/// charged a `Precondition` row for it (`add_direct_call_contract_summaries`). The
/// two routes that answer "resolved" for a local item — the reified-constant
/// carve-out of the indirect-call gate and the callable type-argument test — have
/// no call site to charge, so they called such a function for free. MEASURED on
/// stage 1 of origin/main `8b8d68d1abe` (m3's std): `let fp: fn(u32) -> u32 =
/// div10; fp(y)` built exit 0 under `-Ztrust-policy=certify` with one `unknown`
/// row and no diagnostic, and `v.iter().copied().map(div10).last()` / `.count()`
/// and `.filter(pred).last()` built exit 0 under strict and the default policy;
/// each program divided by zero at run time. Worse than a panic: with
/// `fn add1(x: u32) -> u32 requires x < 100 { x + 1 }` reified the same way,
/// certify built exit 0 and `p(u32::MAX)` RETURNED 0 — the verify-on library had
/// no overflow check left in `add1` (its row proved under the `requires`), while
/// the same library built verify-off panics. So the default lane's "keeps its
/// runtime check" premise does not hold for these routes either, and they are
/// refused on every fail-closed lane (docs/KNOWN_HAZARDS.md, "CLOSED 2026-09-29 —
/// a local function's `requires` …").
///
/// The item is asked as NAMED. A trait impl method is never named by any call
/// (every route names the trait's item), so its `requires` is refused at the impl
/// instead (`trait_impl_requires`); a trait DEFAULT method's clause is on the
/// named item and is asked here.
///
/// Fail-closed: `def_owes_caller_precondition` answers from the same contract set
/// the direct-call lane charges, so an unparseable `requires` still counts. An
/// `ensures`-only function keeps the carve-out: its body is proved for every
/// input, and nothing at an indirect call assumes its postcondition (no summary
/// is keyed on `@trust-indirect-callee`). The integer/char/discriminant range
/// preconditions extraction adds are type invariants every well-typed argument
/// already satisfies, so they owe no caller anything and are not asked here.
///
/// Trust (2026-09-29, adversarial review of the change above): "LOCAL" is not
/// yet "verified as its own root". The item must also NAME A BODY this crate
/// verifies (`local_fn_item_resolved_body`). Two local items do not, and each
/// built exit 0 on every lane with the call reaching verify-off code (MEASURED,
/// stage 1 of the requires-gate change and of origin/main `fb9f57688a6` alike):
///  * a `safe fn` declared in a local `unsafe extern "Rust"` block, whose body is
///    a dependency's `#[no_mangle]` function built verify-off — `let fp: fn(u32)
///    -> u32 = trust_probe_boom; fp(y)` passed strict, the default policy and
///    certify and divided by zero; `map(trust_probe_boom)` passed strict and
///    default. The direct call was already refused on all three.
///  * a local TRAIT item whose `Self` is not concrete — `<dyn Tr as Tr>::m0`
///    reified or handed to `map`, `T::m0` in a generic body — whose body is
///    whatever impl the caller supplies, e.g. one in a verify-off crate.
///    `let fp: fn(&T) -> u32 = T::m0` passed certify and panicked in such an
///    impl; the direct calls `d.m0()` were already refused on all three.
/// A trait item is resolved in the body's own typing environment; when it
/// resolves to a different local body (a concrete impl), that body's `requires`
/// is asked too.
fn local_fn_item_is_verified_unconditionally<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    def_id: DefId,
    args: ty::GenericArgs<'tcx>,
) -> bool {
    let debug = env_flag_enabled("TRUST_VANILLA_DEBUG");
    if local_fn_item_owes_caller_precondition(tcx, typing_env, def_id, args) {
        if debug {
            eprintln!(
                "[CALLABLE_TYPE_ARG] local item `{}` owes its caller a `requires`; not resolved",
                tcx.def_path_str(def_id)
            );
        }
        return false;
    }
    // A constructor has no body and cannot panic.
    if matches!(tcx.def_kind(def_id), DefKind::Ctor(..)) {
        return true;
    }
    let verified_here = local_fn_item_resolved_body(tcx, typing_env, def_id, args).is_some();
    if !verified_here && debug {
        eprintln!(
            "[CALLABLE_TYPE_ARG] local item `{}` names no body this crate verifies; not resolved",
            tcx.def_path_str(def_id)
        );
    }
    verified_here
}

/// Trust (2026-09-29): the LOCAL body a call to the local item `def_id` at `args`
/// runs, when that is statically known: `None` for a foreign-item declaration
/// (an `extern` block — its body is another crate's), for a trait item whose
/// impl this body's generics leave open (`T::m`, `<dyn Tr as Tr>::m`, which
/// resolves to a virtual call), for anything that resolves to a shim or to
/// another crate's item, and for an item with no MIR here. Never `None` for a
/// constructor only because callers ask `DefKind::Ctor` first.
fn local_fn_item_resolved_body<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    def_id: DefId,
    args: ty::GenericArgs<'tcx>,
) -> Option<DefId> {
    if !def_id.is_local()
        || tcx.is_foreign_item(def_id)
        || !matches!(tcx.def_kind(def_id), DefKind::Fn | DefKind::AssocFn)
    {
        return None;
    }
    let Ok(Some(instance)) = ty::Instance::try_resolve(tcx, typing_env, def_id, args) else {
        return None;
    };
    let ty::InstanceKind::Item(item) = instance.def else { return None };
    (item.is_local() && !tcx.is_foreign_item(item) && tcx.is_mir_available(item)).then_some(item)
}

/// Trust (2026-09-29): does a call to the local item `def_id` at `args` owe its
/// caller a `requires` — on the item as NAMED (what the direct-call lane
/// charges), or on the local body it resolves to when that is a different item
/// (a concrete impl of a trait item)? Fail-closed toward "owes".
fn local_fn_item_owes_caller_precondition<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    def_id: DefId,
    args: ty::GenericArgs<'tcx>,
) -> bool {
    trust_mir_extract::def_owes_caller_precondition(tcx, def_id)
        || local_fn_item_resolved_body(tcx, typing_env, def_id, args).is_some_and(|item| {
            item != def_id && trust_mir_extract::def_owes_caller_precondition(tcx, item)
        })
}

/// Trust (W4 ITER-HOF (b) self-check, 2026-09-25; rebased onto the requires gate
/// 2026-09-29): "a LOCAL item is verified as its own root" is true of a
/// NON-generic item and of nothing else. A verdict on a generic function is
/// PER-INSTANCE (docs/TCB.md, "What a verdict claims for a
/// GENERIC function"), and an instance handed over as a TYPE ARGUMENT
/// (`v.iter().map(widen::<u32>)`) is called inside the sysroot callee, where no
/// lane of this compilation instantiates it: the `DefId` lane declines a generic
/// body, and the B-lane instantiates only a DIRECT call's callee. Before W4 such a
/// call was refused anyway (its HOF became an absent callee whose `F` is not
/// foundational); W4 routes a fn-item HOF exactly like a closure HOF, so this is
/// where that refusal now has to be stated. It is asked BESIDE
/// [`local_fn_item_is_verified_unconditionally`] (which already refuses an item
/// owing its caller a `requires` and one naming no verified local body) and adds
/// only the per-instance question. `true` — unresolved — for:
///  * an item whose generic arguments still carry a parameter (the caller is
///    itself generic, so no single instance exists here);
///  * a local item whose RESOLVED body ([`local_fn_item_resolved_body`], the
///    item itself or the concrete impl a trait item selects) requires
///    monomorphization (`native_defid_lane_definition_requires_monomorphization`,
///    which ignores lifetimes);
///  * an item that resolves to no local body at all.
/// A constructor has no body and stays resolved, as on the foreign side.
fn local_fn_item_type_arg_is_unverified_instance<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    def_id: DefId,
    args: ty::GenericArgs<'tcx>,
) -> bool {
    if matches!(tcx.def_kind(def_id), DefKind::Ctor(..)) {
        return false;
    }
    if args.has_non_region_param() {
        return true;
    }
    match local_fn_item_resolved_body(tcx, typing_env, def_id, args) {
        Some(body) => native_defid_lane_definition_requires_monomorphization(tcx, body),
        None => true,
    }
}

/// Trust (2026-09-19): is this indirect call's callee operand a fn pointer this
/// body itself REIFIED from a named function — `_1 = g as fn() (ReifyFnPointer)`
/// followed by `copy _1()`?
///
/// Such a call is indirect only in spelling: the target is `g`, statically, and
/// `g` is verified as its own root like any other function — UNCONDITIONALLY only
/// when `g` owes its callers no precondition, which is why a `requires`-carrying
/// `g` is excluded below (2026-09-29). Refusing it would
/// cost completeness and buy no soundness, and it would turn a deliberate guard
/// rail red for the WRONG REASON —
/// `tests/ui/trust/static_str_write_fmt_assumed_total_second_pointer_hop_control.rs`
/// exists to catch exactly that: its header warns that a lane which "declined on
/// the SHAPE it now walks" would make "every pointer-reifying bundle
/// unspendable". Measured: without this carve-out that control was the ONE
/// unexpected casualty of the gate across all 907 `tests/ui/trust` cases.
///
/// FAIL-CLOSED in every direction that is not the exact shape above:
///  * the operand must be a whole local, no projection (a field read is not a
///    reification — `tests/fn-pointer-witness/fragment/f2_pointer_in_a_struct_field.rs`);
///  * that local must have EXACTLY ONE assignment in the whole body (zero means
///    a parameter, which is the hole itself; two or more means the value is not
///    pinned);
///  * that assignment must be a `ReifyFnPointer` cast of a CONSTANT operand — a
///    cast of another local, a transmute, or any other rvalue is refused;
///  * the reified item must be LOCAL, name a body this crate verifies, and owe
///    its callers no precondition (`local_fn_item_is_verified_unconditionally`)
///    — nothing charges its `requires` at this call, and a local `extern`
///    declaration or a trait item whose impl is still open (`T::m`,
///    `<dyn Tr as Tr>::m`) runs code nobody here verified;
///  * the local must never be borrowed or have its address taken anywhere, so no
///    aliased write can reseat it after the reification.
fn indirect_callee_is_a_reified_constant<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func: &rustc_middle::mir::Operand<'tcx>,
) -> bool {
    // Trust (OD-1, 2026-10-04, open shapes): the structural half (one whole local,
    // exactly one assignment, a `ReifyFnPointer` cast of a constant, never borrowed,
    // never written by a call) is `sole_reified_constant_of_callee`, shared with the
    // instance-hypothesis admission of a pointer reified from an open trait item. The
    // predicate on WHAT was reified stays here, unchanged.
    let Some(constant) = sole_reified_constant_of_callee(body, func) else { return false };
    // Trust (2026-09-25): and the reified item must be LOCAL. The
    // carve-out's premise is that the target "is verified as its own root
    // like any other function", which holds only for a function of THIS
    // crate. A sysroot or dependency item is verified by nobody here, so
    // `let p: fn(u32, u32) -> u32 = u32::div_euclid; p(100, b)` built rc=0
    // with no row for the call and panicked (measured, wave-3 assert-gate
    // adversarial review, probe c01). It now falls to the indirect-call gate.
    // Trust (2026-09-29): and its verification must not rest on a
    // precondition the caller owes (`local_fn_item_is_verified_unconditionally`).
    // `let fp: fn(u32) -> u32 = div10; fp(y)`, with `div10` carrying
    // `requires x != 0`, built exit 0 under certify with no row for the
    // call and divided by zero (measured, origin/main `8b8d68d1abe`). The
    // call is not charged here, so it falls to the indirect-call gate.
    // Nor may it be a local `extern` declaration or an open trait item,
    // which name no body this crate verifies (measured, adversarial
    // review: `fp = trust_probe_boom` and `fp = T::m0` passed certify).
    // Trust (2026-09-30, the ADT residual): nor may its type arguments carry
    // an item owing a `requires` (`run::<Map<Once<u32>, fn(u32) -> u32
    // {add1}>>` calls `add1` inside `run`; `uncharged_callable`).
    // Trust (OD-1 open-shapes adversarial review, 2026-10-05): and it must be a
    // NON-generic instance — the per-instance question the type-argument route
    // already asks (`local_fn_item_type_arg_is_unverified_instance`), which this
    // route never did. A verdict on a generic function is per instance (docs/TCB.md),
    // and since OD-1 a generic body's verdict may be CONDITIONAL on instance
    // hypotheses that only a call charges. MEASURED (probes p8/p9, stage 1 of
    // 1177c327fa and of the open-shapes branch): `let f: fn(&T) -> u32 =
    // helper2::<T>; f(t)`, with `helper2<T: Tr2>` carrying the hypothesis
    // `<T as Tr2>::m2`, published no hypothesis for that dispatch and passed the gate
    // as "verified as its own root"; on the branch a caller lowered under `helper`'s
    // hypotheses then passed strict with `m2` named nowhere. Asked identically for a
    // concrete instance (fail-closed: no lane of this compilation instantiates the
    // body a pointer names, unlike a direct call's callee, and whether a concrete
    // mention is charged a discharge row rests on the best-effort callee-first
    // demand order). `requires_callee_inside_adt_type_argument.rs#reify_twin_o3`,
    // a total program reifying `run::<Map<..>>`, is refused for this.
    // Trust (merge 2026-10-14): the 2026-09-30 requires gate is kept as an extra
    // fail-closed conjunct — the reified item (resolved through a trait to the
    // impl that runs) must carry no authored `requires`
    // (`fn_item_reaches_authored_requires`).
    matches!(
        *constant.const_.ty().kind(),
        ty::FnDef(def_id, args)
            if def_id.is_local()
                && local_fn_item_is_verified_unconditionally(
                    tcx,
                    body.typing_env(tcx),
                    def_id,
                    args.skip_binder(),
                )
                && !fn_item_reaches_authored_requires(
                    tcx,
                    ty::TypingEnv::post_analysis(tcx, body.source.def_id()),
                    def_id,
                    args.skip_binder(),
                )
    ) && !uncharged_callable::ty_carries_requires_carrying_fn_item(
        tcx,
        body.typing_env(tcx),
        constant.const_.ty(),
    ) && matches!(
        // Asked LAST, so a `requires` carried inside the type arguments is still
        // named by its own diagnostic (`[CALLABLE_TYPE_ARG]` and the gate's note).
        *constant.const_.ty().kind(),
        ty::FnDef(def_id, args)
            if !local_fn_item_type_arg_is_unverified_instance(
                tcx,
                body.typing_env(tcx),
                def_id,
                args.skip_binder(),
            )
    )
}

/// Trust (OD-1, 2026-10-04, open shapes): the STRUCTURAL half of
/// [`indirect_callee_is_a_reified_constant`]: the one constant a fn-pointer callee
/// operand was reified from in this body, when the value is pinned to it — the
/// operand is a whole local (no projection), that local has EXACTLY ONE assignment
/// in the whole body and it is a `ReifyFnPointer` cast of a constant, the local is
/// never borrowed or has its address taken, and no call writes it. `None` for every
/// other shape. Says nothing about WHAT was reified; each caller asks that itself.
pub(super) fn sole_reified_constant_of_callee<'a, 'tcx>(
    body: &'a Body<'tcx>,
    func: &rustc_middle::mir::Operand<'tcx>,
) -> Option<&'a rustc_middle::mir::ConstOperand<'tcx>> {
    use rustc_middle::mir::{CastKind, Operand, Rvalue};
    let (Operand::Copy(place) | Operand::Move(place)) = func else { return None };
    if !place.projection.is_empty() {
        return None;
    }
    sole_whole_assignment(body, place.local, |rvalue| match rvalue {
        Rvalue::Cast(
            CastKind::PointerCoercion(ty::adjustment::PointerCoercion::ReifyFnPointer(..), _),
            Operand::Constant(constant),
            _,
        ) => Some(&**constant),
        _ => None,
    })
}

/// Trust (OD-1; T6, 2026-10-09): what `pick` reads from the ONLY assignment of the
/// whole local `local` in `body` — `None` when the local is borrowed or has its
/// address taken anywhere (a later reseat would be invisible to this scan), is
/// written through a projection, is a call's destination, or has any number of
/// whole assignments other than exactly one. `let mut p = T::m; if b { p = T::n; }
/// p(t)` is pinned to neither item, whatever the last assignment says: admitting it
/// as `T::n` alone would leave `T::m` never discharged.
///
/// The structural core of [`sole_reified_constant_of_callee`], kept free of what is
/// read so its conjuncts are pinned on hand-built MIR (`trust_verify/tests.rs`,
/// `a_local_assigned_twice_has_no_sole_value`): in a proof session the `-O0` MIR
/// pipeline keeps the call temporary (`_4 = copy _3; _4(..)`) of a local that is
/// assigned twice, which refuses the site before this conjunct is reached, so no UI
/// fixture can see it.
pub(super) fn sole_whole_assignment<'a, 'tcx, T>(
    body: &'a Body<'tcx>,
    local: rustc_middle::mir::Local,
    pick: impl Fn(&'a rustc_middle::mir::Rvalue<'tcx>) -> Option<T>,
) -> Option<T> {
    use rustc_middle::mir::{Rvalue, StatementKind};
    let mut picked = None;
    let mut assignments = 0usize;
    for bb in body.basic_blocks.iter() {
        for stmt in bb.statements.iter() {
            let StatementKind::Assign(boxed) = &stmt.kind else { continue };
            let (dest, rvalue) = &**boxed;
            // Any borrow or raw-pointer take of the local makes a later reseat
            // invisible to this scan.
            match rvalue {
                Rvalue::Ref(_, _, borrowed) | Rvalue::RawPtr(_, borrowed) => {
                    if borrowed.local == local {
                        return None;
                    }
                }
                _ => {}
            }
            if dest.local != local {
                continue;
            }
            if !dest.projection.is_empty() {
                return None;
            }
            assignments += 1;
            picked = pick(rvalue);
        }
        // A call or other terminator that writes the local is not an assignment
        // this scan modelled; refuse rather than reason about it.
        if let Some(term) = &bb.terminator
            && let TerminatorKind::Call { destination, .. } = &term.kind
            && destination.local == local
        {
            return None;
        }
    }
    if assignments == 1 { picked } else { None }
}

fn abort_on_full_verification_failure<'tcx>(

    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &VerificationArtifacts,
    // The tally of the rows this function publishes: its clock count is the
    // engine status note's `timed_out=` (`verifier_status_timed_out_note`).
    published_rows: PublishedRowTally,
    // Trust (2026-10-10, ZERO-ROW-GATE): the publisher's own verdict on a body with
    // zero bridged obligations (`zero_obligation_native_vacuously_clean`); `None`
    // when the body has bridged obligations.
    zero_obligation_vacuously_clean: Option<bool>,
) {
    if let Some(diagnostic) = publication_failure::prepare_full_verification_failure(
        tcx, body, func_path, artifacts, published_rows, zero_obligation_vacuously_clean,
    ) {
        diagnostic.into_original().emit(tcx, body.span);
    }
}

/// Trust: a skip the strict lane does not permit is a build ERROR ("abort" in the
/// name refers to aborting the BUILD — the emitted `ErrorGuaranteed` fails it at the
/// driver checkpoint — not the compile session mid-pass).
///
/// Trust (scope-truncation fix): emit and CONTINUE — no mid-pass `abort_if_errors`,
/// so the remaining functions still get verified. See the soundness note in
/// `report_strict_l0_verification_failure`.
fn abort_full_verification_skipped(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    func_path: &str,
    // Trust (skip taxonomy): WHICH of the four skip verdicts this is. The
    // headline prefix is unchanged — see `SkipClass::headline_suffix` for why
    // the existing pins still match — but the error now says who it is about.
    class: SkipClass,
    // Trust (skip taxonomy): the `assumption:<tag>` row this body ACTUALLY
    // wrote before the policy ruled, if any. `None` under human-only output,
    // for a step-4 narrowed def, and at the no-artifacts site (which writes a
    // `native-verification-gap` UNKNOWN row instead) — the error states a
    // ledger row only when one exists.
    ledger_row: Option<&str>,
    reason: &str,
) {
    emit_full_verification_skipped_at(tcx, body.span, func_path, class, ledger_row, reason, None);
}

/// Trust (skip taxonomy): the ONE emission seam for a skip error.
///
/// Span-addressed rather than body-addressed so the crate checkpoint — which
/// has no `Body` — can emit a deferred error for an inherited body whose
/// declaration did not report (see `trust_reconcile_inherited_skips`). Every
/// emission, from either caller, records the identity in
/// `declared_skip_errors`; that record is what makes the checkpoint
/// reconciliation an observation instead of an assumption.
fn emit_full_verification_skipped_at(
    tcx: TyCtxt<'_>,
    span: rustc_span::Span,
    func_path: &str,
    class: SkipClass,
    ledger_row: Option<&str>,
    reason: &str,
    // `Some(declaration)` marks an error RECOVERED at the checkpoint because
    // the named declaration never emitted one of its own.
    orphaned_from: Option<&str>,
) {
    // Record BEFORE emitting, from the one seam every skip error passes
    // through, so the reconciliation set can never be short of what was
    // printed.
    tcx.sess.with_trust_compiler_state::<SessionSkipCensus, _>(|census| {
        census.declared_skip_errors.insert(func_path.to_owned());
    });
    let mut diag = tcx.dcx().struct_span_err(
        span,
        format!("Trust full verification skipped `{func_path}`{}", class.headline_suffix()),
    );
    // Trust (skip taxonomy): say how many nested bodies this ONE declaration
    // speaks for, so the bodies that are no longer printed separately are still
    // ACCOUNTED FOR here as well as in the census.
    //
    // ROUND 2 — this note states only what it has OBSERVED (N nested bodies
    // named this declaration as the one they deferred to) and no longer asserts
    // the conclusion (that they are therefore covered). Two reasons: it reads a
    // walk-order-populated map, so it can be absent; and the deferral it
    // describes is only verified later. The reconciled verdict — which of those
    // bodies this declaration actually covers, and which were recovered as
    // orphans — is stated once at the crate checkpoint, by
    // `trust_reconcile_inherited_skips`, and that is the authoritative account.
    let covered = inherited_skip_count(tcx, func_path);
    if covered > 0 {
        diag.note(format!(
            "at least {covered} nested body/bodies (closures or nested functions defined inside \
             it) inherit this `#[trust::skip]` and had deferred their own report to this error \
             when it was emitted; bodies walked later are not in this number. Each is still \
             counted individually (and, under JSON transport output, written as its own \
             `assumption:user-opt-out` row). The complete, reconciled `also covers` account for \
             this declaration is stated at the crate checkpoint, after the walk"
        ));
    }
    if let Some(declaration) = orphaned_from {
        diag.note(format!(
            "this body inherits `#[trust::skip]` from `{declaration}`, and its error was \
             deferred to that declaration — but `{declaration}` emitted no skip error of its \
             own in this compilation, so the deferral would have LOST a report. The crate \
             checkpoint recovered it here"
        ));
        diag.note(
            "the deduplication is verified at the crate checkpoint, not assumed from walk \
             order: every deferred body is reconciled against the set of declarations that \
             actually reported, and an unmatched one is emitted rather than dropped",
        );
    }
    if let Some(tag) = ledger_row {
        diag.note(format!(
            "this skip is also recorded as an `assumption:{tag}` transport row (outcome \
             `skipped`, never proof), so the premises this crate's result rests on are \
             enumerable; the row does not make the skip acceptable under this policy"
        ));
    }
    diag = diag
        .with_note(reason.to_string())
        .with_note(class.attribution())
        .with_note("this skip is not permitted under strict batteries-on verification; unsupported MIR and user opt-outs become explicit unverified assumptions only under a nonfatal policy, while strict scope accepts no unproved in-scope function");
    diag.emit();
}

/// Trust (skip taxonomy): the reconciliation itself, with no `tcx` in it.
///
/// Split out so the property this whole lane rests on — *a deferred body whose
/// declaration did not report is returned as an orphan, for every combination
/// of inputs* — is decided by a function that a unit test can drive directly,
/// rather than only by a compiler run that happens to exhibit the state.
///
/// Returns `(also-covers account, orphans in deterministic order, how many
/// deferrals actually withheld an error)`.
fn reconcile_inherited_skips<'a>(
    deferred: &'a [DeferredInheritedSkip],
    declared: &std::collections::BTreeSet<String>,
) -> (std::collections::BTreeMap<String, usize>, Vec<&'a DeferredInheritedSkip>, usize) {
    let mut covered: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    let mut orphans: Vec<&DeferredInheritedSkip> = Vec::new();
    let mut demanding = 0usize;
    for entry in deferred {
        if entry.demanded_error {
            demanding += 1;
        }
        // The ONLY admissible reason to stay silent about this body is that the
        // declaration it was deferred to was OBSERVED emitting a skip error.
        if declared.contains(&entry.origin) {
            *covered.entry(entry.origin.clone()).or_insert(0) += 1;
        } else if entry.demanded_error {
            orphans.push(entry);
        }
    }
    orphans.sort_by(|a, b| a.func_path.cmp(&b.func_path));
    (covered, orphans, demanding)
}

/// Trust (skip taxonomy): VERIFY the inherited-skip deduplication at the crate
/// checkpoint, and state its account from the reconciled sets.
///
/// Runs unconditionally on every enabled crate, after the complete eager walk.
/// Two jobs, in order:
///
///   (a) FAIL-CLOSED RECONCILIATION. Each `DeferredInheritedSkip` whose own
///       decision demanded an error is matched against `declared_skip_errors`
///       — the identities on which a skip error was OBSERVED this compilation.
///       An unmatched entry is an ORPHAN: its report was deferred to a
///       declaration that never reported, which is exactly the path by which a
///       withheld finding could reach a green build. Its deferred error is
///       emitted here, so the build fails on it. Nothing about walk order,
///       `classify_def` agreement or policy agreement is assumed; the
///       conclusion those premises were supposed to guarantee is checked.
///
///   (b) THE ACCOUNT. `also covers N` is recomputed here from the reconciled
///       pairs (deferred body -> a declaration that DID report). The inline
///       note on each declaration's error remains a convenience that may be
///       absent; this one is complete by construction because it is computed
///       after the walk has finished, from both sets at once.
///
/// It cannot redden a build that had nothing suppressed: `demanded_error` is
/// `false` in every advisory/nonfatal lane, where no skip error was going to
/// be printed at all, so those entries carry no obligation and the account is
/// not stated.
fn trust_reconcile_inherited_skips(tcx: TyCtxt<'_>) {
    let Some((deferred, declared)) =
        tcx.sess.with_trust_compiler_state::<SessionSkipCensus, _>(|census| {
            if census.deferred_inherited.is_empty() {
                None
            } else {
                Some((census.deferred_inherited.clone(), census.declared_skip_errors.clone()))
            }
        })
    else {
        return;
    };
    let (covered, orphans, demanding) = reconcile_inherited_skips(&deferred, &declared);
    // (a) Emit every orphan's deferred error, in a deterministic order.
    for entry in &orphans {
        emit_full_verification_skipped_at(
            tcx,
            tcx.def_span(entry.def_id),
            &entry.func_path,
            entry.class,
            entry.ledger_row,
            &entry.reason,
            Some(&entry.origin),
        );
    }
    if demanding == 0 {
        // Nothing was actually suppressed from the output; there is no account
        // to state and no obligation to discharge.
        return;
    }
    // (b) State the reconciled account once per crate. Reached only on a
    // compilation that was already printing skip errors.
    let folded: usize = covered.values().sum();
    let mut lines = vec![format!(
        "Trust skip deduplication account (reconciled at the crate checkpoint): {folded} nested \
         body/bodies were reported through {} enclosing declaration(s) instead of separately, \
         and {} had no reporting declaration and were emitted individually above",
        covered.len(),
        orphans.len()
    )];
    for (origin, n) in &covered {
        lines.push(format!("  {origin}: also covers {n}"));
    }
    for entry in &orphans {
        lines.push(format!(
            "  [orphan, recovered] {} (declared by {})",
            entry.func_path, entry.origin
        ));
    }
    lines.push(
        "this account is computed after the complete walk from the deferred set and the set of \
         declarations that actually emitted a skip error, so it cannot depend on the order \
         bodies were visited in"
            .to_string(),
    );
    tcx.dcx().note(lines.join("\n"));
}

/// The step-4 bootstrap library verification lane, read from the shim's IPC
/// env exactly once per process. Unset (every build except an explicit
/// `TRUST_BOOTSTRAP_VERIFY_LIBRARY` invocation) parses to the lane's `off()`
/// state, under which `classify_def` degenerates to `classify_crate`.
fn step4_library_lane() -> &'static trust_mir_extract::policy::LibraryVerificationLane {
    static LANE: std::sync::OnceLock<trust_mir_extract::policy::LibraryVerificationLane> =
        std::sync::OnceLock::new();
    LANE.get_or_init(trust_mir_extract::policy::LibraryVerificationLane::from_env)
}

/// Trust (§5 step 4, wiring B): whether the library lane NARROWED this def —
/// crate-level classification says `UpstreamRustModified`, def-level says
/// `TrustOwnedDefault`. Keyed on the narrowing itself, not on
/// `unsupported_is_failure()` alone: every ordinary local def is
/// `TrustOwnedDefault` too, and their skip semantics must not change.
fn step4_lane_narrowed_def<'tcx>(tcx: TyCtxt<'tcx>, def_id: DefId) -> bool {
    use trust_mir_extract::policy::PolicyBucket;
    trust_mir_extract::policy::classify_crate(tcx, def_id.krate)
        == PolicyBucket::UpstreamRustModified
        && trust_mir_extract::policy::classify_def(tcx, def_id, step4_library_lane())
            == PolicyBucket::TrustOwnedDefault
}

fn verification_decision<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    policy: &TrustVerifyPolicy,
) -> TrustVerifyDecision {
    let mir_source = body.source;
    let synthetic_instance = matches!(
        mir_source.instance,
        ty::InstanceKind::Intrinsic(..) | ty::InstanceKind::Virtual(..)
    );
    // Trust: 1.99 — upstream collapsed every compiler-generated shim variant
    // (DropGlue, CloneShim, FnPtrShim, ReifyShim, VTableShim, ClosureOnceShim,
    // ThreadLocalShim, ConstructCoroutineInClosureShim, FnPtrAddrShim,
    // AsyncDropGlueCtorShim, …) into `InstanceKind::Shim(ShimKind)`. One arm now
    // covers the same set by construction, including future shim kinds.
    let compiler_generated_shim = matches!(mir_source.instance, ty::InstanceKind::Shim(_));

    let def_id = mir_source.def_id();

    // Crate-role strings are untrusted reporting metadata. They must not alter
    // this decision: accepting `dependency`/`build-script` here let a raw
    // compiler invocation silently opt out while appearing Targo-scoped. The
    // explicit verifier off-switch is handled before this pass exists.

    // Trust #verifier-perf: Trust's own verification PIPELINE crates
    // (trust-vc*, trust-mc*, trust-wp*, trust-vcgen, trust-router,
    // trust-backprop, …) now self-verify like any other Trust-owned crate.
    //
    // They were previously blanket-skipped because self-verifying them hung
    // for hours at 100% CPU with FLAT RSS. That signature is a compute-bound
    // loop over already-allocated data — i.e. the accidentally-quadratic
    // O(n*m) result-assembly scans (now O(n+m)), NOT a non-terminating /
    // allocating extraction loop. With those scans fixed AND the per-function
    // wall-clock budget bounding solver dispatch (a pathological function
    // degrades its obligations to Unknown rather than hanging), the verifier
    // terminates on its own pipeline. Self-verification of the verifier is the
    // core motivation of the project, so the blanket skip is removed.

    // Trust #37: per-crate policy bucket. External dependencies (syn,
    // serde, the upstream `cargo` tool's dep tree, …) are not Trust-owned
    // code and have no Trust specs — the verifier can only ever produce
    // "Unsupported" rows for them, and doing so on heavy-generic crates
    // like `syn` costs *hours* per build (observed: 1h+ on syn alone
    // while building the `targo` tool from upstream cargo source). The
    // policy-bucket model (Codex review): external/upstream code normally gets
    // boundary extraction, not full per-function obligations. Until a
    // dedicated boundary-extraction pass exists, "boundary extraction" means
    // skip unless dependency verification is explicitly requested. Full mode is
    // fail-closed for the selected/local crate by default; dependency scope is a
    // separate opt-in so ordinary Cargo dependency graphs remain buildable.
    match verification_scope_policy_decision(
        // Trust (§5 step 4, wiring A): per-DEF classification. With the
        // bootstrap library lane unset, `classify_def` is `classify_crate` by
        // construction; under TRUST_BOOTSTRAP_SHIM_VERIFY_UNITS it narrows the
        // targeted core::num defs to TrustOwnedDefault so they are VERIFIED
        // rather than boundary-skipped. This is the only compiler consumer of
        // the bucket.
        trust_mir_extract::policy::classify_def(tcx, def_id, step4_library_lane()),
        def_id.is_local(),
        // Trust (cross-crate value composition): the per-DEF bundling-scope
        // bit. See `verification_scope_policy_decision` for what it suppresses
        // and why it is not `include_dependencies`. `false` for every local
        // def, so no ordinary compilation changes.
        declared_bundle_scope_subject(tcx, def_id),
        policy,
    ) {
        TrustVerifyDecision::Verify => {}
        skip @ TrustVerifyDecision::Skip(_) => return skip,
    }

    // Trust (CB4): rustc's libtest harness code (a builtin `#[test]` runner
    // closure, the harness `main`) is EXCLUDED — on provenance plus an exact MIR
    // shape check, and only for non-shim, non-promoted `Item` bodies; see
    // `test_harness_exclusion`. A harness body that fails the shape check falls
    // through and is verified exactly as before.
    if !synthetic_instance
        && !compiler_generated_shim
        && let test_harness_exclusion::HarnessDecision::Exclude(exclusion) =
            test_harness_exclusion::decide(tcx, body)
    {
        trace!("Trust: excluding libtest harness body {def_id:?}");
        return TrustVerifyDecision::Skip(TrustVerifySkipReason::TestHarnessSynthesized(exclusion));
    }

    // `#[trust::skip]` is an explicit advisory assumption. The policy layer
    // rejects it under full verification instead of silently shrinking the
    // obligation inventory.
    if !synthetic_instance && !compiler_generated_shim && item_has_trust_skip_attr(tcx, def_id) {
        trace!("Trust: skipping {def_id:?} per #[trust::skip]");
        return TrustVerifyDecision::Skip(TrustVerifySkipReason::UserOptOut);
    }

    // Keep `#[trust::skip]` precedence when both attributes are present: skip
    // remains strict-fatal, whereas assume_total is the narrower audited lane.
    if !synthetic_instance
        && !compiler_generated_shim
        && item_has_trust_attr(tcx, def_id, "assume_total")
    {
        // Trust (D8-P0, 2026-09-23): totality is not validity. A body that can
        // perform an unsafe operation is verified in full; see
        // `validity_transmute::assume_total_cannot_cover_body`. Trust (2026-09-30):
        // nor is it a callee's `requires`, which a skipped body charges at no call:
        // `uncharged_callable::assume_total_cannot_cover_calls`.
        // Trust (r15, 2026-10-07): both revocations are asked and each one that fires
        // says so — the unverified-edge enumeration (`unverified_edges`, inside
        // `assume_total_cannot_cover_body`) now also names a dependency call, a
        // reified pointer or a minted vtable, which can be the same site a callee's
        // `requires` makes uncovered, and neither reason may hide the other.
        let cannot_cover_body = validity_transmute::assume_total_cannot_cover_body(tcx, body);
        if cannot_cover_body {
            validity_transmute::warn_assume_total_does_not_cover_unsafe(tcx, def_id, body);
        }
        let uncovered_calls = uncharged_callable::assume_total_cannot_cover_calls(tcx, body);
        if let Some(uncovered) = &uncovered_calls {
            uncharged_callable::warn_assume_total_does_not_cover_calls(tcx, def_id, uncovered);
        }
        if !cannot_cover_body && uncovered_calls.is_none() {
            trace!("Trust: skipping {def_id:?} per #[trust::assume_total] (recorded assumption)");
            return TrustVerifyDecision::Skip(TrustVerifySkipReason::AssumedTotal);
        }
    }

    if matches!(tcx.def_kind(def_id), DefKind::Closure) {
        if let Some(local_def_id) = def_id.as_local() {
            let closure_hir_id = tcx.local_def_id_to_hir_id(local_def_id);
            // Trust (contract-checker closure false REFUTATION, P0): a closure nested
            // under a `LocalSource::Contract` binding is rustc's inherited
            // `__requires_checker` / `__ensures_checker` compatibility machinery
            // (or a user closure nested inside such a predicate). It is never Trust
            // proof inventory: first-class clauses are the canonical proposition,
            // Trust-active compilations reject the legacy runtime projection, and
            // the explicit vanilla-compatibility lane disables Trust verification.
            // Verifying it as a standalone function drops the parent's
            // `#[requires]` over the captured params (the capture is a projected
            // place, so the requires formula cannot even bind by name), which let
            // the native lane REFUTE e.g. the `x + 1` inside
            // `ensures(move |ret| *ret == x + 1)` with an unconstrained capture —
            // a false refutation of unreachable code (a verified counterexample of
            // the ISOLATED function is not a whole-program counterexample).
            // Skipping it is sound for Trust: no invocation-selected compatibility
            // projection may add this closure to the proof inventory. Certified
            // monitors are derived from the canonical proposition instead.
            if tcx.hir_parent_iter(closure_hir_id).any(
                |(_, node)| matches!(node, Node::LetStmt(local) if matches!(local.source, LocalSource::Contract)),
            )
            {
                trace!("Trust: skipping contract-generated closure {def_id:?}");
                return TrustVerifyDecision::Skip(TrustVerifySkipReason::ContractGeneratedClosure);
            }
        }
    }

    if let TerminatorKind::Unreachable = body.basic_blocks[START_BLOCK].terminator().kind {
        // An uninhabited BY-VALUE argument means no call can exist (a reference
        // to an uninhabited type is itself inhabited, so `&!` is excluded).
        if let Some(local) = def_id.as_local() {
            let module = tcx.parent_module_from_def_id(local);
            let typing_env = ty::TypingEnv::post_analysis(tcx, def_id);
            if body
                .args_iter()
                .any(|arg| !body.local_decls[arg].ty.is_inhabited_from(tcx, module, typing_env))
            {
                trace!("Trust: skipping uncallable function {def_id:?} (uninhabited argument)");
                return TrustVerifyDecision::Skip(TrustVerifySkipReason::UninhabitedArgument);
            }
        }
        trace!("Trust: skipping unreachable function {def_id:?}");
        return TrustVerifyDecision::Skip(TrustVerifySkipReason::UnreachableStart);
    }

    // Trust #verifier-perf: cheap MIR-shape supportability check. Cost
    // bounded by one walk of local_decls + statements/terminators. If the
    // function carries a Trust contract attribute we always verify; the
    // classifier short-circuits on `has_contracts` so spec-bearing code
    // is never silently skipped.
    //
    // This skip path *only* prevents the expensive trust-ir lowering on
    // functions whose MIR shape provably can't lower (pattern types,
    // un-monomorphized generic params, escaped binders, coroutines).
    // The classifier is intentionally conservative: false negatives are
    // tolerable (we waste one expensive lowering, same as today); false
    // positives would mask verifiable functions and are not.
    //
    // Avoid instantiating the on-disk contract query for local definitions that
    // cannot carry contracts; extern definitions still decode their metadata.
    let has_contracts = !synthetic_instance
        && !compiler_generated_shim
        && trust_contracts_if_any(tcx, def_id).is_some_and(|bundle| !bundle.is_empty());
    match trust_mir_extract::supportability::classify(tcx, body, has_contracts) {
        trust_mir_extract::supportability::Supportability::Unsupported(reason) => {
            trace!("Trust: classifier rejects {def_id:?}: {reason:?}");
            return TrustVerifyDecision::Skip(TrustVerifySkipReason::TreatedAsAssumption(reason));
        }
        trust_mir_extract::supportability::Supportability::SpecBearing
        | trust_mir_extract::supportability::Supportability::Inferrable => {}
    }

    TrustVerifyDecision::Verify
}

/// Trust (cross-crate value composition): the per-def input to
/// [`verification_scope_policy_decision`]'s scoped suppression.
///
/// `false` for every LOCAL def, so no ordinary compilation is affected, and
/// `false` for every non-local def outside the caller-declared bundling scope.
///
/// A/B measurement switch, DEFAULT ON, on the same discipline as
/// `TRUST_NO_BUNDLE_DECLARED` (which also turns this off, since the scope is
/// what it reads): `TRUST_COMPOSE_NO_SCOPE=1` reverts EDIT 2 ALONE, so the
/// pre-registered "Edit 1 without Edit 2 is a +0" liveness control runs on the
/// SAME binary as the full lane instead of needing a second build. Turning it
/// on can only restore a scope SKIP — i.e. less verification, never more — so
/// there is no setting of it that admits anything.
fn declared_bundle_scope_subject(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    !def_id.is_local()
        && !env_flag_enabled("TRUST_COMPOSE_NO_SCOPE")
        && native_bundle_crate_is_declared(tcx, def_id)
}

/// Trust (cross-crate value composition): the two SCOPE skips, plus the scoped
/// per-def suppression that lets a build-declared bundling scope be verified as
/// a SUBJECT rather than only read as bytes.
///
/// # Why a scoped bit and not `-Ztrust-verify-include-dependencies`
///
/// Both scope skips are COST policy: `NonLocalMir` keeps an ordinary build from
/// verifying its whole dependency graph, and `ExternalDependencyScope` keeps it
/// out of `syn`-shaped generic code where the verifier can only ever produce
/// `Unsupported` rows (measured: 1h+ on `syn` alone). Neither is a soundness
/// gate, and the postcondition-reuse lane cannot work without lifting one:
/// [`callee_postconditions_are_reusable`] forces `trust_proof_results` on the
/// callee, and the query provider re-enters [`verification_decision`], which
/// returns `Skip(NonLocalMir)` for every non-local def and therefore `None`.
/// Widening the reuse gate WITHOUT this refuses one conjunct later.
///
/// `include_dependencies` is the wrong lever, and measurably so: it is GLOBAL
/// and also flips `skip_is_full_verification_failure`, so every OTHER crate's
/// `NonLocalMir` skip becomes a build abort. The bit here is per-def, derived
/// from the same caller-side `-Ztrust-bundle-foreign-crate` declaration the
/// bundling lane already runs on, and never touches `TrustVerifyPolicy` — so
/// the artifact cache key (which records `include_dependencies`) is unchanged
/// and every def outside the declared scope decides exactly as before.
///
/// # The bucket conjunct (widened to `ExternalDep` by D4-A, 2026-09-24)
///
/// This once admitted `TrustOwned*` only, on the reasoning that an
/// `ExternalDep` crate's gaps would be recorded as ASSUMPTION rows
/// (`unsupported_is_failure() == false`). That method has no compiler caller —
/// this decision is the only compiler consumer of the bucket — so the bucket
/// changes skip vs. verify here and never how a verdict is graded (measured: one
/// `clamp_index` body minted a verdict named `trust_xcbundle_dep` and none named
/// `xcbundle_dep`). The sysroot (`UpstreamRustModified`) and `Unknown` stay
/// out. The conjunct lives in `foreign_rederivation` so the bar's re-derivation
/// predicate reads the same one; the drop-glue premise does NOT get the
/// widening (`foreign_rederivation::dependency_destructor_withheld_from_
/// rederivation`, the X1 rule). Cost stays demand-bounded: a declared body is
/// verified only when the shared bar or the postcondition-reuse lane asks for
/// its verdict, and both go through `foreign_rederivation::
/// admit_foreign_rederivation`'s per-body and per-crate bounds first.
///
/// # What it does NOT suppress
///
/// Everything after the scope decision still applies to the foreign body:
/// `#[trust::skip]`, `#[trust::assume_total]`, the contract-closure carve-out,
/// the unreachable-start skip, and the supportability classifier. Any of those
/// yields a non-`Verify` decision, hence `None` from the query, hence a refusal
/// at the reuse gate. Fail-closed.
fn verification_scope_policy_decision(
    policy_bucket: trust_mir_extract::policy::PolicyBucket,
    def_id_is_local: bool,
    declared_bundle_scope: bool,
    policy: &TrustVerifyPolicy,
) -> TrustVerifyDecision {
    // Scoped, per-def suppression of BOTH scope skips. It was written as a
    // suppression of both so that widening the bucket set could not silently
    // re-open one of them — and D4-A (2026-09-24) did widen it: the bucket
    // conjunct now admits `ExternalDep`, so a declared `ExternalDep` def skips
    // the `ExternalDep` arm below through this suppression. The conjunct is
    // shared with the bar's re-derivation predicate; see
    // `foreign_rederivation::declared_scope_bucket_is_rederivable`.
    let scoped_bundle_subject = declared_bundle_scope
        && !def_id_is_local
        && foreign_rederivation::declared_scope_bucket_is_rederivable(policy_bucket);

    if !scoped_bundle_subject {
        if matches!(policy_bucket, trust_mir_extract::policy::PolicyBucket::ExternalDep)
            && should_skip_external_dep_body(def_id_is_local, policy)
        {
            return TrustVerifyDecision::Skip(TrustVerifySkipReason::ExternalDependencyScope);
        }

        // Trust: advisory and full verification verify local-crate
        // MIR only. Explicit dependency scope includes cross-crate inlined MIR
        // bodies.
        if should_skip_non_local_mir_for_policy(def_id_is_local, policy) {
            return TrustVerifyDecision::Skip(TrustVerifySkipReason::NonLocalMir);
        }
    }

    TrustVerifyDecision::Verify
}

fn should_skip_non_local_mir_for_policy(def_id_is_local: bool, policy: &TrustVerifyPolicy) -> bool {
    if def_id_is_local || policy.includes_non_local_mir() {
        return false;
    }
    true
}

fn should_skip_external_dep_body(def_id_is_local: bool, policy: &TrustVerifyPolicy) -> bool {
    if policy.includes_non_local_mir() {
        return false;
    }
    // A body from the crate currently being compiled is never an external
    // dependency — verify first-party (local) MIR regardless of corpus policy.
    // Previously local bodies were skipped as ExternalDependencyScope unless
    // TRUST_VERIFY_POLICY requested the example corpus, which silently hid all
    // first-party verification (every `targo trust check` returned 0 proved).
    if def_id_is_local {
        return false;
    }
    // Non-local bodies remain out of external-dependency scope by default.
    true
}

/// Whether `get_all_attrs(did)` is safe to query. rmeta never encodes an
/// attributes entry for some def kinds (`should_encode_attrs` in
/// `rustc_metadata::rmeta::encoder` — notably `DefKind::ForeignMod`, i.e.
/// `extern` blocks), and the decoder's missing-entry fallback in
/// `get_item_attrs` asserts the def is a `Ctor` — so querying such a def
/// CROSS-CRATE is a guaranteed ICE (`decoder.rs` `ForeignMod != Ctor`,
/// hit by the `item_has_trust_skip_attr` ancestor walk on any resolved
/// `libc` foreign fn, e.g. aterm-pty's `unix::fd_is_tty` → `libc::isatty`:
/// the extern-block ancestor has no encoded attributes). Local defs resolve
/// through HIR and are always safe. Skipping a non-local ancestor here loses
/// nothing: an attribute on it would not have been encoded anyway. `Ctor` is
/// NOT excluded — the decoder fallback redirects it to its parent by design.
fn attrs_queryable(tcx: TyCtxt<'_>, did: DefId) -> bool {
    if did.is_local() {
        return true;
    }
    !matches!(
        tcx.def_kind(did),
        DefKind::ForeignMod
            | DefKind::ExternCrate
            | DefKind::Use
            | DefKind::AnonConst
            | DefKind::OpaqueTy
            | DefKind::GlobalAsm
            | DefKind::TyParam
            | DefKind::ConstParam
            | DefKind::LifetimeParam
            | DefKind::SyntheticCoroutineBody
            | DefKind::Static { nested: true, .. }
    )
}

/// Check whether an item has a `#[trust::skip]` tool attribute.
///
/// Consumer crates opt in with `#![feature(register_tool)]` and
/// `#![register_tool(trust)]` at the crate root, then apply
/// `#[trust::skip]` to any item that should be excluded from the
/// trust_verify MIR pass. Tool attributes are preserved verbatim by
/// `get_all_attrs` (unlike built-in attrs which get parsed into typed
/// `AttributeKind` representations and stripped from the raw attr
/// list), so a path-based match on `[trust, skip]` is the correct
/// detection idiom.
///
/// Items matching this attribute get `TrustVerifySkipReason::UserOptOut`.
/// Every policy records an `assumption:user-opt-out` row for it (under JSON
/// transport output); a fail-closed policy additionally rejects the skip as an
/// unproved coverage gap. A closure or nested fn that only INHERITS the
/// attribute reports through its declaration — see
/// [`trust_skip_attr_inherited_from`].
fn item_has_trust_skip_attr(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    let mut current = Some(def_id);
    while let Some(did) = current {
        // Skip ancestors whose attributes rmeta never encoded (e.g. a cross-crate
        // `extern` block) — querying them cross-crate ICEs. See [`attrs_queryable`].
        if !attrs_queryable(tcx, did) {
            current = tcx.opt_parent(did);
            continue;
        }
        #[allow(deprecated)]
        let has_attr = tcx.get_all_attrs(did).iter().any(|attr| {
            matches!(
                attr.path().as_slice(),
                [tool, skip] if tool.as_str() == "trust" && skip.as_str() == "skip"
            )
        });
        if has_attr {
            return true;
        }

        // Trust: If this is an item in an impl, check if the impl subject (the struct/enum)
        // has the skip attribute. This handles macro-generated derive impls.
        if let Some(local_did) = did.as_local() {
            if let Node::ImplItem(impl_item) = tcx.hir_node_by_def_id(local_did) {
                let impl_did = tcx.hir_get_parent_item(impl_item.hir_id()).def_id;
                let impl_ty = tcx.type_of(impl_did).instantiate_identity().skip_normalization();
                if let ty::Adt(adt_def, _) = impl_ty.kind() {
                    #[allow(deprecated)]
                    if tcx.get_all_attrs(adt_def.did()).iter().any(|attr| {
                        matches!(
                            attr.path().as_slice(),
                            [tool, skip] if tool.as_str() == "trust" && skip.as_str() == "skip"
                        )
                    }) {
                        return true;
                    }
                }
            }
        }

        current = tcx.opt_parent(did);
    }
    false
}

/// Trust (skip taxonomy, 2026-09-16): is `#[trust::skip]` written ON this def,
/// or INHERITED from an enclosing item?
///
/// [`item_has_trust_skip_attr`] walks ancestors on purpose — one attribute on a
/// function must cover the closures inside it, or the waiver would be full of
/// holes. But the skip DIAGNOSTIC walked nothing: every body that inherited
/// the attribute emitted its own top-level error. Measured on the aterm corpus
/// (2026-09-16): 111 source annotations in `aterm-types` produced 219 `Trust
/// full verification skipped` errors, and 40 of those 219 are `{closure#N}`
/// bodies whose parent function carries the attribute. The author wrote one
/// line and was billed once per nested closure.
///
/// Returns `Some(ancestor)` — the NEAREST enclosing local fn-like def that
/// carries the attribute itself — when the attribute is inherited, so the
/// body's error can be reported through that declaration. This changes no
/// verdict: an inherited skip is still a skip and still fails closed, and the
/// deferral is checked at the crate checkpoint
/// (`trust_reconcile_inherited_skips`), which re-emits the body's own error if
/// the declaration never reported.
fn trust_skip_attr_inherited_from(tcx: TyCtxt<'_>, def_id: DefId) -> Option<DefId> {
    if !item_has_trust_skip_attr(tcx, def_id) {
        return None;
    }
    // The def itself carrying the attribute is a DECLARATION, not an
    // inheritance — checked with a one-def probe, never the ancestor walk.
    if !attrs_queryable(tcx, def_id) {
        return None;
    }
    #[allow(deprecated)]
    let direct = tcx.get_all_attrs(def_id).iter().any(|attr| {
        matches!(
            attr.path().as_slice(),
            [tool, skip] if tool.as_str() == "trust" && skip.as_str() == "skip"
        )
    });
    if direct {
        return None;
    }
    // Walk to the NEAREST ancestor that carries it. `item_has_trust_skip_attr`
    // already said one exists; this only names it, and falls back to `None`
    // (i.e. "treated as a declaration") if the walk cannot, so an unnameable
    // ancestor can never make an error quieter than it is today.
    let mut current = tcx.opt_parent(def_id);
    while let Some(did) = current {
        if attrs_queryable(tcx, did) {
            #[allow(deprecated)]
            let has = tcx.get_all_attrs(did).iter().any(|attr| {
                matches!(
                    attr.path().as_slice(),
                    [tool, skip] if tool.as_str() == "trust" && skip.as_str() == "skip"
                )
            });
            if has {
                // FAIL-CLOSED: only a LOCAL, FUNCTION-LIKE ancestor may be named
                // as the declaration this body inherits from. Anything else — a
                // `mod`, an `impl` block, the impl SELF-TYPE arm that
                // `item_has_trust_skip_attr` also honours (and which is not an
                // ancestor at all, so this walk never reaches it) — has no MIR
                // body, emits no skip error of its own, and must therefore leave
                // this body reported exactly as it is today.
                if did.is_local()
                    && matches!(
                        tcx.def_kind(did),
                        DefKind::Fn | DefKind::AssocFn | DefKind::Closure
                    )
                {
                    return Some(did);
                }
                return None;
            }
        }
        current = tcx.opt_parent(did);
    }
    None
}

/// Trust: whether `#[trust::<name>]` is declared on the item or its impl subject
/// (struct/enum). Mirrors `item_has_trust_skip_attr`; used for `single_writer`
/// (mmap temporal) and `backing` (relational buffer+length invariant).
fn item_has_trust_attr(tcx: TyCtxt<'_>, def_id: DefId, name: &str) -> bool {
    let matches_attr = |attr: &rustc_attr_ir::Attribute| {
        matches!(
            attr.path().as_slice(),
            [tool, attr_name] if tool.as_str() == "trust" && attr_name.as_str() == name
        )
    };
    let mut current = Some(def_id);
    while let Some(did) = current {
        // Skip ancestors whose attributes rmeta never encoded (e.g. a cross-crate
        // `extern` block) — querying them cross-crate ICEs. See [`attrs_queryable`].
        if !attrs_queryable(tcx, did) {
            current = tcx.opt_parent(did);
            continue;
        }
        #[allow(deprecated)]
        if tcx.get_all_attrs(did).iter().any(matches_attr) {
            return true;
        }
        if let Some(local_did) = did.as_local()
            && let Node::ImplItem(impl_item) = tcx.hir_node_by_def_id(local_did)
        {
            let impl_did = tcx.hir_get_parent_item(impl_item.hir_id()).def_id;
            let impl_ty = tcx.type_of(impl_did).instantiate_identity().skip_normalization();
            if let ty::Adt(adt_def, _) = impl_ty.kind() {
                #[allow(deprecated)]
                if tcx.get_all_attrs(adt_def.did()).iter().any(matches_attr) {
                    return true;
                }
            }
        }
        current = tcx.opt_parent(did);
    }
    false
}

/// Trust (ty / temporal): verify the `#[trust::terminating]` and
/// `#[trust::reachable]` temporal assertions on an enum-step transition function.
///
/// This engages the typestate/temporal lane end-to-end: extract the function's
/// state machine from its MIR (`fn step(s: E) -> E { match s { .. } }`), then
/// EXHAUSTIVELY model-check the finite transition graph:
/// - `#[trust::terminating]` — the machine CONVERGES (no livelock): every state
///   reaches a fixed point in finitely many steps. A cycle through ≥ 2 distinct
///   variants is a livelock and a hard error.
/// - `#[trust::reachable]` — every state is REACHABLE from the initial state via
///   `step` (no dead state). An unreachable variant is a hard error.
/// Each present assertion that holds emits a PROVED note. A function outside the
/// recognizable enum-step shape is reported "not checked" (sound: no verdict).
fn verify_terminating_attr<'tcx>(tcx: TyCtxt<'tcx>, def_id: DefId, body: &Body<'tcx>) {
    let terminating = item_has_trust_attr(tcx, def_id, "terminating");
    let reachable = item_has_trust_attr(tcx, def_id, "reachable");
    if !terminating && !reachable {
        return;
    }
    let func = trust_mir_extract::extract_function(tcx, body);
    let span = body.span;
    let dcx = tcx.dcx();
    let Some(machine) = trust_vcgen::extract_enum_step_machine(&func) else {
        dcx.struct_span_warn(
            span,
            "Trust: temporal assertion not checked — not a recognizable enum-step \
             transition function `fn(E) -> E { match s { .. } }`",
        )
        .emit();
        return;
    };

    if terminating {
        match machine.nontrivial_cycle() {
            None => {
                dcx.struct_span_note(
                    span,
                    "Trust: `#[trust::terminating]` PROVED — the state machine converges \
                     (no livelock); every state reaches a fixed point, by exhaustive \
                     finite-state model checking",
                )
                .emit();
            }
            Some(cycle) => {
                dcx.struct_span_err(
                    span,
                    format!(
                        "Trust: `#[trust::terminating]` FAILED — the state machine \
                         livelocks on the cycle {} (never reaches a fixed point)",
                        cycle.join(" -> ")
                    ),
                )
                .emit();
            }
        }
    }

    if reachable {
        let dead = machine.unreachable_states();
        if dead.is_empty() {
            dcx.struct_span_note(
                span,
                "Trust: `#[trust::reachable]` PROVED — every state is reachable from the \
                 initial state via `step` (no dead state), by exhaustive finite-state \
                 model checking",
            )
            .emit();
        } else {
            dcx.struct_span_err(
                span,
                format!(
                    "Trust: `#[trust::reachable]` FAILED — state(s) {} are never reached \
                     from the initial state via `step` (dead state)",
                    dead.join(", ")
                ),
            )
            .emit();
        }
    }
}

/// Trust (trust-vc / ownership): verify the `#[trust::must_consume]` linearity
/// assertion — the function's single owned by-value parameter is MOVED OUT
/// (consumed) on every path to `Return`, never silently dropped.
///
/// This engages the ownership lane: a sound forward reachability over the MIR
/// move dataflow (only a genuine `Operand::Move(param)` counts, so the verdict is
/// never a false `Consumed`). A leak path is a hard error; full consumption is a
/// PROVED note. A non-single-owned-parameter function is "not checked" (sound).
/// The property is one Rust's affine types do NOT enforce — an owned value may be
/// dropped — so it is genuinely additive verification.
fn verify_must_consume_attr<'tcx>(tcx: TyCtxt<'tcx>, def_id: DefId, body: &Body<'tcx>) {
    if !item_has_trust_attr(tcx, def_id, "must_consume") {
        return;
    }
    let func = trust_mir_extract::extract_function(tcx, body);
    let span = body.span;
    match trust_vcgen::check_must_consume(&func) {
        trust_vcgen::MustConsume::Consumed => {
            tcx.dcx()
                .struct_span_note(
                    span,
                    "Trust: `#[trust::must_consume]` PROVED — the owned parameter is moved \
                     out (consumed) on every path; it is never silently dropped",
                )
                .emit();
        }
        trust_vcgen::MustConsume::Leaked { .. } => {
            tcx.dcx()
                .struct_span_err(
                    span,
                    "Trust: `#[trust::must_consume]` FAILED — the owned parameter is \
                     dropped (leaked) on at least one path instead of being moved out",
                )
                .emit();
        }
        trust_vcgen::MustConsume::NotApplicable => {
            tcx.dcx()
                .struct_span_warn(
                    span,
                    "Trust: `#[trust::must_consume]` not checked — expected a function \
                     with exactly one owned by-value parameter",
                )
                .emit();
        }
    }
}

/// Trust (trust-cg / verified codegen): decide the `#[trust::verified_codegen]`
/// assertion — trust-cg compiles this function without changing what it computes.
///
/// Engages the trust-cg lane end-to-end (it is otherwise NOT wired into the
/// verifier): lower the function's MIR to trust-cg LIR, lift it back and compare
/// the round trip, then emit the function to a real object for the compilation's
/// own target, decode the emitted bytes, and discharge equality between their
/// machine semantics and the semantics auto-derived from the IR.
///
/// The diagnostic names which of those two checks carried, because they are not
/// interchangeable. The round trip compares block count, argument count, and the
/// arithmetic-operation multiset — a necessary condition that never inspects an
/// instruction, so it cannot see a miscompile in the encoding, the register
/// allocation, or the ABI. Only the byte-level gate can, and its frontier is
/// bounded (AArch64 machine semantics, straight-line integer scalar shapes), so
/// a function outside it gets the weaker sentence rather than the stronger one.
///
/// A refuted output preservation, a broken round trip, or a function outside the
/// lowerable fragment is a hard error; an undecided byte-level verdict is a
/// warning, since the assertion is about trust-cg's fragment and the user cannot
/// act on a decoder gap.
///
/// Two limits are worth stating because the diagnostic reads stronger than they
/// are. The emission checked here uses trust-cg's default lowering settings, not
/// this compilation's optimization level, so it is a claim about the target's ABI
/// and ISA rather than about a specific `-C opt-level`. And under the default
/// LLVM backend the object this build ships comes from LLVM, which is
/// unverified — the attribute says trust-cg would compile this function
/// faithfully, not that the shipped bytes are correct.
fn verify_codegen_attr<'tcx>(tcx: TyCtxt<'tcx>, def_id: DefId, body: &Body<'tcx>) {
    if !item_has_trust_attr(tcx, def_id, "verified_codegen") {
        return;
    }
    let func = trust_mir_extract::extract_function(tcx, body);
    let span = body.span;
    // A codegen claim is a claim about machine code for ONE target. Checking
    // host emission while cross-compiling would describe a different machine
    // than the one this compilation is producing code for.
    let backend =
        trust_router::TrustCgCodegenBackend::new(trust_router::TrustCgBackendConfig::for_target(
            tcx.sess.target.arch.desc(),
            tcx.sess.opts.target_triple.tuple(),
        ));
    match backend.verify_codegen(&func) {
        Ok(trust_router::CodegenVerdict::KernelProved) => {
            tcx.dcx()
                .struct_span_note(
                    span,
                    "Trust: `#[trust::verified_codegen]` PROVED — trust-cg's emitted machine \
                     code for this function computes its IR semantics on every input, and the \
                     Clean kernel re-checked the certificate",
                )
                .emit();
        }
        Ok(trust_router::CodegenVerdict::AyValidated) => {
            tcx.dcx()
                .struct_span_note(
                    span,
                    "Trust: `#[trust::verified_codegen]` VALIDATED — ay proved that trust-cg's \
                     emitted machine code for this function computes its IR semantics on every \
                     input; no kernel-re-checkable certificate covers this obligation, so ay is \
                     the sole authority for the claim",
                )
                .emit();
        }
        Ok(trust_router::CodegenVerdict::Miscompiled { detail }) => {
            tcx.dcx()
                .struct_span_err(
                    span,
                    format!(
                        "Trust: `#[trust::verified_codegen]` FAILED — trust-cg MISCOMPILES this \
                         function: {detail}"
                    ),
                )
                .emit();
        }
        Ok(trust_router::CodegenVerdict::RoundTripMismatch { detail }) => {
            tcx.dcx()
                .struct_span_err(
                    span,
                    format!(
                        "Trust: `#[trust::verified_codegen]` FAILED — the trust-cg lowering did \
                         not round-trip: {detail}"
                    ),
                )
                .emit();
        }
        Ok(trust_router::CodegenVerdict::RoundTripOnly { undecided }) => {
            tcx.dcx()
                .struct_span_warn(
                    span,
                    format!(
                        "Trust: `#[trust::verified_codegen]` not machine-checked — only the \
                         trust-cg structural round-trip check held (necessary, not sufficient); \
                         the emitted machine code was not checked against the function's IR \
                         semantics: {undecided}"
                    ),
                )
                .emit();
        }
        Ok(trust_router::CodegenVerdict::Unavailable { reason }) => {
            tcx.dcx()
                .struct_span_warn(
                    span,
                    format!("Trust: `#[trust::verified_codegen]` not checked — {reason}"),
                )
                .emit();
        }
        Err(e) => {
            tcx.dcx()
                .struct_span_err(
                    span,
                    format!(
                        "Trust: `#[trust::verified_codegen]` FAILED — the function is not \
                         verified-codegen-able by trust-cg: {e}"
                    ),
                )
                .emit();
        }
    }
}

// Trust: crate-wide proof inputs computed at the analysis phase and consumed by
// MIR/codegen worker threads. These used to be process-global OnceLocks. That is
// unsound for rustc_driver clients that run multiple Sessions: the second crate
// could inherit the first crate's R1 verdict flips or backing certificates. The
// state now lives in Session's typed extension store, so it is shared only by
// workers of this invocation and dropped with the Session.
#[derive(Default)]
struct CrateVerificationState {
    backing_initialized: bool,
    /// Private source facts, never callee proof. A disagreeing recapture permanently
    /// withdraws that owner's bindings for this invocation.
    reified_fnptr_bindings: FxHashMap<DefId, Option<reified_fnptr_charge::Bindings>>,
    /// Memoized `crate_static_constructor` verdict (see
    /// `installed_process_signal_policy`): the scan walks every free item, and
    /// its caller runs once per BODY, so an un-memoized scan is quadratic in
    /// crate size. Crate-scoped and immutable for the compilation.
    static_constructor_scan: Option<Option<(LocalDefId, String)>>,
    /// Vanilla-sysroot verdicts recorded by the BUNDLE walk, keyed by the same
    /// `func_operand_name` the root-body ledger uses. ANDed per name.
    bundle_walk_vanilla_callees: FxHashMap<String, bool>,
    /// Trust (2026-09-26, std-absent-callee): the sysroot panic census's verdict
    /// cache — `true` = censused total — keyed by the RESOLVED INSTANCE's stable
    /// hash, never by a rendered call key, so a rendering collision cannot let one
    /// instance's answer stand for another's. The census ignores argument values,
    /// so one instance has one answer; the report rides along for the refusal
    /// note. A CACHE: a verdict is only ever spent through the per-bundle
    /// `CensusDischarges` ledger or the per-caller set below.
    sysroot_census_verdicts: FxHashMap<String, (bool, Option<sysroot_panic_census::CensusReport>)>,
    /// Trust (2026-09-26): why a declined call key was declined — the sites the
    /// census reached, or why it did not run — for the `certify` refusal note.
    /// Diagnostics only; keyed by the call key the bridge's row renders.
    sysroot_census_reports: FxHashMap<String, sysroot_panic_census::CensusReport>,
    /// Trust (2026-09-26): per-caller census-total call keys — THIS function's own
    /// calls every one of whose sites the census derived total
    /// (`sysroot_panic_census::own_census_total_calls`), published by the
    /// function's own bundle build and read by its zero-obligation call gates.
    /// Same per-caller, self-poisoning discipline as `drop_absent_cell_set_calls`;
    /// an absent caller yields an EMPTY set, which admits nothing.
    sysroot_census_total_calls: FxHashMap<String, FxHashSet<String>>,
    /// Trust (2026-10-13, CALL-REACH-1-D8): per root (def path, as
    /// `safe_def_path_str` renders it for the gate), the first call of its bundle
    /// the call-reach walk left OPEN after the census's credit, as `(callee, why)`.
    /// Written by the root's own bundle build, OR-ed toward open (a later build
    /// never removes an entry), and read by `abort_on_full_verification_failure`:
    /// such a call keeps the function fail-closed under the default policy
    /// whichever bridge arm lowered it. The bridge's deny arm claims only an
    /// ABSENT callee; a BUNDLED one runs its sysroot body, whose open edge (an
    /// indirect call, a virtual call) lowers to a havoc row the default policy
    /// would otherwise report as runtime-checked. Absent = no open call.
    call_reach_withdrawn: FxHashMap<String, (String, String)>,
    /// Trust (D1 increment 1): the writer-relative facts each formatting-impl root's
    /// bundle produced (`DynDispatchBundleFacts::writer_relative_facts`), keyed by
    /// the root. `None` = the bundle refused the class; a root verified more than
    /// once keeps a key set only if every verification produced the same one
    /// (`fmt_writer_relative::record_writer_relative_facts`). Absent = never
    /// recorded, which every reader treats as refused.
    writer_relative_facts: FxHashMap<DefId, Option<fmt_writer_relative::WriterRelativeFacts>>,
    /// Functions whose OWN verification finished in the fail-closed lane with no
    /// error — proved, or a gap the default policy tolerated — keyed by def path.
    /// Written only at the end of `publish_body_verification_outcome`, after every
    /// body-level abort has had its say; read when a caller's bundle decides
    /// whether an unproven local member may stay bundled (`keeps_local_member`).
    strict_accepted_fns: FxHashSet<String>,
    /// Trust (2026-09-25, `member_assert_ownership`): what each LOCAL root's own
    /// Assert gate charged at its direct calls, keyed by `LocalDefId`. Written
    /// when the root's bundle is built (before its verdict); `Err` records why the
    /// root can own nothing, or that two constructions disagreed.
    own_root_assert_charges_pending: FxHashMap<
        LocalDefId,
        Result<Vec<member_assert_ownership::OwnRootMemberAssertCharge>, &'static str>,
    >,
    /// ... promoted at the `strict_accepted_fns` point, and only when every
    /// charged row is `Trusted`/`Certified` in the root's own results. The ONLY
    /// thing a caller's bundle reads (`own_root_assert_charge_evidence`).
    own_root_assert_charges_verified: FxHashMap<
        LocalDefId,
        Result<Vec<member_assert_ownership::OwnRootMemberAssertCharge>, &'static str>,
    >,
    /// Trust (VEC-INSERT, 2026-09-25): per root (def path), the call blocks whose
    /// `Vec` index mutator vcgen charged its REAL index precondition
    /// (`trust_vcgen::vec_mutator_charged_blocks`), recorded when the root's VCs are
    /// generated and read by that same root's vanilla ledger. Absent = none.
    vec_mutator_charged_blocks: FxHashMap<String, Vec<trust_types::BlockId>>,
    callee_summaries: trust_vcgen::CalleeSummaryContext,
    native_callee_summaries: trust_ir_bridge::NativeCalleeSummaryContext,
    /// Trust (D5-B): the crate's KERNEL-CERTIFIED body-inferred return
    /// equalities, keyed by the callee's `DefId` (`inferred_return::
    /// mint_inferred_returns`). Read per call site by
    /// `inferred_return::callee_summary`; empty (nothing summarized) when the
    /// analysis-phase init never ran.
    inferred_returns: FxHashMap<DefId, trust_vcgen::InferredReturn>,
    // Trust: exact original callee bodies and already-checked payloads, reusable as a DAG.
    inferred_return_derivations:
        FxHashMap<DefId, trust_certify::inferred_return_proof::InferredReturnProofNode>,
    /// Trust (TINV step 9): the type-invariant pre-pass ran (`-Ztrust-tinv`).
    tinv_initialized: bool,
    /// Trust (TINV step 10.0): the use set of the run whose certificates are published
    /// in `type_invariant_certificates` (`None` when nothing was published: the ∧I gate
    /// is all-or-nothing, TINV-22). Step 10.5: `callee_summaries` carries `Arc::clone` of
    /// exactly this allocation under `-Ztrust-tinv` (checked by pointer identity).
    type_invariant_use_set: Option<Arc<trust_vcgen::type_invariant::TinvUseSet>>,
    /// Trust (TINV step 10.7): the rendered disclosure line of every conjunct the use set
    /// above publishes (`assumes type_invariant(S)#k `text` [certificate provenance]`),
    /// published with it; a `TypeInvariantComposed` token is minted only with these lines.
    type_invariant_disclosures: std::collections::BTreeMap<(String, u32), String>,
    /// Trust (TINV step 10.4, TINV-27): the bodies whose rows carry a type-invariant
    /// premise (a use-site fact was conjoined into one of them), recorded by the
    /// authority phase. Never a premise for another body
    /// (`verdict_rests_on_user_axiom_for`). Empty unless step 10.5 installed a use set.
    tinv_premised_verdicts: FxHashSet<DefId>,
    /// Trust (TINV step 10.7): per type `def_path`, the functions with at least one row
    /// graded `TypeInvariantComposed` under one of its conjuncts (the consumer list the
    /// `TRUST_TINV_NOTES` report prints). Report only: nothing reads it as a premise.
    type_invariant_consumers:
        std::collections::BTreeMap<String, std::collections::BTreeSet<String>>,
    /// Trust (TINV step 9): the kernel-certified type invariants, keyed by the
    /// type's `DefId` (`type_invariant::trust_init_type_invariant_certificates`).
    /// Every row's evidence is `CleanCic`, minted by `certify_vc` and replayed.
    /// Read by NO VC, summary or hypothesis until step 10 (only the
    /// `TRUST_TINV_NOTES` report reads it). Empty — fail-closed — by default.
    type_invariant_certificates: FxHashMap<
        DefId,
        Arc<
            trust_vcgen::type_invariant::houdini::TypeInvariantCertificate<trust_ir::ProofEvidence>,
        >,
    >,
    /// Trust (TINV step 9): the v7/D3 notes per type (design P7), sorted by the
    /// type's rendered name: every gate that refused it, every dropped conjunct, and
    /// what certified.
    type_invariant_notes: Vec<(DefId, Vec<String>)>,
    /// Constructor-free whole-crate paired-condvar authority minted by the
    /// TyCtxt-owned exhaustive inventory for this exact Session revision.
    paired_condvar_certificate: Option<Arc<trust_mir_extract::PairedCondvarCrateCertificate>>,
    /// Trust (D2 tier 1): `trust_init_adapter_yield_premises` ran.
    adapter_yield_initialized: bool,
    /// Trust (D2 tier 1): the `ADAPTER_YIELD` premises minted at the pre-steal
    /// seam, keyed by the closure's `LocalDefId` (never a rendered path). Read by
    /// the closure's own verification (`adapter_yield::premises_for_body`), the
    /// check-elision exclusion, and the disclosure. Empty — fail-closed — for a
    /// crate the seam never initialized.
    adapter_yield_premises: FxHashMap<LocalDefId, Vec<trust_vcgen::ClosureAdapterPremise>>,
    /// Trust (2026-10-08): the argument premises (`argument_premise`) installed
    /// for each body, as disclosure strings. Non-empty marks the body: its rows
    /// are demoted to `Trusted`, it is never check-elided, and no caller spends
    /// its verdict.
    argument_premises: FxHashMap<LocalDefId, Vec<String>>,
    /// Trust (2026-10-18, FRESH-CAPTURE-1): `trust_init_fresh_capture_premises` ran.
    fresh_capture_initialized: bool,
    /// Trust (2026-10-18, FRESH-CAPTURE-1): per local closure (keyed by its
    /// `LocalDefId`, never a rendered path), the upvar fields whose captured shared
    /// reference is a fresh borrow in every value of the closure type
    /// (`fresh_capture::fields_for_body`). Read by the closure's own verification and
    /// the check-elision exclusion. Empty — fail-closed — for a crate the seam never
    /// initialized.
    fresh_capture_fields: FxHashMap<LocalDefId, Vec<usize>>,
    /// Trust (STR_BYTE_POSITION): `trust_init_byte_eq_predicates` ran.
    byte_eq_initialized: bool,
    /// Trust (STR_BYTE_POSITION): the local closures certified to be exactly
    /// `|b: u8| b == K`, keyed by `LocalDefId`, with `K`. Read per body by
    /// `byte_eq_predicate::ascii_eq_bytes_position_calls`. Empty — fail-closed —
    /// for a crate the seam never initialized.
    byte_eq_predicates: FxHashMap<LocalDefId, u8>,
    r1_initialized: bool,
    r1_attributions: BTreeMap<String, Vec<R1Flip>>,
    /// Why the crate-wide R1 caller scan could not account for this crate
    /// (`CrateCallInfo::incomplete_notes`, already bounded and rendered by the
    /// oracle; each entry carries the offending item's span). Non-empty means R1's
    /// verdict-improvement lane was disabled for EVERY function, so
    /// `trust_ensure_whole_crate_verification` reports the cause once, beside the
    /// coverage-shortfall report — but only when a verdict was actually withheld
    /// (`l0_verdict_withheld`), so ordinary all-proved source never pays a warning
    /// for merely containing a `global_asm!` item. Empty when the scan was
    /// complete or never ran (`-Ztrust-no-r1`).
    r1_scan_gaps: Vec<crate::trust_r1_oracle::R1ScanGapNote>,
    /// True iff at least one function in this crate ended the walk with a
    /// non-proved Level-0 outcome (the `strict_l0_verification_failure` /
    /// `abort_on_full_verification_failure` reporting seams fired, in any policy
    /// or output mode) — i.e. a verdict was actually withheld that R1's
    /// improvement lane could conceivably have mattered to. Gates the crate-level
    /// scan-gap warning above; deliberately coarse (crate-level, may
    /// under-approximate on exotic reporting seams, which errs toward SILENCE —
    /// never toward warning on clean source; verification itself stays
    /// fail-closed regardless).
    l0_verdict_withheld: bool,
    /// Trust (2026-09-14): bodies whose fail-closed lane already emitted the
    /// LOCATED per-function preprocessing-budget error. The no-artifacts abort
    /// consults this so the same body is not refused a second time with a
    /// generic "produced no artifacts" error that names no remedy (v7/D3).
    budget_aborted_defs: FxHashSet<rustc_hir::def_id::DefId>,
    /// Legacy display-name view of the panic-free registry. The ordinary call
    /// arms in the zero-row/R40 gate and identity gate do not authorize from it.
    /// Other legacy collectors still consume this view under their own rules;
    /// converting this field does not qualify those separate consumers.
    panic_free_proven_funcs: FxHashSet<String>,
    /// The IDENTITY-keyed view of `panic_free_proven_funcs`: the same fact about
    /// the same functions, keyed by rustc's `DefId`+substs instead of by a
    /// rendered path.
    ///
    /// WHY. `panic_free_proven_funcs` is keyed by `safe_def_path_str` and every
    /// call site is keyed by `func_operand_name`. Those are two different
    /// renderers, and they do not agree. MEASURED (ny-cert, gate R43):
    ///
    /// ```text
    /// [PF_REG]      fn=ny_cert::json::Parser::<'a>::peek established=true nrows=0
    /// [PF_CALLGATE] fn=…::skip_whitespace UNREGISTERED callee blocks discharge:
    ///               ny_cert::json::Parser::<'_>::peek
    /// ```
    ///
    /// — registered with the DECLARED lifetime, queried with the ELIDED one; 11
    /// call sites over 3 keys blocked 9 caller functions on a fact this very
    /// session already held. Two earlier desyncs of the same class
    /// (`::<__trust_args@HASH>`; crate-less vs crate-qualified def paths) were
    /// each repaired by teaching one more string spelling, and adding string
    /// spellings is the move that produced FALSE PROOF #14. This set repairs the
    /// CAUSE instead: a `DefId` is not spellable in source, so no identifier a
    /// user may choose can reach it.
    ///
    /// Ordinary registration and deferred R40 publish the item identity with
    /// its display view under the same premise refusal. Modeled Clean-origin
    /// registration uses its separate kernel-backed rule. No writer derives an
    /// identity from the display view.
    ///
    /// NOT A KEY RELAXATION. `trust_mir_extract::item_identity` mints nothing for
    /// a type/const-generic item (its identity args mention a `ty::Param`), so a
    /// generic body's single pre-monomorphization proof still cannot discharge a
    /// concrete call — the distinction `parametric_panic_free_funcs` below exists
    /// to protect. What DOES newly meet is the case where the two keys always
    /// denoted the same code and only the RENDERING differed: no type or const
    /// argument anywhere, lifetimes erased on both sides.
    panic_free_proven_identities: FxHashSet<trust_types::CalleeIdentity>,
    /// R43 — the SUBSET of `panic_free_proven_funcs` whose registration is
    /// GENERIC-PARAMETER-INDEPENDENT, i.e. whose rustc MIR body contains no
    /// panic-capable terminator AT ALL (`body_is_parametrically_panic_free`).
    ///
    /// WHY A SECOND SET AND NOT A KEY RELAXATION. `panic_free_proven_funcs` is
    /// keyed by the ARGUMENT-FREE `safe_def_path_str`, while every call site is
    /// keyed by `func_operand_name`, which carries the instantiated turbofish. For
    /// a generic callee the two never match, so `collect_proven_total_panic_free_
    /// callees` fails closed on `!gen_args.is_empty()` and the caller keeps a
    /// `[trust-absent-callee-assumption] … may panic` row (measured: 12 such rows
    /// for `ny_cert::err_barrier::<E>` in ny `.gatelogs/R42.log`, while
    /// `[PF_REG] fn=ny_cert::err_barrier established=true nrows=0`).
    ///
    /// STRIPPING THE TURBOFISH TO MAKE THE KEYS MEET WOULD BE FALSE PROOF #14
    /// POINTED THE OTHER WAY: the generic body is verified ONCE, pre-monomorphization,
    /// and for most generic functions "the generic body verified" does NOT imply
    /// "every instantiation is panic-free". This set therefore records the strictly
    /// narrower fact that DOES transfer, decided from the callee's own MIR rather
    /// than from its verdict. Written only where `panic_free_proven_funcs` is
    /// written, so membership is always a subset of it.
    parametric_panic_free_funcs: FxHashSet<String>,
    /// FALSE PROOF #11 (transport half). Compiler owners whose ZERO-OBLIGATION run was
    /// POSITIVELY found to contain a `Terminator::Call` that no authenticated
    /// registry discharges — i.e. `all_calls_target_proven_panic_free` returned
    /// `false` while `summary.total == 0`.
    ///
    /// This is a NEGATIVE set, deliberately. Membership is only ever written by
    /// `zero_obligation_run_establishes_unconditional_panic_freedom`, from a
    /// POSITIVELY computed "this function has an undischarged call"; an absent
    /// entry means "no lane computed the fact", which leaves the transport row
    /// exactly as it is today rather than manufacturing a gap for every
    /// zero-obligation function on a lane that never runs the registry gate.
    ///
    /// It exists so the TRANSPORT row and the REGISTRY decision cannot disagree:
    /// the registry now refuses to call such a function panic-free, so the
    /// transport must not publish `no_obligations` ("trivially panic-free",
    /// outcome `proved`) for it either. Consumed once, in
    /// `publish_body_verification_outcome`, where a hit swaps
    /// `transport_no_obligations_row()` for `transport_native_verification_gap_row()`.
    ///
    /// ORDERING IS ESTABLISHED, not assumed: the write happens inside
    /// `collect_full_verification_artifacts`, which runs (via
    /// `collect_verification_artifacts_cached_after_decision`) strictly BEFORE
    /// `publish_body_verification_outcome` for the same body.
    zero_obligation_undischarged_call_funcs: FxHashSet<DefId>,
    /// Trust (OD-1 phase 1): the subset of `zero_obligation_undischarged_call_funcs`
    /// whose ONLY undischarged calls are the body's admitted instance-hypothesis
    /// sites. Read only by the zero-obligation transport decision, which then
    /// publishes the hypothesis rows in place of the gap row (and never the
    /// `no_obligations` proved row); no registry reads it.
    zero_obligation_calls_only_hypotheses: FxHashSet<DefId>,
    /// R23. Per-def-path carry of the INTERPROCEDURAL panic-freedom seam's OWN
    /// positively-computed gate result — "`refuted == 0`, every non-pf,
    /// non-`Postcondition` row of this function is `Proved`, and EVERY
    /// `Terminator::Call` in its extracted body was discharged by
    /// `all_calls_discharge_panic_free`" — recorded UNCONDITIONALLY only (a
    /// `#[trust::requires]` function's conditional discharge is deliberately
    /// NOT recorded, mirroring the `trust-assert-refute-under-precondition`
    /// solver tag that the unconditional authority installer already refuses).
    ///
    /// WHY IT EXISTS. The seam's own verdict WRITE is guarded by
    /// `!is_definitive`, so a pf catch-all that some earlier lane already left
    /// `Proved` — with NO proof authority, hence transport-refused as
    /// `runtime_checked` — is never re-stamped with the seam's
    /// `trust-assert-refute` tag, which is the ONLY tag
    /// `install_interprocedural_callee_closure_authorities` admits. That made an
    /// already-`Proved` row strictly WORSE OFF than an Unknown one. This record
    /// carries the gate FACT to the installer instead, so the row can be
    /// authorized on the seam's own argument WITHOUT rewriting anyone's verdict:
    /// no certificate is destroyed, no provenance is laundered, and the
    /// installer's still-`None` authority-slot guard keeps a real independent
    /// proof untouched.
    ///
    /// FAIL-CLOSED BY CONSTRUCTION, identically to the sibling above:
    ///  * an ABSENT entry reads `false` (no lane computed the fact ⇒ no
    ///    authority), and
    ///  * a re-insert AND-merges, so two monomorphizations that disagree
    ///    collapse to the conservative answer.
    ///
    /// It is a NECESSARY, NEVER A SUFFICIENT, condition: the installer still
    /// requires the exact pf catch-all row shape, a frozen row identity, an
    /// empty authority slot, every SIBLING row `Proved` under its own
    /// unconditional static authority, and no entry/assumed-total assumption
    /// anywhere in the function — so a row appended AFTER the gate ran (e.g. a
    /// call-site L0 replay `Failed`) still blocks it.
    ///
    /// Only `refute_full_assert_obligations` writes it, from its own positively
    /// computed gate; nothing else may set it `true`.
    interprocedural_pf_call_closure_funcs: FxHashMap<String, bool>,
    /// Trust (assumption-root gate): for each body whose verification reached the
    /// USER-AXIOM CENSUS, whether that verification was established free of
    /// user-written axioms — `#[trust::assume_total]` and `#[trust::skip]` CALLEES
    /// whose call keys the bundle SPENT, i.e. handed to the bridge in
    /// `assumed_total` / `expected_absent`.
    ///
    /// NOT "every callee anywhere in the bundle": the census reads the root body
    /// and the DefId walk, which is measurably not the whole bundle (see
    /// `bundled_def_id_reads_complete`). It does not need to be — a user axiom the
    /// bundle did not spend leaves its call site an unproved absent callee, which
    /// conjunct 1 of the shared bar refuses on its own. The full case split, and
    /// the programs that measure both of its branches, are on
    /// [`verdict_rests_on_user_axiom`].
    ///
    /// `false` means the verdict is CONDITIONAL on a user declaration; ABSENT
    /// means no census was ever taken, which is UNANSWERED, not clean. Both
    /// refuse — see [`verdict_rests_on_user_axiom`], the ONE authenticator every
    /// premise lane consults.
    ///
    /// Conjoined on insert (`&=`): one def can be verified as more than one
    /// bundle, and a single axiom-bearing bundle is enough to make its verdict
    /// conditional. Session state, like `panic_free_proven_funcs`, so parallel
    /// workers see it and a later crate with the same def-path cannot inherit it.
    axiom_free_verdicts: FxHashMap<DefId, bool>,
    /// Trust (2026-09-29): bodies at least one of whose verifications kept a
    /// bundled std/core/alloc member under the runtime-checked disposition
    /// (`VerificationArtifacts::runtime_checked_std_members`). Such a verdict is
    /// CONDITIONAL on that member's own runtime checks, so
    /// [`verdict_rests_on_user_axiom`] — the one authenticator every premise lane
    /// consults — declines to spend it. Insert-only: one conditional
    /// verification is enough.
    runtime_checked_std_member_verdicts: FxHashSet<DefId>,
    /// Trust (OD-1 phase 1, 2026-10-04): bodies that carry an instance hypothesis
    /// (an admitted open generic dispatch site, or one propagated from a callee;
    /// `instance_hypothesis.rs`). Such a verdict claims panic-freedom only under the
    /// hypothesis, so it is CONDITIONAL exactly like a runtime-checked std member's:
    /// [`verdict_rests_on_user_axiom`] declines it for every premise lane, and the
    /// registration gates (`register_proven_panic_free`, Part B, the R40 fixpoint)
    /// never see it as unconditional. Insert-only.
    instance_hypothesis_verdicts: FxHashSet<DefId>,
    /// Trust (OD-1, 2026-10-04, open shapes): per body, the callee names of the open
    /// dispatches its PUBLISHED rows were stamped `failed` for (class (c) of "L0
    /// refutation rows": `AdversarialOpenDispatch`), recorded by
    /// `publish_body_verification_outcome`. A still-generic caller reads it to
    /// propagate the refutation onto its own absent-callee row for the call
    /// (`propagated_open_dispatch_refutation`).
    open_dispatch_refuted_callees: FxHashMap<DefId, FxHashSet<String>>,
    /// Exact extracted call identities for bodyless foreign, non-unwinding
    /// C-family imports. Only the compiler's `is_foreign_item` classification
    /// can populate this set; a local Rust `extern "C" fn` is never admitted.
    abi_nonunwind_total_callees: FxHashSet<String>,
    /// Trust (Part B — conditional panic-freedom). Functions proven panic-free
    /// ONLY UNDER their `#[trust::requires(P)]` entry assumption: every panic
    /// site proved and the panic-freedom catch-all discharged while ASSUMING `P`
    /// at entry, with functional postconditions permitted to remain open. Keyed
    /// by def_path; the value is the callee summary (param names/types + the
    /// precondition `P`) needed to render `P[args]` at each call site. This is
    /// SEPARATE from the unconditional `panic_free_proven_funcs` and can NEVER
    /// discharge a call by assumption: a member discharges a caller's call ONLY
    /// when the caller PROVES `P[args]` at that exact call site (Path-2b, the
    /// guarantee side — `all_calls_discharge_panic_free`).
    panic_free_under_precondition: FxHashMap<String, trust_vcgen::FunctionSummary>,
    /// Round-4 (pf call gate, sort-comparator seam). Closure def_paths whose
    /// EXTRACTED bundled body was classified by the bridge's audited FIX B
    /// total-ord-key comparator recognizer
    /// (`closure_body_is_total_ord_key_comparator`), with the verdict.
    /// Populated at native-bundle build (`build_native_trust_ir_bundle_for_
    /// verifier_api`) from the SAME extraction snapshot the lanes verify;
    /// MONOTONE toward `false` (once any registration for a def_path fails
    /// classification, it stays failed). Consumed ONLY by
    /// `all_calls_discharge_panic_free`'s slice-sort seam; an absent or
    /// `false` entry keeps the call's obligation (fail-closed).
    total_ord_comparator_closures: FxHashMap<String, bool>,
    /// Exact extracted call identities for calls the COMPILER type-verified as
    /// advancing a concrete, sysroot-authenticated std iterator whose `next`
    /// runs no user code and cannot panic
    /// (`callee_is_type_verified_total_std_iterator`).
    ///
    /// Deliberately DISTINCT from two neighbouring sets:
    ///  - `assumed_total` (`#[trust::assume_total]`) is a USER-WRITTEN axiom;
    ///    registering it here would make panic-freedom user-declarable.
    ///  - `abi_nonunwind_total_callees` is the bodyless-foreign ABI lane.
    ///
    /// Membership is decided from real `ty::Ty` + `CrateNum`, never from a
    /// rendered path, a callee-name suffix, or a user attribute.
    type_total_std_callees: FxHashSet<String>,
    /// FRONT B (R15) — the zero-obligation call gate's TYPED `Cell::<T>::set` arm.
    ///
    /// Maps a VERIFIED FUNCTION's `def_path` to the exact extracted call
    /// identities, WITHIN THAT FUNCTION'S OWN BODY, of `core::cell::Cell::<T>::set`
    /// calls whose CONCRETE monomorphized payload `T` the compiler proved has NO
    /// DROP GLUE AT ALL (`!ty.needs_drop(tcx, typing_env)`).
    ///
    /// PER-CALLER KEYING IS DELIBERATE and is the difference between this and the
    /// two flat name-keyed sets above. `type_total_std_callees` /
    /// `abi_nonunwind_total_callees` are crate-global: a name registered while
    /// verifying one function discharges that name in EVERY later function. That is
    /// defensible for those lanes (the property is a function of the callee alone),
    /// but `Cell::set`'s totality is a property of `T`, so a crate-global name set
    /// would re-create exactly the "callee string as authority" hazard that R14
    /// deliberately kept `Cell::set` off `callee_is_recognized_total_no_panic` to
    /// avoid. Keying by caller means the decision is made, and consumed, on the SAME
    /// call site — and it makes the lane ORDER-INDEPENDENT: a caller's entry is
    /// written by its own bundle build, which always precedes its own gate.
    ///
    /// FAIL-CLOSED, INCLUDING UNDER RENDERING COLLISION. The set for a caller holds
    /// a call key only when EVERY occurrence of that key in that caller qualified
    /// (`collect_drop_absent_cell_set_calls` poisons a key on its first declining
    /// occurrence and never un-poisons). So if two distinct `T`s ever rendered to
    /// one `func_operand_name`, the pair poisons itself rather than letting the
    /// good occurrence license the bad one.
    drop_absent_cell_set_calls: FxHashMap<String, FxHashSet<String>>,
    /// LEVER 3 — per-caller call keys of the MOVED-VALUE-ARGUMENT family
    /// (`Option::<T>::unwrap_or`, `Option::<T>::ok_or::<E>`,
    /// `Result::<T, E>::unwrap_or`) whose CONCRETE monomorphized by-value operands
    /// the compiler proved have NO DROP GLUE AT ALL.
    ///
    /// WHY THIS IS A TYPED RECORD AND NOT A NAME. trust-recon `957f47a332` RETIRED
    /// these exact names from the string-only surface
    /// (`callee_is_recognized_total_no_panic`) because the proposition they asserted
    /// is FALSE for a caller-chosen payload: each of these methods takes an argument
    /// BY VALUE and DROPS it on the branch that does not consume it, running the
    /// CALLER's `Drop::drop`.
    ///
    /// ```text
    ///     struct P; impl Drop for P { fn drop(&mut self) { panic!() } }
    ///     fn f(o: Option<P>) -> P { o.unwrap_or(P) }   // panics on every Some
    /// ```
    ///
    /// std acknowledges it with the `T: [const] Destruct` bounds
    /// (option.rs:1036/1333, result.rs:1588). A callee STRING cannot see `T`, which
    /// is exactly why the retirement was correct and why re-admission has to happen
    /// here — the `Cell::set` template. Identification is by `DefId` + the
    /// `sym::Option`/`sym::Result` diagnostic items; the PROPOSITION is re-decided
    /// per call site from the instantiated signature's `needs_drop`.
    ///
    /// PER-CALLER KEYING AND SELF-POISONING are inherited verbatim from
    /// `drop_absent_cell_set_calls`: the decision is consumed only at the call sites
    /// it was made for, a key that declined at ANY occurrence in that caller is
    /// removed and never restored, and an absent caller yields an EMPTY set, which
    /// admits nothing (false proof #12).
    drop_absent_moved_value_arg_calls: FxHashMap<String, FxHashSet<String>>,
    /// R41 — per-caller call keys of the INSTANTIATED-`Self` total std trait family:
    /// `<intN as core::cmp::Ord>::{max,min}`, `<intN as core::convert::From<prim>>::from`,
    /// `<intN as core::convert::TryFrom<intM>>::try_from` and
    /// `<str as alloc::string::ToString>::to_string`, admitted ONLY where `TyCtxt` says
    /// the instantiated `Self` (and, for the conversions, the instantiated source) really
    /// IS the language primitive / `str`.
    ///
    /// WHY THIS IS A TYPED RECORD AND NOT A NAME. The three primitive-int members were
    /// STRING recognizers in trust-ir-bridge (`PRIMITIVE_INT_SPELLINGS` +
    /// `is_primitive_int_{from_widening,ord_min_max,tryfrom}_callee`) resting on the
    /// claim "no user type can be named a bare `u128`/`usize`/…", and the `str` member
    /// was written as `qualified_callee_self_spelling(callee) == Some("str")` and
    /// REVERTED as a false proof (`ccabd7b763`). THE CLAIM IS FALSE: those names are
    /// legal generic parameters and a `ty::Param` renders BARE in every print mode, so
    ///
    /// ```text
    ///     #![allow(non_camel_case_types)]
    ///     pub fn attack<u64: Ord>(a: u64, b: u64) -> u64 { a.max(b) }
    ///         // MIR: `<u64 as core::cmp::Ord>::max` — and at `Self = Evil`,
    ///         // whose `Ord::cmp` is `panic!()`, this panics on every input.
    /// ```
    ///
    /// is byte-identical to the honest spelling. Measured on the deployed driver
    /// (`TRUST_PF_MATCH_TRACE=1`, 2026-08-22) the string arms really did accept it:
    /// `[PF_ZEROGATE] fn=Q::attack_ord_max arm=bridge-total callee=<u64 as core::cmp::Ord>::max`.
    /// A callee STRING cannot see `Self`, which is why re-admission has to happen here —
    /// the `Cell::set` / moved-value-argument template. Identification is by
    /// `trait_of_assoc` + the library's own `#[rustc_diagnostic_item]` names; the
    /// PROPOSITION is re-decided per call site from `gen_args.type_at(..)`
    /// (`typed_self_total_std_call` / `collect_typed_self_total_std_calls`).
    ///
    /// PER-CALLER KEYING AND SELF-POISONING are inherited verbatim from
    /// `drop_absent_cell_set_calls`, and here they are load-bearing rather than
    /// defensive: an honest `u64::max` and a forged `<u64 as Ord>::max` in the SAME
    /// caller render one key, and the declining occurrence removes it for both. An
    /// absent caller yields an EMPTY set, which admits nothing (false proof #12).
    typed_self_total_std_calls: FxHashMap<String, FxHashSet<String>>,
    /// R16 FRONT A — per-caller `LocalKey::<T>::try_with` call keys whose ACCESSOR
    /// is a const-initialized eager thread-local (structurally call-free) AND whose
    /// CLOSURE is already in `panic_free_proven_funcs`. Written by
    /// `collect_const_init_tls_try_with_total_calls` from the caller's OWN body
    /// during its own bundle build, which always precedes that same function's
    /// `zero_obligation_run_establishes_unconditional_panic_freedom` — so the lane
    /// is order-independent, exactly like `drop_absent_cell_set_calls`.
    ///
    /// PER-CALLER KEYING IS LOAD-BEARING, for the same reason as the `Cell::set`
    /// lane above and one more: `try_with`'s totality is a property of the KEY's
    /// const-init-ness and of the CLOSURE, neither of which is recoverable from the
    /// rendered callee string. A crate-global name set would let a const-init key's
    /// grant license a LAZY key's call — false proof #13 verbatim. The set is also
    /// self-poisoning: a key that declined at ANY occurrence in that caller is
    /// removed and never restored.
    ///
    /// WHY IT EXISTS SEPARATELY FROM THE BUNDLE'S `compiler_total_callees`. That
    /// channel removes the caller's absent-callee OBLIGATION; this one lets the
    /// resulting zero-obligation run also REGISTER the caller as panic-free, so the
    /// discharge propagates to its callers. Without it a cleared `poisoned()` still
    /// blocks `ensure_healthy()` and the whole cascade stops one level up. Both are
    /// fed by the SAME decision, made by the SAME collector — no second premise.
    const_init_tls_try_with_calls: FxHashMap<String, FxHashSet<String>>,
    /// Trust (2026-10-10, ZERO-ROW-GATE recovery item 2, SLICE-ITER-CONSUMER):
    /// per-caller call keys of `<core::slice::Iter<'_, T> as Iterator>::{all, fold}`
    /// whose closure argument is a LOCAL closure ALREADY in `panic_free_proven_funcs`
    /// when the caller's bundle is built. Written by
    /// `collect_slice_iter_consumer_total_calls` from the caller's OWN body, decided
    /// from `TyCtxt` (the `Iterator` trait's and the `SliceIter` ADT's diagnostic
    /// items, both in a resident sysroot crate, and the resolved impl method), never
    /// from a callee string. Same per-caller keying and self-poisoning as
    /// `const_init_tls_try_with_calls`, whose closure premise it shares; read through
    /// `per_caller_typed_total_calls`, so the zero-obligation gate, the transport
    /// (`zero_obligation_native_vacuously_clean`), the R40 fixpoint and
    /// `all_calls_discharge_panic_free` read one set. TCB row: docs/TCB.md
    /// "slice-iterator consumer reading".
    slice_iter_consumer_total_calls: FxHashMap<String, FxHashSet<String>>,
    /// Trust (2026-10-13, R43-ZERO-ROW-PARITY): per-caller call keys of GENERIC
    /// local callees discharged by the R43 parametric premises (in
    /// `panic_free_proven_funcs` AND `parametric_panic_free_funcs`, and the call
    /// resolves to that very `InstanceKind::Item`). Written by
    /// `collect_parametric_generic_callee_total_calls` from the caller's OWN body,
    /// with the same registry snapshots and the same decision as the bundle's
    /// `collect_proven_total_panic_free_callees`; read through
    /// `per_caller_typed_total_calls` like the slice-iterator set above.
    parametric_generic_callee_total_calls: FxHashMap<String, FxHashSet<String>>,
    /// Trust (2026-10-15, VERIFIED-CALLABLE-ZERO-ROW-PARITY): per-caller call keys of
    /// the drive-only `Iterator` consumers, `str` pattern methods and array closure
    /// calls the bundle already treats as total because their callable's own verdict
    /// discharges it (`collect_verified_callable_consumer_total_calls`, docs/TCB.md),
    /// from the caller's OWN body with the SAME decision; read through
    /// `per_caller_typed_total_calls` like the two sets above. Before it, a body whose
    /// only calls were such consumers had its call removed from the bundle and then,
    /// with zero rows left, was refused by ZERO-ROW-GATE for that very call, which no
    /// registry the gate read could discharge (measured on the stage 1 of the
    /// 2026-10-14 merge: `v.windows(2).all(|w| w[0] <= w[1])`,
    /// `tests/ui/trust/adapter_yield/windows_all.rs#on`).
    verified_callable_consumer_total_calls: FxHashMap<String, FxHashSet<String>>,
    /// Trust (2026-10-15, CONST-CHUNK-SIZE-ZERO-ROW-PARITY): per-caller call keys of
    /// core's inherent `[T]::{chunks*, rchunks*, windows}` whose EVERY call in the
    /// caller's own body passes a non-zero CONSTANT size, the one way each panics
    /// (`size == 0`). vcgen charges exactly that at the call site
    /// (`SliceMethodPanic::NonZeroArg`) and a constant non-zero size leaves no row, so
    /// such a body reached the zero-obligation gate with the call undischarged (measured
    /// on the stage 1 of the 2026-10-14 merge: `v.windows(2).all(..)`, `[PF_ZEROGATE]
    /// ... arm=NONE callee=core::slice::<impl [u32]>::windows`). Written by
    /// `collect_const_nonzero_slice_chunking_total_calls`, read through
    /// `per_caller_typed_total_calls` like the sets above.
    const_nonzero_slice_chunking_total_calls: FxHashMap<String, FxHashSet<String>>,
    /// Trust (2026-10-15, BOUNDED-VEC-COLLECT-ZERO-ROW-PARITY): per-caller call keys of
    /// `Iterator::collect::<Vec<Item>>` over a total, drop-free std iterator whose item
    /// count bounds the reservation, the calls the bundle already treats as total
    /// (`collect_bounded_vec_collect_total_calls`, the SAME function over the SAME body).
    /// Before it, such a body reached the zero-obligation gate with the call
    /// undischarged and was refused for it (measured on the stage 1 of the 2026-10-14
    /// merge: `v.iter().copied().collect::<Vec<u32>>()`, `[PF_ZEROGATE] ... arm=NONE
    /// callee=<Copied<Iter<'_, u32>> as Iterator>::collect::<Vec<u32>>::<__trust_elem_bytes@4>`,
    /// `tests/ui/trust/vec_collect_with_bounded_bytes.rs#copied_slice`). Read through
    /// `per_caller_typed_total_calls` like the sets above.
    bounded_vec_collect_total_calls: FxHashMap<String, FxHashSet<String>>,
    /// Trust (1.101 migration, 2026-10-18, ENCODE-UTF8-BUF4-PARITY): per-caller
    /// call keys of core's `char::encode_utf8`/`encode_utf8_raw` whose every
    /// site in the caller's own body passes an unsize cast of `&mut [u8; N]`,
    /// `N >= 4` (`collect_char_encode_utf8_fitting_buffer_calls`, the SAME
    /// decision the bundle spends). vcgen's L0 row for the call is suppressed
    /// by the same fact, so without this set such a body reached the
    /// zero-obligation gate with the call undischarged. Read through
    /// `per_caller_typed_total_calls` like the sets above.
    char_encode_utf8_fitting_buffer_total_calls: FxHashMap<String, FxHashSet<String>>,
    /// R40 candidates keyed by the actual pre-monomorphization Item DefId.
    /// Some carries the same four established non-call premises, exact Call/
    /// TailCall surface, authenticated optional item identity and this owner's
    /// freshly computed typed grants. None is permanent poison for this owner.
    /// Repeated walks union call duties and intersect typed grants. Display
    /// paths are labels only: same-rendered other owners neither merge nor clear
    /// each other's findings. Missing/shim/promoted owner shapes admit nothing.
    zero_obligation_blessing_candidates: FxHashMap<DefId, Option<ZeroObligationBlessingCandidate>>,
    /// Fresh root-only typed facts, collected from that owner's own MIR below.
    /// These never read the legacy display-path maps to reconstruct authority.
    zero_obligation_typed_call_facts: FxHashMap<DefId, ZeroObligationTypedCallFacts>,
    /// Public obligation ids whose result row the compiler's OWN grounding pass
    /// re-pointed at the grounded residual violation, retiring the row binding
    /// in the process (`rewrite_result_formula_revoking_binding`). The value is
    /// the complete, collision-free row identity — never only the per-function
    /// row number. Consumed ONLY by the post-run native proof-authority
    /// validation, which judges such an obligation on that exact grounded row
    /// instead of on a binding the compiler deliberately revoked.
    grounded_panic_freedom_obligations: FxHashMap<String, ExactResultRowIdentity>,
    /// Trust (2026-10-05, ADVISORY-REQUIRES-TRANSITIVE-1): the local functions that
    /// owe their callers a `requires` and that no call compiled in another crate
    /// reaches through a chain of `requires` bodies — the only bodies
    /// `elide_kernel_certified_checks` may remove a check proved under the clause
    /// from (`trait_impl_requires::entry_requires_charged_only_in_this_crate`).
    /// `None` until the first elision that asks; then crate-scoped and immutable.
    requires_charged_only_here: Option<FxHashSet<LocalDefId>>,
}

fn with_crate_verification_state<R>(
    sess: &Session,
    f: impl FnOnce(&mut CrateVerificationState) -> R,
) -> R {
    sess.with_trust_compiler_state(f)
}

/// Carrier for an R1 verdict flip.
///
/// AUTHORITY: the only field that matters is `sealed` — a
/// `SealedCallerPropagationCertificate`, which the router will only mint after it
/// has REPLAYED, through the clean CIC kernel, both the strengthened obligation's
/// proof and every enumerated call site's discharge proof (see
/// `trust_router::strengthen_whole_program::mint_caller_propagation_certificate`).
/// The token's fields are private and it has no public constructor, so an
/// `R1Flip` cannot exist without that replay having happened, and the `Proved`
/// verdict it writes is produced by the token itself
/// (`attributed_verdict`) — not fabricated at the flip seam.
///
/// `location`/`kind_desc` are the STABLE match key only (the violation formula
/// carries SSA-version suffixes like `_4#s0_3` that differ between the harvest's
/// pre-optimization MIR and the per-body post-optimization MIR, so a formula
/// compare would never match). The certificate binds the exact pre-opt formula.
#[derive(Clone)]
struct R1Flip {
    location: trust_types::SourceSpan,
    kind_desc: String,
    sealed: trust_router::strengthen_whole_program::SealedCallerPropagationCertificate,
}

/// Trust #540 (R1): one flip `apply_r1_flips` actually wrote into `results` — the
/// flipped row index PLUS the sealed certificate that authorized it, so the
/// authority-install seam (`install_r1_flip_authorities`) can only mint a row
/// authority while holding the very token that produced the row's verdict.
struct R1AppliedFlip {
    row: ExactResultRowIdentity,
    sealed: trust_router::strengthen_whole_program::SealedCallerPropagationCertificate,
}

/// Trust #540 (R1, native transport rows): the SOURCE-obligation flip key of one
/// full-lane result row, recovered from the bound native verifier-api obligation.
///
/// On the FULL lane, `results` rows are rebuilt from the native transport
/// (`full_verification_legacy_results_bound`), and a VC the native engines could
/// not own comes back as a placeholder `VcKind::UnsupportedMir` whose
/// `description()` is the `unsupported MIR \`FullVerification::…\`: …` wrapper —
/// so the sealed certificate's exact-kind key (`authorizes_operation`, which binds
/// the harvested `vc.kind.description()`) can never match the row's own VC. The
/// native obligation itself, however, still carries the EXACT minted source
/// identity: trust-mir-extract's `function_to_verifier_api_bundle` sets
/// `description: vc.kind.description()` and `source: source_location(&vc.location)`
/// verbatim from the same vcgen VC the harvest keyed on. This struct is that
/// identity, at the SAME precision as the legacy route (kind description + file +
/// start line/col).
struct R1NativeRowFlipKey<'vcs> {
    kind_desc: String,
    file: String,
    line: u32,
    col: u32,
    /// Trust (composition review 2026-07-18, finding (c)): the ORIGINAL per-body
    /// vcgen violation formula of this row's bound obligation, recovered through
    /// the typed `vc_index` origin (`source_vc_for_api_obligation`) at key-build
    /// time. The transport row's own reconstructed formula is a placeholder, so
    /// this is the only honest formula for the narrowed-flip binding check
    /// (`r1_narrowed_flip_assumption_binds_row`); recovery failure stays `None`
    /// and the narrowed flip then refuses (fail-closed).
    source_formula: Option<&'vcs trust_types::Formula>,
}

/// R1 apply seam, enabled only when the router supplies its sealed, digest-bound
/// strengthening capability. The authority gate is checked before any session
/// state is read, and every applied verdict is authored by that non-forgeable
/// carrier. The remaining checks keep the live lane fail-closed:
/// - a flip is harvested for EXACTLY ONE obligation, so it may land on AT MOST ONE;
/// - match by the STABLE per-operation key (kind, source file, start line+col) — the
///   harvest reads pre-optimization MIR while this seam runs on optimized MIR, so SSA
///   names + the violation formula shift, but the source location does not;
/// - if a flip's key matches MORE THAN ONE not-yet-proved obligation (e.g. two divisions
///   on one source line, `a/b + c/d`), REFUSE to apply it to any — the harvest proved
///   only one, so flipping both would mark a genuinely-violable VC Proved (catastrophic);
/// - the ambiguity population is ALL key-matching rows REGARDLESS of proved-ness
///   (composition review 2026-07-18, finding (c)): rows the full lane proves BEFORE this
///   seam (ay bridge, `promote_kernel_certifiable`) must not silently narrow a
///   would-be-refused ambiguous key down to a single different row. A flip beside proved
///   co-matches lands only on a sole unproved row the sealed certificate's assumption
///   BINDS (`r1_narrowed_flip_assumption_binds_row`); otherwise it refuses.
/// Empty map (R1 inferred no flip for this fn) ⇒ no-op. Fail-closed throughout.
/// Trust #540 (R1): apply flips with the FULL lane's per-row native flip
/// keys (index-aligned with `results`; `&[]` on lanes without native bindings).
///
/// SOUNDNESS of the native-key route (the full-lane discharge seam). The native
/// typed-CHC/PDR runner verifies each transported VC IN ISOLATION, so for an
/// obligation R1 covers it honestly refutes the isolated duplicate ("SOME input
/// violates") even while the sealed certificate holds ("EVERY actual caller
/// establishes the strengthened precondition, kernel-replayed per caller").
/// Under the ratified R1 whole-program semantics
/// (docs/design-notes/2026-07-14-r1-authority-restoration.md) the sealed flip
/// discharges the isolated obligation for the whole program: the token's
/// closed-world coverage check proved the enumerated callers are ALL the ways
/// the function is ever entered, so the refuting "some input" is unreachable in
/// every real execution. The isolated duplicate row for the SAME source
/// obligation must therefore be discharged onto the flip authority rather than
/// surviving as an independent refutation — leaving it Failed would let a
/// weaker, isolated re-check of the same obligation override the sealed
/// whole-program proof.
///
/// FAIL-CLOSED boundaries, all preserved from the legacy route:
/// - the key decision is still delegated to the SEALED CERTIFICATE
///   (`authorizes_operation`) — this seam only supplies the native obligation's
///   own minted identity where the reconstructed placeholder VC kind can never
///   match; it cannot widen what the token binds;
/// - a row is eligible ONLY when its bound native obligation is provably a VC
///   transport duplicate (`r1_native_row_flip_key`: typed context producer
///   `CompilerMirExtract`, origin `VerificationCondition`, current schema,
///   `vc:`-minted id) — contract markers, proof items, and admissions never
///   participate;
/// - BOTH routes feed ONE match set per flip, so the MF-1 ambiguity refusal
///   (`reject_two_divisions_one_line`) spans them: a key matching two distinct
///   not-yet-proved rows applies to NEITHER — and the match set is computed
///   over ALL key-matching rows, proved or not, so a row proved earlier in
///   this very pipeline (bridge/kernel-promote) cannot narrow a refused
///   ambiguity into a false single match (composition review 2026-07-18 (c));
/// - an obligation with no sealed certificate gets no flip at all (the
///   attribution map has no entry), so every genuine refutation without a
///   covering sealed flip — the five `r1/reject_*` fixtures — survives intact.
///
/// Trust (T3 L4, C07r): `results` is the full lane's carrier, and a flip changes only a
/// row's verdict, so it is written through `RowResults::set_result`: the row's VC, and so
/// its id in the body's context, stays.
fn apply_r1_flips_with_native_row_keys(
    sess: &Session,
    def_path: &str,
    results: &mut RowResults,
    native_row_keys: &[Option<R1NativeRowFlipKey<'_>>],
) -> Vec<R1AppliedFlip> {
    // Trust: R1 seam tracing (TRUST_R1_TRACE) — show the per-body lookup key, the
    // stored keys, and (on a hit) every candidate result VC so a def_path/location
    // mismatch between harvest (pre-opt MIR) and this seam (opt MIR) is visible.
    let r1_trace = env_flag_enabled("TRUST_R1_TRACE");
    let (flips, stored_keys) = with_crate_verification_state(sess, |state| {
        let flips = state.r1_attributions.get(def_path).cloned();
        let keys = r1_trace.then(|| state.r1_attributions.keys().cloned().collect::<Vec<_>>());
        (flips, keys)
    });
    let Some(flips) = flips else {
        if r1_trace {
            eprintln!(
                "TRUST_R1_TRACE: apply_r1_flips: NO flip for def_path='{def_path}'; stored keys={:?}",
                stored_keys.unwrap_or_default(),
            );
        }
        return Vec::new();
    };
    if r1_trace {
        eprintln!(
            "TRUST_R1_TRACE: apply_r1_flips: def_path='{def_path}' has {} flip(s); {} result VC(s):",
            flips.len(),
            results.len()
        );
        for (index, (vc, res)) in results.iter().enumerate() {
            eprintln!(
                "TRUST_R1_TRACE:   result kind='{}' loc={}:{} file={:?} proved={}",
                vc.kind.description(),
                vc.location.line_start,
                vc.location.col_start,
                std::path::Path::new(&vc.location.file).file_name(),
                res.is_proved()
            );
            if let Some(Some(key)) = native_row_keys.get(index) {
                eprintln!(
                    "TRUST_R1_TRACE:     native key kind='{}' loc={}:{} file={:?}",
                    key.kind_desc,
                    key.line,
                    key.col,
                    std::path::Path::new(&key.file).file_name(),
                );
            }
        }
        for flip in &flips {
            eprintln!(
                "TRUST_R1_TRACE:   FLIP kind='{}' loc={}:{} file={:?}",
                flip.kind_desc,
                flip.location.line_start,
                flip.location.col_start,
                std::path::Path::new(&flip.location.file).file_name()
            );
        }
    }
    let mut applied = Vec::new();
    for flip in &flips {
        // ONE match set per flip across BOTH key routes (legacy VC key + native
        // transport key), so the ambiguity refusal below cannot be split-brained
        // into two single matches for two distinct operations.
        //
        // Trust (composition review 2026-07-18, finding (c) — MF-1 narrowing):
        // the match set spans ALL key-matching rows REGARDLESS of proved-ness.
        // On the full lane, rows become Proved BEFORE this seam runs (ay bridge,
        // `promote_kernel_certifiable` — including rows the trust-vc planning
        // exclusion routed to exactly that bridge+promote path), and the old
        // `!res.is_proved()` pre-filter let such a row silently leave the match
        // set: a would-be-refused ambiguous key (two same-kind operations
        // sharing file, line AND column — macro-twin spans) narrowed to a
        // single DIFFERENT, genuinely-violable row, minting a false
        // Proved+R1CallerPropagation for an obligation whose violation the
        // certificate never examined. Ambiguity is now judged on the full key
        // population; landing beside proved co-matches additionally requires
        // the certificate to BIND the sole unproved row (below).
        let matched: Vec<usize> = results
            .iter()
            .enumerate()
            .filter(|(index, (vc, _))| {
                r1_flip_matches(flip, vc)
                    || native_row_keys.get(*index).and_then(Option::as_ref).is_some_and(|key| {
                        // Same delegation as `r1_flip_matches`: the SEALED
                        // CERTIFICATE decides, on its own exact-identity
                        // key, from the native obligation's minted source
                        // identity.
                        flip.sealed.authorizes_operation(
                            &key.kind_desc,
                            &key.file,
                            key.line,
                            key.col,
                        )
                    })
            })
            .map(|(i, _)| i)
            .collect();
        let unproved: Vec<usize> =
            matched.iter().copied().filter(|&index| !results[index].1.is_proved()).collect();
        let decision = r1_flip_decision(matched.len(), &unproved, |index| {
            r1_narrowed_flip_assumption_binds_row(
                flip.sealed.assumption(),
                r1_row_source_formula(index, &results[..], native_row_keys),
            )
        });
        match decision {
            R1FlipDecision::Apply(index) => {
                let Some(row) = exact_result_row_identity(index, &results[index].0) else {
                    continue;
                };
                debug!(
                    "R1: flipped {} @ {def_path} {}:{} (sealed cert {})",
                    flip.kind_desc,
                    flip.location.line_start,
                    flip.location.col_start,
                    flip.sealed.digest()
                );
                // The verdict comes FROM the sealed certificate. There is no path
                // here that can write a `Proved` without holding one. `index` is a row of
                // `results` (`r1_flip_decision` picks it from `matched`).
                results.set_result(index, flip.sealed.attributed_verdict());
                applied.push(R1AppliedFlip { row, sealed: flip.sealed.clone() });
            }
            R1FlipDecision::NoTarget => {}
            R1FlipDecision::RefuseNarrowed => {
                debug!(
                    "R1: REFUSING narrowed flip for {def_path} ({} @ line {}): {} rows share the \
                     key and the sealed assumption does not bind the sole unproved row",
                    flip.kind_desc,
                    flip.location.line_start,
                    matched.len()
                );
                if r1_trace {
                    eprintln!(
                        "TRUST_R1_TRACE: apply_r1_flips: REFUSED narrowed flip for \
                         '{def_path}' kind='{}' loc={}:{} ({} key matches, sole unproved row \
                         unbound)",
                        flip.kind_desc,
                        flip.location.line_start,
                        flip.location.col_start,
                        matched.len()
                    );
                }
            }
            R1FlipDecision::RefuseAmbiguous => debug!(
                "R1: REFUSING ambiguous flip for {def_path} ({} @ line {}): {} obligations share the key",
                flip.kind_desc,
                flip.location.line_start,
                unproved.len()
            ),
        }
    }
    // The private carrier retains the exact pre-write row identity plus the
    // authorizing token. Public/native evidence and summary buckets remain
    // untouched; downstream compiler decisions consume this private authority.
    applied
}

/// Trust #540 (R1, native transport rows): per-row flip keys for the FULL lane,
/// index-aligned with `results` through `bindings`. A row without a binding, a
/// binding whose obligation is missing from the run, or an obligation that is
/// not a VC transport duplicate yields `None` (that row simply keeps the legacy
/// key route only — fail-closed).
fn r1_native_transport_flip_keys<'vcs>(
    run: &trust_verifier_api::VerificationRunResult,
    bindings: &[Option<ResultObligationBinding>],
    all_vcs: &'vcs [VerificationCondition],
) -> Vec<Option<R1NativeRowFlipKey<'vcs>>> {
    bindings
        .iter()
        .map(|binding| {
            let binding = binding.as_ref()?;
            let obligation = run
                .requested_obligations
                .iter()
                .find(|o| o.obligation_id == binding.public_obligation_id)?;
            r1_native_row_flip_key(obligation, all_vcs)
        })
        .collect()
}

/// Recover the exact source VC through its typed current-schema origin, then
/// re-check the source description and location written by the bundle mint.
/// Synthetic or ambiguous obligations cannot borrow another VC's formula.
fn source_vc_for_api_obligation<'a>(
    obligation: &trust_verifier_api::TrustObligation,
    all_vcs: &'a [VerificationCondition],
) -> Option<&'a VerificationCondition> {
    let mut contexts = obligation
        .metadata
        .iter()
        .filter(|entry| entry.key == trust_verifier_api::OBLIGATION_CONTEXT_METADATA_KEY);
    let context_entry = contexts.next()?;
    if contexts.next().is_some() {
        return None;
    }
    let context =
        trust_verifier_api::ObligationContext::from_metadata_entry(context_entry).ok()??;
    if !context.has_current_schema()
        || !matches!(context.producer, trust_verifier_api::ObligationProducer::CompilerMirExtract)
    {
        return None;
    }
    let trust_verifier_api::ObligationOrigin::VerificationCondition { vc_index, .. } =
        context.origin
    else {
        return None;
    };
    let vc = all_vcs.get(vc_index)?;
    let location = &vc.location;
    let source_matches = obligation.source.file.as_deref()
        == (!location.file.is_empty()).then_some(location.file.as_str())
        && obligation.source.line == (location.line_start != 0).then_some(location.line_start)
        && obligation.source.column == (location.col_start != 0).then_some(location.col_start);
    (obligation.description == vc.kind.description() && source_matches).then_some(vc)
}

/// Trust #540 (R1, native transport rows): recover the SOURCE obligation's flip
/// key from a native verifier-api obligation, ONLY when the obligation is
/// provably the VC transport duplicate of a vcgen VC:
/// - not the synthetic per-function admission;
/// - minted with the `vc:` id shape trust-mir-extract uses for VC obligations;
/// - carrying EXACTLY ONE typed obligation context, current schema, produced by
///   `CompilerMirExtract` with origin `VerificationCondition` — the metadata
///   `function_to_verifier_api_bundle` stamps on every VC-derived obligation.
///   (Contract markers carry origin `Contract`, proof items `ProofItem`; both
///   refuse here, so a free-text contract description can never impersonate a
///   VC kind description.)
/// For such an obligation, `description` IS `vc.kind.description()` and
/// `source` IS the VC's own location, verbatim from the mint — the exact
/// identity the sealed certificate binds. Any absent field fails closed.
fn r1_native_row_flip_key<'vcs>(
    obligation: &trust_verifier_api::TrustObligation,
    all_vcs: &'vcs [VerificationCondition],
) -> Option<R1NativeRowFlipKey<'vcs>> {
    if obligation.is_default_admission() || !obligation.obligation_id.starts_with("vc:") {
        return None;
    }
    let mut contexts = obligation
        .metadata
        .iter()
        .filter(|entry| entry.key == trust_verifier_api::OBLIGATION_CONTEXT_METADATA_KEY);
    let context_entry = contexts.next()?;
    if contexts.next().is_some() {
        return None;
    }
    let context =
        trust_verifier_api::ObligationContext::from_metadata_entry(context_entry).ok()??;
    if !context.has_current_schema()
        || !matches!(context.producer, trust_verifier_api::ObligationProducer::CompilerMirExtract)
        || !matches!(
            context.origin,
            trust_verifier_api::ObligationOrigin::VerificationCondition { .. }
        )
    {
        return None;
    }
    let file = obligation.source.file.clone()?;
    if file.is_empty() {
        return None;
    }
    Some(R1NativeRowFlipKey {
        kind_desc: obligation.description.clone(),
        file,
        line: obligation.source.line?,
        col: obligation.source.column?,
        // The audited typed-origin recovery (`vc_index` + description/source
        // cross-check). `None` on any skew — the narrowed-flip binding check
        // then refuses (fail-closed); the span-key routes above are unaffected.
        source_formula: source_vc_for_api_obligation(obligation, all_vcs).map(|vc| &vc.formula),
    })
}

/// Trust #540 (R1): seal each applied flip's row authority. Runs AFTER
/// `build_result_proof_authorities` on both lanes; without this the flipped
/// row's `Proved` is a label with no row-bound authority token, so every
/// authority-era consumer (`convert_result`, the strict L0 gap count,
/// transport) demotes it back to Unknown and R1 can never actually save a
/// build. Minting REQUIRES the applied flip's own sealed certificate (carried
/// by [`R1AppliedFlip`] from the only seam that could write the verdict), so
/// this authority cannot exist for a row no token flipped. An already-present
/// authority is kept — it can only be a real independent proof of the row
/// itself (kernel/native/revalidation), which outranks attribution.
fn install_r1_flip_authorities(
    applied: &[R1AppliedFlip],
    results: &[(trust_types::VerificationCondition, trust_types::VerificationResult)],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) {
    if results.len() != proof_authorities.len() {
        return;
    }
    for flip in applied {
        let index = flip.row.index;
        let Some((vc, result)) = results.get(index) else { continue };
        let Some(current_row) = exact_result_row_identity(index, vc) else { continue };
        // `R1AppliedFlip` is a private carrier constructed only at the exact
        // write seam after the sealed certificate authorized either this row's
        // native SOURCE key or its legacy VC key. Full-lane rows deliberately
        // reconstruct a placeholder VC, so rechecking that placeholder here
        // would revoke every correctly source-authorized native flip. The
        // frozen exact row identity prevents moving the applied capability, and
        // the complete attributed verdict comparison prevents replacing the
        // token-authored result before installation.
        if current_row != flip.row || !r1_attributed_verdict_matches(result, &flip.sealed) {
            continue;
        }
        let Some(slot) = proof_authorities.get_mut(index) else { continue };
        if slot.is_some() {
            continue;
        }
        *slot = Some(ResultProofAuthority::CallerPropagation {
            row: flip.row.clone(),
            sealed: flip.sealed.clone(),
        });
    }
}

/// Trust (VF5): the label a calculus row's result carries. Only the calculus
/// mint writes it, and `CalculusRowProved` authorizes no other result.
const CALCULUS_ROW_SOLVER: &str = "clean-kernel-vf5-calculus";

/// Trust (VF5): the result `install_calculus_row_authorities` writes on a row
/// it proved.
fn calculus_row_result() -> VerificationResult {
    VerificationResult::Proved {
        solver: CALCULUS_ROW_SOLVER.into(),
        time_ms: 0,
        strength: ProofStrength::constructive(),
        proof_certificate: None,
        solver_warnings: None,
        native_proof_envelope: None,
    }
}

/// Trust (VF5): whether `result` is exactly the calculus mint's.
fn is_calculus_row_result(result: &VerificationResult) -> bool {
    matches!(
        result,
        VerificationResult::Proved {
            solver,
            strength,
            proof_certificate: None,
            solver_warnings: None,
            native_proof_envelope: None,
            ..
        } if solver.as_str() == CALCULUS_ROW_SOLVER && *strength == ProofStrength::constructive()
    )
}

/// Trust (VF5): the rows a "proved (calculus)" certificate covers: the L0
/// obligations whose violation is a run that `ClosedSafe` excludes, read off
/// Clean's `vf5_f1` (`Bad` is `ub | typeError | unsupported | panic` and
/// nothing else): a MIR `Assert` that fails (division or remainder by zero, an
/// index out of bounds) or an `Unreachable` reached, and the
/// overflow rows only when this compile checks overflow (`overflow_checks`),
/// because only then is an overflow the `Assert` panic SemR reads (without the
/// check the operation wraps, which SemR does not call `Bad`). Every other L0
/// kind (an unbounded allocation, a format string, a tainted branch, an
/// ownership or ABI property, an unmodeled construct, an unchecked operation
/// whose UB SemR may not model, an `Assertion` row, which the FFI and binary
/// lanes also mint for contracts outside the module) states a property the
/// theorem does not, and is never covered. No type-invariant fact may be in the formula.
fn calculus_row_covers(vc: &VerificationCondition, overflow_checks: bool) -> bool {
    let kind_covered = match &vc.kind {
        VcKind::DivisionByZero
        | VcKind::RemainderByZero
        | VcKind::IndexOutOfBounds
        | VcKind::Unreachable => true,
        VcKind::ArithmeticOverflow { .. }
        | VcKind::ShiftOverflow { .. }
        | VcKind::NegationOverflow { .. } => overflow_checks,
        _ => false,
    };
    kind_covered
        && is_strict_l0_vc_kind(&vc.kind)
        && matches!(vc.type_invariant_tags(), trust_types::TinvTagScan::None)
}

/// Trust (VF5): mint `CalculusRowProved` on every row of the function `symbol`
/// that its certificate covers, and return the rows minted (the caller writes
/// [`calculus_row_result`] on each).
///
/// The certificate is the one the process recorded for `symbol` whose
/// judgment was about exactly `artifact`
/// (`trust_certify::calculus_row::calculus_row_certificate_bound`); the caller
/// passes the symbol its own published trust-ir module gives the body and that
/// module's own bytes ([`calculus_row_binding_of_body`]), so a certificate about
/// another crate's artifact, or a stale one, mints nothing. Nothing is minted
/// in a function where any covered row is refuted or the carrier is skewed: a
/// solver's refutation of an obligation the calculus proved is a
/// contradiction, and the calculus never overrides it. A row any other lane
/// already claimed keeps its authority; a row whose result is neither
/// `Proved`, `Unknown` nor `Timeout` is left alone.
fn install_calculus_row_authorities(
    symbol: &[u8],
    artifact: &[u8],
    overflow_checks: bool,
    results: &[(VerificationCondition, VerificationResult)],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) -> Vec<usize> {
    let Some(certificate) =
        trust_certify::calculus_row::calculus_row_certificate_bound(symbol, artifact)
    else {
        return Vec::new();
    };
    install_calculus_certificate_authorities(
        &certificate, symbol, artifact, overflow_checks, results, proof_authorities,
    )
}

fn install_calculus_certificate_authorities(
    certificate: &trust_certify::calculus_row::CalculusRowCertificate,
    symbol: &[u8],
    artifact: &[u8],
    overflow_checks: bool,
    results: &[(VerificationCondition, VerificationResult)],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) -> Vec<usize> {
    if !certificate.binds_symbol(symbol) || !certificate.binds_artifact(artifact) {
        return Vec::new();
    }
    if results.len() != proof_authorities.len()
        || results.iter().any(|(vc, result)| {
            calculus_row_covers(vc, overflow_checks)
                && matches!(result, VerificationResult::Failed { .. })
        })
    {
        return Vec::new();
    }
    let mut minted = Vec::new();
    for (index, (vc, result)) in results.iter().enumerate() {
        if proof_authorities[index].is_some()
            || !calculus_row_covers(vc, overflow_checks)
            || !matches!(
                result,
                VerificationResult::Proved { .. }
                    | VerificationResult::Unknown { .. }
                    | VerificationResult::Timeout { .. }
            )
        {
            continue;
        }
        let Some(row) = exact_result_row_identity(index, vc) else { continue };
        proof_authorities[index] = Some(ResultProofAuthority::CalculusRowProved {
            row,
            symbol: symbol.to_vec(),
            certificate: certificate.clone(),
        });
        minted.push(index);
    }
    minted
}

/// Trust (VF5): the symbol the published crate module gives the function
/// `def_path`: the module's own `display_path` index (ambiguous paths already
/// removed) names one function, and that function's link-time name must
/// itself resolve back to it (ambiguous names already removed). `None` when
/// either is missing or ambiguous, so a body is matched to one function of
/// this compile's module or to none.
fn calculus_row_symbol_in_module(
    def_path: &str,
    display_paths: &BTreeMap<String, trust_ir::FuncId>,
    symbols: &BTreeMap<String, trust_ir::FuncId>,
    module: &trust_ir::Module,
) -> Option<String> {
    let id = *display_paths.get(def_path)?;
    let function = module.functions.iter().find(|function| function.id == id)?;
    (!function.name.is_empty() && symbols.get(&function.name) == Some(&id))
        .then(|| function.name.clone())
}

/// Trust (VF5): what a calculus certificate for this body must be about: the
/// symbol THIS compile's published trust-ir module gives the body
/// ([`calculus_row_symbol_in_module`], keyed by the def path exactly as the
/// trust-ir codegen frontend keys it) and that module's own bytes (the
/// binary image `-Ztrust-dump=ir:` publishes). `None` when the process records
/// no certificate (no work at all), for a generic, non-local or non-`fn` body,
/// and when no module is published yet (verification ran before crate
/// finalization, or the module was refused): fail closed. Not
/// `tcx.symbol_name`: asking for this body's symbol from inside its own MIR
/// optimization is a query cycle.
fn calculus_row_binding_of_body<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Option<(Vec<u8>, Vec<u8>)> {
    if !trust_certify::calculus_row::any_registered() {
        return None;
    }
    let def_id = body.source.def_id();
    if !def_id.is_local()
        || !matches!(tcx.def_kind(def_id), DefKind::Fn | DefKind::AssocFn)
        || tcx.generics_of(def_id).requires_monomorphization(tcx)
    {
        return None;
    }
    let def_path = with_no_trimmed_paths!(tcx.def_path_str(def_id));
    trust_thir_lower::crate_module::with_published_crate_module(tcx.sess, |published| {
        let published = published.ok()?;
        let symbol = calculus_row_symbol_in_module(
            &def_path,
            published.display_paths(),
            published.symbols(),
            published.module(),
        )?;
        let artifact = trust_ir::binary::serialize_module(published.module()).ok()?;
        Some((symbol.into_bytes(), artifact))
    })
}

/// Trust (interprocedural panic-freedom closure): seal the whole-function
/// panic-freedom catch-all row that `refute_full_assert_obligations`'
/// interprocedural seam (`all_calls_discharge_panic_free`) discharged.
///
/// The seam writes a `Proved` verdict on the pf catch-all row but installs NO
/// authority — for a call-dispatch-dominated function (no assert/panic block of
/// its own and no other open obligation) the grounding "others" set is empty, so
/// `ground_panic_freedom_catchall` is a no-op, the opaque `panic_reachable:` atom
/// survives, and `certify_all`/`build_result_proof_authorities` mint nothing. A
/// `None`-authority `Proved` pf row is demoted to Unknown at strict L0 and never
/// enters the interprocedural panic-free registry, so the discharge cannot chain
/// to callers. This installs the exact, row-frozen, UNCONDITIONAL
/// `InterproceduralCalleeClosure` authority on precisely that row.
///
/// IDENTIFICATION (fail-closed, anti-transplant). A target row is recognized by
/// the exact seam verdict shape: a whole-function panic-freedom `Assertion` whose
/// formula is still the symbolic `panic_reachable:` `Var` (the empty-others case
/// `ground_panic_freedom_catchall` left untouched), whose result is exactly the
/// seam's `Proved { solver: "trust-assert-refute", proof_certificate: None,
/// native_proof_envelope: None }`, and whose authority slot is still `None`. The
/// still-symbolic formula is what distinguishes THIS interprocedural discharge
/// from the intraprocedural one, which ALWAYS re-points the formula to a grounded
/// assert-feasibility disjunction; and `trust-assert-refute` is minted only by
/// those two seams. So a symbolic pf row `Proved` under `trust-assert-refute` can
/// only be the interprocedural seam — which fired ONLY after
/// `all_calls_discharge_panic_free` held. The frozen exact row identity
/// carried in the authority prevents any later transplant; the `None`-slot guard
/// (mirroring `install_r1_flip_authorities`) prevents overwriting a real
/// independent proof (kernel/native/revalidation).
///
/// HARDENING (self-justifying). Installs ONLY when every OTHER result row is an
/// unconditional static proof and no row is an entry/assumed-total discharge —
/// the identical bar `results_establish_unconditional_panic_freedom` applies — so
/// the single pf row carrying this authority is all-input panic-free in
/// isolation, exactly like every other unconditional authority.
fn install_interprocedural_callee_closure_authorities(
    sess: &Session,
    func: &trust_types::VerifiableFunction,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) {
    if results.len() != proof_authorities.len() {
        return;
    }
    if !result_bindings.is_empty() && results.len() != result_bindings.len() {
        return;
    }
    // The seam's UNCONDITIONAL verdict shape. The distinct
    // `trust-assert-refute-under-precondition` tag (a `#[requires]` fn's Part-B
    // conditional discharge) is deliberately NOT accepted: a conditional
    // discharge must never mint this unconditional authority.
    let seam_proved_unconditional = |result: &VerificationResult| {
        matches!(
            result,
            VerificationResult::Proved {
                solver,
                proof_certificate: None,
                native_proof_envelope: None,
                ..
            } if solver.as_str() == "trust-assert-refute"
        )
    };
    // Two authenticated pf catch-all shapes:
    //  * the vcgen/rekeyed Assertion row (still-symbolic `panic_reachable:` Var —
    //    the empty-others case `ground_panic_freedom_catchall` left untouched);
    //  * the full-lane TRANSPORT RESTATEMENT (`UnsupportedMir{FullVerification::
    //    Assertion}`) whose identity is sealed by its row binding's compiler-held
    //    canonical obligation (`is_full_lane_panic_freedom_restatement_row` —
    //    recomputed id/marker/digests, never display strings). In both shapes the
    //    `trust-assert-refute` verdict written with cert/envelope `None` can only
    //    originate from the two refute seams, and for the restatement shape only
    //    from Path 2 — which fired ONLY after `others_all_proved` and the
    //    call-discharge gate held.
    //
    // R23. The seam's gate FACT for this function, recorded by
    // `refute_full_assert_obligations` from its own positively-computed
    // `others_all_proved && all_calls_discharge_panic_free` and ONLY for the
    // unconditional tag. Absent ⇒ `false`.
    let seam_gate_held_unconditionally =
        recorded_interprocedural_pf_call_closure(sess, &func.def_path);
    let is_seam_discharged_pf_row =
        |index: usize, vc: &VerificationCondition, result: &VerificationResult| {
            let is_pf_catchall_row = is_panic_freedom_assertion_vc(vc)
                && matches!(&vc.formula, trust_types::Formula::Var(name, _) if name.starts_with("panic_reachable"))
                || is_full_lane_panic_freedom_restatement_row(
                    func,
                    index,
                    vc,
                    result_bindings.get(index).and_then(Option::as_ref),
                );
            if !is_pf_catchall_row {
                return false;
            }
            // (1) the seam WROTE this row's verdict (the original shape,
            //     unchanged — an Unknown row it upgraded); or
            // (2) R23: the seam's gate HELD for this function but the row was
            //     already `Proved` by another lane, so the `!is_definitive`
            //     overwrite guard correctly left the verdict alone. The pf claim
            //     is entailed by the GATE, not by whoever wrote the verdict, so
            //     the authority is justified either way — and the still-`None`
            //     slot check below is what makes "this `Proved` has no authority"
            //     OBSERVABLE rather than inferred: every real lane
            //     (kernel/native/source/body-bound/R1/E9) has already run and
            //     claimed its rows by the time this installer executes.
            //
            // NOT A WIDENING OF WHAT THE AUTHORITY MEANS. Every hardening gate
            // below is unchanged and each is load-bearing here: an empty slot,
            // a frozen exact row identity, EVERY sibling row `Proved` under its
            // own unconditional static authority (so a `Failed` row APPENDED
            // after the gate ran — a call-site L0 replay refutation — still
            // blocks it), and no entry/assumed-total assumption anywhere.
            seam_proved_unconditional(result)
                || (seam_gate_held_unconditionally && result.is_proved())
        };
    for index in 0..results.len() {
        if !is_seam_discharged_pf_row(index, &results[index].0, &results[index].1) {
            continue;
        }
        // Anti-transplant slot gate (mirrors `install_r1_flip_authorities`):
        // never overwrite a real independent proof of the pf row itself; only
        // seal a slot the authority builder left `None`.
        if proof_authorities[index].is_some() {
            continue;
        }
        // Freeze the exact identity of THIS row and seal the authority to it. A
        // later carrier rewrite of the formula changes the canonical VC and
        // `matches_row` fails, so the capability can never move to another row.
        let Some(row) = exact_result_row_identity(index, &results[index].0) else {
            continue;
        };
        // HARDENING sibling-gate: every OTHER row must itself be an unconditional
        // static proof (the same bar `results_establish_unconditional_panic_freedom`
        // applies), so this single pf row is all-input panic-free on its own.
        let siblings_all_unconditional =
            results.iter().zip(proof_authorities.iter()).enumerate().all(
                |(other, ((other_vc, other_result), other_authority))| {
                    other == index
                        || (other_result.is_proved()
                            && other_authority.as_ref().is_some_and(|authority| {
                                authority.is_unconditional_static_proof_for(
                                    other,
                                    other_vc,
                                    other_result,
                                    result_bindings.get(other).and_then(Option::as_ref),
                                )
                            }))
                },
            );
        if !siblings_all_unconditional {
            continue;
        }
        // No row may be an entry/assumed-total discharge — the identical
        // exclusion `results_establish_unconditional_panic_freedom` makes: a
        // conditional modular assumption is never an unconditional all-input
        // proof and must not authorize the global registry.
        if results.iter().any(|(_, result)| {
            is_entry_assumption_discharge(result) || is_assumed_total_discharge(result)
        }) {
            continue;
        }
        if proof_authorities.iter().any(|authority| {
            matches!(
                authority,
                Some(
                    ResultProofAuthority::DefinitionEntryAssumption { .. }
                        | ResultProofAuthority::AssumedTotalCalleeAssumption { .. }
                        | ResultProofAuthority::CallerPropagation { .. }
                        // Trust (TINV step 10.4, TINV-27): conditional on a
                        // type-invariant certificate; never a registry premise.
                        | ResultProofAuthority::TypeInvariantComposed { .. }
                        // Trust (merge 2026-10-14): nor a row resting on an
                        // argument premise (D14/D15).
                        | ResultProofAuthority::ArgumentPremiseKernelDischarge { .. }
                        // Trust (VF5): nor a calculus row (closed-world entry).
                        | ResultProofAuthority::CalculusRowProved { .. }
                )
            )
        }) {
            continue;
        }
        proof_authorities[index] = Some(ResultProofAuthority::InterproceduralCalleeClosure { row });
    }
}

fn r1_attributed_verdict_matches(
    result: &VerificationResult,
    sealed: &trust_router::strengthen_whole_program::SealedCallerPropagationCertificate,
) -> bool {
    let expected = sealed.attributed_verdict();
    matches!(
        (result, &expected),
        (
            VerificationResult::Proved {
                solver,
                time_ms,
                strength,
                proof_certificate,
                solver_warnings,
                native_proof_envelope,
            },
            VerificationResult::Proved {
                solver: expected_solver,
                time_ms: expected_time_ms,
                strength: expected_strength,
                proof_certificate: expected_certificate,
                solver_warnings: expected_warnings,
                native_proof_envelope: expected_native_proof_envelope,
            },
        ) if solver == expected_solver
            && time_ms == expected_time_ms
            && strength == expected_strength
            && proof_certificate == expected_certificate
            && solver_warnings == expected_warnings
            && native_proof_envelope == expected_native_proof_envelope
    )
}

/// Stable per-operation flip key: kind + file path + start line/col. Drops
/// `line_end`/`col_end` and the SSA-laden formula (which shift pre-opt→opt), but keeps
/// `col_start` so two same-kind operations on one line (`a/b + c/d`) stay distinct.
///
/// Trust: the file comparison requires component-aligned path-suffix agreement
/// of at least TWO components (directory + file), not a bare basename match.
/// The harvest reads pre-optimization MIR while `apply_r1_flips` runs on
/// post-inlining bodies whose VC set mixes obligations from OTHER files, and
/// Rust trees are full of colliding `mod.rs`/`lib.rs` basenames — a bare
/// basename key could single-match a foreign obligation and flip the WRONG
/// verdict. Suffix matching keeps the tolerance for prefix-rendering
/// differences (absolute vs crate-relative) without that collision; an
/// unmatched flip is simply not applied (fail-closed — the verdict stays at
/// its honest pre-R1 value).
///
/// The decision is delegated to the SEALED CERTIFICATE
/// (`authorizes_operation`), so the row key a flip lands on is the one the token
/// itself binds — the flip seam cannot widen it.
fn r1_flip_matches(flip: &R1Flip, vc: &trust_types::VerificationCondition) -> bool {
    flip.sealed.authorizes_operation(
        &vc.kind.description(),
        &vc.location.file,
        vc.location.line_start,
        vc.location.col_start,
    )
}

/// Trust (composition review 2026-07-18, finding (c)): the flip seam's landing
/// decision over one flip's full key population. Pure so the refusal lattice is
/// unit-testable without a `Session`/sealed certificate.
#[derive(Debug, PartialEq, Eq)]
enum R1FlipDecision {
    /// No key match at all, or every key-matching row is already proved on its
    /// own evidence — the flip has nothing to discharge.
    NoTarget,
    /// Land on exactly this row index.
    Apply(usize),
    /// MF-1: the key matches two or more not-yet-proved obligations. The
    /// harvest proved only one, so flipping any would mark a genuinely-violable
    /// VC Proved (catastrophic). Refuse ALL.
    RefuseAmbiguous,
    /// Review (c): proved co-matches narrowed the key population to a sole
    /// unproved row that the sealed certificate's assumption does not bind —
    /// the exact configuration MF-1 refused before those rows were proved.
    RefuseNarrowed,
}

/// The refusal lattice (composition review 2026-07-18, finding (c)):
///
/// * no unproved match ⇒ [`R1FlipDecision::NoTarget`];
/// * ≥ 2 unproved matches ⇒ [`R1FlipDecision::RefuseAmbiguous`] (MF-1,
///   unchanged — this bound is over the SAME population as before the review
///   fix, so nothing previously refused is admitted);
/// * a UNIQUE key match that is the sole unproved row ⇒ apply (the pre-review
///   behavior for the unambiguous case; the binding predicate is deliberately
///   not consulted — there is nothing to disambiguate);
/// * ≥ 2 key matches with exactly ONE unproved (the NARROWED case — proved
///   co-matches used to hide this configuration from MF-1 entirely) ⇒ apply
///   ONLY when `binds_sole_unproved` holds, i.e. the sealed certificate can be
///   bound to that row beyond the shared span key; otherwise refuse.
///
/// Refusal-only relative to the pre-review seam: every configuration this
/// admits was admitted before; the narrowed case now additionally refuses.
fn r1_flip_decision(
    matched_count: usize,
    unproved: &[usize],
    binds_sole_unproved: impl FnOnce(usize) -> bool,
) -> R1FlipDecision {
    match (matched_count, unproved) {
        (_, []) => R1FlipDecision::NoTarget,
        (1, &[index]) => R1FlipDecision::Apply(index),
        (_, &[index]) => {
            if binds_sole_unproved(index) {
                R1FlipDecision::Apply(index)
            } else {
                R1FlipDecision::RefuseNarrowed
            }
        }
        _ => R1FlipDecision::RefuseAmbiguous,
    }
}

/// Trust (composition review 2026-07-18, finding (c)): the SOURCE violation
/// formula of one result row, for the narrowed-flip binding check. A row bound
/// to a native transport obligation answers ONLY through the key's recovered
/// per-body vcgen formula (`R1NativeRowFlipKey::source_formula`) — the
/// transport row's own reconstructed formula is a placeholder and must never
/// stand in for it (recovery failure ⇒ `None` ⇒ the narrowed flip refuses). A
/// row without a native key (the default lane, whose rows ARE the vcgen VCs)
/// answers with its own carried formula.
fn r1_row_source_formula<'row>(
    index: usize,
    results: &'row [(trust_types::VerificationCondition, trust_types::VerificationResult)],
    native_row_keys: &'row [Option<R1NativeRowFlipKey<'_>>],
) -> Option<&'row trust_types::Formula> {
    if let Some(Some(key)) = native_row_keys.get(index) {
        return key.source_formula;
    }
    results.get(index).map(|(vc, _)| &vc.formula)
}

/// Trust (composition review 2026-07-18, finding (c)): whether a sealed
/// certificate's caller assumption `P` BINDS a narrowed-flip landing row —
/// every free variable of `P` must occur among the free variables of the row's
/// source violation formula, comparing SSA-version-stripped base names
/// (`divisor` binds `divisor#s0_1`; the harvest reads pre-optimization MIR
/// while the seam's rows are post-optimization, so version tokens shift but
/// parameter base names do not).
///
/// This is `mint_caller_propagation_certificate`'s connectedness requirement
/// (its check (3): `P`'s free variables are a non-empty subset of `V`'s)
/// re-applied AT THE LANDING ROW: a `P` over variables the row's violation
/// never mentions cannot be the assumption that discharges THIS operation —
/// the certificate belongs to a different same-key operation (the macro-twin
/// hazard), so the flip refuses. Same-operation encoding twins (the vcgen
/// assert-terminator/statement pair of one division — `flip_caller_covered`'s
/// per-key layout, `reject_two_divisions_one_line`'s per-key pairs) stay
/// connected through the shared operand and keep flipping.
///
/// RESIDUAL (documented, strictly narrower than the pre-review seam, which
/// performed NO such check): the binding is variable-connectivity, not a
/// kernel entailment re-check — two DISTINCT same-key operations over the SAME
/// operands still admit. Closing that requires the harvest-side per-key
/// ordinal/discriminator in `SealedVcIdentity` suggested by the review.
///
/// Fail-closed: an unrecoverable source formula never binds, and a closed
/// assumption (no free variables — unreachable past the mint's connectedness
/// check) never binds.
// Iteration order over the two free-variable sets cannot affect the outcome:
// the decision is a pure subset test (`all` of one set found in the other),
// which is order-invariant.
#[allow(rustc::potential_query_instability)]
fn r1_narrowed_flip_assumption_binds_row(
    assumption: &trust_types::Formula,
    source_formula: Option<&trust_types::Formula>,
) -> bool {
    let Some(source_formula) = source_formula else {
        return false;
    };
    let assumption_variables = assumption.free_variables();
    if assumption_variables.is_empty() {
        return false;
    }
    let row_variables: Vec<String> = source_formula
        .free_variables()
        .into_iter()
        .map(|name| r1_variable_base_name(&name).to_owned())
        .collect();
    assumption_variables.iter().all(|assumed| {
        let assumed = r1_variable_base_name(assumed);
        row_variables.iter().any(|row_variable| row_variable.as_str() == assumed)
    })
}

/// The SSA-version-stripped base name of a formula variable: `divisor#s0_1` →
/// `divisor`. Version tokens are exactly the `#`-suffixed statement-version
/// spellings (`normalize_ssa_version_tokens` / vcgen's `StmtVersionCtx`);
/// source-level parameter names can never contain `#`.
fn r1_variable_base_name(name: &str) -> &str {
    name.split('#').next().unwrap_or(name)
}

/// Trust #540 (R1): initialize whole-program strengthening state.
///
/// Every flip this records is authorized by a sealed certificate the router mints
/// only after kernel-replaying the strengthened proof AND every caller's discharge
/// proof. `-Ztrust-no-r1` returns here before the crate-wide MIR scan or any
/// solver construction, so the negative control costs nothing to run.
#[allow(rustc::untracked_query_information, rustc::potential_query_instability)]
pub fn trust_init_r1_attributions(tcx: TyCtxt<'_>) {
    if !verification_enabled(tcx.sess)
        || with_crate_verification_state(tcx.sess, |state| state.r1_initialized)
    {
        return;
    }
    if tcx.sess.opts.unstable_opts.trust_no_r1 {
        with_crate_verification_state(tcx.sess, |state| {
            state.r1_attributions.clear();
            // No scan ran, so there is no scan gap to report: R1 is off by request,
            // not poisoned. Reporting one here would blame the crate for a flag.
            state.r1_scan_gaps.clear();
            state.r1_initialized = true;
        });
        return;
    }
    // Trust (T3 L4, C06a): the R1 pre-pass's elision-audit scope, for the whole harvest.
    let _audit_scope = elide_audit::CrateScope::enter(tcx, "crate:r1");
    // Trust (T3 L4, C07p): the row oracle's count over every harvest's own VC context,
    // folded as each harvest ends (`with_scoped_rows`).
    let mut r1_parity = trust_types::vc_context::ParityTally::default();
    let info = crate::trust_r1_oracle::scan_crate_calls(tcx);
    // Verify through the deterministic IN-PROCESS ay backend — NOT the external-binary
    // cached router, whose per-VC subprocess timeout makes verdicts nondeterministic at
    // this analysis seam (Failed one build, Unknown the next). `InProcessAyBackend` is
    // always available (rustc_mir_transform enables trust-router's `ay-backend`).
    let ay = trust_router::Router::deterministic_in_process_ay(
        vc_timeout_ms(tcx.sess),
        effort_scale(tcx.sess),
    );
    let trace = env_flag_enabled("TRUST_R1_TRACE");
    if trace {
        eprintln!(
            "TRUST_R1_TRACE: init: incomplete={} address_taken={} callers_keys={} recursive={} hidden={}",
            info.incomplete.len(),
            info.address_taken.len(),
            info.callers.len(),
            info.recursive.len(),
            info.hidden_call_target.len(),
        );
    }
    let mut map: BTreeMap<String, Vec<R1Flip>> = BTreeMap::new();
    for &local in tcx.mir_keys(()) {
        if !matches!(tcx.def_kind(local.to_def_id()), DefKind::Fn | DefKind::AssocFn) {
            continue;
        }
        // Trust (L0 termination guarantee): arm the per-function verification
        // budget around the harvest. MEASURED 2026-08-31: the only production
        // `VerifyBudgetGuard::install` was in the PER-BODY pass, so this
        // whole-crate PRE-PASS ran with `VERIFY_STEPS = u64::MAX` and no
        // deadline — every `budget_exhausted()` poll reachable from here was
        // dead, and no timeout could bound it. On `trust-spec-elab` the pre-pass
        // consumed >=99.7% of the process's thread time and the compilation
        // never reached a report. A fresh guard per function (restored on drop,
        // including unwind) makes the polls live and bounds each harvest
        // independently. Fail-closed: an over-budget harvest returns `None`,
        // which mints NO flip — strictly fewer claims, never a proof.
        let harvested = {
            let _r1_budget = trust_types::verify_budget::VerifyBudgetGuard::install(
                verify_fn_deadline(tcx.sess),
                tcx.sess.opts.unstable_opts.trust_verify_function_budget_steps,
            );
            // Determinism plan §3.2a (R1 row): each harvest solve stops on its
            // own query's count — R1 flips feed OTHER functions' verdicts, so
            // they must be reproducible, and no count is shared across solves.
            // Trust (ALLOC-WIDTH-1): every generation the harvest runs — F's VCs, the
            // F-safe-under-P re-check, the mono and SCC variants — judges allocation
            // rows at the target's pointer width, as the per-body pass does, so "the
            // first Failed VC" and its discharge are the rows that pass will see.
            // Trust (T3 L4, C07p; design D-VC-6): each harvest writes its rows into a VC
            // context of its own, dropped when the harvest ends.
            with_scoped_rows(&mut r1_parity, |rows| {
                trust_vcgen::with_target_pointer_bits(trust_target_pointer_bits(tcx), || {
                    try_harvest_flip(tcx, local, &info, &ay, rows)
                })
            })
        };
        if let Some((def_path, flip)) = harvested {
            debug!(
                "R1: stored flip key='{}' kind='{}' loc={:?}",
                def_path, flip.kind_desc, flip.location
            );
            if trace {
                eprintln!(
                    "TRUST_R1_TRACE: stored flip key='{}' kind='{}' loc={}:{} file={:?}",
                    def_path,
                    flip.kind_desc,
                    flip.location.line_start,
                    flip.location.col_start,
                    std::path::Path::new(&flip.location.file).file_name()
                );
            }
            map.entry(def_path).or_default().push(flip);
        }
    }
    debug!(
        "Trust R1: harvested {} caller-covered flip(s)",
        map.values().map(Vec::len).sum::<usize>()
    );
    // Trust (T3 L4, C07p): the harvests' row-oracle count, once per pre-pass that ran.
    elide_audit::record_crate_parity(
        tcx,
        "crate:r1",
        &r1_parity,
        &[trust_types::vc_context::Oracle::Row],
    );

    // Carry the scan's OWN reasons (with the offending items' spans) to the
    // crate-level reporting seam. A poisoned scan disables the R1
    // verdict-improvement lane for every function in the crate; without this, an
    // affected function emitted an ordinary "Level 0 safety verification
    // incomplete" with nothing anywhere naming the cause.
    let scan_gaps = info.incomplete_notes.clone();
    with_crate_verification_state(tcx.sess, |state| {
        state.r1_attributions = map;
        state.r1_scan_gaps = scan_gaps;
        state.r1_initialized = true;
    });
}

/// Trust (scope-truncation fix): eagerly demand `optimized_mir` — and with it the
/// `TrustVerify` pass, its last pass — for EVERY local function/closure body, making
/// the verification universe the WHOLE crate independent of diagnostic ordering.
///
/// Why: the universe used to be demand-driven — a deterministic analysis-phase wave
/// (the R1/backing-certificate init hooks above demand a body subset), then everything
/// else via the codegen collector and the callee-BFS
/// (`native_trust_ir_verifiable_function_closure`). When an EARLY-wave function emitted
/// a verification ERROR, the session died before the collector wave — formerly at a
/// mid-pass `abort_if_errors` (since removed), and otherwise at rustc's pre-codegen
/// `has_errors_or_delayed_bugs` gate in `rustc_interface::passes::start_codegen` — so
/// the crate's remaining functions were silently NEVER VERIFIED and the report
/// presented a smaller, passing-looking scope. Which functions got verified was pure
/// error-ORDERING luck. This walk is called from `rustc_interface::passes::analysis`
/// right after the pre-steal trust init hooks (which must read
/// `mir_drops_elaborated_and_const_checked` BEFORE `optimized_mir` steals it) and
/// BEFORE any fatal error gate, establishing the invariant: one function's
/// verification error can never prevent another function from being verified.
///
/// SOUNDNESS: a strict WIDENING of verification coverage under an already-failing
/// build. Every emitted error still fails the build (`ErrorGuaranteed` at the driver
/// checkpoint), no refutation is masked, and error classification is untouched — the
/// only change is that MORE functions are verified (and reported) than before.
/// Fail-closed is preserved and strengthened.
fn whole_crate_coverage_shortfall_is_fatal(
    policy: &TrustVerifyPolicy,
    eligible: usize,
    processed: usize,
) -> bool {
    // Direct comparison avoids the old anomaly heuristic's multiplication and
    // therefore cannot overflow at large body counts. Memory-safe retains the
    // strict policy object, so it is fatal here; only survey is nonfatal.
    processed != eligible && policy.fail_closed()
}

/// Whether the crate-level R1 scan-gap warning fires: the scan must be poisoned
/// AND some function must actually have kept a non-proved Level-0 verdict this
/// compile. The second conjunct is the UX contract pinned by
/// `tests::r1_scan_gap_warning_requires_a_withheld_verdict`: a raw `dcx` warning
/// cannot be suppressed by `-Awarnings`/`#[allow]`, so ordinary fully-proved
/// source containing a `global_asm!` item must compile without it. The positive
/// half (poison + withheld verdict ⇒ warn, naming the cause) is pinned
/// end-to-end by tests/ui/trust/r1/reject_global_asm_names_reason.rs.
fn r1_scan_gap_warning_applies(scan_poisoned: bool, l0_verdict_withheld: bool) -> bool {
    scan_poisoned && l0_verdict_withheld
}

// Trust (TG14): retain canonical cycle diagnostics for prefix and recovered suffix.
fn trust_report_island_cycles(
    tcx: TyCtxt<'_>,
    islands: &[(rustc_span::Span, String)],
    cycles: &[trust_certify::clean_island_batch::CleanIslandCycle],
) {
    for cycle in cycles {
        let Some(primary) = cycle.sites.first() else { continue };
        let site_span = |site: &trust_certify::clean_island_batch::CleanIslandCycleSite| {
            let Some((content_span, text)) = islands.get(site.island) else {
                tcx.dcx().fatal("Clean cycle refers to an unavailable source unit");
            };
            let start = site.start.min(text.len());
            let end = site.end.max(start).min(text.len());
            let lo = content_span.lo() + rustc_span::BytePos(start as u32);
            let mut hi = content_span.lo() + rustc_span::BytePos(end as u32);
            if hi == lo && lo < content_span.hi() {
                hi = lo + rustc_span::BytePos(1);
            }
            content_span.with_lo(lo).with_hi(hi)
        };
        let mut diagnostic = tcx.dcx().struct_span_err(
            site_span(primary),
            format!("Clean declarations form a dependency cycle: {}", cycle.render()),
        );
        for site in cycle.sites.iter().skip(1) {
            diagnostic = diagnostic
                .with_span_label(site_span(site), format!("`{}` closes the cycle", site.name));
        }
        diagnostic
            .with_note(
                "declaration headers are collected across every Clean island before \
                         any body is registered, so this cycle is found structurally rather \
                         than by the kernel diverging; nothing from these islands was \
                         registered",
            )
            // Clean's own refusal, verbatim. It names the ways forward
            // in order of preference and says what each one costs;
            // paraphrasing it here would let the two repos drift about
            // what the fix actually is.
            .with_note(cycle.message.clone())
            .emit();
    }
}

/// Check the crate's deferred island suffix — every island from the first one
/// that names `trust_import_` on — in authored order against the session's
/// stateful environment, once the program admissions it needs are minted.
///
/// One body for both lanes (the verification walk and TG3's kernel-only lane
/// under `-Ztrust-verify=off`), so the two cannot report a deferred island
/// differently. A rejection is a hard compiler error, exactly as it is in the
/// pre-walk phase; deferral never authorizes unchecked declarations.
fn trust_check_deferred_island_suffix(
    tcx: TyCtxt<'_>,
    clean_session: &mut trust_certify::clean_island::CleanIslandSession,
    deferred_islands: &[(rustc_span::Span, String)],
    census_phase: crate::trust_lean_census::CheckPhase,
    unchecked_bindings_note: &str,
) {
    // Trust (LEAN-CENSUS-EMPTY-SUFFIX-1): a crate with no deferred island has
    // no suffix check, with or without the census. `check_import_islands(&[])`
    // is the empty batch, but the census path recorded it as a post-admission
    // check of zero islands, which the observer refuses, so `-Ztrust-lean-census`
    // failed on every crate whose islands name no `trust_import_*` (the
    // per-island loop this batch replaced made no call there). This also covers
    // PERF-MIR-ISLAND-KERNEL-TARGETS-2's census-off fast path.
    if deferred_islands.is_empty() {
        return;
    }
    // Trust (TG14): keep the complete surviving suffix header-first. A
    // refused unit is excluded transactionally, never a source-order barrier.
    // The census records this call as ONE import batch, refused units named
    // (LEAN-CENSUS-IMPORT-BATCH-1).
    let texts: Vec<&str> = deferred_islands.iter().map(|(_, text)| text.as_str()).collect();
    let batch = if tcx.sess.opts.unstable_opts.trust_lean_census.is_some() {
        let (batch, roster) = clean_session.check_import_islands_with_census(&texts);
        let sources: Vec<_> =
            deferred_islands.iter().map(|(span, text)| (*span, text.as_str())).collect();
        crate::trust_lean_census::checked(
            tcx.sess,
            &sources,
            census_phase,
            batch.is_rejected(),
            &roster.report,
        );
        batch
    } else {
        clean_session.check_import_islands(&texts)
    };
    trust_report_island_cycles(tcx, deferred_islands, &batch.cycles);
    for ((content_span, text), outcome) in deferred_islands.iter().zip(batch.outcomes) {
        if outcome.is_rejected() {
            for err in &outcome.errors {
                let start = err.start.min(text.len());
                let end = err.end.max(start).min(text.len());
                let lo = content_span.lo() + rustc_span::BytePos(start as u32);
                let mut hi = content_span.lo() + rustc_span::BytePos(end as u32);
                if hi == lo && lo < content_span.hi() {
                    hi = lo + rustc_span::BytePos(1);
                }
                tcx.dcx()
                    .struct_span_err(content_span.with_lo(lo).with_hi(hi), err.message.clone())
                    .with_note(
                        "this island names the kernel-import namespace, so it was checked after \
                         program admissions were minted (two-language design item 10)",
                    )
                    .emit();
            }
        } else if !outcome.registered.is_empty() {
            tcx.dcx()
                .struct_span_note(
                    *content_span,
                    format!(
                        "Clean island kernel-checked after program admission: {} declaration(s) \
                         registered ({})",
                        outcome.registered.len(),
                        outcome.registered.join(", ")
                    ),
                )
                .emit();
        }
        // Trust: the deferred suffix discloses a stand-in `import` exactly as
        // the pre-walk batch does.
        trust_disclose_island_standin_imports(tcx, *content_span, text, &outcome);
        trust_report_island_model_checks(tcx, *content_span, text, &outcome);
        trust_report_unchecked_island_bindings(
            tcx,
            *content_span,
            text,
            &outcome,
            Some(unchecked_bindings_note),
        );
    }
}

/// The program bodies a crate's KERNEL obligations name, for TG3's kernel-only
/// lane (see [`trust_kernel_discharge_without_verification`]).
struct KernelObligationTargets {
    /// Every body to extract and offer to the E6 mint, in source order: the
    /// named bodies and, transitively, the local bodies they call (the facet
    /// composition reads callees, exactly as the verification walk's does).
    bodies: Vec<LocalDefId>,
    /// Each `trust_import_*` identifier a deferred island spells, where it is
    /// spelled, and the local functions whose imports it can name. A token
    /// naming no local function is left to the island check, which refuses
    /// the unknown constant.
    imports: Vec<(rustc_span::Span, String, Vec<LocalDefId>)>,
}

/// Every maximal identifier in `text` (Unicode alphanumerics and `_`), with its
/// byte offset. For Rust clause text; island text is read with Clean's lexer
/// (`island_kernel_import_identifiers`).
fn trust_identifier_tokens(text: &str) -> Vec<(usize, &str)> {
    let is_ident = |c: char| c.is_alphanumeric() || c == '_';
    let mut tokens = Vec::new();
    let mut start: Option<usize> = None;
    for (index, c) in text.char_indices() {
        match (is_ident(c), start) {
            (true, None) => start = Some(index),
            (false, Some(from)) => {
                tokens.push((from, &text[from..index]));
                start = None;
            }
            _ => {}
        }
    }
    if let Some(from) = start {
        tokens.push((from, &text[from..]));
    }
    tokens
}

/// Every identifier and every `a::b` path a clause spells: the keys a spec
/// call can be looked up under (`trust_spec_elab::spec_spellings`).
fn trust_clause_path_spellings(text: &str) -> FxHashSet<String> {
    let mut spellings = FxHashSet::default();
    let tokens = trust_identifier_tokens(text);
    let mut index = 0;
    while index < tokens.len() {
        let (from, first) = tokens[index];
        spellings.insert(first.to_string());
        let mut end = from + first.len();
        let mut next = index + 1;
        while next < tokens.len() && text[end..].starts_with("::") && tokens[next].0 == end + 2 {
            end = tokens[next].0 + tokens[next].1.len();
            spellings.insert(text[from..end].to_string());
            next += 1;
        }
        index += 1;
    }
    spellings
}

/// TG3: select the bodies the crate's kernel obligations name — the functions
/// a deferred island's `trust_import_*` identifiers import, every function
/// carrying a cited clause (its own body binds `result`), every function a
/// cited clause calls — then close the set over local callees.
///
/// Over-selection costs only an import attempt; under-selection would leave a
/// kernel obligation without the body it needs, which then fails closed (the
/// island refuses the unknown constant, the citation refuses the unadmitted
/// call), never passes.
fn trust_kernel_obligation_targets(
    tcx: TyCtxt<'_>,
    deferred_islands: &[(rustc_span::Span, String)],
) -> KernelObligationTargets {
    // The universe the verification walk reads, restricted to nameable
    // functions: a closure has no spelling a clause or an import can use.
    // Built lazily so crates with no deferred-island kernel imports and no
    // cited contracts do not force `mir_keys(())` or format `safe_def_path_str`
    // for every function in the crate.
    let universe: std::cell::OnceCell<Vec<(LocalDefId, String)>> = std::cell::OnceCell::new();
    let get_universe = || {
        universe.get_or_init(|| {
            let mut entries: Vec<(LocalDefId, String)> = tcx
                .mir_keys(())
                .iter()
                .copied()
                .filter(|&local| {
                    matches!(tcx.def_kind(local.to_def_id()), DefKind::Fn | DefKind::AssocFn)
                        && trust_coverage_eligible_body(tcx, local)
                })
                .map(|local| (local, trust_mir_extract::safe_def_path_str(tcx, local.to_def_id())))
                .collect();
            entries.sort_by_key(|&(local, _)| {
                let span = tcx.def_span(local);
                (span.lo(), span.hi())
            });
            entries
        })
    };
    let mut selected: FxHashSet<LocalDefId> = FxHashSet::default();

    let mut imports = Vec::new();
    for (content_span, text) in deferred_islands {
        // Clean's lexer reads the identifiers, so a comment or a string that
        // mentions the namespace selects nothing.
        for (start, end, token) in
            trust_certify::clean_island::island_kernel_import_identifiers(text)
        {
            let named: Vec<LocalDefId> = get_universe()
                .iter()
                .filter(|(_, path)| {
                    trust_certify::clean_island::island_identifier_names_kernel_import(&token, path)
                })
                .map(|&(local, _)| local)
                .collect();
            selected.extend(named.iter().copied());
            let span = content_span
                .with_lo(content_span.lo() + rustc_span::BytePos(start as u32))
                .with_hi(content_span.lo() + rustc_span::BytePos(end as u32));
            if !named.is_empty() {
                imports.push((span, token, named));
            }
        }
    }

    for local in tcx
        .hir_body_owners()
        .filter(|&local| TrustContractBundle::def_may_have_contracts(tcx, local))
    {
        let bundle = tcx.trust_contracts(local.to_def_id());
        let mut cited = false;
        for contract in bundle.iter_all() {
            if contract.citation.is_none() {
                continue;
            }
            cited = true;
            // An unrecoverable clause is the citation sweep's hard error; it
            // names no callee here.
            let Ok(clause_text) = cited_ensures_clause_text(tcx, contract) else { continue };
            let spelled = trust_clause_path_spellings(&clause_text);
            for (callee, path) in get_universe() {
                if spelled.contains(path)
                    || trust_spec_elab::spec_spellings(path).iter().any(|s| spelled.contains(s))
                {
                    selected.insert(*callee);
                }
            }
        }
        if cited && get_universe().iter().any(|&(owner, _)| owner == local) {
            selected.insert(local);
        }
    }

    if selected.is_empty() {
        return KernelObligationTargets { bodies: Vec::new(), imports };
    }

    let universe = get_universe();
    let universe_members: FxHashSet<LocalDefId> =
        universe.iter().map(|&(local, _)| local).collect();

    // Close over local callees, as the facet composition reads them.
    // Seeded in source order (never by iterating the hash set), so the walk and
    // every diagnostic it leads to are deterministic.
    let mut worklist: Vec<LocalDefId> =
        universe.iter().map(|&(local, _)| local).filter(|local| selected.contains(local)).collect();
    while let Some(local) = worklist.pop() {
        let body = tcx.optimized_mir(local.to_def_id());
        for block in body.basic_blocks.iter() {
            let TerminatorKind::Call { func, .. } = &block.terminator().kind else { continue };
            let Some((callee, _)) = func.const_fn_def() else { continue };
            let Some(callee) = callee.as_local() else { continue };
            if universe_members.contains(&callee) && selected.insert(callee) {
                worklist.push(callee);
            }
        }
    }

    let bodies =
        universe.iter().map(|&(local, _)| local).filter(|local| selected.contains(local)).collect();
    KernelObligationTargets { bodies, imports }
}

/// TG3: the E6 extraction of one body, as the verification walk's facet intake
/// (`collect_verification_artifacts_inner_with_policy`, before
/// `record_fn_facets`) extracts it: the compiler contract bundle converted the
/// same way, the same extractor, read from the same query — `optimized_mir`,
/// the body codegen receives.
///
/// What it does NOT do: bind loop clauses (`bind_compiler_loop_contract_bundle`).
/// The E6 readers refuse every loop, so a body with a loop is unreadable here
/// and in the walk alike, and the refusal names the loop either way.
///
/// Which optimization passes ran is part of what the body says
/// (KNOWN_HAZARDS: "WHICH OPTIMIZATION PASSES RAN"). This lane reads the body
/// this compilation emits code for, and since TG16 (KERNEL-MIR-PARITY-1) that
/// body ran the level a verifying session runs, 1, at every `-Copt-level`: a
/// crate with a kernel obligation does not get the vanilla `-O` lane's level 2
/// (`PassCtx::for_body`, `trust_session_mir_opt_level`). An explicit
/// `-Zmir-opt-level`, `-Zinline-mir` or `#[optimize]` still decides.
fn trust_kernel_extract_function(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
) -> Result<trust_types::VerifiableFunction, String> {
    let def_id = local.to_def_id();
    let body = tcx.optimized_mir(def_id);
    let empty_contracts = TrustContractBundle::empty(def_id);
    let rustc_contracts = trust_contracts_if_any(tcx, def_id).unwrap_or(&empty_contracts);
    let compiler_contracts = trust_mir_extract::convert_trust_contract_bundle(tcx, rustc_contracts)
        .map_err(|reason| format!("its contract bundle cannot be converted: {reason}"))?;
    Ok(trust_mir_extract::extract_function_with_contract_bundle(
        tcx,
        body,
        Some(&compiler_contracts),
    ))
}

/// Trust (TG3, COMPILE-TIME-FACTS-1, owner ruling 2026-11-05: "checks are
/// supposed to be check at compile time!"): discharge the crate's KERNEL
/// obligations with verification off.
///
/// A kernel obligation is one the Clean kernel alone decides: a deferred island
/// (it names a `trust_import_*` constant, the equality between a Rust body and
/// its imported term) and an `ensures … by <theorem>` citation. Before TG3 the
/// first was a hard error under `-Ztrust-verify=off` ("populated only by an
/// enabled verification walk") and the second, when its clause mentions
/// `result`, only a note saying it was NOT checked. Now:
///
/// 1. E6-admit exactly the bodies those obligations name
///    ([`trust_kernel_obligation_targets`]): extract each one
///    ([`trust_kernel_extract_function`]), record its facets, and mint the
///    admissions from the composed table ([`trust_mint_program_admissions`]),
///    the same calls the walk's facet intake and post-walk mint make;
/// 2. refuse, naming the shape, every `trust_import_*` identifier whose body
///    could not be imported ([`trust_refuse_unreadable_kernel_imports`]);
/// 3. check the deferred islands ([`trust_check_deferred_island_suffix`]);
/// 4. run the citation sweep ([`trust_check_citations`]) with those
///    admissions bound, so a cited clause over `result` is judged against the
///    function's imported definition and a mismatch is the hard error it is
///    with verification on.
///
/// No VC is generated and no solver runs: an `ensures` without `by` is not
/// read here (TG13 owns SMT obligations in every build), and nothing here
/// installs proof authority for a verified lane — this compilation makes no
/// verified-lane claim and still says so once per crate.
///
/// SEAM FOR TG6 (the content-keyed fact store): every input a kernel fact
/// depends on is in hand at step 1 — the extracted bodies whose admissions
/// (and so whose E6 terms) the islands and citations read — and steps 3 and 4
/// are the only kernel work. A fact store keys on those admissions and the
/// session's island environment and replaces steps 3–4 on a hit; nothing in
/// this function reads anything else.
fn trust_kernel_discharge_without_verification(
    tcx: TyCtxt<'_>,
    clean_session: &mut trust_certify::clean_island::CleanIslandSession,
    deferred_islands: &[(rustc_span::Span, String)],
) {
    // No body verification runs in this lane: extraction's "not assumed for body
    // verification" warning would describe one that does not happen.
    trust_mir_extract::declare_no_body_verification(tcx);
    let targets = trust_kernel_obligation_targets(tcx, deferred_islands);
    let mut unreadable: FxHashMap<LocalDefId, String> = FxHashMap::default();
    for &local in &targets.bodies {
        match trust_kernel_extract_function(tcx, local) {
            Ok(func) => record_fn_facets(tcx.sess, &func),
            Err(reason) => {
                unreadable.insert(local, reason);
            }
        }
    }
    trust_mint_program_admissions(tcx, clean_session);
    // A tainted session mints nothing (an earlier island was rejected, and that
    // rejection is already an error). Blaming each import's body would name the
    // wrong cause; the island check below still refuses the unknown constants.
    if !clean_session.is_tainted() {
        trust_refuse_unreadable_kernel_imports(tcx, &targets, &unreadable);
    }
    // Trust (LEAN-CENSUS-IMPORT-BATCH-1): the mint above changed the session
    // environment exactly as the walk's post-walk mint does; record the same
    // boundary so the suffix batch's identity delta is not read as continuous.
    crate::trust_lean_census::program_admissions_boundary(tcx.sess);
    trust_check_deferred_island_suffix(
        tcx,
        clean_session,
        deferred_islands,
        crate::trust_lean_census::CheckPhase::VerificationDisabled,
        "this island is checked only after the bodies it imports are admitted (it, or an \
         island before it, names `trust_import_`), which is after the thread census ran",
    );
    // The same post-suffix bookkeeping the walk's lane does: the session mirror
    // for later readers, and identity rows for Clean-origin defs the suffix
    // registered.
    stash_session_island_env(tcx.sess, clean_session);
    trust_record_clean_origin_identity_rows(tcx, clean_session);
    trust_check_citations(tcx, clean_session);
}

/// TG3 step 2: a deferred island that imports a body the E6 lane cannot read
/// is a hard error naming the gate and the construct that refused it — never
/// a skipped obligation. The island check that follows refuses the unknown
/// constant as well; this error says why it is unknown.
fn trust_refuse_unreadable_kernel_imports(
    tcx: TyCtxt<'_>,
    targets: &KernelObligationTargets,
    unreadable: &FxHashMap<LocalDefId, String>,
) {
    if targets.imports.is_empty() {
        return;
    }
    let facets =
        tcx.sess.with_trust_compiler_state::<SessionFnFacets, _>(|state| state.composed_table());
    let mut reported: FxHashSet<String> = FxHashSet::default();
    for (span, token, named) in &targets.imports {
        if !facets.admission_paths_for_kernel_const(token).is_empty()
            || !reported.insert(token.clone())
        {
            continue;
        }
        let mut diag = tcx.dcx().struct_span_err(
            *span,
            format!(
                "`{token}` names a Rust function body that cannot be imported into the Clean \
                 kernel"
            ),
        );
        for &local in named {
            let def_path = trust_mir_extract::safe_def_path_str(tcx, local.to_def_id());
            let why = match unreadable.get(&local) {
                Some(reason) => reason.clone(),
                None => trust_e6_self_admission_shortfall(
                    tcx,
                    local,
                    &def_path,
                    &trust_spec_elab::self_fn_spelling(&def_path),
                    &facets,
                ),
            };
            diag.span_note(tcx.def_span(local), format!("`{def_path}`: {why}"));
        }
        diag.note(format!(
            "a kernel import is checked in every build (COMPILE-TIME-FACTS-1); the importable \
             body shapes are {}",
            trust_certify::clean_island::E6_IMPORTABLE_SHAPES
        ));
        diag.emit();
    }
}

/// Check the crate's islands (the pre-walk batch; the deferred suffix is
/// returned, not checked) and prepare the session state both the verification
/// walk and the kernel-only lane read: the deferred-suffix flag, the stashed
/// environment, and the Clean-origin identity rows.
fn trust_open_island_session(
    tcx: TyCtxt<'_>,
) -> (trust_certify::clean_island::CleanIslandSession, Vec<(rustc_span::Span, String)>) {
    let (clean_session, deferred_islands) = trust_check_clean_islands(tcx);
    // Trust (item 10 phase 2): tell the in-walk citation lane, BEFORE the body
    // walk starts, whether this crate has a deferred island suffix at all. Only
    // then may an unregistered theorem name be read as "not checked yet" instead
    // of "absent" — see `SessionPendingImportCitations`.
    let has_deferred_islands = !deferred_islands.is_empty();
    tcx.sess.with_trust_compiler_state::<SessionPendingImportCitations, _>(|state| {
        state.crate_has_deferred_islands = has_deferred_islands;
    });
    // Trust: E9 §5d — stash a clone of the island-checked env for the in-walk
    // ensures-citation discharge. `environment()` is `None` when the session is
    // tainted, so a partially-registered island crate can never mint discharge
    // evidence (same fail-closed policy as every other island consumer).
    stash_session_island_env(tcx.sess, &clean_session);
    // Trust (joint cited theorem, 2026-09-15): give every Clean-origin def a
    // compiler-facing IDENTITY row (Rust def-path -> the audited island
    // admission) BEFORE the body walk, so a Rust body forwarding to it can be
    // E6-admitted and its cited `ensures` discharged against the island term.
    //
    // Trust (2026-09-18): takes the SESSION, which holds both halves — the
    // checked environment and the stand-in substitutions its islands' imports
    // were served by. The `environment()` guard moved inside, unchanged in
    // effect: a tainted session still records no identity row.
    trust_record_clean_origin_identity_rows(tcx, &clean_session);
    (clean_session, deferred_islands)
}

/// Trust (TG3, COMPILE-TIME-FACTS-1): the kernel obligations of a crate that
/// rustdoc documents. rustdoc runs no `analysis` and so never reached
/// `trust_ensure_whole_crate_verification`: the resolver seam checked the
/// islands it can see, and every island it cannot — the deferred
/// `trust_import_*` suffix and every island a macro introduced — went
/// unchecked with no diagnostic (reported by aterm's PF1 worker, 2026-11-05:
/// a false theorem built under `targo --unverified doc`). It now gets the same
/// island check and kernel-only lane an ordinary compilation with
/// verification off gets. No VC is generated and no solver runs.
///
/// Scope: a crate that carries a kernel obligation
/// ([`trust_crate_has_kernel_obligations`]: a Clean island, or a clause that
/// cites a theorem), both read from HIR. An island-free crate whose `by` clause
/// cites a theorem, a dependency's included (which every compilation refuses,
/// `clean_extern_proof`), gets the check its compilation gets: TG3's residual,
/// closed by `0423bda52a0`; TG16 made the gate the query `PassCtx` reads too. A
/// crate with neither keeps rustdoc's upstream behavior: no contract query
/// runs, so documenting std and other contract-heavy crates costs nothing new.
pub fn trust_check_kernel_obligations_for_rustdoc(tcx: TyCtxt<'_>) {
    if !tcx.trust_crate_has_kernel_obligations(()) {
        return;
    }
    let (mut clean_session, deferred_islands) = trust_open_island_session(tcx);
    trust_kernel_discharge_without_verification(tcx, &mut clean_session, &deferred_islands);
}

/// Trust (TG16): the `trust_crate_has_kernel_obligations` provider — a Clean
/// island item anywhere in the crate, or a requires/ensures/decreases or loop
/// clause anywhere in it that cites a theorem. It over-approximates what the
/// kernel-only lane imports ([`trust_kernel_obligation_targets`] narrows that
/// set from MIR): both readers only need "is there anything at all".
///
/// HIR only, never `trust_contracts`, typeck or MIR: `PassCtx::for_body` asks
/// this for every body it builds, CTFE bodies included, and a CTFE body is
/// built inside some function's typeck.
pub(crate) fn trust_crate_has_kernel_obligations(tcx: TyCtxt<'_>, (): ()) -> bool {
    // Every island is `DefKind::GlobalAsm` (`DefCollector::visit_item`); ask that
    // first so no other item is lowered (PERF-MIR-ISLAND-KERNEL-TARGETS-2).
    let items = tcx.hir_crate_items(());
    if items.free_items().any(|item_id| {
        tcx.def_kind(item_id.owner_id) == DefKind::GlobalAsm
            && matches!(tcx.hir_item(item_id).kind, rustc_hir::ItemKind::CleanIsland { .. })
    }) {
        return true;
    }
    tcx.hir_body_owners().any(|owner| {
        tcx.hir_maybe_body_owned_by(owner).and_then(|body| body.contract).is_some_and(|contract| {
            contract
                .requires
                .iter()
                .chain(contract.ensures)
                .chain(contract.decreases)
                .any(|clause| clause.citation.is_some())
                || contract.loop_clauses.iter().any(|clause| clause.citation.is_some())
        })
    })
}

#[allow(rustc::potential_query_instability)]
pub fn trust_ensure_whole_crate_verification(tcx: TyCtxt<'_>) {
    // Parser islands and authored citations are language-integrity checks, not
    // verifier-router work. Validate them even in Rust-compatibility mode:
    // `-Ztrust-verify=off` must never turn ill-typed Clean, sorry/trusted debt,
    // parser recovery, or a broken citation into accepted source.
    //
    // Trust (TG3, COMPILE-TIME-FACTS-1, 2026-11-05): kernel obligations — a
    // deferred island that names `trust_import_*` and an `ensures … by`
    // citation, `result`-dependent ones included — are discharged in this lane
    // too: `trust_kernel_discharge_without_verification` imports exactly the
    // bodies they name. The earlier exception (a `result` clause noted as NOT
    // checked) is gone; with verification ON nothing about citation checking
    // changed.
    //
    // Trust: E6 ordering — islands + monitor certification run BEFORE the
    // per-body walk (`inject_certified_test_monitors` consumes the monitor
    // records from inside `run_pass`); the CITATION sweep runs AFTER it, so
    // the session facet table is populated when a cited clause mentions a
    // program function. Diagnostics-only consequence: citation errors now
    // follow per-body verification output; no verdict changes either way
    // (facets refine the fail-closed message, never admit a call).
    let (mut clean_session, deferred_islands) = trust_open_island_session(tcx);
    if !verification_enabled(tcx.sess) {
        // Trust (loud-when-off): silent-vanilla must be unrepresentable. When
        // the explicit `-Ztrust-verify=off` argv spelling compiled a crate the
        // batteries-on toolchain COULD have verified, say so once per crate,
        // in-band — a note, deliberately not a lint and not a warning, so it
        // can neither be `allow`ed away nor promoted to an error by
        // `-Dwarnings` (the deferred-verification lane note in
        // `rustc_interface::passes` is the mechanism precedent). Three
        // deauthorizations are announced elsewhere and stay quiet here:
        // deauthorized-by-design frontends (embedded/doctest) never set the
        // explicitness bit; a Targo-resolved scope always carries a
        // non-`unscoped` reporting role (its session inventory records the
        // exclusion); and harnesses that stamp the flag as recorded policy
        // (compiletest isolation, bootstrap's non-self-proving build — which
        // is ALSO the only production setter of the inherited
        // `TRUST_NO_VERIFY=1` transport) set the diagnostic-only
        // `TRUST_VANILLA_ANNOUNCED` env marker. The env transport itself DOES
        // set the bit since 2026-09-14, so a bare-shell `TRUST_NO_VERIFY=1`
        // with no announcing parent lands here and announces
        // (`tests/ui/trust/vanilla_off_note.rs`, revision `env`).
        if tcx.sess.opts.trust_verify_explicit_off
            && tcx.sess.trust_crate_role() == rustc_session::TrustCrateRole::Unscoped
            && !env_flag_enabled("TRUST_VANILLA_ANNOUNCED")
        {
            tcx.dcx().note("compiled WITHOUT Trust verification — 0 obligations checked");
        }
        // Trust (TG3, COMPILE-TIME-FACTS-1, owner ruling 2026-11-05): kernel
        // obligations are compile-time obligations in EVERY build. With
        // verification off there is no body walk, so the kernel-only lane
        // imports exactly the bodies those obligations name, then checks the
        // deferred islands and the citations against them. No VC walk and no
        // solver: an `ensures` without `by` is not read here.
        trust_kernel_discharge_without_verification(tcx, &mut clean_session, &deferred_islands);
        return;
    }
    // Reporting-role metadata cannot truncate this inventory: every enabled
    // local crate receives the same eager, assertion-grade coverage walk.
    let policy = TrustVerifyPolicy::from_session(tcx.sess);
    let mut eligible_bodies: FxHashSet<LocalDefId> = FxHashSet::default();
    for &local in tcx.mir_keys(()) {
        if !trust_coverage_eligible_body(tcx, local) {
            continue;
        }
        eligible_bodies.insert(local);
    }
    // Trust (I5 cross-authority call modeling): register MODELED Clean-origin
    // defs in the panic-free callee registry BEFORE the demand-order walk. The
    // walk below only covers ELIGIBLE bodies, and a Clean-origin def is
    // outside the VC pipeline's coverage universe by construction (see
    // `trust_coverage_eligible_body`) — no walk order can ever register one.
    // The claim itself needs no VC run: panic-freedom holds BY CONSTRUCTION of
    // the emitter, on the same plan of record the kernel gate checked (the
    // gate fatally refuses compilation if the emitted body disagrees with that
    // plan; see `clean_origin_plan_of_record` for the chain), shape by shape:
    //   * `Projection`: `_0 = move _{i+1}; return` — one statement, no calls,
    //     no asserts, no unwind edge.
    //   * `WrappingBinOp`: `bb0: _0 = Call(u{w}::wrapping_{op}, [l, r]) ->
    //     bb1: Return` — this body CONTAINS a call, so the Projection
    //     rationale extends honestly rather than silently: the ONE callee is
    //     core's inherent `u{w}::wrapping_{add,sub,mul}`, selected by the
    //     EMITTER itself (never by user code) through
    //     `clean_origin_mir::resolve_core_wrapping_method`, which refuses any
    //     resolution failing
    //     `trust_mir_extract::tcx_is_authenticated_core_integer_wrapping_method`
    //     — the same marker authentication the extractor's own wrapping lane
    //     trusts. Those primitives are TOTAL (defined on every input, no
    //     panic path; wrapping is their semantics, not an error), and the
    //     call's unwind edge is `UnwindAction::Unreachable`.
    // `register_proven_panic_free` is deliberately NOT used: its axiom-census
    // gate reads census absence as "unanswered" — the right fail-closed
    // default for verdicts produced by a bundle run that can spend
    // assumptions — but these bodies have no real HIR and no attribute
    // surface on which a user axiom could be spent (`Projection` and, since
    // 2026-09-28, `Select`, `ConstantUint` and the `Bool`-valued W6 shapes have no calls at all; `WrappingBinOp`'s one call is emitter-chosen, marker-
    // authenticated core code, not a user-nameable site), and their authority
    // is the kernel gate, not a census-taking verification.
    // Trust (W5 increment 3): charge every `RustCallChain` def's Rust callees BEFORE
    // the registration loop below, because that loop reads
    // `clean_origin_call_model_of_record`, which reads the set this pass publishes.
    // Charging after the walk — where the design of record anchors it — would publish
    // into a set both consumers have already read.
    trust_charge_clean_rust_callees(tcx);
    // Only modeled shapes register; every other shape (and any plan/env
    // refusal) keeps its callers fail-closed (`clean_origin_call_model_of_record`).
    for local in crate::clean_origin_mir::clean_origin_defs(tcx) {
        if clean_origin_call_model_of_record(tcx, local.to_def_id()).is_none() {
            continue;
        }
        let def_path = trust_mir_extract::safe_def_path_str(tcx, local.to_def_id());
        debug!("Trust (I5): registering modeled Clean-origin def `{def_path}` as panic-free");
        // Publish BOTH views of the one fact, from the one `DefId`, so the
        // identity registry can never hold less than the rendered one for a
        // function this site blesses. `None` (a generic emitter def) simply
        // records nothing — never a path-derived substitute.
        let identity = trust_mir_extract::item_identity(tcx, local.to_def_id());
        with_crate_verification_state(tcx.sess, |state| {
            state.panic_free_proven_funcs.insert(def_path.clone());
            if let Some(identity) = identity {
                state.panic_free_proven_identities.insert(identity);
            }
        });
    }
    // The panic-free callee registry is consumed while a caller's one-shot
    // verdict is built, so populate it in callee-first order. This is only a
    // permutation of the same eligible body set; cycles cannot bootstrap a proof
    // because at least one member is still visited before a sibling it calls.
    for local in trust_callee_first_demand_order(tcx, &eligible_bodies) {
        tcx.ensure_done().optimized_mir(local.to_def_id());
    }
    // Trust (r15): the synthetic by-move coroutine bodies are eligible (see
    // `trust_coverage_eligible_body`) but are no node of the local call graph
    // (`trust_mir_call_graph_node_eligible`), so the demand order leaves them out;
    // demand them HERE, inside the walk, so their rows precede the coverage row and
    // the crate summary instead of arriving during codegen. Nothing calls one
    // directly (only its parent closure's `AsyncFnOnce` shim), so callee-first order
    // is unaffected.
    for local in tcx.mir_keys(()) {
        if matches!(tcx.def_kind(local.to_def_id()), DefKind::SyntheticCoroutineBody)
            && eligible_bodies.contains(local)
        {
            tcx.ensure_done().optimized_mir(local.to_def_id());
        }
    }
    // Trust (T3 L4, C06a): crate finalization's elision-audit scope, from the end of the
    // body walk to the crate accounting.
    let audit_finalize_scope = elide_audit::CrateScope::enter(tcx, "crate:finalize");
    // Trust rung 1 (§(a)+(b)): every implementation of a `#[trust::panic_free]`
    // trait method carries the inherited obligation to PROVE panic-freedom, and
    // a failure is reported at the implementation that owns the body. Runs here,
    // after the walk, so every `trust_proof_results` it reads is already
    // computed and no impl can be discharged against a stale or missing verdict.
    trait_panic_free::discharge_trait_panic_free_contracts(tcx);
    // Trust (2026-10-03, the minting-site seam): refuse a `requires`-carrying function
    // turned into a value in a body no verification pass reads — a promoted, a `const`,
    // `static`, associated, inline or anonymous constant's initializer, a compile-time
    // function — or in a local opaque type's hidden type or a `global_asm!` `sym` operand
    // (`uncharged_callable`; docs/DECISION_QUEUE.md, AT-REQ-2). HERE, at top level: after
    // the walk above (no `optimized_mir` is demanded, so the callee-first order is
    // untouched), with verification enabled on a front-end-clean crate only, and outside
    // every query the type system can reach — its `mir_for_ctfe`, `promoted_mir`,
    // `type_of` and `typeck` demands are E0391 anywhere inside one. An error on a
    // fail-closed policy, a warning under advisory; emit and continue.
    uncharged_callable::refuse_requires_carrying_values_minted_outside_verified_bodies(
        tcx,
        policy.fail_closed(),
    );
    // Trust §5 step 6 (skeleton): `#[trust::panic_free_drop]` placement
    // validation. Recognized-but-inert — acceptance warns that nothing is
    // enforced, misplacement is a hard error carrying the fix, and NOTHING is
    // charged; see `panic_free_drop`'s module doc for the implementation map.
    panic_free_drop::validate_panic_free_drop_declarations(tcx);
    // Trust (2026-09-29): a local `unsafe impl` of a foreign unsafe trait (a user
    // `Allocator` handed to a std container) is a safety promise the trait
    // owner's code relies on and no lane checks. Crate-level, after the walk, so
    // every function's own report comes first. See `unsafe_impl_promise`.
    unsafe_impl_promise::refuse_unverified_unsafe_impl_promises(tcx, &policy);
    // Trust (2026-09-30): the link-level twin — a local `#[no_mangle]` /
    // `#[export_name]` definition of a symbol a linked crate imports (`malloc`,
    // which std's `Global` calls through `libc`) replaces that crate's callee, and
    // no lane checks the replacement. See `symbol_interposition`.
    symbol_interposition::refuse_interposed_imports(tcx, &policy);
    // Trust (2026-10-01): the rest of that class — a `global_asm!` item or a
    // `#[link_section]` item puts bytes where the linker or the loader acts on
    // them (a `_malloc` defined in assembly, a constructor table) without any
    // Rust call, and no lane reads them. See `link_level_code`.
    link_level_code::refuse_link_level_code(tcx, &policy);
    // Trust (2026-10-02): the premises that let the default policy accept a std
    // growth or allocation panic unproved (the push-growth class, the vanilla
    // std-callee class, vcgen's allocation ceilings and bounded-source grants)
    // are calibrated against a 64-bit `isize::MAX`; on a narrower target the
    // panics they excuse are reachable. See `narrow_target`.
    narrow_target::refuse_narrow_target(tcx, &policy);
    // E6 kernel-import: the walk above populated the facet table + body
    // inventory, so mint admissions for recognized facet-certified functions into
    // the session env BEFORE the citation sweep reads it.
    trust_mint_program_admissions(tcx, &mut clean_session);
    // Trust (TG14): name the refused E6 shape in the verified lane too,
    // before the island elaborator reports the unavailable import constant.
    if !clean_session.is_tainted() && !deferred_islands.is_empty() {
        let targets = trust_kernel_obligation_targets(tcx, &deferred_islands);
        trust_refuse_unreadable_kernel_imports(tcx, &targets, &FxHashMap::default());
    }
    crate::trust_lean_census::program_admissions_boundary(tcx.sess);
    // The required program constants now exist. Check each deferred island in
    // authored order against the same stateful Environment + FileContext. A
    // rejection is a hard compiler error, exactly as it is in the pre-walk
    // phase; deferral never authorizes unchecked declarations.
    trust_check_deferred_island_suffix(
        tcx,
        &mut clean_session,
        &deferred_islands,
        crate::trust_lean_census::CheckPhase::AfterProgramAdmissions,
        "this island is checked only after the body walk (it, or an island before it, names \
         `trust_import_`), which is after the thread census ran",
    );
    // Keep the session mirror exact for post-walk readers. The in-walk
    // discharge lanes have already run, so this does not pretend that a
    // deferred theorem discharged a clause.
    stash_session_island_env(tcx.sess, &clean_session);
    // Trust (joint cited theorem, 2026-09-15): re-record after the deferred
    // island suffix is kernel-checked, so defs registered late get identity
    // rows before the authoritative admissions mint below. The deferred suffix
    // may be where an `import` served by the prelude stand-in was spelled, so
    // this re-record is also what widens the crate's stand-in qualification;
    // both the stash and the row-side record take the union.
    trust_record_clean_origin_identity_rows(tcx, &clean_session);
    // Trust (item 10 phase 2): THIS is the authoritative stage — complete program
    // admissions, the deferred island suffix kernel-checked in authored order,
    // and the full facet table. Adjudicate every quarantined ensures-citation
    // here, where parity holds by construction rather than by care, and publish
    // each affected body's single withheld outcome.
    //
    // Placed BEFORE the coverage reconciliation below so every envelope this
    // emits is already in the transport set when the identity inventory is
    // stated; targo compares the two as exact SETS, so emission order is free but
    // emission-before-inventory is not.
    finalize_pending_import_citations(tcx, &clean_session);
    trust_check_citations(tcx, &clean_session);
    // W3: now that program admissions and deferred islands are complete,
    // expose every UNCITED function clause's canonical Clean denotation (or
    // explicit refusal) as zero-authority observational evidence. This walk is
    // intentionally outside all discharge paths and cannot change a verdict.
    emit_uncited_contract_clean_denotations(tcx);
    // Fail-closed backstop for the quarantine. A body recorded as pending has had
    // its SOLE envelope withheld, so a leftover record means one eligible body
    // published no evidence at all while still counting as processed — coverage
    // would reconcile and the transport set would be short. `finalize` above
    // drains the map and nothing can record into it after the walk, so this is
    // unreachable today; it exists so that a future lane which records later
    // fails loudly here instead of silently shrinking the evidence inventory.
    let leftover_pending = tcx
        .sess
        .with_trust_compiler_state::<SessionPendingImportCitations, _>(|state| state.bodies.len());
    if leftover_pending != 0 {
        tcx.dcx()
            .struct_err(format!(
                "Trust verification accounting incomplete: {leftover_pending} function \
                 body/bodies had a deferred ensures-citation quarantined but were never \
                 adjudicated; their verification evidence was withheld and never published"
            ))
            .with_note(
                "a quarantined body must be finalized by \
                 `finalize_pending_import_citations` in the same invocation that \
                 withheld it",
            )
            .emit();
    }
    if calculus_pending::retain_inventory(tcx, &eligible_bodies) {
        // The same inventory owner runs after every withheld sole outcome.
        // Dropping this audit scope records completed early-finalization work.
        return;
    }
    finish_verification_inventory(tcx, &policy, eligible_bodies, audit_finalize_scope);
}

/// Close the completed verification inventory after every body's sole outcome
/// has been published. Kept separate from computation so final-artifact proof
/// reporting can use this SAME coverage/summary owner without rerunning MIR.
/// This extraction alone changes no publication point or judgment.
fn finish_verification_inventory<'tcx>(
    tcx: TyCtxt<'tcx>,
    policy: &TrustVerifyPolicy,
    eligible_bodies: FxHashSet<LocalDefId>,
    audit_finalize_scope: elide_audit::CrateScope<'tcx>,
) {
    // Trust (assertion-grade coverage, roadmap §4.1): the walk above guarantees an
    // attributable outcome for every eligible body — the `TrustVerify` pass ran, or
    // `inner_optimized_mir` took a credited pre-pass early-out (tainted-by-errors /
    // lone-`unreachable`; see `trust_note_coverage_early_out`). `processed !=
    // eligible` therefore means the accounting is incomplete or malformed. An
    // under-count means functions were NEVER verified (mid-pass abort, query cycle,
    // ICE, incremental replay of a cached `optimized_mir`, a disabled pass — all
    // observed or possible truncation modes); an over-count means duplicate or
    // cross-unit evidence contaminated the inventory. A cached `optimized_mir`
    // cannot be "credited": its query value contains code, not this invocation's
    // proof diagnostics/transport, so replaying it would still leave the evidence
    // inventory incomplete. `finalize_untracked_session_state` supplies a fresh
    // query identity to prevent such replay; this assertion is the independent
    // fail-closed backstop if that invalidation ever regresses.
    let processed_bodies = tcx
        .sess
        .with_trust_compiler_state::<SessionReportState, _>(|state| state.processed_bodies.clone());
    // These hash traversals inherited the caller's scoped waiver before this
    // inventory owner was extracted. No traversal position chooses a body:
    // identity lists are sorted before publication, and the intersection's
    // cardinality is order-independent. Keep the waiver on these bindings so
    // subsequent query-bearing code remains subject to the module's deny.
    #[allow(rustc::potential_query_instability)]
    let mut missing_names: Vec<String> = eligible_bodies
        .iter()
        .filter(|local| !processed_bodies.contains(local))
        .map(|local| trust_mir_extract::safe_def_path_str(tcx, local.to_def_id()))
        .collect();
    missing_names.sort();
    // Trust (coverage identity reconciliation, protocol v7): the identity
    // inventory MUST use the same canonical crate-qualified spelling as the
    // per-function transport envelopes (`emit_transport_json`'s `func_path`,
    // via `trust_mir_extract::safe_def_path_str` -> `crate::path`) — targo's
    // `require_raw_coverage_authentication` compares the two as EXACT sets
    // (transport.rs `eligible coverage identities` / `processed coverage
    // identities`, fixture convention `demo::f`). The bare `def_path_str`
    // spelling (no local crate name) desynced the sets and failed the strict
    // coverage-authentication capability probe for every consumer.
    // `missing_names` above already uses the canonical form.
    #[allow(rustc::potential_query_instability)]
    let mut eligible_functions = eligible_bodies
        .iter()
        // Coverage identities must be byte-identical to the function envelope
        // identities emitted by `TrustVerify::run_pass`. `tcx.def_path_str`
        // omits the local crate prefix for root items (`main`), while
        // `safe_def_path_str` deliberately emits the semantic crate-qualified
        // spelling (`crate_name::main`). Mixing the two made current strict
        // Targo reject the compiler's own otherwise-complete inventory.
        .map(|local| trust_mir_extract::safe_def_path_str(tcx, local.to_def_id()))
        .collect::<Vec<_>>();
    eligible_functions.sort();
    #[allow(rustc::potential_query_instability)]
    let mut processed_functions = processed_bodies
        .intersection(&eligible_bodies)
        .map(|local| trust_mir_extract::safe_def_path_str(tcx, local.to_def_id()))
        .collect::<Vec<_>>();
    processed_functions.sort();
    let eligible = eligible_bodies.len();
    #[allow(rustc::potential_query_instability)]
    let processed = processed_bodies.intersection(&eligible_bodies).count();
    if !missing_names.is_empty() {
        let listed = missing_names.iter().take(8).cloned().collect::<Vec<_>>().join(", ");
        let omitted = missing_names.len().saturating_sub(8);
        let missing_detail =
            if omitted == 0 { listed } else { format!("{listed}, and {omitted} more") };
        let message = format!(
            "Trust verification coverage incomplete: the verification pass processed \
             {processed} of {eligible} eligible local function bodies; missing: \
             {missing_detail}; the verification report does NOT cover the whole crate"
        );
        if whole_crate_coverage_shortfall_is_fatal(&policy, eligible, processed) {
            let mut diag = tcx.dcx().struct_err(message);
            diag.note(
                "strict and memory-safe policy require an attributable result for every \
                 eligible in-scope body, independent of human/JSON output mode",
            );
            diag.note(
                "cached optimized MIR is not proof evidence: it cannot replay this \
                 invocation's verifier diagnostics or authenticated transport",
            );
            diag.emit();
        } else {
            tcx.dcx().warn(format!(
                "{message}; survey remains nonfatal but this coverage gap carries no proof credit"
            ));
        }
    }
    // Trust (skip taxonomy, round 2): VERIFY the inherited-skip deduplication
    // here, where the walk is complete and both sets exist. Placed with the
    // other crate-level verification reconciliations and BEFORE the transport
    // coverage row / crate summary below, so any error it recovers is part of
    // the same failing compilation those rows describe.
    trust_reconcile_inherited_skips(tcx);
    // Trust (R1 scan-poison reason channel): report, ONCE per crate, that the
    // whole-program caller scan could not account for this crate — and why.
    //
    // The scan feeds R1's verdict-IMPROVEMENT lane (an obligation unprovable in
    // isolation may be discharged when every caller establishes a precondition). A
    // gap poisons it for every function in the crate. Before this warning existed
    // NOTHING stated the cause anywhere: the pure core's gap classification is
    // dropped at its only other consumer (`try_harvest_flip` tests Total/not-Total
    // and discards the gap list), so an affected function reported an ordinary
    // "Level 0 safety verification incomplete" and the crate-wide reason was
    // silent. This warning IS the fix for that silence; it lives here because this
    // seam already owns crate-level verification reporting (the coverage-shortfall
    // report directly above — a dcx diagnostic, unlike trust_ir_flip's
    // `note_fallback`, which is only a `tracing::warn!` log line and is NOT a
    // precedent for user-facing warnings).
    //
    // GATED on `l0_verdict_withheld`: a raw `dcx` warning is unsuppressible
    // (`-Awarnings`/`#[allow]`/`--cap-lints` cannot touch a non-lint), and
    // `-Ztrust-verify` defaults to On — so firing on the mere PRESENCE of a
    // `global_asm!` item would warn on every compile of ordinary, fully-proved
    // source. The cause is worth stating exactly when its effect was felt: some
    // function actually kept a non-proved Level-0 verdict this compile. Those
    // compiles already emit per-function diagnostics, so this adds the missing
    // crate-level cause, never new noise on clean builds.
    //
    // A WARNING, never an error: the poison only ever KEEPS an honest verdict
    // (fail-closed), so it cannot make an unsound build pass, and it must not turn
    // a sound build into a failing one either. Empty under `-Ztrust-no-r1`.
    let (r1_scan_gaps, l0_verdict_withheld) = with_crate_verification_state(tcx.sess, |state| {
        (state.r1_scan_gaps.clone(), state.l0_verdict_withheld)
    });
    // Trust (TINV step 9): the type-invariant report, only under
    // `TRUST_TINV_NOTES=1`. A NOTE per type; it grants no authority (step 10.7: it
    // also lists each certified type's consumers).
    if env_flag_enabled("TRUST_TINV_NOTES") {
        report_type_invariants(tcx);
    }
    if r1_scan_gap_warning_applies(!r1_scan_gaps.is_empty(), l0_verdict_withheld) {
        let mut diag = tcx.dcx().struct_warn(
            "Trust R1 whole-program caller coverage is disabled for this crate: the crate-wide \
             call scan could not account for every item, so no function's caller set is \
             provably exhaustive",
        );
        for note in &r1_scan_gaps {
            match note.span {
                // Point at the offending item itself: an anonymous def path like
                // `crate::{global_asm#0}` is not a location a reader can act on.
                Some(span) => diag.span_note(span, note.text.clone()),
                None => diag.note(note.text.clone()),
            };
        }
        diag.note(
            "this is conservative, not a failure: every affected function keeps its honest \
             verdict, so an obligation a caller-established precondition would have discharged \
             is reported incomplete instead of proved",
        );
        diag.emit();
    }
    // Emit the crate-level coverage row once, at the end of the eager walk, on the
    // same JSON transport lane as the per-function rows. SOUNDNESS: pure fail-closed
    // hardening — the row adds accounting a consumer may only use to DEMOTE a
    // passing gate (shortfall -> inconclusive at best); it never masks an error
    // or claims proof. Human mode already received the policy-appropriate
    // error/warning above.
    // Drained in every output mode: a stop noted here belongs to this compile
    // alone, whether or not a JSON summary carries it.
    let noted_stops = trust_types::determinism::take_noted_stops();
    // Trust (T3 L4, C06a): the elision audit's crate rows, beside the crate accounting.
    drop(audit_finalize_scope);
    elide_audit::drain_crate_level(tcx);
    // Trust (T3 L4, C09w; L4-SUMMARY-1): the crate's memory counters, read once every pass
    // and amendment has run, for the coverage row and the memory census alike.
    let memory = memory_summary(tcx);
    if TrustOutputMode::parse(tcx.sess).emit_json() {
        // Trust: a separate terminal resource inventory, before coverage/summary.
        // Sorting is performed by the recorder; no hash iteration reaches output.
        #[allow(rustc::potential_query_instability)] // sorted by the resource recorder
        let native_bodies: Vec<_> = eligible_bodies.iter().copied().collect();
        native_admission::emit(tcx, &native_bodies);
        let msg = TransportMessage::CoverageSummary(CoverageTransportSummary {
            crate_name: tcx.crate_name(LOCAL_CRATE).to_string(),
            package_name: tcx
                .sess
                .opts
                .unstable_opts
                .trust_verify_package_name
                .clone()
                .unwrap_or_default(),
            primary_package: tcx.sess.trust_crate_role().is_cargo_primary(),
            verification_session: tcx
                .sess
                .opts
                .unstable_opts
                .trust_verify_session
                .clone()
                .unwrap_or_default(),
            eligible,
            processed,
            function_identities: Some(CoverageFunctionIdentityInventory {
                schema: COVERAGE_FUNCTION_IDENTITY_SCHEMA_V1.to_string(),
                eligible_functions,
                processed_functions,
            }),
            // Trust (determinism plan §2, review 2026-09-29): every backstop that
            // fired in this compile — in a row or in work the compiler consumed
            // without publishing one (the R1 harvest, refutation attempts, S1
            // revalidation, a function deadline a lane tested itself) — as the
            // solver lanes and budget scopes reported it. The walk is complete,
            // so nothing notes after this; draining keeps a later compile in
            // the same process from inheriting these.
            noted_stops,
            // Trust (T9): how many obligation keys of this compile were minted
            // on a degraded anchor (coarser than a content address).
            degraded_anchors: tcx.sess.with_trust_compiler_state::<TransportSourceIndex, _>(
                |index| index.degraded_anchors,
            ),
            // Trust (T3 L4, C09w): required on the wire; report-only, in no vector or key.
            memory: memory.clone(),
        });
        if let Ok(json) = serde_json::to_string(&msg) {
            // Use the same mode-aware transport seam as function/crate rows.
            // In Cargo JSON mode this must be a compiler-owned diagnostic so
            // the outer package/target envelope authenticates its provenance;
            // raw stderr is intentionally accepted only in human mode.
            emit_transport_payload(tcx, &json);
        }
    }
    // Trust: emit the crate summary HERE, at the end of the completed eager walk,
    // right after the coverage row — NOT only from the post-`f(tcx)` success hook
    // in `rustc_interface::passes`. A fail-closed compile (an in-scope function
    // came back unknown/failed) accumulates the error and CONTINUES the walk (no
    // mid-pass abort — see `abort_full_verification_skipped`), so the coverage
    // inventory IS complete here even though rustc will later abort on the pending
    // error and unwind past that success hook. Emitting the summary at this
    // complete-inventory point lets a fail-closed compile publish an HONEST,
    // authenticatable transport (the summary reports the failures; it never masks
    // them — the compile still fails). This is idempotent
    // (`TransportCrateAccumulator::emitted`), so the success-path hook becomes a
    // no-op; and a genuine coverage SHORTFALL leaves `processed != eligible` in the
    // coverage row above, which `authenticated_transport` already rejects — so an
    // incomplete walk cannot borrow authentication from this summary. An ICE/panic
    // never reaches this line, so a truly-incomplete inventory is never published.
    trust_emit_transport_crate_summary(tcx);

    // Trust (skip census): publish the crate's skip taxonomy after the complete
    // walk, so the counts name a finished inventory rather than a partial one.
    emit_skip_census(tcx);
    // Trust (CB4): the ONE human line naming how many libtest harness bodies
    // were excluded (silent when none were).
    test_harness_exclusion::emit_crate_summary(tcx);

    // Trust (memory): the retained-memory census for this crate, beside the
    // summary it explains. Only under -Ztrust-memory-notes (host-dependent).
    emit_memory_census_note(tcx, &memory);

    // Trust (v6/D1): seal the `targo trust spec --emit clean` session artifact
    // (no-op unless emission was requested). The reader refuses an unsealed
    // artifact, and the -Ztrust-verify=off early return above never reaches
    // this line — that pair is what makes the subcommand fail closed.
    crate::trust_spec_emit::seal_session(tcx);

    // Trust (W16 mono-extract): after publishing the complete ordinary
    // verification inventory, optionally dump concrete foreign generic
    // instances reached by codegen. This is an observational corpus lane only;
    // it cannot add transport rows or change a verification verdict.
    trust_dump_monomorphic_instances(tcx);
}

/// Prepare the fixed mathematical base before analysis-seam initializer
/// demands enter per-body verification. Pin/verification/root-off is inert.
pub fn trust_init_calculus_reporting(tcx: TyCtxt<'_>) {
    calculus_pending::initialize(tcx);
}

/// Flush withheld original outcomes before the existing frontend fatal gate
/// if any independent error already exists. Pending rows never mask it.
pub fn trust_finalize_calculus_reporting_on_error(tcx: TyCtxt<'_>) {
    if tcx.dcx().has_errors_or_delayed_bugs().is_some() {
        calculus_pending::finalize(tcx, false);
    }
}

/// Close final-artifact reporting after ordinary THIR publication (or its
/// absence). Every miss is judged by the original policy and sole publisher.
pub fn trust_finalize_calculus_reporting(tcx: TyCtxt<'_>) {
    let allow_proofs = tcx.dcx().has_errors_or_delayed_bugs().is_none();
    calculus_pending::finalize(tcx, allow_proofs);
}

/// Dump fully monomorphized foreign function instances for offline corpus work.
///
/// The ordinary extractor walks local `DefId`s and therefore sees generic
/// library bodies before substitution. Under the explicit `-Ztrust-dump=mir:`
/// plus `TRUST_DUMP_MONO=1` opt-in, this lane reuses rustc's codegen instance
/// inventory and its fallible MIR-instantiation helper to expose the concrete
/// bodies that codegen actually reaches.
///
/// This hook deliberately runs after the coverage row and crate summary. It is
/// unavailable when the front end already has errors or the invocation has no
/// codegen output, so forcing the codegen mono graph cannot suppress the honest
/// fail-closed summary. LOCAL instances are admitted since 2026-08-19 for the
/// contract-free generic case only (fn/assoc-fn requiring monomorphization; the
/// native-store contract guard declines any `def_may_have_contracts` local, and
/// non-generic locals plus all closures stay excluded — the ordinary lane owns
/// them). One recorded softness: a local whose spec arrives via the LEGACY
/// HIR-attribute channel is not declined here — no spec is ERASED (the ordinary
/// lane's extraction recovers those attributes into its own dumped row, and
/// downstream consumers fail closed on `requires != Some([])`), but such a mono
/// row is spec-carrying-by-attribute; extend the guard to that channel before
/// relying on "mono rows are spec-free" as an invariant.
///
/// Every admission check declines rather than approximates: only real function
/// bodies are considered (foreign, or the narrowed local class above), the
/// instance arguments and the entire instantiated `Body` must contain no
/// non-region parameter, inference, or placeholder, and collection must not
/// enlarge the already-complete local verification inventory.
#[allow(rustc::potential_query_instability)]
fn trust_dump_monomorphic_instances(tcx: TyCtxt<'_>) {
    let Some(dump_path) = tcx.sess.opts.unstable_opts.trust_dump.mir.as_deref() else {
        return;
    };
    if !env_flag_enabled("TRUST_DUMP_MONO")
        || tcx.dcx().has_errors_excluding_lint_errors().is_some()
        || tcx.sess.opts.unstable_opts.no_codegen
        || !tcx.sess.opts.output_types.should_codegen()
    {
        return;
    }
    std::fs::create_dir_all(dump_path).unwrap_or_else(|error| {
        tcx.dcx().fatal(format!(
            "failed to create -Ztrust-dump=mir: directory `{}` for monomorphic dump: {error}",
            dump_path.display()
        ))
    });

    let processed_before = tcx
        .sess
        .with_trust_compiler_state::<SessionReportState, _>(|state| state.processed_bodies.clone());
    let transport_before =
        tcx.sess.with_trust_compiler_state::<TransportCrateAccumulator, _>(|state| state.clone());
    let partitions = tcx.collect_and_partition_mono_items(());
    let collection_has_errors = tcx.dcx().has_errors_excluding_lint_errors().is_some();
    let processed_after = tcx
        .sess
        .with_trust_compiler_state::<SessionReportState, _>(|state| state.processed_bodies.clone());
    let transport_after =
        tcx.sess.with_trust_compiler_state::<TransportCrateAccumulator, _>(|state| state.clone());
    if processed_after != processed_before || transport_after != transport_before {
        tcx.dcx().fatal(
            "TRUST_DUMP_MONO changed the completed verification or transport inventory; refusing stale observational dumps",
        );
    }
    if collection_has_errors {
        return;
    }

    let mut dumped = FxHashSet::default();
    for cgu in partitions.codegen_units {
        for (item, _data) in cgu.items() {
            let rustc_middle::mono::MonoItem::Fn(instance) = item else { continue };
            // Shims, intrinsics, and virtual dispatch have no ordinary user MIR.
            let ty::InstanceKind::Item(def) = instance.def else { continue };
            // Trust (LOCAL MONO INSTANCES, 2026-08-19): a CONTRACT-FREE local
            // generic's concrete instance is admitted — the bytesize intake's
            // `<ByteSize as AddAssign<u64>>::add_assign` class, which NOTHING
            // else can dump concretely (the ordinary local-`DefId` extractor
            // sees the generic body with `TyKind::Param` locals). The recorded
            // withholding rationale — "dumping a local instance with `None`
            // would silently erase specification identity" — is preserved by
            // the SHARED contract guard below: `trust_contracts_if_any` reads
            // local bundles too (`def_may_have_contracts`), so any
            // contract-carrying local body still declines, and only bodies
            // with NO authored spec flow through. NON-generic local bodies
            // stay excluded: the ordinary extractor already dumps them, and
            // this lane would only duplicate that row under a mono path.
            if def.is_local()
                && (!tcx.generics_of(def).requires_monomorphization(tcx)
                    // Every closure carries synthetic own Type params, so
                    // `requires_monomorphization` is unconditionally TRUE for
                    // closures — without this exclusion every reachable local
                    // closure would dump here AND in the ordinary lane,
                    // double-counting rows and aliasing the identity key for
                    // non-generic parents (round finding, 2026-08-19). A local
                    // closure of a GENERIC parent is dumped generically by the
                    // ordinary lane; its concrete instances wait for a
                    // dedicated identity treatment rather than an ambiguous
                    // one-string-two-bodies row.
                    || matches!(tcx.def_kind(def), DefKind::Closure))
            {
                continue;
            }
            // Trust (W16 breadth, wave-2): admit a CONCRETE foreign instance too.
            // The prior `!requires_monomorphization => continue` disqualifier
            // silently dropped every reachable NON-generic foreign body
            // (`core::cmp::Ordering::reverse`/`then`, `i32::cmp`, the
            // `core::num` `saturating_*` method leaves), so a caller's
            // certified-callee lookup for those leaves missed. A non-generic
            // foreign fn is NOT walked by the ordinary local-`DefId` extractor
            // either (that lane only sees LOCAL bodies), so nothing else dumps
            // it. Removing that single disqualifier lets both the generic-
            // requiring bodies (unchanged) and the concrete foreign leaves flow
            // through the SAME fail-closed guards below; the fully-monomorphic
            // cardinal checks (`has_non_region_{param,infer,placeholders}` on
            // args and on the instantiated body) hold TRIVIALLY for a
            // param-free instance, and the contract-free / `InstanceKind::Item` /
            // fn-like / `is_mir_available` / non-local / instance-dedup guards
            // are all retained verbatim. Still DOUBLE-GATED behind
            // `-Ztrust-dump=mir:` + `TRUST_DUMP_MONO` (checked at the top): no
            // default-behavior change.
            if !matches!(tcx.def_kind(def), DefKind::Fn | DefKind::AssocFn | DefKind::Closure)
                || !tcx.is_mir_available(def)
                || trust_contracts_if_any(tcx, def).is_some_and(|bundle| {
                    // A nonzero summary with empty decoded vectors is malformed
                    // or incomplete metadata, not permission to erase a spec.
                    !bundle.is_empty() || bundle.summary.total != 0
                })
            {
                continue;
            }
            if instance.args.has_non_region_param()
                || instance.args.has_non_region_infer()
                || instance.args.has_non_region_placeholders()
            {
                continue;
            }

            if !dumped.insert(*instance) {
                continue;
            }
            let mono_def_path = trust_mir_extract::exact_def_path_str_with_args(
                tcx,
                instance.def_id(),
                instance.args,
            );

            let generic_body = tcx.instance_mir(instance.def);
            let Ok(mono_body) = instance.try_instantiate_mir_and_normalize_erasing_regions(
                tcx,
                ty::TypingEnv::fully_monomorphized(),
                ty::EarlyBinder::bind(tcx, generic_body.clone()),
            ) else {
                continue;
            };
            if mono_body.has_non_region_param()
                || mono_body.has_non_region_infer()
                || mono_body.has_non_region_placeholders()
            {
                continue;
            }

            let mut func =
                trust_mir_extract::extract_function_with_contract_bundle(tcx, &mono_body, None);
            func.def_path = mono_def_path.clone();
            let json = serde_json::to_string_pretty(&func).unwrap_or_else(|error| {
                tcx.dcx().fatal(format!(
                    "failed to serialize monomorphic instance `{mono_def_path}` for -Ztrust-dump=mir:: {error}"
                ))
            });
            let file_path = dump_path.join(mir_dump_filename(&func.def_path, &json));
            write_mir_dump_create_new(&file_path, &json).unwrap_or_else(|error| {
                tcx.dcx().fatal(format!(
                    "failed to publish monomorphic -Ztrust-dump=mir: evidence for `{mono_def_path}` at `{}`: {error}",
                    file_path.display()
                ))
            });
            trace!("Trust: monomorphic MIR dump for {mono_def_path} at {}", file_path.display());
        }
    }
}

/// Trust (2026-10-03; hoisted from the backing escape census): whether the local `def`
/// owns a promoted table worth reading — a non-Clean-origin function, closure or synthetic
/// coroutine body (a Clean-origin def's table is empty by construction, and its
/// `promoted_mir` is served without HIR), or a non-trivial constant or static (a trivial
/// const is `_0 = const <value>` and promotes nothing). ONE definition of "which owners
/// have promoteds", shared by the backing escape census and the minting-site seam
/// (`uncharged_callable::refuse_requires_carrying_values_minted_outside_verified_bodies`).
fn local_def_may_have_promoted_mir(tcx: TyCtxt<'_>, def: DefId) -> bool {
    let Some(local) = def.as_local() else { return false };
    match tcx.def_kind(def) {
        DefKind::Fn | DefKind::AssocFn | DefKind::Closure | DefKind::SyntheticCoroutineBody => {
            !crate::clean_origin_mir::is_clean_origin(tcx, local)
        }
        DefKind::Const { .. }
        | DefKind::AssocConst { .. }
        | DefKind::AnonConst
        | DefKind::Static { .. } => !tcx.is_trivial_const(local),
        _ => false,
    }
}

/// Trust (assertion-grade coverage): is `local` in the per-function verification
/// universe? The SINGLE eligibility predicate shared by the eager whole-crate walk
/// (`trust_ensure_whole_crate_verification`, the `eligible` denominator), the
/// `TrustVerify::run_pass` processed-identity set, and the `inner_optimized_mir`
/// early-out credits — one definition so the coverage assertion `processed ==
/// eligible` compares the same set on both sides.
///
/// Functions and closures (incl. coroutine bodies) only: const/static/anon-const
/// initializers take the `mir_for_ctfe` path (`inner_optimized_mir` panics on
/// them), and ctor shims / synthetic coroutine bodies are compiler-generated glue
/// outside the per-function verification universe. `optimized_mir` is defined for
/// runtime bodies and `const fn` only.
pub(crate) fn trust_coverage_eligible_body(tcx: TyCtxt<'_>, local: LocalDefId) -> bool {
    // Trust (r15, 2026-10-07): the BY-MOVE body rustc synthesizes for an async
    // closure (`DefKind::SyntheticCoroutineBody`, `{closure#0}::{synthetic#0}`) is
    // a runtime body the TrustVerify pass verifies and publishes a row for, so it
    // is in the coverage universe. Before, it was not eligible, so the eager walk
    // never demanded it: codegen did, AFTER the coverage row and the crate summary
    // were published, and its row (a FAILED one included) was missing from both.
    // MEASURED on stage-1 `ae0494648a`, `-Ztrust-policy=advisory`: crate totals 3
    // failed against 4 published rows (`trust_ir_lower_site_args_closure_family.rs`)
    // and 6 against 7 (`async_closure_by_move_body_no_ice.rs`). It has no HIR, so it
    // answers here, before the HIR reads below; it is never Clean-origin and never a
    // contract checker, and it is a fn-like runtime body, never a const context.
    if matches!(tcx.def_kind(local.to_def_id()), DefKind::SyntheticCoroutineBody) {
        return true;
    }
    if !matches!(tcx.def_kind(local.to_def_id()), DefKind::Fn | DefKind::AssocFn | DefKind::Closure)
    {
        return false;
    }
    // Trust (I5): a Clean-origin def is OUTSIDE the VC pipeline's coverage
    // universe by construction — its `optimized_mir` is the kernel-gated
    // emission, served BEFORE the pass manager, so `TrustVerify::run_pass`
    // never observes it, and its correctness authority is the faithfulness
    // gate (`clean_origin_mir`), not a VC verdict. Counting it in the
    // denominator would make coverage name a body the verifier CORRECTLY
    // never processes — the same shape as the dead-contract-closure exclusion
    // below, and the FIFTH site the mir_keys seeding of Clean-origin defs
    // reached (predicted from this reconciliation's own `processed ==
    // eligible` assertion, not discovered as an ICE). Nothing goes silent:
    // the island lane separately reports the kernel check of every
    // declaration, and the gate refuses emission outright on disagreement.
    // This check also sits BEFORE the `hir_body_const_context` read at the
    // bottom, which is not written for a synthetic HIR owner.
    if crate::clean_origin_mir::is_clean_origin(tcx, local) {
        return false;
    }
    // Runtime contract checks are disabled by default. Their compiler-generated
    // checker closures are then never constructed or called and are intentionally
    // excluded by `verification_decision`. Counting them in the denominator
    // would make coverage name a function the verifier correctly never emits.
    if trust_is_statically_dead_contract_closure(tcx, local) {
        return false;
    }
    matches!(tcx.hir_body_const_context(local), None | Some(rustc_hir::ConstContext::ConstFn))
}

fn trust_is_statically_dead_contract_closure(tcx: TyCtxt<'_>, local: LocalDefId) -> bool {
    if tcx.sess.contract_checks() || !matches!(tcx.def_kind(local.to_def_id()), DefKind::Closure) {
        return false;
    }
    let closure_hir_id = tcx.local_def_id_to_hir_id(local);
    tcx.hir_parent_iter(closure_hir_id).any(
        |(_, node)| matches!(node, Node::LetStmt(local) if matches!(local.source, LocalSource::Contract)),
    )
}

/// Trust (assertion-grade coverage): credit a coverage-eligible body that
/// `inner_optimized_mir` legitimately early-outs BEFORE the optimization pipeline
/// (and therefore before `TrustVerify::run_pass`) as PROCESSED, so the crate
/// coverage assertion (`processed == eligible`) does not false-alarm on:
///
/// * `tainted_by_errors` — the body carries an `ErrorGuaranteed`, so the BUILD
///   ALREADY FAILS; crediting it can never turn under-coverage into a pass
///   (targo's gate is `Fail` on any nonzero compiler exit regardless).
/// * a lone-`unreachable` body (unsatisfiable predicates shrink MIR to a single
///   `unreachable` terminator) — no executable path exists, so verification
///   coverage is vacuous; such a body contributes zero obligation rows and can
///   therefore never mint proof credit either.
///
/// Every eligible body reaches exactly one of: this credit, or
/// `TrustVerify::run_pass` (steal semantics run `optimized_mir` once per body) —
/// which is what makes any `processed != eligible` result an ASSERTION of broken
/// coverage accounting rather than a heuristic. No-op when verification is
/// disabled or the body is outside the coverage universe.
pub(crate) fn trust_note_coverage_early_out(
    tcx: TyCtxt<'_>,
    local: LocalDefId,
    kind: CoverageEarlyOutKind,
) {
    if !verification_enabled(tcx.sess) {
        return;
    }
    if !trust_coverage_eligible_body(tcx, local) {
        return;
    }
    let newly_processed = tcx.sess.with_trust_compiler_state::<SessionReportState, _>(|state| {
        state.processed_bodies.insert(local)
    });
    // Trust: these bodies do not cross the scheduling boundary and receive no grant.
    if newly_processed {
        native_admission::early_out(
            tcx,
            local,
            match kind {
                CoverageEarlyOutKind::TaintedByErrors => "tainted_by_errors",
                CoverageEarlyOutKind::VacuouslyUnreachable => "no_executable_path",
            },
        );
    }
    let emit_json = TrustOutputMode::parse(tcx.sess).emit_json();
    if !newly_processed || !(emit_json || elide_audit::enabled()) {
        return;
    }

    // Canonical crate-qualified spelling (see the coverage-identity
    // reconciliation note above `eligible_functions`): every transport envelope
    // must match the identity inventory as an exact set, so the early-out rows
    // use the same `safe_def_path_str` identity as every other
    // `emit_transport_json` call site.
    let function = trust_mir_extract::safe_def_path_str(tcx, local.to_def_id());
    let row = match kind {
        CoverageEarlyOutKind::TaintedByErrors => transport_tainted_body_row(),
        CoverageEarlyOutKind::VacuouslyUnreachable => transport_no_obligations_row(),
    };
    // Trust (T3 C05): the elision audit's verdict vector, in either output mode.
    audit_published_rows(tcx, local.to_def_id(), &function, std::slice::from_ref(&row));
    if emit_json {
        emit_transport_json(tcx, Some(local), &function, &[row], 0);
    }
}

/// Trust #540 (R1): is `name` an SSA/synthetic MIR local (`_3`, `_3#s0_1`, …) rather than
/// a source-level parameter name? vcgen renders an indexed local as `_<n>` (optionally with
/// a `#<version>` SSA suffix); a real parameter is rendered by its debug name (`i`, `len`).
/// Used to recognize the block-def equality facts vcgen threads into a violation formula.
fn r1_is_synthetic_local(name: &str) -> bool {
    name.starts_with('_') || name.contains('#')
}

/// True iff `f` is an ALWAYS-TRUE integer type-range bound over a single variable, of the
/// shape vcgen's `conjoin_arg_type_ranges` / `input_range_constraint` emit: an `And` of
/// exactly two comparisons pinning one `Var` between the min and max literals of some integer
/// type (`0 <= u <= 2^w-1`, `−2^(w-1) <= s <= 2^(w-1)−1`). Recognizes both operand orders
/// (`min <= v`/`v >= min`, `v <= max`/`max >= v`). Used by `simplify_violation_negation` to
/// drop these unconditionally-true facts before negating a violation — dropping an always-true
/// conjunct removes only an always-FALSE disjunct from `¬V`, preserving its meaning exactly.
fn is_always_true_type_range(f: &trust_types::Formula) -> bool {
    use trust_types::Formula as F;
    // (var_name, literal, is_lower_bound). A `Ge(v,k)`/`Le(k,v)` lower-bounds v by k; a
    // `Le(v,k)`/`Ge(k,v)` upper-bounds v by k.
    fn lit(g: &F) -> Option<i128> {
        match g {
            F::Int(n) => Some(*n),
            F::UInt(n) => i128::try_from(*n).ok(),
            _ => None,
        }
    }
    fn var(g: &F) -> Option<&str> {
        if let F::Var(n, _) = g { Some(n.as_str()) } else { None }
    }
    fn bound(cmp: &F) -> Option<(&str, i128, bool)> {
        match cmp {
            F::Ge(a, b) => {
                // lower bound `v >= k`, or equivalently upper bound `k >= v`.
                if let (Some(v), Some(k)) = (var(a), lit(b)) {
                    Some((v, k, true))
                } else if let (Some(k), Some(v)) = (lit(a), var(b)) {
                    Some((v, k, false))
                } else {
                    None
                }
            }
            F::Le(a, b) => {
                // lower bound `k <= v`, or equivalently upper bound `v <= k`.
                if let (Some(k), Some(v)) = (lit(a), var(b)) {
                    Some((v, k, true))
                } else if let (Some(v), Some(k)) = (var(a), lit(b)) {
                    Some((v, k, false))
                } else {
                    None
                }
            }
            _ => None,
        }
    }
    // A `(min, max)` pair is a valid type range iff it is the extremes of some integer width.
    fn is_type_range(min: i128, max: i128) -> bool {
        for &w in &[8u32, 16, 32, 64, 128] {
            // unsigned [0, 2^w - 1]
            let umax = if w == 128 {
                i128::MAX // u128::MAX exceeds i128; a u128::MAX bound arrives via UInt≥i128::MAX filter
            } else {
                (1i128 << w) - 1
            };
            if min == 0 && (max == umax || (w == 128 && max == i128::MAX)) {
                return true;
            }
            // signed [-2^(w-1), 2^(w-1) - 1]
            let (smin, smax) = if w == 128 {
                (i128::MIN, i128::MAX)
            } else {
                (-(1i128 << (w - 1)), (1i128 << (w - 1)) - 1)
            };
            if min == smin && max == smax {
                return true;
            }
        }
        false
    }
    let F::And(items) = f else { return false };
    if items.len() != 2 {
        return false;
    }
    let (Some((v0, k0, lo0)), Some((v1, k1, lo1))) = (bound(&items[0]), bound(&items[1])) else {
        return false;
    };
    if v0 != v1 || lo0 == lo1 {
        return false; // must be the same var, one lower + one upper bound
    }
    let (min, max) = if lo0 { (k0, k1) } else { (k1, k0) };
    is_type_range(min, max)
}

/// Trust #540 (R1): the WEAKEST sound precondition that discharges the failed violation `v`
/// — i.e. `¬v`, with vcgen's block-def equality threading folded back out and the negation
/// pushed inward so the result is a clean parameter-level predicate.
///
/// vcgen threads SSA-renaming facts into a violation as leading conjuncts, e.g. for `a[i]`
/// (`i: usize`) the failed bounds VC is
/// ```text
/// And([ Eq(_3, i),                 // the index local _3 aliases param i
///       Eq(_4, Lt(_3, 4)),         // the bounds-check bool (irrelevant here)
///       Ge(_3, 4) ])               // THE violation: index >= len
/// ```
/// Naively negating the whole `And` yields a disjunction over the synthetic locals `_3`/`_4`,
/// which the contract-assumption gate (rightly) rejects as non-parameter. So we instead:
///   1. peel the `Eq(synthetic, rhs)` binding conjuncts and build a substitution that maps
///      each synthetic local to its definition, resolved to a fixed point so chains collapse
///      (`_3 -> i`);
///   2. apply that substitution to the remaining "core" conjuncts, eliminating synthetics;
///   3. negate the core, pushing `¬` inward across the comparison / `Or` / `And` shapes vcgen
///      emits (so a signed-index `Lt(i,0) ∨ Ge(i,len)` core becomes `Ge(i,0) ∧ Lt(i,len)`).
///
/// The result is over EXACTLY the core's variables after substitution. If those are all
/// unique parameters of F, the gate accepts it and it is CONNECTED to the goal; otherwise the
/// gate rejects it ⇒ fail-closed. Crucially, this is only a candidate GENERATOR: the proposed
/// P is independently (a) kernel-certified to discharge F's real VC and (b) discharged at
/// every caller, so even a mis-derived candidate cannot produce an unsound flip.
// Maximum amount of structural work the R1 synthetic-local candidate machinery
// may perform across one whole candidate. One unit is charged for each Formula
// or Sort node, metadata record/byte, output node, and bounded scan step. Unlike
// a wall-clock timeout, this composes across conjuncts and is machine-independent.
const R1_SUBSTITUTION_WORK_BUDGET: usize = 65_536;

// Independent bound applied before any recursive Formula clone/rewrite.
const R1_SUBSTITUTION_DEPTH_BUDGET: usize = 512;

fn r1_formula_wide_child_count(formula: &trust_types::Formula) -> usize {
    use trust_types::Formula as F;
    match formula {
        F::And(items) | F::Or(items) => items.len(),
        F::Pred(_, args) => args.len(),
        F::Ctor { args, .. } | F::FnApp { args, .. } => args.len(),
        _ => 0,
    }
}

struct R1SubstitutionBudget {
    remaining_work: usize,
}

impl R1SubstitutionBudget {
    fn new() -> Self {
        Self { remaining_work: R1_SUBSTITUTION_WORK_BUDGET }
    }

    #[cfg(test)]
    fn with_work(remaining_work: usize) -> Self {
        Self { remaining_work }
    }

    fn charge_work(&mut self, work: usize) -> bool {
        // The deterministic structural budget is the primary bound. Also honor
        // the shared ambient per-function budget added by the verifier-wide
        // watchdog, so this pre-dispatch candidate lane cannot consume work
        // after the enclosing verification request has exhausted either bound.
        if trust_types::verify_budget::exhausted_readonly() || work > self.remaining_work {
            return false;
        }
        self.remaining_work -= work;
        true
    }

    fn charge_node(&mut self) -> bool {
        self.charge_work(1)
    }

    fn can_queue(&self, already_queued: usize, additional: usize) -> bool {
        additional <= self.remaining_work.saturating_sub(already_queued)
    }

    /// Bound every recursively cloned part of a Sort, including datatype
    /// constructor/field records and their retained strings. `inherited_depth`
    /// is the enclosing Formula depth, so the cap applies to the combined
    /// derive-Clone call stack rather than treating metadata as depth zero.
    fn preflight_sort(&mut self, root: &trust_types::Sort, inherited_depth: usize) -> bool {
        use trust_types::Sort as S;

        // Count the Sort root at the enclosing Formula's depth. This preserves
        // the established Formula boundary for scalar metadata while every
        // recursive Sort edge still consumes one additional depth level.
        let mut worklist = vec![(root, inherited_depth)];
        while let Some((current, depth)) = worklist.pop() {
            if depth > R1_SUBSTITUTION_DEPTH_BUDGET || !self.charge_node() {
                return false;
            }
            match current {
                S::Array(index, element) => {
                    if !self.can_queue(worklist.len(), 2) {
                        return false;
                    }
                    worklist.push((index, depth + 1));
                    worklist.push((element, depth + 1));
                }
                S::Datatype { name, constructors } => {
                    if !self.charge_work(name.len()) || !self.charge_work(constructors.len()) {
                        return false;
                    }
                    for (constructor, fields) in constructors {
                        if !self.charge_work(constructor.len()) || !self.charge_work(fields.len()) {
                            return false;
                        }
                        for (field, sort) in fields {
                            if !self.charge_work(field.len()) || !self.can_queue(worklist.len(), 1)
                            {
                                return false;
                            }
                            worklist.push((sort, depth + 1));
                        }
                    }
                }
                _ => {}
            }
        }
        true
    }

    fn preflight_formula_metadata(&mut self, formula: &trust_types::Formula, depth: usize) -> bool {
        use trust_types::Formula as F;

        match formula {
            F::Var(name, sort) => self.charge_work(name.len()) && self.preflight_sort(sort, depth),
            F::SymVar(_, sort) => self.preflight_sort(sort, depth),
            F::Forall(bindings, _) | F::Exists(bindings, _) => {
                if !self.charge_work(bindings.len()) {
                    return false;
                }
                bindings.iter().all(|(_, sort)| self.preflight_sort(sort, depth))
            }
            F::Ctor { ctor, sort, .. } => {
                self.charge_work(ctor.len()) && self.preflight_sort(sort, depth)
            }
            F::Sel { datatype, field, field_sort, .. } => {
                self.charge_work(datatype.len())
                    && self.charge_work(field.len())
                    && self.preflight_sort(field_sort, depth)
            }
            F::IsCtor { datatype, ctor, .. } => {
                self.charge_work(datatype.len()) && self.charge_work(ctor.len())
            }
            F::FnApp { func, sort, .. } => {
                self.charge_work(func.len()) && self.preflight_sort(sort, depth)
            }
            _ => true,
        }
    }

    /// Iteratively validate a borrowed tree before any recursive clone or
    /// rewrite. The wide-node check happens before `Formula::children()` so an
    /// attacker-sized `And`/`Or`/application cannot allocate an equally large
    /// scratch vector merely to be rejected.
    fn preflight_formula_from_depth(
        &mut self,
        formula: &trust_types::Formula,
        root_depth: usize,
    ) -> bool {
        let mut worklist = vec![(formula, root_depth)];
        while let Some((current, depth)) = worklist.pop() {
            if depth > R1_SUBSTITUTION_DEPTH_BUDGET
                || !self.charge_node()
                || !self.preflight_formula_metadata(current, depth)
            {
                return false;
            }

            let mut child_count = r1_formula_wide_child_count(current);
            if child_count == 0 {
                trust_types::for_each_formula_child(current, |_| child_count += 1);
            }
            if !self.can_queue(worklist.len(), child_count) {
                return false;
            }
            trust_types::for_each_formula_child(current, |child| {
                worklist.push((child, depth + 1));
            });
        }
        true
    }

    fn preflight_formula(&mut self, formula: &trust_types::Formula) -> bool {
        self.preflight_formula_from_depth(formula, 0)
    }
}

/// Iteratively peel nested conjunctions into borrowed first-binding
/// substitutions and borrowed core formulas. No Formula is cloned here.
fn collect_r1_candidate_parts<'a>(
    violation: &'a trust_types::Formula,
    budget: &mut R1SubstitutionBudget,
) -> Option<(Vec<(&'a str, &'a trust_types::Formula)>, Vec<&'a trust_types::Formula>)> {
    use trust_types::Formula as F;

    // Bound every retained name/sort before the first shape classifier can
    // scan it. Collection then charges its own visits below; later hashing,
    // resolution, cloning, and follow-on scans are charged independently.
    if !budget.preflight_formula(violation) {
        return None;
    }

    let mut substitutions = Vec::new();
    let mut core = Vec::new();
    let mut worklist = vec![(violation, 0usize)];
    while let Some((formula, depth)) = worklist.pop() {
        if depth > R1_SUBSTITUTION_DEPTH_BUDGET || !budget.charge_node() {
            return None;
        }
        match formula {
            F::And(items) => {
                if items.len() == 2 && is_always_true_type_range(formula) {
                    continue;
                }
                if !budget.can_queue(worklist.len(), items.len()) {
                    return None;
                }
                // Reverse the LIFO insertion so duplicate bindings retain the
                // old depth-first, source-order "first binding wins" behavior.
                worklist.extend(items.iter().rev().map(|item| (item, depth + 1)));
            }
            F::Eq(lhs, rhs) => match (&**lhs, &**rhs) {
                (F::Var(name, _), _) if r1_is_synthetic_local(name) => {
                    substitutions.push((name.as_str(), &**rhs));
                }
                (_, F::Var(name, _)) if r1_is_synthetic_local(name) => {
                    substitutions.push((name.as_str(), &**lhs));
                }
                _ => core.push(formula),
            },
            _ => core.push(formula),
        }
    }
    Some((substitutions, core))
}

/// Resolve a batch under one shared structural-work/depth budget. Cycles or
/// exhaustion reject the entire candidate; no partially expanded Formula escapes.
fn resolve_r1_synthetic_substitution_batch<'a>(
    formulas: &[&'a trust_types::Formula],
    substitutions: &[(&'a str, &'a trust_types::Formula)],
    budget: &mut R1SubstitutionBudget,
) -> Option<Vec<trust_types::Formula>> {
    for (name, replacement) in substitutions {
        // Test/helpers may supply a substitution table not produced by the
        // collection walk. Charge every key before FxHashMap hashes it, as
        // well as the replacement tree that may be cloned below.
        if !budget.charge_work(name.len()) || !budget.preflight_formula(replacement) {
            return None;
        }
    }
    for formula in formulas {
        if !budget.preflight_formula(formula) {
            return None;
        }
    }

    let mut first = FxHashMap::default();
    for (name, value) in substitutions {
        first.entry(*name).or_insert(*value);
    }

    fn resolve_owned<'a>(
        formula: trust_types::Formula,
        substitutions: &FxHashMap<&'a str, &'a trust_types::Formula>,
        visiting: &mut FxHashSet<&'a str>,
        budget: &mut R1SubstitutionBudget,
        depth: usize,
    ) -> Option<trust_types::Formula> {
        if depth > R1_SUBSTITUTION_DEPTH_BUDGET || !budget.charge_node() {
            return None;
        }

        if let trust_types::Formula::Var(name, _) = &formula
            && let Some((binding_name, replacement)) = substitutions.get_key_value(name.as_str())
        {
            let binding_name = *binding_name;
            if !visiting.insert(binding_name) {
                return None;
            }
            // Charge the complete RHS again for every materialized occurrence.
            // The batch preflight bounds the input; this occurrence preflight
            // prevents one metadata-heavy RHS from being cloned thousands of
            // times while paying for its Sort/strings only once.
            if !budget.preflight_formula_from_depth(replacement, depth + 1) {
                visiting.remove(binding_name);
                return None;
            }
            let resolved =
                resolve_owned((**replacement).clone(), substitutions, visiting, budget, depth + 1);
            visiting.remove(binding_name);
            return resolved;
        }

        let mut failed = false;
        let mapped = formula.map_children(&mut |child| {
            if failed {
                return child;
            }
            match resolve_owned(child, substitutions, visiting, budget, depth + 1) {
                Some(resolved) => resolved,
                None => {
                    failed = true;
                    // The enclosing mapped result is discarded. A fixed leaf
                    // avoids cloning the failed child solely to satisfy the
                    // infallible `map_children` callback type.
                    trust_types::Formula::Bool(false)
                }
            }
        });
        (!failed).then_some(mapped)
    }

    let mut resolved = Vec::with_capacity(formulas.len());
    for formula in formulas {
        // Safe after the shared iterative preflight above.
        resolved.push(resolve_owned(
            (*formula).clone(),
            &first,
            &mut FxHashSet::default(),
            budget,
            0,
        )?);
    }
    Some(resolved)
}

/// Single-formula test/helper wrapper around the production batch resolver.
#[cfg(test)]
fn resolve_r1_synthetic_substitutions(
    formula: &trust_types::Formula,
    substitutions: &[(String, trust_types::Formula)],
) -> Option<trust_types::Formula> {
    let substitutions =
        substitutions.iter().map(|(name, value)| (name.as_str(), value)).collect::<Vec<_>>();
    resolve_r1_synthetic_substitution_batch(
        &[formula],
        &substitutions,
        &mut R1SubstitutionBudget::new(),
    )?
    .pop()
}

fn simplify_violation_negation(v: &trust_types::Formula) -> Option<trust_types::Formula> {
    use trust_types::Formula as F;
    let mut budget = R1SubstitutionBudget::new();
    let (substitutions, core) = collect_r1_candidate_parts(v, &mut budget)?;

    if !substitutions.is_empty() && !core.is_empty() {
        // Resolve every core conjunct as one batch. A cycle or exhaustion drops
        // the whole candidate; falling back to a raw clone here would re-enter
        // the hostile tree outside the budget.
        let resolved = resolve_r1_synthetic_substitution_batch(&core, &substitutions, &mut budget)?;
        let mut core_sub = Vec::with_capacity(resolved.len());
        for formula in &resolved {
            // `negate_inward` recursively clones the selected children. Meter
            // those formula and metadata clones before invoking it.
            if !budget.preflight_formula(formula) {
                return None;
            }
            core_sub.push(negate_inward(formula));
        }
        // Trust (R1 array-bounds regression): vcgen's block-def conjoining pulls
        // UNRELATED synthetic facts onto a bounds violation — e.g. the recursive
        // `n - 1` checked-sub's `Eq(_10, _11-1)` guard, whose negation survives as
        // a disjunct `And([Ge(_11,1), Not(Eq(_10, _11-1))])` carrying SSA temps
        // `_10`/`_11` that have no `Eq(temp, param)` binding to substitute away.
        // The gate then rejects the whole `Or` on those non-param vars, even though
        // the parameter-level bound disjunct (`Lt(i, 4)`) is present and usable.
        // Drop the disjuncts that still carry an un-substituted synthetic, keeping
        // the parameter-only ones — a STRONGER `P` (a smaller `Or`), sound for the
        // inductive flip exactly as the always-true-type-range drop above (a caller
        // must establish a stronger `P`, never weaker; can only fail-close more).
        // Keep every disjunct if that would empty the set (nothing param-only to
        // salvage) so the raw `¬V` still reaches the gate, which rejects it honestly.
        let mut synthetic = Vec::with_capacity(core_sub.len());
        for disjunct in &core_sub {
            synthetic.push(r1_formula_mentions_synthetic(disjunct, &mut budget)?);
        }
        if synthetic.iter().any(|mentions| !mentions) {
            core_sub = core_sub
                .into_iter()
                .zip(synthetic)
                .filter_map(|(disjunct, mentions)| (!mentions).then_some(disjunct))
                .collect();
        }
        return Some(if core_sub.len() == 1 {
            core_sub.into_iter().next().unwrap()
        } else {
            if !budget.charge_node() {
                return None;
            }
            F::Or(core_sub)
        });
    }

    // Non-conjunction violations and conjunctions without usable bindings keep
    // the legacy direct negation, but only after iterative depth/node preflight.
    budget.preflight_formula(v).then(|| negate_inward(v))
}

/// Trust (piece #8 — length-relationship preconditions): a length TERM `L` that a
/// caller can render exactly — a `<param>__slice_len` runtime slice length or a
/// `__trust_constparam_{index}_{name}` const-generic array length. The recognizer
/// keys on the SPELLING only; soundness comes from the gate (which admits it only
/// when it is a slice/array PARAMETER's length), the kernel certification of
/// F-under-P, and the caller discharge — not from this loose match.
fn r1_is_length_term(f: &trust_types::Formula) -> bool {
    if let trust_types::Formula::Var(n, _) = f {
        n.ends_with("__slice_len") || n.starts_with("__trust_constparam_")
    } else {
        false
    }
}

/// Trust (piece #8): synthesize the loop-bound precondition `P = Le(B, L)` from a
/// failed bounds violation `V`, for the caller-supplied-loop-bound family
/// (`fn fill(arr:&mut[u32], n){ for i in 0..n { arr[i] } }`). `simplify_violation_negation`
/// cannot produce this cleanly — for a loop body `V` mentions the loop-index LOCAL
/// `i` (a non-parameter), so `¬V` is rejected by the gate. Here we instead read the
/// TRANSITIVE lemma directly off `V`'s conjuncts:
///
///   V = And([ Ge(i, 0), Lt(i, B), Ge(i, L) ])   (unsigned index; range-yield + bounds)
///
/// where `Lt(i, B)` is the range-iterator UPPER-yield fact (`B` = the loop end, a
/// param `n` or param arithmetic), and `Ge(i, L)` is the bounds violation with `L` a
/// param-slice length term. Mint `P = Le(B, L)` (`n <= arr__slice_len`): then
/// `i < B` (yield) ∧ `B <= L` (P) ⇒ `i < L` ⇒ `¬(i >= L)`, so the violation is UNSAT.
///
/// `P` mentions only `{B's vars, L}` — the SAME symbols `V` uses — so it is CONNECTED
/// to `V` (the R1 gate's subset check) and, when `B` is over params + `L` is a
/// param-slice length, ADMISSIBLE under the piece #8 gate whitelist. The recognizer
/// is only a candidate GENERATOR: the minted `P` is independently kernel-certified to
/// discharge F's real strengthened VC and discharged at every caller, so a
/// mis-recognized shape can only cost completeness (drop), never soundness. Returns
/// `None` when the shape is absent.
fn synthesize_loop_bound_precondition(v: &trust_types::Formula) -> Option<trust_types::Formula> {
    synthesize_loop_bound_precondition_with_budget(v, R1SubstitutionBudget::new())
}

fn synthesize_loop_bound_precondition_with_budget(
    v: &trust_types::Formula,
    mut budget: R1SubstitutionBudget,
) -> Option<trust_types::Formula> {
    use trust_types::Formula as F;

    // Flatten `V` to its core conjuncts, resolving SSA block-def bindings
    // `Eq(_synthetic, rhs)` exactly as `simplify_violation_negation` does — the
    // range-yield / bounds facts arrive over synthetic temps (`Eq(_5, i)`) that must
    // collapse so the index term is the loop-variable name, not `_5`.
    let (substitutions, core) = collect_r1_candidate_parts(v, &mut budget)?;
    // A cyclic or exponentially-expanding binding set is not a usable source
    // of a specialized loop lemma. Refuse it deterministically rather than
    // retaining a timing-dependent partially-expanded formula.
    let core = resolve_r1_synthetic_substitution_batch(&core, &substitutions, &mut budget)?;

    // Collect, per index term, the upper-yield bounds `B` (`Lt(i,B)`/`Le(i,B)`, B not
    // a length term) and the length lower-bounds `L` (`Ge(i,L)`, L a length term).
    // The index term `i` must be IDENTICAL between the two — this ties the transitive
    // lemma to one variable. `i` need not be a param (it is the loop local); only `B`
    // and `L` end up in `P`, and the gate validates those.
    for c in &core {
        if !budget.charge_node() {
            return None;
        }
        // Violation conjunct: `Ge(i, L)` with L a length term.
        let F::Ge(gi, gl) = c else { continue };
        if !r1_is_index_term(gi) || !r1_is_length_term(gl) {
            continue;
        }
        // Find a matching upper-yield conjunct `Lt(i, B)` / `Le(i, B)` over the SAME i.
        for u in &core {
            if !budget.charge_node() {
                return None;
            }
            let (i_u, b, strict) = match u {
                F::Lt(a, b) => (a, b, true),
                F::Le(a, b) => (a, b, false),
                _ => continue,
            };
            if !r1_index_terms_match(i_u, gi) {
                continue;
            }
            // Do not mint `n <= L` when `B` is itself a length term (that is a
            // length-vs-length relation, not a loop bound) or references `i` (a
            // self-referential bound). `B` should be a param scalar / param
            // arithmetic; the gate re-validates its vars regardless.
            if r1_is_length_term(b) || r1_formula_mentions_index(b, gi, &mut budget)? {
                continue;
            }
            // The returned comparison clones both selected subtrees and adds
            // one output node. Charge and depth-check that output first.
            if !budget.charge_node()
                || !budget.preflight_formula_from_depth(b, 1)
                || !budget.preflight_formula_from_depth(gl, 1)
            {
                return None;
            }
            // `for i in 0..B { a[i] }` is an EXCLUSIVE range (`Lt(i, B)`), so the
            // tight, correct precondition is `B <= L`. A `Le(i, B)` (inclusive upper
            // yield) needs `B < L`; mint the exact one for each.
            return Some(if strict {
                F::Le(b.clone(), gl.clone())
            } else {
                F::Lt(b.clone(), gl.clone())
            });
        }
    }
    None
}

fn r1_is_index_term(formula: &trust_types::Formula) -> bool {
    use trust_types::{Formula as F, Sort as S};
    matches!(formula, F::Var(_, S::Int | S::BitVec(_)) | F::SymVar(_, S::Int | S::BitVec(_)))
}

fn r1_index_terms_match(left: &trust_types::Formula, right: &trust_types::Formula) -> bool {
    use trust_types::Formula as F;
    match (left, right) {
        (F::Var(left_name, left_sort), F::Var(right_name, right_sort)) => {
            left_name == right_name && left_sort == right_sort
        }
        (F::SymVar(left_name, left_sort), F::SymVar(right_name, right_sort)) => {
            left_name == right_name && left_sort == right_sort
        }
        _ => false,
    }
}

/// True iff the simple local index `needle` occurs anywhere in `formula`.
/// Every visited node and pending child is bounded by the candidate's shared
/// work budget; a complex needle is outside this narrow recognizer.
fn r1_formula_mentions_index(
    formula: &trust_types::Formula,
    needle: &trust_types::Formula,
    budget: &mut R1SubstitutionBudget,
) -> Option<bool> {
    if !r1_is_index_term(needle) {
        return None;
    }
    let mut worklist = vec![formula];
    while let Some(current) = worklist.pop() {
        if !budget.charge_node() {
            return None;
        }
        if r1_index_terms_match(current, needle) {
            return Some(true);
        }
        let mut child_count = r1_formula_wide_child_count(current);
        if child_count == 0 {
            trust_types::for_each_formula_child(current, |_| child_count += 1);
        }
        if !budget.can_queue(worklist.len(), child_count) {
            return None;
        }
        trust_types::for_each_formula_child(current, |child| worklist.push(child));
    }
    Some(false)
}

/// True iff `f` mentions an un-substitutable MIR TEMP — a `Var` whose name is
/// `_`-prefixed (`_5`, `_10`). Used by `simplify_violation_negation` to drop the
/// `¬V` disjuncts that survive with such a temp (e.g. the `n-1` checked-sub
/// negation `And([Ge(_11,1), Not(Eq(_10, _11-1))])` that vcgen's block-def
/// conjoining pulls onto a bounds violation over the UNRELATED index) — the
/// contract-assumption gate rejects the whole `Or` on those `NonParamVariable`
/// temps.
///
/// CRUCIALLY this must NOT match a `#`-VERSIONED source local (`i#s0_1_s4_0`):
/// that is a real source variable (a loop-induction `i`), gate-acceptable and
/// load-bearing in a synthesized invariant like `i < arr__slice_len`. An earlier
/// over-broad `r1_is_synthetic_local` match (which also spans `contains('#')`)
/// dropped THAT disjunct too, discarding the only real bound and leaving P = the
/// always-false type-range garbage — breaking the piece-#8 length-precond fixture
/// (`r1_length_precond_array`). So this checks `starts_with('_')` ONLY, distinct
/// from `r1_is_synthetic_local` (which the SUBSTITUTION step uses, and which
/// legitimately also spans `#` to resolve `Eq(_temp, i#versioned)` bindings).
///
/// Dropping only genuine-temp disjuncts yields a `P` no weaker than the raw `¬V`
/// the gate saw before the drop (a smaller-or-equal `Or` ⇒ a stronger-or-equal
/// `P`), which is sound for the inductive flip — a caller must establish a
/// stronger `P`, never weaker, so this can only fail-close more, never admit a
/// genuinely-OOB index.
fn r1_formula_mentions_synthetic(
    formula: &trust_types::Formula,
    budget: &mut R1SubstitutionBudget,
) -> Option<bool> {
    let mut worklist = vec![formula];
    while let Some(current) = worklist.pop() {
        if !budget.charge_node() {
            return None;
        }
        if let trust_types::Formula::Var(n, _) = current
            && n.starts_with('_')
        {
            return Some(true);
        }
        let mut child_count = r1_formula_wide_child_count(current);
        if child_count == 0 {
            trust_types::for_each_formula_child(current, |_| child_count += 1);
        }
        if !budget.can_queue(worklist.len(), child_count) {
            return None;
        }
        trust_types::for_each_formula_child(current, |child| worklist.push(child));
    }
    Some(false)
}

/// Push `¬` inward across the comparison / `Or` / `And` shapes a violation formula takes, so
/// the result is a clean predicate rather than a `Not` wrapper around a disjunction. Sound on
/// the total integer/bool orders vcgen's bounds/overflow/div violations range over; a literal
/// `Not(..)` fallback (still in the gate's assumable fragment) covers everything else.
fn negate_inward(v: &trust_types::Formula) -> trust_types::Formula {
    use trust_types::Formula as F;
    match v {
        F::Or(items) => F::And(items.iter().map(negate_inward).collect()),
        F::And(items) => F::Or(items.iter().map(negate_inward).collect()),
        F::Lt(a, b) => F::Ge(a.clone(), b.clone()),
        F::Le(a, b) => F::Gt(a.clone(), b.clone()),
        F::Gt(a, b) => F::Le(a.clone(), b.clone()),
        F::Ge(a, b) => F::Lt(a.clone(), b.clone()),
        F::Not(inner) => (**inner).clone(),
        other => F::Not(Box::new(other.clone())),
    }
}

/// Trust (E step 0): has the R1 harvest's ambient budget TRIPPED?
///
/// Once the step budget is spent it stays spent (`budget_exhausted` saturates the counter at
/// zero) and a passed deadline stays passed, so this non-charging read is true for EVERY VC
/// generated after the trip. Such a VC may have been built by a walk that degraded on the
/// trip (the path-guard, path-definition and block-definition walks still poll; the
/// statement-version oracle, whose trip once rendered every inter-block read BARE, no longer
/// polls itself, but its SSA replacement is built from the polled block-definition
/// extraction, so an oracle built after a trip can still version too few reads): a
/// strengthened VC or a caller-site VC built on a degraded walk can be kernel-valid while
/// misrepresenting the program, and kernel replay cannot tell. This check is therefore NOT
/// made redundant by the SSA oracle. The main pass discards a tripped inventory at its
/// post-generation checkpoint
/// (`preprocessing_budget_exceeded`); the harvesters had no such checkpoint, so a sealed flip
/// could be minted from a truncated VC and then applied by the main pass. Every caller answers
/// `true` with `return None`: the harvest mints nothing, strictly fewer claims.
fn r1_budget_tripped(trace: bool, f_dp: &str, phase: &str) -> bool {
    if !trust_types::verify_budget::exhausted_readonly() {
        return false;
    }
    if trace {
        eprintln!("TRUST_R1_TRACE: {f_dp}: verification budget exhausted {phase} — no flip minted");
    }
    debug!("R1 skip {f_dp}: verification budget exhausted {phase}");
    true
}

/// Trust #540 (R1 2b): try to admit ONE whole-program verdict flip for `f_local`.
/// Returns `(def_path, R1Flip)` iff the router MINTS A SEALED CERTIFICATE — i.e. it
/// kernel-REPLAYED the strengthened proof and every enumerated caller's discharge proof,
/// and EVERY caller of F establishes the gated strengthening P. ANY `None`/`Err`/uncertain
/// step ⇒ `None` (F keeps its honest Failed verdict). All MIR borrows are pre-steal.
#[allow(rustc::untracked_query_information, rustc::potential_query_instability)]
/// Trust (ARGS-FINGERPRINT-READ-1 round 4, 2026-10-08): the R1 oracle's VC
/// generation for one extracted function, optionally under one extra
/// precondition (`generate_vcs_with_extra_precondition`), with the compiler's
/// `DefId`-decided direct-self-call blocks installed
/// (`termination_unmeasured::direct_self_call_identity_blocks`, computed by the
/// caller from the SAME body it extracted `func` from).
///
/// Round 3 installed that set on the production generation and on the bundle
/// regeneration only. R1 regenerates on a fresh frame, so its direct-self
/// termination lanes compared rendered paths alone, and a call into a twin impl
/// that renders the same def path read as a self call there. The set can only
/// withdraw such a classification (a conjunct), and `generate_vcs`'s fresh frame
/// now inherits it from this owner's frame.
///
/// Trust (T3 L4, C07p): the rows are generated into `rows`, the harvest's own VC context
/// (`with_scoped_rows`), through the row oracle.
fn r1_generate_vcs(
    func: &trust_types::VerifiableFunction,
    direct_self_call_blocks: Option<std::collections::BTreeSet<usize>>,
    extra_precondition: Option<&trust_types::Formula>,
    rows: &mut trust_types::vc_context::VcContext,
) -> Vec<trust_types::VerificationCondition> {
    trust_vcgen::with_termination_identity_context(
        &func.def_path,
        None,
        direct_self_call_blocks,
        || match extra_precondition {
            Some(extra) => {
                trust_vcgen::generate_vcs_with_extra_precondition_rows(func, extra, rows)
            }
            None => trust_vcgen::generate_vcs_rows(func, rows),
        },
    )
}

/// Trust (T3 L4, C07p; design D-VC-6): run one short-lived producer of a crate phase (an
/// R1 harvest, an inferred-return admission) with a VC context of its own. Every row it
/// generates is interned into that context through the row oracle; the context lives
/// exactly as long as `work` (what `work` returns cannot borrow it), and its parity counts
/// fold into `parity`, the phase's (`PARITY crate:r1`, `PARITY crate:inferred-return`).
fn with_scoped_rows<R>(
    parity: &mut trust_types::vc_context::ParityTally,
    work: impl FnOnce(&mut trust_types::vc_context::VcContext) -> R,
) -> R {
    let mut rows = trust_types::vc_context::VcContext::new();
    let produced = work(&mut rows);
    parity.fold(&rows);
    produced
}

fn try_harvest_flip<'tcx>(
    tcx: TyCtxt<'tcx>,
    f_local: LocalDefId,
    info: &crate::trust_r1_oracle::CrateCallInfo<'tcx>,
    ay: &trust_router::Router,
    // Trust (T3 L4, C07p; design D-VC-6): this harvest's own VC context
    // (`with_scoped_rows`); every row the harvest generates is interned into it.
    rows: &mut trust_types::vc_context::VcContext,
) -> Option<(String, R1Flip)> {
    use trust_router::strengthen_whole_program::{
        CallerCoverage, CallerDischargeProof, StrengthenedProof, classify_coverage,
        mint_caller_propagation_certificate,
    };

    // Trust (I5): a Clean-origin def has no ordinary MIR pipeline — step (1)'s
    // `mir_drops_elaborated_and_const_checked` walks `mir_borrowck` ->
    // `mir_promoted` -> `mir_built` -> `check_match` -> `typeck`, and `typeck`
    // `span_bug!`s on a def with a synthetic HIR owner and no body. MEASURED:
    // this is the FOURTH such site (`can't type-check body of
    // DefId(..::m::pick)` on `tests/ui/trust/clean_origin_verify_on.rs`), after
    // the backing inventory, the R1 call-graph scan, and the MIR pipeline —
    // it fires because Clean-origin defs are seeded into `mir_keys`, which is
    // exactly the loop `trust_init_r1_attributions` harvests from.
    //
    // Unlike the R1 SCAN (which must stay COMPLETE and therefore reads the
    // gated emission out of `optimized_mir`), the flip HARVEST is opportunistic
    // strengthening of an unproved RUST obligation by charging a precondition
    // to callers. A Clean-origin body's meaning is owned by the kernel
    // faithfulness gate, not by Rust contracts — minting a caller-propagation
    // flip against it would mix two proof authorities — and the emitted
    // projection generates no failing VC to strengthen anyway. Returning `None`
    // mints nothing: fail-closed, strictly fewer claims.
    if crate::clean_origin_mir::is_clean_origin(tcx, f_local) {
        return None;
    }

    // (0) Coverage MUST be provably Total. The signals carry recursive/address-taken/
    //     public/hidden (recursion folded into is_public, so the recursive set passed to
    //     classify_coverage is empty) plus the crate-scan poison in its OWN
    //     `scan_incomplete` channel (NOT in is_public — a poisoned scan says nothing
    //     about external reachability).
    let trace = env_flag_enabled("TRUST_R1_TRACE");
    let f_did = f_local.to_def_id();
    // Trust (R1 completeness #3): a CLOSED-WORLD GENERIC F is coverable per-MONOMORPHIZATION,
    // not by the DefId-level path (its `[u8; N]` stays symbolic un-monomorphized). Route it to
    // the per-mono harvest, which extracts F monomorphized to each observed `A` and requires
    // every caller of each `F::<A>` to establish P for that mono. `generic_mono_coverable`
    // already enforces the SAME closed-world condition R1 uses (a pub-in-lib generic is
    // rejected) plus every per-mono hazard gate.
    if crate::trust_r1_oracle::generic_mono_coverable(tcx, f_local, info) {
        return try_harvest_generic_mono_flip(tcx, f_local, info, ay, rows);
    }
    // Trust (R1 completeness #4 — inductive recursive proof): a RECURSIVE F (self- or
    // mutual-recursion) that meets every OTHER closed-world condition is coverable by an
    // INDUCTIVE-invariant proof, not the DefId path (which rejects any recursion outright).
    // Route it to the inductive harvest: base case (every external caller establishes P) +
    // inductive step (P proved preserved across each intra-SCC recursive call).
    if crate::trust_r1_oracle::recursive_inductive_coverable(tcx, f_local, info) {
        return try_harvest_recursive_flip(tcx, f_local, info, ay, rows);
    }
    let signals = crate::trust_r1_oracle::compute_coverage_signals(tcx, f_local, info);
    let empty_rec: FxHashSet<String> = FxHashSet::default();
    let f_dp = with_no_trimmed_paths!(tcx.def_path_str(f_did));
    if !matches!(classify_coverage(f_dp.as_str(), &empty_rec, &signals), CallerCoverage::Total) {
        // `scan_incomplete` is reported separately from `is_public`: a poisoned
        // crate-wide scan is not evidence that F is externally reachable.
        if trace {
            eprintln!(
                "TRUST_R1_TRACE: {f_dp}: not Total (is_public={} address_taken={} \
                 scan_incomplete={})",
                signals.is_public,
                signals.address_taken,
                signals.scan_incomplete.len()
            );
        }
        debug!(
            "R1 skip {f_dp}: not Total (is_public={} address_taken={} scan_incomplete={})",
            signals.is_public,
            signals.address_taken,
            signals.scan_incomplete.len()
        );
        return None;
    }

    // (1) Extract F (pre-steal) + find the FIRST genuinely-Failed VC.
    let f_steal = tcx.mir_drops_elaborated_and_const_checked(f_local);
    if f_steal.is_stolen() {
        return None;
    }
    let f_body = f_steal.borrow();
    let f_vf = trust_mir_extract::extract_function_with_contract_bundle(tcx, &f_body, None);
    // Trust (ARGS-FINGERPRINT-READ-1 round 4): R1 regenerates F's VCs on a fresh
    // vcgen frame; carry the compiler's `DefId`-decided self-call blocks onto it
    // (`r1_generate_vcs`), so its direct-self termination lanes classify as the
    // production generation does instead of on rendered paths alone.
    let f_self_call_blocks = termination_unmeasured::direct_self_call_identity_blocks(tcx, &f_body);
    let f_vcs = r1_generate_vcs(&f_vf, f_self_call_blocks.clone(), None, rows);
    // Trust (E step 0): a VC generated over a tripped budget may carry bare reads.
    if r1_budget_tripped(trace, &f_dp, "after F's VC generation") {
        return None;
    }
    let mut failed: Option<(trust_types::VerificationCondition, trust_types::VerificationResult)> =
        None;
    for vc in &f_vcs {
        let Some(r) = ay.verify_all(std::slice::from_ref(vc)).into_iter().next().map(|(_, r)| r)
        else {
            continue;
        };
        debug!(
            "R1 {f_dp}: vc '{}' proved={} failed={}",
            vc.kind.description(),
            r.is_proved(),
            r.is_failed()
        );
        if r.is_failed() {
            failed = Some((vc.clone(), r));
            break;
        }
    }
    let Some((v_vc, original_result)) = failed else {
        if trace {
            eprintln!("TRUST_R1_TRACE: {f_dp}: no Failed VC among {} obligation(s)", f_vcs.len());
        }
        debug!("R1 skip {f_dp}: no Failed VC among {} obligation(s)", f_vcs.len());
        return None;
    };
    if trace {
        eprintln!(
            "TRUST_R1_TRACE: {f_dp}: found Failed VC kind='{}' loc={}:{} formula={:?} freevars={:?}",
            v_vc.kind.description(),
            v_vc.location.line_start,
            v_vc.location.col_start,
            v_vc.formula,
            v_vc.formula.free_variables(),
        );
    }

    // (2) Propose P, gate it against F's body namespace.
    //
    // A precondition P is admissible iff (a) it parses, (b) the contract-assumption
    // gate accepts it — meaning every free variable of P is a UNIQUE parameter local of
    // F (so the caller-site substitution σ is well-defined and unambiguous), and (c) the
    // emptiness/witness checks pass. Two candidate sources, tried in order; both pass
    // through the IDENTICAL gate so neither weakens soundness:
    //
    //   * the strengthen proposer (`trust_strengthen::strengthen`) — produces named
    //     proposals like `i < a.len()`; works when source names are recoverable.
    //   * `¬V` directly off the failed violation formula — the WEAKEST sound precondition
    //     that discharges V, expressed over EXACTLY V's variables. This is the general
    //     bounds/overflow/div case: V already references F's parameters by their debug
    //     names (the extractor maps a param operand to its debug name), so `¬V` is a
    //     parameter-only formula the gate accepts. If V references a non-parameter local
    //     (a block temporary), the gate rejects `¬V` ⇒ fail-closed (no flip).
    //
    // Both candidates are CONNECTED to V by construction-or-gate, kernel-certified at the
    // strengthened VC below, and discharged at EVERY caller — so admitting either is the
    // same assume-guarantee soundness obligation. The proposer is preferred only because
    // its named form is more legible; `¬V` is the completeness backstop.
    let analysis = trust_strengthen::analyze_failure(&v_vc, &original_result);
    let proposals =
        trust_strengthen::strengthen(&f_vf.def_path, &f_vf.name, std::slice::from_ref(&analysis));
    let dbg = trust_mir_extract::build_debug_name_multimap(&f_body);
    // Gate one candidate formula `cand` against F's namespace; `Some(gated)` iff admissible.
    let gate_candidate = |cand: trust_types::Formula| -> Option<trust_types::Formula> {
        let mut pv = vec![cand];
        // `None`: this lane gates a SYNTHESIZED candidate precondition, not an
        // authored clause, and has no HIR parameter vector to hand. The forced
        // restatement therefore declines — correct here regardless, since a
        // proposer's candidate is already written in the body's own namespace.
        let reasons = trust_mir_extract::contract_assumption_gate::gate_contract_preconditions(
            &mut pv, &f_vf.body, &dbg, None,
        );
        if !reasons.is_empty() || pv.is_empty() {
            return None;
        }
        pv.pop()
    };
    let p_from_proposer = proposals.iter().find_map(|prop| {
        let trust_strengthen::ProposalKind::AddPrecondition { spec_body } = &prop.kind else {
            return None;
        };
        let Some(parsed) = trust_types::parse_spec_expr(spec_body) else {
            debug!("R1 {f_dp}: proposal spec_body did not parse: {spec_body:?}");
            return None;
        };
        gate_candidate(parsed)
    });
    // `¬V` backstop: negate the failed violation formula. `simplify_negation` folds the
    // double-negation / comparison flips so the result stays in the gate's assumable
    // fragment (a bare comparison, not a literal `Not(...)` wrapper around an `Or`).
    let p_from_neg_v = p_from_proposer
        .is_none()
        .then(|| {
            let neg = simplify_violation_negation(&v_vc.formula)?;
            if trace {
                eprintln!("TRUST_R1_TRACE: {f_dp}: trying P = ¬V = {neg:?}");
            }
            gate_candidate(neg)
        })
        .flatten();
    // Trust (piece #8 — length-relationship preconditions): the loop-bound
    // synthesizer. `¬V` keeps the loop-index LOCAL `i` (non-param, gate-rejected) for
    // a `for i in 0..n { arr[i] }` body, so neither existing source yields the clean
    // `n <= arr__slice_len`. Read the transitive lemma `B <= L` directly off `V`'s
    // range-yield + bounds conjuncts and gate it like any other candidate. Tried LAST
    // (after proposer + `¬V`) so it only fires on the loop-bound family the others miss.
    let p_from_length = (p_from_proposer.is_none() && p_from_neg_v.is_none())
        .then(|| {
            let synth = synthesize_loop_bound_precondition(&v_vc.formula)?;
            if trace {
                eprintln!("TRUST_R1_TRACE: {f_dp}: trying P = loop-bound = {synth:?}");
            }
            gate_candidate(synth)
        })
        .flatten();
    let p_opt = p_from_proposer.or(p_from_neg_v).or(p_from_length);
    let Some(p) = p_opt else {
        if trace {
            eprintln!(
                "TRUST_R1_TRACE: {f_dp}: no usable P ({} proposal(s), ¬V rejected too)",
                proposals.len()
            );
        }
        debug!("R1 skip {f_dp}: no usable P ({} proposal(s))", proposals.len());
        return None;
    };
    if trace {
        eprintln!("TRUST_R1_TRACE: {f_dp}: proposed P = {p:?}");
    }

    // (3) Strengthened, kernel-Certified verdict for F's SAME VC (location+kind).
    let s_vcs = r1_generate_vcs(&f_vf, f_self_call_blocks, Some(&p), rows);
    // Trust (E step 0): never certify a strengthened VC built over a tripped budget.
    if r1_budget_tripped(trace, &f_dp, "after the strengthened VC's generation") {
        return None;
    }
    // VcKind has no PartialEq (#[non_exhaustive]); match on (location, kind-description).
    let Some(s_vc) = s_vcs
        .into_iter()
        .find(|c| c.location == v_vc.location && c.kind.description() == v_vc.kind.description())
    else {
        if trace {
            eprintln!("TRUST_R1_TRACE: {f_dp}: no strengthened VC matching V (loc/kind)");
        }
        debug!("R1 skip {f_dp}: no strengthened VC matching V (loc/kind)");
        return None;
    };
    let sv_ff = format!("{:?}", s_vc.formula);
    debug!("R1 {f_dp}: strengthened VC formula={}", &sv_ff[..sv_ff.len().min(300)]);
    // KEEP the kernel certificate. The pre-audit code called `certify_vc` only for
    // its `is_none()` and then handed the gate a synthetic public `Proved` label —
    // which is precisely why the gate had to be hard-blocked (a label is not a
    // proof). The evidence now travels to the mint, which REPLAYS it.
    let Some(s_evidence) = trust_certify::certify_vc(&s_vc) else {
        if trace {
            eprintln!("TRUST_R1_TRACE: {f_dp}: strengthened VC NOT kernel-certified");
        }
        debug!("R1 skip {f_dp}: strengthened VC not kernel-certified");
        return None;
    };

    // (4) Per caller C of F: build the REAL guard-aware discharge obligations.
    // Derive F's param names from the body ALREADY borrowed above (f_body). Do NOT call
    // callee_param_names(tcx, f_did): it routes through tcx.optimized_mir(f_did), which
    // STEALS mir_drops_elaborated_and_const_checked(f_did) — the exact Steal f_body holds
    // a live borrow of at this pre-steal seam (would abort). var_debug_info names match.
    let f_param_names = mir_param_names(&f_body);
    // Trust (piece #8): F's param TYPES, so the σ length-renderer at each caller can
    // detect slice/array formals and bind their `<formal>__slice_len`.
    let f_param_types = mir_param_types_from_vf(&f_vf);
    let Some(callers) = info.callers.get(&f_did) else {
        if trace {
            eprintln!("TRUST_R1_TRACE: {f_dp}: no recorded callers");
        }
        debug!("R1 skip {f_dp}: no recorded callers");
        return None;
    };
    if trace {
        eprintln!(
            "TRUST_R1_TRACE: {f_dp}: {} recorded caller(s); params={:?}",
            callers.len(),
            f_param_names
        );
    }
    // Own the per-site (VC, evidence) pairs so the borrows outlive the mint call.
    let mut site_evidence: Vec<(
        String,
        trust_types::VerificationCondition,
        trust_types::Formula,
        Vec<trust_types::Formula>,
        trust_ir::ProofEvidence,
    )> = Vec::new();
    // Every caller the ORACLE enumerated. The mint cross-checks the discharged set
    // against this, so a caller dropped anywhere in this loop is caught (rather
    // than silently yielding an unsound flip).
    let mut enumerated_callers: Vec<String> = Vec::new();
    for &c_did in callers {
        let c_local = c_did.as_local()?;
        if !matches!(tcx.def_kind(c_did), DefKind::Fn | DefKind::AssocFn) {
            return None;
        }
        let c_steal = tcx.mir_drops_elaborated_and_const_checked(c_local);
        if c_steal.is_stolen() {
            return None;
        }
        let c_body = c_steal.borrow();
        let c_vf = trust_mir_extract::extract_function_with_contract_bundle(tcx, &c_body, None);
        enumerated_callers.push(c_vf.def_path.clone());

        // One-entry DB: F keyed by its def_path, carrying ONLY the strengthening P.
        let mut db = trust_vcgen::SummaryDatabase::new();
        db.insert(
            trust_vcgen::FunctionSummary::new(f_vf.def_path.clone())
                .with_param_names(f_param_names.clone())
                .with_param_types(f_param_types.clone())
                .with_precondition(p.clone()),
        );

        let site_vcs =
            trust_vcgen::generate_callsite_precondition_vcs_attributed_rows(&c_vf, &db, rows);
        // Trust (E step 0): never certify a caller-site VC built over a tripped budget.
        if r1_budget_tripped(trace, &f_dp, "after a caller's site-VC generation") {
            return None;
        }
        let mut produced_for_c = 0usize;
        for (vc, assumption_substituted, allowed_guards) in site_vcs {
            let trust_types::VcKind::Precondition { callee } = &vc.kind else {
                return None; // arity mismatch / unsupported at an F call ⇒ skip F
            };
            if *callee != f_vf.def_path {
                continue;
            }
            produced_for_c += 1;
            // KEEP the certificate (see the strengthened step above) — the mint
            // replays it through the kernel.
            let Some(evidence) = trust_certify::certify_vc(&vc) else {
                if trace {
                    eprintln!(
                        "TRUST_R1_TRACE: {f_dp}: caller {} site NOT certified (¬P[σ] SAT) formula={:?}",
                        c_vf.def_path, vc.formula
                    );
                }
                debug!("R1 skip {f_dp}: caller {} site not certified (¬P[σ] SAT)", c_vf.def_path);
                return None;
            };
            site_evidence.push((
                c_vf.def_path.clone(),
                vc,
                assumption_substituted, // P[σ], the producer's independent pre-image
                allowed_guards,
                evidence,
            ));
        }
        if produced_for_c == 0 {
            if trace {
                eprintln!(
                    "TRUST_R1_TRACE: {f_dp}: caller {} produced no F-obligation",
                    c_vf.def_path
                );
            }
            debug!("R1 skip {f_dp}: caller {} produced no F-obligation", c_vf.def_path);
            return None; // a recorded caller with no F-obligation can't be discharged
        }
    }
    if trace {
        eprintln!(
            "TRUST_R1_TRACE: {f_dp}: built {} caller obligation(s) — minting sealed certificate",
            site_evidence.len()
        );
    }
    let caller_proofs: Vec<CallerDischargeProof<'_>> = site_evidence
        .iter()
        .map(|(caller, vc, assumption_substituted, allowed_guards, evidence)| {
            CallerDischargeProof {
                caller: caller.clone(),
                call_site: vc.location.clone(),
                assumption_substituted: assumption_substituted.clone(),
                vc,
                allowed_guards: allowed_guards.clone(),
                evidence,
            }
        })
        .collect();

    // (5) THE decision — mint the sealed certificate. This REPLAYS the strengthened
    // proof and every call-site proof through the clean CIC kernel; no public
    // assurance label is consulted anywhere. Ok ⇒ record the flip keyed by F's
    // def_path (== the per-body key).
    // Trust (E step 0): the budget is sticky, so this one read covers every VC above.
    if r1_budget_tripped(trace, &f_dp, "before the sealed mint") {
        return None;
    }
    match mint_caller_propagation_certificate(
        &v_vc,
        &original_result,
        &p,
        &f_vf.preconditions,
        &StrengthenedProof { vc: &s_vc, evidence: &s_evidence },
        &CallerCoverage::Total,
        &enumerated_callers,
        &caller_proofs,
    ) {
        // Trust (E step 0): a trip INSIDE the mint discards its seal too.
        Ok(_) if r1_budget_tripped(trace, &f_dp, "during the sealed mint") => None,
        Ok(sealed) => {
            if trace {
                eprintln!("TRUST_R1_TRACE: {f_dp}: ADMITTED FLIP (sealed {})", sealed.digest());
            }
            Some((
                f_vf.def_path.clone(),
                R1Flip {
                    location: v_vc.location.clone(),
                    kind_desc: v_vc.kind.description(),
                    sealed,
                },
            ))
        }
        Err(e) => {
            if trace {
                eprintln!("TRUST_R1_TRACE: {f_dp}: sealed-certificate mint REJECTED: {e:?}");
            }
            debug!("R1 skip {f_dp}: sealed-certificate mint rejected: {e:?}");
            None
        }
    }
}

/// Trust #540 (R1 completeness #3): harvest ONE verdict flip for a CLOSED-WORLD GENERIC F,
/// keyed per-MONOMORPHIZATION. The DefId-level `try_harvest_flip` cannot handle a generic —
/// its un-monomorphized body carries a symbolic `[u8; N]` whose bounds VC's negation `i < N`
/// still mentions the symbolic `N`, so `¬P[σ]` never certifies. Here we instead, for EVERY
/// in-crate monomorphization `F::<A>` observed at a call site:
///   * extract F's body MONOMORPHIZED to `A` (so `[u8; N]` becomes e.g. `[u8; 4]` and the
///     bounds VC is concrete `i >= 4`);
///   * infer P (`i < 4`), kernel-certify F-safe-under-P for this mono;
///   * require that EVERY caller of THIS mono establishes P for it, and MINT a sealed,
///     kernel-replayed certificate per mono (`mint_caller_propagation_certificate`).
/// A flip is admitted ONLY IF *every* observed mono passes all of the above — because the
/// single generic body (which `apply_r1_flips` runs on) has ONE Failed bounds VC covering all
/// monos, so flipping it asserts safety for all of them. Any mono that fails ⇒ NO flip (F keeps
/// its honest Failed verdict). SOUND: `generic_mono_coverable` (the caller's gate) already
/// established F is closed in-crate, so the observed monos are ALL the monos there are.
#[allow(rustc::untracked_query_information, rustc::potential_query_instability)]
fn try_harvest_generic_mono_flip<'tcx>(
    tcx: TyCtxt<'tcx>,
    f_local: LocalDefId,
    info: &crate::trust_r1_oracle::CrateCallInfo<'tcx>,
    ay: &trust_router::Router,
    // Trust (T3 L4, C07p; design D-VC-6): this harvest's own VC context
    // (`with_scoped_rows`); every row the harvest generates is interned into it.
    rows: &mut trust_types::vc_context::VcContext,
) -> Option<(String, R1Flip)> {
    use trust_router::strengthen_whole_program::{
        CallerCoverage, CallerDischargeProof, StrengthenedProof,
        mint_caller_propagation_certificate, seal_generic_flip,
    };
    let trace = env_flag_enabled("TRUST_R1_TRACE");
    let f_did = f_local.to_def_id();
    let f_dp = with_no_trimmed_paths!(tcx.def_path_str(f_did));
    // One sealed certificate per observed monomorphization; `seal_generic_flip`
    // admits the generic flip only if EVERY mono produced one.
    let mut mono_certs: Vec<
        trust_router::strengthen_whole_program::SealedCallerPropagationCertificate,
    > = Vec::new();

    // The generic body (pre-steal). We extract it monomorphized per mono; also used to key
    // the flip's def_path and (via source spans) its location, which is mono-independent.
    let f_steal = tcx.mir_drops_elaborated_and_const_checked(f_local);
    if f_steal.is_stolen() {
        return None;
    }
    let generic_body = f_steal.borrow();
    let f_def_path = trust_mir_extract::safe_def_path_str(tcx, f_did);

    // Group the observed call sites by monomorphization (resolved `args`). Each distinct
    // `args` is one mono `F::<A>`; its callers are the sites carrying those args.
    let sites = info.mono_call_sites.get(&f_did)?;
    if sites.is_empty() {
        return None;
    }
    // Distinct monos, in first-seen order (deterministic).
    let mut monos: Vec<ty::GenericArgs<'tcx>> = Vec::new();
    for s in sites {
        if !monos.iter().any(|m| *m == s.args) {
            monos.push(s.args);
        }
    }
    if trace {
        eprintln!(
            "TRUST_R1_TRACE: {f_dp}: GENERIC per-mono harvest — {} distinct mono(s), {} site(s)",
            monos.len(),
            sites.len()
        );
    }

    // The flip we will emit if EVERY mono discharges. All monos share the same generic-body
    // source location + kind (the single `a[i]` operation), so one flip covers them all. We
    // record the (location, kind) from the FIRST mono and require every later mono to agree.
    let mut agreed_flip: Option<(trust_types::SourceSpan, String)> = None;

    for &margs in &monos {
        // Trust (2026-09-09, MEASURED on first-party/ty's vendored `clap_builder`): a
        // "mono" is only a mono if its args are CONCRETE. An observed call site inside
        // a generic caller carries that caller's params — clap's
        // `extend_context_unchecked<const N>` forwarding `[(K, V); N]` to
        // `extend_unchecked(impl IntoIterator)` observed the callee with
        // `I = [(K, V); N]` — and normalizing F's body under F's OWN typing env then
        // asks the trait solver for the type of a const F never declared:
        // `find_const_ty_from_env` → `bug!` (rustc_middle/src/ty/sty.rs:365), an ICE
        // in a dependency crate under every policy. Such a site is not evidence for a
        // per-mono closed-world claim anyway; decline the whole harvest (no flip).
        // Pinned by `tests/ui/trust/generic_mono_harvest_rejects_non_concrete_args.rs`.
        if margs.has_non_region_param() || margs.has_non_region_infer() {
            if trace {
                eprintln!(
                    "TRUST_R1_TRACE: {f_dp}: mono {margs:?} is not concrete (a caller's own \
                     generics) — reject"
                );
            }
            return None;
        }
        // Resolve + monomorphize F to this mono's args, then extract the concrete body.
        let Ok(Some(instance)) =
            ty::Instance::try_resolve(tcx, ty::TypingEnv::post_analysis(tcx, f_did), f_did, margs)
        else {
            if trace {
                eprintln!("TRUST_R1_TRACE: {f_dp}: mono {margs:?} did not resolve — reject");
            }
            return None;
        };
        let Ok(mono_body) = instance.try_instantiate_mir_and_normalize_erasing_regions(
            tcx,
            ty::TypingEnv::post_analysis(tcx, f_did),
            ty::EarlyBinder::bind(tcx, generic_body.clone()),
        ) else {
            if trace {
                eprintln!("TRUST_R1_TRACE: {f_dp}: mono {margs:?} body normalize failed — reject");
            }
            return None;
        };

        let f_vf = trust_mir_extract::extract_function_with_contract_bundle(tcx, &mono_body, None);
        // Trust (ARGS-FINGERPRINT-READ-1 round 4): see `r1_generate_vcs`.
        let f_self_call_blocks =
            termination_unmeasured::direct_self_call_identity_blocks(tcx, &mono_body);
        let f_vcs = r1_generate_vcs(&f_vf, f_self_call_blocks.clone(), None, rows);
        // Trust (E step 0): a VC generated over a tripped budget may carry bare reads.
        if r1_budget_tripped(trace, &f_dp, "after a mono's VC generation") {
            return None;
        }
        // Find the FIRST genuinely-Failed VC of THIS mono.
        let mut failed: Option<(
            trust_types::VerificationCondition,
            trust_types::VerificationResult,
        )> = None;
        for vc in &f_vcs {
            let Some(r) =
                ay.verify_all(std::slice::from_ref(vc)).into_iter().next().map(|(_, r)| r)
            else {
                continue;
            };
            if r.is_failed() {
                failed = Some((vc.clone(), r));
                break;
            }
        }
        let Some((v_vc, original_result)) = failed else {
            // This mono has NO Failed VC (already safe unconditionally). Nothing to flip
            // FOR THIS MONO — but the generic body's VC is only flippable if it is genuinely
            // Failed and we can point each flip at it. A mono with no Failed VC cannot pin the
            // flip location, and (more importantly) means this mono contributes no obligation
            // constraining the shared generic VC. To stay sound and simple: require EVERY mono
            // to exhibit the SAME failed operation (same location/kind). If a mono is already
            // safe, we cannot confirm it corresponds to the generic Failed VC ⇒ reject.
            if trace {
                eprintln!(
                    "TRUST_R1_TRACE: {f_dp}: mono {margs:?} has no Failed VC ({} obligation(s)) — reject to stay sound",
                    f_vcs.len()
                );
            }
            return None;
        };

        // Propose P for this mono (concrete — `[u8; N]` is now `[u8; A]`). Gate against F's
        // mono-body namespace, IDENTICAL machinery to the DefId path.
        let dbg = trust_mir_extract::build_debug_name_multimap(&mono_body);
        let gate_candidate = |cand: trust_types::Formula| -> Option<trust_types::Formula> {
            let mut pv = vec![cand];
            // `None`: this lane gates a SYNTHESIZED candidate precondition, not an
            // authored clause, and has no HIR parameter vector to hand. The forced
            // restatement therefore declines — correct here regardless, since a
            // proposer's candidate is already written in the body's own namespace.
            let reasons = trust_mir_extract::contract_assumption_gate::gate_contract_preconditions(
                &mut pv, &f_vf.body, &dbg, None,
            );
            if !reasons.is_empty() || pv.is_empty() {
                return None;
            }
            pv.pop()
        };
        let analysis = trust_strengthen::analyze_failure(&v_vc, &original_result);
        let proposals = trust_strengthen::strengthen(
            &f_vf.def_path,
            &f_vf.name,
            std::slice::from_ref(&analysis),
        );
        let p_from_proposer = proposals.iter().find_map(|prop| {
            let trust_strengthen::ProposalKind::AddPrecondition { spec_body } = &prop.kind else {
                return None;
            };
            let parsed = trust_types::parse_spec_expr(spec_body)?;
            gate_candidate(parsed)
        });
        let p = match p_from_proposer
            .or_else(|| {
                simplify_violation_negation(&v_vc.formula)
                    .and_then(|candidate| gate_candidate(candidate))
            })
            // Trust (piece #8): loop-bound length synthesizer, same as the DefId path.
            .or_else(|| synthesize_loop_bound_precondition(&v_vc.formula).and_then(gate_candidate))
        {
            Some(p) => p,
            None => {
                if trace {
                    eprintln!("TRUST_R1_TRACE: {f_dp}: mono {margs:?} no usable P — reject");
                }
                return None;
            }
        };
        if trace {
            eprintln!("TRUST_R1_TRACE: {f_dp}: mono {margs:?} proposed P = {p:?}");
        }

        // Strengthened, kernel-Certified verdict for THIS mono's SAME VC (location+kind).
        let s_vcs = r1_generate_vcs(&f_vf, f_self_call_blocks, Some(&p), rows);
        // Trust (E step 0): never certify a strengthened VC built over a tripped budget.
        if r1_budget_tripped(trace, &f_dp, "after a mono's strengthened VC generation") {
            return None;
        }
        let Some(s_vc) = s_vcs.into_iter().find(|c| {
            c.location == v_vc.location && c.kind.description() == v_vc.kind.description()
        }) else {
            return None;
        };
        let Some(s_evidence) = trust_certify::certify_vc(&s_vc) else {
            if trace {
                eprintln!(
                    "TRUST_R1_TRACE: {f_dp}: mono {margs:?} strengthened VC NOT certified — reject"
                );
            }
            return None;
        };

        // Per caller of THIS MONO: build SITE-PRECISE guard-aware discharge obligations. A
        // caller may call SEVERAL monos of F (`idx::<4>(a,3); idx::<8>(b,5)`), and each site
        // is discharged under ITS OWN mono's P. So we key on the exact call `(line,col)`: this
        // mono's sites in caller C are exactly the `mono_call_sites` whose `args == margs` and
        // `caller == C`, and we require EACH such site's producer VC to certify (and EVERY one
        // to appear). VCs at OTHER sites (a different mono) are IGNORED here — they are handled
        // when that mono is processed. This is what prevents cross-mono conflation.
        let f_param_names = mir_param_names(&mono_body);
        // Trust (piece #8): this mono's param types for σ length-rendering.
        let f_param_types = mir_param_types_from_vf(&f_vf);
        // Owned per-site (caller, VC, P[σ], guards, kernel evidence) for THIS mono; the
        // borrows in `caller_proofs` below must outlive the mint call.
        #[allow(clippy::type_complexity)]
        let mut site_evidence: Vec<(
            String,
            trust_types::VerificationCondition,
            trust_types::Formula,
            Vec<trust_types::Formula>,
            trust_ir::ProofEvidence,
        )> = Vec::new();
        let mut enumerated_callers: Vec<String> = Vec::new();
        // caller DefId -> set of (line,col) call sites of THIS mono in that caller.
        let mut mono_sites_by_caller: FxHashMap<DefId, FxHashSet<(u32, u32)>> =
            FxHashMap::default();
        for s in sites {
            if s.args == margs {
                mono_sites_by_caller.entry(s.caller).or_default().insert(s.call_line_col);
            }
        }
        if mono_sites_by_caller.is_empty() {
            return None;
        }
        for (c_did, want_sites) in &mono_sites_by_caller {
            let c_did = *c_did;
            let c_local = c_did.as_local()?;
            if !matches!(tcx.def_kind(c_did), DefKind::Fn | DefKind::AssocFn) {
                return None;
            }
            let c_steal = tcx.mir_drops_elaborated_and_const_checked(c_local);
            if c_steal.is_stolen() {
                return None;
            }
            let c_body = c_steal.borrow();
            // The caller's actuals at the F call site are concrete (e.g. a caller
            // `h(a: &[u8; 4])` calling `idx(a, 3)`). The caller is typically non-generic (the
            // common case) — a plain extraction. `generic_mono_coverable`/`mono_unresolved`
            // already fail-closed any still-generic caller whose call site did not resolve, so
            // a caller reaching here resolved to a concrete mono of F.
            let c_vf = trust_mir_extract::extract_function_with_contract_bundle(tcx, &c_body, None);

            // One-entry DB: F (by its def_path — mono-independent) carrying ONLY P for this mono.
            let mut db = trust_vcgen::SummaryDatabase::new();
            db.insert(
                trust_vcgen::FunctionSummary::new(f_def_path.clone())
                    .with_param_names(f_param_names.clone())
                    .with_param_types(f_param_types.clone())
                    .with_precondition(p.clone()),
            );
            let site_vcs =
                trust_vcgen::generate_callsite_precondition_vcs_attributed_rows(&c_vf, &db, rows);
            // Trust (E step 0): never certify a caller-site VC built over a tripped budget.
            if r1_budget_tripped(trace, &f_dp, "after a mono caller's site-VC generation") {
                return None;
            }
            // Track which of THIS mono's wanted sites we actually saw + certified.
            let mut covered: FxHashSet<(u32, u32)> = FxHashSet::default();
            for (vc, assumption_substituted, allowed_guards) in site_vcs {
                let trust_types::VcKind::Precondition { callee } = &vc.kind else {
                    return None;
                };
                if *callee != f_def_path {
                    continue;
                }
                let site = (vc.location.line_start, vc.location.col_start);
                // Only THIS mono's sites are our obligation. A VC at a site belonging to a
                // DIFFERENT mono of F (a different `(line,col)`) is skipped — it will be
                // discharged under its own mono's P. This is the anti-conflation guard.
                if !want_sites.contains(&site) {
                    continue;
                }
                let Some(evidence) = trust_certify::certify_vc(&vc) else {
                    if trace {
                        eprintln!(
                            "TRUST_R1_TRACE: {f_dp}: mono {margs:?} caller {} site {site:?} NOT certified (¬P[σ] SAT) formula={:?}",
                            c_vf.def_path, vc.formula
                        );
                    }
                    return None;
                };
                covered.insert(site);
                enumerated_callers.push(c_vf.def_path.clone());
                site_evidence.push((
                    c_vf.def_path.clone(),
                    vc,
                    assumption_substituted,
                    allowed_guards,
                    evidence,
                ));
            }
            // Every wanted site of this mono MUST have produced (and certified) an obligation.
            // A wanted site the producer did not emit an F-precondition VC for is undischarged
            // ⇒ reject (fail-closed). This closes the "a recorded site yields no obligation"
            // hole per mono, exactly as the DefId path does per caller.
            if &covered != want_sites {
                if trace {
                    eprintln!(
                        "TRUST_R1_TRACE: {f_dp}: mono {margs:?} caller {} covered {covered:?} != wanted {want_sites:?} — reject",
                        c_vf.def_path
                    );
                }
                return None;
            }
        }

        // THE decision for this mono — mint a sealed certificate (kernel-replays the
        // strengthened proof and every call-site proof). Any Err ⇒ the whole generic F
        // is not flippable.
        let caller_proofs: Vec<CallerDischargeProof<'_>> = site_evidence
            .iter()
            .map(|(caller, vc, assumption_substituted, allowed_guards, evidence)| {
                CallerDischargeProof {
                    caller: caller.clone(),
                    call_site: vc.location.clone(),
                    assumption_substituted: assumption_substituted.clone(),
                    vc,
                    allowed_guards: allowed_guards.clone(),
                    evidence,
                }
            })
            .collect();
        enumerated_callers.sort();
        enumerated_callers.dedup();
        // Trust (E step 0): the budget is sticky, so this one read covers every VC above.
        if r1_budget_tripped(trace, &f_dp, "before a mono's sealed mint") {
            return None;
        }
        match mint_caller_propagation_certificate(
            &v_vc,
            &original_result,
            &p,
            &f_vf.preconditions,
            &StrengthenedProof { vc: &s_vc, evidence: &s_evidence },
            &CallerCoverage::Total,
            &enumerated_callers,
            &caller_proofs,
        ) {
            // Trust (E step 0): a trip INSIDE the mint discards its seal too.
            Ok(_) if r1_budget_tripped(trace, &f_dp, "during a mono's sealed mint") => {
                return None;
            }
            Ok(sealed) => mono_certs.push(sealed),
            Err(e) => {
                if trace {
                    eprintln!("TRUST_R1_TRACE: {f_dp}: mono {margs:?} mint REJECTED: {e:?}");
                }
                return None;
            }
        }

        // This mono discharged. Record/confirm the shared flip key (location + kind). All
        // monos must agree on the same generic-body operation — a divergence means the monos
        // fail at DIFFERENT operations, which one generic VC cannot faithfully represent, so
        // reject to stay sound.
        let key = (v_vc.location.clone(), v_vc.kind.description());
        match &agreed_flip {
            None => agreed_flip = Some(key),
            Some(existing) if *existing == key => {}
            Some(_) => {
                if trace {
                    eprintln!(
                        "TRUST_R1_TRACE: {f_dp}: mono {margs:?} Failed VC key differs from a prior mono — reject"
                    );
                }
                return None;
            }
        }
    }

    let (location, kind_desc) = agreed_flip?;
    if trace {
        eprintln!(
            "TRUST_R1_TRACE: {f_dp}: ADMITTED GENERIC FLIP over {} mono(s) at {}:{}",
            monos.len(),
            location.line_start,
            location.col_start
        );
    }
    // Every mono sealed. `seal_generic_flip` re-checks they all pin the SAME source
    // operation before it will vouch for the single generic-body obligation.
    let sealed = seal_generic_flip(mono_certs)
        .map_err(|e| {
            if trace {
                eprintln!("TRUST_R1_TRACE: {f_dp}: seal_generic_flip REJECTED: {e:?}");
            }
        })
        .ok()?;
    Some((f_def_path, R1Flip { location, kind_desc, sealed }))
}

/// Trust #540 (R1 completeness #4): the per-SCC-member data an inductive recursive proof
/// needs — the extracted body IR (`vf`), its param names/types, its ONE genuinely-Failed VC
/// (`v_vc`) with its original verdict, the gated inductive invariant `P` (over this
/// member's own params), and the strengthened obligation `V ∧ P` WITH its kernel
/// certificate (the evidence travels to the inductive mint, which REPLAYS it). Built once
/// per member; consumed by both the base-case caller check and the inductive-step
/// recursive-call check.
struct RecursiveMember {
    did: DefId,
    /// This member's extracted IR (the `VerifiableFunction`). Extracted ONCE from the owned
    /// clone of the member's elaborated MIR body at construction; the raw body is not retained
    /// (everything downstream — call-site VC generation, param names — reads the IR).
    vf: trust_types::VerifiableFunction,
    def_path: String,
    param_names: Vec<String>,
    /// Param types for the σ length-renderer at each caller (slice/array formals
    /// bind `<formal>__slice_len`), same as the DefId and per-mono paths.
    param_types: Vec<trust_types::Ty>,
    v_vc: trust_types::VerificationCondition,
    original_result: trust_types::VerificationResult,
    p: trust_types::Formula,
    /// The strengthened obligation (`V ∧ P`) at V's own kind/location …
    s_vc: trust_types::VerificationCondition,
    /// … and its clean-kernel certificate, KEPT (not consumed for a boolean) so
    /// the inductive mint can kernel-REPLAY it.
    s_evidence: trust_ir::ProofEvidence,
}

/// Trust #540 (R1 completeness #4): one SCC member's owned discharge-evidence rows,
/// accumulated by the harvest and borrowed by the mint call. `base`/`ind` rows are
/// `(caller def_path, obligation VC, P[σ], allowed guards, kernel evidence)`.
#[derive(Default)]
struct RecursiveMemberEvidence {
    /// Oracle-enumerated EXTERNAL (non-SCC) callers of this member.
    enumerated_external: Vec<String>,
    /// External callers whose EVERY call site to this member establishes `P`
    /// by interval dominance, so trust-vcgen mints no base-case VC (F5).
    /// Carries the caller body so the MINT can re-derive the verdict against a
    /// fresh summary containing the exact member invariant, instead of trusting
    /// this record or a producer-supplied summary database.
    dominated: Vec<(String, trust_types::VerifiableFunction)>,
    /// Per external call site: the UNCONDITIONAL discharge `¬P[σ]` + evidence.
    #[allow(clippy::type_complexity)]
    base: Vec<(
        String,
        trust_types::VerificationCondition,
        trust_types::Formula,
        Vec<trust_types::Formula>,
        trust_ir::ProofEvidence,
    )>,
    /// Oracle-enumerated INTRA-SCC callers (SCC members calling this member).
    enumerated_scc: Vec<String>,
    /// Per intra-SCC call site: the preservation discharge
    /// `P_caller ∧ guards ∧ ¬P[σ]` + evidence.
    #[allow(clippy::type_complexity)]
    ind: Vec<(
        String,
        trust_types::VerificationCondition,
        trust_types::Formula,
        Vec<trust_types::Formula>,
        trust_ir::ProofEvidence,
    )>,
}

/// Compare the oracle's call-site inventory with the VC producer's attributed
/// rows as multisets. Multiplicity is load-bearing: if one caller invokes the
/// same recursive member twice, one produced row cannot discharge both sites.
/// A removal walk keeps the comparison order-independent without introducing
/// a hash-based identity or truncating the full source span.
fn exact_callsite_span_multiset_matches(
    expected: &[trust_types::SourceSpan],
    produced: &[trust_types::SourceSpan],
) -> bool {
    if expected.len() != produced.len() {
        return false;
    }
    let mut unmatched = expected.to_vec();
    for site in produced {
        let Some(index) = unmatched.iter().position(|candidate| candidate == site) else {
            return false;
        };
        unmatched.swap_remove(index);
    }
    unmatched.is_empty()
}

/// Trust #540 (R1 completeness #4): harvest ONE verdict flip for a RECURSIVE F (self- or
/// mutual-recursion) by a SOUND INDUCTIVE-INVARIANT proof. The DefId path rejects any
/// recursion outright; here we instead prove F's inferred precondition `P` is a genuine
/// INDUCTIVE invariant of the whole call cycle:
///
///   * BASE CASE — every EXTERNAL (outside-the-SCC) caller of each SCC member M establishes
///     M's precondition P_M. This is the STANDARD R1 caller-obligation check (`¬P_M[σ]`
///     certified UNSAT at each external call site), run WITHOUT any inductive hypothesis.
///   * INDUCTIVE STEP — assume P_M holds on M's entry (the inductive hypothesis), then at
///     EACH intra-SCC recursive call `M → N(args)` prove `P_N[args]` holds under the path
///     condition reaching that call: the obligation `And([P_M, path_guards…, ¬P_N[σ]])`
///     must be kernel-certified UNSAT (i.e. `P_M ∧ path_guards ⇒ P_N[σ]`). A REAL solver
///     discharge — never assumed, never structural. If ANY inductive VC is not certified
///     ⇒ REJECT the whole SCC (fail-closed).
///
/// A flip is admitted ONLY when the WHOLE SCC is jointly inductive AND every external caller
/// of every member establishes the relevant P. We then return the flip for THIS F (the other
/// members get their own flip when the `mir_keys` loop reaches them — each recomputes the
/// same joint proof, which is idempotent and cheap). Any `None`/uncertain step ⇒ no flip
/// (every member keeps its honest Failed verdict). SOUNDNESS: `recursive_inductive_coverable`
/// (the caller's gate) already established F and every SCC member is closed-world coverable
/// (private/exactly-bin, not address-taken, non-generic, non-trait-dispatch, no hidden edge,
/// scan complete), so the external callers we enumerate are ALL the non-recursive entries.
/// SEALED-EVIDENCE ADMISSION (2026-07-14 restoration, completed). The 72ada1163c
/// audit correctly stopped this lane while it flipped on public assurance labels,
/// and the 2026-07-14 restoration kept it fail-closed pending its OWN evidence
/// carrier — the base-case `SealedCallerPropagationCertificate` contract ("every
/// caller establishes P, unconditionally") does not cover an intra-SCC discharge,
/// which establishes `P_N[σ]` only UNDER the inductive hypothesis `P_M`. That
/// carrier now exists: `mint_inductive_caller_propagation_certificate` (in
/// `trust_router::strengthen_whole_program`, next to the direct mint) re-checks
/// the whole induction structure in the pure core — exact caller sets per member,
/// hypothesis hygiene (a discharge may assume ONLY its own member's `P`),
/// base-case grounding — and kernel-REPLAYS every certificate it binds: (a) each
/// member's strengthened proof, (b) each external caller's unconditional
/// discharge, and (c) each intra-SCC call's `P_M ∧ guards ⇒ P_N[σ]` preservation
/// proof. Its doc carries the written soundness argument for the induction. Any
/// replay or structural failure ⇒ no token ⇒ no flip (fail-closed). See
/// docs/design-notes/2026-07-14-r1-authority-restoration.md.
#[allow(rustc::untracked_query_information, rustc::potential_query_instability)]
fn try_harvest_recursive_flip<'tcx>(
    tcx: TyCtxt<'tcx>,
    f_local: LocalDefId,
    info: &crate::trust_r1_oracle::CrateCallInfo<'tcx>,
    ay: &trust_router::Router,
    // Trust (T3 L4, C07p; design D-VC-6): this harvest's own VC context
    // (`with_scoped_rows`); every row the harvest generates is interned into it.
    rows: &mut trust_types::vc_context::VcContext,
) -> Option<(String, R1Flip)> {
    use trust_router::strengthen_whole_program::{
        CallerDischargeProof, InductiveMemberProof, InductiveStepProof, StrengthenedProof,
        mint_inductive_caller_propagation_certificate,
    };
    let trace = env_flag_enabled("TRUST_R1_TRACE");
    let f_did = f_local.to_def_id();
    let f_dp = with_no_trimmed_paths!(tcx.def_path_str(f_did));

    // The full call-cycle membership set for F (the whole mutual-recursion SCC, or `{F}`
    // for a self-loop). `recursive_inductive_coverable` guaranteed this is present and that
    // every member is a local, closed-world, non-generic ordinary/assoc fn.
    let scc = info.recursive_scc.get(&f_did)?;
    if scc.is_empty() {
        return None;
    }
    // Stable member order so both query demand and proof construction are reproducible.
    let members: Vec<DefId> = tcx.with_stable_hashing_context(|mut hcx| {
        scc.to_sorted(&mut hcx, true).into_iter().copied().collect()
    });
    if trace {
        eprintln!(
            "TRUST_R1_TRACE: {f_dp}: INDUCTIVE recursive harvest — SCC has {} member(s)",
            members.len()
        );
    }

    // Extract each member (pre-steal), find its ONE genuinely-Failed VC, infer + gate +
    // kernel-certify its inductive invariant P (F-safe-under-P for its OWN body), KEEPING
    // the kernel certificate for the mint's replay. Any member with no Failed VC, or no
    // usable/certified P, ⇒ reject the whole SCC (fail-closed): the cycle is only jointly
    // inductive if EVERY member's obligation is discharged under P.
    let mut recs: Vec<RecursiveMember> = Vec::new();
    for &m_did in &members {
        let m_local = m_did.as_local()?;
        let m_steal_ref = tcx.mir_drops_elaborated_and_const_checked(m_local);
        if m_steal_ref.is_stolen() {
            return None;
        }
        // Take an OWNED clone of the body via a fresh Steal, so each member's body outlives
        // the per-member borrow (we hold several member bodies simultaneously below).
        let m_body_owned = m_steal_ref.borrow().clone();
        let m_dp = with_no_trimmed_paths!(tcx.def_path_str(m_did));
        let m_vf =
            trust_mir_extract::extract_function_with_contract_bundle(tcx, &m_body_owned, None);
        let m_def_path = m_vf.def_path.clone();
        // Trust (ARGS-FINGERPRINT-READ-1 round 4): see `r1_generate_vcs`.
        let m_self_call_blocks =
            termination_unmeasured::direct_self_call_identity_blocks(tcx, &m_body_owned);
        let m_vcs = r1_generate_vcs(&m_vf, m_self_call_blocks.clone(), None, rows);
        // Trust (E step 0): a VC generated over a tripped budget may carry bare reads.
        if r1_budget_tripped(trace, &f_dp, "after an SCC member's VC generation") {
            return None;
        }
        let mut failed: Option<(
            trust_types::VerificationCondition,
            trust_types::VerificationResult,
        )> = None;
        for vc in &m_vcs {
            let Some(r) =
                ay.verify_all(std::slice::from_ref(vc)).into_iter().next().map(|(_, r)| r)
            else {
                continue;
            };
            if r.is_failed() {
                failed = Some((vc.clone(), r));
                break;
            }
        }
        let Some((v_vc, original_result)) = failed else {
            if trace {
                eprintln!(
                    "TRUST_R1_TRACE: {f_dp}: SCC member {m_dp} has no Failed VC — reject (nothing to flip inductively)"
                );
            }
            return None;
        };

        // Propose P for this member, gate against its OWN body namespace. IDENTICAL
        // machinery to the DefId path — the strengthen proposer, then `¬V` as the backstop.
        let dbg = trust_mir_extract::build_debug_name_multimap(&m_body_owned);
        let m_vf_body = m_vf.body.clone();
        let gate_candidate = |cand: trust_types::Formula| -> Option<trust_types::Formula> {
            let mut pv = vec![cand];
            // `None`: this lane gates a SYNTHESIZED candidate precondition, not an
            // authored clause, and has no HIR parameter vector to hand. The forced
            // restatement therefore declines — correct here regardless, since a
            // proposer's candidate is already written in the body's own namespace.
            let reasons = trust_mir_extract::contract_assumption_gate::gate_contract_preconditions(
                &mut pv, &m_vf_body, &dbg, None,
            );
            if !reasons.is_empty() || pv.is_empty() {
                return None;
            }
            pv.pop()
        };
        let analysis = trust_strengthen::analyze_failure(&v_vc, &original_result);
        let proposals = trust_strengthen::strengthen(
            &m_vf.def_path,
            &m_vf.name,
            std::slice::from_ref(&analysis),
        );
        let p_from_proposer = proposals.iter().find_map(|prop| {
            let trust_strengthen::ProposalKind::AddPrecondition { spec_body } = &prop.kind else {
                return None;
            };
            let parsed = trust_types::parse_spec_expr(spec_body)?;
            gate_candidate(parsed)
        });
        let p = match p_from_proposer
            .or_else(|| {
                simplify_violation_negation(&v_vc.formula)
                    .and_then(|candidate| gate_candidate(candidate))
            })
            // Trust (piece #8): loop-bound length synthesizer. The member record now
            // threads `param_types`, so the σ length-render can bind `<p>__slice_len`
            // at each caller; an un-rendered atom still fails closed at the caller.
            .or_else(|| synthesize_loop_bound_precondition(&v_vc.formula).and_then(gate_candidate))
        {
            Some(p) => p,
            None => {
                if trace {
                    eprintln!("TRUST_R1_TRACE: {f_dp}: SCC member {m_dp} no usable P — reject");
                }
                return None;
            }
        };
        if trace {
            eprintln!("TRUST_R1_TRACE: {f_dp}: SCC member {m_dp} proposed P = {p:?}");
        }

        // Strengthened verdict for THIS member's SAME VC (location+kind): F-safe-under-P
        // for its own body (independent of the caller/recursion side). KEEP the kernel
        // certificate — the mint replays it; a bare `is_none()` check would be a label.
        let s_vcs = r1_generate_vcs(&m_vf, m_self_call_blocks, Some(&p), rows);
        // Trust (E step 0): never certify a strengthened VC built over a tripped budget.
        if r1_budget_tripped(trace, &f_dp, "after an SCC member's strengthened VC generation") {
            return None;
        }
        let Some(s_vc) = s_vcs.into_iter().find(|c| {
            c.location == v_vc.location && c.kind.description() == v_vc.kind.description()
        }) else {
            return None;
        };
        let Some(s_evidence) = trust_certify::certify_vc(&s_vc) else {
            if trace {
                eprintln!(
                    "TRUST_R1_TRACE: {f_dp}: SCC member {m_dp} strengthened VC NOT certified — reject"
                );
            }
            return None;
        };

        let param_names = mir_param_names(&m_body_owned);
        let param_types = mir_param_types_from_vf(&m_vf);
        recs.push(RecursiveMember {
            did: m_did,
            vf: m_vf,
            def_path: m_def_path,
            param_names,
            param_types,
            v_vc,
            original_result,
            p,
            s_vc,
            s_evidence,
        });
    }

    // A summary DB carrying EVERY SCC member (by def_path) with its param names/types + P.
    // Used to emit `¬P_N[σ]` at every call to an SCC member N — for both the base-case
    // (external caller) and inductive-step (intra-SCC recursive) discharge obligations.
    let mut scc_db = trust_vcgen::SummaryDatabase::new();
    for r in &recs {
        scc_db.insert(
            trust_vcgen::FunctionSummary::new(r.def_path.clone())
                .with_param_names(r.param_names.clone())
                .with_param_types(r.param_types.clone())
                .with_precondition(r.p.clone()),
        );
    }
    let scc_def_paths: FxHashSet<String> = recs.iter().map(|r| r.def_path.clone()).collect();
    let scc_dids: FxHashSet<DefId> = members.iter().copied().collect();
    let member_dp_of: FxHashMap<DefId, String> =
        recs.iter().map(|r| (r.did, r.def_path.clone())).collect();
    let idx_of: FxHashMap<String, usize> =
        recs.iter().enumerate().map(|(i, r)| (r.def_path.clone(), i)).collect();
    // Owned evidence rows per member (index-aligned with `recs`); the mint borrows them.
    let mut ev: Vec<RecursiveMemberEvidence> =
        (0..recs.len()).map(|_| RecursiveMemberEvidence::default()).collect();

    // The ORACLE-enumerated intra-SCC caller set per member (`info.callers` ∩ SCC),
    // recorded INDEPENDENTLY of the vcgen walk below. The mint demands the discharged
    // set match this exactly, so an intra-SCC edge the producer failed to emit an
    // obligation for is caught as a set mismatch (fail-closed) rather than silently
    // skipped.
    for (i, n) in recs.iter().enumerate() {
        if let Some(callers) = info.callers.get(&n.did) {
            for c_did in callers {
                if let Some(dp) = member_dp_of.get(c_did) {
                    ev[i].enumerated_scc.push(dp.clone());
                }
            }
        }
    }

    // (A) INDUCTIVE STEP. For each SCC member M, extract M and emit its call-site
    //     precondition VCs against the whole-SCC DB. A VC targeting an SCC member N is an
    //     intra-SCC recursive call: conjoin M's entry hypothesis P_M and require
    //     `P_M ∧ guards ⇒ P_N[σ]` (certified UNSAT), KEEPING the kernel certificate for
    //     the mint's replay. This is where a wrong invariant becomes a false proof, so it
    //     MUST be a real kernel discharge.
    for m in &recs {
        let site_vcs =
            trust_vcgen::generate_callsite_precondition_vcs_attributed_rows(&m.vf, &scc_db, rows);
        // Trust (E step 0): never certify an inductive-step VC built over a tripped budget.
        if r1_budget_tripped(trace, &f_dp, "after an inductive-step site-VC generation") {
            return None;
        }
        let mut produced_intra_sites: Vec<(String, trust_types::SourceSpan)> = Vec::new();
        // The inductive hypothesis: P_M over M's OWN params, assumed on entry.
        let hyp = m.p.clone();
        for (vc, assumption_substituted, allowed_guards) in site_vcs {
            let trust_types::VcKind::Precondition { callee } = &vc.kind else {
                // Arity mismatch / unsupported at an intra-SCC call ⇒ can't discharge ⇒ reject.
                if scc_def_paths.iter().any(|dp| format!("{:?}", vc.kind).contains(dp)) {
                    return None;
                }
                continue;
            };
            // Only intra-SCC recursive calls are inductive-step obligations here.
            if !scc_def_paths.contains(callee) {
                continue;
            }
            produced_intra_sites.push((callee.clone(), vc.location.clone()));
            // Build the inductive obligation: `And([P_M, existing_guards…, ¬P_N[σ]])`. The
            // producer's `vc.formula` is already `¬P_N[σ] [∧ guards]`; splice in the hypothesis
            // as a flat top-level conjunct and add it to `allowed_guards` so the pure core's
            // `is_admissible_caller_discharge` accepts it (¬P_N[σ] stays a direct conjunct).
            // The mint's hypothesis hygiene re-checks that the ONLY member invariant among
            // the guards is M's own P.
            let not_pn = trust_types::Formula::Not(Box::new(assumption_substituted.clone()));
            let ind_formula = match &vc.formula {
                trust_types::Formula::And(cs) => {
                    let mut v = vec![hyp.clone()];
                    v.extend(cs.iter().cloned());
                    trust_types::Formula::And(v)
                }
                other => trust_types::Formula::And(vec![hyp.clone(), other.clone()]),
            };
            let mut ind_guards = allowed_guards.clone();
            ind_guards.push(hyp.clone());
            let ind_vc = trust_types::VerificationCondition {
                kind: vc.kind.clone(),
                function: vc.function.clone(),
                location: vc.location.clone(),
                formula: ind_formula.clone(),
                contract_metadata: None,
                // Not a contract-derived VC: no obligation to back-reference.
                obligation: None,
            };
            // THE inductive discharge — a REAL kernel-certified UNSAT of
            // `P_M ∧ guards ∧ ¬P_N[σ]`. Not assumed. Not structural. Evidence KEPT.
            if trace {
                eprintln!(
                    "TRUST_R1_TRACE: {f_dp}: inductive step {}→{callee} @ {}:{} P_M={hyp:?} obligation={:?}",
                    m.def_path, vc.location.line_start, vc.location.col_start, ind_formula
                );
            }
            let Some(ind_evidence) = trust_certify::certify_vc(&ind_vc) else {
                if trace {
                    eprintln!(
                        "TRUST_R1_TRACE: {f_dp}: inductive step at {}→{callee} @ {}:{} NOT certified (P_M∧guards⇏P_N[σ]) — reject",
                        m.def_path, vc.location.line_start, vc.location.col_start
                    );
                }
                return None;
            };
            // Sanity: `¬P_N[σ]` must be a direct conjunct so the structural check holds.
            let trust_types::Formula::And(cs) = &ind_formula else {
                return None;
            };
            if !cs.contains(&not_pn) {
                return None;
            }
            let Some(&n_idx) = idx_of.get(callee.as_str()) else {
                return None;
            };
            ev[n_idx].ind.push((
                m.def_path.clone(),
                ind_vc,
                assumption_substituted,
                ind_guards,
                ind_evidence,
            ));
        }
        // Caller sets alone are insufficient: two same-caller edges collapse
        // in `info.callers`. Bind every produced inductive row to the oracle's
        // exact `(caller, callee, span)` multiset before the sealed mint can
        // see it. Missing, duplicate, or synthetic rows all fail closed.
        for n in &recs {
            let expected_sites: Vec<trust_types::SourceSpan> = info
                .direct_call_sites
                .iter()
                .filter(|site| site.caller == m.did && site.callee == n.did)
                .map(|site| site.call_site.clone())
                .collect();
            let produced_sites: Vec<trust_types::SourceSpan> = produced_intra_sites
                .iter()
                .filter(|(callee, _)| callee == &n.def_path)
                .map(|(_, site)| site.clone())
                .collect();
            if !exact_callsite_span_multiset_matches(&expected_sites, &produced_sites) {
                if trace {
                    eprintln!(
                        "TRUST_R1_TRACE: {f_dp}: inductive call-site inventory mismatch {}→{} (oracle={}, produced={}) — reject",
                        m.def_path,
                        n.def_path,
                        expected_sites.len(),
                        produced_sites.len(),
                    );
                }
                return None;
            }
        }
    }

    // (B) BASE CASE. For each SCC member N, every EXTERNAL caller C (a caller of N that is
    //     NOT itself an SCC member) must establish P_N — the STANDARD R1 caller obligation,
    //     with NO inductive hypothesis, evidence KEPT for the mint's replay. At least one
    //     external caller must exist across the whole SCC so P is established at some real
    //     entry (the mint independently re-checks this grounding).
    let mut total_external_callers = 0usize;
    for (i, n) in recs.iter().enumerate() {
        let Some(callers) = info.callers.get(&n.did) else {
            continue; // no recorded callers at all for N — its external set is empty
        };
        // One-entry DB: N carrying ONLY its P (base-case σ substitution is over N's formals).
        let mut n_db = trust_vcgen::SummaryDatabase::new();
        n_db.insert(
            trust_vcgen::FunctionSummary::new(n.def_path.clone())
                .with_param_names(n.param_names.clone())
                .with_param_types(n.param_types.clone())
                .with_precondition(n.p.clone()),
        );
        for &c_did in callers {
            if scc_dids.contains(&c_did) {
                continue; // intra-SCC edge — handled by the inductive step, not the base case
            }
            total_external_callers += 1;
            let c_local = c_did.as_local()?;
            if !matches!(tcx.def_kind(c_did), DefKind::Fn | DefKind::AssocFn) {
                return None;
            }
            let c_steal = tcx.mir_drops_elaborated_and_const_checked(c_local);
            if c_steal.is_stolen() {
                return None;
            }
            let c_body = c_steal.borrow();
            let c_vf = trust_mir_extract::extract_function_with_contract_bundle(tcx, &c_body, None);
            ev[i].enumerated_external.push(c_vf.def_path.clone());
            let site_vcs =
                trust_vcgen::generate_callsite_precondition_vcs_attributed_rows(&c_vf, &n_db, rows);
            // Trust (E step 0): never certify a base-case site VC built over a tripped budget.
            if r1_budget_tripped(trace, &f_dp, "after a base-case caller's site-VC generation") {
                return None;
            }
            let mut produced_sites = Vec::new();
            for (vc, assumption_substituted, allowed_guards) in site_vcs {
                let trust_types::VcKind::Precondition { callee } = &vc.kind else {
                    return None;
                };
                if *callee != n.def_path {
                    continue;
                }
                produced_sites.push(vc.location.clone());
                let Some(evidence) = trust_certify::certify_vc(&vc) else {
                    if trace {
                        eprintln!(
                            "TRUST_R1_TRACE: {f_dp}: base-case caller {} of {} NOT certified (¬P[σ] SAT) — reject",
                            c_vf.def_path, n.def_path
                        );
                    }
                    return None;
                };
                ev[i].base.push((
                    c_vf.def_path.clone(),
                    vc,
                    assumption_substituted,
                    allowed_guards,
                    evidence,
                ));
            }
            let expected_sites: Vec<trust_types::SourceSpan> = info
                .direct_call_sites
                .iter()
                .filter(|site| site.caller == c_did && site.callee == n.did)
                .map(|site| site.call_site.clone())
                .collect();
            if expected_sites.is_empty()
                || !exact_callsite_span_multiset_matches(&expected_sites, &produced_sites)
            {
                // An F5-SUPPRESSED call site mints no VC precisely BECAUSE the
                // precondition is already established there by interval
                // dominance — indistinguishable, in this empty list, from "the
                // producer knew nothing". Ask the same question the suppressor
                // asked: if EVERY call site to this member in this caller is
                // structurally dominated, the base case holds and needs no
                // evidence row. (Measured: `go` calls `walk(&[1,2,3,4], 3, 2)`,
                // whose `2 < 4` is dominated, and R1 discarded a base case that
                // was in fact proved.) Anything less still fails closed.
                if !expected_sites.is_empty()
                    && produced_sites.is_empty()
                    && trust_vcgen::all_callsites_precondition_dominated(&c_vf, &n_db, &n.def_path)
                {
                    if trace {
                        eprintln!(
                            "TRUST_R1_TRACE: {f_dp}: base-case caller {} of {} is F5-DOMINATED at every site — recorded for mint re-derivation",
                            c_vf.def_path, n.def_path
                        );
                    }
                    ev[i].dominated.push((c_vf.def_path.clone(), c_vf.clone()));
                    continue;
                }
                if trace {
                    eprintln!(
                        "TRUST_R1_TRACE: {f_dp}: base-case call-site inventory mismatch {}→{} (oracle={}, produced={}) — reject",
                        c_vf.def_path,
                        n.def_path,
                        expected_sites.len(),
                        produced_sites.len(),
                    );
                }
                return None;
            }
        }
    }
    // At least one external entry across the whole SCC — else P is established at no real
    // entry, so we cannot ground the induction. The mint re-checks this (fail-closed both
    // ways); refusing early keeps the bf92-era trace message.
    if total_external_callers == 0 {
        if trace {
            eprintln!(
                "TRUST_R1_TRACE: {f_dp}: SCC has NO external caller — reject (base case ungrounded)"
            );
        }
        return None;
    }

    // (C) THE decision — the INDUCTIVE sealed mint. The pure core re-checks the whole
    //     induction structure (exact caller sets per member, hypothesis hygiene,
    //     grounding, strengthened-formula shape) and kernel-REPLAYS every certificate
    //     bound above. Any member's Err ⇒ the WHOLE SCC is not flippable.
    let member_proofs: Vec<InductiveMemberProof<'_>> = recs
        .iter()
        .zip(ev.iter())
        .map(|(r, e)| InductiveMemberProof {
            def_path: r.def_path.clone(),
            original_vc: &r.v_vc,
            original_result: &r.original_result,
            assumption: r.p.clone(),
            param_names: r.param_names.clone(),
            param_types: r.param_types.clone(),
            gated_requires: r.vf.preconditions.clone(),
            strengthened: StrengthenedProof { vc: &r.s_vc, evidence: &r.s_evidence },
            enumerated_external_callers: e.enumerated_external.clone(),
            base_case_proofs: e
                .base
                .iter()
                .map(|(caller, vc, assumption_substituted, allowed_guards, evidence)| {
                    CallerDischargeProof {
                        caller: caller.clone(),
                        call_site: vc.location.clone(),
                        assumption_substituted: assumption_substituted.clone(),
                        vc,
                        allowed_guards: allowed_guards.clone(),
                        evidence,
                    }
                })
                .collect(),
            dominated_external_callers: e
                .dominated
                .iter()
                .map(|(caller, caller_function)| {
                    trust_router::strengthen_whole_program::DominatedCallerClaim {
                        caller: caller.clone(),
                        caller_function,
                    }
                })
                .collect(),
            enumerated_scc_callers: e.enumerated_scc.clone(),
            inductive_step_proofs: e
                .ind
                .iter()
                .map(|(caller_member, vc, assumption_substituted, allowed_guards, evidence)| {
                    InductiveStepProof {
                        caller_member: caller_member.clone(),
                        call_site: vc.location.clone(),
                        assumption_substituted: assumption_substituted.clone(),
                        vc,
                        allowed_guards: allowed_guards.clone(),
                        evidence,
                    }
                })
                .collect(),
        })
        .collect();
    // Trust (E step 0): the budget is sticky, so this one read covers every VC above; the
    // post-mint read covers the mint's own dominance re-derivation (which runs vcgen).
    if r1_budget_tripped(trace, &f_dp, "before the inductive sealed mint") {
        return None;
    }
    let certs = match mint_inductive_caller_propagation_certificate(&member_proofs) {
        Ok(_) if r1_budget_tripped(trace, &f_dp, "during the inductive sealed mint") => {
            return None;
        }
        Ok(certs) => certs,
        Err(e) => {
            if trace {
                eprintln!("TRUST_R1_TRACE: {f_dp}: inductive sealed mint REJECTED: {e:?}");
            }
            debug!("R1 skip {f_dp}: inductive sealed mint rejected: {e:?}");
            return None;
        }
    };

    // The whole SCC is jointly inductive, grounded, and fully kernel-replayed. Return the
    // flip for THIS F (its own member token — `certs` is index-aligned with `recs`). Each
    // other member emits its flip when the `mir_keys` loop reaches it (recomputing the
    // identical, idempotent joint proof).
    let f_idx = recs.iter().position(|r| r.did == f_did)?;
    let sealed = certs.into_iter().nth(f_idx)?;
    let f_rec = &recs[f_idx];
    if trace {
        eprintln!(
            "TRUST_R1_TRACE: {f_dp}: ADMITTED INDUCTIVE RECURSIVE FLIP over {}-member SCC at {}:{} (sealed {})",
            members.len(),
            f_rec.v_vc.location.line_start,
            f_rec.v_vc.location.col_start,
            sealed.digest()
        );
    }
    Some((
        f_rec.def_path.clone(),
        R1Flip {
            location: f_rec.v_vc.location.clone(),
            kind_desc: f_rec.v_vc.kind.description(),
            sealed,
        },
    ))
}

/// Trust: compute, once per crate, the backing structs whose relational
/// invariant (`ptr` valid for `len` elements) is interprocedurally CERTIFIED —
/// SEALED (private backing fields ⇒ no external constructor/mutator) ∩
/// ESTABLISHED (every constructor proves `alloc_size >= self.len`, via
/// `trust_vcgen::certify_backing_invariants`). Only a name in BOTH sets licenses
/// the use-site ASSUME to discharge a guarded access; everything else stays
/// fail-closed (CAUGHT). See `docs/backing-cert-compiler-wiring.md`.
///
/// MUST be called at the analysis phase: it borrows
/// `mir_drops_elaborated_and_const_checked`, which `optimized_mir` later STEALS
/// during codegen — borrowing here (pre-steal) is sound and panic-free, and does
/// not run `TrustVerify` (no query cycle). Const-context bodies, whose `Steal`
/// `inner_mir_for_ctfe`'s stealing arm consumes during `check_crate`'s eager
/// const-eval (BEFORE this hook runs), are RECOVERED through `mir_for_ctfe` —
/// the steal CONSUMER, a tracked query returning a stable `&Body` after the
/// steal — so the backing-certification inventory stays COMPLETE. Struct names
/// are keyed by `safe_def_path_str` to match the extracted IR's `Ty::Adt` name.
// `is_stolen` here only selects between two views of the SAME body (borrow the
// intact `Steal` vs read the `mir_for_ctfe` recovery) or blocks certification
// CLOSED — it can never REMOVE a body from the certifier's evidence, so the
// untracked read cannot flip a verdict anti-conservatively on either side of an
// incremental replay; the set intersection is order-independent (collected back
// into a set). Trust (2026-10-03): so is the run-by-run merge of a summary map
// (`summaries_over_admitted_runs`: each run's keys are unique, the runs merged in
// their fixed order).
#[allow(rustc::untracked_query_information, rustc::potential_query_instability)]
pub fn trust_init_backing_certificates(tcx: TyCtxt<'_>) {
    if !verification_enabled(tcx.sess)
        || with_crate_verification_state(tcx.sess, |state| state.backing_initialized)
    {
        return;
    }
    // 1. Sealed set — cheap, type-level; if empty (the common case: no
    //    `#[trust::backing]` struct), certify nothing and skip all extraction.
    let mut sealed_structs = compute_sealed_backing_structs(tcx);
    // Trust: TINV step 6a — the certificate-keyed name set is read per role. The
    // match is exhaustive on purpose: a new `SealedRole` must decide here whether
    // its names join the backing set.
    let sealed: FxHashSet<String> = sealed_structs
        .values()
        .filter_map(|s| match s.role {
            backing_escape_census::SealedRole::Backing { .. } => Some(s.name.clone()),
            // Trust: TINV step 6b — a TINV candidate is never a backing name.
            backing_escape_census::SealedRole::TypeInvariant => None,
        })
        .collect();
    // Trust: TINV step 9 (a) — the type-invariant candidates (step 5), opt-in under
    // the TRACKED `-Ztrust-tinv` (step 10.0; it replaced the untracked `TRUST_TINV=1`
    // env read of decision TINV-10, which is no longer consulted at all). Unset,
    // `tinv` is empty and everything below runs exactly as before.
    let tinv_enabled = tcx.sess.opts.unstable_opts.trust_tinv;
    let (tinv, tinv_gate_notes) = if tinv_enabled {
        type_invariant::compute_invariant_candidate_types(tcx, &sealed_structs)
    } else {
        Default::default()
    };
    // Trust: TINV step 9 (b) — the candidates join the census's sealed set with
    // their own role; disjointness from the backing set was decided at step 5.
    for (did, candidate) in &tinv {
        sealed_structs.insert(
            *did,
            backing_escape_census::SealedType {
                name: candidate.name.clone(),
                role: backing_escape_census::SealedRole::TypeInvariant,
            },
        );
    }
    // Trust: TINV step 9 (d) — the metadata of every inventoried body, parallel to
    // `backing_funcs`; recorded only when a TINV candidate exists.
    let mut backing_meta: Vec<type_invariant::InventoryMeta> = Vec::new();
    if env_flag_enabled("TRUST_CERT_DEBUG") {
        eprintln!("TRUST_CERT_DEBUG: sealed = {sealed:?}");
    }
    // Trust (2026-09-30): the escape census (`backing_escape_census`). Every body the
    // certifier is given is ALSO scanned on its rustc MIR, where the ways to reach a
    // sealed struct's storage without naming its fields (a raw pointer, a transmute,
    // a union, a foreign or unsafe callee, a generic instantiation) are visible. It
    // only ever denies.
    let mut census = (!sealed_structs.is_empty())
        .then(|| backing_escape_census::Census::new(tcx, &sealed_structs));
    // The whole-crate extraction below also feeds clamp-via-helper return-bound
    // summaries for every enabled local crate, not only crates containing a
    // `#[trust::backing]` struct. Reporting roles cannot suppress this work.
    // 2. Extract the whole-crate body inventory.
    //
    //    SOUNDNESS — the certifier's shape dictates this loop's shape.
    //    `certify_backing_invariants` starts `all_establish = true` /
    //    `broken_by_mutation = false` and only ever WEAKENS them from evidence
    //    it SEES; only `saw_constructor` is evidence-driven. A body missing
    //    from its input therefore pushes TOWARD certification — and the
    //    certificate publishes the use-site ASSUME `alloc_size >= self.len`,
    //    which turns a guarded access from CAUGHT into PROVED. This loop used
    //    to drop bodies silently on two paths, each justified by an inverted
    //    "omission is fail-closed" claim: a `def_kind` filter to
    //    `Fn | AssocFn` (dropping every closure, const/static initializer,
    //    ctor shim, and synthetic coroutine body `mir_keys` yields) and an
    //    `is_stolen()` `continue` (dropping `#[rustc_comptime]` fns, whose
    //    always-const bodies `inner_mir_for_ctfe`'s stealing arm consumes
    //    during `check_crate`'s eager const-eval). A non-establishing
    //    constructor in ANY of those bodies — `const B: S = S { ptr, len }`,
    //    a `static` initializer, a tuple-ctor shim used as a function value,
    //    a constructing closure, a stolen comptime fn — was invisible, so the
    //    struct certified from the bodies that remained.
    //
    //    The discipline is the one the paired-condvar lane's const arm already
    //    models (`certify_paired_condvars_for_crate`): inventory EVERY
    //    `mir_keys` body owner, RECOVERING what a plain borrow cannot see —
    //    `mir_for_ctfe` is the const-context steal's CONSUMER, a tracked query
    //    returning a stable `&Body` after the steal, and serves ctor shims
    //    directly via `shim::build_adt_ctor` — plus each owner's
    //    `promoted_mir` fragments (promotion MOVES a `&S { .. }` aggregate out
    //    of its parent body, so the constructor lives in the promoted body
    //    only). Trivial consts (`tcx.trivial_const`: a lone
    //    `_0 = const <val>; return`) provably contain no aggregate, no field
    //    write, and no promoteds — and `mir_for_ctfe`/`mir_promoted`
    //    debug-assert against them — so skipping them is sound AND required.
    //    Only a body that can neither be borrowed nor recovered may block
    //    certification, and it blocks CLOSED
    //    (`backing_inventory_complete = false` ⇒ no certificate), never open.
    //
    //    `funcs` — the input of the six per-function summary lanes below —
    //    deliberately keeps its old universe (`Fn | AssocFn` bodies whose
    //    `Steal` is intact): those lanes are per-function inserts whose
    //    omission only ever LOSES a summary (conservative). `backing_funcs` is
    //    the complete inventory and feeds certification alone.
    let need_backing = !sealed.is_empty();
    // Trust: TINV step 9 (c) — the complete inventory is built for either lane.
    let need_inventory = need_backing || !tinv.is_empty();
    let mut funcs = Vec::new();
    // Trust (D5-B): `func_def_ids[i]` is the `DefId` `funcs[i]` was extracted
    // from — the identity the body-inferred return lane keys on.
    let mut func_def_ids: Vec<DefId> = Vec::new();
    let mut backing_funcs: Vec<trust_types::VerifiableFunction> = Vec::new();
    // Trust (2026-10-01): closure bodies, kept OUT of `funcs` (whose lanes key call
    // sites by name), for the one summary a closure feeds: its return interval, read
    // where it is passed by value to `Iterator::map` (`closure_return_item_bounds`).
    let mut closure_funcs: Vec<trust_types::VerifiableFunction> = Vec::new();
    let mut closure_def_ids: Vec<DefId> = Vec::new();
    let mut backing_inventory_complete = true;
    for &local_def_id in tcx.mir_keys(()) {
        let def_id = local_def_id.to_def_id();
        match tcx.def_kind(def_id) {
            kind @ (DefKind::Fn
            | DefKind::AssocFn
            | DefKind::Closure
            | DefKind::SyntheticCoroutineBody) => {
                let fn_like = matches!(kind, DefKind::Fn | DefKind::AssocFn);
                let closure = matches!(kind, DefKind::Closure);
                if !fn_like && !closure && !need_inventory {
                    continue;
                }
                // Trust (I5): a Clean-origin def is in `mir_keys` but has no
                // ordinary MIR pipeline behind it. Asking for
                // `mir_drops_elaborated_and_const_checked` walks
                // `mir_borrowck` -> `mir_promoted` -> `mir_built` ->
                // `check_match` -> `typeck`, and `typeck`'s first act is
                // `node.body_id().unwrap_or_else(|| span_bug!(...))` on a def
                // that has a synthetic HIR owner and no body — a hard ICE,
                // measured on `m::pick` (2026-08-19).
                //
                // The body is taken from `optimized_mir` instead, which for
                // these defs IS the gated emission — so the backing inventory
                // stays COMPLETE (it is not skipped, which would silently drop
                // a body from an inventory whose completeness gates
                // certification) and the function summary is extracted from
                // exactly the body that will be codegened.
                if crate::clean_origin_mir::is_clean_origin(tcx, local_def_id) {
                    let body = tcx.optimized_mir(local_def_id);
                    let func =
                        trust_mir_extract::extract_function_with_contract_bundle(tcx, body, None);
                    if need_inventory {
                        backing_funcs.push(func.clone());
                        tinv_meta_push(&mut backing_meta, &tinv, &mut census, body, def_id, None);
                    }
                    if let Some(census) = census.as_mut() {
                        census.scan_body(body);
                    }
                    if fn_like {
                        funcs.push(func);
                        func_def_ids.push(def_id); // Trust: D5-B identity, parallel to `funcs`.
                    }
                    continue;
                }
                let steal = tcx.mir_drops_elaborated_and_const_checked(local_def_id);
                if !steal.is_stolen() {
                    let body = steal.borrow();
                    let func =
                        trust_mir_extract::extract_function_with_contract_bundle(tcx, &body, None);
                    if need_inventory {
                        backing_funcs.push(func.clone());
                        tinv_meta_push(&mut backing_meta, &tinv, &mut census, &body, def_id, None);
                    }
                    if let Some(census) = census.as_mut() {
                        census.scan_body(&body);
                    }
                    if closure {
                        closure_funcs.push(func.clone());
                        closure_def_ids.push(def_id);
                    }
                    if fn_like {
                        funcs.push(func);
                        func_def_ids.push(def_id); // Trust: D5-B identity, parallel to `funcs`.
                    }
                } else if need_inventory {
                    // Stolen at the analysis phase ⇒ `inner_mir_for_ctfe`'s
                    // stealing arm consumed it (codegen's `optimized_mir` steal
                    // happens later), which fires only for an always-const body
                    // — a `#[rustc_comptime]` fn. Recover through the steal
                    // consumer. `SyntheticCoroutineBody` has no HIR body
                    // (`hir_body_const_context` would panic on it) and no const
                    // context, so it cannot legitimately be stolen here.
                    //
                    // Trust (2026-09-29): a COROUTINE body is no longer stolen
                    // here either. Its layout used to be read from
                    // `optimized_mir` during `run_required_analyses`, which stole
                    // it (and, through TrustVerify's bundling, some of its
                    // callees) before this seam, so every crate with an `async`
                    // body blocked CLOSED below. With verification enabled the
                    // layout is served pre-steal (`trust_local_coroutine_layout`),
                    // so the body is in the inventory — the certifier's own
                    // completeness condition, not a relaxed check.
                    if !matches!(kind, DefKind::SyntheticCoroutineBody)
                        && matches!(
                            tcx.hir_body_const_context(local_def_id),
                            Some(
                                rustc_hir::ConstContext::Const { .. }
                                    | rustc_hir::ConstContext::Static(_)
                            )
                        )
                    {
                        let body = tcx.mir_for_ctfe(local_def_id);
                        backing_funcs.push(
                            trust_mir_extract::extract_function_with_contract_bundle(
                                tcx, body, None,
                            ),
                        );
                        tinv_meta_push(&mut backing_meta, &tinv, &mut census, body, def_id, None);
                        if let Some(census) = census.as_mut() {
                            census.scan_body(body);
                        }
                    } else {
                        // No recovery query exists for this body: block CLOSED.
                        backing_inventory_complete = false;
                        continue;
                    }
                } else {
                    continue;
                }
                if need_inventory {
                    for (index, promoted) in tcx.promoted_mir(def_id).iter_enumerated() {
                        backing_funcs.push(
                            trust_mir_extract::extract_function_with_contract_bundle(
                                tcx, promoted, None,
                            ),
                        );
                        tinv_meta_push(
                            &mut backing_meta,
                            &tinv,
                            &mut census,
                            promoted,
                            def_id,
                            Some(index.as_usize()),
                        );
                        if let Some(census) = census.as_mut() {
                            census.scan_body(promoted);
                        }
                    }
                }
            }
            DefKind::Const { .. }
            | DefKind::AssocConst { .. }
            | DefKind::AnonConst
            | DefKind::Static { .. } => {
                // A const/static initializer is itself a body that can
                // CONSTRUCT a backing struct (`const B: S = S { ptr, len }` is
                // exactly the non-establishing-constructor shape).
                if !need_inventory || tcx.is_trivial_const(local_def_id) {
                    continue;
                }
                let body = tcx.mir_for_ctfe(local_def_id);
                backing_funcs.push(trust_mir_extract::extract_function_with_contract_bundle(
                    tcx, body, None,
                ));
                tinv_meta_push(&mut backing_meta, &tinv, &mut census, body, def_id, None);
                if let Some(census) = census.as_mut() {
                    census.scan_body(body);
                }
                for (index, promoted) in tcx.promoted_mir(def_id).iter_enumerated() {
                    backing_funcs.push(trust_mir_extract::extract_function_with_contract_bundle(
                        tcx, promoted, None,
                    ));
                    tinv_meta_push(
                        &mut backing_meta,
                        &tinv,
                        &mut census,
                        promoted,
                        def_id,
                        Some(index.as_usize()),
                    );
                    if let Some(census) = census.as_mut() {
                        census.scan_body(promoted);
                    }
                }
            }
            DefKind::Ctor(..) => {
                // The tuple-ctor SHIM constructs the struct
                // (`_0 = S(move _1, move _2)`); a ctor used as a function VALUE
                // constructs inside the shim, not at its call site.
                // `mir_for_ctfe` serves ctors via `shim::build_adt_ctor`
                // without touching any `Steal`; ctor shims have no promoteds.
                //
                // CAPABILITY COST, named rather than implied: `mir_keys` yields
                // every tuple-struct ctor unconditionally, and a shim's establish
                // obligation is over its UNTRACKED parameter pointer — symbolic
                // size, never UNSAT. Inventorying shims therefore makes a tuple
                // `#[trust::backing]` struct CATEGORICALLY uncertifiable: its
                // ctor is always a visible non-establishing constructor. That is
                // the sound direction (the shim really can construct the struct
                // from anything), and the escape is a named-field struct whose
                // constructors are ordinary bodies. Recorded here because the
                // regression is a consequence of THIS arm, and silently losing a
                // capability is the failure mode this file's audit history warns
                // about.
                if need_inventory {
                    let body = tcx.mir_for_ctfe(local_def_id);
                    backing_funcs.push(trust_mir_extract::extract_function_with_contract_bundle(
                        tcx, body, None,
                    ));
                    tinv_meta_push(&mut backing_meta, &tinv, &mut census, body, def_id, None);
                    if let Some(census) = census.as_mut() {
                        census.scan_body(body);
                    }
                }
            }
            _ => {
                // `mir_keys` yielded a body-owner kind outside the enumeration
                // above (`GlobalAsm` is stripped by `mir_keys` itself). No
                // borrow or recovery is known for it: block certification
                // CLOSED rather than certify from a partial inventory.
                if need_inventory {
                    backing_inventory_complete = false;
                }
            }
        }
    }
    // 3a. Body-derived callee summaries — whole-crate, always. Each lane below
    //     reads a callee's extracted BODY and turns it into a fact every call
    //     site of that callee may assume about the call's result (or, for a
    //     setter, its effect).
    //
    // Trust (2026-10-03, INTERPOSE-SUM-1): ONE IDENTITY gate, decided here from
    // `TyCtxt`, for EVERY body-derived summary lane below. A body whose symbol
    // can be interposed at link time (`#[no_mangle]`/`#[export_name]`/
    // `#[linkage]`: `contains_extern_indicator`, with the two fields it reads
    // spelled out as D5-B spells them) need not be the body a call runs —
    // another object can define the same symbol and the call binds to it — so
    // it neither records nor lends a summary. D5-B (`inferred_return.rs`)
    // refuses it for the same reason. A Clean-origin def is left to its own
    // definitional lane, as D5-B leaves it. A parallel-vector mismatch admits
    // nothing. Until 2026-10-03 only the field-read lane applied this gate: with
    // `#[no_mangle] fn five() -> u32 { 5 }`, `five() + (u32::MAX - 5)` was
    // kernel-certified overflow-free under certify from `five`'s const-set
    // summary, and a binary that linked another `five` panicked on that add
    // (`tests/ui/trust/return_const_summary_interposable_callee_not_summarised.rs`).
    //
    // Trust (2026-10-04, F6-INTERPOSE-1): the predicate is now the shared
    // `body_summary_identity_refused`, which the F6 float result-interval lane
    // and the callee-tracing body lane apply too.
    //
    // Trust (2026-10-05, SUMMARY-NAME-COLLIDE-1): and a body whose `def_path` key
    // another local body owner also renders to is refused in every lane, D5-B
    // included (`body_summary_key_collisions`). The key is the only thing a call
    // site matches on, so a shared key cannot say which body a call runs; the
    // lanes used to keep whichever body came last, and a call through the other
    // impl was handed its facts (`tests/ui/trust/summary_hrtb_impl_name_collision.rs`).
    let summary_key_collisions = body_summary_key_collisions(tcx, &funcs, &func_def_ids);
    let summary_refused: Option<FxHashSet<&str>> = (funcs.len() == func_def_ids.len()).then(|| {
        funcs
            .iter()
            .zip(&func_def_ids)
            .filter(|(func, def_id)| {
                body_summary_identity_refused(tcx, **def_id)
                    || summary_key_collisions.contains(func.def_path.as_str())
            })
            .map(|(func, _)| func.def_path.as_str())
            .collect()
    });
    // The six lanes computed over these runs are per-function inserts keyed on
    // `def_path`, each reading one body and no other function or summary
    // (`summary_candidates` and its callers in
    // `trust_vcgen::generate::callee_summaries`), so computing a lane run by run
    // and merging in order is computing it over the admitted functions alone: a
    // refused body is never an input, rather than an output filtered away.
    let admitted_runs = admitted_summary_runs(&funcs, summary_refused.as_ref());
    // Clamp-via-helper return-bound summaries (sound: only const-certain,
    // single-assigned, non-negative return bounds, and the use-site emission is
    // itself SSA-gated + staleness-versioned). Plus their mirrors over the same
    // extraction: the constant return LOWER bound and the exact const-return SET
    // (every return site a constant), each fail-closed by construction in
    // trust-vcgen.
    let return_bounds =
        summaries_over_admitted_runs(&admitted_runs, trust_vcgen::compute_return_bound_summaries);
    let return_lower_bounds = summaries_over_admitted_runs(
        &admitted_runs,
        trust_vcgen::compute_return_lower_bound_summaries,
    );
    // Trust (2026-10-03): which same-crate return bounds were recorded, and over which
    // extraction (`mir_drops_elaborated_and_const_checked`, not the verified body). A
    // `TRUST_RETURN_SUMMARY_DEBUG=<dir>` run also writes that extraction as JSON, so a
    // summary that is recorded offline but not here can be diagnosed on the same bodies.
    if let Some(dir) = std::env::var_os("TRUST_RETURN_SUMMARY_DEBUG") {
        let mut upper: Vec<_> = return_bounds.iter().collect();
        upper.sort();
        let mut lower: Vec<_> = return_lower_bounds.iter().collect();
        lower.sort();
        let mut collisions: Vec<_> = summary_key_collisions.iter().collect();
        collisions.sort();
        eprintln!(
            "TRUST_RETURN_SUMMARY_DEBUG: upper={upper:?} lower={lower:?} \
             refused_key_collisions={collisions:?}"
        );
        if let Ok(json) = serde_json::to_string(&funcs) {
            let _ = std::fs::write(std::path::Path::new(&dir).join("summary_funcs.json"), json);
        }
    }
    let return_const_sets = summaries_over_admitted_runs(
        &admitted_runs,
        trust_vcgen::compute_return_const_set_summaries,
    );
    // Trust (2026-09-30): the return INTERVAL, from the production interval
    // fixpoint over each body for every input (fail-closed per function in
    // trust-vcgen), where the recognizers above find nothing: `x as u32 + 1` over a
    // `u8`, a fieldless enum's `self as usize`, a branch clamp.
    // Trust (merge 2026-10-14): computed over the admitted runs, so the
    // INTERPOSE-SUM-1 / SUMMARY-NAME-COLLIDE-1 identity gate applies to it too.
    let mut return_intervals = summaries_over_admitted_runs(&admitted_runs, |run| {
        trust_vcgen::compute_return_interval_summaries(run, tcx.sess.overflow_checks())
    });
    // Trust (2026-10-01): the PAYLOAD interval of an `Option<iN>`/`Result<iN, E>`
    // return, from the same fixpoint, consumed on a caller's `Some`/`Ok` payload
    // (directly or through `?`). Same lender exclusions as above.
    let mut return_payload_intervals = summaries_over_admitted_runs(&admitted_runs, |run| {
        trust_vcgen::compute_return_payload_interval_summaries(run, tcx.sess.overflow_checks())
    });
    // Trust (G1, 2026-10-27): same-crate wrappers that return a documented
    // pointer-returning libc call's result unchanged (`fn errno_slot() -> *mut c_int {
    // unsafe { libc::__error() } }`), so a caller's deref of the wrapper's result
    // carries the libc contract (`trust_vcgen::ffi_pointer_contract`). Same identity
    // gate and lender exclusions as the intervals.
    let mut return_ffi_pointer_contracts = summaries_over_admitted_runs(
        &admitted_runs,
        trust_vcgen::compute_return_ffi_pointer_summaries,
    );
    // A function with an authored contract is used through its contract: a caller
    // relies on what the contract says, not on what the body happens to return
    // (`postcondition_composition_upper_bound_only.rs` pins that a weak `ensures`
    // stays weak). The extraction above carries no contract bundle, so the bundle
    // is asked here, as the inferred-return lane asks it. A body under
    // `#[trust::skip]` or `#[trust::assume_total]` is outside what verification
    // checks, and lends nothing either (round 12 of the review needed that attribute
    // for every shape it could still push through).
    for (func, &def_id) in funcs.iter().zip(&func_def_ids) {
        if trust_contracts_if_any(tcx, def_id).is_some_and(|bundle| !bundle.is_empty())
            || item_has_trust_skip_attr(tcx, def_id)
            || item_has_trust_attr(tcx, def_id, "assume_total")
        {
            return_intervals.remove(&func.def_path);
            return_payload_intervals.remove(&func.def_path);
            return_ffi_pointer_contracts.remove(&func.def_path); // Trust: G1
        }
    }
    // Closure return intervals, under the same lender exclusions; a closure carries
    // no contract bundle, but it can carry `#[trust::skip]`/`#[trust::assume_total]`.
    let mut closure_intervals =
        trust_vcgen::compute_return_interval_summaries(&closure_funcs, tcx.sess.overflow_checks());
    for (func, &def_id) in closure_funcs.iter().zip(&closure_def_ids) {
        if item_has_trust_skip_attr(tcx, def_id) || item_has_trust_attr(tcx, def_id, "assume_total")
        {
            closure_intervals.remove(&func.def_path);
        }
    }
    return_intervals.extend(closure_intervals);
    // Return-discriminant summaries over the same extraction: the returned
    // Option/Result tag shape (fail-closed per function in trust-vcgen),
    // consumed by the unwrap panic-freedom lane's call-result receiver shape.
    let return_disc_summaries =
        summaries_over_admitted_runs(&admitted_runs, trust_vcgen::compute_return_disc_summaries);
    // Trivial-setter summaries over the same extraction: the exact post-call
    // effect of a `*p = <param|const>; return` body (fail-closed recognizer in
    // trust-vcgen; the recognizer is the proof), consumed at `set(&mut a, v)`
    // call sites so the caller's `assert!(a == v)` proves in the base lane.
    let setter_summaries =
        summaries_over_admitted_runs(&admitted_runs, trust_vcgen::compute_trivial_setter_summaries);
    // Inferred bool-pred contracts over the same extraction: the guard-helper
    // channel (fail-closed per function in trust-vcgen — only bodies proven to
    // be pure tag predicates over a pinned shared-ref param record anything).
    // The native bool-pred subset below is built from this map, so it inherits
    // the identity gate.
    let return_bool_preds = summaries_over_admitted_runs(
        &admitted_runs,
        trust_vcgen::compute_return_bool_pred_summaries,
    );
    // Trust (TRUST-10): field-read summaries over the same extraction — a getter
    // `ret == (*self).k` and a bool comparison `ret ⇔ ((*self).k REL c)`, directly
    // or through such a getter (`is_empty` → `len`). Fail-closed per function in
    // trust-vcgen (`generate::return_field_summary`); consumed at call sites over
    // the caller's own spelling of the field. The same identity gate, applied as
    // the lane's own admission predicate rather than run by run: its rounds
    // compose one function's summary from another's (`is_empty` through `len`),
    // and its `def_path` collision count must see every extracted body.
    let return_field_summaries =
        trust_vcgen::compute_return_field_summaries_admitting(&funcs, |func| {
            summary_refused
                .as_ref()
                .is_some_and(|refused| !refused.contains(func.def_path.as_str()))
        });
    // Trust (2026-09-30): which calls reach each summarized body, from the `DefId`
    // it was extracted from. Every summary above is looked up by the call's
    // rendered name, and applies only at a call whose identity reaches the body.
    let mut summary_body_identities = summary_body_identities(tcx, &funcs, &func_def_ids);
    // A closure's def path is never a direct call's callee spelling (a closure is
    // called through `Fn*::call*`), so its identity entry is read only by the
    // closure-by-value consumers (`trust_vcgen`'s `summary_body_is_unique`).
    summary_body_identities.extend(self::summary_body_identities(
        tcx,
        &closure_funcs,
        &closure_def_ids,
    ));
    // Trust (D5-B): KERNEL-CHECKED body-inferred return equalities over the same
    // extraction. A candidate `_0 == E(params)` is proposed by an untrusted
    // synthesizer and minted only if the Clean kernel certifies every one of its
    // postcondition check VCs against the callee's own body; consumed per call
    // site through the existing postcondition-composition lane
    // (`add_direct_call_contract_summaries`). See `inferred_return`.
    let (inferred_returns, inferred_return_derivations) =
        inferred_return::mint_inferred_returns(tcx, &funcs, &func_def_ids, &summary_key_collisions);
    // Trust: original-body kernel-checked constructor field equalities, with
    // separate typed call-site facts and no aggregate refutation pinning.
    let constructor_returns =
        constructor_return::mint(tcx, &funcs, &func_def_ids, &summary_key_collisions);
    // Trust: TINV step 9 (e) — the census's item scan, instantiation drain and
    // crate-wide reconciliation run ONCE, after every inventoried body was scanned
    // (dyn facts are reconciled crate-wide), for whichever lane sealed a type. A
    // census over an incomplete inventory is never finished: both lanes withhold.
    let census_finished = backing_inventory_complete
        && census.as_mut().is_some_and(|census| {
            census.scan_items();
            census.drain();
            census.finish();
            true
        });
    // Trust: TINV step 9 (f) — the type-invariant mint, over the same complete
    // inventory, with the census's TINV denials. Its result is published below and
    // read by no VC or summary (step 10 is the consumer).
    let tinv_minted = if !tinv_enabled {
        type_invariant::TinvMinted::default()
    } else {
        // Parity (G1): every inventoried body was ALSO census-scanned and has its
        // metadata. Anything else withholds every candidate.
        let scans = census.as_ref().map_or(0, |census| census.scans());
        let parity = scans == backing_funcs.len() && backing_meta.len() == backing_funcs.len();
        if env_flag_enabled("TRUST_CERT_DEBUG") {
            eprintln!(
                "TRUST_CERT_DEBUG: TINV inventory: scans = {scans}, bodies = {}, meta = {}, \
                 complete = {backing_inventory_complete}",
                backing_funcs.len(),
                backing_meta.len()
            );
        }
        let tinv_denied: rustc_data_structures::fx::FxIndexMap<DefId, Vec<String>> = census
            .as_ref()
            .map(|census| {
                census
                    .denied()
                    .iter()
                    .filter(|(did, _)| tinv.contains_key(*did))
                    .map(|(did, reasons)| (*did, reasons.clone()))
                    .collect()
            })
            .unwrap_or_default();
        // Trust: TINV step 10.0 — the mint refuses at RUNTIME when a use set is
        // already visible in the session's callee-summary context (circularity).
        let use_set_visible = with_crate_verification_state(tcx.sess, |state| {
            state.callee_summaries.type_invariants().is_some()
        });
        // Trust: TINV (decision TINV-33) — the crate-wide `dyn`/parameter evidence,
        // only from a FINISHED census (else none: every such reach stays unknown).
        let tinv_opaque = match census.as_mut() {
            Some(census) if census_finished => {
                type_invariant::opaque_reach_evidence(tcx, &tinv, census)
            }
            _ => Default::default(),
        };
        type_invariant::trust_init_type_invariant_certificates(
            tcx,
            &tinv,
            tinv_gate_notes,
            &backing_funcs,
            &backing_meta,
            census_finished && parity,
            &tinv_denied,
            &tinv_opaque,
            use_set_visible,
        )
    };
    // 3b. Certify backing across the COMPLETE body inventory, intersect with
    //     the sealed set (only when a sealed backing struct exists — else
    //     nothing to certify). An incomplete inventory fails CLOSED: the
    //     certifier only weakens from evidence it sees, so judging from a
    //     partial view could only ever push TOWARD certification.
    let certified: FxHashSet<String> = if sealed.is_empty() {
        FxHashSet::default()
    } else if !backing_inventory_complete {
        if env_flag_enabled("TRUST_CERT_DEBUG") {
            eprintln!(
                "TRUST_CERT_DEBUG: backing inventory INCOMPLETE ({} body(ies) extracted); \
                 established = {{}} (fail closed)",
                backing_funcs.len()
            );
        }
        FxHashSet::default()
    } else {
        let mut established = trust_vcgen::certify_backing_invariants(&backing_funcs);
        // Trust (2026-09-30): the escape census's denials, after its item scan and
        // its per-instantiation scans of local generic bodies. Removing a name can
        // only withhold a certificate, never grant one.
        // Trust: TINV step 9 (e) — the census was finished above (here the inventory
        // is complete, so it was).
        if let Some(census) = census.as_ref() {
            let denied_names: FxHashSet<&str> = census
                .denied()
                .keys()
                .filter_map(|did| sealed_structs.get(did))
                // Trust: TINV step 6a — exhaustive per role, as for `sealed` above.
                .filter_map(|s| match s.role {
                    backing_escape_census::SealedRole::Backing { .. } => Some(s.name.as_str()),
                    // Trust: TINV step 6b — a TINV denial never withholds a backing name.
                    backing_escape_census::SealedRole::TypeInvariant => None,
                })
                .collect();
            established.retain(|name| !denied_names.contains(name.as_str()));
            if env_flag_enabled("TRUST_CERT_DEBUG") {
                for (did, reasons) in census.denied() {
                    if let Some(s) = sealed_structs.get(did)
                        && matches!(s.role, backing_escape_census::SealedRole::Backing { .. })
                    {
                        for reason in reasons {
                            eprintln!("TRUST_CERT_DEBUG: backing `{}` DENIED: {reason}", s.name);
                        }
                    }
                }
            }
        }
        if env_flag_enabled("TRUST_CERT_DEBUG") {
            eprintln!(
                "TRUST_CERT_DEBUG: extracted {} body(ies); established = {established:?}",
                backing_funcs.len()
            );
        }
        established.intersection(&sealed).cloned().collect()
    };
    debug!(
        "Trust: {} backing struct(s) certified (sealed ∩ established) of {} sealed",
        certified.len(),
        sealed.len(),
    );

    // Build the invocation-owned summary frames once. Both contexts are
    // internally shared, so every function snapshots them in O(1) rather than
    // cloning seven crate-sized maps and rebuilding the native subset.
    let native_bool_preds = return_bool_preds
        .iter()
        .filter(|(_, summary)| {
            summary.pred_field.is_none() && summary.kind == trust_vcgen::ReturnBoolPredKind::Iff
        })
        .map(|(def_path, summary)| {
            (
                def_path.clone(),
                trust_ir_bridge::NativeBoolPredSummary {
                    enum_name: summary.enum_name.clone(),
                    params_len: summary.params.len(),
                    pred_param: summary.pred_param,
                    pred_tag: summary.pred_tag,
                    pred_is_eq: summary.pred_is_eq,
                    variants: summary.variants.clone(),
                },
            )
        })
        .collect();
    let native_callee_summaries =
        trust_ir_bridge::NativeCalleeSummaryContext::with_bool_preds(native_bool_preds);
    // PAIRED-CONDVAR: whole-crate `#[trust::paired]` pairing certificates.
    // Reconciled at extraction time into a fresh compiler-owned exact-site
    // sidecar; source callee strings carry no authority. The discharge is per
    // CALL SITE, not per callee name. Empty for the common case (no attribute),
    // and on ANY completeness violation (fail closed).
    let paired_condvar_certificate =
        Arc::new(trust_mir_extract::certify_paired_condvars_for_crate(tcx));
    let callee_summaries = trust_vcgen::CalleeSummaryContext::default()
        .with_certified_backing_structs(certified)
        .with_return_bounds(return_bounds)
        .with_return_lower_bounds(return_lower_bounds)
        .with_return_const_sets(return_const_sets)
        .with_return_intervals(return_intervals)
        .with_return_payload_intervals(return_payload_intervals)
        .with_return_disc_summaries(return_disc_summaries)
        .with_setter_summaries(setter_summaries)
        .with_return_bool_preds(return_bool_preds)
        .with_return_ffi_pointer_contracts(return_ffi_pointer_contracts) // Trust: G1
        .with_summary_body_identities(summary_body_identities)
        .with_return_field_summaries(return_field_summaries) // Trust: TRUST-10
        .with_constructor_returns(constructor_returns)
        // Trust (ORD-WITNESS-CONSISTENT-1): the only payload types whose
        // comparison guards the ordering-witness lane may read as order facts.
        .with_order_consistent_adts(order_consistent_adts(tcx))
        // Trust (TINV step 10.5): INSTALL the run's published use set, behind the
        // tracked `-Ztrust-tinv` (default off). It is `Arc::clone` of the very set
        // stored in `type_invariant_use_set` below — never a rebuilt or deep-cloned
        // one: the grading decodes a row's tags only against a generation whose set is
        // POINTER-identical to the stored one (KNOWN_HAZARDS, 10.5 (a)), and the
        // liveness check after the publish refuses an install that is not. Installed
        // here, after Houdini, the ∧I gate, `mint_inferred_returns` and the backing
        // certification have all run, so no certificate can rest on a use-site fact.
        .with_type_invariants(type_invariant::installable_use_set(
            tinv_enabled,
            tinv_minted.use_set.as_ref(),
        ));
    with_crate_verification_state(tcx.sess, |state| {
        state.callee_summaries = callee_summaries;
        state.native_callee_summaries = native_callee_summaries;
        state.inferred_returns = inferred_returns;
        state.inferred_return_derivations = inferred_return_derivations;
        state.paired_condvar_certificate = Some(paired_condvar_certificate);
        // Trust: TINV step 9 (g) — published, consumed by nothing until step 10.
        state.tinv_initialized = tinv_enabled;
        state.type_invariant_certificates = tinv_minted.certificates;
        state.type_invariant_notes = tinv_minted.notes;
        // Trust: TINV step 10.0 — the run's use set is STORED; step 10.5 installs
        // `Arc::clone` of exactly this allocation into `callee_summaries` above.
        state.type_invariant_use_set = tinv_minted.use_set;
        // Trust: TINV step 10.5 — LIVENESS. The installed set must be the stored one
        // (pointer identity). A mismatch would make every tagged row refuse silently;
        // it is detected here, the install is withdrawn (no fact is given at all) and
        // the refusal is reported, never accepted.
        if !type_invariant::installed_use_set_is_live(
            state.callee_summaries.type_invariants(),
            state.type_invariant_use_set.as_ref(),
        ) {
            state.callee_summaries =
                std::mem::take(&mut state.callee_summaries).with_type_invariants(None);
            tcx.dcx().note(
                "Trust (TINV step 10.5): the installed type-invariant use set is not the \
                 stored published set; the install is withdrawn and no use-site fact is given",
            );
        }
        // Trust: TINV step 10.7 — the premise lines every surface discloses.
        state.type_invariant_disclosures = tinv_minted.disclosures;
        state.backing_initialized = true;
    });
}

/// Trust (2026-09-30): which calls reach each extracted body, keyed by its def path
/// — the definition side of `trust_vcgen::call_reaches_summarized_body`.
///
/// * A free function or an inherent impl's method is reached by every call whose
///   identity names its `DefId`, at any instantiation (`Item`).
/// * A trait impl's method is reached by a call naming the TRAIT item, and only at
///   the impl's own trait-reference arguments, normalized; those must be fully
///   concrete, and `Instance::try_resolve` must route that instantiation to this very
///   body (`Instance`). A generic impl's method gets no entry.
/// * A trait's default method gets no entry: a call names the trait item whichever
///   body runs, the default or an override.
///
/// A body whose symbol can be interposed at link time, or an intrinsic's fallback
/// body, gets no entry: the call need not run it.
///
/// A def path two extracted bodies share gets no entry either, since a summary keyed
/// by it may be either body's. Measured cause (round 7): a nested type is not
/// namespace-tagged, so `<Holder<krate::S::Inner> as Tr>::d` is both the def path of
/// an override and the rendering of a call that runs the default.
fn summary_body_identities<'tcx>(
    tcx: TyCtxt<'tcx>,
    funcs: &[trust_types::VerifiableFunction],
    def_ids: &[DefId],
) -> FxHashMap<String, trust_vcgen::SummaryBodyIdentity> {
    let mut seen: FxHashMap<&str, usize> = FxHashMap::default();
    for func in funcs {
        *seen.entry(func.def_path.as_str()).or_default() += 1;
    }
    funcs
        .iter()
        .zip(def_ids)
        .filter(|(func, _)| seen.get(func.def_path.as_str()) == Some(&1))
        .filter_map(|(func, &def_id)| {
            // A body the final link or the backend can replace is not the body a
            // call runs, whatever its identity: an exported symbol can be
            // interposed (`#[no_mangle]`, `#[export_name]`, a weak `#[linkage]`),
            // and an intrinsic's fallback body is overridden by codegen. Round 9
            // measured the first: a weak `#[export_name]` method's `x.min(3)`
            // proved, kernel-certified, a caller that ran a strong definition
            // returning `x`. The same exclusion as the inferred-return lane
            // (`inferred_return::identity_admissible`).
            let attrs = tcx.codegen_fn_attrs(def_id);
            if attrs.contains_extern_indicator()
                || attrs.symbol_name.is_some()
                || attrs.linkage.is_some()
                || tcx.intrinsic(def_id).is_some()
            {
                return None;
            }
            let reach = if tcx.trait_of_assoc(def_id).is_some() {
                return None;
            } else if let Some(impl_def_id) = tcx.trait_impl_of_assoc(def_id) {
                let trait_item = tcx.opt_associated_item(def_id)?.trait_item_def_id()?;
                let trait_ref =
                    tcx.impl_trait_ref(impl_def_id).instantiate_identity().skip_normalization();
                let args = ty::GenericArgs::identity_for_item(tcx, def_id).rebase_onto(
                    tcx,
                    impl_def_id,
                    trait_ref.args,
                );
                if args.has_non_region_param() {
                    return None;
                }
                // The call's identity is minted from NORMALIZED arguments, so the
                // header is normalized too (`impl Tr for [u8; N]`, `W<<u8 as Id>::Out>`).
                let typing_env = ty::TypingEnv::fully_monomorphized();
                let args = tcx
                    .try_normalize_erasing_regions(typing_env, ty::Unnormalized::new_wip(args))
                    .ok()?;
                // And only if rustc routes that instantiation to THIS body. Coherence
                // alone does not: under `specialization`, an impl whose where-clause
                // can never hold is not selected, and the call runs the fallback
                // (round 8: `impl<'a> Tr for Holder<u8> where &'a (): Never`).
                let routes_here = matches!(
                    ty::Instance::try_resolve(tcx, typing_env, trait_item, args),
                    Ok(Some(instance)) if instance.def == ty::InstanceKind::Item(def_id)
                );
                if !routes_here {
                    return None;
                }
                trust_vcgen::SummaryBodyIdentity::Instance(trust_mir_extract::instance_identity(
                    tcx, trait_item, args,
                )?)
            } else {
                trust_vcgen::SummaryBodyIdentity::Item {
                    stable_crate_id: tcx.stable_crate_id(def_id.krate).as_u64(),
                    def_index: def_id.index.as_u32(),
                }
            };
            Some((func.def_path.clone(), reach))
        })
        .collect()
}

/// Trust (TINV step 9): the `TRUST_TINV_NOTES` report — one note per type at its
/// definition: certified (with its conjuncts and kernel-certified row count) or
/// withheld, with every note the pre-pass recorded for it as a child. Report only.
// The certificate map is only collected into a lookup map; the report iterates the
// notes, which the pre-pass sorted by rendered name.
#[allow(rustc::potential_query_instability)]
fn report_type_invariants(tcx: TyCtxt<'_>) {
    let (initialized, notes, certified, consumers) =
        with_crate_verification_state(tcx.sess, |state| {
            (
                state.tinv_initialized,
                state.type_invariant_notes.clone(),
                state
                    .type_invariant_certificates
                    .iter()
                    // Trust (TINV-21): with the carried arm lemmas.
                    .map(|(did, cert)| {
                        (*did, (cert.conjuncts().len(), cert.rows().len(), cert.lemma_summary()))
                    })
                    .collect::<FxHashMap<DefId, (usize, usize, String)>>(),
                state.type_invariant_consumers.clone(),
            )
        });
    if !initialized {
        return;
    }
    for (did, lines) in notes {
        let name = trust_mir_extract::sysroot_authenticated_def_path_str(tcx, did);
        let headline = match certified.get(&did) {
            Some((conjuncts, rows, lemmas)) => format!(
                "TINV: type invariant of `{name}` certified: {conjuncts} conjunct(s), {rows} \
                 kernel-certified row(s), {lemmas}"
            ),
            None => format!("TINV: no type invariant of `{name}` is certified"),
        };
        let mut diag = tcx.dcx().struct_span_note(tcx.def_span(did), headline);
        for line in lines {
            diag.note(line);
        }
        // Trust (TINV step 10.7): the functions whose rows were graded under it.
        if certified.contains_key(&did) {
            match consumers.get(&name) {
                Some(fns) if !fns.is_empty() => diag.note(format!(
                    "consumed by {} function(s) (`TypeInvariantComposed` rows, each disclosing \
                     `assumes type_invariant({name})#k`): {}",
                    fns.len(),
                    fns.iter().map(String::as_str).collect::<Vec<_>>().join(", ")
                )),
                _ => diag.note("consumed by no function's row"),
            };
        }
        diag.emit();
    }
}

/// Trust: TINV step 9 (d) — record the metadata of one inventoried body beside its
/// `backing_funcs` push, from THE SAME rustc `body` that was extracted. A no-op when
/// no TINV candidate exists (the default), so the backing lane is unchanged.
fn tinv_meta_push<'tcx>(
    meta: &mut Vec<type_invariant::InventoryMeta>,
    tinv: &rustc_data_structures::fx::FxIndexMap<DefId, type_invariant::TinvCandidate>,
    census: &mut Option<backing_escape_census::Census<'_, 'tcx>>,
    body: &Body<'tcx>,
    def_id: DefId,
    promoted: Option<usize>,
) {
    if !tinv.is_empty() {
        meta.push(type_invariant::inventory_meta(body, def_id, promoted, tinv, census.as_mut()));
    }
}

/// Trust (INTERPOSE-SUM-1 2026-10-03; F6-INTERPOSE-1 2026-10-04): the IDENTITY gate of every
/// lane that turns a callee's BODY into a fact its call sites may use — `true`
/// when `def_id`'s extracted body need not be the body a call to it runs, or is
/// owned by another lane:
///
/// * a non-local def — no body of this compilation;
/// * a Clean-origin def — left to its own definitional lane
///   (`clean_origin_callee_summary`), as D5-B (`inferred_return.rs`) leaves it;
///   asked BEFORE `codegen_fn_attrs`, the order every identity gate keeps;
/// * a foreign item — its definition is wherever the linker finds it
///   (`contains_extern_indicator` answers `false` for one, so it is asked here);
/// * a symbol that can be interposed at link time: `#[no_mangle]`,
///   `#[export_name]`, `#[linkage]` (`contains_extern_indicator`, with the two
///   fields it reads spelled out as D5-B spells them). Another object can define
///   the same symbol and the call binds to it.
///
/// One predicate, so the gates cannot drift apart: the six summary lanes of
/// `trust_init_backing_certificates` (`summary_refused`), and since
/// F6-INTERPOSE-1 `f6_derived_callee_result_range` and
/// `extracted_callee_body_for_tracing`, whose only callers are the direct-call
/// summary build and its transitive trace worklist. Until then a
/// `#[no_mangle] fn f6_scale() -> f64 { 2.0 }` lent `x * f6_scale()` the interval
/// `[2, 2]`, certify dropped the `float_overflow_to_infinity` row, and a binary
/// that linked another `f6_scale` returned `inf`
/// (`tests/ui/trust/f6_float_range_interposable_callee_not_summarised.rs`).
///
/// Stateless, so a `DefId`-keyed memo behind a caller of it stays consistent.
fn body_summary_identity_refused(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    def_id.as_local().is_none_or(|local| {
        crate::clean_origin_mir::is_clean_origin(tcx, local) || tcx.is_foreign_item(def_id) || {
            let attrs = tcx.codegen_fn_attrs(def_id);
            attrs.contains_extern_indicator()
                || attrs.symbol_name.is_some()
                || attrs.linkage.is_some()
        }
    })
}

/// Trust (2026-10-05, SUMMARY-NAME-COLLIDE-1): the `def_path` keys that two or
/// more local body owners render to. No body-derived summary may be recorded
/// under one, in any lane: the six run lanes and the field lane through
/// `summary_refused`, D5-B through `mint_inferred_returns`.
///
/// Every lane keys its summary on the callee's rendered `def_path`
/// (`safe_def_path_str`), and a call site finds it by its own rendered callee
/// name; nothing at the call site names a `DefId`. The render is not injective:
/// it canonicalizes lifetimes to `'_` (`canonicalize_rendered_lifetimes`), and
/// two impls whose self types differ only in a region under a `for<>` binder are
/// distinct impls with distinct bodies (rust#56105, accepted with the
/// `coherence_leak_check` warning). Both methods of
/// `impl Tr for W<for<'a> fn(&'a u8) -> &'static u8>` and
/// `impl Tr for W<for<'a> fn(&'a u8) -> &'a u8>` render
/// `<k::W<for<'_> fn(&'_ u8) -> &'_ u8> as k::Tr>::get`, and the lanes kept
/// whichever body came last. MEASURED on the stage 1 of `76a6ea45b2`: a caller
/// through the first impl was handed the second impl's const-set, upper-bound,
/// lower-bound, setter and bool-predicate summaries, and its overflow, rem-by-zero
/// and `unwrap` rows proved — kernel-certified under certify — while a binary
/// running the first impl panicked (`tests/ui/trust/summary_hrtb_impl_name_collision.rs`).
///
/// The universe is EVERY `mir_keys` owner, not only the extracted `funcs`: a
/// stolen `#[rustc_comptime]` body, a constructor shim or any other body owner
/// that renders the same key is still something a call can name, and the field
/// lane's and D5-B's own duplicate counts saw only the extracted bodies. Each
/// extracted body is fed again with its own `DefId`, which is one owner, not a
/// second. A `DefId`-keyed summary (the call's `CalleeIdentity` against the
/// body's) would make this unnecessary; it needs trait-method resolution at the
/// call site first, so this refuses instead.
///
/// This set is the DEFINITION-side half only: it sees two definitions that
/// render one key. A CALL can also print as a definition's key while running
/// another body (a call through a bounded generic impl, instantiated so that
/// it prints as a concrete sibling impl's key); only one definition renders
/// that key, so nothing here fires. That half is closed where the call is
/// named (`trust_mir_extract::convert::tag_local_definition_key_alias`, 2026-10-05,
/// `tests/ui/trust/summary_generic_impl_call_key_alias.rs`).
fn body_summary_key_collisions(
    tcx: TyCtxt<'_>,
    funcs: &[trust_types::VerifiableFunction],
    func_def_ids: &[DefId],
) -> FxHashSet<String> {
    let rendered: Vec<(String, DefId)> = tcx
        .mir_keys(())
        .iter()
        .map(|&local_def_id| {
            let def_id = local_def_id.to_def_id();
            (trust_mir_extract::safe_def_path_str(tcx, def_id), def_id)
        })
        .collect();
    trust_vcgen::summary_key_collisions(
        rendered.iter().map(|(key, def_id)| (key.as_str(), *def_id)).chain(
            funcs.iter().zip(func_def_ids).map(|(func, def_id)| (func.def_path.as_str(), *def_id)),
        ),
    )
}

/// Trust (2026-10-05, ORD-WITNESS-CONSISTENT-1): the rendered names (the
/// extracted `Ty::Adt` name, `sysroot_authenticated_def_path_str`) of the local
/// types whose `PartialOrd` operators are ONE consistent total order — the only
/// payload types whose comparison guards the ordering-witness lane
/// (`trust_vcgen::generate::witness_grounding`) may read as facts about the
/// integer order its contract atoms are encoded in.
///
/// That lane read a dominating `a <= b` as `a ≤ b` over ℤ and discharged a
/// contract atom spelled with ANOTHER operator (`d > c`) against it. Rust does
/// not enforce the `PartialOrd` laws: a hand-written impl whose `le` and `gt`
/// both answer `true` is valid, and `!matches!(r, Ok((d, c)) if d > c)` was
/// reported proved under certify for a body that returns `Ok((1, 2))` with
/// `d > c` true (`tests/ui/trust/ordering_witness_inconsistent_partial_ord.rs`).
/// Even `Some(self.cmp(o))` with the default operators is not enough: an impure
/// `cmp` breaks agreement between the guard's call and the contract's.
///
/// A type is admitted when, all decided from `TyCtxt`:
///  * it is a local, non-generic `struct` or `enum` whose rendered name no other
///    local ADT shares, in a crate graph where no other crate shares this
///    crate's name (the name is the lane's only key);
///  * its `PartialEq<Self>`, `PartialOrd<Self>` and (if it has one) `Ord` impls
///    are each the only one and each `is_builtin_derived` — `#[automatically_derived]`
///    alone is writable by hand, the builtin-macro expansion is not — and each
///    defines only the method the derive emits (`eq`, `partial_cmp`, `cmp`), so
///    `lt`/`le`/`gt`/`ge` are core's defaults over one `partial_cmp`;
///  * every field is an integer, `bool` or `char`, or an admitted type. The
///    derived `partial_cmp` is then the lexicographic order of total orders —
///    pure, total (never `None`), and `Equal` exactly when the derived `==`
///    holds — so the {Lt, Eq, Gt} reading the lane pins is exact.
///
/// The three traits must be authentic core's (`crate_is_authentic_core`). Any
/// failure admits nothing. MEASURED on the stage 1 of `76a6ea45b2`: the
/// comparisons of such a type do not reach the lane today, because the
/// extractor rewrites a provably-total derived comparison to the total-call
/// sentinel (`apply_total_partial_ord_sentinel`), so this set gates a credit no
/// current extraction asks for. The capability cost is ny-cert's `Rat` (a
/// hand-written `Ord` over an arena): DECISION_QUEUE ORD-WITNESS-CONSISTENT-1.
// Iteration order over the candidate set cannot reach the result: `retain` keeps
// each member by a test that reads only the previous round's snapshot, the
// result is itself a set, and the debug listing is sorted before it is printed.
#[allow(rustc::potential_query_instability)]
fn order_consistent_adts(tcx: TyCtxt<'_>) -> FxHashSet<String> {
    let mut admitted = FxHashSet::default();
    let lang_items = tcx.lang_items();
    let (Some(eq_trait), Some(partial_ord_trait)) =
        (lang_items.eq_trait(), lang_items.partial_ord_trait())
    else {
        return admitted;
    };
    if !crate_is_authentic_core(tcx, eq_trait.krate)
        || !crate_is_authentic_core(tcx, partial_ord_trait.krate)
    {
        return admitted;
    }
    let ord_trait = authentic_core_diagnostic_item(tcx, sym::Ord);
    let local_name = tcx.crate_name(LOCAL_CRATE);
    if tcx.crates(()).iter().any(|&krate| tcx.crate_name(krate) == local_name) {
        return admitted;
    }
    // Per local ADT: its impls of the three traits, `Rhs = Self` only (another
    // `Rhs` is a different trait instance and no `<T as PartialOrd>::le` call
    // reaches it).
    #[derive(Default)]
    struct CmpImpls {
        eq: Vec<DefId>,
        partial_ord: Vec<DefId>,
        ord: Vec<DefId>,
    }
    let mut cmp_impls: FxHashMap<DefId, CmpImpls> = FxHashMap::default();
    let mut adts: Vec<DefId> = Vec::new();
    let mut name_count: FxHashMap<String, usize> = FxHashMap::default();
    for local in tcx.hir_crate_items(()).definitions() {
        let def_id = local.to_def_id();
        match tcx.def_kind(def_id) {
            DefKind::Struct | DefKind::Enum | DefKind::Union => {
                *name_count
                    .entry(trust_mir_extract::sysroot_authenticated_def_path_str(tcx, def_id))
                    .or_default() += 1;
                if !matches!(tcx.def_kind(def_id), DefKind::Union)
                    && tcx.generics_of(def_id).count() == 0
                {
                    adts.push(def_id);
                }
            }
            DefKind::Impl { of_trait: true } => {
                let trait_ref =
                    tcx.impl_trait_ref(def_id).instantiate_identity().skip_normalization();
                let self_ty = trait_ref.self_ty();
                let ty::Adt(adt, _) = self_ty.kind() else { continue };
                let rhs_is_self = trait_ref.args.types().nth(1) == Some(self_ty);
                if trait_ref.def_id == eq_trait && rhs_is_self {
                    cmp_impls.entry(adt.did()).or_default().eq.push(def_id);
                } else if trait_ref.def_id == partial_ord_trait && rhs_is_self {
                    cmp_impls.entry(adt.did()).or_default().partial_ord.push(def_id);
                } else if Some(trait_ref.def_id) == ord_trait {
                    cmp_impls.entry(adt.did()).or_default().ord.push(def_id);
                }
            }
            _ => {}
        }
    }
    // The impl is the derive's own: compiler-expanded, and defining exactly the
    // one method the derive emits.
    let derived_only = |impl_did: DefId, method: Symbol| {
        tcx.is_builtin_derived(impl_did)
            && tcx
                .associated_item_def_ids(impl_did)
                .iter()
                .all(|&item| tcx.opt_item_name(item) == Some(method))
    };
    let mut candidates: FxHashSet<DefId> = adts
        .into_iter()
        .filter(|did| {
            let Some(impls) = cmp_impls.get(did) else { return false };
            let eq_derived = matches!(impls.eq.as_slice(), [only] if derived_only(*only, sym::eq));
            let partial_ord_derived = matches!(
                impls.partial_ord.as_slice(),
                [only] if derived_only(*only, sym::partial_cmp)
            );
            let ord_derived_or_absent = match impls.ord.as_slice() {
                [] => true,
                [only] => derived_only(*only, sym::cmp),
                _ => false,
            };
            let name = trust_mir_extract::sysroot_authenticated_def_path_str(tcx, *did);
            eq_derived
                && partial_ord_derived
                && ord_derived_or_absent
                && name_count.get(&name) == Some(&1)
        })
        .collect();
    // Fields: integers, `bool`, `char`, or another candidate — to a fixpoint, so
    // a type whose field type drops out drops out too.
    loop {
        let before = candidates.len();
        let snapshot = candidates.clone();
        candidates.retain(|did| {
            tcx.adt_def(*did).all_fields().all(|field| {
                let field_ty = tcx.type_of(field.did).instantiate_identity().skip_normalization();
                match field_ty.kind() {
                    ty::Int(_) | ty::Uint(_) | ty::Bool | ty::Char => true,
                    ty::Adt(field_adt, _) => snapshot.contains(&field_adt.did()),
                    _ => false,
                }
            })
        });
        if candidates.len() == before {
            break;
        }
    }
    for did in candidates {
        admitted.insert(trust_mir_extract::sysroot_authenticated_def_path_str(tcx, did));
    }
    if env_flag_enabled("TRUST_ORDWIT_DEBUG") {
        let mut names: Vec<_> = admitted.iter().collect();
        names.sort();
        eprintln!("TRUST_ORDWIT_DEBUG: order-consistent ADTs = {names:?}");
    }
    admitted
}

/// Trust (2026-10-03, INTERPOSE-SUM-1): the maximal runs of `funcs` between the
/// bodies the summary identity gate refuses, in order, empty runs dropped. With
/// `refused` absent (the gate admits nothing: its parallel-vector check failed)
/// there are no runs at all.
fn admitted_summary_runs<'f>(
    funcs: &'f [trust_types::VerifiableFunction],
    refused: Option<&FxHashSet<&str>>,
) -> Vec<&'f [trust_types::VerifiableFunction]> {
    let Some(refused) = refused else {
        return Vec::new();
    };
    funcs
        .split(|func| refused.contains(func.def_path.as_str()))
        .filter(|run| !run.is_empty())
        .collect()
}

/// Trust (2026-10-03, INTERPOSE-SUM-1): one per-function summary lane of
/// `trust_init_backing_certificates`, computed over the runs of the crate's
/// extraction its identity gate admits, merged in run order — the lane's map over
/// the admitted functions alone, with no refused body ever handed to `compute`.
/// That equality holds only for a lane that reads one body per entry and no other
/// function or summary, keyed on that body's `def_path` (a later body with the
/// same key replaces an earlier one, as in a single pass). A lane that composes
/// across functions takes the gate as an admission predicate instead
/// (`compute_return_field_summaries_admitting`).
///
/// The iteration order of a run's map cannot reach the result: its keys are
/// unique, and the runs are merged in their fixed order.
fn summaries_over_admitted_runs<M>(
    admitted_runs: &[&[trust_types::VerifiableFunction]],
    compute: impl Fn(&[trust_types::VerifiableFunction]) -> M,
) -> M
where
    M: Default + IntoIterator + Extend<<M as IntoIterator>::Item>,
{
    let mut summaries = M::default();
    for &run in admitted_runs {
        summaries.extend(compute(run));
    }
    summaries
}

/// Trust: local `#[trust::backing]` structs of the unambiguous buffer+length
/// shape (exactly one raw-pointer field + one unsigned-integer field) whose BOTH
/// backing fields are PRIVATE — Rust then forbids any external crate from
/// constructing (a private field blocks the struct literal) or mutating those
/// fields by name. Privacy alone does not close the world, though: in-crate
/// code can reach the same storage through a raw pointer, a transmute, a union,
/// a foreign or unsafe callee, or a generic body instantiated with the struct.
/// The escape census (`backing_escape_census`) is what checks that none does.
///
/// Keyed by the struct's `DefId`; each entry carries the certificate key
/// (`safe_def_path_str`, the extracted IR's `Ty::Adt` name) and the two fields
/// the invariant relates.
fn compute_sealed_backing_structs(
    tcx: TyCtxt<'_>,
) -> rustc_data_structures::fx::FxIndexMap<DefId, backing_escape_census::SealedType> {
    // Trust: TINV step 6a — the census record is `SealedType { name, role }`.
    let mut sealed = rustc_data_structures::fx::FxIndexMap::default();
    for item in tcx.hir_crate_items(()).free_items() {
        let did = item.owner_id.to_def_id();
        if !matches!(tcx.def_kind(did), DefKind::Struct)
            || !item_has_trust_attr(tcx, did, "backing")
        {
            continue;
        }
        let variant = tcx.adt_def(did).non_enum_variant();
        let args = ty::GenericArgs::identity_for_item(tcx, did);
        let mut ptr_field: Option<(rustc_abi::FieldIdx, &ty::FieldDef)> = None;
        let mut len_field: Option<(rustc_abi::FieldIdx, &ty::FieldDef)> = None;
        let mut ptrs = 0usize;
        let mut uints = 0usize;
        for (idx, f) in variant.fields.iter_enumerated() {
            let fty = f.ty(tcx, args).skip_normalization();
            if fty.is_raw_ptr() {
                ptrs += 1;
                ptr_field = Some((idx, f));
            } else if matches!(fty.kind(), ty::Uint(_)) {
                uints += 1;
                len_field = Some((idx, f));
            }
        }
        if ptrs == 1
            && uints == 1
            && let (Some((pi, pf)), Some((li, lf))) = (ptr_field, len_field)
            && !pf.vis.is_public()
            && !lf.vis.is_public()
        {
            sealed.insert(
                did,
                // Trust: TINV step 6a — `SealedType { name, role: Backing { .. } }`.
                backing_escape_census::SealedType {
                    name: trust_mir_extract::safe_def_path_str(tcx, did),
                    role: backing_escape_census::SealedRole::Backing {
                        ptr_field: pi,
                        len_field: li,
                    },
                },
            );
        }
    }
    sealed
}

/// Trust (2026-09-30): the ESCAPE CENSUS — the closed-world half of a backing
/// certificate's premise, checked instead of assumed.
///
/// A certificate for a sealed `#[trust::backing]` struct `S { ptr, len }` publishes
/// the use-site ASSUME `alloc_size >= self.len`, which turns a guarded
/// `self.ptr.add(i)` into a PROVED `[unsafe:sep:offset]` row. That is sound only if
/// every value of `S` that can ever exist came out of a struct literal the
/// certifier audited (`trust_vcgen::certify_backing_invariants`) and was never
/// written afterwards. The certifier sees struct literals and field-projection
/// stores in the extracted IR, and field privacy stops OTHER crates from naming the
/// fields — but neither sees the ways in-crate code reaches `S`'s bytes WITHOUT
/// naming a field, and each of those was a measured false PROVED row:
/// `*((b as *mut S as *mut usize).add(1)) = n`, `u.raw.1 = n` over a union holding
/// `ManuallyDrop<S>`, `transmute::<(*const u8, usize), S>(..)`, an `extern "C"`
/// callee handed `&mut S`, `ptr::write_bytes` over an `S`.
///
/// The census runs over every body the certifier's inventory holds (the same
/// completeness discipline: a body it cannot read blocks certification CLOSED) and
/// over the crate's item declarations, and DENIES `S` when any of them:
///
/// * writes `S`'s pointer or length field in place (a store, a `&mut`/`&raw`
///   borrow, a call or asm destination) — through any path, including a raw
///   pointer, a containing value, or a coroutine's saved state;
/// * takes a raw pointer to storage that holds `S` (the place's type, or any
///   prefix of it after the last deref, reaches `S`), holds or casts a value
///   whose type is a raw pointer (or `NonNull`) to something reaching `S`, or
///   assembles one;
/// * transmutes to or from a type reaching `S`, declares a union reaching `S`,
///   or projects/constructs such a union by a field it can name;
/// * erases a value reaching `S` into a `dyn Trait` and — in any body — recovers a
///   thin pointer or an integer out of a `dyn` pointer (which discards the vtable,
///   the only sanctioned access to the erased bytes). The concrete type is gone
///   from the `dyn`, so the census records what each body erases and reconciles the
///   two facts crate-wide in `finish`;
/// * mentions (calls or reifies) a foreign function, an unsafe intrinsic, or an
///   unsafe function whose body is not in this crate — or is HANDED a `&mut`/raw
///   path reaching `S` by a safe function of a crate that is neither this one nor
///   the authenticated sysroot — with a type reaching `S` among its generic
///   arguments, parameters or return type (`Pin`'s unchecked
///   constructors/projections, and the parametric unsafe accessors
///   `ManuallyDrop::{drop,take}`/`get_unchecked(_mut)`/`unwrap_unchecked`, are
///   exempt: they move a pointer or a whole value, never a pointee's bytes);
/// * declares a foreign function or static over `S`, exports a function or static
///   over `S` by symbol or foreign ABI, `unsafe impl`s a THIRD-PARTY non-auto trait
///   for a type reaching `S`, or hands `S`'s storage to inline or global assembly.
///
/// Generic code is followed per INSTANTIATION, not per definition: a local generic
/// body is scanned again with the arguments at every site that instantiates it
/// with a type reaching `S` — a direct call or reification, a trait method
/// resolved to a local generic impl, a dyn coercion's vtable, drop glue of a local
/// generic `Drop` impl, a generic closure or coroutine, a generic constant, a
/// local generic impl a sysroot API can reach through its trait bounds, and the
/// own-generic METHODS of such an impl (with the impl's arguments fixed to `S` and
/// the method's own parameters left parametric).
///
/// What is TRUSTED rather than checked (docs/TCB.md): the authenticated sysroot's
/// SAFE APIs (a safe `core`/`alloc`/`std` function is parametric in its type
/// arguments and cannot break an invariant of a type whose fields it cannot name),
/// a short list of parametric UNSAFE sysroot accessors whose unsafety is a
/// precondition rather than type-punning, a third-party crate's read-only or
/// by-value use of `S`, and the Rust privacy premise that code outside this crate —
/// including another crate's instantiation of this crate's public generic API —
/// does not use `unsafe` to write a private field. The census only ever REMOVES a
/// struct from the certified set.
mod backing_escape_census {
    use std::rc::Rc;

    use rustc_abi::FieldIdx;
    use rustc_data_structures::fx::{FxHashMap, FxHashSet, FxIndexMap, FxIndexSet};
    use rustc_hir::def::DefKind;
    use rustc_index::IndexVec;
    use rustc_index::bit_set::DenseBitSet;
    use rustc_middle::mir::visit::{
        MutatingUseContext, NonMutatingUseContext, PlaceContext, Visitor,
    };
    use rustc_middle::mir::{
        self, AggregateKind, Body, CastKind, ConstOperand, InlineAsmOperand, Local, LocalDecl,
        Location, Operand, Place, ProjectionElem, RawPtrKind, Rvalue, StatementKind, Terminator,
        TerminatorKind,
    };
    use rustc_middle::ty::adjustment::PointerCoercion;
    use rustc_middle::ty::print::with_no_trimmed_paths;
    use rustc_middle::ty::{
        self, GenericArgs, Instance, InstanceKind, ShimKind, Ty, TyCtxt, TypeVisitableExt,
        TypingEnv,
    };
    use rustc_span::def_id::DefId;
    use rustc_span::sym;

    /// Trust: TINV step 6a — a sealed type the census guards: the name its
    /// certificate is keyed by and the role that says what is sealed about it.
    pub(in super::super) struct SealedType {
        pub(in super::super) name: String,
        pub(in super::super) role: SealedRole,
    }

    /// Trust: TINV step 6a — why a type is sealed.
    pub(in super::super) enum SealedRole {
        /// A `#[trust::backing]` struct: the two fields its invariant relates.
        Backing { ptr_field: FieldIdx, len_field: FieldIdx },
        /// Trust: TINV step 6b — a type-invariant candidate
        /// (`type_invariant::compute_invariant_candidate_types`). Every field is
        /// sealed: no field write is denied here (writes are the windows vcgen
        /// checks), but the TINV-only denials D1-D5 apply to it on top of the
        /// shared ones. A denial of one role never withholds the other.
        TypeInvariant,
    }

    /// Instance scans the census performs after the inventory, and type nodes one
    /// type walk visits. Past either bound the census fails CLOSED (every sealed
    /// struct is denied): polymorphic recursion can generate unboundedly many
    /// instantiations, and a partial census is exactly the premise it must not
    /// publish.
    const MAX_INSTANCES: usize = 20_000;
    const MAX_WALK: usize = 100_000;
    /// Distinct denial reasons kept per struct, for the debug report. One is enough
    /// to deny; the rest say which other paths a fix would also have to close.
    const MAX_REASONS: usize = 8;

    /// What one type walk learned about a type.
    #[derive(Default)]
    struct TyFacts<'tcx> {
        /// Sealed structs whose storage the type holds, or points to through a
        /// reference, raw pointer, `Box`-like argument, upvar or saved local.
        reached: Vec<DefId>,
        /// Local GENERIC closures, coroutines and coroutine-closures the type
        /// contains, with their parent's type arguments: their bodies run with the
        /// type's arguments.
        bodies: Vec<(DefId, GenericArgs<'tcx>, Vec<Ty<'tcx>>)>,
        /// Local ADT instances whose local `Drop` impl is generic: the drop glue of
        /// the type runs that impl with the ADT's arguments.
        drops: Vec<Ty<'tcx>>,
        /// Whether the type holds, or points to storage that holds, a `dyn Trait`
        /// (anywhere `reached` would look: behind any reference, raw pointer or
        /// `Box`-like argument, in a field, upvar or saved local).
        holds_dyn: bool,
    }

    /// What `Census::mut_reached` learned about a type.
    struct MutReach {
        /// Sealed structs the type reaches through a mutable reference or raw pointer.
        sealed: Vec<DefId>,
        /// Whether it reaches a `dyn Trait` through one.
        dyn_trait: bool,
    }

    struct Pending<'tcx> {
        def: DefId,
        args: GenericArgs<'tcx>,
        /// The body whose typing environment the arguments' remaining parameters
        /// (if any) live in.
        env_def: DefId,
    }

    pub(in super::super) struct Census<'a, 'tcx> {
        tcx: TyCtxt<'tcx>,
        sealed: &'a FxIndexMap<DefId, SealedType>, // Trust: TINV step 6a
        /// Each denied struct with the distinct reasons found, in scan order (the
        /// first `MAX_REASONS` of them).
        denied: FxIndexMap<DefId, Vec<String>>,
        queue: Vec<Pending<'tcx>>,
        queued: FxHashSet<(DefId, GenericArgs<'tcx>)>,
        followed: FxHashSet<(DefId, GenericArgs<'tcx>)>,
        facts: FxHashMap<Ty<'tcx>, Rc<TyFacts<'tcx>>>,
        raw: FxHashMap<Ty<'tcx>, Rc<Vec<DefId>>>,
        mutable: FxHashMap<Ty<'tcx>, Rc<MutReach>>,
        processed: usize,
        /// Sealed structs a body unsize-coerces INTO a `dyn Trait` pointer. Once
        /// erased, the concrete type is gone: a `dyn` pointer's own type reaches
        /// nothing, so `facts`/`raw_reached` cannot see the struct behind it, and
        /// the vtable is the only sanctioned way to touch its bytes.
        dyn_erased: FxIndexSet<DefId>,
        /// Whether raw byte access to whatever was erased into a `dyn` can be
        /// recovered past its vtable: a body casts a pointer to `dyn Trait` to a thin
        /// pointer (or exposes its provenance as an integer) — `note_dyn_to_thin` —
        /// or a function whose body is in neither this crate nor the sysroot is handed
        /// a mutable or raw path reaching a `dyn` (it can make that cast itself) —
        /// `note_dyn_handoff`. Because the erased type is gone, either is tied to no
        /// specific struct; taken together with `dyn_erased` at `finish`, it denies
        /// every struct that this crate ever put behind a `dyn` (trait-upcasting makes
        /// a finer, per-trait match unsound). The first such reason found is kept.
        ///
        /// "Recovers" is decided per operation kind, with no kind left out: every
        /// cast kind and rvalue (`BodyScan::visit_rvalue`), a union accessed or built
        /// over a `dyn` pointer, every intrinsic, and the calls whose body the census
        /// does not scan and does not trust as parametric over a `dyn` (`dyn_call`).
        dyn_to_thin: Option<String>,
        /// Sealed structs handed to code whose body the census does not scan (a
        /// sysroot or third-party function, an intrinsic, a foreign function): that
        /// code can erase them into a `dyn` itself (`std::panic::panic_any` boxes its
        /// payload as `Box<dyn Any + Send>`), and the `dyn` can come back to this
        /// crate, so `finish` denies them with `dyn_erased`.
        handed_out: FxIndexSet<DefId>,
        /// Per-type memo of `carries_address`.
        addresses: FxHashMap<Ty<'tcx>, bool>,
        /// Trust: TINV step 6b — whether any sealed type has the `TypeInvariant`
        /// role. Every TINV-only scan (D1-D5) runs only then, so a crate with only
        /// backing structs is scanned exactly as before.
        has_tinv: bool,
        /// Trust: TINV step 6b — per-type memo of `owned_or_mut_reached` (D1).
        owned_mut: FxHashMap<Ty<'tcx>, Rc<Vec<DefId>>>,
        /// Trust: TINV step 6b — per-type memo of the D3 structural walk.
        unclassified: FxHashMap<Ty<'tcx>, Rc<D3Walk<'tcx>>>,
        /// Trust: TINV step 9 — inventoried bodies scanned (`scan_body` calls), for
        /// the inventory parity check.
        scans: usize,
        /// Trust: TINV (decision TINV-33) — sealed structs some type argument of a queued
        /// local generic instantiation reaches (`enqueue`): a type parameter of that
        /// item's polymorphic body may stand for a type reaching them.
        instantiated: FxIndexSet<DefId>,
        /// Trust: TINV — per local generic def, whether its body mentions a projection
        /// over its own parameters (`def_has_param_aliases`).
        param_alias_defs: FxHashMap<DefId, bool>,
        /// Trust (decision CENSUS-THIRD-PARTY-1) — the first use of THIRD-PARTY code
        /// found (a call of, an impl of, or a value of an item of a crate that is
        /// neither this crate nor the sysroot, `sysroot_def`). When set, `finish`
        /// denies EVERY sealed struct: no certificate rests on what third-party code
        /// can forge or corrupt.
        third_party_use: Option<String>,
    }

    /// Trust: TINV step 6b — what the D3 walk of one local type found.
    #[derive(Default)]
    struct D3Walk<'tcx> {
        /// The walk ran past `MAX_WALK`: the type is not classified.
        overflow: bool,
        /// Alias types met in storage positions; each must normalize.
        aliases: Vec<Ty<'tcx>>,
        /// A `dyn` whose trait or projection arguments reach a TINV type.
        dyn_reaches_tinv: bool,
    }

    impl<'a, 'tcx> Census<'a, 'tcx> {
        pub(in super::super) fn new(
            tcx: TyCtxt<'tcx>,
            sealed: &'a FxIndexMap<DefId, SealedType>, // Trust: TINV step 6a
        ) -> Self {
            Census {
                tcx,
                sealed,
                denied: FxIndexMap::default(),
                queue: Vec::new(),
                queued: FxHashSet::default(),
                followed: FxHashSet::default(),
                facts: FxHashMap::default(),
                raw: FxHashMap::default(),
                mutable: FxHashMap::default(),
                processed: 0,
                dyn_erased: FxIndexSet::default(),
                dyn_to_thin: None,
                handed_out: FxIndexSet::default(),
                addresses: FxHashMap::default(),
                // Trust: TINV step 6b.
                has_tinv: sealed.values().any(|s| matches!(s.role, SealedRole::TypeInvariant)),
                owned_mut: FxHashMap::default(),
                unclassified: FxHashMap::default(),
                scans: 0,
                instantiated: FxIndexSet::default(),
                param_alias_defs: FxHashMap::default(),
                third_party_use: None,
            }
        }

        /// Trust: TINV step 9 — the number of inventoried bodies `scan_body` saw.
        pub(in super::super) fn scans(&self) -> usize {
            self.scans
        }

        /// Trust: TINV step 6b — the members of `structs` with the TINV role.
        fn tinv_only(&self, structs: &[DefId]) -> Vec<DefId> {
            structs
                .iter()
                .copied()
                .filter(|did| {
                    self.sealed
                        .get(did)
                        .is_some_and(|s| matches!(s.role, SealedRole::TypeInvariant))
                })
                .collect()
        }

        /// Trust: TINV step 6b — every sealed type with the TINV role.
        fn tinv_all(&self) -> Vec<DefId> {
            let all: Vec<DefId> = self.sealed.keys().copied().collect();
            self.tinv_only(&all)
        }

        /// Trust: TINV step 9 — the TINV types a value of `ty` reaches (the census's
        /// own walk, `facts`), for the extractor cross-check (G1b-b).
        pub(in super::super) fn tinv_reached(&mut self, ty: Ty<'tcx>) -> Vec<DefId> {
            let reached = self.reached(ty);
            self.tinv_only(&reached)
        }

        /// Trust: TINV (decision TINV-33) — the census's crate-wide evidence for the
        /// sealed struct `did`, read only after `finish`: `(dyn, param)`. `dyn`: no scanned
        /// body unsizes a type reaching it into a `dyn` (`dyn_erased`) and it is never handed
        /// to code the census does not scan (`handed_out`, which may erase it itself).
        /// `param`: additionally, no local generic instantiation the census followed has a
        /// type argument reaching it (`instantiated`). The caller adds crate privacy and the
        /// opaque-type check; neither is a census fact.
        pub(in super::super) fn tinv_opaque_reach(&self, did: DefId) -> (bool, bool) {
            let dyn_clear = !self.dyn_erased.contains(&did) && !self.handed_out.contains(&did);
            (dyn_clear, dyn_clear && !self.instantiated.contains(&did))
        }

        /// Trust: TINV (decision TINV-33) — the TINV types a value of `ty` may hold, or
        /// `None` when the census walk cannot say (a parameter, an alias, a `dyn`, or an
        /// unnormalizable type), in the typing environment of `def`.
        pub(in super::super) fn tinv_reached_closed(
            &mut self,
            def: DefId,
            ty: Ty<'tcx>,
        ) -> Option<Vec<DefId>> {
            let env = TypingEnv::post_analysis(self.tcx, def);
            let ty = self.tcx.try_normalize_erasing_regions(env, ty::Unnormalized::new(ty)).ok()?;
            if ty.has_param() || ty.has_aliases() || self.holds_dyn(ty) {
                return None;
            }
            Some(self.tinv_reached(ty))
        }

        /// Trust: TINV (decision TINV-32) — the TINV types a MIR constant of type `ty`
        /// in `body` may hold, or `None` when this walk is no evidence: the type keeps a
        /// parameter (`facts` covers a parameter per instantiation, and a polymorphic
        /// body's `T::C` may be an `S`), keeps an alias after normalization, does not
        /// normalize, or holds a `dyn` (a `&'static dyn Any` may point at an `S`; a walk
        /// past `MAX_WALK` sets `holds_dyn` too, so overflow is covered).
        pub(in super::super) fn tinv_const_reached(
            &mut self,
            body: &Body<'tcx>,
            ty: Ty<'tcx>,
        ) -> Option<Vec<DefId>> {
            let ty = self
                .tcx
                .try_normalize_erasing_regions(body.typing_env(self.tcx), ty::Unnormalized::new(ty))
                .ok()?;
            if ty.has_param() || ty.has_aliases() || self.holds_dyn(ty) {
                return None;
            }
            Some(self.tinv_reached(ty))
        }

        /// Trust: TINV step 6b (D1) — the sealed structs a value of `root` OWNS or
        /// reaches through a mutable reference or raw pointer: every position except
        /// one below a shared reference. A shared `&` clears the flag for everything
        /// beneath it; `&mut`, raw pointers, `NonNull` and owned components keep it.
        /// Memoized per type; fails closed past the walk bound (every sealed struct).
        fn owned_or_mut_reached(&mut self, root: Ty<'tcx>) -> Rc<Vec<DefId>> {
            if let Some(hit) = self.owned_mut.get(&root) {
                return Rc::clone(hit);
            }
            let tcx = self.tcx;
            let mut out = Vec::new();
            let mut seen: FxHashSet<(Ty<'tcx>, bool)> = FxHashSet::default();
            let mut stack = vec![(root, true)];
            while let Some((ty, writable)) = stack.pop() {
                if !seen.insert((ty, writable)) {
                    continue;
                }
                if seen.len() > MAX_WALK {
                    out = self.sealed.keys().copied().collect();
                    break;
                }
                match *ty.kind() {
                    ty::Ref(_, inner, mutbl) => stack.push((inner, writable && mutbl.is_mut())),
                    ty::RawPtr(inner, _) => stack.push((inner, writable)),
                    ty::Adt(adt, args)
                        if tcx.is_lang_item(
                            adt.did(),
                            rustc_attr_ir::lang_items::LangItem::NonNull,
                        ) =>
                    {
                        stack.push((args.type_at(0), writable))
                    }
                    ty::Dynamic(preds, ..) => {
                        // A `dyn`'s trait arguments are the types its methods take and
                        // return; kept at the current flag (conservative).
                        for pred in preds.iter() {
                            match pred.skip_binder() {
                                ty::ExistentialPredicate::Trait(trait_ref) => {
                                    stack.extend(trait_ref.args.types().map(|t| (t, writable)))
                                }
                                ty::ExistentialPredicate::Projection(projection) => {
                                    stack.extend(projection.args.types().map(|t| (t, writable)));
                                    if let Some(term) = projection.term.as_type() {
                                        stack.push((term, writable));
                                    }
                                }
                                ty::ExistentialPredicate::AutoTrait(_) => {}
                            }
                        }
                    }
                    _ => {
                        // Trust (final review): interior mutability (`UnsafeCell`, `Cell`,
                        // `RefCell`, atomics, `Mutex` ...) is writable below a shared `&`.
                        let writable = writable || interior_mutable(tcx, ty);
                        if writable
                            && let ty::Adt(adt, _) = *ty.kind()
                            && self.sealed.contains_key(&adt.did())
                        {
                            out.push(adt.did());
                        }
                        // Trust: TINV — a component the census cannot normalize fails
                        // closed (every sealed struct).
                        if !push_storage_components(tcx, ty, |component| {
                            stack.push((component, writable))
                        }) {
                            out = self.sealed.keys().copied().collect();
                            break;
                        }
                    }
                }
            }
            out.sort_by_key(|did| (did.krate.as_u32(), did.index.as_u32()));
            out.dedup();
            let hit = Rc::new(out);
            self.owned_mut.insert(root, Rc::clone(&hit));
            hit
        }

        /// Trust: TINV step 6b (D3) — the structural walk of a local's type: its
        /// storage components (`push_storage_components`) and reference and raw
        /// pointer pointees. Records the alias types met (the caller asks each to
        /// normalize), and whether a `dyn` there names a TINV type in its arguments.
        /// Memoized per type.
        fn d3_walk(&mut self, root: Ty<'tcx>) -> Rc<D3Walk<'tcx>> {
            if let Some(walk) = self.unclassified.get(&root) {
                return Rc::clone(walk);
            }
            let tcx = self.tcx;
            let mut out = D3Walk::default();
            let mut seen: FxHashSet<Ty<'tcx>> = FxHashSet::default();
            let mut stack = vec![root];
            let mut dyn_args: Vec<Ty<'tcx>> = Vec::new();
            while let Some(ty) = stack.pop() {
                if !seen.insert(ty) {
                    continue;
                }
                if seen.len() > MAX_WALK {
                    out.overflow = true;
                    break;
                }
                match *ty.kind() {
                    ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => stack.push(inner),
                    ty::Alias(..) => out.aliases.push(ty),
                    ty::Dynamic(preds, ..) => {
                        for pred in preds.iter() {
                            match pred.skip_binder() {
                                ty::ExistentialPredicate::Trait(trait_ref) => {
                                    dyn_args.extend(trait_ref.args.types())
                                }
                                ty::ExistentialPredicate::Projection(projection) => {
                                    dyn_args.extend(projection.args.types());
                                    if let Some(term) = projection.term.as_type() {
                                        dyn_args.push(term);
                                    }
                                }
                                ty::ExistentialPredicate::AutoTrait(_) => {}
                            }
                        }
                    }
                    _ => {}
                }
                // Trust: TINV — an unnormalizable component leaves the type unclassified.
                if !push_storage_components(tcx, ty, |component| stack.push(component)) {
                    out.overflow = true;
                    break;
                }
            }
            for arg in dyn_args {
                if !self.tinv_reached(arg).is_empty() {
                    out.dyn_reaches_tinv = true;
                    break;
                }
            }
            let walk = Rc::new(out);
            self.unclassified.insert(root, Rc::clone(&walk));
            walk
        }

        /// Reconcile the whole-crate `dyn`-erasure facts, after every body and item
        /// has been scanned (so scan order cannot matter). If any body recovered raw
        /// byte access out of a `dyn` pointer, or handed a mutable `dyn` path to code
        /// that can, every sealed struct this crate erased into a `dyn` — or handed to
        /// code that can erase it into one — is denied: the thin pointer could address
        /// any of them, and nothing else ties the recovery back to a concrete struct.
        pub(in super::super) fn finish(&mut self) {
            // Trust (decision CENSUS-THIRD-PARTY-1): the coarse rule. The precise
            // third-party analysis (rule 4, TINV D1, `follow_bounds`) stays as a
            // refinement that can only add denials.
            // Trust (CENSUS-THIRD-PARTY-1, crate level): ANY linked crate outside the
            // authenticated sysroot denies every certificate, whether or not a use of it
            // was found (per-use detection missed statics, consts, extern items a
            // dependency implements, `dyn` principals and shims). The per-use note only
            // sharpens the reason.
            if let Some(krate) = third_party_crate(self.tcx) {
                let used = self.third_party_use.take();
                self.third_party_use = Some(match used {
                    Some(what) => {
                        format!("the crate graph links `{krate}`; first use found: {what}")
                    }
                    None => format!("the crate graph links `{krate}`"),
                });
            }
            if let Some(what) = self.third_party_use.take() {
                let reason = format!(
                    "the crate uses third-party code ({what}), and no certificate rests on what \
                     code outside this crate and the sysroot can forge or corrupt \
                     (CENSUS-THIRD-PARTY-1)"
                );
                // Reported FIRST and past `MAX_REASONS`: it is the reason that governs.
                let all: Vec<DefId> = self.sealed.keys().copied().collect();
                for did in all {
                    let reasons = self.denied.entry(did).or_default();
                    if !reasons.contains(&reason) {
                        reasons.insert(0, reason.clone());
                    }
                }
            }
            if let Some(reason) = self.dyn_to_thin.take() {
                let erased: Vec<DefId> = self.dyn_erased.iter().copied().collect();
                self.deny(&erased, || {
                    format!(
                        "it is erased into a `dyn Trait` and {reason}, which recovers raw byte \
                         access to it past the vtable"
                    )
                });
                let handed_out: Vec<DefId> = self.handed_out.iter().copied().collect();
                self.deny(&handed_out, || {
                    format!(
                        "it is handed to code the census does not scan, which can erase it into \
                         a `dyn Trait`, and {reason}, which recovers raw byte access to it past \
                         the vtable"
                    )
                });
            }
        }

        /// The denied sealed structs, each with the reasons found.
        pub(in super::super) fn denied(&self) -> &FxIndexMap<DefId, Vec<String>> {
            &self.denied
        }

        fn all_denied(&self) -> bool {
            self.denied.len() >= self.sealed.len()
        }

        fn deny(&mut self, structs: &[DefId], reason: impl FnOnce() -> String) {
            let open: Vec<DefId> = structs
                .iter()
                .copied()
                .filter(|did| {
                    self.sealed.contains_key(did)
                        && self.denied.get(did).is_none_or(|reasons| reasons.len() < MAX_REASONS)
                })
                .collect();
            if open.is_empty() {
                return;
            }
            let reason = reason();
            for did in open {
                let reasons = self.denied.entry(did).or_default();
                if !reasons.contains(&reason) {
                    reasons.push(reason.clone());
                }
            }
        }

        fn deny_all(&mut self, reason: &str) {
            let all: Vec<DefId> = self.sealed.keys().copied().collect();
            self.deny(&all, || reason.to_string());
        }

        /// The type walk: which sealed structs `root` reaches, and which local
        /// generic bodies and destructors it implies. Memoized per type.
        fn facts(&mut self, root: Ty<'tcx>) -> Rc<TyFacts<'tcx>> {
            if let Some(facts) = self.facts.get(&root) {
                return Rc::clone(facts);
            }
            let tcx = self.tcx;
            let mut out = TyFacts::default();
            let mut seen: FxHashSet<Ty<'tcx>> = FxHashSet::default();
            let mut stack = vec![root];
            let mut overflow = false;
            while let Some(ty) = stack.pop() {
                if !seen.insert(ty) {
                    continue;
                }
                if seen.len() > MAX_WALK {
                    overflow = true;
                    break;
                }
                // Pointers and references are followed to their pointee. Everything
                // else this walk adds to the shared storage step is a side record.
                // `dyn Trait` hides its type: the coercion that erased it is where
                // the census looks (`BodyScan::unsize`), and `holds_dyn` records that
                // one is here. Function types carry no storage. Parameters are
                // covered per instantiation.
                match *ty.kind() {
                    ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => stack.push(inner),
                    ty::Dynamic(..) => out.holds_dyn = true,
                    ty::Adt(adt, _) if !adt.is_phantom_data() => {
                        let did = adt.did();
                        if self.sealed.contains_key(&did) {
                            out.reached.push(did);
                        }
                        if did.is_local()
                            && let Some(dtor) = tcx.adt_destructor(did)
                            && dtor.did.is_local()
                            && tcx.generics_of(dtor.did).requires_monomorphization(tcx)
                        {
                            out.drops.push(ty);
                        }
                    }
                    ty::Closure(did, args) => {
                        let view = args.as_closure();
                        let parent = view.parent_args();
                        self.note_body(&mut out, did, args, parent);
                    }
                    ty::CoroutineClosure(did, args) => {
                        let view = args.as_coroutine_closure();
                        let parent = view.parent_args();
                        self.note_body(&mut out, did, args, parent);
                    }
                    ty::Coroutine(did, args) => {
                        let view = args.as_coroutine();
                        let parent = view.parent_args();
                        self.note_body(&mut out, did, args, parent);
                    }
                    _ => {}
                }
                // Trust: TINV — a component the census cannot normalize (a projection
                // that stays an alias) may be anything: fail closed like overflow.
                if !push_storage_components(tcx, ty, |component| stack.push(component)) {
                    overflow = true;
                    break;
                }
            }
            if overflow {
                out.reached = self.sealed.keys().copied().collect();
                out.holds_dyn = true;
            }
            out.reached.sort_by_key(|did| (did.krate.as_u32(), did.index.as_u32()));
            out.reached.dedup();
            let facts = Rc::new(out);
            self.facts.insert(root, Rc::clone(&facts));
            facts
        }

        /// Record the first way found to recover a `dyn`'s data pointer past its
        /// vtable (`dyn_to_thin`).
        fn note_dyn_recovery(&mut self, reason: impl FnOnce() -> String) {
            if self.dyn_to_thin.is_none() {
                self.dyn_to_thin = Some(reason());
            }
        }

        /// Whether a value of `ty` holds, or points to storage that holds, a
        /// `dyn Trait` (`TyFacts::holds_dyn`).
        fn holds_dyn(&mut self, ty: Ty<'tcx>) -> bool {
            self.facts(ty).holds_dyn
        }

        fn holds_dyn_in(&mut self, tys: impl IntoIterator<Item = Ty<'tcx>>) -> bool {
            tys.into_iter().any(|ty| self.holds_dyn(ty))
        }

        /// Whether code instantiated with `tys` must be scanned per instantiation:
        /// they reach a sealed struct, or hold a `dyn` (a generic body can recover a
        /// thin pointer out of one — `p as *mut u8` for `p: *mut T`, `T: ?Sized` —
        /// which its scan as written, over the parameter, cannot see).
        /// Trust (decision CENSUS-THIRD-PARTY-1) — record the first use of third-party code.
        fn note_third_party(&mut self, what: impl FnOnce() -> String) {
            if self.third_party_use.is_none() {
                self.third_party_use = Some(what());
            }
        }

        /// Trust: TINV — whether the body of the local generic `def` mentions a type
        /// with a projection over its parameters (`I::Item`, `T::Out`). Its scan as
        /// written treats such a projection like the parameter; but unlike a parameter,
        /// the projection can be an `S` although no type argument reaches `S`
        /// (`count::<Map<Range<u8>, fn(u8) -> S>>`), so every instantiation of such a
        /// body must be scanned ([`Self::instantiation_matters_for`]). Memoized; an
        /// unreadable body mentions nothing (it is never scanned either way).
        fn def_has_param_aliases(&mut self, def: DefId) -> bool {
            if let Some(&hit) = self.param_alias_defs.get(&def) {
                return hit;
            }
            struct Projections {
                hit: bool,
            }
            impl<'tcx> Visitor<'tcx> for Projections {
                fn visit_ty(&mut self, ty: Ty<'tcx>, _: mir::visit::TyContext) {
                    if ty.has_aliases() && ty.has_non_region_param() {
                        self.hit = true;
                    }
                }
                fn visit_args(&mut self, args: &GenericArgs<'tcx>, _: Location) {
                    if args.has_aliases() && args.has_non_region_param() {
                        self.hit = true;
                    }
                }
            }
            let tcx = self.tcx;
            let mut v = Projections { hit: false };
            let read = with_body(tcx, def, |body| {
                v.visit_body(body);
                // A projection over a parameter in the signature counts as well.
                v.visit_ty(
                    body.return_ty(),
                    mir::visit::TyContext::ReturnTy(rustc_middle::mir::SourceInfo::outermost(
                        body.span,
                    )),
                );
            });
            // Only a body that was read can have promoted MIR (asking a bodyless trait
            // item ICEs).
            if read && !v.hit && super::local_def_may_have_promoted_mir(tcx, def) {
                for promoted in tcx.promoted_mir(def).iter() {
                    v.visit_body(promoted);
                }
            }
            self.param_alias_defs.insert(def, v.hit);
            v.hit
        }

        /// Trust: TINV — [`Self::instantiation_matters`], or the local generic `def`'s
        /// body mentions a projection over its parameters ([`Self::def_has_param_aliases`]).
        fn instantiation_matters_for(
            &mut self,
            def: DefId,
            tys: impl IntoIterator<Item = Ty<'tcx>>,
        ) -> bool {
            self.instantiation_matters(tys) || (def.is_local() && self.def_has_param_aliases(def))
        }

        fn instantiation_matters(&mut self, tys: impl IntoIterator<Item = Ty<'tcx>>) -> bool {
            let tys: Vec<Ty<'tcx>> = tys.into_iter().collect();
            !self.reached_in(tys.iter().copied()).is_empty() || self.holds_dyn_in(tys)
        }

        /// Whether a value of `ty` carries an address no `dyn` type governs: an
        /// integer or float (bits an address can be stored in), a function pointer,
        /// or a reference, raw pointer or `NonNull` whose pointee holds no `dyn`,
        /// anywhere in its own storage (pointees are not followed: a pointer whose
        /// pointee holds a `dyn` keeps that `dyn` typed). Memoized per type; fails
        /// closed (`true`) past the walk bound.
        fn carries_address(&mut self, root: Ty<'tcx>) -> bool {
            if let Some(&hit) = self.addresses.get(&root) {
                return hit;
            }
            let tcx = self.tcx;
            let mut seen: FxHashSet<Ty<'tcx>> = FxHashSet::default();
            let mut stack = vec![root];
            let mut hit = false;
            while let Some(ty) = stack.pop() {
                if !seen.insert(ty) {
                    continue;
                }
                if seen.len() > MAX_WALK {
                    hit = true;
                    break;
                }
                let thin_pointee = match *ty.kind() {
                    ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::FnPtr(..) => {
                        hit = true;
                        break;
                    }
                    ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _) => Some(pointee),
                    ty::Adt(adt, args)
                        if tcx.is_lang_item(
                            adt.did(),
                            rustc_attr_ir::lang_items::LangItem::NonNull,
                        ) =>
                    {
                        Some(args.type_at(0))
                    }
                    _ => None,
                };
                match thin_pointee {
                    Some(pointee) => {
                        if !self.holds_dyn(pointee) {
                            hit = true;
                            break;
                        }
                    }
                    None => {
                        if !push_storage_components(tcx, ty, |c| stack.push(c)) {
                            hit = true;
                            break;
                        }
                    }
                }
            }
            self.addresses.insert(root, hit);
            hit
        }

        fn note_body(
            &self,
            out: &mut TyFacts<'tcx>,
            did: DefId,
            args: GenericArgs<'tcx>,
            parent: &[ty::GenericArg<'tcx>],
        ) {
            if did.is_local() && self.tcx.generics_of(did).requires_monomorphization(self.tcx) {
                out.bodies.push((
                    did,
                    args,
                    parent.iter().filter_map(|arg| arg.as_type()).collect(),
                ));
            }
        }

        fn reached(&mut self, ty: Ty<'tcx>) -> Vec<DefId> {
            self.facts(ty).reached.clone()
        }

        fn reached_in(&mut self, tys: impl IntoIterator<Item = Ty<'tcx>>) -> Vec<DefId> {
            let mut out = Vec::new();
            for ty in tys {
                out.extend(self.facts(ty).reached.iter().copied());
            }
            out.sort_by_key(|did| (did.krate.as_u32(), did.index.as_u32()));
            out.dedup();
            out
        }

        /// The sealed structs `root` holds a RAW handle to: a raw pointer or
        /// `NonNull` whose pointee reaches the struct, anywhere in `root`'s own
        /// structure (local ADT fields, generic arguments, references, upvars). A raw
        /// pointer in a foreign ADT's private fields is not a raw handle (its fields are
        /// walked with pointers read as pointees, `push_storage_components`) — `Box<S>`
        /// and `Vec<S>` hand out raw pointers only through an API whose result this
        /// census sees.
        fn raw_reached(&mut self, root: Ty<'tcx>) -> Rc<Vec<DefId>> {
            if let Some(hit) = self.raw.get(&root) {
                return Rc::clone(hit);
            }
            let tcx = self.tcx;
            let mut pointees = Vec::new();
            let mut seen: FxHashSet<Ty<'tcx>> = FxHashSet::default();
            let mut stack = vec![root];
            let mut overflow = false;
            while let Some(ty) = stack.pop() {
                if !seen.insert(ty) {
                    continue;
                }
                if seen.len() > MAX_WALK {
                    overflow = true;
                    break;
                }
                match *ty.kind() {
                    ty::RawPtr(pointee, _) => pointees.push(pointee),
                    ty::Adt(adt, args)
                        if tcx.is_lang_item(
                            adt.did(),
                            rustc_attr_ir::lang_items::LangItem::NonNull,
                        ) =>
                    {
                        pointees.push(args.type_at(0))
                    }
                    ty::Ref(_, inner, _) => stack.push(inner),
                    _ => {
                        if !push_storage_components(tcx, ty, |c| stack.push(c)) {
                            overflow = true;
                            break;
                        }
                    }
                }
            }
            let hit = if overflow {
                self.sealed.keys().copied().collect()
            } else {
                self.reached_in(pointees)
            };
            let hit = Rc::new(hit);
            self.raw.insert(root, Rc::clone(&hit));
            hit
        }

        /// The sealed structs `root` reaches through a MUTABLE reference or a raw
        /// pointer: `&mut S`, `*mut/*const S`, `NonNull<S>`, or the same wrapping a
        /// type reaching `S` — a coroutine whose saved local holds `S` included. A
        /// `&S` (shared) or an owned position does NOT count — receiving `S` by value
        /// transfers ownership away, and a shared borrow grants only reads. Used to
        /// decide whether a third-party callee could write an `S` this crate keeps
        /// (task rule 4), and whether it is handed a mutable `dyn` (`MutReach`).
        /// Memoized per type. Fails closed past the walk bound (every sealed struct,
        /// and a `dyn`).
        fn mut_reached(&mut self, root: Ty<'tcx>) -> Rc<MutReach> {
            if let Some(hit) = self.mutable.get(&root) {
                return Rc::clone(hit);
            }
            let tcx = self.tcx;
            let mut out = Vec::new();
            let mut seen: FxHashSet<(Ty<'tcx>, bool)> = FxHashSet::default();
            let mut stack = vec![(root, false)];
            let mut reaches_dyn = false;
            while let Some((ty, mut_seen)) = stack.pop() {
                if !seen.insert((ty, mut_seen)) {
                    continue;
                }
                if seen.len() > MAX_WALK {
                    out = self.sealed.keys().copied().collect();
                    reaches_dyn = true;
                    break;
                }
                match *ty.kind() {
                    ty::RawPtr(inner, _) => stack.push((inner, true)),
                    ty::Adt(adt, args)
                        if tcx.is_lang_item(
                            adt.did(),
                            rustc_attr_ir::lang_items::LangItem::NonNull,
                        ) =>
                    {
                        stack.push((args.type_at(0), true))
                    }
                    ty::Ref(_, inner, mutbl) => stack.push((inner, mut_seen || mutbl.is_mut())),
                    ty::Dynamic(preds, ..) => {
                        // A `dyn` behind a mutable or raw path: the receiver can discard
                        // the vtable and write whatever was erased into it, and no type
                        // says which struct that is (`Census::finish` reconciles it with
                        // `dyn_erased`).
                        reaches_dyn |= mut_seen;
                        // Its trait arguments are the types its methods take and return.
                        // A third-party `Box<dyn FnMut(&mut S)>` is third-party code this
                        // crate later hands `&mut S` through the vtable, and that virtual
                        // call resolves to no body the census can scan.
                        for pred in preds.iter() {
                            match pred.skip_binder() {
                                ty::ExistentialPredicate::Trait(trait_ref) => {
                                    stack.extend(trait_ref.args.types().map(|t| (t, false)))
                                }
                                ty::ExistentialPredicate::Projection(projection) => {
                                    stack.extend(projection.args.types().map(|t| (t, false)));
                                    if let Some(term) = projection.term.as_type() {
                                        stack.push((term, false));
                                    }
                                }
                                ty::ExistentialPredicate::AutoTrait(_) => {}
                            }
                        }
                    }
                    _ => {
                        // Trust (final review): interior mutability (`UnsafeCell`, `Cell`,
                        // `RefCell`, atomics, `Mutex` ...) is writable below a shared `&`.
                        let mut_seen = mut_seen || interior_mutable(tcx, ty);
                        if mut_seen
                            && let ty::Adt(adt, _) = *ty.kind()
                            && self.sealed.contains_key(&adt.did())
                        {
                            out.push(adt.did());
                        }
                        if !push_storage_components(tcx, ty, |component| {
                            stack.push((component, mut_seen))
                        }) {
                            out = self.sealed.keys().copied().collect();
                            reaches_dyn = true;
                            break;
                        }
                    }
                }
            }
            out.sort_by_key(|did| (did.krate.as_u32(), did.index.as_u32()));
            out.dedup();
            let hit = Rc::new(MutReach { sealed: out, dyn_trait: reaches_dyn });
            self.mutable.insert(root, Rc::clone(&hit));
            hit
        }

        /// Whether any of `tys` reaches a `dyn Trait` through a mutable reference or a
        /// raw pointer (`mut_reached`).
        fn mut_reaches_dyn(&mut self, tys: impl IntoIterator<Item = Ty<'tcx>>) -> bool {
            tys.into_iter().any(|ty| self.mut_reached(ty).dyn_trait)
        }

        fn enqueue(&mut self, def: DefId, args: GenericArgs<'tcx>, env_def: DefId) {
            // Trust: TINV (TINV-33) — every instantiation of a local generic item the
            // census follows passes through here; record what its arguments reach.
            let reached = self.reached_in(args.types());
            self.instantiated.extend(reached);
            if self.queued.insert((def, args)) {
                self.queue.push(Pending { def, args, env_def });
            }
        }

        /// Scan one inventoried body as written.
        pub(in super::super) fn scan_body(&mut self, body: &Body<'tcx>) {
            self.scans += 1; // Trust: TINV step 9 — inventory parity.
            let env = body.typing_env(self.tcx);
            let env_def = body.source.def_id();
            BodyScan::new(self, body, None, env, env_def).run();
        }

        /// Crate-level declarations that open a path to a sealed struct without any
        /// body doing so.
        pub(in super::super) fn scan_items(&mut self) {
            let tcx = self.tcx;
            let items = tcx.hir_crate_items(());
            for item in items.free_items() {
                let did = item.owner_id.to_def_id();
                match tcx.def_kind(did) {
                    DefKind::Struct | DefKind::Enum | DefKind::Static { .. } => {
                        // Trust (CENSUS-THIRD-PARTY-1): a value of a third-party type stored
                        // in a field or a static.
                        let ty = tcx.type_of(did).instantiate_identity().skip_normalization();
                        let fields: Vec<Ty<'tcx>> = match *ty.kind() {
                            ty::Adt(adt, args) => adt
                                .all_fields()
                                .map(|f| f.ty(tcx, args).skip_normalization())
                                .collect(),
                            _ => vec![ty],
                        };
                        let held = fields.into_iter().find(|t| mentions_third_party(tcx, *t));
                        if let Some(t) = held {
                            self.note_third_party(|| {
                                format!(
                                    "`{}` stores a value of the third-party type `{t}`",
                                    path(tcx, did)
                                )
                            });
                        }
                    }
                    DefKind::Union => {
                        let ty = tcx.type_of(did).instantiate_identity().skip_normalization();
                        if mentions_third_party(tcx, ty) {
                            self.note_third_party(|| {
                                format!("`{}` stores a value of a third-party type", path(tcx, did))
                            });
                        }
                        let hit = self.reached(ty);
                        self.deny(&hit, || {
                            format!("the union `{}` is declared over it", path(tcx, did))
                        });
                    }
                    DefKind::Impl { of_trait: true } => {
                        let header = tcx.impl_trait_header(did);
                        // Trust (CENSUS-THIRD-PARTY-1): implementing a third-party trait.
                        let trait_did = header.trait_ref.skip_binder().def_id;
                        if !trait_did.is_local() && !sysroot_def(tcx, trait_did) {
                            self.note_third_party(|| {
                                format!(
                                    "`{}` implements the third-party trait `{}`",
                                    path(tcx, did),
                                    path(tcx, trait_did)
                                )
                            });
                        }
                        if matches!(header.safety, rustc_hir::Safety::Unsafe) {
                            let trait_ref =
                                header.trait_ref.instantiate_identity().skip_normalization();
                            // The `unsafe` keyword asserts an invariant a human
                            // audited; it grants no write access on its own. The
                            // impl's own methods are local bodies the inventory scans,
                            // and a sysroot trait's provided methods are parametric.
                            // Only a THIRD-PARTY trait's provided method is
                            // un-inventoried code that could touch `S` through a
                            // `&mut self` reaching it, so only a third-party unsafe
                            // impl denies. (Auto traits — `Send`/`Sync` — never.)
                            // This keeps `unsafe impl GlobalAlloc for Arena { buf: Buf }`
                            // and a local `unsafe trait` marker certifying.
                            let owned = trait_ref.def_id.is_local()
                                || trust_mir_extract::def_is_in_real_sysroot_crate(
                                    tcx,
                                    trait_ref.def_id,
                                );
                            if !tcx.trait_is_auto(trait_ref.def_id) && !owned {
                                let hit = self.reached_in(trait_ref.args.types());
                                self.deny(&hit, || {
                                    format!(
                                        "an `unsafe impl` of the third-party trait `{}` lets its \
                                         un-inventoried code reach a type that holds it",
                                        path(tcx, trait_ref.def_id)
                                    )
                                });
                            }
                        }
                    }
                    DefKind::GlobalAsm => {
                        // A `clean { … }` island shares `DefKind::GlobalAsm` (see
                        // `def_collector.rs`) but is no assembly: the HIR item kind
                        // tells the two apart, and asking an island for its assembly
                        // was an ICE (`expect_global_asm: found Item{.. CleanIsland
                        // ..}`) in every crate that pairs an island with a sealed
                        // struct. The island names no operand; the functions it
                        // declares are Clean-origin bodies in `mir_keys`, which the
                        // inventory scans like any other body.
                        let asm = match tcx.hir_expect_item(item.owner_id.def_id).kind {
                            rustc_hir::ItemKind::GlobalAsm { asm, .. } => asm,
                            rustc_hir::ItemKind::CleanIsland { .. } => continue,
                            ref kind => rustc_span::span_bug!(
                                tcx.def_span(did),
                                "a `DefKind::GlobalAsm` item is neither assembly nor a Clean \
                                 island: {kind:?}"
                            ),
                        };
                        for (operand, _) in asm.operands {
                            match operand {
                                rustc_hir::InlineAsmOperand::SymStatic { def_id, .. } => {
                                    let ty = tcx
                                        .type_of(*def_id)
                                        .instantiate_identity()
                                        .skip_normalization();
                                    let hit = self.reached(ty);
                                    self.deny(&hit, || {
                                        "global assembly names a static that holds it".to_string()
                                    });
                                    if self.holds_dyn(ty) {
                                        self.note_dyn_recovery(|| {
                                            format!(
                                                "global assembly names the static `{}`, which \
                                                 holds a `dyn`",
                                                path(tcx, *def_id)
                                            )
                                        });
                                    }
                                }
                                rustc_hir::InlineAsmOperand::SymFn { .. } => {
                                    // The assembly can call the function with any argument;
                                    // its signature is not resolved here, so fail closed.
                                    self.deny_all(
                                        "global assembly names a function by `sym`, which it can \
                                         call with arguments the census cannot see",
                                    );
                                }
                                _ => {}
                            }
                        }
                    }
                    _ => {}
                }
            }
            for item in items.foreign_items() {
                let did = item.owner_id.to_def_id();
                match tcx.def_kind(did) {
                    DefKind::Fn => {
                        let sig = declared_sig(tcx, did);
                        let hit = self.reached_in(sig.inputs_and_output.iter());
                        self.deny(&hit, || {
                            format!("the foreign function `{}` is declared over it", path(tcx, did))
                        });
                    }
                    DefKind::Static { .. } => {
                        let ty = tcx.type_of(did).instantiate_identity().skip_normalization();
                        let hit = self.reached(ty);
                        self.deny(&hit, || {
                            format!("the foreign static `{}` holds it", path(tcx, did))
                        });
                    }
                    _ => {}
                }
            }
            // Entry points and data that code outside Rust reaches by symbol or ABI.
            for &local in tcx.mir_keys(()) {
                let did = local.to_def_id();
                match tcx.def_kind(did) {
                    DefKind::Fn | DefKind::AssocFn => {
                        let sig = declared_sig(tcx, did);
                        if tcx.codegen_fn_attrs(did).contains_extern_indicator()
                            || !sig.abi().is_rustic_abi()
                        {
                            let hit = self.reached_in(sig.inputs_and_output.iter());
                            self.deny(&hit, || {
                                format!(
                                    "`{}` is exported or has a foreign ABI, so code outside Rust \
                                     can call it with a value of it",
                                    path(tcx, did)
                                )
                            });
                            if self.holds_dyn_in(sig.inputs_and_output.iter()) {
                                self.note_dyn_recovery(|| {
                                    format!(
                                        "`{}` is exported or has a foreign ABI, so code outside \
                                         Rust exchanges a `dyn` with it",
                                        path(tcx, did)
                                    )
                                });
                            }
                        }
                    }
                    DefKind::Static { .. } => {
                        if tcx.codegen_fn_attrs(did).contains_extern_indicator() {
                            let ty = tcx.type_of(did).instantiate_identity().skip_normalization();
                            let hit = self.reached(ty);
                            self.deny(&hit, || {
                                format!("the exported static `{}` holds it", path(tcx, did))
                            });
                            if self.holds_dyn(ty) {
                                self.note_dyn_recovery(|| {
                                    format!(
                                        "the exported static `{}` holds a `dyn`",
                                        path(tcx, did)
                                    )
                                });
                            }
                        }
                    }
                    _ => {}
                }
            }
        }

        /// Scan every queued instantiation (and every one those scans queue).
        pub(in super::super) fn drain(&mut self) {
            while let Some(pending) = self.queue.pop() {
                if self.all_denied() {
                    return;
                }
                self.processed += 1;
                if self.processed > MAX_INSTANCES {
                    self.deny_all(
                        "the census exhausted its instantiation budget (fail closed): \
                         polymorphic recursion or a very large generic closure",
                    );
                    return;
                }
                let tcx = self.tcx;
                let env = if pending.args.has_non_region_param() {
                    TypingEnv::post_analysis(tcx, pending.env_def)
                } else {
                    TypingEnv::fully_monomorphized()
                };
                let read = with_body(tcx, pending.def, |body| {
                    BodyScan::new(self, body, Some(pending.args), env, pending.env_def).run();
                });
                if !read {
                    self.deny_all(&format!(
                        "the census could not read the body of `{}` (fail closed)",
                        path(tcx, pending.def)
                    ));
                    return;
                }
                if super::local_def_may_have_promoted_mir(tcx, pending.def) {
                    for promoted in tcx.promoted_mir(pending.def).iter() {
                        BodyScan::new(self, promoted, Some(pending.args), env, pending.env_def)
                            .run();
                    }
                }
            }
        }
    }

    fn path(tcx: TyCtxt<'_>, did: DefId) -> String {
        with_no_trimmed_paths!(tcx.def_path_str(did))
    }

    /// The types whose storage a value of `ty` holds BY VALUE, each handed to `push`: every
    /// ADT's fields, instantiated and normalized (a foreign ADT's raw-pointer and `NonNull`
    /// fields as their pointees) and its type arguments; an array's or slice's element and
    /// a pattern type's base; a tuple's fields; the upvars of a closure, coroutine-closure
    /// or coroutine; a coroutine's saved locals (its witness); an opaque type's hidden
    /// type; an unsafe binder's inner type.
    ///
    /// Trust: TINV (ONE normalization discipline, `storage_component`): every field and
    /// hidden type is instantiated and normalized before it is pushed. A component that
    /// is or keeps ANY projection (one that did not normalize, or one over a generic
    /// parameter), or that does not normalize at all, makes this return `false`, and
    /// every caller fails CLOSED (every sealed struct, and a `dyn`). Per-instantiation
    /// scans (`Census::def_has_param_aliases`) remain a precision refinement only.
    ///
    /// ONE definition for every type walk of the census (`facts`, `raw_reached`,
    /// `mut_reached`, the `Clone` shim's components), so a storage edge one of
    /// them follows cannot be missing from another: `mut_reached` once followed
    /// a coroutine's upvars but not its saved locals, and missed a third-party callee
    /// handed `&mut` to a future that holds `S` across an `.await`. References and raw
    /// pointers are each walk's own decision and push nothing here; neither do
    /// `PhantomData` (zero-sized: it holds no value of its argument, so a
    /// `PhantomData<*const S>` variance marker is not a pointer to `S`), `dyn Trait`,
    /// function types and parameters.
    #[must_use]
    fn push_storage_components<'tcx>(
        tcx: TyCtxt<'tcx>,
        ty: Ty<'tcx>,
        mut push: impl FnMut(Ty<'tcx>),
    ) -> bool {
        let mut complete = true;
        match *ty.kind() {
            ty::Adt(adt, _) if adt.is_phantom_data() => {}
            ty::Adt(adt, args) => {
                // Trust: TINV — EVERY field of EVERY ADT, instantiated and normalized,
                // whatever its privacy: a foreign adapter's storage need not be any of
                // its type arguments (`Peekable<I>` holds `Option<Option<I::Item>>`, a
                // third-party `Hold<I>(Inner<I>)` one more level down). A raw pointer or
                // `NonNull` inside a SYSROOT ADT's private fields is that type's own
                // (owning or borrowed) storage, handed out only through an API this
                // census sees; it is read as the pointee held by value, which is how the
                // type arguments were read before (`Vec<S>` holds `S`, it does not hand
                // out a raw pointer to it).
                // Trust: TINV (final review) — only an artifact-authenticated SYSROOT ADT
                // (`Vec`, `Box`, `Rc`, std's `hashbrown` table ...) gets the by-value
                // pointee reading; a THIRD-PARTY ADT's `*mut T` / `NonNull<T>` field keeps
                // its raw-pointer reading (a writable path in `mut_reached`, a raw handle
                // in `raw_reached`): such a type can write through it from `&self`.
                let pointer_fields_as_written =
                    adt.did().is_local() || !sysroot_def(tcx, adt.did());
                for field in adt.all_fields() {
                    match storage_component(tcx, field.ty(tcx, args).skip_normalization()) {
                        Some(field_ty) if pointer_fields_as_written => push(field_ty),
                        Some(mut field_ty) => {
                            let mut unwrapped = 0;
                            loop {
                                match *field_ty.kind() {
                                    ty::RawPtr(pointee, _) => field_ty = pointee,
                                    ty::Adt(inner, inner_args)
                                        if tcx.is_lang_item(
                                            inner.did(),
                                            rustc_attr_ir::lang_items::LangItem::NonNull,
                                        ) =>
                                    {
                                        field_ty = inner_args.type_at(0)
                                    }
                                    _ => break,
                                }
                                unwrapped += 1;
                                if unwrapped > MAX_WALK {
                                    complete = false;
                                    break;
                                }
                            }
                            push(field_ty)
                        }
                        None => complete = false,
                    }
                }
                args.types().for_each(&mut push);
            }
            ty::Array(inner, _) | ty::Slice(inner) | ty::Pat(inner, _) => push(inner),
            ty::Tuple(tys) => tys.iter().for_each(&mut push),
            ty::Closure(_, args) => push(args.as_closure().tupled_upvars_ty()),
            ty::CoroutineClosure(_, args) => push(args.as_coroutine_closure().tupled_upvars_ty()),
            ty::Coroutine(did, args) => {
                push(args.as_coroutine().tupled_upvars_ty());
                if !push_witness(tcx, did, args, &mut push) {
                    complete = false;
                }
            }
            ty::CoroutineWitness(did, args) => {
                if !push_witness(tcx, did, args, &mut push) {
                    complete = false;
                }
            }
            ty::Alias(_, alias) => {
                if let ty::AliasTyKind::Opaque { def_id } = alias.kind {
                    alias.args.types().for_each(&mut push);
                    let hidden =
                        tcx.type_of(def_id).instantiate(tcx, alias.args).skip_normalization();
                    match storage_component(tcx, hidden) {
                        Some(hidden) => push(hidden),
                        None => complete = false,
                    }
                } else {
                    // Trust: TINV (fail closed on every lane, decision TINV-33 amended): a
                    // projection that did not normalize may be anything, and one over a
                    // parameter (`I::Item`, `T::Out`) is NOT read like the parameter: it
                    // can be an `S` although no type argument of any instantiation shows
                    // one, and the census cannot rely on every concrete instantiation being
                    // scanned.
                    complete = false;
                }
            }
            ty::UnsafeBinder(inner) => push((*inner).skip_binder()),
            _ => {}
        }
        complete
    }

    /// Trust (decision CENSUS-THIRD-PARTY-1, crate level) — the first crate of the crate
    /// graph that is not the authenticated sysroot: neither core/alloc/std
    /// (`def_is_in_real_sysroot_crate`) nor std's hash table crate, nor a crate that is
    /// sysroot-resident AND reached only as a dependency of another crate (std's own
    /// dependencies: `libc`, `compiler_builtins`, `panic_unwind`, ...). A sysroot-resident
    /// crate this crate names DIRECTLY (`extern crate libc` under `rustc_private`) counts as
    /// third-party. Macros-only dependencies (proc-macro and `macro_rules!` crates) are
    /// not linked: the code they expand to is this crate's own and is scanned.
    fn third_party_crate(tcx: TyCtxt<'_>) -> Option<String> {
        tcx.crates(()).iter().copied().find_map(|cnum| {
            use rustc_crate_store::CrateDepKind;
            if matches!(tcx.crate_dep_kind(cnum), CrateDepKind::MacrosOnly) {
                return None;
            }
            let root = cnum.as_def_id();
            if sysroot_def(tcx, root) {
                return None;
            }
            let direct = tcx.extern_crate(cnum).is_some_and(|e| e.is_direct());
            if trust_mir_extract::def_is_in_sysroot_resident_crate(tcx, root) && !direct {
                return None;
            }
            Some(tcx.crate_name(cnum).to_string())
        })
    }

    /// Trust (final review) — whether `ty` is an ADT with interior mutability (not
    /// `Freeze`: it holds an `UnsafeCell`), whose contents a shared `&` can write. A type
    /// with parameters answers yes (fail closed: its `Freeze`-ness is not decided here).
    fn interior_mutable<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
        match *ty.kind() {
            ty::Adt(adt, _) if adt.is_phantom_data() => false,
            ty::Adt(..) => {
                ty.has_non_region_param()
                    || ty.has_aliases()
                    || !ty.is_freeze(tcx, TypingEnv::fully_monomorphized())
            }
            _ => false,
        }
    }

    /// Trust (decision CENSUS-THIRD-PARTY-1) — whether `did` belongs to the authenticated
    /// sysroot: core/alloc/std by name and artifact (`def_is_in_real_sysroot_crate`), or the
    /// crate implementing std's `HashMap` table (`def_is_in_std_hash_table_crate`, withdrawn
    /// when the crate names it directly). Every other non-local crate is third-party.
    fn sysroot_def(tcx: TyCtxt<'_>, did: DefId) -> bool {
        trust_mir_extract::def_is_in_real_sysroot_crate(tcx, did)
            || trust_mir_extract::def_is_in_std_hash_table_crate(tcx, did)
    }

    /// Trust: TINV — whether `ty` names, anywhere in it, an item of a crate that is neither
    /// this crate nor the authenticated sysroot (an ADT, fn item, closure, coroutine or
    /// foreign type; an alias is judged by the types it is made of): code the census does
    /// not scan may run on it.
    fn mentions_third_party<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
        let foreign = |did: DefId| !did.is_local() && !sysroot_def(tcx, did);
        ty.walk().any(|arg| {
            let Some(t) = arg.as_type() else { return false };
            match *t.kind() {
                ty::Adt(adt, _) => foreign(adt.did()),
                ty::FnDef(did, _)
                | ty::Closure(did, _)
                | ty::CoroutineClosure(did, _)
                | ty::Coroutine(did, _)
                | ty::Foreign(did) => foreign(did),
                _ => false,
            }
        })
    }

    /// Trust: TINV — a local item's declared signature, normalized in its own typing
    /// environment when it can be (else as declared: a concrete projection left in it
    /// makes the census walks fail closed).
    fn declared_sig<'tcx>(tcx: TyCtxt<'tcx>, did: DefId) -> ty::FnSig<'tcx> {
        let sig = tcx.instantiate_bound_regions_with_erased(
            tcx.fn_sig(did).instantiate_identity().skip_normalization(),
        );
        let env = TypingEnv::post_analysis(tcx, did);
        tcx.try_normalize_erasing_regions(env, ty::Unnormalized::new(sig)).unwrap_or(sig)
    }

    /// Trust: TINV — a storage component instantiated and normalized: `Some(ty)` with
    /// no concrete projection left that could be normalized, or `None` when it does not
    /// normalize (the caller fails closed). A type with parameters is left as it is
    /// (`push_storage_components` treats a parameter-dependent alias as a parameter).
    fn storage_component<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
        if !ty.has_aliases() || ty.has_non_region_param() {
            return Some(ty);
        }
        if ty.has_escaping_bound_vars() {
            return None;
        }
        let env = TypingEnv::fully_monomorphized();
        tcx.try_normalize_erasing_regions(env, ty::Unnormalized::new(ty)).ok()
    }

    /// The definition whose body runs when `instance` is called, for the instance
    /// kinds that run one user-written body: an item (directly, reified or through a
    /// vtable shim) or a closure / coroutine-closure behind its `FnOnce` shim. `None`
    /// for intrinsics, virtual calls (whose concrete impl is enumerated at the
    /// coercion that made the `dyn`), and compiler-generated glue.
    fn callee_body_def(instance: Instance<'_>) -> Option<DefId> {
        match instance.def {
            InstanceKind::Item(def)
            | InstanceKind::Shim(ShimKind::Reify(def, _) | ShimKind::VTable(def)) => Some(def),
            InstanceKind::Shim(ShimKind::ClosureOnce { closure, .. }) => Some(closure),
            InstanceKind::Shim(ShimKind::ConstructCoroutineInClosure {
                coroutine_closure_def_id,
                ..
            }) => Some(coroutine_closure_def_id),
            _ => None,
        }
    }

    fn push_witness<'tcx>(
        tcx: TyCtxt<'tcx>,
        did: DefId,
        args: GenericArgs<'tcx>,
        mut push: impl FnMut(Ty<'tcx>),
    ) -> bool {
        let mut complete = true;
        if did.is_local() {
            // A coroutine's saved locals are part of its storage: a raw pointer to the
            // coroutine reaches them. Trust: TINV — normalized like every component.
            if let Some(layout) = tcx.mir_coroutine_witnesses(did) {
                for saved in layout.field_tys.iter() {
                    let saved = ty::EarlyBinder::bind(tcx, saved.ty)
                        .instantiate(tcx, args)
                        .skip_normalization();
                    match storage_component(tcx, saved) {
                        Some(saved) => push(saved),
                        None => complete = false,
                    }
                }
            }
        } else {
            args.types().for_each(push);
        }
        complete
    }

    /// Read the body of a local `def` the way the inventory does, and run `f` on it.
    /// `false` when no view of the body is available (the caller fails closed).
    // `is_stolen` only selects between two views of the SAME body, as in the
    // inventory; it can never remove a body from the census.
    #[allow(rustc::untracked_query_information)]
    fn with_body<'tcx>(tcx: TyCtxt<'tcx>, def: DefId, f: impl FnOnce(&Body<'tcx>)) -> bool {
        let Some(local) = def.as_local() else { return false };
        // Trust: TINV — a trait item with no default has no body: reading one ICEs
        // ("can't type-check body of `K::C`"). No view of it is available.
        if tcx.trait_of_assoc(def).is_some() && !tcx.defaultness(def).has_value() {
            return false;
        }
        match tcx.def_kind(def) {
            kind @ (DefKind::Fn
            | DefKind::AssocFn
            | DefKind::Closure
            | DefKind::SyntheticCoroutineBody) => {
                if crate::clean_origin_mir::is_clean_origin(tcx, local) {
                    f(tcx.optimized_mir(local));
                    return true;
                }
                let steal = tcx.mir_drops_elaborated_and_const_checked(local);
                if !steal.is_stolen() {
                    f(&steal.borrow());
                    return true;
                }
                if !matches!(kind, DefKind::SyntheticCoroutineBody)
                    && matches!(
                        tcx.hir_body_const_context(local),
                        Some(
                            rustc_hir::ConstContext::Const { .. }
                                | rustc_hir::ConstContext::Static(_)
                        )
                    )
                {
                    f(tcx.mir_for_ctfe(local));
                    return true;
                }
                false
            }
            DefKind::Const { .. }
            | DefKind::AssocConst { .. }
            | DefKind::AnonConst
            | DefKind::Static { .. } => {
                if !tcx.is_trivial_const(local) {
                    f(tcx.mir_for_ctfe(local));
                }
                true
            }
            DefKind::Ctor(..) => {
                f(tcx.mir_for_ctfe(local));
                true
            }
            _ => false,
        }
    }

    /// `Pin`'s unchecked constructors and projections: `unsafe` for the pinning
    /// contract, and they move a POINTER, never a pointee's bytes. Every `.await`
    /// lowers to `Pin::new_unchecked(&mut future)`, so without this every coroutine
    /// that holds a sealed struct across an await would deny it.
    fn is_pin_projection(tcx: TyCtxt<'_>, def: DefId) -> bool {
        let Some(pin) = tcx.lang_items().pin_type() else { return false };
        let Some(impl_did) = tcx.impl_of_assoc(def) else { return false };
        if !matches!(tcx.def_kind(impl_did), DefKind::Impl { of_trait: false }) {
            return false;
        }
        let self_ty = tcx.type_of(impl_did).instantiate_identity().skip_normalization();
        matches!(self_ty.kind(), ty::Adt(adt, _) if adt.did() == pin)
            && matches!(
                tcx.item_name(def).as_str(),
                "new_unchecked"
                    | "get_unchecked_mut"
                    | "into_inner_unchecked"
                    | "map_unchecked"
                    | "map_unchecked_mut"
            )
    }

    /// Parametric unsafe SYSROOT accessors whose unsafety is a PRECONDITION (a bound,
    /// an initialisation or drop state), never type-punning. Under the no-undefined-
    /// behaviour assumption the whole verification already rests on, each can only
    /// move a WHOLE `S`, or hand out a reference to one — never forge one or write a
    /// field of one — exactly like the safe sysroot APIs the census already trusts as
    /// parametric. Trusting them keeps `ManuallyDrop::{drop,take}` (the idiom in a
    /// `Drop` impl over a backing struct), `<[S]>::get_unchecked(_mut)`, and
    /// `Option`/`Result::unwrap_unchecked` from denying `S`. Documented as a TCB
    /// deviation. Dangerous unsafe sysroot fns — `ptr::write`, `write_bytes`,
    /// `copy*`, `mem::{transmute,zeroed}`, `MaybeUninit::assume_init*` — are NOT here
    /// and still deny, because they can forge or byte-write `S`.
    fn is_parametric_unsafe_accessor(tcx: TyCtxt<'_>, def: DefId) -> bool {
        let Some(impl_did) = tcx.impl_of_assoc(def) else { return false };
        let self_ty = tcx.type_of(impl_did).instantiate_identity().skip_normalization();
        let name = tcx.item_name(def);
        match self_ty.kind() {
            ty::Slice(_) | ty::Array(..) => {
                matches!(name.as_str(), "get_unchecked" | "get_unchecked_mut")
            }
            ty::Adt(adt, _) => {
                let did = adt.did();
                if tcx.lang_items().manually_drop() == Some(did) {
                    matches!(name.as_str(), "drop" | "take")
                } else if tcx.is_diagnostic_item(sym::Option, did) {
                    name.as_str() == "unwrap_unchecked"
                } else if tcx.is_diagnostic_item(sym::Result, did) {
                    matches!(name.as_str(), "unwrap_unchecked" | "unwrap_err_unchecked")
                } else {
                    false
                }
            }
            _ => false,
        }
    }

    /// The pointee pair an unsizing coercion from `src` to `dst` erases:
    /// `(&S, &dyn T)`, `(Box<S>, Box<dyn T>)`, or any `CoerceUnsized` struct whose one
    /// changing field is such a pointer.
    fn unsize_pointees<'tcx>(
        tcx: TyCtxt<'tcx>,
        src: Ty<'tcx>,
        dst: Ty<'tcx>,
    ) -> Option<(Ty<'tcx>, Ty<'tcx>)> {
        match (src.kind(), dst.kind()) {
            (ty::Ref(_, a, _) | ty::RawPtr(a, _), ty::Ref(_, b, _) | ty::RawPtr(b, _)) => {
                Some((*a, *b))
            }
            (ty::Adt(da, aa), ty::Adt(db, ab)) if da == db => {
                if da.is_box() {
                    return Some((aa.type_at(0), ab.type_at(0)));
                }
                da.all_fields().find_map(|field| {
                    let fa = field.ty(tcx, *aa).skip_normalization();
                    let fb = field.ty(tcx, *ab).skip_normalization();
                    if fa == fb { None } else { unsize_pointees(tcx, fa, fb) }
                })
            }
            _ => None,
        }
    }

    /// Whether a use in `context` can change the value stored at the place.
    fn can_write(context: PlaceContext) -> bool {
        match context {
            PlaceContext::MutatingUse(_) => true,
            // `&raw const s.len` can be cast to `*mut usize` and written through.
            PlaceContext::NonMutatingUse(NonMutatingUseContext::RawBorrow) => true,
            _ => false,
        }
    }

    /// One body, as written (`args: None`) or instantiated.
    struct BodyScan<'c, 'a, 'b, 'tcx> {
        census: &'c mut Census<'a, 'tcx>,
        body: &'b Body<'tcx>,
        args: Option<GenericArgs<'tcx>>,
        typing_env: TypingEnv<'tcx>,
        env_def: DefId,
        /// `ElaborateBoxDerefs` temporaries: `_t = transmute(box.0.0) as *const T`,
        /// each only ever dereferenced. They are how every `*b` of a `Box` reads in
        /// runtime MIR, not a raw pointer the program holds.
        box_temps: DenseBitSet<Local>,
        box_defs: FxHashSet<Location>,
        /// `RawPtrKind::FakeForPtrMetadata` temporaries: `_t = &raw const (fake) (*s)`
        /// on a non-`Copy` slice place, consumed only by `PtrMetadata` to read a
        /// length. Not a raw pointer the program holds.
        metadata_temps: DenseBitSet<Local>,
        /// Trust: TINV step 6b — the TINV types this body's locals reach (filled by
        /// `run` when the census has any); D3 and D5 deny over it.
        tinv_mentioned: Vec<DefId>,
        /// Trust: TINV step 6b (D4) — a coroutine body (analysis-phase MIR: the
        /// coroutine is not yet state-transformed) or a synthetic coroutine body.
        coroutine: bool,
    }

    impl<'c, 'a, 'b, 'tcx> BodyScan<'c, 'a, 'b, 'tcx> {
        fn new(
            census: &'c mut Census<'a, 'tcx>,
            body: &'b Body<'tcx>,
            args: Option<GenericArgs<'tcx>>,
            typing_env: TypingEnv<'tcx>,
            env_def: DefId,
        ) -> Self {
            let (box_temps, box_defs) = box_deref_temps(body);
            let metadata_temps = metadata_temps(body);
            // Trust: TINV step 6b (D4).
            let coroutine = body.coroutine.is_some()
                || matches!(
                    census.tcx.def_kind(body.source.def_id()),
                    DefKind::SyntheticCoroutineBody
                );
            BodyScan {
                census,
                body,
                args,
                typing_env,
                env_def,
                box_temps,
                box_defs,
                metadata_temps,
                tinv_mentioned: Vec::new(),
                coroutine,
            }
        }

        fn run(mut self) {
            let body = self.body;
            // Trust: TINV step 6b — the TINV-only passes run first, and only when a
            // TINV type is sealed: D2's alias pass over the whole body, then the
            // ordinary visit, whose hooks add D1 and D3-D5.
            if self.census.has_tinv {
                let mut mentioned = Vec::new();
                for decl in body.local_decls.iter() {
                    let ty = self.ty(decl.ty);
                    mentioned.extend(self.census.tinv_reached(ty));
                }
                mentioned.sort_by_key(|did| (did.krate.as_u32(), did.index.as_u32()));
                mentioned.dedup();
                self.tinv_mentioned = mentioned;
                self.tinv_field_aliases();
            }
            self.visit_body(body);
        }

        fn tcx(&self) -> TyCtxt<'tcx> {
            self.census.tcx
        }

        /// `ty` as this scan sees it: instantiated with the scan's arguments.
        fn ty(&self, ty: Ty<'tcx>) -> Ty<'tcx> {
            let Some(args) = self.args else { return ty };
            let tcx = self.tcx();
            tcx.try_instantiate_and_normalize_erasing_regions(
                args,
                self.typing_env,
                ty::EarlyBinder::bind(tcx, ty),
            )
            .unwrap_or_else(|_| {
                ty::EarlyBinder::bind(tcx, ty).instantiate(tcx, args).skip_normalization()
            })
        }

        fn generic_args(&self, value: GenericArgs<'tcx>) -> GenericArgs<'tcx> {
            let Some(args) = self.args else { return value };
            let tcx = self.tcx();
            tcx.try_instantiate_and_normalize_erasing_regions(
                args,
                self.typing_env,
                ty::EarlyBinder::bind(tcx, value),
            )
            .unwrap_or_else(|_| {
                ty::EarlyBinder::bind(tcx, value).instantiate(tcx, args).skip_normalization()
            })
        }

        fn place_ty(&self, place: mir::PlaceRef<'tcx>) -> Ty<'tcx> {
            self.ty(place.ty(self.body, self.tcx()).ty)
        }

        fn owner(&self) -> String {
            let tcx = self.tcx();
            let source = self.body.source;
            let mut owner = path(tcx, source.def_id());
            if let Some(promoted) = source.promoted {
                owner.push_str(&format!(" (promoted {})", promoted.as_usize()));
            }
            if let Some(args) = self.args {
                owner.push_str(&format!(" instantiated with {args:?}"));
            }
            owner
        }

        fn deny(&mut self, structs: &[DefId], what: impl FnOnce() -> String) {
            if structs.is_empty() {
                return;
            }
            let owner = self.owner();
            self.census.deny(structs, || format!("{} in `{owner}`", what()));
        }

        /// Local generic bodies and destructors a type implies, instantiated.
        fn note_instances(&mut self, ty: Ty<'tcx>) {
            let facts = self.census.facts(ty);
            let tcx = self.tcx();
            for (def, args, parent) in &facts.bodies {
                if self.census.instantiation_matters_for(*def, parent.iter().copied()) {
                    self.census.enqueue(*def, *args, self.env_def);
                }
            }
            for &adt_ty in &facts.drops {
                let ty::Adt(adt, adt_args) = *adt_ty.kind() else { continue };
                // Trust: TINV — or the local `Drop` impl mentions a projection over its
                // parameters, which may be an `S` that no argument shows.
                let projected = tcx
                    .adt_destructor(adt.did())
                    .is_some_and(|dtor| self.census.def_has_param_aliases(dtor.did));
                if !projected && !self.census.instantiation_matters(adt_args.types()) {
                    continue;
                }
                let Some(drop_trait) = tcx.lang_items().drop_trait() else { continue };
                let Some(&drop_fn) = tcx.associated_item_def_ids(drop_trait).first() else {
                    continue;
                };
                match Instance::try_resolve(
                    tcx,
                    self.typing_env,
                    drop_fn,
                    tcx.mk_args(&[adt_ty.into()]),
                ) {
                    Ok(Some(instance)) if instance.def_id().is_local() => {
                        self.census.enqueue(instance.def_id(), instance.args, self.env_def)
                    }
                    Ok(Some(_)) => {}
                    _ => {
                        let hit = self.census.reached(adt_ty);
                        self.deny(&hit, || {
                            format!("the generic destructor of `{adt_ty}` could not be resolved")
                        });
                        if self.census.holds_dyn(adt_ty) {
                            self.note_dyn_recovery(|| {
                                format!(
                                    "the generic destructor of `{adt_ty}`, which holds a `dyn`, \
                                     could not be resolved"
                                )
                            });
                        }
                    }
                }
            }
        }

        /// A function named as a callee or a value.
        /// Trust: TINV — a callee's signature instantiated with `args` and NORMALIZED in
        /// this scan's typing environment (`<Map<.., fn(u8) -> S> as Iterator>::Item` is
        /// `S` here). `None` when it does not normalize, or keeps a projection with no
        /// parameter in it: the caller fails closed. A projection over a parameter of a
        /// polymorphic scan stays (covered per instantiation, like the parameter).
        fn callee_sig(&self, did: DefId, args: GenericArgs<'tcx>) -> Option<ty::FnSig<'tcx>> {
            let tcx = self.tcx();
            let sig = tcx.instantiate_bound_regions_with_erased(
                tcx.fn_sig(did).instantiate(tcx, args).skip_normalization(),
            );
            let env = self.typing_env;
            let sig = tcx.try_normalize_erasing_regions(env, ty::Unnormalized::new(sig)).ok()?;
            sig.inputs_and_output
                .iter()
                .all(|t| !t.has_aliases() || t.has_non_region_param())
                .then_some(sig)
        }

        /// Trust: TINV (final review) — every type in the where-clauses of `def`
        /// instantiated with `args` (trait and projection clauses: their arguments and
        /// projected term), normalized in this scan's typing environment where it
        /// normalizes (else as written, which the census walks fail closed on).
        fn callee_predicate_types(&self, def: DefId, args: GenericArgs<'tcx>) -> Vec<Ty<'tcx>> {
            let tcx = self.tcx();
            let env = self.typing_env;
            let mut out = Vec::new();
            for clause in tcx.clauses_of(def).instantiate(tcx, args).clauses {
                let kind =
                    tcx.instantiate_bound_regions_with_erased(clause.skip_normalization().kind());
                match kind {
                    ty::ClauseKind::Trait(pred) => out.extend(pred.trait_ref.args.types()),
                    ty::ClauseKind::Projection(pred) => {
                        out.extend(pred.projection_term.args.types());
                        out.extend(pred.term.as_type());
                    }
                    _ => {}
                }
            }
            out.into_iter()
                .map(|ty| {
                    tcx.try_normalize_erasing_regions(env, ty::Unnormalized::new(ty)).unwrap_or(ty)
                })
                .collect()
        }

        /// Trust: TINV — a callee whose signature does not normalize: it may pass or
        /// return anything, so every sealed struct is denied and counted handed out.
        fn unnormalized_callee(&mut self, did: DefId) {
            let tcx = self.tcx();
            let all: Vec<DefId> = self.census.sealed.keys().copied().collect();
            self.census.handed_out.extend(all.iter().copied());
            self.deny(&all, || {
                format!(
                    "the signature of `{}` does not normalize, so the census cannot see what it \
                     is handed or returns (fail closed)",
                    path(tcx, did)
                )
            });
        }

        /// Trust: TINV — whether `did` with the CONCRETE `args` resolves to a local generic
        /// body that mentions a projection over its parameters
        /// (`Census::def_has_param_aliases`): it must be scanned per instantiation.
        fn projection_instance(&mut self, did: DefId, args: GenericArgs<'tcx>) -> bool {
            let tcx = self.tcx();
            if args.has_non_region_param() {
                return false;
            }
            let Ok(Some(instance)) = Instance::try_resolve(tcx, self.typing_env, did, args) else {
                return false;
            };
            callee_body_def(instance).is_some_and(|body| {
                body.is_local()
                    && tcx.generics_of(body).requires_monomorphization(tcx)
                    && self.census.def_has_param_aliases(body)
            })
        }

        fn mention_fn(&mut self, did: DefId, args: GenericArgs<'tcx>) {
            let tcx = self.tcx();
            // Trust (CENSUS-THIRD-PARTY-1): a call of (or a fn item value naming) a
            // third-party function, directly or as the body a trait method resolves to.
            let resolved_body = match Instance::try_resolve(tcx, self.typing_env, did, args) {
                Ok(Some(instance)) => callee_body_def(instance),
                _ => None,
            };
            for def in [Some(did), resolved_body].into_iter().flatten() {
                if !def.is_local() && !sysroot_def(tcx, def) {
                    let owner = self.owner();
                    self.census.note_third_party(|| {
                        format!("`{owner}` calls the third-party `{}`", path(tcx, def))
                    });
                }
            }
            let Some(sig) = self.callee_sig(did, args) else {
                self.unnormalized_callee(did);
                return;
            };
            let touched = self.census.reached_in(args.types().chain(sig.inputs_and_output.iter()));
            // A mutable or raw path to a `dyn` reaches no sealed struct by type — the
            // erasure hid it — so it is checked even when `touched` is empty.
            let dyn_handoff = self.census.mut_reaches_dyn(sig.inputs_and_output.iter());
            // Likewise any `dyn` the call is instantiated with or handed: the callee
            // may recover a thin pointer out of it (`dyn_call`), and a local generic
            // callee is scanned per instantiation (`mention_instance`).
            let dyn_source =
                self.census.holds_dyn_in(args.types().chain(sig.inputs().iter().copied()));
            // Trust: TINV — a concrete instantiation of a local generic body whose
            // projections over its parameters may be an `S` no argument shows.
            let projected = self.projection_instance(did, args);
            // Trust: TINV — a sysroot callee instantiated with a third-party type may call
            // that type's third-party impls (`follow_bounds`) although nothing visibly
            // reaches a sealed struct (`Take<Conjure<I>>` reaches none; its
            // `Conjure::next` returns `I::Item`).
            // Trust: TINV (final review) — and a THIRD-PARTY callee itself is always judged
            // (TINV D1 reads its type arguments and where-clauses, which can name an `S`
            // its signature does not: `each<I, F: FnMut(I::Item)>`).
            let third_party = args.types().any(|t| mentions_third_party(tcx, t))
                || (!did.is_local() && !sysroot_def(tcx, did));
            if touched.is_empty() && !dyn_handoff && !dyn_source && !projected && !third_party {
                return;
            }
            let unsafe_fn = matches!(sig.safety(), rustc_hir::Safety::Unsafe);
            if let Some(intrinsic) = tcx.intrinsic(did) {
                if dyn_source {
                    self.dyn_intrinsic(did, args, sig);
                }
                self.census.handed_out.extend(touched.iter().copied());
                if unsafe_fn && intrinsic.name != sym::write_box_via_move {
                    self.deny(&touched, || {
                        format!("the intrinsic `{}` is applied to it", intrinsic.name)
                    });
                }
                return;
            }
            if tcx.is_foreign_item(did) {
                if dyn_handoff {
                    self.note_dyn_handoff(did);
                }
                if dyn_source {
                    self.note_dyn_recovery(|| {
                        format!("the foreign function `{}` is handed a `dyn`", path(tcx, did))
                    });
                }
                self.deny(&touched, || {
                    format!("the foreign function `{}` receives or returns it", path(tcx, did))
                });
                return;
            }
            match Instance::try_resolve(tcx, self.typing_env, did, args) {
                Ok(Some(instance)) => {
                    let body = callee_body_def(instance);
                    if dyn_handoff
                        && let Some(body) = body
                        && !body.is_local()
                        && !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, body)
                    {
                        self.note_dyn_handoff(body);
                    }
                    if dyn_source {
                        self.dyn_call(instance, sig);
                    }
                    if !body.is_some_and(|body| body.is_local()) {
                        self.census.handed_out.extend(touched.iter().copied());
                    }
                    if !touched.is_empty() || dyn_source || projected || third_party {
                        self.mention_instance(instance, &touched);
                    }
                }
                _ => {
                    // Unresolvable here: a trait method over a type parameter. Each
                    // concrete instantiation this crate makes is scanned on its own;
                    // what stays open is an impl of a trait neither this crate nor
                    // the sysroot owns, or an `unsafe` trait method.
                    let owned = tcx.trait_of_assoc(did).is_some_and(|t| {
                        t.is_local() || trust_mir_extract::def_is_in_real_sysroot_crate(tcx, t)
                    });
                    if dyn_handoff && !owned {
                        self.note_dyn_handoff(did);
                    }
                    if dyn_source && !owned && unsafe_fn {
                        self.note_dyn_recovery(|| {
                            format!(
                                "the unsafe call `{}`, which resolves to no body the census can \
                                 scan, is handed a `dyn`",
                                path(tcx, did)
                            )
                        });
                    }
                    if !owned {
                        self.census.handed_out.extend(touched.iter().copied());
                    }
                    if !owned || unsafe_fn {
                        self.deny(&touched, || {
                            format!(
                                "the call `{}` over it resolves to no body the census can scan",
                                path(tcx, did)
                            )
                        });
                    }
                }
            }
        }

        fn mention_instance(&mut self, instance: Instance<'tcx>, touched: &[DefId]) {
            let tcx = self.tcx();
            match instance.def {
                InstanceKind::Item(def)
                | InstanceKind::Shim(ShimKind::Reify(def, _) | ShimKind::VTable(def)) => {
                    if def.is_local() {
                        if tcx.generics_of(def).requires_monomorphization(tcx)
                            && self.census.instantiation_matters_for(def, instance.args.types())
                        {
                            self.census.enqueue(def, instance.args, self.env_def);
                        }
                        return;
                    }
                    self.external_fn(def, instance.args, touched);
                }
                InstanceKind::Intrinsic(def) | InstanceKind::LlvmIntrinsic(def) => {
                    let unsafe_fn = matches!(
                        tcx.fn_sig(def).skip_binder().skip_binder().safety(),
                        rustc_hir::Safety::Unsafe
                    );
                    if unsafe_fn && tcx.item_name(def) != sym::write_box_via_move {
                        self.deny(touched, || {
                            format!("the intrinsic `{}` is applied to it", tcx.item_name(def))
                        });
                    }
                }
                // The concrete impl was enumerated at the coercion that made the `dyn`.
                InstanceKind::Virtual(..) => {}
                InstanceKind::Shim(
                    ShimKind::FnPtr(..)
                    | ShimKind::FnPtrAsPtr(..)
                    | ShimKind::FnPtrFromPtr(..)
                    | ShimKind::ThreadLocal(..),
                ) => {}
                InstanceKind::Shim(
                    ShimKind::ClosureOnce { .. } | ShimKind::ConstructCoroutineInClosure { .. },
                ) => {
                    for ty in instance.args.types() {
                        self.note_instances(ty);
                    }
                }
                InstanceKind::Shim(ShimKind::DropGlue(_, ty)) => {
                    if let Some(ty) = ty {
                        self.note_instances(ty);
                    }
                }
                InstanceKind::Shim(ShimKind::Clone(clone_fn, ty)) => {
                    self.note_instances(ty);
                    // The builtin `Clone` of a tuple, array, closure or coroutine clones
                    // each component it holds by value: for a coroutine
                    // (`coroutine_clone`), its saved locals as well as its upvars.
                    let mut components: Vec<Ty<'tcx>> = Vec::new();
                    if !push_storage_components(tcx, ty, |component| components.push(component)) {
                        self.deny(touched, || {
                            format!("the components of `{ty}` do not normalize (fail closed)")
                        });
                    }
                    for component in components {
                        if self.census.reached(component).is_empty() {
                            continue;
                        }
                        match Instance::try_resolve(
                            tcx,
                            self.typing_env,
                            clone_fn,
                            tcx.mk_args(&[component.into()]),
                        ) {
                            Ok(Some(inner)) => self.mention_instance(inner, touched),
                            _ => self.deny(touched, || {
                                format!("the `Clone` of `{component}` could not be resolved")
                            }),
                        }
                    }
                }
                InstanceKind::Shim(ShimKind::FutureDropPoll(_, proxy, inner)) => {
                    self.note_instances(proxy);
                    self.note_instances(inner);
                }
                InstanceKind::Shim(
                    ShimKind::AsyncDropGlueCtor(_, ty) | ShimKind::AsyncDropGlue(_, ty),
                ) => self.note_instances(ty),
            }
        }

        /// A callee whose body this crate does not contain.
        fn external_fn(&mut self, def: DefId, args: GenericArgs<'tcx>, touched: &[DefId]) {
            let tcx = self.tcx();
            let sysroot = trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def);
            let fn_like =
                matches!(tcx.def_kind(def), DefKind::Fn | DefKind::AssocFn | DefKind::Ctor(..));
            if !fn_like {
                // A foreign closure or coroutine body instantiated with the struct.
                if !sysroot {
                    self.deny(touched, || {
                        format!("the non-sysroot body `{}` is instantiated with it", path(tcx, def))
                    });
                }
                return;
            }
            let unsafe_fn = matches!(
                tcx.fn_sig(def).skip_binder().skip_binder().safety(),
                rustc_hir::Safety::Unsafe
            );
            if unsafe_fn {
                if sysroot
                    && (is_pin_projection(tcx, def) || is_parametric_unsafe_accessor(tcx, def))
                {
                    return;
                }
                self.deny(touched, || {
                    format!(
                        "the unsafe function `{}`, whose body is not in this crate, is applied \
                         to it",
                        path(tcx, def)
                    )
                });
                return;
            }
            if sysroot {
                self.follow_bounds(def, args);
                return;
            }
            // A SAFE function of a third-party crate. It cannot forge `S` (no
            // `unsafe`) and cannot name `S`'s private fields. It matters only when it
            // can WRITE an `S` this crate keeps and later reads — i.e. when it is
            // handed a `&mut S` (or a raw pointer, though holding one is denied at its
            // source). Receiving `S` by value transfers ownership away (this crate no
            // longer reads that `S`), and a shared `&S` grants only reads; both are
            // sound to allow under the verify-off-dependency trust, and denying them
            // would block ordinary use of `serde`, `tracing`, `parking_lot` and the
            // like. This is exactly task rule 4's boundary (`*mut S`/`&mut S`), not
            // any touch.
            let Some(sig) = self.callee_sig(def, args) else {
                self.unnormalized_callee(def);
                return;
            };
            let mut mut_hit = Vec::new();
            for input in sig.inputs_and_output.iter() {
                mut_hit.extend(self.census.mut_reached(input).sealed.iter().copied());
            }
            mut_hit.sort_by_key(|did| (did.krate.as_u32(), did.index.as_u32()));
            mut_hit.dedup();
            self.deny(&mut_hit, || {
                format!(
                    "`{}`, from a crate that is neither this crate nor the sysroot, is handed a \
                     mutable reference or raw pointer that reaches it",
                    path(tcx, def)
                )
            });
            // Trust: TINV step 6b — D1 FOREIGN FORGE. A type invariant is a claim about
            // EVERY value of `S`, so a third-party function that RETURNS a value
            // reaching `S` (`conjure::<S>()`, which may `mem::zeroed` it) or takes one
            // by value or through `&mut` (`fix::<S>(s) -> S`) can hand this crate an
            // `S` no construction it checked made. Its body is not inventoried, so the
            // TINV role denies on the signature alone. A shared `&S` grants only reads.
            if self.census.has_tinv {
                let mut forged = self.census.reached(sig.output());
                for input in sig.inputs() {
                    forged.extend(self.census.owned_or_mut_reached(*input).iter().copied());
                }
                // Trust: TINV (final review) — a third-party function can also hand this
                // crate an `S` through a CALLBACK: its type arguments (`each::<S, _>`) and
                // its where-clauses (`F: FnOnce(T)`, `F: FnMut(I::Item)`) name what it
                // may construct and pass to local code. Each type there that reaches a
                // TINV type (a parameter projection fails closed) is a forge too.
                for ty in args.types().chain(self.callee_predicate_types(def, args)) {
                    forged.extend(self.census.reached(ty));
                }
                forged.sort_by_key(|did| (did.krate.as_u32(), did.index.as_u32()));
                forged.dedup();
                let forged = self.census.tinv_only(&forged);
                self.deny(&forged, || {
                    format!(
                        "`{}`, from a crate that is neither this crate nor the sysroot, returns or \
                         takes ownership of or `&mut` to it (TINV D1 foreign forge)",
                        path(tcx, def)
                    )
                });
            }
        }

        /// A safe sysroot function instantiated with a type reaching a sealed struct
        /// runs no code of this crate EXCEPT the impls its trait bounds select (and
        /// drop glue, which `note_instances` covers through the argument types). A
        /// local GENERIC impl among them runs with the struct as an argument.
        fn follow_bounds(&mut self, def: DefId, args: GenericArgs<'tcx>) {
            let tcx = self.tcx();
            for ty in args.types() {
                self.note_instances(ty);
            }
            if args.has_non_region_param() || !self.census.followed.insert((def, args)) {
                return;
            }
            let clauses: Vec<ty::Clause<'tcx>> = tcx
                .clauses_of(def)
                .instantiate(tcx, args)
                .clauses
                .into_iter()
                .map(|clause| clause.skip_normalization())
                .collect();
            let env = TypingEnv::fully_monomorphized();
            for clause in rustc_infer::traits::util::elaborate(tcx, clauses) {
                let Some(trait_pred) = clause.as_trait_clause() else { continue };
                let trait_pred = tcx.instantiate_bound_regions_with_erased(trait_pred);
                if trait_pred.polarity != ty::ClausePolarity::Positive {
                    continue;
                }
                let Ok(trait_ref) = tcx.try_normalize_erasing_regions(
                    env,
                    ty::Unnormalized::new(trait_pred.trait_ref),
                ) else {
                    continue;
                };
                if trait_ref.has_non_region_param() || tcx.trait_is_auto(trait_ref.def_id) {
                    continue;
                }
                let args_matter = self.census.instantiation_matters(trait_ref.args.types());
                let Ok(source) = tcx.codegen_select_candidate(env.as_query_input(trait_ref)) else {
                    continue;
                };
                let rustc_middle::traits::ImplSource::UserDefined(data) = source else { continue };
                if !data.impl_def_id.is_local() {
                    if sysroot_def(tcx, data.impl_def_id) {
                        // Trust: TINV — an AUTHENTICATED sysroot impl is sysroot code under
                        // the same trust; its own where-clauses are followed in turn (a
                        // `Take<I>` impl bounds `I: Iterator`, which may select a
                        // third-party impl).
                        self.follow_bounds(data.impl_def_id, data.args);
                    } else {
                        // Trust: TINV — a THIRD-PARTY impl is external code the sysroot
                        // calls on this crate's behalf: its methods face TINV D1 and rule
                        // 4 on their normalized signatures exactly as a direct call does
                        // (`impl<I: Iterator> Iterator for Conjure<I> { type Item = I::Item;
                        // .. }` forges an `S` that comes back through `collect`).
                        self.third_party_impl(data.impl_def_id, data.args);
                    }
                    continue;
                }
                if !tcx.generics_of(data.impl_def_id).requires_monomorphization(tcx) {
                    // A local non-generic impl is scanned as written.
                    continue;
                }
                // Trust: TINV — or an impl item mentions a projection over the impl's
                // parameters, which may be an `S` that no trait argument shows.
                if !args_matter
                    && !tcx
                        .associated_item_def_ids(data.impl_def_id)
                        .iter()
                        .any(|&item| self.census.def_has_param_aliases(item))
                {
                    continue;
                }
                for &item in tcx.associated_item_def_ids(data.impl_def_id) {
                    if !matches!(tcx.def_kind(item), DefKind::AssocFn | DefKind::AssocConst { .. })
                    {
                        continue;
                    }
                    // Fix the IMPL's arguments (which reach the struct — e.g. `T = S`
                    // in `impl<T> Hash for Key<T>`) and leave the METHOD's own
                    // parameters (`H` in `fn hash<H: Hasher>`) abstract. Scanning the
                    // body this way catches every escape through the fixed arguments
                    // (a `&raw mut self.0` now names `S`) while the method's own
                    // parameters, whose concrete values the sysroot supplies from
                    // types that do not hold `S`, stay parametric. Denying instead
                    // would reject `HashMap<Key<S>, _>` and `collect::<Bag<S>>()`,
                    // which are not escapes. (TCB: the method's own parameters are
                    // trusted parametric, the same trust as an unresolved sysroot-owned
                    // trait method.)
                    let own_generic = tcx.generics_of(item).own_requires_monomorphization();
                    let item_args = ty::GenericArgs::for_item(tcx, item, |param, _| {
                        match data.args.get(param.index as usize) {
                            Some(arg) => arg,
                            None => match param.kind {
                                ty::GenericParamDefKind::Lifetime => tcx.lifetimes.re_erased.into(),
                                _ => tcx.mk_param_from_def(param),
                            },
                        }
                    });
                    let env_def = if own_generic { item } else { self.env_def };
                    self.census.enqueue(item, item_args, env_def);
                }
            }
        }

        /// Trust: TINV — a third-party impl selected through a sysroot bound: every
        /// method is judged as a direct call of it would be (`external_fn`: TINV D1 and
        /// rule 4 on the signature instantiated with the impl's arguments, normalized; the
        /// method's own parameters stay parameters, so a projection over one fails
        /// closed), and an associated constant whose type reaches a TINV type is a forge.
        fn third_party_impl(&mut self, impl_def: DefId, impl_args: GenericArgs<'tcx>) {
            let tcx = self.tcx();
            self.census.note_third_party(|| {
                format!("the sysroot is bound to the third-party impl `{}`", path(tcx, impl_def))
            });
            let touched = self.census.reached_in(impl_args.types());
            for &item in tcx.associated_item_def_ids(impl_def) {
                let item_args = ty::GenericArgs::for_item(tcx, item, |param, _| {
                    match impl_args.get(param.index as usize) {
                        Some(arg) => arg,
                        None => match param.kind {
                            ty::GenericParamDefKind::Lifetime => tcx.lifetimes.re_erased.into(),
                            _ => tcx.mk_param_from_def(param),
                        },
                    }
                });
                match tcx.def_kind(item) {
                    DefKind::AssocFn => self.external_fn(item, item_args, &touched),
                    DefKind::AssocConst { .. } if self.census.has_tinv => {
                        let ty = tcx.type_of(item).instantiate(tcx, item_args).skip_normalization();
                        let env = self.typing_env;
                        let ty = tcx
                            .try_normalize_erasing_regions(env, ty::Unnormalized::new(ty))
                            .unwrap_or(ty);
                        let hit = self.census.reached(ty);
                        let hit = self.census.tinv_only(&hit);
                        self.deny(&hit, || {
                            format!(
                                "the third-party constant `{}` has a type reaching it (TINV D1 \
                                 foreign forge)",
                                path(tcx, item)
                            )
                        });
                    }
                    _ => {}
                }
            }
        }

        /// An unsizing coercion that erases a type reaching a sealed struct into a
        /// `dyn Trait`: the vtable's methods run on that struct's storage.
        fn unsize(&mut self, src: Ty<'tcx>, dst: Ty<'tcx>) {
            let tcx = self.tcx();
            let touched = self.census.reached(src);
            if touched.is_empty() {
                return;
            }
            let Some((a, b)) = unsize_pointees(tcx, src, dst) else {
                self.deny(&touched, || {
                    format!("an unsizing coercion from `{src}` to `{dst}` the census cannot follow")
                });
                return;
            };
            let (src_tail, dst_tail) =
                tcx.struct_lockstep_tails_raw(a, b, |ty| ty.skip_normalization());
            let ty::Dynamic(preds, _) = *dst_tail.kind() else { return };
            // The concrete `src_tail` is now hidden behind a `dyn` pointer: record
            // that these structs are behind a `dyn`, so a later thin-cast out of one
            // (`finish`) denies them. The vtable below still covers ordinary trait
            // calls; this covers only the escape that discards the vtable.
            self.census.dyn_erased.extend(touched.iter().copied());
            self.note_instances(src_tail);
            let Some(principal) = preds.principal() else { return };
            let trait_ref =
                tcx.instantiate_bound_regions_with_erased(principal.with_self_ty(tcx, src_tail));
            if trait_ref.has_non_region_param() || trait_ref.has_infer() {
                // A generic-context coercion: the concrete vtable cannot be resolved
                // here. It need not be. The erased type's trait methods are either
                // local bodies — the closure body, or the impl method — which the
                // inventory ALREADY scans as written (a fixed field reaching a sealed
                // struct is caught there) and re-scans per concrete instantiation at
                // every call site that supplies a struct-reaching argument, or they
                // are sysroot/foreign parametric methods. `note_instances` above
                // enqueues the local generic bodies `src_tail` contains. Denying here
                // would reject every generic type that merely holds a sealed struct
                // and is ever shown through `dyn` (a `Debug`, an `Fn`), which is not
                // an escape.
                return;
            }
            for entry in tcx.vtable_entries(trait_ref) {
                if let ty::VtblEntry::Method(instance) = entry {
                    self.mention_instance(*instance, &touched);
                }
            }
        }

        /// A function whose body is in neither this crate nor the sysroot is handed a
        /// mutable reference or raw pointer that reaches a `dyn Trait`. Its body is not
        /// inventoried, so it may make the `dyn`-to-thin cast `note_dyn_to_thin` looks
        /// for itself (a safe function can hold an `unsafe` block); `finish` denies
        /// the erased structs. A shared `&dyn` or an owned `Box<dyn>` grants no write
        /// to bytes this crate keeps, as for `S` itself (`external_fn`).
        fn note_dyn_handoff(&mut self, callee: DefId) {
            if self.census.dyn_to_thin.is_none() {
                let tcx = self.tcx();
                let owner = self.owner();
                self.census.dyn_to_thin = Some(format!(
                    "`{}`, from a crate that is neither this crate nor the sysroot, is handed a \
                     mutable reference or raw pointer to a `dyn` in `{owner}`",
                    path(tcx, callee)
                ));
            }
        }

        /// Record that a `dyn`'s data pointer can be recovered past its vtable in this
        /// body; `finish` denies the erased structs.
        fn note_dyn_recovery(&mut self, what: impl FnOnce() -> String) {
            if self.census.dyn_to_thin.is_none() {
                let owner = self.owner();
                self.census.note_dyn_recovery(|| format!("{} in `{owner}`", what()));
            }
        }

        /// A conversion of a `src` value into `dst` — a cast or transmute of any kind
        /// — that does not keep every `dyn` it holds typed (`preserves_dyn`). When
        /// `src` holds a `dyn` the result can carry its data pointer as a thin
        /// pointer, an integer, a tuple or array of them, or a pointer to storage
        /// that holds one read at another type (`&raw const fat as *const usize`).
        /// When `dst` is a pointer to storage that holds a `dyn`, a `dyn` pointer
        /// written through it is read back through `src`'s type (`*mut [usize; 2]`
        /// as `*mut *mut dyn Any`).
        fn note_dyn_conversion(&mut self, src: Ty<'tcx>, dst: Ty<'tcx>) {
            let tcx = self.tcx();
            if self.census.dyn_to_thin.is_some() || preserves_dyn(tcx, src, dst) {
                return;
            }
            if self.census.holds_dyn(src) {
                self.note_dyn_recovery(|| {
                    format!("a thin pointer is recovered from it (`{src}` to `{dst}`)")
                });
            } else if pointer_pointee(tcx, dst).is_some() && self.census.holds_dyn(dst) {
                self.note_dyn_recovery(|| {
                    format!(
                        "a pointer to other storage is reinterpreted as a pointer to a `dyn` \
                         pointer (`{src}` to `{dst}`)"
                    )
                });
            }
        }

        /// A call whose instantiation holds a `dyn` (in its type arguments or
        /// parameters) to a function whose body the census does not scan. Each kind
        /// of callee is decided, with none left out:
        ///
        /// * a VIRTUAL call is the vtable itself, the sanctioned use of an erased
        ///   type; a local body is scanned (per instantiation: `mention_instance`);
        ///   compiler-generated glue and shims move or drop values whole;
        /// * an intrinsic: `transmute` is a conversion (`note_dyn_conversion`);
        ///   `size_of_val`, `align_of_val`, `vtable_size` and `vtable_align` read the
        ///   vtable; any other recovers when its result carries an address;
        /// * a sysroot function is trusted as parametric over a `dyn` it is handed —
        ///   except the `core::ptr` API (`<*mut T>::cast`, `addr`,
        ///   `expose_provenance`, `to_raw_parts`, `NonNull::cast`, …), whose purpose
        ///   is to convert pointers, and an `unsafe` one, whose contract the census
        ///   does not check: those recover when their result carries an address
        ///   (`carries_address`);
        /// * a function of a crate that is neither this one nor the sysroot is code
        ///   the census never sees: an `unsafe` one recovers whatever it is handed;
        ///   a safe one handed a mutable or raw path to a `dyn` is `note_dyn_handoff`
        ///   (by `mention_fn`), and a shared `&dyn` or an owned `Box<dyn>` grants it
        ///   no write to bytes this crate keeps, as for `S` itself (`external_fn`).
        fn dyn_call(&mut self, instance: Instance<'tcx>, sig: ty::FnSig<'tcx>) {
            let tcx = self.tcx();
            let def = match instance.def {
                InstanceKind::Intrinsic(def) | InstanceKind::LlvmIntrinsic(def) => {
                    self.dyn_intrinsic(def, instance.args, sig);
                    return;
                }
                InstanceKind::Item(def)
                | InstanceKind::Shim(ShimKind::Reify(def, _) | ShimKind::VTable(def)) => def,
                InstanceKind::Virtual(..)
                | InstanceKind::Shim(
                    ShimKind::FnPtr(..)
                    | ShimKind::FnPtrAsPtr(..)
                    | ShimKind::FnPtrFromPtr(..)
                    | ShimKind::ThreadLocal(..)
                    | ShimKind::ClosureOnce { .. }
                    | ShimKind::ConstructCoroutineInClosure { .. }
                    | ShimKind::DropGlue(..)
                    | ShimKind::Clone(..)
                    | ShimKind::FutureDropPoll(..)
                    | ShimKind::AsyncDropGlueCtor(..)
                    | ShimKind::AsyncDropGlue(..),
                ) => return,
            };
            if def.is_local() {
                return;
            }
            let unsafe_fn = matches!(
                tcx.fn_sig(def).skip_binder().skip_binder().safety(),
                rustc_hir::Safety::Unsafe
            );
            if !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def) {
                if unsafe_fn {
                    self.note_dyn_recovery(|| {
                        format!(
                            "the unsafe function `{}`, from a crate that is neither this crate \
                             nor the sysroot, is handed a `dyn`",
                            path(tcx, def)
                        )
                    });
                }
                return;
            }
            if (unsafe_fn || is_core_ptr_api(tcx, def)) && self.census.carries_address(sig.output())
            {
                self.note_dyn_recovery(|| {
                    format!(
                        "`{}` returns an address taken from a `dyn` (`{}`)",
                        path(tcx, def),
                        sig.output()
                    )
                });
            }
        }

        /// An intrinsic applied to a `dyn` (`dyn_call`).
        fn dyn_intrinsic(&mut self, def: DefId, args: GenericArgs<'tcx>, sig: ty::FnSig<'tcx>) {
            let tcx = self.tcx();
            let name = tcx.item_name(def);
            if name == sym::transmute || name == sym::transmute_unchecked {
                self.note_dyn_conversion(args.type_at(0), args.type_at(1));
            } else if name == sym::size_of_val
                || name == sym::align_of_val
                || name == sym::vtable_size
                || name == sym::vtable_align
            {
                // A size or an alignment read from the vtable, not an address.
            } else if self.census.carries_address(sig.output()) {
                self.note_dyn_recovery(|| {
                    format!(
                        "the intrinsic `{name}` returns an address taken from a `dyn` (`{}`)",
                        sig.output()
                    )
                });
            }
        }

        /// Trust: TINV step 6b — D3 (narrowed) and D4's v1 clause for one local of
        /// type `ty` (instantiated). D3 supplies the rustc-side "cannot classify"
        /// denial vcgen's root-shape refusal cannot see: an error, inference,
        /// placeholder or escaping bound type (none can occur in typeck'd MIR, so a
        /// belt); a storage-position alias that does not normalize, in a body that
        /// holds a TINV type; a `dyn` whose arguments reach a TINV type. A bare type
        /// parameter is NOT a denial: an instantiation at `S` is re-scanned per
        /// instantiation, and vcgen gives a generic body no identity.
        fn tinv_local_type(&mut self, ty: Ty<'tcx>) {
            let tcx = self.tcx();
            let mut unclassified = ty.references_error()
                || ty.has_infer()
                || ty.has_placeholders()
                || ty.has_escaping_bound_vars();
            if !unclassified {
                let walk = self.census.d3_walk(ty);
                unclassified = walk.overflow || walk.dyn_reaches_tinv;
                if !unclassified && !self.tinv_mentioned.is_empty() {
                    unclassified = walk.aliases.iter().any(|alias| {
                        alias.has_escaping_bound_vars()
                            || tcx
                                .try_normalize_erasing_regions(
                                    self.typing_env,
                                    ty::Unnormalized::new(*alias),
                                )
                                .is_err()
                    });
                }
            }
            if unclassified {
                let all = self.census.tinv_all();
                self.deny(&all, || format!("a local's type `{ty}` cannot be classified (TINV D3)"));
            }
            // D4, conservative v1 (TINV-17): a coroutine body holding a mutable path
            // to a TINV type can write it across a suspension point.
            if self.coroutine {
                let hit = self.census.mut_reached(ty).sealed.clone();
                let tinv = self.census.tinv_only(&hit);
                self.deny(&tinv, || {
                    format!(
                        "a coroutine body holds a mutable path to it (`{ty}`) (TINV D4, \
                         conservative v1)"
                    )
                });
            }
        }

        /// Trust: TINV step 6b — the TINV types whose FIELD storage `place` borrows: a
        /// `Field` projection of it whose base is a TINV type (any position).
        fn tinv_field_bases(&mut self, place: mir::PlaceRef<'tcx>) -> Vec<DefId> {
            let mut out = Vec::new();
            for (base, elem) in place.iter_projections() {
                if !matches!(elem, ProjectionElem::Field(..)) {
                    continue;
                }
                if let ty::Adt(adt, _) = *self.place_ty(base).kind() {
                    out.extend(self.census.tinv_only(&[adt.did()]));
                }
            }
            out
        }

        /// Trust: TINV step 6b — D2's element allowlist: the call is the authenticated
        /// sysroot `IndexMut::index_mut` of `Vec<T, A>` or `[T; N]`, or `DerefMut::deref_mut`
        /// of `Vec<T, A>`. Such a call returns a borrow of ELEMENT storage: the
        /// container's pointer and length are unchanged, and no v1 term reads element
        /// contents (TCB assumption: the sysroot impls are as documented).
        fn d2_element_access(&self, func: &Operand<'tcx>) -> bool {
            let tcx = self.tcx();
            let ty::FnDef(def, args) = *self.ty(func.ty(self.body, tcx)).kind() else {
                return false;
            };
            let lang = tcx.lang_items();
            let Some(trait_did) = tcx.trait_of_assoc(def) else { return false };
            let index = Some(trait_did) == lang.index_mut_trait();
            if !index && Some(trait_did) != lang.deref_mut_trait() {
                return false;
            }
            let Ok(Some(instance)) =
                Instance::try_resolve(tcx, self.typing_env, def, args.skip_binder())
            else {
                return false;
            };
            let InstanceKind::Item(impl_fn) = instance.def else { return false };
            if !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, impl_fn) {
                return false;
            }
            let Some(impl_did) = tcx.impl_of_assoc(impl_fn) else { return false };
            match *tcx.type_of(impl_did).instantiate_identity().skip_normalization().kind() {
                ty::Adt(adt, _) => tcx.is_diagnostic_item(sym::Vec, adt.did()),
                ty::Array(..) => index,
                _ => false,
            }
        }

        /// Trust: TINV step 6b — D2's call rule (iv), LIFETIME PARAMETRICITY on the
        /// callee's DECLARED signature: argument `k` may carry a field alias only if
        /// the callee is safe and its declared parameter `k` is `&'r mut T` with `'r` a
        /// late-bound region that occurs nowhere else — not in `T`, no other input,
        /// not the output. The callee then cannot keep the borrow past the call
        /// (it cannot name `'r` anywhere it could store it or hand it back). A late-bound
        /// region never occurs in the predicates, by definition. For a trait method the
        /// call names the trait item, so this reads the trait item's own signature,
        /// which every impl must be at least as general as. Occurrences are compared by
        /// bound-variable index across binder depths, which over-approximates (a nested
        /// binder's own variable of the same index counts): fail closed.
        fn d2_call_keeps_borrow_local(&self, func: &Operand<'tcx>, k: usize) -> bool {
            let tcx = self.tcx();
            let ty::FnDef(def, _) = *self.ty(func.ty(self.body, tcx)).kind() else {
                return false;
            };
            let sig = tcx.fn_sig(def).instantiate_identity().skip_normalization();
            let sig = sig.skip_binder();
            if !matches!(sig.safety(), rustc_hir::Safety::Safe) {
                return false;
            }
            let inputs = sig.inputs();
            let Some(&param) = inputs.get(k) else { return false };
            let ty::Ref(region, pointee, ty::Mutability::Mut) = *param.kind() else {
                return false;
            };
            let ty::ReBound(_, bound) = region.kind() else { return false };
            let occurs = |t: Ty<'tcx>| {
                t.walk().any(|arg| {
                    arg.as_region().is_some_and(
                        |r| matches!(r.kind(), ty::ReBound(_, b) if b.var == bound.var),
                    )
                })
            };
            !occurs(pointee)
                && !occurs(sig.output())
                && inputs.iter().enumerate().all(|(j, &t)| j == k || !occurs(t))
        }

        /// Trust: TINV step 6b — D2, FIELD-BORROW PROVENANCE (G5). A `&mut` borrow of a
        /// TINV type's field (or of anything inside one) is tracked through the locals
        /// it flows into, and every use of such an alias must be one of:
        ///
        /// * (i) a place that dereferences it first — a read or a write THROUGH it, as
        ///   an operand, an assignment or call destination, a drop;
        /// * (ii) a shared reborrow `&(*a).…`;
        /// * (iii) a non-semantic statement (storage, fake read, mention, ascription);
        /// * (iv) a call argument the callee's DECLARED signature keeps local
        ///   (`d2_call_keeps_borrow_local`);
        /// * (v) the receiver of an allowlisted element access (`d2_element_access`),
        ///   whose result is an alias of ELEMENT storage — unrestricted when the
        ///   element type reaches no TINV type, otherwise tracked like a field alias;
        ///
        /// plus the flows that define aliases (a `&mut` borrow, a move/copy of an
        /// alias, a `&mut` reborrow through one) into a BARE non-return local. Every
        /// other use denies: a return, a store into a projection, an aggregate or a
        /// capture, a cast, a raw pointer, any other rvalue or terminator operand, and
        /// any statement or terminator form not listed. An allowlist, not a blocklist.
        ///
        /// Premise (TINV-14, docs/KNOWN_HAZARDS.md): a write through an admitted alias
        /// is seen by vcgen's safety walk as a havoc of the sticky-dirty root's field.
        fn tinv_field_aliases(&mut self) {
            let body = self.body;
            let n = body.local_decls.len();
            let mut alias: IndexVec<Local, Vec<DefId>> = IndexVec::from_elem_n(Vec::new(), n);
            let merge = |alias: &mut IndexVec<Local, Vec<DefId>>, local: Local, add: &[DefId]| {
                let mut grew = false;
                for did in add {
                    if !alias[local].contains(did) {
                        alias[local].push(*did);
                        grew = true;
                    }
                }
                grew
            };
            // The alias sets only grow and are bounded by locals × TINV types.
            let bound = n.saturating_mul(self.census.tinv_all().len().max(1)).saturating_add(2);
            let mut rounds = 0usize;
            loop {
                rounds += 1;
                if rounds > bound {
                    let mentioned = self.tinv_mentioned.clone();
                    self.deny(&mentioned, || "the D2 alias fixpoint did not converge".to_string());
                    return;
                }
                let mut changed = false;
                for data in body.basic_blocks.iter() {
                    for stmt in &data.statements {
                        let StatementKind::Assign(assign) = &stmt.kind else { continue };
                        let (dest, rvalue) = &**assign;
                        if !dest.projection.is_empty() {
                            continue;
                        }
                        let gained: Vec<DefId> = match rvalue {
                            Rvalue::Ref(_, mir::BorrowKind::Mut { .. }, place) => {
                                let mut got = self.tinv_field_bases(place.as_ref());
                                if place.projection.first() == Some(&ProjectionElem::Deref) {
                                    got.extend(alias[place.local].iter().copied());
                                }
                                got
                            }
                            Rvalue::Use(Operand::Copy(place) | Operand::Move(place), ..)
                            | Rvalue::CopyForDeref(place)
                                if place.projection.is_empty() =>
                            {
                                alias[place.local].clone()
                            }
                            _ => Vec::new(),
                        };
                        changed |= merge(&mut alias, dest.local, &gained);
                    }
                    // (v): the element borrow an allowlisted access returns.
                    if let TerminatorKind::Call { func, args, destination, .. } =
                        &data.terminator().kind
                        && destination.projection.is_empty()
                        && let Some(receiver) = args.first()
                        && let Operand::Copy(place) | Operand::Move(place) = &receiver.node
                        && place.projection.is_empty()
                        && !alias[place.local].is_empty()
                        && self.d2_element_access(func)
                    {
                        let dest_ty = self.ty(body.local_decls[destination.local].ty);
                        let element = match *dest_ty.kind() {
                            ty::Ref(_, pointee, _) => self.census.tinv_reached(pointee),
                            _ => self.census.tinv_all(),
                        };
                        if !element.is_empty() {
                            let mut add = alias[place.local].clone();
                            add.extend(element);
                            changed |= merge(&mut alias, destination.local, &add);
                        }
                    }
                }
                if !changed {
                    break;
                }
            }

            // The use pass.
            let mut denials: Vec<(Vec<DefId>, String)> = Vec::new();
            for (bb, data) in body.basic_blocks.iter_enumerated() {
                for (index, stmt) in data.statements.iter().enumerate() {
                    let location = Location { block: bb, statement_index: index };
                    let mentions = AliasMentions::of_statement(&alias, stmt, location);
                    match &stmt.kind {
                        StatementKind::Assign(assign) => {
                            let (dest, rvalue) = &**assign;
                            let bare_dest =
                                dest.projection.is_empty() && dest.local != mir::RETURN_PLACE;
                            // The destination: a bare local (re)binds a pointer; a deref
                            // writes through it (i).
                            if !alias[dest.local].is_empty()
                                && !dest.projection.is_empty()
                                && dest.projection.first() != Some(&ProjectionElem::Deref)
                            {
                                denials.push((
                                    alias[dest.local].clone(),
                                    format!("its field alias is projected at {location:?}"),
                                ));
                            }
                            match rvalue {
                                Rvalue::Ref(_, kind, place) => {
                                    let mut structs = Vec::new();
                                    if matches!(kind, mir::BorrowKind::Mut { .. }) {
                                        structs = self.tinv_field_bases(place.as_ref());
                                    }
                                    let through =
                                        place.projection.first() == Some(&ProjectionElem::Deref);
                                    if !alias[place.local].is_empty() {
                                        if !through {
                                            // A borrow of the alias local itself.
                                            denials.push((
                                                alias[place.local].clone(),
                                                format!(
                                                    "its field alias is borrowed at {location:?}"
                                                ),
                                            ));
                                        } else if matches!(kind, mir::BorrowKind::Mut { .. }) {
                                            structs.extend(alias[place.local].iter().copied());
                                        }
                                    }
                                    if !structs.is_empty() && !bare_dest {
                                        denials.push((
                                            structs,
                                            format!(
                                                "a `&mut` borrow of its field flows into `{dest:?}` \
                                                 at {location:?}"
                                            ),
                                        ));
                                    }
                                }
                                Rvalue::Use(Operand::Copy(place) | Operand::Move(place), ..)
                                | Rvalue::CopyForDeref(place)
                                    if place.projection.is_empty()
                                        && !alias[place.local].is_empty() =>
                                {
                                    if !bare_dest {
                                        denials.push((
                                            alias[place.local].clone(),
                                            format!(
                                                "its field alias flows into `{dest:?}` at {location:?}"
                                            ),
                                        ));
                                    }
                                }
                                Rvalue::RawPtr(RawPtrKind::FakeForPtrMetadata, place)
                                    if place.projection.first() == Some(&ProjectionElem::Deref) => {
                                }
                                Rvalue::RawPtr(_, place) if !alias[place.local].is_empty() => {
                                    denials.push((
                                        alias[place.local].clone(),
                                        format!("a raw pointer is taken through its field alias at {location:?}"),
                                    ));
                                }
                                // Any other rvalue: only reads through an alias (i).
                                _ => {
                                    for local in &mentions.bare {
                                        denials.push((
                                            alias[*local].clone(),
                                            format!(
                                                "its field alias is used by value at {location:?}"
                                            ),
                                        ));
                                    }
                                }
                            }
                        }
                        // A write through the alias (i), or nothing to do with one.
                        StatementKind::SetDiscriminant { .. } => {
                            for local in &mentions.bare {
                                denials.push((
                                    alias[*local].clone(),
                                    format!("its field alias is used at {location:?}"),
                                ));
                            }
                        }
                        // (iii).
                        StatementKind::FakeRead(..)
                        | StatementKind::StorageLive(..)
                        | StatementKind::StorageDead(..)
                        | StatementKind::PlaceMention(..)
                        | StatementKind::AscribeUserType(..)
                        | StatementKind::Coverage(..)
                        | StatementKind::ConstEvalCounter
                        | StatementKind::Nop
                        | StatementKind::BackwardIncompatibleDropHint { .. } => {}
                        StatementKind::Intrinsic(..) => {
                            for local in mentions.bare.iter().chain(&mentions.deref) {
                                denials.push((
                                    alias[*local].clone(),
                                    format!("an intrinsic statement uses its field alias at {location:?}"),
                                ));
                            }
                        }
                    }
                }
                let location = body.terminator_loc(bb);
                let terminator = data.terminator();
                let mentions = || AliasMentions::of_terminator(&alias, terminator, location);
                match &terminator.kind {
                    TerminatorKind::Call { func, args, destination, .. } => {
                        let func_mentions = AliasMentions::of_operand(&alias, func, location);
                        for local in func_mentions.bare.iter().chain(&func_mentions.deref) {
                            denials.push((
                                alias[*local].clone(),
                                format!(
                                    "the callee is reached through its field alias at {location:?}"
                                ),
                            ));
                        }
                        if !alias[destination.local].is_empty()
                            && !destination.projection.is_empty()
                            && destination.projection.first() != Some(&ProjectionElem::Deref)
                        {
                            denials.push((
                                alias[destination.local].clone(),
                                format!("its field alias is projected at {location:?}"),
                            ));
                        }
                        for (k, arg) in args.iter().enumerate() {
                            let (Operand::Copy(place) | Operand::Move(place)) = &arg.node else {
                                continue;
                            };
                            if alias[place.local].is_empty()
                                || place.projection.first() == Some(&ProjectionElem::Deref)
                            {
                                continue;
                            }
                            let admitted = place.projection.is_empty()
                                && ((k == 0 && self.d2_element_access(func))
                                    || self.d2_call_keeps_borrow_local(func, k));
                            if !admitted {
                                let callee = self.ty(func.ty(body, self.tcx()));
                                denials.push((
                                    alias[place.local].clone(),
                                    format!(
                                        "its field alias is passed as argument {k} of `{callee}`, \
                                         whose declared signature does not keep the borrow \
                                         local, at {location:?}"
                                    ),
                                ));
                            }
                        }
                    }
                    // A drop of the reference itself, or a drop-and-replace through it (i).
                    TerminatorKind::Drop { .. } => {}
                    TerminatorKind::SwitchInt { .. } | TerminatorKind::Assert { .. } => {
                        for local in &mentions().bare {
                            denials.push((
                                alias[*local].clone(),
                                format!("its field alias is used by value at {location:?}"),
                            ));
                        }
                    }
                    TerminatorKind::Goto { .. }
                    | TerminatorKind::UnwindResume
                    | TerminatorKind::UnwindTerminate(..)
                    | TerminatorKind::Return
                    | TerminatorKind::Unreachable
                    | TerminatorKind::CoroutineDrop
                    | TerminatorKind::FalseEdge { .. }
                    | TerminatorKind::FalseUnwind { .. } => {}
                    TerminatorKind::TailCall { .. }
                    | TerminatorKind::Yield { .. }
                    | TerminatorKind::InlineAsm { .. } => {
                        let mentions = mentions();
                        for local in mentions.bare.iter().chain(&mentions.deref) {
                            denials.push((
                                alias[*local].clone(),
                                format!("its field alias reaches a tail call, yield or assembly at {location:?}"),
                            ));
                        }
                    }
                }
            }
            for (structs, what) in denials {
                self.deny(&structs, || format!("{what} (TINV D2 field-borrow provenance)"));
            }
        }
    }

    /// Trust: TINV step 6b — the field-alias locals (D2) one statement, terminator
    /// or operand mentions: `deref` when the place dereferences the alias first (a
    /// use through it), `bare` otherwise (the alias value itself).
    struct AliasMentions<'s> {
        alias: &'s IndexVec<Local, Vec<DefId>>,
        bare: Vec<Local>,
        deref: Vec<Local>,
    }

    impl<'s> AliasMentions<'s> {
        fn new(alias: &'s IndexVec<Local, Vec<DefId>>) -> Self {
            AliasMentions { alias, bare: Vec::new(), deref: Vec::new() }
        }

        fn of_statement<'tcx>(
            alias: &'s IndexVec<Local, Vec<DefId>>,
            stmt: &mir::Statement<'tcx>,
            location: Location,
        ) -> Self {
            let mut out = Self::new(alias);
            out.visit_statement(stmt, location);
            out
        }

        fn of_terminator<'tcx>(
            alias: &'s IndexVec<Local, Vec<DefId>>,
            terminator: &Terminator<'tcx>,
            location: Location,
        ) -> Self {
            let mut out = Self::new(alias);
            out.visit_terminator(terminator, location);
            out
        }

        fn of_operand<'tcx>(
            alias: &'s IndexVec<Local, Vec<DefId>>,
            operand: &Operand<'tcx>,
            location: Location,
        ) -> Self {
            let mut out = Self::new(alias);
            out.visit_operand(operand, location);
            out
        }
    }

    impl<'tcx> Visitor<'tcx> for AliasMentions<'_> {
        fn visit_place(
            &mut self,
            place: &Place<'tcx>,
            _context: PlaceContext,
            _location: Location,
        ) {
            if self.alias[place.local].is_empty() {
                return;
            }
            if place.projection.first() == Some(&ProjectionElem::Deref) {
                self.deref.push(place.local);
            } else {
                self.bare.push(place.local);
            }
        }
    }

    /// The pointee of a pointer-like `ty`: a reference, raw pointer, `Box` or
    /// `NonNull`.
    fn pointer_pointee<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
        match *ty.kind() {
            ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _) => Some(pointee),
            ty::Adt(adt, args)
                if adt.is_box()
                    || tcx
                        .is_lang_item(adt.did(), rustc_attr_ir::lang_items::LangItem::NonNull) =>
            {
                Some(args.type_at(0))
            }
            _ => None,
        }
    }

    /// Whether converting a `src` value into `dst` keeps every `dyn` it holds typed:
    /// the same type; one pointer-like value converted to another over the SAME
    /// pointee (a mutability change, reference to raw pointer, `Box` to raw pointer,
    /// …) or over its array or slice element; or a pointer to a `dyn` converted to a
    /// pointer to a `dyn` (the vtable travels with the data pointer: an auto-trait
    /// change, an upcast, a lifetime extension).
    fn preserves_dyn<'tcx>(tcx: TyCtxt<'tcx>, src: Ty<'tcx>, dst: Ty<'tcx>) -> bool {
        if src == dst {
            return true;
        }
        match (pointer_pointee(tcx, src), pointer_pointee(tcx, dst)) {
            (Some(a), Some(b)) => {
                a == b
                    || matches!(*a.kind(), ty::Array(elem, _) | ty::Slice(elem) if elem == b)
                    || (matches!(a.kind(), ty::Dynamic(..)) && matches!(b.kind(), ty::Dynamic(..)))
            }
            _ => false,
        }
    }

    /// Whether `def` is the `core::ptr` API — a function of that module or a method
    /// of a type it defines (raw pointers, `NonNull`, `Unique`): the sysroot
    /// functions whose purpose is to convert one pointer into another or into an
    /// address. `DynMetadata`'s methods, also there, read the vtable, not the data
    /// pointer. `def` is in the real sysroot (the caller checks).
    fn is_core_ptr_api(tcx: TyCtxt<'_>, def: DefId) -> bool {
        if tcx.crate_name(def.krate) != sym::core
            || !matches!(
                tcx.def_path(def).data.first().map(|segment| segment.data),
                Some(rustc_hir::definitions::DefPathData::TypeNs(name)) if name == sym::ptr
            )
        {
            return false;
        }
        let Some(impl_did) = tcx.impl_of_assoc(def) else { return true };
        !matches!(
            *tcx.type_of(impl_did).instantiate_identity().skip_normalization().kind(),
            ty::Adt(adt, _) if tcx.lang_items().dyn_metadata() == Some(adt.did())
        )
    }

    /// `ElaborateBoxDerefs` temporaries (single-assignment locals defined by
    /// `transmute(copy box.0.0) as *const T`) and the locations defining them.
    fn box_deref_temps<'tcx>(body: &Body<'tcx>) -> (DenseBitSet<Local>, FxHashSet<Location>) {
        let mut assignments: IndexVec<Local, u32> = IndexVec::from_elem(0, &body.local_decls);
        let mut candidates: Vec<(Local, Location)> = Vec::new();
        for (bb, data) in body.basic_blocks.iter_enumerated() {
            for (idx, stmt) in data.statements.iter().enumerate() {
                let StatementKind::Assign(assign) = &stmt.kind else { continue };
                let (place, rvalue) = &**assign;
                if !place.projection.is_empty() {
                    continue;
                }
                assignments[place.local] += 1;
                // Trust (1.101): the pass now spells the temporary
                // `Cast(BoxDerefTransmute, Copy(_box.0), *const T)` — one field
                // projection to the `BoxRaw`, then the dedicated cast kind —
                // where 1.99 spelled `Cast(Transmute, Copy(_box.0.0), *const T)`
                // through Unique/NonNull. Both spellings are the pass's shape
                // and nothing else's (a user transmute of a box field is neither
                // single-projection BoxDerefTransmute nor, in optimized MIR,
                // distinguishable from the old one — the old arm is kept for
                // bodies that never saw the pass, e.g. promoted constants).
                if let Rvalue::Cast(kind, Operand::Copy(src), _) = rvalue
                    && body.local_decls[src.local].ty.is_box()
                    && match kind {
                        CastKind::BoxDerefTransmute => {
                            src.projection.len() == 1
                                && matches!(src.projection[0], ProjectionElem::Field(f, _) if f.as_usize() == 0)
                        }
                        CastKind::Transmute => {
                            src.projection.len() == 2
                                && src
                                    .projection
                                    .iter()
                                    .all(|elem| matches!(elem, ProjectionElem::Field(..)))
                        }
                        _ => false,
                    }
                {
                    candidates.push((place.local, Location { block: bb, statement_index: idx }));
                }
            }
        }
        let mut temps = DenseBitSet::new_empty(body.local_decls.len());
        let mut defs = FxHashSet::default();
        // A temporary assigned more than once is not the pass's shape.
        for (local, location) in candidates {
            if assignments[local] == 1 {
                temps.insert(local);
                defs.insert(location);
            }
        }
        (temps, defs)
    }

    /// `RawPtrKind::FakeForPtrMetadata` temporaries: a local single-assigned from
    /// `&raw const (fake) <place>`. The MIR builder emits exactly this to read the
    /// length of a non-`Copy` slice place before a bounds check
    /// (`_t = &raw const (fake) (*s); _len = PtrMetadata(move _t)`); the pointer
    /// addresses no field, is never dereferenced, and no user syntax names it. A
    /// local assigned more than once is not this shape and is not exempted.
    fn metadata_temps<'tcx>(body: &Body<'tcx>) -> DenseBitSet<Local> {
        let mut assignments: IndexVec<Local, u32> = IndexVec::from_elem(0, &body.local_decls);
        let mut candidates: Vec<Local> = Vec::new();
        for data in body.basic_blocks.iter() {
            for stmt in data.statements.iter() {
                let StatementKind::Assign(assign) = &stmt.kind else { continue };
                let (place, rvalue) = &**assign;
                if !place.projection.is_empty() {
                    continue;
                }
                assignments[place.local] += 1;
                if let Rvalue::RawPtr(RawPtrKind::FakeForPtrMetadata, _) = rvalue {
                    candidates.push(place.local);
                }
            }
        }
        let mut temps = DenseBitSet::new_empty(body.local_decls.len());
        for local in candidates {
            if assignments[local] == 1 {
                temps.insert(local);
            }
        }
        temps
    }

    impl<'tcx> Visitor<'tcx> for BodyScan<'_, '_, '_, 'tcx> {
        fn visit_local_decl(&mut self, local: Local, decl: &LocalDecl<'tcx>) {
            // Trust (CENSUS-THIRD-PARTY-1): a value of a third-party type (its drop glue
            // and every method on it are third-party code).
            {
                let tcx = self.tcx();
                let ty = self.ty(decl.ty);
                if mentions_third_party(tcx, ty) {
                    let owner = self.owner();
                    self.census.note_third_party(|| {
                        format!("`{owner}` holds a value of the third-party type `{ty}`")
                    });
                }
            }
            if !self.box_temps.contains(local) && !self.metadata_temps.contains(local) {
                let ty = self.ty(decl.ty);
                let hit = self.census.raw_reached(ty);
                self.deny(&hit, || format!("a raw pointer to it is held (`{ty}`)"));
                self.note_instances(ty);
            }
            // Trust: TINV step 6b — D3 (narrowed) and D4's conservative v1 clause.
            if self.census.has_tinv {
                let ty = self.ty(decl.ty);
                self.tinv_local_type(ty);
            }
            self.super_local_decl(local, decl);
        }

        fn visit_place(&mut self, place: &Place<'tcx>, context: PlaceContext, location: Location) {
            if matches!(context, PlaceContext::NonUse(_)) {
                return;
            }
            if self.box_temps.contains(place.local)
                && place.projection.first() != Some(&ProjectionElem::Deref)
                && !matches!(context, PlaceContext::MutatingUse(MutatingUseContext::Store))
            {
                let ty = self.ty(self.body.local_decls[place.local].ty);
                let hit = self.census.raw_reached(ty);
                self.deny(&hit, || "a `Box`'s pointer escapes as a raw pointer".to_string());
            }
            // The storage a write changes lies after the place's LAST deref: a field
            // before a later deref only names the pointer read on the way
            // (`*self.ptr = v` writes THROUGH the pointer, not TO it).
            let storage_from = place
                .projection
                .iter()
                .rposition(|elem| matches!(elem, ProjectionElem::Deref))
                .map_or(0, |deref| deref + 1);
            let write = can_write(context);
            for (index, (base, elem)) in place.iter_projections().enumerate() {
                let ProjectionElem::Field(field, _) = elem else { continue };
                let base_ty = self.place_ty(base);
                let ty::Adt(adt, _) = *base_ty.kind() else { continue };
                if adt.is_union() {
                    // A union field this crate can name reinterprets the union's bytes.
                    // (`MaybeUninit`'s private `value` field is reached only by the
                    // compiler's own `write_box_via_move` lowering, which stores a whole
                    // value of the field's type.)
                    let visible = adt.did().is_local()
                        || adt.non_enum_variant().fields[field].vis.is_public();
                    if visible {
                        let hit = self.census.reached(base_ty);
                        self.deny(&hit, || {
                            format!("the union `{base_ty}` that holds it is accessed by a field")
                        });
                        // A `dyn` pointer stored through one field is read as the
                        // other field's type.
                        if self.census.holds_dyn(base_ty) {
                            self.note_dyn_recovery(|| {
                                format!("the union `{base_ty}` over a `dyn` pointer is accessed by a field")
                            });
                        }
                    }
                    continue;
                }
                // Trust: TINV step 6b — D4: a coroutine body that writes (or borrows
                // mutably) a field of a TINV type opens a window on it across a
                // suspension point the obligations do not model. Any field position,
                // before or after a deref.
                if write
                    && self.coroutine
                    && self.census.has_tinv
                    && let tinv = self.census.tinv_only(&[adt.did()])
                    && !tinv.is_empty()
                {
                    self.deny(&tinv, || {
                        "a coroutine body writes or mutably borrows one of its fields (TINV D4)"
                            .to_string()
                    });
                }
                if !write || index < storage_from {
                    continue;
                }
                // Trust: TINV step 6a — the backing role's field-write denial.
                if let Some(SealedType {
                    role: SealedRole::Backing { ptr_field, len_field }, ..
                }) = self.census.sealed.get(&adt.did())
                    && (field == *ptr_field || field == *len_field)
                {
                    let what = if field == *len_field { "length" } else { "pointer" };
                    let did = adt.did();
                    self.deny(&[did], || format!("its {what} field is written"));
                }
            }
            self.super_place(place, context, location);
        }

        fn visit_rvalue(&mut self, rvalue: &Rvalue<'tcx>, location: Location) {
            let tcx = self.tcx();
            match rvalue {
                // `&raw const (fake)` is the pointer the MIR builder takes on a
                // non-`Copy` slice place PURELY to read its length by `PtrMetadata`
                // (`RawPtrKind::FakeForPtrMetadata`). It addresses no field, is never
                // dereferenced, and the program cannot name it, so it is not an
                // escape — every bounds-checked index and slice pattern on `&mut [S]`
                // or `Box<[S]>` lowers through it. The temporary it defines is
                // exempted in `visit_local_decl`.
                Rvalue::RawPtr(RawPtrKind::FakeForPtrMetadata, _) => {}
                Rvalue::RawPtr(_, place) => {
                    // The pointer's provenance covers the place and, through pointer
                    // arithmetic, the storage holding it: every prefix after the last
                    // deref.
                    let storage_from = place
                        .projection
                        .iter()
                        .rposition(|elem| matches!(elem, ProjectionElem::Deref))
                        .map_or(0, |deref| deref + 1);
                    let mut tys = vec![self.place_ty(place.as_ref())];
                    for (index, (base, _)) in place.iter_projections().enumerate() {
                        if index >= storage_from {
                            tys.push(self.place_ty(base));
                        }
                    }
                    let hit = self.census.reached_in(tys);
                    self.deny(&hit, || {
                        "a raw pointer is taken to storage that holds it".to_string()
                    });
                }
                // The `ElaborateBoxDerefs` temporary's definition: a `Box`'s own
                // pointer at its own pointee type (`box_deref_temps`).
                Rvalue::Cast(..) if self.box_defs.contains(&location) => {}
                Rvalue::Cast(kind, operand, target) => {
                    let src = self.ty(operand.ty(self.body, tcx));
                    let dst = self.ty(*target);
                    // Every cast kind, so a new one cannot pass unexamined: each that can
                    // change how bytes are typed goes through `note_dyn_conversion`.
                    match kind {
                        CastKind::Transmute => {
                            self.note_dyn_conversion(src, dst);
                            let hit = self.census.reached_in([src, dst]);
                            self.deny(&hit, || format!("it is transmuted (`{src}` to `{dst}`)"));
                        }
                        CastKind::PtrToPtr
                        | CastKind::BoxDerefTransmute
                        | CastKind::FnPtrToPtr
                        | CastKind::PointerExposeProvenance
                        | CastKind::PointerWithExposedProvenance
                        | CastKind::PointerCoercion(
                            PointerCoercion::MutToConstPointer | PointerCoercion::ArrayToPointer,
                            _,
                        ) => {
                            self.note_dyn_conversion(src, dst);
                            let mut hit = (*self.census.raw_reached(src)).clone();
                            hit.extend(self.census.raw_reached(dst).iter().copied());
                            self.deny(&hit, || {
                                format!("a raw pointer to it is cast (`{src}` to `{dst}`)")
                            });
                        }
                        // Erases INTO a `dyn`, or changes one `dyn` (or array) pointee
                        // into another unsized one: the value keeps its type.
                        CastKind::PointerCoercion(PointerCoercion::Unsize, _) => {
                            self.unsize(src, dst)
                        }
                        // A fn item, a non-capturing closure, a fn pointer or a number:
                        // no data pointer to recover (`note_dyn_conversion` keeps that
                        // a checked fact rather than an assumption about the kinds).
                        CastKind::PointerCoercion(
                            PointerCoercion::ReifyFnPointer(_)
                            | PointerCoercion::UnsafeFnPointer
                            | PointerCoercion::ClosureFnPointer(_),
                            _,
                        )
                        | CastKind::IntToInt
                        | CastKind::FloatToInt
                        | CastKind::FloatToFloat
                        | CastKind::IntToFloat
                        | CastKind::Subtype => self.note_dyn_conversion(src, dst),
                    }
                }
                Rvalue::Aggregate(kind, _) => match **kind {
                    AggregateKind::Adt(did, _, args, _, _) if tcx.adt_def(did).is_union() => {
                        let ty = Ty::new_adt(tcx, tcx.adt_def(did), self.generic_args(args));
                        let hit = self.census.reached(ty);
                        self.deny(&hit, || format!("a union `{ty}` that holds it is constructed"));
                        if self.census.holds_dyn(ty) {
                            self.note_dyn_recovery(|| {
                                format!("a union `{ty}` over a `dyn` pointer is constructed")
                            });
                        }
                    }
                    AggregateKind::RawPtr(pointee, _) => {
                        let pointee = self.ty(pointee);
                        let hit = self.census.reached(pointee);
                        self.deny(&hit, || {
                            format!("a raw pointer to `{pointee}` is assembled from parts")
                        });
                    }
                    // Trust: TINV step 6b — D4: a coroutine body constructs a TINV type.
                    AggregateKind::Adt(did, ..)
                        if self.coroutine
                            && self.census.has_tinv
                            && !self.census.tinv_only(&[did]).is_empty() =>
                    {
                        self.deny(&[did], || {
                            "a coroutine body constructs it (TINV D4)".to_string()
                        });
                    }
                    // Typed values built from their parts; a `RawPtr` aggregate builds a
                    // `dyn` pointer FROM a data pointer and metadata, never the reverse.
                    AggregateKind::Array(_)
                    | AggregateKind::Tuple
                    | AggregateKind::Adt(..)
                    | AggregateKind::Closure(..)
                    | AggregateKind::Coroutine(..)
                    | AggregateKind::CoroutineClosure(..) => {}
                },
                // The binder's inner type is the operand's own (up to lifetimes): it
                // keeps a `dyn` typed.
                Rvalue::WrapUnsafeBinder(operand, target) => {
                    let src = self.ty(operand.ty(self.body, tcx));
                    let dst = self.ty(*target);
                    let hit = self.census.reached_in([src, dst]);
                    self.deny(&hit, || "it is wrapped in an unsafe binder".to_string());
                }
                // Typed copies and moves (`Use`, `CopyForDeref`, `Repeat`), typed
                // references to a place (`Ref`, `ThreadLocalRef`; `RawPtr` above), an
                // enum's discriminant, a `dyn` pointer's metadata (`PtrMetadata`: the
                // vtable, not the data pointer), and arithmetic and comparisons (on
                // pointers: a `bool`, an `Ordering`, or `Offset`'s pointer of the same
                // type). None turns a `dyn` pointer's data pointer into another type.
                // Trust: TINV step 6b — D4: a coroutine body takes `&mut` of a whole
                // TINV value.
                Rvalue::Ref(_, mir::BorrowKind::Mut { .. }, place)
                    if self.coroutine && self.census.has_tinv =>
                {
                    let ty = self.place_ty(place.as_ref());
                    if let ty::Adt(adt, _) = *ty.kind() {
                        let tinv = self.census.tinv_only(&[adt.did()]);
                        self.deny(&tinv, || {
                            "a coroutine body takes `&mut` of a value of it (TINV D4)".to_string()
                        });
                    }
                }
                Rvalue::Use(..)
                | Rvalue::CopyForDeref(..)
                | Rvalue::Repeat(..)
                | Rvalue::Ref(..)
                | Rvalue::ThreadLocalRef(..)
                | Rvalue::Discriminant(..)
                | Rvalue::UnaryOp(..)
                | Rvalue::BinaryOp(..) => {}
                // A bitwise copy of an ADT at its own type (`Mut`) or at its
                // `CoerceShared` target (`Not`): a type with the same layout, i.e. a
                // reinterpretation of the bytes, as a transmute is.
                Rvalue::Reborrow(target, _, place) => {
                    let src = self.place_ty(place.as_ref());
                    let dst = self.ty(*target);
                    if src != dst {
                        self.note_dyn_conversion(src, dst);
                        let hit = self.census.reached_in([src, dst]);
                        self.deny(&hit, || {
                            format!("it is reinterpreted by a reborrow (`{src}` to `{dst}`)")
                        });
                    }
                }
            }
            self.super_rvalue(rvalue, location);
        }

        fn visit_const_operand(&mut self, constant: &ConstOperand<'tcx>, location: Location) {
            let tcx = self.tcx();

            let ty = self.ty(constant.const_.ty());
            let hit = self.census.raw_reached(ty);
            self.deny(&hit, || format!("a constant raw pointer to it is used (`{ty}`)"));
            if let ty::FnDef(did, args) = *ty.kind() {
                self.mention_fn(did, args.skip_binder());
            }
            if let mir::Const::Unevaluated(unevaluated, _) = constant.const_
                && unevaluated.def.is_local()
            {
                let args = self.generic_args(unevaluated.args);
                if self.census.instantiation_matters_for(unevaluated.def, args.types())
                    && tcx.generics_of(unevaluated.def).requires_monomorphization(tcx)
                {
                    // Trust: TINV — a TRAIT associated const (`T::C`, instantiated with a
                    // concrete `T`) names the trait item, which may have no body at all;
                    // reading one ICEd in `with_body`. Scan the impl's (or the default's)
                    // body it resolves to; an unresolvable one denies what it touches.
                    if tcx.trait_of_assoc(unevaluated.def).is_some() {
                        match Instance::try_resolve(tcx, self.typing_env, unevaluated.def, args) {
                            Ok(Some(instance)) => {
                                let def = instance.def_id();
                                if def.is_local()
                                    && tcx.generics_of(def).requires_monomorphization(tcx)
                                {
                                    self.census.enqueue(def, instance.args, self.env_def);
                                }
                            }
                            _ => {
                                let hit = self.census.reached_in(args.types());
                                self.deny(&hit, || {
                                    format!(
                                        "the associated constant `{}` over it resolves to no body \
                                         the census can scan",
                                        path(tcx, unevaluated.def)
                                    )
                                });
                            }
                        }
                    } else {
                        self.census.enqueue(unevaluated.def, args, self.env_def);
                    }
                }
            }
            self.super_const_operand(constant, location);
        }

        fn visit_terminator(&mut self, terminator: &Terminator<'tcx>, location: Location) {
            let tcx = self.tcx();
            if let TerminatorKind::InlineAsm { operands, .. } = &terminator.kind {
                let mut tys = Vec::new();
                for operand in operands.iter() {
                    match operand {
                        InlineAsmOperand::In { value, .. } => {
                            tys.push(self.ty(value.ty(self.body, tcx)))
                        }
                        InlineAsmOperand::Out { place: Some(place), .. } => {
                            tys.push(self.place_ty(place.as_ref()))
                        }
                        InlineAsmOperand::InOut { in_value, out_place, .. } => {
                            tys.push(self.ty(in_value.ty(self.body, tcx)));
                            if let Some(place) = out_place {
                                tys.push(self.place_ty(place.as_ref()));
                            }
                        }
                        InlineAsmOperand::SymStatic { def_id } => tys
                            .push(tcx.type_of(*def_id).instantiate_identity().skip_normalization()),
                        InlineAsmOperand::SymFn { value } => {
                            if let ty::FnDef(did, args) = *self.ty(value.const_.ty()).kind() {
                                match self.callee_sig(did, args.skip_binder()) {
                                    Some(sig) => tys.extend(sig.inputs_and_output.iter()),
                                    None => self.unnormalized_callee(did),
                                }
                            }
                        }
                        _ => {}
                    }
                }
                if self.census.holds_dyn_in(tys.iter().copied()) {
                    self.note_dyn_recovery(|| "inline assembly is handed a `dyn`".to_string());
                }
                let hit = self.census.reached_in(tys);
                self.deny(&hit, || "inline assembly reaches it".to_string());
            }
            // Trust: TINV step 6b — D5: a tail call replaces this frame, so no R or U
            // point of it is ever reached; a census belt for vcgen's `URefusal::TailCall`.
            if let TerminatorKind::TailCall { .. } = &terminator.kind
                && self.census.has_tinv
            {
                let mentioned = self.tinv_mentioned.clone();
                self.deny(&mentioned, || {
                    "a body that holds it makes a tail call (TINV D5)".to_string()
                });
            }
            self.super_terminator(terminator, location);
        }
    }
}

/// The one synthetic-verdict shape every structurally-skipped function reports:
/// a SINGLE `UnsupportedMir { kind: unsupported_mir_kind, detail }` obligation at
/// the body's span whose result is `Unknown { solver, reason }`. It can never read
/// as `Proved`/passed in the terminal report, the cache, or any downstream gate,
/// and `full_verification: None` keeps any consumer from mistaking it for a
/// completed full-verification run. Every caller's `unsupported_mir_kind`,
/// `solver` and `reason` strings are keyed on by tests and `targo` reports, so
/// they stay spelled at the call site.
fn single_unknown_row_artifacts(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    def_path: &str,
    unsupported_mir_kind: &str,
    detail: String,
    solver: &str,
    reason: String,
) -> VerificationArtifacts {
    single_row_artifacts(
        tcx,
        body,
        def_path,
        unsupported_mir_kind,
        detail,
        VerificationResult::Unknown {
            solver: trust_types::Symbol::intern(solver),
            time_ms: 0,
            reason,
        },
    )
}

/// [`single_unknown_row_artifacts`] for any undecided `result`.
fn single_row_artifacts(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    def_path: &str,
    unsupported_mir_kind: &str,
    detail: String,
    result: VerificationResult,
) -> VerificationArtifacts {
    let vc = VerificationCondition {
        kind: VcKind::UnsupportedMir { kind: unsupported_mir_kind.to_string(), detail },
        function: trust_types::Symbol::intern(def_path),
        location: source_span_from_rustc_span(tcx, body.span),
        formula: trust_types::Formula::Bool(false),
        contract_metadata: None,
        // Not a contract-derived VC: no obligation to back-reference.
        obligation: None,
    };
    let results = vec![(vc, result)];
    // Trust (M-Pkg perf): kernel-certify each obligation once, then share the
    // verdicts with both the proof-results and transport builders.
    // Trust (M5 blocker #0): a synthetic single-obligation undecided result
    // (`Unknown`, or a clock's `Timeout`) never reaches the kernel here
    // (`certify_all` only attempts `Proved` results), so no deadline is needed —
    // pass `None` (unbounded, byte-identical to before).
    let cleancic = certify_all(&results, None);
    let proof_authorities = build_result_proof_authorities(&results, &[], None, &cleancic);
    let proof_results = build_proof_results(tcx.sess, &results, &[], &[], &proof_authorities, None);
    let telemetry = build_proof_telemetry(tcx.sess, &results, &[], &proof_authorities);
    let transport_results = build_transport_results(tcx.sess, &results, None, Some(&cleancic));

    // Trust (T3 L4, C07r): a synthetic artifact generated nothing, so its one row is the
    // only row of a context of its own.
    let mut rows = trust_types::vc_context::VcContext::new();
    let results = RowResults::intern(&mut rows, results);

    VerificationArtifacts {
        proof_results,
        telemetry,
        results,
        transport_results,
        full_verification: None,
        expanded_function_identity: None,
        result_bindings: Vec::new(),
        proof_authorities,
        overflow_check_origins: OverflowCheckOrigins::default(),
        coroutine_resume_contract: None,
        max_proof_level: None,
        runtime_checked_std_members: Vec::new(),
        calculus_reporting: None,
        ctx: Arc::new(rows),
    }
}

fn unsupported_contract_artifacts(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    def_path: &str,
    reason: String,
) -> VerificationArtifacts {
    single_unknown_row_artifacts(
        tcx,
        body,
        def_path,
        "TrustContractBundle",
        reason.clone(),
        "trust-contract-query",
        reason,
    )
}

/// Trust (M5 blocker #0 — census core repeatability): synthetic artifacts for
/// `-Ztrust-dump=mir-only:<dir>`. The caller has already extracted `func` (and, because
/// `-Ztrust-dump=mir:` was also set, dumped it to disk) but this deliberately never
/// dispatches any obligation to a solver or the clean kernel — that dispatch
/// (unbounded per-VC, see `promote_kernel_certifiable`/`certify_all`) is exactly
/// the work dump-only mode exists to skip so a whole-`core` MIR dump stays fast.
///
/// Fail-closed reporting: the single synthetic obligation is `Unknown` with an
/// explicit "dump-only" reason — the SAME shape `unsupported_contract_artifacts`
/// already uses for a structurally-skipped function — so a dump-only run can
/// never read as `Proved`/passed in the terminal report, the cache, or any
/// downstream gate. `full_verification: None` so no consumer mistakes it for a
/// completed full-verification run.
fn dump_only_artifacts(tcx: TyCtxt<'_>, body: &Body<'_>, def_path: &str) -> VerificationArtifacts {
    // Trust (M5 blocker #0): the synthetic obligation is `Unknown`, so
    // `certify_all` never reaches the kernel (this path exists specifically to
    // AVOID kernel/solver dispatch).
    single_unknown_row_artifacts(
        tcx,
        body,
        def_path,
        "TrustDumpOnly",
        "-Ztrust-dump=mir-only:<dir>: extraction/dump completed, verification dispatch skipped"
            .to_string(),
        "trust-dump-mir-only",
        "-Ztrust-dump=mir-only:<dir>: verification dispatch skipped (nonfatal mode, not a proof)"
            .to_string(),
    )
}

/// Fail-closed artifacts for a configured memory authority that could not
/// admit this function. This is constructed before any solver lane starts, so
/// resource-coordination failure cannot silently become an unreserved solve.
fn memory_admission_artifacts(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    def_path: &str,
    reason: String,
) -> VerificationArtifacts {
    let detail = format!("memory admission failed before solver dispatch: {reason}");
    single_unknown_row_artifacts(
        tcx,
        body,
        def_path,
        VcKind::MEMORY_ADMISSION_UNSUPPORTED_MIR_KIND,
        detail.clone(),
        "trust-memory-coordinator",
        detail,
    )
}

/// Test carrier for the retired derived-total fallback. A structural derive
/// claim without exact native or kernel authority must remain fail-closed in
/// every transport consumer; production no longer constructs this lane.
#[cfg(test)]
fn transport_derived_total_certificate_row() -> TransportObligationResult {
    TransportObligationResult {
        assumes: Vec::new(),
        gap_class: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: "derived-total-certificate".to_string(),
        original_vc_snapshot: None,
        typed_kind: None,
        description: "#[automatically_derived] impl is structurally total (derived-total \
                      certificate), but no native typed obligation inventory exists for its \
                      body (typed-TrustIr lowering failed or was not attempted)"
            .to_string(),
        location: None,
        outcome: Outcome::Unknown,
        solver: "trust-compiler".to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some(
            "fail-closed: the structural totality certificate carries no kernel/native proof \
             authority; recorded as certificate evidence, never as proof credit"
                .to_string(),
        ),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
        monitor: None,
        grade: None,
    }
}

/// Trust (span normalization, authoritative note): rustc `Span` -> `trust_types::SourceSpan`,
/// the RAW LO+HI range. Deliberately does NOT rebase to
/// [`rustc_span::Span::source_callsite`].
///
/// # Why raw, and why that is only half right
///
/// This span is an OBLIGATION IDENTITY KEY before it is a diagnostic, and the identity
/// lane's exact comparisons run ACROSS its copies, so the copies must agree
/// character-for-character:
///
/// * `exact_callsite_span_multiset_matches` (this file) binds R1's oracle call-site
///   inventory (`trust_r1_oracle::source_span` output) to the producer's VC locations
///   (`trust_vcgen` rows off a `trust-mir-extract::convert_span`-stamped
///   `VerifiableFunction`) by exact span MULTISET. It never sees THIS fn's output — what
///   it pins is the lockstep of the other two copies. The fn itself returns `bool`; its
///   callers are what reject (`return None`, fail-closed) on a mismatch.
/// * `collect_synthesized_box_deref_ops` (this file) builds a DROP set from THIS fn's
///   output for the missing-SAFETY documentation lint, matched by exact set membership
///   against `convert_span`-stamped `UnsafeBlock` spans — a cross-copy exact comparison
///   that this fn's output IS part of.
/// * `trust_router::strengthen_whole_program::SealedVcIdentity` keys a sealed VC on
///   `(function, kind, file, line_start, col_start, formula)`, where the location was
///   stamped by whichever identity-lane copy produced the VC.
///
/// `source_callsite()` is NOT a projection — it is a MERGE. It maps every span originating
/// in one macro expansion onto the single point of the invocation. Rebasing this range to
/// it would make two distinct calls inside one macro invocation indistinguishable to a
/// check whose entire purpose is exactness, and would widen the lint drop set so a user's
/// genuine raw deref at the same call site as a compiler-synthesized box deref silently
/// loses its lint. That is anti-conservative, so the raw range stays.
///
/// **BYTE-IDENTICAL COPIES — keep them in lockstep.** `trust-mir-extract/src/convert.rs`
/// (`convert_span`) and `trust_r1_oracle.rs` (`source_span`) are character-for-character the
/// same function; `trust_r1_oracle.rs::span_line_col` is its LO-only projection. Per the
/// comparisons above, normalizing ONE copy and not the others would make R1 fail closed on
/// every macro-generated call site and de-cover the box-deref lint drop.
///
/// # The half that IS wrong — one part fixed here, one part still open
///
/// The same value is also what gets reported to the user and sealed into
/// `SealedVcIdentity.file`. For a macro-generated obligation the LO `BytePos` lies in the
/// macro DEFINITION's `SourceFile`, so:
///
/// * the reported location is not actionable — the user cannot add a `requires` clause or
///   a `// SAFETY:` comment inside `core`'s `macros/mod.rs`; STILL OPEN, see below. And
/// * `bootstrap.toml` sets `remap-debuginfo = true`, and `RealFileName::to_string_lossy`'s
///   `Local` arm falls back to `maybe_remapped` because a decoded foreign `SourceFile`
///   carries no `local` path — so the raw rendering was
///   `/rustc/<sha>/library/core/src/macros/mod.rs`, where `<sha>` is the COMPILER's
///   commit, and the sealed identity moved whenever the compiler was rebuilt at a
///   different commit although the user's program did not change. FIXED at the producers:
///   `trust_types::stable_obligation_file` (behaviourally tested in trust-types) elides
///   the build token to the fixed `<toolchain>` placeholder, in all three copies at once.
/// * The USER's checkout path (WS5.9/WS8.9, F-117): `stable_obligation_file` elides the
///   toolchain token and the registry `CARGO_HOME` prefix, and nothing else — a
///   precedent, not a substitute, because the user's own crate is under neither. So the
///   rendering fed to it is `prefer_remapped_unconditionally()`, the `--remap-path-prefix`
///   projection (the only spelling rustc itself permits in a build artifact), in all three
///   copies at once: with `--remap-path-prefix=<checkout>=/src` a sealed identity, an
///   obligation's `source` and every `request_digest` are the same on any machine, and
///   without a remap the two renderings are one string, so nothing changes. The debug-info
///   lane (`to_source_span`) made the same move for `Module.files`, which every module
///   digest covers; there the producer's own resolver refuses a NON-injective remap
///   (`to_mir.rs::ResolvedFiles`). This lane needs no such refusal: the value is compared,
///   never resolved back to a file, both sides of every exact comparison are stamped by
///   the same rendering in the same session, and the sealed key also carries the
///   def-path-qualified function, which two files cannot share. It does need ONE guard,
///   `trust_types::identity_file_rendering`: `SourceSpan.file` is also read as
///   PROVENANCE (vcgen's trusted-std predicate deletes a std span's `[unsafe:sep:*]`
///   obligations; a `binary:` prefix claims binary provenance), so a remap onto a std or
///   `binary:` shape the local path lacks keeps the LOCAL rendering — a remap may erase a
///   path, never mint provenance.
///
/// Every other user-facing position in this tree is callsite-normalized (see the
/// `source_callsite()` calls in `rustc_lint::for_loops_over_fallibles`,
/// `rustc_borrowck::diagnostics::mutability_errors`, `rustc_expand::base`, and
/// `rustc_const_eval::const_eval::error`), as is the trust-ir debug-info lane
/// (`trust-thir-lower/src/lib.rs::to_source_span`, which carries the long-form analysis).
///
/// The actionability fix is therefore ADDITIVE — carry a callsite ANCHOR beside the raw
/// range (a new field computed from `span.source_callsite()` under a new binding; the
/// parity pin deliberately permits exactly that shape) — never a swap, which trades a
/// reporting defect for an identity defect. It is not attempted here because it is a
/// `trust_types::SourceSpan` schema change reaching every construction site, its
/// `PartialEq`, its serde wire form, and R1's sealed identity.
///
/// The current divergence (six converters across five files) is pinned by
/// `crates/trust-types/tests/span_normalization_parity.rs` so it cannot widen unnoticed.
/// THE SESSION'S AUTHENTICATED TRUSTED-STD SOURCE-FILE TABLE, memoized.
///
/// `trust_mir_extract::trusted_std_source_files` pairs every `SourceFile` in the
/// source map with `is_real_sysroot_crate(tcx, file.cnum)` — ARTIFACT RESIDENCY.
/// Both consumers of the trusted-std question read the table this returns:
/// `synthetic_unmodeled_unsafe_call_vcs` below, and (through
/// `VcgenContext::with_trusted_std_source_files`) `trust_vcgen`'s own
/// `is_trusted_std_span`. One table, one `trust_vcgen::span_is_trusted_std`, so
/// the two sides cannot disagree about a span.
///
/// # Why it is memoized on `files().len()` and not built once
///
/// The source map GROWS during a compilation: a sysroot `SourceFile` is decoded
/// the first time a span needs it. A table built once at the first body would go
/// stale, and a stale table is fail-closed — a span whose file is missing is NOT
/// trusted std, so its obligations are kept and the compiler's finding is
/// minted. Correct, but it would silently re-charge the standard library's own
/// macro internals once the map moved on. `files().len()` is monotone
/// (`MonotonicVec`), so a change in it is exactly "a file was added", and the
/// rebuild is one pass plus one memoized `used_crate_source` query per crate.
///
/// Thread-local, because a rustc session may verify bodies on several threads
/// and each computes the same value from the same `TyCtxt`.
fn trusted_std_source_files(tcx: TyCtxt<'_>) -> trust_types::TrustedStdSourceFiles {
    thread_local! {
        static CACHE: std::cell::RefCell<Option<(usize, trust_types::TrustedStdSourceFiles)>> =
            const { std::cell::RefCell::new(None) };
    }
    let seen = tcx.sess.source_map().files().len();
    CACHE.with(|cache| {
        let mut cache = cache.borrow_mut();
        if let Some((cached_len, table)) = cache.as_ref()
            && *cached_len == seen
        {
            return table.clone();
        }
        let table = trust_mir_extract::trusted_std_source_files(tcx);
        *cache = Some((seen, table.clone()));
        table
    })
}

fn source_span_from_rustc_span(tcx: TyCtxt<'_>, span: rustc_span::Span) -> SourceSpan {
    if span.is_dummy() {
        return SourceSpan::default();
    }

    let source_map = tcx.sess.source_map();
    let lo = source_map.lookup_char_pos(span.lo());
    let hi = source_map.lookup_char_pos(span.hi());

    SourceSpan {
        file: trust_types::stable_obligation_file(trust_types::identity_file_rendering(
            lo.file.name.prefer_local_unconditionally().to_string(),
            lo.file.name.prefer_remapped_unconditionally().to_string(),
        )),
        line_start: lo.line as u32,
        col_start: lo.col.0 as u32,
        line_end: hi.line as u32,
        col_end: hi.col.0 as u32,
    }
}

/// Trust: the MODULAR-arithmetic certificate for this body — the `(span, op)` of
/// every assignment `LowerIntrinsics` produced from
/// `intrinsics::wrapping_{add,sub,mul}` (`mir::Statement::trust_modular_arith`).
///
/// This is the ONLY place the flag is read, and reading it here is the whole
/// point of its existence: the flag rides the MIR statement precisely so that
/// this pass — which runs on the fully optimized body, long after the lowering
/// that destroyed the wrapping identity — can still recover it. Nothing
/// downstream of extraction can: measured with the shipped stage2 `trustc`,
/// `a + b` under `-Coverflow-checks=off` and `intrinsics::wrapping_add(a, b)`
/// extract to the byte-identical `BinaryOp("Add", Copy(_1), Copy(_2))`.
///
/// The span is stamped with `source_span_from_rustc_span`, the SAME renderer the
/// extractor's `convert_span` uses (the two are documented byte-identical), so
/// the keys join exactly against the statement spans vcgen puts on its
/// obligations. A rendering that ever diverged would simply stop matching —
/// fail-closed: every obligation stays.
///
/// Only `Add`/`Sub`/`Mul` are ever emitted, because those are the only ops
/// `LowerIntrinsics` flags.
fn trust_modular_arith_ops<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> trust_types::fx::FxHashSet<(SourceSpan, BinOp)> {
    let mut ops = trust_types::fx::FxHashSet::default();
    for block in body.basic_blocks.iter() {
        for statement in &block.statements {
            if !statement.trust_modular_arith {
                continue;
            }
            // The flag was set on an `Assign` of a `BinaryOp`; if some later pass
            // rewrote the statement into another shape, the certificate no
            // longer describes it. Drop it (fail-closed).
            let StatementKind::Assign(assign) = &statement.kind else {
                continue;
            };
            let Rvalue::BinaryOp(bin_op, _) = &assign.1 else {
                continue;
            };
            let op = match bin_op {
                MirBinOp::Add => BinOp::Add,
                MirBinOp::Sub => BinOp::Sub,
                MirBinOp::Mul => BinOp::Mul,
                // Same reasoning: only the three modular ops are ever flagged,
                // so anything else here means the statement changed under us.
                _ => continue,
            };
            ops.insert((source_span_from_rustc_span(tcx, statement.source_info.span), op));
        }
    }
    ops
}

/// Trust (G1, 2026-10-27): the MIR blocks of `body` whose `Call` is
/// `core::mem::zeroed::<T>()` (the `mem_zeroed` diagnostic item, by `DefId`) with a
/// fully monomorphic `T` that rustc's EXACT validity check admits all-zero
/// (`rustc_const_eval::util::check_validity_requirement_exact` with
/// `ValidityRequirement::Zero`: an all-zero allocation of `T`'s real layout, validated
/// by the interpreter — scalar valid ranges, enum tags, reference / `fn` / `NonNull` /
/// `NonZero` / pattern-type niches, through every field, array element and variant).
/// vcgen's mint covers such a call; every other `zeroed` keeps its structural verdict.
///
/// BlockId alignment: `BlockId` is `bb.as_usize()` on the extractor's side, as for
/// `synthetic_unmodeled_unsafe_call_vcs`.
///
/// FAIL-CLOSED: a `T` with a type or const parameter, a layout error, an `Err`, or a
/// size over 64 KiB (the check allocates an interpreter copy of `T`) is left out.
///
/// UNIONS ARE LEFT OUT (G1 review, 2026-10-27). rustc's check accepts any bytes for a
/// union, so a union, or a type holding one inline, passes it whatever its fields are:
/// `union U { r: &'static u8, x: usize }` zeroed is "valid", and a later `u.r` reads a
/// null reference. Whether that read is sound is the union-read question, not this
/// one, and the read is today refused only because trust-ir has no union
/// representation. So this admission does not lean on that: a `T` with a union
/// anywhere inline ([`zeroed_type_is_union_free`]) keeps its structural verdict.
fn zero_valid_zeroed_call_blocks<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> FxHashSet<trust_types::BlockId> {
    const MAX_CHECKED_BYTES: u64 = 64 * 1024;
    let mut out = FxHashSet::default();
    let typing_env = body.typing_env(tcx);
    for (bb_index, bb) in body.basic_blocks.iter_enumerated() {
        let Some(term) = &bb.terminator else { continue };
        let TerminatorKind::Call { func, .. } = &term.kind else { continue };
        let ty::FnDef(did, args) = *func.ty(&body.local_decls, tcx).kind() else { continue };
        if !tcx.is_diagnostic_item(sym::mem_zeroed, did) {
            continue;
        }
        // FnDef arguments are bound here; a `T` that mentions a bound variable is left
        // out (fail-closed).
        let Some(args) = args.no_bound_vars() else { continue };
        let Some(zeroed_ty) = args.types().next() else { continue };
        // Layout ignores lifetimes; erase them so the query key carries none.
        let zeroed_ty = tcx.erase_and_anonymize_regions(zeroed_ty);
        if zeroed_ty.has_param() || zeroed_ty.has_aliases() {
            continue;
        }
        if !zeroed_type_is_union_free(tcx, zeroed_ty, 0) {
            continue;
        }
        let input = typing_env.as_query_input(zeroed_ty);
        let Ok(layout) = tcx.layout_of(input) else { continue };
        if layout.size.bytes() > MAX_CHECKED_BYTES {
            continue;
        }
        if matches!(
            rustc_const_eval::util::check_validity_requirement_exact(
                tcx,
                rustc_middle::ty::layout::ValidityRequirement::Zero,
                input,
            ),
            Ok(true)
        ) {
            out.insert(trust_types::BlockId(bb_index.as_usize()));
        }
    }
    out
}

/// Trust (REVIEW-A4C4-MINORS-1 fix-forward, 2026-11-07): rustc's computed layout of the
/// pointee of each FOREIGN call's raw-pointer destination in `body` whose pointee is a
/// `struct`, keyed by the call's block: size, ABI alignment, and each member's offset in
/// declaration order (the order the extractor lists `Ty::Adt` members in). vcgen's
/// `ffi_pointer_contract` requires it for a struct-pointee return contract (`getpwuid`'s
/// `struct passwd`): the member list the extractor shows cannot reveal a `repr`, and a
/// `#[repr(C, align(16))]` declaration of the same ten members is 80 bytes, not the C
/// object's 72. The verifying extractor never fills `Ty::Adt::layout` (only faithful
/// extraction does, and its `Some` is semantic-hash-visible), so this side channel, which
/// no serialized model or proof digest carries, is how the layout reaches the row.
///
/// BlockId alignment: `BlockId` is `bb.as_usize()` on the extractor's side, as for
/// `zero_valid_zeroed_call_blocks`.
///
/// FAIL-CLOSED: a callee that is not a foreign item, a destination that is not a raw
/// pointer to a struct, a pointee with a type parameter or alias, a layout error, or a
/// layout with fewer field entries than the struct has members is left out, and vcgen
/// then lends no struct-pointee contract for the call.
fn foreign_return_pointee_layouts<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> FxHashMap<trust_types::BlockId, trust_types::AdtLayoutInfo> {
    let mut out = FxHashMap::default();
    let typing_env = body.typing_env(tcx);
    for (bb_index, bb) in body.basic_blocks.iter_enumerated() {
        let Some(term) = &bb.terminator else { continue };
        let TerminatorKind::Call { func, destination, .. } = &term.kind else { continue };
        let ty::FnDef(did, _) = *func.ty(&body.local_decls, tcx).kind() else { continue };
        if !tcx.is_foreign_item(did) {
            continue;
        }
        let ty::RawPtr(pointee, _) = *destination.ty(&body.local_decls, tcx).ty.kind() else {
            continue;
        };
        let pointee = tcx.erase_and_anonymize_regions(pointee);
        if pointee.has_param() || pointee.has_aliases() {
            continue;
        }
        let ty::Adt(adt_def, _) = *pointee.kind() else { continue };
        if !adt_def.is_struct() {
            continue;
        }
        let Ok(layout) = tcx.layout_of(typing_env.as_query_input(pointee)) else { continue };
        let members = adt_def.non_enum_variant().fields.len();
        // `FieldsShape::offset` panics out of range: bounds-check, never abort.
        if layout.fields.count() < members {
            continue;
        }
        let repr = adt_def.repr();
        let repr = if repr.transparent() {
            "transparent".to_string()
        } else if let Some(pack) = repr.pack {
            format!("packed:{}", pack.bytes())
        } else if repr.c() {
            "c".to_string()
        } else {
            "rust".to_string()
        };
        out.insert(
            trust_types::BlockId(bb_index.as_usize()),
            trust_types::AdtLayoutInfo {
                size: layout.size.bytes(),
                align: layout.align.bytes(),
                field_offsets: (0..members).map(|i| layout.fields.offset(i).bytes()).collect(),
                repr,
            },
        );
    }
    out
}

/// Trust (G1 review, 2026-10-27): does `ty` hold NO union inline — through every
/// struct field, enum variant field, tuple element, array element and pattern base?
/// A pointer, reference or fn pointer ends the walk (its pointee is not part of the
/// zeroed bytes). Every other kind (a closure, a coroutine, `dyn`, `str`, a foreign
/// type, an alias, a parameter) and a nesting deeper than 64 answer `false`:
/// fail-closed, the zeroed call keeps its structural verdict.
fn zeroed_type_is_union_free<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>, depth: u32) -> bool {
    if depth > 64 {
        return false;
    }
    match *ty.kind() {
        ty::Bool | ty::Char | ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Never => true,
        ty::Ref(..) | ty::RawPtr(..) | ty::FnPtr(..) | ty::FnDef(..) => true,
        ty::Array(elem, _) | ty::Slice(elem) => zeroed_type_is_union_free(tcx, elem, depth + 1),
        ty::Pat(base, _) => zeroed_type_is_union_free(tcx, base, depth + 1),
        ty::Tuple(elems) => {
            elems.iter().all(|elem| zeroed_type_is_union_free(tcx, elem, depth + 1))
        }
        ty::Adt(def, args) => {
            !def.is_union()
                && def.variants().iter().all(|variant| {
                    variant.fields.iter().all(|field| {
                        zeroed_type_is_union_free(
                            tcx,
                            field.ty(tcx, args).skip_normalization(),
                            depth + 1,
                        )
                    })
                })
        }
        _ => false,
    }
}

/// Trust COMPLETENESS (authoritative): emit a fail-closed obligation for every
/// call to a function rustc deems UNSAFE (`fn_sig().safety()`) that Trust does
/// NOT already cover (`trust_vcgen::call_has_unsafe_model_keyed`, decided on the
/// callee's structured `CalleeKey` since 2026-09-20 — see that function for why
/// deciding it on `safe_def_path_str` let a USER PATH withhold this obligation)
/// and that is not an FFI item (those get the dedicated FFI-boundary obligation). Driven by rustc's
/// authoritative safety rather than a name list, this closes the residual hole
/// where an unsafe `fn` with an unrecognized name (e.g. a project's own
/// `unsafe fn`) would otherwise generate no obligation and silently pass — the
/// kind of "other" that "prove no others exist" must rule out. The obligation is
/// always-SAT (caught): Trust has no model of the call's effects, so it is
/// fail-closed until specifically modeled.
fn synthetic_unmodeled_unsafe_call_vcs<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    def_path: &str,
) -> Vec<(trust_types::BlockId, VerificationCondition)> {
    let dbg = env_flag_enabled("TRUST_UNSAFE_CALL_DEBUG");
    let mut vcs = Vec::new();
    for (bb_index, bb) in body.basic_blocks.iter_enumerated() {
        // THE BLOCK THIS ROW IS MINTED FOR, carried out with it. `BlockId` is
        // `bb.as_usize()` on the extractor's side (`trust-mir-extract`'s
        // `convert.rs`), so the two name the same MIR basic block, and a call
        // TERMINATES its block, so at most one of these rows exists per id. The
        // mint consumes the set as evidence that the row exists; see
        // `trust_vcgen::VcgenContext::with_compiler_unmodeled_call_blocks`.
        let block_id = trust_types::BlockId(bb_index.as_usize());
        let Some(term) = &bb.terminator else { continue };
        let (callee, call_span) = match &term.kind {
            TerminatorKind::Call { func, fn_span, .. } => (func, *fn_span),
            TerminatorKind::TailCall { func, fn_span, .. } => (func, *fn_span),
            _ => continue,
        };
        let callee_kind = callee.ty(&body.local_decls, tcx);
        let ty::FnDef(did, args) = *callee_kind.kind() else {
            if dbg {
                eprintln!("TRUST_UNSAFE_CALL_DEBUG: {def_path}: non-FnDef call {callee_kind:?}");
            }
            continue;
        };
        // Mirror rustc's call-unsafety rule EXACTLY (check_unsafety.rs):
        //   unsafe iff (sig is unsafe AND NOT a safe-to-call target_feature fn)
        //           OR the callee needs target features the caller lacks.
        // The `safe_target_features` gate is essential: a target_feature_11 fn has
        // an unsafe SIGNATURE but is safe to call from a same-feature context — so
        // gating purely on the signature would FALSELY flag such in-context calls.
        let cg = tcx.codegen_fn_attrs(did);
        let unsafe_sig = matches!(
            tcx.fn_sig(did).instantiate(tcx, args.skip_binder()).skip_binder().safety(),
            rustc_hir::Safety::Unsafe
        );
        let unsafe_fn_call = unsafe_sig && !cg.safe_target_features;
        let target_feature_unsafe = !tcx.is_target_feature_call_safe(
            &cg.target_features,
            &tcx.codegen_fn_attrs(body.source.def_id()).target_features,
        );
        let is_unsafe = unsafe_fn_call || target_feature_unsafe;
        let name = trust_mir_extract::safe_def_path_str(tcx, did);
        // THE CALLEE'S IDENTITY, NOT A RENDERING OF IT (2026-09-20). This site
        // has `tcx` and the `DefId` in hand and used to decide with
        // `call_has_unsafe_model(&name)` — a SUBSTRING predicate over
        // `safe_def_path_str`, which for a LOCAL callee is THE USER'S OWN PATH.
        // `is_unsafe_fn_call`'s table is bare leaf names (`set_len`,
        // `get_unchecked`, `assume_init`, `new_unchecked`, …), so a user who
        // named a method `set_len` decided whether their own `unsafe fn` call
        // received this pass's fail-closed obligation. The key is minted from
        // `(TyCtxt, DefId)` alone; `call_has_unsafe_model_keyed` refuses to let
        // any callee outside the compiler's OWN sysroot suppress the row, and
        // consults the legacy text only for a genuine sysroot definition path.
        let key = trust_mir_extract::callee_key_for(tcx, did);
        if dbg {
            eprintln!(
                "TRUST_UNSAFE_CALL_DEBUG: {def_path}: call {name} unsafe={is_unsafe} (sig={unsafe_sig} tf={target_feature_unsafe}) foreign={} modeled={} item={:?} sysroot={}",
                tcx.is_foreign_item(did),
                trust_vcgen::call_has_unsafe_model_keyed(&key, &name),
                key.sysroot_item,
                key.krate_is_real_sysroot,
            );
        }
        if !is_unsafe || tcx.is_foreign_item(did) {
            continue;
        }
        if trust_vcgen::call_has_unsafe_model_keyed(&key, &name) {
            continue;
        }
        // STD-TCB DISCHARGE (gated TRUST_STD_UNSAFE_CALL_SKIP for A/B). When the unsafe
        // CALL EXPRESSION is std-authored source — a std macro (e.g. `thread_local!`)
        // inlined into this body whose `fn_span` resolves to the sysroot `library/` tree
        // — AND the callee is a non-local (sysroot) item, the call is std-internal, so its
        // unsafe contract is std's, not the ny caller's. This mirrors the sep_engine's
        // identical `vec!`-macro RawVec/Box discharge (`is_trusted_std_span`); charging
        // std's own macro-internal unsafe call to ny is inconsistent with hard-skipping
        // std (trust_verify.rs:21040). NOT a Bool(true)→Proved flip — we DECLINE to emit a
        // false-positive finding for provably-std-authored unsafe. Fail-closed on BOTH
        // conditions: a user's `unsafe { std::ptr::read(p) }` has a `fn_span` in the USER
        // file (macro hygiene → std-def-site spans only for std-written tokens), so the
        // span gate does not fire; and the span gate itself is now AUTHENTICATED.
        //
        // THE LAST CLAUSE USED TO READ "a hand-forged span cannot pass rustc
        // provenance", AND IT WAS FALSE (closed 2026-09-20). Nothing was forging a
        // rustc `Span`; `trust_vcgen::span_is_trusted_std` was matching the RENDERED
        // path — `SourceSpan::file`, the unremapped local path the user compiled —
        // against `library/<std-crate>/src/` and `<std-crate>/src/` prefixes, so a user
        // who put their file in a directory named `core/src/` satisfied it with a
        // perfectly genuine span. It now takes the authenticated
        // `trusted_std_source_files` table (artifact residency, keyed on
        // `SourceFile::cnum`), which is the SAME table the mint's
        // `is_trusted_std_span` reads.
        if env_flag_enabled("TRUST_STD_UNSAFE_CALL_SKIP")
            && !did.is_local()
            && trust_vcgen::span_is_trusted_std(
                &source_span_from_rustc_span(tcx, call_span),
                &trusted_std_source_files(tcx),
            )
        {
            continue;
        }
        let why = if target_feature_unsafe && !unsafe_sig { "target-feature" } else { "unsafe fn" };
        vcs.push((
            block_id,
            VerificationCondition {
                kind: VcKind::Assertion {
                    message: format!(
                        "[unsafe:unmodeled-call] call to `{name}` ({why}) is not covered by \
                     Trust's model (fail-closed — no unsafe operation may silently pass)"
                    ),
                },
                function: trust_types::Symbol::intern(def_path),
                location: source_span_from_rustc_span(tcx, call_span),
                // Always SAT = always a finding: no model of this call's effects.
                formula: trust_types::Formula::Bool(true),
                contract_metadata: None,
                // Not a contract-derived VC: no obligation to back-reference.
                obligation: None,
            },
        ));
    }
    vcs
}

// Trust (D8-P0, 2026-09-23): the `[unsafe:validity-transmute]` creation row and
// the `#[trust::assume_total]` unsafe-body carve-out. See the module doc.
mod validity_transmute;

// Trust (r15, 2026-10-01): the one enumeration of a body's edges into code this
// compilation does not verify. See the module doc.
mod unverified_edges;

// Trust (r20, 2026-10-07): the trait-impl surface of a local type, walked by
// `ty_reaches_foreign_user_code`. See the module doc.
mod local_impl_surface;

// Trust (O2-inline, 2026-09-24): the rows an inlined `unsafe fn` call and a
// GVN-folded raw reborrow lose at `-O`. See the module doc.
mod inlined_unsafe_evidence;

// Trust (2026-09-29): a foreign (std or dependency) panic path the explicit MIR
// inliner copied into a body is never a runtime check the user wrote. See the
// module doc.
mod inlined_sysroot_panic;

// Trust (2026-09-29): a local `unsafe impl` of a foreign unsafe trait is an
// unverified safety promise. See the module doc.
mod unsafe_impl_promise;

// Trust (2026-09-30): a local definition of a symbol a linked crate imports is an
// unverified replacement of that crate's callee. See the module doc.
mod symbol_interposition;

// Trust (2026-10-01): a `global_asm!` item or a `#[link_section]` item is code or
// data the linker or the loader acts on without a Rust call, verified by no lane.
// See the module doc.
mod link_level_code;

// Trust (2026-10-02): a verifying build for a target whose pointers are narrower
// than 64 bits is refused: the default policy's allocation premises are 64-bit.
// See the module doc.
mod narrow_target;

/// Trust COMPLETENESS (authoritative): fail-closed obligations for the non-call
/// unsafe constructs Trust does not otherwise model — UNION field access and
/// MUTABLE / EXTERN STATIC access — found by a MIR `Visitor` over the whole body
/// (sound — it sees every place and const operand). Mirrors rustc's
/// `AccessToUnionField` / `UseOfMutableStatic` / `UseOfExternStatic` unsafety
/// checks. Each obligation is always-SAT (caught): reading a union field may
/// observe an invalid bit-pattern, and a mutable/extern static may be racily
/// mutated — neither is modeled, so both fail closed.
///
/// Trust (SAFETY-ASSUME-1): a hit at an operation `declared` declares (it sits in a
/// user `unsafe { }` block with a clippy-placed `// SAFETY:` comment) mints no row;
/// `declared` records it, and its block is charged an `assumption:safety-comment`
/// row instead.
fn synthetic_nonmodeled_unsafe_op_vcs<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    def_path: &str,
    declared: &mut safety_comment_assumption::SafetyDeclaration,
) -> Vec<VerificationCondition> {
    struct Scan<'a, 'tcx> {
        tcx: TyCtxt<'tcx>,
        body: &'a Body<'tcx>,
        hits: Vec<(rustc_middle::mir::Location, rustc_span::Span, &'static str)>,
    }
    impl<'tcx> rustc_middle::mir::visit::Visitor<'tcx> for Scan<'_, 'tcx> {
        fn visit_place(
            &mut self,
            place: &rustc_middle::mir::Place<'tcx>,
            context: rustc_middle::mir::visit::PlaceContext,
            location: rustc_middle::mir::Location,
        ) {
            use rustc_middle::mir::visit::{MutatingUseContext, PlaceContext};
            // A union-field obligation guards against *reading* an invalid bit-pattern
            // ("cannot prove the read observes a valid value"). A pure *write* into a
            // union field establishes a value; it observes nothing, so it carries no
            // such obligation. This is exactly the `vec!` lowering: `write_box_via_move`
            // becomes a Store of `[elems]` through the `MaybeUninit` union field
            // (`(((*p).1: ManuallyDrop<_>).0 …).0 = [elems]`) — a write, not a read.
            // Treat the union field as OBSERVED iff (a) the enclosing place is read by
            // its context, OR (b) a `Deref` follows the union field in the projection
            // chain (the union holds a pointer that is then dereferenced — a genuine
            // read of the union's bytes). Borrows/Drops are NOT pure writes and stay
            // flagged (conservative). The layout-constrained-field branch below is
            // unaffected: writing such a field is itself the dangerous operation.
            let pure_write = matches!(
                context,
                PlaceContext::MutatingUse(
                    MutatingUseContext::Store
                        | MutatingUseContext::Call
                        | MutatingUseContext::SetDiscriminant
                        | MutatingUseContext::Yield
                        | MutatingUseContext::AsmOutput
                )
            );
            let mut base =
                rustc_middle::mir::PlaceTy::from_ty(self.body.local_decls[place.local].ty);
            for (idx, elem) in place.projection.into_iter().enumerate() {
                if matches!(elem, rustc_middle::mir::ProjectionElem::Field(..))
                    && let ty::Adt(def, adt_args) = base.ty.kind()
                {
                    if def.is_union() {
                        let deref_after_union = place
                            .projection
                            .into_iter()
                            .skip(idx + 1)
                            .any(|e| matches!(e, rustc_middle::mir::ProjectionElem::Deref));
                        let observed = !pure_write || deref_after_union;
                        if observed {
                            self.hits.push((
                                location,
                                self.body.source_info(location).span,
                                "[unsafe:union-field] union field access is not modeled — cannot prove \
                                 the read observes a valid value (fail-closed)",
                            ));
                        }
                    } else if def.all_fields().any(|f| {
                        // Trust: 1.99 — the `rustc_layout_scalar_valid_range_*`
                        // attributes (and the `layout_scalar_valid_range` query) are
                        // gone; `NonZero`/`NonNull`-likes now express the invariant as
                        // a pattern-typed field (`pattern_type!(.. is ..)`, TyKind::Pat).
                        // An ADT with any pattern-typed field is the 1.99 equivalent of
                        // a layout-constrained ADT — a conservative superset, in the
                        // fail-closed direction.
                        matches!(f.ty(self.tcx, *adt_args).skip_normalization().kind(), ty::Pat(..))
                    }) {
                        // A field of a scalar-valid-range type (`NonZero`/`NonNull`-
                        // like). Accessing it can break the type's validity invariant
                        // (rustc's `Borrow`/`MutationOfLayoutConstrainedField`). These
                        // types have PRIVATE fields, so this never fires on ordinary
                        // user code; it completes the catch set to match rustc's full
                        // `UnsafeOpKind`.
                        self.hits.push((
                            location,
                            self.body.source_info(location).span,
                            "[unsafe:layout-constrained-field] access to a scalar-valid-range \
                             type's field is not modeled — cannot prove the validity invariant \
                             is preserved (fail-closed)",
                        ));
                    }
                }
                base = base.projection_ty(self.tcx, elem);
            }
        }

        fn visit_const_operand(
            &mut self,
            constant: &rustc_middle::mir::ConstOperand<'tcx>,
            location: rustc_middle::mir::Location,
        ) {
            // A reference to a MUTABLE or EXTERN static is unsafe (it may be racily
            // mutated / its initialization is opaque). An immutable in-crate static
            // is safe and is skipped.
            if let Some(did) = constant.check_static_ptr(self.tcx)
                && (self.tcx.is_mutable_static(did) || self.tcx.is_foreign_item(did))
            {
                self.hits.push((
                    location,
                    self.body.source_info(location).span,
                    "[unsafe:mutable-static] access to a mutable/extern static is not modeled — \
                     cannot prove the absence of a data race (fail-closed)",
                ));
            }
        }
    }
    let mut scan = Scan { tcx, body, hits: Vec::new() };
    rustc_middle::mir::visit::Visitor::visit_body(&mut scan, body);
    scan.hits
        .into_iter()
        .filter(|(location, _, _)| !declared.withhold_location(*location))
        .map(|(_, span, message)| VerificationCondition {
            kind: VcKind::Assertion { message: message.to_string() },
            function: trust_types::Symbol::intern(def_path),
            location: source_span_from_rustc_span(tcx, span),
            formula: trust_types::Formula::Bool(true),
            contract_metadata: None,
            // Not a contract-derived VC: no obligation to back-reference.
            obligation: None,
        })
        .collect()
}

// Trust (spawn census, design 2026-09-29-spawn-census-by-construction §5.5-§5.6): every
// body that can reach a std thread-creation entry point is refused with an
// `UnmodeledThreadSpawnEffect` row, an always-SAT gap marker no unrelated proof can
// discharge. The rows are LOOKED UP (`trust_spawn_sites`), never re-derived from this
// optimized body: the census computed them once per crate on trust-ir's reachability
// engine from pre-steal facts (`trust_mir_extract::concurrency_effects`), so they are
// identical at every MIR opt level. Only a SPAWNS row claims a spawn (S1-S3: a call of
// a seed, a call that exactly runs a spawning body, a drop whose glue reaches one);
// ESCAPES, INDIRECT and UNKNOWN rows refuse without claiming one. An empty census is
// not evidence of concurrency safety.
//
// Self-audit check 2 (design §5.6) lives here, because this is where the codegen body
// is: see [`trust_spawn_census_uncovered`].
fn unmodeled_thread_spawn_effect_vcs<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    def_path: &str,
) -> Vec<VerificationCondition> {
    use rustc_middle::mir::trust_proof::TrustSpawnVerdict;
    use trust_mir_extract::concurrency_effects as effects;
    let Some(local) = body.source.def_id().as_local() else { return Vec::new() };
    if body.source.promoted.is_some() {
        // A promoted constant's facts are its parent's.
        return Vec::new();
    }
    let sites = tcx.trust_spawn_sites(local);
    let mut rows: Vec<(rustc_span::Span, String)> =
        sites.rows.iter().map(|row| (row.span, row.text.clone())).collect();
    if sites.walked {
        rows.extend(trust_spawn_census_uncovered(tcx, body, &sites.covered));
    }
    if rows.is_empty() && sites.verdict != TrustSpawnVerdict::Quiet {
        rows.push((body.span, effects::unsited_verdict_text(sites.verdict)));
    }
    let mut unique: Vec<(rustc_span::Span, String)> = Vec::with_capacity(rows.len());
    for row in rows {
        if !unique.contains(&row) {
            unique.push(row);
        }
    }
    unique
        .into_iter()
        .map(|(span, detail)| VerificationCondition {
            kind: VcKind::UnsupportedMir { kind: "UnmodeledThreadSpawnEffect".to_string(), detail },
            function: trust_types::Symbol::intern(def_path),
            location: source_span_from_rustc_span(tcx, span),
            // An always-SAT gap marker cannot be discharged by unrelated VCs.
            formula: trust_types::Formula::Bool(true),
            contract_metadata: None,
            obligation: None,
        })
        .collect()
}

/// Trust (spawn census, self-audit check 2, design §5.6): what the CODEGEN body runs or
/// makes callable that the census did not cover. The census read each local body before
/// optimization (with the UB checks the pipeline adds first); this walks the body as it
/// will be codegened, every call, drop, unsize, reification and closure cast
/// (`MentionedItems`'s enumeration) and every panic (`Assert`, unwind termination), and
/// asks for each where it came from:
///
/// * from this body (a scope no inlining made): it must be among the items the census
///   covered here (`covered`);
/// * from a LOCAL body the MIR inliner inlined (its scope's innermost inlined instance,
///   an `InstanceKind::Item`): it must be among that body's covered items, instantiated
///   at the inlined instance. Its own node carries its facts, and this body's census
///   edge runs that node;
/// * from another crate's body or a shim: exempt. The census walked that body from
///   metadata and audited it there against its stored `mentioned_items`.
///
/// An uncovered item means a fact may be missing, so the body is refused as UNKNOWN. It
/// refuses this body only: the census was solved before this body was optimized, so its
/// callers are not re-labelled by it (design §10, "P2 as built").
fn trust_spawn_census_uncovered<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    covered: &[rustc_middle::mir::MentionedItem<'tcx>],
) -> Vec<(rustc_span::Span, String)> {
    use rustc_middle::mir::MentionedItem;
    use trust_mir_extract::concurrency_effects as effects;
    let typing_env = body.typing_env(tcx);
    let mut inlined_covered: FxHashMap<ty::Instance<'tcx>, Option<Vec<MentionedItem<'tcx>>>> =
        FxHashMap::default();
    let mut out: Vec<(rustc_span::Span, String)> = Vec::new();
    let mut check = |item: MentionedItem<'tcx>, location: rustc_middle::mir::Location, span| {
        let scope = body.source_info(location).scope;
        let is_covered = match scope.inlined_instance(&body.source_scopes) {
            None => covered.contains(&item),
            Some(instance) => {
                let (ty::InstanceKind::Item(_), Some(callee)) =
                    (instance.def, instance.def_id().as_local())
                else {
                    return;
                };
                let callee_covered = inlined_covered.entry(instance).or_insert_with(|| {
                    let sites = tcx.trust_spawn_sites(callee);
                    sites.walked.then(|| {
                        sites
                            .covered
                            .iter()
                            .filter_map(|item| {
                                instance
                                    .try_instantiate_mir_and_normalize_erasing_regions(
                                        tcx,
                                        typing_env,
                                        ty::EarlyBinder::bind(tcx, *item),
                                    )
                                    .ok()
                            })
                            .collect()
                    })
                });
                match callee_covered {
                    // A Clean-origin callee (R5) has no census body to audit.
                    None => return,
                    Some(list) => list.contains(&item),
                }
            }
        };
        if !is_covered {
            out.push((span, effects::uncovered_mention_text(&item)));
        }
    };
    crate::mentioned_items::for_each_mentioned_item(tcx, body, |item, span, location| {
        check(item, location, span)
    });
    for (block, data) in body.basic_blocks.iter_enumerated() {
        let terminator = data.terminator();
        let location = body.terminator_loc(block);
        let mut panics = Vec::new();
        match &terminator.kind {
            TerminatorKind::Assert { msg, .. } => panics.push(effects::assert_panic_lang_item(msg)),
            TerminatorKind::UnwindTerminate(reason) => panics.push(reason.lang_item()),
            _ => {}
        }
        if let Some(UnwindAction::Terminate(reason)) = terminator.unwind() {
            panics.push(reason.lang_item());
        }
        for item in panics {
            if let Some(mention) = effects::lang_item_mention(tcx, item) {
                check(mention, location, terminator.source_info.span);
            }
        }
    }
    out
}

// Trust #243 (closed-world dyn dispatch): build modular summaries that record
// sealed-trait `dyn Trait` method contract evidence.
//
// A `dyn Trait` method call lowers to an `FnDef(trait_method, _)` callee that
// `Instance::try_resolve` reports as `InstanceKind::Virtual`. Recording a
// proved summary requires behavioral subtyping with a closed world: (1) the
// trait is sealed (no downstream crate can add a violating impl), (2) every
// enumerated impl was verified against the contract, and (3) the method has
// contract evidence to carry. These are exactly the conditions
// `VtableModel::dyn_dispatch_summary` enforces; the functions below supply the
// rustc facts behind them. When any condition fails the call is left out of the
// database, so the conservative behavior is preserved.

thread_local! {
    /// Re-entrancy guard: def_ids whose dyn-dispatch summaries are currently
    /// being computed. Forcing `trust_proof_results` for an impl method
    /// re-enters verification (see `trust_proof_query`); without this guard a
    /// sealed trait whose impl methods themselves dispatch on the trait would
    /// form a query cycle and abort compilation. A guarded skip is treated as
    /// "not verified" — completeness-only, never a false proof.
    static DYN_SUMMARY_IN_PROGRESS: std::cell::RefCell<FxHashSet<DefId>> =
        std::cell::RefCell::new(FxHashSet::default());
}

/// RAII ownership of one [`DYN_SUMMARY_IN_PROGRESS`] entry.
///
/// `enter` returns `None` when an outer frame already owns `def_id`, preserving
/// the fail-closed recursion skip. A successful entry is removed on every scope
/// exit, including unwinding through a caught panic, so one failed summary build
/// cannot suppress unrelated later verification on the same worker thread.
struct DynSummaryInProgressGuard(DefId);

impl DynSummaryInProgressGuard {
    fn enter(def_id: DefId) -> Option<Self> {
        DYN_SUMMARY_IN_PROGRESS
            .with(|in_progress| in_progress.borrow_mut().insert(def_id))
            .then_some(Self(def_id))
    }
}

impl Drop for DynSummaryInProgressGuard {
    fn drop(&mut self) {
        DYN_SUMMARY_IN_PROGRESS.with(|in_progress| {
            in_progress.borrow_mut().remove(&self.0);
        });
    }
}

thread_local! {
    /// Trust: the def_ids whose `optimized_mir` (and therefore the `trust_verify`
    /// pass running inside it) is CURRENTLY on the stack. Populated for the WHOLE
    /// `TrustVerify::run_pass` of an item body — collection AND publication — and,
    /// as before, at the entry of `collect_verification_artifacts_inner_with_policy`
    /// (which a shim body or a cache-miss read reaches outside that window); removed
    /// on exit. This is the authoritative "would a callee peek cycle?" oracle:
    /// `optimized_mir(callee)` re-enters an in-progress `optimized_mir(ancestor)` — an
    /// E0391 abort — exactly when `callee` IS such an ancestor or transitively REACHES
    /// one. The set identifies the live query ancestors; the cycle oracle combines it with
    /// a traversal over immutable elaborated-MIR snapshots, so the result is independent of
    /// whether an ancestor's working MIR has already been consumed by `optimized_mir`.
    ///
    /// Trust (2026-09-25): the set used to be populated for COLLECTION only, so a body
    /// left it while its verdict was still being PUBLISHED — inside the same
    /// `optimized_mir` — and the publication step forces other bodies' verdicts (the
    /// formatting-sink bar asks `trust_proof_results` of every user formatter a
    /// `format_args!` packs). Two `Debug` impls that format each other re-entered the
    /// first one's `optimized_mir` from the second one's publication, and one impl that
    /// formats its own type re-entered it from its own error-transparency note: E0391 on
    /// valid Rust. See `TrustVerify::run_pass` and
    /// `tests/ui/trust/fmt_recursive_debug_no_query_cycle.rs`.
    static OPTIMIZED_MIR_VERIFY_IN_PROGRESS: std::cell::RefCell<FxHashSet<DefId>> =
        std::cell::RefCell::new(FxHashSet::default());
}

/// RAII: remove `def_id` from [`OPTIMIZED_MIR_VERIFY_IN_PROGRESS`] on scope exit iff
/// this frame is the one that inserted it (`Some`). Panic-safe and re-entrancy-safe.
struct OptimizedMirInProgressGuard(Option<DefId>);
impl OptimizedMirInProgressGuard {
    /// Mark `def_id` in progress. Only the frame that actually inserted it removes it,
    /// so a nested frame for the same def (the pass's own collection, a re-entrant
    /// read) never clears an outer frame's mark early.
    fn enter(def_id: DefId) -> Self {
        Self(
            OPTIMIZED_MIR_VERIFY_IN_PROGRESS
                .with(|s| s.borrow_mut().insert(def_id))
                .then_some(def_id),
        )
    }
}
impl Drop for OptimizedMirInProgressGuard {
    fn drop(&mut self) {
        if let Some(def_id) = self.0 {
            OPTIMIZED_MIR_VERIFY_IN_PROGRESS.with(|s| {
                s.borrow_mut().remove(&def_id);
            });
        }
    }
}

/// Trust (cache-key soundness): whether the crate being compiled is a
/// *whole-program* (closed-world) artifact — every crate type is an
/// `Executable`, `StaticLib`, or `Cdylib`, none of which a downstream Rust crate
/// can link against and extend. Returns `false` for an empty crate-type list
/// (unknown shape — fail open / treat as extensible) or for any `rlib` / `dylib`
/// / proc-macro presence (a downstream crate can add impls).
///
/// This is the single source of truth for the whole-program bit: it gates
/// dyn-dispatch trait sealedness (`dyn_trait_sealedness`) AND is folded into the
/// verification-semantics cache key (`verification_semantics_key`) so a verdict
/// proved under a whole-program assumption can never be served into a
/// downstream-extensible (`rlib`) compilation by any cache that keys on it.
fn crate_types_are_whole_program(tcx: TyCtxt<'_>) -> bool {
    let crate_types = tcx.crate_types();
    !crate_types.is_empty()
        && crate_types.iter().all(|ct| {
            matches!(
                ct,
                rustc_structures::CrateType::Executable
                    | rustc_structures::CrateType::StaticLib
                    | rustc_structures::CrateType::Cdylib
            )
        })
}

/// Classify whether a trait's impls are exhaustive (the closed-world premise).
///
/// Conservative by construction: returns `Open` on any uncertainty, since an
/// incorrect `Sealed` is an unsoundness. `Sealed` requires a local trait with
/// no blanket impl, plus at least one independently-sound closed-world route: a
/// final-artifact compilation (no downstream Rust crate can link it), a
/// non-exported trait (downstream can't name it to impl it), or the sealed-trait
/// idiom (a private supertrait whose impl set is closed and concrete, so no
/// downstream type can satisfy it: [`private_supertrait_seals`]). The last two
/// hold only while the crate defines no def-site-hygienic macro
/// ([`crate_defines_def_site_macro`]).
fn dyn_trait_sealedness<'tcx>(
    tcx: TyCtxt<'tcx>,
    trait_def_id: DefId,
) -> trust_vcgen::TraitSealedness {
    use trust_vcgen::TraitSealedness;

    let Some(trait_local) = trait_def_id.as_local() else {
        return TraitSealedness::Open;
    };

    // A blanket impl admits unboundedly many impl types; we don't enumerate
    // per-type bodies, so the impl set is not exhaustive.
    if !tcx.trait_impls_of(trait_def_id).blanket_impls().is_empty() {
        return TraitSealedness::Open;
    }

    if trait_impl_set_is_closed_world(tcx, trait_def_id, trait_local) {
        TraitSealedness::Sealed
    } else {
        TraitSealedness::Open
    }
}

/// The THREE independently-sound closed-world routes for a LOCAL trait: this
/// artifact is final, or the trait is not exported, or it carries a private
/// supertrait downstream cannot satisfy ([`private_supertrait_seals`], which
/// asks more than "the supertrait is private" since 2026-10-04).
///
/// Factored out of [`dyn_trait_sealedness`] (2026-09-20) so rung 1 can use the
/// same disjunction rung 2 does. It deliberately EXCLUDES the blanket-impl
/// refusal, which belongs to the caller: that check is about ENUMERABILITY ("a
/// blanket impl admits unboundedly many impl types; we don't enumerate per-type
/// bodies"), so it is required by rung 2, which enumerates, and irrelevant to
/// rung 1, which does not (`trait_panic_free.rs`: "UNLIKE rung 2 this does NOT
/// enumerate the impls at the call site, and it therefore accepts blanket and
/// generic impls"). Keeping it at the call site is what lets the two rungs share
/// the closure question without sharing a premise neither needs.
///
/// THE DEFECT THIS EXISTS TO CLOSE. `generic_call_relies_on_panic_free_contract`
/// gated on `crate_types_are_whole_program` ALONE while its own doc said that
/// route is "the `dyn_trait_sealedness` U6 route, reused verbatim rather than
/// reinvented". It is not verbatim — it is one disjunct of three, and the other
/// two were dropped in the reuse. Both dropped routes are closed-world by
/// LANGUAGE VISIBILITY (a downstream crate cannot name a non-exported trait to
/// implement it, and cannot satisfy a CLOSED private supertrait), so they hold
/// in an rlib exactly as in an executable.
/// `tests/open-dispatch-ladder/w8_non_exported_dyn_trait_in_an_rlib_is_sealed.rs`
/// already rails the non-exported route GREEN for the `dyn` lane in a library.
///
/// Trust (2026-10-04, DEP-SEAL-1): the third route used to be "some local
/// supertrait is not exported" (`has_private_supertrait`). Privacy stops a
/// downstream crate from NAMING the supertrait, not from SATISFYING it: with
/// `mod private { pub trait Sealed {} impl<X: ?Sized> Sealed for X {} }` every
/// downstream type is `Sealed` already, so `impl a::T for Bad` is legal Rust
/// downstream, and an rlib certified `pub fn f<K: T>(x: &K) -> u32 { x.m() }`
/// under certify (rung 2 and, with Φ, rung 1) while a verify-off binary's
/// `impl a::T for Bad { fn m(&self) -> u32 { panic!() } }` panicked inside it.
/// The route is now [`private_supertrait_seals`], which asks whether ANY
/// downstream impl of the trait can type-check, not whether the supertrait is
/// private. `tests/open-dispatch-ladder/w14_*` rail it.
///
/// Trust (2026-10-05, DEP-SEAL-1 macro-2.0 residual): routes 2 and 3 are
/// LANGUAGE-VISIBILITY arguments — "no other crate can name this trait" — and a
/// def-site-hygienic macro breaks that premise. A `pub macro seal($t:ty) { impl
/// private::Sealed for $t {} }` resolves `private::Sealed` at ITS definition site,
/// with that site's privacy, wherever it is invoked, so a downstream crate writes
/// `a::seal!(Bad); impl a::T for Bad { … }`. `effective_visibilities().is_exported`
/// does not see that reach (rustc records it one level down, as `Reachable`, which
/// a supertrait in a public interface also is). Both routes are dropped whenever
/// [`crate_defines_def_site_macro`] holds; the whole-program route is not a
/// visibility argument and stays.
fn trait_impl_set_is_closed_world(
    tcx: TyCtxt<'_>,
    trait_def_id: DefId,
    trait_local: rustc_span::def_id::LocalDefId,
) -> bool {
    if crate_types_are_whole_program(tcx) {
        return true;
    }
    // Trust (2026-10-05, DEP-SEAL-1 macro-2.0 residual): see the doc above.
    if crate_defines_def_site_macro(tcx) {
        return false;
    }

    let not_exported = !tcx.effective_visibilities(()).is_exported(trait_local);

    // Trust (2026-10-04, DEP-SEAL-1): was `has_private_supertrait` — privacy alone.
    not_exported || private_supertrait_seals(tcx, trait_def_id)
}

/// Trust (2026-10-05, DEP-SEAL-1 macro-2.0 residual, DECISION_QUEUE
/// SEAL-SUPERTRAIT-1): whether this crate defines a macro that can hand another
/// crate a path resolved at THIS crate's definition site — a macros-2.0 `macro`
/// item (`#![feature(decl_macro)]`; opaque hygiene by default), or any macro that
/// sets `#[rustc_macro_transparency]` (`#![feature(rustc_attrs)]`; `"opaque"` gives
/// a `macro_rules!` the same reach). An invocation of such a macro in a downstream
/// crate resolves the macro's own paths in the module that defined it, with that
/// module's privacy, so it can name, and implement, a trait no `use` exports. A
/// `macro_rules!` without the attribute is semi-transparent: its item paths resolve
/// at the call site, and `$crate::private::Sealed` in a downstream expansion is
/// E0603 (measured on the stage 1 of `76a6ea45b2`).
///
/// Crate-wide and coarse on purpose: any such macro, at any visibility, drops the
/// language-visibility routes for every trait of the crate. rustc's own reach walk
/// (`rustc_resolve::effective_visibilities`, `update_reachability_from_macro`)
/// would allow a per-trait answer, but it carries a FIXME on its precision and a
/// miss there would be silent; recovery is that refinement.
fn crate_defines_def_site_macro(tcx: TyCtxt<'_>) -> bool {
    tcx.hir_crate_items(()).free_items().any(|item_id| {
        let rustc_hir::ItemKind::Macro(_, def, _) = tcx.hir_item(item_id).kind else {
            return false;
        };
        !def.macro_rules
            || rustc_attr_ir::find_attr!(tcx, item_id.owner_id, RustcMacroTransparency(..))
    })
}

/// Trust (2026-10-04, DEP-SEAL-1, DECISION_QUEUE SEAL-SUPERTRAIT-1): the
/// sealed-trait idiom, decided by whether a downstream crate can write ANY impl
/// of `trait_def_id` that type-checks — not by whether the supertrait is private.
///
/// A downstream `impl a::T<..> for X` needs `X: S` for every supertrait `S` of
/// `T`, and the orphan rule needs a downstream-local type somewhere in the header.
/// The seal holds when `T` has a supertrait `S` with:
///
/// * (a) `S` local and NOT exported, so no other crate can name it to add an
///   impl (the old `has_private_supertrait` test, kept). That holds only while the
///   crate defines no def-site-hygienic macro, which can name `S` for a downstream
///   crate; the caller, [`trait_impl_set_is_closed_world`], asks
///   [`crate_defines_def_site_macro`] before this route;
/// * (a') `S` an ordinary trait — not a trait alias (an alias is satisfied by
///   whatever satisfies its bounds and has no impls of its own to enumerate), not
///   an auto trait (every type implements it unless opted out, with no impl in
///   `trait_impls_of`), and not a lang item (built-in impls, also unlisted);
/// * (b) no BLANKET impl of `S` — `impl<X> Sealed for X`, bounded or not, makes
///   downstream types `Sealed`;
/// * (c) every other impl of `S` has a self type with no type or const
///   parameter. That refuses `impl<X> Sealed for Box<X>`, `&X`, `&mut X` and
///   `Pin<X>` — fundamental wrappers, so `impl a::T for Box<Local>` passes the
///   orphan rule downstream — and, conservatively, a non-fundamental `Vec<X>`,
///   which the orphan rule would already stop. Lifetime parameters stay allowed:
///   no downstream type hides in a lifetime.
///
/// With (a)–(c) the types that satisfy `S` are a fixed set of types written in
/// this crate, none of which can contain a downstream-local type. `T` must then
/// satisfy
///
/// * (d) no own type or const parameter besides `Self`. Otherwise
///   `impl a::T<Local> for a::Good` is legal downstream: `Good` is already
///   `Sealed`, and `Local` in the trait's arguments satisfies the orphan rule. A
///   const parameter cannot carry a local type, so refusing it is conservative.
///
/// Each check fails closed: a `false` drops only this route, and the trait is
/// then `Open` unless the artifact is final or the trait is not exported.
/// Checked in the order above so `trait_impls_of` is never asked of an alias.
fn private_supertrait_seals(tcx: TyCtxt<'_>, trait_def_id: DefId) -> bool {
    // (d) the sealed trait itself: `Self` is its only type/const parameter.
    let generics = tcx.generics_of(trait_def_id);
    let own_ty_or_const = generics.own_params.iter().filter(|p| p.kind.is_ty_or_const()).count();
    if own_ty_or_const > usize::from(generics.has_self) {
        return false;
    }
    tcx.explicit_super_clauses_of(trait_def_id)
        .iter_identity_copied()
        .map(ty::Unnormalized::skip_norm_wip)
        .filter_map(|(pred, _)| match pred.kind().skip_binder() {
            ty::ClauseKind::Trait(trait_pred) => Some(trait_pred.trait_ref.def_id),
            _ => None,
        })
        .any(|super_def_id| supertrait_impl_set_is_closed_and_concrete(tcx, super_def_id))
}

/// Trust (2026-10-04, DEP-SEAL-1): rules (a)–(c) of [`private_supertrait_seals`]
/// for one supertrait: no downstream type can satisfy `super_def_id`.
fn supertrait_impl_set_is_closed_and_concrete(tcx: TyCtxt<'_>, super_def_id: DefId) -> bool {
    // (a) local and not exported.
    let Some(super_local) = super_def_id.as_local() else {
        return false;
    };
    if tcx.effective_visibilities(()).is_exported(super_local) {
        return false;
    }
    // (a') an ordinary trait whose impl set `trait_impls_of` lists completely.
    if tcx.def_kind(super_def_id) != DefKind::Trait
        || tcx.trait_is_auto(super_def_id)
        || tcx.as_lang_item(super_def_id).is_some()
    {
        return false;
    }
    let impls = tcx.trait_impls_of(super_def_id);
    // (b) no blanket impl.
    if !impls.blanket_impls().is_empty() {
        return false;
    }
    // (c) every impl's self type is concrete up to lifetimes. Unnormalized on
    // purpose: normalizing can only REMOVE a parameter, so this errs closed.
    impls.non_blanket_impls().values().flatten().all(|&impl_def_id| {
        !tcx.type_of(impl_def_id).instantiate_identity().skip_normalization().has_non_region_param()
    })
}

/// Whether every local impl of `trait_def_id` soundly refines the trait
/// contract for `trait_method_def_id`, so a proved dynamic-dispatch summary may
/// be recorded for the trait method.
///
/// Soundness requires, for *every* local impl:
///
///  1. The impl body is fully verified against its own contract
///     (`trust_proof_results(...).is_fully_verified()` plus local nonzero and
///     accounting guards).
///  2. The impl contract *refines* the trait contract (Liskov): the impl
///     postcondition implies the trait postcondition (covariance). Exact
///     compiler-extracted contract identity under an exactly aligned formal
///     parameter environment is a structural proof; every non-identical
///     refinement must discharge its `verify_liskov` VCs through both the
///     router and the Clean certificate lane. Differently named or reordered
///     formal environments fail closed because their free-variable namespaces
///     have not been capture-avoidably canonicalized to positional binders.
///
/// For v1 we additionally require the trait method (and every overriding impl)
/// to carry **no precondition**, so the caller has no precondition obligation
/// to discharge at the dynamic call. A non-overriding impl inherits the trait's
/// default body, which already carries the trait contract verbatim, so it is
/// sound exactly when that default body is itself fully verified.
///
/// All `trust_proof_results` forcing is guarded against re-entrancy so recursive
/// dispatch cannot cycle the query engine. Any impl that is missing, guarded
/// out, unverified, or fails refinement yields `false` — the conservative
/// answer that suppresses the proved dynamic-dispatch summary.
/// Trust (assumption-root gate): `sess`/`def_id` are REQUIRED, not conveniences.
/// Every caller of this predicate is spending ANOTHER body's verdict as a premise
/// (the `dyn` contract summary's per-impl and default-body checks, and rung 2's
/// sealed closed-world dispatch), and a verdict that consumed a user axiom is
/// conditional — with no trace of it in `results` (measured: empty dispositions,
/// `no_obligations`/`proved`). Threading the identity through the ONE predicate
/// they share is what keeps a future caller from inheriting the hole instead of
/// the check, and it is why THIS is the function with the obvious name: a call
/// written from memory lands on the gated wrapper, not on the pure core.
fn has_nonzero_accounted_static_proof(
    sess: &Session,
    def_id: DefId,
    results: &TrustProofResults,
) -> bool {
    nonzero_accounted_static_proof_decision(verdict_rests_on_user_axiom(sess, def_id), results)
}

/// The WHOLE decision the gated wrapper above makes, with only the Session lookup
/// factored out. Both conjuncts are here, so a unit test can pin the gated
/// behaviour — including the contract-assumed bookkeeping seam that must never
/// seed a dynamic-dispatch summary, and the census decline that must veto a row
/// set which would otherwise pass. A `Session` cannot be built in a unit test, so
/// this split is what makes the production decision testable at all; the pure
/// row-only core below is the narrower half and covers only the row accounting.
fn nonzero_accounted_static_proof_decision(
    axiom_decline: Option<&str>,
    results: &TrustProofResults,
) -> bool {
    axiom_decline.is_none() && results_are_nonzero_accounted_static_proof(results)
}

/// The pure core of the gate above: everything decidable from the RESULT ROWS
/// alone. Separate so the row-accounting boundary stays directly unit-testable
/// without a `Session` (same reason `all_calls_target_proven_or_abi_total_in_sets`
/// is split out), and NOT to be called from production — the axiom census is not
/// in `results`, so a row-only answer is only half the question.
fn results_are_nonzero_accounted_static_proof(results: &TrustProofResults) -> bool {
    results.is_fully_verified()
        && results.summary.total > 0
        && results.summary.trusted.saturating_add(results.summary.certified)
            == results.summary.total
        && results.has_aligned_obligation_arrays()
        // `Trusted + None` is the explicit contract-assumed bookkeeping
        // disposition. It preserves modular verification under `requires`
        // but is not an independently discharged proof and must never seed a
        // dynamic-dispatch summary.
        && results
            .dispositions
            .iter()
            .all(|disposition| disposition.strength != TrustProofStrength::None)
}

/// Trust (postcondition composition, slice 2): the assumption-root gate for a
/// callee whose `ensures` will be assumed UNDER ITS OWN `requires`.
///
/// [`has_nonzero_accounted_static_proof`] is the right bar for an
/// UNCONDITIONAL reuse, and slice 1 uses it unchanged. It cannot be the bar for
/// a preconditioned callee, and the reason is not a technicality: its last
/// conjunct rejects every `TrustProofStrength::None` row, and a callee that
/// declares `requires` ALWAYS carries one — the `DefinitionEntryAssumption`
/// bookkeeping row recording that its body was proved ASSUMING its precondition
/// at entry. Applying the unconditional gate to a preconditioned callee is
/// therefore not conservative, it is VACUOUS: it refuses every single callee
/// this lane exists for.
///
/// So this variant tolerates exactly that row, and nothing else. Every other
/// conjunct is verbatim.
///
/// # Why tolerating it is sound HERE and nowhere else
///
/// The entry-assumption row is not an unproved obligation the callee got away
/// with. It is the record of WHICH HYPOTHESIS the callee's other proofs stand
/// on: its own `requires`, at entry. A postcondition proved under that
/// hypothesis establishes `requires -> ensures` — precisely the formula this
/// lane injects at the call site
/// (`generate::rebind_callee_postconditions`). The assumption is not dropped,
/// it is carried into the caller as the antecedent and discharged there or not
/// at all. The other three call sites of the unconditional gate seed a
/// dynamic-dispatch summary, which has no such antecedent to carry — its own
/// `all_trait_impls_verified` refuses a trait method with preconditions
/// outright — so they keep the strict bar and are untouched.
///
/// # The `assume_total` row is the same shape, and is refused by TWO conjuncts
///
/// `Trusted + None` has exactly two producers (`result_proof_disposition`):
/// `DefinitionEntryAssumption` and `AssumedTotalCalleeAssumption`. The second is
/// a user-written axiom and must never be inherited, and a `TrustDisposition`
/// carries kind/status/strength only — it cannot tell the two apart on its own.
/// Both directions of that hazard are closed here rather than one:
///
///  * `verdict_rests_on_user_axiom` is a POSITIVE census — it declines unless
///    the verification that produced this verdict was recorded axiom-free, and
///    an absent record declines too. A spent `#[trust::assume_total]` /
///    `#[trust::skip]` callee is exactly what it records, so a clean census
///    means no `AssumedTotalCalleeAssumption` row exists to tolerate; and
///  * the strengthless rows are COUNTED and bounded by the callee's authored
///    `requires` count, so an unexpected extra assumption row refuses the mint
///    even if the census were ever to miss one.
///
/// Every other `TrustProofStrength::None` disposition in the tree is `Unknown`,
/// `Failed`, `Timeout` or `RuntimeChecked`, all of which `is_fully_verified()`
/// and the `trusted + certified == total` conjunct already exclude before this
/// count is reached.
fn has_nonzero_accounted_static_proof_under_own_requires(
    sess: &Session,
    def_id: DefId,
    results: &TrustProofResults,
    authored_requires: usize,
) -> bool {
    // A precondition-free callee is slice 1 and keeps slice 1's exact bar.
    if authored_requires == 0 {
        return has_nonzero_accounted_static_proof(sess, def_id, results);
    }
    if verdict_rests_on_user_axiom(sess, def_id).is_some() {
        return false;
    }
    if !(results.is_fully_verified()
        && results.summary.total > 0
        && results.summary.trusted.saturating_add(results.summary.certified)
            == results.summary.total
        && results.has_aligned_obligation_arrays())
    {
        return false;
    }
    let strengthless = results
        .dispositions
        .iter()
        .filter(|disposition| disposition.strength == TrustProofStrength::None)
        .count();
    strengthless <= authored_requires
        && results.dispositions.iter().all(|disposition| {
            disposition.strength != TrustProofStrength::None
                || disposition.status == TrustStatus::Trusted
        })
}

fn all_trait_impls_verified<'tcx>(
    tcx: TyCtxt<'tcx>,
    trait_def_id: DefId,
    trait_method_def_id: DefId,
    trait_name: &str,
    method_name: &str,
    trait_pre: &[trust_types::Formula],
    trait_post: &[trust_types::Formula],
) -> bool {
    let probe = dyn_probe_enabled();

    // v1 soundness: only summarize methods with no trait-level precondition, so
    // the dynamic caller carries no precondition obligation at the call site.
    if !trait_pre.is_empty() {
        if probe {
            eprintln!("TRUST_DYN_PROBE: impls_verified=false (trait method has preconditions)");
        }
        return false;
    }
    // No dynamic-dispatch contract evidence to carry.
    if trait_post.is_empty() {
        return false;
    }

    let impls = tcx.local_trait_impls(trait_def_id);
    if impls.is_empty() {
        return false;
    }

    let trait_contract = trust_vcgen::TraitContract {
        trait_name: trait_name.to_string(),
        method: method_name.to_string(),
        parameter_names: source_contract_param_names(tcx, trait_method_def_id),
        preconditions: trait_pre.to_vec(),
        postconditions: trait_post.to_vec(),
    };

    for impl_local in impls {
        let impl_def_id = impl_local.to_def_id();
        let impl_type = trust_mir_extract::safe_def_path_str(tcx, impl_def_id);

        match tcx.impl_item_implementor_ids(impl_def_id).get(&trait_method_def_id) {
            // Overriding impl method: must self-verify and refine the trait contract.
            Some(&impl_method_def_id) => {
                // Never force a def_id whose summaries are already being computed
                // up the stack — the query cycle this guard exists to break.
                let in_progress =
                    DYN_SUMMARY_IN_PROGRESS.with(|s| s.borrow().contains(&impl_method_def_id));
                if in_progress {
                    if probe {
                        eprintln!(
                            "TRUST_DYN_PROBE: impls_verified=false ({impl_type} in progress)"
                        );
                    }
                    return false;
                }

                let self_verified = matches!(
                    tcx.trust_proof_results(ty::InstanceKind::Item(impl_method_def_id)),
                    Some(results)
                        if has_nonzero_accounted_static_proof(
                            tcx.sess,
                            impl_method_def_id,
                            results,
                        ),
                );
                if !self_verified {
                    if probe {
                        eprintln!(
                            "TRUST_DYN_PROBE: impls_verified=false ({impl_type} not self-verified)"
                        );
                    }
                    return false;
                }

                let (impl_pre, impl_post) =
                    trust_mir_extract::extract_contract_formulas_for_def(tcx, impl_method_def_id);

                // v1: an overriding impl must not strengthen the (empty) precondition.
                if !impl_pre.is_empty() {
                    if probe {
                        eprintln!(
                            "TRUST_DYN_PROBE: impls_verified=false ({impl_type} has preconditions)"
                        );
                    }
                    return false;
                }

                let impl_contract = trust_vcgen::ImplContract {
                    impl_type: impl_type.clone(),
                    method: method_name.to_string(),
                    parameter_names: source_contract_param_names(tcx, impl_method_def_id),
                    preconditions: impl_pre,
                    postconditions: impl_post,
                };

                if trait_contract.parameter_names != impl_contract.parameter_names {
                    if probe {
                        eprintln!(
                            "TRUST_DYN_PROBE: impls_verified=false ({impl_type} has unaligned contract binders)"
                        );
                    }
                    return false;
                }

                // Liskov refinement: impl_post => trait_post (covariance). With an
                // empty trait precondition, verify_liskov emits only covariance VCs.
                let liskov_vcs = trust_vcgen::verify_liskov(&trait_contract, &impl_contract);
                if !trust_vcgen::liskov_contracts_have_exact_identity(
                    &trait_contract,
                    &impl_contract,
                ) && !liskov_vcs.is_empty()
                {
                    // Trust (plan P4, T4.2): the plain router, which dedups only
                    // within this batch. No verdict is carried across functions.
                    // Trust (plan P4, T4.1): a fresh router for this impl pair,
                    // its SMT lane the in-process ay; nothing it learns
                    // outlives this call.
                    let results = build_router(tcx.sess).verify_all(&liskov_vcs);
                    if probe {
                        // Diagnostic only: the router's own verdicts, before the
                        // Clean re-check below decides acceptance.
                        let proved = results.iter().filter(|(_, r)| r.is_proved()).count();
                        let refuted = results
                            .iter()
                            .filter(|(_, r)| matches!(r, VerificationResult::Failed { .. }))
                            .count();
                        eprintln!(
                            "TRUST_DYN_PROBE: {impl_type} Liskov router: {} VC(s), {proved} proved, {refuted} refuted",
                            results.len()
                        );
                    }
                    // A public `VerificationResult`/`ProofStrength` is transport
                    // metadata, not an authority capability: either can be
                    // constructed or deserialized with an arbitrary assurance
                    // label. Re-certify each *exact* Liskov VC independently and
                    // accept refinement only when Clean returns a checked term for
                    // that judgment. The router result remains useful as a
                    // scheduling/diagnostic hint, but cannot mint the dynamic-call
                    // summary whose postcondition downstream callers assume.
                    // Today Clean declines the `Not(Implies(..))` shape
                    // `verify_liskov` emits, so this refuses every refinement
                    // that is not an exact identity (docs/DECISION_QUEUE.md,
                    // T4.1-IMPL-2).
                    let refined = results
                        .iter()
                        .all(|(vc, r)| r.is_proved() && trust_certify::certify_vc(vc).is_some());
                    if !refined {
                        if probe {
                            eprintln!(
                                "TRUST_DYN_PROBE: impls_verified=false ({impl_type} fails Liskov refinement)"
                            );
                        }
                        return false;
                    }
                }
            }
            // Non-overriding impl: inherits the trait default body, which carries
            // the trait contract verbatim. Sound iff that default body verifies.
            None => {
                let in_progress =
                    DYN_SUMMARY_IN_PROGRESS.with(|s| s.borrow().contains(&trait_method_def_id));
                if in_progress {
                    if probe {
                        eprintln!(
                            "TRUST_DYN_PROBE: impls_verified=false ({impl_type} default body in progress)"
                        );
                    }
                    return false;
                }
                let default_verified = matches!(
                    tcx.trust_proof_results(ty::InstanceKind::Item(trait_method_def_id)),
                    Some(results)
                        if has_nonzero_accounted_static_proof(
                            tcx.sess,
                            trait_method_def_id,
                            results,
                        ),
                );
                if !default_verified {
                    if probe {
                        eprintln!(
                            "TRUST_DYN_PROBE: impls_verified=false ({impl_type} default body unverified)"
                        );
                    }
                    return false;
                }
            }
        }
    }
    true
}

/// CLOSED-WORLD generic dispatch (rung 2 of the discharge lattice; aterm
/// docs/measurements/2026-07-12-generic-dispatch-lattice-design.md): whether a
/// statically-unresolvable `<S as Trait>::m` (S a type parameter,
/// `Instance::try_resolve` = `Ok(None)`) is panic-free BY EXHAUSTION of the
/// trait's impl set. Sound iff BOTH hold:
///
/// 1. the impl set is provably CLOSED — `dyn_trait_sealedness` = `Sealed`
///    (local trait, no blanket impls, and final-artifact / non-exported /
///    private-supertrait), so no impl can exist outside this enumeration and
///    no future instantiation can dispatch outside it; and
/// 2. EVERY member of the enumerated set — each overriding impl method, plus
///    the trait's default body wherever an impl inherits it — is itself
///    verified panic-free (`has_nonzero_accounted_static_proof`).
///
/// Under exactly those conditions the R3 counterexample ("at mono an impl may
/// supply a body that PANICS") cannot exist: every body any monomorphization
/// can select is inside the verified conjunction. Anything less fails closed:
/// an Open/blanket/exported trait, an unverified or in-progress impl, a
/// cyclic MIR query, or an EMPTY impl set (vacuity must stay visible as the
/// fatal row, never become a silent green) all return `false`.
///
/// Trust (D4 increment B, 2026-09-25): `shape` serves the FOREIGN-trait arm only.
/// `dyn_trait_sealedness` answers `Open` for every foreign trait, because no
/// seal is visible from here; the arm below closes the impl set by ENUMERATION
/// instead (`foreign_trait_closure`, rung `Sealed`: whole-program artifact,
/// generic call with a `Sized` `Self`, no blanket impl, every dispatch target —
/// local or foreign — through the shared bar, each foreign one re-derived in this
/// compilation). A local trait never reaches it and decides exactly as before.
fn sealed_generic_dispatch_impls_all_panic_free<'tcx>(
    tcx: TyCtxt<'tcx>,
    scanned_body_def_id: DefId,
    trait_def_id: DefId,
    trait_method_def_id: DefId,
    shape: foreign_trait_closure::RelianceShape,
) -> bool {
    // Diagnostic-only trace (TRUST_RUNG2_PROBE=1): names the bail point.
    // Verdict-neutral — no branch depends on it.
    let probe = trust_env_var_present("TRUST_RUNG2_PROBE");
    let sealedness = dyn_trait_sealedness(tcx, trait_def_id);
    if probe {
        eprintln!(
            "TRUST_RUNG2_PROBE: trait={} sealedness={:?}",
            probe_label(tcx, trait_def_id),
            sealedness,
        );
    }
    if !trait_def_id.is_local() {
        return foreign_trait_closure::foreign_impl_set_rederived_panic_free(
            tcx,
            trait_def_id,
            trait_method_def_id,
            shape,
            foreign_trait_closure::ClosureRung::Sealed,
        );
    }
    if sealedness != trust_vcgen::TraitSealedness::Sealed {
        return false;
    }
    let impls = tcx.local_trait_impls(trait_def_id);
    if probe {
        eprintln!("TRUST_RUNG2_PROBE: impl_count={}", impls.len());
    }
    // Vacuity control: zero impls means the call can never execute, but a
    // silent demotion would be indistinguishable from a real discharge in the
    // gate output. Keep the fatal row (fail-closed, visible).
    if impls.is_empty() {
        return false;
    }
    for impl_local in impls {
        let impl_def_id = impl_local.to_def_id();
        let target = match tcx.impl_item_implementor_ids(impl_def_id).get(&trait_method_def_id) {
            // Overriding impl method.
            Some(&impl_method_def_id) => impl_method_def_id,
            // Non-overriding impl: the trait default body is the dispatch
            // target for this impl (rustc guarantees it exists here).
            None => trait_method_def_id,
        };
        // Never force verification of the body currently being scanned (direct
        // self-recursion through the generic call), a def whose summaries are
        // already being computed up the stack, or a def whose `optimized_mir`
        // peek would form an E0391 query cycle — each bails fail-closed.
        if target == scanned_body_def_id {
            if probe {
                eprintln!("TRUST_RUNG2_PROBE: bail=self-scan target={}", probe_label(tcx, target));
            }
            return false;
        }
        let in_progress = DYN_SUMMARY_IN_PROGRESS.with(|s| s.borrow().contains(&target));
        if in_progress {
            if probe {
                eprintln!(
                    "TRUST_RUNG2_PROBE: bail=in-progress target={}",
                    probe_label(tcx, target)
                );
            }
            return false;
        }
        if optimized_mir_query_would_cycle(tcx, target) {
            if probe {
                eprintln!("TRUST_RUNG2_PROBE: bail=mir-cycle target={}", probe_label(tcx, target));
            }
            return false;
        }
        // A `#[trust::skip]`'d impl body is UNVERIFIED by user decree; its
        // zero-obligation artifact shape below would be indistinguishable
        // from "trivially panic-free", so gate on the attribute explicitly.
        if item_has_trust_skip_attr(tcx, target) {
            if probe {
                eprintln!("TRUST_RUNG2_PROBE: bail=trust-skip target={}", probe_label(tcx, target));
            }
            return false;
        }
        let results = tcx.trust_proof_results(ty::InstanceKind::Item(target));
        // Trust (assumption-root gate): the `#[trust::skip]` bail above is the
        // ATTRIBUTE ON THE TARGET. A skip or `#[trust::assume_total]` on a CALLEE
        // inside the target's own bundle produces the same "zero obligations,
        // trivially panic-free" shape and carries no attribute here to gate on —
        // measured. Consulted AFTER the query above, which is what forces the
        // verdict and writes the census.
        let axiom_decline = verdict_rests_on_user_axiom(tcx.sess, target);
        let verified = axiom_decline.is_none()
            && matches!(
                results,
                Some(r) if has_nonzero_accounted_static_proof(tcx.sess, target, r)
                    // Ran (query returned results for a LOCAL, non-skip'd item)
                    // with ZERO obligations and zero rows: vcgen emits an
                    // obligation for every panic-capable construct, so an empty
                    // set means the body has none — trivially panic-free (e.g. a
                    // field read). Contract-panic and failed rows make the set
                    // NON-empty and land in the accounted branch above, which
                    // rejects them (trusted+certified must equal total).
                    || (r.summary.total == 0
                        && r.dispositions.is_empty()
                        && r.has_aligned_obligation_arrays()),
            );
        if let Some(reason) = axiom_decline
            && probe
        {
            eprintln!(
                "TRUST_RUNG2_PROBE: bail=assumption-root target={} ({reason})",
                probe_label(tcx, target)
            );
        }
        if probe {
            match results {
                Some(r) => eprintln!(
                    "TRUST_RUNG2_PROBE: target={} fully_verified={} total={} trusted={} certified={} aligned={} => verified={}",
                    probe_label(tcx, target),
                    r.is_fully_verified(),
                    r.summary.total,
                    r.summary.trusted,
                    r.summary.certified,
                    r.has_aligned_obligation_arrays(),
                    verified,
                ),
                None => eprintln!(
                    "TRUST_RUNG2_PROBE: target={} proof_results=None",
                    probe_label(tcx, target),
                ),
            }
        }
        if !verified {
            return false;
        }
    }
    if probe {
        eprintln!("TRUST_RUNG2_PROBE: DEMOTE method={}", probe_label(tcx, trait_method_def_id));
    }
    true
}

/// Build the database of assumable `dyn Trait` callee summaries for `body`.
///
/// Empty for any function that makes no sealed-contracted dynamic call, so the
/// live VC path is byte-identical on the default path.
fn build_dyn_dispatch_summaries<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    // Trust: shared per-DB-build memo for `extract_contract_formulas_for_def`
    // (verdict-identical caching of a pure result; see `build_callee_contract_summaries`).
    memo: &mut ContractFormulaMemo<'tcx>,
) -> trust_vcgen::SummaryDatabase {
    let mut db = trust_vcgen::SummaryDatabase::new();
    let caller_def_id = body.source.def_id();

    // Guard our own entry so nested impl verification can detect the cycle.
    // A re-entrant call fails closed; the owning frame is panic-safe.
    let Some(_in_progress_guard) = DynSummaryInProgressGuard::enter(caller_def_id) else {
        return db;
    };

    let typing_env = ty::TypingEnv::post_analysis(tcx, caller_def_id);

    for bb in body.basic_blocks.iter() {
        let Some(term) = &bb.terminator else { continue };
        let (TerminatorKind::Call { func: callee_op, .. }
        | TerminatorKind::TailCall { func: callee_op, .. }) = &term.kind
        else {
            continue;
        };
        let probe = dyn_probe_enabled();
        let Some((callee_def_id, args)) = callee_op.const_fn_def() else {
            if probe {
                eprintln!("TRUST_DYN_PROBE: call with no const_fn_def in {:?}", caller_def_id);
            }
            continue;
        };
        let resolved = ty::Instance::try_resolve(tcx, typing_env, callee_def_id, args);
        if probe {
            eprintln!(
                "TRUST_DYN_PROBE: call callee={} resolved={}",
                probe_label(tcx, callee_def_id),
                match &resolved {
                    Ok(Some(i)) => format!("{:?}", i.def),
                    Ok(None) => "Ok(None)".to_string(),
                    Err(_) => "Err".to_string(),
                },
            );
        }
        let Ok(Some(instance)) = resolved else {
            continue;
        };
        let ty::InstanceKind::Virtual(method_def_id, _slot) = instance.def else { continue };

        let Some(trait_def_id) = tcx.trait_of_assoc(method_def_id) else { continue };

        if probe {
            let (hpre, hpost) =
                extract_contract_formulas_memo(tcx, method_def_id, instance.args, memo);
            let native_n =
                trust_contracts_if_any(tcx, method_def_id).map_or(0, |b| b.contracts.len());
            let sealed = dyn_trait_sealedness(tcx, trait_def_id);
            eprintln!(
                "TRUST_DYN_PROBE: virtual call method={} trait={} sealed={:?} hir_pre={} hir_post={} native_contracts={}",
                probe_label(tcx, method_def_id),
                probe_label(tcx, trait_def_id),
                sealed,
                hpre.len(),
                hpost.len(),
                native_n,
            );
        }

        let sealedness = dyn_trait_sealedness(tcx, trait_def_id);
        if sealedness != trust_vcgen::TraitSealedness::Sealed {
            continue;
        }

        let (preconditions, postconditions) =
            extract_contract_formulas_memo(tcx, method_def_id, instance.args, memo);
        if probe {
            eprintln!(
                "TRUST_DYN_PROBE: extracted pre={} post={} for {}",
                preconditions.len(),
                postconditions.len(),
                probe_label(tcx, method_def_id),
            );
        }
        if postconditions.is_empty() {
            continue;
        }

        // Use the exact identity-bearing key carried by the extracted call.
        // A diagnostic `safe_def_path_str` is not injective when two dependency
        // versions share a crate name; `func_operand_name` adds the stable-crate
        // discriminator in precisely that case and is also the direct-summary
        // registration boundary below.
        let callee_name = trust_mir_extract::func_operand_name_in_body(tcx, body, callee_op);
        let method_name = tcx.item_name(method_def_id).to_string();
        let trait_name = trust_mir_extract::safe_def_path_str(tcx, trait_def_id);

        let impls_ok = all_trait_impls_verified(
            tcx,
            trait_def_id,
            method_def_id,
            &trait_name,
            &method_name,
            &preconditions,
            &postconditions,
        );
        if probe {
            eprintln!("TRUST_DYN_PROBE: all_trait_impls_verified={}", impls_ok);
        }
        if !impls_ok {
            continue;
        }

        let vtable = trust_types::VTable { trait_name: trait_name.clone(), slots: vec![] };
        let contract = trust_vcgen::MethodContract {
            method_name: method_name.clone(),
            preconditions,
            postconditions,
        };
        let model = trust_vcgen::VtableModel::new(trait_name, vtable, vec![contract])
            .with_sealedness(sealedness);

        let summary = model.dyn_dispatch_summary(&method_name, callee_name.as_str(), true);
        if probe {
            eprintln!(
                "TRUST_DYN_PROBE: dyn_dispatch_summary for callee={} -> {}",
                callee_name,
                if summary.is_some() { "SOME (inserted)" } else { "None" },
            );
        }
        if let Some(summary) = summary {
            // Trust (audit enhancement — extend R2 #9 postcondition reuse to dyn):
            //
            // We only reach here when the trait is SEALED (closed world, gated on
            // the whole-program bit and folded into the verification cache key) AND
            // every enumerated impl was REALLY verified against the contract
            // (`all_trait_impls_verified` -> `trust_proof_results` per impl, the
            // artifact backing). The closed world means the actual `dyn` callee —
            // whichever sealed impl — satisfies the trait's `#[ensures]`, and the
            // caller separately discharges its `#[requires]` at the call site, so
            // assuming the postcondition is sound (the same modular argument as a
            // direct call). Mint reusable evidence so the dyn call's postcondition
            // discharges downstream caller obligations. The artifact-backed
            // condition is supplied HERE; the model's `dyn_dispatch_summary` stays
            // flag-only (no evidence) — exactly what the open-world / unverified
            // guardrail tests in `vtable_model` require.
            //
            // param_names (audit R3 #2/#3): the model's `dyn_dispatch_summary` does
            // NOT set param_names, but the call-site injection gate
            // (`callee_postcondition_is_injectable`) requires
            // `param_names.len() == arg_count`, and a virtual call always carries a
            // `self` receiver (arg_count >= 1). Without param_names the gate is
            // universally false and the dyn postcondition reuse is silently INERT.
            // Attach the trait method's formal names — INCLUDING the `self`
            // receiver (`callee_param_names` numbers MIR locals `1..=arg_count` /
            // uses `fn_arg_idents`, both receiver-inclusive) — so the count matches
            // the virtual call's args and the positional formals->args rebinding of
            // any `#[requires]` is correct. (Combined with R3 #1, the postcondition
            // is only assumed at >= L1Functional, where the precondition VC is also
            // checked — so this stays modular-sound.)
            // Carry the same instantiated formal types as direct summaries so
            // an exact collection-length precondition is positionally rebound
            // to the virtual call's actual receiver/arguments. If `Self` or a
            // generic remains unresolved, the empty vector deliberately keeps
            // that length term non-dischargeable.
            let param_types = trust_mir_extract::extract_contract_param_types_for_instance(
                tcx,
                method_def_id,
                instance.args,
            )
            .unwrap_or_default();
            let summary = summary
                .with_param_names(callee_param_names(tcx, method_def_id))
                .with_param_types(param_types)
                .with_verified_contract_evidence(callee_name.clone());
            db.insert(summary);
        }
    }

    db
}

/// Trust: per-DB-build memo for `extract_contract_formulas_for_def`.
///
/// The extractor is a pure function of `(tcx, def_id)` — it reads only the
/// `trust_contracts` query and HIR attributes, with no body or call-graph
/// dependence — so caching its `(preconditions, postconditions)` result per
/// `DefId` for the duration of one `build_callee_contract_summaries` invocation
/// is value-identical to recomputing it. Used to avoid re-extracting the same
/// callee's contract formulas across the dyn-dispatch and direct-call passes.
type ContractFormulaMemo<'tcx> =
    FxHashMap<(DefId, ty::GenericArgs<'tcx>), (Vec<Formula>, Vec<Formula>)>;

/// Trust: memoized wrapper over `extract_contract_formulas_for_def`.
///
/// VERDICT-IDENTITY: returns exactly what the underlying extractor returns for
/// `def_id`; the memo only avoids recomputation of an identical pure result.
fn extract_contract_formulas_memo<'tcx>(
    tcx: TyCtxt<'tcx>,
    def_id: DefId,
    args: ty::GenericArgs<'tcx>,
    memo: &mut ContractFormulaMemo<'tcx>,
) -> (Vec<Formula>, Vec<Formula>) {
    if let Some(cached) = memo.get(&(def_id, args)) {
        return cached.clone();
    }
    let extracted = trust_mir_extract::extract_contract_formulas_for_instance(tcx, def_id, args);
    memo.insert((def_id, args), extracted.clone());
    extracted
}

/// Trust (F6 — interprocedural float interval summaries): session-scoped memo
/// for `f6_derived_callee_result_range`. The derivation is a pure function of
/// the callee's final optimized MIR and its extracted contracts — both fixed
/// for one compiler invocation — so caching per callee `DefId` is
/// value-identical to recomputing it in every caller's summary build (matrix
/// code reaches the same f64 leaf from dozens of callers). A cached `None`
/// records a PURE fail-closed refusal (extraction error / no derivable
/// interval) so its extraction-sized miss cost is also paid once; the
/// stack-dependent query-cycle refusal is deliberately NOT cached (see
/// `f6_derived_callee_result_range`). Session ownership mirrors
/// `SessionArtifactCache`: a later rustc_driver compilation must never replay
/// another crate's derivations.
#[derive(Default)]
struct SessionFloatResultRanges {
    ranges: FxHashMap<DefId, Option<((f64, f64), Vec<Formula>)>>,
}

/// Trust (F6): a direct callee's derived f64 RESULT interval for the
/// production callee-contract summaries, together with the precondition set
/// the derivation was entitled to assume.
///
/// SOUNDNESS (assume-guarantee alignment): `trust_vcgen::derive_float_result_range`
/// yields an interval valid only WHEN THE CALLEE'S OWN PRECONDITIONS HOLD —
/// the tracer reads the extracted `VerifiableFunction::preconditions` as
/// contract facts. The vcgen consumer (`float_summary_result_range`)
/// structurally re-establishes `FunctionSummary::preconditions` at each call
/// site before honoring the interval (self-contained assume-guarantee), so
/// the attach site must verify that every formula returned here is carried by
/// the summary — a derivation assumption missing from the summary would go
/// unchecked. This helper returns the assumed set to make that checkable.
///
/// RECURSION: cut HERE, one level deep — the derivation itself never crosses
/// a call boundary (its `FloatRangeCtx` carries NO summaries, so every callee
/// dest inside the traced body fails closed to `None`). No fixpoint exists to
/// diverge, and refusing an entry only weakens the interval toward `None`.
///
/// FAIL-CLOSED gates (a `None` can only ever KEEP a caller-side VC, never
/// discharge one):
/// - non-`Fn`/`AssocFn` callees (the `fn_sig` query panics for closures/consts);
/// - generic callees (`generics_of(..).count() != 0`) and calls whose args
///   carry non-region params (`has_non_region_param`, the trust-mir-extract
///   discipline) — the polymorphic MIR is not the monomorphic function this
///   call executes, and the `DefId`-keyed memo must not mix instantiations;
/// - non-local or MIR-unavailable callees — no body to derive from;
/// - Trust (2026-10-04, F6-INTERPOSE-1): callees the shared identity gate
///   `body_summary_identity_refused` refuses — an interposable symbol
///   (`#[no_mangle]`, `#[export_name]`, `#[linkage]`), whose checked body need not
///   be the one the call binds to at link time, a foreign item, and a
///   Clean-origin def (its own definitional lane's);
/// - callees whose `optimized_mir` would re-enter a live query (a self-call
///   up the verification stack or a mutual-recursion SCC): the elaborated
///   `mir_for_trust_verification` snapshot is NOT substituted here because
///   the summary-side body must stay byte-identical to the body the interval
///   claims to describe — the final optimized MIR codegen executes;
/// - non-f64 return types (pre-extraction; `derive_float_result_range`
///   re-checks on the extracted body's `return_ty`).
///
/// The extraction REUSES `native_trust_ir_extract_callee_function` on
/// `tcx.optimized_mir(callee)` — the same extraction fn + contract policy the
/// callee's own verification applies (`extract_function_with_contract_bundle`
/// at the `collect_verification_artifacts_inner_with_policy` seam) to the
/// same final body (`TrustVerify` is the last pass of `inner_optimized_mir`).
/// The `optimized_mir` force adds no new query edge: `callee_param_names`
/// already forces it for exactly the callees admitted here.
fn f6_derived_callee_result_range<'tcx>(
    tcx: TyCtxt<'tcx>,
    callee_def_id: DefId,
    args: ty::GenericArgs<'tcx>,
) -> Option<((f64, f64), Vec<Formula>)> {
    use rustc_middle::ty::TypeVisitableExt;
    if !matches!(tcx.def_kind(callee_def_id), DefKind::Fn | DefKind::AssocFn) {
        return None;
    }
    if tcx.generics_of(callee_def_id).count() != 0 || args.has_non_region_param() {
        return None;
    }
    let local = callee_def_id.as_local()?;
    // Trust (2026-10-04, F6-INTERPOSE-1): the identity gate the body-derived
    // summary lanes share. An interposable symbol's body need not be the one
    // the call runs, and a Clean-origin def is its own lane's.
    if body_summary_identity_refused(tcx, callee_def_id) {
        return None;
    }
    if !tcx.is_mir_available(callee_def_id) {
        return None;
    }
    // Cheap pre-extraction gate: only an f64-returning callee can carry an
    // interval (aggregate float returns are deferred — vcgen derives `None`).
    if tcx.fn_sig(callee_def_id).instantiate_identity().skip_binder().output() != tcx.types.f64 {
        return None;
    }
    if let Some(cached) =
        tcx.sess.with_trust_compiler_state::<SessionFloatResultRanges, _>(|state| {
            state.ranges.get(&callee_def_id).cloned()
        })
    {
        return cached;
    }
    // The cycle gate is checked at COMPUTE time and its refusal is never
    // cached: whether `optimized_mir(callee)` is live up the stack depends on
    // verification order, and memoizing a transient refusal would make the
    // summary content order-dependent. A pure `None` (below) is cacheable.
    if optimized_mir_query_would_cycle(tcx, callee_def_id) {
        return None;
    }
    // Compute OUTSIDE the session-state lock: forcing `optimized_mir` can
    // synchronously verify the callee, whose own summary build re-enters this
    // memo for ITS callees — and the per-type state cell is a non-reentrant
    // mutex. A racing duplicate computation is value-identical (pure).
    let callee_body = tcx.optimized_mir(local.to_def_id());
    let derived = native_trust_ir_extract_callee_function(tcx, callee_body).ok().and_then(|vf| {
        trust_vcgen::derive_float_result_range(&vf).map(|range| (range, vf.preconditions))
    });
    tcx.sess.with_trust_compiler_state::<SessionFloatResultRanges, _>(|state| {
        state.ranges.entry(callee_def_id).or_insert(derived).clone()
    })
}

/// Trust (wave-3 — context-sensitive callee tracing): session-scoped memo for
/// the callee `VerifiableFunction` bodies attached to summaries so the float
/// tracer can RE-TRACE a callee under caller-derived argument intervals (the
/// static per-callee result interval closes almost nothing — struct/vector
/// chains need CALLSITE-specific ranges; the tracer evaluates the requested
/// return-place projection inside the callee body with the actuals' proven
/// intervals as parameter overrides). Same DefId-keyed, session-owned discipline
/// as `SessionFloatResultRanges`; an `Arc` because one body serves every caller.
/// A cached `None` records a fail-closed refusal (extraction error / gate miss)
/// — the body is an ANALYSIS INPUT carrying NO proof authority, so a wrong or
/// missing body can only weaken a discharge toward "obligation kept".
#[derive(Default)]
struct SessionCalleeBodies {
    bodies: FxHashMap<DefId, Option<std::sync::Arc<trust_types::VerifiableFunction>>>,
}

/// The callee's extracted `VerifiableFunction` for context-sensitive re-tracing,
/// or `None` under the SAME fail-closed gates as `f6_derived_callee_result_range`
/// EXCEPT the f64-return pre-gate: a struct/vector-returning callee (`Vec3::add`,
/// `Vec3::new`, `Mat4::row`) is exactly the case the whole-callee re-trace exists
/// to serve, and CONTRACT-LESS callees (unannotated constructors like
/// `Vec3::new` / `Vec4::new`) MUST get a body too — they are invisible to the
/// contract-summary path and their per-field passthrough is what lets a matrix
/// row's `Vec4::new(dot, …)` fields be traced at all.
fn extracted_callee_body_for_tracing<'tcx>(
    tcx: TyCtxt<'tcx>,
    callee_def_id: DefId,
    args: ty::GenericArgs<'tcx>,
) -> Option<std::sync::Arc<trust_types::VerifiableFunction>> {
    use rustc_middle::ty::TypeVisitableExt;
    if !matches!(tcx.def_kind(callee_def_id), DefKind::Fn | DefKind::AssocFn) {
        return None;
    }
    if tcx.generics_of(callee_def_id).count() != 0 || args.has_non_region_param() {
        return None;
    }
    let local = callee_def_id.as_local()?;
    // Trust (2026-10-04, F6-INTERPOSE-1): the same identity gate. Every body this
    // lane attaches is re-traced at a call site, and seeds the transitive trace
    // worklist, so an interposable callee must attach none.
    if body_summary_identity_refused(tcx, callee_def_id) {
        return None;
    }
    if !tcx.is_mir_available(callee_def_id) {
        return None;
    }
    if let Some(cached) = tcx.sess.with_trust_compiler_state::<SessionCalleeBodies, _>(|state| {
        state.bodies.get(&callee_def_id).cloned()
    }) {
        return cached;
    }
    if optimized_mir_query_would_cycle(tcx, callee_def_id) {
        return None; // stack-dependent; never cached (mirrors the F6 discipline)
    }
    let callee_body = tcx.optimized_mir(local.to_def_id());
    let extracted = native_trust_ir_extract_callee_function(tcx, callee_body)
        .ok()
        .map(|vf| std::sync::Arc::new(vf));
    tcx.sess.with_trust_compiler_state::<SessionCalleeBodies, _>(|state| {
        state.bodies.entry(callee_def_id).or_insert(extracted).clone()
    })
}

/// Trust (I5 cross-authority call modeling): the plan of record for a LOCAL
/// Clean-origin def — the SAME decision the sole body emitter acts on.
///
/// # The authority chain, and why this function may exist at all
///
/// `clean_origin_mir::build_gated_body` derives a `CleanOriginPlan` via
/// `clean_crate_environment` (the kernel-checked island environment) plus
/// `trust_clean_origin::plan_clean_origin_body` (which re-checks the
/// declaration's `FullKernelCheck` provenance and its total carrier
/// signature), emits MIR from the plan's shape, and the faithfulness gate
/// (`check_faithful`) then FATALLY refuses compilation unless the emitted body
/// kernel-identifies with the declaration. So for any Clean-origin def that
/// COMPILES, the plan returned here describes the emitted body exactly — not
/// because anyone re-read MIR bytes, but because the emitter cannot produce a
/// body that disagrees with this plan and live.
///
/// This function re-runs that SAME derivation (`clean_crate_environment` →
/// `plan_clean_origin_body`, both deterministic over the same island bytes;
/// the registry lookup keys the same `clean_origin_defs` row the emitter
/// keys). It NEVER reads the emitted MIR and NEVER parses Clean text itself.
///
/// `None` on ANY refusal — not a Clean-origin def, tainted/unrecoverable
/// island session, plan refused. Every consumer must treat `None` as "no
/// knowledge": the call stays havocked/absent and fails closed exactly as it
/// did before this lane existed. Never a default, never a guess.
///
/// COST: the registry lookup comes first and is empty in every crate without
/// a `clean { … }` island, so ordinary crates never elaborate anything here.
/// Trust: registry hits reuse the session's checked crate environment and cache the
/// resulting plan by local definition, matching `clean_origin_mir`'s inputs.
#[derive(Default)]
struct SessionCleanOriginPlans {
    plans: FxHashMap<DefId, Option<trust_clean_origin::CleanOriginPlan>>,
}

fn clean_origin_plan_of_record(
    tcx: TyCtxt<'_>,
    callee_def_id: DefId,
) -> Option<trust_clean_origin::CleanOriginPlan> {
    let local = callee_def_id.as_local()?;
    let (name, _span) = crate::clean_origin_mir::clean_origin_registry_entry(tcx, local)?;
    if let Some(cached) =
        tcx.sess.with_trust_compiler_state::<SessionCleanOriginPlans, _>(|state| {
            state.plans.get(&callee_def_id).cloned()
        })
    {
        return cached;
    }
    let env = crate::clean_origin_mir::clean_crate_environment(tcx)?;
    // Trust (W5): the same callee table the gate planned over, so the plan of
    // record is the plan the body was emitted from.
    let plan = trust_clean_origin::plan_clean_origin_body_with_rust_callees(
        &env,
        &name,
        &crate::clean_origin_mir::rust_callee_table(tcx),
    )
    .ok();
    tcx.sess.with_trust_compiler_state::<SessionCleanOriginPlans, _>(|state| {
        state.plans.insert(callee_def_id, plan.clone());
    });
    plan
}

/// Trust (I5 cross-authority call modeling): the validated call model for a
/// LOCAL Clean-origin def whose plan-of-record shape this lane models —
/// everything the caller-side consumers (panic-free registry, compiler-total
/// classification, definitional summary) need, re-checked against the plan
/// rather than trusted from it.
enum CleanOriginCallModel {
    /// Trust (W5 increment 3): a `RustCallChain` whose every Rust callee this crate
    /// CHARGED as `Pure ∧ Total ∧ Deterministic ∧ NoPanic`.
    ///
    /// Carries the arity and NO value semantics: the charge closes the "only if the
    /// callee returns" conditional, it does not say what the callee returns. The
    /// kernel proved the chain against an OPAQUE constant, so no value fact about it
    /// exists to state — see `clean_origin_callee_summary`, which returns `None` for
    /// this variant deliberately.
    RustCallChain { arity: usize },
    /// `fun x0 … x_{n-1} => x_i`: the emitted body is `_0 = move _{i+1};
    /// return` — call-free, total, complete value semantics `_0 == arg_i`.
    Projection { projected: usize, arity: usize },
    /// A single wrapping `+`/`-`/`*` over parameters / in-range numerals at
    /// ONE unsigned machine width: the emitted body is `bb0: _0 =
    /// Call(u{width}::wrapping_{op}, [l, r]) -> bb1: Return`, with the callee
    /// emitter-selected and marker-authenticated
    /// (`clean_origin_mir::resolve_core_wrapping_method` refuses anything
    /// failing `tcx_is_authenticated_core_integer_wrapping_method`) and the
    /// unwind edge `UnwindAction::Unreachable` — total by construction for
    /// ALL THREE ops. Value semantics are expressible for `Add`/`Sub` only
    /// (`trust_vcgen::clean_origin_wrapping_binop_postconditions`, which
    /// refuses `Mul` — that boundary is recorded at its definition).
    WrappingBinOp {
        op: trust_types::admissible_body::ArithBinOp,
        left: trust_types::admissible_body::ArithOperand,
        right: trust_types::admissible_body::ArithOperand,
        width: u32,
        arity: usize,
    },
    /// Trust (2026-09-28): `fun x… => if x_l ⊲ R then T else E` at ONE unsigned
    /// machine width, where `R`, `T` and `E` are each a parameter or an in-range
    /// numeral: R2/C5a `Select` (all parameters), R2/C9 `SelectLiteral` (a
    /// numeral `R`) and §6f landing 3 `SelectOperands` (numeral arms). The
    /// emitted body is the four-block diamond (`recognize_select`): a comparison,
    /// a `SwitchInt`, one move or constant into `_0` per arm. It has no call and
    /// no panic path, and the gate refuses compilation if the emitted diamond
    /// disagrees with this plan. Complete value semantics:
    /// `_0 == ite(x_l ⊲ R, T, E)`.
    Select {
        cmp: trust_types::admissible_body::SelectCmp,
        cmp_left: usize,
        cmp_right: CleanOriginSelectOperand,
        then_arm: CleanOriginSelectOperand,
        else_arm: CleanOriginSelectOperand,
        arity: usize,
    },
    /// Trust (2026-09-28): `fun x… => v`, an in-range numeral at the result's
    /// unsigned machine width, at any arity including zero (§6f landing 2). The
    /// emitted body is `_0 = const v; return`: no call, no panic path. Complete
    /// value semantics: `_0 == v`. The parameters are unread.
    ConstantUint { value: u128, arity: usize },
    /// Trust (2026-09-28): a `Bool`-valued comparison of two parameters at one
    /// unsigned width (W6 `DecideComparison`). The emitted body is
    /// `_0 = <cmp>(l, r); return`. Complete value semantics: `_0 == (x_l ⊲ x_r)`.
    DecideComparison {
        cmp: trust_types::admissible_body::SelectCmp,
        cmp_left: usize,
        cmp_right: usize,
        arity: usize,
    },
    /// Trust (2026-09-28): `Bool.not` of a `Bool` parameter (W6 `BoolNot`),
    /// emitted as `_0 = Not(p); return`. Value semantics: `_0 == ¬x_p`.
    BoolNot { param: usize, arity: usize },
    /// Trust (2026-09-28): `and`/`or` of two `Bool` parameters (W6
    /// `BoolConnective`), emitted as the strict `_0 = BitAnd|BitOr(l, r);
    /// return`, which computes exactly the total `Bool.and`/`Bool.or`. Value
    /// semantics: `_0 == (x_l ∧ x_r)` / `_0 == (x_l ∨ x_r)`.
    BoolConnective {
        op: trust_types::admissible_body::BoolBinOp,
        left: usize,
        right: usize,
        arity: usize,
    },
    /// Trust (2026-09-28): the one-instruction raw binop (§6f landing 7) in the
    /// forms whose value is an exact quotient or remainder by a positive numeral,
    /// at one unsigned width: `/` and `%` by a positive numeral, `>>` by an
    /// in-range numeral (`x / 2^k`), and `&` with a `2^k - 1` mask (`x % 2^k`).
    /// The emitted body is `_0 = BinaryOp(op, l, r); return`, with no call and no
    /// panic path at a nonzero constant divisor. Value semantics: `_0 == x / c` or
    /// `_0 == x % c`, which is exactly what
    /// `trust_vcgen::contracts::formula_is_exact_division_by_positive_literal`
    /// admits past the machine-arithmetic filter. Every other raw-binop form
    /// (a parameter operand on both sides, `|`, `^`, a non-mask `&`) stays
    /// unmodeled.
    ExactDivision { param: usize, divisor: u128, remainder: bool, arity: usize },
    /// Trust (2026-10-20): the general `Bool`-decision select (§6f landing 8),
    /// `if (cmp_left == cmp_right) = scrutinee then then_arm else else_arm` at
    /// one unsigned machine width, where `cmp_left` and `cmp_right` may be
    /// computed raw-binop nodes (`BeqOperand::RawBin`). Validated as total and
    /// panic-free whenever every `Div`/`Rem` operand has a strictly positive
    /// numeral divisor and every `Shr` constant shift is `< width`. Value
    /// semantics `_0 == ite([¬](L == R), T, E)` are injected when every
    /// `RawBin` operand is one of the four exact-division-by-positive-literal
    /// forms (`x / c`, `x % c`, `x >> k`, `x & (2^k - 1)`), preserving the
    /// authored `scrutinee` polarity without swapping arms.
    SelectBeqGeneral {
        scrutinee: bool,
        cmp_left: trust_types::admissible_body::BeqOperand,
        cmp_right: trust_types::admissible_body::BeqOperand,
        then_arm: CleanOriginSelectOperand,
        else_arm: CleanOriginSelectOperand,
        width: u32,
        arity: usize,
    },
}

/// Trust (2026-09-28): the comparison's right operand, or an arm, of a modeled
/// Clean-origin select.
#[derive(Clone, Copy, Debug)]
enum CleanOriginSelectOperand {
    /// A 0-based source parameter.
    Param(usize),
    /// An in-range numeral.
    Literal(u128),
}

impl CleanOriginSelectOperand {
    fn of(operand: trust_types::admissible_body::ArithOperand) -> Self {
        match operand {
            trust_types::admissible_body::ArithOperand::Param(index) => Self::Param(index),
            trust_types::admissible_body::ArithOperand::Const(value) => Self::Literal(value),
        }
    }
}

/// Trust (I5 cross-authority call modeling): the [`CleanOriginCallModel`] for
/// a LOCAL Clean-origin def; `None` for every other def, every unmodeled
/// shape, and any plan invariant violation (fail-closed, never a guess).
///
/// The match is deliberately EXHAUSTIVE over `CleanOriginShape` with no `_`
/// arm: this lane models direct/inductive projection, `WrappingBinOp` and (since
/// 2026-09-28) the two parameter-armed selects, `ConstantUint` and the three
/// `Bool`-valued W6 shapes. Any future
/// variant fails compilation here by design and gets its own explicit arm (a
/// modeling arm or a fail-closed `None` arm), never a fall-through —
/// `Composed`, which landed while this lane was being extended, starts
/// exactly that way below: fail-closed `None` (no summary, no panic-freedom,
/// no totality claim; its callers keep the fatal absent-callee arm and the
/// v7/D3 note) until a summary lane for it exists.
fn clean_origin_call_model_of_record(
    tcx: TyCtxt<'_>,
    callee_def_id: DefId,
) -> Option<CleanOriginCallModel> {
    clean_origin_call_record_of_record(tcx, callee_def_id)
        // Trust (Clean-origin caller-side preconditions): a def whose
        // declaration carries a caller obligation is NOT unconditionally
        // modeled. Both consumers of this function make an UNCONDITIONAL claim
        // — the panic-free registry and the compiler-total classification — and
        // a hypothesis-carrying `def` is total only WHERE ITS OBLIGATION HOLDS
        // (`(h : b ≠ 0)` exists precisely because the body diverges from the
        // Clean term at `b = 0`; `fa788aab89` measured that the kernel gate is
        // BLIND to that divergence). Registering it as panic-free would assert
        // the hazard away, which is the same class of fail-open as a DECLARED
        // invariant shrinking a model. It stays fail-closed here; its
        // obligation reaches call sites through
        // `clean_origin_callee_summary`, which is the lane that can state a
        // CONDITIONAL fact.
        .filter(|record| record.preconditions.is_empty())
        .map(|record| record.model)
}

/// Trust (I5 + Clean-origin caller-side preconditions): the call model AND the
/// caller obligations the declaration carries, together.
///
/// They travel as one value on purpose. The obligations are what make a
/// Clean-origin call's totality CONDITIONAL, so a consumer that reads the model
/// without them is a consumer making an unconditional claim it did not check —
/// exactly the split `650674bc71` closed one layer down (a value fact that
/// cannot travel with its guard must not travel at all).
struct CleanOriginCallRecord {
    model: CleanOriginCallModel,
    preconditions: Vec<trust_clean_origin::CleanOriginPrecondition>,
}

/// Trust (2026-09-28): the [`CleanOriginCallModel::Select`] for a select plan,
/// or `None` on any invariant the planner guarantees and this re-checks: one
/// unsigned machine width over the result and every parameter, every index in
/// range, and every literal fitting that width.
fn clean_origin_select_model(
    plan: &trust_clean_origin::CleanOriginPlan,
    cmp: trust_types::admissible_body::SelectCmp,
    cmp_left: usize,
    cmp_right: CleanOriginSelectOperand,
    then_arm: CleanOriginSelectOperand,
    else_arm: CleanOriginSelectOperand,
) -> Option<CleanOriginCallModel> {
    let arity = plan.param_tys().len();
    let trust_types::Ty::Int { width, signed: false } = plan.return_ty() else {
        return None;
    };
    let width = *width;
    if !matches!(width, 8 | 16 | 32 | 64) {
        return None;
    }
    if plan
        .param_tys()
        .iter()
        .any(|ty| !matches!(ty, trust_types::Ty::Int { width: w, signed: false } if *w == width))
    {
        return None;
    }
    let valid = |operand: CleanOriginSelectOperand| match operand {
        CleanOriginSelectOperand::Param(index) => index < arity,
        // width <= 64 (checked above), so the shift cannot overflow.
        CleanOriginSelectOperand::Literal(value) => value < (1u128 << width),
    };
    (cmp_left < arity && valid(cmp_right) && valid(then_arm) && valid(else_arm)).then_some(
        CleanOriginCallModel::Select { cmp, cmp_left, cmp_right, then_arm, else_arm, arity },
    )
}

/// Trust (2026-10-20): the [`CleanOriginCallModel::SelectBeqGeneral`] for a
/// general `Bool`-decision select plan, or `None` on any invariant violation:
/// one unsigned machine width over the result and every parameter, every
/// parameter index in range, every numeral fitting that width, every `Div`/`Rem`
/// leaf carrying a strictly positive numeral divisor, and every constant `Shr`
/// shift amount `< width`.
fn clean_origin_select_beq_general_model(
    plan: &trust_clean_origin::CleanOriginPlan,
    scrutinee: bool,
    cmp_left: trust_types::admissible_body::BeqOperand,
    cmp_right: trust_types::admissible_body::BeqOperand,
    then_arm: CleanOriginSelectOperand,
    else_arm: CleanOriginSelectOperand,
) -> Option<CleanOriginCallModel> {
    use trust_types::admissible_body::{ArithOperand, BeqOperand, RawBinOpKind};
    let arity = plan.param_tys().len();
    let trust_types::Ty::Int { width, signed: false } = plan.return_ty() else {
        return None;
    };
    let width = *width;
    if !matches!(width, 8 | 16 | 32 | 64) {
        return None;
    }
    if plan
        .param_tys()
        .iter()
        .any(|ty| !matches!(ty, trust_types::Ty::Int { width: w, signed: false } if *w == width))
    {
        return None;
    }
    let in_band = |value: u128| value < (1u128 << width);
    let valid_arm = |operand: CleanOriginSelectOperand| match operand {
        CleanOriginSelectOperand::Param(index) => index < arity,
        CleanOriginSelectOperand::Literal(value) => in_band(value),
    };
    let valid_leaf = |operand: ArithOperand| match operand {
        ArithOperand::Param(index) => index < arity,
        ArithOperand::Const(value) => in_band(value),
    };
    let valid_beq = |operand: BeqOperand| match operand {
        BeqOperand::Param(index) => index < arity,
        BeqOperand::Const(value) => in_band(value),
        BeqOperand::RawBin { op, left, right } => {
            if !valid_leaf(left) || !valid_leaf(right) {
                return false;
            }
            match op {
                RawBinOpKind::BitAnd | RawBinOpKind::BitOr | RawBinOpKind::BitXor => true,
                RawBinOpKind::Div | RawBinOpKind::Rem => {
                    matches!(right, ArithOperand::Const(divisor) if divisor > 0)
                }
                RawBinOpKind::Shr => match right {
                    ArithOperand::Param(_) => true,
                    ArithOperand::Const(shift) => shift < u128::from(width),
                },
            }
        }
    };
    (valid_beq(cmp_left) && valid_beq(cmp_right) && valid_arm(then_arm) && valid_arm(else_arm))
        .then_some(CleanOriginCallModel::SelectBeqGeneral {
            scrutinee,
            cmp_left,
            cmp_right,
            then_arm,
            else_arm,
            width,
            arity,
        })
}

/// Trust (2026-09-28): the [`CleanOriginCallModel::ExactDivision`] for a raw-binop
/// plan, or `None` for every form outside it and on any invariant the planner
/// guarantees and this re-checks: one unsigned machine width over the result and
/// every parameter, the parameter index in range, and the numeral in band.
fn clean_origin_raw_binop_model(
    plan: &trust_clean_origin::CleanOriginPlan,
    op: trust_types::admissible_body::RawBinOpKind,
    left: trust_types::admissible_body::ArithOperand,
    right: trust_types::admissible_body::ArithOperand,
) -> Option<CleanOriginCallModel> {
    use trust_types::admissible_body::{ArithOperand, RawBinOpKind};
    let arity = plan.param_tys().len();
    let trust_types::Ty::Int { width, signed: false } = plan.return_ty() else {
        return None;
    };
    let width = *width;
    if !matches!(width, 8 | 16 | 32 | 64)
        || plan.param_tys().iter().any(
            |ty| !matches!(ty, trust_types::Ty::Int { width: w, signed: false } if *w == width),
        )
    {
        return None;
    }
    let in_band = |value: u128| value < (1u128 << width);
    let (param, numeral) = match (left, right) {
        (ArithOperand::Param(param), ArithOperand::Const(numeral)) => (param, numeral),
        // `&` is commutative; the mask may be written on the left.
        (ArithOperand::Const(numeral), ArithOperand::Param(param))
            if op == RawBinOpKind::BitAnd =>
        {
            (param, numeral)
        }
        _ => return None,
    };
    if param >= arity || !in_band(numeral) {
        return None;
    }
    let (divisor, remainder) = match op {
        RawBinOpKind::Div if numeral > 0 => (numeral, false),
        RawBinOpKind::Rem if numeral > 0 => (numeral, true),
        RawBinOpKind::Shr if numeral < u128::from(width) => (1u128 << numeral, false),
        RawBinOpKind::BitAnd if (numeral + 1).is_power_of_two() => (numeral + 1, true),
        _ => return None,
    };
    Some(CleanOriginCallModel::ExactDivision { param, divisor, remainder, arity })
}

fn clean_origin_call_record_of_record(
    tcx: TyCtxt<'_>,
    callee_def_id: DefId,
) -> Option<CleanOriginCallRecord> {
    use trust_types::admissible_body::ArithOperand;
    let plan = clean_origin_plan_of_record(tcx, callee_def_id)?;
    let preconditions = plan.preconditions();
    let arity = plan.param_tys().len();
    let model = match plan.shape() {
        trust_clean_origin::CleanOriginShape::Projection { projected }
        | trust_clean_origin::CleanOriginShape::InductiveProjection { projected } => {
            // The planner guarantees `projected < arity`; if that invariant is
            // ever violated, refuse the summary rather than trust it.
            (*projected < arity)
                .then_some(CleanOriginCallModel::Projection { projected: *projected, arity })
        }
        trust_clean_origin::CleanOriginShape::WrappingBinOp { op, left, right } => {
            // The planner guarantees a single unsigned machine width across
            // EVERY signature position and in-range operands
            // (`recognise_wrapping_binop` / `recognise_arith_operand`).
            // Re-validate all of it here — same refuse-not-trust discipline
            // as the `projected < arity` check above: any violation refuses
            // the model instead of minting a wrong summary or a wrong
            // totality claim.
            let trust_types::Ty::Int { width, signed: false } = plan.return_ty() else {
                return None;
            };
            let width = *width;
            if !matches!(width, 8 | 16 | 32 | 64) {
                return None;
            }
            if plan.param_tys().iter().any(
                |ty| !matches!(ty, trust_types::Ty::Int { width: w, signed: false } if *w == width),
            ) {
                return None;
            }
            let operand_valid = |operand: &ArithOperand| match operand {
                ArithOperand::Param(i) => *i < arity,
                // width <= 64 (checked above), so the shift cannot overflow.
                ArithOperand::Const(v) => *v < (1u128 << width),
            };
            (operand_valid(left) && operand_valid(right)).then_some(
                CleanOriginCallModel::WrappingBinOp {
                    op: *op,
                    left: *left,
                    right: *right,
                    width,
                    arity,
                },
            )
        }
        // Trust (§6f landing 2): fail-closed `None`, and this arm exists
        // BECAUSE the match above is exhaustive by design — adding
        // `ConstantUint` to `CleanOriginShape` failed compilation here, which
        // is the mechanism working, not an obstacle to route around.
        //
        // The shape is the one whose summary would be easiest to state
        // (`result == <value>`, no call, no allocation, so genuinely total and
        // panic-free) and it is deliberately NOT stated here: minting a
        // caller-side summary is a separate increment with its own verify-on
        // ui fixture, and this landing measured the EMISSION, not the summary.
        // Claiming totality for a shape whose summary lane was never built is
        // exactly the kind of unearned claim §6f's discipline is against. Until
        // that increment, callers of a constant def stay fail-closed: result
        // havocked, the fatal absent-callee arm, and the v7/D3 note naming the
        // callee as Clean-origin with its options.
        //
        // Trust (2026-09-28): that increment, with its verify-on fixture
        // (`tests/ui/trust/clean_origin_constant_call_summary.rs`). The value is
        // re-range-checked against the result's unsigned width, as the plan was.
        trust_clean_origin::CleanOriginShape::ConstantUint { value } => {
            let trust_types::Ty::Int { width, signed: false } = plan.return_ty() else {
                return None;
            };
            (matches!(*width, 8 | 16 | 32 | 64) && *value < (1u128 << *width))
                .then_some(CleanOriginCallModel::ConstantUint { value: *value, arity })
        }
        // NOT MODELED by this increment: no summary, no panic-freedom claim,
        // no compiler-total classification — callers of a `Composed` def stay
        // fail-closed (havocked result, fatal absent-callee arm, the v7/D3
        // note naming the callee as Clean-origin) until this lane grows a
        // per-node composition of the same extractor-pinned encoding.
        trust_clean_origin::CleanOriginShape::Composed { .. } => None,
        // Trust (2026-09-28): the select summary lane, for the two
        // parameter-armed select shapes. Their clause is the definitional `ite`
        // equality (`clean_origin_callee_summary`). The planner guarantees one
        // unsigned machine width over every signature position (the reflected
        // side B is single-domain), in-range indices and an in-range literal;
        // all of it is re-validated here, as for `WrappingBinOp`. Measured
        // before: `fn min2(a, b) -> u64 ensures result <= a { min_isl(a, b) }`
        // over `def min_isl a b := if a < b then a else b` could not be proved,
        // while the same callee written in Rust proved; the result was
        // havocked. The `==`-lifted selects (`SelectBeq*`) stay fail-closed
        // below, for the reasons their arms record; `SelectOperands` joined this
        // lane.
        trust_clean_origin::CleanOriginShape::Select {
            cmp,
            cmp_left,
            cmp_right,
            then_param,
            else_param,
        } => clean_origin_select_model(
            &plan,
            *cmp,
            *cmp_left,
            CleanOriginSelectOperand::Param(*cmp_right),
            CleanOriginSelectOperand::Param(*then_param),
            CleanOriginSelectOperand::Param(*else_param),
        ),
        trust_clean_origin::CleanOriginShape::SelectLiteral {
            cmp,
            cmp_param,
            literal,
            then_param,
            else_param,
        } => clean_origin_select_model(
            &plan,
            *cmp,
            *cmp_param,
            CleanOriginSelectOperand::Literal(*literal),
            CleanOriginSelectOperand::Param(*then_param),
            CleanOriginSelectOperand::Param(*else_param),
        ),
        // Trust (§6f landing 3): fail-closed `None`, and this arm exists
        // BECAUSE the match is exhaustive by design — adding `SelectOperands`
        // to `CleanOriginShape` failed compilation here, which is the
        // mechanism working, not an obstacle to route around (the same thing
        // landing 2's `ConstantUint` arm records).
        //
        // The summary would be the `ite` equality the other two select shapes
        // are also waiting on, with numeral arms in place of two of its
        // parameter reads — so it is genuinely the SAME missing lane rather
        // than a new one, and stating it here for one shape and not its two
        // siblings would be a claim the landing did not measure. Until that
        // lane exists, callers of a general-select def stay fail-closed:
        // result havocked, the fatal absent-callee arm, and the v7/D3 note
        // naming the callee as Clean-origin with its options.
        //
        // Trust (2026-09-28): that lane exists now (the `Select` model above),
        // and it covers this shape as the arm said it should: the same `ite`
        // equality, with a numeral where a parameter read was.
        trust_clean_origin::CleanOriginShape::SelectOperands {
            cmp,
            cmp_left,
            cmp_right,
            then_arm,
            else_arm,
        } => clean_origin_select_model(
            &plan,
            *cmp,
            *cmp_left,
            CleanOriginSelectOperand::of(*cmp_right),
            CleanOriginSelectOperand::of(*then_arm),
            CleanOriginSelectOperand::of(*else_arm),
        ),
        // Trust (§6f landing 6): fail-closed `None`, and this arm exists
        // BECAUSE the match is exhaustive by design — adding `SelectBeq` to
        // `CleanOriginShape` failed compilation here, which is the mechanism
        // working, exactly as landings 2 and 3 each recorded for their own
        // variant.
        //
        // The summary is the SAME missing lane the other four select shapes
        // wait on — the definitional `ite` equality — with one extra wrinkle
        // that is worth writing down rather than discovering later: this
        // shape's `ite` condition is a `Bool`-level decision lifted by
        // `= Bool.true`, not the propositional equality, so a summary lane
        // that states the other four in terms of `a = b` would state THIS one
        // wrongly if it treated `==` as the same clause. Until that lane
        // exists and distinguishes them, callers of an `==`-select def stay
        // fail-closed: result havocked, the fatal absent-callee arm, and the
        // v7/D3 note naming the callee as Clean-origin with its options.
        trust_clean_origin::CleanOriginShape::SelectBeq {
            cmp_left,
            cmp_right,
            then_arm,
            else_arm,
        } => clean_origin_select_model(
            &plan,
            trust_types::admissible_body::SelectCmp::Eq,
            *cmp_left,
            CleanOriginSelectOperand::of(*cmp_right),
            CleanOriginSelectOperand::of(*then_arm),
            CleanOriginSelectOperand::of(*else_arm),
        ),
        // Trust (§6f landing 8): fail-closed `None`, and this arm exists
        // BECAUSE the match is exhaustive by design — adding `SelectBeqGeneral`
        // to `CleanOriginShape` failed compilation here, which is the mechanism
        // working, exactly as landings 2, 3, 6 and 7 each recorded for their
        // own variant.
        //
        // TWO things a future summary lane must not do with this shape, and
        // both are the kind that only look wrong in hindsight:
        //
        //  * a summary must NOT normalize the polarity. This shape's `ite`
        //    condition is a `Bool` decision lifted by `= <scrutinee>`, and the
        //    scrutinee may be `Bool.false`. `(a == b) = false` and the `==`
        //    body with its arms SWAPPED compute the same function and are NOT
        //    definitionally equal — the kernel refuses `rfl` between them
        //    (`landing8_selection_probes::l8_p2`) — so a summary lane that
        //    "simplified" a `false` lift into swapped arms would state a clause
        //    about a term the gate never checked.
        //  * a summary for a COMPUTED operand must carry the operand's own
        //    semantics, which for `/` and `%` are Clean's TOTAL `{C}.div`/`.mod`
        //    and not Rust's trapping operators — landing 7's trap, one layer
        //    inside a condition, and it holds here for the same reason: the two
        //    agree ONLY because the planner admits nothing but a strictly
        //    positive numeral divisor.
        //
        // Trust (2026-10-20): modeled via `clean_origin_select_beq_general_model`,
        // preserving `scrutinee` polarity without swapping arms and re-checking
        // the positive-numeral divisor precondition on every `Div`/`Rem` operand.
        trust_clean_origin::CleanOriginShape::SelectBeqGeneral {
            scrutinee,
            cmp_left,
            cmp_right,
            then_arm,
            else_arm,
        } => clean_origin_select_beq_general_model(
            &plan,
            *scrutinee,
            *cmp_left,
            *cmp_right,
            CleanOriginSelectOperand::of(*then_arm),
            CleanOriginSelectOperand::of(*else_arm),
        ),
        // Trust (§6f landing 7): fail-closed `None`, and this arm exists
        // BECAUSE the match is exhaustive by design — adding `RawBinOp` to
        // `CleanOriginShape` failed compilation here, which is the mechanism
        // working, exactly as landings 2, 3 and 6 each recorded for their own
        // variant.
        //
        // Most of the raw operators would have the EASIEST summary in this
        // whole match to state — `&`, `|`, `^`, `%`/`/` at a nonzero constant
        // and `>>` at an in-range constant amount are one instruction, no call,
        // no allocation, hence genuinely total and panic-free — and it is deliberately NOT stated, for the reason
        // landing 2's `ConstantUint` arm gives: minting a caller-side summary
        // is a separate increment with its own verify-on ui fixture, and this
        // landing measured the EMISSION, not the summary.
        //
        // ONE THING IS WORTH WRITING DOWN BEFORE THAT LANE IS WRITTEN, because
        // it is the trap this shape carries and nothing else in the match
        // does: a summary for `/` or `%` must NOT be stated as Rust's `/`/`%`.
        // The Clean declaration is `UInt{N}.div`/`.mod`, which are TOTAL
        // (`x / 0 = 0`, `x % 0 = x`), while Rust's operators panic — the two
        // agree ONLY because the planner admits nothing but a strictly
        // positive numeral divisor. A summary lane that reused a generic
        // integer-division clause would state a claim that is true of the
        // emitted body and false of the declaration the moment that divisor
        // rule is relaxed. Until such a lane exists and encodes the divisor
        // precondition explicitly, callers of a raw-binop def stay
        // fail-closed: result havocked, the fatal absent-callee arm, and the
        // v7/D3 note naming the callee as Clean-origin with its options.
        //
        // Trust (2026-09-28): the forms whose value is an exact quotient or
        // remainder by a positive numeral are modeled (`clean_origin_raw_binop_model`).
        // They are stated as `Div`/`Rem` by a POSITIVE LITERAL, which is the
        // divisor precondition written into the clause itself. The model refuses
        // any other divisor, so relaxing the planner's divisor rule cannot make
        // this summary state a false claim.
        trust_clean_origin::CleanOriginShape::RawBinOp { op, left, right } => {
            clean_origin_raw_binop_model(&plan, *op, *left, *right)
        }
        // Trust (W6, Rust-calls-Clean): a comparison returned as `Bool`. Like
        // the select shapes above, its caller-side summary model is `None` for
        // now — a call to it under verification-on has its result havocked with
        // the v7/D3 Clean-origin note, exactly as a select-valued callee does.
        // The MIR lane still EMITS and gate-verifies it; this is only the
        // cross-authority CALL summary, which no value-producing Clean-origin
        // shape carries yet.
        //
        // Trust (2026-09-28): now modeled, as are the negation and connective
        // below: each is a one-block body with no call and no panic path, whose
        // value is a `Bool` equality of the kind vcgen already states for a block
        // definition (`_4 == (_5 < _6)`). Every carrier is re-checked here: the
        // comparison's two operands at ONE unsigned width, the connectives'
        // operands and every result at `Bool`.
        trust_clean_origin::CleanOriginShape::DecideComparison { cmp, cmp_left, cmp_right } => {
            let params = plan.param_tys();
            let width_of = |index: usize| match params.get(index) {
                Some(trust_types::Ty::Int { width, signed: false }) => Some(*width),
                _ => None,
            };
            (matches!(plan.return_ty(), trust_types::Ty::Bool)
                && width_of(*cmp_left).is_some()
                && width_of(*cmp_left) == width_of(*cmp_right))
            .then_some(CleanOriginCallModel::DecideComparison {
                cmp: *cmp,
                cmp_left: *cmp_left,
                cmp_right: *cmp_right,
                arity,
            })
        }
        // Trust (W6, Rust-calls-Clean): a boolean negation/connective returned
        // as `Bool`. Modeled since 2026-09-28; see the comparison arm above.
        trust_clean_origin::CleanOriginShape::BoolNot { param } => {
            let is_bool =
                |index: usize| matches!(plan.param_tys().get(index), Some(trust_types::Ty::Bool));
            (matches!(plan.return_ty(), trust_types::Ty::Bool) && is_bool(*param))
                .then_some(CleanOriginCallModel::BoolNot { param: *param, arity })
        }
        trust_clean_origin::CleanOriginShape::BoolConnective { op, left, right } => {
            let is_bool =
                |index: usize| matches!(plan.param_tys().get(index), Some(trust_types::Ty::Bool));
            (matches!(plan.return_ty(), trust_types::Ty::Bool) && is_bool(*left) && is_bool(*right))
                .then_some(CleanOriginCallModel::BoolConnective {
                    op: *op,
                    left: *left,
                    right: *right,
                    arity,
                })
        }
        // Trust: composed Boolean source bodies have no qualified call-summary
        // representation yet. Keep callers fail-closed rather than asserting
        // an unchecked summary from the emitter's tree.
        trust_clean_origin::CleanOriginShape::BoolExpression { .. } => None,
        // Trust: source/native faithfulness does not supply a caller contract.
        trust_clean_origin::CleanOriginShape::UnsignedConditional { .. } => None,
        // Trust (R1, §6e as amended): fail-closed `None` — CALL MODELING FOR
        // RECURSION IS A LATER INCREMENT, deliberately not this one. The
        // recursive shapes are the first whose honest summary is not a plain
        // dest equality: a definitional summary for `tozero` would have to
        // carry the defining equations plus a termination-derived totality
        // claim, and the panic-freedom half is genuinely FALSE to claim
        // structurally (the emitted recursion is O(value) deep and its bignum
        // ops allocate — the call CAN abort/unwind on real inputs). Until a
        // summary lane states exactly what the per-equation gate licenses and
        // no more, callers of a StructuralNatRec def stay fail-closed: result
        // havocked, the fatal absent-callee arm, and the v7/D3 note naming
        // the callee as Clean-origin with its options — measured boundary
        // pinned by tests/ui/trust/clean_origin_structural_rec_verify_on.rs.
        trust_clean_origin::CleanOriginShape::StructuralNatRec { .. } => None,
        // Trust (R2, §6e MEASUREMENT NOTE): fail-closed `None`, for exactly
        // the R1 reason above and one more that is specific to this shape. An
        // honest summary would have to carry the defining equations plus a
        // totality claim; here that totality rests on the kernel's typing rule
        // at the decrease slot AND on an audited-empty axiom closure, and a
        // caller-side summary has no way to state the second — it is a
        // property of the DECLARATION's environment, not of the call. Until a
        // summary lane says exactly what the F-layer gate licenses and no
        // more, callers of a WellFoundedNatRec def stay fail-closed: result
        // havocked, the fatal absent-callee arm, and the v7/D3 note naming the
        // callee as Clean-origin with its options — the boundary
        // tests/ui/trust/clean_origin_wf_rec_verify_on.rs pins.
        trust_clean_origin::CleanOriginShape::WellFoundedNatRec { .. } => None,
        // Trust (W5, Lean-calls-Rust): modeled ONLY when increment 3's charge
        // certified every Rust callee this chain names. The def's totality rests on
        // those callees' facets, so an uncharged or failing def stays fail-closed —
        // no panic-free registration, no summary, the fatal absent-callee arm.
        //
        // `charged == false` means the pre-walk pass has not run for this session;
        // it licenses NOTHING, which is what keeps a read-before-charge from being
        // mistaken for "charged, and nothing passed".
        trust_clean_origin::CleanOriginShape::RustCallChain { nodes } => {
            let admitted =
                tcx.sess.with_trust_compiler_state::<SessionCleanRustCallChainCharged, _>(
                    |state| state.charged && state.admitted.contains(&callee_def_id),
                );
            // Re-validate the plan rather than trusting the set, the same
            // refuse-don't-trust discipline the sibling arms apply.
            if admitted
                && !nodes.is_empty()
                && nodes.iter().all(|node| node.callee < plan.callees().len())
            {
                Some(CleanOriginCallModel::RustCallChain { arity })
            } else {
                None
            }
        }
    };
    Some(CleanOriginCallRecord { model: model?, preconditions })
}

/// Trust (I5 cross-authority call modeling): the caller-side summary for a
/// call to a Clean-origin function whose shape the summary lane models,
/// derived from the plan of record (`clean_origin_call_model_of_record` —
/// kernel gate → plan → this summary; see `clean_origin_plan_of_record` for
/// the full chain).
///
/// # The exact semantics injected
///
/// * `Projection`: `result == arg_{projected}`, spelled `_0 ==
///   <formal_{projected}>` over synthetic formals. For the emitted body
///   `_0 = move _{projected+1}; return` this is the body's COMPLETE value
///   semantics.
/// * `WrappingBinOp` at `Add`/`Sub`: `_0 == (l op r) mod 2^width`, spelled as
///   the single-`Ite` modular reduction in Int/LIA — THE EXTRACTOR'S OWN
///   wrapping encoding (`trust-vcgen`'s `wrapping_call_assert_model` mints
///   the identical formula when it models the same `u{w}::wrapping_{op}`
///   primitive inside an ordinary extracted body; the constructor
///   `trust_vcgen::clean_origin_wrapping_binop_postconditions` owns the
///   encoding and its unit tests pin the two together, because a summary that
///   encoded wrapping differently from the extractor would be a soundness
///   bug). Operand range facts ride alongside, exactly as the extractor's do.
/// * `WrappingBinOp` at `Mul`: NO summary (`None` — the constructor's
///   recorded boundary: the Int/LIA lane that consumes these clauses has no
///   faithful nonlinear-mod encoding, matching the extractor's own refusal).
///   The call's PANIC-FREEDOM is still discharged (the op is total either
///   way); only its result stays havocked, fail-closed.
///
/// trust-vcgen rebinds each clause at each call site (formals → actual
/// operands, `_0` → the caller's dest) and version-pins it to the dest's
/// post-call SSA token, so the definition fact is an EQUALITY that refutes a
/// wrong caller claim (`assert!(s == 1)` after `wsum(u64::MAX, 1)`) exactly
/// as it discharges a right one (`assert!(s == 0)` — the WRAPPED value; an
/// unwrapped integer summary would refute it) — the summary states what the
/// callee returns, it does not bless what the caller asserts.
///
/// The formal names are synthetic (`__trust_clean_origin_arg{i}`): the plan
/// does not carry source parameter names, and none are needed — the clauses
/// are constructed over these names and they are substituted away wholesale
/// at rebinding, so they never reach a solver namespace. They exist only to
/// satisfy the arity/rebindability gates that make injection sound
/// (`callee_postcondition_is_injectable`).
///
/// The summary carries NO extracted body, contract, or float range: its clauses
/// are the facts the plan authorizes, and nothing else.
/// `with_definitional_postcondition` is the trust-vcgen authority carrier whose
/// contract this producer satisfies — see its doc.
///
/// # Preconditions — carried when the DECLARATION has them
///
/// It used to carry none, on the reasoning that "the plan's existence IS the
/// total-carrier evidence for the whole signature". That is still true of the
/// CARRIER obligation and says nothing about a caller obligation the
/// declaration itself states: `def safe_rem (a b : UInt64) (h : b ≠ 0)` erases
/// its proof binder into a Rust `fn` of arity 2, and the requirement the proof
/// stood for has to travel to the call sites or it is gone. So the plan's
/// `preconditions()` are handed to `trust_vcgen::clean_origin_summary`, which
/// refuses to publish the value facts unless it can carry every one of them.
///
/// **The set is empty for every plan today** — `plan_clean_origin_body` reads
/// the type through the un-lifted `carrier_signature_for`, which refuses a
/// hypothesis binder outright — so this is currently a no-op that keeps the
/// producer honest by construction rather than by comment. See
/// `CleanOriginPlan::preconditions`.
fn clean_origin_callee_summary(
    tcx: TyCtxt<'_>,
    callee_def_id: DefId,
    callee_name: &str,
) -> Option<trust_vcgen::FunctionSummary> {
    let record = clean_origin_call_record_of_record(tcx, callee_def_id)?;
    let synthetic_formals = |arity: usize| -> Vec<String> {
        (0..arity).map(|i| format!("__trust_clean_origin_arg{i}")).collect()
    };
    // Trust (Clean-origin caller-side preconditions): the value facts and the
    // declaration's caller obligations are handed to ONE constructor, which
    // returns `None` unless it can carry every obligation. That is the
    // `650674bc71` rule made structural at the producer: there is no argument
    // order here that publishes the value fact without its guard. A `None`
    // leaves the call unmodeled, which is the pre-existing fail-closed
    // behaviour (havocked result, the fatal absent-callee arm, the v7/D3 note)
    // — never an empty summary, which would read downstream exactly like a
    // callee that never had a contract.
    let (param_names, posts) = match record.model {
        // Trust (W5 increment 3): NO VALUE FACT, deliberately. The charge established
        // that every Rust callee returns; it established nothing about WHAT it
        // returns, because the kernel proved the chain against an OPAQUE constant.
        // Stating any postcondition here would be inventing semantics the kernel
        // never checked. The compiler forces this arm to exist — that is the
        // mechanism working.
        CleanOriginCallModel::RustCallChain { .. } => return None,
        CleanOriginCallModel::Projection { projected, arity } => {
            let param_names: Vec<String> = synthetic_formals(arity);
            let post = Formula::Eq(
                Box::new(Formula::var("_0", Sort::Int)),
                Box::new(Formula::var(&param_names[projected], Sort::Int)),
            );
            (param_names, vec![post])
        }
        CleanOriginCallModel::WrappingBinOp { op, left, right, width, arity } => {
            let param_names: Vec<String> = synthetic_formals(arity);
            // `None` for `Mul` (and any invalid instance): inject nothing —
            // the call stays havocked while its totality travels separately.
            let posts = trust_vcgen::clean_origin_wrapping_binop_postconditions(
                op,
                left,
                right,
                width,
                &param_names,
            )?;
            (param_names, posts)
        }
        // Trust (2026-09-28): `_0 == ite(x_l ⊲ R, T, E)`, over the same
        // Int-sorted formals as the projection. Every value is a machine
        // integer of one unsigned width, so the Int order IS the unsigned
        // order, and each arm is a parameter read or an in-band numeral.
        CleanOriginCallModel::Select { cmp, cmp_left, cmp_right, then_arm, else_arm, arity } => {
            use trust_types::admissible_body::SelectCmp;
            let param_names: Vec<String> = synthetic_formals(arity);
            let operand = |operand: CleanOriginSelectOperand| -> Option<Formula> {
                Some(match operand {
                    CleanOriginSelectOperand::Param(index) => {
                        Formula::var(&param_names[index], Sort::Int)
                    }
                    CleanOriginSelectOperand::Literal(value) => {
                        Formula::Int(i128::try_from(value).ok()?)
                    }
                })
            };
            let left = Box::new(Formula::var(&param_names[cmp_left], Sort::Int));
            let rhs = Box::new(operand(cmp_right)?);
            let condition = match cmp {
                SelectCmp::Lt => Formula::Lt(left, rhs),
                SelectCmp::Le => Formula::Le(left, rhs),
                SelectCmp::Eq => Formula::Eq(left, rhs),
            };
            let post = Formula::Eq(
                Box::new(Formula::var("_0", Sort::Int)),
                Box::new(Formula::Ite(
                    Box::new(condition),
                    Box::new(operand(then_arm)?),
                    Box::new(operand(else_arm)?),
                )),
            );
            (param_names, vec![post])
        }
        // Trust (2026-09-28): the `Bool`-valued shapes, over `Bool`-sorted `_0`
        // (the caller's destination is a `bool` local, so the rebinding's
        // `_0 -> dest` keeps the sort).
        CleanOriginCallModel::DecideComparison { cmp, cmp_left, cmp_right, arity } => {
            use trust_types::admissible_body::SelectCmp;
            let param_names: Vec<String> = synthetic_formals(arity);
            let left = Box::new(Formula::var(&param_names[cmp_left], Sort::Int));
            let right = Box::new(Formula::var(&param_names[cmp_right], Sort::Int));
            let value = match cmp {
                SelectCmp::Lt => Formula::Lt(left, right),
                SelectCmp::Le => Formula::Le(left, right),
                SelectCmp::Eq => Formula::Eq(left, right),
            };
            let post = Formula::Eq(Box::new(Formula::var("_0", Sort::Bool)), Box::new(value));
            (param_names, vec![post])
        }
        CleanOriginCallModel::BoolNot { param, arity } => {
            let param_names: Vec<String> = synthetic_formals(arity);
            let value = Formula::Not(Box::new(Formula::var(&param_names[param], Sort::Bool)));
            let post = Formula::Eq(Box::new(Formula::var("_0", Sort::Bool)), Box::new(value));
            (param_names, vec![post])
        }
        CleanOriginCallModel::BoolConnective { op, left, right, arity } => {
            use trust_types::admissible_body::BoolBinOp;
            let param_names: Vec<String> = synthetic_formals(arity);
            let operands = vec![
                Formula::var(&param_names[left], Sort::Bool),
                Formula::var(&param_names[right], Sort::Bool),
            ];
            let value = match op {
                BoolBinOp::And => Formula::And(operands),
                BoolBinOp::Or => Formula::Or(operands),
            };
            let post = Formula::Eq(Box::new(Formula::var("_0", Sort::Bool)), Box::new(value));
            (param_names, vec![post])
        }
        // Trust (2026-09-28): `_0 == x / c` or `_0 == x % c`, `c` a positive
        // literal: the exact shape the injection filter's second exemption admits.
        CleanOriginCallModel::ExactDivision { param, divisor, remainder, arity } => {
            let param_names: Vec<String> = synthetic_formals(arity);
            let x = Box::new(Formula::var(&param_names[param], Sort::Int));
            let c = Box::new(Formula::Int(i128::try_from(divisor).ok()?));
            let value = if remainder { Formula::Rem(x, c) } else { Formula::Div(x, c) };
            let post = Formula::Eq(Box::new(Formula::var("_0", Sort::Int)), Box::new(value));
            (param_names, vec![post])
        }
        // Trust (2026-09-28): `_0 == v`.
        CleanOriginCallModel::ConstantUint { value, arity } => {
            let post = Formula::Eq(
                Box::new(Formula::var("_0", Sort::Int)),
                Box::new(Formula::Int(i128::try_from(value).ok()?)),
            );
            (synthetic_formals(arity), vec![post])
        }
        // Trust (2026-10-20): `_0 == ite([¬](L == R), T, E)`, preserving the
        // authored `scrutinee` polarity without swapping arms and rendering
        // computed `RawBin` operands only when they are exact quotient/remainder
        // by a positive literal (`x / c`, `x % c`, `x >> k`, `x & (2^k - 1)`).
        // Other total `RawBin` operands (`|`, `^`, non-mask `&`) return `None`
        // here so the result stays havocked while totality travels separately.
        CleanOriginCallModel::SelectBeqGeneral {
            scrutinee,
            cmp_left,
            cmp_right,
            then_arm,
            else_arm,
            width,
            arity,
        } => {
            use trust_types::admissible_body::{ArithOperand, BeqOperand, RawBinOpKind};
            let param_names: Vec<String> = synthetic_formals(arity);
            let arm_operand = |operand: CleanOriginSelectOperand| -> Option<Formula> {
                Some(match operand {
                    CleanOriginSelectOperand::Param(index) => {
                        Formula::var(&param_names[index], Sort::Int)
                    }
                    CleanOriginSelectOperand::Literal(value) => {
                        Formula::Int(i128::try_from(value).ok()?)
                    }
                })
            };
            let beq_operand = |operand: BeqOperand| -> Option<Formula> {
                match operand {
                    BeqOperand::Param(index) => Some(Formula::var(&param_names[index], Sort::Int)),
                    BeqOperand::Const(value) => Some(Formula::Int(i128::try_from(value).ok()?)),
                    BeqOperand::RawBin { op, left, right } => {
                        let (param, numeral) = match (left, right) {
                            (ArithOperand::Param(param), ArithOperand::Const(numeral)) => {
                                (param, numeral)
                            }
                            (ArithOperand::Const(numeral), ArithOperand::Param(param))
                                if op == RawBinOpKind::BitAnd =>
                            {
                                (param, numeral)
                            }
                            _ => return None,
                        };
                        let (divisor, remainder) = match op {
                            RawBinOpKind::Div if numeral > 0 => (numeral, false),
                            RawBinOpKind::Rem if numeral > 0 => (numeral, true),
                            RawBinOpKind::Shr if numeral < u128::from(width) => {
                                (1u128 << numeral, false)
                            }
                            RawBinOpKind::BitAnd if (numeral + 1).is_power_of_two() => {
                                (numeral + 1, true)
                            }
                            _ => return None,
                        };
                        let x = Box::new(Formula::var(&param_names[param], Sort::Int));
                        let c = Box::new(Formula::Int(i128::try_from(divisor).ok()?));
                        Some(if remainder { Formula::Rem(x, c) } else { Formula::Div(x, c) })
                    }
                }
            };
            let left = Box::new(beq_operand(cmp_left)?);
            let right = Box::new(beq_operand(cmp_right)?);
            let eq = Formula::Eq(left, right);
            let condition = if scrutinee { eq } else { Formula::Not(Box::new(eq)) };
            let post = Formula::Eq(
                Box::new(Formula::var("_0", Sort::Int)),
                Box::new(Formula::Ite(
                    Box::new(condition),
                    Box::new(arm_operand(then_arm)?),
                    Box::new(arm_operand(else_arm)?),
                )),
            );
            (param_names, vec![post])
        }
    };
    trust_vcgen::clean_origin_summary(callee_name, param_names, posts, &record.preconditions)
}

/// Trust (Clean-origin definitional grounding, ASSERT-REFUTATION lane): the
/// identity-keyed refute-lane carriers of every Clean-origin DEFINITIONAL
/// summary a direct call in `body` resolves to — the SAME kernel-gated plan of
/// record [`clean_origin_callee_summary`] reads for the VC lane, handed to
/// `trust_vcgen`'s assert-refutation lane under the call's sealed
/// [`trust_types::CalleeIdentity`] instead of its rendered name.
///
/// MEASURED DEFECT (2026-09-13, stage1 at HEAD, `-Ztrust-verify=on`, opt 0):
/// `mod m { clean { def pick (a : UInt64) (b : UInt64) : UInt64 := a } }
/// fn main() { let v = m::pick(41, 7); assert!(v == 41); }` closed its
/// Assertion row KernelCertified in the VC lane from exactly this summary, yet
/// `vc:main__main:assertion:panic-freedom:0` stayed UNKNOWN: the refutation
/// lane (`refute_full_assert_obligations` ->
/// `generate_full_assert_refutation_vcs_with_context`) modeled call results
/// only for `wrapping_*` and the `?`/slice extractors and never read the
/// summary DB, so `v` stayed free (`[ASSERT_REFUTE] grounded=false
/// free=["_2#s1_0"]`), `panic_calls_proven_unreachable` stayed false, and the
/// assert's own `core::panicking::panic` edge then blocked the interprocedural
/// call gate (`[PF_CALLGATE] … UNREGISTERED callee blocks discharge:
/// core::panicking::panic`). Ruling `983bc1a3b6` names the grounded-residual
/// route as the sound one; this is that route's missing input.
///
/// # What may define a value in the refutation lane
///
/// ONLY a kernel-gated definitional summary of a Clean-origin callee — never
/// a name match, never an ordinary contract:
///  * the summary comes from [`clean_origin_callee_summary`], i.e. from
///    `clean_origin_plan_of_record` (registry entry -> Clean environment ->
///    `plan_clean_origin_body`), the plan the emitter acted on and the
///    faithfulness gate refuses compilation against;
///  * `trust_vcgen::CleanOriginDefinitionalCallModel::from_clean_origin_summary`
///    admits nothing but a PURE definitional summary (its doc lists each
///    refusal, including the proved-`ensures` shape that is sound to assume in
///    the UNSAT-only VC lane and a false refutation in this one);
///  * the key is `trust_mir_extract::instance_identity(tcx, def_id, args)` —
///    the very function the extractor uses to stamp
///    `Terminator::Call::callee_identity`, so the consumer's lookup is an
///    exact `DefId` + region-erased-substs match with no string anywhere in
///    the decision. Two call sites resolving one identity to DIFFERENT
///    models (cannot happen for one `DefId`; guarded anyway) poison the key.
///
/// The consumer additionally re-checks determination on the REBOUND clause
/// set and pins the definition to the call's destination exactly as
/// `with_definitional_postcondition`'s injection path does (it IS that path:
/// `callee_postcondition_is_injectable` + `rebind_callee_postconditions`).
///
/// Fail-closed: no plan of record, an unmodeled shape, a refused summary, a
/// refused carrier, or a call the extractor cannot fingerprint contributes
/// nothing, and an empty map is byte-identical to the pre-lane behaviour.
fn clean_origin_definitional_call_models<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> FxHashMap<trust_types::CalleeIdentity, trust_vcgen::CleanOriginDefinitionalCallModel> {
    let mut models: FxHashMap<
        trust_types::CalleeIdentity,
        trust_vcgen::CleanOriginDefinitionalCallModel,
    > = FxHashMap::default();
    if !body_has_call_terminator(body) {
        return models;
    }
    let mut poisoned: FxHashSet<trust_types::CalleeIdentity> = FxHashSet::default();
    for bb in body.basic_blocks.iter() {
        let Some(term) = &bb.terminator else {
            continue;
        };
        let (TerminatorKind::Call { func: callee_op, .. }
        | TerminatorKind::TailCall { func: callee_op, .. }) = &term.kind
        else {
            continue;
        };
        let Some((callee_def_id, args)) = callee_op.const_fn_def() else {
            continue;
        };
        // Same key spelling the extracted `Terminator::Call.func` carries; the
        // carrier keeps it as a belt on top of the identity key.
        let callee_name = trust_mir_extract::func_operand_name_in_body(tcx, body, callee_op);
        let Some(summary) = clean_origin_callee_summary(tcx, callee_def_id, &callee_name) else {
            continue;
        };
        let Some(model) =
            trust_vcgen::CleanOriginDefinitionalCallModel::from_clean_origin_summary(&summary)
        else {
            continue;
        };
        let Some(identity) = trust_mir_extract::instance_identity(tcx, callee_def_id, args) else {
            continue;
        };
        if poisoned.contains(&identity) {
            continue;
        }
        let conflicting = models.get(&identity).is_some_and(|existing| *existing != model);
        if conflicting {
            models.remove(&identity);
            poisoned.insert(identity);
            continue;
        }
        models.entry(identity).or_insert(model);
    }
    models
}

/// Trust: cheap scan for whether `body` contains any direct call terminator.
///
/// The callee-contract DB is built entirely from `Call`/`TailCall`
/// terminators, so a call-free body yields an empty DB on both passes. This
/// predicate gates a verdict-identical early-out.
fn body_has_call_terminator(body: &Body<'_>) -> bool {
    body.basic_blocks.iter().any(|bb| {
        matches!(
            &bb.terminator,
            Some(term)
                if matches!(
                    term.kind,
                    TerminatorKind::Call { .. } | TerminatorKind::TailCall { .. }
                )
        )
    })
}

fn build_callee_contract_summaries<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> trust_vcgen::SummaryDatabase {
    // Trust: empty-DB early-out (rank 16). Both summary passes below build the DB
    // exclusively from `Call` terminators, so a body with no calls produces an
    // empty `SummaryDatabase` either way. An empty callee-contract DB adds no
    // assumption to any caller-side VC, so returning early here is VERDICT-
    // IDENTICAL: no callee contract obligation or dyn summary is added or
    // dropped. It also skips the balanced `DYN_SUMMARY_IN_PROGRESS` insert/remove
    // churn (which has no observable effect when the loop body never runs). Gated
    // ONLY on "no calls" — nothing else.
    if !body_has_call_terminator(body) {
        return trust_vcgen::SummaryDatabase::new();
    }

    // Trust: shared contract-formula memo (rank 15). The dyn-dispatch and
    // direct-call passes can both query `extract_contract_formulas_for_def` for
    // the same callee `DefId`; memoizing the pure result for this DB build avoids
    // the redundant re-extraction without changing any produced summary.
    let mut memo = ContractFormulaMemo::default();
    let mut db = build_dyn_dispatch_summaries(tcx, body, &mut memo);
    add_direct_call_contract_summaries(tcx, body, &mut db, &mut memo);
    db
}

