/// Trust (assumption ledger): the skip reasons recorded as explicit unverified
/// assumption rows. Since the skip taxonomy (RECORD, THEN RULE in `run_pass`)
/// every policy records them: a nonfatal policy records and continues, and a
/// fail-closed policy records the row beside the build-failing error that
/// refuses the skip (memory-safe's no-unsafe demotions record and continue, as
/// before). A def the step-4 library lane narrowed records nothing. Deliberately excludes
/// `ContractGeneratedClosure`: it marks inherited compatibility machinery that
/// is never part of Trust's proof inventory and is never-a-gap in
/// `skip_is_full_verification_failure`, so it never reaches
/// this demotion question. Also excludes the dependency skips (crate-granularity ledger entries
/// produced by targo from the dep-TCB set, and their include-deps abort
/// contract is explicit). `UserOptOut` is included: every policy
/// must expose the user's assumption, and strict verification still refuses it
/// with an error beside the row.
fn skip_reason_is_recorded_assumption(reason: &TrustVerifySkipReason) -> bool {
    matches!(
        reason,
        TrustVerifySkipReason::TreatedAsAssumption(_)
            | TrustVerifySkipReason::UnreachableStart
            | TrustVerifySkipReason::UserOptOut
            | TrustVerifySkipReason::AssumedTotal
    )
}

/// Trust (2026-10-17, coverage identity): does a body declined for `reason`
/// publish the zero-obligation inventory envelope
/// ([`publish_zero_obligation_envelope`])?
///
/// Only `UninhabitedArgument`: a body no value can enter has zero obligations,
/// exactly like the lone-`unreachable` body `trust_note_coverage_early_out`
/// credits. Every other reason either publishes its own one envelope (an
/// `assumption:<tag>` row, [`skip_reason_is_recorded_assumption`]; the
/// `excluded:` harness row) or is not in the local proof inventory at all. The
/// match is exhaustive so a new reason has to answer this question.
fn skip_publishes_zero_obligation_envelope(reason: &TrustVerifySkipReason) -> bool {
    match reason {
        TrustVerifySkipReason::UninhabitedArgument => true,
        TrustVerifySkipReason::ExternalDependencyScope
        | TrustVerifySkipReason::NonLocalMir
        | TrustVerifySkipReason::ContractGeneratedClosure
        | TrustVerifySkipReason::TestHarnessSynthesized(_)
        | TrustVerifySkipReason::UnreachableStart
        | TrustVerifySkipReason::UserOptOut
        | TrustVerifySkipReason::AssumedTotal
        | TrustVerifySkipReason::TreatedAsAssumption(_) => false,
    }
}

/// Publish the ONE function envelope of a credited body that can never execute:
/// the zero-obligation inventory row (`transport_no_obligations_row`, the row
/// targo recognises exactly, `is_exact_zero_obligation_inventory_row`), under
/// the canonical `safe_def_path_str` identity the coverage inventory uses.
fn publish_zero_obligation_envelope(tcx: TyCtxt<'_>, local: LocalDefId, func_path: &str) {
    let row = transport_no_obligations_row();
    // Trust (T3 C05): the elision audit's verdict vector, in either output mode.
    audit_published_rows(tcx, local.to_def_id(), func_path, std::slice::from_ref(&row));
    if TrustOutputMode::parse(tcx.sess).emit_json() {
        emit_transport_json(tcx, Some(local), func_path, &[row], 0);
    }
}

/// Trust (assumption ledger): stable machine-readable tag for a
/// recorded-assumption skip. Delegates to `UnsupportedReason::tag()` for
/// classifier gaps; `unreachable-start` is pinned by a unit test.
fn skip_assumption_tag(reason: &TrustVerifySkipReason) -> &'static str {
    match reason {
        TrustVerifySkipReason::TreatedAsAssumption(r) => r.tag(),
        TrustVerifySkipReason::UnreachableStart => "unreachable-start",
        TrustVerifySkipReason::UserOptOut => "user-opt-out",
        TrustVerifySkipReason::AssumedTotal => "assumed-total",
        // Trust (CB4): not an assumption — never written as an `assumption:` row
        // (`skip_reason_is_recorded_assumption` is false) — but the skip census
        // keys its count on this tag, the same one the exclusion row carries.
        TrustVerifySkipReason::TestHarnessSynthesized(_) => {
            trust_types::exclusion::TEST_HARNESS_EXCLUSION_TAG
        }
        // Unreachable while `skip_reason_is_recorded_assumption` gates callers;
        // a stable fallback beats a panic in a diagnostics path.
        _ => "other",
    }
}

/// Trust (assumption ledger): the transport row for an unverified assumption.
/// Fail-closed labeling contract: `outcome` is the pre-existing `"skipped"`
/// wire value (counted unknown+skipped by every consumer, never proof);
/// `kind` is `assumption:<tag>` (never `no_obligations`, never `transport:*`
/// so it still counts as evidence the verifier ran); no field may contain
/// full-verifier marker text (`is_full_verifier_text` in targo would
/// misclassify the row as full-verifier evidence).
fn transport_assumption_row(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    tag: &str,
    detail: &str,
    solver: &str,
) -> TransportObligationResult {
    let reason_class = assumption_reason_class(tag);
    TransportObligationResult {
        assumes: Vec::new(),
        gap_class: None,
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: format!("assumption:{tag}"),
        original_vc_snapshot: None,
        typed_kind: None,
        description: format!("unverified assumption: {detail}"),
        location: Some(source_span_from_rustc_span(tcx, body.span)),
        outcome: Outcome::Skipped,
        solver: solver.to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some(format!(
            "{reason_class} `{tag}`: this function was NOT verified; \
             the crate's proof is conditional on it"
        )),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
        grade: None,
    }
}

const COROUTINE_PROTOCOL_ASSUMPTION_TAG: &str = "coroutine";
const COROUTINE_PROTOCOL_ASSUMPTION_DETAIL: &str = "coroutine resume-state executor protocol is assumed valid; supported user data-safety \
     obligations were still verified";

/// Whether this optimized MIR body contains one of rustc's three coroutine
/// executor-protocol sentinels. The allowlist is intentionally exact: null,
/// alignment, invalid-enum, and future assert kinds remain ordinary fail-closed
/// safety obligations in vcgen.
fn body_has_coroutine_protocol_assert(body: &Body<'_>) -> bool {
    count_coroutine_protocol_asserts(body) != 0
}

/// Exact count of the coroutine executor-protocol sentinels in this optimized
/// MIR body. The coroutine resume-state contract upgrade requires the bridge's
/// evidence to account for EVERY one of them (a pruned or dropped sentinel
/// withholds the contract row, fail-closed). Same exact allowlist as
/// [`body_has_coroutine_protocol_assert`].
fn count_coroutine_protocol_asserts(body: &Body<'_>) -> usize {
    body.basic_blocks
        .iter()
        .filter(|block| {
            matches!(
                &block.terminator().kind,
                TerminatorKind::Assert { msg, .. }
                    if matches!(
                        msg.as_ref(),
                        rustc_middle::mir::AssertKind::ResumedAfterReturn(_)
                            | rustc_middle::mir::AssertKind::ResumedAfterPanic(_)
                            | rustc_middle::mir::AssertKind::ResumedAfterDrop(_)
                    )
            )
        })
        .count()
}

/// Add exactly one coroutine-protocol assumption while preserving all real
/// verification rows. Every lane receives the same honest inventory; callers
/// separately decide whether explicit advisory policy may continue or strict /
/// memory-safe policy must reject the unproved premise.
fn rows_with_coroutine_protocol_assumption(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    let row_kind = format!("assumption:{COROUTINE_PROTOCOL_ASSUMPTION_TAG}");
    let mut out: Vec<_> = rows.iter().filter(|row| row.kind != row_kind).cloned().collect();
    let mut coroutine_row = transport_assumption_row(
        tcx,
        body,
        COROUTINE_PROTOCOL_ASSUMPTION_TAG,
        COROUTINE_PROTOCOL_ASSUMPTION_DETAIL,
        "trust-classifier",
    );
    coroutine_row.reason = Some(
        "coroutine executor-protocol assumption `coroutine`: supported user data-safety \
         obligations were verified; the crate's result remains conditional on correct executor use"
            .to_string(),
    );
    out.push(coroutine_row);
    out
}

/// The PURE publish decision for a coroutine body's executor-protocol premise
/// — the ONE seam that couples the bridge's entry resume-state `Assume`
/// (witnessed by `evidence`, minted only from the live lowered module) to a
/// published row. Structural invariant, enforced by this match shape rather
/// than by distant agreement between the bridge and this file: once evidence
/// exists for the function, `NotACoroutineResumeBody` (publish NOTHING) is
/// unreachable — the premise publishes either as the contract row or as the
/// assumption row (with the strict abort), EVEN IF the MIR sentinel count is
/// zero. The D1 defect was exactly the unpaired state this rules out: an
/// entry `Assume` narrowing the selector while no row (and no abort) ever
/// surfaced the pruned premise.
enum CoroutineProtocolPublishDecision {
    /// No `ResumedAfter*` sentinel in the MIR body AND no bridge contract
    /// engagement: not a coroutine resume body — publish nothing (nothing was
    /// assumed).
    NotACoroutineResumeBody,
    /// The authenticated evidence accounts for every MIR sentinel, every
    /// published row is statically proved with the sentinel proof visible, no
    /// UNMARKED row claims proof over the entry `Assume` (D2 part B), and the
    /// lane is the explicit ADVISORY one (D2 part A): publish the
    /// `contract:coroutine-resume-state` row.
    PublishContractRow,
    /// Every other engaged state: publish the fail-closed
    /// `assumption:coroutine` row (strict / memory-safe lanes then reject the
    /// unproved premise).
    PublishAssumptionRow,
}

/// `contract_publication_permitted` is [`TrustVerifyPolicy::is_explicit_advisory`]
/// — the D2 gate (part A).
///
/// THE D2 DEFECT, and why the gate is a POLICY gate rather than a stronger
/// evidence check. There is NO caller-side discharge lane for the exported
/// resume-state precondition: `crates/trust-ir-bridge/src/lower.rs` says so in
/// the obligation text it mints ("no caller-side discharge lane exists yet"),
/// and the callsite charge fires only for an in-bundle `Call` terminator whose
/// callee signature carries `coroutine_resume_contract`. The REAL caller of an
/// `async fn` body is the generated `Future::poll` shim plus an executor that
/// lives in another crate — and Targo compiles every dependency unit with
/// `-Ztrust-verify=off`. Measured: a cross-crate consumer under strict
/// verification receives NO resume-precondition obligation, and neither does an
/// in-crate `async fn` caller. So in a fail-closed lane, publishing a contract
/// row converts an UNDISCHARGED premise into SILENCE: the build goes green with
/// nothing, anywhere, obliged to establish the premise.
///
/// `pub async fn tick(x: u32) -> u32 { x }` under default strict policy
/// therefore reported "2 proved … of which 2 kernel-certified", exit 0, while a
/// two-poll driver panicked `` `async fn` resumed after completion `` at the
/// exact span of the row certified "panic freedom: no assertion,
/// `unreachable!`, or panic is reachable".
///
/// Fail-closed lanes get the assumption row and
/// `abort_on_coroutine_protocol_assumption` back. `ContractPublished` survives
/// for the explicit advisory lane, which makes no proof claim and exists to
/// report conditional evidence — the feature is GATED, not deleted.
fn coroutine_protocol_publish_decision(
    sentinel_count: usize,
    evidence: Option<&trust_ir_bridge::CoroutineResumeContractModuleEvidence>,
    rows_all_statically_proved: bool,
    sentinel_proof_visible: bool,
    contract_publication_permitted: bool,
    no_unmarked_conditional_proof: bool,
) -> CoroutineProtocolPublishDecision {
    match evidence {
        None if sentinel_count == 0 => CoroutineProtocolPublishDecision::NotACoroutineResumeBody,
        Some(evidence)
            if evidence.sentinel_obligation_count == sentinel_count
                && rows_all_statically_proved
                && sentinel_proof_visible
                // D2 part A: a fail-closed lane may not publish a contract
                // whose premise no caller is obliged to discharge.
                && contract_publication_permitted
                // D2 part B: and no row may have silently consumed the entry
                // `Assume` while still claiming bare `Proved`.
                && no_unmarked_conditional_proof =>
        {
            CoroutineProtocolPublishDecision::PublishContractRow
        }
        // Sentinels with no (or mismatched) evidence, unproved rows, invisible
        // sentinel proofs, a fail-closed lane, an unmarked conditional proof —
        // and the D1 arm: evidence with zero MIR sentinels.
        _ => CoroutineProtocolPublishDecision::PublishAssumptionRow,
    }
}

/// D2 part B — the structural half. The bridge injects
/// `Assume(resume_state ∈ live_states)` at the coroutine body's ENTRY
/// (`crates/trust-ir-bridge/src/lower.rs`), and entry DOMINATES every block, so
/// EVERY obligation discharged in that body is conditional on the
/// executor-protocol premise — not merely the sentinels.
///
/// The bridge marks the sentinel rows it mints
/// (`COROUTINE_RESUME_CONTRACT_OBLIGATION_PREFIX`), and those are conditional BY
/// DESIGN: describing them is what the contract row is FOR. Any OTHER row
/// claiming `Outcome::Proved` in such a body is a proof that consumed the entry
/// `Assume` without saying so — measured on the exhibit, the whole-function
/// panic-freedom aggregate carried a CIC term and context BYTE-IDENTICAL to the
/// sentinel row's, i.e. the same ex-falso derivation from
/// `resume_state = 0 ∧ resume_state = 1`, and still reported `proved` /
/// `Certified` / `KernelRechecked` / `axiom_closure: Empty`.
///
/// `axiom_closure: Empty` is LITERALLY TRUE of that term — ex falso quodlibet
/// needs no axiom — and MATERIALLY MISLEADING about the obligation, because the
/// premise was not an axiom the kernel could see: it had been baked into the
/// hypothesis CONTEXT the kernel was handed. The kernel did its job faithfully.
///
/// So this predicate refuses the contract upgrade whenever an unmarked row
/// claims proof, and `stamp_coroutine_conditional_rows` puts the marker on the
/// row itself so the leak cannot recur through a different lane.
fn coroutine_rows_free_of_unmarked_conditional_proof(
    rows: &[TransportObligationResult],
    evidence: &trust_ir_bridge::CoroutineResumeContractModuleEvidence,
) -> bool {
    rows.iter().all(|row| {
        row.outcome != Outcome::Proved
            || row.design_mandate
            || row_is_marked_coroutine_sentinel(row, evidence)
    })
}

/// Whether `row` is one of the bridge-marked sentinel rows for `evidence` — the
/// rows whose conditionality the contract row exists to state. Matched against
/// the rendered description, stripping exactly the `VcKind::Assertion` renderer
/// prefix and no other (same convention as
/// `rows_exhibit_coroutine_sentinel_proof`).
fn row_is_marked_coroutine_sentinel(
    row: &TransportObligationResult,
    evidence: &trust_ir_bridge::CoroutineResumeContractModuleEvidence,
) -> bool {
    trust_types::assumption::parse_coroutine_resume_contract_obligation_description(
        row.description.strip_prefix("assertion: ").unwrap_or(&row.description),
    )
    .is_some_and(|(states, _)| states == evidence.live_states)
}

/// D2 part B — put the marker ON THE ROW THAT CONSUMED THE ASSUME.
///
/// Every `Proved` row in a contract-engaged coroutine body is conditional on the
/// entry `Assume` (see [`coroutine_rows_free_of_unmarked_conditional_proof`]).
/// The bridge-marked sentinel rows already say so in their description; this
/// rewrites every OTHER proved row so it can no longer be mistaken — by a
/// consumer, a report, or a future lane — for an unconditional proof:
///
///  * `kind` gains [`COROUTINE_RESUME_CONDITIONAL_ROW_KIND_PREFIX`], keeping the
///    original kind after the prefix so the row keeps its diagnostic identity;
///  * `outcome` drops from `Proved` to `Skipped` — targo's
///    `partition_outcome_counts` buckets the row as `assumed` and grants it no
///    proof credit, which is the link that was missing (the aggregate's `kind`
///    was `assert`, its `outcome` was `proved`, and NOTHING tied it to the
///    sibling `contract:coroutine-resume-state` row that carried the
///    conditionality);
///  * `proof_evidence` is STRIPPED. The `Certified` / `KernelRechecked` grade
///    described an unconditional discharge of a formula whose hypothesis context
///    already contained the premise; retaining it next to a conditional outcome
///    would reproduce the exact ambiguity this closes;
///  * `original_vc_snapshot` is cleared. The synthetic conditional row no longer
///    publishes the original claim's classification, so it must not retain that
///    claim's offline replay sidecar.
///
/// Design-mandate rows are inventory, never discharge targets, and are left
/// alone.
///
/// # `evidence: None`
///
/// The premise the rows are decided under is derived from the BODY, not from
/// this evidence: `trust_vcgen`'s `build_coroutine_resume_state_facts` publishes
/// `selector ∈ live_states` off its own recognizer. So `evidence: None` does not
/// mean "nothing is conditional here", and skipping the stamp on `None` would
/// ship those rows as bare `Outcome::Proved` — the unmarked conditional proof
/// [`coroutine_rows_free_of_unmarked_conditional_proof`] exists to prevent.
///
/// The stamp therefore fires whatever the evidence, and the fail-closed
/// direction is what makes over-firing safe: the map below only ever demotes
/// `Proved` to `Skipped` and strips `proof_evidence`, so a row it need not have
/// touched loses proof credit and can never gain any.
///
/// With evidence, a bridge-marked sentinel row keeps its exemption: its state
/// set is checked against the authenticated evidence. Without evidence there is
/// no authenticated set to check a marker against, so the row's own description
/// is unauthenticated public text and buys no exemption — every proved row is
/// stamped. That is the same doctrine this file applies to every other
/// serialized hint.
fn stamp_coroutine_conditional_rows(
    rows: &[TransportObligationResult],
    evidence: Option<&trust_ir_bridge::CoroutineResumeContractModuleEvidence>,
) -> Vec<TransportObligationResult> {
    rows.iter()
        .map(|row| {
            if row.outcome != Outcome::Proved
                || row.design_mandate
                || evidence.is_some_and(|evidence| row_is_marked_coroutine_sentinel(row, evidence))
            {
                return row.clone();
            }
            let mut out = row.clone();
            out.kind = trust_types::assumption::coroutine_resume_conditional_row_kind(&row.kind);
            out.outcome = Outcome::Skipped;
            out.proof_evidence = None;
            out.original_vc_snapshot = None;
            // Trust (VF1): the row now rests on the executor-protocol premise,
            // so its grade names it; a row no authority graded stays ungraded.
            out.grade = out.grade.take().map(|grade| {
                grade.with_premise(trust_types::authority_grade::GradePremise::ExecutorProtocol)
            });
            out.reason =
                Some(trust_types::assumption::COROUTINE_RESUME_CONDITIONAL_ROW_REASON.to_string());
            out
        })
        .collect()
}

/// How a coroutine body's executor-protocol premise publishes.
enum CoroutineProtocolDisposition {
    /// The bridge converted EVERY sentinel to a refutable obligation under the
    /// recognized resume-state contract AND every published row is statically
    /// proved: the premise publishes as a `contract:coroutine-resume-state`
    /// row (verified-modulo-callers).
    ///
    /// CORRECTED 2026-08-20 (D2): this variant no longer means "and strict does
    /// NOT abort", because it is no longer REACHABLE from a fail-closed lane —
    /// it is explicit-advisory-only. Publishing a conditional row in a lane that
    /// makes a proof claim, while no caller anywhere is obliged to discharge the
    /// premise, is what produced the false `Certified` verdict on
    /// `pub async fn tick(x: u32) -> u32 { x }`.
    ContractPublished(Vec<TransportObligationResult>),
    /// Today's fail-closed path: exactly one additive `assumption:coroutine`
    /// skipped row; strict and memory-safe lanes reject the unproved premise.
    UnprovedAssumption(Vec<TransportObligationResult>),
}

/// Decide how this coroutine body's protocol premise publishes. `None` ONLY
/// when the body carries no `ResumedAfter*` sentinel AND the bridge's contract
/// lane never engaged (no authenticated evidence for this function) — i.e. not
/// a coroutine resume body. Once evidence exists, the routing through
/// [`coroutine_protocol_publish_decision`] structurally guarantees a published
/// row: contract, or assumption + strict abort (the D1 coupling).
///
/// The upgrade to [`CoroutineProtocolDisposition::ContractPublished`] requires
/// ALL of (fail-closed on each):
///  1. the bridge's authenticated module evidence
///     (`artifacts.coroutine_resume_contract`, minted only from the live native
///     bundle — never transport text, never re-pattern-matched MIR);
///  2. the evidence accounting for EXACTLY the MIR body's sentinel count (a
///     pruned/dropped sentinel keeps the assumption + abort);
///  3. every published row statically PROVED (post-demotion `Outcome::Proved`;
///     design-mandate inventory rows excepted) — the sentinel obligations are
///     real refutable rows now, so an unproved/refuted sentinel blocks here;
///  4. the sentinel proof VISIBLE among the rows as per-sentinel marker rows
///     matching the evidence count and state set — the anti-silent-drop belt:
///     "all rows proved" must never be vacuously true because the solver never
///     saw the sentinels (the R3 counted-carrier fail-open class);
///  5. `contract_publication_permitted` — the explicit ADVISORY lane only (D2
///     part A): no caller-side discharge lane exists, so a fail-closed lane
///     publishing this row would turn an undischarged premise into silence;
///  6. no UNMARKED row claiming `Proved` (D2 part B): every proof in this body
///     consumed the entry `Assume`, and only the bridge-marked sentinel rows
///     are allowed to be conditional without saying so on the row.
fn coroutine_protocol_disposition(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
    artifacts: &VerificationArtifacts,
    func_path: &str,
    contract_publication_permitted: bool,
) -> Option<CoroutineProtocolDisposition> {
    let sentinel_count = count_coroutine_protocol_asserts(body);
    // Evidence is only ever consulted for THIS function; another bundled
    // coroutine's evidence neither publishes nor suppresses anything here.
    let evidence = artifacts
        .coroutine_resume_contract
        .as_ref()
        .filter(|evidence| evidence.function_def_path == func_path);
    let decision = coroutine_protocol_publish_decision(
        sentinel_count,
        evidence,
        coroutine_contract_rows_all_statically_proved(rows),
        evidence.is_some_and(|evidence| rows_exhibit_coroutine_sentinel_proof(rows, evidence)),
        contract_publication_permitted,
        evidence.is_none_or(|evidence| {
            coroutine_rows_free_of_unmarked_conditional_proof(rows, evidence)
        }),
    );
    match decision {
        CoroutineProtocolPublishDecision::NotACoroutineResumeBody => None,
        CoroutineProtocolPublishDecision::PublishContractRow => {
            // Trust: PublishContractRow is only produced with evidence present.
            // Decline to publish rather than aborting the compiler if it is not.
            let Some(evidence) = evidence else {
                return None;
            };
            // Strip any pre-existing row that CLAIMS the published kinds (only
            // this seam may mint them), then publish the single contract row.
            let contract_kind = trust_types::assumption::COROUTINE_RESUME_CONTRACT_ROW_KIND;
            let assumption_kind = format!("assumption:{COROUTINE_PROTOCOL_ASSUMPTION_TAG}");
            let mut out: Vec<TransportObligationResult> = rows
                .iter()
                .filter(|row| row.kind != contract_kind && row.kind != assumption_kind)
                .cloned()
                .collect();
            out.push(coroutine_resume_contract_transport_row(tcx, body, evidence));
            Some(CoroutineProtocolDisposition::ContractPublished(out))
        }
        CoroutineProtocolPublishDecision::PublishAssumptionRow => {
            // D2 part B: stamp before adding the assumption row, so a row that
            // consumed the entry `Assume` cannot ship as bare `Proved` /
            // `Certified` even in the lane that merely RECORDS the premise.
            //
            // UNCONDITIONALLY, including when `evidence` is `None`.
            // `coroutine_protocol_publish_decision` reaches this arm only when
            // the bridge published evidence OR the MIR body carries a
            // `ResumedAfter*` sentinel, and the premise those rows are decided
            // under is derived from the BODY. Keying the stamp on the evidence
            // would key it on a different signal from the one that injects the
            // premise, so an evidence-less path would ship bare `Proved` rows of
            // a body whose proofs were conditional. See
            // `stamp_coroutine_conditional_rows`.
            let stamped = stamp_coroutine_conditional_rows(rows, evidence);
            Some(CoroutineProtocolDisposition::UnprovedAssumption(
                rows_with_coroutine_protocol_assumption(tcx, body, &stamped),
            ))
        }
    }
}

/// Every row statically proved (post-demotion), so the coroutine body's whole
/// obligation surface — including the now-refutable sentinel obligations —
/// carries real proof. Design-mandate rows are inventory, not discharge
/// targets (their violation formula is the tautology `true`), mirroring
/// `extern_call_demotion_others_all_proved`. Empty row sets DECLINE: a
/// zero-row coroutine body means the sentinel obligations never surfaced.
fn coroutine_contract_rows_all_statically_proved(rows: &[TransportObligationResult]) -> bool {
    !rows.is_empty() && rows.iter().all(|row| row.design_mandate || row.outcome == Outcome::Proved)
}

/// The anti-silent-drop belt for the contract upgrade: the sentinel proof must
/// be VISIBLE in the published rows as every bridge-marked sentinel obligation
/// carrying its own PROVED row, with the count equal to the evidence's and the
/// marker's live-state set equal to the evidence's.
///
/// THE AGGREGATE FALLBACK IS DELETED, NOT REPAIRED. It accepted "the
/// whole-function panic-freedom AGGREGATE row is proved" as a stand-in, on the
/// theory that the aggregate subsumes the per-site sentinel asserts. It does
/// not: measured on the real fixture, that row's `Proved` came from the
/// INTERPROCEDURAL panic-freedom rule, whose site enumeration (obligations +
/// `Terminator::Call`) cannot see a sentinel `Terminator::Assert` at all and is
/// vacuously satisfied by a call-free resume body. Accepting it would make the
/// contract vacuous — exactly the R3 counted-carrier fail-open this belt exists
/// to prevent. The per-sentinel marker rows are the only accepted evidence.
///
/// The marker is matched against the row's rendered description, which carries
/// `VcKind::Assertion`'s `"assertion: "` renderer prefix
/// (`trust_types::formula::vc_kind`); strip exactly that one prefix before
/// parsing, and no other.
fn rows_exhibit_coroutine_sentinel_proof(
    rows: &[TransportObligationResult],
    evidence: &trust_ir_bridge::CoroutineResumeContractModuleEvidence,
) -> bool {
    // An evidence set that accounts for no sentinel cannot be witnessed by
    // "zero marker rows found": fail closed rather than let 0 == 0 pass.
    if evidence.sentinel_obligation_count == 0 {
        return false;
    }
    let marked_proved = rows
        .iter()
        .filter(|row| {
            row.outcome == Outcome::Proved
                && trust_types::assumption::parse_coroutine_resume_contract_obligation_description(
                    row.description.strip_prefix("assertion: ").unwrap_or(&row.description),
                )
                .is_some_and(|(states, _)| states == evidence.live_states)
        })
        .count();
    marked_proved == evidence.sentinel_obligation_count
}

/// The published `contract:coroutine-resume-state` row. `Outcome::Skipped` on
/// the wire — a published contract is conditional evidence, never solver proof
/// credit — with the exact kind/solver/reason triple targo's fail-closed shape
/// check requires (a hand-built row that merely claims the kind cannot green).
fn coroutine_resume_contract_transport_row(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    evidence: &trust_ir_bridge::CoroutineResumeContractModuleEvidence,
) -> TransportObligationResult {
    TransportObligationResult {
        assumes: Vec::new(),
        gap_class: None,
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: trust_types::assumption::COROUTINE_RESUME_CONTRACT_ROW_KIND.to_string(),
        original_vc_snapshot: None,
        typed_kind: None,
        description: trust_types::assumption::coroutine_resume_contract_row_description(
            &evidence.live_states,
        ),
        location: Some(source_span_from_rustc_span(tcx, body.span)),
        outcome: Outcome::Skipped,
        solver: trust_types::assumption::COROUTINE_RESUME_CONTRACT_ROW_SOLVER.to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some(trust_types::assumption::COROUTINE_RESUME_CONTRACT_ROW_REASON.to_string()),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
        grade: None,
    }
}

/// Reject the unproved coroutine executor-protocol premise in every fail-closed
/// lane. This runs only after human result reporting and JSON transport emission,
/// so the premise never masks or replaces genuine arithmetic/bounds/refutation
/// evidence from the same coroutine body.
fn abort_on_coroutine_protocol_assumption(tcx: TyCtxt<'_>, body: &Body<'_>, func_path: &str) {
    publication_contracts::prepare_coroutine_protocol_assumption(tcx, body, func_path).emit(tcx);
}

fn transport_row_is_coroutine_protocol_assumption(row: &TransportObligationResult) -> bool {
    row.kind.strip_prefix("assumption:") == Some(COROUTINE_PROTOCOL_ASSUMPTION_TAG)
        && row.outcome == Outcome::Skipped
        && row.solver == "trust-classifier"
        && !row.design_mandate
        && row.native_trust_ir.is_none()
        && row.proof_evidence.is_none()
}

// ---------------------------------------------------------------------------
// §5 STEP 5 — `GlobalAlloc::dealloc` as a checked caller contract.
//
// Plan of record (docs/design/2026-08-19-verified-sysroot-scoping.md, §5 step
// 5): "publish a `contract:global-alloc-dealloc-panic-free` row, charge every
// allocation-owning drop, block `register_proven_panic_free` for bodies that
// rely on it, and discharge it at the `#[global_allocator]` impl (or vacuously
// when there is none and `Global` is used, which *is* verifiable because
// `Global::dealloc`'s body is in `alloc`)."
//
// This is the coroutine-resume-state contract shape at its cheapest point.
// The premise being named: the drop classifier
// (`trust-ir-bridge::is_std_owning_or_scaffold` and its callers) discharges
// the drop glue of std OWNING containers, whose glue DEALLOCATES through the
// global allocator — so every such discharge silently assumed that
// `GlobalAlloc::dealloc` never panics. With the default `Global` allocator
// that assumption is checkable by inspection: the whole in-`alloc` chain
// (`Global::deallocate` → `deallocate_impl_runtime` → `dealloc_nonnull` →
// `__rust_dealloc`, library/alloc/src/alloc.rs; the std default handler
// `__rdl_dealloc` → `System.dealloc` → `libc::free`,
// library/std/src/alloc.rs:460 / sys/alloc/unix.rs:47) contains no panic
// path. With a USER `#[global_allocator]` it is FALSE in general — a
// panicking `dealloc` makes every allocation-owning drop able to panic.
//
// SLICE IMPLEMENTED HERE (the smallest sound one): publish + charge +
// vacuous-`Global` discharge. The user-allocator case fails CLOSED (strict
// abort; advisory records the refused row): no lane verifies the user
// `dealloc` impl body and discharges the contract at it yet. That discharge
// lane is the deliberate stopping point of this step's first landing.
//
// Info-flow note: unlike the coroutine contract, the reliance signal is
// computed COMPILER-SIDE from the optimized MIR (`TerminatorKind::Drop` +
// the type's transitive field closure), never parsed out of bridge transport
// rows — so there is no forgeable text channel, and the detector
// OVER-approximates (a charged body whose drop the bridge in fact declined is
// charged anyway; conservative, never fail-open).

/// The published row kind. Kept in exact-string form (not built at the call
/// sites) so the forgery-strip in [`global_alloc_dealloc_disposition`] and
/// the row mint cannot drift apart.
const GLOBAL_ALLOC_DEALLOC_CONTRACT_ROW_KIND: &str =
    trust_types::assumption::GLOBAL_ALLOC_DEALLOC_CONTRACT_ROW_KIND;

/// The REFUSED spelling of the row kind. A distinct kind (not a reason-text
/// convention) so every lane gate distinguishes the two states structurally:
/// the discharged kind is admissible conditional evidence; the refused kind is
/// an unproved premise that keeps fail-closed lanes fail-closed.
const GLOBAL_ALLOC_DEALLOC_CONTRACT_REFUSED_ROW_KIND: &str =
    trust_types::assumption::GLOBAL_ALLOC_DEALLOC_CONTRACT_REFUSED_ROW_KIND;

/// The def-path fragments of the std/alloc ALLOCATION-OWNING types — the
/// subset of the bridge's `is_std_owning_or_scaffold` PARTS whose drop glue
/// performs a `GlobalAlloc::dealloc` (owning containers and the `Global`
/// handle itself). Deliberately EXCLUDES the non-allocating entries of that
/// allowlist (`Option`/`Result`, `PhantomData`, atomics/cells,
/// `array::IntoIter`, `NonNull`/`Unique` scaffold): their drop deallocates
/// nothing, so charging them would be pure noise. Matching is
/// crate-prefix-gated + substring, mirroring the bridge exactly, so producer
/// (bridge acceptance) and consumer (this charge) use the same name algebra.
fn adt_path_is_global_alloc_owning(path: &str) -> bool {
    if !(path.starts_with("std::") || path.starts_with("alloc::") || path.starts_with("core::")) {
        return false;
    }
    const ALLOC_OWNING_PARTS: &[&str] = &[
        "::vec::Vec",
        "::vec::IntoIter",
        "::vec::into_iter::",
        "::string::String",
        "::boxed::Box",
        "::collections::",
        "::raw_vec::RawVec",
        "::sync::Arc",
        "::rc::Rc",
        "::path::PathBuf",
        "::ffi::OsString",
        "::os_str::",
        "::alloc::Global",
    ];
    ALLOC_OWNING_PARTS.iter().any(|p| path.contains(p))
}

/// Does this body make any call that could reach an allocation — any call to a
/// NON-LOCAL callee, or through a value (fn pointer / closure) whose target this
/// walk cannot name? Conservative on purpose: it only matters when a user
/// `#[global_allocator]` is in the graph, and there every allocating sysroot
/// routine (bundled or absent) runs that allocator's unverified `alloc`.
fn body_has_non_local_call<'tcx>(body: &Body<'tcx>) -> bool {
    body.basic_blocks.iter().any(|bb| match &bb.terminator {
        Some(Terminator { kind: TerminatorKind::Call { func, .. }, .. })
        | Some(Terminator { kind: TerminatorKind::TailCall { func, .. }, .. }) => {
            func.const_fn_def().is_none_or(|(def_id, _)| !def_id.is_local())
        }
        _ => false,
    })
}

/// Does this body drop a value whose type (transitive field closure) reaches
/// an allocation-owning std container? Such a drop's panic-freedom — whether
/// the bridge's classifier discharged it or declined it — rests on
/// `GlobalAlloc::dealloc` never panicking, so the body is CHARGED the
/// `contract:global-alloc-dealloc-panic-free` premise.
///
/// OVER-approximates, on purpose, in exactly two ways, both conservative:
///  * it does not re-run the bridge's accept/decline decision (a declined
///    drop already carries an honest unproved row; charging it again cannot
///    fail open), and it descends through `ManuallyDrop`/`MaybeUninit` and
///    dead enum variants that the classifier would skip;
///  * fuel exhaustion and the visited-set truncating a pathological type
///    graph CHARGE (return true) rather than exonerate.
fn body_has_alloc_owning_drop<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    /// Defense-in-depth bound; a real monomorphized field graph is finite and
    /// the visited set already terminates it.
    const ALLOC_OWNING_DROP_WALK_FUEL: u32 = 4096;
    let typing_env = ty::TypingEnv::post_analysis(tcx, body.source.def_id());
    let mut worklist: Vec<(Ty<'tcx>, u32)> = Vec::new();
    for block in body.basic_blocks.iter() {
        let TerminatorKind::Drop { place, .. } = &block.terminator().kind else {
            continue;
        };
        let drop_ty = place.ty(&body.local_decls, tcx).ty;
        let drop_ty = tcx.normalize_erasing_regions(typing_env, ty::Unnormalized::new_wip(drop_ty));
        worklist.push((drop_ty, ALLOC_OWNING_DROP_WALK_FUEL));
    }
    let mut visited: FxHashSet<Ty<'tcx>> = FxHashSet::default();
    while let Some((ty, fuel)) = worklist.pop() {
        let Some(child_fuel) = fuel.checked_sub(1) else {
            // Fuel-bail CHARGES: an unexplorable tree is treated as relying on
            // the contract, never as free of it.
            return true;
        };
        if !visited.insert(ty) {
            continue;
        }
        if let ty::Adt(adt_def, _) = ty.kind()
            && adt_path_is_global_alloc_owning(&trust_mir_extract::safe_def_path_str(
                tcx,
                adt_def.did(),
            ))
        {
            return true;
        }
        for component in structural_drop_component_types(tcx, typing_env, ty) {
            worklist.push((component, child_fuel));
        }
    }
    false
}

/// Is a USER allocator in the crate graph in view — a `#[global_allocator]`
/// registered anywhere, or a crate that DEFINES a libc allocator symbol std's
/// `System` allocator calls (`crate_graph_system_allocator_interposer`)?
/// `has_global_allocator` is the metadata-authenticated per-crate fact the
/// allocator shim itself is built from — never a name or attribute re-scan. When
/// this is false, every `GlobalAlloc::{alloc,dealloc}` reachable from this
/// compilation is the std default chain (see the module comment above), which is
/// panic-free by inspection of its `alloc`/`std` bodies down to the platform's
/// `malloc`/`free`.
fn crate_graph_registers_user_global_allocator(tcx: TyCtxt<'_>) -> bool {
    crate_graph_registers_global_allocator_attr(tcx)
        || crate_graph_system_allocator_interposer(tcx).is_some()
}

fn crate_graph_registers_global_allocator_attr(tcx: TyCtxt<'_>) -> bool {
    tcx.has_global_allocator(LOCAL_CRATE)
        || tcx.crates(()).iter().any(|&cnum| tcx.has_global_allocator(cnum))
}

/// The interposer when the user allocator in view is ONLY a `System` symbol
/// interposer (no `#[global_allocator]`), for the row and abort text.
fn user_allocator_interposer_only(tcx: TyCtxt<'_>) -> Option<SystemAllocatorInterposer> {
    if crate_graph_registers_global_allocator_attr(tcx) {
        None
    } else {
        crate_graph_system_allocator_interposer(tcx)
    }
}

/// Trust (2026-10-03): how a crate in the graph can replace a libc allocator symbol
/// std's `System` allocator calls (`crate_graph_system_allocator_interposer`).
#[derive(Clone, Copy, Debug)]
enum SystemAllocatorInterposer {
    /// `krate` defines a Rust item (`#[no_mangle]` or `#[export_name]`) whose link
    /// name is `symbol`, one of [`SYSTEM_ALLOCATOR_LINK_SYMBOLS`].
    Symbol { krate: rustc_span::Symbol, symbol: rustc_span::Symbol },
    /// `krate` holds global assembly — a `global_asm!` item that is not a Clean
    /// island — which can define any symbol, these included, with no Rust item to
    /// carry the name (review of 2026-10-03, measured: a dependency whose
    /// `global_asm!` defines `_malloc` as a pass-through to the malloc zone API left
    /// `Box::new(T[i & 1])` credited `bounds: proved` with no premise row, built with
    /// codegen, the executable's own `_malloc` in `nm`).
    GlobalAsm { krate: rustc_span::Symbol },
}

impl SystemAllocatorInterposer {
    /// "crate `k` defines `malloc`, a libc allocator symbol std's default `System`
    /// allocator calls" — the clause every row, human line and abort shares.
    fn clause(self) -> String {
        match self {
            SystemAllocatorInterposer::Symbol { krate, symbol } => format!(
                "crate `{krate}` defines `{symbol}`, a libc allocator symbol std's default \
                 `System` allocator calls"
            ),
            SystemAllocatorInterposer::GlobalAsm { krate } => format!(
                "crate `{krate}` holds global assembly (`global_asm!`), which can define a libc \
                 allocator symbol std's default `System` allocator calls"
            ),
        }
    }

    /// The short form for the row's `reason`.
    fn reason(self) -> String {
        match self {
            SystemAllocatorInterposer::Symbol { krate, symbol } => format!(
                "global-alloc dealloc contract refused (fail-closed): crate `{krate}` defines \
                 the `System` allocator symbol `{symbol}`, no lane verifies it"
            ),
            SystemAllocatorInterposer::GlobalAsm { krate } => format!(
                "global-alloc dealloc contract refused (fail-closed): crate `{krate}` holds \
                 global assembly, which can define a `System` allocator symbol; no lane \
                 verifies it"
            ),
        }
    }
}

/// The libc allocator entry points std's `System` allocator calls on a unix-family
/// target (`library/std/src/sys/alloc/unix.rs`: `malloc`, `calloc`, `realloc`,
/// `free`, `posix_memalign`; `memalign` on horizon/vita), plus the other C allocation
/// entry points of the same family (`aligned_alloc`, `valloc`). One set for every
/// target: a name that `System` does not call on this target only over-charges.
/// Windows' `System` calls `HeapAlloc` & co. through import thunks, which a
/// definition in a Rust crate does not replace.
const SYSTEM_ALLOCATOR_LINK_SYMBOLS: &[&str] = &[
    "malloc",
    "calloc",
    "realloc",
    "free",
    "posix_memalign",
    "aligned_alloc",
    "memalign",
    "valloc",
];

/// Is `name` — a definition's link name (`#[no_mangle]` item name or
/// `#[export_name]`) — one of [`SYSTEM_ALLOCATOR_LINK_SYMBOLS`]? A leading `\x01`
/// (LLVM's "emit this name verbatim" marker) and leading underscores are ignored, so
/// `#[export_name = "\x01_malloc"]` (which IS `malloc` on a target whose C symbols
/// carry a `_` prefix) is caught; on other targets that only over-charges.
fn is_system_allocator_link_symbol(name: &str) -> bool {
    let bare = name.trim_start_matches('\u{1}').trim_start_matches('_');
    SYSTEM_ALLOCATOR_LINK_SYMBOLS.contains(&bare)
}

thread_local! {
    /// Memo of [`crate_graph_system_allocator_interposer`] per compilation (keyed by
    /// the local `StableCrateId`): the answer is a property of the crate graph, and
    /// the question is asked for every verified body and every vanilla-class decision.
    static SYSTEM_ALLOCATOR_INTERPOSER_MEMO: std::cell::RefCell<
        FxHashMap<u64, Option<SystemAllocatorInterposer>>,
    > = std::cell::RefCell::new(FxHashMap::default());
}

/// Trust (2026-10-03): the first crate in the graph — this one, or a dependency —
/// that DEFINES one of the libc allocator symbols std's `System` allocator calls, or
/// can define one in global assembly ([`SystemAllocatorInterposer`]). std's default
/// global allocator is `System`, and `System` calls `malloc`/`free`/… by their C
/// names; a Rust definition of one of those
/// names linked into the artifact replaces the platform's for those calls (the
/// static linker binds an executable's own references to its own definition before
/// a shared library's). So unverified code runs inside every allocation and every
/// dealloc of the default chain: exactly the channel a user `#[global_allocator]`
/// opens, and it is charged the same way (`crate_graph_registers_user_global_allocator`).
///
/// MEASURED before this (stage 1 of origin/main `57121fb6713`, m3): a binary that
/// itself defines `#[no_mangle] extern "C" fn malloc/calloc/realloc/free/
/// posix_memalign` (each forwarding unchanged to the platform allocator; `nm` shows
/// the executable's own `_malloc`) credited `Box::new(T[i & 1])` and
/// `String::from(T[i & 1] as char)` with no premise row (`functions_verified` 4 of 15
/// — the build failed only on the forwarders' own unsafe bodies). With the same
/// forwarders in a verify-off DEPENDENCY (`#[no_mangle]`, or `#[export_name =
/// "malloc"]`) nothing was credited, but not by this contract: the spawn census
/// answered UNKNOWN for every function of the binary, `x / 2` included, because an
/// exported symbol that calls foreign code joins the pool of what MIR-less Rust (the
/// allocator) may call. That refusal answers the census's question, not this one;
/// this charge states the premise that is actually broken.
///
/// The link name is read the way `trust_mir_extract::concurrency_effects`'s symbol
/// table reads it: `codegen_fn_attrs(def).symbol_name` (`#[export_name]`) or, under
/// `NO_MANGLE`, the item name; foreign items (declarations) are skipped. This crate's
/// definitions come from its HIR inventory. A dependency's come from EVERY def in its
/// metadata, not from `exported_non_generic_symbols`: that list is empty for a crate
/// compiled without codegen (`symbol_export.rs` returns `&[]` when
/// `!should_codegen()`), while `codegen_fn_attrs` is encoded for every def that has
/// them (measured: reading that list instead, `dep_metadata_only` of
/// `tests/ui/trust/policy_b/system_allocator_symbol_is_a_user_allocator.rs` built exit
/// 0). Sysroot crates are skipped (they ARE the platform runtime `System` is
/// credited against), and so are crates loaded only for their macros (a proc-macro
/// crate is not linked into the artifact).
///
/// Global assembly is read the same way, per def: a `DefKind::GlobalAsm` def that is
/// not a Clean island (`trust_def_is_clean_island`, which has a dependency arm in
/// metadata; an island shares the def kind and emits no code) can define any symbol,
/// so it counts — the rule the certified-monitor surface checks
/// (`rustc_driver_impl`) and the spawn census (design §14) already apply to assembly.
///
/// Not seen, and recorded as residual in `docs/KNOWN_HAZARDS.md`: a non-Rust object
/// (a C static library, a `cc`-built `-sys` crate) defining the symbol, assembly
/// inside a function body (`asm!`, `naked_asm!`) that defines one, and the process
/// environment (`LD_PRELOAD`, `DYLD_INSERT_LIBRARIES`).
fn crate_graph_system_allocator_interposer(tcx: TyCtxt<'_>) -> Option<SystemAllocatorInterposer> {
    use rustc_hir::def::DefKind;
    use rustc_middle::middle::codegen_fn_attrs::CodegenFnAttrFlags;
    let key = tcx.stable_crate_id(LOCAL_CRATE).as_u64();
    if let Some(known) =
        SYSTEM_ALLOCATOR_INTERPOSER_MEMO.with(|memo| memo.borrow().get(&key).copied())
    {
        return known;
    }
    let interposer = |def: DefId, krate: rustc_span::Symbol| -> Option<SystemAllocatorInterposer> {
        match tcx.def_kind(def) {
            DefKind::GlobalAsm => (!tcx.trust_def_is_clean_island(def))
                .then_some(SystemAllocatorInterposer::GlobalAsm { krate }),
            DefKind::Fn | DefKind::AssocFn | DefKind::Static { .. }
                if !tcx.is_foreign_item(def) =>
            {
                let attrs = tcx.codegen_fn_attrs(def);
                let symbol = attrs.symbol_name.or_else(|| {
                    attrs.flags.contains(CodegenFnAttrFlags::NO_MANGLE).then(|| tcx.item_name(def))
                })?;
                is_system_allocator_link_symbol(symbol.as_str())
                    .then_some(SystemAllocatorInterposer::Symbol { krate, symbol })
            }
            _ => None,
        }
    };
    let local_name = tcx.crate_name(LOCAL_CRATE);
    let local = tcx
        .hir_crate_items(())
        .definitions()
        .find_map(|def| interposer(def.to_def_id(), local_name));
    let found = local.or_else(|| {
        tcx.crates(()).iter().find_map(|&krate| {
            if foreign_destructor_admission::crate_is_sysroot_credited(tcx, krate)
                || tcx.crate_dep_kind(krate).macros_only()
            {
                return None;
            }
            let name = tcx.crate_name(krate);
            (0..tcx.num_extern_def_ids(krate)).find_map(|index| {
                interposer(
                    DefId { krate, index: rustc_span::def_id::DefIndex::from_usize(index) },
                    name,
                )
            })
        })
    });
    SYSTEM_ALLOCATOR_INTERPOSER_MEMO.with(|memo| memo.borrow_mut().insert(key, found));
    found
}

/// Trust (2026-10-03): may a crate in the graph — this one or a dependency — install
/// an allocation-error hook? `trust_crate_references_alloc_error_hook` is a per-crate
/// fact carried in metadata (`CrateRoot`), computed by each crate's own compilation
/// from its HIR (`trust_crate_references_alloc_error_hook_local`).
///
/// Why it matters: `handle_alloc_error` in a binary that links `std` runs `rust_oom`,
/// which calls the hook and aborts only if the hook returns. `std::alloc::
/// set_alloc_error_hook` documents that the hook "may choose to panic", and rustc's
/// own `tests/ui/panics/alloc_error_hook-unwind.rs` catches that unwind. So with a
/// hook installed, an allocation's failure path is a PANIC path running unverified
/// code, and every allocation-failure premise (a `Box::new` result is non-null; the
/// vanilla class's allocating routines are panic-free; `__rust_alloc` is a bodyless
/// edge modeled panic-free) is false for it.
///
/// Trust (std-call-summaries P2 review, 2026-10-12): it also answers `true` when any
/// crate of the graph other than the compiler's own `std` defines an
/// `#[alloc_error_handler]` (`has_alloc_error_handler`, a metadata fact). That
/// handler REPLACES `rust_oom`/`__rdl_alloc_error_handler` as the target of
/// `__rust_alloc_error_handler` and may panic, so allocation failure is no longer
/// known to abort. Fail-closed defense in depth: such a graph is `#![no_std]` with a
/// user `#[global_allocator]`, which the global-allocator contract already refuses.
/// `std` itself is excluded by artifact residency because its `rust_oom` IS that
/// attribute's carrier, and its hook route is the metadata fact above.
fn crate_graph_may_install_alloc_error_hook(tcx: TyCtxt<'_>) -> bool {
    let user_alloc_error_handler = |cnum: CrateNum| {
        tcx.has_alloc_error_handler(cnum)
            && !(tcx.crate_name(cnum).as_str() == "std"
                && trust_mir_extract::is_real_sysroot_crate(tcx, cnum))
    };
    tcx.trust_crate_references_alloc_error_hook(LOCAL_CRATE)
        || tcx.crates(()).iter().any(|&cnum| tcx.trust_crate_references_alloc_error_hook(cnum))
        || user_alloc_error_handler(LOCAL_CRATE)
        || tcx.crates(()).iter().any(|&cnum| user_alloc_error_handler(cnum))
}

/// Trust (T6): local arm of `trust_crate_mir_is_proof_session_pipeline` — was
/// this crate's MIR built by the proof-session `-O0` MIR pipeline
/// (`Session::trust_mir_is_proof_session_pipeline`)? Encoded into this crate's
/// metadata; a verified dependent re-derives its encoded MIR only when it is
/// (`foreign_rederivation`, conjunct (8)).
pub(crate) fn trust_crate_mir_is_proof_session_pipeline_local(
    tcx: TyCtxt<'_>,
    _: rustc_middle::query::LocalCrate,
) -> bool {
    tcx.sess.trust_mir_is_proof_session_pipeline()
}

/// Local arm of `trust_crate_references_alloc_error_hook`: does any body of this
/// crate NAME a function called `set_alloc_error_hook` — std's, or anything else so
/// named (over-approximation is the fail-closed direction)? Read from HIR, so every
/// form of naming counts: a call, a path through a `use … as` rename, a function
/// pointer taken from it, a macro expansion. `take_alloc_error_hook` is not counted:
/// it installs the default hook (it returns the old one; calling that value is an
/// indirect call, which the indirect-call gates already refuse). Encoded into this
/// crate's metadata so a downstream compilation sees it (`crate_graph_may_install_
/// alloc_error_hook`). A body with no HIR is skipped: a Clean-origin def (its emitted
/// shapes call only marker-authenticated core primitives) and a synthetic coroutine
/// body (a by-move copy of a parent whose own HIR is walked).
pub(crate) fn trust_crate_references_alloc_error_hook_local(
    tcx: TyCtxt<'_>,
    _: rustc_middle::query::LocalCrate,
) -> bool {
    use rustc_hir::intravisit::{self, Visitor};
    struct Finder<'tcx> {
        tcx: TyCtxt<'tcx>,
        found: bool,
    }
    impl<'tcx> Visitor<'tcx> for Finder<'tcx> {
        fn visit_path(&mut self, path: &rustc_hir::Path<'tcx>, _id: rustc_hir::HirId) {
            if let rustc_hir::def::Res::Def(rustc_hir::def::DefKind::Fn, def_id) = path.res
                && self.tcx.item_name(def_id).as_str() == "set_alloc_error_hook"
            {
                self.found = true;
            }
            intravisit::walk_path(self, path);
        }
    }
    let mut finder = Finder { tcx, found: false };
    // Every body owner — fns, closures, consts, statics, anon and inline consts —
    // each visited on its own (the default nested filter does not descend into a
    // nested body, which is its own owner here).
    for owner in tcx.hir_body_owners() {
        if crate::clean_origin_mir::is_clean_origin(tcx, owner)
            || matches!(tcx.def_kind(owner), rustc_hir::def::DefKind::SyntheticCoroutineBody)
        {
            continue;
        }
        let Some(body) = tcx.hir_maybe_body_owned_by(owner) else { continue };
        finder.visit_body(body);
        if finder.found {
            return true;
        }
    }
    false
}

/// How a body's `GlobalAlloc::dealloc` reliance publishes. Both variants carry
/// the FULL replacement row set (base rows + exactly one contract row), and
/// both leave the body's proof CONDITIONAL: `register_proven_panic_free` is
/// blocked for every charged body (see its call gate), because even the
/// vacuous discharge is a statement about the crate graph in view — a final
/// link is still free to register an allocator this compilation never saw.
enum GlobalAllocDeallocDisposition {
    /// No `#[global_allocator]` anywhere in the crate graph: the premise
    /// discharges vacuously against `Global`'s std dealloc chain. The row is
    /// `Outcome::Skipped` — discharged conditional evidence, never solver
    /// proof credit — and verification proceeds.
    DischargedVacuouslyForGlobal(Vec<TransportObligationResult>),
    /// A user allocator is in the graph — a `#[global_allocator]`, or a crate
    /// defining a libc allocator symbol `System` calls — and no lane verifies it
    /// yet: the contract REFUSES. Fail-closed: strict lanes abort
    /// (`abort_on_global_alloc_dealloc_contract_refusal`), advisory lanes record the
    /// refused row and continue (they make no proof claim).
    RefusedUserAllocator(Vec<TransportObligationResult>),
    /// Trust (2026-10-03): a crate in the graph may install an allocation-error
    /// hook (`crate_graph_may_install_alloc_error_hook`) and this body can reach a
    /// failing allocation (`sysroot_drop_reach::body_allocation_failure_reach`): its
    /// allocation failure runs the hook, which may panic, and no lane verifies the
    /// hook. Refused exactly like `RefusedUserAllocator`.
    RefusedAllocErrorHook(Vec<TransportObligationResult>),
}

/// Why a charged body's premise is refused, for the row text and the strict abort.
#[derive(Clone, Copy)]
enum GlobalAllocRefusal {
    UserAllocator,
    AllocErrorHook,
}

/// Trust (2026-09-16, round-2 refutation): the ONE detector for "this body is
/// charged the `contract:global-alloc-dealloc-panic-free` premise", used by the
/// publication seam (`global_alloc_dealloc_disposition`), the interprocedural
/// registry gate (the `register_proven_panic_free` call site) and R40
/// NO SUBJECT EXEMPTION. Charging the allocator's OWN bodies (an `impl
/// GlobalAlloc` method, the four `#[global_allocator]` expansion shims) looks
/// circular, and a refuter argued for exempting them — but `ff041d4b0c` pinned
/// the opposite deliberately: a user `#[global_allocator]` is a process-global
/// channel into user code from every allocating sysroot routine, not only from a
/// drop, and the `alloc` / `__rust_*` refusals are pinned in
/// `tests/ui/trust/global_alloc_dealloc_contract_*_user_dealloc_*.rs` "so the
/// widening cannot be silently reverted". An exemption here reverts that ruling
/// silently; it is not taken.
///
/// zero-obligation candidacy — so producer and consumer cannot drift. They had:
/// the seam was widened to the allocation side (`body_has_non_local_call` under
/// a user allocator) while the registry gate still asked only about
/// allocation-owning drops, so `fn b() { let s = String::from("x");
/// mem::forget(s) }` was published REFUSED and, in the same Session, registered
/// unconditionally panic-free — a local caller `fn a() { b() }` then published
/// `no_obligations: proved` on the strength of a callee the crate refused.
///
/// Trust (2026-10-02): the allocation side is charged WITHOUT a user allocator in
/// view too, when this compilation does not choose the final link's allocator
/// (`!crate_types_are_whole_program`: an rlib or a dylib is linked later, into an
/// artifact that may register a `#[global_allocator]` this crate never sees).
/// Measured on origin/main `280ff7c48cd`: an rlib returning `Box::new(7u8)`, or
/// running `x.to_string()` or `String::from("x")` + `mem::forget`, certified 5 of
/// 5 with no premise row, and a `main` that registered a panicking allocator —
/// itself, or through a sibling dependency — panicked inside each verified
/// function. The detector is a reach walk (`sysroot_drop_reach::
/// body_global_allocator_reach`), not "any non-local call": a body that provably
/// reaches no global-allocator shim (`x / 2`, `Vec::new()`) keeps its credit. In a
/// whole-program compilation the allocator IS decided here: a user one is in view
/// (and refused above), or std's default `System` chain has no panic path.
///
/// Trust (2026-10-03): two more channels into the allocation path, each charged:
///  * "a user allocator is in view" now also means a crate that DEFINES a libc
///    allocator symbol std's `System` calls (`crate_graph_system_allocator_interposer`,
///    folded into `crate_graph_registers_user_global_allocator`): with it, std's
///    default chain runs that crate's code in every allocation and dealloc;
///  * a crate in the graph that may install an allocation-error hook
///    (`crate_graph_may_install_alloc_error_hook`) turns every allocation's failure
///    into a possible PANIC, so a body that can reach a failing allocation
///    (`body_reaches_hookable_allocation_failure`) is charged — and refused — in a
///    whole-program compilation too. Measured before (stage 1 of origin/main
///    `57121fb6713`, m3): a binary that installed the hook exactly as
///    `tests/ui/panics/alloc_error_hook-unwind.rs` does — in `main`, or through a
///    dependency's `install()` — credited `Box::new(T[i & 1])` (`bounds: proved`,
///    under strict and `certify`) and `Box::<MaybeUninit<[u8; 1 << 60]>>::new_uninit()`
///    (`no_obligations: proved`, under strict) with no premise row, and the second
///    unwound out of the hook at runtime (`catch_unwind` caught it).
fn body_is_charged_global_alloc_contract<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    body_has_alloc_owning_drop(tcx, body)
        || (crate_graph_registers_user_global_allocator(tcx)
            && (body_has_non_local_call(body) || body_has_needs_drop_terminator(tcx, body)))
        || (!crate_types_are_whole_program(tcx)
            && sysroot_drop_reach::body_global_allocator_reach(tcx, body).is_err())
        || body_reaches_hookable_allocation_failure(tcx, body)
}

/// Trust (2026-10-03): may an allocation-error hook run — and panic — inside this
/// body? True when a crate in the graph may install one and the body can reach a
/// failing allocation (an allocating global-allocator shim or the
/// allocation-error handler; `dealloc` cannot fail). Fail-closed: a walk that
/// cannot tell answers "can reach".
fn body_reaches_hookable_allocation_failure<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    crate_graph_may_install_alloc_error_hook(tcx)
        && sysroot_drop_reach::body_allocation_failure_reach(tcx, body).is_err()
}

/// Any `Drop` terminator whose type has non-trivial drop glue (`needs_drop`).
///
/// Trust (2026-09-16, refuted): `body_has_alloc_owning_drop` recognizes owners
/// by NAME (`ALLOC_OWNING_PARTS`) and deliberately treats `NonNull`/`PhantomData`
/// as non-allocating scaffold — so `std::io::Error` (a `Box<Custom>` behind a
/// tagged `NonNull` that only `Repr`'s manual `Drop` knows about) and
/// `ThinBox<T>` were never charged, and `consume(e: io::Error) { let _ = e; }`
/// proved panic-free with a verify-off `#[global_allocator]` whose `dealloc`
/// panics in the graph (runtime: the panic, from the verified body's drop
/// glue). No allow-list enumerates every std owner; under a USER allocator the
/// conservative charge is the same one the call side already applies — any
/// drop that runs glue at all may reach `dealloc`. Without a user allocator the
/// vacuous `Global` discharge covers whatever the glue owns, so the name-keyed
/// recognizer stays the publication trigger there.
/// The first FOREIGN ADT (non-local, outside this compiler's own core/alloc/std)
/// reachable as a TYPE ARGUMENT of a type this body drops, rendered for the
/// diagnostic. `None` when every dropped type is instantiated only at local or
/// sysroot types. See the call site for why this is decided here, not in the
/// bridge.
fn body_drops_foreign_adt_argument<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> Option<String> {
    fn foreign_argument<'tcx>(
        tcx: TyCtxt<'tcx>,
        ty: Ty<'tcx>,
        seen: &mut FxHashSet<Ty<'tcx>>,
    ) -> Option<String> {
        if !seen.insert(ty) {
            return None;
        }
        match ty.kind() {
            ty::Adt(def, args) => {
                if !def.did().is_local()
                    && !trust_mir_extract::def_is_in_real_sysroot_crate(tcx, def.did())
                {
                    return Some(trust_mir_extract::safe_def_path_str(tcx, def.did()));
                }
                args.types().find_map(|arg| foreign_argument(tcx, arg, seen))
            }
            ty::Ref(_, inner, _)
            | ty::RawPtr(inner, _)
            | ty::Array(inner, _)
            | ty::Slice(inner)
            | ty::Pat(inner, _) => foreign_argument(tcx, *inner, seen),
            ty::Tuple(elems) => elems.iter().find_map(|t| foreign_argument(tcx, t, seen)),
            _ => None,
        }
    }
    let typing_env = ty::TypingEnv::post_analysis(tcx, body.source.def_id());
    let mut seen: FxHashSet<Ty<'tcx>> = FxHashSet::default();
    body.basic_blocks.iter().find_map(|block| {
        let TerminatorKind::Drop { place, .. } = &block.terminator().kind else {
            return None;
        };
        let drop_ty = place.ty(&body.local_decls, tcx).ty;
        let drop_ty = tcx.normalize_erasing_regions(typing_env, ty::Unnormalized::new_wip(drop_ty));
        if !drop_ty.needs_drop(tcx, typing_env) {
            return None;
        }
        foreign_argument(tcx, drop_ty, &mut seen)
    })
}

fn body_has_needs_drop_terminator<'tcx>(tcx: TyCtxt<'tcx>, body: &Body<'tcx>) -> bool {
    let typing_env = ty::TypingEnv::post_analysis(tcx, body.source.def_id());
    body.basic_blocks.iter().any(|block| {
        let TerminatorKind::Drop { place, .. } = &block.terminator().kind else {
            return false;
        };
        let drop_ty = place.ty(&body.local_decls, tcx).ty;
        let drop_ty = tcx.normalize_erasing_regions(typing_env, ty::Unnormalized::new_wip(drop_ty));
        drop_ty.needs_drop(tcx, typing_env)
    })
}

/// Decide how this body's `GlobalAlloc::dealloc` premise publishes. `None`
/// iff the body is not charged (`body_is_charged_global_alloc_contract`) —
/// nothing was relied on, so nothing publishes. Once the charge fires, a row
/// ALWAYS publishes (the
/// D1-coupling lesson from the coroutine seam: a consumed premise with no
/// surfaced row is the defect class this machinery exists to close).
fn global_alloc_dealloc_disposition<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    rows: &[TransportObligationResult],
) -> Option<GlobalAllocDeallocDisposition> {
    let user_allocator = crate_graph_registers_user_global_allocator(tcx);
    // Trust (refuted 2026-09-16, round 2): with a user `#[global_allocator]` in
    // the graph the ALLOCATION side is unverified too, and it is reached from
    // more than absent-callee rows — `String::from`/`Box::new` are BUNDLED and
    // credited over a bundle in which `__rust_alloc` is a bodyless extern edge
    // modeled panic-free (measured: `String::from(..); mem::forget(..)` with a
    // verify-off dependency allocator that panics in `alloc` built exit 0 with
    // ONE proved row, under the default policy AND `certify`, and aborted in
    // the dependency). Until a discharge-at-impl lane exists, every body that
    // can reach an allocation — conservatively, any non-local call at all — is
    // charged the REFUSED contract in such a graph; with no user allocator the
    // charge stays on allocation-owning drops (the `Global` chain has no panic
    // path on either side) — and, when this compilation is not the final link,
    // on every body that may reach the global allocator (2026-10-02, see
    // `body_is_charged_global_alloc_contract`), DISCHARGED like a drop's.
    if !body_is_charged_global_alloc_contract(tcx, body) {
        return None;
    }
    // Only this seam may mint the contract kinds: strip any pre-existing row
    // claiming either (staleness/forgery defense, same as the coroutine seam).
    let mut out: Vec<TransportObligationResult> = rows
        .iter()
        .filter(|row| {
            row.kind != GLOBAL_ALLOC_DEALLOC_CONTRACT_ROW_KIND
                && row.kind != GLOBAL_ALLOC_DEALLOC_CONTRACT_REFUSED_ROW_KIND
        })
        .cloned()
        .collect();
    // Trust (2026-10-03): a hook that may be installed in the graph refuses a body
    // that can reach a failing allocation, whole-program or not — the hook is in
    // view, so "discharged against std's chain" would be false of it. A body charged
    // for a drop alone (dealloc cannot fail) keeps the vacuous discharge.
    if user_allocator {
        out.push(global_alloc_dealloc_contract_transport_row(
            tcx,
            body,
            Some(GlobalAllocRefusal::UserAllocator),
        ));
        Some(GlobalAllocDeallocDisposition::RefusedUserAllocator(out))
    } else if body_reaches_hookable_allocation_failure(tcx, body) {
        out.push(global_alloc_dealloc_contract_transport_row(
            tcx,
            body,
            Some(GlobalAllocRefusal::AllocErrorHook),
        ));
        Some(GlobalAllocDeallocDisposition::RefusedAllocErrorHook(out))
    } else {
        out.push(global_alloc_dealloc_contract_transport_row(tcx, body, None));
        Some(GlobalAllocDeallocDisposition::DischargedVacuouslyForGlobal(out))
    }
}

/// Trust (2026-09-16): the entry function's return type, when it reaches foreign
/// user code or a trait object, is dispatched by `lang_start` through
/// `<T as Termination>::report` (its `Debug` on `Err`, its `Drop` always) — code
/// this compilation never sees as a terminator. Publishes ONE honest
/// runtime-checked row for it (policy B: reported, conditional, fatal under
/// `certify`); `None` when the body is not the `EntryFnType::Main` entry or its
/// return type stays within foundational/local types (`()`, `ExitCode`,
/// `io::Result<()>`, `Result<(), String>` mint nothing).
fn entry_termination_dispatch_rows<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    rows: &[TransportObligationResult],
) -> Option<Vec<TransportObligationResult>> {
    let def_id = body.source.def_id();
    let Some((entry_def_id, rustc_session::config::EntryFnType::Main { .. })) = tcx.entry_fn(())
    else {
        return None;
    };
    if entry_def_id != def_id || body.source.promoted.is_some() {
        return None;
    }
    let typing_env = ty::TypingEnv::post_analysis(tcx, def_id);
    let ret_ty =
        tcx.normalize_erasing_regions(typing_env, ty::Unnormalized::new_wip(body.return_ty()));
    let mut memo: FxHashMap<Ty<'tcx>, bool> = FxHashMap::default();
    // Trust (IOERROR-PAYLOAD-1, 2026-10-27): the rule is withheld here
    // (`dyn_error_payload::withheld`), so an `io::Error` return type keeps its row.
    if !dyn_error_payload::withheld(|| ty_reaches_foreign_user_code(tcx, ret_ty, &mut memo)) {
        return None;
    }
    // Trust (X2, 2026-09-23): `with_no_trimmed_paths!` is LOAD-BEARING. `{ret_ty}`
    // renders through `trimmed_def_paths`, which arms rustc's `must_produce_diag`;
    // this row reaches only the transport/JSON output, so when `main` has no other
    // row nothing is emitted and `DiagCtxtInner::drop` ICEd ("`trimmed_def_paths`
    // called, diagnostics were expected but none were emitted") on
    // `fn main() -> Result<(), std::io::Error> { Ok(()) }`, `Box<dyn Error>`, and
    // any `dep::E` — pinned by `policy_b/entry_termination_row_renders_no_ice.rs`.
    let kind = VcKind::Assertion {
        message: with_no_trimmed_paths!(format!(
            "panic freedom: `<{ret_ty} as std::process::Termination>::report` runs under \
             `lang_start` and dispatches the `Debug`/`Drop` of a foreign or dynamic type this \
             compilation does not verify"
        )),
    };
    // Only this seam mints the row: strip any pre-existing row claiming it.
    let mut out: Vec<TransportObligationResult> = rows
        .iter()
        .filter(|row| row.reason.as_deref() != Some(ENTRY_TERMINATION_DISPATCH_REASON))
        .cloned()
        .collect();
    out.push(TransportObligationResult {
        assumes: Vec::new(),
        gap_class: None,
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: kind.transport_tag(),
        original_vc_snapshot: None,
        typed_kind: Some(Box::new(kind.clone())),
        description: kind.description(),
        location: Some(source_span_from_rustc_span(tcx, body.span)),
        outcome: Outcome::RuntimeChecked,
        solver: trust_types::assumption::GLOBAL_ALLOC_DEALLOC_CONTRACT_ROW_SOLVER.to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some(ENTRY_TERMINATION_DISPATCH_REASON.to_string()),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
        grade: None,
    });
    Some(out)
}

/// The exact reason string of the entry-`Termination` dispatch row (policy B).
const ENTRY_TERMINATION_DISPATCH_REASON: &str = "entry `Termination::report` dispatch: reported \
     gap (policy B) — a panic in the returned value's `Debug`/`Drop` is a defined abort during \
     error reporting; return `()`, `ExitCode`, or an error type whose `Debug`/`Drop` this crate \
     verifies to close it";

fn abort_on_entry_termination_dispatch(tcx: TyCtxt<'_>, body: &Body<'_>, func_path: &str) {
    publication_contracts::prepare_entry_termination_dispatch(tcx, body, func_path).emit(tcx);
}

/// The published `contract:global-alloc-dealloc-panic-free` row.
/// `Outcome::Skipped` on the wire in BOTH states — a published contract is
/// conditional evidence, never solver proof credit (the coroutine row's
/// rule); the discharged/refused split lives in the description/reason pair
/// and in the strict abort keyed off the disposition, not off row text.
fn global_alloc_dealloc_contract_transport_row(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    refusal: Option<GlobalAllocRefusal>,
) -> TransportObligationResult {
    let (description, reason) = match refusal {
        None => (
            "allocation(s) and/or allocation-owning drop(s) in this body rely on \
             `GlobalAlloc::{alloc,dealloc}` never panicking; DISCHARGED vacuously: no \
             `#[global_allocator]` is registered in the crate graph, so every allocation and \
             dealloc is `Global`'s std chain (`__rust_alloc` / `__rust_dealloc` → the std \
             default allocator), which has no panic path; conditional on the final link \
             registering no other allocator"
                .to_string(),
            trust_types::assumption::GLOBAL_ALLOC_DEALLOC_CONTRACT_DISCHARGED_REASON.to_string(),
        ),
        Some(GlobalAllocRefusal::UserAllocator) => match user_allocator_interposer_only(tcx) {
            None => (
                "allocation(s) and/or allocation-owning drop(s) in this body rely on \
                 `GlobalAlloc::{alloc,dealloc}` never panicking; REFUSED: a user \
                 `#[global_allocator]` is registered in the crate graph and no lane verifies its \
                 impl panic-free yet — a panicking `alloc`/`dealloc` would make every allocating \
                 call and every such drop able to panic"
                    .to_string(),
                "global-alloc dealloc contract refused (fail-closed): user `#[global_allocator]` \
                 present, discharge-at-impl lane not implemented"
                    .to_string(),
            ),
            Some(interposer) => (
                format!(
                    "allocation(s) and/or allocation-owning drop(s) in this body rely on \
                     `GlobalAlloc::{{alloc,dealloc}}` never panicking; REFUSED: {}, so unverified \
                     code runs inside every allocation and dealloc of the default chain — a panic \
                     there would make every allocating call and every such drop able to panic",
                    interposer.clause()
                ),
                interposer.reason(),
            ),
        },
        Some(GlobalAllocRefusal::AllocErrorHook) => (
            "allocation(s) in this body rely on allocation failure never panicking; REFUSED: \
             a crate in the graph references `std::alloc::set_alloc_error_hook`, and \
             `handle_alloc_error` runs the installed hook, which may panic (the unwind is \
             catchable) — no lane verifies the hook, so every allocation that can fail here \
             is able to panic"
                .to_string(),
            "global-alloc contract refused (fail-closed): an allocation-error hook may be \
             installed in the crate graph, and no lane verifies it"
                .to_string(),
        ),
    };
    let kind = if refusal.is_none() {
        GLOBAL_ALLOC_DEALLOC_CONTRACT_ROW_KIND
    } else {
        GLOBAL_ALLOC_DEALLOC_CONTRACT_REFUSED_ROW_KIND
    };
    TransportObligationResult {
        assumes: Vec::new(),
        gap_class: None,
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: kind.to_string(),
        original_vc_snapshot: None,
        typed_kind: None,
        description,
        location: Some(source_span_from_rustc_span(tcx, body.span)),
        outcome: Outcome::Skipped,
        solver: trust_types::assumption::GLOBAL_ALLOC_DEALLOC_CONTRACT_ROW_SOLVER.to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some(reason),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
        grade: None,
    }
}

/// The exact published-and-DISCHARGED contract row shape — kind, outcome,
/// solver, and provenance fields all pinned, mirroring
/// `transport_row_is_coroutine_protocol_assumption`, so a hand-built row that
/// merely claims the kind cannot pass a lane gate. The REFUSED kind
/// deliberately does NOT match: a refused premise stays an unproved row for
/// every fail-closed lane.
fn transport_row_is_discharged_global_alloc_dealloc_contract(
    row: &TransportObligationResult,
) -> bool {
    row.kind == GLOBAL_ALLOC_DEALLOC_CONTRACT_ROW_KIND
        && row.outcome == Outcome::Skipped
        && row.solver == "trust-classifier"
        && !row.design_mandate
        && row.native_trust_ir.is_none()
        && row.proof_evidence.is_none()
}

/// Reject the refused `GlobalAlloc::dealloc` contract in every fail-closed
/// lane. Mirrors `abort_on_coroutine_protocol_assumption`: runs only after
/// human result reporting and JSON transport emission, so the refusal never
/// masks or replaces the body's genuine arithmetic/bounds/refutation rows.
fn abort_on_global_alloc_dealloc_contract_refusal(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    func_path: &str,
    refusal: GlobalAllocRefusal,
) {
    publication_contracts::prepare_global_alloc_dealloc_contract_refusal(tcx, body, func_path, refusal).emit(tcx);
}

fn assumption_reason_class(tag: &str) -> &'static str {
    match tag {
        "user-opt-out" => "explicit user opt-out",
        "assumed-total" | "assumed-total-callee" => "explicit user-audited assumption",
        "unreachable-start" => "verification policy assumption",
        _ => "verifier capability gap",
    }
}

/// Trust (assumption ledger, W3.5): is this transport row an EXTERN print/format/
/// write dispatch panic-freedom row (marked by the bridge with
/// `EXTERN_CALL_ASSUMPTION_PREFIX`) that is NOT proved? Such a row is a recorded
/// may-panic-via-user-`Display` gap, eligible for demotion to `assumption:extern-
/// call` in advisory mode. A proved row is never demoted.
fn transport_row_is_unproved_extern_call(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row.description.contains(trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX)
}

/// FIX b59: the dispatch callee the bridge carries between the backticks of an
/// `EXTERN_CALL_ASSUMPTION_PREFIX` row description (the bridge emits
/// "…dispatch `{callee}` runs a user Display/Debug impl…", see `extern_fmt_dispatch_call`).
/// The prefix and the "extern print/format/write dispatch " lead-in carry no backticks,
/// so the first backtick pair delimits the callee.
fn extern_call_row_callee(description: &str) -> Option<&str> {
    let (_, after) = description.split_once('`')?;
    let (callee, _) = after.split_once('`')?;
    Some(callee)
}

/// FIX b59: the SAFE SUBSET of the unproved extern-call dispatch rows — the
/// `fmt::format` (`format!` macro backend) leg SPECIFICALLY. `alloc::fmt::format`
/// builds a `String` with NO stdout sink, so — unlike the `_print`/`_eprint` legs
/// (which drive a `Display` INTO stdout and can additionally hit a broken pipe /
/// SIGPIPE) or the `write_fmt`/`fmt::write` writer legs — it is the one dispatch leg
/// eligible for demotion OUTSIDE the memory-safe lane (strict fail-closed and the
/// survey `ny-cert` lane included). Reads the callee the bridge carried in the
/// row description; the row's provenance (only `core::`/`alloc::`/`std::` dispatch
/// callees ever mint an `EXTERN_CALL_ASSUMPTION_PREFIX` row) makes the
/// `::fmt::format` suffix unambiguous. A proved row is never demoted.
fn transport_row_is_unproved_fmt_format_extern_call(row: &TransportObligationResult) -> bool {
    transport_row_is_unproved_extern_call(row)
        && extern_call_row_callee(&row.description)
            .is_some_and(|callee| callee.ends_with("::fmt::format"))
}

/// Trust (assumption ledger): is this transport row an ABSENT-CALLEE panic-freedom
/// row (marked by the bridge with `ABSENT_CALLEE_ASSUMPTION_PREFIX` — the target's
/// body was not in the lowered bundle) that is NOT proved? Eligible for demotion to
/// `assumption:absent-callee` in advisory mode only; the strict full lane keeps
/// it Unknown (fail-closed). A proved row is never demoted.
fn transport_row_is_unproved_absent_callee(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row.description.contains(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
        // The EXPECTED-absent prefix is NOT a substring of the fatal one (guarded
        // by the assumption-crate `assumption_prefixes_are_mutually_non_substring`
        // test), but `.contains` on the fatal prefix would false-negate here only
        // if it were — belt-and-suspenders, exclude it explicitly so a future
        // prefix edit cannot silently make an expected-absent row fatal.
        && !transport_row_is_unproved_expected_absent_callee(row)
        && !transport_row_is_unproved_assumed_total_callee(row)
}

/// Trust: is this an UNPROVED EXPECTED-absent callee row — a user
/// `#[trust::skip]` or a compiler-authenticated non-unwinding C-family call
/// (marked by the bridge with `EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX`)? It is
/// still an assumption, never proof: only survey may rewrite it to an
/// `assumption:expected-absent-callee` ledger row. Strict and memory-safe reject
/// it. Unresolved generic dispatch is deliberately not in this producer class.
fn transport_row_is_unproved_expected_absent_callee(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row
            .description
            .contains(trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX)
}

/// SOUNDNESS GAP — RECORDED, NOT FIXED. `.contains()` on a USER-CONTROLLED string.
///
/// `row.description` is user-reachable text. The shortest path found:
/// `unsupported_predicate_reason` in `trust_contract_query.rs` inlines
/// `span_to_snippet(span)` raw into "unsupported contract predicate expression
/// `{snippet}`" for any `#[requires(EXPR)]` that declines to lower — e.g. one
/// containing a string literal — and that text flows unsanitized through
/// trust-mir-extract into this row's description. Embedding the assumption prefix
/// in a contract expression therefore classifies the row as an
/// `#[trust::assume_total]` callee assumption the author never wrote.
///
/// Effect, scoped honestly: this is a GATE DOWNGRADE, not a false proof. Strict
/// and Certify fold `assumed` back into `unknown`, so only the Advisory lane
/// flips — `unknown > 0 => Inconclusive/exit 1` becomes
/// `assumed > 0, F=U=0 => ConditionalPass/exit 0`. In the memory-safe lane the
/// marker causes OVER-rejection, not a bypass; do not "fix" in that direction.
/// What is real: an unverified user string launders a fail-closed unknown into
/// the "explicit user-audited assumption" bucket and flips a documented blocking
/// status.
///
/// This file already knows the hazard — see the note that "the description is
/// user-controlled, so only the final `contract_id` suffix is authoritative",
/// hardening applied to the ensures-citation parser and not here. The sibling
/// check on this same marker, `api_obligation_is_assumed_total_callee_marker`,
/// does it correctly with `strip_prefix` plus full provenance recomputation, and
/// has an adversarial test whose first case is literally "embedded marker". This
/// predicate has none.
///
/// FIX SHAPE: carry the class on an authenticated channel, as the compiler
/// already does for the assumed-total SET via `insert_exact_absent_call_identity`
/// (whose own comment warns of "the 'spelling as authority' hazard"); or sanitize
/// `obligation.description` in `legacy_unsupported_kind_detail` before it becomes
/// `detail`. NOT applied here because this crate cannot be compile-validated
/// without a full bootstrap, and the change wants a regression test modelled on
/// the sibling's — which needs the same build.
fn transport_row_is_unproved_assumed_total_callee(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row.description.contains(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX)
}

/// Trust (OD-1 phase 0 review, 2026-10-04): may the advisory post-pass rewrite this
/// row into an `assumption:expected-absent-callee` ledger row? Only when it is an
/// unproved expected-absent row that nothing has REFUTED. A `failed` row is never
/// demoted: the Level-0 refutation stamp (`rows_with_l0_refutations`) runs first,
/// and the whole-function panic-freedom aggregate keeps the text of its FIRST fold
/// site, so `#[trust::skip] f(); t.m()` (open dispatch co-folded behind a skipped
/// callee) arrives here as a `failed` row whose description carries the
/// expected-absent prefix. Measured on the phase-0 build `52d352514b`: demoting it
/// published `skipped` (`"failed":0`) under `-Ztrust-policy=advisory` while the
/// Level-0 summary said "1 failed", and the reverse statement order published
/// `failed`. The same rule as the native-lowering collapse: never hide a
/// refutation behind an assumption.
fn transport_row_is_demotable_expected_absent_callee(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Failed && transport_row_is_unproved_expected_absent_callee(row)
}

/// Trust (OD-1 phase 0 review, 2026-10-04): the `#[trust::assume_total]` twin of
/// [`transport_row_is_demotable_expected_absent_callee`]: a refuted (`failed`)
/// row is never rewritten into an `assumption:assumed-total-callee` row.
fn transport_row_is_demotable_assumed_total_callee(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Failed && transport_row_is_unproved_assumed_total_callee(row)
}

fn transport_row_is_assumed_total_assumption(row: &TransportObligationResult) -> bool {
    row.kind.strip_prefix("assumption:")
        == Some(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_TAG)
        && row.outcome == Outcome::Skipped
        && !row.design_mandate
        && row.native_trust_ir.is_none()
        && row.proof_evidence.is_none()
}

fn expected_absent_callee_demotion_applies(
    policy: &TrustVerifyPolicy,
    rows: &[TransportObligationResult],
) -> bool {
    policy.is_explicit_advisory()
        && rows.iter().any(transport_row_is_unproved_expected_absent_callee)
}

/// Trust (assumption ledger): drop-glue twin of the absent-callee predicate —
/// a `PanicFreedom` row for a Drop whose glue's panic-freedom is unproven.
fn transport_row_is_unproved_drop_glue(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row.description.contains(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
}

/// Trust: fail-closed on absent-callee / expected-absent / drop-glue panic
/// (revert of d8a9bbc28e / d848dcad97 fail-open; unproven panic MUST fail
/// closed). An UNPROVEN `PanicFreedom` row marked by any of those bridge prefixes
/// is a genuine undischarged panic obligation: the
/// bridge lowers the site with an `Assert(false)+NoPanic` marker that keeps the
/// panic REACHABLE, so the obligation is Unknown by construction (never a false
/// PROVE) — but Unknown here means "a panic path we could not rule out", not a
/// mere coverage gap. The originating commits claimed the strict lane "keeps it
/// Unknown, fail-closed"; empirically the abort predicate below only consulted
/// `failure.failed`, so these Unknown rows returned rc=0 (accept a program that
/// panics — a FAIL-OPEN). This predicate re-arms the fail-closed abort: an
/// unproven assumption-tagged panic row is FATAL in the fail-closed (default +
/// strict) lane. SOUNDNESS: the row is never `proved` (the reachable panic marker
/// forbids it), so treating it as fatal can never false-refute provably-safe code
/// — it only rejects a call/drop whose panic-freedom the native lane genuinely
/// could not establish, which is exactly the fail-closed doctrine. The demotion
/// explicit survey rewrite path is unaffected: this predicate is consulted
/// only where strict enforcement requires a hard build error.
fn transport_row_is_unproved_assumption_panic(row: &TransportObligationResult) -> bool {
    assumption_panic_row_cause(row).is_some()
}

/// WHICH of the four disjuncts above made this row an assumption-panic row.
///
/// THE DEFECT THIS CLOSES, and it is a diagnosis defect rather than a verdict
/// one. The note this feeds already says the right kind of thing — "say which
/// condition withheld it … 'it just fails' is not a diagnosis anyone can act
/// on" — but for THIS condition it listed all four causes and named none, so a
/// reader could not tell an absent callee from drop glue from an `unsafe`-using
/// body. Measured cost: the `vec![1, 2, 3]` residue was attributed FOUR times
/// (allocator contract, a policy-B ruling, `panic_free_drop` item 1, drop glue)
/// and committed wrong once, each time by reading this note's disjunction as if
/// it were a finding. `tests/vec-literal-lowering/a1_*.rs` carries that
/// retraction.
///
/// ONE SOURCE OF TRUTH, deliberately: the boolean predicate DELEGATES here
/// rather than repeating the disjunction. A second copy of a four-way list is
/// how the two drift apart and the note starts naming a cause the gate did not
/// use — which would be worse than naming none.
///
/// Order matters only for reporting: a row can satisfy more than one disjunct,
/// and the first match is reported. The gate's own answer is unchanged either
/// way, since it only asks whether ANY matched.
/// The SUBJECT a drop-glue assumption row names — "drop glue for `main::S` may
/// panic" -> that whole phrase — or `None` when the row carries no detail.
///
/// Factored out of the transport-demotion site rather than copied: both callers
/// split on the same prefix, and two copies of a parse is how the demotion row
/// and the diagnostic start describing different things.
///
/// WHY IT IS WORTH SURFACING. The exclusion note gained the CLASS on
/// 2026-09-20 ("drop glue" rather than a four-way list), which was enough to
/// tell `vec![1, 2, 3]` apart from an absent callee. It was not enough to say
/// WHICH drop: the sized `Box`, `Box<u32>`, `to_vec` and `Vec::new`+`push`
/// neighbours all verify, so the obvious candidates are already excluded and the
/// row is the only thing that knows.
fn drop_glue_assumption_detail(row: &TransportObligationResult) -> Option<&str> {
    row.description
        .split(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
        .nth(1)
        .map(str::trim)
        .filter(|d| !d.is_empty())
}

fn assumption_panic_row_cause(row: &TransportObligationResult) -> Option<&'static str> {
    if transport_row_is_unproved_absent_callee(row) {
        Some("a generic absent callee")
    } else if transport_row_is_unproved_expected_absent_callee(row) {
        Some("an expected-absent callee")
    } else if transport_row_is_unproved_drop_glue(row) {
        Some("drop glue")
    } else if transport_row_is_fatal_unproved_extern_call(row) {
        Some("an extern call")
    } else {
        None
    }
}

/// Trust (fmt-frontier P0): the extern print/format/write DISPATCH rows that must
/// keep the fail-closed lane FATAL — every leg except the one `fmt::format` leg
/// that b59 deliberately made demotable under its own two gates.
///
/// This closes a MEASURED fail-open. `impl Display for S { fn fmt(&self, f) {
/// write!(f, "S") } }` compiled with `-Ztrust-verify=on` returned rc=0 while the
/// identical program PANICKED at runtime: `write!` lowers to `Formatter::write_fmt`,
/// which `extern_fmt_dispatch_call` classes as an extern-call row, and that class
/// was absent from this predicate — so the row was neither proved nor fatal.
///
/// The split was BACKWARDS. `write_fmt`/`fmt::write` drive ARBITRARY user
/// `Display`/`Debug::fmt` impls (a `todo!()` in any one of them panics) and the
/// `_print`/`_eprint` legs additionally hit a broken pipe / SIGPIPE, whereas the
/// harsher-treated `Formatter::write_str` forwards a SINGLE vtable call. The more
/// dangerous class was the tolerated one.
///
/// `alloc::fmt::format` is excluded because it is not tolerated here by accident:
/// b59 gates it on the function being unsafe-free AND every other obligation being
/// Proved, and routes it through `demote_fmt_format_extern_call_transport_rows`
/// into a RECORDED `assumption:extern-call` ledger row. That is a carried
/// condition, not a silent pass, so it keeps its existing path.
///
/// SOUNDNESS: an extern-call row is never `Proved` (the bridge lowers the site with
/// a reachable `Assert(false)+NoPanic` marker), so making it fatal cannot
/// false-refute provably-safe code.
fn transport_row_is_fatal_unproved_extern_call(row: &TransportObligationResult) -> bool {
    transport_row_is_unproved_extern_call(row)
        && !transport_row_is_unproved_fmt_format_extern_call(row)
}

// Trust (policy B restoration, 2026-09-10): a std stdout/stderr PRINT-BACKEND
// absent-callee row (`std::io::stdio::_print`/`_eprint`, or the `std::io::_print`
// spelling). Under the DEFAULT policy this is a runtime-checked completeness gap,
// not a refutation: the only unproved behaviour is std's own DEFINED
// write-failure / broken-pipe `panic!`, which is bit-for-bit vanilla Rust
// semantics (the panic path stays reachable). The green front door
// (7005b41c01, 2026-07-02) greened ordinary `println!` under strict-default;
// 42b923a273 (2026-08-09) re-broke it as a side effect of closing a `write_fmt`
// fail-open, undoing the owner's ratified completeness-gap ruling B
// (docs/design/2026-07-25-completeness-gap-policy-ruling.md) for this case.
//
// SCOPE IS DELIBERATELY NARROW. This matches ONLY std's stdout/stderr print
// backends. It does NOT match `write_fmt`/`fmt::write` (which drive arbitrary
// user `Display`/`Debug::fmt` — a verify-off dep impl is not verified as its own
// root), nor a generic absent callee (an unverified dependency body — the
// `read_any` UB-deref shape), nor drop glue.
//
// Trust (HOLE A close — 2026-09-14): classify by CRATE + EXACT def-path segments,
// NEVER a `.contains()` on a spoofable substring. The old assertion that
// "`std::io::` cannot appear in a non-std callee path" is FALSE: a dependency
// built `-Ztrust-verify=off` can define `a::std::io::_print`, whose rendered path
// CONTAINS `std::io::_print`, and the substring test then classified its panic as
// the benign std backend and TOLERATED it (a false SAFE claim; measured: exit 0
// while the program panics at runtime). This row carries no `TyCtxt`/`DefId` —
// only the rendered description — so the callee is extracted from the first
// backtick pair (both the extern-dispatch and absent-callee markers wrap it that
// way; `extern_call_row_callee`) and verified by CRATE ROOT (`std`) plus exact
// terminal segments. `depA::a::std::io::_print` is crate-rooted at `depA`, so it
// is NOT std's backend: it becomes an ordinary absent callee and fails closed.
fn transport_row_is_std_print_dispatch(row: &TransportObligationResult) -> bool {
    extern_call_row_callee(&row.description).is_some_and(def_path_str_is_std_print_backend)
}

/// Trust (2026-09-17): the completeness-gap CLASS a transport row carries on the
/// wire (`TransportObligationResult::gap_class`), so a consumer that tolerates a
/// gap keys on the compiler's attestation instead of re-deriving anything from
/// the prose description.
///
/// TWO GATES, both required. `attested` is the per-FUNCTION attestation made
/// where the panic-freedom fold is visible
/// (`panic_freedom_fold_is_std_print_exclusive`, at bundle synthesis, carried
/// through `SessionGapClassAttestations`): the whole-function panic-freedom
/// aggregate stands for the std print backend ALONE. The row-level gate then
/// stamps only the row that IS that aggregate — the absent-callee row naming the
/// print backend — and never a `proved` row (a proof is not a gap; the print
/// row is a reachable-panic marker that is never proved anyway). A row's shape
/// alone is NOT enough: the aggregate's description names only its FIRST marked
/// site, so a user `assert!` folded under a `println!` would otherwise inherit
/// the class (adversarially confirmed 2026-09-17, battery row r28).
/// Classification only — it changes no outcome and grants no credit.
fn transport_gap_class(
    attested: Option<trust_types::TransportGapClass>,
    row: &TransportObligationResult,
) -> Option<trust_types::TransportGapClass> {
    let class = attested?;
    if row.outcome == Outcome::Proved {
        return None;
    }
    match class {
        trust_types::TransportGapClass::StdPrintDispatch => {
            (transport_row_is_unproved_absent_callee(row)
                && transport_row_is_std_print_dispatch(row))
            .then_some(class)
        }
    }
}

/// Trust (2026-09-17): the per-function gap-class attestations of this
/// compiler invocation, keyed by the function's def path — written ONLY by
/// `record_session_gap_class_attestation` at native-bundle synthesis (where the
/// panic-freedom fold is visible) and read ONLY by the transport builders that
/// stamp `TransportObligationResult::gap_class`. Kept on the `Session` because
/// rustc_driver may run more than one compiler session per process.
#[derive(Default)]
struct SessionGapClassAttestations {
    by_def_path: FxHashMap<String, trust_types::TransportGapClass>,
    /// The marked per-site panic sources folded into each function's aggregate
    /// (`panic_freedom_fold_marked_sites`), read only by the row gate
    /// (`transport_rows_with_fold_sites`).
    fold_sites_by_def_path: FxHashMap<String, Vec<String>>,
}

/// What the whole-function panic-freedom synthesis attests about the fold it
/// stands for. Written where the fold is visible, published through the session
/// ledger, and reset wherever the bundle does not survive.
#[derive(Default)]
struct PanicFreedomFoldAttestation {
    gap_class: Option<trust_types::TransportGapClass>,
    marked_sites: Vec<String>,
}

fn record_session_gap_class_attestation(
    sess: &Session,
    def_path: &str,
    attestation: PanicFreedomFoldAttestation,
) {
    sess.with_trust_compiler_state::<SessionGapClassAttestations, _>(|state| {
        // A re-synthesis that no longer attests must not leave a stale entry behind.
        match attestation.gap_class {
            Some(class) => {
                state.by_def_path.insert(def_path.to_string(), class);
            }
            None => {
                state.by_def_path.remove(def_path);
            }
        }
        if attestation.marked_sites.is_empty() {
            state.fold_sites_by_def_path.remove(def_path);
        } else {
            state.fold_sites_by_def_path.insert(def_path.to_string(), attestation.marked_sites);
        }
    });
}

fn session_panic_freedom_fold_sites(sess: &Session, def_path: &str) -> Option<Vec<String>> {
    sess.with_trust_compiler_state::<SessionGapClassAttestations, _>(|state| {
        state.fold_sites_by_def_path.get(def_path).cloned()
    })
}

/// Trust (2026-09-23): the rows the fail-closed gate must judge — every
/// transport row, plus one row per MARKED site folded into this function's
/// whole-function panic-freedom aggregate.
///
/// THE HOLE THIS CLOSES (measured on stage1 `96f2019566`):
///
///     pub fn g(a: i32, b: i32, c: u32, d: u32) -> u32 {
///         let _ = a.checked_add(b);
///         c.wrapping_div(d)
///     }
///
/// built exit 0 on the default verifying lane, and `g(1, 2, 7, 0)` panics
/// ("attempt to divide by zero"). The bridge folds every absent/foreign panic
/// source of the bundle into ONE aggregate row whose description is the FIRST
/// marked site; here that is the vanilla `checked_add`, so the gate tolerated the
/// row and never saw `wrapping_div`, which it refuses on its own. Swapping the
/// two statements refused. A verdict that depends on statement order is not a
/// verdict about the program.
///
/// The per-row predicates stay the single authority: each folded site is
/// re-judged by them exactly as if it had been the representative, so the gate
/// tolerates the aggregate only when it would have tolerated EVERY site. Only an
/// unproved row carrying an assumption marker stands for the fold. The original
/// row is kept, so this can add refusals and never removes one.
///
/// Trust (memory, 2026-11-01): the transport rows are BORROWED, and only the per-site
/// rows are built. This used to return `rows.to_vec()` plus the site rows, a deep copy
/// of every row on every call — once per verified body in the pass, and again for each
/// writer-relative premise asked of a body whose slot is still full — including each
/// certified row's `clean_cic` kernel payload (several MB of `serde_json::Value` per row;
/// see [`premise_transport_row`]). Every reader only iterates the judged rows.
fn transport_rows_with_fold_sites<'a>(
    rows: &'a [TransportObligationResult],
    fold_sites: Option<&[String]>,
) -> FoldJudgedRows<'a> {
    let mut sites_judged = Vec::new();
    if let Some(sites) = fold_sites
        && let Some(aggregate) = rows.iter().find(|row| transport_row_stands_for_fold(row))
    {
        sites_judged.reserve(sites.len());
        for site in sites {
            let mut row = aggregate.clone();
            row.description = site.clone();
            sites_judged.push(row);
        }
    }
    FoldJudgedRows { transport: rows, sites: sites_judged }
}

/// The rows the fail-closed gate judges ([`transport_rows_with_fold_sites`]): the
/// body's transport rows, borrowed, then one row per marked site folded into its
/// panic-freedom aggregate (the aggregate with that site's text), in that order.
struct FoldJudgedRows<'a> {
    transport: &'a [TransportObligationResult],
    sites: Vec<TransportObligationResult>,
}

impl FoldJudgedRows<'_> {
    /// Every judged row: the transport rows, then the per-site rows.
    fn iter(&self) -> impl Iterator<Item = &TransportObligationResult> {
        self.transport.iter().chain(self.sites.iter())
    }
}

/// Does this unproved row stand for the whole-function panic-freedom FOLD, i.e.
/// is its text a per-site marker the aggregate's representative was chosen from?
fn transport_row_stands_for_fold(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && PANIC_FREEDOM_FOLD_MARKERS.iter().any(|marker| row.description.contains(marker))
}

/// The five bridge markers a per-site `PanicFreedom` obligation can carry — the
/// set the aggregate's representative is chosen from.
const PANIC_FREEDOM_FOLD_MARKERS: [&str; 5] = [
    trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX,
    trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX,
    trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX,
    trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX,
    trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX,
];

/// Every MARKED per-site `PanicFreedom` obligation folded into this module's
/// whole-function aggregate, in module order: function-level aggregates (the
/// claim, not a source) and sites whose `Assert` is over a constant `true` (they
/// can never fire, so they fold nothing) are skipped.
///
/// DROP GLUE is left out on purpose. A co-folded drop has a TYPE-based authority
/// that sees more than its row text: `masked_fail_closed_source`
/// (`drop_ty_has_masked_fail_closed_glue`) refuses a user `Drop` or a foreign
/// allocator parameter and admits pure-sysroot glue as vanilla, which is the
/// policy-B argument itself. Re-judging a drop site here by its prefix alone would
/// refuse `std::env::args().skip(1)` for dropping `Skip<Args>` (measured:
/// `policy_b/absent_sysroot_callee_run_pass.rs`). What this list adds is the
/// class no MIR scan covers: a sysroot callee that is not vanilla because it
/// panics on the caller's value (`wrapping_div`), hidden behind a tolerated one.
fn panic_freedom_fold_marked_sites(module: &trust_ir::Module) -> Vec<String> {
    let const_true_assert_sites = module_const_true_assert_sites(module);
    module
        .proof_obligations
        .iter()
        .filter(|obligation| obligation.kind == trust_ir::ObligationKind::PanicFreedom)
        .filter(|obligation| {
            let source_id = member_panic_census_source_id(obligation);
            !(source_id.starts_with("mir-assertions:") && source_id.ends_with(":panic-freedom"))
        })
        .filter(|obligation| {
            !obligation.site.is_some_and(|site| {
                const_true_assert_sites.contains(&(
                    site.function,
                    site.block,
                    site.inst_index as usize,
                ))
            })
        })
        .filter(|obligation| {
            let description = obligation.description.as_str();
            PANIC_FREEDOM_FOLD_MARKERS.iter().any(|marker| description.starts_with(marker))
                && !description.starts_with(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
        })
        .map(|obligation| obligation.description.clone())
        .collect()
}

fn session_gap_class_attestations(
    sess: &Session,
) -> FxHashMap<String, trust_types::TransportGapClass> {
    sess.with_trust_compiler_state::<SessionGapClassAttestations, _>(|state| {
        state.by_def_path.clone()
    })
}

/// The `(function, block, inst)` site of every `Assert` over a constant `true`:
/// an error rule that can never fire. Shared by the two fold readers
/// (`panic_freedom_fold_is_std_print_exclusive`, `panic_freedom_fold_marked_sites`)
/// so they agree on what folds.
fn module_const_true_assert_sites(
    module: &trust_ir::Module,
) -> FxHashSet<(trust_ir::FuncId, trust_ir::BlockId, usize)> {
    let mut sites = FxHashSet::default();
    for function in &module.functions {
        let mut true_ids: FxHashSet<trust_ir::ValueId> = FxHashSet::default();
        for block in &function.blocks {
            for (inst_index, node) in block.body.iter().enumerate() {
                match &node.inst {
                    trust_ir::Inst::Const {
                        ty: trust_ir::Ty::Bool,
                        value: trust_ir::Constant::Bool(true),
                    } => {
                        if let Some(&result) = node.results.first() {
                            true_ids.insert(result);
                        }
                    }
                    trust_ir::Inst::Assert { cond, .. } if true_ids.contains(cond) => {
                        sites.insert((function.id, block.id, inst_index));
                    }
                    _ => {}
                }
            }
        }
    }
    sites
}

/// Trust (2026-09-17): is the whole-function panic-freedom AGGREGATE of this
/// bundle attributable to the std print backend ALONE? The aggregate is ONE
/// public row per function, checked over the full native bundle, and its
/// description names only the first marked per-site obligation — so the
/// question can only be answered here, over the PER-SITE `PanicFreedom`
/// obligations the bridge minted (root and bundled members alike; a member's
/// panic site folds into the root's aggregate exactly as the root's own do).
/// Function-level aggregates (`mir-assertions:<fn>:panic-freedom`, the CLAIM
/// rather than a source) are skipped. Every remaining per-site obligation must
/// be the ABSENT-callee print-backend row — not the extern print/format/write
/// DISPATCH shape (a user `Display` reached through the machinery), not another
/// absent or expected-absent callee, not drop glue, not an unmarked user
/// `panic call ... must be unreachable` site, not an assumed-total marker — and
/// there must be at least one. Fail-closed on anything it cannot read.
///
/// SECOND GATE, over INSTRUCTIONS (adversarially found 2026-09-17): the
/// aggregate's proof is a CHC in which EVERY `Inst::Assert` of the lowered
/// bundle is an error rule, and not every assert has a `PanicFreedom`
/// obligation — a bounds/overflow check carries a `BoundsCheck` /
/// `ArithmeticSafety` obligation, and some carry none. For the ROOT those have
/// their own counted public rows, so they hide nothing; inside a bundled
/// MEMBER (a std body that survived the poison loop) they have no row anywhere.
/// So every `Inst::Assert` in the module must be one of: the print-backend
/// marker itself (a site whose obligation is the absent-callee print row), or a
/// ROOT-owned assert whose site carries a non-`PanicFreedom` obligation (its
/// own graded row). Any other assert — a member's, whatever its kind, or one
/// with no obligation at its site — withholds the class. Fail-closed by
/// construction: a member's assert of ANY kind leaves the row unclassed even
/// when the member was verified as its own root elsewhere.
/// The r09 gate, with the audited-`assume_total` predicate in place of the std-print one.
///
/// WHAT IT FIXES. `extern_call_description` may label the whole-function panic-freedom
/// AGGREGATE with an `ASSUMED_TOTAL` marker whenever no fatally-prefixed row exists, and the
/// marker then discharges the aggregate. But the aggregate is a FOLD: it covers every panic
/// source in the function, including sites that produce no marker row at all — a BUNDLED
/// callee body's own `Inst::Assert`s, for instance. Measured under `-Ztrust-policy=certify`: a
/// crate calling an unaudited absent callee FAILED, and adding an audited `write_char` on an
/// unrelated type made the same crate PASS. One audit was discharging a site it never covered.
///
/// This gate requires the fold to be the audited site(s) ALONE, which is the condition the
/// r09 `gap_class` attestation already applies to this same aggregate for the std-print gap.
///
/// DISCLOSED RESIDUAL: like r09's, both loops range over `Inst::Assert` plus `PanicFreedom`
/// obligations. trust-mc builds error rules from other sources too (integer overflow and
/// div/rem synthesized from the BinOp node, lossy casts, `Unreachable`, resolved-call
/// summaries, and `add_unsupported_error`), and a fold containing ONLY those is not inspected
/// here. So this narrows the hole rather than closing it, exactly as far as the shipped r09
/// gate's own reach — and it closes the measured case. A complete fix needs the fold
/// enumerated where it is built, in trust-mc's translator.
fn panic_freedom_fold_is_audited_assumed_total_exclusive(
    module: &trust_ir::Module,
    own_row_functions: &FxHashSet<trust_ir::FuncId>,
) -> bool {
    panic_freedom_fold_is_exclusive_for(module, own_row_functions, &|obligation| {
        obligation.kind == trust_ir::ObligationKind::PanicFreedom
            && obligation
                .description
                .starts_with(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX)
    })
}

/// The shared engine behind the two fold-exclusivity gates. `is_attested` names the ONE row
/// class the fold is allowed to consist of; everything else in the fold refuses.
fn panic_freedom_fold_is_exclusive_for(
    module: &trust_ir::Module,
    // The functions whose asserts have their OWN graded rows: the bundle root
    // (its checks are counted public VCs on this wire) and every bundled member
    // whose originating def is LOCAL and not per-instance (verified as its own
    // root in the same compile — the same exemption the bundled-member Assert
    // authority gate grants, for the same reason). Everything else in the
    // bundle is a std/dep body whose asserts are charged to nobody.
    own_row_functions: &FxHashSet<trust_ir::FuncId>,
    is_attested: &dyn Fn(&trust_ir::ProofObligation) -> bool,
) -> bool {
    let is_absent_std_print = is_attested;
    // Trust: 2026-09-20 — the sites of every `Assert` over a CONSTANT TRUE
    // condition, precomputed so the obligation scan below can skip the rows
    // that ride on them.
    //
    // An error rule whose condition is a constant `true` CAN NEVER FIRE, so it
    // folds nothing into the whole-function panic-freedom aggregate that this
    // gate's class describes. Such a row therefore has no bearing on the
    // attestation, and withholding the class for it is an artifact.
    //
    // Measured, which is why this is here rather than the obvious widening.
    // `fn main() { println!("{}", 42); }` is classed. Adding one statement,
    // `let s = String::from("hi");`, withheld the class, and the
    // obligation-scan census named the row:
    //
    //   [MPC_OBLIGATION] WITHHELD kind=PanicFreedom status=Pending
    //   description=drop glue for `alloc::string::String` — discharged: proven
    //   panic-free by the structural drop classifier
    //
    // The obvious widening — skip an obligation whose `ProofStatus` is
    // `Discharged` — was written, built, and measured REACH ZERO, because that
    // row's status is `Pending` while only its DESCRIPTION says discharged.
    // `lower.rs`'s `is_panic_free_drop_ext` lane emits `Inst::Assert` over a
    // const `true` with `ProofAnnotation::NoPanic`, writes that description,
    // and mints through `add_obligation_for_last_inst`, which leaves the status
    // at its default. Setting the status there is the other repair and is NOT
    // local: `native_shadow_request` branches on `status != Pending`.
    //
    // So the key is the SHAPE OF THE CHECK, which is structural, present, and
    // cannot be spoofed by prose — the discipline
    // `tests/e2e_two_language_programs.sh` demands ("widened by an explicit
    // allowlist, never by loosening the recognizer"). Detector and consumer are
    // the same walk, as `const_false_assert_sites` in `trust-thir-lower`
    // explains for the mirror-image case.
    let const_true_assert_sites = module_const_true_assert_sites(module);

    let mut std_print_sites = 0usize;
    for obligation in &module.proof_obligations {
        if obligation.kind != trust_ir::ObligationKind::PanicFreedom {
            continue;
        }
        let source_id = member_panic_census_source_id(obligation);
        if source_id.starts_with("mir-assertions:") && source_id.ends_with(":panic-freedom") {
            continue;
        }
        // A row whose STEP-1 site is an `Assert(const true)` states a check that
        // can never fail. It folds nothing, so it does not withhold.
        if let Some(site) = obligation.site
            && const_true_assert_sites.contains(&(
                site.function,
                site.block,
                site.inst_index as usize,
            ))
        {
            if member_panic_census_enabled() {
                eprintln!(
                    "[MPC_OBLIGATION] ADMITTED-CONST-TRUE-ASSERT kind={:?} status={:?} \
                     source_id={}",
                    obligation.kind,
                    obligation.status,
                    member_panic_census_source_id(obligation),
                );
            }
            continue;
        }
        if !is_absent_std_print(obligation) {
            // Trust: 2026-09-20 — the OBLIGATION-scan half of the census.
            //
            // The instruction scan below already prints one `[MPC_ASSERT]` line
            // per assert. This half printed nothing, so a fold withheld HERE
            // left no trace at all: measured on `let s = String::from("hi");
            // println!("{}", s.len())`, the census printed zero lines and the
            // class was silently absent, because this loop returned before the
            // instruction scan ever ran. A gate that withholds invisibly is the
            // one shape a census cannot otherwise help with.
            if member_panic_census_enabled() {
                eprintln!(
                    "[MPC_OBLIGATION] WITHHELD kind={:?} status={:?} site={:?} \
                     const_true_sites={} source_id={} description={}",
                    obligation.kind,
                    obligation.status,
                    obligation.site.map(|s| (
                        s.function.index(),
                        s.block.index(),
                        s.inst_index as usize
                    )),
                    const_true_assert_sites.len(),
                    member_panic_census_source_id(obligation),
                    obligation.description,
                );
            }
            return false;
        }
        std_print_sites += 1;
    }
    if std_print_sites == 0 {
        if member_panic_census_enabled() {
            eprintln!("[MPC_OBLIGATION] WITHHELD no std print site in the fold");
        }
        return false;
    }
    for function in &module.functions {
        for block in &function.blocks {
            for (inst_index, node) in block.body.iter().enumerate() {
                if !matches!(node.inst, trust_ir::Inst::Assert { .. }) {
                    continue;
                }
                // An obligation is ABOUT this assert if it carries the exact
                // STEP-1 site, or — the absent-callee / panic-call marker arms,
                // which the bridge deliberately leaves unattributed because a
                // helper pushes through `body` between the marker and the
                // obligation — if it is siteless, owned by this function, and
                // its source id names this block's terminator
                // (`mir-assert:<fn>:bb<N>:terminator`; measured on r09, the
                // `_print` marker at `main` bb3 is exactly that shape).
                let terminator_tag = format!(":bb{}:terminator", block.id.index());
                let linked_to = |obligation: &&trust_ir::ProofObligation| match obligation.site {
                    Some(site) => {
                        site.function == function.id
                            && site.block == block.id
                            && site.inst_index as usize == inst_index
                    }
                    None => {
                        obligation.function == Some(function.id)
                            && member_panic_census_source_id(obligation).ends_with(&terminator_tag)
                    }
                };
                let mut linked = false;
                let mut accounted = false;
                let mut kinds: Vec<String> = Vec::new();
                for obligation in module.proof_obligations.iter().filter(linked_to) {
                    linked = true;
                    kinds.push(format!("{:?}", obligation.kind));
                    accounted |= is_absent_std_print(obligation)
                        || (own_row_functions.contains(&function.id)
                            && obligation.kind != trust_ir::ObligationKind::PanicFreedom);
                }
                if member_panic_census_enabled() {
                    eprintln!(
                        "[MPC_ASSERT] fn={} block={} inst={} own_row={} linked={:?} accounted={}",
                        function.name,
                        block.id.index(),
                        inst_index,
                        own_row_functions.contains(&function.id),
                        kinds,
                        accounted
                    );
                }
                if !(linked && accounted) {
                    return false;
                }
            }
        }
    }
    true
}

/// The r09 std-print fold gate: the fold must be the absent `_print` site alone.
fn panic_freedom_fold_is_std_print_exclusive(
    module: &trust_ir::Module,
    own_row_functions: &FxHashSet<trust_ir::FuncId>,
) -> bool {
    panic_freedom_fold_is_exclusive_for(module, own_row_functions, &|obligation| {
        obligation.kind == trust_ir::ObligationKind::PanicFreedom
            && obligation
                .description
                .starts_with(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
            && extern_call_row_callee(&obligation.description)
                .is_some_and(def_path_str_is_std_print_backend)
    })
}

/// Trust (HOLE A close — 2026-09-14): segment-wise recognizer for std's
/// stdout/stderr print backend on a rendered def-path STRING (used where only the
/// row description is available, with no `TyCtxt`). The path must be crate-rooted
/// at `std` and terminate in exactly `io::_print`/`io::stdio::_print` (and the
/// `_eprint` variants), matched by SEGMENTS split on `::`, never by substring
/// containment — so a dep-defined `depA::a::std::io::_print` (crate root `depA`)
/// is rejected even though it contains `std::io::_print`.
fn def_path_str_is_std_print_backend(path: &str) -> bool {
    let segs: Vec<&str> = path.split("::").collect();
    // Crate root must be the real std crate.
    if segs.first() != Some(&"std") {
        return false;
    }
    matches!(
        segs.as_slice(),
        ["std", "io", term] | ["std", "io", "stdio", term]
            if *term == "_print" || *term == "_eprint"
    )
}

/// Trust: fail-closed on absent-callee / expected-absent / drop-glue panic. Does
/// ANY transport row carry such an UNPROVEN panic-freedom assumption? Such a row
/// is a genuine undischarged panic obligation that must abort the fail-closed lane
/// (see [`transport_row_is_unproved_assumption_panic`]). Pure so it can be
/// unit-tested without a TyCtxt, and the form a compact artifact slot can answer
/// (the panic-freedom premise's `NoExcuse` reads it off `PremiseArtifacts`).
fn transport_rows_have_unproved_assumption_panic(rows: &[TransportObligationResult]) -> bool {
    transport_rows_have_unexcused_assumption_panic(rows, |_| false)
}

fn artifacts_have_unproved_assumption_panic(artifacts: &VerificationArtifacts) -> bool {
    transport_rows_have_unproved_assumption_panic(&artifacts.transport_results)
}

/// Trust (D1 increment 1): the ONE implementation behind
/// [`artifacts_have_unproved_assumption_panic`], with a row excuse plugged in —
/// is there an unproved assumption-panic row that `excused` does not excuse?
/// The absolute bar passes `|_| false`; the writer-relative bar
/// (`fmt_writer_relative`) passes its writer-edge test over the fold-expanded
/// rows. An excuse can only remove a row from THIS question.
fn transport_rows_have_unexcused_assumption_panic<'r>(
    rows: impl IntoIterator<Item = &'r TransportObligationResult>,
    excused: impl Fn(&TransportObligationResult) -> bool,
) -> bool {
    rows.into_iter().any(|row| transport_row_is_unproved_assumption_panic(row) && !excused(row))
}

/// Trust (I5 cross-authority call modeling, ruling v7/D3): split this
/// function's unproved assumption-panic rows into the LOCAL Clean-origin
/// absent callees — returned as `(callee_def_path, clean_declaration_name)`,
/// deduplicated — and a flag for whether any OTHER unproved assumption-panic
/// row remains (a genuine std/extern absent callee, drop glue, or an extern
/// dispatch row: anything whose text does not parse to a registry member).
///
/// The recorded defect this serves: the strict-summary note described EVERY
/// absent callee as "a std/extern function whose body is not in the lowered
/// bundle", which is FALSE for a Clean-origin callee — it is local and
/// kernel-defined in the very crate being compiled
/// (`tests/ui/trust/clean_origin_verify_on.rs` pinned this). The caller uses
/// the split to name such a callee truthfully, with options, and to keep the
/// generic note only for rows it still truthfully describes.
///
/// Matching is by the exact `safe_def_path_str` spelling of each registry def
/// against the name inside the bridge's fatal absent-callee marker text (the
/// same `ABSENT_CALLEE_ASSUMPTION_CALLEE_PREFIX` parse the adversarial-witness
/// predicate uses). A name that does not parse or does not match keeps the
/// generic note — fail-safe: this helper can only make the diagnostic MORE
/// specific, never suppress it. Crates with no `clean { … }` island skip the
/// row scan entirely.
fn clean_origin_absent_callees_in_artifacts(
    tcx: TyCtxt<'_>,
    artifacts: &VerificationArtifacts,
) -> (Vec<(String, String)>, bool) {
    let mut registry: Vec<(String, String)> = Vec::new();
    for local in crate::clean_origin_mir::clean_origin_defs(tcx) {
        if let Some((decl, _span)) =
            crate::clean_origin_mir::clean_origin_registry_entry(tcx, local)
        {
            registry.push((trust_mir_extract::safe_def_path_str(tcx, local.to_def_id()), decl));
        }
    }
    let mut clean_origin_hits: Vec<(String, String)> = Vec::new();
    let mut other_rows = false;
    if registry.is_empty() {
        return (clean_origin_hits, artifacts_have_unproved_assumption_panic(artifacts));
    }
    for row in artifacts
        .transport_results
        .iter()
        .filter(|row| transport_row_is_unproved_assumption_panic(row))
    {
        let parsed_callee = row
            .description
            .split(ABSENT_CALLEE_ASSUMPTION_CALLEE_PREFIX)
            .nth(1)
            .and_then(|rest| rest.split('`').next());
        match parsed_callee.and_then(|name| registry.iter().find(|(def_path, _)| def_path == name))
        {
            Some((def_path, decl)) => {
                if !clean_origin_hits.iter().any(|(existing, _)| existing == def_path) {
                    clean_origin_hits.push((def_path.clone(), decl.clone()));
                }
            }
            None => other_rows = true,
        }
    }
    (clean_origin_hits, other_rows)
}

/// Trust (assumption-root gate), IN-BAND half: does this body's own ledger show a
/// `#[trust::assume_total]` axiom being SPENT — either as a recorded
/// `assumption:assumed-total-callee` row, or as the in-process
/// `trust-assumed-total` discharge that mints one?
///
/// The out-of-band census (`verdict_rests_on_user_axiom`) is what closes the
/// measured hole, because in the reduction case there is no row here at all. This
/// predicate is the other direction: whenever the axiom DID leave a row, the
/// refusal follows from the body's own ledger and does not depend on the census
/// having been taken. Two independent witnesses of one fact, both fail-closed;
/// neither is load-bearing alone.
///
/// `transport_row_is_unproved_assumed_total_callee` matches on a description
/// substring, and that string is user-reachable (its own doc records the hazard).
/// Used HERE it can only cost completeness: a forged marker declines a premise,
/// never grants one.
///
/// Split in two so the compact artifact slot can answer it (see
/// `PremiseArtifacts::spends_a_user_assumed_total_axiom`, its one reader): the
/// transport half here, over rows the slot keeps, and the `results` half in
/// [`results_discharge_by_assumed_total`], which the slot precomputes because it
/// drops the results.
fn transport_rows_spend_a_user_assumed_total_axiom(rows: &[TransportObligationResult]) -> bool {
    rows.iter().any(|row| {
        transport_row_is_assumed_total_assumption(row)
            || transport_row_is_unproved_assumed_total_callee(row)
    })
}

/// The `results` half of the in-band assumed-total witness above.
fn results_discharge_by_assumed_total(
    results: &[(VerificationCondition, VerificationResult)],
) -> bool {
    results.iter().any(|(_, result)| is_assumed_total_discharge(result))
}

/// Trust (assumption ledger, W3.6): does this transport row count as a REAL
/// obligation that must be Proved before the fail-closed extern-call catch-all may
/// fire? Design-mandate rows (inventory, never a discharge target) and the extern-
/// call rows themselves are excluded by the caller; here we treat only the genuine
/// verdict outcomes as blockers, so a lingering unresolved obligation keeps the whole
/// function fail-closed (UNKNOWN), never blanket-demoted. `proved` passes; bookkeeping
/// rows (`skipped` assumptions, `cached`, `no_obligations`→`proved`) do not block.
///
/// Stated as "neither discharged nor a bookkeeping skip" rather than as a list of
/// blocking outcomes: an outcome this compiler has not heard of is by definition
/// unresolved, so the fail-closed reading is the one that survives a widened
/// taxonomy.
fn transport_row_blocks_extern_call_demotion(row: &TransportObligationResult) -> bool {
    !row.outcome.is_proved() && !row.outcome.is_skipped()
}

/// Trust (assumption ledger, W2.1): rows that SURVIVE the native-lowering collapse.
/// A genuine PROOF (`proved`) and a genuine REFUTATION (`failed`) must both survive —
/// only the POISONED (unknown/unsupported/runtime-checked/…) rows fold into the single
/// `assumption:native-lowering` row. SOUNDNESS: never hide a refutation behind an
/// assumption (a `failed` row must keep failing the crate closed). That includes a
/// Level-0 refutation the compiler stamped `failed` (`rows_with_l0_refutations`),
/// which therefore stays visible under memory-safe instead of being folded.
fn native_lowering_collapse_keeps_row(row: &TransportObligationResult) -> bool {
    matches!(row.outcome, Outcome::Proved | Outcome::Failed)
        || (row.kind.strip_prefix("assumption:")
            == Some(trust_types::assumption::MEMORY_SAFE_PANIC_ASSUMPTION_TAG)
            && row.solver == trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE
            && row.outcome == Outcome::Skipped)
}

fn vc_kind_has_contract_panic_marker(kind: &VcKind) -> bool {
    let classified = |text: &str| {
        trust_types::tolerance::classify_contract_panic(
            &trust_types::tolerance::ContractPanicView { text, row_kind: None },
        ) != trust_types::tolerance::ContractPanicClass::None
    };
    match kind {
        VcKind::Assertion { message } => classified(message),
        VcKind::UnsupportedMir { kind, detail } => classified(kind) || classified(detail),
        _ => false,
    }
}

fn vc_kind_has_expected_absent_callee_marker(kind: &VcKind) -> bool {
    let has_marker = |text: &str| {
        text.contains(trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX)
    };
    match kind {
        VcKind::Assertion { message } => has_marker(message),
        VcKind::UnsupportedMir { kind, detail } => has_marker(kind) || has_marker(detail),
        _ => false,
    }
}

fn vc_kind_has_assumed_total_callee_marker(kind: &VcKind) -> bool {
    let has_marker =
        |text: &str| text.contains(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX);
    match kind {
        VcKind::Assertion { message } => has_marker(message),
        VcKind::UnsupportedMir { kind, detail } => has_marker(kind) || has_marker(detail),
        _ => false,
    }
}

/// Whether a typed VC failure is exactly a Rust runtime panic that the explicit
/// memory-safe policy may conditionally admit. This is intentionally narrower
/// than all L0 kinds: hardened findings, raw/ownership/FFI memory safety,
/// unbounded-allocation policy, contracts, and other non-panic properties stay
/// fail-closed even in a source-unsafe-free function.
fn vc_kind_is_memory_safe_panic(kind: &VcKind) -> bool {
    if kind.hardened_category().is_some()
        || vc_kind_has_contract_panic_marker(kind)
        || vc_kind_has_expected_absent_callee_marker(kind)
        || vc_kind_has_assumed_total_callee_marker(kind)
    {
        return false;
    }
    match kind {
        VcKind::ArithmeticOverflow { .. }
        | VcKind::ShiftOverflow { .. }
        | VcKind::DivisionByZero
        | VcKind::RemainderByZero
        | VcKind::IndexOutOfBounds
        | VcKind::SliceBoundsCheck
        | VcKind::NegationOverflow { .. }
        | VcKind::Unreachable => true,
        VcKind::Assertion { .. } => true,
        VcKind::UnsupportedMir { kind: unsupported_kind, .. } => {
            // Known unwrap/expect panic gaps and native arithmetic/bounds
            // round-trips are panic-class. Native MemorySafety is deliberately
            // excluded: an unsupported UB obligation is never a safe panic.
            is_known_panicking_call_unsupported_mir(kind)
                || unsupported_kind.starts_with("FullVerification::ArithmeticSafety")
                || unsupported_kind.starts_with("FullVerification::BoundsCheck")
        }
        _ => false,
    }
}

/// Reclassify only compiler-typed, genuinely FAILED safe-panic rows into the
/// explicit memory-safe assumption protocol. The caller passes `enabled` only
/// after `memory_safe_demotion_applies` established both the tracked flag and
/// the absence of source/inlined unsafe code.
///
/// Fail-closed invariants:
/// * typed results and flat rows must be exactly index-aligned;
/// * both layers must say `failed`;
/// * only the narrow panic-kind classifier above qualifies;
/// * proofs, non-panic failures, contract panics, mandates, and every unsafe-body
///   invocation remain byte-unchanged.
fn rewrite_memory_safe_panic_refutation_rows(
    enabled: bool,
    results: &[(VerificationCondition, VerificationResult)],
    rows: &[TransportObligationResult],
) -> Option<Vec<TransportObligationResult>> {
    if !enabled || results.len() != rows.len() {
        return None;
    }
    let mut changed = false;
    let rewritten = results
        .iter()
        .zip(rows)
        .map(|((vc, result), row)| {
            if !matches!(result, VerificationResult::Failed { .. })
                || !row.outcome.is_failed()
                || row.design_mandate
                || transport_row_is_failed_contract_panic(row)
                || transport_row_is_failed_contract_panic_unused(row)
                || transport_row_is_unproved_expected_absent_callee(row)
                || transport_row_is_unproved_assumed_total_callee(row)
                || !vc_kind_is_memory_safe_panic(&vc.kind)
            {
                return row.clone();
            }

            changed = true;
            let mut assumption = row.clone();
            assumption.kind =
                format!("assumption:{}", trust_types::assumption::MEMORY_SAFE_PANIC_ASSUMPTION_TAG);
            // A synthetic assumption classification must not retain the
            // original VC's typed identity — nor the gap class, which is
            // attested for the aggregate ASSERT row and nothing else.
            assumption.original_vc_snapshot = None;
            assumption.typed_kind = None;
            assumption.gap_class = None;
            // Rebuild rather than copy the raw native description: an
            // UnsupportedMir row can contain `FullVerification::...`, which a
            // downstream evidence classifier treats as a full-verifier marker.
            // Assumption text must be clean so it can never masquerade as proof
            // evidence (the source location/counterexample still identify the
            // original failure).
            assumption.description =
                "unverified memory-safe panic: a typed Level-0 Rust runtime panic remains \
                 reachable (conditional policy result, not proved)"
                    .to_string();
            assumption.outcome = Outcome::Skipped;
            assumption.solver =
                trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE.to_string();
            assumption.reason = Some(
                "the explicit memory-safe policy admitted this reachable Rust runtime panic only \
                 because the compiler established that the function contains neither source nor \
                 inlined unsafe code; this is an assumption, never proof credit"
                    .to_string(),
            );
            // A failed native/solver artifact is useful diagnostic history, but
            // it is not proof evidence for the newly-classified assumption and
            // must not survive under a proof-looking field.
            assumption.native_trust_ir = None;
            assumption.proof_evidence = None;
            assumption.claim_digest_sha256 = None;
            assumption
        })
        .collect();
    changed.then_some(rewritten)
}

fn transport_row_is_authenticated_memory_safe_assumption(row: &TransportObligationResult) -> bool {
    row.kind.starts_with("assumption:")
        && row.outcome == Outcome::Skipped
        && row.solver == trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE
        && !row.design_mandate
        && row.native_trust_ir.is_none()
        && row.proof_evidence.is_none()
}

/// The authenticated `assumption:native-lowering` collapse row
/// (`demote_transport_rows_for_default_lane`). It REPLACES the rows the collapse
/// does not keep and has no VC counterpart, so when it is present the human line
/// counts the published rows (`PublishedRowTally`); and it is the ONLY thing that
/// may account for a failed lowering under memory-safe.
fn transport_row_is_authenticated_native_lowering_assumption(
    row: &TransportObligationResult,
) -> bool {
    row.kind.strip_prefix("assumption:")
        == Some(trust_types::assumption::NATIVE_LOWERING_ASSUMPTION_TAG)
        && transport_row_is_authenticated_memory_safe_assumption(row)
}

/// Typed non-proved shapes the memory-safe policy may send through its
/// row-level classifier. The effective-row gate below is still authoritative:
/// a candidate that was not actually rewritten to an authenticated assumption
/// remains fatal. Functional contracts, UB/memory/ownership, hardened, and
/// domain obligations are deliberately absent.
fn vc_kind_is_memory_safe_demotable_gap(kind: &VcKind) -> bool {
    if vc_kind_has_contract_panic_marker(kind)
        || vc_kind_has_expected_absent_callee_marker(kind)
        || vc_kind_has_assumed_total_callee_marker(kind)
    {
        return false;
    }
    if vc_kind_is_memory_safe_panic(kind) {
        return true;
    }
    matches!(
        kind,
        VcKind::UnsupportedMir { kind, detail }
            if kind.starts_with("FullVerification::ArithmeticSafety")
                || kind.starts_with("FullVerification::BoundsCheck")
                || kind.starts_with("FullVerification::Assertion")
                || detail.contains(KNOWN_PANICKING_CALL_UNSUPPORTED_MARKER)
    )
}

/// Trust (2026-10-10, ZERO-ROW-GATE): the memory-safe twin of the strict gate's
/// empty-inventory question. A body with zero bridged obligations is admissible
/// on its empty inventory only when the publisher called it vacuously clean
/// (`zero_obligation_native_vacuously_clean`, which also asks whether every call
/// is discharged by an authenticated registry). `memory_safe_artifacts_have_non_
/// demotable_failure`'s own zero-row branch asks only `native_run_is_vacuously_
/// clean`, so before this a body whose calls no registry discharges published an
/// `unknown` `native-verification-gap` row and exited 0 under memory-safe too.
/// `None` means the body has bridged obligations; this question does not apply.
fn memory_safe_zero_obligation_body_is_unclean(
    artifacts: &VerificationArtifacts,
    zero_obligation_vacuously_clean: Option<bool>,
) -> bool {
    artifacts.proof_results.summary.total == 0 && zero_obligation_vacuously_clean != Some(true)
}

/// Compiler-side counterpart of Targo's memory-safe result gate. The raw
/// compiler must not exit 0 merely because a no-unsafe function selected the
/// policy: every non-proved row must have been *actually* reclassified by the
/// compiler under the shared authenticated source label, and every typed raw
/// gap must belong to the narrow safe-panic/capability family.
fn memory_safe_artifacts_have_non_demotable_failure(
    artifacts: &VerificationArtifacts,
    effective_rows: &[TransportObligationResult],
) -> bool {
    // A failed native lowering is admissible here ONLY through the authenticated
    // collapse row, which the demotion mints only when the body makes no call out of
    // the verified closure (`memory_safe_assumption_uncharged_edges`). Without it
    // the rows left are the ones the VC layer could see, and a clean-looking set of
    // them says nothing about the calls the lowering never charged (on stage-1
    // `b4bc7cdf9d` the `exit`-guarded `dep::deref_raw` read carried ONE VC row, a
    // proved bounds check, which every check below accepts).
    if artifacts.full_verification.as_ref().is_some_and(native_run_trust_ir_lowering_failed)
        && !effective_rows.iter().any(transport_row_is_authenticated_native_lowering_assumption)
    {
        return true;
    }
    let has_unauthenticated_nonproved_row = effective_rows.iter().any(|row| {
        !row.outcome.is_proved()
            && !transport_row_is_authenticated_memory_safe_assumption(row)
            && !transport_row_is_assumed_total_assumption(row)
            // §5 STEP 5: the DISCHARGED `contract:global-alloc-dealloc-panic-
            // free` row is compiler-published conditional evidence (its
            // premise is established against the crate graph in view), not an
            // unproved gap — admit it here exactly like the authenticated
            // ledger shapes. The REFUSED kind deliberately fails this
            // predicate and keeps the memory-safe lane fail-closed, mirroring
            // the unproved coroutine premise's treatment.
            && !transport_row_is_discharged_global_alloc_dealloc_contract(row)
            // Trust (D9, critique H1): the `termination-unmeasured` charge is a
            // disclosed termination premise, not a memory-safety gap; the ruling
            // makes it CONDITIONAL on the default lane, and refusing it here would
            // be a capability loss nobody ratified (`helper`/`unit` built rc 0
            // under memory-safe before the charge existed). Exact shape only.
            && !termination_unmeasured::transport_row_is_termination_unmeasured_assumption(row)
    });
    if artifacts.proof_results.summary.total == 0 {
        let native_gap = match artifacts.full_verification.as_ref() {
            Some(run) => !native_run_is_vacuously_clean(run),
            None => !(artifacts.results.is_empty() && artifacts.transport_results.is_empty()),
        };
        // Synthetic policy rows are additive to the verifier's real-obligation
        // count. In particular, a coroutine protocol premise can be the only
        // effective row even when native verification is otherwise vacuously
        // clean; memory-safe must still reject that unauthenticated premise.
        return native_gap || has_unauthenticated_nonproved_row;
    }

    // A raw Proved result only counts when its exact private authority is an
    // independent static proof. `Trusted + None` is the contract-assumed
    // bookkeeping bucket and must not bypass the memory-safe proof gate.
    for (index, (vc, result)) in artifacts.results.iter().enumerate() {
        let authority = artifacts.proof_authorities.get(index).and_then(Option::as_ref);
        let binding = artifacts.result_bindings.get(index).and_then(Option::as_ref);
        let statically_accepted = authority
            .is_some_and(|authority| authority.is_static_proof_for(index, vc, result, binding));
        let exact_entry_assumption = authority.is_some_and(|authority| {
            authority.is_definition_entry_assumption_for(index, vc, binding)
        });
        let exact_assumed_total = authority.is_some_and(|authority| {
            authority.is_assumed_total_callee_assumption_for(index, vc, binding)
        });
        // The def-site marker is not a safety obligation to discharge; it is
        // the exact conditional premise under which the body was verified.
        // Ignore it here without counting it as static proof.
        if statically_accepted || exact_entry_assumption || exact_assumed_total {
            continue;
        }
        if matches!(result, VerificationResult::Proved { .. })
            || !vc_kind_is_memory_safe_demotable_gap(&vc.kind)
        {
            return true;
        }
    }

    // Trust (D9, review F2): a body that generated obligations but published no
    // row for them is fail-closed. The guard used to read `effective_rows.
    // is_empty()`, which a `termination-unmeasured` charge defeats: the charge
    // rows make the set non-empty although no row speaks for any obligation. So
    // the guard asks whether EVERY effective row is a D9 charge row (vacuously
    // true for the empty set, so the pre-D9 case is unchanged).
    effective_rows
        .iter()
        .all(termination_unmeasured::transport_row_is_termination_unmeasured_assumption)
        || has_unauthenticated_nonproved_row
}

fn abort_on_memory_safe_non_demotable_failure<'tcx>(

    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &VerificationArtifacts,
    effective_rows: &[TransportObligationResult],
    // Trust (2026-10-10, ZERO-ROW-GATE): the publisher's verdict on a zero-
    // obligation body (`zero_obligation_native_vacuously_clean`); `None` when the
    // body has bridged obligations.
    zero_obligation_vacuously_clean: Option<bool>,
) {
    if let Some(diagnostic) = publication_memory_safe::prepare_memory_safe_non_demotable_failure(
        tcx, body, func_path, artifacts, effective_rows, zero_obligation_vacuously_clean,
    ) {
        diagnostic.emit(tcx, body.span);
    }
}

/// Trust (assumption ledger, W3.6): the fail-closed gate — is every OTHER counted
/// obligation Proved, so the marked extern-call row(s) may demote? Design-mandate
/// rows (inventory) and the extern-call rows themselves are excluded; any remaining
/// `failed`/`unknown`/`runtime_checked`/`timeout` row BLOCKS the demotion (keep the
/// function fail-closed / UNKNOWN — never blanket-demote a genuine gap). Pure so it
/// can be unit-tested without a TyCtxt.
fn extern_call_demotion_others_all_proved(rows: &[TransportObligationResult]) -> bool {
    rows.iter().all(|row| {
        if row.design_mandate || transport_row_is_unproved_extern_call(row) {
            return true;
        }
        !transport_row_blocks_extern_call_demotion(row)
    })
}

/// Trust (assumption ledger): the pure decision core for
/// [`demote_transport_rows_for_default_lane`], factored out so the F2 strict-lane
/// gate, the W2.1 memory-safe gate, and the W3.6 fail-closed extern-call gate can be
/// unit-tested without a TyCtxt.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DefaultLaneDemotion {
    /// Emit the original rows unchanged.
    None,
    /// Collapse poisoned non-proved rows into one `assumption:native-lowering` row.
    NativeLowering,
    /// Demote the marked extern-call rows to `assumption:extern-call`.
    ExternCall,
    /// FIX b59: demote ONLY the `fmt::format` (`format!` backend) dispatch rows to
    /// `assumption:extern-call`, leaving any stdout `_print`/`_eprint` leg (SIGPIPE
    /// hazard) and every other row untouched. This is the one demotion the
    /// fail-closed / non-memory-safe lanes permit.
    FmtFormat,
}

fn default_lane_demotion_decision(
    strict_enforcement: bool,
    fmt_format_demotable: bool,
    memory_safe: bool,
    lowering_failed: bool,
    has_unproved_extern_call: bool,
    others_all_proved: bool,
) -> DefaultLaneDemotion {
    // Strict enforcement never demotes an ORDINARY gap. An explicit memory-safe
    // policy passes `false` here only after proving the function contains no `unsafe`.
    //
    // FIX b59: the ONE exception both fail-closed guards now permit is the SAFE
    // `fmt::format` (the `format!` macro backend) subset — `fmt_format_demotable` is
    // set by the caller only after pinning BOTH existing guards: the no-`unsafe` half
    // of `memory_safe_demotion_applies` (an unsafe gap could be UB the fmt panic masks)
    // AND `extern_call_demotion_others_all_proved` (every OTHER obligation Proved, so
    // demoting the fmt row can never mask a real failure elsewhere), scoped to the
    // `::fmt::format` callee so the SIGPIPE-hazard `_print`/`_eprint` stdout legs are
    // EXCLUDED. The fmt `Display` CAN panic, but the row is recorded as an HONEST
    // `assumption:extern-call` ledger entry (never claimed proved) — the
    // allocator-class trust boundary, exactly as the memory-safe lane already demotes
    // it below. This clears the `ny-cert` survey lane's `fmt::format` UNKNOWN rows.
    if strict_enforcement {
        return fmt_format_demotion_only(fmt_format_demotable);
    }
    // W2.1: only a memory-safe (no-unsafe) function demotes a BROAD gap; an unsafe gap
    // could be UB. The safe `fmt::format` subset is still permitted here — this is the
    // survey lane (`ny-cert`) that runs WITHOUT the memory-safe flag.
    if !memory_safe {
        return fmt_format_demotion_only(fmt_format_demotable);
    }
    // The native-lowering backstop takes precedence: a failed lowering left no usable
    // per-obligation rows, so the whole function's gap collapses to one honest row.
    if lowering_failed {
        return DefaultLaneDemotion::NativeLowering;
    }
    // Extern-call demotion is fail-closed: only when a marked row exists AND every
    // OTHER counted obligation is Proved (W3.6). Otherwise stay UNKNOWN.
    if has_unproved_extern_call && others_all_proved {
        return DefaultLaneDemotion::ExternCall;
    }
    DefaultLaneDemotion::None
}

/// FIX b59: the safe-subset demotion decision shared by the two fail-closed guards of
/// [`default_lane_demotion_decision`] — demote to the `fmt::format`-only leg when the
/// caller certified it demotable, otherwise stay fail-closed / UNKNOWN.
fn fmt_format_demotion_only(demotable: bool) -> DefaultLaneDemotion {
    if demotable { DefaultLaneDemotion::FmtFormat } else { DefaultLaneDemotion::None }
}

/// FIX b59: the pure gate for the safe `fmt::format` subset demotion. ALL THREE pins
/// are required (any one false keeps the function fail-closed / UNKNOWN):
///   * `has_fmt_format` — the function has an unproved `fmt::format` dispatch row (the
///     safe subset; the caller excludes the `_print`/`_eprint` stdout legs);
///   * `function_is_unsafe_free` — the no-`unsafe` half of `memory_safe_demotion_applies`
///     (an unsafe gap could be UB the fmt panic masks);
///   * `others_all_proved` — `extern_call_demotion_others_all_proved` (every OTHER
///     obligation Proved, so demoting the fmt row can never mask a real failure).
/// Pure so it can be unit-tested without a `TyCtxt`.
fn fmt_format_demotion_gate(
    has_fmt_format: bool,
    function_is_unsafe_free: bool,
    others_all_proved: bool,
) -> bool {
    has_fmt_format && function_is_unsafe_free && others_all_proved
}

/// Trust (T9 contract-panic): is this row a FAILED panic-freedom/assertion row
/// that trust-vcgen stamped with the contract-panic MATCHED marker? Marker
/// presence == the annotation's `message_contains` payload was a substring of a
/// `&str` CONSTANT operand of that exact panic call (site + message matched at
/// VC mint time). ONLY a `failed` row qualifies: Proved stays Proved (and feeds
/// the unused-annotation check), Unknown stays Unknown — a marker can
/// reclassify only a genuine refutation of the ANNOTATED panic, nothing else.
fn transport_row_is_failed_contract_panic(row: &TransportObligationResult) -> bool {
    // SINGLE SOURCE OF TRUTH (trust_types::tolerance): a raw row carries the marker
    // in its description (its `kind` is not yet a `contract-panic:` prefix), so
    // project the description and ask the shared classifier — do not spell the
    // marker inline. Only a `failed` row qualifies (Matched here is a refutation of
    // the annotated panic; Proved/Unknown are unaffected).
    row.outcome == Outcome::Failed
        && trust_types::tolerance::classify_contract_panic(
            &trust_types::tolerance::ContractPanicView { text: &row.description, row_kind: None },
        ) == trust_types::tolerance::ContractPanicClass::Matched
}

/// Trust (T9 contract-panic): the unused-annotation twin — the FAILED
/// always-SAT row trust-vcgen mints when a `contract_panic` annotation matched
/// NO panic call in the function.
fn transport_row_is_failed_contract_panic_unused(row: &TransportObligationResult) -> bool {
    // SINGLE SOURCE OF TRUTH (trust_types::tolerance): the anti-abuse UNUSED class —
    // an annotation that matched no panic call. Never a declared panic; stays a
    // refutation. Classified from the row description, not spelled inline.
    row.outcome == Outcome::Failed
        && trust_types::tolerance::classify_contract_panic(
            &trust_types::tolerance::ContractPanicView { text: &row.description, row_kind: None },
        ) == trust_types::tolerance::ContractPanicClass::Unused
}

/// Trust (T9 contract-panic): rewrite vcgen-stamped contract-panic rows only in
/// explicit survey policy. Returns `Some(rewritten)` when at least one row
/// rewrites, `None` to emit the original rows unchanged. Strict and memory-safe
/// therefore retain the original failed row and fail closed.
///
///   * a FAILED row carrying the MATCHED marker → kind
///     `contract-panic:matched` (source `trust-contract`), outcome stays
///     `failed` on the wire. targo's partition diverts the `contract-panic:`
///     kind prefix into the always-visible `contract_panics` bucket
///     (conditional-pass-eligible, never proof credit, fail-closed against a
///     Proved/RuntimeChecked claim);
///   * a FAILED row carrying the UNUSED marker → kind `contract-panic-unused`
///     (NOT the `contract-panic:` prefix — dash, not colon — so targo counts it
///     as a genuine FAILURE): an annotation on panic-free code is an ERROR;
///   * every other row — Proved, Unknown, and every unstamped row — is
///     BYTE-UNTOUCHED ("never hide a refutation": an unstamped `failed` row
///     keeps failing the crate closed, exactly like the native-lowering
///     collapse above keeps `failed` rows).
///
/// Contract-panic annotations remain visible conditional evidence only in the
/// broad advisory lanes, never proof credit. This is deliberately disjoint from
/// memory-safe's authenticated safe-code assumptions: an intentional panic must
/// select survey even when the function contains no `unsafe`.
fn rewrite_contract_panic_transport_rows(
    policy: &TrustVerifyPolicy,
    rows: &[TransportObligationResult],
) -> Option<Vec<TransportObligationResult>> {
    if !policy.admits_contract_panic_conditional_evidence() {
        return None;
    }

    // In survey, a declared, message-matched contract panic becomes a
    // `contract-panic:matched` row that targo partitions into its visible
    // `contract_panics` bucket (a CONDITIONAL pass, never a proof); the UNUSED
    // annotation becomes a `contract-panic-unused` row targo counts as a genuine
    // FAILURE. Strict and memory-safe keep the original failure; intentional
    // panic APIs such as `ArrayVec::push` must explicitly choose a nonfatal lane
    // rather than weakening the proof contract of the default compiler.
    if !rows.iter().any(|row| {
        transport_row_is_failed_contract_panic(row)
            || transport_row_is_failed_contract_panic_unused(row)
    }) {
        return None;
    }
    // Pass 1: reclassify the per-site panic-CALL rows (matched → `contract-panic:matched`,
    // unused → `contract-panic-unused`).
    let mut rewritten: Vec<TransportObligationResult> = rows
        .iter()
        .map(|row| {
            if transport_row_is_failed_contract_panic_unused(row) {
                let mut rewritten = row.clone();
                rewritten.kind =
                    trust_types::assumption::CONTRACT_PANIC_UNUSED_ROW_KIND.to_string();
                rewritten.original_vc_snapshot = None;
                rewritten.typed_kind = None;
                rewritten.solver = trust_types::assumption::CONTRACT_PANIC_ROW_SOURCE.to_string();
                rewritten.reason = Some(
                    "unused contract_panic annotation: its `message_contains` payload \
                     matched no panic call in this function; an annotation on panic-free \
                     code is an error"
                        .to_string(),
                );
                rewritten
            } else if transport_row_is_failed_contract_panic(row) {
                let mut rewritten = row.clone();
                rewritten.kind =
                    trust_types::assumption::CONTRACT_PANIC_MATCHED_ROW_KIND.to_string();
                rewritten.original_vc_snapshot = None;
                rewritten.typed_kind = None;
                rewritten.solver = trust_types::assumption::CONTRACT_PANIC_ROW_SOURCE.to_string();
                rewritten.reason = Some(
                    "declared contract panic: the function's contract_panic annotation \
                     message-matched this reachable panic; recorded as an intentional \
                     fail-closed panic (never a proof), counted visibly by targo"
                        .to_string(),
                );
                rewritten
            } else {
                row.clone()
            }
        })
        .collect();

    // Pass 2: the WHOLE-FUNCTION panic-freedom AGGREGATE row. The native trust-mc
    // lane cannot lower this function-level obligation to a typed CHC (it carries a
    // router-placeholder input and defers to a path-sensitive transport that does
    // not model diverging-`Call` panics), so it comes back UNKNOWN even when every
    // reachable panic is a declared contract panic — leaving `ArrayVec::push` with a
    // lone `1 unknown` after its per-site panic was already `contract-panic:matched`.
    // Reclassify that aggregate into the visible `contract_panics` bucket, but ONLY
    // when the function is CLEAN-MODULO-DECLARED-PANICS:
    //   (a) it has ≥1 `contract-panic:matched` per-site row (a declared panic to
    //       attribute the aggregate's non-freedom to), AND
    //   (b) it has NO blocking failure — no `failed` row whose kind is not itself
    //       `contract-panic:` (the aggregate row itself is excluded from this test).
    // SOUNDNESS: in a function with ≥1 obligation (which a contract-panic function
    // always is), EVERY panic — declared or not — gets its OWN per-site obligation
    // (proven empirically: an undeclared `assert!`/`panic!` alongside a declared one
    // still emits its own `panic call: core::panicking::panic` FAILED row). So any
    // UNdeclared reachable panic is a blocking failure that trips (b); an undeclared
    // panic left merely UNKNOWN keeps its own UNKNOWN row that still fails the gate.
    // The canonical-description match excludes an aggregate whose text was REPLACED by
    // a folded extern-call / absent-callee / drop-glue gap, so an unmodeled-callee
    // panic is never laundered. The aggregate never becomes `proved`. Strict
    // and memory-safe never enter this rewrite, so they retain the UNKNOWN
    // aggregate and fail closed.
    let has_matched = rewritten
        .iter()
        .any(|row| row.kind == trust_types::assumption::CONTRACT_PANIC_MATCHED_ROW_KIND);
    let has_blocking_failure = rewritten.iter().any(|row| {
        row.outcome == Outcome::Failed
            && !row.kind.starts_with(trust_types::assumption::CONTRACT_PANIC_ROW_KIND_PREFIX)
            && !transport_row_is_panic_freedom_aggregate(row)
    });
    if has_matched && !has_blocking_failure {
        for row in &mut rewritten {
            // Reclassify on any NON-`proved` outcome. The aggregate commonly comes
            // back `unknown` (native lane can't lower it) or `runtime_checked`
            // (`runtime_check_available` counts the panic itself as its own runtime
            // check) — both mean "not proven panic-free". A genuinely `proved`
            // aggregate is a real proof and is left untouched.
            if transport_row_is_panic_freedom_aggregate(row) && row.outcome != Outcome::Proved {
                row.kind = trust_types::assumption::CONTRACT_PANIC_AGGREGATE_ROW_KIND.to_string();
                row.original_vc_snapshot = None;
                row.typed_kind = None;
                // A reachable — but DECLARED — panic. Force `failed`: targo buckets a
                // `contract-panic:` row into `contract_panics` only when the outcome is
                // not `proved`/`runtime_checked` (it fail-closes either of those to a
                // transport-defect `unknown`, refusing to launder a claimed proof), so
                // `runtime_checked` must not survive on the reclassified row.
                row.outcome = Outcome::Failed;
                row.solver = trust_types::assumption::CONTRACT_PANIC_ROW_SOURCE.to_string();
                row.reason = Some(
                    "whole-function panic-freedom aggregate covered by declared contract \
                     panic(s): every reachable panic in this function is message-matched to \
                     its contract_panic annotation (no undeclared panic remains unproved), \
                     and the native lane cannot lower the function-level aggregate to a typed \
                     CHC; recorded as a conditional contract panic (never a proof)"
                        .to_string(),
                );
            }
        }
    }
    Some(rewritten)
}

/// Trust (T9 contract-panic): the WHOLE-FUNCTION panic-freedom AGGREGATE row —
/// the compiler's synthesized `assertion:panic-freedom:0` obligation carrying the
/// canonical "panic freedom: no assertion, …" description. Matching the canonical
/// text (rather than only the id) EXCLUDES an aggregate whose description was
/// replaced by a folded extern-call / absent-callee / drop-glue gap, so those
/// unmodeled-panic gaps are never reclassified as covered contract panics.
fn transport_row_is_panic_freedom_aggregate(row: &TransportObligationResult) -> bool {
    row.description.contains(trust_types::assumption::PANIC_FREEDOM_AGGREGATE_DESCRIPTION_PREFIX)
        && row.obligation_id.as_deref().is_none_or(|id| id.contains("panic-freedom"))
}

/// Trust (assumption ledger, W2.1 + W3.5/W3.6): under the explicit authenticated
/// memory-safe no-unsafe policy,
/// rewrite the transport rows a verifier CAPABILITY GAP produced into honest
/// `assumption:*` ledger rows, so code that uses `println!`/`format!` (or a construct
/// the native bridge cannot lower) COMPILES with a recorded, machine-
/// readable ledger entry instead of hard-aborting. Returns `Some(rewritten)` when it
/// fires, `None` to emit the original rows unchanged.
///
/// Fires only when strict enforcement is loosened by the explicit memory-safe
/// policy and the function contains no `unsafe`. Two disjoint cases:
///
///   * NATIVE-LOWERING backstop (W2.1): the native typed-TrustIr lowering FAILED
///     (bundle build failed → every obligation poisoned `Unsupported`). Collapse the
///     poisoned NON-proved rows into ONE `assumption:native-lowering` row (keeping any
///     genuinely-proved rows). The rebuilt row's reason is clean
///     (`transport_assumption_row`), never the poisoned rows' verbatim text — which
///     names the full verifier and would trip targo's `is_full_verifier_text` (F3).
///
///   * EXTERN-CALL demotion (W3.5/W3.6): lowering SUCCEEDED but a print/format/write
///     dispatch left an UNKNOWN panic-freedom row marked `EXTERN_CALL_ASSUMPTION_
///     PREFIX`. Demote each such row to `assumption:extern-call`, but ONLY when every
///     OTHER counted obligation (non-mandate, non-extern-call) is Proved — otherwise
///     stay fail-closed (keep UNKNOWN), never blanket-demote a genuine gap. Design-
///     mandate rows are untouched (bucketed as mandates by the targo counting).
///
/// SOUNDNESS: no row is ever rewritten to `proved`; an extern dispatch (which runs
/// arbitrary user `Display` code and CAN panic) becomes an UNVERIFIED assumption,
/// never a proof. Unmodified strict enforcement returns `None` here.
fn demote_transport_rows_for_default_lane<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    policy: &TrustVerifyPolicy,
    artifacts: &VerificationArtifacts,
    // The rows to demote: `artifacts.transport_results` with the Level-0
    // refutations already stamped (`rows_with_l0_refutations`), never the raw rows.
    base_rows: &[TransportObligationResult],
) -> Option<Vec<TransportObligationResult>> {
    let memory_safe = memory_safe_demotion_applies(tcx, body);
    let memory_safe_panics =
        rewrite_memory_safe_panic_refutation_rows(memory_safe, &artifacts.results, base_rows);
    let rows = memory_safe_panics.as_deref().unwrap_or(base_rows);
    // EXPECTED-absent is still an unproved call boundary. Only explicit
    // survey policy may turn it into a visible assumption row. Strict keeps
    // the original row and the full-verification fatal gate rejects it;
    // memory-safe likewise excludes the marker from its authenticated
    // safe-panic/capability demotions.
    let has_expected_absent = expected_absent_callee_demotion_applies(policy, rows);
    // The collapse stands only for gaps INSIDE this body: a failed lowering whose
    // body calls out of the verified closure keeps no collapse row, and
    // `memory_safe_artifacts_have_non_demotable_failure` refuses a lowering failure
    // that no collapse row accounts for. See `memory_safe_assumption_uncharged_edges`.
    let lowering_failed =
        artifacts.full_verification.as_ref().is_some_and(native_run_trust_ir_lowering_failed);
    let uncharged_edges = if memory_safe && lowering_failed {
        memory_safe_assumption_uncharged_edges(tcx, body)
    } else {
        Vec::new()
    };
    let collapsible_lowering_failure = lowering_failed && uncharged_edges.is_empty();
    let has_extern_call = rows.iter().any(transport_row_is_unproved_extern_call);
    let others_all_proved = extern_call_demotion_others_all_proved(rows);
    // FIX b59: the `fmt::format` (`format!` backend) leg is the SAFE SUBSET of the
    // extern-call rows — it builds a `String` with NO stdout sink, so (unlike the
    // `_print`/`_eprint` broken-pipe / SIGPIPE legs) it may demote in EVERY lane once
    // BOTH existing guards hold: the function is unsafe-free (the no-`unsafe` half of
    // `memory_safe_demotion_applies`) AND every OTHER obligation is Proved
    // (`extern_call_demotion_others_all_proved`). Both pins are computed HERE and fed
    // to the pure decision core as one boolean.
    let has_fmt_format_extern_call =
        rows.iter().any(transport_row_is_unproved_fmt_format_extern_call);
    // Trust (HOLE — `format!` of a user/dep Display fold-mask, 2026-09-14): the
    // b59 `fmt::format` demotion may fire ONLY when every value formatted through
    // the machinery is FOUNDATIONAL (a primitive/`str`/`String`) — exactly the
    // boundary the `println!` path uses (`function_format_args_all_foundational_
    // display`). `format!("{}", dep::D(v))` where `dep::D::fmt` panics packs a
    // `new_display::<dep::D>` in THIS body; demoting its `alloc::fmt::format` row
    // to a runtime-checked ledger entry laundered a panicking user/dependency
    // `Display`, while the byte-identical `println!` twin is a hard error. Gate
    // the demotion on the same discriminator so `format!` refuses like `println!`;
    // foundational `format!`/the `ny-cert` survey rows still demote (b59 intact).
    let fmt_format_demotable = fmt_format_demotion_gate(
        has_fmt_format_extern_call,
        !function_uses_unsafe(tcx, body),
        others_all_proved,
    ) && function_format_args_all_foundational_display(tcx, body);
    let standard = match default_lane_demotion_decision(
        policy.fail_closed() && !memory_safe,
        fmt_format_demotable,
        // W2.1: only memory-safe (no-unsafe) functions demote; an unsafe gap could be UB.
        memory_safe,
        collapsible_lowering_failure,
        has_extern_call,
        others_all_proved,
    ) {
        DefaultLaneDemotion::None => memory_safe_panics.clone(),
        DefaultLaneDemotion::NativeLowering => {
            // Keep genuine PROOFS and genuine REFUTATIONS; collapse only the POISONED
            // (unknown/unsupported/runtime-checked/…) rows into one honest
            // `assumption:native-lowering` row with REBUILT (marker-free) reason text.
            // SOUNDNESS: a `failed` row (e.g. a reachable assert the vcgen-refutation
            // path found even when the bridge could not lower the body) MUST survive so
            // targo still fails closed (F>0 → exit 1) — never hide a refutation behind
            // an assumption.
            let mut rebuilt: Vec<TransportObligationResult> = rows
                .iter()
                .filter(|row| native_lowering_collapse_keeps_row(row))
                .cloned()
                .collect();
            // Only a clean boundary DESCRIPTION survives here (F3): no full-verifier
            // marker strings, no verbatim poisoned-row reason.
            let detail = "native typed-TrustIr lowering did not complete for this function; \
                          an unmodeled construct (e.g. an unsupported external call) left its \
                          panic-freedom obligations undischarged";
            rebuilt.push(transport_assumption_row(
                tcx,
                body,
                trust_types::assumption::NATIVE_LOWERING_ASSUMPTION_TAG,
                detail,
                trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
            ));
            Some(rebuilt)
        }
        DefaultLaneDemotion::ExternCall => Some(demote_extern_call_transport_rows(tcx, body, rows)),
        // FIX b59: demote ONLY the `fmt::format` rows (the safe subset), leaving any
        // stdout `_print`/`_eprint` leg and every drop-glue row untouched.
        DefaultLaneDemotion::FmtFormat => {
            Some(demote_fmt_format_extern_call_transport_rows(tcx, body, rows))
        }
    };
    // Advisory expected-absent post-pass: demote those rows over whatever the
    // standard decision produced (or the original rows when it produced None).
    let after_expected = match (standard, has_expected_absent) {
        (Some(demoted), true) => {
            Some(demote_expected_absent_callee_transport_rows(tcx, body, &demoted))
        }
        (Some(demoted), false) => Some(demoted),
        (None, true) => Some(demote_expected_absent_callee_transport_rows(tcx, body, rows)),
        (None, false) => None,
    };
    let current = after_expected.as_deref().unwrap_or(rows);
    let demoted = if current.iter().any(transport_row_is_demotable_assumed_total_callee) {
        Some(demote_assumed_total_callee_transport_rows(tcx, body, current))
    } else {
        after_expected
    };
    if uncharged_edges.is_empty() {
        return demoted;
    }
    // A REFUSED collapse leaves the lowering failure with no row of its own: the
    // rows left are the ones the VC layer saw. Measured without this row (the
    // refusal above on `335a1aeb39`): the `exit`-guarded `dep::deref_raw` read,
    // refused with an error, published `proved: 1, total: 1` — a JSON that reads
    // as verified. Name the failure and the edges it left uncharged on the wire too
    // (an `unknown` row, which no memory-safe gate admits).
    let mut published = demoted.unwrap_or_else(|| rows.to_vec());
    published.push(transport_native_lowering_uncharged_edges_row(&uncharged_edges));
    Some(published)
}

/// Trust (2026-09-27): `rows` plus the `native-verification-gap` rows for the gaps
/// no published row accounts for; `None` when there is none.
///
/// * A FAILED native typed-TrustIr lowering, unless a row already stands for it
///   (the memory-safe `assumption:native-lowering` collapse, or a gap row). A
///   root's proved rows, including sealed R1 flips, account for none of the debt
///   of a discarded bundle. The strict gate always refuses the lowering failure;
///   an authenticated assumption remains transport disclosure, never strict proof.
/// * Each foreign-reaching closure-driving consumer call that no counted
///   obligation charges (`uncharged_foreign_closure_consumer_edges`, passed in).
fn unaccounted_gap_rows(
    artifacts: &VerificationArtifacts,
    rows: &[TransportObligationResult],
    uncharged_consumer_edges: &[String],
    // Trust (2026-10-25, GLR-1): the row disclosing what the indirect-call gate
    // refuses (`unresolved_indirect_call_gap_row`); `None` when it refuses nothing.
    unresolved_indirect_call_row: Option<&TransportObligationResult>,
) -> Option<Vec<TransportObligationResult>> {
    let mut added = Vec::new();
    if let Some(run) = artifacts.full_verification.as_ref()
        && native_run_trust_ir_lowering_failed(run)
        && !rows.iter().any(|row| {
            row.kind == NATIVE_VERIFICATION_GAP_ROW_KIND
                || transport_row_is_authenticated_native_lowering_assumption(row)
        })
    {
        added.push(transport_native_lowering_gap_row(run));
    }
    if !uncharged_consumer_edges.is_empty() {
        let mut row = transport_native_verification_gap_row();
        row.description = format!(
            "a closure-driving consumer call runs code outside the verified closure and the \
             std/core/alloc TCB ({}), and no counted obligation charges it",
            uncharged_consumer_edges.join(", "),
        );
        added.push(row);
    }
    if let Some(row) = unresolved_indirect_call_row {
        added.push(row.clone());
    }
    if added.is_empty() {
        return None;
    }
    let mut published = rows.to_vec();
    published.extend(added);
    Some(published)
}

/// Trust (2026-10-25, GLR-1): the `native-verification-gap` row that DISCLOSES what
/// the indirect-call gate ([`function_has_unresolved_indirect_call`]) refuses, or
/// `None` when it refuses nothing in this body.
///
/// THE HOLE. The gate is the only thing that charges a call whose callee is chosen at
/// run time (a fn-pointer value) or by a caller (a callable type argument nothing
/// here resolves): the bridge lowers such a call to a may-panic marker with no
/// carrier row (docs/KNOWN_HAZARDS.md, "A may-panic MARKER is only as good as its
/// CARRIER"), and the gate's failure (`skipped: 1` in
/// `abort_on_full_verification_failure`) has no row behind it. The gate runs only
/// on the fail-closed lanes, so on the advisory lane (`-Ztrust-policy=advisory`,
/// targo's `--allow-l0-gaps`) nothing at all was said. MEASURED on Trust 15698
/// (2026-10-25 review of the grok-alab fix): `pub fn q(g: fn() -> u8, x: u8) -> u8
/// { if x > 3 { g() } else { x / 2 } }` published one proved division row and the
/// global-alloc premise, and targo's advisory gate read `CONDITIONAL-PASS ...
/// exit 0 (... 0 unknown / 3 total)` with "0 unproved" while `q(boom, 9)` panics.
/// Strict refused it, but its Gate line counted `0 failed ... 0 unknown` too.
///
/// THE ROW. An `unknown` row, never proved, naming each refused site. It is
/// published on every lane, so the advisory gate counts the gap among its
/// conditions ("N unproved") and the fail-closed lanes' counts agree with their
/// refusal. One-directional: it adds a non-proved row and removes none, and it is
/// keyed on the gate's own predicate (`unresolved_indirect_call_blocks` and
/// `uncharged_callable::body_mints_requires_carrying_value`), so the row and the
/// refusal cannot disagree about which bodies they cover. The predicate reads the
/// policy (SYS-CALLABLE-1 resolves a std function item handed to generic code on
/// advisory, default and strict, not on memory-safe and certify), so the row follows
/// the lane it is published on.
///
/// NOT DEDUPLICATED. A call through a fn-pointer value had no row at all (CE1). A
/// caller's `F: Fn` or `dyn Fn` call the gate refuses may already carry a class (c)
/// `failed` row or an absent-callee row (MEASURED 2026-10-26: the closure in
/// `instance_hypothesis/closure_body_fences_not_admitted.rs`, three sites in
/// agy-alab); this row is then a second, never-proved disclosure of the same call. It
/// adds one `unknown` to such a body's counts and can move no exit code that the
/// existing row and the gate did not already decide. Deduplicating by site is GLR-5.
fn unresolved_indirect_call_gap_row<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Option<TransportObligationResult> {
    let blocks: Vec<BasicBlock> = unresolved_indirect_call_blocks(tcx, body).collect();
    let mints_requires_carrying_value =
        uncharged_callable::body_mints_requires_carrying_value(tcx, body);
    if blocks.is_empty() && !mints_requires_carrying_value {
        return None;
    }
    let mut sites: Vec<String> = blocks
        .iter()
        .map(|&block| match &body[block].terminator().kind {
            TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. }
                if matches!(func.ty(&body.local_decls, tcx).kind(), ty::FnPtr(..)) =>
            {
                format!("a call through a fn-pointer value in {block:?}")
            }
            TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. } => format!(
                "`{}` in {block:?}, whose callee or callable argument is unresolved",
                trust_mir_extract::func_operand_name_in_body(tcx, body, func)
            ),
            _ => format!("the call in {block:?}"),
        })
        .collect();
    if mints_requires_carrying_value {
        sites.push("a function value minted from an item that owes a `requires`".to_string());
    }
    let span = blocks.first().map_or(body.span, |&block| body[block].terminator().source_info.span);
    let mut row = transport_native_verification_gap_row();
    // Not "no counted obligation charges it": a caller's `F: Fn` or `dyn Fn` call may
    // already carry a class (c) `failed` row or an absent-callee row (see THE ROW above).
    row.description = format!(
        "an unresolved indirect call: this body calls code this compilation did not verify \
         ({}); this row stands for the indirect-call gate's refusal on every lane, beside \
         any row that already charges the same call",
        sites.join(", "),
    );
    // `unsupported`: no lane can decide a callee nobody names, and the same inputs
    // end the same way, so the stop is deterministic. Unstamped, targo would read
    // it `unclassified` (NOT reproducible) and grade an advisory run that publishes
    // it COULD-NOT-RUN, exit 3, which says the verifier did not run when it did.
    // The called code is not always chosen at run time or by a caller: under
    // memory-safe and certify it can be a named std function item handed to generic
    // code that SYS-CALLABLE-1 does not resolve (`Instant::now` in
    // `policy_b/zero_obligation_charged_body_keeps_gap_row.rs`).
    row.reason = Some(trust_types::determinism::StopCause::Unsupported.stamp(
        "not proved: no body this compilation verified covers the called code (a fn-pointer \
         value, a callable a caller chooses, or a function value this policy does not \
         resolve), so a panic in it is reachable from this body; the fail-closed lanes \
         refuse such a body, and on the advisory lane this row is the gate's only trace",
    ));
    row.location = Some(source_span_from_rustc_span(tcx, span));
    Some(row)
}

/// Trust (2026-09-27): the ROOT body's calls that the bridge lowers as a
/// CLOSURE-DRIVING CONSUMER (`trust_ir_bridge::closure_driving_consumer_call`: an
/// `Iterator`/`Option`/`Result` method that runs code the bridge cannot summarize —
/// `unwrap_or_default`, `map`, `fold`, `count`, …) AND whose type arguments name
/// code nothing here verifies (`ty_names_unverified_code`), or that is handed a
/// masked function value.
///
/// The bridge lowers such a call to an `Assert(false)` marker with a BRIDGE-LOCAL
/// per-site row that carries no assumption prefix, so unless something else mints
/// the body's whole-function panic-freedom aggregate, NO counted obligation charges
/// it. That is by design for a LOCAL closure (verified as its own root — the
/// `ADAPTER_YIELD` parent, `(0..8).all(|i| a[i] == 0)`, has no row), and it was a
/// hole for foreign code: on stage-1 436c9eb6d0 `o.unwrap_or_default().0` over
/// `Option<dep::Boom>`, whose verify-off `Default` is `unreachable_unchecked()`,
/// built rc=0 under strict AND memory-safe, and beside one guarded index its JSON
/// read `proved: 1, total: 1`.
fn foreign_reaching_closure_consumer_edges<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Vec<String> {
    let mut edges = Vec::new();
    for (bb, data) in body.basic_blocks.iter_enumerated() {
        let Some(terminator) = &data.terminator else { continue };
        let (TerminatorKind::Call { func, args, .. } | TerminatorKind::TailCall { func, args, .. }) =
            &terminator.kind
        else {
            continue;
        };
        let Some((_, generic_args)) = func.const_fn_def() else { continue };
        let key = trust_mir_extract::func_operand_name_in_body(tcx, body, func);
        if !trust_ir_bridge::closure_driving_consumer_call(&key) {
            continue;
        }
        let reaches_foreign = generic_args.types().any(|t| ty_names_unverified_code(tcx, t))
            || args.iter().any(|arg| {
                ty_carries_masked_fail_closed_fn_value(tcx, arg.node.ty(&body.local_decls, tcx))
            });
        if reaches_foreign {
            edges.push(format!("`{key}` in {bb:?}"));
        }
    }
    edges
}

/// Trust (2026-09-27): does `ty` — a generic argument of a closure-driving consumer
/// call, walked through its OWN generic arguments (never an ADT's private fields) —
/// name code that no verdict in this compilation covers? A type, closure or
/// coroutine from a crate that is neither this one nor an authentic sysroot crate,
/// a masked function item, and every shape whose code is open: a type parameter, a
/// projection, a trait object, a fn pointer, an extern type. A local ADT's
/// concrete trait-impl surface must also stay inside the verified closure: its
/// generic body's verdict may carry an instance hypothesis rather than establish
/// the concrete method. Local closures are verified as their own roots; sysroot
/// types are the TCB.
///
/// Deliberately narrower than `ty_reaches_foreign_user_code`, which also walks
/// sysroot ADT fields: `Result<(), std::io::Error>::unwrap_or_default` reaches a
/// trait object through `io::Error`'s private representation but runs only
/// `<() as Default>::default`, and the field walk refused it (measured on
/// `native_bundle_std_red_depends_on_bundled_body.rs#nobundle`).
fn ty_names_unverified_code<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let foreign = |did: DefId| !did.is_local() && !crate_is_authentic_foundational(tcx, did.krate);
    let mut walker = ty.walk();
    while let Some(arg) = walker.next() {
        let Some(t) = arg.as_type() else { continue };
        let unverified = match t.kind() {
            ty::Adt(def, args) => {
                // Trust (ADT-IMPL-DISCHARGE-1): a local generic impl can call a
                // verify-off dependency at concrete arguments even when the ADT
                // contains only foundational scalars. The generic body's own
                // instance hypothesis does not establish that dispatch. Reuse
                // the same concrete impl-surface walk as assume_total revocation
                // without replacing this consumer walk with a whole-field walk.
                if def.did().is_local() {
                    let mut memo = FxHashMap::default();
                    memo.insert(t, false);
                    local_impl_surface::local_impl_surface_reaches_foreign(
                        tcx,
                        *def,
                        *args,
                        &mut memo,
                        &mut vec![t],
                    )
                } else {
                    foreign(def.did())
                }
            }
            // A closure's generic arguments are its signature (a `fn` POINTER type) and
            // its captures. A LOCAL closure is verified as its own root, calls through
            // its captures included, so its subtree is not this edge's to judge —
            // measured: walking it flagged the `ADAPTER_YIELD` parent
            // `(0..8).all(|i| a[i] == 0)` on the closure's own signature.
            ty::Closure(did, _) | ty::CoroutineClosure(did, _) | ty::Coroutine(did, _) => {
                if !foreign(*did) {
                    walker.skip_current_subtree();
                    continue;
                }
                true
            }
            ty::FnDef(did, _) => callee_is_masked_fail_closed_dispatch(tcx, *did),
            ty::Param(_)
            | ty::Alias(..)
            | ty::Dynamic(..)
            | ty::FnPtr(..)
            | ty::Foreign(..)
            | ty::Bound(..)
            | ty::Placeholder(..)
            | ty::Infer(..)
            | ty::Error(_) => true,
            _ => false,
        };
        if unverified {
            return true;
        }
    }
    false
}

/// Trust (2026-09-27): [`foreign_reaching_closure_consumer_edges`] that NO counted
/// row charges — empty when the native lane published this function's
/// whole-function panic-freedom aggregate, which folds every `Assert` of the body,
/// the consumer's marker included (the strict fold rule then judges it).
fn uncharged_foreign_closure_consumer_edges<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &VerificationArtifacts,
) -> Vec<String> {
    let aggregate_id = format!(
        "vc:{}:assertion:panic-freedom:0",
        trust_types::canonical_artifact_id_component(func_path)
    );
    if artifacts
        .transport_results
        .iter()
        .any(|row| row.obligation_id.as_deref() == Some(aggregate_id.as_str()))
    {
        return Vec::new();
    }
    foreign_reaching_closure_consumer_edges(tcx, body)
}

/// The `native-verification-gap` row for a run whose native lowering did not
/// complete. When the per-function deadline declined the lowering, the gap is
/// a clock stop and is published as one — `timed_out`, with the
/// `wall-backstop` cause — not as an unknown that states none (determinism
/// plan §3.7). It grants nothing either way.
fn transport_native_lowering_gap_row(
    run: &trust_verifier_api::VerificationRunResult,
) -> TransportObligationResult {
    let mut row = transport_native_verification_gap_row();
    if native_run_lowering_declined_by_deadline(run) {
        row.outcome = Outcome::Timeout;
        row.reason = row
            .reason
            .map(|reason| trust_types::determinism::StopCause::WallBackstop.stamp(&reason));
    }
    row
}

/// Trust (2026-09-26): the `native-verification-gap` row a memory-safe body
/// publishes when its native lowering did not complete and the
/// `assumption:native-lowering` collapse was refused because the body calls out
/// of the verified closure (`memory_safe_assumption_uncharged_edges`). Outcome
/// `unknown`: it grants nothing.
fn transport_native_lowering_uncharged_edges_row(edges: &[String]) -> TransportObligationResult {
    let mut row = transport_native_verification_gap_row();
    row.description = format!(
        "native typed-TrustIr lowering did not complete, and this body calls out of the \
         verified closure ({}); no obligation charges those calls",
        edges.join(", ")
    );
    row
}

/// Trust: under explicit survey policy, rewrite each unproved
/// EXPECTED-absent-callee row (user skip or compiler-authenticated non-unwinding
/// C-family call) into a recorded `assumption:expected-absent-callee` ledger
/// row, leaving every other row untouched. Never rewrites to `proved`.
fn demote_expected_absent_callee_transport_rows(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    rows.iter()
        .map(|row| {
            if transport_row_is_demotable_expected_absent_callee(row) {
                let detail = row
                    .description
                    .split(trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or(
                        "a user-skipped callee or compiler-authenticated non-unwinding C-family \
                         call whose body is absent from this verification unit",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_TAG,
                    detail,
                    "trust-bridge",
                )
            } else {
                row.clone()
            }
        })
        .collect()
}

fn demote_assumed_total_callee_transport_rows(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    rows.iter()
        .map(|row| {
            if transport_row_is_demotable_assumed_total_callee(row) {
                let detail = row
                    .description
                    .split(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|detail| !detail.is_empty())
                    .unwrap_or(
                        "a call to a user-audited #[trust::assume_total] wrapper whose body is deliberately absent from this verification unit",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_TAG,
                    detail,
                    "trust-bridge",
                )
            } else {
                row.clone()
            }
        })
        .collect()
}

/// Trust (assumption ledger, W3.5): rewrite each marked extern-call panic-freedom row
/// into a recorded `assumption:extern-call` ledger row (clean, marker-free text via
/// `transport_assumption_row`), leaving every other row untouched.
fn demote_extern_call_transport_rows<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    // Trust (HOLE — `format!` of a user/dep Display, 2026-09-14): the general
    // ExternCall demotion leg is the one a `format!` (no `println!`) actually
    // reaches. The `alloc::fmt::format` row runs an arbitrary user/dependency
    // `Display`/`Debug` impl that may `panic!`; it may be demoted to the honest
    // `assumption:extern-call` ledger ONLY when every value formatted through the
    // machinery is FOUNDATIONAL (the same boundary the `println!` path uses).
    // Otherwise the `fmt::format` row is EXCLUDED from demotion and left as its
    // raw (unproved, UNKNOWN) row, so `format!` of a panicking user Display stays
    // FATAL and refuses like the `println!` twin (pin
    // `println_cross_crate_display_refused.rs`). Non-`fmt::format` extern-call
    // rows are unaffected, and foundational `format!` still demotes.
    let formats_only_foundational = function_format_args_all_foundational_display(tcx, body);
    rows.iter()
        .map(|row| {
            if transport_row_is_unproved_extern_call(row) {
                // Non-foundational `fmt::format`: keep the raw fatal row.
                if transport_row_is_unproved_fmt_format_extern_call(row)
                    && !formats_only_foundational
                {
                    return row.clone();
                }
                // Carry the dispatch callee into the ledger detail (strip the marker and
                // the reconstructed `assertion: ` VC-kind prefix), so the row can name
                // e.g. `alloc::fmt::format`. Marker-free by construction of the prefix.
                let detail = row
                    .description
                    .split(trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or(
                        "an extern print/format/write dispatch runs a user Display/Debug impl that may panic",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::EXTERN_CALL_ASSUMPTION_TAG,
                    detail,
                    trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
                )
            } else if transport_row_is_unproved_drop_glue(row) {
                let detail = drop_glue_assumption_detail(row)
                    .unwrap_or("drop glue with unproven panic-freedom may panic");
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::DROP_GLUE_ASSUMPTION_TAG,
                    detail,
                    trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
                )
            } else if transport_row_is_unproved_absent_callee(row) {
                // Same demotion shape for a call whose target body was absent
                // from the lowered bundle; the detail names the callee.
                let detail = row
                    .description
                    .split(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or(
                        "a call to a callee whose body is not in the lowered bundle may panic",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_TAG,
                    detail,
                    trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
                )
            } else {
                row.clone()
            }
        })
        .collect()
}

/// FIX b59: the `fmt::format`-only demotion — rewrite ONLY the `fmt::format`
/// (`format!` macro backend) extern-dispatch rows to a recorded
/// `assumption:extern-call` ledger row, leaving EVERY other row BYTE-UNTOUCHED: any
/// stdout `_print`/`_eprint` leg (broken-pipe / SIGPIPE hazard) and any writer leg
/// keep failing closed, every drop-glue / absent-callee row is preserved, and every
/// real obligation is preserved. Used by the fail-closed / non-memory-safe lanes,
/// which admit only this safe subset — unlike [`demote_extern_call_transport_rows`],
/// which (in the memory-safe lane) demotes ALL extern-call, drop-glue, and
/// absent-callee legs. The demoted row is NEVER `proved`; it is an HONEST recorded
/// assumption (the fmt `Display` may panic), same class as the memory-safe lane.
fn demote_fmt_format_extern_call_transport_rows(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    rows.iter()
        .map(|row| {
            if transport_row_is_unproved_fmt_format_extern_call(row) {
                // Carry the dispatch callee into the ledger detail (strip the marker
                // and the reconstructed `assertion: ` VC-kind prefix), so the row can
                // name `alloc::fmt::format`. Marker-free by construction of the prefix.
                let detail = row
                    .description
                    .split(trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or(
                        "the `format!` macro backend (`fmt::format`) runs a user Display/Debug impl that may panic",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::EXTERN_CALL_ASSUMPTION_TAG,
                    detail,
                    trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
                )
            } else {
                row.clone()
            }
        })
        .collect()
}

/// Trust (assumption ledger): record a capability-gap skip as a
/// machine-readable unverified assumption. This is what makes the
/// `TreatedAsAssumption` doc promise ("recorded in the proof report — not
/// silently dropped") true: it emits a `TRUST_JSON` transport row (under
/// `-Z trust-verify-output=json|both`) and, when `emit_human_note`, a human
/// `eprintln` line (under the default human mode).
///
/// Trust (skip taxonomy, RECORD-THEN-RULE): this now runs on EVERY policy's
/// skip path, before the policy rules — including strict/certify/memory-safe,
/// where the build-failing error follows and the plan carries no human note
/// because that error is the human statement. WHAT it writes is decided by the
/// caller as a [`SkipRecordPlan`] (`skip_record_plan`, unit-tested): nothing at
/// all for a def the step-4 library lane narrowed, and the machine row only
/// under JSON transport output — the same field the caller's error reads
/// before it claims a row.
fn record_skip_assumption(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    func_path: &str,
    reason: &TrustVerifySkipReason,
    memory_safe_demotion: bool,
    plan: SkipRecordPlan,
) {
    if !plan.machine_row && !plan.human_note {
        return;
    }
    // Trust: do not add a process-global "seen" guard here. The optimized-MIR
    // query and pass schedule invoke this once per Body in a Session; distinct
    // coroutine bodies can intentionally share a def-path/tag and each needs an
    // honest row. A global guard both collapsed those rows and suppressed every
    // matching row in a later rustc_driver Session. The run-make assumption
    // transport regression pins the exact per-Body count.
    let tag = skip_assumption_tag(reason);
    let detail = match reason {
        TrustVerifySkipReason::TreatedAsAssumption(_) => {
            format!("MIR shape the verifier cannot lower yet ({tag})")
        }
        TrustVerifySkipReason::UnreachableStart => {
            "function body starts at an unreachable terminator; \
             no executable path to verify"
                .to_string()
        }
        TrustVerifySkipReason::UserOptOut => {
            "function is excluded by #[trust::skip]; its behavior is an explicit user assumption"
                .to_string()
        }
        TrustVerifySkipReason::AssumedTotal => {
            "function carries #[trust::assume_total]; its totality is an explicit, \
             user-audited assumption (recorded in every mode, never proof)"
                .to_string()
        }
        _ => format!("unsupported body ({tag})"),
    };
    let solver = if memory_safe_demotion {
        trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE
    } else {
        match reason {
            TrustVerifySkipReason::UnreachableStart
            | TrustVerifySkipReason::UserOptOut
            | TrustVerifySkipReason::AssumedTotal => "trust-policy",
            _ => "trust-classifier",
        }
    };
    // Trust (T3 C05): the elision audit's verdict vector records the row in either
    // output mode (here: whenever the lane records the assumption, as a row or a note).
    if plan.machine_row || elide_audit::enabled() {
        let row = transport_assumption_row(tcx, body, tag, &detail, solver);
        audit_published_rows(tcx, body.source.def_id(), func_path, std::slice::from_ref(&row));
        if plan.machine_row {
            emit_transport_json(tcx, body.source.def_id().as_local(), func_path, &[row], 0);
        }
    }
    if plan.human_note {
        // eprintln, not a diagnostic (house style for verify-pass notes).
        let policy_note = if matches!(reason, TrustVerifySkipReason::AssumedTotal) {
            "recorded in every mode as a visible non-proof premise"
        } else {
            "strict mode rejects it"
        };
        eprintln!(
            "Trust: ASSUMPTION [{tag}] `{func_path}`: {detail} — recorded as an \
             unverified assumption (NOT proved; {policy_note})"
        );
    }
}

// Trust: diagnostic framing of final canonical rows, separate from evidence transport.
mod row_diagnostics;

/// Trust #542: Emit structured JSON transport line for a function's verification results.
///
/// Writes a single `TRUST_JSON:{"type":"function_result",...}` line to stderr.
/// This is consumed by targo-trust for programmatic access to verification
/// results without fragile text parsing of compiler diagnostics.
fn emit_transport_json(
    tcx: TyCtxt<'_>,
    def_id: Option<LocalDefId>,
    func_path: &str,
    obligation_results: &[TransportObligationResult],
    cached: u32,
) {
    emit_transport_json_with_modeled_facts(
        tcx,
        def_id,
        func_path,
        obligation_results,
        cached,
        &[],
        None,
    );
}

/// [`emit_transport_json`] plus the function's modeled-fact disclosures
/// (`FunctionTransportResult::modeled_facts`; D2 tier 1's `ADAPTER_YIELD`).
///
/// Trust (T9): `def_id` is the body the rows belong to. The envelope carries
/// each row's stable obligation id (`transport_stable_ids`) and the body's
/// source digest (`transport_function_source_digest`) — identity for the
/// verdict vector and the committed baseline, never proof authority: neither
/// enters a claim digest or a certificate binding.
fn emit_transport_json_with_modeled_facts(
    tcx: TyCtxt<'_>,
    def_id: Option<LocalDefId>,
    func_path: &str,
    obligation_results: &[TransportObligationResult],
    cached: u32,
    modeled_facts: &[String],
    expanded_function_identity: Option<
        &trust_types::expanded_function_identity::ExpandedFunctionIdentity,
    >,
) {
    let prepared = publication_transport::prepare_transport_json_with_modeled_facts(
        tcx, def_id, func_path, obligation_results, cached, modeled_facts,
        expanded_function_identity,
    );
    let (span, data) = prepared.split();
    data.emit(tcx, span);
}

/// Trust: (TRANSPORT-LINE-BUDGET-1) the transport line budget for this compile:
/// `trust_types::transport_budget::TRANSPORT_LINE_BUDGET_BYTES`, or a LOWER value a test
/// sets in `TRUST_TRANSPORT_LINE_BUDGET_BYTES`. The knob can only lower the bound
/// (`lowered_line_budget` clamps it); an unparseable value leaves the default.
fn transport_line_budget() -> u64 {
    trust_types::transport_budget::lowered_line_budget(
        std::env::var("TRUST_TRANSPORT_LINE_BUDGET_BYTES")
            .ok()
            .and_then(|value| value.trim().parse::<u64>().ok()),
    )
}

/// Trust: (TRANSPORT-LINE-BUDGET-1) `rustc_errors::json` recognizes a transport note by
/// its own copy of the transport code; the two spellings must be one string.
const _: () = {
    let (a, b) = (
        rustc_errors::json::TRUST_TRANSPORT_DIAGNOSTIC_CODE.as_bytes(),
        TRANSPORT_DIAGNOSTIC_CODE.as_bytes(),
    );
    assert!(a.len() == b.len(), "transport diagnostic code spellings differ");
    let mut i = 0;
    while i < a.len() {
        assert!(a[i] == b[i], "transport diagnostic code spellings differ");
        i += 1;
    }
};

/// Trust (T9): the text of this session's LOCAL source files, by the file name
/// `source_span_from_rustc_span` renders, for anchoring stable obligation keys
/// (`trust_types::obligation_identity`). A span in any other file — the
/// sysroot, a registry or path dependency, a macro from another crate — is
/// outside the package and anchors on its path alone. Rebuilt when the source
/// map grows; local files are all loaded before MIR is built, so a rebuild only
/// ever adds imported files, which the filter drops.
#[derive(Default)]
struct TransportSourceIndex {
    seen_files: usize,
    files: FxHashMap<String, (Arc<String>, trust_types::obligation_identity::LineIndex)>,
    /// Trust (T9): rows whose anchor was DEGRADED (`RowAnchor::degraded`: the
    /// span did not lie in its file's text, or covered no token) in this
    /// compile. Published on the coverage row (`degraded_anchors`), so a run
    /// whose keys are coarser than a content address says so.
    degraded_anchors: usize,
}

impl TransportSourceIndex {
    fn refresh(&mut self, tcx: TyCtxt<'_>) {
        let files = tcx.sess.source_map().files();
        if files.len() == self.seen_files {
            return;
        }
        self.seen_files = files.len();
        for file in files.iter().filter(|file| file.cnum == LOCAL_CRATE) {
            let Some(text) = file.src.clone() else { continue };
            let name = trust_types::stable_obligation_file(
                file.name.prefer_local_unconditionally().to_string(),
            );
            self.files.entry(name).or_insert_with(|| {
                let lines = trust_types::obligation_identity::LineIndex::new(&text);
                (text, lines)
            });
        }
    }
}

/// Trust (T9): the stable local id of every row of one function, in row order
/// (`FunctionTransportResult::stable_ids`). One mint for the whole row set,
/// because a row's `nth` counts its siblings. A refused mint — two rows whose
/// ids collide, which distinct `(kind, anchor, nth)` triples make a 64-bit
/// truncation collision — publishes no id for any row of the function and is
/// an error: a consumer reads such a function as could-not-run, never as a
/// subset it can compare.
fn transport_stable_ids(
    tcx: TyCtxt<'_>,
    func_path: &str,
    rows: &[TransportObligationResult],
) -> Vec<String> {
    let (ids, degraded) = stable_ids_of_rows(tcx, rows);
    tcx.sess.with_trust_compiler_state::<TransportSourceIndex, _>(|index| {
        index.degraded_anchors += degraded;
    });
    match ids {
        Ok(ids) => ids,
        Err(collision) => {
            tcx.dcx().err(format!(
                "Trust: `{func_path}`: {collision}; its verdicts cannot be compared, so the unit \
                 this function belongs to is not a measurement"
            ));
            Vec::new()
        }
    }
}

/// The T9 local ids of `rows` and how many of their anchors are degraded, with no
/// side effect: [`transport_stable_ids`] books the degraded count and reports a
/// collision, and the elision audit's `VERDICT` rows (T3 C05) read the same ids in
/// either output mode without doing either.
fn stable_ids_of_rows(
    tcx: TyCtxt<'_>,
    rows: &[TransportObligationResult],
) -> (Result<Vec<String>, trust_types::obligation_identity::IdCollision>, usize) {
    let descriptions: Vec<&str> = rows.iter().map(|row| row.description.as_str()).collect();
    stable_ids_of_described_rows(tcx, rows, &descriptions)
}

/// [`stable_ids_of_rows`] with each row read as described by `descriptions` (one per row,
/// in order) wherever T9 reads a row's description: the anchor of a row with no location,
/// and every row's discriminator. Production passes the rows' own; the elision audit's
/// key (T3 L4, C06a; L4-AUDIT-8) passes them as `audit_ledger::build_independent` spells
/// them.
fn stable_ids_of_described_rows(
    tcx: TyCtxt<'_>,
    rows: &[TransportObligationResult],
    descriptions: &[&str],
) -> (Result<Vec<String>, trust_types::obligation_identity::IdCollision>, usize) {
    use trust_types::obligation_identity::{
        AnchorInput, KeyedRow, local_ids, row_anchor, row_discriminator, span_position,
    };
    let description = |index: usize| descriptions.get(index).copied().unwrap_or_default();
    let (anchors, degraded): (Vec<String>, usize) =
        tcx.sess.with_trust_compiler_state::<TransportSourceIndex, _>(|index| {
            index.refresh(tcx);
            let anchors: Vec<_> = rows
                .iter()
                .enumerate()
                .map(|(at, row)| {
                    let local = row
                        .location
                        .as_ref()
                        .and_then(|span| index.files.get(&span.file))
                        .map(|(text, lines)| (text.as_str(), lines));
                    row_anchor(AnchorInput::of(row.location.as_ref(), description(at), local))
                })
                .collect();
            let degraded = anchors.iter().filter(|anchor| anchor.degraded).count();
            (anchors.into_iter().map(|anchor| anchor.anchor).collect(), degraded)
        });
    // Trust (T9): the content discriminator orders same-position rows by what
    // they say before emission order can.
    let discriminators: Vec<String> =
        (0..rows.len()).map(|at| row_discriminator(description(at))).collect();
    let keyed: Vec<KeyedRow<'_>> = rows
        .iter()
        .zip(&anchors)
        .zip(&discriminators)
        .map(|((row, anchor), discriminator)| KeyedRow {
            kind: &row.kind,
            anchor,
            position: span_position(row.location.as_ref()),
            discriminator,
        })
        .collect();
    (local_ids(&keyed), degraded)
}

/// Trust (T3 C05): one elision-audit `VERDICT` row per published row of `def_id`'s
/// function, in either output mode, so a UI suite (human output) yields the same
/// stable-id verdict vector a JSON-mode compile transports. Measurement only. Since T3 L4
/// C06a the row also carries the audit key (L4-AUDIT-8, `elide_audit`'s module docs): the
/// same mint over the descriptions as the audit spells them across builds.
fn audit_published_rows(
    tcx: TyCtxt<'_>,
    def_id: DefId,
    func_path: &str,
    rows: &[TransportObligationResult],
) {
    if !elide_audit::enabled() {
        return;
    }
    let ids = stable_ids_of_rows(tcx, rows).0.ok();
    let spelled = trust_types::audit_ledger::build_independent(
        &rows.iter().map(|row| row.description.as_str()).collect::<Vec<_>>(),
    );
    let audit_ids = stable_ids_of_described_rows(
        tcx,
        rows,
        &spelled.iter().map(String::as_str).collect::<Vec<_>>(),
    )
    .0
    .ok();
    let key_of = |ids: &Option<Vec<String>>, index: usize| {
        ids.as_ref().and_then(|ids| ids.get(index)).map_or_else(
            || "-".to_string(),
            |id| trust_types::obligation_identity::obligation_key(func_path, id),
        )
    };
    for (index, row) in rows.iter().enumerate() {
        let key = key_of(&ids, index);
        let stop =
            trust_types::determinism::StopCause::of_outcome(row.outcome, row.reason.as_deref());
        elide_audit::record(
            tcx,
            def_id,
            "VERDICT",
            &[
                key,
                row.outcome.as_str().to_string(),
                stop.as_str().to_string(),
                row.kind.clone(),
                row.location.as_ref().map_or_else(|| "-".to_string(), elide_audit::location),
                key_of(&audit_ids, index),
            ],
        );
    }
}

/// Trust (T9): `trust_types::obligation_identity::function_source_digest` of
/// the item's source text (`tcx.source_span`), or `None` when the source map
/// cannot render it faithfully. An expanded item's span can name a macro's
/// template, which does not contain its substituted body tokens.
fn transport_function_source_digest(tcx: TyCtxt<'_>, def_id: LocalDefId) -> Option<String> {
    let span = tcx.source_span(def_id);
    // Trust: neither template text nor a call-site-only fallback identifies
    // the generated item's complete source; preserve the absent identity.
    if span.is_dummy() || span.from_expansion() {
        return None;
    }
    let text = tcx.sess.source_map().span_to_snippet(span).ok()?;
    Some(trust_types::obligation_identity::function_source_digest(&text))
}

#[derive(Clone, Default, PartialEq, Eq)]
struct TransportCrateAccumulator {
    functions_analyzed: usize,
    functions_verified: usize,
    total_proved: usize,
    total_failed: usize,
    total_unknown: usize,
    total_timed_out: usize,
    total_skipped: usize,
    total_runtime_checked: usize,
    total_obligations: usize,
    emitted: bool,
}

/// Emit one end-of-compile target inventory record, including zero-function
/// targets. Targo uses this to prove that every selected primary package target
/// actually ran the verifier; a global "saw some rows" check is insufficient.
pub fn trust_emit_transport_crate_summary(tcx: TyCtxt<'_>) {
    let role = tcx.sess.trust_crate_role();
    if !verification_enabled(tcx.sess) || !TrustOutputMode::parse(tcx.sess).emit_json() {
        return;
    }

    let crate_name = tcx.crate_name(LOCAL_CRATE).to_string();
    let package_name = tcx.sess.opts.unstable_opts.trust_verify_package_name.clone();
    let primary_package = role.is_cargo_primary();
    let summary = tcx.sess.with_trust_compiler_state::<TransportCrateAccumulator, _>(|state| {
        if state.emitted {
            return None;
        }
        state.emitted = true;
        Some(CrateTransportSummary {
            crate_name,
            package_name,
            primary_package,
            verification_session: tcx
                .sess
                .opts
                .unstable_opts
                .trust_verify_session
                .clone()
                .unwrap_or_default(),
            functions_analyzed: state.functions_analyzed,
            functions_verified: state.functions_verified,
            total_proved: state.total_proved,
            total_failed: state.total_failed,
            total_unknown: state.total_unknown,
            total_timed_out: state.total_timed_out,
            total_skipped: state.total_skipped,
            total_runtime_checked: state.total_runtime_checked,
            total_obligations: state.total_obligations,
        })
    });
    if let Some(summary) = summary
        && let Ok(json) = serde_json::to_string(&TransportMessage::CrateSummary(summary))
    {
        emit_transport_payload(tcx, &json);
    }
}

/// Trust: (TRANSPORT-LINE-BUDGET-1) the stderr framing a transport line takes in this
/// compile's error format.
fn transport_line_framing(tcx: TyCtxt<'_>) -> TransportLineFraming {
    match tcx.sess.opts.error_format {
        ErrorOutputType::HumanReadable { .. } => TransportLineFraming::RawStderr,
        ErrorOutputType::Json { .. } => {
            TransportLineFraming::json_diagnostic(&transport_note_span_file_name(tcx))
        }
    }
}

/// Trust: (TRANSPORT-LINE-BUDGET-1, review F4) the `file_name` rustc's JSON emitter writes
/// for the transport note's one span (`emit_transport_payload` notes at `DUMMY_SP`), found
/// exactly as `rustc_errors::json::DiagnosticSpan::from_span_full` finds it: the source
/// file at the span's start, named by `filename_for_diagnostics`. It is the crate root's
/// path after `--remap-path-prefix`, so its length is the compile's choice and the line
/// budget counts it rather than assuming it short. With no source file the emitter's own
/// stand-in name is shorter than the fixed frame's slack, so the empty name is exact enough.
fn transport_note_span_file_name(tcx: TyCtxt<'_>) -> String {
    let sm = tcx.sess.source_map();
    if sm.files().is_empty() {
        return String::new();
    }
    let start = sm.lookup_char_pos(DUMMY_SP.lo());
    sm.filename_for_diagnostics(&start.file.name).to_string()
}

fn emit_transport_payload(tcx: TyCtxt<'_>, json: &str) {
    // Trust: (TRANSPORT-LINE-BUDGET-1) no transport line passes the budget, whatever
    // emits it. A function report is fitted before it gets here, so this refuses only a
    // crate-level row (coverage, crate summary) or a function envelope whose identity
    // alone outruns the budget. Such a line is not written, and the compile fails: the
    // unit's report is incomplete, which its consumer must refuse, and the other lines
    // still reach it instead of a closed pipe killing this process.
    let framing = transport_line_framing(tcx);
    let budget = transport_line_budget();
    let line_bytes = framing.line_bytes(json);
    if line_bytes > budget {
        let kind = serde_json::from_str::<serde_json::Value>(json)
            .ok()
            .and_then(|value| value.get("type").and_then(|kind| kind.as_str()).map(str::to_string))
            .unwrap_or_else(|| "transport".to_string());
        tcx.dcx().err(format!(
            "Trust: a `{kind}` transport line would take {line_bytes} bytes, over the \
             {budget}-byte transport line budget; it is not emitted, so this unit's \
             verification report is incomplete"
        ));
        return;
    }
    let payload = format!("{TRANSPORT_PREFIX}{json}");
    match tcx.sess.opts.error_format {
        ErrorOutputType::HumanReadable { .. } => {
            // Raw trustc/driver consumers retain the one-line protocol. Do not
            // also emit a diagnostic here: human diagnostics render a second
            // `note: TRUST_JSON:...` copy and make one logical row look like two.
            eprintln!("{payload}");
        }
        ErrorOutputType::Json { .. } => {
            // Cargo JSON mode wraps diagnostics in a compiler-message carrying
            // package/target identity. Targo accepts crate-mode evidence only
            // through that envelope, so build-script stderr cannot forge
            // verifier transport. A raw line in this mode would sit outside the
            // Cargo envelope and re-open that provenance ambiguity.
            let mut diagnostic = tcx.dcx().struct_span_note(DUMMY_SP, payload);
            // This code marks a transport envelope, not a version-gated lint;
            // there is no minimum Rust version associated with it.
            diagnostic.is_lint(TRANSPORT_DIAGNOSTIC_CODE.to_string(), false, None);
            // Trust: preserve every transport byte in `message`, while avoiding
            // a rendered duplicate that can exceed the reader's line cap.
            diagnostic.set_json_rendered_message(
                "Trust verification results are available in the structured JSON message",
            );
            diagnostic.emit();
        }
    }
}

/// Trust: Returns true when the generated program retains a corresponding runtime check.
///
/// This is the incremental step toward #22: when static proof fails for an obligation
/// that Rust already guards dynamically, we classify it as `RUNTIME-CHECKED` instead
/// of leaving it as a bare UNKNOWN/TIMEOUT.
fn has_runtime_check(sess: &Session, kind: &VcKind) -> bool {
    runtime_check_available(kind, sess.overflow_checks())
}

/// Trust: Pure runtime-check classification helper for unit tests and diagnostics.
///
/// THE COMPILER-SIDE FUNNEL. Every in-compiler consumer of the runtime-check
/// question goes through here — the per-function summary partition
/// (`has_runtime_check`), the telemetry fallback rows, the transport row, the
/// `convert_result` row and the residual-gap tolerance scan — so the question is
/// asked once, of one authority, and cannot drift between them.
///
/// ONE MEANING, TREE-WIDE, AND NO SECOND OPINION HELD HERE. The body is exactly
/// `VcKind::has_runtime_fallback`, which asks whether the PROPERTY THE
/// OBLIGATION ASSERTS is enforced dynamically in the generated program. It
/// already answers `false` for every `VcKind::HardenedBoundary`, including the
/// `mir_assert::*` panic subfamily: rustc's `Assert` does survive the hardening
/// profile (MEASURED — byte-identical LLVM IR with and without
/// `-Ztrust-verify-profile=unix_hardened`), but that boundary's obligation is
/// that the panic is UNREACHABLE, and the surviving `Assert` does not enforce
/// unreachability — it IS the panic. There, the panic is the hazard, not the
/// wrong value underneath it.
///
/// An earlier revision of this function restated that refusal locally, as
/// compiler POLICY, because the authority had been widened to answer the
/// subfamily `true`. The widening was reverted (it moved report labelling for
/// every consumer of `classify_runtime_disposition_in`, which no flag guards),
/// so the local restatement is gone too: a second opinion held here would be
/// free to drift from the authority silently, which is the exact failure the
/// funnel exists to prevent. `no_hardened_boundary_answers_the_runtime_check_funnel`
/// pins the answer at this seam.
///
/// The NARROWER, purely factual question — "does rustc's own check still execute
/// at this site, whether or not it discharges anything" — is
/// `VcKind::site_retains_language_check_in`. Nothing in the compiler asks it.
/// Exactly one caller in the tree does: targo's
/// `--test-target-panics=runtime-checked`, an explicit flag with no default and
/// no environment variable, which applies only inside a cargo `["test"]` target
/// and layers its own narrower policy on top.
fn runtime_check_available(kind: &VcKind, overflow_checks: bool) -> bool {
    kind.has_runtime_fallback(overflow_checks)
}

/// Trust: Human-readable note explaining the runtime fallback.
fn runtime_check_note(kind: &VcKind) -> &'static str {
    match kind {
        VcKind::ArithmeticOverflow { .. }
        | VcKind::ShiftOverflow { .. }
        | VcKind::NegationOverflow { .. } => {
            "compiler retained the existing overflow check because the proof is not yet static"
        }
        VcKind::DivisionByZero | VcKind::RemainderByZero => {
            "compiler retained the existing division-by-zero check because the proof is not yet static"
        }
        VcKind::IndexOutOfBounds | VcKind::SliceBoundsCheck => {
            "compiler retained the existing bounds check because the proof is not yet static"
        }
        VcKind::Assertion { .. } => {
            "compiler retained the existing assertion because the proof is not yet static"
        }
        // No `VcKind::Unreachable` arm: it has no runtime fallback, so this
        // function is never reached with it (callers gate on `has_runtime_check`)
        // and the `_` arm below is the correct answer if it ever were.
        VcKind::FloatDivisionByZero | VcKind::FloatOverflowToInfinity { .. } => {
            "floating-point operations do not trap at runtime; no dynamic fallback exists"
        }
        VcKind::CastOverflow { .. }
        | VcKind::Precondition { .. }
        | VcKind::Postcondition
        | VcKind::DeadState { .. }
        | VcKind::Deadlock
        | VcKind::Temporal { .. }
        | VcKind::Liveness { .. }
        | VcKind::Fairness { .. }
        | VcKind::TaintViolation { .. }
        | VcKind::RefinementViolation { .. }
        | VcKind::ResilienceViolation { .. }
        | VcKind::ProtocolViolation { .. }
        | VcKind::NonTermination { .. } => {
            "no runtime-check fallback is available for this obligation kind"
        }
        _ => "no runtime-check fallback is available for this obligation kind",
    }
}

/// Trust: Format a VcKind into a short tag for bracketed display.
fn format_vc_kind(kind: &VcKind) -> String {
    // Trust: a native full-lane round-trip row retains the original typed
    // family and description inside `UnsupportedMir`. Recover its REAL kind
    // tag for presentation instead of collapsing to "unknown"; proof identity,
    // strict-L0 classification, and cache keys continue to read the raw typed
    // kind/fields — see `VcKind::recovered_full_lane_vc_tag`.
    if let VcKind::UnsupportedMir { kind: raw, detail } = kind
        && let Some(tag) = VcKind::recovered_full_lane_vc_tag(raw, detail)
    {
        return tag.to_string();
    }
    // Trust: single source of truth for the compact tag. The typed VC now also
    // travels in `TransportObligationResult::typed_kind`, and consumers check
    // the `typed_kind.transport_tag() == kind` correspondence — deriving both
    // from the same `trust_types` method keeps them from drifting.
    kind.transport_tag()
}

/// Trust (M-Pkg perf): run kernel certification ONCE per obligation, up front.
///
/// `trust_certify::certify_vc` reconstructs and re-checks a CIC proof term with
/// the clean kernel — the expensive part of the Certified tier. Both downstream
/// consumers need its result: `build_proof_results` (only the `is_some()` bit,
/// to decide the `Certified` status) and `build_transport_results` (the full
/// `CleanCic` term, to ship as a re-checkable report artifact). Previously each
/// re-ran `certify_vc` independently, kernel-checking every Proved obligation
/// twice. Hoisting it here computes it exactly once; the returned vector is
/// index-aligned with `results` (entry `i` is `Some(evidence)` iff `results[i]`
/// is a Proved obligation the kernel independently certified, else `None`), so
/// both builders can read the precomputed slice positionally.
///
/// Certification is attempted only for `Proved` results — fail-closed: any
/// other outcome (Failed/Unknown/Timeout) is never certifiable and maps to
/// `None` without invoking the kernel.
///
/// Trust (M5 blocker #0 — census core repeatability): `deadline` is the SAME
/// per-function wall-clock deadline the solver dispatch already respects
/// (`verify_fn_deadline` / tracked `-Ztrust-verify-function-budget-ms`; zero means
/// no deadline). Once the
/// deadline is reached this STOPS invoking the kernel for any further
/// obligation in this function — each is mapped to `None` exactly as an
/// obligation the kernel declined to certify already would be. Fail-closed: a
/// skipped certification can only DOWNGRADE the "Certified" evidence tier
/// (the underlying `Proved` verdict from the solver is untouched), never
/// upgrade or fabricate a certification that never ran.
fn certify_all(
    results: &[(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
) -> Vec<Option<trust_ir::ProofEvidence>> {
    certify_all_until(results, deadline).0
}

/// [`certify_all`], also returning the index of the first row the deadline
/// kept from the kernel (`None` when every row was attempted). A `Proved` row
/// at or past it was not declined by the kernel; the clock stopped the work
/// before it got there (determinism plan §3.7).
fn certify_all_until(
    results: &[(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
) -> (Vec<Option<trust_ir::ProofEvidence>>, Option<usize>) {
    certify_all_until_with_artifacts(results, deadline, None)
}

fn certify_all_until_with_artifacts(
    results: &[(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
    proof_artifact_root: Option<&std::path::Path>,
) -> (Vec<Option<trust_ir::ProofEvidence>>, Option<usize>) {
    let (evidence, _, cut_at) =
        certify_all_until_with_artifacts_and_replay_audits(results, deadline, proof_artifact_root);
    (evidence, cut_at)
}

fn certify_all_until_with_artifacts_and_replay_audits(
    results: &[(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
    proof_artifact_root: Option<&std::path::Path>,
) -> (
    Vec<Option<trust_ir::ProofEvidence>>,
    Vec<Option<trust_certify::proof_artifacts::ReplayAudit>>,
    Option<usize>,
) {
    certify_all_until_with_artifacts_and_early_replays(
        results,
        deadline,
        proof_artifact_root,
        |_, _| None,
    )
}

// Trust: reuse the owned exact proof earned before primary dispatch instead
// of rerunning either search or the kernel. All sweep stop gates remain shared.
fn certify_all_until_with_artifacts_and_early_replays(
    results: &[(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
    proof_artifact_root: Option<&std::path::Path>,
    mut early_replay: impl FnMut(
        usize,
        &VerificationCondition,
    ) -> Option<(
        trust_ir::ProofEvidence,
        trust_certify::proof_artifacts::ReplayAudit,
    )>,
) -> (
    Vec<Option<trust_ir::ProofEvidence>>,
    Vec<Option<trust_certify::proof_artifacts::ReplayAudit>>,
    Option<usize>,
) {
    // Trust (T3 L4, C06a): with the elision audit on, each certification also reports the
    // stop that reached its run, and the sweep's stops become CERTIFY-STOP rows of the body
    // (`elide_audit`). The evidence is `certify_vc`'s either way.
    let audit = elide_audit::enabled();
    let (selected, cut_at, stops) = certify_all_until_reporting_owned(
        results,
        deadline,
        audit,
        |index, vc| {
            if let Some(proof) = early_replay(index, vc) {
                return (Some((proof.0, Some(proof.1))), None);
            }
            if let Some(root) = proof_artifact_root {
                let (proof, stop) =
                trust_certify::proof_artifacts::certify_vc_with_artifacts_reporting_stop_and_audit_until(
                    vc, root, deadline,
                );
                (proof.map(|proof| proof.into_parts()), if audit { stop } else { None })
            } else if audit {
                let (evidence, stop) = trust_certify::certify_vc_reporting_stop(vc);
                (evidence.map(|proof| (proof, None)), stop)
            } else {
                (trust_certify::certify_vc(vc).map(|proof| (proof, None)), None)
            }
        },
    );
    for (index, cause) in stops {
        trust_types::audit_ledger::certify_stop(Some(index), cause);
    }
    let (evidence, replay_audits) = selected
        .into_iter()
        .map(|proof| match proof {
            Some((evidence, audit)) => (Some(evidence), audit),
            None => (None, None),
        })
        .unzip();
    (evidence, replay_audits, cut_at)
}

/// [`certify_all_until`] over the certifier `certify` (T3 L4, C06a), and, when `audit`, the
/// sweep's CERTIFY-STOP entries: each row whose run a stop reached, with that stop, and
/// each `Proved` row at or past the deadline's cut, with `wall-backstop` (the clock kept
/// it from the kernel). Measurement only: the stops never change the evidence.
fn certify_all_until_reporting(
    results: &[(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
    audit: bool,
    certify: impl FnMut(
        &VerificationCondition,
    ) -> (
        Option<trust_ir::ProofEvidence>,
        Option<trust_types::determinism::StopCause>,
    ),
) -> (
    Vec<Option<trust_ir::ProofEvidence>>,
    Option<usize>,
    Vec<(usize, trust_types::determinism::StopCause)>,
) {
    let mut certify = certify;
    certify_all_until_reporting_owned(results, deadline, audit, |_, vc| certify(vc))
}

/// Keep the proof and its optional observation as one owned value throughout
/// selection and deadline handling. Existing evidence-only callers use the
/// same sweep, without constructing an observation.
fn certify_all_until_reporting_owned<T>(
    results: &[(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
    audit: bool,
    mut certify: impl FnMut(
        usize,
        &VerificationCondition,
    ) -> (Option<T>, Option<trust_types::determinism::StopCause>),
) -> (Vec<Option<T>>, Option<usize>, Vec<(usize, trust_types::determinism::StopCause)>) {
    let mut evidence = Vec::with_capacity(results.len());
    let mut stops = Vec::new();
    for (index, (vc, result)) in results.iter().enumerate() {
        if deadline.is_some_and(|at| std::time::Instant::now() >= at) {
            if audit {
                stops.extend(
                    results
                        .iter()
                        .enumerate()
                        .skip(index)
                        .filter(|(_, (_, result))| {
                            matches!(result, VerificationResult::Proved { .. })
                        })
                        .map(|(cut, _)| (cut, trust_types::determinism::StopCause::WallBackstop)),
                );
            }
            evidence.extend((evidence.len()..results.len()).map(|_| None));
            return (evidence, Some(index), stops);
        }
        evidence.push(if matches!(result, VerificationResult::Proved { .. }) {
            let (certified, stop) = certify(index, vc);
            if let Some(cause) = stop.filter(|_| audit) {
                stops.push((index, cause));
            }
            if certified.is_none() {
                trust_certify_miss_trace(vc);
            }
            certified
        } else {
            None
        });
    }
    (evidence, None, stops)
}

/// [`trust_certify::certify_vc_for_native_planning`]; with the elision audit on, a stop
/// that reached its run is a CERTIFY-STOP row of the body (T3 L4, C06a). The evidence is
/// the planning entry's either way.
fn certify_vc_for_native_planning_audited(
    vc: &VerificationCondition,
) -> Option<trust_ir::ProofEvidence> {
    if !elide_audit::enabled() {
        return trust_certify::certify_vc_for_native_planning(vc);
    }
    let (evidence, stop) = trust_certify::certify_vc_for_native_planning_reporting_stop(vc);
    if let Some(cause) = stop {
        trust_types::audit_ledger::certify_stop(None, cause);
    }
    evidence
}

/// Diagnostic-only: report the SHAPE of a `Proved` obligation that
/// [`trust_certify::certify_vc`] could not kernel-certify.
///
/// Gated on `TRUST_CERTIFY_TRACE`, writes to stderr only, reads no proof state and
/// changes no verdict — the same discipline as `trust_enqueue_trace` and the
/// `TRUST_BUNDLE_MEMBERS` census.
///
/// WHY THIS EXISTS. A `Proved` row with no attachable certificate is downgraded to
/// UNKNOWN by the gate's publication-evidence check ("compiler transport claimed a
/// favorable outcome without attachable native or clean-kernel proof evidence;
/// downgraded before publication"). On ny-cert that is **74 of 348 unknowns (21%)**
/// — the single largest class after absent-callee, and the one that actually bounds
/// `proved`, since these obligations already reach the solver and come back
/// favorable. `certify_vc` succeeds only for the formula FAMILIES the clean-CIC
/// kernel can discharge, and until now there was no way to see WHICH shapes miss:
/// the function simply returns `None`. Four modeling/bundling levers were measured
/// to exhaustion against the absent-callee class in one session and every one was
/// verdict-inert, precisely because the binding constraint is here instead.
///
/// The output is meant to be histogrammed (`sort | uniq -c`) to rank which new
/// certifiable families would buy the most obligations, so the kernel work is
/// aimed by measurement rather than by guess.
///
/// THIS IS NOT A LEVER. Nothing here upgrades a verdict, and the correct response
/// to a miss is to PRODUCE the missing certificate, never to relax the check that
/// caught it — doing that would promote a gate-invisible false proof into a
/// gate-visible `[VERIFIED]`, which is the exact hazard
/// `ground_panic_freedom_catchall`'s audit block names.
fn trust_certify_miss_trace(vc: &VerificationCondition) {
    if !trust_env_var_present("TRUST_CERTIFY_TRACE") {
        return;
    }
    // Char-safe truncation: these are arbitrary rendered formulas, and slicing a
    // `String` on a byte index can land mid-codepoint and panic in a diagnostic.
    let clip = |s: String, n: usize| -> String { s.chars().take(n).collect() };
    eprintln!(
        "[CERTIFY_MISS] kind={} formula={}",
        clip(format!("{:?}", vc.kind), 72),
        clip(format!("{:?}", vc.formula), 220),
    );
}

/// A strict re-solve, or the stop cause of one that minted nothing
/// (`trust_router::in_process_ay_backend::revalidate_vc_unsat_strict_or_stop`):
/// `wall-backstop` when the re-solve's own clock ended it.
fn strict_smt_revalidate(
    formula: &trust_types::Formula,
    budget_ms: u64,
    effort: trust_types::determinism::EffortScale,
) -> StrictSmtRevalidationOutcome {
    let outcome = trust_router::in_process_ay_backend::revalidate_vc_unsat_strict_or_stop(
        formula, budget_ms, effort,
    )?;
    Ok(StrictSmtRevalidation {
        canonical_problem: outcome.canonical_problem().to_string(),
        problem_sha256: outcome.canonical_problem_sha256().to_string(),
        time_ms: outcome.time_ms(),
    })
}

/// Which clock ended the work a [`ClockStop`] records — or, for S1's strict
/// re-solve, which other non-reproducible stop did.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StoppingClock {
    /// The per-function deadline (`-Ztrust-verify-function-budget-ms`).
    FunctionDeadline,
    /// One solve's own clock: the allowance, in ms, the solve was handed (S1's
    /// four-second re-solve clock, clamped to the function's remaining time).
    SolveBudget(u64),
    /// Not a clock: a stated stop that is not reproducible either (a
    /// process-RSS reading, a solver fault, a refused admission) ended S1's
    /// strict re-solve before it decided, so the row's missing authority is
    /// that stop's. Published as an `Unknown` that states it, never as a
    /// timeout, and never as the bare "Proved without exact kernel/native
    /// proof authority" it would otherwise read: had the stop not fired, the
    /// re-solve could have minted.
    Backstop(trust_types::determinism::StopCause),
}

/// Trust (determinism plan §3.7, 2026-10-01): one result row a CLOCK left
/// unproved. A lane that would have decided the row, or minted the authority
/// its verdict needs, stopped because the per-function deadline had passed or
/// because a solve's own clock ended it.
///
/// Before this record the lanes that give up on the deadline filled the rows
/// they had not reached with "no result" and said nothing: such a row reached
/// the transport as an `unknown` that states no cause (or the cause of an
/// earlier lane), `0ms`, and `timed_out` stayed 0. Measured 2026-10-01 on the
/// release lane at load ~70: aterm-codec's `base64::encode_padded` fell from
/// 73/81 proved to 0/83, every row `trust-full-verifier, 0ms`, and nothing on
/// the row or in its function's counts said a clock had decided it.
#[derive(Debug, Clone, PartialEq, Eq)]
struct ClockStop {
    row: ExactResultRowIdentity,
    clock: StoppingClock,
}

/// Every [`ClockStop`] one function's full-lane run recorded, published by
/// [`stamp_clock_stopped_rows`] once every lane has had its chance at the row.
#[derive(Debug, Default)]
struct ClockStops(Vec<ClockStop>);

impl ClockStops {
    /// Record that `clock` stopped the work on row `index`. A row without an
    /// exact identity is not recorded: it keeps what its lanes said.
    fn record(&mut self, index: usize, vc: &VerificationCondition, clock: StoppingClock) {
        if let Some(row) = exact_result_row_identity(index, vc) {
            self.0.push(ClockStop { row, clock });
        }
    }

    /// [`Self::record`] for a lane whose proof becomes authority only past the
    /// plain vacuity gate (the kernel, S1, the ay bridge, the promotions; see
    /// `build_result_proof_authorities_with_revalidations`). No such lane can
    /// authorize a row whose violation formula is vacuously UNSAT (the gate
    /// refuses it) or the literal `true` (SAT by construction), so no clock
    /// decided that row and none is recorded.
    fn record_provable(&mut self, index: usize, vc: &VerificationCondition, clock: StoppingClock) {
        if !matches!(vc.formula, Formula::Bool(true))
            && !trust_router::constant_folder::violation_formula_is_vacuously_unsat(&vc.formula)
        {
            self.record(index, vc, clock);
        }
    }

    fn append(&mut self, other: ClockStops) {
        self.0.extend(other.0);
    }
}

/// Which clock or other non-reproducible stop, if any, kept a strict S1
/// re-solve from yielding authority. `late`: the function deadline had passed
/// when the re-solve returned. A late success and a re-solve a clock ended
/// are clock stops; a re-solve another STATED non-reproducible stop ended (an
/// RSS reading, a solver fault, a refused admission) is that stop
/// ([`StoppingClock::Backstop`]). A refuting re-solve, one that ended
/// undecided for a reproducible reason of its own (a count, the proof's own
/// refusal), and one whose stop nobody explained minted nothing whatever the
/// clock did and keep the row's own account: an unexplained stop already reads
/// `unclassified` there, beside the missing authority it names.
fn strict_revalidation_clock(
    fresh: &StrictSmtRevalidationOutcome,
    late: bool,
    budget_ms: u64,
) -> Option<StoppingClock> {
    use trust_types::determinism::{Reproducibility, StopCause};
    match (fresh, late) {
        (Ok(_), false) => None,
        (Ok(_), true) => Some(StoppingClock::FunctionDeadline),
        (Err(StopCause::WallBackstop), true) => Some(StoppingClock::FunctionDeadline),
        (Err(StopCause::WallBackstop), false) => Some(StoppingClock::SolveBudget(budget_ms)),
        (Err(cause), _)
            if *cause != StopCause::Unclassified
                && cause.reproducibility() != Reproducibility::Deterministic =>
        {
            Some(StoppingClock::Backstop(*cause))
        }
        (Err(_), _) => None,
    }
}

/// Trust (determinism plan §3.7, 2026-10-01): publish every row a clock left
/// unproved the way a solver timeout is published, as a
/// `VerificationResult::Timeout`. The rest is the existing timeout path: the
/// transport writes `timed_out` with the `[stop:wall-backstop]` token (or
/// `runtime_checked` with that token where a runtime check stands in), the
/// function's counts and the human line count it as timed out, and
/// `timeout_ms` names the clock that ran out instead of a `0ms` placeholder.
///
/// Runs LAST in the authority phase, so every lane has had its chance at the
/// row. It rewrites only a row that is still the one the clock stopped (same
/// index, same canonical VC), carries no authority of any kind, and is either
/// an unauthorized `Proved` label or an `Unknown`. A generic held refutation
/// keeps its prefix and Unknown outcome while retaining a reason-only clock
/// attribution. A refutation, a legacy exact-string held assertion, an
/// authorized proof, a recorded assumption and a row a later lane rebuilt
/// are never touched, nor
/// is a row that already states another backstop (the RSS guard, a solver
/// fault) or a refused admission: it is at least as unreproducible as a clock
/// (`StopCause::combine`) and names what ended its own search. A timeout is
/// never proved and never refuted: the row stays unproved; only the reason it
/// is unproved becomes visible.
///
/// Returns how many rows it rewrote.
fn stamp_clock_stopped_rows(
    results: &mut [(VerificationCondition, VerificationResult)],
    proof_authorities: &[Option<ResultProofAuthority>],
    clock_stops: &ClockStops,
    function_budget_ms: u64,
) -> usize {
    let mut stamped = 0usize;
    for stop in &clock_stops.0 {
        let index = stop.row.index;
        let Some((vc, result)) = results.get_mut(index) else { continue };
        if exact_result_row_identity(index, vc).as_ref() != Some(&stop.row)
            || proof_authorities.get(index).is_some_and(Option::is_some)
            || (result_is_held_assert_refutation(result)
                && !result_is_held_generic_refutation(result))
            || matches!(
                trust_types::determinism::StopCause::of_result(result),
                trust_types::determinism::StopCause::RssBackstop
                    | trust_types::determinism::StopCause::SolverFault
                    | trust_types::determinism::StopCause::AdmissionRefused
            )
        {
            continue;
        }
        let (solver, time_ms) = match &*result {
            VerificationResult::Proved { solver, time_ms, .. }
            | VerificationResult::Unknown { solver, time_ms, .. } => (*solver, *time_ms),
            _ => continue,
        };
        // Trust: replacing this with Timeout would erase the generic hold's
        // prefix and restore runtime-check tolerance. Keep it Unknown and use
        // the existing shared cause combination on the exact recorded row.
        if result_is_held_generic_refutation(result) {
            let (cause, detail) = match stop.clock {
                StoppingClock::FunctionDeadline => (
                    trust_types::determinism::StopCause::WallBackstop,
                    format!(
                        "the exact row's function deadline stopped proof work ({function_budget_ms}ms allowance)"
                    ),
                ),
                StoppingClock::SolveBudget(budget_ms) => (
                    trust_types::determinism::StopCause::WallBackstop,
                    format!(
                        "the exact row's solve clock stopped proof work ({budget_ms}ms allowance)"
                    ),
                ),
                StoppingClock::Backstop(cause) => {
                    (cause, format!("the exact row's strict re-solve stopped on {cause}"))
                }
            };
            if let VerificationResult::Unknown { reason, .. } = result {
                *reason = cause.stamp(&format!("{reason}; {detail}"));
                stamped += 1;
            }
            continue;
        }
        *result = match stop.clock {
            StoppingClock::FunctionDeadline => {
                VerificationResult::Timeout { solver, timeout_ms: function_budget_ms }
            }
            StoppingClock::SolveBudget(budget_ms) => {
                VerificationResult::Timeout { solver, timeout_ms: budget_ms }
            }
            StoppingClock::Backstop(cause) => VerificationResult::Unknown {
                solver,
                time_ms,
                reason: cause.stamp(
                    "S1's strict re-solve was stopped before it decided, so no exact \
                     kernel/native proof authority was minted",
                ),
            },
        };
        stamped += 1;
    }
    stamped
}

/// Record, as clock stops, the rows from `cut_at` on that a kernel lane the
/// deadline cut there would still have tried (`tried` selects them by result).
///
/// An `UnsupportedMir` row is not recorded: the transport publishes it unknown
/// whatever a kernel lane proves (`fail_closed_unsupported_mir_transport_outcome`),
/// so no clock decided it.
fn record_kernel_lane_clock_cut(
    clock_stops: &mut ClockStops,
    results: &[(VerificationCondition, VerificationResult)],
    cut_at: usize,
    tried: impl Fn(&VerificationResult) -> bool,
) {
    for (index, (vc, result)) in results.iter().enumerate().skip(cut_at) {
        if tried(result) && !matches!(vc.kind, VcKind::UnsupportedMir { .. }) {
            clock_stops.record_provable(index, vc, StoppingClock::FunctionDeadline);
        }
    }
}

/// Record, as clock stops, every row of a run whose native bundle the
/// per-function deadline declined (`native_run_lowering_declined_by_deadline`).
/// Such a bundle was never verified: its rows are filled `Unsupported`
/// (`trust-full-verifier`, `0ms`), but the clock, not the engines, left each
/// of them undecided. A compiler-side `unsupported_mir` refusal is excepted:
/// no engine decides it either way.
fn record_deadline_declined_bundle_clock_stops(
    clock_stops: &mut ClockStops,
    run: &trust_verifier_api::VerificationRunResult,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
) {
    if !native_run_lowering_declined_by_deadline(run) {
        return;
    }
    for (index, (vc, _)) in results.iter().enumerate() {
        let refusal = result_bindings
            .get(index)
            .and_then(Option::as_ref)
            .is_some_and(|binding| is_unsupported_mir_obligation(&binding.canonical_obligation));
        if !refusal {
            clock_stops.record(index, vc, StoppingClock::FunctionDeadline);
        }
    }
}

/// Record, as clock stops, the rows whose live receipts a mint lane refused
/// because the function deadline had passed (the reports' `clock_rejected`):
/// the native engine proved the row, and the clock refused the authority.
///
/// An `UnsupportedMir` row is not recorded, for the reason
/// [`record_kernel_lane_clock_cut`] gives. The vacuity gate is not consulted:
/// the direct live lanes are exempt from it (`apply_vacuity_gate_with_authority`).
fn record_live_mint_clock_stops(
    clock_stops: &mut ClockStops,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    clock_rejected: &[String],
) {
    if clock_rejected.is_empty() {
        return;
    }
    let rows = build_exact_result_binding_row_index(results, result_bindings);
    for obligation_id in clock_rejected {
        let Some(&index) = rows.unique_rows.get(obligation_id.as_str()) else { continue };
        let vc = &results[index].0;
        if !matches!(vc.kind, VcKind::UnsupportedMir { .. }) {
            clock_stops.record(index, vc, StoppingClock::FunctionDeadline);
        }
    }
}

/// The full lane's kernel certification and S1 re-solve, and the private
/// authority they mint (`build_result_proof_authorities_with_revalidations`):
/// one deadline-bound step of the authority phase, with every row a clock kept
/// from either lane recorded in `clock_stops` (determinism plan §3.7) — a
/// `Proved` row the certify sweep's deadline cut, and the rows S1's `revalidate`
/// reports. Production passes `revalidate_all_solver_proofs` as `revalidate`;
/// a test injects the re-solve, and the same wiring runs.
///
/// `panic_grounding`'s exact certificate is seeded between the two: a grounding
/// whose certificate was already earned keeps it even when the deadline cut the
/// sweep, so its row is authorized and no clock stop is published for it.
#[allow(clippy::too_many_arguments)]
fn certify_and_revalidate_full_lane_rows(
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    full_result: Option<&trust_verifier_api::VerificationRunResult>,
    panic_grounding: Option<CertifiedPanicFreedomGrounding>,
    deadline: Option<std::time::Instant>,
    clock_stops: &mut ClockStops,
    // Trust (TINV step 10.4): the body's type-invariant disclosure.
    tinv: &type_invariant::TinvRowDisclosure,
    proof_artifact_root: Option<&std::path::Path>,
    mut early_replays: Option<(
        &trust_verifier_api::TrustContractBundle,
        &trust_router::VerifierExecutionContext,
        &mut BTreeMap<String, trust_router::CurrentKernelProofReplay>,
    )>,
    revalidate: impl FnOnce(&[Option<trust_ir::ProofEvidence>]) -> SolverRevalidations,
) -> (Vec<Option<trust_ir::ProofEvidence>>, Vec<Option<ResultProofAuthority>>) {
    let (mut cleancic, replay_audits, certify_cut_at) =
        certify_all_until_with_artifacts_and_early_replays(
            results,
            deadline,
            proof_artifact_root,
            |index, vc| {
                let (bundle, context, proofs) = early_replays.as_mut()?;
                let binding = result_bindings.get(index)?.as_ref()?;
                if !binding.matches_row(index, vc) {
                    return None;
                }
                if !proofs.get(&binding.public_obligation_id)?.matches(
                    bundle,
                    &binding.canonical_obligation,
                    vc,
                    context,
                ) {
                    return None;
                }
                proofs.remove(&binding.public_obligation_id)?.into_parts_for(
                    bundle,
                    &binding.canonical_obligation,
                    vc,
                    context,
                )
            },
        );
    // A `Proved` row the deadline kept from the kernel is a clock stop. This
    // sweep also stands for the catch-all grounding before it, which the same
    // deadline would have cut.
    if let Some(cut_at) = certify_cut_at {
        record_kernel_lane_clock_cut(clock_stops, results, cut_at, |result| {
            matches!(result, VerificationResult::Proved { .. })
        });
    }
    // Keep the already earned exact certificate even if the shared deadline
    // expires during the later certification pass. A changed row or verdict
    // cannot inherit it, and its native binding was correctly retired.
    if let Some(grounding) = panic_grounding {
        grounding.seed_exact_certificate(results, &mut cleancic);
    }
    let SolverRevalidations { receipts, clock_stops: s1_clock_stops } = revalidate(&cleancic);
    clock_stops.append(s1_clock_stops);
    let mut proof_authorities = build_result_proof_authorities_with_revalidations_and_replay_audits(
        results,
        result_bindings,
        full_result,
        &cleancic,
        &receipts,
        &replay_audits,
    );
    // Trust (TINV step 10.4): the composed rung, over the SAME S1 receipts.
    mint_type_invariant_composed_authorities(
        results,
        result_bindings,
        &receipts,
        &mut proof_authorities,
        tinv,
    );
    (cleancic, proof_authorities)
}

/// Trust: sealed-authority S1 (SolverReplayAuthority, SMT lane). Only rows
/// carrying a private, exact [`SolverRevalidationEligibility`] minted by the
/// local AY bridge are re-solved. Public `Proved` labels and evidence strings
/// are deliberately irrelevant. The CleanCIC carrier is consumed alongside the
/// rows so a kernel-certified row is skipped rather than redundantly downgraded
/// to SMT authority. Any carrier-length skew returns all `None` without calling
/// the solver.
fn revalidate_all_solver_proofs(
    results: &[(VerificationCondition, VerificationResult)],
    eligibilities: &[Option<SolverRevalidationEligibility>],
    cleancic: &[Option<trust_ir::ProofEvidence>],
    deadline: Option<std::time::Instant>,
    effort: trust_types::determinism::EffortScale,
) -> SolverRevalidations {
    revalidate_all_solver_proofs_with(
        results,
        eligibilities,
        cleancic,
        deadline,
        std::time::Instant::now,
        |formula, budget_ms| strict_smt_revalidate(formula, budget_ms, effort),
    )
}

/// What S1 leaves for one function's rows.
#[derive(Debug, Default)]
struct SolverRevalidations {
    /// Fresh receipts, index-aligned with the rows; `None` where none was
    /// minted.
    receipts: Vec<Option<SolverRevalidationReceipt>>,
    /// The exact eligible rows a CLOCK kept from a receipt: rows the function
    /// deadline left un-re-solved, a strict success that returned after it,
    /// and a re-solve its own clock ended (determinism plan §3.7).
    clock_stops: ClockStops,
}

/// Injectable core for deterministic deadline and provenance tests. Production
/// passes `Instant::now` and `strict_smt_revalidate`; the injected callbacks do
/// not add an alternate production authority seam.
fn revalidate_all_solver_proofs_with<Now, Revalidate>(
    results: &[(VerificationCondition, VerificationResult)],
    eligibilities: &[Option<SolverRevalidationEligibility>],
    cleancic: &[Option<trust_ir::ProofEvidence>],
    deadline: Option<std::time::Instant>,
    mut now: Now,
    mut revalidate: Revalidate,
) -> SolverRevalidations
where
    Now: FnMut() -> std::time::Instant,
    Revalidate: FnMut(&trust_types::Formula, u64) -> StrictSmtRevalidationOutcome,
{
    let mut revalidations = SolverRevalidations::default();
    if results.len() != eligibilities.len() || results.len() != cleancic.len() {
        revalidations.receipts = vec![None; results.len()];
        return revalidations;
    }

    let SolverRevalidations { receipts, clock_stops } = &mut revalidations;
    receipts.reserve(results.len());
    // Once the function deadline has passed no further row is re-solved, but
    // every remaining exact eligible row is still recognized: it is a row the
    // clock, not the solver, kept from a receipt, and it is recorded as one
    // instead of being filled with a silent `None`.
    let mut deadline_passed = false;
    for (index, (vc, result)) in results.iter().enumerate() {
        // A row with no eligibility is never re-solved and never recorded: it
        // skips the canonical serialization and the SMT print below, which
        // would otherwise run, past the deadline, for every remaining row of a
        // large function.
        let Some(eligibility) = eligibilities[index].as_ref() else {
            receipts.push(None);
            continue;
        };
        let current_row = exact_result_row_identity(index, vc);
        let expected_problem = trust_router::in_process_ay_backend::problem_smt2(&vc.formula);
        let has_kernel_proof = matches!(
            cleancic.get(index).and_then(Option::as_ref),
            Some(trust_ir::ProofEvidence::CleanCic { .. })
        );
        let is_exact_eligible_row = is_strict_smt_proved_result(result)
            && !has_kernel_proof
            && !matches!(vc.kind, VcKind::UnsupportedMir { .. })
            && current_row.as_ref().is_some_and(|row| {
                &eligibility.row == row
                    && eligibility.producer_canonical_problem.as_bytes()
                        == expected_problem.as_bytes()
            });
        if !is_exact_eligible_row {
            receipts.push(None);
            continue;
        }
        if deadline_passed {
            receipts.push(None);
            clock_stops.record_provable(index, vc, StoppingClock::FunctionDeadline);
            continue;
        }

        // Each fresh solve runs on the effort budget its `revalidate` carries
        // (determinism plan §3.2, S1 row), gets at most four seconds
        // (`SOLVER_REVALIDATION_BUDGET_MS`, unchanged until plan T2d) and
        // never more than the remaining absolute
        // function budget. The post-check is equally authoritative: the
        // synchronous AY API cannot enforce time spent waiting for its
        // process-global lock, so a late success is discarded.
        let pre_solve_now = now();
        let budget_ms = if deadline.is_some_and(|at| pre_solve_now >= at) {
            None
        } else {
            remaining_solver_timeout_ms(SOLVER_REVALIDATION_BUDGET_MS, deadline, pre_solve_now)
        };
        let Some(budget_ms) = budget_ms else {
            deadline_passed = true;
            receipts.push(None);
            clock_stops.record_provable(index, vc, StoppingClock::FunctionDeadline);
            continue;
        };
        let fresh = revalidate(&vc.formula, budget_ms);
        let late = deadline.is_some_and(|at| now() >= at);
        if let Some(clock) = strict_revalidation_clock(&fresh, late, budget_ms) {
            clock_stops.record_provable(index, vc, clock);
        }
        if late {
            deadline_passed = true;
            receipts.push(None);
            continue;
        }
        let Ok(fresh) = fresh else {
            receipts.push(None);
            continue;
        };
        let receipt = match current_row {
            Some(current_row)
                if fresh.canonical_problem.as_bytes() == expected_problem.as_bytes() =>
            {
                Some(SolverRevalidationReceipt {
                    row_index: current_row.index,
                    canonical_vc: current_row.canonical_vc,
                    canonical_problem: fresh.canonical_problem,
                    problem_sha256: fresh.problem_sha256,
                    time_ms: fresh.time_ms,
                })
            }
            _ => None,
        };
        receipts.push(receipt);
    }
    revalidations
}

// ---------------------------------------------------------------------------
// Trust: VC + VerificationResult -> TrustProofResults conversion (#35)
//
// Bridges the trust-types verification IR to the compiler-internal
// TrustProofResults type that will be stored in the query system.
// ---------------------------------------------------------------------------

/// Re-generate the compiler-owned VC set and retain only exact definition-site
/// `Requires` bookkeeping rows.
///
/// A recursive call has `callee == function`, exactly like the function's own
/// entry marker, so names and the literal `Bool(false)` representation are not
/// sufficient provenance. The vcgen producer stamps the dense authored-clause
/// index; this consumer validates that index, kind, span, and complete VC bytes
/// against a fresh generation from the canonical [`trust_types::VerifiableFunction`]. Any
/// missing, duplicate, stale, or forged hint therefore yields no exemption.
fn exact_definition_entry_assumption_rows(
    function: &trust_types::VerifiableFunction,
) -> Vec<VerificationCondition> {
    if !function
        .contracts
        .iter()
        .any(|contract| matches!(contract.kind, trust_types::ContractKind::Requires))
    {
        return Vec::new();
    }

    trust_vcgen::generate_vcs(function)
        .into_iter()
        .filter(|vc| {
            let Some(source_index) =
                vc.contract_metadata.and_then(|metadata| metadata.source_contract_index)
            else {
                return false;
            };
            let Some(contract) = function.contracts.get(source_index) else {
                return false;
            };
            matches!(contract.kind, trust_types::ContractKind::Requires)
                && contract.span == vc.location
                && vc.function.as_str() == function.name
                && matches!(
                    &vc.kind,
                    VcKind::Precondition { callee } if callee == &function.name
                )
                && matches!(vc.formula, Formula::Bool(false))
        })
        .collect()
}

fn is_exact_definition_entry_assumption_row(
    vc: &VerificationCondition,
    regenerated_rows: &[VerificationCondition],
) -> bool {
    let Some(key) = exact_vc_key(vc) else { return false };
    regenerated_rows.iter().filter(|expected| exact_vc_key(expected).as_ref() == Some(&key)).count()
        == 1
}

/// The current result carrier must also contain the exact row once. Fresh
/// regeneration proves source ownership, but cannot distinguish one supplied
/// row from two byte-identical copies of that row. A duplicate carrier is
/// ambiguous and must not receive definition-entry assumption authority.
fn exact_result_row_counts(
    results: &[(VerificationCondition, VerificationResult)],
) -> FxHashMap<ExactVcKey, usize> {
    let mut counts = FxHashMap::default();
    let mut keyed = Vec::new();
    for (vc, _) in results {
        if let Some(key) = exact_vc_key(vc) {
            if row_key::oracle_runs() {
                keyed.push(key.canonical_payload.clone());
            }
            *counts.entry(key).or_default() += 1;
        }
    }
    // Trust (T3 L4, C09): the counts' lookups compare only keys whose strings hash alike; two
    // rows whose strings differ and whose identities are one are counted here (`row_key`'s
    // docs).
    row_key::count_partition(&keyed);
    counts
}

fn is_unique_exact_result_row(
    vc: &VerificationCondition,
    counts: &FxHashMap<ExactVcKey, usize>,
) -> bool {
    let Some(key) = exact_vc_key(vc) else { return false };
    counts.get(&key) == Some(&1)
}

fn fail_closed_unproved_precondition(
    kind: &VcKind,
    status: TrustStatus,
    is_definition_entry: bool,
) -> TrustStatus {
    if matches!(kind, VcKind::Precondition { .. })
        && !is_definition_entry
        && matches!(
            status,
            TrustStatus::Unknown | TrustStatus::Timeout | TrustStatus::RuntimeChecked
        )
    {
        TrustStatus::Failed
    } else {
        status
    }
}

/// Trust: Build compiler-internal TrustProofResults from verification pipeline output.
///
/// Creates one TrustDisposition per (VC, result) pair, computes a 128-bit
/// Fingerprint for each obligation (structural hash of VC kind + function + index),
/// and aggregates a TrustFunctionSummary with counts per status.
///
/// The returned TrustProofResults is ready for storage in the query system
/// (pending #32 query registration).
fn build_proof_results(
    sess: &Session,
    results: &[(VerificationCondition, VerificationResult)],
    fallback_vcs: &[VerificationCondition],
    result_bindings: &[Option<ResultObligationBinding>],
    // Exact private authority, index-aligned with `results`. Missing or
    // misaligned entries fail closed; public result labels cannot substitute.
    authorities: &[Option<ResultProofAuthority>],
    // Canonical source used to distinguish a definition-entry assumption from
    // a recursive call-site precondition. `None` grants no source-based skip.
    source_function: Option<&trust_types::VerifiableFunction>,
) -> TrustProofResults {
    build_proof_results_with_runtime_checks(
        sess.overflow_checks(),
        results,
        fallback_vcs,
        result_bindings,
        authorities,
        source_function,
    )
}

/// Pure core shared with authority-parity unit tests. Runtime fallback is the
/// only part of proof-result conversion that depends on Session configuration.
fn build_proof_results_with_runtime_checks(
    overflow_checks: bool,
    results: &[(VerificationCondition, VerificationResult)],
    fallback_vcs: &[VerificationCondition],
    result_bindings: &[Option<ResultObligationBinding>],
    authorities: &[Option<ResultProofAuthority>],
    source_function: Option<&trust_types::VerifiableFunction>,
) -> TrustProofResults {
    // Trust: Build parallel IndexVec<ObligationId, _> for dispositions and fingerprints.
    let mut dispositions: IndexVec<ObligationId, TrustDisposition> = IndexVec::new();
    // Trust (TINV step 10.7): the disclosed premises of TINV-composed rows.
    let mut premises: Vec<TrustObligationPremise> = Vec::new();
    let mut fingerprints: IndexVec<ObligationId, Fingerprint> = IndexVec::new();

    // Trust: Summary counters.
    let mut trusted: u32 = 0;
    let mut certified: u32 = 0;
    let mut failed: u32 = 0;
    let mut unknown: u32 = 0;
    let mut runtime_checked: u32 = 0;
    let mut max_level = TrustProofLevel::None;
    let definition_entry_rows =
        source_function.map(exact_definition_entry_assumption_rows).unwrap_or_default();
    let supplied_row_counts = exact_result_row_counts(results);

    // Trust: If results are available (trust-router ran), use paired (VC, result).
    // Otherwise fall back to VCs-only with Unknown status (no solver ran yet).
    if !results.is_empty() {
        for (index, (vc, result)) in results.iter().enumerate() {
            let kind = convert_vc_kind(&vc.kind);
            let unique_result_row = is_unique_exact_result_row(vc, &supplied_row_counts);
            // Trust: phase-A vacuity gate — a Proved result whose violation
            // formula constant-folds to `false` (a literal true/false goal) is
            // vacuous and must not be certified. Downgrades to Unknown so it
            // cannot count as a real proof; genuine symbolic proofs pass through.
            //
            // The authority carrier was minted from this exact row's CleanCic
            // term, fresh solver revalidation, or compiler-owned live body
            // receipt. `.get` is defensive: a length mismatch loses authority
            // rather than borrowing a token.
            let binding = result_bindings.get(index).and_then(Option::as_ref);
            let authority = authorities
                .get(index)
                .and_then(Option::as_ref)
                .filter(|authority| {
                    authority.matches_row(index, vc, binding)
                        && authority.matches_compiler_result(result)
                })
                .filter(|authority| {
                    unique_result_row
                        || !matches!(
                            authority,
                            ResultProofAuthority::DefinitionEntryAssumption { .. }
                        )
                });
            // Trust (P1.2): the def-site `#[requires]` bookkeeping placeholder
            // is exempt from the vacuity gate only when the exact private
            // DefinitionEntryAssumption token is present. The public solver
            // label is attribution, never authority.
            let gated_result =
                apply_vacuity_gate_with_authority(index, vc, result.clone(), binding, authority);
            let (status, strength) =
                convert_result(overflow_checks, index, vc, binding, &gated_result, authority);
            // Trust (#5-PRE-A — caller-side precondition is a CHECKED obligation,
            // fail-closed): a `VcKind::Precondition` is the compensating caller-side
            // check that MUST hold because the callee discharged its OWN Level-0 safety
            // obligation (DivisionByZero / IndexOutOfBounds / overflow / …) by ASSUMING
            // its `#[requires]` (`generate_vcs_with_extra_precondition` conjoins the
            // precondition onto every callee body VC, and the def-site `#[requires]` VC
            // is a trivially-discharged `Bool(false)` ASSUMPTION, not an obligation —
            // contracts.rs). So a caller-side precondition VC whose negation the solver
            // could NOT refute means the callee's assumed precondition was never
            // established here: shipping green would be a false-PROVE of the callee's L0
            // property (the cardinal sin — trust_verify.rs modular-soundness comment).
            //
            // The proof level makes this a silent hole: a Precondition VC is
            // `ProofLevel::L1Functional` (vc_kind.rs), excluded from both strict-L0
            // fatal gates (`is_strict_l0_vc_kind` / `is_strict_l0_api_obligation_kind`),
            // and an unproved owner result is otherwise bucketed non-fatally as
            // a coverage gap. Reclassify a non-proved Precondition into `Failed`
            // here so the
            // authoritative `proof_results.summary.failed` (which
            // `abort_on_full_verification_failure` reads via `full_verification_failure`)
            // drives the fail-closed abort. This is the caller-side analogue of the
            // existing `is_known_panicking_call_unsupported_mir` reclassification.
            //
            // SOUNDNESS / no-over-rejection: a caller that GENUINELY establishes a
            // decidable (linear) precondition arrives here ALREADY `Proved` — the ay
            // re-solve (`bridge_v1_ay_proofs_into_native_results`, now that
            // `InProcessAyBackend::can_handle` admits `Precondition`) refutes `¬P[σ]` for a
            // violated linear precondition (→ Failed, kept) and proves it UNSAT for an
            // established one (→ Proved, NOT reclassified). Only a residual
            // Unknown/RuntimeChecked/Timeout Precondition — one no engine could discharge —
            // is reclassified. `Certified`/`Trusted` and `Proved` are preserved. A caller
            // of a genuinely-true NONLINEAR precondition the backends cannot prove now
            // fails closed (a completeness gap the follow-on backend-routing piece
            // addresses), never a false PROVE.
            //
            // CRITICAL SCOPING: exempt only an exact private full-lane entry
            // authority or a source-indexed row byte-identically regenerated
            // from this function. The former `callee != function` heuristic
            // was unsound for recursive self-calls: their call-site obligation
            // also has `callee == function` and could survive Unknown without
            // establishing the recursive precondition.
            let is_definition_entry = unique_result_row
                && (authority.is_some_and(|authority| {
                    authority.is_definition_entry_assumption_for(index, vc, binding)
                }) || is_exact_definition_entry_assumption_row(vc, &definition_entry_rows));
            let status = fail_closed_unproved_precondition(&vc.kind, status, is_definition_entry);
            let is_certified = matches!(status, TrustStatus::Certified);

            let disposition = TrustDisposition { kind, status, strength, certified: is_certified };

            // Trust (TINV step 10.7): a `Trusted` row proved under a certified type
            // invariant carries its premise lines beside its disposition.
            if status == TrustStatus::Trusted
                && let Some(lines) = authority.and_then(|authority| {
                    authority.type_invariant_disclosure_for(index, vc, &gated_result, binding)
                })
            {
                premises.push(TrustObligationPremise {
                    obligation: ObligationId::from_usize(dispositions.len()),
                    assumes: lines.iter().map(|line| Symbol::intern(line)).collect(),
                });
            }
            dispositions.push(disposition);
            fingerprints.push(compute_obligation_fingerprint(vc));

            // Trust: Accumulate summary counts.
            match status {
                TrustStatus::Trusted => trusted += 1,
                TrustStatus::Certified => certified += 1,
                TrustStatus::Failed => failed += 1,
                TrustStatus::Unknown | TrustStatus::Timeout => unknown += 1,
                TrustStatus::RuntimeChecked => runtime_checked += 1,
            }

            // Trust: Track max proof level from VC kind.
            let level = convert_proof_level(&vc.kind);
            if level > max_level {
                max_level = level;
            }
        }
    } else {
        // Trust: No solver results — create Unknown dispositions for all VCs.
        for vc in fallback_vcs {
            let kind = convert_vc_kind(&vc.kind);
            let disposition = TrustDisposition {
                kind,
                status: TrustStatus::Unknown,
                strength: TrustProofStrength::None,
                certified: false,
            };

            dispositions.push(disposition);
            fingerprints.push(compute_obligation_fingerprint(vc));
            unknown += 1;

            let level = convert_proof_level(&vc.kind);
            if level > max_level {
                max_level = level;
            }
        }
    }

    let total = dispositions.len() as u32;

    let summary = TrustFunctionSummary {
        total,
        trusted,
        certified,
        failed,
        unknown,
        runtime_checked,
        // Trust: fresh-computed summary (no cache replay), so no cached HITs.
        cached: 0,
        max_level,
    };

    TrustProofResults { dispositions, fingerprints, summary, premises }
}

fn build_proof_telemetry(
    sess: &Session,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    authorities: &[Option<ResultProofAuthority>],
) -> TrustProofTelemetry {
    build_proof_telemetry_with(
        &|kind| has_runtime_check(sess, kind),
        results,
        result_bindings,
        authorities,
    )
}

/// [`build_proof_telemetry`] over an explicit runtime-check predicate (the session-free
/// half, so the TINV disclosure can be pinned by a unit test).
fn build_proof_telemetry_with(
    runtime_check: &dyn Fn(&VcKind) -> bool,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    authorities: &[Option<ResultProofAuthority>],
) -> TrustProofTelemetry {
    let mut details: IndexVec<ObligationId, TrustObligationDetail> = IndexVec::new();

    for (index, (vc, result)) in results.iter().enumerate() {
        let binding = result_bindings.get(index).and_then(Option::as_ref);
        let fallback_for_row = |outcome, reason| {
            runtime_check(&vc.kind).then(|| runtime_fallback_detail(outcome, reason))
        };
        let (solver, time_ms, counterexample, runtime_fallback) = match result {
            VerificationResult::Proved { solver, time_ms, .. }
                if authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
                    authority.permits_static_proved_transport_for(index, vc, result, binding)
                }) =>
            {
                (solver.as_str(), *time_ms, None, None)
            }
            VerificationResult::Proved { solver, time_ms, .. }
                if authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
                    authority.is_definition_entry_assumption_for(index, vc, binding)
                }) =>
            {
                (solver.as_str(), *time_ms, None, None)
            }
            VerificationResult::Proved { solver, time_ms, .. } => {
                let fallback = fallback_for_row(
                    RuntimeFallbackOutcome::Unknown,
                    "solver reported Proved without exact kernel/native proof authority",
                );
                (solver.as_str(), *time_ms, None, fallback)
            }
            VerificationResult::Failed { solver, time_ms, counterexample } => {
                (solver.as_str(), *time_ms, counterexample.as_ref(), None)
            }
            VerificationResult::Unknown { solver, time_ms, reason } => {
                let fallback = fallback_for_row(RuntimeFallbackOutcome::Unknown, reason);
                (solver.as_str(), *time_ms, None, fallback)
            }
            VerificationResult::Timeout { solver, timeout_ms } => {
                let fallback = fallback_for_row(
                    RuntimeFallbackOutcome::Timeout,
                    "solver timed out before proving the obligation",
                );
                (solver.as_str(), *timeout_ms, None, fallback)
            }
            _ => (
                result.solver_name(),
                result.time_ms(),
                None,
                fallback_for_row(
                    RuntimeFallbackOutcome::Unknown,
                    "unsupported verification result variant",
                ),
            ),
        };

        // Trust (TINV step 10.7): the premise lines of a row proved under a certified
        // type invariant (the same lines the proof results and the transport carry).
        let assumes = authorities
            .get(index)
            .and_then(Option::as_ref)
            .and_then(|authority| {
                authority.type_invariant_disclosure_for(index, vc, result, binding)
            })
            .map(|lines| lines.iter().map(|line| Symbol::intern(line)).collect())
            .unwrap_or_default();
        details.push(TrustObligationDetail {
            assumes,
            solver: Symbol::intern(solver),
            time_us: time_ms.saturating_mul(1_000),
            counterexample: counterexample
                .map(|cex| {
                    cex.assignments
                        .iter()
                        .map(|(name, value)| {
                            (Symbol::intern(name), encode_counterexample_value(value))
                        })
                        .collect()
                })
                .unwrap_or_default(),
            runtime_fallback,
        });
    }

    TrustProofTelemetry { details }
}

enum RuntimeFallbackOutcome {
    Unknown,
    Timeout,
}

fn runtime_fallback_for(
    sess: &Session,
    kind: &VcKind,
    outcome: RuntimeFallbackOutcome,
    reason: &str,
) -> Option<TrustRuntimeFallback> {
    if !has_runtime_check(sess, kind) {
        return None;
    }

    Some(runtime_fallback_detail(outcome, reason))
}

fn runtime_fallback_detail(outcome: RuntimeFallbackOutcome, reason: &str) -> TrustRuntimeFallback {
    let (fallback_reason, note) = match outcome {
        RuntimeFallbackOutcome::Unknown => {
            (TrustRuntimeFallbackReason::Unknown, format!("solver returned unknown: {reason}"))
        }
        RuntimeFallbackOutcome::Timeout => {
            (TrustRuntimeFallbackReason::Timeout, reason.to_string())
        }
    };

    TrustRuntimeFallback { reason: fallback_reason, note }
}

/// Trust: Convert a trust-types VcKind to the compiler-internal TrustObligationKind.
///
/// Maps the serde-friendly VcKind variants to the Copy/HashStable/TyEncodable
/// TrustObligationKind used in the query system.
fn convert_vc_kind(kind: &VcKind) -> TrustObligationKind {
    if let Some(category) = kind.hardened_category() {
        return TrustObligationKind::HardenedBoundary(convert_hardened_category(category));
    }

    match kind {
        VcKind::ArithmeticOverflow { op, .. } | VcKind::FloatOverflowToInfinity { op, .. } => {
            convert_binop(op)
                .map(TrustObligationKind::ArithmeticOverflow)
                .unwrap_or(TrustObligationKind::UnsupportedMir)
        }
        VcKind::ShiftOverflow { .. } => TrustObligationKind::ShiftOverflow,
        VcKind::DivisionByZero => TrustObligationKind::DivisionByZero,
        VcKind::FloatDivisionByZero => TrustObligationKind::DivisionByZero,
        VcKind::RemainderByZero => TrustObligationKind::RemainderByZero,
        VcKind::IndexOutOfBounds | VcKind::SliceBoundsCheck => {
            TrustObligationKind::IndexOutOfBounds
        }
        VcKind::Assertion { .. } => TrustObligationKind::Assertion,
        VcKind::Precondition { .. } => TrustObligationKind::Precondition,
        VcKind::Postcondition => TrustObligationKind::Postcondition,
        VcKind::CastOverflow { .. } => TrustObligationKind::CastOverflow,
        VcKind::NegationOverflow { .. } => TrustObligationKind::NegationOverflow,
        VcKind::Unreachable => TrustObligationKind::Unreachable,
        VcKind::UnsupportedMir { .. } => TrustObligationKind::UnsupportedMir,
        VcKind::DeadState { .. } | VcKind::Deadlock => TrustObligationKind::Deadlock,
        VcKind::Temporal { .. } => TrustObligationKind::Temporal,
        VcKind::Liveness { .. } | VcKind::Fairness { .. } => TrustObligationKind::Liveness,
        VcKind::TaintViolation { .. } => TrustObligationKind::TaintViolation,
        VcKind::RefinementViolation { .. } => TrustObligationKind::RefinementViolation,
        VcKind::ResilienceViolation { .. } => TrustObligationKind::ResilienceViolation,
        VcKind::ProtocolViolation { .. } => TrustObligationKind::ProtocolViolation,
        VcKind::NonTermination { .. } => TrustObligationKind::NonTermination,
        // Trust: TINV gets its own kind. The L1 fallback would label it `Postcondition`,
        // and the compose gate counts those rows as the callee's `ensures` rows.
        VcKind::TypeInvariant { .. } => TrustObligationKind::TypeInvariant,
        _ => fallback_internal_obligation_for_proof_level(kind),
    }
}

fn fallback_internal_obligation_for_proof_level(kind: &VcKind) -> TrustObligationKind {
    match convert_proof_level(kind) {
        TrustProofLevel::None => TrustObligationKind::UnsupportedMir,
        TrustProofLevel::L0Safety => TrustObligationKind::Assertion,
        TrustProofLevel::L1Functional => TrustObligationKind::Postcondition,
        TrustProofLevel::L2Domain => TrustObligationKind::ProtocolViolation,
    }
}

fn convert_hardened_category(category: HardenedVcCategory) -> TrustHardenedVcCategory {
    match category {
        HardenedVcCategory::RawPathApi => TrustHardenedVcCategory::RawPathApi,
        HardenedVcCategory::PathIdentity => TrustHardenedVcCategory::PathIdentity,
        HardenedVcCategory::PermissionChange => TrustHardenedVcCategory::PermissionChange,
        HardenedVcCategory::PermissionCreate => TrustHardenedVcCategory::PermissionCreate,
        HardenedVcCategory::PermissionWindow => TrustHardenedVcCategory::PermissionWindow,
        HardenedVcCategory::Utf8Reject => TrustHardenedVcCategory::Utf8Reject,
        HardenedVcCategory::ByteLoss => TrustHardenedVcCategory::ByteLoss,
        HardenedVcCategory::ErrorDiscard => TrustHardenedVcCategory::ErrorDiscard,
        HardenedVcCategory::PanicBoundary => TrustHardenedVcCategory::PanicBoundary,
        HardenedVcCategory::CompatObservable => TrustHardenedVcCategory::CompatObservable,
        HardenedVcCategory::ProcessSemantics => TrustHardenedVcCategory::ProcessSemantics,
        HardenedVcCategory::TrustDomain => TrustHardenedVcCategory::TrustDomain,
        HardenedVcCategory::TrustDomainOrder => TrustHardenedVcCategory::TrustDomainOrder,
        HardenedVcCategory::UnsafeOperation => TrustHardenedVcCategory::UnsafeOperation,
        HardenedVcCategory::FfiBoundary => TrustHardenedVcCategory::FfiBoundary,
        HardenedVcCategory::Unknown(tag) => {
            TrustHardenedVcCategory::Unknown(Symbol::intern(tag.as_str()))
        }
        _ => TrustHardenedVcCategory::Unknown(Symbol::intern(category.as_tag())),
    }
}

/// Convert an overflow-capable trust-types `BinOp` to its exact compiler
/// representation.
///
/// `TrustBinOp` intentionally has no comparison or bitwise variants because
/// those operations cannot name an arithmetic-overflow obligation. Returning
/// `None` keeps malformed/future `ArithmeticOverflow` inputs fail-closed as
/// `UnsupportedMir`; fabricating `Add` here would corrupt the query identity and
/// could let a cached/addition proof stand in for an unrelated operation.
fn convert_binop(op: &BinOp) -> Option<TrustBinOp> {
    match op {
        BinOp::Add => Some(TrustBinOp::Add),
        BinOp::Sub => Some(TrustBinOp::Sub),
        BinOp::Mul => Some(TrustBinOp::Mul),
        BinOp::Div => Some(TrustBinOp::Div),
        BinOp::Rem => Some(TrustBinOp::Rem),
        BinOp::Shl => Some(TrustBinOp::Shl),
        BinOp::Shr => Some(TrustBinOp::Shr),
        BinOp::Eq
        | BinOp::Ne
        | BinOp::Lt
        | BinOp::Le
        | BinOp::Gt
        | BinOp::Ge
        | BinOp::BitAnd
        | BinOp::BitOr
        | BinOp::BitXor
        | BinOp::Cmp => None,
        // `BinOp` is non-exhaustive. A newly added operation must be modeled
        // explicitly before it can participate in a stable proof/cache key.
        _ => None,
    }
}

/// Trust: Convert a VerificationResult to (TrustStatus, TrustProofStrength).
///
/// Maps a result plus its private exact-row authority to the trust model:
/// - Proved + kernel token -> Certified
/// - Proved + private solver-revalidation token -> Trusted
/// - Proved + exact source-clause/live-body token -> Trusted (deductive derivation)
/// - Proved label without a token -> Unknown
/// - Failed -> (Failed, None)
/// - Unknown/Timeout -> (Unknown/Timeout, None)
fn convert_result(
    overflow_checks: bool,
    index: usize,
    vc: &VerificationCondition,
    binding: Option<&ResultObligationBinding>,
    result: &VerificationResult,
    authority: Option<&ResultProofAuthority>,
) -> (TrustStatus, TrustProofStrength) {
    let runtime_fallback = runtime_check_available(&vc.kind, overflow_checks);
    match result {
        VerificationResult::Proved { .. } => {
            // Trust (#2d): attempt in-process kernel certification FIRST — the de
            // Bruijn criterion. `trust_certify::certify_vc` is INDEPENDENT of the
            // incoming solver's self-reported `strength`: it re-asserts this
            // obligation's violation to clean-auto's own in-process ay backend,
            // confirms `UNSAT`, reconstructs the native proof into a CIC proof
            // term under a ZERO-TRUST budget (no `trustedAy`), and RE-CHECKS that
            // term with the clean kernel (`check_type`, `infer_only = false`). A
            // `Some(CleanCic)` therefore means the clean kernel — not the SMT
            // solver — established the obligation, so the original solver is
            // OUTSIDE the trusted base and we may report `Certified` regardless
            // of that solver's own assurance. The separately tracked, default-off
            // overflow-elision lane additionally requires a unique private
            // VC-to-MIR-block origin and live Add/Sub/Mul Assert recheck. This
            // ordering is the whole point of certification:
            // it is exactly the mechanism that upgrades an `Unchecked` SMT solve
            // (e.g. the ay subprocess proving a guard-bounded slice index) into a
            // kernel-checked proof. The weaker `Trusted` tier requires a
            // separately minted private revalidation, source-clause, or live
            // native capability.
            //
            // FAIL-CLOSED: `None` (any unsupported formula shape, non-`UNSAT`
            // solve, residual trust, or kernel rejection) has no kernel token.
            // The verdict was computed once by `certify_all`; no public bool or
            // strength label is accepted in its place.
            if matches!(authority, Some(ResultProofAuthority::KernelCertified { .. })) {
                if env_flag_enabled("TRUST_VERIFY_TRACE_CERTIFIED") {
                    eprintln!("TRUST_E2E_CERTIFIED fn={} kind={:?}", vc.function.as_str(), vc.kind);
                }
            }
            // Trust (TINV step 10.7, TINV-28 amended): a `TypeInvariantComposed` token
            // grades `Trusted`/`Deductive` through `trust_disposition_for_authority`
            // below, never `Certified`; its premises travel beside the disposition in
            // `TrustProofResults::premises` (`build_proof_results`).
            if let Some(disposition) =
                trust_disposition_for_authority(authority, index, vc, result, binding)
            {
                return disposition;
            }
            // A public `Proved`/strength label without a row-bound authority
            // token is advisory only. It cannot mint Trusted or Certified.
            (TrustStatus::Unknown, TrustProofStrength::None)
        }
        VerificationResult::Failed { .. } => (TrustStatus::Failed, TrustProofStrength::None),
        VerificationResult::Unknown { .. } => {
            if runtime_fallback {
                (TrustStatus::RuntimeChecked, TrustProofStrength::None)
            } else {
                (TrustStatus::Unknown, TrustProofStrength::None)
            }
        }
        VerificationResult::Timeout { .. } => {
            if runtime_fallback {
                (TrustStatus::RuntimeChecked, TrustProofStrength::None)
            } else {
                (TrustStatus::Timeout, TrustProofStrength::None)
            }
        }
        _ => (TrustStatus::Unknown, TrustProofStrength::None),
    }
}

#[cfg(test)]
fn proof_strength_satisfies_static_trust(strength: &ProofStrength) -> bool {
    !strength.is_bounded()
        && strength.reasoning.is_complete()
        && strength.assurance.strength_order()
            >= trust_types::AssuranceLevel::Sound.strength_order()
}

/// Trust: Convert a VcKind to TrustProofLevel (L0/L1/L2).
///
/// Mirrors VcKind::proof_level() but returns the compiler-internal enum.
fn convert_proof_level(kind: &VcKind) -> TrustProofLevel {
    match kind.proof_level() {
        trust_types::ProofLevel::L0Safety => TrustProofLevel::L0Safety,
        trust_types::ProofLevel::L1Functional => TrustProofLevel::L1Functional,
        trust_types::ProofLevel::L2Domain => TrustProofLevel::L2Domain,
        _ => TrustProofLevel::L2Domain,
    }
}

/// Trust: Compute a 128-bit Fingerprint for an obligation.
///
/// The fingerprint is a structural hash over the obligation's function,
/// canonical VC kind payload, and logical formula. This provides a stable identity that
/// does NOT depend on MIR locations (which shift during optimization) or on
/// incidental ordering in the generated VC list.
///
/// Trust (T3 L4, C09w; design §8): v4 binds the formula by its Merkle digest
/// (`trust_types::formula_merkle`) in place of its SMT-LIB text, and keeps the function
/// and the kind key v3 bound. A formula with no Merkle digest (none is known: the DAG is
/// fresh, and the plain digest refuses only a payload that does not serialize) is bound
/// under a refusal tag by its SMT-LIB text, as v3 bound every formula, so the fallback
/// tells formulas apart exactly as v3 did and never shares a fingerprint with a digest.
fn compute_obligation_fingerprint(vc: &VerificationCondition) -> Fingerprint {
    let mut hasher = StableHasher::new();
    "trust-obligation-fingerprint-v4".hash(&mut hasher);
    vc.function.as_str().hash(&mut hasher);
    vc_kind_fingerprint_key(&vc.kind).hash(&mut hasher);
    match trust_types::formula_merkle::formula_digest(&vc.formula) {
        Ok(digest) => {
            "formula-merkle".hash(&mut hasher);
            digest.as_bytes().hash(&mut hasher);
        }
        Err(_) => {
            "formula-merkle-refused".hash(&mut hasher);
            vc.formula.to_smtlib().hash(&mut hasher);
        }
    }
    hasher.finish()
}

/// Trust: produce a bounded, content-addressed MIR-dump filename.
///
/// The full definition path and exact serialized body participate in the
/// address. Distinct bodies therefore never intentionally share a pathname,
/// even if their human-readable definition paths would sanitize identically.
fn mir_dump_filename(def_path: &str, json: &str) -> String {
    let mut hasher = StableHasher::new();
    "trust-mir-dump-v2".hash(&mut hasher);
    def_path.hash(&mut hasher);
    json.hash(&mut hasher);
    let address: Fingerprint = hasher.finish();
    format!("trust-mir-{address}.json")
}

fn native_bundle_dump_filename(def_path: &str, json: &str) -> String {
    let mut hasher = StableHasher::new();
    "trust-native-bundle-dump-v1".hash(&mut hasher);
    def_path.hash(&mut hasher);
    json.hash(&mut hasher);
    let address: Fingerprint = hasher.finish();
    format!("trust-native-bundle-{address}.json")
}

/// Trust: publish a content-addressed dump without overwriting evidence.
///
/// `create_new` makes a hash collision or accidental duplicate observable. An
/// identical pre-existing file is safe to reuse (for repeated MIR queries),
/// while different contents fail closed instead of destroying the first body.
fn write_mir_dump_create_new(path: &std::path::Path, json: &str) -> std::io::Result<bool> {
    match std::fs::OpenOptions::new().write(true).create_new(true).open(path) {
        Ok(mut file) => {
            if let Err(error) = file.write_all(json.as_bytes()) {
                drop(file);
                let _ = std::fs::remove_file(path);
                return Err(error);
            }
            Ok(true)
        }
        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
            // Reuse is proof-evidence publication, not an ordinary cache hit:
            // never follow a pre-created leaf symlink. `symlink_metadata`
            // supplies a portable fast rejection and O_NOFOLLOW closes the
            // check/open race on Unix.
            let metadata = std::fs::symlink_metadata(path)?;
            if metadata.file_type().is_symlink() || !metadata.is_file() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidInput,
                    "existing MIR dump is not a non-symlink regular file",
                ));
            }
            let mut options = std::fs::OpenOptions::new();
            options.read(true);
            #[cfg(unix)]
            {
                use std::os::unix::fs::OpenOptionsExt as _;

                options.custom_flags(libc::O_NOFOLLOW);
            }
            let mut file = options.open(path)?;
            if !file.metadata()?.is_file() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidInput,
                    "existing MIR dump changed away from a regular file",
                ));
            }
            let mut existing = String::new();
            file.read_to_string(&mut existing)?;
            if existing == json {
                Ok(false)
            } else {
                Err(std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "MIR dump address collision with different contents",
                ))
            }
        }
        Err(error) => Err(error),
    }
}

fn vc_kind_fingerprint_key(kind: &VcKind) -> String {
    serde_json::to_string(kind).unwrap_or_else(|_| kind.description())
}

fn encode_counterexample_value(value: &CounterexampleValue) -> i128 {
    match value {
        CounterexampleValue::Bool(value) => i128::from(*value),
        CounterexampleValue::Int(value) => *value,
        CounterexampleValue::Uint(value) => (*value).min(i128::MAX as u128) as i128,
        CounterexampleValue::Float(value) => i128::from(value.to_bits()),
        _ => 0,
    }
}

